    def _follow_float(name: str, default: float) -> float:
        try:
            value = float(os.environ.get(name, str(default)) or default)
        except (TypeError, ValueError):
            value = float(default)
        if not math.isfinite(value):
            value = float(default)
        return float(value)

    def _follow_bool(name: str, default: bool) -> bool:
        raw = str(os.environ.get(name, "1" if default else "0") or "").strip().lower()
        return raw in {"1", "true", "yes", "on"}

    follow_near_before_hours = max(0.0, _follow_float("PM_AUTO_TRADE_ENTRY_FOLLOW_NEAR_BEFORE_HOURS", 24.0))
    follow_near_after_hours = max(0.0, _follow_float("PM_AUTO_TRADE_ENTRY_FOLLOW_NEAR_AFTER_HOURS", 6.0))
    follow_no_price_min = max(0.0, _follow_float("PM_AUTO_TRADE_ENTRY_FOLLOW_NO_PRICE_MIN", 0.95))
    if follow_no_price_min > 1:
        follow_no_price_min = follow_no_price_min / 100.0
    follow_yes_price_max = max(0.0, _follow_float("PM_AUTO_TRADE_ENTRY_FOLLOW_YES_PRICE_MAX", 0.35))
    if follow_yes_price_max > 1:
        follow_yes_price_max = follow_yes_price_max / 100.0
    follow_edge_cost_buffer = max(0.0, _follow_float("PM_AUTO_TRADE_ENTRY_FOLLOW_EDGE_COST_BUFFER", 0.01))
    follow_signal_edge_min = max(0.0, _follow_float("PM_AUTO_TRADE_ENTRY_FOLLOW_SIGNAL_EDGE_MIN", 0.0))
    follow_bypass_exec_edge = _follow_bool("PM_AUTO_TRADE_ENTRY_FOLLOW_BYPASS_EXEC_EDGE_GATE", False)
