    LONDON_FOLLOW_SIM_NEAR_BEFORE_HOURS = follow_near_before_hours
    LONDON_FOLLOW_SIM_NEAR_AFTER_HOURS = follow_near_after_hours
    LONDON_FOLLOW_SIM_REQUIRE_NEAR_SETTLEMENT = True
    LONDON_FOLLOW_SIM_NO_PRICE_MIN = follow_no_price_min
    LONDON_FOLLOW_SIM_YES_PRICE_MAX = 0.0 if follow_no_only else follow_yes_price_max
    if follow_bypass_exec_edge:
        LONDON_FOLLOW_SIM_MODE = "strict"
    else:
        LONDON_FOLLOW_SIM_MODE = "edge_gated"
        # Pass condition is edge > 0, so fold signal_edge_min into effective cost.
        LONDON_FOLLOW_SIM_EDGE_COST_BUFFER = follow_edge_cost_buffer + follow_signal_edge_min
