def _prune_most_likely_cache(now_ts: Optional[float] = None) -> None:
    if not _MOST_LIKELY_CACHE:
        return
    now_val = float(now_ts if now_ts is not None else time.time())
    stale_keys = [
        key
        for key, (ts, _payload) in list(_MOST_LIKELY_CACHE.items())
        if now_val - float(ts or 0.0) > float(MOST_LIKELY_CACHE_SEC) * 2.0
    ]
    for key in stale_keys:
        _MOST_LIKELY_CACHE.pop(key, None)
    overflow = len(_MOST_LIKELY_CACHE) - int(MOST_LIKELY_CACHE_MAX_ENTRIES)
    if overflow <= 0:
        return
    oldest = sorted(_MOST_LIKELY_CACHE.items(), key=lambda item: float(item[1][0] or 0.0))[:overflow]
    for key, _value in oldest:
        _MOST_LIKELY_CACHE.pop(key, None)


