def _latest_weather_anomaly_file(pattern: str) -> Optional[Path]:
    try:
        paths = [p for p in WEATHER_ANOMALY_REPORT_DIR.glob(pattern) if p.is_file()]
    except Exception:
        return None
    if not paths:
        return None
    return max(paths, key=lambda p: p.stat().st_mtime)


def _read_json_file_safe(path: Optional[Path]) -> Dict[str, Any]:
    if path is None:
        return {}
    try:
        payload = json.loads(path.read_text(encoding="utf-8"))
    except Exception:
        return {}
    return payload if isinstance(payload, dict) else {}


def _severity_rank(value: Any) -> int:
    text = str(value or "").strip().lower()
    if text == "critical":
        return 4
    if text == "high":
        return 3
    if text == "medium":
        return 2
    if text == "low":
        return 1
    return 0


def _alert_type_key(value: Any) -> str:
    key = str(value or "").strip().lower()
    return key if key in ANOMALY_ALERT_TYPE_META else "model_market_or_book_anomaly"


def _anomaly_alert_bucket_label(alert: Mapping[str, Any]) -> str:
    for key in ("bucket", "outcome", "label"):
        value = str(alert.get(key) or "").strip()
        if value:
            return value
    return ""


def _anomaly_fmt_prob(value: Any) -> str:
    num = to_float(value)
    if num is None or not math.isfinite(float(num)):
        return ""
    pct = float(num) * 100.0 if abs(float(num)) <= 1.000001 else float(num)
    return f"{pct:.1f}%"


def _anomaly_fmt_pp(value: Any) -> str:
    num = to_float(value)
    if num is None or not math.isfinite(float(num)):
        return ""
    pp = float(num) * 100.0 if abs(float(num)) <= 1.000001 else float(num)
    return f"{'+' if pp > 0 else ''}{pp:.1f}pp"


def _anomaly_fmt_num(value: Any) -> str:
    num = to_float(value)
    if num is None or not math.isfinite(float(num)):
        return ""
    if abs(float(num)) >= 100:
        return f"{float(num):.0f}"
    if abs(float(num)) >= 10:
        return f"{float(num):.1f}"
    return f"{float(num):.2f}"


def _anomaly_window_notional(alert: Mapping[str, Any], key: str) -> Optional[float]:
    windows = alert.get("recent_trade_windows")
    if not isinstance(windows, Mapping):
        return None
    row = windows.get(key)
    if not isinstance(row, Mapping):
        return None
    num = to_float(row.get("total_notional"))
    return float(num) if num is not None and math.isfinite(float(num)) else None


def _anomaly_alert_compact_line(alert: Mapping[str, Any], *, type_label: str) -> str:
    bucket = _anomaly_alert_bucket_label(alert) or "未知桶"
    behavior = str(type_label or alert.get("alert_type") or "盘口异常").strip()
    evidence: List[str] = []
    risk = _anomaly_fmt_num(alert.get("risk_score"))
    if risk:
        evidence.append(f"risk {risk}")
    mid = _anomaly_fmt_prob(alert.get("market_mid"))
    if mid:
        evidence.append(f"mid {mid}")
    gap = _anomaly_fmt_pp(alert.get("market_model_gap"))
    if gap:
        evidence.append(f"gap {gap}")
    trade_30m = _anomaly_window_notional(alert, "30m")
    if trade_30m is None:
        wallet = alert.get("wallet_concentration")
        if isinstance(wallet, Mapping):
            trade_30m = to_float(wallet.get("recent_trade_notional_30m"))
    if trade_30m is not None and math.isfinite(float(trade_30m)):
        evidence.append(f"30m成交 {_anomaly_fmt_num(trade_30m)}")
    wallet = alert.get("wallet_concentration")
    if isinstance(wallet, Mapping):
        top3 = _anomaly_fmt_prob(wallet.get("recent_30m_top3_wallet_share"))
    else:
        top3 = _anomaly_fmt_prob(alert.get("top3_wallet_share"))
    if top3:
        evidence.append(f"top3 {top3}")
    book = alert.get("book_inducement")
    if isinstance(book, Mapping) and book.get("triggered"):
        evidence.append("低成交跳价")
    market_context = alert.get("market_context")
    if isinstance(market_context, Mapping) and market_context.get("triggered"):
        evidence.append("页面Context更新")
    internal_context = alert.get("internal_repricing_context")
    if isinstance(internal_context, Mapping) and internal_context.get("triggered"):
        q_delta = _anomaly_fmt_pp(internal_context.get("q_primary_delta"))
        evidence.append(f"内部重估{(' ' + q_delta) if q_delta else ''}".strip())
    secondary = alert.get("secondary_evidence_types")
    if isinstance(secondary, list):
        for raw in secondary[:2]:
            label = ANOMALY_ALERT_TYPE_META.get(_alert_type_key(raw), {}).get("label")
            if label and label != behavior and label not in evidence:
                evidence.append(label)
    evidence = [part for idx, part in enumerate(evidence) if part and part not in evidence[:idx]]
    return f"{bucket} · {behavior} · {' · '.join(evidence[:6]) if evidence else '证据待补齐'}"


def _build_chengdu_anomaly_alerts_payload() -> Dict[str, Any]:
    alerts_path = _latest_weather_anomaly_file("chengdu_weather_market_alerts_*.json")
    report_path = _latest_weather_anomaly_file("chengdu_weather_market_anomaly_*.json")
    alerts_payload = _read_json_file_safe(alerts_path)
    report_payload = _read_json_file_safe(report_path)
    alerts = alerts_payload.get("alerts")
    if not isinstance(alerts, list):
        summary = report_payload.get("summary") if isinstance(report_payload.get("summary"), dict) else {}
        alerts = summary.get("alerts") if isinstance(summary.get("alerts"), list) else []

    groups: Dict[str, Dict[str, Any]] = {}
    for key in ANOMALY_ALERT_TYPE_ORDER:
        meta = ANOMALY_ALERT_TYPE_META[key]
        groups[key] = {
            "alert_type": key,
            "label": meta["label"],
            "description": meta["description"],
            "count": 0,
            "max_severity": "",
            "alerts": [],
        }
    for raw_alert in alerts:
        if not isinstance(raw_alert, dict):
            continue
        key = _alert_type_key(raw_alert.get("alert_type"))
        group = groups.setdefault(
            key,
            {
                "alert_type": key,
                "label": key.replace("_", " "),
                "description": "",
                "count": 0,
                "max_severity": "",
                "alerts": [],
            },
        )
        alert = dict(raw_alert)
        type_label = str(group.get("label") or ANOMALY_ALERT_TYPE_META.get(key, {}).get("label") or key)
        alert["compact_line"] = _anomaly_alert_compact_line(alert, type_label=type_label)
        group["alerts"].append(alert)
        group["count"] += 1
        if _severity_rank(raw_alert.get("severity")) > _severity_rank(group.get("max_severity")):
            group["max_severity"] = str(raw_alert.get("severity") or "")

    grouped_alerts = [
        group for key, group in groups.items()
        if group.get("count") or key in {"market_context", "book_inducement", "wallet_concentration"}
    ]
    grouped_alerts.sort(
        key=lambda group: (
            0 if group["alert_type"] in ANOMALY_ALERT_TYPE_ORDER else 1,
            ANOMALY_ALERT_TYPE_ORDER.index(group["alert_type"])
            if group["alert_type"] in ANOMALY_ALERT_TYPE_ORDER
            else 999,
        )
    )
    for group in grouped_alerts:
        group["alerts"] = sorted(
            group.get("alerts") or [],
            key=lambda alert: (
                -_severity_rank(alert.get("severity")),
                -(float(alert.get("risk_score") or 0.0) if isinstance(alert, dict) else 0.0),
                str(alert.get("label") or "") if isinstance(alert, dict) else "",
            ),
        )
        bucket_labels: List[str] = []
        seen_buckets: Set[str] = set()
        for alert in group.get("alerts") or []:
            if not isinstance(alert, Mapping):
                continue
            bucket_label = _anomaly_alert_bucket_label(alert)
            if not bucket_label or bucket_label in seen_buckets:
                continue
            seen_buckets.add(bucket_label)
            bucket_labels.append(bucket_label)
        group["buckets"] = bucket_labels
        group["bucket_summary"] = "、".join(bucket_labels)
        if bucket_labels:
            group["label_with_buckets"] = (
                f"{group.get('label') or group.get('alert_type')}:"
                f"{'、'.join(bucket_labels)}"
            )
        compact_lines = [
            str(alert.get("compact_line") or "").strip()
            for alert in group.get("alerts") or []
            if isinstance(alert, Mapping) and str(alert.get("compact_line") or "").strip()
        ]
        group["compact_summary"] = "；".join(compact_lines[:3])

    summary = report_payload.get("summary") if isinstance(report_payload.get("summary"), dict) else {}
    return {
        "ok": bool(alerts_path or report_path),
        "generated_at": alerts_payload.get("generated_at") or summary.get("generated_at") or now_text(),
        "updated_at": now_text(),
        "alerts_path": str(alerts_path) if alerts_path else "",
        "report_path": str(report_path) if report_path else "",
        "alert_count": len([a for a in alerts if isinstance(a, dict)]),
        "grouped_alerts": grouped_alerts,
        "group_counts": {group["alert_type"]: group["count"] for group in grouped_alerts},
        "market_context_summaries": (
            summary.get("market_context_summaries")
            if isinstance(summary.get("market_context_summaries"), list)
            else []
        ),
        "climo_regime_summaries": (
            summary.get("climo_regime_summaries")
            if isinstance(summary.get("climo_regime_summaries"), list)
            else []
        ),
        "source_gaps": summary.get("source_gaps") if isinstance(summary.get("source_gaps"), list) else [],
    }


def _cached_chengdu_anomaly_alerts(
    cache_key: str,
    *,
    max_age_sec: float,
    stale: bool = False,
    reason: str = "",
) -> Optional[Dict[str, Any]]:
    if max_age_sec <= 0:
        return None
    with _CHENGDU_ANOMALY_ALERT_CACHE_LOCK:
        cached = _CHENGDU_ANOMALY_ALERT_CACHE.get(cache_key)
    if not cached:
        return None
    age = time.time() - float(cached[0] or 0.0)
    if age > float(max_age_sec):
        return None
    payload = copy.deepcopy(cached[1])
    payload["cache_hit"] = True
    payload["cache_age_sec"] = max(0.0, age)
    if stale:
        payload["cache_stale"] = True
        payload["cache_stale_reason"] = reason or "anomaly_alert_cache_stale"
    return payload


def _store_chengdu_anomaly_alerts(cache_key: str, payload: Dict[str, Any]) -> None:
    if not isinstance(payload, dict):
        return
    with _CHENGDU_ANOMALY_ALERT_CACHE_LOCK:
        _CHENGDU_ANOMALY_ALERT_CACHE[cache_key] = (time.time(), copy.deepcopy(payload))
        if len(_CHENGDU_ANOMALY_ALERT_CACHE) > 8:
            oldest_key = min(
                _CHENGDU_ANOMALY_ALERT_CACHE.items(),
                key=lambda item: float((item[1] or (0, {}))[0] or 0.0),
            )[0]
            _CHENGDU_ANOMALY_ALERT_CACHE.pop(oldest_key, None)


def _start_chengdu_anomaly_alert_rebuild(cache_key: str) -> bool:
    if not _CHENGDU_ANOMALY_ALERT_BUILD_LOCK.acquire(blocking=False):
        return False

    def _background() -> None:
        try:
            _store_chengdu_anomaly_alerts(cache_key, _build_chengdu_anomaly_alerts_payload())
        except Exception:
            pass
        finally:
            _CHENGDU_ANOMALY_ALERT_BUILD_LOCK.release()

    threading.Thread(
        target=_background,
        name=f"chengdu_anomaly_alerts:{cache_key}",
        daemon=True,
    ).start()
    return True


def latest_chengdu_anomaly_alerts() -> Dict[str, Any]:
    cache_key = str(WEATHER_ANOMALY_REPORT_DIR)
    fresh = _cached_chengdu_anomaly_alerts(
        cache_key,
        max_age_sec=CHENGDU_ANOMALY_ALERT_CACHE_SEC,
    )
    if fresh:
        return fresh
    stale = _cached_chengdu_anomaly_alerts(
        cache_key,
        max_age_sec=CHENGDU_ANOMALY_ALERT_STALE_CACHE_SEC,
        stale=True,
        reason="anomaly_alert_refresh_started",
    )
    if stale:
        started = _start_chengdu_anomaly_alert_rebuild(cache_key)
        stale["cache_rebuild_started"] = bool(started)
        if not started:
            stale["cache_stale_reason"] = "anomaly_alert_build_in_flight"
            stale["cache_rebuild_in_flight"] = True
        return stale
    if not _CHENGDU_ANOMALY_ALERT_BUILD_LOCK.acquire(blocking=False):
        payload = {
            "ok": False,
            "busy": True,
            "error": "anomaly_alert_build_in_flight",
            "cache_hit": False,
            "updated_at": now_text(),
            "grouped_alerts": [],
            "group_counts": {},
        }
    try:
        payload = _build_chengdu_anomaly_alerts_payload()
        _store_chengdu_anomaly_alerts(cache_key, payload)
        payload["cache_hit"] = False
        return payload
    finally:
        _CHENGDU_ANOMALY_ALERT_BUILD_LOCK.release()


def _chengdu_today_date_key() -> str:
    try:
        return datetime.now(ZoneInfo("Asia/Shanghai")).date().isoformat()
    except Exception:
        return datetime.now(timezone.utc).date().isoformat()


def _prob_pct_from_ssot_value(value: Any) -> Optional[float]:
    val = to_float(value)
    if val is None or not math.isfinite(float(val)):
        return None
    return float(val) * 100.0 if abs(float(val)) <= 1.0 else float(val)


def _bucket_label_from_ssot_row(row: Any) -> str:
    if not isinstance(row, Mapping):
        return ""
    return str(row.get("outcome") or row.get("label") or row.get("bucket") or "").strip()


def _posterior_pct_from_ssot_row(row: Any) -> Optional[float]:
    if not isinstance(row, Mapping):
        return None
    for key in (
        "q_temperature_bucket_posterior",
        "q_bayes_posterior",
        "target_bucket_probability",
        "q_posterior",
        "probability",
    ):
        pct = _prob_pct_from_ssot_value(row.get(key))
        if pct is not None:
            return pct
    for key in (
        "q_temperature_bucket_posterior_pct",
        "q_bayes_posterior_pct",
        "target_bucket_probability_pct",
        "probability_pct",
    ):
        pct = to_float(row.get(key))
        if pct is not None and math.isfinite(float(pct)):
            return float(pct)
    return None


def _ssot_row_is_hard_zero(row: Any) -> bool:
    if not isinstance(row, Mapping):
        return False
    reasons = row.get("posterior_settlement_candidate_bucket_hard_zero_reasons")
    if not isinstance(reasons, list):
        reasons = []
    reason_text = " ".join(str(reason or "").lower() for reason in reasons)
    return bool(
        _truthy(row.get("posterior_settlement_candidate_bucket_hard_zero"))
        or _truthy(row.get("q_posterior_observed_constraints_hard_zero"))
        or _truthy(row.get("q_bayes_physical_likelihood_hard_zero"))
        or _truthy(row.get("hard_zero"))
        or _truthy(row.get("hard_masked"))
        or _truthy(row.get("impossible_by_observed_max"))
        or "observed_today_max_above_bucket" in reason_text
        or "final_bucket_lock" in reason_text
        or "hard_source_final_bucket_lock" in reason_text
    )


def _posterior_ssot_unavailable_reason_for_ui(item: Mapping[str, Any]) -> str:
    if not isinstance(item, Mapping):
        return ""
    if item.get("settlement_actual") not in (None, "", [], {}):
        return ""
    ssot = item.get("posterior_ssot_fact")
    if not isinstance(ssot, Mapping):
        has_posterior_surface = any(
            item.get(key) not in (None, "", [], {})
            for key in (
                "posterior_temperature_distribution",
                "posterior_temperature_distribution_map",
                "distribution",
                "target_bucket",
                "ssot_target_bucket",
                "target_bucket_selection",
                "posterior_target_bucket_selection",
                "target_bucket_outlook",
                "target_realization_capital_plan",
            )
        )
        return "posterior_ssot_fact_missing" if has_posterior_surface else ""
    schema = str(ssot.get("schema") or "").strip()
    state = str(ssot.get("state") or "").strip()
    if schema not in {
        "bayes_posterior_ssot_fact_v1",
        "bayes_posterior_ssot_fact_placeholder_v1",
    } and not state:
        return ""
    label = str(ssot.get("target_bucket") or ssot.get("top_bucket") or ssot.get("selected_bucket") or "").strip()
    probability = _ui_snapshot_prob01_from_value(ssot.get("target_probability"))
    if schema == "bayes_posterior_ssot_fact_v1" and state == "available" and label and probability is not None:
        return ""
    return str(
        ssot.get("state_reason")
        or ssot.get("na_reason")
        or (f"posterior_ssot_fact_{state}" if state else "posterior_ssot_fact_unavailable")
    )


def _suppress_ui_target_fields_when_posterior_ssot_unavailable(item: MutableMapping[str, Any]) -> None:
    if not isinstance(item, MutableMapping):
        return
    reason = _posterior_ssot_unavailable_reason_for_ui(item)
    if not reason:
        return
    for key in (
        "ssot_target_bucket",
        "target_bucket",
        "target_bucket_probability_pct",
        "target_probability_pct",
        "target_probability",
        "target_bucket_probability",
        "target_bucket_selection",
        "posterior_target_bucket_selection",
        "target_bucket_outlook",
        "target_realization_capital_plan",
        "target_switch_context",
        "temperature_path_distribution",
        "posterior_highest_bucket_label",
        "posterior_highest_probability_pct",
    ):
        item.pop(key, None)
    item["target_bucket_source"] = "posterior_ssot_fact.unavailable"
    item["target_bucket_source_semantics"] = "bayes_posterior_ssot_fact_v1"
    item["target_bucket_probability_field"] = "posterior_ssot_fact.target_probability"
    item["target_bucket_na_reason"] = reason
    item["posterior_target_na_reason"] = reason
    summary = item.get("chengdu_intraday_summary")
    if isinstance(summary, MutableMapping):
        for key in (
            "ssot_target_bucket",
            "target_bucket",
            "target_bucket_probability_pct",
            "target_bucket_selection",
            "posterior_target_bucket_selection",
            "target_bucket_outlook",
            "target_realization_capital_plan",
            "target_switch_context",
            "temperature_path_distribution",
            "posterior_highest_bucket_label",
            "posterior_highest_probability_pct",
        ):
            summary.pop(key, None)
        summary["target_bucket_source"] = "posterior_ssot_fact.unavailable"
        summary["target_bucket_source_semantics"] = "bayes_posterior_ssot_fact_v1"
        summary["target_bucket_probability_field"] = "posterior_ssot_fact.target_probability"
        summary["target_bucket_na_reason"] = reason
        summary["posterior_target_na_reason"] = reason


def _ssot_bucket_row_by_label(rows: Any, label: Any) -> Dict[str, Any]:
    wanted = str(label or "").strip()
    if not wanted or not isinstance(rows, list):
        return {}
    for raw in rows:
        if not isinstance(raw, Mapping):
            continue
        if _bucket_label_from_ssot_row(raw) == wanted:
            return dict(raw)
    return {}


def _latest_fact_payload_for_chengdu_intraday_ssot(event_date: str) -> Dict[str, Any]:
    event_key = str(event_date or "").strip()
    if not event_key or not DB_PATH.exists():
        return {}
    try:
        db_key = str(Path(DB_PATH).resolve())
    except Exception:
        db_key = str(DB_PATH)
    cache_key = f"{db_key}:{event_key}"
    now_ts = time.time()
    cached: Optional[Tuple[float, int, Dict[str, Any]]] = None
    with _CHENGDU_INTRADAY_SSOT_PAYLOAD_CACHE_LOCK:
        cached = _CHENGDU_INTRADAY_SSOT_PAYLOAD_CACHE.get(cache_key)
    if cached and (now_ts - float(cached[0] or 0.0)) <= CHENGDU_INTRADAY_SSOT_CACHE_SEC:
        return dict(cached[2] or {})
    try:
        # sqlite3.Connection.__enter__ only manages the transaction; it does
        # not close the connection.  Use the shared read-only context so this
        # hot UI path cannot leak one DB/WAL descriptor per refresh.
        with open_db_ro_fast(timeout_sec=0.08, busy_timeout_ms=0) as conn:
            conn.row_factory = sqlite3.Row
            latest = conn.execute(
                """
                SELECT l.fact_id
                FROM event_fact_latest l
                WHERE l.event_date = ?
                ORDER BY l.updated_at DESC, l.fact_id DESC
                LIMIT 1
                """,
                (event_key,),
            ).fetchone()
            if not latest:
                return {}
            fact_id = int(latest["fact_id"] or 0)
            if cached and int(cached[1] or 0) == fact_id:
                with _CHENGDU_INTRADAY_SSOT_PAYLOAD_CACHE_LOCK:
                    _CHENGDU_INTRADAY_SSOT_PAYLOAD_CACHE[cache_key] = (now_ts, fact_id, dict(cached[2] or {}))
                return dict(cached[2] or {})
            row = conn.execute(
                """
                SELECT h.fact_json
                FROM event_fact_history h
                WHERE h.id = ?
                LIMIT 1
                """,
                (fact_id,),
            ).fetchone()
    except sqlite3.Error:
        if cached:
            return dict(cached[2] or {})
        return {}
    if not row:
        return {}
    try:
        payload = json.loads(row["fact_json"] or "{}")
    except Exception:
        if cached:
            return dict(cached[2] or {})
        return {}
    if not isinstance(payload, dict):
        return dict(cached[2] or {}) if cached else {}
    with _CHENGDU_INTRADAY_SSOT_PAYLOAD_CACHE_LOCK:
        _CHENGDU_INTRADAY_SSOT_PAYLOAD_CACHE[cache_key] = (now_ts, fact_id, dict(payload))
        if len(_CHENGDU_INTRADAY_SSOT_PAYLOAD_CACHE) > 32:
            for old_key, _old_payload in sorted(
                _CHENGDU_INTRADAY_SSOT_PAYLOAD_CACHE.items(),
                key=lambda item: float(item[1][0] or 0.0),
            )[:8]:
                _CHENGDU_INTRADAY_SSOT_PAYLOAD_CACHE.pop(old_key, None)
    return payload


_REPORTED_PHYSICAL_X_SSOT_SCHEMAS = frozenset(
    {
        "sequential_temperature_posterior_ssot_v3_reported_x",
        "sequential_temperature_posterior_ssot_v4_reported_x",
    }
)
_SEQUENTIAL_TEMPERATURE_SSOT_SCHEMAS = frozenset(
    {"sequential_temperature_posterior_ssot_v2", *_REPORTED_PHYSICAL_X_SSOT_SCHEMAS}
)


def _is_reported_physical_x_ssot_schema(value: Any) -> bool:
    return str(value or "").strip() in _REPORTED_PHYSICAL_X_SSOT_SCHEMAS


def _is_sequential_temperature_ssot_schema(value: Any) -> bool:
    return str(value or "").strip() in _SEQUENTIAL_TEMPERATURE_SSOT_SCHEMAS


def _canonical_target_from_fact_payload(payload: Mapping[str, Any]) -> Dict[str, Any]:
    if not isinstance(payload, Mapping):
        return {}

    def valid_target(label_value: Any, row_value: Any = None) -> bool:
        label_text = str(label_value or "").strip()
        if not label_text:
            return False
        return not _ssot_row_is_hard_zero(row_value)

    posterior_ssot = payload.get("posterior_ssot_fact")
    if not isinstance(posterior_ssot, Mapping):
        return {}
    reported_x_schema = _is_reported_physical_x_ssot_schema(posterior_ssot.get("schema"))
    market_rows_value = posterior_ssot.get("market_bucket_probabilities")
    if reported_x_schema and not market_rows_value:
        # X is a physical whole-degree posterior.  Only the approved X->S->B
        # bridge may create a market target; the UI must never infer B from an
        # observed temperature, X lower bound, or the X distribution itself.
        return {}
    state = str(posterior_ssot.get("state") or "").strip()
    label = str(
        posterior_ssot.get("target_bucket")
        or posterior_ssot.get("top_bucket")
        or posterior_ssot.get("selected_bucket")
        or ""
    ).strip()
    prob = _ui_snapshot_prob01_from_value(posterior_ssot.get("target_probability"))
    prob_pct = float(prob) * 100.0 if prob is not None else _prob_pct_from_ssot_value(
        posterior_ssot.get("target_probability_pct")
    )
    target_rows = (
        _compact_posterior_ssot_bucket_rows_for_ui_snapshot(market_rows_value, limit=12)
        if reported_x_schema
        else payload.get("distribution") if isinstance(payload.get("distribution"), list) else []
    )
    target_distribution_row = _ssot_bucket_row_by_label(target_rows, label)
    if label and (not state or state == "available") and valid_target(label, target_distribution_row):
        ranked_rows = _compact_posterior_ssot_bucket_rows_for_ui_snapshot(
            market_rows_value
            if reported_x_schema
            else posterior_ssot.get("bucket_probabilities")
            or posterior_ssot.get("ranked_bucket_probabilities"),
            limit=12,
        )
        ranked_rows = _sorted_posterior_ssot_bucket_rows_for_ui_snapshot(ranked_rows, limit=12)
        if not ranked_rows and prob is not None:
            ranked_rows = [
                {
                    "outcome": label,
                    "probability": float(prob),
                    "probability_pct": float(prob) * 100.0,
                    "posterior_field": "posterior_ssot_fact.target_probability",
                }
            ]
        second_row = next(
            (
                row
                for row in ranked_rows
                if str(row.get("outcome") or row.get("label") or row.get("bucket") or "").strip()
                and str(row.get("outcome") or row.get("label") or row.get("bucket") or "").strip() != label
                and valid_target(
                    str(row.get("outcome") or row.get("label") or row.get("bucket") or "").strip(),
                    row,
                )
                and (_ui_snapshot_prob01_from_value(row.get("probability")) or 0.0) > 0.0
            ),
            None,
        )
        second_label = (
            str(
                second_row.get("outcome")
                or second_row.get("label")
                or second_row.get("bucket")
                or ""
            ).strip()
            if isinstance(second_row, Mapping)
            else ""
        )
        second_prob = (
            _ui_snapshot_prob01_from_value(second_row.get("probability"))
            if isinstance(second_row, Mapping)
            else None
        )
        target_row = next(
            (
                row
                for row in ranked_rows
                if str(row.get("outcome") or row.get("label") or row.get("bucket") or "").strip() == label
            ),
            ranked_rows[0] if ranked_rows else {},
        )
        return {
            "label": label,
            "prob_pct": prob_pct,
            "prob": prob,
            "row": dict(target_row) if isinstance(target_row, Mapping) else {},
            "second_label": second_label,
            "second_prob_pct": float(second_prob) * 100.0 if second_prob is not None else None,
            "second_prob": second_prob,
            "probability_field": str(
                posterior_ssot.get("target_probability_field")
                or "posterior_ssot_fact.target_probability"
            ),
            "source": "posterior_ssot_fact.top_bucket",
            "ranked_rows": ranked_rows,
        }
    return {}


def _align_chengdu_summary_to_latest_fact_ssot(summary: Any) -> Dict[str, Any]:
    if not isinstance(summary, Mapping):
        return {}
    out = dict(summary)
    event_date = str(out.get("event_date") or "").strip()
    if not event_date:
        return out
    fact_payload = _latest_fact_payload_for_chengdu_intraday_ssot(event_date)
    _overlay_latest_fact_observation_fields(out, fact_payload)
    canonical = _canonical_target_from_fact_payload(fact_payload)
    label = str(canonical.get("label") or "").strip()
    if not label:
        return out
    prob_pct = canonical.get("prob_pct")
    prob = canonical.get("prob")
    probability_field = str(canonical.get("probability_field") or "event_fact_latest.canonical_target").strip()
    source = str(canonical.get("source") or "event_fact_latest.canonical_target").strip()
    second_label = str(canonical.get("second_label") or "").strip()
    second_prob_pct = canonical.get("second_prob_pct")
    second_prob = canonical.get("second_prob")
    target_row = canonical.get("row") if isinstance(canonical.get("row"), Mapping) else {}
    watch_rows = canonical.get("ranked_rows") if isinstance(canonical.get("ranked_rows"), list) else []

    out["ssot_target_bucket"] = label
    out["target_bucket"] = label
    out["target_bucket_source"] = source
    out["target_bucket_source_semantics"] = "single_event_fact_latest_canonical_target_v1"
    out["target_bucket_probability_field"] = probability_field
    out["posterior_highest_bucket_label"] = label
    if prob_pct is not None and math.isfinite(float(prob_pct)):
        out["target_bucket_probability_pct"] = float(prob_pct)
        out["posterior_highest_probability_pct"] = float(prob_pct)

    if isinstance(fact_payload.get("distribution"), list):
        fact_distribution_rows = [
            dict(row) for row in fact_payload.get("distribution") if isinstance(row, Mapping)
        ]
        out["bucket_probabilities"] = fact_distribution_rows
        if isinstance(summary.get("distribution"), list) or isinstance(summary.get("rows"), list):
            out["distribution"] = [dict(row) for row in fact_distribution_rows]

    selection = dict(out.get("target_bucket_selection") or {}) if isinstance(out.get("target_bucket_selection"), Mapping) else {}
    fact_selection = fact_payload.get("target_bucket_selection")
    if isinstance(fact_selection, Mapping):
        selection = {**dict(fact_selection), **selection}
    selection.update(
        {
            "target_bucket": label,
            "ssot_source": "event_fact_latest",
            "target_bucket_selection_source": source,
            "selection_priority": source,
            "target_selection_priority_version": "single_event_fact_latest_canonical_target_v1",
            "target_probability_field": probability_field,
            "target_row": dict(target_row) if target_row else selection.get("target_row"),
            "watch_buckets": [dict(row) for row in watch_rows] if watch_rows else selection.get("watch_buckets"),
            "selection_runtime_recomputed": False,
        }
    )
    if prob_pct is not None and math.isfinite(float(prob_pct)):
        selection["target_probability_pct"] = float(prob_pct)
        selection["target_bucket_probability_pct"] = float(prob_pct)
        selection["target_probability"] = float(prob_pct) / 100.0
        selection["target_bucket_probability"] = float(prob_pct) / 100.0
    if second_label:
        selection["second_target_bucket"] = second_label
    if second_prob_pct is not None and math.isfinite(float(second_prob_pct)):
        selection["second_target_probability_pct"] = float(second_prob_pct)
        selection["second_target_probability"] = float(second_prob_pct) / 100.0
    out["target_bucket_selection"] = selection
    out["posterior_target_bucket_selection"] = dict(selection)

    outlook = dict(out.get("target_bucket_outlook") or {}) if isinstance(out.get("target_bucket_outlook"), Mapping) else {}
    fact_outlook = fact_payload.get("target_bucket_outlook")
    if isinstance(fact_outlook, Mapping):
        outlook = {**dict(fact_outlook), **outlook}
    outlook.update(
        {
            "available": True,
            "target_bucket": label,
            "final_bucket": label,
            "posterior_final_bucket": label,
            "cumulative_posterior_final_bucket": label,
            "target_bucket_source": source,
            "source": source,
            "probability_source": probability_field,
            "target_probability_source": probability_field,
            "constraint_source": source,
            "ssot_source": "event_fact_latest",
        }
    )
    if prob_pct is not None and math.isfinite(float(prob_pct)):
        for key in (
            "target_bucket_probability_pct",
            "target_final_probability_pct",
            "final_bucket_probability_pct",
            "posterior_final_bucket_probability_pct",
            "cumulative_posterior_final_bucket_probability_pct",
        ):
            outlook[key] = float(prob_pct)
    if second_label:
        outlook["second_target_bucket"] = second_label
    out["target_bucket_outlook"] = _normalize_target_bucket_outlook_display_contract(
        outlook,
        out.get("temperature_path_distribution") or fact_payload.get("temperature_path_distribution"),
    )

    fact_plan = fact_payload.get("target_realization_capital_plan")
    capital_plan = dict(fact_plan) if isinstance(fact_plan, Mapping) else (
        dict(out.get("target_realization_capital_plan") or {})
        if isinstance(out.get("target_realization_capital_plan"), Mapping)
        else {}
    )
    if capital_plan:
        capital_plan.update(
            {
                "target_bucket": label,
                "target_bucket_selection_source": source,
                "source": "event_fact_latest",
                "ssot_source": "event_fact_latest",
                "ssot_aligned_to_event_fact_latest": True,
            }
        )
        if prob is not None and math.isfinite(float(prob)):
            capital_plan["target_posterior"] = float(prob)
        if second_label:
            capital_plan["second_target_bucket"] = second_label
        if second_prob is not None and math.isfinite(float(second_prob)):
            capital_plan["second_target_posterior"] = float(second_prob)
        out["target_realization_capital_plan"] = capital_plan

    decision = dict(out.get("decision") or {}) if isinstance(out.get("decision"), Mapping) else {}
    raw_plan = decision.get("target_realization_trade_plan")
    trade_plan = dict(raw_plan) if isinstance(raw_plan, Mapping) else {}
    if capital_plan:
        trade_plan = {**capital_plan, **trade_plan}
    trade_plan.update(
        {
            "target_bucket": label,
            "target_bucket_selection_source": source,
            "source": "event_fact_latest",
            "ssot_source": "event_fact_latest",
            "ssot_aligned_to_event_fact_latest": True,
        }
    )
    if prob is not None and math.isfinite(float(prob)):
        trade_plan["target_posterior"] = float(prob)
    if second_label:
        trade_plan["second_target_bucket"] = second_label
    if second_prob is not None and math.isfinite(float(second_prob)):
        trade_plan["second_target_posterior"] = float(second_prob)
    decision["target_realization_trade_plan"] = trade_plan
    decision["target_bucket"] = label
    if prob is not None and math.isfinite(float(prob)):
        decision["target_posterior"] = float(prob)
    out["decision"] = decision

    path_dist = dict(out.get("temperature_path_distribution") or {}) if isinstance(out.get("temperature_path_distribution"), Mapping) else {}
    if path_dist:
        path_dist["target_bucket"] = label
        path_dist["target_bucket_posterior_field"] = probability_field
        path_dist["posterior_source"] = source
        path_dist["posterior_aligned_to_distribution"] = True
        path_dist["posterior_aligned_to_event_fact_latest"] = True
        if prob is not None and math.isfinite(float(prob)):
            path_dist["target_bucket_posterior"] = float(prob)
            path_dist["target_bucket_posterior_pct"] = float(prob) * 100.0
        if second_label:
            path_dist["second_target_bucket"] = second_label
        if second_prob is not None and math.isfinite(float(second_prob)):
            path_dist["second_target_bucket_posterior"] = float(second_prob)
            path_dist["second_target_bucket_posterior_pct"] = float(second_prob) * 100.0
        out["temperature_path_distribution"] = path_dist

    out["single_ssot_target_alignment"] = {
        "version": "single_event_fact_latest_canonical_target_v1",
        "source": source,
        "target_bucket": label,
        "target_probability_pct": float(prob_pct) if prob_pct is not None and math.isfinite(float(prob_pct)) else None,
        "aligned_fields": [
            "target_bucket",
            "posterior_highest_bucket_label",
            "target_bucket_selection",
            "posterior_target_bucket_selection",
            "target_bucket_outlook",
            "target_realization_capital_plan",
            "decision.target_realization_trade_plan",
            "temperature_path_distribution",
        ],
    }
    return out


def _overlay_latest_fact_observation_fields(out: Dict[str, Any], fact_payload: Mapping[str, Any]) -> None:
    if not isinstance(out, dict) or not isinstance(fact_payload, Mapping):
        return

    def _mapping_value(key: str) -> Dict[str, Any]:
        raw = fact_payload.get(key)
        if isinstance(raw, Mapping) and raw:
            return dict(raw)
        summary = fact_payload.get("chengdu_intraday_summary")
        if isinstance(summary, Mapping):
            raw = summary.get(key)
            if isinstance(raw, Mapping) and raw:
                return dict(raw)
        return {}

    latest_features = fact_payload.get("weather_likelihood_features_compact")
    if not isinstance(latest_features, Mapping):
        latest_features = _compact_weather_likelihood_features_for_ui(
            fact_payload.get("weather_likelihood_features")
        )
    if isinstance(latest_features, Mapping) and latest_features:
        existing_features = (
            dict(out.get("weather_likelihood_features_compact") or {})
            if isinstance(out.get("weather_likelihood_features_compact"), Mapping)
            else {}
        )
        for key, value in latest_features.items():
            if value not in (None, "", [], {}):
                existing_features[key] = value
        out["weather_likelihood_features_compact"] = _normalize_ui_temperature_rise_rate_fields(
            existing_features
        )

    for key in (
        "fact_snapshot_id",
        "posterior_run_id",
        "correlation_id",
        "source_event_id",
        "source_event_ids",
        "source_observation_id",
        "source_observation_ids",
        "lineage_state",
        "source_observations",
        "source_acquisition_trace",
        "source_to_posterior_timing",
        "v6_execution_deadline_timing",
        "amsc_latency_slo_audit",
        "signal_to_order_timing",
        "hard_source_acceptance_state",
        "signal_id",
        "decision_id",
        "order_intent_id",
        "review_id",
    ):
        value = fact_payload.get(key)
        if out.get(key) in (None, "", [], {}) and value not in (None, "", [], {}):
            out[key] = copy.deepcopy(value)

    nested_summary = (
        dict(out.get("chengdu_intraday_summary") or {})
        if isinstance(out.get("chengdu_intraday_summary"), Mapping)
        else None
    )
    for key in (
        "key_metrics",
        "temperature_trajectory_status",
        "temperature_path_distribution",
        "temperature_realization_reliability",
        "source_observation_comparison",
        "target_bucket_observation_state",
        "physical_likelihood",
        "physical_weather_modifier",
        "forecast_reference_bayes",
        "observation_led_bayes",
        "settlement_lock_bayes",
        "recoil_state_ssot",
        "physical_cutoff_evidence",
        "termination_risk",
        "amsc_latency_slo_audit",
    ):
        value = _mapping_value(key)
        if not value:
            continue
        out[key] = value
        if nested_summary is not None:
            nested_summary[key] = dict(value)
    if nested_summary is not None:
        out["chengdu_intraday_summary"] = nested_summary
    _sync_ui_snapshot_amsc_observation_ssot_fields(out, source_payload=fact_payload)
    out["latest_fact_observation_overlay_source"] = "event_fact_latest"


def _ui_snapshot_latest_fact_needs_posterior_projection(payload: Mapping[str, Any]) -> bool:
    if not isinstance(payload, Mapping):
        return False
    ssot = payload.get("posterior_ssot_fact")
    # A sequential production SSOT must never be fed through the retired v3.1
    # projection path.  v2 is retained only as an explicit legacy-latent NA;
    # v3 is the report-defined integer-X authority.
    if (
        isinstance(ssot, Mapping)
        and _is_sequential_temperature_ssot_schema(ssot.get("schema"))
        and str(ssot.get("writer_mode") or "").strip() == "production"
        and str(ssot.get("state") or "").strip() in {
            "available",
            "physical_only_market_projection_na",
        }
    ):
        return False
    ssot_available = isinstance(ssot, Mapping) and str(ssot.get("state") or "") == "available"
    production_model_family = (
        str(ssot.get("production_model_family") or "").strip()
        if isinstance(ssot, Mapping)
        else ""
    )
    production_probability_policy = (
        str(ssot.get("production_probability_policy") or "").strip()
        if isinstance(ssot, Mapping)
        else ""
    )
    prior_meta = payload.get("prior_meta")
    prior_source = (
        str(prior_meta.get("source") or "").strip()
        if isinstance(prior_meta, Mapping)
        else ""
    )
    prior_settlement_s_used = (
        prior_meta.get("settlement_s_used")
        if isinstance(prior_meta, Mapping)
        else None
    )
    unique_model_ready = bool(
        production_model_family == "joint_weak_physical_strong"
        and production_probability_policy == "unique_joint_weak_physical_strong_only_fail_closed"
    )
    physical_x_prior_ready = bool(
        prior_source == "approved_ncei_ghcnh_hourly_climate_reference_prior"
        and prior_settlement_s_used is False
    )
    has_prior = isinstance(payload.get("prior_distribution"), Mapping) and bool(payload.get("prior_distribution"))
    has_strong = isinstance(payload.get("metar_strong_likelihood"), Mapping) and bool(payload.get("metar_strong_likelihood"))
    has_rows = bool(payload.get("posterior_temperature_distribution") or payload.get("distribution") or payload.get("rows"))
    has_sources = bool(payload.get("source_observations")) or bool(
        isinstance(payload.get("source_acquisition_trace"), Mapping)
        and payload.get("source_acquisition_trace", {}).get("source_observations")
    )
    return bool(
        (has_sources or has_rows)
        and (
            not ssot_available
            or not unique_model_ready
            or not physical_x_prior_ready
            or not has_prior
            or not has_strong
            or not has_rows
        )
    )


def _ui_snapshot_project_latest_fact_payload_no_apply(
    conn: sqlite3.Connection,
    *,
    fact_id: Any,
    slug: str,
    event_date: str,
    run_date: str,
    fact_as_of: str,
    composer_version: str,
    payload: Mapping[str, Any],
) -> Tuple[Dict[str, Any], Dict[str, Any]]:
    if not _ui_snapshot_latest_fact_needs_posterior_projection(payload):
        return dict(payload), {}
    try:
        from posterior_ssot_projection_runtime import build_fact_projection_no_apply

        projection = build_fact_projection_no_apply(
            slug=str(slug or payload.get("slug") or ""),
            event_date=str(event_date or payload.get("event_date") or ""),
            run_date=str(run_date or payload.get("run_date") or event_date or ""),
            fact_as_of=str(fact_as_of or payload.get("fact_as_of") or ""),
            payload=payload,
            current_fact_id=int(fact_id or 0),
            current_fact_as_of=str(fact_as_of or ""),
            composer_version=str(composer_version or ""),
            conn=conn,
            write_reason="ui_snapshot_latest_fact_projection_no_apply",
        )
    except Exception as exc:
        return dict(payload), {
            "schema": "ui_snapshot_latest_fact_projection_v1",
            "state": "projection_error",
            "error": str(exc)[:160],
            "read_only": True,
        }
    projected = projection.get("projected_payload")
    if not isinstance(projected, Mapping) or not projected:
        return dict(payload), {
            "schema": "ui_snapshot_latest_fact_projection_v1",
            "state": "projection_unavailable",
            "projection_mode": str(projection.get("projection_mode") or ""),
            "issues": list(projection.get("issues") or []),
            "read_only": True,
        }
    return dict(projected), {
        "schema": "ui_snapshot_latest_fact_projection_v1",
        "state": "available",
        "projection_mode": str(projection.get("projection_mode") or ""),
        "context": dict(projection.get("context") or {}),
        "issues": list(projection.get("issues") or []),
        "read_only": True,
        "writes_archive_db": False,
        "places_orders": False,
    }


