def _fact_backed_chengdu_intraday_summary_fallback(key: str, payload: Mapping[str, Any]) -> Dict[str, Any]:
    base = dict(payload or {})
    base["event_date"] = str(base.get("event_date") or key or "").strip()
    aligned = _align_chengdu_summary_to_latest_fact_ssot(base)
    if aligned.get("single_ssot_target_alignment"):
        aligned["ok"] = True
        aligned["summary_partial"] = True
        aligned["summary_partial_reason"] = str(base.get("error") or base.get("cache_stale_reason") or "summary_cache_cold")
        aligned["source"] = "event_fact_latest_fast_fallback"
        aligned["ssot"] = "/api/chengdu-intraday-summary"
    return aligned


def _cached_chengdu_intraday_summary(
    key: str,
    *,
    max_age_sec: float,
    stale: bool = False,
    reason: str = "",
) -> Optional[Dict[str, Any]]:
    if max_age_sec <= 0:
        return None
    with _CHENGDU_INTRADAY_SUMMARY_CACHE_LOCK:
        cached = _CHENGDU_INTRADAY_SUMMARY_CACHE.get(key)
    if not cached:
        return None
    age = time.time() - float(cached[0] or 0.0)
    if age > float(max_age_sec):
        return None
    payload = _align_chengdu_summary_to_latest_fact_ssot(cached[1])
    payload["cache_hit"] = True
    if stale:
        payload["cache_stale"] = True
        payload["cache_stale_age_sec"] = max(0.0, age)
        payload["cache_stale_reason"] = reason or "summary_cache_stale"
    return payload


def _build_and_store_chengdu_intraday_summary(key: str) -> Dict[str, Any]:
    payload = _align_chengdu_summary_to_latest_fact_ssot(
        build_chengdu_intraday_summary(DB_PATH, event_date=key)
    )
    if payload.get("ok"):
        with _CHENGDU_INTRADAY_SUMMARY_CACHE_LOCK:
            _CHENGDU_INTRADAY_SUMMARY_CACHE[key] = (time.time(), dict(payload))
        payload["cache_hit"] = False
    return payload


def _start_chengdu_intraday_summary_rebuild(key: str) -> bool:
    if not _CHENGDU_INTRADAY_SUMMARY_BUILD_LOCK.acquire(blocking=False):
        return False

    def _background() -> None:
        try:
            _build_and_store_chengdu_intraday_summary(key)
        except Exception:
            pass
        finally:
            _CHENGDU_INTRADAY_SUMMARY_BUILD_LOCK.release()

    threading.Thread(
        target=_background,
        name=f"chengdu_intraday_summary:{key}",
        daemon=True,
    ).start()
    return True


def _chengdu_intraday_summary_revalidate_allowed(key: str) -> bool:
    interval = float(CHENGDU_INTRADAY_SUMMARY_REVALIDATE_MIN_INTERVAL_SEC or 0.0)
    if interval <= 0:
        return True
    now_ts = time.time()
    with _CHENGDU_INTRADAY_SUMMARY_REVALIDATE_LOCK:
        last_ts = float(_CHENGDU_INTRADAY_SUMMARY_REVALIDATE_LAST.get(key) or 0.0)
        if last_ts and (now_ts - last_ts) < interval:
            return False
        _CHENGDU_INTRADAY_SUMMARY_REVALIDATE_LAST[key] = now_ts
        if len(_CHENGDU_INTRADAY_SUMMARY_REVALIDATE_LAST) > 128:
            for old_key, _old_ts in sorted(
                _CHENGDU_INTRADAY_SUMMARY_REVALIDATE_LAST.items(),
                key=lambda item: float(item[1] or 0.0),
            )[:32]:
                _CHENGDU_INTRADAY_SUMMARY_REVALIDATE_LAST.pop(old_key, None)
        return True


def latest_chengdu_intraday_summary(event_date: str = "") -> Dict[str, Any]:
    key = str(event_date or "").strip() or _chengdu_today_date_key()
    fresh = _cached_chengdu_intraday_summary(
        key,
        max_age_sec=CHENGDU_INTRADAY_SUMMARY_CACHE_SEC,
    )
    if fresh:
        return fresh

    stale = _cached_chengdu_intraday_summary(
        key,
        max_age_sec=CHENGDU_INTRADAY_SUMMARY_STALE_CACHE_SEC,
        stale=True,
        reason="summary_refresh_started",
    )
    if stale:
        if not _chengdu_intraday_summary_revalidate_allowed(key):
            stale["cache_stale_reason"] = "summary_revalidate_throttled"
            stale["cache_rebuild_started"] = False
        elif not _start_chengdu_intraday_summary_rebuild(key):
            stale["cache_stale_reason"] = "summary_build_in_flight"
            stale["cache_rebuild_in_flight"] = True
        else:
            stale["cache_rebuild_started"] = True
        return stale

    build_acquired = _CHENGDU_INTRADAY_SUMMARY_BUILD_LOCK.acquire(blocking=False)
    if not build_acquired:
        in_flight_stale = _cached_chengdu_intraday_summary(
            key,
            max_age_sec=CHENGDU_INTRADAY_SUMMARY_STALE_CACHE_SEC,
            stale=True,
            reason="summary_build_in_flight",
        )
        if in_flight_stale:
            return in_flight_stale
        return _fact_backed_chengdu_intraday_summary_fallback(key, {
            "ok": False,
            "error": "summary_build_in_flight",
            "event_date": key,
            "cache_hit": False,
            "busy": True,
        })
    try:
        fresh = _cached_chengdu_intraday_summary(
            key,
            max_age_sec=CHENGDU_INTRADAY_SUMMARY_CACHE_SEC,
        )
        if fresh:
            return fresh
        payload = _build_and_store_chengdu_intraday_summary(key)
        if payload.get("ok"):
            return payload
        fallback = _cached_chengdu_intraday_summary(
            key,
            max_age_sec=CHENGDU_INTRADAY_SUMMARY_STALE_CACHE_SEC,
            stale=True,
            reason=str(payload.get("error") or "latest_summary_unavailable"),
        )
        return fallback or _fact_backed_chengdu_intraday_summary_fallback(key, payload)
    finally:
        _CHENGDU_INTRADAY_SUMMARY_BUILD_LOCK.release()


def latest_chengdu_intraday_summary_nonblocking(event_date: str = "", *, compact: bool = True) -> Dict[str, Any]:
    key = str(event_date or "").strip() or _chengdu_today_date_key()
    fresh = _cached_chengdu_intraday_summary(
        key,
        max_age_sec=CHENGDU_INTRADAY_SUMMARY_CACHE_SEC,
    )
    if fresh:
        return _compact_chengdu_intraday_summary_for_endpoint(fresh) if compact else fresh
    stale = _cached_chengdu_intraday_summary(
        key,
        max_age_sec=CHENGDU_INTRADAY_SUMMARY_STALE_CACHE_SEC,
        stale=True,
        reason="summary_refresh_started",
    )
    if stale:
        started = False
        revalidate_allowed = _chengdu_intraday_summary_revalidate_allowed(key)
        if revalidate_allowed:
            started = _start_chengdu_intraday_summary_rebuild(key)
        stale["cache_rebuild_started"] = bool(started)
        if not revalidate_allowed:
            stale["cache_stale_reason"] = "summary_revalidate_throttled"
        elif not started:
            stale["cache_stale_reason"] = "summary_build_in_flight"
            stale["cache_rebuild_in_flight"] = True
        return _compact_chengdu_intraday_summary_for_endpoint(stale) if compact else stale
    started = _start_chengdu_intraday_summary_rebuild(key)
    payload = {
        "ok": False,
        "event_date": key,
        "error": "summary_build_started" if started else "summary_build_in_flight",
        "busy": True,
        "cache_hit": False,
        "cache_rebuild_started": bool(started),
        "cache_rebuild_in_flight": not bool(started),
    }
    payload = _fact_backed_chengdu_intraday_summary_fallback(key, payload)
    return _compact_chengdu_intraday_summary_for_endpoint(payload) if compact else payload


def _latest_chengdu_intraday_summary_for_ui_snapshot(event_date: str = "") -> Dict[str, Any]:
    key = str(event_date or "").strip() or _chengdu_today_date_key()
    fresh = _cached_chengdu_intraday_summary(
        key,
        max_age_sec=UI_SNAPSHOT_CHENGDU_INTRADAY_CACHE_SEC,
    )
    if fresh:
        fresh["cache_scope"] = "ui_snapshot"
        return fresh
    stale = _cached_chengdu_intraday_summary(
        key,
        max_age_sec=CHENGDU_INTRADAY_SUMMARY_STALE_CACHE_SEC,
        stale=True,
        reason="ui_snapshot_nonblocking_stale",
    )
    if stale:
        stale["cache_scope"] = "ui_snapshot"
        if not _chengdu_intraday_summary_revalidate_allowed(key):
            stale["cache_stale_reason"] = "summary_revalidate_throttled"
            stale["cache_rebuild_started"] = False
        elif not _start_chengdu_intraday_summary_rebuild(key):
            stale["cache_stale_reason"] = "summary_build_in_flight"
            stale["cache_rebuild_in_flight"] = True
        else:
            stale["cache_rebuild_started"] = True
        return stale
    _start_chengdu_intraday_summary_rebuild(key)
    return {}


def _chengdu_physical_component_path_probability_scale(delta_c: Any) -> Optional[float]:
    delta = _to_float_safe(delta_c)
    if delta is None:
        return None
    if delta < 0:
        scale = max(0.65, 1.0 + delta * 0.22)
    elif delta > 0:
        scale = min(1.10, 1.0 + delta * 0.10)
    else:
        scale = 1.0
    return round(scale, 3)


def _fill_chengdu_physical_weather_component_scales(modifier: Any) -> Any:
    if not isinstance(modifier, Mapping):
        return modifier
    out = dict(modifier)
    components = out.get("components")
    if not isinstance(components, list):
        return out
    filled_components: List[Any] = []
    for component in components:
        if not isinstance(component, Mapping):
            filled_components.append(component)
            continue
        row = dict(component)
        if row.get("path_probability_scale") in (None, ""):
            scale = _chengdu_physical_component_path_probability_scale(row.get("peak_mu_delta_c"))
            if scale is not None:
                row["path_probability_scale"] = scale
        filled_components.append(row)
    out["components"] = filled_components
    return out


def _is_chengdu_zuuu_ui_snapshot_item(row: sqlite3.Row, payload: Mapping[str, Any]) -> bool:
    def row_get(key: str) -> Any:
        try:
            return row[key]
        except (IndexError, KeyError, TypeError):
            return None

    slug = str(row_get("slug") or payload.get("slug") or "").strip().lower()
    title = str(row_get("title") or payload.get("title") or "").strip().lower()
    city = str(row_get("city") or payload.get("city") or "").strip().lower()
    station = str(row_get("station_id") or payload.get("station_id") or "").strip().upper()
    source = str(row_get("resolution_source") or payload.get("resolution_source") or "").strip().lower()
    return bool(
        station == "ZUUU"
        or "chengdu" in slug
        or "chengdu" in title
        or city == "chengdu"
        or "/cn/chengdu/" in source
    )


def _compact_chengdu_intraday_summary_for_ui_snapshot(summary: Any) -> Optional[Dict[str, Any]]:
    if not isinstance(summary, Mapping):
        return None
    compact = _compact_chengdu_intraday_summary_for_endpoint(summary)
    if not compact:
        return None
    if isinstance(compact.get("target_bucket_outlook"), Mapping):
        compact["target_bucket_outlook"] = _normalize_target_bucket_outlook_display_contract(
            compact.get("target_bucket_outlook"),
            compact.get("temperature_path_distribution"),
        )
    if isinstance(compact.get("physical_weather_modifier"), Mapping):
        compact["physical_weather_modifier"] = _fill_chengdu_physical_weather_component_scales(
            compact.get("physical_weather_modifier")
        )
    if isinstance(compact.get("physical_likelihood"), Mapping):
        physical_likelihood = dict(compact.get("physical_likelihood") or {})
        if isinstance(physical_likelihood.get("weather_modifier"), Mapping):
            physical_likelihood["weather_modifier"] = _fill_chengdu_physical_weather_component_scales(
                physical_likelihood.get("weather_modifier")
            )
            compact["physical_likelihood"] = physical_likelihood
    compact["source"] = "chengdu_intraday_summary_ssot"
    compact["ssot"] = "/api/ui_snapshot"
    return compact


