def _compact_intraday_distribution_row_for_endpoint(row: Any) -> Dict[str, Any]:
    if not isinstance(row, Mapping):
        return {}
    out: Dict[str, Any] = {}
    for key, value in row.items():
        if value in (None, ""):
            continue
        key_s = str(key)
        if key_s not in _CHENGDU_INTRADAY_ENDPOINT_ROW_KEYS:
            continue
        if isinstance(value, (str, int, float, bool)):
            out[key_s] = value
        elif isinstance(value, list) and key_s.endswith("reason_codes"):
            reason_codes = [
                str(item)
                for item in value
                if item not in (None, "")
            ][:8]
            if reason_codes:
                out[key_s] = reason_codes
    compact_chain = _compact_bayes_chain_for_bucket_series(row)
    if compact_chain and (
        compact_chain.get("schema") == "hierarchical_layer_contributions_chain_v1"
        or compact_chain.get("prior_prob") is not None
        or compact_chain.get("likelihood_prob") is not None
    ):
        out["bayes_chain"] = compact_chain
        if compact_chain.get("prior_prob") is not None:
            out.setdefault("q_prior", compact_chain.get("prior_prob"))
        if compact_chain.get("likelihood_prob") is not None:
            out.setdefault("q_likelihood", compact_chain.get("likelihood_prob"))
    _align_compact_row_to_temperature_posterior_ssot(out)
    return out


def _align_compact_row_to_temperature_posterior_ssot(row: MutableMapping[str, Any]) -> None:
    if not isinstance(row, MutableMapping):
        return
    temp_prob = to_float(row.get("q_temperature_bucket_posterior"))
    if temp_prob is None:
        temp_pct = to_float(row.get("q_temperature_bucket_posterior_pct"))
        if temp_pct is not None and math.isfinite(float(temp_pct)):
            temp_prob = float(temp_pct) / 100.0
    if temp_prob is None or not math.isfinite(float(temp_prob)):
        return
    temp_prob = max(0.0, min(1.0, float(temp_prob) / 100.0 if float(temp_prob) > 1.0 else float(temp_prob)))
    row["q_temperature_bucket_posterior"] = temp_prob
    row["q_temperature_bucket_posterior_pct"] = temp_prob * 100.0

    for key in ("q_bayes_posterior", "q_contract_payout_posterior"):
        old_prob = to_float(row.get(key))
        if old_prob is not None and math.isfinite(float(old_prob)):
            old_norm = float(old_prob) / 100.0 if float(old_prob) > 1.0 else float(old_prob)
            if abs(old_norm - temp_prob) > 1e-12:
                row[f"{key}_pre_ssot_display_alignment"] = old_norm
        row[key] = temp_prob
        row[f"{key}_pct"] = temp_prob * 100.0
    row["q_bayes_posterior_no"] = max(0.0, min(1.0, 1.0 - temp_prob))
    row["posterior_ssot_display_aligned"] = True
    row["posterior_ssot_display_source"] = "q_temperature_bucket_posterior"


def _compact_intraday_distribution_rows_for_endpoint(rows: Any, *, limit: int = 8) -> List[Dict[str, Any]]:
    if not isinstance(rows, list):
        return []
    out: List[Dict[str, Any]] = []
    for row in rows[: max(0, int(limit or 0))]:
        compact = _compact_intraday_distribution_row_for_endpoint(row)
        if compact:
            out.append(compact)
    return out


def _compact_intraday_mapping_for_endpoint(
    value: Any,
    *,
    nested_keys: Optional[Set[str]] = None,
    row_keys: Optional[Set[str]] = None,
) -> Dict[str, Any]:
    if not isinstance(value, Mapping):
        return {}
    nested = nested_keys or set()
    row_fields = row_keys or set()
    out: Dict[str, Any] = {}
    for key, raw in value.items():
        if raw in (None, "", [], {}):
            continue
        key_s = str(key)
        if isinstance(raw, (str, int, float, bool)):
            out[key_s] = raw
        elif isinstance(raw, list):
            if key_s in row_fields:
                row_limit = 16 if key_s == "bucket_distribution" else 8
                rows = _compact_intraday_distribution_rows_for_endpoint(raw, limit=row_limit)
                if rows:
                    out[key_s] = rows
            elif all(isinstance(item, (str, int, float, bool)) for item in raw):
                out[key_s] = list(raw[:16])
            elif key_s in nested:
                nested_rows = [
                    _compact_intraday_mapping_for_endpoint(item)
                    for item in raw[:4]
                    if isinstance(item, Mapping)
                ]
                nested_rows = [item for item in nested_rows if item]
                if nested_rows:
                    out[key_s] = nested_rows
        elif isinstance(raw, Mapping):
            if key_s in row_fields:
                compact_row = _compact_intraday_distribution_row_for_endpoint(raw)
                if compact_row:
                    out[key_s] = compact_row
            elif key_s in nested:
                nested_map = _compact_intraday_mapping_for_endpoint(raw)
                if nested_map:
                    out[key_s] = nested_map
    return out


def _compact_temperature_regime_v1_for_endpoint(value: Any) -> Dict[str, Any]:
    if not isinstance(value, Mapping):
        return {}
    out: Dict[str, Any] = {}
    scalar_keys = (
        "enabled",
        "available",
        "source",
        "na_reason",
        "status",
        "group",
        "role",
        "source_class",
        "dedupe_policy",
        "regime_model_status",
        "rate_hat",
        "accel_hat",
        "rate_hat_c_per_hour",
        "accel_hat_c_per_hour2",
        "curvature_confidence",
        "path_realization_scale",
        "path_aggregation",
        "path_draw_count",
        "path_mu_c",
        "mean_c",
        "path_p90_c",
        "path_upper_candidate_c",
        "path_sigma_c",
        "sigma_c",
        "kinematic_baseline_mu",
        "kinematic_baseline_mu_c",
        "path_delta_c",
        "rate_spread_c_per_hour",
        "live_apply_default",
    )
    for key in scalar_keys:
        raw = value.get(key)
        if raw not in (None, "", [], {}):
            out[key] = copy.deepcopy(raw)
    for key in ("regime_probs", "forcing_onset_probs", "local_quadratic_fit", "soft_intraday_momentum"):
        raw = value.get(key)
        if isinstance(raw, Mapping) and raw:
            out[key] = copy.deepcopy(raw)
    peak_rows = value.get("peak_hour_distribution")
    if isinstance(peak_rows, list):
        out["peak_hour_distribution"] = [
            copy.deepcopy(row)
            for row in peak_rows[:12]
            if isinstance(row, Mapping)
        ]
    path_candidates = value.get("path_candidates")
    if isinstance(path_candidates, list):
        out["path_candidates"] = [
            copy.deepcopy(row)
            for row in path_candidates[:8]
            if isinstance(row, Mapping)
        ]
    return out


def _attach_temperature_regime_v1_to_endpoint_key_metrics(
    out_metrics: MutableMapping[str, Any],
    raw_metrics: Any,
) -> None:
    if not isinstance(out_metrics, MutableMapping) or not isinstance(raw_metrics, Mapping):
        return
    peak = raw_metrics.get("peak_estimator")
    if not isinstance(peak, Mapping):
        return
    compact_peak = _compact_intraday_mapping_for_endpoint(peak)
    regime_v1 = _compact_temperature_regime_v1_for_endpoint(
        peak.get("observed_temperature_trajectory_regime_v1")
    )
    if regime_v1:
        compact_peak["observed_temperature_trajectory_regime_v1"] = regime_v1
    if compact_peak:
        out_metrics["peak_estimator"] = compact_peak


