def _compact_target_trade_plan_leg(value: Any) -> Dict[str, Any]:
    if not isinstance(value, Mapping):
        return {}
    out: Dict[str, Any] = {}
    for key in _TARGET_TRADE_PLAN_LEG_KEYS:
        raw = value.get(key)
        if raw in (None, "", [], {}):
            continue
        if isinstance(raw, (str, int, float, bool)):
            out[key] = raw
    semantics = value.get("sell_old_buy_new_semantics")
    if isinstance(semantics, Mapping):
        compact_semantics = {
            str(key): str(raw)
            for key, raw in semantics.items()
            if raw not in (None, "")
        }
        if compact_semantics:
            out["sell_old_buy_new_semantics"] = compact_semantics
    return out


