def _attach_target_trade_plan_leg_fields(compact_plan: Any, raw_plan: Any) -> Dict[str, Any]:
    if not isinstance(compact_plan, Mapping):
        compact: Dict[str, Any] = {}
    else:
        compact = dict(compact_plan)
    if not isinstance(raw_plan, Mapping):
        return compact
    for key in _TARGET_TRADE_PLAN_LEG_LIST_KEYS:
        rows = _compact_target_trade_plan_leg_list(raw_plan.get(key))
        if rows:
            compact[key] = rows
    for key in _TARGET_TRADE_PLAN_SINGLE_LEG_KEYS:
        leg = _compact_target_trade_plan_leg(raw_plan.get(key))
        if leg:
            compact[key] = leg
    for key in (
        "position_legs_resolved",
        "sell_old_buy_new_legs_source",
        "active_old_position_count",
        "active_target_position_count",
        "sell_old_buy_new_missing_reason",
        "no_active_old_position_reason",
    ):
        raw = raw_plan.get(key)
        if raw not in (None, "", [], {}):
            compact[key] = raw
    return compact


