    entry_apply_edge_bias = env_bool("PM_AUTO_TRADE_ENTRY_APPLY_EDGE_BIAS", False)
    entry_require_tradeability_snapshot = env_bool(
        "PM_AUTO_TRADE_ENTRY_REQUIRE_TRADEABILITY_SNAPSHOT",
        env_bool("PM_AUTO_TRADE_ENTRY_REQUIRE_EDGE_REALIZABLE", True),
    )
    entry_yes_top_require_exec_edge = env_bool("PM_AUTO_TRADE_ENTRY_YES_TOP_REQUIRE_EXEC_EDGE", True)
    entry_follow_require_exec_edge = env_bool("PM_AUTO_TRADE_ENTRY_FOLLOW_REQUIRE_EXEC_EDGE", True)
    entry_hard_bound_no_require_exec_edge = env_bool(
        "PM_AUTO_TRADE_ENTRY_HARD_BOUND_NO_REQUIRE_EXEC_EDGE",
        True,
    )
    entry_adj_pair_require_exec_edge = env_bool(
        "PM_AUTO_TRADE_ENTRY_ADJ_PAIR_REQUIRE_EXEC_EDGE",
        True,
    )
    entry_require_q_range = env_bool("PM_AUTO_TRADE_ENTRY_REQUIRE_Q_RANGE", True)
    entry_require_q_band = env_bool("PM_AUTO_TRADE_ENTRY_REQUIRE_Q_BAND", False)
    entry_require_ask_range = env_bool("PM_AUTO_TRADE_ENTRY_REQUIRE_ASK_RANGE", True)
    entry_require_no_ask_range = env_bool("PM_AUTO_TRADE_ENTRY_REQUIRE_NO_ASK_RANGE", True)
    entry_require_yes_overprice = env_bool("PM_AUTO_TRADE_ENTRY_REQUIRE_YES_OVERPRICE", True)
    entry_block_no_by_yes_q = env_bool("PM_AUTO_TRADE_ENTRY_BLOCK_NO_BY_YES_Q", True)
