def _read_selected_env_file_vars(path: Path, keys: Iterable[str]) -> Dict[str, str]:
    wanted = {str(key or "").strip() for key in (keys or []) if str(key or "").strip()}
    if not wanted or not path.exists():
        return {}
    try:
        text = path.read_text(encoding="utf-8")
    except OSError:
        return {}
    out: Dict[str, str] = {}
    for line in text.splitlines():
        stripped = line.strip()
        if not stripped or stripped.startswith("#"):
            continue
        if stripped.startswith("export "):
            stripped = stripped[7:].lstrip()
        if "=" not in stripped:
            if (
                "PRIVATE_KEY" in wanted
                and "PRIVATE_KEY" not in out
                and re.fullmatch(r"0x[0-9A-Fa-f]{64}", stripped)
            ):
                out["PRIVATE_KEY"] = stripped
            continue
        key, value = stripped.split("=", 1)
        key = key.strip()
        if key not in wanted:
            continue
        value = value.strip()
        if value and value[0] not in {"'", '"'} and " #" in value:
            value = value.split(" #", 1)[0].rstrip()
        if len(value) >= 2 and value[0] == value[-1] and value[0] in {"'", '"'}:
            value = value[1:-1]
        out[key] = value
    return out


def _env_file_security_status(path: Path) -> Dict[str, Any]:
    out: Dict[str, Any] = {
        "path": str(path),
        "exists": False,
        "mode": "",
        "owner_uid": None,
        "owner_is_current_user": False,
        "secure": False,
        "issues": [],
    }
    try:
        st = path.stat()
    except OSError:
        out["issues"] = ["missing"]
        return out
    mode = stat.S_IMODE(st.st_mode)
    issues: List[str] = []
    out.update(
        {
            "exists": True,
            "mode": oct(mode),
            "owner_uid": int(st.st_uid),
            "owner_is_current_user": st.st_uid == os.getuid(),
        }
    )
    if st.st_uid != os.getuid():
        issues.append("owner_not_current_user")
    if mode & 0o077:
        issues.append("group_or_other_readable")
    out["issues"] = issues
    out["secure"] = not issues
    return out


def _launchctl_getenv(name: str) -> str:
    key = str(name or "").strip()
    if not key:
        return ""
    launchctl_bin = "/bin/launchctl" if Path("/bin/launchctl").exists() else "launchctl"
    try:
        res = subprocess.run(
            [launchctl_bin, "getenv", key],
            capture_output=True,
            text=True,
            timeout=0.3,
            check=False,
        )
    except Exception:
        return ""
    if res.returncode != 0:
        return ""
    return str(res.stdout or "").strip()


def _hydrate_auto_trade_runtime_env() -> None:
    control_values = _read_selected_env_file_vars(ENV_PATH, AUTO_TRADE_CONTROL_ENV_KEYS)
    for key, value in control_values.items():
        os.environ[key] = str(value)

    repo_shared_values = _read_selected_env_file_vars(ENV_PATH, AUTO_TRADE_SHARED_ENV_KEYS)
    for key, value in repo_shared_values.items():
        if str(value or "").strip() == "":
            continue
        if not os.environ.get(key):
            os.environ[key] = str(value)

    shared_env_path = _shared_poly_env_path()
    shared_values = _read_selected_env_file_vars(shared_env_path, AUTO_TRADE_SHARED_ENV_KEYS)
    for key, value in shared_values.items():
        if str(value or "").strip() == "":
            continue
        if key in AUTO_TRADE_CREDENTIAL_ENV_KEYS or not os.environ.get(key):
            os.environ[key] = str(value)

    allow_launchctl_credentials = _env_bool("PM_ALLOW_LAUNCHCTL_POLY_CREDENTIALS", False)
    for key in AUTO_TRADE_LAUNCHCTL_ENV_KEYS:
        if key in AUTO_TRADE_CREDENTIAL_ENV_KEYS and not allow_launchctl_credentials:
            continue
        if os.environ.get(key):
            continue
        value = _launchctl_getenv(key)
        if value:
            os.environ[key] = value

    if not os.environ.get("PRIVATE_KEY") and os.environ.get("POLY_PRIVATE_KEY"):
        os.environ["PRIVATE_KEY"] = str(os.environ.get("POLY_PRIVATE_KEY") or "")
    if not os.environ.get("PM_FUNDER_ADDRESS") and os.environ.get("POLY_FUNDER_ADDRESS"):
        os.environ["PM_FUNDER_ADDRESS"] = str(os.environ.get("POLY_FUNDER_ADDRESS") or "")


def auto_trade_env_diagnostics() -> Dict[str, Any]:
    _hydrate_auto_trade_runtime_env()
    enabled = os.environ.get("PM_AUTO_TRADE_ENABLED", "0").strip().lower() in {"1", "true", "yes", "on"}
    dry_run = os.environ.get("PM_AUTO_TRADE_DRY_RUN", "1").strip().lower() in {"1", "true", "yes", "on"}
    missing = [name for name in AUTO_TRADE_REQUIRED_ENV if not os.environ.get(name)]
    signature_raw = str(os.environ.get("PM_SIGNATURE_TYPE") or os.environ.get("SIGNATURE_TYPE") or "").strip()
    try:
        signature_type = int(signature_raw) if signature_raw else None
    except (TypeError, ValueError):
        signature_type = None
    funder_address = str(os.environ.get("PM_FUNDER_ADDRESS") or "").strip()
    signer_address = ""
    private_key = str(os.environ.get("PRIVATE_KEY") or "").strip()
    if private_key:
        cached_pk = str(SIGNER_ADDRESS_CACHE.get("private_key") or "")
        cached_address = str(SIGNER_ADDRESS_CACHE.get("address") or "")
        if cached_pk == private_key and cached_address:
            signer_address = cached_address
        else:
            if EthAccount is not None:
                try:
                    signer_address = str(EthAccount.from_key(private_key).address or "").strip()
                except Exception:
                    signer_address = ""
            if not signer_address and _env_bool("PM_AUTO_TRADE_ENV_NODE_FALLBACK", False):
                node_bin = shutil.which("node") or "/opt/homebrew/bin/node" or "/usr/local/bin/node"
                node_cmd = [
                    node_bin,
                    "-e",
                    "const { Wallet } = require('ethers'); console.log(new Wallet(process.env.PRIVATE_KEY).address)",
                ]
                try:
                    res = subprocess.run(
                        node_cmd,
                        env={"PRIVATE_KEY": private_key},
                        capture_output=True,
                        text=True,
                        timeout=3,
                        check=False,
                    )
                    if res.returncode == 0:
                        addr = str((res.stdout or "").strip())
                        if addr.startswith("0x") and len(addr) == 42:
                            signer_address = addr
                except Exception:
                    signer_address = ""
            if signer_address:
                SIGNER_ADDRESS_CACHE["private_key"] = private_key
                SIGNER_ADDRESS_CACHE["address"] = signer_address
    owner = "signer"
    if signature_type == 1 and funder_address:
        owner = "funder"
    credential_source_path = _shared_poly_env_path()
    credential_source = _env_file_security_status(credential_source_path)
    return {
        "enabled": enabled,
        "dry_run": dry_run,
        "missing": missing,
        "credential_source": credential_source,
        "credential_source_path": str(credential_source_path),
        "credential_source_ok": bool(credential_source.get("secure")) and not missing,
        "signature_type": signature_type,
        "signer_address": signer_address,
        "funder_address": funder_address,
        "balance_owner": owner,
    }


def auto_trade_env_error_text(diag: Dict[str, Any]) -> str:
    parts = []
    if diag.get("dry_run"):
        parts.append("PM_AUTO_TRADE_DRY_RUN=1")
    missing = diag.get("missing") or []
    if missing:
        parts.append("缺少 " + ", ".join(missing))
    return " / ".join(parts) if parts else ""


def trade_sync_env_missing() -> List[str]:
    return [name for name in AUTO_TRADE_REQUIRED_ENV if not os.environ.get(name)]


def _env_bool(name: str, default: bool = False) -> bool:
    raw = os.environ.get(name)
    if raw is None:
        return default
    return str(raw).strip().lower() in {"1", "true", "yes", "on"}


def _env_float(name: str, default: Optional[float] = None) -> Optional[float]:
    raw = os.environ.get(name)
    if raw is None or str(raw).strip() == "":
        return default
    try:
        value = float(raw)
    except (TypeError, ValueError):
        return default
    if not math.isfinite(value):
        return default
    return value


def _env_int_clamped(name: str, default: int, *, min_value: int, max_value: int) -> int:
    raw = os.environ.get(name)
    try:
        value = int(float(str(raw if raw is not None else default).strip()))
    except (TypeError, ValueError):
        value = int(default)
    return max(int(min_value), min(int(max_value), int(value)))


def _update_env_value(path: Path, key: str, value: str) -> bool:
    try:
        text = path.read_text(encoding="utf-8")
    except FileNotFoundError:
        path.write_text(f"{key}={value}\n", encoding="utf-8")
        return True
    except OSError:
        return False
    pattern = re.compile(rf"^\s*(?:export\s+)?{re.escape(key)}\s*=")
    lines = text.splitlines()
    replaced = False
    out_lines: List[str] = []
    for line in lines:
        if pattern.match(line):
            comment = ""
            if "#" in line:
                _, comment_part = line.split("#", 1)
                if comment_part.strip():
                    comment = " #" + comment_part.strip()
            out_lines.append(f"{key}={value}{comment}")
            replaced = True
        else:
            out_lines.append(line)
    if not replaced:
        if out_lines and out_lines[-1].strip():
            out_lines.append("")
        out_lines.append(f"{key}={value}")
    try:
        path.write_text("\n".join(out_lines) + "\n", encoding="utf-8")
    except OSError:
        return False
    return True


def _restart_auto_trade_runtime_services() -> Dict[str, Any]:
    uid = os.getuid()
    domain = f"gui/{uid}"
    labels = [
        "com.weather.trade_engine",
        "com.weather.auto_trade_worker",
    ]
    results: List[Dict[str, Any]] = []
    for label in labels:
        results.append(
            {
                "label": label,
                "kickstart": _launchctl_run(
                    ["launchctl", "kickstart", "-k", f"{domain}/{label}"],
                    timeout_sec=6,
                ),
            }
        )
    return {"ok": True, "domain": domain, "results": results}


def apply_auto_trade_state(enabled: bool, *, dry_run: Optional[bool] = None) -> Dict[str, Any]:
    value = "1" if enabled else "0"
    sync_value = "1"
    dry_run_value = None if dry_run is None else ("1" if dry_run else "0")
    os.environ["PM_AUTO_TRADE_ENABLED"] = value
    os.environ["PM_AUTO_TRADE_SYNC_TRADES"] = sync_value
    os.environ["PM_AUTO_TRADE_SYNC_OPEN_ORDERS"] = sync_value
    if dry_run_value is not None:
        os.environ["PM_AUTO_TRADE_DRY_RUN"] = dry_run_value
    _update_env_value(ENV_PATH, "PM_AUTO_TRADE_ENABLED", value)
    _update_env_value(ENV_PATH, "PM_AUTO_TRADE_SYNC_TRADES", sync_value)
    _update_env_value(ENV_PATH, "PM_AUTO_TRADE_SYNC_OPEN_ORDERS", sync_value)
    if dry_run_value is not None:
        _update_env_value(ENV_PATH, "PM_AUTO_TRADE_DRY_RUN", dry_run_value)
    if scan_execute_auto_trades is not None:
        try:
            import scan_weather_market as scan_module
        except Exception:
            scan_module = None
        if scan_module is not None:
            try:
                scan_module.AUTO_TRADE_ENABLED = enabled
                scan_module.AUTO_TRADE_SYNC_TRADES = True
                if dry_run_value is not None:
                    scan_module.AUTO_TRADE_DRY_RUN = bool(dry_run)
            except Exception:
                pass
    restart_payload = _restart_auto_trade_runtime_services()
    diag = auto_trade_env_diagnostics()
    return {
        "enabled": diag.get("enabled"),
        "dry_run": diag.get("dry_run"),
        "missing": diag.get("missing"),
        "credential_source_path": diag.get("credential_source_path"),
        "credential_source": diag.get("credential_source"),
        "credential_source_ok": diag.get("credential_source_ok"),
        "sync_trades": _env_bool("PM_AUTO_TRADE_SYNC_TRADES", True),
        "sync_open_orders": _env_bool("PM_AUTO_TRADE_SYNC_OPEN_ORDERS", True),
        "restart": restart_payload,
    }


def auto_trade_health(
    prefer_run_date: str = "",
    force_refresh: bool = False,
    *,
    allow_async_refresh: bool = True,
) -> Dict[str, Any]:
    now_ts = time.time()
    cache = AUTO_TRADE_HEALTH_CACHE
    requested_run_date_key = _normalize_date_key(prefer_run_date)
    cache_key = requested_run_date_key or "__auto__"
    cached = (cache.get("payload") or {}) if str(cache.get("key") or "__auto__") == cache_key else {}
    cache_age_sec = max(0.0, now_ts - float(cache.get("ts") or 0.0)) if cached else None
    fd_usage = get_fd_usage()

    def _refresh_async() -> None:
        try:
            auto_trade_health(
                prefer_run_date,
                force_refresh=True,
                allow_async_refresh=False,
            )
        except Exception:
            pass

    def _spawn_refresh_async() -> bool:
        if not allow_async_refresh:
            return False
        if AUTO_TRADE_HEALTH_LOCK.locked():
            return False
        try:
            threading.Thread(target=_refresh_async, daemon=True).start()
            return True
        except Exception:
            return False

    def _cache_set(payload_obj: Dict[str, Any]) -> None:
        cache["ts"] = now_ts
        cache["payload"] = payload_obj
        cache["key"] = cache_key
    if force_refresh and allow_async_refresh:
        spawned = _spawn_refresh_async()
        if cached:
            out = dict(cached)
            out["stale"] = True
            out["refreshing"] = bool(spawned)
            out["cache_age_sec"] = round(float(cache_age_sec or 0.0), 3)
            out["refresh_mode"] = "async"
            return out
        payload = {
            "ok": True,
            "level": "warn",
            "issues": [
                {
                    "code": "health_refresh_pending",
                    "severity": "warn",
                    "group": "services",
                    "message": "健康检查刷新中（先返回轻量占位）",
                    "evidence": {"run_date": requested_run_date_key},
                }
            ],
            "total": 0,
            "modelOk": 0,
            "dataOk": 0,
            "linkOk": 0,
            "updated_at": now_text(),
            "run_date": requested_run_date_key,
            "stale": True,
            "warming": True,
            "refreshing": bool(spawned),
            "refresh_mode": "async",
        }
    if (not force_refresh) and cached and (now_ts - float(cache.get("ts") or 0.0)) < AUTO_TRADE_HEALTH_CACHE_SEC:
        return dict(cached)
    if (not force_refresh) and cached and allow_async_refresh:
        spawned = _spawn_refresh_async()
        out = dict(cached)
        out["stale"] = True
        out["refreshing"] = bool(spawned)
        out["cache_age_sec"] = round(float(cache_age_sec or 0.0), 3)
        out["refresh_mode"] = "stale_while_revalidate"
        return out
    global AUTO_TRADE_HEALTH_LOCK_AT
    lock_acquired = AUTO_TRADE_HEALTH_LOCK.acquire(blocking=False)
    lock_stale_bypass = False
    if lock_acquired:
        AUTO_TRADE_HEALTH_LOCK_AT = time.time()
    else:
        lock_age_sec = max(0.0, time.time() - float(AUTO_TRADE_HEALTH_LOCK_AT or 0.0))
        if lock_age_sec <= AUTO_TRADE_HEALTH_LOCK_STALE_SEC:
            if cached:
                return dict(cached)
            return {
                "ok": True,
                "level": "warn",
                "issues": [
                    {
                        "code": "health_busy",
                        "severity": "warn",
                        "group": "services",
                        "message": "健康检查繁忙（返回空结果）",
                        "evidence": {},
                    }
                ],
                "total": 0,
                "modelOk": 0,
                "dataOk": 0,
                "linkOk": 0,
                "updated_at": now_text(),
            }
        # Lock holder appears stale; bypass lock once so health payload can self-heal.
        lock_stale_bypass = True
    try:
        if not DB_PATH.exists():
            payload = {
                "ok": True,
                "level": "warn",
                "issues": [
                    {
                        "code": "db_missing",
                        "severity": "warn",
                        "group": "data",
                        "message": "本地数据库不存在（data/archive.db）",
                        "evidence": {"db_path": str(DB_PATH)},
                    }
                ],
                "total": 0,
                "modelOk": 0,
                "dataOk": 0,
                "linkOk": 0,
                "updated_at": now_text(),
            }
            _cache_set(payload)
            return dict(payload)
        issues: List[Dict[str, Any]] = []

        def _add_issue(code: str, severity: str, group: str, message: str, evidence: Optional[Dict[str, Any]] = None) -> None:
            issues.append(
                {
                    "code": str(code or ""),
                    "severity": str(severity or "warn"),
                    "group": str(group or "misc"),
                    "message": str(message or ""),
                    "evidence": evidence or {},
                }
            )

        diag = auto_trade_env_diagnostics()
        balance_disabled = ACCOUNT_REQUESTS_DISABLED or _env_bool("PM_AUTO_TRADE_BALANCE_DISABLED", False)
        if diag.get("missing"):
            _add_issue(
                "env_missing",
                "error",
                "account",
                "自动交易凭证缺失（CLOB API / 钱包）",
                {"missing": list(diag.get("missing") or [])},
            )
        if diag.get("enabled") and diag.get("dry_run"):
            _add_issue("dry_run_enabled", "warn", "account", "PM_AUTO_TRADE_DRY_RUN=1（不会真实下单）")
        if diag.get("enabled") and not ACCOUNT_REQUESTS_DISABLED and not _env_bool("PM_AUTO_TRADE_SYNC_TRADES", True):
            _add_issue("sync_trades_disabled", "error", "account", "PM_AUTO_TRADE_SYNC_TRADES=0（成交同步关闭会导致状态机异常）")

        services = services_health()
        service_launchd = services.get("launchd") if isinstance(services, dict) else {}
        if not isinstance(service_launchd, dict):
            service_launchd = {}

        def _service_launchd_pid(label: str) -> Optional[int]:
            row = service_launchd.get(label) if isinstance(service_launchd, dict) else None
            pid = row.get("pid") if isinstance(row, dict) else None
            if isinstance(pid, int) and pid > 0:
                return pid
            return None

        trade_engine_service_pid = _service_launchd_pid("com.weather.trade_engine")
        legacy_trade_sync_service_pid = _service_launchd_pid("com.weather.trade_sync_loop")
        trade_sync_driver = (
            "trade_engine"
            if trade_engine_service_pid is not None
            else ("legacy_trade_sync_loop" if legacy_trade_sync_service_pid is not None else "status_file")
        )
        if isinstance(services, dict):
            for it in list(services.get("issues") or []):
                if not isinstance(it, dict):
                    continue
                sev = str(it.get("severity") or "warn").strip().lower() or "warn"
                if sev == "ok":
                    continue
                msg = str(it.get("message") or it.get("code") or "").strip()
                if not msg:
                    continue
                _add_issue(str(it.get("code") or "service_issue"), sev, "services", msg, it.get("evidence") if isinstance(it.get("evidence"), dict) else {})

        # DB-derived health
        run_date = ""
        run_date_key = ""
        fact_rows: List[Dict[str, Any]] = []
        facts_total_rows: Optional[int] = None
        facts_total_events: Optional[int] = None
        facts_skipped = False
        market_tick_stats: Dict[str, Any] = {"count": 0, "median_age_sec": None, "max_age_sec": None}
        fact_age_stats: Dict[str, Any] = {"count": 0, "max_age_sec": None}
        cooldown_stats: Dict[str, Any] = {}
        decision_stats: Dict[str, Any] = {}
        exec_blockers: Dict[str, Any] = {}
        exec_job_blockers: Dict[str, Any] = {}
        exec_edge_blockers: Dict[str, Any] = {}
        position_stats: Dict[str, Any] = {}
        trade_sync_subject_stats: Dict[str, Any] = {}
        platt_stable = False
        trade_sync_status = load_trade_sync_status()
        watchdog = build_trade_sync_watchdog(trade_sync_status)
        health_budget_sec = _env_float("PM_AUTO_TRADE_HEALTH_DB_BUDGET_SEC", 8.0) or 8.0
        health_budget_sec = max(1.0, min(30.0, float(health_budget_sec)))
        health_deadline = time.monotonic() + health_budget_sec
        health_progress_interrupted = False

        def _health_progress_handler() -> int:
            nonlocal health_progress_interrupted
            if time.monotonic() > health_deadline:
                health_progress_interrupted = True
                return 1
            return 0

        def _age_sec_from_iso(ts_text: str) -> Optional[float]:
            ts_text = str(ts_text or "").strip()
            if not ts_text:
                return None
            dt = parse_iso_ts(ts_text)
            if dt is None:
                return None
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=timezone.utc)
            return max(0.0, (datetime.now(timezone.utc) - dt).total_seconds())

        try:
            with open_db_ro_fast() as conn:
                try:
                    conn.set_progress_handler(_health_progress_handler, 2000)
                except Exception:
                    pass
                cur = conn.cursor()
                run_date = ""
                if requested_run_date_key:
                    try:
                        cur.execute(
                            """
                            SELECT 1 FROM event_fact_history
                            WHERE run_date = ?
                            LIMIT 1
                            """,
                            (requested_run_date_key,),
                        )
                        run_date = requested_run_date_key if cur.fetchone() else ""
                    except sqlite3.Error:
                        run_date = ""
                    if not run_date:
                        try:
                            cur.execute(
                                """
                                SELECT 1 FROM event_runs
                                WHERE run_date = ?
                                LIMIT 1
                                """,
                                (requested_run_date_key,),
                            )
                            run_date = requested_run_date_key if cur.fetchone() else ""
                        except sqlite3.Error:
                            run_date = ""
                if not run_date:
                    run_date = latest_fact_run_date(conn) or latest_unsettled_run_date(conn) or latest_run_date(conn) or ""
                run_date_key = _normalize_date_key(run_date)
                if not run_date_key:
                    payload = {
                        "ok": True,
                        "level": "warn",
                        "issues": issues
                        + [
                            {
                                "code": "no_run_date",
                                "severity": "warn",
                                "group": "data",
                                "message": "未找到有效 run_date（尚未扫描/合成 facts）",
                                "evidence": {},
                            }
                        ],
                        "total": 0,
                        "modelOk": 0,
                        "dataOk": 0,
                        "linkOk": 0,
                        "updated_at": now_text(),
                        "run_date": run_date,
                    }
                    _cache_set(payload)
                    return dict(payload)

                cur = conn.cursor()
                try:
                    cur.execute("SELECT COUNT(*) AS cnt FROM auto_orders")
                    auto_order_row = cur.fetchone()
                    auto_order_count = int(auto_order_row["cnt"] or 0) if auto_order_row else 0
                except sqlite3.Error:
                    auto_order_count = None
                try:
                    cur.execute(
                        """
                        SELECT COUNT(*) AS cnt
                        FROM edge_trades
                        WHERE state IN ('entry', 'entry_pending', 'exit_pending')
                           OR COALESCE(position_size, 0) > 0.000001
                           OR COALESCE(last_order_id, '') <> ''
                        """
                    )
                    active_trade_row = cur.fetchone()
                    active_trade_count = int(active_trade_row["cnt"] or 0) if active_trade_row else 0
                except sqlite3.Error:
                    active_trade_count = None
                trade_sync_subject_stats = {
                    "auto_orders": auto_order_count,
                    "active_trades": active_trade_count,
                    "idle_no_subjects": auto_order_count == 0 and active_trade_count == 0,
                }
                platt_days = None
                try:
                    platt_days = int(os.environ.get("PM_Q_PLATT_DAYS", "60"))
                except (TypeError, ValueError):
                    platt_days = 60
                platt = _load_platt_calibration_ro(conn, platt_days or 0)
                platt_stable = bool(isinstance(platt, dict) and platt.get("stable_ok"))
                try:
                    cur.execute(
                        """
                        SELECT COUNT(*) AS cnt
                        FROM event_fact_history
                        WHERE run_date = ?
                          AND event_date >= ?
                        """,
                        (run_date_key, run_date_key),
                    )
                    row = cur.fetchone()
                    facts_total_rows = int(row["cnt"] or 0) if row else 0
                except Exception:
                    facts_total_rows = None
                try:
                    cur.execute(
                        """
                        SELECT COUNT(DISTINCT slug || '|' || event_date) AS cnt
                        FROM event_fact_history
                        WHERE run_date = ?
                          AND event_date >= ?
                        """,
                        (run_date_key, run_date_key),
                    )
                    row = cur.fetchone()
                    facts_total_events = int(row["cnt"] or 0) if row else 0
                except Exception:
                    facts_total_events = None
                if facts_total_rows is not None and facts_total_rows > AUTO_TRADE_HEALTH_FACT_MAX_ROWS:
                    facts_skipped = True
                    _add_issue(
                        "facts_skipped",
                        "warn",
                        "data",
                        "facts 行数过多（健康检查跳过详情）",
                        {"rows": facts_total_rows, "max_rows": AUTO_TRADE_HEALTH_FACT_MAX_ROWS},
                    )
                if not facts_skipped:
                    try:
                        # Read-only health: skip table creation/backfill to avoid blocking writers.
                        fact_rows = select_event_fact_rows(conn, run_date_key, include_history=False) or []
                    except Exception as exc:
                        fact_rows = []
                        _add_issue("facts_read_failed", "error", "data", "读取 facts 失败", {"error": str(exc)})

                # Market tick age distribution (per event: latest tick per slug+event_date).
                tick_row_map: List[Dict[str, Any]] = []
                skip_no_orderbook: Dict[str, str] = {}
                try:
                    cur.execute(
                        """
                        SELECT slug, MAX(created_at) AS last_at
                        FROM scan_skips
                        WHERE run_date = ?
                          AND reason LIKE 'market_refresh_failed no_orderbook_quotes:%'
                        GROUP BY slug
                        """,
                        (run_date_key,),
                    )
                    for row in cur.fetchall() or []:
                        slug = str(row["slug"] or "").strip()
                        last_at = str(row["last_at"] or "").strip()
                        if slug:
                            skip_no_orderbook[slug] = last_at
                except sqlite3.Error:
                    skip_no_orderbook = {}
                def _skip_valid(slug: str, last_tick_at: str) -> bool:
                    if not slug or slug not in skip_no_orderbook:
                        return False
                    skip_at = str(skip_no_orderbook.get(slug) or "")
                    if not skip_at:
                        return True
                    skip_dt = parse_iso_ts(skip_at)
                    tick_dt = parse_iso_ts(str(last_tick_at or ""))
                    if skip_dt is None or tick_dt is None:
                        return True
                    if skip_dt.tzinfo is None:
                        skip_dt = skip_dt.replace(tzinfo=timezone.utc)
                    if tick_dt.tzinfo is None:
                        tick_dt = tick_dt.replace(tzinfo=timezone.utc)
                    return tick_dt <= skip_dt
                tick_orphan_skipped = 0
                tick_keys: List[Tuple[str, str]] = []
                for fact_row in fact_rows:
                    try:
                        slug = str(fact_row["slug"] or "").strip()
                        event_date = _normalize_date_key(str(fact_row["event_date"] or ""))
                    except (KeyError, TypeError, IndexError):
                        continue
                    if slug and event_date and event_date >= run_date_key:
                        tick_keys.append((slug, event_date))
                active_health_slugs = {slug for slug, _event_date in tick_keys}
                tick_latest_map = query_market_tick_latest_for_keys(conn, tick_keys)
                tick_rows = [
                    {"slug": slug, "event_date": event_date, "last_tick_at": last_tick_at}
                    for (slug, event_date), last_tick_at in tick_latest_map.items()
                ]
                last_tick_by_slug: Dict[str, str] = {}
                for row in tick_rows:
                    slug = str(row["slug"] or "").strip()
                    last_tick_at = str(row["last_tick_at"] or "")
                    if slug and last_tick_at:
                        prev = last_tick_by_slug.get(slug)
                        if not prev or (last_tick_at > prev):
                            last_tick_by_slug[slug] = last_tick_at
                effective_skips: Dict[str, str] = {}
                for slug, last_at in skip_no_orderbook.items():
                    if slug not in active_health_slugs:
                        continue
                    last_tick_at = last_tick_by_slug.get(slug, "")
                    if _skip_valid(slug, last_tick_at):
                        effective_skips[slug] = last_at
                skip_no_orderbook = effective_skips
                tick_ages: List[float] = []
                for row in tick_rows:
                    slug = str(row["slug"] or "").strip()
                    last_tick_at = str(row["last_tick_at"] or "")
                    if slug and _skip_valid(slug, last_tick_at):
                        continue
                    age = _age_sec_from_iso(last_tick_at)
                    if age is None:
                        continue
                    tick_ages.append(float(age))
                    tick_row_map.append(
                        {
                            "slug": slug,
                            "event_date": str(row["event_date"] or ""),
                            "last_tick_at": last_tick_at,
                            "age_sec": float(age),
                        }
                    )
                tick_ages_sorted = sorted(tick_ages)
                oldest_ticks = sorted(tick_row_map, key=lambda r: float(r.get("age_sec") or 0.0), reverse=True)[:6]
                market_tick_stats = {
                    "count": len(tick_ages_sorted),
                    "median_age_sec": (statistics.median(tick_ages_sorted) if tick_ages_sorted else None),
                    "max_age_sec": (max(tick_ages_sorted) if tick_ages_sorted else None),
                    "run_date": run_date_key,
                    "oldest": oldest_ticks,
                    "skipped_no_orderbook": [
                        {"slug": k, "last_at": v} for k, v in list(skip_no_orderbook.items())[:6]
                    ],
                    "skipped_no_orderbook_count": len(skip_no_orderbook),
                    "orphan_tick_events_skipped": tick_orphan_skipped,
                }

                # Facts staleness (per event: latest fact_as_of per slug+event_date).
                fact_row_map: List[Dict[str, Any]] = []
                try:
                    cur.execute(
                        """
                        SELECT l.slug, l.event_date, h.fact_as_of AS last_fact_as_of
                        FROM event_fact_latest l
                        JOIN event_fact_history h ON h.id = l.fact_id
                        WHERE substr(l.event_date, 1, 10) >= ?
                        """,
                        (run_date_key,),
                    )
                    fact_age_rows = cur.fetchall() or []
                except sqlite3.Error:
                    fact_age_rows = []
                fact_ages: List[float] = []
                for row in fact_age_rows:
                    last_fact_as_of = str(row["last_fact_as_of"] or "")
                    age = _age_sec_from_iso(last_fact_as_of)
                    if age is None:
                        continue
                    fact_ages.append(float(age))
                    fact_row_map.append(
                        {
                            "slug": str(row["slug"] or ""),
                            "event_date": str(row["event_date"] or ""),
                            "last_fact_as_of": last_fact_as_of,
                            "age_sec": float(age),
                        }
                    )
                fact_ages_sorted = sorted(fact_ages)
                oldest_facts = sorted(fact_row_map, key=lambda r: float(r.get("age_sec") or 0.0), reverse=True)[:6]
                fact_age_stats = {
                    "count": len(fact_ages_sorted),
                    "median_age_sec": (statistics.median(fact_ages_sorted) if fact_ages_sorted else None),
                    "max_age_sec": (max(fact_ages) if fact_ages else None),
                    "run_date": run_date_key,
                    "oldest": oldest_facts,
                }

                def _enrich_oldest_with_ticks(entries: List[Dict[str, Any]]) -> None:
                    if not entries:
                        return
                    keys: List[Tuple[str, str]] = []
                    for e in entries:
                        if not isinstance(e, dict):
                            continue
                        slug = str(e.get("slug") or "").strip()
                        event_date = str(e.get("event_date") or "").strip()
                        if slug and event_date:
                            keys.append((slug, event_date))
                    if not keys:
                        return
                    # Query latest tick timestamps for the listed slug+date pairs, to explain "facts stale".
                    # Keep this per-key so SQLite can use the slug/event_date/created_at index.
                    tick_map = query_market_tick_latest_for_keys(conn, keys)
                    for e in entries:
                        if not isinstance(e, dict):
                            continue
                        key = (str(e.get("slug") or ""), str(e.get("event_date") or ""))
                        last_tick_at = tick_map.get(key) or ""
                        e["last_tick_at"] = last_tick_at
                        e["tick_age_sec"] = _age_sec_from_iso(last_tick_at) if last_tick_at else None

                _enrich_oldest_with_ticks(oldest_facts)

                # Open-Meteo 429 cooldown summary (rate-limit / fan-out signal).
                now_iso = utc_now_iso()
                cutoff_6h = (datetime.now(timezone.utc) - timedelta(hours=6)).isoformat()
                try:
                    cur.execute(
                        """
                        SELECT
                          SUM(CASE WHEN reason = 'open_meteo_429' AND created_at >= ? THEN 1 ELSE 0 END) AS recent_6h,
                          SUM(CASE WHEN reason = 'open_meteo_429' AND cooldown_until > ? THEN 1 ELSE 0 END) AS active_now,
                          MAX(created_at) AS last_at
                        FROM model_request_cooldown
                        """,
                        (cutoff_6h, now_iso),
                    )
                    row = cur.fetchone()
                    cooldown_stats = {
                        "open_meteo_429_recent_6h": int(row["recent_6h"] or 0) if row else 0,
                        "open_meteo_429_active_now": int(row["active_now"] or 0) if row else 0,
                        "open_meteo_429_last_at": str(row["last_at"] or "") if row else "",
                    }
                except sqlite3.Error:
                    cooldown_stats = {}

                # Auto-trade decision blockers summary (SSOT for "why no order").
                try:
                    decision_health_limit = max(
                        100,
                        min(
                            1200,
                            int(os.environ.get("PM_AUTO_TRADE_HEALTH_DECISION_ROW_LIMIT", "300") or 300),
                        ),
                    )
                    (
                        rows,
                        decision_run_date,
                        decision_run_date_source,
                    ) = _auto_trade_decision_rows_for_health(
                        cur,
                        run_date_key,
                        limit=decision_health_limit,
                    )
                except sqlite3.Error:
                    rows = []
                    decision_run_date = run_date_key
                    decision_run_date_source = "run_date"
                reason_counts: Dict[str, int] = {}
                will_order_count = 0
                entry_ok_count = 0
                last_decision_at = ""
                chase_market_count = 0
                chase_topup_count = 0
                decision_rows_countable = 0
                non_stat_blocked_count = 0
                no_order_diagnostic = _auto_trade_no_order_diagnostic_from_decision_rows(rows)
                for row in rows:
                    if not last_decision_at:
                        last_decision_at = str(row["created_at"] or "")
                    if int(row["will_order"] or 0) == 1:
                        will_order_count += 1
                    state = str(row["decided_state"] or "")
                    if state == "entry_ok":
                        entry_ok_count += 1
                    codes = safe_json_loads_any(row["reason_codes_json"])
                    row_codes: List[str] = []
                    if isinstance(codes, list):
                        for code in codes:
                            c = str(code or "").strip()
                            if not c:
                                continue
                            row_codes.append(c)
                            if is_non_stat_blocker_code(c):
                                continue
                            reason_counts[c] = int(reason_counts.get(c) or 0) + 1
                    has_non_stat_code = any(is_non_stat_blocker_code(code) for code in row_codes)
                    if has_non_stat_code and int(row["will_order"] or 0) <= 0:
                        non_stat_blocked_count += 1
                    else:
                        decision_rows_countable += 1
                    if int(row["will_order"] or 0) == 1:
                        details = safe_json_loads(row["details_json"])
                        if isinstance(details, dict):
                            if details.get("rising_ask_market") is True:
                                chase_market_count += 1
                            if details.get("topup_chase_applied") is True:
                                chase_topup_count += 1
                top_reasons = sorted(reason_counts.items(), key=lambda kv: (-int(kv[1]), str(kv[0])))[:12]
                decision_stats = {
                    "decision_rows": len(rows),
                    "decision_run_date": decision_run_date,
                    "decision_run_date_source": decision_run_date_source,
                    "decision_rows_countable": int(decision_rows_countable),
                    "non_stat_blocked_count": int(non_stat_blocked_count),
                    "entry_ok_count": entry_ok_count,
                    "will_order_count": will_order_count,
                    "last_decision_at": last_decision_at,
                    "top_reason_codes": [{"code": k, "count": int(v)} for k, v in top_reasons],
                    "no_order_diagnostic": no_order_diagnostic,
                }
                chase_stats = {
                    "decision_rows": len(rows),
                    "will_order_count": will_order_count,
                    "last_decision_at": last_decision_at,
                    "market_rising_ask_count": chase_market_count,
                    "topup_chase_count": chase_topup_count,
                }
                if will_order_count > 0:
                    chase_stats["market_rising_ask_ratio"] = chase_market_count / will_order_count
                    chase_stats["topup_chase_ratio"] = chase_topup_count / will_order_count

                # Execution blockers SSOT:
                # 1) auto_trade_jobs live failures/retrying/stuck (primary)
                # 2) edge_trades last_error (secondary evidence only)
                try:
                    exec_job_blockers = collect_auto_trade_job_blockers(
                        conn, run_date=run_date_key, window_hours=AUTO_TRADE_BLOCKER_WINDOW_HOURS
                    )
                except Exception:
                    exec_job_blockers = {}
                try:
                    exec_edge_blockers = collect_auto_trade_blockers(conn, trade_sync_status=trade_sync_status)
                except Exception:
                    exec_edge_blockers = {}
                if isinstance(exec_job_blockers, dict) and exec_job_blockers.get("has_blocker"):
                    exec_blockers = dict(exec_job_blockers)
                else:
                    exec_blockers = dict(exec_edge_blockers)
                try:
                    open_order_wait_sec = max(
                        30.0,
                        _env_float("PM_AUTO_TRADE_OPEN_ORDER_WAIT_SEC", 90.0) or 90.0,
                    )
                    open_order_recheck_sec = max(
                        5.0,
                        _env_float("PM_AUTO_TRADE_OPEN_ORDER_RECHECK_COOLDOWN_SEC", 20.0) or 20.0,
                    )
                    open_order_auto_cancel_enabled = _env_bool("PM_AUTO_TRADE_OPEN_ORDER_AUTO_CANCEL_ENABLED", True)
                    open_order_auto_cancel_sec = max(
                        open_order_wait_sec + open_order_recheck_sec,
                        _env_float("PM_AUTO_TRADE_OPEN_ORDER_AUTO_CANCEL_SEC", 300.0) or 300.0,
                    )
                    open_order_waiting_sec = max(
                        open_order_wait_sec + open_order_recheck_sec,
                        open_order_auto_cancel_sec if open_order_auto_cancel_enabled else (open_order_wait_sec + open_order_recheck_sec),
                    )

                    def _is_exit_waiting_row(row_obj: sqlite3.Row) -> bool:
                        last_error = str(row_obj["last_error"] or "").strip().lower()
                        last_status = str(row_obj["last_status"] or "").strip().lower()
                        if last_error.startswith("min_hold:") or last_status == "exit_holdoff":
                            return True
                        is_open_order_wait = (
                            last_error.startswith("open_order_exists:")
                            or last_status in {"open_order_pending", "open_order_recheck_pending"}
                            or "open_order_pending" in last_status
                        )
                        if not is_open_order_wait:
                            return False
                        age_sec = _age_sec_from_iso(str(row_obj["last_action_at"] or row_obj["updated_at"] or ""))
                        if age_sec is None:
                            return True
                        return float(age_sec) < float(open_order_waiting_sec)

                    cur.execute(
                        """
                        SELECT slug, event_date, outcome, side, state, position_size, last_status, last_error, last_action_at, updated_at
                        FROM edge_trades
                        WHERE ABS(COALESCE(position_size, 0)) > ?
                        ORDER BY updated_at DESC
                        """,
                        (TIME_EDGE_Q_EPS,),
                    )
                    all_pos_rows = cur.fetchall() or []
                    open_positions = 0
                    exit_positions = 0
                    exit_positions_active = 0
                    exit_positions_waiting = 0
                    exit_positions_legacy = 0
                    last_updated_at = ""
                    exit_samples: List[Dict[str, Any]] = []
                    exit_samples_legacy: List[Dict[str, Any]] = []
                    for r in all_pos_rows:
                        open_positions += 1
                        updated_at = str(r["updated_at"] or "")
                        if updated_at and updated_at > last_updated_at:
                            last_updated_at = updated_at
                        if str(r["state"] or "").strip().lower() != "exit":
                            continue
                        exit_positions += 1
                        event_date_text = str(r["event_date"] or "").strip()
                        is_active = bool(event_date_text and event_date_text >= run_date_key)
                        sample = {
                            "slug": str(r["slug"] or ""),
                            "event_date": event_date_text,
                            "outcome": str(r["outcome"] or ""),
                            "side": str(r["side"] or ""),
                            "state": str(r["state"] or ""),
                            "position_size": r["position_size"],
                            "last_status": str(r["last_status"] or ""),
                            "last_error": str(r["last_error"] or ""),
                            "last_action_at": str(r["last_action_at"] or ""),
                            "updated_at": updated_at,
                        }
                        if is_active:
                            exit_positions_active += 1
                            if _is_exit_waiting_row(r):
                                exit_positions_waiting += 1
                            if len(exit_samples) < 6:
                                exit_samples.append(sample)
                        else:
                            exit_positions_legacy += 1
                            if len(exit_samples_legacy) < 6:
                                exit_samples_legacy.append(sample)
                    position_stats = {
                        "open_positions": int(open_positions),
                        "exit_positions": int(exit_positions),
                        "exit_positions_active": int(exit_positions_active),
                        "exit_positions_waiting": int(exit_positions_waiting),
                        "exit_positions_legacy": int(exit_positions_legacy),
                        "last_updated_at": last_updated_at,
                        "exit_samples": exit_samples,
                        "exit_samples_legacy": exit_samples_legacy,
                    }
                    try:
                        cur.execute("SELECT COUNT(*) AS cnt FROM auto_orders")
                        auto_order_row = cur.fetchone()
                        auto_order_count = int(auto_order_row["cnt"] or 0) if auto_order_row else 0
                    except sqlite3.Error:
                        auto_order_count = None
                    try:
                        cur.execute(
                            """
                            SELECT COUNT(*) AS cnt
                            FROM edge_trades
                            WHERE state IN ('entry', 'entry_pending', 'exit_pending')
                               OR COALESCE(position_size, 0) > 0.000001
                               OR COALESCE(last_order_id, '') <> ''
                            """
                        )
                        active_trade_row = cur.fetchone()
                        active_trade_count = int(active_trade_row["cnt"] or 0) if active_trade_row else 0
                    except sqlite3.Error:
                        active_trade_count = None
                    trade_sync_subject_stats = {
                        "auto_orders": auto_order_count,
                        "active_trades": active_trade_count,
                        "idle_no_subjects": auto_order_count == 0 and active_trade_count == 0,
                    }
                except sqlite3.Error:
                    position_stats = {}
        except sqlite3.Error as exc:
            cached_payload = cached if isinstance(cached, dict) else None
            if cached_payload:
                payload = dict(cached_payload)
                payload["ok"] = True
                payload["level"] = payload.get("level") or "warn"
                payload["issues"] = list(payload.get("issues") or []) + [
                    {
                        "code": "health_db_unavailable",
                        "severity": "warn",
                        "group": "data",
                        "message": "健康检查 DB 读取失败（返回缓存）",
                        "evidence": {
                            "error": str(exc),
                            "budget_sec": health_budget_sec,
                            "timeout": bool(health_progress_interrupted),
                        },
                    }
                ]
                cache["payload"] = payload
                return payload
            _add_issue(
                "health_db_timeout" if health_progress_interrupted else "health_db_unavailable",
                "warn",
                "data",
                "健康检查 DB 读取超时" if health_progress_interrupted else "健康检查 DB 读取失败",
                {
                    "error": str(exc),
                    "budget_sec": health_budget_sec,
                    "timeout": bool(health_progress_interrupted),
                },
            )

        checked_fact_total = len(fact_rows or []) if not facts_skipped else 0
        facts_detail_unavailable = (
            (not facts_skipped)
            and int(facts_total_events or 0) > 0
            and checked_fact_total <= 0
        )
        total = checked_fact_total if checked_fact_total > 0 else (0 if facts_detail_unavailable else (facts_total_events if facts_total_events is not None else 0))
        model_ok = 0
        data_ok = 0
        link_ok = 0
        empty_model = 0
        empty_dist = 0
        q_cal_missing_rows = 0
        q_cal_total_rows = 0
        q_cal_missing_events = 0
        def _row_value(row: Any, key: str) -> Any:
            if isinstance(row, dict):
                return row.get(key)
            try:
                return row[key]
            except Exception:
                return None
    
        for row in fact_rows or []:
            fact = safe_json_loads(_row_value(row, "fact_json"))
            if not isinstance(fact, dict):
                continue
            model_count = 0
            try:
                model_count = int(fact.get("model_count") or 0)
            except (TypeError, ValueError):
                model_count = 0
            if model_count <= 0:
                empty_model += 1
                dist0 = normalize_distribution_rows(fact.get("distribution") or fact.get("rows") or [])
                model_count = len(_models_from_distribution(dist0))
            if model_count > 1:
                model_ok += 1
            dist = normalize_distribution_rows(fact.get("distribution") or fact.get("rows") or [])
            if dist:
                data_ok += 1
            else:
                empty_dist += 1
            if platt_stable and dist:
                missing_any = False
                for drow in dist:
                    if not isinstance(drow, dict):
                        continue
                    q_cal_total_rows += 1
                    q_cal = to_float(drow.get("q_calibrated"))
                    if q_cal is None or not math.isfinite(q_cal):
                        q_cal_missing_rows += 1
                        missing_any = True
                if missing_any:
                    q_cal_missing_events += 1
            url = str(fact.get("event_url") or "")
            if url.startswith("http://") or url.startswith("https://"):
                link_ok += 1
    
        # Interpret staleness & rate-limit signals.
        median_tick = to_float(market_tick_stats.get("median_age_sec"))
        max_tick = to_float(market_tick_stats.get("max_age_sec"))
        if isinstance(market_tick_stats, dict) and int(market_tick_stats.get("skipped_no_orderbook_count") or 0) > 0:
            _add_issue(
                "market_refresh_no_orderbook",
                "warn",
                "market",
                "部分市场无 CLOB 盘口（已从中位时效统计剔除）",
                {
                    "count": int(market_tick_stats.get("skipped_no_orderbook_count") or 0),
                    "samples": market_tick_stats.get("skipped_no_orderbook") if isinstance(market_tick_stats, dict) else None,
                },
            )
        if median_tick is not None and math.isfinite(median_tick) and median_tick >= float(HEALTH_MARKET_MEDIAN_STALE_SEC):
            _add_issue(
                "market_ticks_stale_median",
                "warn",
                "market",
                f"盘口快照中位时效过久（{int(median_tick // 60)}m）",
                {
                    "median_age_sec": median_tick,
                    "threshold_sec": HEALTH_MARKET_MEDIAN_STALE_SEC,
                    "oldest": market_tick_stats.get("oldest") if isinstance(market_tick_stats, dict) else None,
                },
            )
        if max_tick is not None and math.isfinite(max_tick) and max_tick >= float(HEALTH_MARKET_MAX_STALE_SEC):
            _add_issue(
                "market_ticks_stale_max",
                "warn",
                "market",
                f"全日宽表最旧盘口快照过久（{int(max_tick // 60)}m）",
                {
                    "max_age_sec": max_tick,
                    "threshold_sec": HEALTH_MARKET_MAX_STALE_SEC,
                    "oldest": market_tick_stats.get("oldest") if isinstance(market_tick_stats, dict) else None,
                },
            )
    
        fact_median_age = to_float(fact_age_stats.get("median_age_sec"))
        fact_max_age = to_float(fact_age_stats.get("max_age_sec"))
        if fact_median_age is not None and math.isfinite(fact_median_age) and fact_median_age >= float(HEALTH_SCAN_STALE_SEC):
            _add_issue(
                "facts_stale",
                "warn",
                "data",
                f"事实层（facts）中位时效过久（{int(fact_median_age // 60)}m）",
                {
                    "median_age_sec": fact_median_age,
                    "max_age_sec": fact_max_age,
                    "threshold_sec": HEALTH_SCAN_STALE_SEC,
                    "oldest": fact_age_stats.get("oldest") if isinstance(fact_age_stats, dict) else None,
                },
            )
    
        active_429 = to_float(cooldown_stats.get("open_meteo_429_active_now"))
        recent_429 = to_float(cooldown_stats.get("open_meteo_429_recent_6h"))
        if active_429 is not None and active_429 >= 5:
            _add_issue(
                "open_meteo_429_active",
                "warn",
                "model",
                "Open-Meteo 429 冷却中（请求扇出过大/限流）",
                {"active_now": int(active_429), "recent_6h": int(recent_429 or 0), "last_at": cooldown_stats.get("open_meteo_429_last_at")},
            )
    
        # Trade sync staleness based on status file (watcher layer).
        last_ok_age = _age_sec_from_iso(str(trade_sync_status.get("last_ok_at") or ""))
        trade_sync_idle = bool(trade_sync_subject_stats.get("idle_no_subjects"))
        if (
            (not ACCOUNT_REQUESTS_DISABLED)
            and _env_bool("PM_AUTO_TRADE_SYNC_TRADES", True)
            and not trade_sync_idle
            and (last_ok_age is None or last_ok_age >= float(HEALTH_TRADE_SYNC_STALE_SEC))
        ):
            _add_issue(
                "trade_sync_stale",
                "warn",
                "execution",
                "成交同步状态长时间未成功更新（unified trade_engine/成交同步链路可能卡住或网络失败）",
                {
                    "last_ok_at": str(trade_sync_status.get("last_ok_at") or ""),
                    "last_ok_age_sec": last_ok_age,
                    "last_error": str(trade_sync_status.get("last_error") or ""),
                    "last_error_is_502": bool(trade_sync_status.get("last_error_is_502")),
                    "threshold_sec": HEALTH_TRADE_SYNC_STALE_SEC,
                    "subjects": trade_sync_subject_stats,
                    "sync_driver": trade_sync_driver,
                    "trade_engine_pid": trade_engine_service_pid,
                    "legacy_trade_sync_loop_pid": legacy_trade_sync_service_pid,
                },
            )
        if (not ACCOUNT_REQUESTS_DISABLED) and watchdog.get("fetch_trades_timeout_recent"):
            _add_issue(
                "trade_sync_watchdog_timeout",
                "warn",
                "execution",
                "交易同步 watchdog：fetch-trades 超时（窗口内）",
                {"watchdog": watchdog},
            )
        if isinstance(exec_blockers, dict) and exec_blockers.get("has_blocker"):
            source = str(exec_blockers.get("source") or "edge_trades")
            msg = "执行层存在阻塞（auto_trade_jobs）" if source == "auto_trade_jobs" else "执行层存在阻塞（持仓执行账本 last_error）"
            _add_issue(
                "execution_blockers",
                "warn",
                "execution",
                msg,
                {
                    "source": source,
                    "top_error": exec_blockers.get("top_error"),
                    "counts": exec_blockers.get("counts"),
                    "latest": exec_blockers.get("latest"),
                },
            )
        holdoff_count = int((exec_edge_blockers or {}).get("holdoff_count") or 0) if isinstance(exec_edge_blockers, dict) else 0
        if holdoff_count > 0:
            _add_issue(
                "exit_holdoff_waiting",
                "ok",
                "execution",
                "存在退出等待中持仓（min_hold 未到，不属于执行阻塞）",
                {
                    "holdoff_count": holdoff_count,
                    "holdoff_samples": (exec_edge_blockers or {}).get("holdoff_samples"),
                },
            )
        if isinstance(position_stats, dict):
            open_pos = int(position_stats.get("open_positions") or 0)
            exit_pos_active = int(position_stats.get("exit_positions_active") or 0)
            exit_pos_waiting = int(position_stats.get("exit_positions_waiting") or 0)
            exit_pos_legacy = int(position_stats.get("exit_positions_legacy") or 0)
            if exit_pos_active > 0:
                if exit_pos_waiting > 0 and exit_pos_waiting == exit_pos_active:
                    _add_issue(
                        "exit_positions_waiting",
                        "ok",
                        "execution",
                        "存在退出态持仓（均为 min_hold 等待中）",
                        {
                            "exit_positions": exit_pos_active,
                            "exit_positions_waiting": exit_pos_waiting,
                            "open_positions": open_pos,
                            "last_updated_at": position_stats.get("last_updated_at"),
                            "exit_samples": position_stats.get("exit_samples") if isinstance(position_stats, dict) else None,
                        },
                    )
                else:
                    _add_issue(
                        "exit_positions_active",
                        "warn",
                        "execution",
                        "存在退出态持仓（exit state）等待处理",
                        {
                            "exit_positions": exit_pos_active,
                            "exit_positions_waiting": exit_pos_waiting,
                            "open_positions": open_pos,
                            "last_updated_at": position_stats.get("last_updated_at"),
                            "exit_samples": position_stats.get("exit_samples") if isinstance(position_stats, dict) else None,
                        },
                    )
            elif exit_pos_legacy > 0:
                _add_issue(
                    "exit_positions_legacy",
                    "ok",
                    "execution",
                    "存在历史退出态残余持仓（不影响今日自动交易）",
                    {
                        "exit_positions": exit_pos_legacy,
                        "open_positions": open_pos,
                        "last_updated_at": position_stats.get("last_updated_at"),
                        "exit_samples": position_stats.get("exit_samples_legacy") if isinstance(position_stats, dict) else None,
                    },
                )
    
        # If auto-trade is enabled, but there are eligible entries yet no will_order, surface the top blocker.
        entry_ok_count = int(decision_stats.get("entry_ok_count") or 0)
        will_order_count = int(decision_stats.get("will_order_count") or 0)
        if diag.get("enabled") and entry_ok_count > 0 and will_order_count <= 0:
            top = (decision_stats.get("top_reason_codes") or [])
            top_code = str(top[0].get("code") or "") if top and isinstance(top[0], dict) else ""
            _add_issue(
                "eligible_but_no_order",
                "warn",
                "policy",
                "存在“今日达标事件”，但本轮没有 will_order=1（被风控/门槛/节流阻断）",
                {"entry_ok_count": entry_ok_count, "top_reason_code": top_code, "top_reason_codes": top},
            )
        if not diag.get("enabled") and entry_ok_count > 0:
            _add_issue(
                "eligible_but_disabled",
                "warn",
                "policy",
                "存在“今日达标事件”，但 PM_AUTO_TRADE_ENABLED=0（已暂停）",
                {"entry_ok_count": entry_ok_count},
            )
    
        # Model/data coverage signals.
        if facts_detail_unavailable:
            _add_issue(
                "facts_detail_unavailable",
                "warn",
                "data",
                "facts 明细读取不完整（跳过分布覆盖率判定）",
                {
                    "raw_total_events": facts_total_events,
                    "raw_total_rows": facts_total_rows,
                    "timeout": bool(health_progress_interrupted),
                },
            )
        if not facts_skipped and checked_fact_total > 0 and model_ok <= 0:
            _add_issue(
                "no_valid_models",
                "error",
                "model",
                "无有效模型分布（可能出现：No valid ensemble values for any model）",
                {"total": checked_fact_total, "empty_model": empty_model},
            )
        if not facts_skipped and checked_fact_total > 0 and data_ok <= 0:
            _add_issue("no_distribution", "error", "data", "facts 无分布数据（distribution 为空）", {"total": checked_fact_total, "empty_dist": empty_dist})
        if not facts_skipped and platt_stable and q_cal_total_rows > 0 and q_cal_missing_rows > 0:
            ratio = q_cal_missing_rows / q_cal_total_rows
            _add_issue(
                "q_calibrated_missing_ratio",
                "warn",
                "model",
                f"q_calibrated 缺失比例 {ratio:.1%}（Platt 已稳定）",
                {
                    "missing_rows": q_cal_missing_rows,
                    "total_rows": q_cal_total_rows,
                    "missing_events": q_cal_missing_events,
                    "ratio": ratio,
                    "platt_generated_at": (platt or {}).get("generated_at") if isinstance(platt, dict) else "",
                },
            )
    
        # Balance cache snapshot (avoid forcing node calls from health endpoint).
        balance_payload = AUTO_TRADE_BALANCE_CACHE.get("payload") if isinstance(AUTO_TRADE_BALANCE_CACHE, dict) else {}
        balance_ts = float(AUTO_TRADE_BALANCE_CACHE.get("ts") or 0.0) if isinstance(AUTO_TRADE_BALANCE_CACHE, dict) else 0.0
        balance_age_sec = max(0.0, (time.time() - balance_ts)) if balance_ts else None
        balance_ok = bool(balance_payload.get("ok")) if isinstance(balance_payload, dict) else False
        balance_err = str(balance_payload.get("error") or "") if isinstance(balance_payload, dict) else ""
        suppress_balance_issue = False
        if balance_err and "Errno 24" in balance_err and balance_age_sec is not None and balance_age_sec >= ERRNO24_CLEAR_SEC:
            suppress_balance_issue = True
            if isinstance(balance_payload, dict):
                balance_payload = {**balance_payload, "error": ""}
        if diag.get("enabled") and (not balance_disabled) and not balance_ok and balance_payload and not suppress_balance_issue:
            _add_issue(
                "balance_unavailable",
                "warn",
                "account",
                "余额同步不可用（balance 缓存非 ok）",
                {"error": balance_err, "age_sec": balance_age_sec},
            )
        config_full = auto_trade_config_defaults() or {}
        order_usdc = to_float(config_full.get("order_usdc"))
        bal_allow = to_float(balance_payload.get("balance_allowance") if isinstance(balance_payload, dict) else None)
        if bal_allow is None:
            bal_allow = to_float(balance_payload.get("balance") if isinstance(balance_payload, dict) else None)
        if diag.get("enabled") and (not balance_disabled) and balance_ok and order_usdc is not None and math.isfinite(order_usdc):
            if bal_allow is None or not math.isfinite(bal_allow):
                _add_issue("balance_unknown", "warn", "account", "余额/allowance 未知（无可用 balance 缓存）")
            elif bal_allow + 1e-9 < float(order_usdc):
                _add_issue(
                    "insufficient_balance",
                    "error",
                    "account",
                    "余额/allowance 不足，无法按 PM_ORDER_USDC 下单",
                    {"balance_allowance": bal_allow, "order_usdc": order_usdc},
                )
    
        def _level_from_issues(rows: List[Dict[str, Any]]) -> str:
            severities = [str(r.get("severity") or "") for r in rows or []]
            if any(s == "error" for s in severities):
                return "error"
            if any(s == "warn" for s in severities):
                return "warn"
            return "ok"
    
        if _scan_alerts_paused():
            issues = [it for it in issues if not _health_issue_suppressed_when_scan_paused(it)]
            issues = [
                it
                for it in issues
                if str((it or {}).get("severity") or "").strip().lower() == "ok"
            ]
        issues = _suppress_errno24_issues(issues)
        level = _level_from_issues(issues)
        counts_by_sev: Dict[str, int] = {"error": 0, "warn": 0, "ok": 0}
        for it in issues:
            sev = str(it.get("severity") or "warn")
            if sev not in counts_by_sev:
                sev = "warn"
            counts_by_sev[sev] = int(counts_by_sev.get(sev) or 0) + 1

        payload = {
            "ok": True,
            "level": level,
            "issue_counts": counts_by_sev,
            "issues": issues,
            "scan_alerts_paused": bool(_scan_alerts_paused()),
            "total": total,
            "total_rows": facts_total_rows,
            "total_events": facts_total_events,
            "checked_events": checked_fact_total,
            "facts_detail_unavailable": bool(facts_detail_unavailable),
            "modelOk": model_ok,
            "dataOk": data_ok,
            "linkOk": link_ok,
            "emptyModel": empty_model,
            "emptyDist": empty_dist,
            "updated_at": now_text(),
            "run_date": run_date_key or run_date,
            "env": {
                "enabled": bool(diag.get("enabled")),
                "dry_run": bool(diag.get("dry_run")),
                "missing": list(diag.get("missing") or []),
                "signature_type": diag.get("signature_type"),
                "balance_owner": diag.get("balance_owner"),
                "signer_address": str(diag.get("signer_address") or ""),
                "funder_address": str(diag.get("funder_address") or ""),
                "sync_trades": _env_bool("PM_AUTO_TRADE_SYNC_TRADES", True),
                "sync_open_orders": _env_bool("PM_AUTO_TRADE_SYNC_OPEN_ORDERS", True),
            },
            "services": services,
            "market_ticks": market_tick_stats,
            "facts": fact_age_stats,
            "cooldowns": cooldown_stats,
            "decisions": decision_stats,
            "chase_stats": chase_stats,
            "trade_sync": {
                "status": trade_sync_status,
                "watchdog": watchdog,
                "subjects": trade_sync_subject_stats,
            },
            "execution": {
                "blockers": exec_blockers,
                "blockers_jobs": exec_job_blockers,
                "blockers_edge": exec_edge_blockers,
                "positions": position_stats,
            },
            "balance_cache": {
                "ok": bool(balance_ok),
                "age_sec": balance_age_sec,
                "updated_at": str(balance_payload.get("updated_at") or "") if isinstance(balance_payload, dict) else "",
                "error": str(balance_payload.get("error") or "") if isinstance(balance_payload, dict) else "",
                "balance": balance_payload.get("balance") if isinstance(balance_payload, dict) else None,
                "allowance": balance_payload.get("allowance") if isinstance(balance_payload, dict) else None,
                "balance_allowance": balance_payload.get("balance_allowance") if isinstance(balance_payload, dict) else None,
            },
            "fd_usage": fd_usage,
            "policy": {
                "config": {k: v for k, v in (config_full or {}).items() if k in {
                    "edge_score_min",
                    "entry_min_outcome_volume",
                    "entry_outcome_volume_gate_mode",
                    "entry_outcome_volume_refresh_sec",
                    "entry_outcome_volume_refresh_missing_only",
                    "entry_require_signal_edge",
                    "entry_signal_edge_min",
                    "entry_require_ask_range",
                    "entry_ask_min",
                    "entry_ask_max",
                    "entry_require_q_range",
                    "entry_q_min",
                    "entry_q_max",
                    "auto_max_ask",
                    "market_tick_stale_sec",
                    "entry_follow_market_tick_stale_sec",
                    "entry_follow_market_min_usdc",
                    "mirror_min_order_usdc",
                    "entry_follow_refresh_pre_stale_ratio",
                    "entry_follow_yes_aux_size_ratio",
                    "entry_follow_yes_aux_rank_mode",
                    "entry_follow_yes_aux_allow_negative_edge",
                    "market_tick_require_present",
                    "stop_loss_require_edge_confirm",
                    "stop_loss_edge_confirm_max",
                    "exec_edge_spread_weight",
                    "exec_edge_depth_penalty_weight",
                    "exec_edge_cancel_cost",
                    "exec_edge_retry_cost",
                    "settled_reconcile_interval_sec",
                    "settled_reconcile_dust",
                    "open_order_wait_sec",
                    "open_order_recheck_cooldown_sec",
                    "open_order_auto_cancel_enabled",
                    "open_order_auto_cancel_sec",
                    "reentry_cooldown_sec",
                    "order_usdc",
                    "entry_main_size_ratio",
                    "entry_yes_top_size_ratio",
                    "entry_follow_size_ratio",
                    "entry_hard_bound_no_size_ratio",
                    "entry_adj_pair_size_ratio",
                    "mirror_follow_size_ratio",
                    "entry_main_enabled",
                    "entry_yes_top_enabled",
                    "entry_follow_enabled",
                    "entry_hard_bound_no_enabled",
                    "entry_adj_pair_enabled",
                    "mirror_follow_enabled",
                }},
            },
        }
        if lock_stale_bypass:
            payload["health_lock_stale_bypass"] = {
                "active": True,
                "cache_age_sec": cache_age_sec,
                "lock_stale_sec": AUTO_TRADE_HEALTH_LOCK_STALE_SEC,
            }
        _cache_set(payload)
        return dict(payload)
    finally:
        if lock_acquired:
            AUTO_TRADE_HEALTH_LOCK.release()
            AUTO_TRADE_HEALTH_LOCK_AT = 0.0


def _resolve_node_bin() -> str:
    env_val = os.environ.get("PM_NODE_BIN") or os.environ.get("PM_NODE_PATH")
    if env_val:
        return env_val
    node_path = shutil.which("node")
    if node_path:
        return node_path
    for candidate in ("/opt/homebrew/bin/node", "/usr/local/bin/node"):
        if Path(candidate).exists():
            return candidate
    return "node"


def _is_errno24_error_text(text: Any) -> bool:
    blob = str(text or "")
    if not blob:
        return False
    lower = blob.lower()
    return (
        ("errno 24" in lower)
        or ("too many open files" in lower)
        or ("exec_errno24" in lower)
        or ("emfile" in lower)
    )


def _is_exec_timeout_error_text(text: Any) -> bool:
    blob = str(text or "").strip().lower()
    if not blob:
        return False
    return ("timed out after" in blob) or ("timeoutexpired" in blob) or ("exec_timeout" in blob)


def _is_upstream_5xx_error_text(text: Any) -> bool:
    blob = str(text or "").strip().lower()
    if not blob:
        return False
    return (
        ("status code 502" in blob)
        or ("status code 503" in blob)
        or ("status code 504" in blob)
        or ("http 502" in blob)
        or ("http 503" in blob)
        or ("http 504" in blob)
        or ("bad gateway" in blob)
        or ("gateway timeout" in blob)
        or ("service unavailable" in blob)
    )


def _normalize_errno24_payload(payload: Dict[str, Any]) -> Dict[str, Any]:
    out = dict(payload or {})
    blob = " ".join(
        str(out.get(key, "") or "")
        for key in ("error", "error_detail", "stderr", "stdout", "detail")
    )
    if _is_errno24_error_text(blob):
        out["error"] = "exec_errno24"
        out.setdefault("error_detail", "too_many_open_files")
    return out


def _sanitize_errno24_text(text: Any) -> Any:
    if not isinstance(text, str):
        return text
    out = str(text)
    if not _is_errno24_error_text(out):
        return out
    out = re.sub(r"exec_failed:\s*\[Errno\s*24\]\s*Too many open files", "文件句柄不足（已自动降级）", out, flags=re.IGNORECASE)
    out = re.sub(r"\[Errno\s*24\]\s*Too many open files", "文件句柄不足（已自动降级）", out, flags=re.IGNORECASE)
    out = re.sub(r"Too many open files", "文件句柄不足（已自动降级）", out, flags=re.IGNORECASE)
    out = re.sub(r"Errno\s*24", "文件句柄不足（已自动降级）", out, flags=re.IGNORECASE)
    out = re.sub(r"\bEMFILE\b", "文件句柄不足（已自动降级）", out, flags=re.IGNORECASE)
    out = re.sub(r"\bexec_errno24\b", "文件句柄不足（已自动降级）", out, flags=re.IGNORECASE)
    out = re.sub(r"文件句柄不足（已自动降级）(?:\\s*[:：-]\\s*)?文件句柄不足（已自动降级）", "文件句柄不足（已自动降级）", out)
    return out


def _sanitize_errno24_payload(payload: Any) -> Any:
    if isinstance(payload, dict):
        return {str(k): _sanitize_errno24_payload(v) for k, v in payload.items()}
    if isinstance(payload, list):
        return [_sanitize_errno24_payload(v) for v in payload]
    if isinstance(payload, tuple):
        return [_sanitize_errno24_payload(v) for v in payload]
    if isinstance(payload, str):
        return _sanitize_errno24_text(payload)
    return payload


def _prune_raw_response_fields_in_place(node: Any) -> None:
    if isinstance(node, dict):
        node.pop("raw_response", None)
        for value in node.values():
            _prune_raw_response_fields_in_place(value)
        return
    if isinstance(node, list):
        for value in node:
            _prune_raw_response_fields_in_place(value)
        return
    if isinstance(node, tuple):
        for value in node:
            _prune_raw_response_fields_in_place(value)


def _slim_fact_payload_for_ui(payload: Any) -> Any:
    if not isinstance(payload, dict):
        return payload
    _attach_production_posterior_display_contract(payload)
    distribution = payload.get("distribution") or payload.get("rows")
    if isinstance(distribution, list):
        for row in distribution:
            if not isinstance(row, dict):
                continue
            bayes_chain = _bayes_chain_for_distribution_row(row)
            if bayes_chain:
                row.setdefault("bayes_chain", bayes_chain)
                row.setdefault("q_prior", bayes_chain.get("prior_prob"))
                row.setdefault("q_likelihood", bayes_chain.get("likelihood_prob"))
    soft_channels = _ui_snapshot_soft_forecast_channels(payload, distribution)
    if soft_channels:
        payload["soft_forecast_posterior_channels"] = soft_channels
    compact_features = payload.get("weather_likelihood_features_compact")
    if not isinstance(compact_features, Mapping):
        compact_features = _compact_weather_likelihood_features_for_ui(
            payload.get("weather_likelihood_features")
        )
    else:
        compact_features = dict(compact_features)
        full_compact_features = _compact_weather_likelihood_features_for_ui(
            payload.get("weather_likelihood_features")
        )
        for key, value in full_compact_features.items():
            if key not in compact_features and value not in (None, "", [], {}):
                compact_features[key] = value
    if compact_features:
        payload["weather_likelihood_features_compact"] = _normalize_ui_temperature_rise_rate_fields(
            compact_features
        )
    _normalize_ui_temperature_trajectory_root_fields(payload)
    trajectory_status = _ui_temperature_trajectory_status_from_payload(payload, distribution)
    if trajectory_status:
        payload["temperature_trajectory_status"] = trajectory_status
    _attach_rebound_regime_signal(payload, distribution)
    _attach_ui_snapshot_sections_to_item(payload)
    if not UI_STRIP_MODEL_RAW:
        return payload
    provenance = payload.get("model_provenance")
    if isinstance(provenance, (dict, list, tuple)):
        _prune_raw_response_fields_in_place(provenance)
    return payload


def _compact_model_bucket_meta_for_ui_snapshot(meta: Any) -> Optional[Dict[str, Any]]:
    if not isinstance(meta, Mapping):
        return None
    out: Dict[str, Any] = {}
    labels = meta.get("labels")
    if isinstance(labels, list):
        out["labels"] = labels
    for key in ("probs_by_model", "counts_by_model"):
        value = meta.get(key)
        if isinstance(value, Mapping):
            out[key] = dict(value)
    return out or None


def _model_bucket_label_for_rule(
    value: Any,
    labels: Sequence[Any],
    rule: str,
    market_unit: str,
) -> str:
    value_num = to_float(value)
    if value_num is None or not math.isfinite(value_num):
        return ""
    rule_key = str(rule or "").strip().lower()
    if rule_key == "floor":
        bucket_value = math.floor(float(value_num))
    elif rule_key == "ceil":
        bucket_value = math.ceil(float(value_num))
    else:
        bucket_value = math.floor(float(value_num) + 0.5)
    unit = str(market_unit or "C").strip() or "C"
    exact: Dict[int, str] = {}
    lower: Optional[Tuple[int, str]] = None
    upper: Optional[Tuple[int, str]] = None
    for raw_label in labels:
        label = str(raw_label or "").strip()
        if not label:
            continue
        match = re.search(r"(-?\d+(?:\.\d+)?)", label)
        if not match:
            continue
        number = int(round(float(match.group(1))))
        lower_text = label.lower()
        if "below" in lower_text or "or below" in lower_text or "<=" in lower_text:
            lower = (number, label)
        elif "higher" in lower_text or "or higher" in lower_text or ">=" in lower_text:
            upper = (number, label)
        else:
            exact[number] = label
    bucket_int = int(bucket_value)
    if bucket_int in exact:
        return exact[bucket_int]
    if lower and bucket_int <= lower[0]:
        return lower[1]
    if upper and bucket_int >= upper[0]:
        return upper[1]
    return f"{bucket_int}°{unit}"


def _model_bucket_rule_probability_meta(
    members_by_model: Any,
    labels: Sequence[Any],
    rule: str,
    market_unit: str,
) -> Optional[Dict[str, Any]]:
    if not isinstance(members_by_model, Mapping):
        return None
    label_list = [str(label or "").strip() for label in labels if str(label or "").strip()]
    if not label_list:
        return None
    counts_by_model: Dict[str, Dict[str, int]] = {}
    probs_by_model: Dict[str, Dict[str, float]] = {}
    top_by_model: Dict[str, Dict[str, Any]] = {}
    member_total = 0
    for model, raw_members in members_by_model.items():
        if not isinstance(raw_members, Sequence) or isinstance(raw_members, (str, bytes, bytearray)):
            continue
        counts = {label: 0 for label in label_list}
        valid_count = 0
        for member in raw_members:
            label = _model_bucket_label_for_rule(member, label_list, rule, market_unit)
            if not label:
                continue
            if label not in counts:
                counts[label] = 0
            counts[label] += 1
            valid_count += 1
        if valid_count <= 0:
            continue
        model_key = str(model)
        probs = {label: float(counts.get(label, 0)) / float(valid_count) for label in label_list}
        counts_by_model[model_key] = {label: int(counts.get(label, 0)) for label in label_list}
        probs_by_model[model_key] = probs
        top_label = max(label_list, key=lambda label: (probs.get(label, 0.0), -label_list.index(label)))
        top_by_model[model_key] = {
            "label": top_label,
            "q": probs.get(top_label, 0.0),
            "count": int(counts.get(top_label, 0)),
            "n": int(valid_count),
        }
        member_total += valid_count
    if not probs_by_model:
        return None
    return {
        "labels": label_list,
        "rule": str(rule or ""),
        "counts_by_model": counts_by_model,
        "probs_by_model": probs_by_model,
        "top_by_model": top_by_model,
        "member_count": int(member_total),
    }


def _model_bucket_rule_top_delta(raw_top: Any, qm_top: Any, labels: Sequence[Any]) -> Dict[str, Any]:
    if not isinstance(raw_top, Mapping) or not isinstance(qm_top, Mapping):
        return {}
    raw_label = str(raw_top.get("label") or "")
    qm_label = str(qm_top.get("label") or "")
    label_order = {str(label): idx for idx, label in enumerate(labels)}
    out: Dict[str, Any] = {
        "raw_label": raw_label,
        "qm_label": qm_label,
        "top_changed": bool(raw_label and qm_label and raw_label != qm_label),
    }
    raw_q = to_float(raw_top.get("q"))
    qm_q = to_float(qm_top.get("q"))
    if raw_q is not None and qm_q is not None and math.isfinite(raw_q) and math.isfinite(qm_q):
        out["prob_delta"] = float(qm_q) - float(raw_q)
    if raw_label in label_order and qm_label in label_order:
        out["bucket_index_delta"] = int(label_order[qm_label]) - int(label_order[raw_label])
    return out


def _model_raw_top_from_probability_map(prob_map: Any, labels: Sequence[Any]) -> Dict[str, Any]:
    if not isinstance(prob_map, Mapping):
        return {}
    candidates: List[Tuple[float, int, str]] = []
    label_list = [str(label or "").strip() for label in labels if str(label or "").strip()]
    if not label_list:
        label_list = [str(label or "").strip() for label in prob_map.keys() if str(label or "").strip()]
    for index, label in enumerate(label_list):
        q = to_float(prob_map.get(label))
        if q is None or not math.isfinite(q):
            continue
        candidates.append((float(q), -index, label))
    if not candidates:
        return {}
    q, _order, label = max(candidates)
    return {"label": label, "q": float(q)}


def _model_raw_top_state_from_snapshot_payload(payload: Any) -> Dict[str, Any]:
    if not isinstance(payload, Mapping):
        return {}
    distribution = payload.get("distribution") or payload.get("rows") or []
    first_row = distribution[0] if isinstance(distribution, list) and distribution and isinstance(distribution[0], Mapping) else {}
    qm_meta = first_row.get("q_ensemble_qm_meta") if isinstance(first_row, Mapping) else {}
    if not isinstance(qm_meta, Mapping):
        qm_meta = {}
    raw_bucket = qm_meta.get("raw_bucket_probability") if isinstance(qm_meta.get("raw_bucket_probability"), Mapping) else {}
    if not raw_bucket:
        ensemble_qm = payload.get("ensemble_qm_bucket")
        if isinstance(ensemble_qm, Mapping):
            raw_bucket = (
                ensemble_qm.get("raw_bucket_probability")
                if isinstance(ensemble_qm.get("raw_bucket_probability"), Mapping)
                else {}
            )
            provenance = ensemble_qm.get("provenance")
            if not raw_bucket and isinstance(provenance, Mapping):
                raw_bucket = (
                    provenance.get("raw_bucket_probability")
                    if isinstance(provenance.get("raw_bucket_probability"), Mapping)
                    else {}
                )
    labels = raw_bucket.get("labels") if isinstance(raw_bucket, Mapping) else []
    probs_by_model = raw_bucket.get("probs_by_model") if isinstance(raw_bucket, Mapping) else {}
    if not isinstance(labels, list) or not isinstance(probs_by_model, Mapping):
        return {}
    models: Dict[str, Dict[str, Any]] = {}
    for model, prob_map in probs_by_model.items():
        top = _model_raw_top_from_probability_map(prob_map, labels)
        if top:
            models[str(model)] = top
    if not models:
        return {}
    score_meta = payload.get("score_composer") if isinstance(payload.get("score_composer"), Mapping) else {}
    return {
        "labels": [str(label) for label in labels],
        "models": models,
        "model_snapshot_at": str(score_meta.get("model_snapshot_at") or payload.get("model_snapshot_at") or ""),
        "model_snapshot_id": _to_int(score_meta.get("model_snapshot_id") or payload.get("model_snapshot_id")),
    }


def _model_raw_top_history_for_ui_snapshot(
    conn: sqlite3.Connection,
    payload: Mapping[str, Any],
    row: Any = None,
    *,
    limit: int = 96,
) -> Optional[Dict[str, Any]]:
    if not isinstance(payload, Mapping):
        return None
    slug = str(payload.get("slug") or "").strip()
    event_date = _normalize_date_key(str(payload.get("event_date") or ""))
    if not slug or not event_date:
        return None
    referenced_model_snapshot_id = None
    if row is not None:
        try:
            referenced_model_snapshot_id = _to_int(row["model_snapshot_id"])
        except Exception:
            referenced_model_snapshot_id = None
    if referenced_model_snapshot_id is None:
        referenced_model_snapshot_id = _to_int(payload.get("model_snapshot_id"))
    fact_as_of = str(payload.get("fact_as_of") or "").strip()
    if not fact_as_of and row is not None:
        try:
            fact_as_of = str(row["fact_as_of"] or "").strip()
        except Exception:
            fact_as_of = ""
    model_snapshot_id = referenced_model_snapshot_id
    current_created_at = ""
    referenced_created_at = ""
    selection_reason = "referenced_model_snapshot"
    if referenced_model_snapshot_id is not None:
        try:
            snap_row = conn.execute(
                "SELECT created_at FROM model_snapshots WHERE id = ? LIMIT 1",
                (int(referenced_model_snapshot_id),),
            ).fetchone()
            if snap_row is not None:
                referenced_created_at = str(snap_row["created_at"] if isinstance(snap_row, sqlite3.Row) else snap_row[0] or "")
                current_created_at = referenced_created_at
        except Exception:
            current_created_at = ""
    if fact_as_of:
        try:
            latest_row = conn.execute(
                """
                SELECT id, created_at
                FROM model_snapshots
                WHERE slug = ? AND event_date = ? AND created_at <= ?
                ORDER BY created_at DESC, id DESC
                LIMIT 1
                """,
                (slug, event_date, fact_as_of),
            ).fetchone()
        except Exception:
            latest_row = None
        if latest_row is not None:
            latest_id = latest_row["id"] if isinstance(latest_row, sqlite3.Row) else latest_row[0]
            latest_created_at = str(latest_row["created_at"] if isinstance(latest_row, sqlite3.Row) else latest_row[1] or "")
            if latest_created_at and (not current_created_at or latest_created_at > current_created_at):
                model_snapshot_id = _to_int(latest_id)
                current_created_at = latest_created_at
                selection_reason = "latest_model_snapshot_before_fact_as_of"
    rows: List[sqlite3.Row] = []
    try:
        if current_created_at:
            rows = conn.execute(
                """
                SELECT id, created_at, payload_json
                FROM model_snapshots
                WHERE slug = ? AND event_date = ? AND created_at <= ?
                ORDER BY created_at DESC, id DESC
                LIMIT ?
                """,
                (slug, event_date, current_created_at, max(1, int(limit))),
            ).fetchall()
        else:
            rows = conn.execute(
                """
                SELECT id, created_at, payload_json
                FROM model_snapshots
                WHERE slug = ? AND event_date = ?
                ORDER BY created_at DESC, id DESC
                LIMIT ?
                """,
                (slug, event_date, max(1, int(limit))),
            ).fetchall()
    except Exception:
        rows = []
    points: List[Dict[str, Any]] = []
    labels: List[str] = []
    for snap_row in reversed(rows):
        try:
            raw_payload = snap_row["payload_json"] if isinstance(snap_row, sqlite3.Row) else snap_row[2]
            snap_payload = json.loads(raw_payload or "{}")
        except Exception:
            continue
        state = _model_raw_top_state_from_snapshot_payload(snap_payload)
        models = state.get("models") if isinstance(state, Mapping) else {}
        if not isinstance(models, Mapping) or not models:
            continue
        if not labels and isinstance(state.get("labels"), list):
            labels = [str(label) for label in state.get("labels") or []]
        snapshot_id = snap_row["id"] if isinstance(snap_row, sqlite3.Row) else snap_row[0]
        created_at = snap_row["created_at"] if isinstance(snap_row, sqlite3.Row) else snap_row[1]
        points.append(
            {
                "snapshot_id": int(snapshot_id),
                "snapshot_at": str(created_at or ""),
                "model_snapshot_at": str(state.get("model_snapshot_at") or created_at or ""),
                "models": {str(model): dict(value) for model, value in models.items() if isinstance(value, Mapping)},
            }
        )
    if not points:
        return None
    return {
        "version": "model_raw_top_history_v1",
        "source": "model_snapshots",
        "role": "backend_model_snapshot_history",
        "slug": slug,
        "event_date": event_date,
        "labels": labels,
        "limit": max(1, int(limit)),
        "point_count": len(points),
        "current_snapshot_id": points[-1].get("snapshot_id"),
        "previous_snapshot_id": points[-2].get("snapshot_id") if len(points) >= 2 else None,
        "referenced_model_snapshot_id": referenced_model_snapshot_id,
        "referenced_model_snapshot_at": referenced_created_at,
        "selected_snapshot_id": model_snapshot_id,
        "selection_reason": selection_reason,
        "points": points,
    }


def _attach_model_raw_top_history_for_ui_snapshot(
    conn: sqlite3.Connection,
    payload: MutableMapping[str, Any],
    row: Any = None,
) -> None:
    if not isinstance(payload, MutableMapping):
        return
    history = _model_raw_top_history_for_ui_snapshot(conn, payload, row)
    if history:
        payload["model_raw_top_history"] = history


UI_SNAPSHOT_MODEL_MEMBER_CACHE_MODELS: Tuple[str, ...] = (
    "gfs_seamless",
    "icon_seamless",
    "ecmwf_ifs025",
)


def _model_member_cache_loc_key_for_ui_snapshot(payload: Mapping[str, Any]) -> str:
    if not isinstance(payload, Mapping):
        return ""
    if _is_chengdu_zuuu_fact_payload(str(payload.get("slug") or ""), payload):
        return "30.5583,103.9460"
    lat = _to_float_safe(payload.get("lat") or payload.get("station_lat") or payload.get("city_lat"))
    lon = _to_float_safe(payload.get("lon") or payload.get("station_lon") or payload.get("city_lon"))
    if lat is None or lon is None:
        return ""
    return f"{float(lat):.4f},{float(lon):.4f}"


def _coerce_model_member_cache_values(raw_members: Any) -> List[float]:
    if not isinstance(raw_members, Sequence) or isinstance(raw_members, (str, bytes, bytearray)):
        return []
    values: List[float] = []
    for raw_value in raw_members:
        value = to_float(raw_value)
        if value is None or not math.isfinite(value):
            continue
        values.append(round(float(value), 3))
    return values


def _attach_model_member_cache_snapshot_for_ui_snapshot(
    conn: sqlite3.Connection,
    payload: MutableMapping[str, Any],
    row: Any = None,
) -> None:
    if not isinstance(payload, MutableMapping):
        return
    event_date = _normalize_date_key(str(payload.get("event_date") or ""))
    if not event_date and row is not None:
        try:
            event_date = _normalize_date_key(str(row["event_date"] or ""))
        except Exception:
            event_date = ""
    if not event_date:
        return
    market_var = str(payload.get("market_var") or "temperature_2m_max").strip() or "temperature_2m_max"
    market_unit = str(payload.get("market_unit") or "C").strip() or "C"
    loc_key = _model_member_cache_loc_key_for_ui_snapshot(payload)
    existing_raw = payload.get("model_members_decimal_raw")
    raw_members_by_model: Dict[str, Any] = dict(existing_raw) if isinstance(existing_raw, Mapping) else {}
    existing_qm = payload.get("model_members")
    qm_members_by_model: Dict[str, Any] = dict(existing_qm) if isinstance(existing_qm, Mapping) else {}
    counts_raw = payload.get("model_member_counts_raw")
    counts_raw_by_model: Dict[str, Any] = dict(counts_raw) if isinstance(counts_raw, Mapping) else {}
    counts = payload.get("model_member_counts")
    counts_by_model: Dict[str, Any] = dict(counts) if isinstance(counts, Mapping) else {}
    provenance_raw = payload.get("model_provenance")
    provenance: Dict[str, Any] = dict(provenance_raw) if isinstance(provenance_raw, Mapping) else {}
    snapshot_raw = payload.get("model_member_cache_snapshot")
    snapshot: Dict[str, Any] = dict(snapshot_raw) if isinstance(snapshot_raw, Mapping) else {}
    snapshot_models_raw = snapshot.get("models")
    snapshot_models: Dict[str, Any] = dict(snapshot_models_raw) if isinstance(snapshot_models_raw, Mapping) else {}
    filled_models: List[str] = []
    missing_models: List[str] = []
    for model in UI_SNAPSHOT_MODEL_MEMBER_CACHE_MODELS:
        already_has_raw = isinstance(raw_members_by_model.get(model), Sequence) and not isinstance(
            raw_members_by_model.get(model), (str, bytes, bytearray)
        ) and bool(raw_members_by_model.get(model))
        already_has_qm = isinstance(qm_members_by_model.get(model), Sequence) and not isinstance(
            qm_members_by_model.get(model), (str, bytes, bytearray)
        ) and bool(qm_members_by_model.get(model))
        if already_has_raw and already_has_qm and model in snapshot_models:
            continue
        try:
            if loc_key:
                cache_row = conn.execute(
                    """
                    SELECT members_json, loc_key, created_at, official_updated_at,
                           official_updated_source, members_signature
                    FROM model_member_cache
                    WHERE model = ? AND loc_key = ? AND event_date = ?
                      AND market_var = ? AND market_unit = ?
                    ORDER BY datetime(created_at) DESC
                    LIMIT 1
                    """,
                    (model, loc_key, event_date, market_var, market_unit),
                ).fetchone()
            else:
                cache_row = None
            if cache_row is None:
                cache_row = conn.execute(
                    """
                    SELECT members_json, loc_key, created_at, official_updated_at,
                           official_updated_source, members_signature
                    FROM model_member_cache
                    WHERE model = ? AND event_date = ?
                      AND market_var = ? AND market_unit = ?
                    ORDER BY datetime(created_at) DESC
                    LIMIT 1
                    """,
                    (model, event_date, market_var, market_unit),
                ).fetchone()
        except Exception:
            cache_row = None
        if cache_row is None:
            missing_models.append(model)
            continue
        try:
            members = _coerce_model_member_cache_values(json.loads(str(cache_row["members_json"] or "[]")))
        except Exception:
            members = []
        if not members:
            missing_models.append(model)
            continue
        if not already_has_raw:
            raw_members_by_model[model] = members
        if not already_has_qm:
            qm_members_by_model[model] = members
        counts_raw_by_model.setdefault(model, len(members))
        counts_by_model.setdefault(model, len(members))
        mean_c = sum(members) / float(len(members))
        cache_loc_key = str(cache_row["loc_key"] or "")
        cache_created_at = str(cache_row["created_at"] or "")
        official_updated_at = str(cache_row["official_updated_at"] or "")
        official_source = str(cache_row["official_updated_source"] or "")
        snapshot_models.setdefault(
            model,
            {
                "source": "model_member_cache",
                "loc_key": cache_loc_key,
                "event_date": event_date,
                "market_var": market_var,
                "market_unit": market_unit,
                "member_count": len(members),
                "mean_c": round(float(mean_c), 3),
                "min_c": round(float(min(members)), 3),
                "max_c": round(float(max(members)), 3),
                "members": members,
                "created_at": cache_created_at,
                "official_updated_at": official_updated_at,
                "official_updated_source": official_source,
                "members_signature": str(cache_row["members_signature"] or ""),
            },
        )
        model_provenance = provenance.get(model)
        if not isinstance(model_provenance, Mapping):
            provenance[model] = {
                "status": "ok",
                "source_kind": "model_member_cache",
                "cache_source": "model_member_cache",
                "cache_loc_key": cache_loc_key,
                "created_at": cache_created_at,
                "official_updated_at": official_updated_at,
                "official_updated_source": official_source,
                "raw_member_count": len(members),
                "clean_member_count": len(members),
                "final_member_count": len(members),
            }
        filled_models.append(model)
    if raw_members_by_model:
        payload["model_members_decimal_raw"] = raw_members_by_model
    if qm_members_by_model:
        payload["model_members"] = qm_members_by_model
    if counts_raw_by_model:
        payload["model_member_counts_raw"] = counts_raw_by_model
    if counts_by_model:
        payload["model_member_counts"] = counts_by_model
    if provenance:
        payload["model_provenance"] = provenance
    if snapshot_models:
        snapshot.update(
            {
                "version": "model_member_cache_snapshot_v1",
                "source": "model_member_cache",
                "role": "ui_snapshot_member_fill_display_only",
                "event_date": event_date,
                "market_var": market_var,
                "market_unit": market_unit,
                "loc_key": loc_key,
                "models": snapshot_models,
                "filled_models": sorted(set(filled_models)),
                "missing_models": sorted(set(missing_models)),
            }
        )
        payload["model_member_cache_snapshot"] = snapshot
    _attach_model_peak_sources_for_ui_snapshot(payload)


def _attach_model_peak_sources_for_ui_snapshot(
    payload: MutableMapping[str, Any],
) -> None:
    """Expose cached model peaks as display-only values.

    The production posterior is pure state-space: NWP/TAF revisions are
    forcing and are not temperature likelihood buckets.  The dashboard still
    needs to show the independently materialized model forecast peaks, so keep
    this contract separate from ``forecast_weak_likelihood`` and mark it
    explicitly as non-probabilistic.
    """
    if not isinstance(payload, MutableMapping):
        return
    snapshot = payload.get("model_member_cache_snapshot")
    snapshot_models = snapshot.get("models") if isinstance(snapshot, Mapping) else {}
    if not isinstance(snapshot_models, Mapping):
        snapshot_models = {}
    existing = payload.get("model_peak_sources")
    model_peaks: Dict[str, Any] = dict(existing) if isinstance(existing, Mapping) else {}
    for model in UI_SNAPSHOT_MODEL_MEMBER_CACHE_MODELS:
        entry = snapshot_models.get(model)
        entry_map = entry if isinstance(entry, Mapping) else {}
        current = model_peaks.get(model)
        current_map = dict(current) if isinstance(current, Mapping) else {}
        value_key = ""
        value: Optional[float] = None
        for candidate_key in ("peak_c", "forecast_peak_c", "max_c", "mean_c"):
            candidate = to_float(entry_map.get(candidate_key))
            if candidate is not None and math.isfinite(float(candidate)):
                value_key = candidate_key
                value = float(candidate)
                break
        if value is not None:
            current_map.update(
                {
                    "state": "available",
                    "value_c": round(value, 3),
                    "value_field": value_key,
                    "value_semantics": (
                        "cached_member_peak"
                        if value_key in {"peak_c", "forecast_peak_c", "max_c"}
                        else "cached_member_mean"
                    ),
                }
            )
        else:
            current_map.setdefault("state", "missing")
            current_map.setdefault("reason", "model_peak_not_materialized")
        for key in (
            "source",
            "loc_key",
            "event_date",
            "market_var",
            "market_unit",
            "member_count",
            "created_at",
            "official_updated_at",
            "official_updated_source",
            "members_signature",
            "forecast_peak_valid_time",
            "forecast_peak_valid_at",
            "forecast_peak_at",
        ):
            if current_map.get(key) in (None, "", [], {}) and entry_map.get(key) not in (None, "", [], {}):
                current_map[key] = copy.deepcopy(entry_map.get(key))
        current_map.setdefault("source", "model_member_cache")
        current_map.setdefault("display_only", True)
        current_map.setdefault("likelihood_eligible", False)
        current_map.setdefault(
            "boundary",
            "display_only_model_peak_not_state_space_temperature_likelihood",
        )
        model_peaks[model] = current_map
    if model_peaks:
        payload["model_peak_sources"] = model_peaks


def _model_bucket_rule_comparison_for_ui_snapshot(payload: Mapping[str, Any]) -> Optional[Dict[str, Any]]:
    if not isinstance(payload, Mapping):
        return None
    distribution = payload.get("distribution") or payload.get("rows")
    first_row = distribution[0] if isinstance(distribution, list) and distribution and isinstance(distribution[0], Mapping) else {}
    qm_meta = first_row.get("q_ensemble_qm_meta") if isinstance(first_row, Mapping) else {}
    if not isinstance(qm_meta, Mapping):
        qm_meta = {}
    raw_bucket_meta = qm_meta.get("raw_bucket_probability") if isinstance(qm_meta.get("raw_bucket_probability"), Mapping) else {}
    bucket_meta = qm_meta.get("bucket_probability") if isinstance(qm_meta.get("bucket_probability"), Mapping) else {}
    labels = raw_bucket_meta.get("labels") or bucket_meta.get("labels") or []
    if not isinstance(labels, list) or not labels:
        labels = [
            str(row.get("outcome") or "").strip()
            for row in distribution
            if isinstance(row, Mapping) and str(row.get("outcome") or "").strip()
        ] if isinstance(distribution, list) else []
    if not isinstance(labels, list) or not labels:
        return None
    raw_members = payload.get("model_members_decimal_raw")
    qm_members = payload.get("model_members")
    if not isinstance(raw_members, Mapping) and not isinstance(qm_members, Mapping):
        return None
    market_unit = str(payload.get("market_unit") or first_row.get("market_unit") or "C")
    rules = ("round", "floor", "ceil")
    raw_by_rule: Dict[str, Dict[str, Any]] = {}
    qm_by_rule: Dict[str, Dict[str, Any]] = {}
    per_model: Dict[str, Dict[str, Any]] = {}
    for rule in rules:
        raw_meta = _model_bucket_rule_probability_meta(raw_members, labels, rule, market_unit)
        qm_rule_meta = _model_bucket_rule_probability_meta(qm_members, labels, rule, market_unit)
        if raw_meta:
            raw_by_rule[rule] = raw_meta
        if qm_rule_meta:
            qm_by_rule[rule] = qm_rule_meta
        model_keys = set()
        if raw_meta and isinstance(raw_meta.get("top_by_model"), Mapping):
            model_keys.update(str(key) for key in raw_meta.get("top_by_model", {}).keys())
        if qm_rule_meta and isinstance(qm_rule_meta.get("top_by_model"), Mapping):
            model_keys.update(str(key) for key in qm_rule_meta.get("top_by_model", {}).keys())
        for model in model_keys:
            model_out = per_model.setdefault(model, {"rules": {}})
            raw_top = (raw_meta.get("top_by_model", {}).get(model) if raw_meta else None) or {}
            qm_top = (qm_rule_meta.get("top_by_model", {}).get(model) if qm_rule_meta else None) or {}
            rule_out: Dict[str, Any] = {}
            if raw_top:
                rule_out["raw"] = dict(raw_top)
            if qm_top:
                rule_out["qm"] = dict(qm_top)
            delta = _model_bucket_rule_top_delta(raw_top, qm_top, labels)
            if delta:
                rule_out["delta"] = delta
            if rule_out:
                model_out["rules"][rule] = rule_out
    if not raw_by_rule and not qm_by_rule:
        return None
    return {
        "version": "model_member_bucket_rule_comparison_v1",
        "role": "diagnostic_display_only_not_trading_probability",
        "active_rule": "round",
        "rules": list(rules),
        "market_unit": market_unit,
        "labels": [str(label) for label in labels],
        "input_member_sources": {
            "raw": "model_members_decimal_raw" if isinstance(raw_members, Mapping) else "",
            "qm": "model_members" if isinstance(qm_members, Mapping) else "",
        },
        "raw_by_rule": raw_by_rule,
        "qm_by_rule": qm_by_rule,
        "per_model": per_model,
    }


def _attach_model_bucket_rule_comparison_for_ui_snapshot(
    conn: sqlite3.Connection,
    payload: MutableMapping[str, Any],
    row: Any = None,
) -> None:
    if not isinstance(payload, MutableMapping):
        return
    distribution = payload.get("distribution") or payload.get("rows")
    if not isinstance(distribution, list) or not distribution or not isinstance(distribution[0], MutableMapping):
        return
    first_row = distribution[0]
    qm_meta = first_row.get("q_ensemble_qm_meta")
    if not isinstance(qm_meta, MutableMapping):
        qm_meta = {}
        first_row["q_ensemble_qm_meta"] = qm_meta
    if isinstance(qm_meta.get("model_bucket_rule_comparison"), Mapping):
        return
    comparison = _model_bucket_rule_comparison_for_ui_snapshot(payload)
    if not comparison:
        snapshot_payload: Optional[Dict[str, Any]] = None
        model_snapshot_id = None
        if row is not None:
            try:
                model_snapshot_id = row["model_snapshot_id"]
            except Exception:
                model_snapshot_id = None
        if model_snapshot_id in (None, ""):
            model_snapshot_id = payload.get("model_snapshot_id")
        try:
            if model_snapshot_id not in (None, ""):
                snap_row = conn.execute(
                    "SELECT payload_json FROM model_snapshots WHERE id = ? LIMIT 1",
                    (int(model_snapshot_id),),
                ).fetchone()
            else:
                snap_row = conn.execute(
                    """
                    SELECT payload_json
                    FROM model_snapshots
                    WHERE slug = ? AND event_date = ?
                    ORDER BY created_at DESC, id DESC
                    LIMIT 1
                    """,
                    (
                        str(payload.get("slug") or ""),
                        _normalize_date_key(str(payload.get("event_date") or "")),
                    ),
                ).fetchone()
            if snap_row is not None:
                raw_json = snap_row["payload_json"] if isinstance(snap_row, sqlite3.Row) else snap_row[0]
                parsed = json.loads(raw_json or "{}")
                if isinstance(parsed, dict):
                    snapshot_payload = parsed
        except Exception:
            snapshot_payload = None
        if snapshot_payload:
            comparison = _model_bucket_rule_comparison_for_ui_snapshot(snapshot_payload)
    if comparison:
        qm_meta["model_bucket_rule_comparison"] = comparison


def _compact_qm_meta_for_ui_snapshot(meta: Any) -> Optional[Dict[str, Any]]:
    if not isinstance(meta, Mapping):
        return None
    out: Dict[str, Any] = {}
    for key in (
        "calibration_mode",
        "seasonal_correction_enabled",
        "enabled",
        "version",
        "scope_allowed",
    ):
        if key in meta:
            out[key] = meta.get(key)
    qm_apply = meta.get("qm_apply")
    if isinstance(qm_apply, Mapping):
        out["qm_apply"] = {
            key: qm_apply.get(key)
            for key in ("version", "method", "fitted_at")
            if qm_apply.get(key) not in (None, "")
        }
    raw_bucket = _compact_model_bucket_meta_for_ui_snapshot(meta.get("raw_bucket_probability"))
    if raw_bucket:
        out["raw_bucket_probability"] = raw_bucket
    bucket = _compact_model_bucket_meta_for_ui_snapshot(meta.get("bucket_probability"))
    if bucket:
        out["bucket_probability"] = bucket
    rule_comparison = meta.get("model_bucket_rule_comparison")
    if isinstance(rule_comparison, Mapping):
        out["model_bucket_rule_comparison"] = dict(rule_comparison)
    return out or None


def _row_mapping_value(value: Any) -> Dict[str, Any]:
    if isinstance(value, Mapping):
        return dict(value)
    if isinstance(value, str) and value.strip().startswith("{"):
        try:
            parsed = json.loads(value)
        except (TypeError, ValueError, json.JSONDecodeError):
            return {}
        if isinstance(parsed, Mapping):
            return dict(parsed)
    return {}


def _row_probability_value(value: Any) -> Optional[float]:
    num = to_float(value)
    if num is None or not math.isfinite(num):
        return None
    return max(0.0, min(1.0, float(num)))


def _row_bucket_label(row: Mapping[str, Any]) -> str:
    for key in ("outcome", "bucket", "label", "temperature_bucket", "q_temperature_bucket_label"):
        value = str(row.get(key) or "").strip()
        if value:
            return value
    return ""


def _row_bucket_label_candidates(label: str) -> Tuple[str, ...]:
    value = str(label or "").strip()
    candidates = [value]
    if value.endswith("°C"):
        candidates.append(value[:-2].strip())
    if value.endswith("C"):
        candidates.append(value[:-1].strip())
    return tuple(dict.fromkeys(candidate for candidate in candidates if candidate))


def _row_layer_contributions(row: Mapping[str, Any]) -> Dict[str, Any]:
    for key in ("q_bayes_layer_contributions", "layer_contributions"):
        candidate = _row_mapping_value(row.get(key))
        if candidate:
            return candidate
    q_meta = _row_mapping_value(row.get("q_bayes_meta"))
    return _row_mapping_value(q_meta.get("layer_contributions"))


def _row_layer_probability(layer_contributions: Mapping[str, Any], layer_key: str, label: str) -> Optional[float]:
    layer = _row_mapping_value(layer_contributions.get(layer_key))
    distribution = _row_mapping_value(layer.get("distribution"))
    if not distribution:
        return None
    for candidate in _row_bucket_label_candidates(label):
        if candidate in distribution:
            prob = _row_probability_value(distribution.get(candidate))
            if prob is not None:
                return prob
    return None


def _row_layer_beta(
    row: Mapping[str, Any],
    layer_contributions: Mapping[str, Any],
    layer_key: str,
    *,
    default: Optional[float],
) -> Optional[float]:
    layer = _row_mapping_value(layer_contributions.get(layer_key))
    beta = to_float(layer.get("beta"))
    if beta is not None and math.isfinite(beta):
        return float(beta)
    q_meta = _row_mapping_value(row.get("q_bayes_meta"))
    row_key = "q_bayes_beta_weak" if layer_key == "forecast_weak_likelihood" else "q_bayes_beta_strong"
    meta_key = "beta_weak" if layer_key == "forecast_weak_likelihood" else "beta_strong"
    for raw in (row.get(row_key), q_meta.get(meta_key)):
        beta = to_float(raw)
        if beta is not None and math.isfinite(beta):
            return float(beta)
    return default


def _row_combined_layer_likelihood_prob(
    layer_contributions: Mapping[str, Any],
    label: str,
    *,
    beta_weak: Optional[float],
    beta_strong: Optional[float],
) -> Optional[float]:
    weak_layer = _row_mapping_value(layer_contributions.get("forecast_weak_likelihood"))
    strong_layer = _row_mapping_value(layer_contributions.get("metar_strong_likelihood"))
    weak_dist = _row_mapping_value(weak_layer.get("distribution"))
    strong_dist = _row_mapping_value(strong_layer.get("distribution"))
    labels = list(dict.fromkeys([str(key) for key in (*weak_dist.keys(), *strong_dist.keys()) if str(key)]))
    if not labels:
        return None
    weak_beta = max(0.0, float(beta_weak if beta_weak is not None else 0.0))
    strong_beta = max(0.0, float(beta_strong if beta_strong is not None else 1.0))
    scores: Dict[str, float] = {}
    for bucket in labels:
        weak = _row_probability_value(weak_dist.get(bucket))
        strong = _row_probability_value(strong_dist.get(bucket))
        score = 1.0
        if weak_dist:
            score *= max(1e-12, weak if weak is not None else 1.0) ** weak_beta
        if strong_dist:
            score *= max(1e-12, strong if strong is not None else 1.0) ** strong_beta
        scores[bucket] = float(score)
    total = sum(scores.values())
    if total <= 0:
        return None
    for candidate in _row_bucket_label_candidates(label):
        if candidate in scores:
            return _row_probability_value(scores[candidate] / total)
    return None


def _hierarchical_bayes_chain_for_distribution_row(row: Mapping[str, Any]) -> Dict[str, Any]:
    layer_contributions = _row_layer_contributions(row)
    if not layer_contributions:
        return {}
    label = _row_bucket_label(row)
    if not label:
        return {}
    q_meta = _row_mapping_value(row.get("q_bayes_meta"))
    beta_weak = _row_layer_beta(row, layer_contributions, "forecast_weak_likelihood", default=0.0)
    beta_strong = _row_layer_beta(row, layer_contributions, "metar_strong_likelihood", default=1.0)
    layer_parts: Dict[str, Dict[str, Any]] = {}
    likelihood_parts: Dict[str, Dict[str, Any]] = {}
    for layer_key in ("prior", "forecast_weak_likelihood", "metar_strong_likelihood"):
        layer = _row_mapping_value(layer_contributions.get(layer_key))
        prob = _row_layer_probability(layer_contributions, layer_key, label)
        part: Dict[str, Any] = {}
        if prob is not None:
            part["prob"] = float(prob)
        for meta_key in ("role", "boundary", "entropy", "sum"):
            value = layer.get(meta_key)
            if value not in (None, ""):
                part[meta_key] = value
        beta = beta_weak if layer_key == "forecast_weak_likelihood" else beta_strong if layer_key == "metar_strong_likelihood" else None
        if beta is not None:
            part["beta"] = float(beta)
        if part:
            layer_parts[layer_key] = part
            if layer_key in ("forecast_weak_likelihood", "metar_strong_likelihood"):
                likelihood_parts[layer_key] = dict(part)
    prior_prob = _row_layer_probability(layer_contributions, "prior", label)
    likelihood_prob = _row_probability_value(
        row.get("q_likelihood")
        if row.get("q_likelihood") is not None
        else row.get("q_bayes_likelihood_prob")
    )
    if likelihood_prob is None:
        likelihood_prob = _row_combined_layer_likelihood_prob(
            layer_contributions,
            label,
            beta_weak=beta_weak,
            beta_strong=beta_strong,
        )
    if not (prior_prob is not None or likelihood_prob is not None or layer_parts or likelihood_parts):
        return {}
    score_components = _row_mapping_value(row.get("q_bayes_score_components")) or _row_mapping_value(
        q_meta.get("score_components")
    )
    return {
        "schema": "hierarchical_layer_contributions_chain_v1",
        "role": "hierarchical_joint_likelihood_explanation",
        "ui_primary_allowed": True,
        "production_probability_allowed": False,
        "old_additive_evidence_pool_used": False,
        "legacy_compat_fallback_used": False,
        "formula": "continuous_forecast_error_prior_then_sequential_state_zero_inflated_remaining_warming_mixture_then_bucket_integral",
        "bucket": label,
        "prior_prob": prior_prob,
        "likelihood_prob": likelihood_prob,
        "likelihood_parts": likelihood_parts,
        "layer_parts": layer_parts,
        "score_components": score_components,
        "source": str(row.get("q_bayes_source") or q_meta.get("source") or ""),
        "phase": row.get("q_bayes_phase") or q_meta.get("phase"),
        "beta_weak": beta_weak,
        "beta_strong": beta_strong,
        "phase_reason": row.get("q_bayes_phase_reason") or q_meta.get("phase_reason"),
        "hard_mask_reason": row.get("q_bayes_hard_mask_reason") or q_meta.get("hard_mask_reason"),
    }


def _bayes_chain_for_distribution_row(row: Any) -> Dict[str, Any]:
    if not isinstance(row, Mapping):
        return {}
    hierarchical = _hierarchical_bayes_chain_for_distribution_row(row)
    if hierarchical:
        return hierarchical
    # A row written before the hierarchical composer has no layer_contributions
    # to build from, and dropping the chain entirely tells the reader nothing.
    # chengdu_intraday_summary keeps the same two-tier rule and owns the compat
    # chain, which says outright that it is retired and not UI-primary; this
    # copy had lost the second tier, so the same row showed a chain there and
    # none here.  ui/index.html builds the same compat shape client-side.
    legacy = _legacy_additive_bayes_chain_for_distribution_row(row)
    if legacy:
        return legacy
    # Last: a chain the row already carries.  The compact chain is what gets
    # persisted, so a row read back can hold one and no raw fields to rebuild
    # it from.
    return _persisted_bayes_chain_for_distribution_row(row)


def _compact_bayes_chain_for_bucket_series(row: Any) -> Dict[str, Any]:
    chain = _bayes_chain_for_distribution_row(row)
    if not chain:
        return {}
    out: Dict[str, Any] = {}
    for key in (
        "schema",
        "role",
        "ui_primary_allowed",
        "production_probability_allowed",
        "replacement",
        "old_additive_evidence_pool_used",
        "production_replacement_required",
        "replacement_posterior_runtime",
        "prior_prob",
        "likelihood_prob",
        "phase",
        "beta_weak",
        "beta_strong",
        "phase_reason",
        "hard_mask_reason",
        "source",
    ):
        value = chain.get(key)
        if value not in (None, ""):
            out[key] = value
    parts = chain.get("likelihood_parts")
    compact_parts: Dict[str, Dict[str, Any]] = {}
    if isinstance(parts, Mapping):
        for key in (
            "model",
            "wu_forecast",
            "taf_peak",
            "observed_nowcast",
            "temperature_trajectory",
            "independent_physics_residual",
            "post_cool_rebound_regime_prior",
            "post_cool_rebound_intraday_likelihood",
            "forecast_weak_likelihood",
            "metar_strong_likelihood",
        ):
            part = parts.get(key)
            if not isinstance(part, Mapping):
                continue
            prob = to_float(part.get("prob"))
            if prob is not None and math.isfinite(prob):
                compact_part: Dict[str, Any] = {"prob": float(prob)}
                evidence = to_float(part.get("evidence"))
                if evidence is not None and math.isfinite(evidence):
                    compact_part["evidence"] = float(evidence)
                beta = to_float(part.get("beta"))
                if beta is not None and math.isfinite(beta):
                    compact_part["beta"] = float(beta)
                compact_parts[key] = compact_part
    if compact_parts:
        out["likelihood_parts"] = compact_parts
    return out


def _compact_per_model_q_for_ui_snapshot(value: Any) -> Dict[str, Dict[str, Any]]:
    if not isinstance(value, Mapping):
        return {}
    out: Dict[str, Dict[str, Any]] = {}
    for model, raw_model in value.items():
        model_key = str(model or "").strip()
        if not model_key or not isinstance(raw_model, Mapping):
            continue
        entry: Dict[str, Any] = {}
        for key in ("q_round", "q", "q_calibrated", "dir_value", "value", "label"):
            raw_value = raw_model.get(key)
            if raw_value in (None, ""):
                continue
            if key == "label":
                entry[key] = str(raw_value or "")[:80]
                continue
            num = to_float(raw_value)
            if num is not None and math.isfinite(float(num)):
                entry[key] = float(num)
        if entry:
            out[model_key] = entry
    return out


def _compact_physical_d0_explanation_for_ui_snapshot(value: Any) -> Dict[str, Any]:
    if not isinstance(value, Mapping):
        return {}
    out: Dict[str, Any] = {}
    for key in ("title", "summary", "target_bucket", "source", "updated_at"):
        raw_value = value.get(key)
        if raw_value in (None, ""):
            continue
        out[key] = str(raw_value or "")[:240]
    variables_raw = value.get("variables")
    variables_out: List[Dict[str, Any]] = []
    if isinstance(variables_raw, list):
        for raw_variable in variables_raw[:8]:
            if not isinstance(raw_variable, Mapping):
                continue
            variable: Dict[str, Any] = {}
            for key in ("key", "label", "direction", "evidence_state", "na_reason"):
                raw_value = raw_variable.get(key)
                if raw_value not in (None, ""):
                    variable[key] = str(raw_value or "")[:160]
            for key in ("weight", "factor", "log_likelihood", "value"):
                num = to_float(raw_variable.get(key))
                if num is not None and math.isfinite(float(num)):
                    variable[key] = float(num)
            current = raw_variable.get("current")
            if isinstance(current, Mapping):
                current_out: Dict[str, Any] = {}
                for key in ("source_field", "source", "at", "updated_at"):
                    raw_value = current.get(key)
                    if raw_value not in (None, ""):
                        current_out[key] = str(raw_value or "")[:120]
                for key in ("value", "temp_c", "rate_mm_per_h", "probability_pct"):
                    num = to_float(current.get(key))
                    if num is not None and math.isfinite(float(num)):
                        current_out[key] = float(num)
                if current_out:
                    variable["current"] = current_out
            source_profile = raw_variable.get("source_profile")
            if isinstance(source_profile, Mapping):
                source_out: Dict[str, Any] = {}
                for key in ("source", "proxy_source", "source_field", "na_reason"):
                    raw_value = source_profile.get(key)
                    if raw_value not in (None, ""):
                        source_out[key] = str(raw_value or "")[:160]
                for key in ("available", "is_proxy_only"):
                    if key in source_profile:
                        source_out[key] = bool(source_profile.get(key))
                if source_out:
                    variable["source_profile"] = source_out
            if variable:
                variables_out.append(variable)
    if variables_out:
        out["variables"] = variables_out
    return out


