def _slim_fact_payload_for_facts_range_history(payload: Any) -> Dict[str, Any]:
    if not isinstance(payload, Mapping):
        return {}
    top_level_keys = (
        "slug",
        "event_url",
        "title",
        "market_var",
        "city",
        "event_date",
        "event_end_utc",
        "run_date",
        "fact_as_of",
        "market_unit",
        "market_closed",
        "market_close_price",
        "model_count",
        "equal_model_count",
        "model_cache_age_sec",
        "market_stale_sec",
        "market_updated_at",
        "market_quote_updated_at",
        "market_top_label",
        "model_top_label",
        "model_top_q",
        "single_temperature_top_label",
        "single_temperature_top_q",
        "contract_payout_top_label",
        "contract_payout_top_q",
        "corrected_top_bucket",
        "mean_bucket",
    )
    out: Dict[str, Any] = {
        key: payload.get(key)
        for key in top_level_keys
        if key in payload and payload.get(key) not in (None, "")
    }
    distribution = payload.get("distribution")
    if isinstance(distribution, list):
        rows = [
            row
            for row in (
                _compact_distribution_row_for_facts_range_history(raw_row)
                for raw_row in distribution
            )
            if row
        ]
        if rows:
            out["distribution"] = rows
    return out


HISTORY_FACT_COMPACTION_VERSION = "event_fact_history_compact_v1"


def _compact_fact_payload_for_history_storage(
    payload: Any,
    *,
    fact_as_of: str = "",
    compacted_at: str = "",
) -> Dict[str, Any]:
    if not isinstance(payload, Mapping):
        return {}
    compact = _slim_fact_payload_for_ui_snapshot_summary(
        payload,
        include_physical_detail=False,
    )
    if not isinstance(compact, dict):
        compact = {}
    compact.pop("chengdu_intraday_summary", None)
    if fact_as_of and not compact.get("fact_as_of"):
        compact["fact_as_of"] = fact_as_of
    compact["history_compacted"] = True
    compact["history_compaction_version"] = HISTORY_FACT_COMPACTION_VERSION
    compact["history_compacted_at"] = compacted_at or now_text()
    return compact


def _compact_replaced_event_fact_history_row(
    conn: sqlite3.Connection,
    fact_id: int,
    *,
    fact_as_of: str = "",
    fact_json: str = "",
) -> bool:
    return compact_weather_replaced_event_fact_history_row(
        conn,
        int(fact_id or 0),
        fact_as_of=fact_as_of,
        fact_json=fact_json,
    )


def _display_probability_model_value(row: Mapping[str, Any]) -> Optional[float]:
    for key in ("q_calibrated", "raw_q_calibrated", "q_entry", "q_raw", "q_round"):
        value = to_float(row.get(key))
        if value is not None and math.isfinite(value):
            return min(1.0, max(0.0, float(value)))
    return None


def _apply_display_probability_fields_in_place(distribution: List[Dict[str, Any]]) -> bool:
    """
    UI SSOT field for the primary bucket probability.

    Model probabilities remain untouched for diagnostics/trading. If the latest
    YES book is effectively dead, the primary display is zeroed by market-state
    classification rather than derived from the quote price. If the YES quote is
    internally unusable (zero bid with ask pinned near 1), the primary display is
    explicitly unavailable instead of falling back to the model probability.
    """
    touched = False
    for row in distribution or []:
        if not isinstance(row, dict):
            continue
        model_value = _display_probability_model_value(row)
        yes_ask = to_float(row.get("best_ask"))
        yes_bid = to_float(row.get("best_bid"))
        dead_yes = (
            yes_ask is not None
            and yes_bid is not None
            and math.isfinite(yes_ask)
            and math.isfinite(yes_bid)
            and float(yes_ask) <= UI_DEAD_YES_ASK_MAX
            and float(yes_bid) <= UI_DEAD_YES_BID_MAX
        )
        invalid_yes_quote = (
            yes_ask is not None
            and yes_bid is not None
            and math.isfinite(yes_ask)
            and math.isfinite(yes_bid)
            and float(yes_ask) >= UI_INVALID_YES_ASK_MIN
            and float(yes_bid) <= UI_INVALID_YES_BID_MAX
        )
        if invalid_yes_quote:
            display_value = None
            source = "invalid_yes_market_quote"
            invalid_reason = (
                f"yes_ask>={UI_INVALID_YES_ASK_MIN:g},"
                f"yes_bid<={UI_INVALID_YES_BID_MAX:g}"
            )
            dead_reason = ""
        elif dead_yes:
            display_value = 0.0
            source = "dead_yes_market_zero"
            dead_reason = (
                f"yes_ask<={UI_DEAD_YES_ASK_MAX:g},"
                f"yes_bid<={UI_DEAD_YES_BID_MAX:g}"
            )
            invalid_reason = ""
        else:
            display_value = model_value
            source = "model_q_calibrated"
            dead_reason = ""
            invalid_reason = ""
        previous = row.get("display_probability")
        row["display_probability"] = display_value
        row["display_probability_source"] = source
        row["display_probability_na_reason"] = (
            invalid_reason if invalid_yes_quote else ("" if display_value is not None else "missing_model_probability")
        )
        row["display_probability_market_dead"] = bool(dead_yes)
        row["display_probability_market_dead_reason"] = dead_reason
        row["display_probability_market_invalid"] = bool(invalid_yes_quote)
        row["display_probability_market_invalid_reason"] = invalid_reason
        if previous != display_value:
            touched = True
    norm_rows: List[Tuple[Dict[str, Any], float]] = []
    for row in distribution or []:
        if not isinstance(row, dict):
            continue
        value = to_float(row.get("display_probability"))
        invalid = bool(row.get("display_probability_market_invalid"))
        if invalid or value is None or not math.isfinite(value) or value < 0:
            previous_norm = row.get("display_probability_normalized")
            row["display_probability_normalized"] = None
            row["display_probability_normalized_source"] = "display_probability"
            row["display_probability_normalized_na_reason"] = (
                "market_quote_invalid"
                if invalid
                else "display_probability_missing"
            )
            if previous_norm is not None:
                touched = True
            continue
        norm_rows.append((row, float(value)))
    norm_total = sum(value for _, value in norm_rows)
    for row, value in norm_rows:
        previous_norm = row.get("display_probability_normalized")
        if norm_total > 0:
            normalized = max(0.0, min(1.0, value / norm_total))
            na_reason = ""
        else:
            normalized = None
            na_reason = "display_probability_total_zero"
        row["display_probability_normalized"] = normalized
        row["display_probability_normalized_source"] = "display_probability"
        row["display_probability_normalized_na_reason"] = na_reason
        if previous_norm != normalized:
            touched = True
    return touched


try:
    _UI_NODE_SUBPROCESS_MAX_CONCURRENT = int(
        float(os.environ.get("PM_UI_NODE_SUBPROCESS_MAX_CONCURRENT", "1") or 1)
    )
except (TypeError, ValueError):
    _UI_NODE_SUBPROCESS_MAX_CONCURRENT = 1
_UI_NODE_SUBPROCESS_MAX_CONCURRENT = max(1, min(_UI_NODE_SUBPROCESS_MAX_CONCURRENT, 16))
_UI_NODE_SUBPROCESS_SEM = threading.BoundedSemaphore(_UI_NODE_SUBPROCESS_MAX_CONCURRENT)


def _run_ui_node_subprocess(
    cmd: List[str],
    *,
    env: Dict[str, str],
    timeout: Optional[float],
    retries_on_errno24: int = 1,
    retry_sleep_sec: float = 0.35,
) -> subprocess.CompletedProcess:
    retries = max(0, int(retries_on_errno24))
    last_exc: Optional[Exception] = None
    for attempt in range(retries + 1):
        try:
            _UI_NODE_SUBPROCESS_SEM.acquire()
            try:
                return subprocess.run(
                    cmd,
                    capture_output=True,
                    text=True,
                    timeout=timeout,
                    check=False,
                    env=env,
                    close_fds=True,
                )
            finally:
                _UI_NODE_SUBPROCESS_SEM.release()
        except Exception as exc:
            last_exc = exc
            if attempt >= retries or not _is_errno24_error_text(exc):
                raise
            sleep_sec = max(0.05, float(retry_sleep_sec)) * float(attempt + 1)
            time.sleep(sleep_sec)
    if last_exc is not None:
        raise last_exc
    raise RuntimeError("ui_node_subprocess_failed")


def _run_node_open_orders() -> Tuple[bool, Dict[str, Any]]:
    script_override = os.environ.get("PM_NODE_ORDER_SCRIPT", "").strip()
    script_path = Path(script_override) if script_override else (ROOT_DIR / "scripts" / "polymarket_order.mjs")
    if not script_path.exists():
        return False, {"error": f"script_missing:{script_path}"}
    node_bin = _resolve_node_bin()
    if node_bin != "node" and not Path(node_bin).exists():
        return False, {"error": f"node_missing:{node_bin}"}
    cmd = [node_bin, str(script_path), "fetch-open-orders"]
    env = _build_node_env_with_proxy()
    try:
        res = _run_ui_node_subprocess(
            cmd,
            timeout=AUTO_TRADE_BALANCE_TIMEOUT_SEC,
            env=env,
            retries_on_errno24=0,
        )
    except subprocess.TimeoutExpired as exc:
        if AUTO_TRADE_BALANCE_TIMEOUT_RETRY_SEC <= AUTO_TRADE_BALANCE_TIMEOUT_SEC:
            return False, {"error": "exec_timeout", "error_detail": str(exc)}
        try:
            res = _run_ui_node_subprocess(
                cmd,
                timeout=AUTO_TRADE_BALANCE_TIMEOUT_RETRY_SEC,
                env=env,
                retries_on_errno24=0,
            )
        except subprocess.TimeoutExpired:
            return False, {"error": "exec_timeout", "error_detail": str(exc)}
        except OSError as exc2:
            if int(getattr(exc2, "errno", 0) or 0) == 24:
                return False, {"error": "exec_errno24"}
            return False, _normalize_errno24_payload({"error": f"exec_failed:{exc2}"})
        except Exception as exc2:
            return False, _normalize_errno24_payload({"error": f"exec_failed:{exc2}"})
    except OSError as exc:
        if int(getattr(exc, "errno", 0) or 0) == 24:
            return False, {"error": "exec_errno24"}
        return False, _normalize_errno24_payload({"error": f"exec_failed:{exc}"})
    except Exception as exc:
        return False, _normalize_errno24_payload({"error": f"exec_failed:{exc}"})
    if res.returncode != 0:
        return False, _normalize_errno24_payload({
            "error": "exec_nonzero",
            "stderr": res.stderr.strip(),
            "stdout": res.stdout.strip(),
        })
    payload = None
    for line in (res.stdout or "").splitlines():
        line = line.strip()
        if not line or not line.startswith("{") or not line.endswith("}"):
            continue
        try:
            payload = json.loads(line)
            break
        except json.JSONDecodeError:
            continue
    if payload is None:
        payload = {"stdout": res.stdout.strip()}
    if isinstance(payload, dict) and payload.get("ok") is False:
        return False, _normalize_errno24_payload(payload)
    return True, payload


def _run_node_balance(refresh: bool = False, asset_type: str = "COLLATERAL", token_id: str = "") -> Tuple[bool, Dict[str, Any]]:
    script_override = os.environ.get("PM_NODE_ORDER_SCRIPT", "").strip()
