def _model_update_release_delay_sec(model: str) -> int:
    env_key, default = MODEL_UPDATE_DELAY_ENV.get(model, ("", 9000))
    raw = os.environ.get(env_key) if env_key else None
    try:
        return max(0, int(float(raw if raw not in (None, "") else default)))
    except (TypeError, ValueError):
        return default


def _model_update_cycle_hours(model: str) -> List[int]:
    default = MODEL_UPDATE_CYCLE_DEFAULTS.get(model) or [0, 6, 12, 18]
    raw = (
        os.environ.get(f"PM_MODEL_CYCLE_HOURS_{model.upper()}")
        or os.environ.get("PM_ENSEMBLE_CYCLE_HOURS")
        or ""
    )
    hours: List[int] = []
    for part in str(raw or "").split(","):
        try:
            hour = int(part.strip())
        except (TypeError, ValueError):
            continue
        if 0 <= hour <= 23:
            hours.append(hour)
    return sorted(set(hours)) or list(default)


def _utc_iso(dt: datetime) -> str:
    if dt.tzinfo is None:
        dt = dt.replace(tzinfo=timezone.utc)
    return dt.astimezone(timezone.utc).isoformat()


def _model_update_ref_label(cycle_time_utc: str) -> str:
    dt = parse_any_ts(str(cycle_time_utc or ""))
    if dt is None:
        return ""
    if dt.tzinfo is None:
        dt = dt.replace(tzinfo=timezone.utc)
    dt = dt.astimezone(timezone.utc)
    return f"ref {dt.hour:02d}Z"


def _infer_model_cycle_time_utc(model: str, last_update: str) -> str:
    dt = parse_any_ts(str(last_update or ""))
    if dt is None:
        return ""
    if dt.tzinfo is None:
        dt = dt.replace(tzinfo=timezone.utc)
    update_dt = dt.astimezone(timezone.utc)
    delay_sec = _model_update_release_delay_sec(model)
    hours = _model_update_cycle_hours(model)
    day0 = update_dt.replace(hour=0, minute=0, second=0, microsecond=0)
    try:
        grace_sec = int(float(os.environ.get("PM_MODEL_RELEASE_REF_INFER_GRACE_SEC", "1800") or 1800))
    except (TypeError, ValueError):
        grace_sec = 1800
    candidates: List[datetime] = []
    for day_offset in range(-2, 1):
        base = day0 + timedelta(days=day_offset)
        candidates.extend(base + timedelta(hours=hour) for hour in hours)
    due_ready = [
        cycle
        for cycle in candidates
        if cycle + timedelta(seconds=delay_sec) <= update_dt + timedelta(seconds=max(0, grace_sec))
    ]
    if due_ready:
        return _utc_iso(max(due_ready))
    anchor = update_dt - timedelta(seconds=delay_sec)
    fallback = [cycle for cycle in candidates if cycle <= anchor]
    if fallback:
        return _utc_iso(max(fallback))
    return _utc_iso(min(candidates))


def _next_model_expected_update_at(model: str, cycle_time_utc: str, last_update: str) -> Tuple[str, str]:
    cycle_dt = parse_any_ts(str(cycle_time_utc or ""))
    if cycle_dt is not None:
        if cycle_dt.tzinfo is None:
            cycle_dt = cycle_dt.replace(tzinfo=timezone.utc)
        cycle_dt = cycle_dt.astimezone(timezone.utc)
        hours = _model_update_cycle_hours(model)
        day0 = cycle_dt.replace(hour=0, minute=0, second=0, microsecond=0)
        candidates: List[datetime] = []
        for day_offset in range(0, 4):
            base = day0 + timedelta(days=day_offset)
            candidates.extend(base + timedelta(hours=hour) for hour in hours)
        now_utc = datetime.now(timezone.utc)
        delay = timedelta(seconds=_model_update_release_delay_sec(model))
        future_due = [
            candidate + delay
            for candidate in candidates
            if candidate > cycle_dt and candidate + delay > now_utc
        ]
        if future_due:
            return _utc_iso(min(future_due)), "cycle_delay"
        future = [candidate for candidate in candidates if candidate > cycle_dt]
        if future:
            due = min(future) + delay
            return _utc_iso(due), "cycle_delay"
    update_dt = parse_any_ts(str(last_update or ""))
    if update_dt is not None:
        if update_dt.tzinfo is None:
            update_dt = update_dt.replace(tzinfo=timezone.utc)
        return _utc_iso(update_dt.astimezone(timezone.utc) + timedelta(hours=6.5)), "observed_interval"
    return "", ""


def _release_watcher_age_sec(release_watcher: Mapping[str, Any]) -> Optional[float]:
    generated_at = str(release_watcher.get("generated_at") or release_watcher.get("checked_at") or "")
    dt = parse_any_ts(generated_at)
    if dt is None:
        return None
    if dt.tzinfo is None:
        dt = dt.replace(tzinfo=timezone.utc)
    return max(0.0, (datetime.now(timezone.utc) - dt.astimezone(timezone.utc)).total_seconds())


def _release_watcher_is_stale(release_watcher: Mapping[str, Any]) -> bool:
    age_sec = _release_watcher_age_sec(release_watcher)
    if age_sec is None:
        return False
    try:
        max_age_sec = int(float(os.environ.get("PM_MODEL_RELEASE_WATCHER_MAX_AGE_SEC", "900") or 900))
    except (TypeError, ValueError):
        max_age_sec = 900
    return age_sec > max(60, max_age_sec)


def _model_update_display_fields(model: str, release: Mapping[str, Any], last_update: str) -> Dict[str, Any]:
    meta = MODEL_UPDATE_DISPLAY_META.get(model, {})
    reference_time = str(release.get("cycle_time_utc") or "")
    if not reference_time:
        reference_time = _infer_model_cycle_time_utc(model, last_update)
    expected_next = str(release.get("expected_due_at") or "")
    expected_basis = "official_release_watcher" if expected_next else ""
    if not expected_next:
        expected_next, expected_basis = _next_model_expected_update_at(model, reference_time, last_update)
    return {
        "display_name": meta.get("display_name") or model,
        "producer_name": meta.get("producer_name") or "",
        "producer_url": meta.get("producer_url") or "",
        "update_interval_label": meta.get("update_interval_label") or "",
        "reference_time_utc": reference_time,
        "reference_label": _model_update_ref_label(reference_time),
        "expected_next_update_at": expected_next,
        "expected_next_update_basis": expected_basis,
    }


def _read_model_release_watcher() -> Dict[str, Any]:
    try:
        with MODEL_RELEASE_WATCHER_PATH.open("r", encoding="utf-8") as f:
            payload = json.load(f)
    except Exception:
        return {}
    if not isinstance(payload, dict):
        return {}
    models = payload.get("models")
    if not isinstance(models, list):
        payload["models"] = []
    return payload


def model_update_stats(limit: int = 240) -> Dict[str, Any]:
    release_watcher = _read_model_release_watcher()
    release_watcher_stale = _release_watcher_is_stale(release_watcher)
    release_watcher_age_sec = _release_watcher_age_sec(release_watcher)
    release_models = {
        str(item.get("model") or ""): item
        for item in release_watcher.get("models") or []
        if not release_watcher_stale and isinstance(item, Mapping) and str(item.get("model") or "")
    }
    if not DB_PATH.exists():
        return {
            "models": [],
            "expected_models": [],
            "missing_models": [],
            "release_watcher": release_watcher,
            "release_watcher_stale": release_watcher_stale,
            "release_watcher_age_sec": release_watcher_age_sec,
            "health_basis": "official_run_id_first_seen_complete_for_chengdu_peak",
            "updated_at": now_text(),
        }
    with open_db_ro_fast(timeout_sec=0.25, busy_timeout_ms=250) as conn:
        cur = conn.cursor()
        try:
            cur.execute("SELECT DISTINCT model FROM model_member_cache ORDER BY model")
        except sqlite3.OperationalError:
            return {
                "models": [],
                "expected_models": [],
                "missing_models": [],
                "release_watcher": release_watcher,
                "release_watcher_stale": release_watcher_stale,
                "release_watcher_age_sec": release_watcher_age_sec,
                "health_basis": "official_run_id_first_seen_complete_for_chengdu_peak",
                "updated_at": now_text(),
            }
        model_rows = cur.fetchall()
        models = [str(row["model"] or "") for row in model_rows if row["model"]]
        expected_raw = os.environ.get("PM_SCAN_ENSEMBLE_MODELS") or "gfs_seamless,icon_seamless,ecmwf_ifs025,nws_forecast"
        expected_models = [m.strip() for m in expected_raw.split(",") if m.strip()]
        expected_set = set(expected_models)
        present_set = set(models)
        missing_models = [m for m in expected_models if m not in present_set]
        payload = []
        for model in models:
            try:
                cur.execute(
                    """
                    SELECT created_at, official_updated_at, official_updated_source
                    FROM model_member_cache
                    WHERE model = ?
                    ORDER BY created_at DESC
                    LIMIT ?
                    """,
                    (model, limit * 5),
                )
                rows = cur.fetchall()
            except sqlite3.OperationalError:
                cur.execute(
                    """
                    SELECT created_at
                    FROM model_member_cache
                    WHERE model = ?
                    ORDER BY created_at DESC
                    LIMIT ?
                    """,
                    (model, limit * 5),
                )
                rows = cur.fetchall()
            time_entries: List[Tuple[datetime, str]] = []
            last_cache_created_at = ""
            for row in rows:
                official_raw = ""
                official_source = ""
                cache_raw = str(row["created_at"] or "")
                try:
                    official_raw = str(row["official_updated_at"] or "")
                    official_source = str(row["official_updated_source"] or "")
                except (KeyError, IndexError, TypeError):
                    official_raw = ""
                    official_source = ""
                ts = parse_iso_ts(official_raw)
                source = official_source or ("official" if official_raw else "")
                if not ts:
                    ts = parse_iso_ts(cache_raw)
                    source = "cache"
                if not ts:
                    continue
                if ts.tzinfo is None:
                    ts = ts.replace(tzinfo=timezone.utc)
                time_entries.append((ts, source or "cache"))
                if not last_cache_created_at:
                    last_cache_created_at = cache_raw
            if not time_entries:
                continue
            time_entries.sort(key=lambda item: item[0], reverse=True)
            times = [item[0] for item in time_entries]
            last_update = time_entries[0][0]
            last_source = time_entries[0][1]
            buckets: List[datetime] = []
            seen = set()
            for ts in times:
                bucket = ts.replace(minute=0, second=0, microsecond=0)
                key = bucket.isoformat()
                if key in seen:
                    continue
                seen.add(key)
                buckets.append(bucket)
                if len(buckets) >= limit:
                    break
            intervals = []
            for i in range(len(buckets) - 1):
                delta = (buckets[i] - buckets[i + 1]).total_seconds() / 3600.0
                if delta > 0:
                    intervals.append(delta)
            hour_hist: Dict[int, int] = {}
            for bucket in buckets:
                hour_hist[bucket.hour] = hour_hist.get(bucket.hour, 0) + 1
            total_hist = sum(hour_hist.values())
            top_hour = None
            top_count = 0
            for hour, count in hour_hist.items():
                if count > top_count:
                    top_count = count
                    top_hour = hour
            peak_ratio = (top_count / total_hist) if total_hist else None
            intervals_sorted = sorted(intervals)
            if intervals_sorted:
                mid = len(intervals_sorted) // 2
                if len(intervals_sorted) % 2:
                    median = intervals_sorted[mid]
                else:
                    median = (intervals_sorted[mid - 1] + intervals_sorted[mid]) / 2.0
            else:
                median = None
            avg_interval = (sum(intervals_sorted) / len(intervals_sorted)) if intervals_sorted else None
            recent_intervals = intervals[:12]
            release = release_models.get(model) or {}
            release_complete = release.get("complete_for_chengdu_peak")
            release_last_update = (
                str(release.get("complete_first_seen_at") or "")
                or str(release.get("first_seen_at") or "")
                or str(release.get("latest_file_last_modified") or "")
            )
            if release_last_update:
                release_ts = parse_any_ts(release_last_update)
                if release_ts is not None:
                    last_update = release_ts
                    last_source = str(release.get("official_source") or release.get("source_role") or "official_release_watcher")
            row_payload = {
                "model": model,
                "last_update": last_update.isoformat(),
                "age_sec": max(0.0, (datetime.now(last_update.tzinfo or timezone.utc) - last_update).total_seconds()),
                "sample_count": len(times),
                "bucket_count": len(buckets),
                "last_interval_hours": intervals[0] if intervals else None,
                "avg_interval_hours": avg_interval,
                "median_interval_hours": median,
                "recent_intervals": recent_intervals,
                "hour_hist": hour_hist,
                "peak_hour": top_hour,
                "peak_ratio": peak_ratio,
                "ttl_sec": _model_cache_ttl_sec(model),
                "last_update_source": last_source or "cache",
                "last_cache_created_at": last_cache_created_at,
                "official_run_id": str(release.get("run_id") or ""),
                "official_cycle_time_utc": str(release.get("cycle_time_utc") or ""),
                "official_expected_due_at": str(release.get("expected_due_at") or ""),
                "official_source": str(release.get("official_source") or ""),
                "release_status": str(release.get("status") or ""),
                "release_status_reason": str(release.get("status_reason") or ""),
                "release_checked_at": str(release.get("checked_at") or ""),
                "release_first_seen_at": str(release.get("first_seen_at") or ""),
                "release_complete_first_seen_at": str(release.get("complete_first_seen_at") or ""),
                "release_latest_file_last_modified": str(release.get("latest_file_last_modified") or ""),
                "complete_for_chengdu_peak": bool(release_complete) if release else None,
                "run_complete": bool(release_complete) if release else None,
                "required_forecast_hours": list(release.get("required_forecast_hours") or []) if release else [],
                "available_forecast_hours": list(release.get("available_forecast_hours") or []) if release else [],
                "missing_forecast_hours": list(release.get("missing_forecast_hours") or []) if release else [],
                "release_probe_metadata": release.get("probe_metadata") if isinstance(release.get("probe_metadata"), Mapping) else {},
            }
            row_payload.update(_model_update_display_fields(model, release, str(row_payload.get("last_update") or "")))
            payload.append(row_payload)
        seen_models = {str(item.get("model") or "") for item in payload if isinstance(item, Mapping)}
        for model, release in sorted(release_models.items()):
            if model in seen_models:
                continue
            last_update = (
                str(release.get("complete_first_seen_at") or "")
                or str(release.get("first_seen_at") or "")
                or str(release.get("latest_file_last_modified") or "")
            )
            row_payload = {
                "model": model,
                "last_update": last_update,
                "age_sec": _source_health_age_sec(last_update),
                "sample_count": 0,
                "bucket_count": 0,
                "last_interval_hours": None,
                "avg_interval_hours": None,
                "median_interval_hours": None,
                "recent_intervals": [],
                "hour_hist": {},
                "peak_hour": None,
                "peak_ratio": None,
                "ttl_sec": _model_cache_ttl_sec(model),
                "last_update_source": str(release.get("official_source") or "official_release_watcher"),
                "last_cache_created_at": "",
                "official_run_id": str(release.get("run_id") or ""),
                "official_cycle_time_utc": str(release.get("cycle_time_utc") or ""),
                "official_expected_due_at": str(release.get("expected_due_at") or ""),
                "official_source": str(release.get("official_source") or ""),
                "release_status": str(release.get("status") or ""),
                "release_status_reason": str(release.get("status_reason") or ""),
                "release_checked_at": str(release.get("checked_at") or ""),
                "release_first_seen_at": str(release.get("first_seen_at") or ""),
                "release_complete_first_seen_at": str(release.get("complete_first_seen_at") or ""),
                "release_latest_file_last_modified": str(release.get("latest_file_last_modified") or ""),
                "complete_for_chengdu_peak": bool(release.get("complete_for_chengdu_peak")),
                "run_complete": bool(release.get("complete_for_chengdu_peak")),
                "required_forecast_hours": list(release.get("required_forecast_hours") or []),
                "available_forecast_hours": list(release.get("available_forecast_hours") or []),
                "missing_forecast_hours": list(release.get("missing_forecast_hours") or []),
                "release_probe_metadata": release.get("probe_metadata") if isinstance(release.get("probe_metadata"), Mapping) else {},
            }
            row_payload.update(_model_update_display_fields(model, release, str(row_payload.get("last_update") or "")))
            payload.append(row_payload)
        return {
            "models": payload,
            "expected_models": expected_models,
            "missing_models": missing_models,
            "release_watcher": release_watcher,
            "release_watcher_stale": release_watcher_stale,
            "release_watcher_age_sec": release_watcher_age_sec,
            "health_basis": "official_run_id_first_seen_complete_for_chengdu_peak",
            "updated_at": now_text(),
        }


def _safe_model_update_stats(limit: int = 120) -> Dict[str, Any]:
    cache_key = max(1, int(limit or 1))
    now = time.time()
    if MODEL_UPDATE_STATS_CACHE_SEC > 0:
        with _MODEL_UPDATE_STATS_CACHE_LOCK:
            cached = _MODEL_UPDATE_STATS_CACHE.get(cache_key)
            if cached and now - float(cached[0] or 0.0) <= MODEL_UPDATE_STATS_CACHE_SEC:
                payload = dict(cached[1])
                payload["cache_hit"] = True
                return payload
    try:
        payload = model_update_stats(limit=cache_key)
        if isinstance(payload, dict):
            if MODEL_UPDATE_STATS_CACHE_SEC > 0:
                with _MODEL_UPDATE_STATS_CACHE_LOCK:
                    _MODEL_UPDATE_STATS_CACHE[cache_key] = (time.time(), dict(payload))
            return payload
    except Exception as exc:
        return {
            "models": [],
            "expected_models": [],
            "missing_models": [],
            "error": str(exc),
            "health_basis": "official_run_id_first_seen_complete_for_chengdu_peak",
            "updated_at": now_text(),
        }
    return {
        "models": [],
        "expected_models": [],
        "missing_models": [],
        "error": "model_update_stats_empty",
        "health_basis": "official_run_id_first_seen_complete_for_chengdu_peak",
        "updated_at": now_text(),
    }


def _source_health_age_sec(ts_text: str) -> Optional[float]:
    text = str(ts_text or "").strip()
    if not text:
        return None
    dt = parse_any_ts(text)
    if dt is None:
        return None
    try:
        if dt.tzinfo is not None:
            return max(0.0, (datetime.now(dt.tzinfo) - dt).total_seconds())
        return max(0.0, (datetime.now() - dt).total_seconds())
    except Exception:
        return None


def _source_health_status(last_update: str, ttl_sec: Optional[float], *, static_ok: bool = False) -> Tuple[str, Optional[float]]:
    if static_ok:
        return "ok", None
    age_sec = _source_health_age_sec(last_update)
    if age_sec is None:
        return "missing", None
    ttl = float(ttl_sec or 0)
    if ttl <= 0:
        return "ok", age_sec
    if age_sec <= ttl:
        return "ok", age_sec
    if age_sec <= ttl * 2:
        return "warn", age_sec
    return "stale", age_sec


def _source_health_local_check_ttl_sec(ttl_sec: Optional[float]) -> float:
    ttl = float(ttl_sec or 0)
    default = max(1800.0, min(ttl if ttl > 0 else 3600.0, 21600.0))
    return _source_health_ttl_env("PM_DATA_HEALTH_LOCAL_CHECK_TTL_SEC", default)


def _source_health_lag_info(
    status: str,
    *,
    ttl_sec: Optional[float],
    checked_at: str = "",
) -> Dict[str, Any]:
    checked_text = str(checked_at or "").strip()
    checked_age_sec = _source_health_age_sec(checked_text)
    if status == "ok":
        return {
            "checked_at": checked_text,
            "checked_age_sec": checked_age_sec,
            "lag_type": "fresh",
            "lag_label": "正常",
            "lag_detail": "",
        }
    if status == "missing":
        return {
            "checked_at": checked_text,
            "checked_age_sec": checked_age_sec,
            "lag_type": "missing",
            "lag_label": "缺失",
            "lag_detail": "源字段或本地快照缺失，无法判断是否更新。",
        }
    local_check_ttl_sec = _source_health_local_check_ttl_sec(ttl_sec)
    if checked_age_sec is not None and checked_age_sec <= local_check_ttl_sec:
        return {
            "checked_at": checked_text,
            "checked_age_sec": checked_age_sec,
            "lag_type": "source_not_updated",
            "lag_label": "源未更新",
            "lag_detail": "本地已在检查窗口内抓取/物化，上游最新报文或模型周期仍未出新。",
        }
    return {
        "checked_at": checked_text,
        "checked_age_sec": checked_age_sec,
        "lag_type": "local_lag",
        "lag_label": "本地滞后",
        "lag_detail": "本地未在预期窗口内完成抓取或物化，需要检查 scan/composer 链路。",
    }


def _source_health_display_source(value: Any) -> str:
    text = str(value or "").strip()
    if not text:
        return ""
    suffix = "_cached_previous_event_run"
    doubled = suffix + suffix
    while doubled in text:
        text = text.replace(doubled, suffix)
    return text


def _source_health_item(
    key: str,
    label: str,
    *,
    last_update: str = "",
    checked_at: str = "",
    ttl_sec: Optional[float] = None,
    source: str = "",
    detail: str = "",
    coverage: Optional[Dict[str, Any]] = None,
    count: Optional[int] = None,
    na_reason: str = "",
    static_ok: bool = False,
) -> Dict[str, Any]:
    status, age_sec = _source_health_status(last_update, ttl_sec, static_ok=static_ok)
    lag_info = _source_health_lag_info(status, ttl_sec=ttl_sec, checked_at=checked_at)
    source_status = status
    source_age_sec = age_sec
    if status in {"warn", "stale"} and str(lag_info.get("lag_type") or "") == "source_not_updated":
        # The local poller/composer is fresh; the upstream simply has not emitted a newer
        # report. Keep the diagnostic fields, but do not count it as an actionable issue.
        status = "ok"
    if status == "missing" and na_reason:
        detail = detail or na_reason
    item: Dict[str, Any] = {
        "key": str(key or ""),
        "label": str(label or key or ""),
        "status": status,
        "source_status": source_status,
        "last_update": str(last_update or ""),
        "age_sec": age_sec,
        "source_age_sec": source_age_sec,
        "source_update_suppressed": bool(
            source_status in {"warn", "stale"}
            and str(lag_info.get("lag_type") or "") == "source_not_updated"
        ),
        "checked_at": lag_info.get("checked_at") or "",
        "checked_age_sec": lag_info.get("checked_age_sec"),
        "lag_type": str(lag_info.get("lag_type") or ""),
        "lag_label": str(lag_info.get("lag_label") or ""),
        "lag_detail": str(lag_info.get("lag_detail") or ""),
        "ttl_sec": ttl_sec,
        "source": _source_health_display_source(source),
        "detail": str(detail or ""),
        "na_reason": str(na_reason or "") if status == "missing" else "",
    }
    if coverage:
        item["coverage"] = coverage
    if count is not None:
        item["count"] = int(count)
    return item


def _source_health_latest_text(*values: Any) -> str:
    best_text = ""
    best_dt: Optional[datetime] = None
    for value in values:
        if not value:
            continue
        if isinstance(value, (list, tuple)):
            candidates = value
        else:
            candidates = [value]
        for candidate in candidates:
            text = str(candidate or "").strip()
            if not text:
                continue
            dt = parse_any_ts(text)
            if dt is None:
                continue
            dt_cmp = dt.astimezone(timezone.utc) if dt.tzinfo is not None else dt.replace(tzinfo=timezone.utc)
            if best_dt is None or dt_cmp > best_dt:
                best_dt = dt_cmp
                best_text = text
    return best_text


def _source_health_file_mtime_text(path: Path) -> str:
    try:
        ts = path.stat().st_mtime
    except OSError:
        return ""
    try:
        return datetime.fromtimestamp(float(ts), tz=timezone.utc).isoformat(timespec="seconds")
    except Exception:
        return ""


def _source_health_epoch_stamp_text(path: Path) -> str:
    try:
        raw = path.read_text(encoding="utf-8").strip()
    except OSError:
        return _source_health_file_mtime_text(path)
    try:
        ts = float(raw)
    except (TypeError, ValueError):
        return _source_health_file_mtime_text(path)
    if not math.isfinite(ts) or ts <= 0:
        return _source_health_file_mtime_text(path)
    try:
        return datetime.fromtimestamp(ts, tz=timezone.utc).isoformat(timespec="seconds")
    except Exception:
        return _source_health_file_mtime_text(path)


def _source_health_json_timestamp(path: Path, *keys: str) -> str:
    try:
        payload = safe_json_loads(path.read_text(encoding="utf-8"))
    except OSError:
        payload = {}
    values: List[Any] = []
    if isinstance(payload, Mapping):
        for key in keys:
            values.append(payload.get(key))
    values.append(_source_health_file_mtime_text(path))
    return _source_health_latest_text(*values)


def _source_health_weather_events_cache_state() -> Tuple[int, str, str, str]:
    paths = globals().get("_WEATHER_EVENTS_CACHE_FILES") or (
        DATA_DIR / "weather_events_cache.json",
        DATA_DIR / "weather_events_cache.good.json",
    )
    best_count = 0
    best_update = ""
    best_checked = ""
    best_source = ""
    for raw_path in paths:
        path = Path(raw_path)
        checked_at = _source_health_file_mtime_text(path)
        if checked_at:
            best_checked = _source_health_latest_text(best_checked, checked_at)
        try:
            payload = safe_json_loads(path.read_text(encoding="utf-8"))
        except OSError:
            payload = {}
        if not isinstance(payload, Mapping):
            continue
        updated_at = str(payload.get("updated_at") or "").strip() or checked_at
        events = payload.get("events")
        event_count = len(events) if isinstance(events, list) else 0
        if updated_at and updated_at == _source_health_latest_text(best_update, updated_at):
            best_update = updated_at
            best_count = event_count
            best_source = path.name
    return best_count, best_update, best_checked, best_source


def _source_health_ttl_env(key: str, default: float) -> float:
    raw = os.environ.get(key)
    if raw is None or str(raw).strip() == "":
        return float(default)
    try:
        value = float(raw)
    except (TypeError, ValueError):
        return float(default)
    return value if value > 0 else float(default)


def _source_health_first_distribution_row(payload: Mapping[str, Any]) -> Dict[str, Any]:
    dist = payload.get("distribution")
    if isinstance(dist, list):
        for row in dist:
            if isinstance(row, Mapping):
                return dict(row)
    return {}


