    db_items: List[Dict[str, Any]] = []
    with open_db_ro_fast(timeout_sec=0.25, busy_timeout_ms=250) as conn:
        cur = conn.cursor()
        def _latest_table_state(table: str, ts_col: str = "created_at") -> Tuple[int, str]:
            try:
                cur.execute(f"PRAGMA table_info({table})")
                columns = {str(row["name"] or "") for row in cur.fetchall()}
            except sqlite3.OperationalError:
                columns = set()
            if not columns:
                return 0, ""
            try:
                if "id" in columns:
                    cur.execute(f"SELECT MAX(id) AS cnt FROM {table}")
                    row = cur.fetchone()
                    count_est = int(row["cnt"] or 0) if row else 0
                else:
                    cur.execute(f"SELECT COUNT(*) AS cnt FROM {table}")
                    row = cur.fetchone()
                    count_est = int(row["cnt"] or 0) if row else 0
            except sqlite3.OperationalError:
                count_est = 0
            if ts_col not in columns:
                return count_est, ""
            order_col = "id" if "id" in columns else ts_col
            try:
                cur.execute(
                    f"""
                    SELECT {ts_col} AS ts
                    FROM {table}
                    WHERE {ts_col} IS NOT NULL AND {ts_col} != ''
                    ORDER BY {order_col} DESC
                    LIMIT 1
                    """
                )
                row = cur.fetchone()
                return count_est, str(row["ts"] or "") if row else ""
            except sqlite3.OperationalError:
                return count_est, ""
        tick_count, tick_at = _latest_table_state("event_market_ticks", "created_at")
        model_snap_count, model_snap_at = _latest_table_state("model_snapshots", "created_at")
