def _read_launchd_schedule(plist_path: Path) -> Dict[str, Any]:
    if not plist_path.exists():
        return {}
    try:
        with plist_path.open("rb") as handle:
            payload = plistlib.load(handle)
    except Exception:
        return {}
    interval = payload.get("StartInterval")
    run_at_load = bool(payload.get("RunAtLoad"))
    calendar_raw = payload.get("StartCalendarInterval")
    calendar: List[Dict[str, int]] = []
    if isinstance(calendar_raw, dict):
        entry = {}
        for key, value in calendar_raw.items():
            if isinstance(value, int):
                entry[str(key)] = int(value)
        if entry:
            calendar.append(entry)
    elif isinstance(calendar_raw, list):
        for item in calendar_raw:
            if not isinstance(item, dict):
                continue
            entry = {}
            for key, value in item.items():
                if isinstance(value, int):
                    entry[str(key)] = int(value)
            if entry:
                calendar.append(entry)
    return {
        "path": str(plist_path),
        "interval_sec": interval if isinstance(interval, int) else None,
        "run_at_load": run_at_load,
        "calendar": calendar,
    }


def update_policy_status() -> Dict[str, Any]:
    def _env_int(key: str, default: Optional[int] = None) -> Optional[int]:
        raw = os.environ.get(key)
        if raw is None or str(raw).strip() == "":
            return default
        try:
            return int(raw)
        except (TypeError, ValueError):
            return default

    def _env_float(key: str, default: Optional[float] = None) -> Optional[float]:
        raw = os.environ.get(key)
        if raw is None or str(raw).strip() == "":
            return default
        try:
            return float(raw)
        except (TypeError, ValueError):
            return default

    def _env_str(key: str, fallback: str = "") -> str:
        raw = os.environ.get(key)
        if raw is None or str(raw).strip() == "":
            return str(fallback).strip()
        return str(raw).strip()

    def _cycle_value(model_key: str, default_hours: List[int]) -> str:
        raw = _env_str(f"PM_MODEL_CYCLE_HOURS_{model_key.upper()}")
        if raw:
            return raw
        fallback = _env_str("PM_ENSEMBLE_CYCLE_HOURS")
        if fallback:
            return fallback
        return ",".join(str(x) for x in default_hours)

    cycle_defaults = {
        "gfs_seamless": [0, 6, 12, 18],
        "icon_seamless": [0, 6, 12, 18],
        "ecmwf_ifs025": [0, 6, 12, 18],
    }

    scan_schedule = _read_launchd_schedule(
        ROOT_DIR / "launchd" / "com.weather.model_scan.plist"
    )
    daily_schedule = _read_launchd_schedule(
        ROOT_DIR / "launchd" / "com.weather.daily_scan.plist"
    )
    cycles = {
        "gfs_seamless": _cycle_value("gfs_seamless", cycle_defaults["gfs_seamless"]),
        "icon_seamless": _cycle_value("icon_seamless", cycle_defaults["icon_seamless"]),
        "ecmwf_ifs025": _cycle_value("ecmwf_ifs025", cycle_defaults["ecmwf_ifs025"]),
        "nws_forecast": "official",
    }
    return {
        "models": {
            "cycles": cycles,
            "window_minutes": _env_int("PM_MODEL_WINDOW_MINUTES", 180),
            "window_refresh_minutes": _env_int("PM_MODEL_WINDOW_REFRESH_MINUTES", 3),
            "background_refresh_minutes": _env_int("PM_MODEL_BACKGROUND_REFRESH_MINUTES", 45),
            "cache_ttl_sec": {
                "nws_forecast": _env_int("PM_CACHE_TTL_NWS_SEC", 3600),
                "ensemble": _env_int("PM_CACHE_TTL_ENSEMBLE_SEC", 21600),
            },
            "cache_max_age_sec": _env_int("PM_MODEL_CACHE_MAX_AGE_SEC", 172800),
            "cycle_delay_hours": _env_int("PM_ENSEMBLE_CYCLE_DELAY_HOURS", 2),
        },
        "scan": {
            "fast_days_ahead": _env_int("PM_SCAN_FAST_DAYS_AHEAD", 2),
            "full_days_ahead": _env_int("PM_SCAN_FULL_DAYS_AHEAD", -1),
            "full_interval_minutes": _env_int("PM_SCAN_FULL_INTERVAL_MINUTES", 30),
            "schedule": scan_schedule,
        },
        "daily": {
            "schedule": daily_schedule,
        },
        "events": {
            "weather_events_cache_minutes": _env_int("PM_WEATHER_EVENTS_CACHE_MINUTES", 20),
        },
        "open_meteo": {
            "spacing_min_sec": _env_float("PM_SCAN_OPEN_METEO_SPACING_MIN", 1.5),
            "spacing_max_sec": _env_float("PM_SCAN_OPEN_METEO_SPACING_MAX", 3.5),
            "cooldown_sec": _env_int("PM_SCAN_OPEN_METEO_CITY_COOLDOWN_SEC", 3600),
            "retry_429": _env_int("PM_SCAN_OPEN_METEO_429_RETRIES", 2),
            "retry_sleep_min": _env_float("PM_SCAN_OPEN_METEO_429_MIN_SLEEP", 6.0),
            "retry_sleep_max": _env_float("PM_SCAN_OPEN_METEO_429_MAX_SLEEP", 45.0),
            "retry_jitter": _env_float("PM_SCAN_OPEN_METEO_429_JITTER", 0.35),
        },
        "updated_at": now_text(),
    }


def _edge_backtest_liquidity_penalty(
    spread_val: Optional[float],
    ask_val: Optional[float],
) -> float:
    penalty = 0.0
    if spread_val is not None and math.isfinite(spread_val):
        spread_pct = spread_val * 100.0
        penalty += max(0.0, (spread_pct - 8.0) / 10.0)
    if ask_val is not None and math.isfinite(ask_val):
        penalty += max(0.0, (ask_val - 0.6) / 0.2)
    return penalty


def _edge_backtest_lag_factor(
    ask: Optional[float],
    bid: Optional[float],
    spread: Optional[float],
    mid_price: Optional[float],
) -> Optional[float]:
    if ask is None or spread is None or spread <= 0:
        return None
    mid = mid_price
    if mid is None:
        if bid is None:
            return None
        mid = (ask + bid) / 2.0
    return (ask - mid) / spread


def _edge_backtest_side_data(
    bucket: Dict[str, Any],
    side: str,
    q_round: Optional[float],
    q_min: Optional[float],
    q_round_no: Optional[float],
    q_min_no: Optional[float],
) -> Optional[Dict[str, Any]]:
    if side == "YES":
        ask = to_float(bucket.get("best_ask"))
        bid = to_float(bucket.get("best_bid"))
        spread = to_float(bucket.get("spread"))
        lag = to_float(bucket.get("lag_yes"))
        mid_price = to_float(bucket.get("yes_price"))
        p_move = to_float(bucket.get("p_move_yes"))
        q_bound = q_min
        q_val = q_round
        time_factor = to_float(bucket.get("time_factor_yes") or bucket.get("time_factor"))
    else:
        ask = to_float(bucket.get("best_ask_no"))
        bid = to_float(bucket.get("best_bid_no"))
        spread = to_float(bucket.get("spread_no"))
        lag = to_float(bucket.get("lag_no"))
        mid_price = to_float(bucket.get("no_price"))
        p_move = to_float(bucket.get("p_move_no"))
        q_bound = q_min_no
        q_val = q_round_no
        time_factor = to_float(bucket.get("time_factor_no") or bucket.get("time_factor"))
    structure_factor = to_float(bucket.get("structure_factor"))
    if lag is None:
        lag = _edge_backtest_lag_factor(ask, bid, spread, mid_price)
    if ask is None and bid is None and q_bound is None:
        return None
    signal_edge_min = (q_bound - ask) if (q_bound is not None and ask is not None) else None
    edge_points = (max(q_val - ask, 0.0) * 100.0) if (q_val is not None and ask is not None) else None
    penalty = _edge_backtest_liquidity_penalty(spread, ask) if ask is not None else None
    edge_score = None
    if (
        edge_points is not None
        and penalty is not None
        and time_factor is not None
        and structure_factor is not None
        and math.isfinite(time_factor)
        and math.isfinite(structure_factor)
    ):
        time_structure = max(time_factor * structure_factor, EDGE_BACKTEST_TIME_STRUCTURE_MIN)
        edge_score = (edge_points * time_structure) - penalty
    if p_move is None and q_bound is not None and ask is not None:
        p_move = 1.0 if q_bound > ask else 0.0
    return {
        "ask": ask,
        "bid": bid,
        "spread": spread,
        "lag": lag,
        "p_move": p_move,
        "q_min_bound": q_bound,
        "signal_edge_min": signal_edge_min,
        "edge_score": edge_score,
    }


def _edge_backtest_edge_min(
    side_data: Dict[str, Any],
    ask_min: float,
    ask_max: float,
    lag_max: float,
) -> float:
    ask = side_data.get("ask")
    lag = side_data.get("lag")
    signal_edge_min = side_data.get("signal_edge_min")
    if ask is None or not math.isfinite(ask):
        return 0.0
    if ask < ask_min or ask > ask_max:
        return 0.0
    if lag is None or not math.isfinite(lag) or lag > lag_max:
        return 0.0
    if signal_edge_min is None or not math.isfinite(signal_edge_min):
        return 0.0
    return max(signal_edge_min, 0.0)


def _edge_backtest_candidate(
    side_data: Dict[str, Any],
    edge_score_min: float,
    ask_min: float,
    ask_max: float,
    lag_max: float,
    ask_le_q_min_buffer: float,
) -> Optional[Dict[str, Any]]:
    ask = side_data.get("ask")
    spread = side_data.get("spread")
    q_min_bound = side_data.get("q_min_bound")
    edge_score = side_data.get("edge_score")
    if ask is None or not math.isfinite(ask) or ask <= 0:
        return None
    if q_min_bound is None or not math.isfinite(q_min_bound) or ask > q_min_bound + ask_le_q_min_buffer:
        return None
    if spread is not None and (not math.isfinite(spread) or spread < 0):
        return None
    edge_min = _edge_backtest_edge_min(side_data, ask_min, ask_max, lag_max)
    if edge_min <= 0:
        return None
    if edge_score is None or not math.isfinite(edge_score) or edge_score < edge_score_min:
        return None
    return {"edge_min": edge_min, "edge_score": edge_score}


def _edge_backtest_simulate(
    scans: List[Dict[str, Any]],
    actual_labels: Dict[Tuple[str, str], str],
    cfg: Dict[str, Any],
) -> Dict[str, Any]:
    positions: Dict[Tuple[str, str, str, str], Dict[str, Any]] = {}
    last_p_move: Dict[Tuple[str, str, str, str], float] = {}
    trades = 0
    wins = 0
    total_pnl = 0.0
    for scan in scans:
        key = scan["key"]
        actual_label = actual_labels.get(key)
        if not actual_label:
            continue
        ts = scan["ts"]
        for bucket in scan["rows"]:
            outcome = bucket["outcome"]
            candidates: List[Tuple[str, float, float]] = []
            for side_key, side_name in (("yes", "YES"), ("no", "NO")):
                side_data = bucket.get(side_key)
                if not side_data:
                    continue
                cand = _edge_backtest_candidate(
                    side_data,
                    cfg["edge_score_min"],
                    cfg["ask_min"],
                    cfg["ask_max"],
                    cfg["lag_max"],
                    cfg["ask_le_q_min_buffer"],
                )
                if cand:
                    candidates.append((side_name, cand["edge_min"], cand["edge_score"]))
            if len(candidates) > 1:
                candidates.sort(key=lambda item: (item[1], item[2]), reverse=True)
                candidates = candidates[:1]
            candidate_sides = {item[0] for item in candidates}
            for side_key, side_name in (("yes", "YES"), ("no", "NO")):
                side_data = bucket.get(side_key)
                if not side_data:
                    continue
                pos_key = (key[0], key[1], outcome, side_name)
                pos = positions.get(pos_key)
                p_move = side_data.get("p_move")
                prev_p_move = last_p_move.get(pos_key)
                if p_move is not None and math.isfinite(p_move):
                    last_p_move[pos_key] = p_move
                exit_flag = False
                if pos:
                    edge_min = _edge_backtest_edge_min(
                        side_data,
                        cfg["ask_min"],
                        cfg["ask_max"],
                        cfg["lag_max"],
                    )
                    if edge_min < cfg["exit_headroom"]:
                        exit_flag = True
                    lag = side_data.get("lag")
                    if lag is not None and math.isfinite(lag) and lag > cfg["exit_lag"]:
                        exit_flag = True
                    if (
                        prev_p_move is not None
                        and math.isfinite(prev_p_move)
                        and prev_p_move > 0
                        and (p_move or 0) <= 0
                    ):
                        exit_flag = True
                    hold_min = cfg.get("max_hold_min") or 0
                    entry_time = pos.get("entry_time")
                    if entry_time and hold_min > 0:
                        if (ts - entry_time).total_seconds() >= hold_min * 60:
                            exit_flag = True
                if side_name in candidate_sides and not pos and not exit_flag:
                    ask = side_data.get("ask")
                    if ask is None or not math.isfinite(ask) or ask <= 0:
                        continue
                    size = EDGE_BACKTEST_NOTIONAL / ask
                    positions[pos_key] = {"entry_price": ask, "size": size, "entry_time": ts}
                    trades += 1
                    continue
                if pos and exit_flag:
                    exit_price = side_data.get("bid") or side_data.get("ask")
                    if exit_price is None or not math.isfinite(exit_price) or exit_price <= 0:
                        continue
                    pnl = pos["size"] * exit_price - EDGE_BACKTEST_NOTIONAL
                    total_pnl += pnl
                    if pnl > 0:
                        wins += 1
                    positions.pop(pos_key, None)
    for pos_key, pos in positions.items():
        event_key = (pos_key[0], pos_key[1])
        actual_label = actual_labels.get(event_key)
        if not actual_label:
            continue
        outcome = pos_key[2]
        side_name = pos_key[3]
        win = (side_name == "YES" and outcome == actual_label) or (
            side_name == "NO" and outcome != actual_label
        )
        payout = 1.0 if win else 0.0
        pnl = pos["size"] * payout - EDGE_BACKTEST_NOTIONAL
        total_pnl += pnl
        if pnl > 0:
            wins += 1
    roi = (total_pnl / trades) if trades else 0.0
    win_rate = (wins / trades) if trades else 0.0
    return {
        "trades": trades,
        "wins": wins,
        "win_rate": win_rate,
        "total_pnl": total_pnl,
        "roi": roi,
    }


def compute_edge_backtest_summary() -> Dict[str, Any]:
    if not DB_PATH.exists():
        return {"ok": False, "error": "db_missing", "updated_at": now_text()}
    if scan_bucket_label_for_value is None:
        return {"ok": False, "error": "bucket_unavailable", "updated_at": now_text()}
    with open_db() as conn:
        cur = conn.cursor()
        try:
            ensure_fact_tables(conn)
        except Exception:
            return {"ok": False, "error": "facts_missing", "updated_at": now_text()}
        settlement_map: Dict[Tuple[str, str], Optional[float]] = {}
        try:
            cur.execute(
                """
                SELECT slug, event_date, settlement_actual, created_at
                FROM event_daily_temps
                WHERE settlement_actual IS NOT NULL
                ORDER BY created_at DESC, id DESC
                """
            )
            for srow in cur.fetchall():
                slug = str(srow["slug"] or "")
                event_date = date_only(str(srow["event_date"] or ""))
                if not slug or not event_date:
                    continue
                key = (slug, event_date)
                if key in settlement_map:
                    continue
                settlement_map[key] = to_float(srow["settlement_actual"])
        except sqlite3.OperationalError:
            settlement_map = {}
        cur.execute(
            """
            SELECT slug, event_date, fact_as_of, fact_json
            FROM event_fact_history
            ORDER BY fact_as_of ASC, id ASC
            """
        )
        rows = cur.fetchall()
    actual_labels: Dict[Tuple[str, str], str] = {}
    scans: List[Dict[str, Any]] = []
    bucket_count = 0
    for row in rows:
        slug = str(row["slug"] or "")
        event_date = str(row["event_date"] or "")
        if not slug or not event_date:
            continue
        if is_before_stats_cutoff(event_date):
            continue
        created_at = parse_iso_ts(str(row["fact_as_of"] or ""))
        if created_at is None:
            continue
        if created_at.tzinfo is None:
            created_at = created_at.replace(tzinfo=timezone.utc)
        else:
            created_at = created_at.astimezone(timezone.utc)
        fact = safe_json_loads(row["fact_json"])
        if not isinstance(fact, dict):
            continue
        rows_all = fact.get("distribution") or fact.get("rows")
        if not isinstance(rows_all, list) or not rows_all:
            continue
        event_date_key = date_only(event_date)
        key = (slug, event_date_key)
        settlement_actual = settlement_map.get(key)
        if settlement_actual is None or not math.isfinite(settlement_actual):
            continue
        actual_label = actual_labels.get(key)
        if actual_label is None:
            rounding_rule = str(fact.get("rounding_rule") or "")
            actual_label = ""
            try:
                actual_label = scan_bucket_label_for_value(rows_all, settlement_actual, rounding_rule)
            except Exception:
                actual_label = ""
            actual_labels[key] = actual_label or ""
        if not actual_labels.get(key):
            continue
        scan_rows: List[Dict[str, Any]] = []
        for bucket in rows_all:
            label = str(bucket.get("outcome") or "")
            if not label:
                continue
            q_round = to_float(bucket.get("q_round"))
            q_min = to_float(bucket.get("q_min"))
            q_max = to_float(bucket.get("q_max"))
            q_round_no = to_float(bucket.get("q_round_no"))
            if q_round_no is None and q_round is not None:
                q_round_no = 1.0 - q_round
            q_min_no = to_float(bucket.get("q_min_no"))
            if q_min_no is None and q_max is not None:
                q_min_no = 1.0 - q_max
            side_yes = _edge_backtest_side_data(
                bucket,
                "YES",
                q_round,
                q_min,
                q_round_no,
                q_min_no,
            )
            side_no = _edge_backtest_side_data(
                bucket,
                "NO",
                q_round,
                q_min,
                q_round_no,
                q_min_no,
            )
            if not side_yes and not side_no:
                continue
            scan_rows.append({"outcome": label, "yes": side_yes, "no": side_no})
        if not scan_rows:
            continue
        bucket_count += len(scan_rows)
        scans.append({"key": key, "ts": created_at, "rows": scan_rows})
    if not scans:
        return {"ok": False, "error": "no_samples", "updated_at": now_text()}
    scans.sort(key=lambda item: item["ts"])
    buffer_val = auto_trade_config_defaults().get("entry_ask_le_q_min_buffer", 0.0)
    ask_le_q_min_buffer = to_float(buffer_val)
    if ask_le_q_min_buffer is None or not math.isfinite(ask_le_q_min_buffer) or ask_le_q_min_buffer < 0:
        ask_le_q_min_buffer = 0.0
    results = []
    keys = ["edge_score_min", "ask_max", "lag_max", "exit_headroom", "max_hold_min"]
    values = [EDGE_BACKTEST_GRID[k] for k in keys]
    for combo in itertools.product(*values):
        cfg = dict(zip(keys, combo))
        cfg["ask_min"] = EDGE_BACKTEST_ASK_MIN
        cfg["ask_le_q_min_buffer"] = ask_le_q_min_buffer
        cfg["exit_lag"] = EDGE_BACKTEST_EXIT_LAG
        stats = _edge_backtest_simulate(scans, actual_labels, cfg)
        result = dict(cfg)
        result.update(stats)
        results.append(result)
    results.sort(key=lambda item: item["total_pnl"], reverse=True)
    eligible = [
        item
        for item in results
        if item["trades"] >= EDGE_BACKTEST_MIN_TRADES and item["roi"] > 0
    ]
    nonzero = [item for item in results if item["trades"] > 0]
    if eligible:
        best = max(
            eligible,
            key=lambda item: (item["total_pnl"], item["roi"], item["trades"]),
        )
        best_positive = True
    elif nonzero:
        best = max(
            nonzero,
            key=lambda item: (item["roi"], item["total_pnl"], item["trades"]),
        )
        best_positive = False
    else:
        best = max(
            results,
            key=lambda item: (item["total_pnl"], item["roi"], item["trades"]),
        )
        best_positive = False
    top_results = nonzero[:10] if nonzero else results[:10]
    return {
        "ok": True,
        "cutoff_date": STATS_CUTOFF_DATE,
        "generated_at": datetime.now(timezone.utc).isoformat(),
        "sample": {
            "events": len(actual_labels),
            "scans": len(scans),
            "buckets": bucket_count,
        },
        "best": best,
        "best_positive": best_positive,
        "top": top_results,
        "ranges": EDGE_BACKTEST_GRID,
        "fixed": {
            "ask_min": EDGE_BACKTEST_ASK_MIN,
            "exit_lag": EDGE_BACKTEST_EXIT_LAG,
            "min_trades": EDGE_BACKTEST_MIN_TRADES,
            "notional": EDGE_BACKTEST_NOTIONAL,
        },
        "updated_at": now_text(),
    }


def edge_backtest_summary(force: bool = False) -> Dict[str, Any]:
    global EDGE_BACKTEST_CACHE
    with EDGE_BACKTEST_LOCK:
        if EDGE_BACKTEST_CACHE and not force:
            cached = dict(EDGE_BACKTEST_CACHE)
            if cached.get("cutoff_date") == STATS_CUTOFF_DATE:
                return cached
        if EDGE_BACKTEST_CACHE_PATH.exists() and not force:
            try:
                raw = EDGE_BACKTEST_CACHE_PATH.read_text(encoding="utf-8")
                cached = json.loads(raw)
            except (OSError, json.JSONDecodeError):
                cached = None
            if isinstance(cached, dict):
                try:
                    mtime = EDGE_BACKTEST_CACHE_PATH.stat().st_mtime
                    if (time.time() - mtime) <= EDGE_BACKTEST_MAX_AGE_SEC:
                        if cached.get("cutoff_date") == STATS_CUTOFF_DATE:
                            EDGE_BACKTEST_CACHE = dict(cached)
                            return dict(cached)
                except OSError:
                    pass
        summary = compute_edge_backtest_summary()
        EDGE_BACKTEST_CACHE = dict(summary)
        if summary.get("ok"):
            try:
                EDGE_BACKTEST_CACHE_PATH.write_text(
                    json.dumps(summary, ensure_ascii=True),
                    encoding="utf-8",
                )
            except OSError:
                pass
        return dict(summary)


def _load_edge_bias_cache() -> None:
    global EDGE_BIAS_CACHE_LOADED, EDGE_BIAS_CACHE
    if EDGE_BIAS_CACHE_LOADED:
        return
    EDGE_BIAS_CACHE_LOADED = True
    if not EDGE_BIAS_CACHE_PATH.exists():
        return
    try:
        raw = EDGE_BIAS_CACHE_PATH.read_text(encoding="utf-8")
        cached = json.loads(raw)
    except (OSError, json.JSONDecodeError):
        return
    if not isinstance(cached, dict):
        return
    if cached.get("version") != EDGE_BIAS_CACHE_VERSION:
        return
    by_days = cached.get("by_days") if isinstance(cached.get("by_days"), dict) else cached
    if not isinstance(by_days, dict):
        return
    for key, entry in by_days.items():
        try:
            days = int(key)
        except (TypeError, ValueError):
            continue
        if not isinstance(entry, dict):
            continue
        payload = entry.get("payload")
        if not isinstance(payload, dict):
            continue
        EDGE_BIAS_CACHE[days] = dict(entry)


def _save_edge_bias_cache() -> None:
    try:
        payload = {
            "saved_at": now_text(),
            "version": EDGE_BIAS_CACHE_VERSION,
            "by_days": {str(key): value for key, value in EDGE_BIAS_CACHE.items()},
        }
        EDGE_BIAS_CACHE_PATH.write_text(
            json.dumps(payload, ensure_ascii=True),
            encoding="utf-8",
        )
    except OSError:
        pass


def _ensure_feedback_tables(conn: sqlite3.Connection) -> None:
    cur = conn.cursor()
    cur.execute(
        """
        CREATE TABLE IF NOT EXISTS edge_bias_calibration_runs (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            days INTEGER NOT NULL,
            payload_json TEXT,
            ok INTEGER NOT NULL DEFAULT 1,
            error TEXT,
            created_at TEXT NOT NULL
        )
        """
    )
    cur.execute(
        """
        CREATE INDEX IF NOT EXISTS idx_edge_bias_calibration_runs_days_created
        ON edge_bias_calibration_runs(days, created_at DESC)
        """
    )
    cur.execute(
        """
        CREATE TABLE IF NOT EXISTS edge_bias_calibration_bins (
            run_id INTEGER NOT NULL,
            basis TEXT NOT NULL,
            bin_index INTEGER NOT NULL,
            low REAL NOT NULL,
            high REAL NOT NULL,
            count INTEGER NOT NULL,
            win_rate REAL,
            pred_mean REAL,
            real_mean REAL,
            bias_mean REAL,
            ratio REAL,
            PRIMARY KEY (run_id, basis, bin_index)
        )
        """
    )
    cur.execute(
        """
        CREATE INDEX IF NOT EXISTS idx_edge_bias_calibration_bins_lookup
        ON edge_bias_calibration_bins(run_id, basis, bin_index)
        """
    )
    cur.execute(
        """
        CREATE TABLE IF NOT EXISTS feedback_snapshots (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            kind TEXT NOT NULL,
            days INTEGER NOT NULL,
            end_date TEXT,
            payload_json TEXT NOT NULL,
            ok INTEGER NOT NULL DEFAULT 1,
            error TEXT,
            created_at TEXT NOT NULL
        )
        """
    )
    cur.execute(
        """
        CREATE INDEX IF NOT EXISTS idx_feedback_snapshots_lookup
        ON feedback_snapshots(kind, days, created_at DESC)
        """
    )
    cur.execute(
        """
        CREATE TABLE IF NOT EXISTS optimizer_actions (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            kind TEXT NOT NULL,
            days INTEGER NOT NULL,
            end_date TEXT,
            suggestion_snapshot_id INTEGER,
            status TEXT NOT NULL,
            reason_code TEXT,
            reason_text TEXT,
            before_json TEXT,
            after_json TEXT,
            restart_json TEXT,
            scan_json TEXT,
            created_at TEXT NOT NULL
        )
        """
    )
    cur.execute(
        """
        CREATE INDEX IF NOT EXISTS idx_optimizer_actions_kind_created
        ON optimizer_actions(kind, created_at DESC)
        """
    )
    cur.execute(
        """
        CREATE INDEX IF NOT EXISTS idx_optimizer_actions_status_created
        ON optimizer_actions(status, created_at DESC)
        """
    )


def _edge_bias_bins_from_payload(payload: Dict[str, Any], basis: str) -> List[Dict[str, Any]]:
    basis_key = f"{basis}_basis" if basis in {"event", "trade"} else ""
    basis_payload = payload.get(basis_key) if basis_key else None
    if not isinstance(basis_payload, dict):
        basis_payload = payload.get("event_basis") if basis == "event" else payload.get("trade_basis")
    if not isinstance(basis_payload, dict):
        return []
    calib = basis_payload.get("calibration") if isinstance(basis_payload.get("calibration"), dict) else {}
    bins = calib.get("bins") if isinstance(calib, dict) else None
    if not isinstance(bins, list):
        return []
    out: List[Dict[str, Any]] = []
    for idx, row in enumerate(bins):
        if not isinstance(row, dict):
            continue
        rng = row.get("range")
        if not isinstance(rng, list) or len(rng) < 2:
            continue
        low = to_float(rng[0])
        high = to_float(rng[1])
        if low is None or high is None or not math.isfinite(low) or not math.isfinite(high):
            continue
        try:
            count = int(row.get("count") or 0)
        except Exception:
            count = 0
        out.append(
            {
                "basis": basis,
                "bin_index": int(idx),
                "low": float(low),
                "high": float(high),
                "count": int(count),
                "win_rate": to_float(row.get("win_rate")),
                "pred_mean": to_float(row.get("pred_mean")),
                "real_mean": to_float(row.get("real_mean")),
                "bias_mean": to_float(row.get("bias_mean")),
                "ratio": to_float(row.get("ratio")),
            }
        )
    return out


def _load_latest_edge_bias_run_from_db(
    conn: sqlite3.Connection,
    days: int,
    *,
    require_ok: bool,
) -> Optional[Dict[str, Any]]:
    _ensure_feedback_tables(conn)
    cur = conn.cursor()
    if require_ok:
        cur.execute(
            """
            SELECT id, payload_json, error, created_at
            FROM edge_bias_calibration_runs
            WHERE days = ? AND ok = 1
            ORDER BY created_at DESC, id DESC
            LIMIT 1
            """,
            (int(days),),
        )
    else:
        cur.execute(
            """
            SELECT id, payload_json, error, created_at, ok
            FROM edge_bias_calibration_runs
            WHERE days = ?
            ORDER BY created_at DESC, id DESC
            LIMIT 1
            """,
            (int(days),),
        )
    row = cur.fetchone()
    if not row:
        return None
    payload = safe_json_loads(row[1]) if row[1] else None
    if not isinstance(payload, dict):
        payload = {}
    out = {
        "id": int(row[0]),
        "payload": payload,
        "error": str(row[2] or ""),
        "created_at": str(row[3] or ""),
    }
    if not require_ok:
        out["ok"] = int(row[4] or 0)
    return out


def _save_edge_bias_run_to_db(
    conn: sqlite3.Connection,
    days: int,
    payload: Dict[str, Any],
    *,
    ok: bool,
    error: str,
) -> int:
    _ensure_feedback_tables(conn)
    cur = conn.cursor()
    created_at = now_text()
    cur.execute(
        """
        INSERT INTO edge_bias_calibration_runs(days, payload_json, ok, error, created_at)
        VALUES (?, ?, ?, ?, ?)
        """,
        (int(days), json.dumps(payload, ensure_ascii=True), 1 if ok else 0, error or "", created_at),
    )
    run_id = int(cur.lastrowid)
    # Store calibration bins for both bases; scan reads event basis.
    for basis in ("event", "trade"):
        for row in _edge_bias_bins_from_payload(payload, basis):
            cur.execute(
                """
                INSERT OR REPLACE INTO edge_bias_calibration_bins(
                    run_id, basis, bin_index, low, high, count, win_rate, pred_mean, real_mean, bias_mean, ratio
                ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                """,
                (
                    run_id,
                    str(row.get("basis") or basis),
                    int(row.get("bin_index") or 0),
                    float(row.get("low") or 0.0),
                    float(row.get("high") or 0.0),
                    int(row.get("count") or 0),
                    to_float(row.get("win_rate")),
                    to_float(row.get("pred_mean")),
                    to_float(row.get("real_mean")),
                    to_float(row.get("bias_mean")),
                    to_float(row.get("ratio")),
                ),
            )
    return run_id


def _edge_bias_payload(entry: Dict[str, Any], cached: bool, error: Optional[str] = None) -> Dict[str, Any]:
    payload = dict(entry.get("payload") or {})
    payload["cached"] = cached
    payload["last_ok_at"] = entry.get("last_ok_at") or ""
    payload["last_error"] = error if error is not None else (entry.get("last_error") or "")
    return payload


def compute_edge_bias_stats(days: int) -> Dict[str, Any]:
    if not DB_PATH.exists():
        return {"ok": False, "days": days, "events": 0, "generated_at": now_text()}
    with open_db() as conn:
        trade_rows = load_auto_trade_runs(conn, days, require_settlement=True)
        event_rows = load_event_rows(conn, days, require_settlement=True)
    event_rows = pick_latest_rows(event_rows)
    trade_stats = compute_edge_bias_stats_for_rows(trade_rows, days, include_orders=False, basis="trade")
    event_stats = compute_edge_bias_stats_for_rows(event_rows, days, include_orders=False, basis="event")
    payload = dict(trade_stats)
    payload["event_basis"] = event_stats
    payload["trade_basis"] = trade_stats
    return payload


def compute_edge_bias_stats_for_rows(
    rows: List[Dict[str, Any]],
    days: int,
    *,
    include_orders: bool,
    basis: str,
) -> Dict[str, Any]:
    normalized_rows: List[Dict[str, Any]] = []
    for row in rows:
        if isinstance(row, sqlite3.Row):
            normalized_rows.append(dict(row))
        elif isinstance(row, dict):
            normalized_rows.append(dict(row))
        else:
            try:
                normalized_rows.append(dict(row))
            except Exception:
                continue
    event_groups: Dict[Tuple[str, str], List[Dict[str, Any]]] = {}
    for row in normalized_rows:
        key = event_key(row)
        event_groups.setdefault(key, []).append(row)
    total_settled = len(event_groups)
    unique_events = set(event_groups.keys())
    total_events = 0
    effective_events = 0
    excluded = {
        "missing_distribution": 0,
        "missing_actual_label": 0,
        "missing_price": 0,
        "missing_prob": 0,
        "missing_candidate": 0,
        "non_positive_edge": 0,
    }

    def init_entry() -> Dict[str, Any]:
        return {
            "count": 0,
            "hit": 0,
            "pred_sum": 0.0,
            "real_sum": 0.0,
            "bias_sum": 0.0,
            "bias_list": [],
        }

    yes_entry = init_entry()
    no_entry = init_entry()
    best_entry = init_entry()
    top_yes_entry = init_entry()
    top_no_entry = init_entry()
    top_entry = init_entry()
    feature_maps: Dict[str, Dict[str, Dict[str, Any]]] = {
        "label": {},
        "top_label": {},
        "match_top": {},
        "side": {},
        "ask_band": {},
        "q_band": {},
        "edge_band": {},
        "confidence_band": {},
        "roi_band": {},
        "bias_sign": {},
        "bucket_tag": {},
        "model_tag": {},
        "market_tag": {},
        "temp_point": {},
        "temp_range": {},
        "temp_open": {},
    }
    order_feature_maps: Optional[Dict[str, Dict[str, Dict[str, Any]]]] = None
    if include_orders:
        order_feature_maps = {
            "label": {},
            "side": {},
            "match_top": {},
            "ask_band": {},
            "q_band": {},
            "edge_band": {},
            "confidence_band": {},
            "roi_band": {},
            "bias_sign": {},
            "bucket_tag": {},
            "model_tag": {},
            "market_tag": {},
            "temp_point": {},
            "temp_range": {},
            "temp_open": {},
        }
    calibration_bins = [(0.0, 2.0), (2.0, 5.0), (5.0, 10.0), (10.0, 20.0), (20.0, 40.0), (40.0, 100.0)]
    calibration_rows = [
        {"count": 0, "hit": 0, "pred_sum": 0.0, "real_sum": 0.0, "bias_sum": 0.0}
        for _ in calibration_bins
    ]
    roi_stats = {"count": 0, "sum": 0.0, "positive": 0, "values": []}
    order_roi_stats = {"count": 0, "sum": 0.0, "positive": 0, "values": []} if include_orders else None
    side_stats = {"YES": {"count": 0, "sum": 0.0, "positive": 0, "values": []}, "NO": {"count": 0, "sum": 0.0, "positive": 0, "values": []}}
    order_side_stats = {"YES": {"count": 0, "sum": 0.0, "positive": 0, "values": []}, "NO": {"count": 0, "sum": 0.0, "positive": 0, "values": []}} if include_orders else None
    order_entry_total = 0
    order_entry_covered = 0

    def apply_candidate(entry: Dict[str, Any], cand: Dict[str, Any], is_yes: bool, actual_label: str) -> None:
        if not cand:
            return
        edge_val = to_float(cand.get("edge"))
        if edge_val is None or not math.isfinite(edge_val) or edge_val <= 0:
            return
        label = str(cand.get("label") or "")
        q_val = to_float(cand.get("q"))
        ask_val = to_float(cand.get("ask"))
        if q_val is None or ask_val is None:
            return
        actual = 1.0 if label == actual_label else 0.0
        if not is_yes:
            actual = 0.0 if label == actual_label else 1.0
        pred_edge = (q_val - ask_val) * 100.0
        real_edge = (actual - ask_val) * 100.0
        bias = (actual - q_val) * 100.0
        entry["count"] += 1
        entry["hit"] += 1 if actual > 0.5 else 0
        entry["pred_sum"] += pred_edge
        entry["real_sum"] += real_edge
        entry["bias_sum"] += bias
        entry["bias_list"].append(bias)

    def compute_edge_metrics(
        cand: Dict[str, Any],
        is_yes: bool,
        actual_label: str,
    ) -> Optional[Tuple[float, float, float, bool, float, float, str, Optional[float], Optional[float]]]:
        if not cand:
            return None
        edge_val = to_float(cand.get("edge"))
        if edge_val is None or not math.isfinite(edge_val) or edge_val <= 0:
            return None
        label = str(cand.get("label") or "")
        q_val = to_float(cand.get("q"))
        ask_val = to_float(cand.get("ask"))
        if q_val is None or ask_val is None:
            return None
        actual = 1.0 if label == actual_label else 0.0
        if not is_yes:
            actual = 0.0 if label == actual_label else 1.0
        pred_edge = (q_val - ask_val) * 100.0
        real_edge = (actual - ask_val) * 100.0
        bias = (actual - q_val) * 100.0
        hit = actual > 0.5
        ratio = (real_edge / pred_edge) if pred_edge > 0 else None
        roi = (actual - ask_val) / ask_val if ask_val and ask_val > 0 else None
        return pred_edge, real_edge, bias, hit, q_val, ask_val, label, ratio, roi

    def compute_order_metrics(
        q_val: Optional[float],
        ask_val: Optional[float],
        label: str,
        is_yes: bool,
        actual_label: str,
    ) -> Optional[Tuple[float, float, float, bool, Optional[float], Optional[float]]]:
        if q_val is None or ask_val is None:
            return None
        if not math.isfinite(q_val) or not math.isfinite(ask_val):
            return None
        actual = 1.0 if label == actual_label else 0.0
        if not is_yes:
            actual = 0.0 if label == actual_label else 1.0
        pred_edge = (q_val - ask_val) * 100.0
        real_edge = (actual - ask_val) * 100.0
        bias = (actual - q_val) * 100.0
        hit = actual > 0.5
        ratio = (real_edge / pred_edge) if pred_edge != 0 else None
        roi = (actual - ask_val) / ask_val if ask_val > 0 else None
        return pred_edge, real_edge, bias, hit, ratio, roi

    def record_feature(
        feature_map: Dict[str, Dict[str, Any]],
        key: str,
        metrics: Tuple[float, float, float, bool, Optional[float], Optional[float]],
    ) -> None:
        pred_edge, real_edge, bias, hit, ratio, roi = metrics
        entry = feature_map.get(key)
        if not entry:
            entry = {
                "count": 0,
                "hit": 0,
                "pred_sum": 0.0,
                "real_sum": 0.0,
                "bias_sum": 0.0,
                "ratio_sum": 0.0,
                "ratio_count": 0,
                "roi_sum": 0.0,
                "roi_count": 0,
            }
            feature_map[key] = entry
        entry["count"] += 1
        entry["hit"] += 1 if hit else 0
        entry["pred_sum"] += pred_edge
        entry["real_sum"] += real_edge
        entry["bias_sum"] += bias
        if ratio is not None and math.isfinite(ratio):
            entry["ratio_sum"] += ratio
            entry["ratio_count"] += 1
        if roi is not None and math.isfinite(roi):
            entry["roi_sum"] += roi
            entry["roi_count"] += 1

    def update_roi_stats(stats: Dict[str, Any], roi: Optional[float]) -> None:
        if roi is None or not math.isfinite(roi):
            return
        stats["count"] += 1
        stats["sum"] += roi
        stats["positive"] += 1 if roi > 0 else 0
        stats["values"].append(float(roi))

    def finalize_roi_stats(stats: Dict[str, Any]) -> Dict[str, Any]:
        count = int(stats.get("count") or 0)
        if count <= 0:
            return {"count": 0, "mean": None, "median": None, "positive_rate": None}
        values = [float(x) for x in stats.get("values") or [] if x is not None]
        mean = stats.get("sum", 0.0) / count if count else None
        median_val = median(values) if values else None
        positive_rate = (stats.get("positive", 0) / count) if count else None
        return {
            "count": count,
            "mean": mean,
            "median": median_val,
            "positive_rate": positive_rate,
        }

    def finalize_side_stats(stats_map: Dict[str, Dict[str, Any]]) -> Dict[str, Dict[str, Any]]:
        total = sum(int(entry.get("count") or 0) for entry in stats_map.values())
        out: Dict[str, Dict[str, Any]] = {}
        for side, entry in stats_map.items():
            base = finalize_roi_stats(entry)
            share = (entry.get("count", 0) / total) if total else None
            out[side] = {**base, "share": share}
        return out

    def band_label(value: Optional[float], bands: List[Tuple[float, float, str]]) -> str:
        if value is None or not math.isfinite(value):
            return "unknown"
        for low, high, label in bands:
            if value >= low and value < high:
                return label
        return bands[-1][2] if bands else "unknown"

    def top_label_for_key(distribution: List[Dict[str, Any]], key: str) -> str:
        best_val: Optional[float] = None
        best_label = ""
        for drow in distribution:
            label = str(drow.get("outcome") or "")
            if not label:
                continue
            q_val = to_float(drow.get(key))
            if q_val is None:
                q_val = to_float(drow.get("q_round"))
            if q_val is None:
                continue
            if best_val is None or q_val > best_val:
                best_val = q_val
                best_label = label
        return best_label

    def build_per_model_top(distribution: List[Dict[str, Any]]) -> Dict[str, Dict[str, Any]]:
        best_by_model: Dict[str, Dict[str, Any]] = {}
        for drow in distribution:
            label = str(drow.get("outcome") or "")
            if not label:
                continue
            per_model = drow.get("per_model_q")
            if not isinstance(per_model, dict):
                continue
            for model, data in per_model.items():
                if not isinstance(data, dict):
                    continue
                q_val = to_float(data.get("q_round"))
                if q_val is None:
                    continue
                current = best_by_model.get(model)
                if not current or q_val > to_float(current.get("q") or float("-inf")):
                    best_by_model[model] = {"label": label, "q": q_val}
        return best_by_model

    def build_tag_context(
        distribution: List[Dict[str, Any]],
        row: sqlite3.Row,
    ) -> Dict[str, Any]:
        rounding_rule = str(row.get("rounding_rule") or "")
        market_var = str(row.get("market_var") or "")
        market_label = market_top_label(distribution)
        corrected_labels = {
            "equal": str(row.get("corrected_top_bucket_equal") or ""),
            "auto": str(row.get("corrected_top_bucket_auto") or ""),
            "scenario": str(row.get("corrected_top_bucket_scenario") or ""),
        }
        corrected_vals = [val for val in corrected_labels.values() if val]
        corrected_unified = ""
        if corrected_vals and len(set(corrected_vals)) == 1:
            corrected_unified = corrected_vals[0]
        model_top_label, _ = top_bucket_from_distribution(distribution, "q_raw")
        expected_equal = expected_value_from_distribution(distribution, "q_equal", rounding_rule, market_var)
        expected_auto = expected_value_from_distribution(distribution, "q_auto", rounding_rule, market_var)
        expected_scenario = expected_value_from_distribution(distribution, "q_scenario", rounding_rule, market_var)
        tag_equal = (
            bucket_label_for_value(distribution, expected_equal, rounding_rule, market_var)
            if expected_equal is not None
            else ""
        )
        tag_auto = (
            bucket_label_for_value(distribution, expected_auto, rounding_rule, market_var)
            if expected_auto is not None
            else ""
        )
        tag_scenario = (
            bucket_label_for_value(distribution, expected_scenario, rounding_rule, market_var)
            if expected_scenario is not None
            else ""
        )
        top_labels = {
            "equal": top_label_for_key(distribution, "q_equal"),
            "auto": top_label_for_key(distribution, "q_auto"),
            "scenario": top_label_for_key(distribution, "q_scenario"),
        }
        per_model_top = build_per_model_top(distribution)
        return {
            "rounding_rule": rounding_rule,
            "market_var": market_var,
            "market_label": market_label,
            "corrected_labels": corrected_labels,
            "corrected_unified": corrected_unified,
            "model_top_label": model_top_label,
            "tag_equal": tag_equal,
            "tag_auto": tag_auto,
            "tag_scenario": tag_scenario,
            "top_labels": top_labels,
            "per_model_top": per_model_top,
        }

    def bucket_tags_for_label(label: str, context: Dict[str, Any]) -> Tuple[List[str], List[str]]:
        tags: List[str] = []
        model_tags: List[str] = []
        clean_label = str(label or "")
        if not clean_label:
            return tags, model_tags
        market_label = context.get("market_label") or ""
        if market_label and clean_label == market_label:
            tags.append("市场盘口")
        corrected_unified = context.get("corrected_unified") or ""
        corrected_labels = context.get("corrected_labels") or {}
        if corrected_unified and clean_label == corrected_unified:
            tags.append("校正后最高概率")
        if not corrected_unified:
            if corrected_labels.get("equal") and clean_label == corrected_labels.get("equal"):
                tags.append("校正后等权最高概率")
            if corrected_labels.get("auto") and clean_label == corrected_labels.get("auto"):
                tags.append("校正后动态最高概率")
            if corrected_labels.get("scenario") and clean_label == corrected_labels.get("scenario"):
                tags.append("校正后场景最高概率")
        model_top_label = context.get("model_top_label") or ""
        if model_top_label and clean_label == model_top_label:
            tags.append("最高概率")
        if context.get("tag_equal") and clean_label == context.get("tag_equal"):
            tags.append("等权落桶")
        if context.get("tag_auto") and clean_label == context.get("tag_auto"):
            tags.append("动态落桶")
        if context.get("tag_scenario") and clean_label == context.get("tag_scenario"):
            tags.append("场景落桶")
        top_labels = context.get("top_labels") or {}
        if top_labels.get("equal") and clean_label == top_labels.get("equal"):
            tags.append("等权最高概率")
        if top_labels.get("auto") and clean_label == top_labels.get("auto"):
            tags.append("动态最高概率")
        if top_labels.get("scenario") and clean_label == top_labels.get("scenario"):
            tags.append("场景最高概率")
        model_tag_map = {
            "gfs_seamless": "GFS",
            "ecmwf_ifs025": "ECMWF",
            "icon_seamless": "ICON",
            "nws_forecast": "NWS",
        }
        per_model_top = context.get("per_model_top") or {}
        for model, info in per_model_top.items():
            if not info or info.get("label") != clean_label:
                continue
            tag = model_tag_map.get(model)
            if tag:
                tags.append(tag)
                model_tags.append(tag)
        return tags, model_tags

    def market_tags_for_row(dist_row: Optional[Dict[str, Any]], is_yes: bool) -> List[str]:
        if not dist_row:
            return []
        tags: List[str] = []
        spread_key = "spread" if is_yes else "spread_no"
        spread = to_float(dist_row.get(spread_key))
        if spread is not None and math.isfinite(spread):
            if spread <= 0.08:
                tags.append("价差紧")
            elif spread <= 0.15:
                tags.append("价差中")
            else:
                tags.append("价差宽")
        depth_ok_key = "entry_depth_ok_yes" if is_yes else "entry_depth_ok_no"
        depth_ok = dist_row.get(depth_ok_key)
        if depth_ok is True:
            tags.append("深度达标")
        elif depth_ok is False:
            tags.append("深度不足")
        buffer_ok_key = "depth_buffer_ok_yes" if is_yes else "depth_buffer_ok_no"
        buffer_ok = dist_row.get(buffer_ok_key)
        if buffer_ok is True:
            tags.append("缓冲达标")
        elif buffer_ok is False:
            tags.append("缓冲不足")
        depth_ratio_key = "depth_ratio_yes" if is_yes else "depth_ratio_no"
        depth_ratio = to_float(dist_row.get(depth_ratio_key))
        if depth_ratio is not None and math.isfinite(depth_ratio):
            if depth_ratio >= 2:
                tags.append("深度充足")
            elif depth_ratio >= 1:
                tags.append("深度一般")
            else:
                tags.append("深度偏弱")
        bid_depth_key = "bid_depth_topN" if is_yes else "bid_depth_topN_no"
        ask_depth_key = "ask_depth_topN" if is_yes else "ask_depth_topN_no"
        bid_depth = to_float(dist_row.get(bid_depth_key))
        ask_depth = to_float(dist_row.get(ask_depth_key))
        if bid_depth is not None and ask_depth is not None and math.isfinite(bid_depth) and math.isfinite(ask_depth):
            if bid_depth >= ask_depth * 1.5:
                tags.append("买盘更强")
            elif ask_depth >= bid_depth * 1.5:
                tags.append("卖盘更强")
            else:
                tags.append("买卖均衡")
        best_ask_key = "best_ask" if is_yes else "best_ask_no"
        prev_ask_key = "prev_best_ask" if is_yes else "prev_best_ask_no"
        best_ask = to_float(dist_row.get(best_ask_key))
        prev_ask = to_float(dist_row.get(prev_ask_key))
        if best_ask is not None and prev_ask is not None and math.isfinite(best_ask) and math.isfinite(prev_ask):
            delta = best_ask - prev_ask
            if abs(delta) >= 0.01:
                tags.append("盘口上移" if delta > 0 else "盘口下移")
        return tags

    def apply_calibration(cand: Dict[str, Any], is_yes: bool, actual_label: str) -> None:
        if not cand:
            return
        edge_val = to_float(cand.get("edge"))
        if edge_val is None or not math.isfinite(edge_val) or edge_val <= 0:
            return
        label = str(cand.get("label") or "")
        q_val = to_float(cand.get("q"))
        ask_val = to_float(cand.get("ask"))
        if q_val is None or ask_val is None:
            return
        actual = 1.0 if label == actual_label else 0.0
        if not is_yes:
            actual = 0.0 if label == actual_label else 1.0
        pred_edge = (q_val - ask_val) * 100.0
        if pred_edge <= 0:
            return
        real_edge = (actual - ask_val) * 100.0
        bias = (actual - q_val) * 100.0
        bin_index = None
        for idx, (low, high) in enumerate(calibration_bins):
            if pred_edge >= low and (pred_edge < high or (idx == len(calibration_bins) - 1 and pred_edge >= low)):
                bin_index = idx
                break
        if bin_index is None:
            return
        entry = calibration_rows[bin_index]
        entry["count"] += 1
        entry["hit"] += 1 if actual > 0.5 else 0
        entry["pred_sum"] += pred_edge
        entry["real_sum"] += real_edge
        entry["bias_sum"] += bias

    def row_sort_key(entry: Dict[str, Any]) -> Tuple[str, str]:
        if include_orders:
            return (str(entry.get("trade_time") or ""), str(entry.get("created_at") or ""))
        return (str(entry.get("created_at") or ""), "")

    for rows_for_event in event_groups.values():
        if not rows_for_event:
            continue
        row = max(rows_for_event, key=row_sort_key)
        order_row = None
        if include_orders:
            order_rows = [
                r
                for r in rows_for_event
                if str(r.get("order_action") or "").lower() == "entry"
            ]
            order_row = max(order_rows, key=row_sort_key) if order_rows else None
            if order_row is not None:
                order_entry_total += 1
        payload = safe_json_loads(row["payload_json"])
        distribution = normalize_distribution_rows(payload.get("rows") or [])
        if not distribution:
            excluded["missing_distribution"] += 1
            continue
        actual_label = actual_bucket_label(row, distribution)
        if not actual_label:
            excluded["missing_actual_label"] += 1
            continue
        total_events += 1
        tag_context = build_tag_context(distribution, row)
        all_yes: List[Dict[str, Any]] = []
        all_no: List[Dict[str, Any]] = []
        all_candidates: List[Tuple[Dict[str, Any], bool]] = []
        has_yes_q = False
        has_yes_ask = False
        has_no_q = False
        has_no_ask = False
        for dist_row in distribution:
            label = str(dist_row.get("outcome") or "")
            if not label:
                continue
            q_yes = to_float(dist_row.get("q_entry"))
            if q_yes is None:
                q_yes = to_float(dist_row.get("q_calibrated"))
            if q_yes is None:
                q_yes = to_float(dist_row.get("q_raw"))
            if q_yes is None:
                q_yes = to_float(dist_row.get("q_round"))
            ask = to_float(dist_row.get("best_ask"))
            if q_yes is not None and math.isfinite(q_yes):
                has_yes_q = True
            if ask is not None and math.isfinite(ask):
                has_yes_ask = True
            if q_yes is not None and ask is not None:
                edge_val = q_yes - ask
                cand_yes = {"label": label, "q": q_yes, "ask": ask, "edge": edge_val}
                all_yes.append(cand_yes)
                all_candidates.append((cand_yes, True))
            q_no = to_float(dist_row.get("q_entry_no"))
            if q_no is None:
                q_no = to_float(dist_row.get("q_calibrated_no"))
            if q_no is None:
                q_no = to_float(dist_row.get("q_raw_no"))
            if q_no is None:
                q_no = to_float(dist_row.get("q_round_no"))
            if q_no is None and q_yes is not None:
                q_no = 1.0 - q_yes
            ask_no = to_float(dist_row.get("best_ask_no"))
            if q_no is not None and math.isfinite(q_no):
                has_no_q = True
            if ask_no is not None and math.isfinite(ask_no):
                has_no_ask = True
            if q_no is not None and ask_no is not None:
                edge_val = q_no - ask_no
                cand_no = {"label": label, "q": q_no, "ask": ask_no, "edge": edge_val}
                all_no.append(cand_no)
                all_candidates.append((cand_no, False))
        if not all_candidates:
            has_any_ask = has_yes_ask or has_no_ask
            has_any_q = has_yes_q or has_no_q
            if not has_any_ask:
                excluded["missing_price"] += 1
            elif not has_any_q:
                excluded["missing_prob"] += 1
            else:
                excluded["missing_candidate"] += 1
            continue
        def _pick_best(cands: List[Dict[str, Any]]) -> Optional[Dict[str, Any]]:
            best = None
            best_edge = None
            for cand in cands:
                edge_val = to_float(cand.get("edge"))
                if edge_val is None or not math.isfinite(edge_val):
                    continue
                if best_edge is None or edge_val > best_edge:
                    best = cand
                    best_edge = edge_val
            return best

        best_yes = _pick_best(all_yes)
        best_no = _pick_best(all_no)
        apply_candidate(top_yes_entry, best_yes, True, actual_label)
        apply_candidate(top_no_entry, best_no, False, actual_label)
        best_cand = None
        best_is_yes = True
        for cand, is_yes in ((best_yes, True), (best_no, False)):
            if not cand:
                continue
            edge_val = to_float(cand.get("edge"))
            if edge_val is None or not math.isfinite(edge_val):
                continue
            if best_cand is None or edge_val > to_float(best_cand.get("edge")):
                best_cand = cand
                best_is_yes = is_yes
        if best_cand is not None:
            apply_candidate(top_entry, best_cand, best_is_yes, actual_label)

        for cand in all_yes:
            apply_candidate(yes_entry, cand, True, actual_label)
        for cand in all_no:
            apply_candidate(no_entry, cand, False, actual_label)
        has_positive = False
        for cand, is_yes in all_candidates:
            edge_val = to_float(cand.get("edge"))
            if edge_val is None or not math.isfinite(edge_val):
                continue
            if edge_val <= 0:
                continue
            has_positive = True
            effective_events += 1
            apply_candidate(best_entry, cand, is_yes, actual_label)
            apply_calibration(cand, is_yes, actual_label)
            metrics = compute_edge_metrics(cand, is_yes, actual_label)
            if metrics:
                pred_edge, real_edge, bias, hit, q_val, ask_val, label, ratio, roi = metrics
                feature_metrics = (pred_edge, real_edge, bias, hit, ratio, roi)
                record_feature(feature_maps["label"], label or "unknown", feature_metrics)
                record_feature(feature_maps["side"], "YES" if is_yes else "NO", feature_metrics)
                top_label, _ = top_bucket_from_distribution(distribution, "q_round")
                if top_label:
                    record_feature(feature_maps["top_label"], top_label, feature_metrics)
                else:
                    record_feature(feature_maps["top_label"], "unknown", feature_metrics)
                if not top_label:
                    match_key = "unknown"
                else:
                    match_key = "match" if top_label == label else "diff"
                record_feature(feature_maps["match_top"], match_key, feature_metrics)
                ask_bands = [
                    (0.0, 0.2, "0-20%"),
                    (0.2, 0.4, "20-40%"),
                    (0.4, 0.6, "40-60%"),
                    (0.6, 0.8, "60-80%"),
                    (0.8, 1.01, "80-100%"),
                ]
                q_bands = [
                    (0.0, 0.2, "0-20%"),
                    (0.2, 0.4, "20-40%"),
                    (0.4, 0.6, "40-60%"),
                    (0.6, 0.8, "60-80%"),
                    (0.8, 1.01, "80-100%"),
                ]
                edge_bands = [
                    (0.0, 2.0, "0-2%"),
                    (2.0, 5.0, "2-5%"),
                    (5.0, 10.0, "5-10%"),
                    (10.0, 20.0, "10-20%"),
                    (20.0, 40.0, "20-40%"),
                    (40.0, 100.0, "40-100%"),
                ]
                roi_bands = [
                    (float("-inf"), -0.5, "≤-50%"),
                    (-0.5, 0.0, "-50-0%"),
                    (0.0, 0.25, "0-25%"),
                    (0.25, 0.5, "25-50%"),
                    (0.5, 1.0, "50-100%"),
                    (1.0, 2.0, "100-200%"),
                    (2.0, float("inf"), "≥200%"),
                ]
                ratio_bands = [
                    (float("-inf"), 0.0, "<0"),
                    (0.0, 0.25, "0-0.25"),
                    (0.25, 0.5, "0.25-0.5"),
                    (0.5, 0.8, "0.5-0.8"),
                    (0.8, 1.2, "0.8-1.2"),
                    (1.2, 2.0, "1.2-2.0"),
                    (2.0, float("inf"), "≥2.0"),
                ]
                bias_key = "positive" if bias > 0 else ("negative" if bias < 0 else "zero")
                record_feature(feature_maps["ask_band"], band_label(ask_val, ask_bands), feature_metrics)
                record_feature(feature_maps["q_band"], band_label(q_val, q_bands), feature_metrics)
                record_feature(feature_maps["edge_band"], band_label(pred_edge, edge_bands), feature_metrics)
                record_feature(feature_maps["roi_band"], band_label(roi, roi_bands), feature_metrics)
                record_feature(feature_maps["confidence_band"], band_label(ratio, ratio_bands), feature_metrics)
                record_feature(feature_maps["bias_sign"], bias_key, feature_metrics)
                tag_list, model_tags = bucket_tags_for_label(label, tag_context)
                for tag in tag_list:
                    record_feature(feature_maps["bucket_tag"], tag, feature_metrics)
                for tag in set(model_tags):
                    record_feature(feature_maps["model_tag"], tag, feature_metrics)
                dist_row = None
                for drow in distribution:
                    if str(drow.get("outcome") or "") == label:
                        dist_row = drow
                        break
                for tag in market_tags_for_row(dist_row, is_yes):
                    record_feature(feature_maps["market_tag"], tag, feature_metrics)
                update_roi_stats(roi_stats, roi)
                side_key = "YES" if is_yes else "NO"
                update_roi_stats(side_stats[side_key], roi)
                if str(tag_context.get("market_var") or "").startswith("temperature"):
                    try:
                        spec = parse_outcome_label(label)
                    except ValueError:
                        spec = None
                    if spec:
                        if spec.kind == "range":
                            record_feature(feature_maps["temp_range"], label, feature_metrics)
                        elif spec.kind == "eq":
                            record_feature(feature_maps["temp_point"], label, feature_metrics)
                        else:
                            record_feature(feature_maps["temp_open"], label, feature_metrics)
        if not has_positive:
            excluded["non_positive_edge"] += 1
        if order_row is not None:
            order_label = str(order_row.get("order_outcome") or "")
            order_side = str(order_row.get("order_side") or "").upper()
            if order_label and order_side in {"YES", "NO"}:
                dist_row = None
                for drow in distribution:
                    if str(drow.get("outcome") or "") == order_label:
                        dist_row = drow
                        break
                if dist_row:
                    q_round = to_float(dist_row.get("q_round"))
                    q_round_no = to_float(dist_row.get("q_round_no"))
                    if q_round_no is None and q_round is not None:
                        q_round_no = 1.0 - q_round
                    ask_yes = to_float(dist_row.get("best_ask"))
                    ask_no = to_float(dist_row.get("best_ask_no"))
                    order_price = to_float(order_row.get("order_price"))
                    is_yes = order_side == "YES"
                    q_val = q_round if is_yes else q_round_no
                    ask_val = order_price if order_price is not None else (ask_yes if is_yes else ask_no)
                    order_metrics = compute_order_metrics(q_val, ask_val, order_label, is_yes, actual_label)
                    if order_metrics:
                        order_entry_covered += 1
                        pred_edge, real_edge, bias, hit, ratio, roi = order_metrics
                        order_feature_metrics = (pred_edge, real_edge, bias, hit, ratio, roi)
                        record_feature(order_feature_maps["label"], order_label, order_feature_metrics)
                        record_feature(order_feature_maps["side"], order_side, order_feature_metrics)
                        top_label, _ = top_bucket_from_distribution(distribution, "q_round")
                        if not top_label:
                            match_key = "unknown"
                        else:
                            match_key = "match" if top_label == order_label else "diff"
                        record_feature(order_feature_maps["match_top"], match_key, order_feature_metrics)
                        ask_bands = [
                            (0.0, 0.2, "0-20%"),
                            (0.2, 0.4, "20-40%"),
                            (0.4, 0.6, "40-60%"),
                            (0.6, 0.8, "60-80%"),
                            (0.8, 1.01, "80-100%"),
                        ]
                        q_bands = [
                            (0.0, 0.2, "0-20%"),
                            (0.2, 0.4, "20-40%"),
                            (0.4, 0.6, "40-60%"),
                            (0.6, 0.8, "60-80%"),
                            (0.8, 1.01, "80-100%"),
                        ]
                        edge_bands = [
                            (float("-inf"), 0.0, "<0%"),
                            (0.0, 2.0, "0-2%"),
                            (2.0, 5.0, "2-5%"),
                            (5.0, 10.0, "5-10%"),
                            (10.0, 20.0, "10-20%"),
                            (20.0, 40.0, "20-40%"),
                            (40.0, 100.0, "40-100%"),
                            (100.0, float("inf"), "≥100%"),
                        ]
                        roi_bands = [
                            (float("-inf"), -0.5, "≤-50%"),
                            (-0.5, 0.0, "-50-0%"),
                            (0.0, 0.25, "0-25%"),
                            (0.25, 0.5, "25-50%"),
                            (0.5, 1.0, "50-100%"),
                            (1.0, 2.0, "100-200%"),
                            (2.0, float("inf"), "≥200%"),
                        ]
                        ratio_bands = [
                            (float("-inf"), 0.0, "<0"),
                            (0.0, 0.25, "0-0.25"),
                            (0.25, 0.5, "0.25-0.5"),
                            (0.5, 0.8, "0.5-0.8"),
                            (0.8, 1.2, "0.8-1.2"),
                            (1.2, 2.0, "1.2-2.0"),
                            (2.0, float("inf"), "≥2.0"),
                        ]
                        bias_key = "positive" if bias > 0 else ("negative" if bias < 0 else "zero")
                        record_feature(order_feature_maps["ask_band"], band_label(ask_val, ask_bands), order_feature_metrics)
                        record_feature(order_feature_maps["q_band"], band_label(q_val, q_bands), order_feature_metrics)
                        record_feature(order_feature_maps["edge_band"], band_label(pred_edge, edge_bands), order_feature_metrics)
                        record_feature(order_feature_maps["roi_band"], band_label(roi, roi_bands), order_feature_metrics)
                        record_feature(order_feature_maps["confidence_band"], band_label(ratio, ratio_bands), order_feature_metrics)
                        record_feature(order_feature_maps["bias_sign"], bias_key, order_feature_metrics)
                        tag_list, model_tags = bucket_tags_for_label(order_label, tag_context)
                        for tag in tag_list:
                            record_feature(order_feature_maps["bucket_tag"], tag, order_feature_metrics)
                        for tag in set(model_tags):
                            record_feature(order_feature_maps["model_tag"], tag, order_feature_metrics)
                        for tag in market_tags_for_row(dist_row, is_yes):
                            record_feature(order_feature_maps["market_tag"], tag, order_feature_metrics)
                        update_roi_stats(order_roi_stats, roi)
                        if order_side in order_side_stats:
                            update_roi_stats(order_side_stats[order_side], roi)
                        if str(tag_context.get("market_var") or "").startswith("temperature"):
                            try:
                                spec = parse_outcome_label(order_label)
                            except ValueError:
                                spec = None
                            if spec:
                                if spec.kind == "range":
                                    record_feature(order_feature_maps["temp_range"], order_label, order_feature_metrics)
                                elif spec.kind == "eq":
                                    record_feature(order_feature_maps["temp_point"], order_label, order_feature_metrics)
                                else:
                                    record_feature(order_feature_maps["temp_open"], order_label, order_feature_metrics)

    def finalize(entry: Dict[str, Any]) -> Dict[str, Any]:
        count = int(entry["count"] or 0)
        if count <= 0:
            return {
                "count": 0,
                "hit": 0,
                "win_rate": None,
                "pred_mean": None,
                "real_mean": None,
                "bias_mean": None,
                "bias_median": None,
            }
        pred_mean = entry["pred_sum"] / count
        real_mean = entry["real_sum"] / count
        bias_mean = entry["bias_sum"] / count
        bias_median = median([float(x) for x in entry["bias_list"] if x is not None])
        win_rate = entry["hit"] / count
        return {
            "count": count,
            "hit": int(entry["hit"] or 0),
            "win_rate": win_rate,
            "pred_mean": pred_mean,
            "real_mean": real_mean,
            "bias_mean": bias_mean,
            "bias_median": bias_median,
        }

    def finalize_calibration() -> List[Dict[str, Any]]:
        out: List[Dict[str, Any]] = []
        for (low, high), entry in zip(calibration_bins, calibration_rows):
            count = int(entry["count"] or 0)
            if count <= 0:
                out.append(
                    {
                        "range": [low, high],
                        "count": 0,
                        "hit": 0,
                        "win_rate": None,
                        "pred_mean": None,
                        "real_mean": None,
                        "bias_mean": None,
                        "ratio": None,
                    }
                )
                continue
            pred_mean = entry["pred_sum"] / count
            real_mean = entry["real_sum"] / count
            bias_mean = entry["bias_sum"] / count
            ratio = (real_mean / pred_mean) if pred_mean > 0 else None
            win_rate = entry["hit"] / count
            out.append(
                {
                    "range": [low, high],
                    "count": count,
                    "hit": int(entry["hit"] or 0),
                    "win_rate": win_rate,
                    "pred_mean": pred_mean,
                    "real_mean": real_mean,
                    "bias_mean": bias_mean,
                    "ratio": ratio,
                }
            )
        return out

    def finalize_feature_map(feature_map: Dict[str, Dict[str, Any]]) -> List[Dict[str, Any]]:
        out: List[Dict[str, Any]] = []
        for key, entry in feature_map.items():
            count = int(entry["count"] or 0)
            if count <= 0:
                continue
            pred_mean = entry["pred_sum"] / count
            real_mean = entry["real_sum"] / count
            bias_mean = entry["bias_sum"] / count
            win_rate = entry["hit"] / count
            ratio_mean = (entry["ratio_sum"] / entry["ratio_count"]) if entry["ratio_count"] else None
            roi_mean = (entry["roi_sum"] / entry["roi_count"]) if entry["roi_count"] else None
            out.append(
                {
                    "key": key,
                    "count": count,
                    "hit": int(entry["hit"] or 0),
                    "win_rate": win_rate,
                    "pred_mean": pred_mean,
                    "real_mean": real_mean,
                    "bias_mean": bias_mean,
                    "ratio_mean": ratio_mean,
                    "roi_mean": roi_mean,
                }
            )
        out.sort(key=lambda row: (-int(row.get("count") or 0), str(row.get("key") or "")))
        return out

    payload = {
        "ok": True,
        "basis": basis,
        "days": days,
        "events": len(unique_events),
        "settled_events": total_settled,
        "effective_events": effective_events,
        "excluded": excluded,
        "yes": finalize(yes_entry),
        "no": finalize(no_entry),
        "best": finalize(best_entry),
        "top": finalize(top_entry),
        "top_yes": finalize(top_yes_entry),
        "top_no": finalize(top_no_entry),
        "calibration": {"bins": finalize_calibration()},
        "features": {
            "by_label": finalize_feature_map(feature_maps["label"]),
            "by_top_label": finalize_feature_map(feature_maps["top_label"]),
            "by_match_top": finalize_feature_map(feature_maps["match_top"]),
            "by_side": finalize_feature_map(feature_maps["side"]),
            "by_ask_band": finalize_feature_map(feature_maps["ask_band"]),
            "by_q_band": finalize_feature_map(feature_maps["q_band"]),
            "by_edge_band": finalize_feature_map(feature_maps["edge_band"]),
            "by_confidence_band": finalize_feature_map(feature_maps["confidence_band"]),
            "by_roi_band": finalize_feature_map(feature_maps["roi_band"]),
            "by_bias_sign": finalize_feature_map(feature_maps["bias_sign"]),
            "by_bucket_tag": finalize_feature_map(feature_maps["bucket_tag"]),
            "by_model_tag": finalize_feature_map(feature_maps["model_tag"]),
            "by_market_tag": finalize_feature_map(feature_maps["market_tag"]),
            "by_temp_point": finalize_feature_map(feature_maps["temp_point"]),
            "by_temp_range": finalize_feature_map(feature_maps["temp_range"]),
            "by_temp_open": finalize_feature_map(feature_maps["temp_open"]),
        },
        "roi_stats": finalize_roi_stats(roi_stats),
        "side_stats": finalize_side_stats(side_stats),
        "generated_at": now_text(),
    }
    if include_orders and order_feature_maps is not None:
        payload["order_features"] = {
            "by_label": finalize_feature_map(order_feature_maps["label"]),
            "by_side": finalize_feature_map(order_feature_maps["side"]),
            "by_match_top": finalize_feature_map(order_feature_maps["match_top"]),
            "by_ask_band": finalize_feature_map(order_feature_maps["ask_band"]),
            "by_q_band": finalize_feature_map(order_feature_maps["q_band"]),
            "by_edge_band": finalize_feature_map(order_feature_maps["edge_band"]),
            "by_confidence_band": finalize_feature_map(order_feature_maps["confidence_band"]),
            "by_roi_band": finalize_feature_map(order_feature_maps["roi_band"]),
            "by_bias_sign": finalize_feature_map(order_feature_maps["bias_sign"]),
            "by_bucket_tag": finalize_feature_map(order_feature_maps["bucket_tag"]),
            "by_model_tag": finalize_feature_map(order_feature_maps["model_tag"]),
            "by_market_tag": finalize_feature_map(order_feature_maps["market_tag"]),
            "by_temp_point": finalize_feature_map(order_feature_maps["temp_point"]),
            "by_temp_range": finalize_feature_map(order_feature_maps["temp_range"]),
            "by_temp_open": finalize_feature_map(order_feature_maps["temp_open"]),
        }
        payload["order_roi_stats"] = finalize_roi_stats(order_roi_stats)
        payload["order_side_stats"] = finalize_side_stats(order_side_stats)
        payload["order_coverage"] = {
            "total": order_entry_total,
            "covered": order_entry_covered,
            "uncovered": max(0, order_entry_total - order_entry_covered),
            "rate": (order_entry_covered / order_entry_total) if order_entry_total else None,
        }
    return payload


def edge_bias_stats(days: int) -> Dict[str, Any]:
    now_ts = time.time()
    # Reuse a fresh completed DB run when available.
    latest_ok: Optional[Dict[str, Any]] = None
    latest_any: Optional[Dict[str, Any]] = None
    try:
        if DB_PATH.exists():
            with open_db() as conn:
                latest_ok = _load_latest_edge_bias_run_from_db(conn, int(days), require_ok=True)
                latest_any = _load_latest_edge_bias_run_from_db(conn, int(days), require_ok=False)
            if latest_ok:
                ok_at = str(latest_ok.get("created_at") or "")
                ok_dt = parse_iso_ts(ok_at)
                age = (now_ts - ok_dt.timestamp()) if ok_dt else None
                if age is not None and age <= float(EDGE_BIAS_CACHE_MAX_AGE_SEC):
                    payload = dict(latest_ok.get("payload") or {})
                    payload["cached"] = True
                    payload["last_ok_at"] = ok_at
                    payload["last_error"] = ""
                    return payload
    except Exception:
        latest_ok = None
        latest_any = None

    # Otherwise compute, store into DB, then return.
    error_text = ""
    try:
        payload = compute_edge_bias_stats(int(days))
        ok = bool(payload.get("ok"))
        error_text = str(payload.get("error") or "")
        if not ok and not error_text:
            error_text = "no_data"
        if not DB_PATH.exists():
            # Still return computed payload even if db doesn't exist (e.g. first run).
            payload["cached"] = False
            payload["last_ok_at"] = ""
            payload["last_error"] = error_text or ("db_missing" if not DB_PATH.exists() else "")
            return payload
        with open_db() as conn:
            _save_edge_bias_run_to_db(conn, int(days), dict(payload), ok=ok, error=error_text)
            conn.commit()
        payload["cached"] = False
        payload["last_ok_at"] = now_text() if ok else (str(latest_ok.get("created_at") or "") if latest_ok else "")
        payload["last_error"] = "" if ok else (error_text or "no_data")
        return payload
    except Exception as exc:
        error_text = f"{type(exc).__name__}: {exc}"

    # Fallback: return latest ok payload (stale), but surface error.
    if latest_ok:
        payload = dict(latest_ok.get("payload") or {})
        payload["cached"] = True
        payload["last_ok_at"] = str(latest_ok.get("created_at") or "")
        payload["last_error"] = error_text
        return payload
    return {"ok": False, "days": int(days), "events": 0, "generated_at": now_text(), "cached": False, "last_ok_at": "", "last_error": error_text}


def _save_feedback_snapshot_to_db(
    conn: sqlite3.Connection,
    *,
    kind: str,
    days: int,
    end_date: str,
    payload: Dict[str, Any],
    ok: bool = True,
    error: str = "",
) -> None:
    _ensure_feedback_tables(conn)
    cur = conn.cursor()
    cur.execute(
        """
        INSERT INTO feedback_snapshots(kind, days, end_date, payload_json, ok, error, created_at)
        VALUES (?, ?, ?, ?, ?, ?, ?)
        """,
        (
            str(kind or ""),
            int(days),
            str(end_date or ""),
            json.dumps(payload, ensure_ascii=True),
            1 if ok else 0,
            str(error or ""),
            now_text(),
        ),
    )


def materialize_forecast_source_accuracy_report(conn: sqlite3.Connection) -> Dict[str, Any]:
    """Copy the daily research report into archive SSOT without changing any model.

    This is deliberately a feedback-snapshot materialization, not a runtime
    source-weight activation.  The UI subsequently reads archive.db only.
    """
    try:
        report = json.loads(FORECAST_SOURCE_ACCURACY_REPORT_PATH.read_text(encoding="utf-8"))
        if not isinstance(report, dict):
            raise ValueError("forecast_source_accuracy_report_not_mapping")
        if report.get("schema") != "forecast_source_accuracy_report_v1":
            raise ValueError("forecast_source_accuracy_report_schema_invalid")
        if report.get("production_weight_input") is not False:
            raise ValueError("forecast_source_accuracy_report_must_be_research_only")
        report_sha256 = str(report.get("report_sha256") or "")
        if not re.fullmatch(r"[0-9a-f]{64}", report_sha256):
            raise ValueError("forecast_source_accuracy_report_sha_missing")
        try:
            official_formal = json.loads(OFFICIAL_FORECAST_SOURCE_ACCURACY_REPORT_PATH.read_text(encoding="utf-8"))
        except (OSError, ValueError):
            official_formal = {
                "schema": "official_forecast_source_accuracy_report_v1",
                "state": "pending_formal_samples",
                "research_only": True,
                "production_weight_input": False,
                "rows": [],
                "na_reason": "official_formal_accuracy_report_not_materialized",
            }
        if not isinstance(official_formal, dict) or official_formal.get("schema") != "official_forecast_source_accuracy_report_v1":
            raise ValueError("official_forecast_source_accuracy_report_schema_invalid")
        if official_formal.get("production_weight_input") is not False:
            raise ValueError("official_forecast_source_accuracy_report_must_be_research_only")
        formal_sha256 = str(official_formal.get("report_sha256") or "")
        materialization_signature = hashlib.sha256(
            json.dumps({"legacy_report_sha256": report_sha256, "official_formal_report_sha256": formal_sha256, "official_formal_state": official_formal.get("state")}, sort_keys=True).encode("utf-8")
        ).hexdigest()
        latest = _load_latest_feedback_snapshot_from_db(
            conn,
            kind=FORECAST_SOURCE_ACCURACY_SNAPSHOT_KIND,
            days=0,
        )
        if isinstance(latest, dict) and str(latest.get("materialization_signature") or "") == materialization_signature:
            return {
                **report,
                "official_formal": official_formal,
                "materialization_signature": materialization_signature,
                "materialized": True,
                "materialized_kind": FORECAST_SOURCE_ACCURACY_SNAPSHOT_KIND,
                "materialized_write_skipped": True,
                "materialized_write_skip_reason": "unchanged_report_sha256",
                "materialized_existing_snapshot_id": int((latest.get("_meta") or {}).get("id") or 0),
            }
        report["materialized"] = True
        report["materialized_kind"] = FORECAST_SOURCE_ACCURACY_SNAPSHOT_KIND
        report["materialized_at"] = now_text()
        report["official_formal"] = official_formal
        report["materialization_signature"] = materialization_signature
        _save_feedback_snapshot_to_db(
            conn,
            kind=FORECAST_SOURCE_ACCURACY_SNAPSHOT_KIND,
            days=0,
            end_date=str(report.get("generated_at") or "")[:10],
            payload=report,
            ok=True,
            error="",
        )
        return report
    except Exception as exc:
        payload = {
            "schema": "forecast_source_accuracy_snapshot_error_v1",
            "ok": False,
            "research_only": True,
            "production_weight_input": False,
            "na_reason": "forecast_source_accuracy_report_unavailable",
            "error": f"{type(exc).__name__}: {exc}",
            "generated_at": now_text(),
            "materialized": True,
            "materialized_kind": FORECAST_SOURCE_ACCURACY_SNAPSHOT_KIND,
        }
        _save_feedback_snapshot_to_db(
            conn,
            kind=FORECAST_SOURCE_ACCURACY_SNAPSHOT_KIND,
            days=0,
            end_date="",
            payload=payload,
            ok=False,
            error=str(payload["error"]),
        )
        return payload


def materialize_joint_weak_bias_research_readiness(conn: sqlite3.Connection) -> Dict[str, Any]:
    """Copy one verified research readiness report into archive feedback SSOT.

    This is a display/status materialization only.  It cannot approve an
    artifact or alter posterior, execution, source weights, or orders.
    """

    try:
        latest_path = JOINT_WEAK_BIAS_RESEARCH_ROOT / "latest.json"
        latest = safe_json_loads(latest_path.read_text(encoding="utf-8"))
        if not isinstance(latest, dict) or latest.get("schema") != "joint_weak_bias_research_pipeline_v1":
            raise ValueError("joint_weak_bias_research_latest_pointer_invalid")
        pipeline_sha = str(latest.get("pipeline_sha256") or "")
        pipeline_contract_version = str(latest.get("pipeline_contract_version") or "")
        pipeline_contract_sha = str(latest.get("pipeline_contract_sha256") or "")
        report_path = Path(str(latest.get("report_path") or "")).expanduser().resolve()
        root = JOINT_WEAK_BIAS_RESEARCH_ROOT.resolve()
        if root not in report_path.parents:
            raise ValueError("joint_weak_bias_research_report_outside_research_root")
        report = safe_json_loads(report_path.read_text(encoding="utf-8"))
        if not isinstance(report, dict) or report.get("schema") != "joint_weak_bias_research_pipeline_v1":
            raise ValueError("joint_weak_bias_research_report_schema_invalid")
        if str(report.get("pipeline_sha256") or "") != pipeline_sha or not re.fullmatch(r"[0-9a-f]{64}", pipeline_sha):
            raise ValueError("joint_weak_bias_research_report_sha_invalid")
        if (
            pipeline_contract_version != "joint_weak_bias_research_pipeline_contract_v2"
            or str(report.get("pipeline_contract_version") or "") != pipeline_contract_version
            or str(report.get("pipeline_contract_sha256") or "") != pipeline_contract_sha
            or not re.fullmatch(r"[0-9a-f]{64}", pipeline_contract_sha)
        ):
            raise ValueError("joint_weak_bias_research_pipeline_contract_identity_invalid")
        boundary = report.get("boundary") if isinstance(report.get("boundary"), Mapping) else {}
        readiness = report.get("readiness") if isinstance(report.get("readiness"), Mapping) else {}
        if boundary.get("research_only") is not True or boundary.get("writes_posterior") is not False or boundary.get("places_orders") is not False:
            raise ValueError("joint_weak_bias_research_boundary_invalid")
        if readiness.get("schema") != "joint_weak_bias_research_readiness_v1" or readiness.get("production_weight_input") is not False:
            raise ValueError("joint_weak_bias_research_readiness_invalid")
        payload = {
            "schema": "joint_weak_bias_research_snapshot_v1",
            "research_only": True,
            "production_weight_input": False,
            "pipeline_sha256": pipeline_sha,
            "pipeline_contract_version": pipeline_contract_version,
            "pipeline_contract_sha256": pipeline_contract_sha,
            "dataset_sha256": str(report.get("dataset_sha256") or ""),
            "readiness": dict(readiness),
            "materialization_signature": hashlib.sha256(json.dumps({"pipeline_sha256": pipeline_sha, "pipeline_contract_sha256": pipeline_contract_sha, "dataset_sha256": report.get("dataset_sha256")}, sort_keys=True).encode()).hexdigest(),
        }
        latest_snapshot = _load_latest_feedback_snapshot_from_db(conn, kind=JOINT_WEAK_BIAS_RESEARCH_SNAPSHOT_KIND, days=0)
        if isinstance(latest_snapshot, dict) and str(latest_snapshot.get("materialization_signature") or "") == payload["materialization_signature"]:
            return {**payload, "materialized": True, "materialized_write_skipped": True, "materialized_write_skip_reason": "unchanged_pipeline_sha256"}
        _save_feedback_snapshot_to_db(conn, kind=JOINT_WEAK_BIAS_RESEARCH_SNAPSHOT_KIND, days=0, end_date="", payload=payload, ok=True, error="")
        return {**payload, "materialized": True, "materialized_write_skipped": False}
    except Exception as exc:
        payload = {
            "schema": "joint_weak_bias_research_snapshot_error_v1", "ok": False,
            "research_only": True, "production_weight_input": False,
            "na_reason": "joint_weak_bias_research_report_unavailable", "error": f"{type(exc).__name__}: {exc}",
        }
        _save_feedback_snapshot_to_db(conn, kind=JOINT_WEAK_BIAS_RESEARCH_SNAPSHOT_KIND, days=0, end_date="", payload=payload, ok=False, error=str(payload["error"]))
        return payload


def _load_latest_feedback_snapshot_from_db(
    conn: sqlite3.Connection,
    *,
    kind: str,
    days: int,
) -> Optional[Dict[str, Any]]:
    _ensure_feedback_tables(conn)
    cur = conn.cursor()
    cur.execute(
        """
        SELECT id, payload_json, ok, error, created_at, end_date
        FROM feedback_snapshots
        WHERE kind = ? AND days = ?
        ORDER BY created_at DESC, id DESC
        LIMIT 1
        """,
        (str(kind or ""), int(days)),
    )
    row = cur.fetchone()
    if not row:
        return None
    payload = safe_json_loads(row[1]) if row[1] else None
    if not isinstance(payload, dict):
        payload = {}
    payload["_meta"] = {
        "id": int(row[0] or 0),
        "ok": int(row[2] or 0) == 1,
        "error": str(row[3] or ""),
        "created_at": str(row[4] or ""),
        "end_date": str(row[5] or ""),
    }
    return payload


def _decorate_source_lead_day_materialized_payload(
    payload: Dict[str, Any],
    *,
    days_val: int,
    end_date_key: str,
) -> Dict[str, Any]:
    auto_update = payload.get("auto_update") if isinstance(payload.get("auto_update"), dict) else {}
    payload["auto_update"] = {
        **auto_update,
        "enabled": True,
        "policy": "feedback_loop_materialized_post_close_daily_with_read_fallback",
        "snapshot_kind": SOURCE_LEAD_DAY_HIT_RATE_SNAPSHOT_KIND,
        "snapshot_days": int(days_val),
        "write_path": "scripts/feedback_loop.py -> feedback_snapshots",
        "refresh_cadence": "post_close_daily_when_signature_changes",
        "trigger": "post_close_daily_after_new_settlement_visible",
        "manual_refresh_required": False,
    }
    payload["materialized"] = True
    payload["materialized_kind"] = SOURCE_LEAD_DAY_HIT_RATE_SNAPSHOT_KIND
    payload["materialized_at"] = now_text()
    payload["end_date"] = str(payload.get("end_date") or end_date_key)
    return payload


def _is_no_eligible_first_prediction_payload(payload: Mapping[str, Any], error: str = "") -> bool:
    reason = str(error or payload.get("na_reason") or payload.get("error") or "")
    if reason != "no_eligible_first_prediction_events":
        return False
    coverage = payload.get("coverage") if isinstance(payload.get("coverage"), Mapping) else {}
    try:
        eligible = int(coverage.get("eligible_events") or 0) if isinstance(coverage, Mapping) else 0
    except Exception:
        eligible = 0
    return eligible <= 0


def _clear_first_prediction_hit_rate_cache(scope: str, days_val: int) -> None:
    if FIRST_PREDICTION_HIT_RATE_CACHE_SEC <= 0:
        return
    cache_key = f"{scope}:{int(days_val)}"
    with _FIRST_PREDICTION_HIT_RATE_CACHE_LOCK:
        _FIRST_PREDICTION_HIT_RATE_CACHE.pop(cache_key, None)


def materialize_source_lead_day_hit_rates(
    conn: sqlite3.Connection,
    *,
    days: int = SOURCE_LEAD_DAY_HIT_RATE_SNAPSHOT_DAYS,
    end_date: str = "",
    scope: str = "chengdu_zuuu",
) -> Dict[str, Any]:
    """
    Append-only materialization for source/model D2-D0 hit-rate stats.

    This keeps /api/ui_snapshot read-only and fast: the UI can serve the latest
    feedback snapshot first, while feedback_loop only writes a new daily
    post-close snapshot after settlement facts change.
    """
    try:
        days_val = int(days)
    except Exception:
        days_val = SOURCE_LEAD_DAY_HIT_RATE_SNAPSHOT_DAYS
    if days_val < 0:
        days_val = SOURCE_LEAD_DAY_HIT_RATE_SNAPSHOT_DAYS
    end_date_key = _normalize_date_key(end_date) or _today_et_key()
    try:
        payload = dict(first_prediction_hit_rate_stats(conn, days=days_val, scope=scope))
        payload = _decorate_source_lead_day_materialized_payload(
            payload,
            days_val=days_val,
            end_date_key=end_date_key,
        )
        ok = bool(payload.get("ok"))
        error = str(payload.get("error") or payload.get("na_reason") or "")
    except Exception as exc:
        payload = {
            "ok": False,
            "version": "source_lead_day_hit_rate_v2",
            "scope": str(scope or ""),
            "days": int(days_val),
            "end_date": end_date_key,
            "generated_at": now_text(),
            "materialized": True,
            "materialized_kind": SOURCE_LEAD_DAY_HIT_RATE_SNAPSHOT_KIND,
            "materialized_at": now_text(),
            "error": f"{type(exc).__name__}: {exc}",
            "na_reason": "source_lead_day_hit_rate_materialize_failed",
            "sources": [],
            "by_source": {},
            "auto_update": {
                "enabled": True,
                "policy": "feedback_loop_materialized_post_close_daily_with_read_fallback",
                "snapshot_kind": SOURCE_LEAD_DAY_HIT_RATE_SNAPSHOT_KIND,
                "snapshot_days": int(days_val),
                "write_path": "scripts/feedback_loop.py -> feedback_snapshots",
                "refresh_cadence": "post_close_daily_when_signature_changes",
                "trigger": "post_close_daily_after_new_settlement_visible",
                "manual_refresh_required": False,
            },
        }
        ok = False
        error = str(payload.get("error") or "")
    empty_retry_count = 0
    empty_retry_errors: List[str] = []
    while (
        _is_no_eligible_first_prediction_payload(payload, error)
        and empty_retry_count < FIRST_PREDICTION_HIT_RATE_EMPTY_RETRY_MAX
    ):
        empty_retry_count += 1
        _clear_first_prediction_hit_rate_cache(scope, days_val)
        if FIRST_PREDICTION_HIT_RATE_EMPTY_RETRY_SLEEP_SEC > 0:
            time.sleep(FIRST_PREDICTION_HIT_RATE_EMPTY_RETRY_SLEEP_SEC)
        try:
            retry_payload = dict(first_prediction_hit_rate_stats(conn, days=days_val, scope=scope))
            retry_payload = _decorate_source_lead_day_materialized_payload(
                retry_payload,
                days_val=days_val,
                end_date_key=end_date_key,
            )
            retry_payload["materialized_empty_retry_count"] = int(empty_retry_count)
            payload = retry_payload
            ok = bool(payload.get("ok"))
            error = str(payload.get("error") or payload.get("na_reason") or "")
            if not _is_no_eligible_first_prediction_payload(payload, error):
                break
        except Exception as exc:
            empty_retry_errors.append(f"{type(exc).__name__}: {exc}")
            break
    if empty_retry_count:
        payload["materialized_empty_retry_count"] = int(empty_retry_count)
    if empty_retry_errors:
        payload["materialized_empty_retry_errors"] = empty_retry_errors
    try:
        latest_snapshot = _load_latest_feedback_snapshot_from_db(
            conn,
            kind=SOURCE_LEAD_DAY_HIT_RATE_SNAPSHOT_KIND,
            days=int(days_val),
        )
    except sqlite3.Error:
        latest_snapshot = None
    latest_signature = (
        latest_snapshot.get("materialization_signature")
        if isinstance(latest_snapshot, dict)
        and isinstance(latest_snapshot.get("materialization_signature"), dict)
        else None
    )
    latest_meta = latest_snapshot.get("_meta") if isinstance(latest_snapshot, dict) else {}
    latest_snapshot_ok = (
        bool(latest_meta.get("ok"))
        if isinstance(latest_meta, dict) and "ok" in latest_meta
        else bool(latest_snapshot.get("ok")) if isinstance(latest_snapshot, dict) else False
    )
    current_signature = (
        payload.get("materialization_signature")
        if isinstance(payload.get("materialization_signature"), dict)
        else None
    )
    if ok and latest_snapshot_ok and latest_signature and current_signature and latest_signature == current_signature:
        payload["materialized_write_ok"] = True
        payload["materialized_write_skipped"] = True
        payload["materialized_write_skip_reason"] = "unchanged_post_close_daily_signature"
        payload["materialized_existing_snapshot_id"] = int(latest_meta.get("id") or 0) if isinstance(latest_meta, dict) else 0
        payload["materialized_existing_snapshot_created_at"] = (
            str(latest_meta.get("created_at") or "") if isinstance(latest_meta, dict) else ""
        )
        return payload
    if not ok and str(error or payload.get("na_reason") or "") == "no_eligible_first_prediction_events":
        payload["materialized_write_ok"] = True
        payload["materialized_write_skipped"] = True
        payload["materialized_write_skip_reason"] = "no_eligible_first_prediction_events"
        payload["materialized_write_policy"] = "do_not_publish_empty_lead_day_snapshot"
        payload["materialized_existing_snapshot_id"] = int(latest_meta.get("id") or 0) if isinstance(latest_meta, dict) else 0
        payload["materialized_existing_snapshot_ok"] = bool(latest_snapshot_ok)
        payload["materialized_existing_snapshot_created_at"] = (
            str(latest_meta.get("created_at") or "") if isinstance(latest_meta, dict) else ""
        )
        return payload
    try:
        _save_feedback_snapshot_to_db(
            conn,
            kind=SOURCE_LEAD_DAY_HIT_RATE_SNAPSHOT_KIND,
            days=int(days_val),
            end_date=end_date_key,
            payload=payload,
            ok=ok,
            error=error,
        )
    except sqlite3.Error as exc:
        payload["materialized_write_ok"] = False
        payload["materialized_write_error"] = f"{type(exc).__name__}: {exc}"
        if "locked" not in str(exc).lower():
            raise
    return payload


def run_feedback_loop_once(
    *,
    edge_bias_days: int = 30,
    model_bias_days: int = 7,
    place_bias_days: int = 7,
    hit_stats_days: Any = "30,0",
    strategy_days: int = 30,
    orphan_fill_days: int = 60,
    end_date: str = "",
) -> Dict[str, Any]:
    """
    Full feedback loop SSOT:
    - Edge bias calibration (from facts/trades) -> edge_bias_calibration_* tables
    - Model bias stats (°C) -> feedback_snapshots(kind=model_bias)
    - Place bias stats (station/city, °C) -> feedback_snapshots(kind=place_bias)
    - Prediction hit stats (market/model/final vs settlement) -> feedback_snapshots(kind=prediction_hit_stats)
    - Strategy stats snapshot -> feedback_snapshots(kind=strategy_stats)
    - Orphan fill classification snapshot -> feedback_snapshots(kind=orphan_fills) + orphan_fill_classifications table
    """
    if not DB_PATH.exists():
        return {"ok": False, "error": "db_missing"}
    try:
        edge_bias_days = int(edge_bias_days)
    except Exception:
        edge_bias_days = 30
    try:
        model_bias_days = int(model_bias_days)
    except Exception:
        model_bias_days = 7
    try:
        place_bias_days = int(place_bias_days)
    except Exception:
        place_bias_days = 7
    hit_stats_days_values = _parse_hit_stats_days_values(hit_stats_days)
    try:
        strategy_days = int(strategy_days)
    except Exception:
        strategy_days = 30
    try:
        orphan_fill_days = int(orphan_fill_days)
    except Exception:
        orphan_fill_days = 60
    end_date_key = _normalize_date_key(end_date) or _today_et_key()

    edge_payload = edge_bias_stats(edge_bias_days)
    model_payload: Dict[str, Any] = {"ok": False, "error": "not_available"}
    place_payload: Dict[str, Any] = {"ok": False, "error": "not_available"}
    hit_stats_payloads: List[Dict[str, Any]] = []
    source_lead_day_payload: Dict[str, Any] = {"ok": False, "error": "not_available", "days": SOURCE_LEAD_DAY_HIT_RATE_SNAPSHOT_DAYS}
    forecast_source_accuracy_payload: Dict[str, Any] = {"ok": False, "error": "not_available"}
    joint_weak_bias_research_payload: Dict[str, Any] = {"ok": False, "error": "not_available"}
    strategy_payload: Dict[str, Any] = {"ok": False, "error": "not_available"}
    orphan_fill_payload: Dict[str, Any] = {"ok": False, "error": "not_available"}
    try:
        counterfactual_days = int(os.environ.get("PM_COUNTERFACTUAL_REVIEW_DAYS", "7") or 7)
    except Exception:
        counterfactual_days = 7
    counterfactual_payload: Dict[str, Any] = {"ok": False, "error": "not_available", "days": int(counterfactual_days)}
    exit_policy_payload: Dict[str, Any] = {"ok": False, "error": "not_available", "days": 1}
    edge_bias_gate_suggestion: Optional[Dict[str, Any]] = None

    with open_db(owner="ui.server.run_feedback_loop_once") as conn:
        def _feedback_stage_commit() -> None:
            try:
                conn.commit()
            except sqlite3.Error:
                pass

        _ensure_feedback_tables(conn)
        # Model / place bias (from settled event_runs).
        try:
            if scan_compute_model_bias_stats:
                model_bias = scan_compute_model_bias_stats(int(model_bias_days), end_date=end_date_key)
            else:
                model_bias = {}
            model_payload = {
                "ok": True,
                "days": int(model_bias_days),
                "end_date": end_date_key,
                "generated_at": now_text(),
                "bias_c": model_bias,
            }
            _save_feedback_snapshot_to_db(
                conn,
                kind="model_bias",
                days=int(model_bias_days),
                end_date=end_date_key,
                payload=model_payload,
                ok=True,
                error="",
            )
        except Exception as exc:
            model_payload = {"ok": False, "error": f"{type(exc).__name__}: {exc}", "days": int(model_bias_days), "end_date": end_date_key}
            _save_feedback_snapshot_to_db(
                conn,
                kind="model_bias",
                days=int(model_bias_days),
                end_date=end_date_key,
                payload=model_payload,
                ok=False,
                error=str(model_payload.get("error") or ""),
            )
        _feedback_stage_commit()
        try:
            if scan_compute_place_bias_stats:
                place_bias = scan_compute_place_bias_stats(int(place_bias_days), end_date=end_date_key)
            else:
                place_bias = {"station": {}, "city": {}}
            place_payload = {
                "ok": True,
                "days": int(place_bias_days),
                "end_date": end_date_key,
                "generated_at": now_text(),
                "bias_c": place_bias,
            }
            _save_feedback_snapshot_to_db(
                conn,
                kind="place_bias",
                days=int(place_bias_days),
                end_date=end_date_key,
                payload=place_payload,
                ok=True,
                error="",
            )
        except Exception as exc:
            place_payload = {"ok": False, "error": f"{type(exc).__name__}: {exc}", "days": int(place_bias_days), "end_date": end_date_key}
            _save_feedback_snapshot_to_db(
                conn,
                kind="place_bias",
                days=int(place_bias_days),
                end_date=end_date_key,
                payload=place_payload,
                ok=False,
                error=str(place_payload.get("error") or ""),
            )
        _feedback_stage_commit()
        # Market / four-model / final-weighting hit stats vs settled events.
        for hit_days in hit_stats_days_values:
            try:
                hit_stats_payload = compute_prediction_hit_stats(
                    conn,
                    int(hit_days),
                    end_date=end_date_key,
                )
                _save_feedback_snapshot_to_db(
                    conn,
                    kind="prediction_hit_stats",
                    days=int(hit_days),
                    end_date=end_date_key,
                    payload=hit_stats_payload,
                    ok=bool(hit_stats_payload.get("ok")),
                    error=str(hit_stats_payload.get("error") or hit_stats_payload.get("na_reason") or ""),
                )
            except Exception as exc:
                hit_stats_payload = {
                    "ok": False,
                    "error": f"{type(exc).__name__}: {exc}",
                    "days": int(hit_days),
                    "end_date": end_date_key,
                }
                _save_feedback_snapshot_to_db(
                    conn,
                    kind="prediction_hit_stats",
                    days=int(hit_days),
                    end_date=end_date_key,
                    payload=hit_stats_payload,
                    ok=False,
                    error=str(hit_stats_payload.get("error") or ""),
                )
            _feedback_stage_commit()
            hit_stats_payloads.append(hit_stats_payload)
        # Source/model D2-D0 hit rates vs final settled bucket.
        # Stored separately from prediction_hit_stats because model value-bucket and
        # probability-bucket modes are intentionally different evaluation targets.
        try:
            source_lead_day_payload = materialize_source_lead_day_hit_rates(
                conn,
                days=SOURCE_LEAD_DAY_HIT_RATE_SNAPSHOT_DAYS,
                end_date=end_date_key,
                scope="chengdu_zuuu",
            )
        except Exception as exc:
            source_lead_day_payload = {
                "ok": False,
                "days": SOURCE_LEAD_DAY_HIT_RATE_SNAPSHOT_DAYS,
                "end_date": end_date_key,
                "error": f"{type(exc).__name__}: {exc}",
                "na_reason": "source_lead_day_hit_rate_materialize_failed",
            }
        try:
            forecast_source_accuracy_payload = materialize_forecast_source_accuracy_report(conn)
        except Exception as exc:
            forecast_source_accuracy_payload = {
                "ok": False,
                "research_only": True,
                "production_weight_input": False,
                "na_reason": "forecast_source_accuracy_materialize_failed",
                "error": f"{type(exc).__name__}: {exc}",
            }
        try:
            joint_weak_bias_research_payload = materialize_joint_weak_bias_research_readiness(conn)
        except Exception as exc:
            joint_weak_bias_research_payload = {
                "ok": False,
                "research_only": True,
                "production_weight_input": False,
                "na_reason": "joint_weak_bias_research_materialize_failed",
                "error": f"{type(exc).__name__}: {exc}",
            }
        # Commit the lightweight bias/hit snapshots before heavier strategy/orphan work.
        # This keeps the background hit-rate panel fresh even if later feedback stages time out.
        try:
            conn.commit()
        except sqlite3.Error:
            pass
        # Strategy stats snapshot (realized + entry-quality merge).
        try:
            stats = compute_strategy_stats(conn, int(strategy_days))
            try:
                quality = compute_strategy_entry_quality(conn, int(strategy_days))
                if isinstance(quality, dict):
                    for key, q in quality.items():
                        k = str(key or "").strip().lower()
                        if k and isinstance(q, dict) and k in stats and isinstance(stats.get(k), dict):
                            stats[k].update(q)
            except Exception:
                pass
            strategy_payload = {
                "ok": True,
                "days": int(strategy_days),
                "end_date": end_date_key,
                "generated_at": now_text(),
                "strategy_stats": stats,
            }
            _save_feedback_snapshot_to_db(
                conn,
                kind="strategy_stats",
                days=int(strategy_days),
                end_date=end_date_key,
                payload=strategy_payload,
                ok=True,
                error="",
            )
        except Exception as exc:
            strategy_payload = {"ok": False, "error": f"{type(exc).__name__}: {exc}", "days": int(strategy_days), "end_date": end_date_key}
            _save_feedback_snapshot_to_db(
                conn,
                kind="strategy_stats",
                days=int(strategy_days),
                end_date=end_date_key,
                payload=strategy_payload,
                ok=False,
                error=str(strategy_payload.get("error") or ""),
            )
        _feedback_stage_commit()
        # Orphan fills (fills missing auto_orders provenance).
        try:
            orphan_days = int(orphan_fill_days or 60)
            orphan_fill_payload = compute_orphan_fill_stats(
                conn,
                orphan_days,
                max_rows=400,
                writeback=True,
            )
            orphan_fill_payload.update({"end_date": end_date_key})
            _save_feedback_snapshot_to_db(
                conn,
                kind="orphan_fills",
                days=int(orphan_days),
                end_date=end_date_key,
                payload=orphan_fill_payload,
                ok=bool(orphan_fill_payload.get("ok")),
                error=str(orphan_fill_payload.get("error") or ""),
            )
        except Exception as exc:
            orphan_fill_payload = {"ok": False, "error": f"{type(exc).__name__}: {exc}", "days": int(orphan_fill_days or 60), "end_date": end_date_key}
            _save_feedback_snapshot_to_db(
                conn,
                kind="orphan_fills",
                days=int(orphan_fill_days or 60),
                end_date=end_date_key,
                payload=orphan_fill_payload,
                ok=False,
                error=str(orphan_fill_payload.get("error") or ""),
            )
        _feedback_stage_commit()
        # Auto-optimizer (conservative): propose edge-bias confidence threshold from calibration bins.
        try:
            if edge_payload and edge_payload.get("ok"):
                edge_bias_gate_suggestion = suggest_edge_bias_gate_from_payload(
                    dict(edge_payload),
                    days=int(edge_bias_days),
                )
                if isinstance(edge_bias_gate_suggestion, dict) and edge_bias_gate_suggestion.get("ok"):
                    _save_feedback_snapshot_to_db(
                        conn,
                        kind="edge_bias_gate_suggestion",
                        days=int(edge_bias_days),
                        end_date=end_date_key,
                        payload=edge_bias_gate_suggestion,
                        ok=True,
                        error="",
                    )
        except Exception:
            edge_bias_gate_suggestion = None
        _feedback_stage_commit()
        try:
            counterfactual_payload = _load_latest_feedback_snapshot_from_db(
                conn,
                kind="entry_counterfactual_review",
                days=int(counterfactual_days),
            ) or {
                "ok": False,
                "na_reason": "missing_snapshot",
                "days": int(counterfactual_days),
            }
        except Exception as exc:
            counterfactual_payload = {
                "ok": False,
                "error": f"{type(exc).__name__}: {exc}",
                "days": int(counterfactual_days),
            }
        try:
            exit_policy_payload = _load_latest_feedback_snapshot_from_db(
                conn,
                kind="exit_policy_audit",
                days=1,
            ) or {
                "ok": False,
                "na_reason": "missing_snapshot",
                "days": 1,
            }
        except Exception as exc:
            exit_policy_payload = {
                "ok": False,
                "error": f"{type(exc).__name__}: {exc}",
                "days": 1,
            }
        conn.commit()
    return {
        "ok": True,
        "generated_at": now_text(),
        "end_date": end_date_key,
        "edge_bias": {"ok": bool(edge_payload.get("ok")), "days": int(edge_bias_days), "last_ok_at": edge_payload.get("last_ok_at") or ""},
        "model_bias": {"ok": bool(model_payload.get("ok")), "days": int(model_bias_days)},
        "place_bias": {"ok": bool(place_payload.get("ok")), "days": int(place_bias_days)},
        "prediction_hit_stats": {
            "ok": any(bool(item.get("ok")) for item in hit_stats_payloads),
            "windows": [
                {
                    "days": int(item.get("days") or 0),
                    "window_label": str(item.get("window_label") or _prediction_days_label(int(item.get("days") or 0))),
                    "ok": bool(item.get("ok")),
                    "events": int(((item.get("settlement") or {}) if isinstance(item, dict) else {}).get("events") or 0),
                    "eligible_events": int(((item.get("coverage") or {}) if isinstance(item, dict) else {}).get("eligible_events") or 0),
                }
                for item in hit_stats_payloads
            ],
        },
        "source_lead_day_hit_rates": {
            "ok": bool(source_lead_day_payload.get("ok")),
            "days": int(source_lead_day_payload.get("days") or SOURCE_LEAD_DAY_HIT_RATE_SNAPSHOT_DAYS),
            "window_label": str(source_lead_day_payload.get("window_label") or _prediction_days_label(SOURCE_LEAD_DAY_HIT_RATE_SNAPSHOT_DAYS)),
            "eligible_events": int(((source_lead_day_payload.get("coverage") or {}) if isinstance(source_lead_day_payload, dict) else {}).get("eligible_events") or 0),
            "settled_events": int(((source_lead_day_payload.get("coverage") or {}) if isinstance(source_lead_day_payload, dict) else {}).get("settled_events") or 0),
            "snapshot_kind": SOURCE_LEAD_DAY_HIT_RATE_SNAPSHOT_KIND,
            "materialized_at": str(source_lead_day_payload.get("materialized_at") or ""),
            "na_reason": str(source_lead_day_payload.get("na_reason") or source_lead_day_payload.get("error") or ""),
        },
        "forecast_source_accuracy": {
            "ok": bool(forecast_source_accuracy_payload.get("schema") == "forecast_source_accuracy_report_v1"),
            "snapshot_kind": FORECAST_SOURCE_ACCURACY_SNAPSHOT_KIND,
            "report_sha256": str(forecast_source_accuracy_payload.get("report_sha256") or ""),
            "generated_at": str(forecast_source_accuracy_payload.get("generated_at") or ""),
            "na_reason": str(forecast_source_accuracy_payload.get("na_reason") or forecast_source_accuracy_payload.get("error") or ""),
        },
        "joint_weak_bias_research": {
            "ok": bool(joint_weak_bias_research_payload.get("schema") == "joint_weak_bias_research_snapshot_v1"),
            "snapshot_kind": JOINT_WEAK_BIAS_RESEARCH_SNAPSHOT_KIND,
            "pipeline_sha256": str(joint_weak_bias_research_payload.get("pipeline_sha256") or ""),
            "readiness_state": str(((joint_weak_bias_research_payload.get("readiness") or {}) if isinstance(joint_weak_bias_research_payload, dict) else {}).get("state") or ""),
            "na_reason": str(joint_weak_bias_research_payload.get("na_reason") or joint_weak_bias_research_payload.get("error") or ""),
        },
        "strategy_stats": {"ok": bool(strategy_payload.get("ok")), "days": int(strategy_days)},
        "entry_counterfactual_review": {
            "ok": bool(counterfactual_payload.get("ok")),
            "days": int(counterfactual_days),
            "snapshot_id": int(((counterfactual_payload.get("_meta") or {}) if isinstance(counterfactual_payload, dict) else {}).get("id") or 0),
            "created_at": str(((counterfactual_payload.get("_meta") or {}) if isinstance(counterfactual_payload, dict) else {}).get("created_at") or ""),
            "na_reason": str(counterfactual_payload.get("na_reason") or counterfactual_payload.get("error") or ""),
        },
        "exit_policy_audit": {
            "ok": bool(exit_policy_payload.get("ok")),
            "days": 1,
            "snapshot_id": int(((exit_policy_payload.get("_meta") or {}) if isinstance(exit_policy_payload, dict) else {}).get("id") or 0),
            "created_at": str(((exit_policy_payload.get("_meta") or {}) if isinstance(exit_policy_payload, dict) else {}).get("created_at") or ""),
            "na_reason": str(exit_policy_payload.get("na_reason") or exit_policy_payload.get("error") or ""),
        },
        "orphan_fills": {"ok": bool(orphan_fill_payload.get("ok")), "days": int(orphan_fill_payload.get("days") or orphan_fill_days), "count": int(orphan_fill_payload.get("orphan_fill_count") or 0)},
        "optimizer": {"edge_bias_gate_suggestion": bool(edge_bias_gate_suggestion and edge_bias_gate_suggestion.get("ok"))},
    }


def load_feedback_snapshot(kind: str, days: int) -> Dict[str, Any]:
    if not DB_PATH.exists():
        return {"ok": False, "error": "db_missing"}
    try:
        days = int(days)
    except Exception:
        days = 0
    if days <= 0:
        return {"ok": False, "error": "invalid_days"}
    with open_db() as conn:
        payload = _load_latest_feedback_snapshot_from_db(conn, kind=str(kind or ""), days=int(days))
    if not payload:
        return {"ok": False, "na_reason": "missing_snapshot", "kind": str(kind or ""), "days": int(days)}
    return payload


def _auto_trade_runtime_lock_active() -> bool:
    lock_dir = DATA_DIR / "auto_trade_runtime.lock"
    if not lock_dir.exists():
        return False
    meta_path = lock_dir / "meta.json"
    pid = None
    if meta_path.exists():
        meta = safe_json_loads(meta_path.read_text(encoding="utf-8"))
        if isinstance(meta, dict):
            try:
                pid = int(meta.get("pid") or 0)
            except Exception:
                pid = None
    if pid and pid > 0:
        return pid_running(pid)
    # If pid is missing, treat as active (conservative) unless lock is obviously stale.
    return True


def _latest_optimizer_action(conn: sqlite3.Connection, *, kind: str) -> Optional[Dict[str, Any]]:
    _ensure_feedback_tables(conn)
    cur = conn.cursor()
    cur.execute(
        """
        SELECT id, kind, days, end_date, suggestion_snapshot_id, status, reason_code, reason_text, created_at
        FROM optimizer_actions
        WHERE kind = ?
        ORDER BY created_at DESC, id DESC
        LIMIT 1
        """,
        (str(kind or ""),),
    )
    row = cur.fetchone()
    if not row:
        return None
    return {
        "id": int(row[0] or 0),
        "kind": str(row[1] or ""),
        "days": int(row[2] or 0),
        "end_date": str(row[3] or ""),
        "suggestion_snapshot_id": int(row[4] or 0) if row[4] is not None else None,
        "status": str(row[5] or ""),
        "reason_code": str(row[6] or ""),
        "reason_text": str(row[7] or ""),
        "created_at": str(row[8] or ""),
    }


def _latest_optimizer_applied_at(conn: sqlite3.Connection, *, kind: str) -> str:
    _ensure_feedback_tables(conn)
    cur = conn.cursor()
    cur.execute(
        """
        SELECT created_at
        FROM optimizer_actions
        WHERE kind = ? AND status = 'applied'
        ORDER BY created_at DESC, id DESC
        LIMIT 1
        """,
        (str(kind or ""),),
    )
    row = cur.fetchone()
    return str(row[0] or "") if row else ""


_OPTIMIZER_AUTO_APPLY_CACHE: Dict[str, Any] = {
    "ts": 0.0,
    "ts_wall": "",
    "ttl_sec": 30.0,
    "enabled": None,
    "source": "",
    "plist_path": "",
}

LEGACY_OPTIMIZER_APPLY_RETIRED_REASON = "legacy_optimizer_apply_retired_use_parameter_change_governance"


def _legacy_optimizer_apply_retired_payload(*, source: str, end_date: str = "") -> Dict[str, Any]:
    return {
        "ok": True,
        "enabled": False,
        "applied": False,
        "applied_any": False,
        "status": "retired_no_write",
        "source": str(source or ""),
        "end_date": str(end_date or ""),
        "reason_code": LEGACY_OPTIMIZER_APPLY_RETIRED_REASON,
        "reason_text": "旧 optimizer apply 已退役；生产参数变更必须来自 approved calibration candidate。",
        "next_boundary": "create_parameter_change_request_from_approved_calibration_candidate",
        "guards": {
            "writes_archive_db": False,
            "writes_config_files": False,
            "changes_parameters": False,
            "restarts_launchd": False,
            "places_orders": False,
        },
        "generated_at": now_text(),
    }


def _infer_optimizer_auto_apply_enabled() -> Tuple[bool, str]:
    """
    UI may run in a different process than the hourly feedback LaunchAgent.
    Prefer env flag; otherwise infer from LaunchAgent env via `launchctl print`.
    """
    import plistlib
    global _OPTIMIZER_AUTO_APPLY_CACHE

    env_enabled = str(os.environ.get("PM_OPTIMIZER_AUTO_APPLY", "") or "").strip().lower() in {
        "1",
        "true",
        "yes",
        "on",
    }
    if env_enabled:
        # Keep cache coherent so UI can show a stable checked_at/source.
        _OPTIMIZER_AUTO_APPLY_CACHE = {
            "ts": time.monotonic(),
            "ts_wall": now_text(),
            "ttl_sec": float(_OPTIMIZER_AUTO_APPLY_CACHE.get("ttl_sec") or 30.0),
            "enabled": False,
            "source": "retired_env",
            "plist_path": str(_OPTIMIZER_AUTO_APPLY_CACHE.get("plist_path") or ""),
        }
        return False, "retired_env"
    now_ts = time.monotonic()
    cached = _OPTIMIZER_AUTO_APPLY_CACHE
    age = now_ts - float(cached.get("ts") or 0.0)
    ttl = float(cached.get("ttl_sec") or 30.0)
    if age >= 0 and age < ttl and cached.get("enabled") is not None:
        return bool(cached.get("enabled")), str(cached.get("source") or "cache")
    enabled = False
    source = "launchd"
    label = "com.weather.feedback_loop_hourly"
    launchctl_bin = "/bin/launchctl" if Path("/bin/launchctl").exists() else "launchctl"
    plist_path = str(cached.get("plist_path") or "").strip()

    def _parse_bool(raw: Any) -> Optional[bool]:
        if raw is None:
            return None
        if isinstance(raw, bool):
            return bool(raw)
        if isinstance(raw, (int, float)):
            try:
                return bool(int(raw))
            except Exception:
                return None
        text = str(raw).strip().lower()
        if not text:
            return None
        if text in {"1", "true", "yes", "on", "enabled"}:
            return True
        if text in {"0", "false", "no", "off", "disabled"}:
            return False
        return None

    def _read_plist_auto_apply(path: Path) -> Optional[bool]:
        try:
            with path.open("rb") as f:
                doc = plistlib.load(f)
        except Exception:
            return None
        env = doc.get("EnvironmentVariables") if isinstance(doc, dict) else None
        if not isinstance(env, dict):
            return None
        return _parse_bool(env.get("PM_OPTIMIZER_AUTO_APPLY"))

    try:
        uid = os.getuid()
        res = subprocess.run(
            [launchctl_bin, "print", f"gui/{uid}/{label}"],
            capture_output=True,
            text=True,
            timeout=0.35,
            check=False,
        )
        if res.returncode == 0:
            for line in (res.stdout or "").splitlines():
                line = line.strip()
                if line.startswith("path ="):
                    plist_path = line.split("=", 1)[1].strip()
                    break
            for line in (res.stdout or "").splitlines():
                if "PM_OPTIMIZER_AUTO_APPLY" in line and "=>" in line:
                    # Example: PM_OPTIMIZER_AUTO_APPLY => 1
                    m = re.search(r"PM_OPTIMIZER_AUTO_APPLY\\s*=>\\s*([0-9A-Za-z_\\-]+)", line)
                    if m:
                        val = m.group(1).strip().lower()
                        enabled = val in {"1", "true", "yes", "on"}
                        source = "launchctl"
                        break
    except Exception:
        # Keep best-effort; plist fallback below will still run.
        pass

    # If launchctl is slow/failed or doesn't include the env var, fall back to reading the plist.
    if source != "launchctl":
        plist_candidate = Path(plist_path) if plist_path else (LAUNCHD_USER_DIR / f"{label}.plist")
        val = _read_plist_auto_apply(plist_candidate) if plist_candidate.exists() else None
        if val is None:
            repo_plist = ROOT_DIR / "launchd" / f"{label}.plist"
            if repo_plist.exists():
                val = _read_plist_auto_apply(repo_plist)
        if val is not None:
            enabled = bool(val)
            source = "plist"
    if enabled:
        enabled = False
        source = f"retired_{source}"
    _OPTIMIZER_AUTO_APPLY_CACHE = {
        "ts": now_ts,
        "ts_wall": now_text(),
        "ttl_sec": ttl,
        "enabled": enabled,
        "source": source,
        "plist_path": plist_path,
    }
    return bool(enabled), source


def _write_optimizer_action(
    conn: sqlite3.Connection,
    *,
    kind: str,
    days: int,
    end_date: str,
    suggestion_snapshot_id: Optional[int],
    status: str,
    reason_code: str,
    reason_text: str,
    before: Optional[Dict[str, Any]] = None,
    after: Optional[Dict[str, Any]] = None,
    restart: Optional[Dict[str, Any]] = None,
    scan: Optional[Dict[str, Any]] = None,
) -> int:
    _ensure_feedback_tables(conn)
    cur = conn.cursor()
    cur.execute(
        """
        INSERT INTO optimizer_actions(
            kind, days, end_date, suggestion_snapshot_id, status, reason_code, reason_text,
            before_json, after_json, restart_json, scan_json, created_at
        ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
        """,
        (
            str(kind or ""),
            int(days),
            str(end_date or ""),
            int(suggestion_snapshot_id) if suggestion_snapshot_id is not None else None,
            str(status or ""),
            str(reason_code or ""),
            str(reason_text or ""),
            json.dumps(before or {}, ensure_ascii=True),
            json.dumps(after or {}, ensure_ascii=True),
            json.dumps(restart or {}, ensure_ascii=True) if restart is not None else None,
            json.dumps(scan or {}, ensure_ascii=True) if scan is not None else None,
            now_text(),
        ),
    )
    return int(cur.lastrowid or 0)


def optimizer_status(*, days: int = 30) -> Dict[str, Any]:
    base_cfg = auto_trade_config_defaults()
    base_cfg.update(load_auto_trade_config())
    current_conf = to_float(base_cfg.get("entry_edge_confidence_min"))
    if current_conf is None or not math.isfinite(current_conf):
        current_conf = None

    try:
        days = int(days)
    except Exception:
        days = 30
    if days <= 0:
        days = 30
    enabled, enabled_source = _infer_optimizer_auto_apply_enabled()
    checked_at = str(_OPTIMIZER_AUTO_APPLY_CACHE.get("ts_wall") or "").strip()
    kind = "edge_bias_gate_suggestion"
    suggestion = load_feedback_snapshot(kind, days)
    action: Optional[Dict[str, Any]] = None
    last_applied_at = ""
    try:
        if DB_PATH.exists():
            with open_db() as conn:
                action = _latest_optimizer_action(conn, kind="edge_bias_gate_apply")
                last_applied_at = _latest_optimizer_applied_at(conn, kind="edge_bias_gate_apply")
    except Exception:
        action = None
        last_applied_at = ""
    proposed = None
    if isinstance(suggestion, dict) and suggestion.get("ok"):
        proposal = suggestion.get("proposal") if isinstance(suggestion.get("proposal"), dict) else {}
        proposed = to_float(proposal.get("entry_edge_confidence_min"))
        proposed = float(proposed) if proposed is not None and math.isfinite(proposed) else None
    return {
        "ok": True,
        "generated_at": now_text(),
        "auto_apply_enabled": bool(enabled),
        "auto_apply_source": str(enabled_source or ""),
        "auto_apply_checked_at": checked_at,
        "edge_bias_gate": {
            "days": int(days),
            "current_entry_edge_confidence_min": current_conf,
            "proposed_entry_edge_confidence_min": proposed,
            "suggestion": suggestion if isinstance(suggestion, dict) else {},
            "last_action": action or {},
            "last_applied_at": last_applied_at,
        },
    }


def apply_edge_bias_gate_suggestion(
    *,
    days: int = 30,
    end_date: str = "",
    restart: bool = True,
    scan: bool = False,
) -> Dict[str, Any]:
    """
    Apply latest `edge_bias_gate_suggestion` to auto-trade config.
    This is conservative: gated by min interval, max delta, and requires suggestion meets coverage target.
    """
    return _legacy_optimizer_apply_retired_payload(
        source="apply_edge_bias_gate_suggestion",
        end_date=end_date,
    )


def apply_optimizer_suggestions(*, end_date: str = "") -> Dict[str, Any]:
    payload = _legacy_optimizer_apply_retired_payload(
        source="apply_optimizer_suggestions",
        end_date=end_date,
    )
    payload["items"] = {"edge_bias_gate": _legacy_optimizer_apply_retired_payload(source="edge_bias_gate", end_date=end_date)}
    return payload


def suggest_edge_bias_gate_from_payload(edge_bias_payload: Dict[str, Any], *, days: int) -> Optional[Dict[str, Any]]:
    """
    Conservative auto-optimizer:
    Suggest `entry_edge_confidence_min` (a gate on calibration ratio=real_edge/pred_edge)
    from Edge-bias calibration bins (event basis).
    """
    if not isinstance(edge_bias_payload, dict) or not edge_bias_payload.get("ok"):
        return None
    event_basis = edge_bias_payload.get("event_basis") if isinstance(edge_bias_payload.get("event_basis"), dict) else None
    if not isinstance(event_basis, dict):
        return None
    calib = event_basis.get("calibration") if isinstance(event_basis.get("calibration"), dict) else None
    bins = calib.get("bins") if isinstance(calib, dict) else None
    if not isinstance(bins, list) or not bins:
        return None
    try:
        target = float(os.environ.get("PM_EDGE_BIAS_OPT_TARGET_COVERAGE", "0.85") or 0.85)
    except Exception:
        target = 0.85
    target = min(max(target, 0.1), 0.99)
    try:
        min_bin = int(os.environ.get("PM_EDGE_BIAS_OPT_MIN_BIN_COUNT", "20") or 20)
    except Exception:
        min_bin = 20
    min_bin = max(1, min_bin)
    rows: List[Dict[str, Any]] = []
    total = 0
    for row in bins:
        if not isinstance(row, dict):
            continue
        try:
            count = int(row.get("count") or 0)
        except Exception:
            count = 0
        if count <= 0:
            continue
        ratio = to_float(row.get("ratio"))
        real_mean = to_float(row.get("real_mean"))
        pred_mean = to_float(row.get("pred_mean"))
        if ratio is None or real_mean is None or pred_mean is None:
            continue
        if not math.isfinite(ratio) or not math.isfinite(real_mean) or not math.isfinite(pred_mean):
            continue
        if pred_mean <= 0:
            continue
        total += count
        if count < min_bin:
            continue
        rows.append({"count": count, "ratio": float(ratio), "real_mean": float(real_mean), "pred_mean": float(pred_mean)})
    if total <= 0 or not rows:
        return None
    candidates = sorted({float(r["ratio"]) for r in rows if math.isfinite(float(r["ratio"]))})
    candidates.extend([0.7])
    candidates = sorted({float(x) for x in candidates if math.isfinite(float(x))})
    best: Optional[Dict[str, Any]] = None
    for t in candidates:
        kept = [r for r in rows if float(r["ratio"]) >= float(t)]
        kept_count = sum(int(r["count"]) for r in kept)
        if kept_count <= 0:
            continue
        coverage = kept_count / total if total else 0.0
        avg_real = sum(float(r["real_mean"]) * int(r["count"]) for r in kept) / kept_count
        score = avg_real
        meets = coverage >= target - 1e-9
        if best is None:
            best = {"t": float(t), "coverage": coverage, "avg_real": avg_real, "meets": meets, "score": score}
            continue
        if bool(meets) and not bool(best.get("meets")):
            best = {"t": float(t), "coverage": coverage, "avg_real": avg_real, "meets": meets, "score": score}
            continue
        if bool(meets) == bool(best.get("meets")) and score > float(best.get("score") or -1e9):
            best = {"t": float(t), "coverage": coverage, "avg_real": avg_real, "meets": meets, "score": score}
    if not best:
        return None
    return {
        "ok": True,
        "kind": "edge_bias_gate_suggestion",
        "days": int(days),
        "generated_at": now_text(),
        "target_coverage": target,
        "min_bin_count": min_bin,
        "proposal": {"entry_edge_confidence_min": float(best["t"])},
        "metrics": {
            "total_bin_samples": int(total),
            "coverage": float(best["coverage"]),
            "avg_real_edge_points": float(best["avg_real"]),
            "meets_target": bool(best["meets"]),
        },
    }


def _binomial_ci_wilson(successes: int, n: int, z: float = 1.96) -> Tuple[Optional[float], Optional[float]]:
    if n <= 0:
        return None, None
    try:
        successes = int(successes)
        n = int(n)
    except Exception:
        return None, None
    if n <= 0:
        return None, None
    phat = successes / n
    z2 = z * z
    denom = 1.0 + z2 / n
    center = (phat + z2 / (2.0 * n)) / denom
    margin = (z * math.sqrt((phat * (1.0 - phat) + z2 / (4.0 * n)) / n)) / denom
    low = max(0.0, center - margin)
    high = min(1.0, center + margin)
    return low, high


def _calibration_quality_metrics(
    bins: List[Dict[str, Any]],
    total_samples: int,
    brier_sum: float,
) -> Dict[str, Any]:
    if total_samples <= 0:
        return {"ece": None, "mce": None, "brier": None, "n": 0}
    ece = 0.0
    mce = 0.0
    for entry in bins or []:
        count = int(entry.get("count") or 0)
        if count <= 0:
            continue
        pred_mean = to_float(entry.get("pred_mean"))
        real_mean = to_float(entry.get("real_mean"))
        if pred_mean is None or real_mean is None:
            continue
        gap = abs(pred_mean - real_mean)
        ece += gap * (count / total_samples)
        if gap > mce:
            mce = gap
    brier = brier_sum / total_samples if total_samples > 0 else None
    return {"ece": ece, "mce": mce, "brier": brier, "n": total_samples}


def _load_q_calibration_stability_from_db(days: int) -> Optional[Dict[str, Any]]:
    if not DB_PATH.exists():
        return None
    rows = []
    try:
        with open_db() as conn:
            cur = conn.cursor()
            cur.execute(
                """
                CREATE TABLE IF NOT EXISTS q_calibration_stability (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    days INTEGER,
                    bin_index INTEGER,
                    last_val REAL,
                    stable_count INTEGER,
                    updated_at TEXT
                )
                """
            )
            cur.execute(
                """
                CREATE UNIQUE INDEX IF NOT EXISTS idx_q_calibration_stability_key
                ON q_calibration_stability(days, bin_index)
                """
            )
            cur.execute(
                """
                SELECT bin_index, last_val, stable_count
                FROM q_calibration_stability
                WHERE days = ?
                ORDER BY bin_index ASC
                """,
                (days,),
            )
            rows = cur.fetchall()
    except Exception:
        return None
    if not rows:
        return None
    size = len(Q_CALIBRATION_BINS)
    last_vals: List[Optional[float]] = [None] * size
    stable_counts: List[int] = [0] * size
    for bin_index, last_val, stable_count in rows:
        if bin_index is None:
            continue
        try:
            idx = int(bin_index)
        except Exception:
            continue
        if idx < 0 or idx >= size:
            continue
        last_vals[idx] = to_float(last_val)
        stable_counts[idx] = int(stable_count or 0)
    return {"last": last_vals, "counts": stable_counts, "ts": time.time()}


def _save_q_calibration_stability_to_db(days: int, last_vals: List[Optional[float]], counts: List[int]) -> None:
    if not DB_PATH.exists():
        return
    try:
        with open_db() as conn:
            cur = conn.cursor()
            cur.execute(
                """
                CREATE TABLE IF NOT EXISTS q_calibration_stability (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    days INTEGER,
                    bin_index INTEGER,
                    last_val REAL,
                    stable_count INTEGER,
                    updated_at TEXT
                )
                """
            )
            cur.execute(
                """
                CREATE UNIQUE INDEX IF NOT EXISTS idx_q_calibration_stability_key
                ON q_calibration_stability(days, bin_index)
                """
            )
            now_text = datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")
            size = max(len(last_vals), len(counts), len(Q_CALIBRATION_BINS))
            for idx in range(size):
                last_val = last_vals[idx] if idx < len(last_vals) else None
                stable_count = counts[idx] if idx < len(counts) else 0
                cur.execute(
                    """
                    INSERT INTO q_calibration_stability(days, bin_index, last_val, stable_count, updated_at)
                    VALUES(?, ?, ?, ?, ?)
                    ON CONFLICT(days, bin_index) DO UPDATE SET
                        last_val=excluded.last_val,
                        stable_count=excluded.stable_count,
                        updated_at=excluded.updated_at
                    """,
                    (days, idx, last_val, int(stable_count or 0), now_text),
                )
            conn.commit()
    except Exception:
        return


def _apply_q_calibration_stability(payload: Dict[str, Any], days: int) -> Dict[str, Any]:
    stable_n = Q_CALIBRATION_STABLE_N
    stable_eps = Q_CALIBRATION_STABLE_EPS
    try:
        stable_n = int(stable_n)
    except Exception:
        stable_n = 1
    if stable_n <= 1:
        payload["stable_min"] = 1
        payload["stable_eps"] = stable_eps
        return payload
    if not math.isfinite(stable_eps) or stable_eps < 0:
        stable_eps = 0.0
    bins = payload.get("bins") or []
    entry = Q_CALIBRATION_STABLE_CACHE.get(days)
    if not entry:
        entry = _load_q_calibration_stability_from_db(days) or {}
        if entry:
            Q_CALIBRATION_STABLE_CACHE[days] = entry
    last_vals = entry.get("last") or []
    stable_counts = entry.get("counts") or []
    new_last: List[Optional[float]] = []
    new_counts: List[int] = []
    for idx, bin_entry in enumerate(bins):
        count = int(bin_entry.get("count") or 0)
        real_mean = to_float(bin_entry.get("real_mean"))
        if count < Q_CALIBRATION_MIN_COUNT or real_mean is None or not math.isfinite(real_mean):
            bin_entry["calibrated"] = None
            bin_entry["stable_ok"] = False
            new_last.append(None)
            new_counts.append(0)
            continue
        prev_val = last_vals[idx] if idx < len(last_vals) else None
        prev_count = stable_counts[idx] if idx < len(stable_counts) else 0
        if prev_val is None or not math.isfinite(prev_val):
            next_count = 1
        else:
            next_count = prev_count + 1 if abs(real_mean - prev_val) <= stable_eps else 1
        new_last.append(real_mean)
        new_counts.append(int(next_count))
        if next_count < stable_n:
            bin_entry["calibrated"] = None
            bin_entry["stable_ok"] = False
        else:
            bin_entry["calibrated"] = real_mean
            bin_entry["stable_ok"] = True
    Q_CALIBRATION_STABLE_CACHE[days] = {"last": new_last, "counts": new_counts, "ts": time.time()}
    _save_q_calibration_stability_to_db(days, new_last, new_counts)
    payload["stable_min"] = stable_n
    payload["stable_eps"] = stable_eps
    return payload


def q_round_calibration_stats(days: int) -> Dict[str, Any]:
    now_ts = time.time()
    cached = Q_CALIBRATION_STATS_CACHE.get(days)
    if cached:
        ts = float(cached.get("ts") or 0.0)
        if (now_ts - ts) <= Q_CALIBRATION_CACHE_MAX_AGE_SEC:
            return cached.get("payload") or {}
    if not DB_PATH.exists():
        return {"ok": False, "days": days, "events": 0, "generated_at": now_text()}
    with open_db() as conn:
        rows = load_event_rows(conn, days, require_settlement=True)
        latest_rows = pick_latest_rows(rows)
        total_events = 0
        entries = [
            {
                "count": 0,
                "hit": 0,
                "pred_sum": 0.0,
                "pred_sq_sum": 0.0,
                "real_sum": 0.0,
                "bias_sum": 0.0,
            }
            for _ in Q_CALIBRATION_BINS
        ]
        brier_sum = 0.0
        total_samples = 0

        def bin_index(q_val: float) -> Optional[int]:
            for idx, (low, high) in enumerate(Q_CALIBRATION_BINS):
                if q_val >= low and q_val < high:
                    return idx
            return None

        for row in latest_rows:
            payload = safe_json_loads(row["payload_json"])
            distribution = normalize_distribution_rows(payload.get("rows") or [])
            if not distribution:
                continue
            actual_label = actual_bucket_label(row, distribution)
            if not actual_label:
                continue
            total_events += 1
            for dist_row in distribution:
                label = str(dist_row.get("outcome") or "")
                if not label:
                    continue
                q_val = to_float(dist_row.get("q_round"))
                if q_val is None or not math.isfinite(q_val):
                    continue
                if q_val < 0 or q_val > 1:
                    continue
                idx = bin_index(float(q_val))
                if idx is None:
                    continue
                actual = 1.0 if label == actual_label else 0.0
                entry = entries[idx]
                entry["count"] += 1
                entry["hit"] += 1 if actual > 0.5 else 0
                entry["pred_sum"] += float(q_val)
                entry["pred_sq_sum"] += float(q_val) * float(q_val)
                entry["real_sum"] += actual
                entry["bias_sum"] += (actual - float(q_val))
                brier_sum += (float(q_val) - actual) ** 2
                total_samples += 1

        bins_out: List[Dict[str, Any]] = []
        for (low, high), entry in zip(Q_CALIBRATION_BINS, entries):
            count = int(entry["count"] or 0)
            if count <= 0:
                bins_out.append(
                    {
                        "range": [low, high],
                        "count": 0,
                        "hit": 0,
                        "hit_rate": None,
                        "pred_mean": None,
                        "real_mean": None,
                        "bias_mean": None,
                        "calibrated": None,
                        "ci_low": None,
                        "ci_high": None,
                    }
                )
                continue
            pred_mean = entry["pred_sum"] / count
            real_mean = entry["real_sum"] / count
            bias_mean = entry["bias_sum"] / count
            hit_rate = entry["hit"] / count
            calibrated = real_mean if count >= Q_CALIBRATION_MIN_COUNT else None
            ci_low, ci_high = _binomial_ci_wilson(int(entry["hit"] or 0), count)
            bins_out.append(
                {
                    "range": [low, high],
                    "count": count,
                    "hit": int(entry["hit"] or 0),
                    "hit_rate": hit_rate,
                    "pred_mean": pred_mean,
                    "real_mean": real_mean,
                    "bias_mean": bias_mean,
                    "calibrated": calibrated,
                    "ci_low": ci_low,
                    "ci_high": ci_high,
                }
            )

        payload = {
            "ok": True,
            "days": days,
            "events": total_events,
            "min_count": Q_CALIBRATION_MIN_COUNT,
            "bins": bins_out,
            "metrics": _calibration_quality_metrics(bins_out, total_samples, brier_sum),
            "generated_at": now_text(),
        }
        payload = _apply_q_calibration_stability(payload, days)
        Q_CALIBRATION_STATS_CACHE[days] = {"ts": now_ts, "payload": payload}
        return payload


def _load_platt_calibration(days: int) -> Optional[Dict[str, Any]]:
    if not DB_PATH.exists() or not days or days <= 0:
        return None
    with open_db() as conn:
        cur = conn.cursor()
        try:
            cur.execute(
                """
                SELECT days, a, b, sample_count, event_count, start_date, end_date,
                       logloss, brier, stable_ok, stable_count, generated_at, updated_at
                FROM q_platt_calibration
                WHERE days = ?
                LIMIT 1
                """,
                (int(days),),
            )
            row = cur.fetchone()
        except sqlite3.Error:
            row = None
    if not row:
        return None
    return {
        "ok": True,
        "method": "platt",
        "days": int(row[0] or 0),
        "a": to_float(row[1]),
        "b": to_float(row[2]),
        "sample_count": _to_int(row[3]),
        "event_count": _to_int(row[4]),
        "start_date": str(row[5] or ""),
        "end_date": str(row[6] or ""),
        "logloss": to_float(row[7]),
        "brier": to_float(row[8]),
        "stable_ok": bool(int(row[9] or 0)),
        "stable_count": _to_int(row[10]),
        "generated_at": str(row[11] or ""),
        "updated_at": str(row[12] or ""),
    }


