def _load_json_file(path: Path) -> Dict[str, Any]:
    try:
        payload = json.loads(path.read_text(encoding="utf-8"))
    except Exception:
        return {}
    return payload if isinstance(payload, dict) else {}


def load_q_calibration_health(
    conn: sqlite3.Connection,
    *,
    days: int = 30,
) -> Dict[str, Any]:
    out: Dict[str, Any] = {
        "source": "platt",
        "active_version": "",
        "candidate_version": "",
        "bundle_path": str(DATA_DIR / "q_calibration_bundle.json"),
        "candidate_bundle_path": str(DATA_DIR / "q_calibration_bundle.candidate.json"),
        "sample_n": 0,
        "label_n": 0,
        "sample_n_30d": 0,
        "label_n_30d": 0,
        "ece": None,
        "brier": None,
        "logloss": None,
        "psi": None,
        "roi_lcb": None,
        "status": "",
        "promote_recommended": False,
        "last_train_at": "",
        "last_eval_at": "",
    }
    try:
        days_int = max(1, int(days))
    except Exception:
        days_int = 30
    champion_path = Path(out["bundle_path"])
    candidate_path = Path(out["candidate_bundle_path"])
    champion_bundle = _load_json_file(champion_path) if champion_path.exists() else {}
    candidate_bundle = _load_json_file(candidate_path) if candidate_path.exists() else {}
    if champion_bundle:
        out["source"] = "q_calibration_bundle"
        out["active_version"] = str(champion_bundle.get("version") or "")
        out["last_train_at"] = str(champion_bundle.get("generated_at") or "")
        out["sample_n"] = _to_int(champion_bundle.get("sample_n"))
        out["label_n"] = _to_int(champion_bundle.get("label_n"))
        metrics = champion_bundle.get("metrics")
        if isinstance(metrics, dict):
            out["ece"] = to_float(metrics.get("ece"))
            out["brier"] = to_float(metrics.get("brier"))
            out["logloss"] = to_float(metrics.get("logloss"))
    if candidate_bundle:
        out["candidate_version"] = str(candidate_bundle.get("version") or "")
        out["candidate_generated_at"] = str(candidate_bundle.get("generated_at") or "")

    try:
        since_iso = (datetime.now(timezone.utc) - timedelta(days=days_int)).isoformat(timespec="seconds")
        cur = conn.cursor()
        cur.execute(
            """
            SELECT COUNT(1), SUM(CASE WHEN label IN (0, 1) THEN 1 ELSE 0 END)
            FROM calibration_labels
            WHERE datetime(created_at) >= datetime(?)
            """,
            (since_iso,),
        )
        row = cur.fetchone()
        if row:
            out["label_n_30d"] = _to_int(row[0])
    except sqlite3.Error:
        pass
    try:
        since_iso = (datetime.now(timezone.utc) - timedelta(days=days_int)).isoformat(timespec="seconds")
        cur = conn.cursor()
        cur.execute(
            """
            SELECT COUNT(1)
            FROM calibration_samples
            WHERE datetime(created_at) >= datetime(?)
            """,
            (since_iso,),
        )
        row = cur.fetchone()
        if row:
            out["sample_n_30d"] = _to_int(row[0])
    except sqlite3.Error:
        pass
    try:
        cur = conn.cursor()
        cur.execute(
            """
            SELECT id, status, ece, brier, logloss, psi, roi_lcb, created_at, notes_json
            FROM calibration_eval_runs
            ORDER BY id DESC
            LIMIT 1
            """
        )
        row = cur.fetchone()
        if row:
            out["eval_id"] = _to_int(row[0])
            out["status"] = str(row[1] or "")
            out["last_eval_at"] = str(row[7] or "")
            out["ece"] = to_float(row[2]) if row[2] is not None else out.get("ece")
            out["brier"] = to_float(row[3]) if row[3] is not None else out.get("brier")
            out["logloss"] = to_float(row[4]) if row[4] is not None else out.get("logloss")
            out["psi"] = to_float(row[5])
            out["roi_lcb"] = to_float(row[6])
            notes_raw = str(row[8] or "")
            if notes_raw:
                try:
                    notes = json.loads(notes_raw)
                except Exception:
                    notes = {}
                if isinstance(notes, dict):
                    out["promote_recommended"] = bool(notes.get("recommend_promote"))
            if not out.get("promote_recommended"):
                out["promote_recommended"] = str(out.get("status") or "") == "promote_recommended"
    except sqlite3.Error:
        pass

    platt_days = 30
    try:
        platt_days = int(os.environ.get("PM_Q_PLATT_DAYS", "30") or 30)
    except Exception:
        platt_days = 30
    platt = _load_platt_calibration_ro(conn, platt_days)
    if not out.get("active_version") and isinstance(platt, dict):
        out["source"] = "platt"
        out["active_version"] = f"platt_days_{int(platt.get('days') or platt_days)}"
        out["sample_n"] = _to_int(platt.get("sample_count"))
        out["label_n"] = _to_int(platt.get("sample_count"))
        out["last_train_at"] = str(platt.get("generated_at") or "")
        if out.get("brier") is None:
            out["brier"] = to_float(platt.get("brier"))
        if out.get("logloss") is None:
            out["logloss"] = to_float(platt.get("logloss"))
    out["days_window"] = days_int
    return out


def _platt_predict(q_val: float, a: float, b: float, eps: float = 1e-4) -> Optional[float]:
    try:
        q = float(q_val)
    except (TypeError, ValueError):
        return None
    if not math.isfinite(q):
        return None
    if eps <= 0:
        eps = 1e-4
    q = min(max(q, eps), 1.0 - eps)
    try:
        logit = math.log(q / (1.0 - q))
    except (ValueError, ZeroDivisionError):
        return None
    z = a * logit + b
    if z >= 60:
        return 1.0
    if z <= -60:
        return 0.0
    try:
        return 1.0 / (1.0 + math.exp(-z))
    except OverflowError:
        return 0.0 if z < 0 else 1.0


def _ensure_fact_q_calibrated(payload: Dict[str, Any], platt: Optional[Dict[str, Any]]) -> bool:
    if not isinstance(payload, dict):
        return False
    if not platt or not platt.get("stable_ok"):
        return False
    a = to_float(platt.get("a"))
    b = to_float(platt.get("b"))
    if a is None or b is None or not math.isfinite(a) or not math.isfinite(b):
        return False
    eps_raw = os.environ.get("PM_Q_PLATT_LOGIT_EPS")
    try:
        eps = float(eps_raw) if eps_raw is not None else 1e-4
    except (TypeError, ValueError):
        eps = 1e-4
    dist = payload.get("distribution") or payload.get("rows") or []
    if not isinstance(dist, list) or not dist:
        return False
    # If all rows already have q_calibrated, skip.
    missing = 0
    for row in dist:
        if not isinstance(row, dict):
            continue
        q_cal = to_float(row.get("q_calibrated"))
        if q_cal is None or not math.isfinite(q_cal):
            missing += 1
    if missing == 0:
        return False
    unnorm: List[Tuple[Dict[str, Any], float]] = []
    total = 0.0
    for row in dist:
        if not isinstance(row, dict):
            continue
        q_raw = to_float(row.get("q_raw"))
        if q_raw is None or not math.isfinite(q_raw):
            q_raw = to_float(row.get("q_round"))
        if q_raw is None or not math.isfinite(q_raw):
            continue
        cal = _platt_predict(float(q_raw), float(a), float(b), eps)
        if cal is None or not math.isfinite(cal) or cal <= 0:
            continue
        unnorm.append((row, float(cal)))
        total += float(cal)
    if total <= 0 or not unnorm:
        return False
    for row, cal in unnorm:
        q_val = cal / total
        row.setdefault("q_calibrated", q_val)
        if "q_calibrated_no" not in row:
            row["q_calibrated_no"] = max(0.0, min(1.0, 1.0 - q_val))
    prov = payload.get("fact_provenance")
    if isinstance(prov, dict):
        prov["q_calibrated_backfill"] = "platt"
    else:
        payload["fact_provenance"] = {"q_calibrated_backfill": "platt"}
    return True


def _set_fact_q_calibrated_na_reason(payload: Dict[str, Any], platt: Optional[Dict[str, Any]]) -> bool:
    if not isinstance(payload, dict):
        return False
    if not platt or not platt.get("stable_ok"):
        return False
    dist = payload.get("distribution") or payload.get("rows") or []
    if not isinstance(dist, list) or not dist:
        payload["q_calibrated_na_reason"] = "distribution_empty"
        return True
    missing = 0
    total = 0
    for row in dist:
        if not isinstance(row, dict):
            continue
        total += 1
        q_cal = to_float(row.get("q_calibrated"))
        if q_cal is None or not math.isfinite(q_cal):
            missing += 1
    if total <= 0:
        payload["q_calibrated_na_reason"] = "distribution_empty"
        return True
    if missing <= 0:
        payload.pop("q_calibrated_na_reason", None)
        return False
    payload["q_calibrated_na_reason"] = f"missing_q_calibrated_rows:{missing}/{total}"
    return True


def _load_model_spread_latest_rows(
    conn: sqlite3.Connection,
    start_key: str,
    end_key: str,
) -> List[sqlite3.Row]:
    cur = conn.cursor()
    try:
        cur.execute(
            """
            SELECT h.fact_as_of, h.fact_json
            FROM event_fact_latest l
            JOIN event_fact_history h ON h.id = l.fact_id
            WHERE date(h.event_date) BETWEEN ? AND ?
            ORDER BY h.event_date DESC, h.fact_as_of DESC, h.id DESC
            """,
            (start_key, end_key),
        )
        rows = cur.fetchall()
        if rows:
            return rows
    except sqlite3.OperationalError:
        pass
    try:
        cur.execute(
            """
            SELECT fact_as_of, fact_json
            FROM (
                SELECT fact_as_of, fact_json, slug, event_date,
                       ROW_NUMBER() OVER (
                           PARTITION BY slug, event_date
                           ORDER BY fact_as_of DESC, id DESC
                       ) AS rn
                FROM event_fact_history
                WHERE date(event_date) BETWEEN ? AND ?
            ) t
            WHERE rn = 1
            ORDER BY fact_as_of DESC
            """,
            (start_key, end_key),
        )
        return cur.fetchall()
    except sqlite3.OperationalError:
        return []


def model_spread_stats(days: int) -> Dict[str, Any]:
    try:
        days = int(days)
    except (TypeError, ValueError):
        days = 7
    days = max(1, min(days, 60))
    if not DB_PATH.exists():
        return {"ok": False, "days": days, "events": 0, "generated_at": now_text(), "na_reason": "db_missing"}

    now_ts = time.time()
    cached_payload: Optional[Dict[str, Any]] = None
    with MODEL_SPREAD_CACHE_LOCK:
        cached = MODEL_SPREAD_CACHE.get(days)
        if isinstance(cached, dict):
            cached_payload = dict(cached.get("payload") or {})
            cache_ts = float(cached.get("ts") or 0.0)
            if cached_payload and (now_ts - cache_ts) <= float(MODEL_SPREAD_CACHE_SEC):
                return cached_payload

    try:
        with open_db_ro_fast(timeout_sec=0.35, busy_timeout_ms=350) as conn:
            start_date, end_date = resolve_stats_range(conn, days, require_settlement=True)
            start_key = start_date.isoformat()
            end_key = end_date.isoformat()
            latest_rows = _load_model_spread_latest_rows(conn, start_key, end_key)
    except Exception as exc:
        if isinstance(cached_payload, dict) and cached_payload:
            cached_payload["cache_stale"] = True
            cached_payload["na_reason"] = f"db_unavailable:{exc.__class__.__name__}"
            return cached_payload
        return {
            "ok": False,
            "days": days,
            "events": 0,
            "rows": 0,
            "valid": 0,
            "summary": {},
            "thresholds": [],
            "bins": [],
            "generated_at": now_text(),
            "na_reason": f"db_unavailable:{exc.__class__.__name__}",
        }

    spreads: List[float] = []
    total_rows = 0
    missing_spread = 0
    models_lt2 = 0
    event_count = 0

    def parse_model_count(row: Dict[str, Any]) -> Optional[int]:
        per_model = row.get("per_model_q")
        if isinstance(per_model, dict):
            return len(per_model)
        for key in ("model_dir_total", "model_total", "model_count"):
            val = row.get(key)
            try:
                if val is None:
                    continue
                num = int(val)
                if num >= 0:
                    return num
            except (TypeError, ValueError):
                continue
        return None

    for row in latest_rows:
        payload = safe_json_loads(row["fact_json"])
        distribution = normalize_distribution_rows(payload.get("distribution") or payload.get("rows") or [])
        if not distribution:
            continue
        event_count += 1
        for dist_row in distribution:
            total_rows += 1
            model_count = parse_model_count(dist_row)
            if model_count is not None and model_count < 2:
                models_lt2 += 1
                continue
            spread_val = to_float(dist_row.get("q_round_model_spread"))
            if spread_val is None:
                spread_val = to_float(dist_row.get("model_spread"))
            if spread_val is None:
                q_min = to_float(dist_row.get("q_min"))
                q_max = to_float(dist_row.get("q_max"))
                if q_min is not None and q_max is not None:
                    spread_val = q_max - q_min
            if spread_val is None or not math.isfinite(spread_val):
                missing_spread += 1
                continue
            if spread_val < 0:
                spread_val = 0.0
            spreads.append(float(spread_val))

    spreads_sorted = sorted(spreads)

    def percentile(values: List[float], pct: float) -> Optional[float]:
        if not values:
            return None
        if pct <= 0:
            return float(values[0])
        if pct >= 1:
            return float(values[-1])
        k = (len(values) - 1) * pct
        lo = int(math.floor(k))
        hi = int(math.ceil(k))
        if lo == hi:
            return float(values[lo])
        weight = k - lo
        return float(values[lo] + (values[hi] - values[lo]) * weight)

    count = len(spreads_sorted)
    total = float(sum(spreads_sorted)) if spreads_sorted else 0.0
    mean = (total / count) if count else None
    summary = {
        "count": count,
        "mean": mean,
        "min": float(spreads_sorted[0]) if count else None,
        "max": float(spreads_sorted[-1]) if count else None,
        "p25": percentile(spreads_sorted, 0.25),
        "p50": percentile(spreads_sorted, 0.50),
        "p75": percentile(spreads_sorted, 0.75),
        "p90": percentile(spreads_sorted, 0.90),
        "p95": percentile(spreads_sorted, 0.95),
    }

    thresholds: List[Dict[str, Any]] = []
    for limit in (0.10, 0.15, 0.20, 0.25):
        le_count = sum(1 for val in spreads_sorted if val <= limit)
        rate = (le_count / count) if count else None
        thresholds.append({"le": limit, "count": le_count, "rate": rate})

    bin_edges = [0.0, 0.05, 0.10, 0.15, 0.20, 0.25, 0.30, 0.40, 0.50, 1.00]
    bins: List[Dict[str, Any]] = []
    for idx in range(len(bin_edges) - 1):
        low = bin_edges[idx]
        high = bin_edges[idx + 1]
        if idx == len(bin_edges) - 2:
            bin_count = sum(1 for val in spreads_sorted if val >= low and val <= high)
        else:
            bin_count = sum(1 for val in spreads_sorted if val >= low and val < high)
        rate = (bin_count / count) if count else None
        bins.append({"range": [low, high], "count": bin_count, "rate": rate})

    payload = {
        "ok": True,
        "days": days,
        "events": event_count,
        "rows": total_rows,
        "valid": count,
        "missing_spread": missing_spread,
        "models_lt2": models_lt2,
        "summary": summary,
        "thresholds": thresholds,
        "bins": bins,
        "generated_at": now_text(),
    }
    with MODEL_SPREAD_CACHE_LOCK:
        MODEL_SPREAD_CACHE[days] = {"ts": now_ts, "payload": dict(payload)}
    return payload


def auto_trade_run_status() -> Dict[str, Any]:
    with AUTO_TRADE_RUN_LOCK:
        state = dict(AUTO_TRADE_RUN_STATE)
    try:
        jobs = _latest_auto_trade_jobs_snapshot(run_date=str(state.get("run_date") or ""))
    except Exception:
        jobs = {}
    if isinstance(jobs, dict) and isinstance(jobs.get("active"), dict):
        active = jobs.get("active") or {}
        active_state = str(active.get("state") or "").strip().lower()
        if active_state in {"queued", "running", "retrying"}:
            state["running"] = active_state in {"running", "retrying"}
            state["stage"] = f"job_{active_state}"
            state["run_date"] = str(active.get("run_date") or state.get("run_date") or "")
            state["started_at"] = str(active.get("started_at") or state.get("started_at") or "")
            state["progress_at"] = str(active.get("updated_at") or state.get("progress_at") or "")
    if isinstance(jobs, dict) and jobs:
        state["job_queue"] = jobs
    return state


def _latest_auto_trade_jobs_snapshot(run_date: str = "") -> Dict[str, Any]:
    run_date_key = _normalize_date_key(run_date)
    if scan_auto_trade_job_status is not None:
        try:
            payload = scan_auto_trade_job_status(run_date=run_date_key, limit=50)
            if isinstance(payload, dict):
                return payload
        except Exception:
            pass
    if not DB_PATH.exists():
        return {}
    out: Dict[str, Any] = {"ok": True, "run_date": run_date_key, "counts": {}, "active": {}, "items": []}
    with open_db_ro_fast(timeout_sec=0.2, busy_timeout_ms=200) as conn:
        cur = conn.cursor()
        where_sql = ""
        params: List[Any] = []
        if run_date_key:
            where_sql = "WHERE run_date = ?"
            params.append(run_date_key)
        try:
            cur.execute(
                f"""
                SELECT state, COUNT(*) AS cnt
                FROM auto_trade_jobs
                {where_sql}
                GROUP BY state
                """,
                tuple(params),
            )
            out["counts"] = {
                str(r["state"] or ""): int(r["cnt"] or 0) for r in (cur.fetchall() or [])
            }
        except sqlite3.Error:
            out["counts"] = {}
        try:
            cur.execute(
                f"""
                SELECT *
                FROM auto_trade_jobs
                {where_sql}
                ORDER BY created_at DESC, id DESC
                LIMIT 50
                """,
                tuple(params),
            )
            rows = cur.fetchall() or []
            items: List[Dict[str, Any]] = []
            for row in rows:
                item = {str(k): row[k] for k in row.keys()}
                items.append(item)
            out["items"] = items
            active = next(
                (
                    item
                    for item in items
                    if str(item.get("state") or "").strip().lower() in {"queued", "running", "retrying"}
                ),
                {},
            )
            out["active"] = active
        except sqlite3.Error:
            out["items"] = []
            out["active"] = {}
    return out


def _auto_trade_cleanup_stale_runs(now_dt: Optional[datetime] = None) -> Dict[str, Any]:
    now_dt = now_dt or datetime.now().astimezone()
    now_str = now_text()
    now_iso = utc_now_iso()
    stuck_sec = max(60, int(os.environ.get("PM_AUTO_TRADE_RUN_STUCK_SEC", "600") or 600))
    stuck_progress_sec = max(30, int(os.environ.get("PM_AUTO_TRADE_RUN_STUCK_PROGRESS_SEC", "120") or 120))
    cleaned = {"state_reset": False, "db_rows": 0, "stuck_jobs": 0}
    run_id = None
    with AUTO_TRADE_RUN_LOCK:
        state = dict(AUTO_TRADE_RUN_STATE)
        if state.get("running"):
            started_at = str(state.get("started_at") or "").strip()
            started_dt = parse_any_ts(started_at)
            age_sec = None
            if started_dt is not None:
                try:
                    age_sec = (now_dt - started_dt).total_seconds()
                except Exception:
                    age_sec = None
            progress_at = str(state.get("progress_at") or "").strip()
            progress_dt = parse_any_ts(progress_at) if progress_at else None
            progress_age_sec = None
            if progress_dt is not None:
                try:
                    progress_age_sec = (now_dt - progress_dt).total_seconds()
                except Exception:
                    progress_age_sec = None
            is_stuck = False
            if age_sec is not None and age_sec >= stuck_sec:
                is_stuck = True
            if progress_age_sec is not None and progress_age_sec >= stuck_progress_sec:
                is_stuck = True
            if is_stuck:
                AUTO_TRADE_RUN_STATE["running"] = False
                AUTO_TRADE_RUN_STATE["ended_at"] = now_str
                parts = ["stuck_timeout"]
                if age_sec is not None:
                    parts.append(f"age_sec={int(age_sec)}")
                if progress_age_sec is not None:
                    parts.append(f"progress_sec={int(progress_age_sec)}")
                AUTO_TRADE_RUN_STATE["error"] = " ".join(parts)
                AUTO_TRADE_RUN_STATE["stage"] = "stuck_timeout"
                AUTO_TRADE_RUN_STATE["progress_at"] = AUTO_TRADE_RUN_STATE["ended_at"]
                run_id = state.get("run_id")
                cleaned["state_reset"] = True
    if run_id and DB_PATH.exists():
        try:
            with open_db(timeout_sec=0.2, busy_timeout_ms=200) as conn:
                cur = conn.cursor()
                cur.execute(
                    "UPDATE auto_trade_runs SET ended_at=?, ok=0, error=? WHERE id=?",
                    (now_iso, AUTO_TRADE_RUN_STATE.get("error") or "stuck_timeout", int(run_id)),
                )
                conn.commit()
        except Exception:
            pass
    if DB_PATH.exists():
        try:
            cutoff = (datetime.now(timezone.utc) - timedelta(seconds=stuck_sec)).isoformat(timespec="seconds")
            with open_db(timeout_sec=0.2, busy_timeout_ms=200) as conn:
                cur = conn.cursor()
                cur.execute(
                    """
                    UPDATE auto_trade_runs
                    SET
                      ended_at = COALESCE(
                        (
                          SELECT MAX(COALESCE(j.ended_at, j.updated_at, j.started_at, j.created_at))
                          FROM auto_trade_jobs j
                          WHERE (
                            j.run_id = auto_trade_runs.id
                            OR (
                              j.run_id IS NULL
                              AND j.run_date = auto_trade_runs.run_date
                              AND auto_trade_runs.started_at != ''
                              AND j.created_at >= auto_trade_runs.started_at
                            )
                          )
                        ),
                        ?
                      ),
                      ok = CASE
                        WHEN EXISTS (
                          SELECT 1
                          FROM auto_trade_jobs j
                          WHERE (
                            j.run_id = auto_trade_runs.id
                            OR (
                              j.run_id IS NULL
                              AND j.run_date = auto_trade_runs.run_date
                              AND auto_trade_runs.started_at != ''
                              AND j.created_at >= auto_trade_runs.started_at
                            )
                          )
                            AND lower(COALESCE(j.state, '')) = 'stuck'
                        ) THEN 0
                        WHEN ok IS NULL THEN 1
                        ELSE ok
                      END,
                      error = CASE
                        WHEN EXISTS (
                          SELECT 1
                          FROM auto_trade_jobs j
                          WHERE (
                            j.run_id = auto_trade_runs.id
                            OR (
                              j.run_id IS NULL
                              AND j.run_date = auto_trade_runs.run_date
                              AND auto_trade_runs.started_at != ''
                              AND j.created_at >= auto_trade_runs.started_at
                            )
                          )
                            AND lower(COALESCE(j.state, '')) = 'stuck'
                        ) THEN CASE
                          WHEN TRIM(COALESCE(error, '')) != '' THEN error
                          ELSE 'worker_stuck'
                        END
                        ELSE error
                      END
                    WHERE (ended_at IS NULL OR ended_at = '')
                      AND started_at != ''
                      AND started_at <= ?
                      AND EXISTS (
                        SELECT 1
                        FROM auto_trade_jobs j
                        WHERE (
                          j.run_id = auto_trade_runs.id
                          OR (
                            j.run_id IS NULL
                            AND j.run_date = auto_trade_runs.run_date
                            AND auto_trade_runs.started_at != ''
                            AND j.created_at >= auto_trade_runs.started_at
                          )
                        )
                      )
                      AND NOT EXISTS (
                        SELECT 1
                        FROM auto_trade_jobs j
                        WHERE (
                          j.run_id = auto_trade_runs.id
                          OR (
                            j.run_id IS NULL
                            AND j.run_date = auto_trade_runs.run_date
                            AND auto_trade_runs.started_at != ''
                            AND j.created_at >= auto_trade_runs.started_at
                          )
                        )
                          AND lower(COALESCE(j.state, '')) IN ('queued', 'running', 'retrying')
                      )
                    """,
                    (now_iso, cutoff),
                )
                recovered_rows = int(cur.rowcount or 0)
                cur.execute(
                    """
                    UPDATE auto_trade_runs
                    SET ended_at=?, ok=0, error=?
                    WHERE (ended_at IS NULL OR ended_at = '')
                      AND started_at != ''
                      AND started_at <= ?
                      AND (
                        NOT EXISTS (
                          SELECT 1
                          FROM auto_trade_jobs j
                          WHERE (
                            j.run_id = auto_trade_runs.id
                            OR (
                              j.run_id IS NULL
                              AND j.run_date = auto_trade_runs.run_date
                              AND auto_trade_runs.started_at != ''
                              AND j.created_at >= auto_trade_runs.started_at
                            )
                          )
                        )
                        OR EXISTS (
                          SELECT 1
                          FROM auto_trade_jobs j
                          WHERE (
                            j.run_id = auto_trade_runs.id
                            OR (
                              j.run_id IS NULL
                              AND j.run_date = auto_trade_runs.run_date
                              AND auto_trade_runs.started_at != ''
                              AND j.created_at >= auto_trade_runs.started_at
                            )
                          )
                            AND lower(COALESCE(j.state, '')) IN ('queued', 'running', 'retrying')
                        )
                      )
                    """,
                    (now_iso, f"stale_timeout age>={int(stuck_sec)}s", cutoff),
                )
                stale_rows = int(cur.rowcount or 0)
                stuck_count = mark_stale_auto_trade_jobs_stuck(
                    cur,
                    now_iso=now_iso,
                    cutoff_iso=cutoff,
                )
                conn.commit()
                cleaned["db_rows"] = recovered_rows + stale_rows
                cleaned["stuck_jobs"] = int(stuck_count or 0)
        except Exception:
            pass
    return cleaned


def _auto_trade_load_rows_direct(
    run_date: str,
    allow_backfill: bool,
) -> Tuple[Optional[str], List[Dict[str, Any]], Optional[str]]:
    db_cm = open_db if allow_backfill else lambda: open_db_ro_fast(timeout_sec=0.2, busy_timeout_ms=0)
    with db_cm() as conn:
        resolved_date = run_date
        if not resolved_date:
            resolved_date = latest_unsettled_run_date(conn) or latest_fact_run_date(conn) or latest_run_date(conn)
        if not resolved_date:
            return None, [], "no_run_date"
        if allow_backfill:
            try:
                ensure_fact_tables(conn)
            except Exception:
                return None, [], "facts_unavailable"
        run_date_key_local = _normalize_date_key(resolved_date)
        if not run_date_key_local:
            return None, [], "no_run_date"
        if allow_backfill:
            try:
                _backfill_facts_if_needed(conn, run_date_key_local, include_history=False)
            except sqlite3.OperationalError:
                pass
        try:
            rows_local = select_event_fact_rows_latest(conn, run_date_key_local)
        except sqlite3.OperationalError:
            return None, [], "facts_unavailable_busy"
        rows_out: List[Dict[str, Any]] = []
        for row in rows_local:
            rows_out.append(
                {
                    "slug": row["slug"],
                    "event_date": row["event_date"],
                    "fact_json": row["fact_json"],
                }
            )
        return run_date_key_local, rows_out, None


def _auto_trade_event_worker(
    run_date_key: str,
    event_date_key: str,
    payload: Dict[str, Any],
    exit_only: bool,
    run_id: Optional[int],
    queue: multiprocessing.Queue,
    event_timeout_sec: float = 60.0,
) -> None:
    stack_dump_fh: Optional[Any] = None
    dump_stack_on_timeout = _env_bool("PM_AUTO_TRADE_EVENT_WORKER_DUMP_STACK_ON_TIMEOUT", True)
    try:
        if dump_stack_on_timeout and event_timeout_sec and event_timeout_sec > 5:
            try:
                log_path = DATA_DIR / "auto_trade_worker_timeout_stacks.log"
                stack_dump_fh = open(log_path, "a", encoding="utf-8")
                stack_dump_fh.write(
                    f"\n=== {utc_now_iso()} slug={str(payload.get('slug') or '')} "
                    f"event_date={event_date_key} timeout={float(event_timeout_sec):.1f}s ===\n"
                )
                stack_dump_fh.flush()
                faulthandler.dump_traceback_later(
                    max(3.0, float(event_timeout_sec) - 3.0),
                    repeat=False,
                    file=stack_dump_fh,
                )
            except Exception:
                stack_dump_fh = None
        timeout_cap_ms_raw = str(
            os.environ.get("PM_AUTO_TRADE_EVENT_WORKER_CLOB_TIMEOUT_MS", "") or ""
        ).strip()
        timeout_cap_ms = 0
        if timeout_cap_ms_raw:
            try:
                timeout_cap_ms = int(float(timeout_cap_ms_raw))
            except Exception:
                timeout_cap_ms = 0
        if timeout_cap_ms <= 0:
            timeout_cap_ms = int(
                max(4000, min(20000, max(5.0, float(event_timeout_sec or 60.0)) * 1000 * 0.25))
            )
        clob_timeout_raw = str(os.environ.get("PM_CLOB_TIMEOUT_MS", "") or "").strip()
        clob_timeout_ms = 0
        if clob_timeout_raw:
            try:
                clob_timeout_ms = int(float(clob_timeout_raw))
            except Exception:
                clob_timeout_ms = 0
        if clob_timeout_ms <= 0 or clob_timeout_ms > timeout_cap_ms:
            os.environ["PM_CLOB_TIMEOUT_MS"] = str(timeout_cap_ms)
        allow_direct_fallback = str(
            os.environ.get("PM_AUTO_TRADE_EVENT_WORKER_ALLOW_DIRECT_FALLBACK", "1") or ""
        ).strip().lower() in {"1", "true", "yes", "on"}
        force_proxy = str(os.environ.get("PM_CLOB_FORCE_PROXY", "") or "").strip().lower() in {
            "1",
            "true",
            "yes",
            "on",
        }
        force_direct = str(os.environ.get("PM_CLOB_FORCE_DIRECT", "") or "").strip().lower() in {
            "1",
            "true",
            "yes",
            "on",
        }
        if allow_direct_fallback and force_proxy and not force_direct:
            os.environ["PM_CLOB_FORCE_PROXY"] = "0"
            os.environ.setdefault("PM_CLOB_DIRECT_FIRST", "1")
            os.environ.setdefault("PM_CLOB_DIRECT_RETRIES", "1")
            os.environ.setdefault("PM_CLOB_RETRY_MAX", "1")
        # Spawned workers do not share in-process sync cooldown state; disable sync-by-trades
        # by default to avoid each event paying the full network sync cost and hitting timeout.
        worker_sync_trades = str(
            os.environ.get("PM_AUTO_TRADE_EVENT_WORKER_SYNC_TRADES", "0") or ""
        ).strip().lower() in {"1", "true", "yes", "on"}
        if not worker_sync_trades:
            os.environ["PM_AUTO_TRADE_SYNC_TRADES"] = "0"
        worker_sync_open_orders = str(
            os.environ.get("PM_AUTO_TRADE_EVENT_WORKER_SYNC_OPEN_ORDERS", "0") or ""
        ).strip().lower() in {"1", "true", "yes", "on"}
        if not worker_sync_open_orders:
            os.environ["PM_AUTO_TRADE_SYNC_OPEN_ORDERS"] = "0"
        worker_live_volume_gate = str(
            os.environ.get("PM_AUTO_TRADE_EVENT_WORKER_LIVE_VOLUME_GATE", "0") or ""
        ).strip().lower() in {"1", "true", "yes", "on"}
        if not worker_live_volume_gate:
            # Keep outcome-volume risk control, but avoid per-event live refresh network calls in workers.
            os.environ["PM_AUTO_TRADE_ENTRY_OUTCOME_VOLUME_GATE_MODE"] = "pre"
        worker_db_connect_timeout_sec_raw = str(
            os.environ.get("PM_AUTO_TRADE_EVENT_WORKER_DB_CONNECT_TIMEOUT_SEC", "") or ""
        ).strip()
        worker_db_connect_timeout_sec = 0.25
        if worker_db_connect_timeout_sec_raw:
            try:
                worker_db_connect_timeout_sec = float(worker_db_connect_timeout_sec_raw)
            except Exception:
                worker_db_connect_timeout_sec = 0.25
        if not math.isfinite(worker_db_connect_timeout_sec) or worker_db_connect_timeout_sec < 0:
            worker_db_connect_timeout_sec = 0.25
        worker_db_connect_timeout_sec = min(float(worker_db_connect_timeout_sec), 5.0)
        os.environ["PM_DB_CONNECT_TIMEOUT_SEC"] = f"{worker_db_connect_timeout_sec:.3f}"
        worker_db_busy_timeout_ms_raw = str(
            os.environ.get("PM_AUTO_TRADE_EVENT_WORKER_DB_BUSY_TIMEOUT_MS", "") or ""
        ).strip()
        worker_db_busy_timeout_ms = 250
        if worker_db_busy_timeout_ms_raw:
            try:
                worker_db_busy_timeout_ms = int(float(worker_db_busy_timeout_ms_raw))
            except Exception:
                worker_db_busy_timeout_ms = 250
        if worker_db_busy_timeout_ms < 0:
            worker_db_busy_timeout_ms = 250
        worker_db_busy_timeout_ms = min(int(worker_db_busy_timeout_ms), 5000)
        os.environ["PM_DB_BUSY_TIMEOUT_MS"] = str(worker_db_busy_timeout_ms)
        scan_execute_auto_trades(
            run_date_key,
            event_date_key,
            payload,
            exit_only=exit_only,
            run_id=run_id,
        )
        queue.put({"ok": True})
    except Exception as exc:
        queue.put({"ok": False, "error": str(exc)})
    finally:
        if dump_stack_on_timeout:
            try:
                faulthandler.cancel_dump_traceback_later()
            except Exception:
                pass
        if stack_dump_fh is not None:
            try:
                stack_dump_fh.close()
            except Exception:
                pass


def services_health() -> Dict[str, Any]:
    """Backend/runtime health for LaunchAgents + DB freshness (UI SSOT)."""
    t0 = time.monotonic()
    labels = _launchd_health_labels()
    launch_map: Dict[str, Any] = {}
    launch_ok = False
    launch_error = ""
    launch_ms = 0.0
    launchctl_bin = "/bin/launchctl" if Path("/bin/launchctl").exists() else "launchctl"
    global _SERVICES_LAUNCHCTL_CACHE
    cache = _SERVICES_LAUNCHCTL_CACHE
    cache_age = time.monotonic() - float(cache.get("ts") or 0.0)
    if cache_age >= 0 and cache_age < float(cache.get("ttl_sec") or 2.0) and isinstance(cache.get("payload"), dict):
        cached_payload = dict(cache["payload"])
        launch_ok = bool(cache.get("ok"))
        launch_error = str(cache.get("error") or "")
        launch_map = cached_payload
    else:
        t_launch = time.monotonic()
        try:
            res = subprocess.run(
                [launchctl_bin, "list"],
                capture_output=True,
                text=True,
                timeout=2.5,
                check=False,
            )
            if res.returncode == 0:
                launch_ok = True
                for line in (res.stdout or "").splitlines():
                    parts = line.strip().split(None, 2)
                    if len(parts) != 3:
                        continue
                    pid_raw, status_raw, label = parts
                    if label not in labels:
                        continue
                    pid = None
                    if pid_raw and pid_raw != "-" and pid_raw.isdigit():
                        pid = int(pid_raw)
                    status = None
                    try:
                        status = int(status_raw)
                    except (TypeError, ValueError):
                        status = None
                    launch_map[label] = {"pid": pid, "status": status}
            else:
                launch_ok = False
                launch_error = (res.stderr or res.stdout or "").strip() or f"launchctl list exit={res.returncode}"
        except Exception as exc:
            launch_ok = False
            launch_error = str(exc)
        launch_ms = (time.monotonic() - t_launch) * 1000.0
        # launchctl list may report "-" even when the service is running.
        if launch_ok:
            # Only long-running KeepAlive agents need pid backfill via `launchctl print`.
            # Scheduled one-shot jobs often have no pid and can make `launchctl print` slow.
            print_pid_labels = {
                "com.xiong.weather.ui",
                "com.weather.market_ws",
                "com.weather.trade_engine",
                "com.weather.auto_trade_worker",
                "com.weather.trade_sync_loop",
            }
            print_pid_labels.update(
                label for label in _auto_trade_watcher_labels() if label and not label.startswith("system/")
            )
            print_timeout_sec = _env_float("PM_SERVICES_LAUNCHCTL_PRINT_TIMEOUT_SEC", 0.35)
            if print_timeout_sec is None or not math.isfinite(print_timeout_sec):
                print_timeout_sec = 0.35
            print_timeout_sec = max(0.1, min(float(print_timeout_sec), 2.0))
            def _launchctl_print_pid(label: str) -> Optional[int]:
                uid = os.getuid()
                candidate_uids = [uid]
                if uid == 0:
                    try:
                        console_uid = os.stat("/dev/console").st_uid
                        if isinstance(console_uid, int):
                            candidate_uids.append(console_uid)
                    except Exception:
                        pass
                    try:
                        user = os.environ.get("SUDO_USER") or os.environ.get("LOGNAME") or os.environ.get("USER")
                        if user:
                            import pwd

                            candidate_uids.append(pwd.getpwnam(user).pw_uid)
                    except Exception:
                        pass
                seen = set()
                for candidate_uid in candidate_uids:
                    if candidate_uid in seen:
                        continue
                    seen.add(candidate_uid)
                    try:
                        out = subprocess.run(
                            [launchctl_bin, "print", f"gui/{candidate_uid}/{label}"],
                            capture_output=True,
                            text=True,
                            timeout=print_timeout_sec,
                            check=False,
                        )
                    except Exception:
                        continue
                    if out.returncode != 0:
                        continue
                    pid = None
                    state_running = False
                    for line in (out.stdout or "").splitlines():
                        line = line.strip()
                        if line.startswith("state ="):
                            state_running = "running" in line
                        if line.startswith("pid ="):
                            m = re.search(r"pid\\s*=\\s*(\\d+)", line)
                            if m:
                                pid = int(m.group(1))
                    if state_running and isinstance(pid, int) and pid > 0:
                        return pid
                return None

            for label in labels:
                if label not in print_pid_labels:
                    continue
                row = launch_map.get(label)
                if not isinstance(row, dict):
                    row = {"pid": None, "status": None}
                    launch_map[label] = row
                if row.get("pid") is None:
                    pid = _launchctl_print_pid(label)
                    if isinstance(pid, int) and pid > 0:
                        row["pid"] = pid

            monitor_system_label = _auto_trade_watcher_system_label()
            if monitor_system_label:
                try:
                    monitor_out = subprocess.run(
                        [launchctl_bin, "print", monitor_system_label],
                        capture_output=True,
                        text=True,
                        timeout=print_timeout_sec,
                        check=False,
                    )
                    if monitor_out.returncode == 0:
                        monitor_status = ""
                        monitor_pid = None
                        for line in (monitor_out.stdout or "").splitlines():
                            line = line.strip()
                            if line.startswith("state ="):
                                monitor_status = line.split("=", 1)[1].strip()
                            elif line.startswith("pid ="):
                                m = re.search(r"pid\s*=\s*(\d+)", line)
                                if m:
                                    monitor_pid = int(m.group(1))
                        launch_map[monitor_system_label] = {
                            "pid": monitor_pid,
                            "status": 0 if monitor_status == "running" and monitor_pid else -1,
                            "label": monitor_system_label,
                            "state": monitor_status,
                        }
                except Exception:
                    pass
        _SERVICES_LAUNCHCTL_CACHE = {
            "ts": time.monotonic(),
            "ttl_sec": float(cache.get("ttl_sec") or 2.0),
            "ok": bool(launch_ok),
            "error": str(launch_error or ""),
            "payload": dict(launch_map),
        }

    # Infer LaunchAgent enabled/disabled state (launchctl disable doesn't necessarily unload the job).
    launchd_disabled_subset: Dict[str, str] = {}
    if launch_ok:
        global _SERVICES_LAUNCHCTL_DISABLED_CACHE
        dcache = _SERVICES_LAUNCHCTL_DISABLED_CACHE
        d_age = time.monotonic() - float(dcache.get("ts") or 0.0)
        d_ttl = float(dcache.get("ttl_sec") or 10.0)
        disabled_map: Dict[str, str] = {}
        if d_age >= 0 and d_age < d_ttl and isinstance(dcache.get("payload"), dict):
            disabled_map = dict(dcache.get("payload") or {})
        else:
            try:
                uid = os.getuid()
                out = subprocess.run(
                    [launchctl_bin, "print-disabled", f"gui/{uid}"],
                    capture_output=True,
                    text=True,
                    timeout=0.55,
                    check=False,
                )
                if out.returncode == 0:
                    for line in (out.stdout or "").splitlines():
                        m = re.search(r'"([^"]+)"\s*=>\s*(enabled|disabled)', line)
                        if not m:
                            continue
                        disabled_map[str(m.group(1) or "").strip()] = str(m.group(2) or "").strip().lower()
                    _SERVICES_LAUNCHCTL_DISABLED_CACHE = {
                        "ts": time.monotonic(),
                        "ttl_sec": d_ttl,
                        "ok": True,
                        "error": "",
                        "payload": dict(disabled_map),
                    }
                else:
                    _SERVICES_LAUNCHCTL_DISABLED_CACHE = {
                        "ts": time.monotonic(),
                        "ttl_sec": d_ttl,
                        "ok": False,
                        "error": (out.stderr or out.stdout or "").strip() or f"print-disabled exit={out.returncode}",
                        "payload": {},
                    }
            except Exception as exc:
                _SERVICES_LAUNCHCTL_DISABLED_CACHE = {
                    "ts": time.monotonic(),
                    "ttl_sec": d_ttl,
                    "ok": False,
                    "error": str(exc),
                    "payload": {},
                }
        # Attach per-label enabled flag for UI switches.
        for label in labels:
            state = str(disabled_map.get(label) or "").strip().lower()
            if state:
                launchd_disabled_subset[label] = state
            row = launch_map.get(label)
            if isinstance(row, dict):
                pid = row.get("pid")
                active_pid = isinstance(pid, int) and pid > 0
                if active_pid:
                    row["enabled"] = True
                elif state == "disabled":
                    row["enabled"] = False
                elif state == "enabled":
                    row["enabled"] = True

    def _mtime_iso(path: Path) -> str:
        try:
            ts = path.stat().st_mtime
        except OSError:
            return ""
        return datetime.fromtimestamp(ts).astimezone().isoformat()

    repo = Path(__file__).resolve().parents[1]
    logs = {
        "market_refresh": str(repo / "data/market_refresh.log"),
        "market_ws": str(repo / "data/market_ws.log"),
        "model_scan": str(repo / "data/model_scan.log"),
        "auto_trade_entry": str(repo / "data/logs/auto_trade_entry_1m.log"),
        "trade_engine": str(repo / "data/logs/trade_engine.log"),
        "auto_trade_worker": str(repo / "data/logs/auto_trade_worker.log"),
        "auto_trade_watcher": str(repo / "data/logs/auto_trade_watcher.out.log"),
        "trade_sync_loop": str(repo / "data/logs/trade_sync_loop.out.log"),
        "ui_server_out": str(repo / "data/ui_server.out.log"),
        "ui_server_err": str(repo / "data/ui_server.err.log"),
    }
    log_stats: Dict[str, Any] = {}
    t_logs = time.monotonic()
    for key, raw in logs.items():
        p = Path(raw)
        log_stats[key] = {"path": raw, "mtime": _mtime_iso(p)}
    logs_ms = (time.monotonic() - t_logs) * 1000.0

    db_stats: Dict[str, Any] = {}
    t_db = time.monotonic()
    if DB_PATH.exists():
        try:
            # Keep /api/services fast and robust even when the DB is under write load.
            with open_db_ro_fast(timeout_sec=0.2, busy_timeout_ms=200) as conn:
                cur = conn.cursor()
                def _fetch_ts(sql: str) -> str:
                    try:
                        cur.execute(sql)
                    except sqlite3.Error:
                        return ""
                    row = cur.fetchone()
                    if not row:
                        return ""
                    try:
                        keys = set(row.keys()) if hasattr(row, "keys") else set()
                        if "ts" in keys:
                            return str(row["ts"] or "")
                    except Exception:
                        pass
                    return str(row[0] or "") if len(row) else ""

                db_stats["last_market_tick_at"] = _fetch_ts(
                    """
                    SELECT created_at AS ts
                    FROM event_market_ticks
                    WHERE created_at IS NOT NULL AND created_at != ''
                    ORDER BY id DESC
                    LIMIT 1
                    """
                )
                db_stats["last_fact_as_of"] = _fetch_ts("SELECT MAX(fact_as_of) AS ts FROM event_fact_history")
                db_stats["last_event_run_at"] = _fetch_ts("SELECT MAX(created_at) AS ts FROM event_runs")
                try:
                    db_stats["last_auto_order_at"] = _fetch_ts("SELECT MAX(created_at) AS ts FROM auto_orders")
                except sqlite3.Error:
                    db_stats["last_auto_order_at"] = ""
        except Exception as exc:
            db_stats["_error"] = str(exc)
    db_ms = (time.monotonic() - t_db) * 1000.0

    def _age_sec(ts_text: str) -> Optional[float]:
        ts_text = str(ts_text or "").strip()
        if not ts_text:
            return None
        dt = parse_iso_ts(ts_text)
        if dt is None:
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=timezone.utc)
        now_dt = datetime.now(timezone.utc)
        return max(0.0, (now_dt - dt).total_seconds())

    def _log_age_sec(key: str) -> Optional[float]:
        entry = log_stats.get(key) if isinstance(log_stats, dict) else None
        ts_text = entry.get("mtime") if isinstance(entry, dict) else ""
        return _age_sec(ts_text)

    def _read_json_file(path: Path) -> Dict[str, Any]:
        try:
            payload = json.loads(path.read_text(encoding="utf-8"))
        except Exception:
            return {}
        return payload if isinstance(payload, dict) else {}

    def _env_int_local(name: str, default: Optional[int] = None) -> Optional[int]:
        raw = str(os.environ.get(name, "") or "").strip()
        if not raw:
            return default
        try:
            return int(float(raw))
        except (TypeError, ValueError):
            return default

    watcher_log_age = _log_age_sec("auto_trade_watcher")
    trade_engine_log_age = _log_age_sec("trade_engine")
    worker_log_age = _log_age_sec("auto_trade_worker")
    sync_log_age = _log_age_sec("trade_sync_loop")
    watcher_recent = watcher_log_age is not None and watcher_log_age <= 300
    trade_engine_recent = trade_engine_log_age is not None and trade_engine_log_age <= 300
    worker_recent = worker_log_age is not None and worker_log_age <= 300
    sync_recent = sync_log_age is not None and sync_log_age <= 300
    trade_sync_status = load_trade_sync_status()
    def _trade_sync_recent(status: Any) -> bool:
        if not isinstance(status, dict):
            return False
        ts_text = str(status.get("last_ok_at") or status.get("last_attempt_at") or "").strip()
        age = _age_sec(ts_text)
        return age is not None and age <= 600
    sync_status_recent = _trade_sync_recent(trade_sync_status)

    reasons: List[str] = []
    issues: List[Dict[str, Any]] = []
    fd_usage = get_fd_usage()

    def _add_issue(code: str, severity: str, message: str, evidence: Optional[Dict[str, Any]] = None) -> None:
        issues.append(
            {
                "code": str(code or ""),
                "severity": str(severity or "warn"),
                "message": str(message or ""),
                "evidence": evidence or {},
            }
        )

    def _pid_for(label: str) -> Optional[int]:
        row = launch_map.get(label) if isinstance(launch_map, dict) else None
        pid = row.get("pid") if isinstance(row, dict) else None
        if isinstance(pid, int) and pid > 0:
            return pid
        return None

    def _status_for(label: str) -> Optional[int]:
        row = launch_map.get(label) if isinstance(launch_map, dict) else None
        status = row.get("status") if isinstance(row, dict) else None
        if isinstance(status, int):
            return status
        if isinstance(status, str):
            try:
                return int(status)
            except Exception:
                if status == "running":
                    return 0
        return None

    fd_guard = _evaluate_fd_guard(
        launch_map=launch_map,
        fd_usage=fd_usage if isinstance(fd_usage, dict) else {},
        launchctl_bin=launchctl_bin,
    )
    for item in list(fd_guard.get("issues") or []):
        if not isinstance(item, dict):
            continue
        _add_issue(
            str(item.get("code") or "fd_guard"),
            str(item.get("severity") or "warn"),
            str(item.get("message") or ""),
            item.get("evidence") if isinstance(item.get("evidence"), dict) else {},
        )
    for reason in list(fd_guard.get("reasons") or []):
        text = str(reason or "").strip()
        if text and text not in reasons:
            reasons.append(text)
    fd_degrade = _update_fd_degrade(fd_guard if isinstance(fd_guard, dict) else {})
    for item in list(fd_degrade.get("issues") or []):
        if not isinstance(item, dict):
            continue
        _add_issue(
            str(item.get("code") or "fd_degrade"),
            str(item.get("severity") or "warn"),
            str(item.get("message") or ""),
            item.get("evidence") if isinstance(item.get("evidence"), dict) else {},
        )
    for reason in list(fd_degrade.get("reasons") or []):
        text = str(reason or "").strip()
        if text and text not in reasons:
            reasons.append(text)

    # Always-on daemons should have a pid (KeepAlive=true).
    if launch_ok:
        ui_pid = _pid_for("com.xiong.weather.ui")
        if ui_pid is None:
            reasons.append("UI 服务未运行")
            _add_issue("ui_not_running", "error", "UI LaunchAgent 未运行", {"label": "com.xiong.weather.ui"})
        market_ws_pid = _pid_for("com.weather.market_ws")
        market_ws_enabled = True
        try:
            market_ws_row = launch_map.get("com.weather.market_ws")
            if isinstance(market_ws_row, dict) and market_ws_row.get("enabled") is False:
                market_ws_enabled = False
        except Exception:
            market_ws_enabled = True
        market_ws_preferred = _env_bool("PM_MARKET_REFRESH_WS_PREFERRED", True)
        market_ws_hb_path = Path(
            os.environ.get("PM_MARKET_WS_HEARTBEAT_PATH", str(DATA_DIR / "market_ws_heartbeat.json"))
        )
        market_ws_hb = _read_json_file(market_ws_hb_path)
        market_ws_hb_age = _age_sec(str(market_ws_hb.get("updated_at") or ""))
        market_ws_max_age = _env_int_local("PM_HEALTH_MARKET_WS_HEARTBEAT_STALE_SEC")
        if market_ws_max_age is None or market_ws_max_age <= 0:
            market_ws_max_age = _env_int_local("PM_MARKET_WS_HEARTBEAT_MAX_AGE_SEC")
        if market_ws_max_age is None or market_ws_max_age <= 0:
            market_ws_max_age = 20
        if market_ws_preferred and not market_ws_enabled:
            _add_issue(
                "market_ws_disabled",
                "info",
                "market WebSocket 已禁用，market_refresh 将更多依赖 REST",
                {"label": "com.weather.market_ws"},
            )
        elif market_ws_preferred and market_ws_pid is None:
            reasons.append("market WebSocket 未运行")
            _add_issue(
                "market_ws_not_running",
                "warn",
                "market WebSocket LaunchAgent 未运行，盘口刷新会回退 REST",
                {"label": "com.weather.market_ws", "heartbeat_age_sec": market_ws_hb_age},
            )
        elif market_ws_preferred:
            if not market_ws_hb:
                reasons.append("market WebSocket 无心跳")
                _add_issue(
                    "market_ws_heartbeat_missing",
                    "warn",
                    "market WebSocket 心跳文件缺失或不可读，market_refresh 不应按 WS 跳过 REST",
                    {"path": str(market_ws_hb_path)},
                )
            elif not bool(market_ws_hb.get("ok")):
                market_tick_age_sec = _age_sec(
                    db_stats.get("last_market_tick_at") if isinstance(db_stats, dict) else ""
                )
                market_ws_error_grace_sec = _env_int_local("PM_HEALTH_MARKET_WS_ERROR_GRACE_SEC")
                if market_ws_error_grace_sec is None or market_ws_error_grace_sec <= 0:
                    market_ws_error_grace_sec = max(60, int(market_ws_max_age) * 2)
                ticks_fresh_during_ws_error = (
                    market_tick_age_sec is not None
                    and market_tick_age_sec <= float(market_ws_error_grace_sec)
                )
                if ticks_fresh_during_ws_error:
                    try:
                        row = launch_map.get("com.weather.market_ws")
                        if isinstance(row, dict):
                            row["heartbeat_degraded"] = {
                                "status": str(market_ws_hb.get("status") or ""),
                                "error": str(market_ws_hb.get("error") or ""),
                                "heartbeat_age_sec": market_ws_hb_age,
                                "latest_tick_age_sec": market_tick_age_sec,
                                "grace_sec": int(market_ws_error_grace_sec),
                            }
                    except Exception:
                        pass
                else:
                    reasons.append("market WebSocket 心跳报错")
                    _add_issue(
                        "market_ws_heartbeat_error",
                        "warn",
                        "market WebSocket 心跳显示错误，market_refresh 不应按 WS 跳过 REST",
                        {
                            "path": str(market_ws_hb_path),
                            "status": str(market_ws_hb.get("status") or ""),
                            "error": str(market_ws_hb.get("error") or ""),
                            "heartbeat_age_sec": market_ws_hb_age,
                            "latest_tick_age_sec": market_tick_age_sec,
                            "grace_sec": int(market_ws_error_grace_sec),
                        },
                    )
            elif market_ws_hb_age is None or market_ws_hb_age > float(market_ws_max_age):
                reasons.append("market WebSocket 心跳陈旧")
                _add_issue(
                    "market_ws_heartbeat_stale",
                    "warn",
                    "market WebSocket 心跳已陈旧，market_refresh 不应按 WS 跳过 REST",
                    {
                        "path": str(market_ws_hb_path),
                        "heartbeat_age_sec": market_ws_hb_age,
                        "max_age_sec": int(market_ws_max_age),
                    },
                )
            try:
                row = launch_map.get("com.weather.market_ws")
                if isinstance(row, dict):
                    row["heartbeat"] = {
                        "ok": bool(market_ws_hb.get("ok")) if market_ws_hb else False,
                        "status": str(market_ws_hb.get("status") or "") if market_ws_hb else "",
                        "updated_at": str(market_ws_hb.get("updated_at") or "") if market_ws_hb else "",
                        "age_sec": market_ws_hb_age,
                        "max_age_sec": int(market_ws_max_age),
                        "assets": market_ws_hb.get("assets") if market_ws_hb else None,
                        "shards": market_ws_hb.get("shards") if market_ws_hb else None,
                    }
            except Exception:
                pass
        watcher_pid = None
        watcher_label = _auto_trade_watcher_system_label()
        for label in _auto_trade_watcher_labels():
            if label == watcher_label and label.startswith("system/"):
                continue
            pid = _pid_for(label)
            if pid is not None:
                watcher_pid = pid
                break
        if watcher_pid is None:
            watcher_pid = _pid_for(watcher_label)
        if watcher_pid is None and not watcher_recent:
            reasons.append("auto-trade watcher 未运行")
            _add_issue(
                "auto_trade_watcher_not_running",
                "error",
                "auto-trade watcher 未运行",
                {"label": watcher_label, "log_age_sec": watcher_log_age, "candidates": _auto_trade_watcher_labels()},
            )
        trade_engine_pid = _pid_for("com.weather.trade_engine")
        trade_engine_active = trade_engine_pid is not None or trade_engine_recent
        worker_pid = _pid_for("com.weather.auto_trade_worker")
        if (not trade_engine_active) and worker_pid is None and not worker_recent:
            reasons.append("auto-trade worker 未运行")
            _add_issue(
                "auto_trade_worker_not_running",
                "error",
                "auto-trade worker LaunchAgent 未运行",
                {"label": "com.weather.auto_trade_worker", "log_age_sec": worker_log_age},
            )
        sync_pid = _pid_for("com.weather.trade_sync_loop")
        if (not trade_engine_active) and sync_pid is None and not sync_recent and not sync_status_recent:
            reasons.append("交易同步驱动未运行")
            _add_issue(
                "trade_sync_loop_not_running",
                "error",
                "交易同步驱动未运行（unified trade_engine 与 legacy trade_sync_loop 均无新鲜心跳）",
                {
                    "label": "com.weather.trade_engine",
                    "legacy_label": "com.weather.trade_sync_loop",
                    "trade_engine_active": trade_engine_active,
                    "trade_engine_log_age_sec": trade_engine_log_age,
                    "legacy_trade_sync_loop_log_age_sec": sync_log_age,
                    "sync_status_recent": sync_status_recent,
                },
            )
    else:
        if launch_error:
            suppress_errno24 = False
            if "Errno 24" in launch_error:
                global _LAUNCHCTL_ERRNO24_AT
                now_ts = time.time()
                if _LAUNCHCTL_ERRNO24_AT <= 0:
                    _LAUNCHCTL_ERRNO24_AT = now_ts
                elif (now_ts - _LAUNCHCTL_ERRNO24_AT) >= ERRNO24_CLEAR_SEC:
                    suppress_errno24 = True
            if not suppress_errno24:
                _add_issue("launchctl_failed", "warn", f"launchctl list 失败：{launch_error}", {"error": launch_error})
            else:
                launch_error = ""

    # Data staleness + job hints (avoid false positives by combining DB + log + pid).
    tick_age_sec = _age_sec(db_stats.get("last_market_tick_at") if isinstance(db_stats, dict) else "")
    market_log_age_sec = _age_sec(log_stats.get("market_refresh", {}).get("mtime") if isinstance(log_stats, dict) else "")
    market_pid = _pid_for("com.weather.market_refresh_1m") if launch_ok else None
    market_enabled = True
    try:
        market_row = launch_map.get("com.weather.market_refresh_1m")
        if isinstance(market_row, dict) and market_row.get("enabled") is False:
            market_enabled = False
    except Exception:
        market_enabled = True
    if tick_age_sec is not None and tick_age_sec >= float(HEALTH_MARKET_MEDIAN_STALE_SEC):
        if market_log_age_sec is not None and market_log_age_sec <= 5 * 60:
            reasons.append("market_refresh 在跑但盘口未写入（可能 CLOB/网络失败）")
            _add_issue(
                "market_refresh_no_ticks",
                "warn",
                "market_refresh 有日志但 DB 盘口 ticks 未更新，可能 CLOB/网络失败",
                {"tick_age_sec": tick_age_sec, "market_log_age_sec": market_log_age_sec},
            )
        if (market_pid is None) and (market_log_age_sec is None or market_log_age_sec > 10 * 60):
            if not market_enabled:
                _add_issue(
                    "market_refresh_disabled",
                    "info",
                    "盘口已陈旧，但 market_refresh 已禁用（系统开关关闭）",
                    {"tick_age_sec": tick_age_sec, "market_log_age_sec": market_log_age_sec},
                )
            else:
                reasons.append("盘口已陈旧且 market_refresh 未运行")
                _add_issue(
                    "market_refresh_not_running",
                    "error",
                    "盘口已陈旧且 market_refresh 未运行（或长期无日志）",
                    {"tick_age_sec": tick_age_sec, "market_log_age_sec": market_log_age_sec},
                )

    fact_age_sec = _age_sec(db_stats.get("last_fact_as_of") if isinstance(db_stats, dict) else "")
    model_log_age_sec = _age_sec(log_stats.get("model_scan", {}).get("mtime") if isinstance(log_stats, dict) else "")
    model_pid = _pid_for("com.weather.model_scan") if launch_ok else None
    model_enabled = True
    try:
        model_row = launch_map.get("com.weather.model_scan")
        if isinstance(model_row, dict) and model_row.get("enabled") is False:
            model_enabled = False
    except Exception:
        model_enabled = True
    if fact_age_sec is not None and fact_age_sec >= float(HEALTH_SCAN_STALE_SEC):
        if (model_pid is None) and (model_log_age_sec is None or model_log_age_sec > 10 * 60):
            if not model_enabled:
                _add_issue(
                    "model_scan_disabled",
                    "info",
                    "事实层已陈旧，但 model_scan 已禁用（系统开关关闭）",
                    {"fact_age_sec": fact_age_sec, "model_log_age_sec": model_log_age_sec},
                )
            else:
                reasons.append("事实层长时间未更新（model_scan 未运行）")
                _add_issue(
                    "model_scan_not_running",
                    "error",
                    "事实层长时间未更新，且 model_scan 未运行（或长期无日志）",
                    {"fact_age_sec": fact_age_sec, "model_log_age_sec": model_log_age_sec},
                )

    # launchctl list 的 status 是“最近一次退出状态码”，不等价于当前健康。
    # 只在 pid 不存在（未运行）时，才把非 0 status 作为可行动的告警信号；避免“历史状态”污染健康面板。
    if launch_ok:
        for label in (
            "com.xiong.weather.ui",
            "com.weather.market_ws",
            "com.weather.trade_engine",
            "com.weather.auto_trade_worker",
            *(_auto_trade_watcher_labels()),
            "com.weather.trade_sync_loop",
        ):
            pid = _pid_for(label)
            status = _status_for(label)
            if pid is None and status is not None and status != 0:
                _add_issue(
                    "launchd_nonzero_status",
                    "warn",
                    f"LaunchAgent 最近退出状态非 0：{label} status={status}",
                    {"label": label, "status": status},
                )

    if _scan_alerts_paused():
        issues = [it for it in issues if not _service_issue_suppressed_when_scan_paused(it)]
        reasons = []

    banner_text = ""
    banner_severity = "ok"
    if reasons:
        banner_text = "⚠ 后端任务告警 · " + " · ".join(reasons)
        banner_severity = "error" if any(i.get("severity") == "error" for i in issues) else "warn"

    issues = _suppress_errno24_issues(issues)
    return {
        "ok": True,
        "now": now_text(),
        "launchd_ok": bool(launch_ok),
        "launchd_error": str(launch_error or ""),
        "launchd": launch_map,
        "launchd_disabled": launchd_disabled_subset,
        "logs": log_stats,
        "db": db_stats,
        "banner": {
            "active": bool(reasons),
            "severity": banner_severity,
            "text": banner_text,
            "reasons": reasons,
            "alerts_paused": bool(_scan_alerts_paused()),
        },
        "issues": issues,
        "scan_alerts_paused": bool(_scan_alerts_paused()),
        "fd_usage": fd_usage,
        "fd_guard": fd_guard,
        "fd_degrade": fd_degrade,
        "timing_ms": {
            "launchctl": round(float(launch_ms), 2),
            "logs": round(float(logs_ms), 2),
            "db": round(float(db_ms), 2),
            "total": round(float((time.monotonic() - t0) * 1000.0), 2),
        },
    }


def _launchd_legacy_trade_labels() -> List[str]:
    return [
        "com.weather.auto_trade_worker",
        "com.weather.trade_sync_loop",
    ]


def _launchd_health_labels() -> List[str]:
    labels: List[str] = []
    for label in [*_launchd_service_labels(), *_launchd_legacy_trade_labels()]:
        if label not in labels:
            labels.append(label)
    return labels


def _launchd_service_labels() -> List[str]:
    return [
        "com.xiong.weather.ui",
        "com.weather.market_ws",
        "com.weather.market_refresh_1m",
        "com.weather.model_scan",
        "com.weather.auto_trade_entry_1m",
        "com.weather.trade_engine",
        "com.weather.daily_scan",
    ]


def _launchctl_run(cmd: List[str], timeout_sec: float = 8) -> Dict[str, Any]:
    try:
        res = subprocess.run(cmd, capture_output=True, text=True, timeout=timeout_sec, check=False)
    except Exception as exc:
        return {"ok": False, "cmd": cmd, "error": str(exc), "code": None, "out": "", "err": ""}
    return {
        "ok": res.returncode == 0,
        "cmd": cmd,
        "code": res.returncode,
        "out": (res.stdout or "").strip(),
        "err": (res.stderr or "").strip(),
    }


def _system_pause_labels() -> List[str]:
    labels: List[str] = []
    for label in [*_launchd_service_labels(), *_launchd_legacy_trade_labels()]:
        if label == "com.xiong.weather.ui" or label in labels:
            continue
        labels.append(label)
    return labels


def _infer_launchd_enabled(label: str, disabled_map: Dict[str, str], launch_map: Dict[str, Any]) -> bool:
    row = launch_map.get(label)
    if isinstance(row, dict):
        pid = row.get("pid")
        if isinstance(pid, int) and pid > 0:
            return True
    state = str(disabled_map.get(label) or "").strip().lower()
    if state == "disabled":
        return False
    if state == "enabled":
        return True
    if isinstance(row, dict) and isinstance(row.get("enabled"), bool):
        return bool(row.get("enabled"))
    return label in launch_map


def launchd_apply_all(action: str) -> Dict[str, Any]:
    """Start/stop/restart LaunchAgents (gui/$UID) best-effort."""
    action = str(action or "").strip().lower()
    if action not in {"start", "stop", "restart"}:
        return {"ok": False, "error": "invalid_action"}
    uid = os.getuid()
    domain = f"gui/{uid}"
    labels = _launchd_service_labels()
    legacy_labels = _launchd_legacy_trade_labels()
    results: List[Dict[str, Any]] = []

    def _start_label(label: str) -> None:
        plist = LAUNCHD_USER_DIR / f"{label}.plist"
        if not plist.exists():
            results.append({"label": label, "skipped": True, "reason": "plist_missing"})
            return
        # bootstrap may fail if already loaded; ignore but record.
        results.append({"label": label, "bootstrap": _launchctl_run(["launchctl", "bootstrap", domain, str(plist)])})
        results.append({"label": label, "enable": _launchctl_run(["launchctl", "enable", f"{domain}/{label}"])})
        results.append({"label": label, "kickstart": _launchctl_run(["launchctl", "kickstart", "-k", f"{domain}/{label}"])})

    def _stop_label(label: str) -> None:
        plist = LAUNCHD_USER_DIR / f"{label}.plist"
        if not plist.exists():
            results.append({"label": label, "skipped": True, "reason": "plist_missing"})
            return
        results.append({"label": label, "stop": _launchctl_run(["launchctl", "stop", f"{domain}/{label}"])})
        results.append({"label": label, "bootout": _launchctl_run(["launchctl", "bootout", domain, str(plist)])})

    if action == "restart":
        for label in [*labels, *legacy_labels]:
            _stop_label(label)
        for label in labels:
            _start_label(label)
    elif action == "stop":
        for label in [*labels, *legacy_labels]:
            _stop_label(label)
    else:
        for label in legacy_labels:
            _stop_label(label)
        for label in labels:
            _start_label(label)
    return {"ok": True, "action": action, "domain": domain, "results": results}


def launchd_apply_labels(
    action: str,
    labels: List[str],
    *,
    kickstart: bool = True,
) -> Dict[str, Any]:
    """Start/stop selected LaunchAgents (gui/$UID) best-effort.

    Note: for scheduled one-shot jobs, kickstarting immediately may be undesired. Callers can pass
    kickstart=False to only (boot)load/unload the job.
    """
    action = str(action or "").strip().lower()
    if action not in {"start", "stop", "restart"}:
        return {"ok": False, "error": "invalid_action"}
    uid = os.getuid()
    domain = f"gui/{uid}"
    wanted = []
    seen = set()
    for raw in (labels or []):
        lab = str(raw or "").strip()
        if not lab or lab in seen:
            continue
        seen.add(lab)
        wanted.append(lab)
    if not wanted:
        return {"ok": False, "error": "missing_labels"}
    results: List[Dict[str, Any]] = []

    # KeepAlive agents are safe to kickstart immediately; scheduled jobs usually aren't.
    keepalive_labels = {
        "com.xiong.weather.ui",
        "com.weather.trade_engine",
        "com.weather.auto_trade_worker",
        "com.weather.trade_sync_loop",
    }

    def _start_label(label: str) -> None:
        plist = LAUNCHD_USER_DIR / f"{label}.plist"
        if not plist.exists():
            results.append({"label": label, "skipped": True, "reason": "plist_missing"})
            return
        results.append({"label": label, "bootstrap": _launchctl_run(["launchctl", "bootstrap", domain, str(plist)])})
        results.append({"label": label, "enable": _launchctl_run(["launchctl", "enable", f"{domain}/{label}"])})
        if kickstart and label in keepalive_labels:
            results.append({"label": label, "kickstart": _launchctl_run(["launchctl", "kickstart", "-k", f"{domain}/{label}"])})

    def _stop_label(label: str) -> None:
        plist = LAUNCHD_USER_DIR / f"{label}.plist"
        if not plist.exists():
            results.append({"label": label, "skipped": True, "reason": "plist_missing"})
            return
        results.append({"label": label, "stop": _launchctl_run(["launchctl", "stop", f"{domain}/{label}"])})
        results.append({"label": label, "bootout": _launchctl_run(["launchctl", "bootout", domain, str(plist)])})

    if action == "restart":
        for label in wanted:
            _stop_label(label)
        for label in wanted:
            _start_label(label)
    elif action == "stop":
        for label in wanted:
            _stop_label(label)
    else:
        for label in wanted:
            _start_label(label)
    return {"ok": True, "action": action, "domain": domain, "labels": wanted, "results": results}


def launchd_set_enabled_labels(
    labels: List[str],
    enabled: bool,
    *,
    kickstart: bool = True,
    bootstrap: bool = True,
) -> Dict[str, Any]:
    """Enable/disable selected LaunchAgents (gui/$UID) without unloading them.

    Rationale: `launchctl disable` does not necessarily remove the job from `launchctl list`.
    UI switches should reflect "enabled to run" rather than just "loaded".
    """
    uid = os.getuid()
    domain = f"gui/{uid}"
    wanted: List[str] = []
    seen = set()
    for raw in (labels or []):
        lab = str(raw or "").strip()
        if not lab or lab in seen:
            continue
        seen.add(lab)
        wanted.append(lab)
    if not wanted:
        return {"ok": False, "error": "missing_labels"}
    results: List[Dict[str, Any]] = []

    keepalive_labels = {
        "com.xiong.weather.ui",
        "com.weather.trade_engine",
        "com.weather.auto_trade_worker",
        "com.weather.trade_sync_loop",
    }

    if enabled:
        for label in wanted:
            if bootstrap:
                plist = LAUNCHD_USER_DIR / f"{label}.plist"
                if plist.exists():
                    results.append({"label": label, "bootstrap": _launchctl_run(["launchctl", "bootstrap", domain, str(plist)])})
                else:
                    results.append({"label": label, "bootstrap": {"ok": False, "err": "plist_missing", "out": "", "cmd": "", "code": -1}})
            results.append({"label": label, "enable": _launchctl_run(["launchctl", "enable", f"{domain}/{label}"])})
            if kickstart and label in keepalive_labels:
                results.append({"label": label, "kickstart": _launchctl_run(["launchctl", "kickstart", "-k", f"{domain}/{label}"])})
    else:
        for label in wanted:
            results.append({"label": label, "disable": _launchctl_run(["launchctl", "disable", f"{domain}/{label}"])})
            # Best-effort: stop current run if any; does not unload.
            results.append({"label": label, "stop": _launchctl_run(["launchctl", "stop", f"{domain}/{label}"])})

    return {"ok": True, "enabled": bool(enabled), "domain": domain, "labels": wanted, "results": results}


def apply_system_pause(paused: bool) -> Dict[str, Any]:
    labels = _system_pause_labels()
    if paused:
        services = services_health()
        disabled_map = services.get("launchd_disabled") if isinstance(services, dict) else {}
        launch_map = services.get("launchd") if isinstance(services, dict) else {}
        enabled_snapshot: Dict[str, bool] = {}
        for label in labels:
            enabled_snapshot[label] = _infer_launchd_enabled(label, disabled_map or {}, launch_map or {})
        snapshot = {
            "auto_trade_enabled": _env_bool("PM_AUTO_TRADE_ENABLED", False),
            "services_enabled": enabled_snapshot,
            "captured_at": utc_now_iso(),
        }
        auto_trade_payload = apply_auto_trade_state(False)
        service_payload = launchd_set_enabled_labels(labels, False, kickstart=False)
        # Avoid long-running bootout/stop loops that can cause UI timeouts. Disable + stop is enough.
        stop_payload = {"ok": True, "skipped": True, "reason": "disabled_only"}
        killed = kill_repo_processes(skip_ui=True, timeout_sec=1.0)
        _write_json_atomic(
            SYSTEM_PAUSE_STATE_PATH,
            {"paused": True, "snapshot": snapshot, "updated_at": utc_now_iso()},
        )
        return {
            "ok": True,
            "paused": True,
            "snapshot": snapshot,
            "auto_trade": auto_trade_payload,
            "services": service_payload,
            "stopped": stop_payload,
            "killed": killed,
        }
    state = _read_system_pause_state()
    snapshot = state.get("snapshot") if isinstance(state, dict) else None
    services_enabled = snapshot.get("services_enabled") if isinstance(snapshot, dict) else {}
    if not isinstance(services_enabled, dict):
        services_enabled = {}
    enable_labels = [label for label in labels if services_enabled.get(label) is True]
    # Always re-enable core data refresh services on resume.
    core_labels = {
        "com.weather.model_scan",
        "com.weather.market_refresh_1m",
        "com.weather.trade_engine",
    }
    auto_trade_enabled = snapshot.get("auto_trade_enabled") if isinstance(snapshot, dict) else None
    auto_trade_labels = {
        "com.weather.auto_trade_entry_1m",
        "com.weather.auto_trade_worker",
    }
    for label in core_labels:
        if label not in enable_labels:
            enable_labels.append(label)
    if auto_trade_enabled:
        for label in auto_trade_labels:
            if label not in enable_labels:
                enable_labels.append(label)
    service_payload = (
        launchd_set_enabled_labels(enable_labels, True, kickstart=True, bootstrap=False)
        if enable_labels
        else {"ok": True, "enabled": True, "labels": []}
    )
    auto_trade_payload = None
    if auto_trade_enabled is not None:
        auto_trade_payload = apply_auto_trade_state(bool(auto_trade_enabled))
    _write_json_atomic(
        SYSTEM_PAUSE_STATE_PATH,
        {"paused": False, "snapshot": snapshot or {}, "updated_at": utc_now_iso()},
    )
    return {
        "ok": True,
        "paused": False,
        "snapshot": snapshot or {},
        "services": service_payload,
        "auto_trade": auto_trade_payload,
        "warning": "" if snapshot else "snapshot_missing_restored_partial",
    }


def clean_runtime_locks() -> Dict[str, Any]:
    removed: List[str] = []
    for name in (
        "market_refresh.lock",
        "model_scan.lock",
        "auto_trade_entry.lock",
        "auto_trade_worker.lock",
        "facts_materialize.lock",
        "auto_trade_smoke_test.lock",
    ):
        path = DATA_DIR / name
        if path.exists():
            try:
                shutil.rmtree(path)
                removed.append(str(path))
            except OSError:
                pass
    return {"ok": True, "removed": removed}


def kill_repo_processes(skip_ui: bool = False, timeout_sec: float = 3.0) -> Dict[str, Any]:
    """Best-effort cleanup for duplicated/background processes under this repo."""
    root = str(ROOT_DIR)
    patterns = [
        f"{root}/scan_weather_market.py",
        f"{root}/scripts/auto_trade_watcher.py",
        f"{root}/scripts/trade_sync_loop.sh",
    ]
    if not skip_ui:
        patterns.insert(1, f"{root}/ui/server.py")
    killed: List[Dict[str, Any]] = []
    me = os.getpid()
    for pat in patterns:
        try:
            res = subprocess.run(["pgrep", "-f", pat], capture_output=True, text=True, timeout=timeout_sec, check=False)
        except Exception:
            continue
        if res.returncode != 0:
            continue
        for line in (res.stdout or "").splitlines():
            line = line.strip()
            if not line.isdigit():
                continue
            pid = int(line)
            if pid == me:
                continue
            try:
                os.kill(pid, 15)
                killed.append({"pid": pid, "pattern": pat, "signal": "TERM"})
            except OSError:
                continue
    # Give processes a moment; then SIGKILL remaining.
    time.sleep(0.3)
    for entry in list(killed):
        pid = entry.get("pid")
        if not isinstance(pid, int):
            continue
        try:
            os.kill(pid, 0)
        except OSError:
            continue
        try:
            os.kill(pid, 9)
            entry["signal2"] = "KILL"
        except OSError:
            pass
    return {"ok": True, "killed": killed}


def materialize_facts_http(run_date: str, days: int = 1) -> Dict[str, Any]:
    lock_dir = FACTS_MATERIALIZE_LOCK_DIR
    pid_path = lock_dir / "pid"
    try:
        lock_dir.mkdir(parents=True, exist_ok=False)
        pid_path.write_text(str(os.getpid()), encoding="utf-8")
    except FileExistsError:
        old_pid = ""
        try:
            old_pid = pid_path.read_text(encoding="utf-8").strip()
        except OSError:
            old_pid = ""
        if old_pid.isdigit():
            try:
                os.kill(int(old_pid), 0)
                return {"ok": False, "error": "materialize_running"}
            except OSError:
                pass
        try:
            shutil.rmtree(lock_dir)
            lock_dir.mkdir(parents=True, exist_ok=False)
            pid_path.write_text(str(os.getpid()), encoding="utf-8")
        except OSError:
            return {"ok": False, "error": "materialize_lock_failed"}
    try:
        _write_facts_materialize_lock_meta(
            mode="facts_materialize_http",
            facts_date=run_date,
            facts_days=days,
            write_scope=os.environ.get("PM_ARCHIVE_WRITE_SCOPE") or "",
        )
        if not DB_PATH.exists():
            return {"ok": False, "error": "db_missing"}
        try:
            apply_auto_trade_config(load_auto_trade_config())
        except Exception:
            pass
        days = int(days or 1)
        days = max(1, min(days, 30))
        with open_db() as conn:
            ensure_fact_tables(conn)
            end_key = _normalize_date_key(run_date or latest_unsettled_run_date(conn) or latest_run_date(conn))
            if not end_key:
                return {"ok": False, "error": "no_run_date"}
            if days <= 1:
                created = _materialize_facts_from_snapshots_for_run_date(conn, end_key)
                return {"ok": True, "created": created, "run_date": end_key}
            end_dt = datetime.fromisoformat(end_key).date()
            start_dt = end_dt - timedelta(days=max(0, days - 1))
            start_key = start_dt.isoformat()
            created = _materialize_facts_from_snapshots_for_range(conn, start_key, end_key)
            return {"ok": True, "created": created, "start": start_key, "end": end_key}
    finally:
        try:
            shutil.rmtree(lock_dir)
        except OSError:
            pass


def auto_trade_smoke_test_http(params: Dict[str, List[str]], client_ip: str) -> Dict[str, Any]:
    # Explicit, real-money operation: require local caller + per-request enable,
    # manual intent, and an operator confirmation phrase.
    local_only = client_ip in {"127.0.0.1", "::1"}
    request_enable_flag = params.get("enable", [""])[0] == "1"
    env_enable_flag = _env_bool("PM_AUTO_TRADE_SMOKE_TEST_ENABLED", False)
    enable_flag = bool(request_enable_flag or env_enable_flag)
    intent_flag = params.get("intent", [""])[0] == "manual_smoke_test"
    confirm_raw = str(params.get("confirm", [""])[0] or "").strip()
    confirm_phrase = AUTO_TRADE_SMOKE_TEST_CONFIRM_PHRASE or "REAL_MONEY_SMOKE_TEST"
    confirm_flag = bool(confirm_raw and confirm_raw == confirm_phrase)
    if not local_only:
        return {"ok": False, "error": "local_only", "client_ip": client_ip}
    if not enable_flag:
        return {
            "ok": False,
            "error": "smoke_test_disabled",
            "hint": "pass enable=1 (per request) or set PM_AUTO_TRADE_SMOKE_TEST_ENABLED=1",
        }
    if not (request_enable_flag and intent_flag and confirm_flag):
        return {
            "ok": False,
            "error": "missing_manual_confirm",
            "hint": (
                "real smoke test requires enable=1, intent=manual_smoke_test, "
                "and confirm=<PM_AUTO_TRADE_SMOKE_TEST_CONFIRM_PHRASE>"
            ),
            "manual_confirm_required": True,
            "request_enable": bool(request_enable_flag),
            "manual_intent": bool(intent_flag),
            "confirm_phrase_matched": bool(confirm_flag),
        }
    if not DB_PATH.exists():
        return {"ok": False, "error": "db_missing"}

    # Best-effort runtime lock to avoid concurrent smoke tests.
    lock_dir = AUTO_TRADE_SMOKE_TEST_LOCK_DIR
    pid_path = lock_dir / "pid"
    try:
        lock_dir.mkdir(parents=True, exist_ok=False)
        pid_path.write_text(str(os.getpid()), encoding="utf-8")
    except FileExistsError:
        return {"ok": False, "error": "smoke_test_running"}

    try:
        run_date = str(params.get("date", [""])[0] or "").strip()
        slug_hint = str(params.get("slug", [""])[0] or "").strip()
        event_date_hint = str(params.get("event_date", [""])[0] or "").strip()
        outcome_hint = str(params.get("outcome", [""])[0] or "").strip()
        side_hint = str(params.get("side", ["YES"])[0] or "YES").strip().upper()
        if side_hint not in {"YES", "NO"}:
            side_hint = "YES"
        size_raw = params.get("size", [""])[0]
        entry_price_raw = params.get("entry_price", [""])[0]
        exit_price_raw = params.get("exit_price", [""])[0]

        try:
            size = float(size_raw) if size_raw else float(os.environ.get("PM_SMOKE_TEST_ORDER_SIZE", "0") or 0)
        except ValueError:
            size = 0.0
        if not math.isfinite(size) or size <= 0:
            try:
                size = float(os.environ.get("PM_MIN_ORDER_SIZE", "1") or 1)
            except ValueError:
                size = 1.0
        size = max(1.0, float(size))

        def _to_float(value: Any) -> Optional[float]:
            try:
                out = float(value)
            except (TypeError, ValueError):
                return None
            return out if math.isfinite(out) else None

        entry_price_override = _to_float(entry_price_raw) if entry_price_raw else None
        exit_price_override = _to_float(exit_price_raw) if exit_price_raw else None

        # Load facts (SSOT) and select a liquid target.
        with open_db() as conn:
            ensure_fact_tables(conn)
            if not run_date:
                run_date = latest_fact_run_date(conn) or latest_unsettled_run_date(conn) or latest_run_date(conn) or ""
        if not run_date:
            return {"ok": False, "error": "no_run_date"}
        facts = query_facts(run_date, include_history=False)

        def _dist_rows(fact: Dict[str, Any]) -> List[Dict[str, Any]]:
            dist = fact.get("distribution")
            if isinstance(dist, list):
                return [row for row in dist if isinstance(row, dict)]
            if isinstance(dist, dict):
                rows = dist.get("rows")
                if isinstance(rows, list):
                    return [row for row in rows if isinstance(row, dict)]
            return []

        candidates: List[Dict[str, Any]] = []
        for fact in facts:
            if not isinstance(fact, dict):
                continue
            if fact.get("market_closed"):
                continue
            slug = str(fact.get("slug") or "").strip()
            event_date = str(fact.get("event_date") or fact.get("date") or "").strip()
            if "T" in event_date:
                event_date = event_date.split("T", 1)[0]
            if not slug or not event_date:
                continue
            if slug_hint and slug != slug_hint:
                continue
            if event_date_hint and event_date != event_date_hint:
                continue
            for row in _dist_rows(fact):
                outcome = str(row.get("outcome") or "").strip()
                if not outcome:
                    continue
                if outcome_hint and outcome != outcome_hint:
                    continue
                vol = _to_float(row.get("outcome_volume")) or 0.0
                if vol < 200:
                    continue
                if side_hint == "YES":
                    token_id = str(row.get("yes_token") or "").strip()
                    ask = _to_float(row.get("best_ask"))
                    bid = _to_float(row.get("best_bid"))
                    spread = _to_float(row.get("spread"))
                else:
                    token_id = str(row.get("no_token") or "").strip()
                    ask = _to_float(row.get("best_ask_no"))
                    bid = _to_float(row.get("best_bid_no"))
                    spread = _to_float(row.get("spread_no"))
                if not token_id or ask is None or bid is None or spread is None:
                    continue
                if ask < 0.15 or ask > 0.60:
                    continue
                if spread <= 0 or spread > 0.03:
                    continue
                candidates.append(
                    {
                        "slug": slug,
                        "event_date": event_date,
                        "title": str(fact.get("title") or slug),
                        "outcome": outcome,
                        "side": side_hint,
                        "token_id": token_id,
                        "ask": ask,
                        "bid": bid,
                        "spread": spread,
                        "outcome_volume": vol,
                    }
                )
        if not candidates:
            return {
                "ok": False,
                "error": "no_candidates",
                "run_date": run_date,
                "filters": {
                    "slug": slug_hint or None,
                    "event_date": event_date_hint or None,
                    "outcome": outcome_hint or None,
                    "side": side_hint,
                    "min_outcome_volume": 200,
                    "ask_range": [0.15, 0.60],
                    "spread_max": 0.03,
                },
            }
        # Prefer the most liquid candidate, but bias towards cheaper asks.
        def _score(item: Dict[str, Any]) -> float:
            vol = float(item.get("outcome_volume") or 0.0)
            ask = float(item.get("ask") or 0.0)
            spr = float(item.get("spread") or 0.0)
            cheap_bonus = 0.0
            if 0.15 <= ask <= 0.35:
                cheap_bonus = 500.0
            return vol + cheap_bonus - spr * 1000.0 - abs(ask - 0.30) * 100.0

        target = max(candidates, key=_score)
        token_id = str(target["token_id"])
        entry_price = entry_price_override if entry_price_override is not None else float(target["ask"])

        # Re-fetch orderbook before acting to ensure price is current.
        try:
            import scan_weather_market as swm
        except Exception as exc:
            return {"ok": False, "error": "auto_trade_unavailable", "detail": str(exc)}
        try:
            book = swm.fetch_orderbook(token_id)
            bid, ask, spread, _bd, _ad, _bidsz, _asksz = swm.best_bid_ask_and_depth(book, levels=5)
        except Exception:
            bid = None
            ask = None
            spread = None
        if ask is not None and math.isfinite(ask) and ask > 0:
            entry_price = entry_price_override if entry_price_override is not None else float(ask)

        def _smoke_order_context(intent_action: str) -> Dict[str, Any]:
            return {
                "execution_domain": "manual_smoke_test",
                "order_execution_domain": "manual_smoke_test",
                "order_execution_source": "ui_auto_trade_smoke_test_http",
                "order_execution_reason": "manual_real_money_smoke_test",
                "manual_confirm_source": "ui_auto_trade_smoke_test_http",
                "intent_action": str(intent_action or "").strip() or "manual_smoke_test",
                "strategy_source": "smoke_test",
                "entry_order_submit_source": "ui_auto_trade_smoke_test",
                "slug": str(target.get("slug") or ""),
                "event_date": str(target.get("event_date") or ""),
                "outcome": str(target.get("outcome") or ""),
                "outcome_side": str(target.get("side") or ""),
            }

        def _wait_matched(order_id: str, timeout_sec: float = 30.0) -> Tuple[bool, Dict[str, Any]]:
            deadline = time.time() + max(1.0, float(timeout_sec or 0))
            last_payload: Dict[str, Any] = {}
            while time.time() < deadline:
                ok, payload = swm._run_node_get_order(order_id)
                last_payload = payload if isinstance(payload, dict) else {"payload": payload}
                order = last_payload.get("order") if isinstance(last_payload, dict) else None
                status = ""
                if isinstance(order, dict):
                    status = str(order.get("status") or "").upper()
                if ok and status == "MATCHED":
                    return True, last_payload
                if status in {"CANCELED", "CANCELLED", "REJECTED"}:
                    return False, last_payload
                time.sleep(1.0)
            return False, last_payload

        # Place BUY.
        buy_ok, buy_payload = swm._run_node_order(
            "place-order",
            token_id,
            "BUY",
            price=entry_price,
            size=size,
            order_type="GTC",
            order_context=_smoke_order_context("entry"),
        )
        if not buy_ok:
            return {"ok": False, "error": "buy_failed", "target": target, "detail": buy_payload}
        buy_order_id = str(buy_payload.get("orderID") or buy_payload.get("order_id") or "")
        if not buy_order_id:
            return {"ok": False, "error": "buy_missing_order_id", "target": target, "detail": buy_payload}
        buy_matched, buy_order_payload = _wait_matched(buy_order_id, timeout_sec=30.0)
        if not buy_matched:
            return {
                "ok": False,
                "error": "buy_not_matched",
                "target": target,
                "buy": {"order_id": buy_order_id, "payload": buy_order_payload},
            }

        buy_order = buy_order_payload.get("order") if isinstance(buy_order_payload, dict) else None
        buy_size = _to_float((buy_order or {}).get("size_matched")) or size
        buy_price = _to_float((buy_order or {}).get("price")) or entry_price
        buy_trades = (buy_order or {}).get("associate_trades") if isinstance(buy_order, dict) else None

        now_iso = datetime.now(timezone.utc).isoformat()
        # Record entry in DB (auto_orders + edge_trades).
        with open_db() as conn:
            cur = conn.cursor()
            try:
                insert_auto_order_ignore(
                    cur,
                    order_id=buy_order_id,
                    slug=target["slug"],
                    event_date=target["event_date"],
                    outcome=target["outcome"],
                    side=target["side"],
                    action="entry",
                    price=buy_price,
                    size=buy_size,
                    order_type="GTC",
                    q_raw=None,
                    q_calibrated=None,
                    q_edge=None,
                    strategy="smoke_test",
                    created_at=now_iso,
                )
            except sqlite3.OperationalError:
                pass
            try:
                upsert_smoke_test_entry(
                    cur,
                    slug=target["slug"],
                    event_date=target["event_date"],
                    outcome=target["outcome"],
                    side=target["side"],
                    order_id=buy_order_id,
                    price=buy_price,
                    size=buy_size,
                    now_iso=now_iso,
                )
            except sqlite3.OperationalError:
                pass
            conn.commit()

        # Place SELL using current best bid.
        sell_price = exit_price_override
        try:
            book2 = swm.fetch_orderbook(token_id)
            bid2, ask2, _spr2, _bd2, _ad2, _bidsz2, _asksz2 = swm.best_bid_ask_and_depth(book2, levels=5)
        except Exception:
            bid2 = None
        if sell_price is None:
            if bid2 is not None and math.isfinite(bid2) and bid2 > 0:
                sell_price = float(bid2)
            else:
                sell_price = float(target["bid"])
        sell_ok, sell_payload = swm._run_node_order(
            "place-order",
            token_id,
            "SELL",
            price=sell_price,
            size=buy_size,
            order_type="GTC",
            order_context=_smoke_order_context("exit"),
        )
        if not sell_ok:
            return {
                "ok": False,
                "error": "sell_failed",
                "target": target,
                "buy": {"order_id": buy_order_id, "matched": True, "trade_ids": buy_trades},
                "detail": sell_payload,
            }
        sell_order_id = str(sell_payload.get("orderID") or sell_payload.get("order_id") or "")
        if not sell_order_id:
            return {
                "ok": False,
                "error": "sell_missing_order_id",
                "target": target,
                "buy": {"order_id": buy_order_id, "matched": True, "trade_ids": buy_trades},
                "detail": sell_payload,
            }
        sell_matched, sell_order_payload = _wait_matched(sell_order_id, timeout_sec=30.0)
        if not sell_matched:
            return {
                "ok": False,
                "error": "sell_not_matched",
                "target": target,
                "buy": {"order_id": buy_order_id, "matched": True, "trade_ids": buy_trades},
                "sell": {"order_id": sell_order_id, "payload": sell_order_payload},
            }
        sell_order = sell_order_payload.get("order") if isinstance(sell_order_payload, dict) else None
        sell_size = _to_float((sell_order or {}).get("size_matched")) or buy_size
        sell_price_eff = _to_float((sell_order or {}).get("price")) or sell_price
        sell_trades = (sell_order or {}).get("associate_trades") if isinstance(sell_order, dict) else None

        now2_iso = datetime.now(timezone.utc).isoformat()
        with open_db() as conn:
            cur = conn.cursor()
            try:
                insert_auto_order_ignore(
                    cur,
                    order_id=sell_order_id,
                    slug=target["slug"],
                    event_date=target["event_date"],
                    outcome=target["outcome"],
                    side=target["side"],
                    action="exit",
                    price=sell_price_eff,
                    size=sell_size,
                    order_type="GTC",
                    q_raw=None,
                    q_calibrated=None,
                    q_edge=None,
                    strategy="smoke_test",
                    created_at=now2_iso,
                )
            except sqlite3.OperationalError:
                pass
            try:
                update_edge_trade_by_key(
                    cur,
                    slug=target["slug"],
                    event_date=target["event_date"],
                    outcome=target["outcome"],
                    side=target["side"],
                    values={
                        "state": "exit",
                        "last_order_id": sell_order_id,
                        "last_action": "smoke_test_exit",
                        "last_action_price": sell_price_eff,
                        "last_action_size": sell_size,
                        "last_action_order_type": "GTC",
                        "last_action_at": now2_iso,
                        "last_status": "sell_matched",
                        "last_error": "",
                        "position_size": 0,
                        "updated_at": now2_iso,
                    },
                )
            except sqlite3.OperationalError:
                pass
            conn.commit()

        # Sync fills for this token to validate the full pipeline.
        token_map = {
            token_id: {
                "slug": str(target["slug"]),
                "event_date": str(target["event_date"]),
                "outcome": str(target["outcome"]),
                "side": str(target["side"]),
            }
        }
        mark_map = {(str(target["slug"]), str(target["event_date"]), str(target["outcome"]), str(target["side"])): float(sell_price_eff)}
        try:
            sync_ok = bool(swm.sync_trade_fills(token_map, mark_map))
        except Exception as exc:
            sync_ok = False
            sync_err = str(exc)
        else:
            sync_err = ""
        fills_found = 0
        with open_db() as conn:
            try:
                cur = conn.cursor()
                cur.execute(
                    """
                    SELECT COUNT(1)
                    FROM edge_trade_fills
                    WHERE slug=? AND event_date=? AND outcome=? AND outcome_side=?
                      AND trade_time >= ?
                    """,
                    (
                        target["slug"],
                        target["event_date"],
                        target["outcome"],
                        target["side"],
                        (datetime.now(timezone.utc) - timedelta(hours=1)).isoformat(),
                    ),
                )
                row = cur.fetchone()
                fills_found = int(row[0] or 0) if row else 0
            except sqlite3.OperationalError:
                fills_found = 0

        return {
            "ok": True,
            "run_date": run_date,
            "target": target,
            "buy": {
                "order_id": buy_order_id,
                "price": buy_price,
                "size": buy_size,
                "trade_ids": buy_trades,
            },
            "sell": {
                "order_id": sell_order_id,
                "price": sell_price_eff,
                "size": sell_size,
                "trade_ids": sell_trades,
            },
            "sync": {"ok": sync_ok, "error": sync_err, "fills_found_1h": fills_found},
        }
    finally:
        try:
            shutil.rmtree(lock_dir)
        except OSError:
            pass


def restart_auto_trade_watcher() -> Dict[str, Any]:
    label = str(AUTO_TRADE_WATCHER_LABEL or "").strip()
    if not label:
        return {"ok": False, "error": "missing_label"}
    if not label.startswith("system/") and not label.startswith("gui/"):
        user_label = label
    else:
        user_label = label.rsplit("/", 1)[-1]

    system_label = label
    if not system_label.startswith("system/"):
        system_label = f"system/{label}"
    user_plist = LAUNCHD_USER_DIR / f"{label}.plist"
    if user_plist.exists():
        user_label = f"gui/{os.getuid()}/{user_label}"
        cmd = ["launchctl", "kickstart", "-k", user_label]
        try:
            res = subprocess.run(
                cmd,
                capture_output=True,
                text=True,
                timeout=8,
                check=False,
            )
        except Exception as exc:
            return {"ok": False, "error": "kickstart_failed", "detail": str(exc)}
        if res.returncode == 0:
            return {"ok": True, "label": user_label}
        detail = (res.stderr or res.stdout or "").strip()
        return {"ok": False, "error": "kickstart_failed", "detail": detail, "code": res.returncode}

    system_plist = LAUNCHD_SYSTEM_DIR / f"{system_label.replace('system/','')}.plist"
    if system_plist.exists():
        cmd = ["sudo", "-n", "launchctl", "kickstart", "-k", system_label]
        try:
            res = subprocess.run(
                cmd,
                capture_output=True,
                text=True,
                timeout=8,
                check=False,
            )
        except Exception as exc:
            return {"ok": False, "error": "kickstart_failed", "detail": str(exc)}
        if res.returncode == 0:
            return {"ok": True, "label": system_label}
        detail = (res.stderr or res.stdout or "").strip()
        if "password" in detail.lower() or res.returncode in (1, 3):
            hint = f"需要 sudo 执行：sudo launchctl kickstart -k {system_label}"
            if detail:
                hint = f"{hint}（{detail}）"
            return {"ok": False, "error": "sudo_required", "detail": hint, "code": res.returncode}
        return {"ok": False, "error": "kickstart_failed", "detail": detail, "code": res.returncode}

    for action in ("stop", "start"):
        target_label = label.rsplit("/", 1)[-1]
        try:
            res = subprocess.run(
                ["launchctl", action, target_label],
                capture_output=True,
                text=True,
                timeout=8,
                check=False,
            )
        except Exception as exc:
            return {"ok": False, "error": f"{action}_failed", "detail": str(exc)}
        if res.returncode != 0:
            detail = (res.stderr or res.stdout or "").strip()
            return {
                "ok": False,
                "error": f"{action}_failed",
                "detail": detail,
                "code": res.returncode,
            }
    return {"ok": True, "label": label}


def _compact_ui_decision_details(
    details: Optional[Mapping[str, Any]],
    action: str,
    will_order: bool,
) -> Dict[str, Any]:
    if not isinstance(details, Mapping):
        return {}
    compact_fn = globals().get("_compact_scan_decision_details")
    if callable(compact_fn):
        try:
            return compact_fn(details, action=action, will_order=bool(will_order))
        except Exception:
            # If scan-side compaction cannot be used in this runtime, fallback to a
            # deterministic local compact path so SSOT write size remains bounded.
            pass

    compact: Dict[str, Any] = {}
    if not _env_bool("PM_DECISION_DETAILS_COMPACT", True):
        return dict(details)

    base_keep = {
        "ask",
        "bid",
        "q_entry",
        "q_quote",
        "spread",
        "volume",
        "market_tick_age_sec",
        "market_tick_stale_sec",
        "follow_market_tick_stale_sec",
        "ask_le_q_limit",
        "q_min",
        "q_max",
        "ask_min",
        "ask_max",
        "threshold",
        "status",
        "worker_error",
        "dry_run",
        "strategy",
        "strategy_variant",
        "weather_strategy_kind",
        "weather_strategy_profit_value",
        "weather_strategy_raw_ev",
        "weather_strategy_positive_ev",
        "source",
        "source_kind",
        "source_fit_tier",
        "source_fit_na_reason",
        "source_na_reason",
        "source_usable_for_settlement",
        "source_aux_only",
        "observed_nowcast_source_kind",
        "observed_nowcast_source_fit_tier",
        "observed_nowcast_source_trust_tier",
        "observed_nowcast_source_na_reason",
        "observed_nowcast_source_usable",
        "market_closed",
        "market_archived",
        "market_active",
        "market_accepting_orders",
        "market_enable_orderbook",
        "location_key",
        "location_label",
        "location_blocking_trade",
        "order_id",
        "auto_order_id",
        "entry_order_id",
        "token_id",
        "order_price",
        "order_size",
        "order_type",
        "trade_id",
        "trade_time",
        "size",
        "price",
        "strategy_size_scale",
        "entry_strategy_family",
        "entry_original_reason_codes",
        "entry_soft_reason_codes",
        "entry_soft_no_order",
        "entry_soft_reasons",
        "entry_hard_reason_codes",
        "entry_hard_reason_normalized",
    }
    prefix_keep = (
        "edge_tradeability_",
        "entry_usable_edge",
        "entry_soft_",
        "entry_edge",
        "exit_policy_",
        "exit_reason_",
        "exit_operational_",
        "exit_edge_",
        "edge_realizable",
        "edge_signal_",
        "edge_path_",
        "exec_edge",
        "exec_fee",
        "source_fit_",
        "source_",
        "market_",
        "weather_strategy_",
        "observed_nowcast_",
        "hold_edge_realizable",
        "entry_realizable_",
        "lcb_",
        "plain_lcb_",
        "kelly_",
        "entry_signal",
        "location_",
    )

    def _should_keep_detail_key(key: str) -> bool:
        if key in base_keep:
            return True
        if action == "entry" and not will_order and key.startswith("entry_"):
            return True
        for prefix in prefix_keep:
            if key.startswith(prefix):
                return True
        return False

    compact = {key: value for key, value in details.items() if _should_keep_detail_key(str(key))}

    compact_limit = _env_int("PM_DECISION_DETAILS_COMPACT_MAX_BYTES")
    if compact_limit is None or compact_limit <= 0:
        compact_limit = 2048

    def _payload_len(payload: Mapping[str, Any]) -> int:
        return len(json.dumps(payload, ensure_ascii=False, separators=(",", ":")))

    if _payload_len(compact) <= compact_limit:
        return compact

    # Keep a leaner required baseline for non-will_order entries to control DB growth.
    required = {
        "ask",
        "bid",
        "q_entry",
        "q_quote",
        "spread",
        "strategy",
        "edge_tradeability_pass",
        "edge_tradeability_mode",
        "edge_tradeability_profit_value",
        "edge_tradeability_edge_lcb",
        "edge_realizable",
        "hold_edge_realizable",
    }
    compacted = {k: compact[k] for k in required if k in compact}
    ordered = list(compact.keys())
    removable = [k for k in ordered if k in compact and k not in compacted]

    for key in removable:
        if _payload_len(compacted) <= compact_limit:
            break
        if key in compacted:
            compacted.pop(key, None)
    if _payload_len(compacted) <= compact_limit:
        return compacted

    # Last resort: shrink composite values then null out leftovers.
    def _shrink_value(value: Any) -> Any:
        if isinstance(value, Mapping):
            return {str(k): _shrink_value(v) for k, v in list(value.items())[:2]}
        if isinstance(value, list):
            if not value:
                return []
            return [_shrink_value(value[0])]
        if isinstance(value, tuple):
            if not value:
                return []
            return [_shrink_value(value[0])]
        if isinstance(value, str):
            return value if len(value) <= 80 else value[:60] + "...(truncated)"
        return value

    changed = True
    while _payload_len(compacted) > compact_limit and changed:
        changed = False
        for key in list(compacted):
            next_val = _shrink_value(compacted[key])
            if next_val != compacted[key]:
                compacted[key] = next_val
                changed = True
                if _payload_len(compacted) <= compact_limit:
                    break
        if changed:
            continue
        for key in list(compacted):
            if compacted.get(key) is not None:
                compacted[key] = None
                changed = True
                if _payload_len(compacted) <= compact_limit:
                    break
    return compacted


def _record_auto_trade_fallback_decisions(
    *,
    run_id: Optional[int],
    run_date: str,
    slug: str,
    event_date: str,
    title: str,
    targets: List[Dict[str, str]],
    reason_code: str,
    reason_text: str,
    details: Optional[Dict[str, Any]] = None,
) -> int:
    if not targets or not DB_PATH.exists():
        return 0
    now_iso = utc_now_iso()
    payload_details = details if isinstance(details, dict) else {}
    rows: List[Tuple[Any, ...]] = []
    seen: set[Tuple[str, str]] = set()
    for item in targets:
        if not isinstance(item, dict):
            continue
        outcome = str(item.get("outcome") or "").strip()
        side = str(item.get("side") or "").strip().upper()
        strategy = str(item.get("strategy") or "").strip().lower()
        if not outcome or side not in {"YES", "NO"}:
            continue
        dedupe_key = (outcome, side)
        if dedupe_key in seen:
            continue
        seen.add(dedupe_key)
        row_details = dict(payload_details)
        for item_key, item_val in item.items():
            if item_key in {"outcome", "side"}:
                continue
            if item_key in row_details and row_details.get(item_key) not in (None, "", []):
                continue
            if isinstance(item_val, (str, int, float, bool)) or item_val is None:
                row_details[item_key] = item_val
        if callable(scan_entry_strategy_family_from_details):
            row_details["entry_strategy_family"] = scan_entry_strategy_family_from_details(row_details)
        row_details["entry_usable_edge_diagnostic_only"] = True
        row_details["entry_usable_edge_runtime_influence"] = False
        compact_fn = (
            _compact_scan_decision_details
            if callable(_compact_scan_decision_details)
            else _compact_ui_decision_details
        )
        row_details = compact_fn(
            row_details,
            action="entry",
            will_order=False,
        )
        if strategy:
            row_details["strategy"] = strategy
        rows.append(
            (
                int(run_id) if run_id else None,
                str(run_date or ""),
                str(slug or ""),
                str(event_date or ""),
                str(title or ""),
                outcome,
                side,
                "entry",
                "error_timeout",
                0,
                json.dumps(reason_codes, ensure_ascii=False),
                json.dumps([reason_text], ensure_ascii=False),
                json.dumps(row_details, ensure_ascii=False, separators=(",", ":")),
                now_iso,
            )
        )
    if not rows:
        return 0
    try:
        with open_db(timeout_sec=0.3, busy_timeout_ms=300) as conn:
            ensure_fact_tables(conn)
            cur = conn.cursor()
            insert_auto_trade_decision_rows(cur, rows)
            conn.commit()
            return len(rows)
    except Exception:
        return 0


def run_auto_trade_for_date(
    run_date: str,
    *,
    exit_only: bool = False,
    update_state: bool = True,
) -> Dict[str, Any]:
    if scan_execute_auto_trades is None:
        return {"ok": False, "error": "auto_trade_unavailable"}
    if not DB_PATH.exists():
        return {"ok": False, "error": "db_missing"}
    timeout_raw = str(os.environ.get("PM_AUTO_TRADE_EVENT_TIMEOUT_SEC", "60") or "").strip()
    try:
        event_timeout_sec = float(timeout_raw)
    except Exception:
        event_timeout_sec = 60.0
    if event_timeout_sec < 0:
        event_timeout_sec = 0.0
    backoff_raw = str(os.environ.get("PM_AUTO_TRADE_EVENT_BACKOFF_SEC", "2") or "").strip()
    try:
        event_backoff_sec = float(backoff_raw)
    except Exception:
        event_backoff_sec = 2.0
    if event_backoff_sec < 0:
        event_backoff_sec = 0.0
    timeout_inline_retry = _env_bool("PM_AUTO_TRADE_EVENT_TIMEOUT_INLINE_RETRY", False)
    if update_state:
        with AUTO_TRADE_RUN_LOCK:
            # Real-time progress for UI/diagnostics (SSOT).
            AUTO_TRADE_RUN_STATE["stage"] = "load_facts"
            AUTO_TRADE_RUN_STATE["progress_at"] = now_text()
            AUTO_TRADE_RUN_STATE["total"] = 0
            AUTO_TRADE_RUN_STATE["current_slug"] = ""
            AUTO_TRADE_RUN_STATE["current_event_date"] = ""
            AUTO_TRADE_RUN_STATE["current_title"] = ""
    facts_timeout_raw = str(os.environ.get("PM_AUTO_TRADE_FACTS_TIMEOUT_SEC", "8") or "").strip()
    try:
        facts_timeout_sec = float(facts_timeout_raw)
    except Exception:
        facts_timeout_sec = 8.0
    if facts_timeout_sec < 0:
        facts_timeout_sec = 0.0
    allow_backfill = _env_bool("PM_FACTS_ALLOW_READ_BACKFILL", False)
    t0 = time.monotonic()
    run_date_key, rows, rows_err = _auto_trade_load_rows_direct(run_date, allow_backfill)
    elapsed = time.monotonic() - t0
    if facts_timeout_sec > 0 and elapsed > facts_timeout_sec:
        rows_err = "facts_timeout"
    if rows_err:
        if update_state:
            with AUTO_TRADE_RUN_LOCK:
                AUTO_TRADE_RUN_STATE["stage"] = "load_facts_timeout"
                AUTO_TRADE_RUN_STATE["progress_at"] = now_text()
        return {"ok": False, "error": rows_err}
    if not run_date_key:
        return {"ok": False, "error": "no_run_date"}
    if update_state:
        with AUTO_TRADE_RUN_LOCK:
            AUTO_TRADE_RUN_STATE["stage"] = "loop"
            AUTO_TRADE_RUN_STATE["progress_at"] = now_text()
            AUTO_TRADE_RUN_STATE["total"] = int(len(rows) if rows else 0)
    seen: set[Tuple[str, str]] = set()
    candidates: List[Tuple[float, str, str, Dict[str, Any], List[Dict[str, str]]]] = []
    processed = 0
    skipped = 0
    for row in rows:
        slug = str(row["slug"] or "")
        event_date = str(row["event_date"] or "")
        key = (slug, event_date)
        if not slug or not event_date:
            skipped += 1
            continue
        if key in seen:
            continue
        seen.add(key)
        try:
            fact = json.loads(str(row["fact_json"] or ""))
        except json.JSONDecodeError:
            skipped += 1
            continue
        if not isinstance(fact, dict):
            skipped += 1
            continue
        rows_payload = fact.get("distribution") or fact.get("rows") or []
        if not isinstance(rows_payload, list) or not rows_payload:
            skipped += 1
            continue
        payload = dict(fact)
        payload["rows"] = rows_payload
        if not payload.get("event_url"):
            payload["event_url"] = str(fact.get("event_url") or "")
        if not payload.get("title"):
            payload["title"] = str(fact.get("title") or "")
        # For entry runs, only process "today entry-ok" events so one unrelated slow event won't
        # block the whole loop (SSOT: same entry_ok list shown in UI).
        if not exit_only:
            payload.setdefault("distribution", rows_payload)
            ssot = _get_or_build_auto_trade_ssot(payload)
            cand_main = ssot.get("main_candidate") if isinstance(ssot, dict) else None
            cand_yes_top = ssot.get("model_yes_top_candidate") if isinstance(ssot, dict) else None
            main_ok = isinstance(cand_main, dict) and bool(cand_main.get("entry_ok"))
            yes_top_enabled = _env_bool("PM_AUTO_TRADE_ENTRY_YES_TOP_ENABLED", False)
            yes_top_only = _env_bool("PM_AUTO_TRADE_ENTRY_YES_TOP_ONLY", False)
            follow_enabled = _env_bool("PM_AUTO_TRADE_ENTRY_FOLLOW_ENABLED", False)
            hard_bound_enabled = _env_bool("PM_AUTO_TRADE_ENTRY_HARD_BOUND_NO_ENABLED", False)
            adj_pair_enabled = _env_bool("PM_AUTO_TRADE_ENTRY_ADJ_PAIR_ENABLED", False)
            lcb_global_enabled = _env_bool("PM_LCB_GLOBAL_ENABLED", False)
            yes_top_ok = (
                yes_top_enabled
                and isinstance(cand_yes_top, dict)
                and bool(cand_yes_top.get("entry_ok"))
            )
            runtime_strategy_enabled = (
                lcb_global_enabled
                or follow_enabled
                or hard_bound_enabled
                or adj_pair_enabled
            )
            event_entry_ok = yes_top_ok if yes_top_only else (main_ok or yes_top_ok or runtime_strategy_enabled)
            if not event_entry_ok:
                skipped += 1
                continue
            decision_targets: List[Dict[str, Any]] = []
            def _append_decision_target(strategy: str, cand: Dict[str, Any]) -> None:
                decision_targets.append(
                    {
                        "strategy": strategy,
                        "outcome": str(cand.get("outcome") or ""),
                        "side": str(cand.get("side") or ""),
                        "entry_ok": bool(cand.get("entry_ok")),
                        "entry_reasons": list(cand.get("entry_reasons") or [])
                        if isinstance(cand.get("entry_reasons"), list)
                        else [],
                        "edge_score": to_float(cand.get("edge_score")),
                        "exec_edge_score": to_float(cand.get("exec_edge_score")),
                        "exec_edge_entry": to_float(cand.get("exec_edge_entry")),
                        "exec_edge_exit": to_float(cand.get("exec_edge_exit")),
                        "hold_edge_realizable": to_float(cand.get("hold_edge_realizable")),
                        "hold_edge_realizable_score": to_float(cand.get("hold_edge_realizable_score")),
                        "exit_edge_primary_source": str(cand.get("exit_edge_primary_source") or ""),
                        "edge_realizable": to_float(cand.get("edge_realizable")),
                        "edge_realizable_score": to_float(cand.get("edge_realizable_score")),
                        "exec_fee_bps": to_float(cand.get("exec_fee_bps")),
                        "exec_fee_cost": to_float(cand.get("exec_fee_cost")),
                        "edge_min": to_float(cand.get("edge_min")),
                        "ask": to_float(cand.get("ask")),
                        "q_min_bound": to_float(cand.get("q_min_bound")),
                        "spread": to_float(cand.get("spread")),
                        "lag": to_float(cand.get("lag")),
                        "token_id": str(cand.get("token_id") or ""),
                    }
                )
            if main_ok and isinstance(cand_main, dict):
                _append_decision_target("main", cand_main)
            if decision_targets:
                payload["entry_expected_targets"] = decision_targets
            rank_vals: List[float] = []
            if main_ok and isinstance(cand_main, dict):
                rank_vals.append(_ssot_candidate_rank(cand_main))
            rank = max(rank_vals) if rank_vals else -999.0
            candidates.append((rank, slug, event_date, payload, decision_targets))
        else:
            candidates.append((0.0, slug, event_date, payload, []))
    if not exit_only:
        candidates.sort(key=lambda it: it[0], reverse=True)
        if update_state:
            with AUTO_TRADE_RUN_LOCK:
                AUTO_TRADE_RUN_STATE["stage"] = "loop_entry_ok"
                AUTO_TRADE_RUN_STATE["progress_at"] = now_text()
                AUTO_TRADE_RUN_STATE["total"] = int(len(candidates))
    for _rank, slug, event_date, payload, decision_targets in candidates:
        run_id: Optional[int] = None
        if update_state:
            with AUTO_TRADE_RUN_LOCK:
                AUTO_TRADE_RUN_STATE["stage"] = "execute_auto_trades"
                AUTO_TRADE_RUN_STATE["progress_at"] = now_text()
                AUTO_TRADE_RUN_STATE["current_slug"] = str(payload.get("slug") or slug)
                AUTO_TRADE_RUN_STATE["current_event_date"] = str(event_date)
                AUTO_TRADE_RUN_STATE["current_title"] = str(payload.get("title") or "")
                try:
                    run_id = int(AUTO_TRADE_RUN_STATE.get("run_id") or 0) or None
                except Exception:
                    run_id = None
        def _run_with_timeout() -> Tuple[bool, str]:
            if event_timeout_sec <= 0:
                scan_execute_auto_trades(
                    run_date_key,
                    date_only(event_date),
                    payload,
                    exit_only=exit_only,
                    run_id=run_id,
                )
                return True, ""
            ctx = multiprocessing.get_context("spawn")
            proc: Optional[multiprocessing.Process] = None
            queue: Optional[multiprocessing.Queue] = None
            try:
                queue = ctx.Queue()
                proc = ctx.Process(
                    target=_auto_trade_event_worker,
                    args=(
                        run_date_key,
                        date_only(event_date),
                        payload,
                        exit_only,
                        run_id,
                        queue,
                        event_timeout_sec,
                    ),
                )
                proc.start()
                proc.join(event_timeout_sec)
                if proc.is_alive():
                    try:
                        proc.terminate()
                    except Exception:
                        pass
                    proc.join(2)
                    return False, "event_timeout"
                try:
                    res = queue.get_nowait()
                except Exception:
                    return False, "worker_no_result"
                if bool(res.get("ok")):
                    return True, ""
                err = str(res.get("error") or "worker_failed").strip()
                return False, (err or "worker_failed")
            finally:
                if queue is not None:
                    try:
                        queue.close()
                    except Exception:
                        pass
                    try:
                        queue.join_thread()
                    except Exception:
                        pass
                if proc is not None:
                    try:
                        if proc.is_alive():
                            proc.terminate()
                            proc.join(1)
                    except Exception:
                        pass
                    try:
                        proc.close()
                    except Exception:
                        pass

        def _run_inline_lightweight() -> Tuple[bool, str]:
            overrides: Dict[str, str] = {}
            if not _env_bool("PM_AUTO_TRADE_EVENT_WORKER_SYNC_TRADES", False):
                overrides["PM_AUTO_TRADE_SYNC_TRADES"] = "0"
            if not _env_bool("PM_AUTO_TRADE_EVENT_WORKER_SYNC_OPEN_ORDERS", False):
                overrides["PM_AUTO_TRADE_SYNC_OPEN_ORDERS"] = "0"
            if not _env_bool("PM_AUTO_TRADE_EVENT_WORKER_LIVE_VOLUME_GATE", False):
                overrides["PM_AUTO_TRADE_ENTRY_OUTCOME_VOLUME_GATE_MODE"] = "pre"
            prev_vals = {k: os.environ.get(k) for k in overrides.keys()}
            try:
                for k, v in overrides.items():
                    os.environ[k] = v
                scan_execute_auto_trades(
                    run_date_key,
                    date_only(event_date),
                    payload,
                    exit_only=exit_only,
                    run_id=run_id,
                )
                return True, ""
            except Exception as exc:
                return False, str(exc)
            finally:
                for k, prev in prev_vals.items():
                    if prev is None:
                        os.environ.pop(k, None)
                    else:
                        os.environ[k] = prev

        ok, err_reason = _run_with_timeout()
        inline_retried = False
        if (
            (not ok)
            and err_reason == "event_timeout"
            and timeout_inline_retry
        ):
            inline_retried = True
            ok_inline, inline_err = _run_inline_lightweight()
            if ok_inline:
                ok = True
                err_reason = ""
                print(
                    f"[auto-trade] event timeout recovered by inline retry {slug} {event_date}"
                )
            else:
                err_reason = f"event_timeout_inline_failed:{inline_err or 'unknown'}"
        if ok:
            processed += 1
        else:
            skipped += 1
            reason_code = "event_worker_failed"
            reason_text = "执行子进程失败"
            if err_reason == "event_timeout":
                reason_code = "event_worker_timeout"
                reason_text = f"执行超时：子进程在 {int(event_timeout_sec)}s 内未完成"
            elif err_reason.startswith("event_timeout_inline_failed:"):
                reason_code = "event_worker_timeout_inline_failed"
                reason_text = "执行超时且内联重试失败"
            elif err_reason:
                reason_text = f"执行子进程失败: {err_reason}"
            print(
                f"[auto-trade] event skipped {slug} {event_date} reason={reason_code} detail={err_reason or '-'}"
            )
            if decision_targets:
                _record_auto_trade_fallback_decisions(
                    run_id=run_id,
                    run_date=run_date_key,
                    slug=slug,
                    event_date=str(event_date or ""),
                    title=str(payload.get('title') or ''),
                    targets=decision_targets,
                    reason_code=reason_code,
                    reason_text=reason_text,
                    details={
                        "source": "auto_trade_event_worker",
                        "worker_error": err_reason,
                        "event_timeout_sec": event_timeout_sec,
                        "inline_retry_enabled": bool(timeout_inline_retry),
                        "inline_retry_attempted": bool(inline_retried),
                    },
                )
            if event_backoff_sec > 0:
                time.sleep(event_backoff_sec)
        if update_state:
            with AUTO_TRADE_RUN_LOCK:
                AUTO_TRADE_RUN_STATE["processed"] = int(processed)
    return {"ok": True, "run_date": run_date, "processed": processed, "skipped": skipped}


def start_auto_trade_run(run_date: str = "", *, force: bool = False) -> Dict[str, Any]:
    if scan_enqueue_auto_trade_job is None:
        return {"started": False, "running": False, "message": "auto_trade_queue_unavailable"}
    if not DB_PATH.exists():
        return {"started": False, "running": False, "message": "db_missing"}
    diag = auto_trade_env_diagnostics()
    if diag.get("dry_run") or diag.get("missing"):
        return {
            "started": False,
            "running": False,
            "message": "auto_trade_env_invalid",
            "detail": auto_trade_env_error_text(diag),
        }
    run_date_key = _normalize_date_key(run_date)
    if not run_date_key:
        try:
            with open_db_ro_fast(timeout_sec=0.2, busy_timeout_ms=200) as conn:
                run_date_key = latest_fact_run_date(conn) or latest_unsettled_run_date(conn) or latest_run_date(conn) or ""
        except Exception:
            run_date_key = ""
    if not run_date_key:
        run_date_key = _today_et_key()
    today_et_key = _today_et_key()
    if run_date_key < today_et_key:
        with AUTO_TRADE_RUN_LOCK:
            AUTO_TRADE_RUN_STATE.update(
                {
                    "running": False,
                    "run_date": run_date_key,
                    "stage": "past_run_date_not_tradeable",
                    "progress_at": now_text(),
                    "error": "",
                }
            )
        return {
            "started": False,
            "running": False,
            "queued": False,
            "message": "past_run_date_not_tradeable",
            "run_date": run_date_key,
            "today_et": today_et_key,
        }

    queue_snapshot = _latest_auto_trade_jobs_snapshot(run_date_key)
    active_job = queue_snapshot.get("active") if isinstance(queue_snapshot, dict) else {}
    if not isinstance(active_job, dict):
        active_job = {}
    active_state = str(active_job.get("state") or "").strip().lower()
    if active_state in {"queued", "running", "retrying"}:
        with AUTO_TRADE_RUN_LOCK:
            AUTO_TRADE_RUN_STATE["run_date"] = run_date_key
            AUTO_TRADE_RUN_STATE["stage"] = f"job_{active_state}"
            AUTO_TRADE_RUN_STATE["progress_at"] = str(active_job.get("updated_at") or now_text())
            AUTO_TRADE_RUN_STATE["running"] = active_state in {"running", "retrying"}
            if active_state in {"running", "retrying"}:
                AUTO_TRADE_RUN_STATE["started_at"] = str(active_job.get("started_at") or AUTO_TRADE_RUN_STATE.get("started_at") or now_text())
        return {
            "started": False,
            "running": active_state in {"running", "retrying"},
            "queued": active_state == "queued",
            "message": "auto_trade_job_active",
            "run_date": run_date_key,
            "job": active_job,
        }

    with AUTO_TRADE_RUN_LOCK:
        state = dict(AUTO_TRADE_RUN_STATE)
        min_interval = AUTO_TRADE_MIN_RUN_INTERVAL_SEC
        if (not force) and min_interval > 0:
            ended_at = str(state.get("ended_at") or "").strip()
            ended_dt = parse_any_ts(ended_at)
            if ended_dt is not None:
                now_dt = datetime.now().astimezone()
                try:
                    age_sec = (now_dt - ended_dt).total_seconds()
                except Exception:
                    age_sec = None
                if age_sec is not None and age_sec >= 0 and age_sec < min_interval:
                    wait_sec = int(max(min_interval - age_sec, 1))
                    return {
                        "started": False,
                        "running": False,
                        "message": "throttled",
                        "wait_sec": wait_sec,
                        "min_interval_sec": int(min_interval),
                        "last_ended_at": ended_at,
                    }
        AUTO_TRADE_RUN_STATE.update(
            {
                "running": False,
                "started_at": "",
                "ended_at": "",
                "error": "",
                "run_date": run_date_key,
                "processed": 0,
                "skipped": 0,
                "run_id": None,
                "total": 0,
                "stage": "job_queued",
                "progress_at": now_text(),
                "current_slug": "",
                "current_event_date": "",
                "current_title": "",
            }
        )
    payload = {"force": bool(force), "requested_from": "ui_server"}
    try:
        enqueue_res = scan_enqueue_auto_trade_job(
            run_date_key,
            source="ui_api",
            priority=120 if force else 100,
            payload=payload,
            force_enqueue=False,
        )
    except Exception as exc:
        with AUTO_TRADE_RUN_LOCK:
            AUTO_TRADE_RUN_STATE["stage"] = "job_enqueue_failed"
            AUTO_TRADE_RUN_STATE["error"] = str(exc)
            AUTO_TRADE_RUN_STATE["progress_at"] = now_text()
        return {
            "started": False,
            "running": False,
            "message": "job_enqueue_failed",
            "run_date": run_date_key,
            "error": str(exc),
        }

    job = enqueue_res.get("job") if isinstance(enqueue_res, dict) else {}
    if not isinstance(job, dict):
        job = {}
    with AUTO_TRADE_RUN_LOCK:
        AUTO_TRADE_RUN_STATE["run_date"] = run_date_key
        AUTO_TRADE_RUN_STATE["stage"] = "job_queued"
        AUTO_TRADE_RUN_STATE["progress_at"] = now_text()
        AUTO_TRADE_RUN_STATE["error"] = ""
        AUTO_TRADE_RUN_STATE["running"] = False
        AUTO_TRADE_RUN_STATE["started_at"] = str(job.get("created_at") or "")
        AUTO_TRADE_RUN_STATE["ended_at"] = ""

    return {
        "started": bool(enqueue_res.get("enqueued")),
        "running": False,
        "queued": True,
        "run_date": run_date_key,
        "message": "auto_trade_job_enqueued" if enqueue_res.get("enqueued") else str(enqueue_res.get("reason") or "auto_trade_job_active"),
        "job": job,
    }


def _format_auto_trade_stage_hint(run_state_public: Optional[Dict[str, Any]]) -> str:
    if not isinstance(run_state_public, dict):
        return ""
    stage = str(run_state_public.get("stage") or "").strip().lower()
    job_state = str(run_state_public.get("job_state") or "").strip().lower()
    if stage.startswith("job_") and not job_state:
        job_state = stage.replace("job_", "", 1)
    current = str(run_state_public.get("current_title") or "").strip()
    if job_state == "queued" or stage == "job_queued":
        return "队列排队中，等待 worker 领取任务"
    if job_state == "running" or stage == "job_running":
        if current:
            return f"worker 执行中 · 当前={current}"
        return "worker 执行中"
    if job_state == "retrying" or stage == "job_retrying":
        retry_count = int(run_state_public.get("job_retry_count") or 0)
        max_retry = int(run_state_public.get("job_max_retry") or 0)
        next_retry_at = str(run_state_public.get("job_next_retry_at") or "").strip()
        next_dt = parse_any_ts(next_retry_at) if next_retry_at else None
        eta_text = ""
        if next_dt is not None:
            try:
                remain = int(max(0.0, (next_dt - datetime.now().astimezone()).total_seconds()))
                eta_text = f" · 下次重试约{remain}s"
            except Exception:
                eta_text = ""
        if max_retry > 0:
            return f"worker 重试中({retry_count}/{max_retry}){eta_text}"
        return f"worker 重试中{eta_text}"
    if stage:
        return f"执行阶段 {stage}"
    return ""


def _build_auto_trade_trace(
    entry: Dict[str, Any],
    no_order_reasons: List[str],
    auto_run_inflight: bool,
    wait_sec: Optional[int],
    last_run_row: Optional[Dict[str, Any]],
    run_state_public: Optional[Dict[str, Any]] = None,
) -> Dict[str, Any]:
    def _step(label: str, status: str, detail: str = "", at: str = "") -> Dict[str, Any]:
        return {
            "label": label,
            "status": status,
            "detail": detail,
            "at": at,
        }

    entry_ok = bool(entry.get("entry_ok"))
    decision = entry.get("entry_decision") if isinstance(entry.get("entry_decision"), dict) else None
    order = entry.get("entry_order") if isinstance(entry.get("entry_order"), dict) else None
    hist_order = entry.get("entry_order_historical") if isinstance(entry.get("entry_order_historical"), dict) else None
    trade = entry.get("trade_info") if isinstance(entry.get("trade_info"), dict) else {}
    fills_count = to_float(trade.get("fills_count"))
    position_size = to_float(trade.get("position_size"))
    fills_i = int(fills_count or 0) if fills_count is not None and math.isfinite(fills_count) else 0
    pos_val = float(position_size) if position_size is not None and math.isfinite(position_size) else 0.0
    has_position = bool(pos_val > TIME_EDGE_Q_EPS)
    has_fill_history = bool(fills_i > 0)
    had_entry = False

    steps: List[Dict[str, Any]] = []
    steps.append(_step("入场条件", "ok" if entry_ok else "warn", "达标" if entry_ok else "待达标"))

    dec_status = "warn"
    dec_detail = ""
    dec_at = ""
    will_order = None
    decision_failed = False
    decision_failed_detail = ""
    if isinstance(decision, dict):
        will_order = int(decision.get("will_order") or 0)
        dec_state = str(decision.get("decided_state") or "").strip()
        dec_at = str(decision.get("created_at") or "").strip()
        reason_codes = decision.get("reason_codes") if isinstance(decision.get("reason_codes"), list) else []
        reason_text = str(decision.get("reason_text") or "").strip()
        reason_detail = str(decision.get("reason_detail") or "").strip()
        if will_order == 0 and dec_state and dec_state != "entry_ok":
            dec_status = "bad"
            base_text = reason_text or (reason_codes[0] if reason_codes else dec_state)
            if (
                isinstance(reason_codes, list)
                and any(str(code or "").strip() in {"market_tick_stale", "market_tick_missing"} for code in reason_codes)
                and reason_detail
                and reason_detail != base_text
            ):
                if reason_detail.startswith(base_text):
                    dec_detail = reason_detail
                else:
                    dec_detail = f"{base_text} · {reason_detail}"
            else:
                dec_detail = base_text
        else:
            dec_status = "ok" if dec_state else "warn"
            dec_detail = dec_state or "已生成"
        if dec_state in {"entry_failed", "place_order_failed", "place_order_error"} or any(
            str(code or "").strip() in {"place_order_failed", "order_price_invalid", "order_size_invalid", "strategy_size_ratio_zero"}
            for code in reason_codes
        ):
            decision_failed = True
            decision_failed_detail = reason_detail or reason_text or dec_state or "下单失败"
        if has_position and dec_status == "bad":
            dec_status = "ok"
            dec_detail = "已持仓(本轮未再入场)"
    else:
        dec_status = "warn"
        if auto_run_inflight:
            dec_detail = _format_auto_trade_stage_hint(run_state_public) or "等待本轮决策"
        elif wait_sec is not None and wait_sec > 0:
            dec_detail = f"节流剩余{int(wait_sec)}s"
        else:
            last_run_ts = ""
            if isinstance(last_run_row, dict):
                last_run_ts = str(last_run_row.get("ended_at") or "") or str(last_run_row.get("started_at") or "")
            dec_detail = f"未生成决策{f' · 最近{last_run_ts}' if last_run_ts else ''}"
    state_text = str(trade.get("state") or "").strip().lower()
    hist_closed_before_decision = False
    if isinstance(hist_order, dict):
        hist_order_dt = parse_any_ts(str(hist_order.get("created_at") or ""))
        dec_dt = parse_any_ts(dec_at) if dec_at else None
        if (
            state_text == "exit"
            and pos_val <= TIME_EDGE_Q_EPS
            and fills_i > 0
            and hist_order_dt is not None
            and dec_dt is not None
            and dec_dt > hist_order_dt
        ):
            hist_closed_before_decision = True
            if dec_status == "bad":
                dec_status = "warn"
                if dec_detail:
                    dec_detail = f"{dec_detail}(本轮未再入场)"
    if state_text == "exit" and not has_position and has_fill_history and dec_status == "bad":
        dec_status = "ok"
        dec_detail = "历史持仓已退出(本轮未再入场)"
    steps.append(_step("决策", dec_status, dec_detail, dec_at))

    order_status = "skip"
    order_detail = ""
    order_at = ""
    if isinstance(order, dict) and order.get("order_id"):
        order_status = "ok"
        order_detail = str(order.get("order_status") or order.get("order_id") or "").strip()
        order_at = str(order.get("created_at") or "").strip()
        had_entry = True
    elif isinstance(hist_order, dict) and hist_order.get("order_id"):
        order_status = "ok"
        hist_order_id = str(hist_order.get("order_id") or "").strip()
        if dec_status == "bad" and not has_position:
            blocked_reason = dec_detail or "决策阻断"
            order_detail = f"历史单已结束(本轮阻断: {blocked_reason})"
        else:
            order_detail = f"历史下单 {hist_order_id}"
        order_at = str(hist_order.get("created_at") or "").strip()
        had_entry = True
    else:
        if state_text == "exit" and not has_position and has_fill_history:
            order_status = "ok"
            order_detail = "历史成交已完成"
            had_entry = True
        elif has_position and will_order != 1:
            order_status = "ok"
            order_detail = "已有持仓(不重复下单)"
            had_entry = True
        elif decision_failed:
            order_status = "bad"
            order_detail = decision_failed_detail or "下单失败"
        elif will_order == 1:
            order_status = "warn"
            order_detail = "待下单"
        elif dec_status == "bad":
            order_status = "skip"
            order_detail = "决策阻断"
        else:
            order_status = "warn"
            order_detail = "未下单"
    steps.append(_step("下单", order_status, order_detail, order_at))

    fill_status = "skip"
    fill_detail = ""
    fill_at = str(trade.get("last_fill_at") or "").strip()
    trade_last_status = str(trade.get("last_status") or "").strip().lower()
    trade_last_action = str(trade.get("last_action") or "").strip().lower()
    trade_last_error = str(trade.get("last_error") or "").strip().lower()
    open_order_inflight = (
        trade_last_status in {
            "open_order_wait",
            "open_order_recheck_pending",
            "open_order_sync",
            "open_order_exists",
            "open_order_recheck",
        }
        or trade_last_error.startswith("open_order_")
    )
    has_trade_history = bool(trade_last_status or trade_last_action or trade_last_error or fill_at)
    no_fill_cancelled = (
        fills_i <= 0
        and pos_val <= TIME_EDGE_Q_EPS
        and state_text == "exit"
        and (
            trade_last_status in {"open_order_cancelled", "open_order_cleared", "open_order_cancel_empty"}
            or trade_last_action == "open_order_cancel"
        )
    )
    if has_fill_history or has_position:
        fill_status = "ok"
        fill_detail = f"持仓{pos_val:.2f} · 成交{fills_i}" if has_position else f"已平仓 · 成交{fills_i}"
        had_entry = True
    elif no_fill_cancelled:
        fill_status = "ok"
        fill_detail = "未成交(挂单已撤单)"
    elif order_status == "ok":
        fill_status = "warn"
        fill_detail = "挂单在途" if open_order_inflight else "待成交"
    no_fill_exit = (fills_i <= 0 and pos_val <= TIME_EDGE_Q_EPS and state_text == "exit")
    if no_fill_exit and fill_status in {"warn", "skip"}:
        if had_entry or order_status == "ok":
            fill_status = "ok"
            fill_detail = fill_detail or "未成交"
        elif dec_status == "warn":
            fill_status = "warn"
            fill_detail = "待处理"
        else:
            fill_status = "skip"
            fill_detail = "未成交"
    if (
        fill_status == "ok"
        and not has_position
        and not has_fill_history
        and order_status != "ok"
        and not had_entry
        and not has_trade_history
    ):
        fill_status = "warn" if dec_status == "warn" else "skip"
        fill_detail = "待处理" if dec_status == "warn" else "未成交"
    steps.append(_step("成交/持仓", fill_status, fill_detail, fill_at))

    exit_status = "skip"
    exit_detail = ""
    exit_at = str(trade.get("exit_triggered_at") or "").strip()
    exit_skip_reason = str(trade.get("exit_skip_reason") or "").strip()
    exit_skip_detail = str(trade.get("exit_skip_detail") or "").strip()

    def _fmt_exit_skip(reason_text: str, detail_text: str) -> str:
        reason_key = str(reason_text or "").strip().lower()
        raw_detail = str(detail_text or "").strip()
        if reason_key == "exit_retry_blocked":
            return "退出重试冷却中"
        if reason_key == "no_orderbook":
            return f"退出盘口缺失({raw_detail})" if raw_detail else "退出盘口缺失(no_orderbook)"
        if reason_key == "exit_no_trigger":
            def _pct(name: str) -> Optional[float]:
                m = re.search(rf"{re.escape(name)}=(-?\d+(?:\.\d+)?)%", raw_detail)
                if not m:
                    return None
                try:
                    return float(m.group(1))
                except Exception:
                    return None
            pnl_pct = _pct("pnl")
            dd_pct = _pct("dd")
            sl_pct = _pct("sl")
            trail_pct = _pct("trail")
            threshold_hit = False
            if pnl_pct is not None and sl_pct is not None:
                threshold_hit = threshold_hit or (pnl_pct <= -abs(sl_pct))
            if dd_pct is not None and trail_pct is not None:
                threshold_hit = threshold_hit or (dd_pct <= -abs(trail_pct))
            if threshold_hit:
                return (
                    f"退出未执行：已触及阈值，等待流动性/确认({raw_detail})"
                    if raw_detail
                    else "退出未执行：已触及阈值，等待流动性/确认"
                )
            return f"退出条件未触发({raw_detail})" if raw_detail else "退出条件未触发"
        if raw_detail and raw_detail != reason_text:
            return f"{reason_text}({raw_detail})"
        return reason_text

    state = str(trade.get("state") or "").strip()
    if had_entry:
        if state == "exit" and pos_val <= TIME_EDGE_Q_EPS:
            if has_fill_history:
                exit_status = "ok"
                exit_detail = "已退出"
            else:
                exit_status = "skip"
                exit_detail = "未成交"
        elif exit_skip_reason:
            exit_status = "warn"
            exit_detail = _fmt_exit_skip(exit_skip_reason, exit_skip_detail)
        elif state and state != "exit":
            exit_status = "warn"
            exit_detail = f"state={state}"
    else:
        exit_status = "skip"
        exit_detail = "未入场"
    steps.append(_step("退出", exit_status, exit_detail, exit_at))

    if not entry_ok:
        if has_position:
            steps[0]["status"] = "ok"
            steps[0]["detail"] = "已入场(当前未达标)"
        elif had_entry or has_fill_history or isinstance(hist_order, dict):
            steps[0]["status"] = "ok"
            steps[0]["detail"] = "历史已达标(本轮未达标)"

    bottleneck = ""
    flow_status = "ok"
    flow_step = ""
    if has_position and exit_status in {"warn", "bad"}:
        flow_status = "blocked" if exit_status == "bad" else "pending"
        flow_step = "退出"
        bottleneck = exit_detail or "等待退出条件"
    else:
        for step in steps[1:]:
            status = step.get("status")
            if status == "bad":
                flow_status = "blocked"
                bottleneck = step.get("detail") or step.get("label") or ""
                flow_step = step.get("label") or ""
                break
        if flow_status != "blocked":
            for step in steps[1:]:
                status = step.get("status")
                if status == "warn":
                    flow_status = "pending"
                    bottleneck = step.get("detail") or step.get("label") or ""
                    flow_step = step.get("label") or ""
                    break
    if not bottleneck and no_order_reasons:
        bottleneck = str(no_order_reasons[0] or "")
    if not flow_step:
        for step in steps:
            if step.get("status") in ("bad", "warn"):
                flow_step = step.get("label") or ""
                break
    if not flow_step and exit_status == "ok":
        flow_step = "退出"
    if hist_closed_before_decision and exit_status == "ok":
        flow_status = "ok"
        flow_step = "退出"
        bottleneck = ""

    return {
        "flow_status": flow_status,
        "flow_step": flow_step,
        "bottleneck": bottleneck,
        "steps": steps,
    }


def _load_auto_trade_run_context() -> Dict[str, Any]:
    diag = auto_trade_env_diagnostics()
    auto_enabled = bool(diag.get("enabled"))
    auto_dry_run = bool(diag.get("dry_run"))
    missing_env = diag.get("missing") if isinstance(diag.get("missing"), list) else []
    with AUTO_TRADE_RUN_LOCK:
        run_state = dict(AUTO_TRADE_RUN_STATE)
    jobs_snapshot = _latest_auto_trade_jobs_snapshot(str(run_state.get("run_date") or ""))
    active_job = jobs_snapshot.get("active") if isinstance(jobs_snapshot, dict) else {}
    if not isinstance(active_job, dict):
        active_job = {}
    active_state = str(active_job.get("state") or "").strip().lower()
    if active_state in {"queued", "running", "retrying"}:
        run_state["run_date"] = str(active_job.get("run_date") or run_state.get("run_date") or "")
        run_state["stage"] = f"job_{active_state}"
        run_state["progress_at"] = str(active_job.get("updated_at") or run_state.get("progress_at") or "")
        if active_state in {"running", "retrying"}:
            run_state["running"] = True
            run_state["started_at"] = str(active_job.get("started_at") or run_state.get("started_at") or "")
        else:
            run_state["running"] = False
            if not run_state.get("started_at"):
                run_state["started_at"] = str(active_job.get("created_at") or "")
    min_interval = AUTO_TRADE_MIN_RUN_INTERVAL_SEC
    ended_at = str(run_state.get("ended_at") or "").strip()
    ended_dt = parse_any_ts(ended_at)
    started_at_state = str(run_state.get("started_at") or "").strip()
    started_dt_state = parse_any_ts(started_at_state) if started_at_state else None
    now_dt = datetime.now().astimezone()
    wait_sec = None
    if min_interval > 0 and ended_dt is not None:
        try:
            age = (now_dt - ended_dt).total_seconds()
        except Exception:
            age = None
        if age is not None and age >= 0 and age < min_interval:
            wait_sec = int(max(min_interval - age, 0))
    if active_state in {"queued", "running", "retrying"}:
        wait_sec = 0
    running_age_sec = None
    if bool(run_state.get("running")) and started_dt_state is not None:
        try:
            running_age_sec = max(0.0, (now_dt - started_dt_state).total_seconds())
        except Exception:
            running_age_sec = None
    scan_state = load_scan_state()
    scan_running = False
    scan_pid = scan_state.get("pid")
    if scan_state.get("running") and scan_pid:
        try:
            scan_running = pid_running(int(scan_pid))
        except Exception:
            scan_running = False
    run_state_public = {
        "running": bool(run_state.get("running")),
        "started_at": str(run_state.get("started_at") or ""),
        "ended_at": str(run_state.get("ended_at") or ""),
        "error": str(run_state.get("error") or ""),
        "run_date": str(run_state.get("run_date") or ""),
        "processed": int(run_state.get("processed") or 0),
        "skipped": int(run_state.get("skipped") or 0),
        "total": int(run_state.get("total") or 0),
        "stage": str(run_state.get("stage") or ""),
        "progress_at": str(run_state.get("progress_at") or ""),
        "current_slug": str(run_state.get("current_slug") or ""),
        "current_event_date": str(run_state.get("current_event_date") or ""),
        "current_title": str(run_state.get("current_title") or ""),
        "run_id": run_state.get("run_id"),
    }
    if active_state in {"queued", "running", "retrying"}:
        run_state_public["job_state"] = active_state
        run_state_public["job_id"] = active_job.get("id")
        run_state_public["job_retry_count"] = int(active_job.get("retry_count") or 0)
        run_state_public["job_max_retry"] = int(active_job.get("max_retry") or 0)
        run_state_public["job_next_retry_at"] = str(active_job.get("next_retry_at") or "")
        run_state_public["job_last_error"] = str(active_job.get("last_error") or "")
        if active_state == "queued":
            run_state_public["running"] = False
            run_state_public["stage"] = "job_queued"
            run_state_public["progress_at"] = str(active_job.get("updated_at") or run_state_public.get("progress_at") or "")
        else:
            run_state_public["running"] = True
            run_state_public["stage"] = f"job_{active_state}"
            run_state_public["started_at"] = str(active_job.get("started_at") or run_state_public.get("started_at") or "")
            run_state_public["progress_at"] = str(active_job.get("updated_at") or run_state_public.get("progress_at") or "")
    return {
        "diag": diag,
        "auto_enabled": auto_enabled,
        "auto_dry_run": auto_dry_run,
        "missing_env": missing_env,
        "run_state": run_state,
        "run_state_public": run_state_public,
        "wait_sec": wait_sec,
        "running_age_sec": running_age_sec,
        "scan_state": {
            "running": bool(scan_running),
            "pid": int(scan_pid) if scan_pid else None,
            "started_at": str(scan_state.get("started_at") or ""),
            "ended_at": str(scan_state.get("ended_at") or ""),
        },
        "jobs": jobs_snapshot,
        "now_dt": now_dt,
    }


def _format_auto_trade_decision_detail(decision: Dict[str, Any]) -> str:
    reason_codes = decision.get("reason_codes") if isinstance(decision.get("reason_codes"), list) else []
    reasons = decision.get("reasons") if isinstance(decision.get("reasons"), list) else []
    details = decision.get("details") if isinstance(decision.get("details"), dict) else {}
    code = str(reason_codes[0] or "").strip() if reason_codes else ""
    reason = str(reasons[0] or "").strip() if reasons else ""
    metric_parts: List[str] = []
    if isinstance(details, dict):
        for key in (
            "signal_edge",
            "signal_edge_min",
            "spread",
            "spread_max",
            "ask",
            "ask_min",
            "ask_max",
            "q_entry",
            "q_min",
            "q_max",
            "ask_le_q_limit",
            "threshold",
            "volume",
            "market_tick_age_sec",
            "market_tick_stale_sec",
            "follow_market_tick_stale_sec",
        ):
            val = to_float(details.get(key))
            if val is None or not math.isfinite(val):
                continue
            digits = 4 if abs(val) < 10 else 3
            metric_parts.append(f"{key}={val:.{digits}f}")
        for key in ("volume_reason", "worker_error", "strategy", "market_tick_refresh_note"):
            text = str(details.get(key) or "").strip()
            if text:
                metric_parts.append(f"{key}={text}")
    metrics = ", ".join(metric_parts[:4])
    base = reason or code
    if not base:
        base = str(decision.get("decided_state") or "").strip()
    if metrics and base:
        return f"{base} · {metrics}"
    return base


def _build_tradeability_gate_snapshot(
    entry: Dict[str, Any],
    decision: Optional[Dict[str, Any]],
) -> Dict[str, Any]:
    details = decision.get("details") if isinstance(decision, dict) and isinstance(decision.get("details"), dict) else {}
    if not isinstance(details, dict):
        details = {}

    def _v(*vals: Any) -> Optional[float]:
        for raw in vals:
            val = to_float(raw)
            if val is not None and math.isfinite(val):
                return float(val)
        return None

    eps = float(TIME_EDGE_Q_EPS)
    signal_lcb_min_env = _env_float("PM_LCB_GLOBAL_SIGNAL_LCB_MIN", 0.0)
    if signal_lcb_min_env is None or not math.isfinite(signal_lcb_min_env):
        signal_lcb_min_env = 0.0
    signal_lcb_min_env = float(signal_lcb_min_env)
    path_lcb_min_env = _env_float("PM_LCB_GLOBAL_PATH_LCB_MIN", 0.0)
    if path_lcb_min_env is None or not math.isfinite(path_lcb_min_env):
        path_lcb_min_env = 0.0
    path_lcb_min_env = max(0.0, min(1.0, float(path_lcb_min_env)))

    edge_lcb_val = _v(
        details.get("edge_tradeability_profit_value"),
        details.get("edge_tradeability_edge_lcb"),
        entry.get("edge_tradeability_profit_value"),
        entry.get("edge_tradeability_edge_lcb"),
        entry.get("edge_realizable_v2"),
        entry.get("edge_realizable"),
    )
    edge_lcb_min = _v(
        details.get("edge_realizable_hq_edge_lcb_min"),
        details.get("edge_tradeability_profit_min"),
        details.get("edge_tradeability_edge_lcb_min"),
        entry.get("edge_realizable_hq_edge_lcb_min"),
        entry.get("edge_tradeability_profit_min"),
        entry.get("edge_tradeability_edge_lcb_min"),
        0.0,
    )
    if edge_lcb_min is None:
        edge_lcb_min = 0.0
    edge_lcb_min = float(edge_lcb_min)
    edge_lcb_pass = bool(
        edge_lcb_val is not None and math.isfinite(edge_lcb_val) and edge_lcb_val + eps >= edge_lcb_min
    )
    edge_lcb_status = "pass" if edge_lcb_pass else ("missing" if edge_lcb_val is None else "fail")

    signal_lcb_val = _v(details.get("edge_signal_lcb"), entry.get("edge_signal_lcb"))
    signal_lcb_min = _v(
        details.get("edge_tradeability_signal_lcb_min"),
        entry.get("edge_tradeability_signal_lcb_min"),
        signal_lcb_min_env,
    )
    signal_soft_band_override = bool(
        details.get("edge_tradeability_signal_soft_band_override")
        if "edge_tradeability_signal_soft_band_override" in details
        else entry.get("edge_tradeability_signal_soft_band_override")
    )
    signal_soft_band_shadow = bool(
        details.get("edge_tradeability_signal_soft_band_shadow")
        if "edge_tradeability_signal_soft_band_shadow" in details
        else entry.get("edge_tradeability_signal_soft_band_shadow")
    )
    if signal_lcb_min is None:
        signal_lcb_min = 0.0
    signal_lcb_min = float(signal_lcb_min)
    signal_lcb_enabled = bool(signal_lcb_min > eps)
    if not signal_lcb_enabled:
        signal_lcb_pass = True
        signal_lcb_status = "off"
    elif signal_lcb_val is None:
        signal_lcb_pass = False
        signal_lcb_status = "missing"
    else:
        signal_lcb_pass = bool(signal_lcb_val + eps >= signal_lcb_min)
        signal_lcb_status = "pass" if signal_lcb_pass else "fail"
    if signal_soft_band_override:
        signal_lcb_pass = True
        signal_lcb_status = "bypass"

    path_lcb_val = _v(details.get("edge_path_p_reach_lcb"), entry.get("edge_path_p_reach_lcb"))
    path_lcb_min = _v(
        details.get("edge_tradeability_path_lcb_min"),
        entry.get("edge_tradeability_path_lcb_min"),
        path_lcb_min_env,
    )
    if path_lcb_min is None:
        path_lcb_min = 0.0
    path_lcb_min = max(0.0, min(1.0, float(path_lcb_min)))
    path_lcb_enabled = bool(path_lcb_min > eps)
    if not path_lcb_enabled:
        path_lcb_pass = True
        path_lcb_status = "off"
    elif path_lcb_val is None:
        path_lcb_pass = False
        path_lcb_status = "missing"
    else:
        path_lcb_pass = bool(path_lcb_val + eps >= path_lcb_min)
        path_lcb_status = "pass" if path_lcb_pass else "fail"

    overall_pass = bool(edge_lcb_pass and signal_lcb_pass and path_lcb_pass)
    if overall_pass:
        overall_status = "pass"
    elif (
        edge_lcb_status == "missing"
        and signal_lcb_status in {"missing", "off"}
        and path_lcb_status in {"missing", "off"}
    ):
        overall_status = "missing"
    else:
        overall_status = "fail"

    return {
        "overall": {"pass": overall_pass, "status": overall_status},
        "edge_lcb": {
            "value": edge_lcb_val,
            "min": edge_lcb_min,
            "pass": edge_lcb_pass,
            "status": edge_lcb_status,
        },
        "signal_lcb": {
            "value": signal_lcb_val,
            "min": signal_lcb_min,
            "enabled": signal_lcb_enabled,
            "pass": signal_lcb_pass,
            "status": signal_lcb_status,
        },
        "path_lcb": {
            "value": path_lcb_val,
            "min": path_lcb_min,
            "enabled": path_lcb_enabled,
            "pass": path_lcb_pass,
            "status": path_lcb_status,
        },
        "soft_band": {
            "override": signal_soft_band_override,
            "shadow": signal_soft_band_shadow,
            "mode": str(
                details.get("edge_tradeability_signal_soft_band_mode")
                or entry.get("edge_tradeability_signal_soft_band_mode")
                or ""
            ),
            "min": _v(
                details.get("edge_tradeability_signal_soft_band_min"),
                entry.get("edge_tradeability_signal_soft_band_min"),
            ),
            "max": _v(
                details.get("edge_tradeability_signal_soft_band_max"),
                entry.get("edge_tradeability_signal_soft_band_max"),
            ),
            "size_ratio": _v(
                details.get("edge_tradeability_signal_soft_band_size_ratio"),
                entry.get("edge_tradeability_signal_soft_band_size_ratio"),
            ),
        },
    }


def _refresh_entry_tradeability_gate(
    entry: Dict[str, Any],
    decision: Optional[Dict[str, Any]] = None,
) -> None:
    if not isinstance(entry, dict):
        return
    entry["tradeability_gate"] = _build_tradeability_gate_snapshot(
        entry,
        decision if isinstance(decision, dict) else None,
    )


def _tradeability_reason_texts(
    gate: Dict[str, Any],
    reason_codes: Any = None,
) -> List[str]:
    out: List[str] = []
    gate_dict = gate if isinstance(gate, dict) else {}
    codes_raw = reason_codes
    if isinstance(codes_raw, str):
        codes = [str(x or "").strip() for x in codes_raw.split(",") if str(x or "").strip()]
    elif isinstance(codes_raw, list):
        codes = [str(x or "").strip() for x in codes_raw if str(x or "").strip()]
    else:
        codes = []
    code_set = set(codes)

    def _append(text: str) -> None:
        value = str(text or "").strip()
        if value and value not in out:
            out.append(value)

    def _fmt_metric(raw: Any, digits: int) -> str:
        val = to_float(raw)
        if val is None or not math.isfinite(val):
            return "—"
        return f"{float(val):.{digits}f}"

    metric_map = (
        ("signal_lcb", "signal_lcb", 3, "signal_lcb_missing", "signal_lcb_below_min"),
        ("path_lcb", "path_lcb", 3, "path_lcb_missing", "path_lcb_below_min"),
        ("edge_lcb", "edge_lcb", 4, "edge_lcb_missing", "edge_lcb_below_min"),
    )
    for gate_key, label, digits, missing_code, below_code in metric_map:
        metric = gate_dict.get(gate_key) if isinstance(gate_dict.get(gate_key), dict) else {}
        status = str(metric.get("status") or "").strip().lower()
        if missing_code in code_set or status == "missing":
            _append(f"{label}缺失")
            continue
        if below_code in code_set or status == "fail":
            value_text = _fmt_metric(metric.get("value"), digits)
            min_text = _fmt_metric(metric.get("min"), digits)
            _append(f"{label}={value_text}<{min_text}")

    if "v2_missing" in code_set:
        _append("可兑现V2缺失")
    if "exec_audit_not_pass" in code_set:
        _append("执行审计门未通过")
    if not out and codes:
        _append(f"路径概率跟随门禁未通过({','.join(codes)})")
    return out


def _decorate_entry_execution(
    entry: Dict[str, Any],
    *,
    decisions_by_key: Dict[Tuple[str, str, str, str], Dict[str, Any]],
    decisions_by_key_strategy: Optional[Dict[Tuple[str, str, str, str, str], Dict[str, Any]]] = None,
    decisions_by_event: Dict[Tuple[str, str], List[Dict[str, Any]]],
    entry_orders_by_key: Dict[Tuple[str, str, str, str], Dict[str, Any]],
    entry_orders_by_key_strategy: Optional[Dict[Tuple[str, str, str, str, str], Dict[str, Any]]] = None,
    auto_run_inflight: bool,
    wait_sec: Optional[int],
    last_run_row: Optional[Dict[str, Any]],
    run_state_public: Dict[str, Any],
    now_dt: datetime,
) -> None:
    order_key = (
        str(entry.get("slug") or ""),
        str(entry.get("event_date") or ""),
        str(entry.get("outcome") or ""),
        str(entry.get("side") or "").upper(),
    )
    strategy_key = str(entry.get("strategy") or "").strip().lower() or "main"

    def _resolve_decision() -> Optional[Dict[str, Any]]:
        if isinstance(decisions_by_key_strategy, dict):
            decision_by_strategy = decisions_by_key_strategy.get(
                (order_key[0], order_key[1], order_key[2], order_key[3], strategy_key)
            )
            if isinstance(decision_by_strategy, dict):
                return decision_by_strategy
        decision_fallback = decisions_by_key.get(order_key)
        if isinstance(decision_fallback, dict):
            return decision_fallback
        return None

    decision = _resolve_decision()
    _refresh_entry_tradeability_gate(entry, decision if isinstance(decision, dict) else None)
    if isinstance(decision, dict):
        reason_codes = (
            list(decision.get("reason_codes") or [])
            if isinstance(decision.get("reason_codes"), list)
            else []
        )
        reasons = (
            list(decision.get("reasons") or [])
            if isinstance(decision.get("reasons"), list)
            else []
        )
        details = decision.get("details") if isinstance(decision.get("details"), dict) else {}
        reason_detail = _format_auto_trade_decision_detail(decision)
        target_realization_risk_text = str(details.get("target_realization_ui_risk_explanation_text") or "").strip()
        target_realization_decision_details: Dict[str, Any] = {}
        for risk_key in (
            "target_realization_ui_risk_explanation_text",
            "target_realization_ui_risk_codes",
            "target_realization_trade_follow_allowed",
            "target_realization_trade_follow_reason",
            "target_realization_path_reliability_state",
            "target_realization_path_reliability_label",
            "target_realization_path_reliability_score",
            "target_realization_freshness_source_stale",
            "target_realization_observation_age_minutes",
        ):
            if risk_key in details:
                target_realization_decision_details[risk_key] = details.get(risk_key)
        market_tick_age_sec = to_float(details.get("market_tick_age_sec"))
        market_tick_stale_sec = to_float(details.get("market_tick_stale_sec"))
        follow_tick_stale_sec = to_float(details.get("follow_market_tick_stale_sec"))
        market_tick_refresh_note = str(details.get("market_tick_refresh_note") or "").strip()
        market_tick_block: Optional[Dict[str, Any]] = None
        if (
            (market_tick_age_sec is not None and math.isfinite(market_tick_age_sec))
            or (market_tick_stale_sec is not None and math.isfinite(market_tick_stale_sec))
        ):
            market_tick_block = {
                "age_sec": float(market_tick_age_sec) if market_tick_age_sec is not None and math.isfinite(market_tick_age_sec) else None,
                "stale_sec": float(market_tick_stale_sec) if market_tick_stale_sec is not None and math.isfinite(market_tick_stale_sec) else None,
                "follow_stale_sec": float(follow_tick_stale_sec) if follow_tick_stale_sec is not None and math.isfinite(follow_tick_stale_sec) else None,
                "refresh_note": market_tick_refresh_note,
            }
        entry["entry_decision"] = {
            "decided_state": str(decision.get("decided_state") or ""),
            "will_order": int(decision.get("will_order") or 0),
            "reason_codes": reason_codes,
            "reason_text": str(reasons[0] or "").strip() if reasons else "",
            "reason_detail": reason_detail,
            "created_at": str(decision.get("created_at") or ""),
            "market_tick": market_tick_block,
            "details": target_realization_decision_details,
        }
    else:
        entry["entry_decision"] = None

    def _resolve_entry_order() -> Optional[Dict[str, Any]]:
        if isinstance(entry_orders_by_key_strategy, dict):
            order_by_strategy = entry_orders_by_key_strategy.get(
                (order_key[0], order_key[1], order_key[2], order_key[3], strategy_key)
            )
            if isinstance(order_by_strategy, dict):
                return order_by_strategy
        order_fallback = entry_orders_by_key.get(order_key)
        if isinstance(order_fallback, dict):
            return order_fallback
        return None

    entry_order = _resolve_entry_order()
    entry["entry_order_historical"] = None
    entry["entry_order_current_na_reason"] = ""
    if isinstance(entry_order, dict) and entry_order.get("order_id"):
        entry_order_current = dict(entry_order)
        entry_order_historical: Optional[Dict[str, Any]] = None
        trade_for_match = entry.get("trade_info") if isinstance(entry.get("trade_info"), dict) else {}
        dec_for_match = entry.get("entry_decision") if isinstance(entry.get("entry_decision"), dict) else None
        dec_dt = parse_any_ts(str(dec_for_match.get("created_at") or "")) if isinstance(dec_for_match, dict) else None
        ord_dt = parse_any_ts(str(entry_order_current.get("created_at") or ""))
        state_text = str(trade_for_match.get("state") or "").strip().lower()
        pos_val_match = to_float(trade_for_match.get("position_size"))
        pos_val_match = float(pos_val_match) if pos_val_match is not None and math.isfinite(pos_val_match) else 0.0
        fills_match = to_float(trade_for_match.get("fills_count"))
        fills_match_i = int(fills_match or 0) if fills_match is not None and math.isfinite(fills_match) else 0
        # Avoid mixing a historical entry order with a much later blocked decision in the same trace card.
        if (
            dec_dt is not None
            and ord_dt is not None
            and dec_dt > (ord_dt + timedelta(seconds=30))
            and (state_text == "exit" and pos_val_match <= TIME_EDGE_Q_EPS)
        ):
            entry_order_historical = entry_order_current
            entry_order_current = None
            entry["entry_order_current_na_reason"] = "history_closed_before_latest_decision"
        entry["entry_order"] = entry_order_current
        if isinstance(entry_order_historical, dict):
            entry["entry_order_historical"] = entry_order_historical
    else:
        entry["entry_order"] = None

    entry_ok = bool(entry.get("entry_ok"))
    no_order_reasons: List[str] = []
    if entry_ok and not entry.get("entry_order"):
        decision = _resolve_decision()
        hist_order = entry.get("entry_order_historical")
        trade_hist = entry.get("trade_info") if isinstance(entry.get("trade_info"), dict) else {}
        trade_state_hist = str(trade_hist.get("state") or "").strip().lower()
        trade_pos_hist = to_float(trade_hist.get("position_size"))
        trade_pos_hist = float(trade_pos_hist) if trade_pos_hist is not None and math.isfinite(trade_pos_hist) else 0.0
        if isinstance(hist_order, dict) and trade_state_hist == "exit" and trade_pos_hist <= TIME_EDGE_Q_EPS:
            no_order_reasons.append("历史订单已完成并退出；当前轮次按最新决策未再入场")
        if isinstance(decision, dict):
            dec_reasons = decision.get("reasons") if isinstance(decision.get("reasons"), list) else []
            dec_details = decision.get("details") if isinstance(decision.get("details"), dict) else {}
            dec_state = str(decision.get("decided_state") or "").strip()
            dec_at = str(decision.get("created_at") or "").strip()
            target_realization_risk_text = str(
                dec_details.get("target_realization_ui_risk_explanation_text") or ""
            ).strip()
            if target_realization_risk_text:
                no_order_reasons.append(f"路径风险解释: {target_realization_risk_text}")
            if dec_reasons:
                head = f"执行阻断({dec_state or 'unknown'})"
                if dec_at:
                    head += f" @ {dec_at}"
                no_order_reasons.append(
                    head + ": " + " / ".join(str(x) for x in dec_reasons if str(x).strip())
                )
            loc_key = str(dec_details.get("location_key") or "").strip()
            loc_label = str(dec_details.get("location_label") or "").strip()
            blocker = dec_details.get("location_blocking_trade")
            if isinstance(blocker, dict):
                b_slug = str(blocker.get("slug") or "").strip()
                b_date = str(blocker.get("event_date") or "").strip()
                b_outcome = str(blocker.get("outcome") or "").strip()
                b_side = str(blocker.get("side") or "").strip()
                b_reason = str(blocker.get("reason") or "").strip()
                b_label = str(blocker.get("label") or "").strip()
                blocker_text = b_label or b_reason or "地点风控阻断"
                suffix = ""
                if b_slug or b_date or b_outcome or b_side:
                    suffix = f" · {b_slug or ''} {b_date or ''} {b_side} {b_outcome}".strip()
                if loc_key or loc_label:
                    suffix = (suffix + f" · {loc_label or loc_key}").strip()
                no_order_reasons.append(f"地点风控阻断: {blocker_text}{suffix}")
        else:
            strategy = str(entry.get("strategy") or "").strip().lower()
            strategy_enabled = True
            if strategy == "yes_top":
                strategy_enabled = _env_bool("PM_AUTO_TRADE_ENTRY_YES_TOP_ENABLED", False)
            elif strategy == "follow_copy":
                strategy_enabled = _env_bool("PM_AUTO_TRADE_ENTRY_FOLLOW_ENABLED", False)
            elif strategy == "hard_bound_no":
                strategy_enabled = _env_bool("PM_AUTO_TRADE_ENTRY_HARD_BOUND_NO_ENABLED", False)
            elif strategy == "adj_pair":
                strategy_enabled = _env_bool("PM_AUTO_TRADE_ENTRY_ADJ_PAIR_ENABLED", False)
            elif strategy in {"path_probability_follow", "lcb_global", "hard_source_direct"}:
                strategy_enabled = _env_bool("PM_LCB_GLOBAL_ENABLED", False)
            if strategy and strategy != "main" and not strategy_enabled:
                hint = (
                    f"决策未生成：{strategy} 候选仅用于追踪展示"
                    "（自动交易当前未对该策略写入决策）"
                )
            else:
                hint = "未发现 auto_trade_decisions 记录"
            try:
                event_key = (str(entry.get("slug") or ""), str(entry.get("event_date") or ""))
            except Exception:
                event_key = ("", "")
            avail = decisions_by_event.get(event_key) if event_key != ("", "") else None
            if isinstance(avail, list) and avail:
                shown = []
                latest_at = ""
                for item in avail:
                    side = str(item.get("side") or "").upper()
                    outcome = str(item.get("outcome") or "")
                    if not outcome or side not in {"YES", "NO"}:
                        continue
                    shown.append(f"{side} {outcome}")
                    ts = str(item.get("created_at") or "")
                    if ts and ts > latest_at:
                        latest_at = ts
                    if len(shown) >= 3:
                        break
                if shown:
                    if strategy and strategy != "main" and not strategy_enabled:
                        hint += " · 该事件已有决策: " + ", ".join(shown)
                    else:
                        hint = "决策缺失：未找到该 outcome/side"
                        hint += " · 已有: " + ", ".join(shown)
                    if latest_at:
                        hint += f" · 最近@{latest_at}"
            if auto_run_inflight and isinstance(run_state_public, dict):
                stage_hint = _format_auto_trade_stage_hint(run_state_public)
                if stage_hint:
                    hint += f" · {stage_hint}"
                no_order_reasons.append(hint)
            else:
                no_order_reasons.append(hint)
        if wait_sec is not None and wait_sec > 0:
            no_order_reasons.append(f"auto-trade 节流剩余{int(wait_sec)}s")
        def _append_once(text: str) -> None:
            if not text:
                return
            if text in no_order_reasons:
                return
            no_order_reasons.append(text)
        trade = entry.get("trade_info")
        if isinstance(trade, dict):
            last_action = str(trade.get("last_action") or "").strip()
            last_err = str(trade.get("last_error") or "").strip()
            last_status = str(trade.get("last_status") or "").strip()
            last_err_lower = last_err.lower()
            last_status_lower = last_status.lower()
            last_order_id = str(trade.get("last_order_id") or "").strip()
            stale_closed_no_orderbook = (
                trade_state_hist == "exit"
                and trade_pos_hist <= TIME_EDGE_Q_EPS
                and (
                    last_status_lower == "no_orderbook"
                    or (
                        "orderbook" in last_err_lower
                        and ("does not exist" in last_err_lower or "not exist" in last_err_lower)
                    )
                )
            )
            if last_action and last_action.startswith("entry") and (last_err or last_status):
                no_order_reasons.append(f"上次入场失败({last_action}): {last_err or last_status}")
            elif last_err and last_err_lower not in AUTO_TRADE_IGNORED_ERRORS and not stale_closed_no_orderbook:
                no_order_reasons.append(f"上次记录错误: {last_err}")
            if last_order_id and not entry_order:
                no_order_reasons.append("已记录 last_order_id 但 auto_orders 无 entry 记录")
        last_run_ts = ""
        if isinstance(last_run_row, dict):
            last_run_ts = str(last_run_row.get("ended_at") or "") or str(
                last_run_row.get("started_at") or ""
            )
        last_run_dt = parse_any_ts(last_run_ts) if last_run_ts else None
        if last_run_dt is None:
            _append_once("未发现 auto-trade-run 记录(可能服务刚重启/DB 忙导致未写入)")
        else:
            try:
                run_age_sec = max(0.0, (now_dt - last_run_dt).total_seconds())
            except Exception:
                run_age_sec = None
            if run_age_sec is not None and run_age_sec >= 10 * 60:
                _append_once(f"auto-trade-run 距今约{int(run_age_sec // 60)}分钟")
            else:
                _append_once("等待 watcher/entry_1m 触发下单")
        entry["no_order_reasons"] = no_order_reasons
    else:
        entry["no_order_reasons"] = []

    progress: Dict[str, Any] = {"tone": "idle", "label": "—", "detail": "", "stage": ""}
    if entry_ok:
        trade = entry.get("trade_info") if isinstance(entry.get("trade_info"), dict) else {}
        fills_count = to_float(trade.get("fills_count"))
        position_size = to_float(trade.get("position_size"))
        fills_count_i = int(fills_count or 0) if fills_count is not None and math.isfinite(fills_count) else 0
        pos_val = float(position_size) if position_size is not None and math.isfinite(position_size) else 0.0
        if entry.get("entry_order"):
            last_status = str(trade.get("last_status") or "").strip()
            stage = "ordered"
            label = "已下单"
            if fills_count_i > 0 or pos_val > TIME_EDGE_Q_EPS:
                stage = "filled"
                label = "已成交"
            detail = last_status or str(entry_order.get("order_status") or "").strip()
            progress = {"tone": "ok", "label": label, "detail": detail, "stage": stage}
        else:
            dec = entry.get("entry_decision") if isinstance(entry.get("entry_decision"), dict) else None
            if isinstance(dec, dict):
                dec_state = str(dec.get("decided_state") or "").strip()
                will_order = int(dec.get("will_order") or 0)
                codes = dec.get("reason_codes") if isinstance(dec.get("reason_codes"), list) else []
                reason_text = str(dec.get("reason_text") or "").strip()
                reason_detail = str(dec.get("reason_detail") or "").strip()
                top_code = str(codes[0] or "").strip() if codes else ""
                if will_order == 0 and dec_state and dec_state != "entry_ok":
                    progress = {
                        "tone": "bad",
                        "label": "阻断",
                        "detail": reason_text or top_code or dec_state,
                        "stage": "blocked",
                    }
                elif will_order == 1:
                    progress = {"tone": "warn", "label": "下单中", "detail": dec_state, "stage": "ordering"}
                else:
                    progress = {"tone": "warn", "label": "待触发", "detail": dec_state, "stage": "pending"}
            elif auto_run_inflight:
                stage = str(run_state_public.get("stage") or "").strip().lower()
                label = "处理中"
                stage_key = "inflight"
                if stage == "job_queued":
                    label = "排队中"
                    stage_key = "job_queued"
                elif stage == "job_retrying":
                    label = "重试中"
                    stage_key = "job_retrying"
                elif stage == "job_running":
                    label = "执行中"
                    stage_key = "job_running"
                progress = {
                    "tone": "warn",
                    "label": label,
                    "detail": _format_auto_trade_stage_hint(run_state_public) or str(run_state_public.get("stage") or ""),
                    "stage": stage_key,
                }
            elif wait_sec is not None and wait_sec > 0:
                progress = {"tone": "warn", "label": "节流", "detail": f"{int(wait_sec)}s", "stage": "throttled"}
            else:
                progress = {"tone": "warn", "label": "待触发", "detail": "", "stage": "pending"}
    entry["progress"] = progress
    entry["trace"] = _build_auto_trade_trace(
        entry,
        no_order_reasons,
        auto_run_inflight,
        wait_sec,
        last_run_row,
        run_state_public=run_state_public,
    )


def _filter_decision_rows_latest_run(
    rows: List[sqlite3.Row],
    run_date_key: str,
    last_run_row: Optional[Dict[str, Any]],
) -> List[sqlite3.Row]:
    if not rows or not run_date_key:
        return rows
    run_id = 0
    run_started = ""
    run_ended = ""
    if isinstance(last_run_row, dict) and str(last_run_row.get("run_date") or "").strip() == run_date_key:
        try:
            run_id = int(last_run_row.get("id") or 0)
        except Exception:
            run_id = 0
        run_started = str(last_run_row.get("started_at") or "").strip()
        run_ended = str(last_run_row.get("ended_at") or "").strip()
    if run_id <= 0 and not run_started:
        return rows

    by_run_id: List[sqlite3.Row] = []
    if run_id > 0:
        for row in rows:
            try:
                row_run_id = int(row["run_id"] or 0)
            except Exception:
                row_run_id = 0
            if row_run_id == run_id:
                by_run_id.append(row)
    if by_run_id:
        return by_run_id

    if not run_started:
        return []
    by_time_window: List[sqlite3.Row] = []
    for row in rows:
        created_at = str(row["created_at"] or "").strip()
        if not created_at:
            continue
        if created_at < run_started:
            continue
        if run_ended and created_at > run_ended:
            continue
        by_time_window.append(row)
    if by_time_window:
        # Keep newest-window rows first, then backfill missing candidate keys from
        # the broader run_date scope. This avoids null gate metrics on in-position
        # events when the current inflight run hasn't revisited that key yet.
        merged_rows: List[sqlite3.Row] = list(by_time_window)
        seen_keys: Set[Tuple[str, str, str, str, str]] = set()

        def _row_key(raw_row: sqlite3.Row) -> Tuple[str, str, str, str, str]:
            try:
                return (
                    str(raw_row["slug"] or ""),
                    str(raw_row["event_date"] or ""),
                    str(raw_row["outcome"] or ""),
                    str(raw_row["side"] or ""),
                    str(raw_row["action"] or ""),
                )
            except Exception:
                return ("", "", "", "", "")

        for row in by_time_window:
            key = _row_key(row)
            if key[0] and key[1] and key[2]:
                seen_keys.add(key)
        for row in rows:
            key = _row_key(row)
            if not (key[0] and key[1] and key[2]):
                continue
            if key in seen_keys:
                continue
            merged_rows.append(row)
            seen_keys.add(key)
        return merged_rows
    # When the latest run is inflight but hasn't written decisions yet, keep
    # the run_date scope fallback so trace cards (especially live positions)
    # still have the latest available gate metrics instead of all-null values.
    return rows


def auto_trade_digest(run_date: str, limit: int = 10) -> Dict[str, Any]:
    limit = max(1, min(int(limit or 10), 50))
    run_date_key = _normalize_date_key(run_date)
    if not run_date_key:
        with open_db() as conn:
            run_date_key = latest_fact_run_date(conn) or latest_unsettled_run_date(conn) or latest_run_date(conn) or ""
    if not run_date_key:
        return {"ok": False, "error": "no_run_date"}
    if not DB_PATH.exists():
        return {"ok": False, "error": "db_missing"}
    ctx = _load_auto_trade_run_context()
    diag = ctx.get("diag") or {}
    auto_enabled = bool(ctx.get("auto_enabled"))
    auto_dry_run = bool(ctx.get("auto_dry_run"))
    missing_env = ctx.get("missing_env") if isinstance(ctx.get("missing_env"), list) else []
    run_state = ctx.get("run_state") if isinstance(ctx.get("run_state"), dict) else {}
    run_state_public = ctx.get("run_state_public") if isinstance(ctx.get("run_state_public"), dict) else {}
    wait_sec = ctx.get("wait_sec") if isinstance(ctx.get("wait_sec"), int) or ctx.get("wait_sec") is None else None
    running_age_sec = ctx.get("running_age_sec")
    scan_state = ctx.get("scan_state") if isinstance(ctx.get("scan_state"), dict) else {}
    now_dt = ctx.get("now_dt") if isinstance(ctx.get("now_dt"), datetime) else datetime.now().astimezone()

    last_run_row: Optional[Dict[str, Any]] = None
    auto_decisions_rows: List[sqlite3.Row] = []
    auto_orders_rows: List[sqlite3.Row] = []
    try:
        with open_db_ro_fast(timeout_sec=0.2, busy_timeout_ms=200) as conn:
            rows = select_event_fact_rows(conn, run_date_key, include_history=False)
            cur = conn.cursor()
            try:
                cur.execute(
                """
                SELECT id, run_date, started_at, ended_at, ok, error, processed, skipped
                FROM auto_trade_runs
                WHERE run_date = ?
                ORDER BY started_at DESC, id DESC
                LIMIT 1
                """,
                (run_date_key,),
                )
                r = cur.fetchone()
                if not r:
                    cur.execute(
                    """
                    SELECT id, run_date, started_at, ended_at, ok, error, processed, skipped
                    FROM auto_trade_runs
                    ORDER BY started_at DESC, id DESC
                    LIMIT 1
                    """
                    )
                    r = cur.fetchone()
                if r:
                    last_run_row = {
                        "id": int(r["id"] or 0),
                        "run_date": str(r["run_date"] or ""),
                        "started_at": str(r["started_at"] or ""),
                        "ended_at": str(r["ended_at"] or ""),
                        "ok": None if r["ok"] is None else int(r["ok"]),
                        "error": str(r["error"] or ""),
                        "processed": int(r["processed"] or 0) if r["processed"] is not None else 0,
                        "skipped": int(r["skipped"] or 0) if r["skipped"] is not None else 0,
                    }
            except sqlite3.OperationalError:
                last_run_row = None
            try:
                cur.execute(
                """
                SELECT slug, event_date, outcome, side, action, order_id, order_status, order_type, created_at, price, size, strategy
                FROM auto_orders
                WHERE action = 'entry'
                  AND created_at >= ?
                ORDER BY created_at DESC, id DESC
                """
                ,
                (run_date_key,)
                )
                auto_orders_rows = cur.fetchall()
            except sqlite3.OperationalError:
                auto_orders_rows = []
            try:
                # Use run_date scope instead of a single run_id so UI can always show the latest
                # available execution decision per candidate, even while a new run is inflight.
                cur.execute(
                """
                SELECT run_id, run_date, slug, event_date, title, outcome, side, action,
                       decided_state, will_order, reason_codes_json, reasons_json, details_json, created_at
                FROM auto_trade_decisions
                WHERE run_date = ? AND action = 'entry'
                ORDER BY created_at DESC, id DESC
                LIMIT ?
                """,
                (run_date_key, int(AUTO_TRADE_TRACE_DECISION_ROW_LIMIT)),
                )
                auto_decisions_rows = cur.fetchall()
            except sqlite3.OperationalError:
                auto_decisions_rows = []
            auto_decisions_rows = _filter_decision_rows_latest_run(
                auto_decisions_rows,
                run_date_key,
                last_run_row,
            )
    except Exception as exc:
        return {"ok": False, "error": "db_unavailable", "detail": str(exc)}
    # "Currently running" must follow the in-memory state (the worker thread lives in-process).
    run_stage = str(run_state.get("stage") or "").strip().lower()
    auto_run_inflight = bool(run_state.get("running")) or run_stage in {"job_queued", "job_retrying"}
    auto_run_age_sec = running_age_sec if (auto_run_inflight and running_age_sec is not None) else None
    # If the last DB run row looks "inflight" but the process isn't running, treat it as orphaned
    # (e.g. UI restart during a run) and close it best-effort to avoid confusing SSOT.
    if isinstance(last_run_row, dict):
        started_at = str(last_run_row.get("started_at") or "").strip()
        ended_at_val = str(last_run_row.get("ended_at") or "").strip()
        ok_val = last_run_row.get("ok")
        if started_at and not ended_at_val and ok_val is None and not auto_run_inflight:
            last_run_row["orphaned"] = True
            try:
                ended_now = now_text()
                last_run_row["ended_at"] = ended_now
                last_run_row["ok"] = 0
                last_run_row["error"] = (str(last_run_row.get("error") or "").strip() + " orphaned_inflight").strip()
                with open_db(timeout_sec=0.2, busy_timeout_ms=200) as conn:
                    ensure_fact_tables(conn)
                    cur = conn.cursor()
                    cur.execute(
                        "UPDATE auto_trade_runs SET ended_at=?, ok=0, error=? WHERE id=?",
                        (ended_now, str(last_run_row.get("error") or ""), int(last_run_row.get("id") or 0)),
                    )
                    conn.commit()
            except Exception:
                pass
    entry_orders_by_key: Dict[Tuple[str, str, str, str], Dict[str, Any]] = {}
    entry_orders_by_key_strategy: Dict[Tuple[str, str, str, str, str], Dict[str, Any]] = {}
    for row in auto_orders_rows:
        try:
            slug = str(row["slug"] or "")
            event_date = str(row["event_date"] or "")
            outcome = str(row["outcome"] or "")
            side = str(row["side"] or "").upper()
        except Exception:
            continue
        if not slug or not event_date or not outcome or side not in {"YES", "NO"}:
            continue
        strategy = str(row["strategy"] or "").strip().lower() or "main"
        key = (slug, event_date, outcome, side)
        row_entry = {
            "order_id": str(row["order_id"] or ""),
            "order_status": str(row["order_status"] or ""),
            "order_type": str(row["order_type"] or ""),
            "created_at": str(row["created_at"] or ""),
            "price": to_float(row["price"]),
            "size": to_float(row["size"]),
            "strategy": str(row["strategy"] or ""),
        }
        if key not in entry_orders_by_key:
            entry_orders_by_key[key] = row_entry
        key_strategy = (slug, event_date, outcome, side, strategy)
        if key_strategy not in entry_orders_by_key_strategy:
            entry_orders_by_key_strategy[key_strategy] = dict(row_entry)

    decisions_by_key: Dict[Tuple[str, str, str, str], Dict[str, Any]] = {}
    decisions_by_key_strategy: Dict[Tuple[str, str, str, str, str], Dict[str, Any]] = {}
    decisions_by_event: Dict[Tuple[str, str], List[Dict[str, Any]]] = {}
    def _safe_json_loads_any(value: Any) -> Any:
        if value is None:
            return None
        text = str(value or "").strip()
        if not text:
            return None
        try:
            return json.loads(text)
        except Exception:
            return None
    for row in auto_decisions_rows:
        try:
            slug = str(row["slug"] or "")
            event_date = str(row["event_date"] or "")
            outcome = str(row["outcome"] or "")
            side = str(row["side"] or "").upper()
        except Exception:
            continue
        if not slug or not event_date or not outcome or side not in {"YES", "NO"}:
            continue
        key = (slug, event_date, outcome, side)
        reason_codes = _safe_json_loads_any(row["reason_codes_json"])
        reasons = _safe_json_loads_any(row["reasons_json"])
        details = _safe_json_loads_any(row["details_json"])
        details_dict = details if isinstance(details, dict) else {}
        strategy = str(details_dict.get("strategy") or "").strip().lower() or "main"
        decision_row = {
            "run_id": int(row["run_id"] or 0) if row["run_id"] is not None else None,
            "run_date": str(row["run_date"] or ""),
            "decided_state": str(row["decided_state"] or ""),
            "will_order": int(row["will_order"] or 0) if row["will_order"] is not None else 0,
            "reason_codes": reason_codes if isinstance(reason_codes, list) else [],
            "reasons": reasons if isinstance(reasons, list) else [],
            "details": details_dict,
            "strategy": strategy,
            "created_at": str(row["created_at"] or ""),
        }
        if key not in decisions_by_key:
            decisions_by_key[key] = decision_row
        key_strategy = (slug, event_date, outcome, side, strategy)
        if key_strategy not in decisions_by_key_strategy:
            decisions_by_key_strategy[key_strategy] = decision_row
        decisions_by_event.setdefault((slug, event_date), []).append(
            {
                "outcome": outcome,
                "side": side,
                "strategy": strategy,
                "created_at": str(row["created_at"] or ""),
                "decided_state": str(row["decided_state"] or ""),
            }
        )

    total = 0
    ok_count = 0
    blocked_count = 0
    missing_count = 0
    ok_list: List[Dict[str, Any]] = []
    blocked_list: List[Dict[str, Any]] = []
    reason_counts: Dict[str, int] = {}
    ok_with_order = 0
    ok_without_order = 0
    for row in rows:
        try:
            fact = safe_json_loads(row["fact_json"])
        except Exception:
            fact = {}
        if not isinstance(fact, dict) or not fact:
            continue
        market_var = str(fact.get("market_var") or "")
        if market_var and not market_var.startswith("temperature"):
            continue
        total += 1
        ssot = _get_or_build_auto_trade_ssot(fact)
        cand = (ssot or {}).get("main_candidate") if isinstance(ssot, dict) else None
        if not isinstance(cand, dict):
            missing_count += 1
            continue
        entry_ok = bool(cand.get("entry_ok"))
        reasons = cand.get("entry_reasons")
        reasons_list = reasons if isinstance(reasons, list) else []
        for r in reasons_list:
            text = str(r or "").strip()
            if not text:
                continue
            reason_counts[text] = int(reason_counts.get(text) or 0) + 1
        entry: Dict[str, Any] = {
            "slug": str(fact.get("slug") or ""),
            "event_date": str(fact.get("event_date") or ""),
            "title": str(fact.get("title") or ""),
            "run_date": str(fact.get("run_date") or run_date_key or ""),
            "market_closed": bool(fact.get("market_closed")),
            "side": str(cand.get("side") or ""),
            "outcome": str(cand.get("outcome") or ""),
            "entry_ok": entry_ok,
            "edge_score": cand.get("edge_score"),
            "exec_edge_score": cand.get("exec_edge_score"),
            "exec_edge_entry": cand.get("exec_edge_entry"),
            "exec_edge_exit": cand.get("exec_edge_exit"),
            "hold_edge_realizable": cand.get("hold_edge_realizable"),
            "hold_edge_realizable_score": cand.get("hold_edge_realizable_score"),
            "exit_edge_primary_source": cand.get("exit_edge_primary_source"),
            "edge_realizable": cand.get("edge_realizable"),
            "edge_realizable_score": cand.get("edge_realizable_score"),
            "exec_fee_bps": cand.get("exec_fee_bps"),
            "exec_fee_cost": cand.get("exec_fee_cost"),
            "edge_min": cand.get("edge_min"),
            "ask": cand.get("ask"),
            "q_min_bound": cand.get("q_min_bound"),
            "outcome_volume": cand.get("outcome_volume"),
            "reasons": reasons_list,
            "trade_info": cand.get("trade_info") if isinstance(cand.get("trade_info"), dict) else None,
        }
        _decorate_entry_execution(
            entry,
            decisions_by_key=decisions_by_key,
            decisions_by_key_strategy=decisions_by_key_strategy,
            decisions_by_event=decisions_by_event,
            entry_orders_by_key=entry_orders_by_key,
            entry_orders_by_key_strategy=entry_orders_by_key_strategy,
            auto_run_inflight=auto_run_inflight,
            wait_sec=wait_sec,
            last_run_row=last_run_row,
            run_state_public=run_state_public,
            now_dt=now_dt,
        )
        if entry_ok:
            ok_count += 1
            if entry.get("entry_order"):
                ok_with_order += 1
            else:
                ok_without_order += 1
            ok_list.append(entry)
        else:
            blocked_count += 1
            blocked_list.append(entry)

    def _rank(e: Dict[str, Any]) -> float:
        v = to_float(e.get("edge_score"))
        if v is not None and math.isfinite(v):
            return float(v)
        v = to_float(e.get("edge_min"))
        if v is not None and math.isfinite(v):
            return float(v)
        q = to_float(e.get("q_min_bound"))
        a = to_float(e.get("ask"))
        if q is not None and a is not None and math.isfinite(q) and math.isfinite(a):
            return float(q - a)
        return -999.0

    ok_list.sort(key=_rank, reverse=True)
    blocked_list.sort(key=_rank, reverse=True)

    reason_top = sorted(reason_counts.items(), key=lambda kv: (-kv[1], kv[0]))[:30]
    min_interval = AUTO_TRADE_MIN_RUN_INTERVAL_SEC
    ended_at = str(run_state.get("ended_at") or "").strip()
    return {
        "ok": True,
        "run_date": run_date_key,
        "total": total,
        "entry_ok": ok_count,
        "entry_ok_with_order": ok_with_order,
        "entry_ok_without_order": ok_without_order,
        "blocked": blocked_count,
        "missing": missing_count,
        "top_ok": ok_list[:limit],
        "top_blocked": blocked_list[:limit],
        "entry_ok_items": ok_list[:50],
        "reason_top": [{"reason": k, "count": v} for k, v in reason_top],
        "auto_trade_env": {
            "enabled": auto_enabled,
            "dry_run": auto_dry_run,
            "missing": missing_env,
        },
        "auto_trade_run_state": run_state_public,
        "last_auto_trade_run": last_run_row,
        "scan_state": scan_state,
        "throttle": {
            "min_interval_sec": int(min_interval),
            "last_ended_at": ended_at,
            "wait_sec": wait_sec,
        },
        "generated_at": now_text(),
    }


def _trace_payload_has_live_position_events(payload: Dict[str, Any]) -> bool:
    if not isinstance(payload, dict):
        return False
    for key_name in ("live_position_events", "live_redeemable_events"):
        live_events = payload.get(key_name)
        if not isinstance(live_events, list):
            continue
        for event in live_events:
            if not isinstance(event, dict):
                continue
            slug = str(event.get("slug") or "").strip()
            event_date = str(event.get("event_date") or "").strip()
            if slug and event_date:
                return True
    items = payload.get("items")
    if not isinstance(items, list):
        return False
    for item in items:
        if not isinstance(item, dict):
            continue
        trade = item.get("trade_info")
        if not isinstance(trade, dict):
            continue
        pos_val = to_float(trade.get("position_size"))
        if pos_val is not None and math.isfinite(pos_val) and pos_val > TIME_EDGE_Q_EPS:
            return True
    return False


def _trace_source_signature(
    conn: sqlite3.Connection,
    run_date_key: str,
    event_keys: Optional[List[Any]] = None,
) -> Dict[str, str]:
    sig: Dict[str, str] = {}
    if not run_date_key:
        return sig
    cur = conn.cursor()
    try:
        cur.execute(
            """
            SELECT MAX(fact_as_of) AS fact_as_of,
                   MAX(market_updated_at) AS market_updated_at,
                   MAX(model_updated_at) AS model_updated_at
            FROM event_fact_history
            WHERE run_date = ?
            """,
            (run_date_key,),
        )
        row = cur.fetchone()
        if row:
            sig["fact_as_of"] = str(row["fact_as_of"] or "")
            sig["market_updated_at"] = str(row["market_updated_at"] or "")
            sig["model_updated_at"] = str(row["model_updated_at"] or "")
    except sqlite3.Error:
        pass
    try:
        latest_run_id = 0
        cur.execute(
            """
            SELECT id
            FROM auto_trade_runs
            WHERE run_date = ?
            ORDER BY started_at DESC, id DESC
            LIMIT 1
            """,
            (run_date_key,),
        )
        run_row = cur.fetchone()
        if run_row:
            try:
                latest_run_id = int(run_row["id"] or 0)
            except Exception:
                latest_run_id = 0
        decision_ts = ""
        if latest_run_id > 0:
            cur.execute(
                "SELECT MAX(created_at) AS ts FROM auto_trade_decisions WHERE run_id = ? AND action = 'entry'",
                (latest_run_id,),
            )
            row = cur.fetchone()
            if row:
                decision_ts = str(row["ts"] or "").strip()
        if not decision_ts and latest_run_id <= 0:
            cur.execute(
                "SELECT MAX(created_at) AS ts FROM auto_trade_decisions WHERE run_date = ? AND action = 'entry'",
                (run_date_key,),
            )
            row = cur.fetchone()
            decision_ts = str(row["ts"] or "").strip() if row else ""
        sig["decisions_at"] = decision_ts
    except sqlite3.Error:
        pass
    try:
        cur.execute(
            """
            SELECT MAX(COALESCE(ended_at, started_at, created_at)) AS ts
            FROM auto_trade_runs
            WHERE run_date = ?
            """,
            (run_date_key,),
        )
        row = cur.fetchone()
        sig["runs_at"] = str(row["ts"] or "") if row else ""
    except sqlite3.Error:
        pass
    try:
        cur.execute(
            """
            SELECT MAX(updated_at) AS ts
            FROM auto_trade_jobs
            WHERE run_date = ?
            """,
            (run_date_key,),
        )
        row = cur.fetchone()
        sig["jobs_at"] = str(row["ts"] or "") if row else ""
    except sqlite3.Error:
        pass
    try:
        cur.execute("SELECT MAX(created_at) AS ts FROM auto_orders")
        row = cur.fetchone()
        sig["orders_at"] = str(row["ts"] or "") if row else ""
    except sqlite3.Error:
        pass
    try:
        cur.execute("SELECT MAX(updated_at) AS ts FROM edge_trades")
        row = cur.fetchone()
        sig["trades_at"] = str(row["ts"] or "") if row else ""
    except sqlite3.Error:
        pass
    pairs: List[Tuple[str, str]] = []
    if isinstance(event_keys, list) and event_keys:
        for item in event_keys:
            slug_val = ""
            date_val = ""
            if isinstance(item, (list, tuple)) and len(item) >= 2:
                slug_val = str(item[0] or "").strip()
                date_val = str(item[1] or "").strip()
            else:
                text = str(item or "")
                if "|" in text:
                    slug_val, date_val = text.split("|", 1)
                    slug_val = slug_val.strip()
                    date_val = date_val.strip()
            if not slug_val or not date_val:
                continue
            date_val = date_only(date_val)
            if not date_val:
                continue
            pairs.append((slug_val, date_val))
    if pairs:
        placeholders = ",".join(["(?, ?)"] * len(pairs))
        flat: List[str] = []
        for slug_val, date_val in pairs:
            flat.extend([slug_val, date_val])
        try:
            cur.execute(
                f"""
                SELECT MAX(created_at) AS ts
                FROM event_market_ticks
                WHERE (slug, event_date) IN ({placeholders})
                """,
                tuple(flat),
            )
            row = cur.fetchone()
            sig["ticks_at"] = str(row["ts"] or "") if row else ""
        except sqlite3.Error:
            pass
    return sig


def auto_trade_trace(run_date: str, limit: int = 20, readonly: bool = False) -> Dict[str, Any]:
    try:
        limit_val = int(limit or 0)
    except (TypeError, ValueError):
        limit_val = 20
    if limit_val <= 0:
        limit_val = int(AUTO_TRADE_TRACE_RESPONSE_MAX_ITEMS)
    else:
        limit_val = max(1, min(limit_val, int(AUTO_TRADE_TRACE_RESPONSE_MAX_ITEMS)))
    run_date_key = _normalize_date_key(run_date)
    if not run_date_key:
        try:
            with open_db_ro_fast(timeout_sec=0.25, busy_timeout_ms=200) as conn:
                run_date_key = latest_run_date_fast(conn) or ""
        except Exception:
            run_date_key = ""
        if not run_date_key:
            try:
                with open_db_ro_fast(timeout_sec=0.08, busy_timeout_ms=0) as conn:
                    run_date_key = (
                        latest_fact_run_date(conn)
                        or latest_unsettled_run_date(conn)
                        or latest_run_date(conn)
                        or ""
                    )
            except Exception:
                run_date_key = ""
    if not run_date_key:
        return {"ok": False, "error": "no_run_date"}
    if not DB_PATH.exists():
        return {"ok": False, "error": "db_missing"}

    def _trace_refresh_start(now_ts: float) -> bool:
        with _AUTO_TRADE_TRACE_REFRESH_LOCK:
            started_at = _AUTO_TRADE_TRACE_REFRESHING_AT.get(run_date_key)
            if run_date_key in _AUTO_TRADE_TRACE_REFRESHING and started_at is not None:
                if (now_ts - float(started_at)) <= float(AUTO_TRADE_TRACE_REFRESH_STALE_SEC):
                    return False
            _AUTO_TRADE_TRACE_REFRESHING.add(run_date_key)
            _AUTO_TRADE_TRACE_REFRESHING_AT[run_date_key] = now_ts
            return True

    def _trace_refresh_done() -> None:
        with _AUTO_TRADE_TRACE_REFRESH_LOCK:
            _AUTO_TRADE_TRACE_REFRESHING.discard(run_date_key)
            _AUTO_TRADE_TRACE_REFRESHING_AT.pop(run_date_key, None)

    def _trace_refresh_spawn(now_ts: float, seed_payload: Optional[Dict[str, Any]] = None) -> bool:
        if not _trace_refresh_start(now_ts):
            return False
        try:
            threading.Thread(target=_refresh_async, args=(seed_payload,), daemon=True).start()
            return True
        except Exception:
            _trace_refresh_done()
            return False

    def _compute_payload() -> Dict[str, Any]:
        # UI trace is a read-only projection. Stale execution state is repaired
        # by the execution worker, never by an HTTP read competing with the
        # observation-to-posterior writer lane.
        cfg = auto_trade_config_defaults()
        try:
            cfg.update(load_auto_trade_config())
        except Exception:
            pass

        def _cfg_flag(key: str, fallback: bool) -> bool:
            raw = cfg.get(key, fallback)
            if isinstance(raw, bool):
                return raw
            if isinstance(raw, (int, float)):
                try:
                    return bool(int(raw))
                except Exception:
                    return fallback
            if raw is None:
                return fallback
            return str(raw).strip().lower() in {"1", "true", "yes", "on"}

        def _cfg_float(key: str, fallback: float) -> float:
            raw = cfg.get(key, fallback)
            try:
                val = float(raw)
            except (TypeError, ValueError):
                return float(fallback)
            if not math.isfinite(val):
                return float(fallback)
            return float(val)

        lcb_global_enabled = _cfg_flag("lcb_global_enabled", _env_bool("PM_LCB_GLOBAL_ENABLED", False))
        lcb_global_edge_lcb_min = min(0.10, max(-0.05, _cfg_float("lcb_global_edge_lcb_min", 0.0)))
        lcb_global_block_d2_plus = _cfg_flag(
            "lcb_global_block_d2_plus",
            _env_bool("PM_LCB_GLOBAL_BLOCK_D2_PLUS", True),
        )
        lcb_global_max_spread = max(0.0, _cfg_float("lcb_global_max_spread", 0.08))
        entry_only_realizable = _cfg_flag("entry_only_realizable", False)
        entry_edge_realizable_min = _cfg_float("entry_edge_realizable_min", 0.0)
        entry_realizable_floor = max(0.0, float(entry_edge_realizable_min))
        if lcb_global_enabled:
            display_realizable_floor = float(lcb_global_edge_lcb_min)
        else:
            display_realizable_floor = max(entry_realizable_floor, 0.05)
        exit_edge_headroom_min = _cfg_float("exit_edge_headroom_min", 0.02)

        def _market_sanity_reason(
            ask_val: Optional[float],
            spread_val: Optional[float],
            bid_val: Optional[float] = None,
        ) -> List[str]:
            reasons: List[str] = []
            if ask_val is None or not math.isfinite(ask_val):
                reasons.append("盘口ask缺失")
            else:
                if (
                    ask_val <= float(AUTO_TRADE_TRACE_ONE_SIDED_ASK_MAX) + TIME_EDGE_Q_EPS
                    and (bid_val is None or not math.isfinite(bid_val))
                ):
                    reasons.append("单边薄簿/不可交易")
                    return reasons
                if ask_val < 0.02 - TIME_EDGE_Q_EPS:
                    reasons.append("盘口ask异常(<0.02)")
                elif ask_val > 0.99 + TIME_EDGE_Q_EPS:
                    reasons.append("盘口ask异常(>0.99)")
            if spread_val is None or not math.isfinite(spread_val):
                reasons.append("盘口spread缺失")
            elif spread_val < -TIME_EDGE_Q_EPS:
                reasons.append("盘口spread<0")
            return reasons

        def _realizable_reason(
            edge_val: Optional[float],
            ask_val: Optional[float],
            spread_val: Optional[float],
            bid_val: Optional[float] = None,
        ) -> List[str]:
            market_reasons = _market_sanity_reason(ask_val, spread_val, bid_val)
            if market_reasons:
                return market_reasons
            if edge_val is None or not math.isfinite(edge_val):
                return ["目标兑现诊断缺失"]
            if edge_val < display_realizable_floor - TIME_EDGE_Q_EPS:
                return [f"目标兑现诊断={edge_val:.4f}<{display_realizable_floor:.4f}"]
            return [f"目标兑现诊断<{display_realizable_floor:.4f}"]

        def _realizable_ok(
            edge_val: Optional[float],
            ask_val: Optional[float],
            spread_val: Optional[float],
            bid_val: Optional[float] = None,
        ) -> bool:
            if _market_sanity_reason(ask_val, spread_val, bid_val):
                return False
            if edge_val is None or not math.isfinite(edge_val):
                return False
            return edge_val >= display_realizable_floor + TIME_EDGE_Q_EPS

        main_enabled = _cfg_flag("entry_main_enabled", True)
        yes_top_enabled = _cfg_flag("entry_yes_top_enabled", False)
        follow_enabled = _cfg_flag("entry_follow_enabled", False)
        hard_bound_enabled = _cfg_flag("entry_hard_bound_no_enabled", False)
        adj_pair_enabled = _cfg_flag("entry_adj_pair_enabled", False)
        mirror_follow_enabled = _cfg_flag("mirror_follow_enabled", False)
        trace_enabled_strategies: List[str] = []
        if lcb_global_enabled:
            trace_enabled_strategies.append("path_probability_follow")
        else:
            if main_enabled:
                trace_enabled_strategies.append("main")
            if yes_top_enabled:
                trace_enabled_strategies.append("yes_top")
            if follow_enabled:
                trace_enabled_strategies.append("follow_copy")
            if hard_bound_enabled:
                trace_enabled_strategies.append("hard_bound_no")
            if adj_pair_enabled:
                trace_enabled_strategies.append("adj_pair")
        if mirror_follow_enabled:
            trace_enabled_strategies.append("mirror_follow")

        ctx = _load_auto_trade_run_context()
        run_state = ctx.get("run_state") if isinstance(ctx.get("run_state"), dict) else {}
        run_state_public = ctx.get("run_state_public") if isinstance(ctx.get("run_state_public"), dict) else {}
        wait_sec = ctx.get("wait_sec") if isinstance(ctx.get("wait_sec"), int) or ctx.get("wait_sec") is None else None
        now_dt = ctx.get("now_dt") if isinstance(ctx.get("now_dt"), datetime) else datetime.now().astimezone()

        last_run_row: Optional[Dict[str, Any]] = None
        trace_strategy_stats: Dict[str, Dict[str, Any]] = strategy_stats_defaults()
        auto_decisions_rows: List[sqlite3.Row] = []
        auto_orders_rows: List[sqlite3.Row] = []
        rows: List[sqlite3.Row] = []
        live_positions_by_event: Dict[Tuple[str, str], Dict[str, Any]] = {}
        live_positions_by_key: Dict[Tuple[str, str, str, str], Dict[str, Any]] = {}
        live_redeemable_by_event: Dict[Tuple[str, str], Dict[str, Any]] = {}
        live_redeemable_by_key: Dict[Tuple[str, str, str, str], Dict[str, Any]] = {}
        recent_closed_by_event: Dict[Tuple[str, str], Dict[str, Any]] = {}
        recent_closed_by_key: Dict[Tuple[str, str, str, str], Dict[str, Any]] = {}
        position_truth_source = "local_position_ledger"
        position_sync_error_local = ""
        use_positions_truth = False
        position_overrides: Dict[Tuple[str, str, str, str], Dict[str, Any]] = {}
        strict_mirror_follow = bool(STATS_STRICT_MIRROR_FOLLOW)
        auto_order_ids: Set[str] = set()
        inferred_auto_keys: Set[Tuple[str, str, str, str]] = set()
        mirror_follow_keys: Set[Tuple[str, str, str, str]] = set()

        def _parse_bool(value: Any) -> Optional[bool]:
            if isinstance(value, bool):
                return value
            if isinstance(value, (int, float)):
                try:
                    return bool(int(value))
                except Exception:
                    return None
            text = str(value or "").strip().lower()
            if not text:
                return None
            if text in {"1", "true", "yes", "on", "y"}:
                return True
            if text in {"0", "false", "no", "off", "n"}:
                return False
            return None

        def _looks_auto_managed_trade(last_status: str, last_action: str) -> bool:
            status = str(last_status or "").strip().lower()
            action = str(last_action or "").strip().lower()
            if status.startswith(("entry_", "exit_", "open_order_", "reconcile_")):
                return True
            if action in {
                "entry",
                "entry_skip",
                "entry_order",
                "entry_retry",
                "exit",
                "exit_skip",
                "exit_order",
                "exit_retry",
                "blocker_reconcile",
            }:
                return True
            return status in {"no_balance"}

        try:
            with open_db_ro_fast(timeout_sec=0.2, busy_timeout_ms=200) as conn:
                rows = select_event_fact_rows(conn, run_date_key, include_history=False)
                try:
                    trace_strategy_stats = compute_strategy_stats(conn, 1, run_date=run_date_key)
                except Exception:
                    trace_strategy_stats = strategy_stats_defaults()
                cur = conn.cursor()
                try:
                    cur.execute(
                        """
                        SELECT slug, event_date, outcome, side, position_size, state, avg_price, updated_at,
                               last_order_id, last_status, last_error, last_action,
                               mark_price, peak_price, realized_pnl, unrealized_pnl,
                               entry_at, last_fill_at, exit_skip_reason, exit_skip_detail, exit_skip_at, exit_triggered_at
                        FROM edge_trades
                        WHERE position_size > ?
                        """,
                        (TIME_EDGE_Q_EPS,),
                    )
                    for pos_row in cur.fetchall():
                        slug_key = str(pos_row["slug"] or "").strip()
                        event_date_key = str(pos_row["event_date"] or "").strip()
                        outcome_key = str(pos_row["outcome"] or "").strip()
                        side_key = str(pos_row["side"] or "").strip().upper()
                        pos_size = to_float(pos_row["position_size"])
                        if (
                            not slug_key
                            or not event_date_key
                            or not outcome_key
                            or side_key not in {"YES", "NO"}
                            or pos_size is None
                            or not math.isfinite(pos_size)
                            or pos_size <= TIME_EDGE_Q_EPS
                        ):
                            continue
                        event_key = (slug_key, event_date_key)
                        event_entry = live_positions_by_event.setdefault(
                            event_key,
                            {"total": 0.0, "count": 0, "summary_rows": [], "updated_at_max": ""},
                        )
                        event_entry["total"] = float(event_entry.get("total") or 0.0) + float(pos_size)
                        event_entry["count"] = int(event_entry.get("count") or 0) + 1
                        summary_rows = event_entry.get("summary_rows")
                        if isinstance(summary_rows, list) and len(summary_rows) < 3:
                            summary_rows.append(f"{outcome_key} {side_key} {float(pos_size):.3f}")
                        updated_at = str(pos_row["updated_at"] or "").strip()
                        if updated_at:
                            prev = str(event_entry.get("updated_at_max") or "")
                            if not prev or updated_at > prev:
                                event_entry["updated_at_max"] = updated_at
                        live_positions_by_key[(slug_key, event_date_key, outcome_key, side_key)] = {
                            "position_size": float(pos_size),
                            "state": str(pos_row["state"] or ""),
                            "avg_price": to_float(pos_row["avg_price"]),
                            "updated_at": str(pos_row["updated_at"] or ""),
                            "last_order_id": str(pos_row["last_order_id"] or ""),
                            "last_status": str(pos_row["last_status"] or ""),
                            "last_error": str(pos_row["last_error"] or ""),
                            "last_action": str(pos_row["last_action"] or ""),
                            "mark_price": to_float(pos_row["mark_price"]),
                            "peak_price": to_float(pos_row["peak_price"]),
                            "realized_pnl": to_float(pos_row["realized_pnl"]),
                            "unrealized_pnl": to_float(pos_row["unrealized_pnl"]),
                            "entry_at": str(pos_row["entry_at"] or ""),
                            "last_fill_at": str(pos_row["last_fill_at"] or ""),
                            "exit_skip_reason": str(pos_row["exit_skip_reason"] or ""),
                            "exit_skip_detail": str(pos_row["exit_skip_detail"] or ""),
                            "exit_skip_at": str(pos_row["exit_skip_at"] or ""),
                            "exit_triggered_at": str(pos_row["exit_triggered_at"] or ""),
                        }
                except sqlite3.OperationalError:
                    pass
                try:
                    cur.execute(
                        """
                        SELECT slug, event_date, outcome, side, position_size, avg_price,
                               state, last_action, last_action_price, last_action_at, updated_at
                        FROM edge_trades
                        WHERE avg_price > ?
                          AND updated_at >= ?
                        """,
                        (TIME_EDGE_Q_EPS, run_date_key),
                    )
                    for row in cur.fetchall():
                        slug_key = str(row["slug"] or "").strip()
                        event_date_key = str(row["event_date"] or "").strip()
                        outcome_key = str(row["outcome"] or "").strip()
                        side_key = str(row["side"] or "").strip().upper()
                        if not slug_key or not event_date_key or not outcome_key or side_key not in {"YES", "NO"}:
                            continue
                        pos_size = to_float(row["position_size"])
                        if pos_size is not None and math.isfinite(pos_size) and pos_size > TIME_EDGE_Q_EPS:
                            continue
                        state_text = str(row["state"] or "").strip().lower()
                        if state_text and state_text != "exit":
                            continue
                        updated_at = str(row["updated_at"] or row["last_action_at"] or "").strip()
                        if not updated_at or updated_at < run_date_key:
                            continue
                        avg_price = to_float(row["avg_price"])
                        if avg_price is None or not math.isfinite(avg_price) or avg_price <= TIME_EDGE_Q_EPS:
                            continue
                        payload = {
                            "updated_at": updated_at,
                            "avg_price": float(avg_price),
                            "last_action": str(row["last_action"] or ""),
                            "last_action_price": to_float(row["last_action_price"]),
                            "last_action_at": str(row["last_action_at"] or ""),
                        }
                        key = (slug_key, event_date_key, outcome_key, side_key)
                        prev_key = recent_closed_by_key.get(key)
                        if not prev_key or updated_at > str(prev_key.get("updated_at") or ""):
                            recent_closed_by_key[key] = payload
                        ev_key = (slug_key, event_date_key)
                        prev_ev = recent_closed_by_event.get(ev_key)
                        if not prev_ev or updated_at > str(prev_ev.get("updated_at") or ""):
                            recent_closed_by_event[ev_key] = payload
                except sqlite3.OperationalError:
                    pass
                try:
                    cur.execute(
                        """
                        SELECT id, run_date, started_at, ended_at, ok, error, processed, skipped
                        FROM auto_trade_runs
                        WHERE run_date = ?
                        ORDER BY started_at DESC, id DESC
                        LIMIT 1
                        """,
                        (run_date_key,),
                    )
                    r = cur.fetchone()
                    if not r:
                        cur.execute(
                            """
                            SELECT id, run_date, started_at, ended_at, ok, error, processed, skipped
                            FROM auto_trade_runs
                            ORDER BY started_at DESC, id DESC
                            LIMIT 1
                            """
                        )
                        r = cur.fetchone()
                    if r:
                        last_run_row = {
                            "id": int(r["id"] or 0),
                            "run_date": str(r["run_date"] or ""),
                            "started_at": str(r["started_at"] or ""),
                            "ended_at": str(r["ended_at"] or ""),
                            "ok": None if r["ok"] is None else int(r["ok"]),
                            "error": str(r["error"] or ""),
                            "processed": int(r["processed"] or 0) if r["processed"] is not None else 0,
                            "skipped": int(r["skipped"] or 0) if r["skipped"] is not None else 0,
                        }
                except sqlite3.OperationalError:
                    last_run_row = None
                try:
                    cur.execute(
                        """
                        SELECT slug, event_date, outcome, side, action, order_id, order_status, order_type, created_at, price, size, strategy
                        FROM auto_orders
                        WHERE action = 'entry'
                          AND created_at >= ?
                        ORDER BY created_at DESC, id DESC
                        """,
                        (run_date_key,),
                    )
                    auto_orders_rows = cur.fetchall()
                except sqlite3.OperationalError:
                    auto_orders_rows = []
                try:
                    cur.execute(
                        """
                        SELECT run_id, run_date, slug, event_date, title, outcome, side, action,
                               decided_state, will_order, reason_codes_json, reasons_json, details_json, created_at
                        FROM auto_trade_decisions
                        WHERE run_date = ? AND action = 'entry'
                        ORDER BY created_at DESC, id DESC
                        LIMIT ?
                        """,
                        (run_date_key, int(AUTO_TRADE_TRACE_DECISION_ROW_LIMIT)),
                    )
                    auto_decisions_rows = cur.fetchall()
                except sqlite3.OperationalError:
                    auto_decisions_rows = []
                auto_decisions_rows = _filter_decision_rows_latest_run(
                    auto_decisions_rows,
                    run_date_key,
                    last_run_row,
                )
                for row in auto_orders_rows:
                    try:
                        slug_key = str(row["slug"] or "").strip()
                        event_date_key = date_only(str(row["event_date"] or "").strip())
                        outcome_key = str(row["outcome"] or "").strip()
                        side_key = str(row["side"] or "").strip().upper()
                    except Exception:
                        continue
                    if slug_key and event_date_key and outcome_key and side_key in {"YES", "NO"}:
                        key = (slug_key, event_date_key, outcome_key, side_key)
                        inferred_auto_keys.add(key)
                        strategy_key = str(row["strategy"] or "").strip().lower()
                        if strategy_key == "mirror_follow":
                            mirror_follow_keys.add(key)
                    oid = str(row["order_id"] or "").strip()
                    if oid:
                        auto_order_ids.add(oid)
                if not strict_mirror_follow:
                    for key, payload in live_positions_by_key.items():
                        if not (isinstance(key, tuple) and len(key) == 4 and isinstance(payload, dict)):
                            continue
                        if _looks_auto_managed_trade(
                            str(payload.get("last_status") or ""),
                            str(payload.get("last_action") or ""),
                        ):
                            inferred_auto_keys.add(key)
                            oid = str(payload.get("last_order_id") or "").strip()
                            if oid:
                                auto_order_ids.add(oid)
                if ACCOUNT_REQUESTS_DISABLED:
                    position_truth_source = "data_only_local"
                    position_sync_error_local = "account_requests_disabled"
                elif not POSITIONS_SYNC_ENABLED:
                    position_truth_source = "local_position_ledger_sync_disabled"
                    position_sync_error_local = "positions_sync_disabled"
                elif not POSITIONS_API_URL:
                    position_truth_source = "local_position_ledger_missing_url"
                    position_sync_error_local = "missing_positions_url"
                else:
                    position_overrides, pos_err, _pos_updated = fetch_positions_cache(conn)
                    position_sync_error_local = str(pos_err or "")
                    if position_sync_error_local:
                        position_truth_source = "local_position_ledger_sync_error"
                    else:
                        position_truth_source = "positions_api_funder"
                        use_positions_truth = True
        except Exception as exc:
            return {"ok": False, "error": "db_unavailable", "detail": str(exc)}

        if use_positions_truth:
            def _upsert_live_event(
                event_map: Dict[Tuple[str, str], Dict[str, Any]],
                key_map: Dict[Tuple[str, str, str, str], Dict[str, Any]],
                key: Tuple[str, str, str, str],
                *,
                position_size: float,
                avg_price: Optional[float],
                updated_at: str,
                row_payload: Optional[Dict[str, Any]],
                redeemable: bool,
            ) -> None:
                slug_key, event_date_key, outcome_key, side_key = key
                event_key = (slug_key, event_date_key)
                event_entry = event_map.setdefault(
                    event_key,
                    {"total": 0.0, "count": 0, "summary_rows": [], "updated_at_max": ""},
                )
                event_entry["total"] = float(event_entry.get("total") or 0.0) + float(position_size)
                event_entry["count"] = int(event_entry.get("count") or 0) + 1
                summary_rows = event_entry.get("summary_rows")
                if isinstance(summary_rows, list) and len(summary_rows) < 3:
                    summary_rows.append(f"{outcome_key} {side_key} {float(position_size):.3f}")
                if updated_at:
                    prev = str(event_entry.get("updated_at_max") or "")
                    if not prev or updated_at > prev:
                        event_entry["updated_at_max"] = updated_at
                key_map[key] = {
                    "position_size": float(position_size),
                    "state": "redeemable" if redeemable else "entry",
                    "avg_price": avg_price,
                    "updated_at": updated_at,
                    "last_order_id": str((row_payload or {}).get("last_order_id") or ""),
                    "last_status": str((row_payload or {}).get("last_status") or ""),
                    "last_error": str((row_payload or {}).get("last_error") or ""),
                    "last_action": str((row_payload or {}).get("last_action") or ""),
                    "mark_price": to_float((row_payload or {}).get("mark_price")),
                    "peak_price": to_float((row_payload or {}).get("peak_price")),
                    "realized_pnl": to_float((row_payload or {}).get("realized_pnl")),
                    "unrealized_pnl": to_float((row_payload or {}).get("unrealized_pnl")),
                    "entry_at": str((row_payload or {}).get("entry_at") or ""),
                    "last_fill_at": str((row_payload or {}).get("last_fill_at") or ""),
                    "exit_skip_reason": str((row_payload or {}).get("exit_skip_reason") or ""),
                    "exit_skip_detail": str((row_payload or {}).get("exit_skip_detail") or ""),
                    "exit_skip_at": str((row_payload or {}).get("exit_skip_at") or ""),
                    "exit_triggered_at": str((row_payload or {}).get("exit_triggered_at") or ""),
                    "redeemable": redeemable,
                }

            local_rows_by_key: Dict[Tuple[str, str, str, str], Dict[str, Any]] = {}
            for key, payload in live_positions_by_key.items():
                if isinstance(payload, dict):
                    local_rows_by_key[key] = dict(payload)
            live_positions_by_event = {}
            live_positions_by_key = {}
            live_redeemable_by_event = {}
            live_redeemable_by_key = {}
            for raw_key, override in position_overrides.items():
                if not isinstance(raw_key, tuple) or len(raw_key) != 4:
                    continue
                slug_key = str(raw_key[0] or "").strip()
                event_date_key = date_only(str(raw_key[1] or "").strip())
                outcome_key = str(raw_key[2] or "").strip()
                side_key = str(raw_key[3] or "").strip().upper()
                if not slug_key or not event_date_key or not outcome_key or side_key not in {"YES", "NO"}:
                    continue
                pos_size = to_float(override.get("position_size"))
                if pos_size is None:
                    pos_size = to_float(override.get("size"))
                if pos_size is None or not math.isfinite(pos_size) or pos_size <= TIME_EDGE_Q_EPS:
                    continue
                key = (slug_key, event_date_key, outcome_key, side_key)
                is_auto = key in mirror_follow_keys if strict_mirror_follow else key in inferred_auto_keys
                row_payload = local_rows_by_key.get(key) or {}
                if not is_auto:
                    last_order_id = str((row_payload or {}).get("last_order_id") or "").strip()
                    if last_order_id and last_order_id in auto_order_ids:
                        is_auto = True
                if not is_auto:
                    continue
                avg_price = to_float(override.get("avg_price"))
                if avg_price is None:
                    avg_price = to_float(override.get("avgPrice"))
                if avg_price is None:
                    avg_price = to_float((row_payload or {}).get("avg_price"))
                updated_at = str(
                    override.get("updated_at")
                    or (row_payload or {}).get("updated_at")
                    or (row_payload or {}).get("last_action_at")
                    or ""
                ).strip()
                redeemable = bool(_parse_bool(override.get("redeemable")))
                if redeemable:
                    _upsert_live_event(
                        live_redeemable_by_event,
                        live_redeemable_by_key,
                        key,
                        position_size=float(pos_size),
                        avg_price=avg_price,
                        updated_at=updated_at,
                        row_payload=row_payload,
                        redeemable=True,
                    )
                else:
                    _upsert_live_event(
                        live_positions_by_event,
                        live_positions_by_key,
                        key,
                        position_size=float(pos_size),
                        avg_price=avg_price,
                        updated_at=updated_at,
                        row_payload=row_payload,
                        redeemable=False,
                    )

        if live_positions_by_key:
            existing_decision_keys: Set[Tuple[str, str, str, str]] = set()
            for row in auto_decisions_rows:
                try:
                    key = (
                        str(row["slug"] or "").strip(),
                        str(row["event_date"] or "").strip(),
                        str(row["outcome"] or "").strip(),
                        str(row["side"] or "").strip().upper(),
                    )
                except Exception:
                    continue
                if key[0] and key[1] and key[2] and key[3] in {"YES", "NO"}:
                    existing_decision_keys.add(key)
            missing_live_keys = [
                key
                for key in live_positions_by_key.keys()
                if key not in existing_decision_keys
            ]
            if missing_live_keys:
                try:
                    with open_db_ro_fast(timeout_sec=0.2, busy_timeout_ms=200) as conn_dec:
                        cur_dec = conn_dec.cursor()
                        for slug_key, event_date_key, outcome_key, side_key in missing_live_keys:
                            cur_dec.execute(
                                """
                                SELECT run_id, run_date, slug, event_date, title, outcome, side, action,
                                       decided_state, will_order, reason_codes_json, reasons_json, details_json, created_at
                                FROM auto_trade_decisions
                                WHERE action='entry'
                                  AND slug=?
                                  AND event_date=?
                                  AND outcome=?
                                  AND side=?
                                ORDER BY created_at DESC, id DESC
                                LIMIT 1
                                """,
                                (slug_key, event_date_key, outcome_key, side_key),
                            )
                            row = cur_dec.fetchone()
                            if row is not None:
                                auto_decisions_rows.append(row)
                except Exception:
                    pass

        entry_orders_by_key: Dict[Tuple[str, str, str, str], Dict[str, Any]] = {}
        entry_orders_by_key_strategy: Dict[Tuple[str, str, str, str, str], Dict[str, Any]] = {}
        for row in auto_orders_rows:
            try:
                slug = str(row["slug"] or "")
                event_date = str(row["event_date"] or "")
                outcome = str(row["outcome"] or "")
                side = str(row["side"] or "").upper()
            except Exception:
                continue
            if not slug or not event_date or not outcome or side not in {"YES", "NO"}:
                continue
            strategy = str(row["strategy"] or "").strip().lower() or "main"
            key = (slug, event_date, outcome, side)
            row_entry = {
                "order_id": str(row["order_id"] or ""),
                "order_status": str(row["order_status"] or ""),
                "order_type": str(row["order_type"] or ""),
                "created_at": str(row["created_at"] or ""),
                "price": to_float(row["price"]),
                "size": to_float(row["size"]),
                "strategy": str(row["strategy"] or ""),
            }
            if key not in entry_orders_by_key:
                entry_orders_by_key[key] = row_entry
            key_strategy = (slug, event_date, outcome, side, strategy)
            if key_strategy not in entry_orders_by_key_strategy:
                entry_orders_by_key_strategy[key_strategy] = dict(row_entry)

        decisions_by_key: Dict[Tuple[str, str, str, str], Dict[str, Any]] = {}
        decisions_by_key_strategy: Dict[Tuple[str, str, str, str, str], Dict[str, Any]] = {}
        decisions_by_event: Dict[Tuple[str, str], List[Dict[str, Any]]] = {}
        def _safe_json_loads_any(value: Any) -> Any:
            if value is None:
                return None
            text = str(value or "").strip()
            if not text:
                return None
            try:
                return json.loads(text)
            except Exception:
                return None
        for row in auto_decisions_rows:
            try:
                slug = str(row["slug"] or "")
                event_date = str(row["event_date"] or "")
                outcome = str(row["outcome"] or "")
                side = str(row["side"] or "").upper()
            except Exception:
                continue
            if not slug or not event_date or not outcome or side not in {"YES", "NO"}:
                continue
            key = (slug, event_date, outcome, side)
            reason_codes = _safe_json_loads_any(row["reason_codes_json"])
            reasons = _safe_json_loads_any(row["reasons_json"])
            details = _safe_json_loads_any(row["details_json"])
            details_dict = details if isinstance(details, dict) else {}
            strategy = str(details_dict.get("strategy") or "").strip().lower() or "main"
            decision_row = {
                "run_id": int(row["run_id"] or 0) if row["run_id"] is not None else None,
                "run_date": str(row["run_date"] or ""),
                "decided_state": str(row["decided_state"] or ""),
                "will_order": int(row["will_order"] or 0) if row["will_order"] is not None else 0,
                "reason_codes": reason_codes if isinstance(reason_codes, list) else [],
                "reasons": reasons if isinstance(reasons, list) else [],
                "details": details_dict,
                "strategy": strategy,
                "title": str(row["title"] or ""),
                "created_at": str(row["created_at"] or ""),
            }
            if key not in decisions_by_key:
                decisions_by_key[key] = decision_row
            key_strategy = (slug, event_date, outcome, side, strategy)
            if key_strategy not in decisions_by_key_strategy:
                decisions_by_key_strategy[key_strategy] = decision_row
            decisions_by_event.setdefault((slug, event_date), []).append(
                {
                    "outcome": outcome,
                    "side": side,
                    "strategy": strategy,
                    "created_at": str(row["created_at"] or ""),
                    "decided_state": str(row["decided_state"] or ""),
                }
            )

        run_stage = str(run_state.get("stage") or "").strip().lower()
        auto_run_inflight = bool(run_state.get("running")) or run_stage in {"job_queued", "job_retrying"}

        def _event_live_position_metrics(trade_info_map: Any) -> Dict[str, Any]:
            if not isinstance(trade_info_map, dict):
                return {
                    "event_live_position_size": 0.0,
                    "event_live_position_count": 0,
                    "event_live_position_summary": "",
                }
            total_size = 0.0
            count = 0
            summary_rows: List[str] = []
            for key, trade in trade_info_map.items():
                if not isinstance(trade, dict):
                    continue
                pos = to_float(trade.get("position_size"))
                if pos is None or not math.isfinite(pos) or pos <= TIME_EDGE_Q_EPS:
                    continue
                count += 1
                total_size += float(pos)
                if len(summary_rows) >= 3:
                    continue
                outcome = side = ""
                if isinstance(key, tuple) and len(key) >= 2:
                    outcome = str(key[0] or "")
                    side = str(key[1] or "").upper()
                if not outcome:
                    outcome = str(trade.get("outcome") or "")
                if not side:
                    side = str(trade.get("side") or "").upper()
                label = " ".join([x for x in [outcome, side] if x]).strip() or "持仓"
                summary_rows.append(f"{label} {float(pos):.3f}")
            summary = " · ".join(summary_rows)
            if count > len(summary_rows):
                summary = f"{summary} · +{count - len(summary_rows)} legs" if summary else f"{count} legs"
            return {
                "event_live_position_size": float(total_size),
                "event_live_position_count": int(count),
                "event_live_position_summary": summary,
            }

        def _apply_live_position_overlay(entry: Dict[str, Any]) -> None:
            if not isinstance(entry, dict):
                return
            slug_key = str(entry.get("slug") or "").strip()
            event_date_key = str(entry.get("event_date") or "").strip()
            outcome_key = str(entry.get("outcome") or "").strip()
            side_key = str(entry.get("side") or "").strip().upper()
            if not slug_key or not event_date_key:
                return
            ev = live_positions_by_event.get((slug_key, event_date_key))
            if isinstance(ev, dict):
                live_total = to_float(ev.get("total"))
                live_count = int(ev.get("count") or 0)
                summary_rows = ev.get("summary_rows") if isinstance(ev.get("summary_rows"), list) else []
                summary = " · ".join([str(x) for x in summary_rows if str(x or "").strip()])
                if live_count > len(summary_rows):
                    summary = f"{summary} · +{live_count - len(summary_rows)} legs" if summary else f"{live_count} legs"
                cur_total = to_float(entry.get("event_live_position_size"))
                cur_count = int(entry.get("event_live_position_count") or 0)
                if live_total is not None and math.isfinite(live_total):
                    if cur_total is None or not math.isfinite(cur_total) or live_total > cur_total:
                        entry["event_live_position_size"] = float(live_total)
                if live_count > cur_count:
                    entry["event_live_position_count"] = live_count
                if summary:
                    entry["event_live_position_summary"] = summary
            if outcome_key and side_key in {"YES", "NO"}:
                pos_key = live_positions_by_key.get((slug_key, event_date_key, outcome_key, side_key))
                if isinstance(pos_key, dict):
                    entry["live_position_size"] = to_float(pos_key.get("position_size"))
                    trade_info = entry.get("trade_info")
                    trade_info_dict = trade_info if isinstance(trade_info, dict) else {}
                    pos_new = to_float(pos_key.get("position_size"))
                    if pos_new is not None and math.isfinite(pos_new):
                        merged = dict(trade_info_dict)
                        merged["position_size"] = float(pos_new)
                        for key_name in (
                            "state",
                            "last_order_id",
                            "last_status",
                            "last_error",
                            "last_action",
                            "entry_at",
                            "last_fill_at",
                            "updated_at",
                            "exit_skip_reason",
                            "exit_skip_detail",
                            "exit_skip_at",
                            "exit_triggered_at",
                        ):
                            merged[key_name] = str(pos_key.get(key_name) or "")
                        for num_name in (
                            "avg_price",
                            "mark_price",
                            "peak_price",
                            "realized_pnl",
                            "unrealized_pnl",
                        ):
                            num_val = to_float(pos_key.get(num_name))
                            merged[num_name] = (
                                float(num_val)
                                if num_val is not None and math.isfinite(num_val)
                                else None
                            )
                        entry["trade_info"] = merged
                elif use_positions_truth:
                    redeemable_key = live_redeemable_by_key.get((slug_key, event_date_key, outcome_key, side_key))
                    trade_info = entry.get("trade_info")
                    trade_info_dict = trade_info if isinstance(trade_info, dict) else {}
                    merged = dict(trade_info_dict)
                    if isinstance(redeemable_key, dict):
                        redeemable_size = to_float(redeemable_key.get("position_size"))
                        entry["live_redeemable"] = True
                        entry["live_redeemable_size"] = (
                            float(redeemable_size)
                            if redeemable_size is not None and math.isfinite(redeemable_size)
                            else None
                        )
                        merged["position_size"] = 0.0
                        merged["redeemable_position_size"] = entry.get("live_redeemable_size")
                        merged["state"] = "redeemable"
                    else:
                        entry["live_redeemable"] = False
                        merged["position_size"] = 0.0
                        if str(merged.get("state") or "").strip().lower() == "entry":
                            merged["state"] = "exit"
                    entry["live_position_size"] = 0.0
                    if merged:
                        entry["trade_info"] = merged

        def _apply_recent_trade_overlay(entry: Dict[str, Any]) -> None:
            if not isinstance(entry, dict):
                return
            slug_key = str(entry.get("slug") or "").strip()
            event_date_key = str(entry.get("event_date") or "").strip()
            outcome_key = str(entry.get("outcome") or "").strip()
            side_key = str(entry.get("side") or "").strip().upper()
            if not slug_key or not event_date_key:
                return
            rec = None
            if outcome_key and side_key in {"YES", "NO"}:
                rec = recent_closed_by_key.get((slug_key, event_date_key, outcome_key, side_key))
            if rec is None:
                rec = recent_closed_by_event.get((slug_key, event_date_key))
            if not isinstance(rec, dict):
                return
            entry["recent_trade_at"] = str(rec.get("updated_at") or "")
            entry["recent_exit_price"] = to_float(rec.get("last_action_price"))
            entry["recent_trade_action"] = str(rec.get("last_action") or "")
            entry["recent_entry_price"] = to_float(rec.get("avg_price"))

        def _coalesce_numeric(current: Any, *vals: Any) -> Optional[float]:
            cur = to_float(current)
            if cur is not None and math.isfinite(cur):
                return float(cur)
            for raw in vals:
                val = to_float(raw)
                if val is not None and math.isfinite(val):
                    return float(val)
            return None

        def _hydrate_entry_from_decision(entry: Dict[str, Any]) -> None:
            if not isinstance(entry, dict):
                return
            slug_key = str(entry.get("slug") or "").strip()
            event_date_key = str(entry.get("event_date") or "").strip()
            outcome_key = str(entry.get("outcome") or "").strip()
            side_key = str(entry.get("side") or "").strip().upper()
            if not slug_key or not event_date_key or not outcome_key or side_key not in {"YES", "NO"}:
                return
            strategy_key = str(entry.get("strategy") or "").strip().lower() or "main"
            decision = decisions_by_key_strategy.get(
                (slug_key, event_date_key, outcome_key, side_key, strategy_key)
            )
            if not isinstance(decision, dict):
                decision = decisions_by_key.get((slug_key, event_date_key, outcome_key, side_key))
            details = decision.get("details") if isinstance(decision, dict) and isinstance(decision.get("details"), dict) else {}
            if not isinstance(details, dict):
                return
            metric_keys = (
                "edge_score",
                "exec_edge_score",
                "exec_edge_entry",
                "exec_edge_exit",
                "exec_exit_price",
                "hold_edge_realizable",
                "hold_edge_realizable_score",
                "hold_edge_realizable_trigger",
                "prev_hold_edge_realizable",
                "exit_hold_edge_realizable_min",
                "edge_realizable",
                "edge_realizable_score",
                "edge_realizable_v2",
                "edge_realizable_score_v2",
                "edge_realizable_p_realize",
                "edge_realizable_p_converge",
                "edge_realizable_p_realize_min",
                "edge_realizable_p_converge_min",
                "edge_realizable_p_fill_entry",
                "edge_realizable_p_fill_exit",
                "edge_realizable_hold_cost",
                "edge_realizable_target_exit_price",
                "edge_realizable_delta_exit",
                "edge_tradeability_profit_value",
                "edge_signal_alpha",
                "edge_signal_lcb",
                "edge_signal_sigma",
                "edge_signal_confidence",
                "edge_path_p_reach",
                "edge_path_p_reach_lcb",
                "edge_path_p_reach_ucb",
                "edge_tradeability_signal_lcb_min",
                "edge_tradeability_path_lcb_min",
                "edge_tradeability_profit_min",
                "edge_tradeability_edge_expected",
                "edge_tradeability_edge_ucb",
                "edge_tradeability_miss_cost",
                "edge_tradeability_slippage_buffer",
                "plain_lcb_peak_no_price",
                "plain_lcb_peak_no_min_price",
                "edge_tradeability_signal_soft_band_min",
                "edge_tradeability_signal_soft_band_max",
                "edge_tradeability_signal_soft_band_size_ratio",
                "edge_tradeability_signal_soft_band_size_before",
                "edge_realizable_soft_block_value",
                "edge_realizable_soft_block_min",
                "edge_realizable_hq_edge_lcb_min",
                "exec_fee_bps",
                "exec_fee_cost",
                "ask",
                "spread",
            )
            for k in metric_keys:
                v = _coalesce_numeric(entry.get(k), details.get(k))
                if v is not None:
                    entry[k] = v
            profit_val = _coalesce_numeric(
                entry.get("edge_tradeability_profit_value"),
                entry.get("edge_tradeability_edge_lcb"),
                details.get("edge_tradeability_profit_value"),
                details.get("edge_tradeability_edge_lcb"),
            )
            if profit_val is not None:
                entry["edge_tradeability_profit_value"] = profit_val
            profit_min = _coalesce_numeric(
                entry.get("edge_tradeability_profit_min"),
                entry.get("edge_tradeability_edge_lcb_min"),
                details.get("edge_tradeability_profit_min"),
                details.get("edge_tradeability_edge_lcb_min"),
            )
            if profit_min is not None:
                entry["edge_tradeability_profit_min"] = profit_min
            for key_name in (
                "edge_tradeability_mode",
                "edge_tradeability_reasons",
                "edge_realizable_soft_block_reason",
                "edge_realizable_soft_block_detail",
                "exit_edge_primary_source",
                "edge_path_bucket_key",
                "edge_path_bucket_key_used",
                "edge_path_source",
                "lcb_q_peak_outcome",
                "plain_lcb_peak_no_price_source",
                "edge_tradeability_signal_soft_band_mode",
            ):
                if str(entry.get(key_name) or "").strip():
                    continue
                value = details.get(key_name)
                if value is not None:
                    entry[key_name] = value
            for key_name in (
                "edge_path_sample_n",
                "edge_path_fallback_rank",
                "edge_tradeability_policy_enforce",
                "edge_tradeability_canary_sampled",
                "edge_tradeability_pass",
                "edge_tradeability_blocked",
                "edge_tradeability_shadow_block",
                "plain_lcb_peak_no_filtered",
                "edge_tradeability_signal_soft_band_eligible",
                "edge_tradeability_signal_soft_band_shadow",
                "edge_tradeability_signal_soft_band_override",
                "edge_tradeability_path_gate_enforced",
                "edge_realizable_soft_blocked",
            ):
                if entry.get(key_name) is None and key_name in details:
                    entry[key_name] = details.get(key_name)
            for key_name in (
                "edge_realizable_hq_bypass_p_realize_min",
                "edge_realizable_hq_bypass_p_converge_min",
                "edge_realizable_hq_bypassed_p_realize_min",
                "edge_realizable_hq_bypassed_p_converge_min",
            ):
                if key_name in details:
                    entry[key_name] = bool(details.get(key_name))
            q_min_bound = _coalesce_numeric(entry.get("q_min_bound"), details.get("q_entry"), details.get("q_min_bound"))
            if q_min_bound is not None:
                entry["q_min_bound"] = q_min_bound
            _refresh_entry_tradeability_gate(entry, decision)

        def _entry_should_hide_negative(entry: Dict[str, Any]) -> bool:
            if not isinstance(entry, dict):
                return False
            trade_info = entry.get("trade_info") if isinstance(entry.get("trade_info"), dict) else {}
            pos_val = to_float(trade_info.get("position_size"))
            event_pos_val = to_float(entry.get("event_live_position_size"))
            if bool(entry.get("holding_event")):
                return False
            if pos_val is not None and math.isfinite(pos_val) and pos_val > TIME_EDGE_Q_EPS:
                return False
            if event_pos_val is not None and math.isfinite(event_pos_val) and event_pos_val > TIME_EDGE_Q_EPS:
                return False
            for k in ("edge_realizable", "edge_realizable_v2", "edge_realizable_p_realize"):
                val = to_float(entry.get(k))
                if val is not None and math.isfinite(val) and val < -TIME_EDGE_Q_EPS:
                    return True
            return False

        def _entry_has_trace_core(entry: Dict[str, Any]) -> bool:
            if not isinstance(entry, dict):
                return False
            ask_val = to_float(entry.get("ask"))
            edge_v1 = to_float(entry.get("edge_realizable"))
            edge_v2 = to_float(entry.get("edge_realizable_v2"))
            has_ask = ask_val is not None and math.isfinite(ask_val)
            has_edge = (
                (edge_v1 is not None and math.isfinite(edge_v1))
                or (edge_v2 is not None and math.isfinite(edge_v2))
            )
            return bool(has_ask and has_edge)

        def _entry_has_required_metrics(entry: Dict[str, Any]) -> bool:
            if not _entry_has_trace_core(entry):
                return False
            spread_val = to_float(entry.get("spread"))
            if spread_val is None or not math.isfinite(spread_val):
                return False
            p_realize_val = to_float(entry.get("edge_realizable_p_realize"))
            if p_realize_val is None or not math.isfinite(p_realize_val):
                return False
            target_exit = _coalesce_numeric(
                entry.get("edge_realizable_target_exit_price"),
                entry.get("exec_exit_price"),
            )
            if target_exit is None:
                return False
            return True

