        items: List[Dict[str, Any]] = []
        not_ok_items: List[Dict[str, Any]] = []
        item_keys: set[Tuple[str, str, str, str, str]] = set()
        not_ok_keys: set[Tuple[str, str, str, str, str]] = set()
        event_fact_ctx: Dict[Tuple[str, str], Dict[str, Any]] = {}
        total_facts = 0
        skipped_non_temp = 0
        missing_ssot = 0
        missing_main_candidate = 0
        missing_yes_top_candidate = 0
        entry_ok_main_count = 0
        entry_ok_yes_top_count = 0
        not_ok_main_count = 0
        not_ok_yes_top_count = 0
        not_ok_follow_count = 0
        not_ok_hard_bound_count = 0
        not_ok_adj_pair_count = 0
        not_ok_mirror_follow_count = 0
        entry_ok_follow_count = 0
        entry_ok_hard_bound_count = 0
        entry_ok_adj_pair_count = 0
        entry_ok_mirror_follow_count = 0

        def _push_not_ok(entry_dict: Optional[Dict[str, Any]]) -> bool:
            if not isinstance(entry_dict, dict):
                return False
            slug_key = str(entry_dict.get("slug") or "")
            date_key = str(entry_dict.get("event_date") or "")
            outcome_key = str(entry_dict.get("outcome") or "")
            side_key = str(entry_dict.get("side") or "").upper()
            strategy_key = str(entry_dict.get("strategy") or "")
            if not slug_key or not date_key:
                return False
            key = (slug_key, date_key, outcome_key, side_key, strategy_key)
            if key in not_ok_keys:
                return False
            not_ok_keys.add(key)
            not_ok_items.append(entry_dict)
            return True
        for row in rows:
            try:
                fact = safe_json_loads(row["fact_json"])
            except Exception:
                continue
            if not isinstance(fact, dict) or not fact:
                continue
            total_facts += 1
            market_var = str(fact.get("market_var") or "")
            if market_var and not market_var.startswith("temperature"):
                skipped_non_temp += 1
                continue
            slug = str(fact.get("slug") or "")
            event_date = str(fact.get("event_date") or "")
            event_date_key = event_date.split("T", 1)[0] if "T" in event_date else event_date
            if fact.get("market_closed"):
                ev_key = (slug, event_date_key)
                if ev_key not in live_positions_by_event and ev_key not in recent_closed_by_event:
                    continue
            if slug and event_date and (slug, event_date) not in event_fact_ctx:
                dist_rows = (
                    fact.get("distribution")
                    if isinstance(fact.get("distribution"), list)
                    else (fact.get("rows") if isinstance(fact.get("rows"), list) else [])
                )
                row_by_outcome: Dict[str, Dict[str, Any]] = {}
                for drow in dist_rows:
                    if not isinstance(drow, dict):
                        continue
                    outcome_label = str(drow.get("outcome") or "")
                    if not outcome_label or outcome_label in row_by_outcome:
                        continue
                    row_by_outcome[outcome_label] = drow
                needs_tick_patch = False
                for drow in row_by_outcome.values():
                    ask_yes = to_float(drow.get("best_ask"))
                    ask_no = to_float(drow.get("best_ask_no"))
                    spread_yes = to_float(drow.get("spread"))
                    spread_no = to_float(drow.get("spread_no"))
                    if ask_yes is not None and math.isfinite(ask_yes) and spread_yes is None:
                        needs_tick_patch = True
                        break
                    if ask_no is not None and math.isfinite(ask_no) and spread_no is None:
                        needs_tick_patch = True
                        break
                    if ask_yes is None or ask_no is None:
                        needs_tick_patch = True
                        break
                if needs_tick_patch:
                    try:
                        tick_map = _latest_ticks_for_event(conn, slug, event_date)
                    except Exception:
                        tick_map = {}
                    if tick_map:
                        for outcome_label, drow in row_by_outcome.items():
                            if not isinstance(drow, dict):
                                continue
                            tick_yes = tick_map.get((outcome_label, "YES"))
                            if tick_yes:
                                if drow.get("best_bid") is None and tick_yes["best_bid"] is not None:
                                    drow["best_bid"] = tick_yes["best_bid"]
                                if drow.get("best_ask") is None and tick_yes["best_ask"] is not None:
                                    drow["best_ask"] = tick_yes["best_ask"]
                                if drow.get("spread") is None:
                                    if tick_yes["spread"] is not None:
                                        drow["spread"] = tick_yes["spread"]
                                    elif drow.get("best_bid") is not None and drow.get("best_ask") is not None:
                                        drow["spread"] = max(float(drow["best_ask"]) - float(drow["best_bid"]), 0.0)
                                if drow.get("bid_depth_topN") is None and tick_yes["bid_depth_topN"] is not None:
                                    drow["bid_depth_topN"] = tick_yes["bid_depth_topN"]
                                if drow.get("ask_depth_topN") is None and tick_yes["ask_depth_topN"] is not None:
                                    drow["ask_depth_topN"] = tick_yes["ask_depth_topN"]
                            tick_no = tick_map.get((outcome_label, "NO"))
                            if tick_no:
                                if drow.get("best_bid_no") is None and tick_no["best_bid"] is not None:
                                    drow["best_bid_no"] = tick_no["best_bid"]
                                if drow.get("best_ask_no") is None and tick_no["best_ask"] is not None:
                                    drow["best_ask_no"] = tick_no["best_ask"]
                                if drow.get("spread_no") is None:
                                    if tick_no["spread"] is not None:
                                        drow["spread_no"] = tick_no["spread"]
                                    elif drow.get("best_bid_no") is not None and drow.get("best_ask_no") is not None:
                                        drow["spread_no"] = max(float(drow["best_ask_no"]) - float(drow["best_bid_no"]), 0.0)
                                if drow.get("bid_depth_topN_no") is None and tick_no["bid_depth_topN"] is not None:
                                    drow["bid_depth_topN_no"] = tick_no["bid_depth_topN"]
                                if drow.get("ask_depth_topN_no") is None and tick_no["ask_depth_topN"] is not None:
                                    drow["ask_depth_topN_no"] = tick_no["ask_depth_topN"]
                event_fact_ctx[(slug, event_date)] = {
                    "fact": fact,
                    "row_by_outcome": row_by_outcome,
                    "trade_info_map": _ssot_trade_info_map(fact.get("auto_trades")),
                    "market_top_label": str(fact.get("market_top_label") or ""),
                }
            ssot = _get_or_build_auto_trade_ssot(fact)
            if not isinstance(ssot, dict):
                missing_ssot += 1
                continue
            main_cand = ssot.get("main_candidate") if isinstance(ssot, dict) else None
            yes_top_cand = ssot.get("model_yes_top_candidate") if isinstance(ssot, dict) else None
            if main_enabled and not isinstance(main_cand, dict):
                missing_main_candidate += 1
            if yes_top_enabled and not isinstance(yes_top_cand, dict):
                missing_yes_top_candidate += 1
            if main_enabled:
                main_edge_val = to_float(main_cand.get("edge_realizable")) if isinstance(main_cand, dict) else None
                main_ask_val = to_float(main_cand.get("ask")) if isinstance(main_cand, dict) else None
                main_spread_val = to_float(main_cand.get("spread")) if isinstance(main_cand, dict) else None
                main_entry_ok = _realizable_ok(main_edge_val, main_ask_val, main_spread_val)
                main_entry = _make_entry(
                    fact,
                    main_cand,
                    "main",
                    allow_not_ok=True,
                    entry_ok_override=main_entry_ok,
                )
                if main_entry:
                    edge_val = to_float(main_entry.get("edge_realizable"))
                    ask_val = to_float(main_entry.get("ask"))
                    spread_val = to_float(main_entry.get("spread"))
                    if _realizable_ok(edge_val, ask_val, spread_val):
                        items.append(main_entry)
                        item_keys.add(
                            (
                                str(main_entry.get("slug") or ""),
                                str(main_entry.get("event_date") or ""),
                                str(main_entry.get("outcome") or ""),
                                str(main_entry.get("side") or "").upper(),
                                "main",
                            )
                        )
                        entry_ok_main_count += 1
                    else:
                        not_ok = _make_not_ok_entry(fact, main_entry, "main")
                        if _push_not_ok(not_ok):
                            not_ok_main_count += 1
                else:
                    not_ok = _make_not_ok_entry(
                        fact,
                        main_cand,
                        "main",
                        na_reason="不适用：缺少主策略候选" if not isinstance(main_cand, dict) else "",
                    )
                    if _push_not_ok(not_ok):
                        not_ok_main_count += 1
            if yes_top_enabled:
                yes_edge_val = to_float(yes_top_cand.get("edge_realizable")) if isinstance(yes_top_cand, dict) else None
                yes_ask_val = to_float(yes_top_cand.get("ask")) if isinstance(yes_top_cand, dict) else None
                yes_spread_val = to_float(yes_top_cand.get("spread")) if isinstance(yes_top_cand, dict) else None
                yes_entry_ok = _realizable_ok(yes_edge_val, yes_ask_val, yes_spread_val)
                yes_entry = _make_entry(
                    fact,
                    yes_top_cand,
                    "yes_top",
                    allow_not_ok=True,
                    entry_ok_override=yes_entry_ok,
                )
                if yes_entry:
                    edge_val = to_float(yes_entry.get("edge_realizable"))
                    ask_val = to_float(yes_entry.get("ask"))
                    spread_val = to_float(yes_entry.get("spread"))
                    if _realizable_ok(edge_val, ask_val, spread_val):
                        items.append(yes_entry)
                        item_keys.add(
                            (
                                str(yes_entry.get("slug") or ""),
                                str(yes_entry.get("event_date") or ""),
                                str(yes_entry.get("outcome") or ""),
                                str(yes_entry.get("side") or "").upper(),
                                "yes_top",
                            )
                        )
                        entry_ok_yes_top_count += 1
                    else:
                        not_ok = _make_not_ok_entry(fact, yes_entry, "yes_top")
                        if _push_not_ok(not_ok):
                            not_ok_yes_top_count += 1
                else:
                    na_reason = str(ssot.get("model_yes_top_na_reason") or "").strip()
                    label_fallback = str(ssot.get("model_yes_top_label") or "").strip()
                    not_ok = _make_not_ok_entry(
                        fact,
                        yes_top_cand,
                        "yes_top",
                        na_reason=na_reason,
                        outcome_fallback=label_fallback,
                        side_fallback="YES",
                    )
                    if _push_not_ok(not_ok):
                        not_ok_yes_top_count += 1

        def _coalesce_metric(*vals: Any) -> Optional[float]:
            for raw in vals:
                val = to_float(raw)
                if val is not None and math.isfinite(val):
                    return float(val)
            return None

        for key_strategy, decision in decisions_by_key_strategy.items():
            slug, event_date, outcome, side, strategy = key_strategy
            strategy = str(strategy or "").strip().lower()
            if strategy in {"", "exit"}:
                continue
            if lcb_global_enabled:
                allowed_strategies = {
                    "path_probability_follow",
                    "lcb_global",
                    "hard_source_direct",
                    "main",
                    "yes_top",
                    "follow_copy",
                    "hard_bound_no",
                    "adj_pair",
                    "mirror_follow",
                }
            else:
                allowed_strategies = {
                    "main",
                    "yes_top",
                    "follow_copy",
                    "hard_bound_no",
                    "adj_pair",
                    "mirror_follow",
                }
            if strategy not in allowed_strategies:
                continue
            strategy_view = _normalize_strategy_key(
                strategy,
                fallback="path_probability_follow" if lcb_global_enabled else "main",
            )
            entry_key = (slug, event_date, outcome, side, strategy_view)
            if entry_key in item_keys:
                continue
            event_ctx = event_fact_ctx.get((slug, event_date))
            fact_ctx = event_ctx if isinstance(event_ctx, dict) else {}
            fact = fact_ctx.get("fact") if isinstance(fact_ctx.get("fact"), dict) else {}
            row_by_outcome = (
                fact_ctx.get("row_by_outcome")
                if isinstance(fact_ctx.get("row_by_outcome"), dict)
                else {}
            )
            row_ref = row_by_outcome.get(outcome) if isinstance(row_by_outcome, dict) else None
            trade_info_map = (
                fact_ctx.get("trade_info_map")
                if isinstance(fact_ctx.get("trade_info_map"), dict)
                else {}
            )
            market_top_label = str(fact_ctx.get("market_top_label") or "")
            cand: Dict[str, Any] = {}
            if isinstance(row_ref, dict):
                strategy_context = _ssot_target_context_from_payload(fact)
                cand_from_row = _ssot_candidate_from_row(
                    row_ref,
                    side,
                    market_top_label,
                    trade_info_map,
                    strategy_context=strategy_context,
                )
                if isinstance(cand_from_row, dict):
                    cand = dict(cand_from_row)
            details = decision.get("details") if isinstance(decision.get("details"), dict) else {}
            cand["side"] = side
            cand["outcome"] = outcome
            cand["strategy"] = strategy_view
            ask_val = _coalesce_metric(details.get("ask"), cand.get("ask"))
            if ask_val is not None:
                cand["ask"] = ask_val
            spread_val = _coalesce_metric(details.get("spread"), cand.get("spread"))
            if spread_val is not None:
                cand["spread"] = spread_val
            edge_score_val = _coalesce_metric(details.get("edge_score"), cand.get("edge_score"))
            exec_edge_score_val = _coalesce_metric(details.get("exec_edge_score"), cand.get("exec_edge_score"))
            exec_edge_entry_val = _coalesce_metric(details.get("exec_edge_entry"), cand.get("exec_edge_entry"))
            exec_edge_exit_val = _coalesce_metric(details.get("exec_edge_exit"), cand.get("exec_edge_exit"))
            exec_exit_price_val = _coalesce_metric(details.get("exec_exit_price"), cand.get("exec_exit_price"))
            hold_edge_realizable_val = _coalesce_metric(
                details.get("hold_edge_realizable"),
                cand.get("hold_edge_realizable"),
            )
            hold_edge_realizable_score_val = _coalesce_metric(
                details.get("hold_edge_realizable_score"),
                cand.get("hold_edge_realizable_score"),
            )
            edge_realizable_val = _coalesce_metric(details.get("edge_realizable"), cand.get("edge_realizable"))
            edge_realizable_score_val = _coalesce_metric(
                details.get("edge_realizable_score"),
                cand.get("edge_realizable_score"),
            )
            exec_fee_bps_val = _coalesce_metric(details.get("exec_fee_bps"), cand.get("exec_fee_bps"))
            exec_fee_cost_val = _coalesce_metric(details.get("exec_fee_cost"), cand.get("exec_fee_cost"))
            q_entry_val = _coalesce_metric(details.get("q_entry"), cand.get("q_min_bound"))
            if q_entry_val is not None:
                cand["q_min_bound"] = q_entry_val
            entry = {
                "slug": slug,
                "event_date": event_date,
                "title": str(fact.get("title") or decision.get("title") or ""),
                "event_url": str(fact.get("event_url") or ""),
                "run_date": str(fact.get("run_date") or run_date_key or ""),
                "strategy": strategy_view,
                "side": side,
                "outcome": outcome,
                "entry_ok": True,
                "edge_score": edge_score_val,
                "exec_edge_score": exec_edge_score_val,
                "exec_edge_entry": exec_edge_entry_val,
                "exec_edge_exit": exec_edge_exit_val,
                "exec_exit_price": exec_exit_price_val,
                "hold_edge_realizable": hold_edge_realizable_val,
                "hold_edge_realizable_score": hold_edge_realizable_score_val,
                "exit_edge_primary_source": str(
                    details.get("exit_edge_primary_source")
                    or cand.get("exit_edge_primary_source")
                    or ""
                ),
                "edge_realizable": edge_realizable_val,
                "edge_realizable_score": edge_realizable_score_val,
                "edge_realizable_v2": cand.get("edge_realizable_v2"),
                "edge_realizable_score_v2": cand.get("edge_realizable_score_v2"),
                "edge_realizable_p_realize": cand.get("edge_realizable_p_realize"),
                "edge_realizable_p_converge": cand.get("edge_realizable_p_converge"),
                "edge_realizable_p_fill_entry": cand.get("edge_realizable_p_fill_entry"),
                "edge_realizable_p_fill_exit": cand.get("edge_realizable_p_fill_exit"),
                "edge_realizable_hold_cost": cand.get("edge_realizable_hold_cost"),
                "edge_realizable_target_exit_price": cand.get("edge_realizable_target_exit_price"),
                "edge_realizable_delta_exit": cand.get("edge_realizable_delta_exit"),
                "edge_realizable_soft_blocked": cand.get("edge_realizable_soft_blocked"),
                "edge_realizable_soft_block_reason": cand.get("edge_realizable_soft_block_reason"),
                "edge_realizable_soft_block_detail": cand.get("edge_realizable_soft_block_detail"),
                "edge_realizable_soft_block_value": cand.get("edge_realizable_soft_block_value"),
                "edge_realizable_soft_block_min": cand.get("edge_realizable_soft_block_min"),
                "exec_fee_bps": exec_fee_bps_val,
                "exec_fee_cost": exec_fee_cost_val,
                "ask": cand.get("ask"),
                "spread": cand.get("spread"),
                "q_min_bound": cand.get("q_min_bound"),
                "trade_info": cand.get("trade_info") if isinstance(cand.get("trade_info"), dict) else None,
            }
            entry.update(_event_live_position_metrics(trade_info_map))
            _apply_live_position_overlay(entry)
            _apply_recent_trade_overlay(entry)
            _decorate_entry_execution(
                entry,
                decisions_by_key=decisions_by_key,
                decisions_by_key_strategy=decisions_by_key_strategy,
                decisions_by_event=decisions_by_event,
                entry_orders_by_key=entry_orders_by_key,
                entry_orders_by_key_strategy=entry_orders_by_key_strategy,
                auto_run_inflight=auto_run_inflight,
                wait_sec=wait_sec,
                last_run_row=last_run_row,
                run_state_public=run_state_public,
                now_dt=now_dt,
            )
            edge_val = to_float(entry.get("edge_realizable"))
            ask_val = to_float(entry.get("ask"))
            spread_val = to_float(entry.get("spread"))
            if _realizable_ok(edge_val, ask_val, spread_val):
                items.append(entry)
                item_keys.add(entry_key)
                if strategy_view == "hard_bound_no":
                    entry_ok_hard_bound_count += 1
                elif strategy_view == "adj_pair":
                    entry_ok_adj_pair_count += 1
                elif strategy_view == "mirror_follow":
                    entry_ok_mirror_follow_count += 1
                elif strategy_view == "follow_copy":
                    entry_ok_follow_count += 1
                else:
                    entry_ok_main_count += 1
            else:
                not_ok = _make_not_ok_entry(fact, entry, strategy_view)
                if _push_not_ok(not_ok):
                    if strategy_view == "hard_bound_no":
                        not_ok_hard_bound_count += 1
                    elif strategy_view == "adj_pair":
                        not_ok_adj_pair_count += 1
                    elif strategy_view == "mirror_follow":
                        not_ok_mirror_follow_count += 1
                    elif strategy_view == "follow_copy":
                        not_ok_follow_count += 1
                    else:
                        not_ok_main_count += 1

            will_order = int(decision.get("will_order") or 0)
            dec_state = str(decision.get("decided_state") or "").strip()
            if will_order == 0 and dec_state and dec_state != "entry_ok":
                reasons = decision.get("reasons") if isinstance(decision.get("reasons"), list) else []
                codes = decision.get("reason_codes") if isinstance(decision.get("reason_codes"), list) else []
                reasons_clean = [str(x or "").strip() for x in reasons if str(x or "").strip()]
                if not reasons_clean:
                    reasons_clean = [str(x or "").strip() for x in codes if str(x or "").strip()]
                if not reasons_clean:
                    reasons_clean = [f"决策阻断({dec_state})"]
                cand_block = {
                    "side": side,
                    "outcome": outcome,
                    "entry_reasons": reasons_clean,
                    "edge_score": edge_score_val,
                    "exec_edge_score": exec_edge_score_val,
                    "exec_edge_entry": exec_edge_entry_val,
                    "exec_edge_exit": exec_edge_exit_val,
                    "hold_edge_realizable": hold_edge_realizable_val,
                    "hold_edge_realizable_score": hold_edge_realizable_score_val,
                    "exit_edge_primary_source": str(
                        details.get("exit_edge_primary_source")
                        or cand.get("exit_edge_primary_source")
                        or ""
                    ),
                    "edge_realizable": edge_realizable_val,
                    "edge_realizable_score": edge_realizable_score_val,
                    "edge_realizable_v2": cand.get("edge_realizable_v2"),
                    "edge_realizable_score_v2": cand.get("edge_realizable_score_v2"),
                    "edge_realizable_p_realize": cand.get("edge_realizable_p_realize"),
                    "edge_realizable_p_converge": cand.get("edge_realizable_p_converge"),
                    "edge_realizable_p_fill_entry": cand.get("edge_realizable_p_fill_entry"),
                    "edge_realizable_p_fill_exit": cand.get("edge_realizable_p_fill_exit"),
                    "edge_realizable_hold_cost": cand.get("edge_realizable_hold_cost"),
                    "edge_realizable_p_realize_missing": cand.get("edge_realizable_p_realize_missing"),
                    "edge_realizable_p_realize_low_sample": cand.get("edge_realizable_p_realize_low_sample"),
                    "edge_realizable_p_realize_samples_min": cand.get("edge_realizable_p_realize_samples_min"),
                    "edge_realizable_target_exit_price": cand.get("edge_realizable_target_exit_price"),
                    "edge_realizable_delta_exit": cand.get("edge_realizable_delta_exit"),
                    "edge_realizable_soft_blocked": cand.get("edge_realizable_soft_blocked"),
                    "edge_realizable_soft_block_reason": cand.get("edge_realizable_soft_block_reason"),
                    "edge_realizable_soft_block_detail": cand.get("edge_realizable_soft_block_detail"),
                    "edge_realizable_soft_block_value": cand.get("edge_realizable_soft_block_value"),
                    "edge_realizable_soft_block_min": cand.get("edge_realizable_soft_block_min"),
                    "exec_fee_bps": exec_fee_bps_val,
                    "exec_fee_cost": exec_fee_cost_val,
                    "ask": ask_val,
                    "spread": spread_val,
                    "q_min_bound": q_entry_val,
                    "trade_info": cand.get("trade_info") if isinstance(cand.get("trade_info"), dict) else None,
                }
                not_ok = _make_not_ok_entry(fact, cand_block, strategy_view)
                if _push_not_ok(not_ok):
                    if strategy_view == "hard_bound_no":
                        not_ok_hard_bound_count += 1
                    elif strategy_view == "adj_pair":
                        not_ok_adj_pair_count += 1
                    elif strategy_view == "mirror_follow":
                        not_ok_mirror_follow_count += 1
                    elif strategy_view == "follow_copy":
                        not_ok_follow_count += 1
                    else:
                        not_ok_main_count += 1

        def _rank(e: Dict[str, Any]) -> Tuple[int, float, float]:
            trade_info = e.get("trade_info") if isinstance(e.get("trade_info"), dict) else {}
            pos_val = to_float(trade_info.get("position_size"))
            fills_val = to_float(trade_info.get("fills_count"))
            has_live_pos = (
                (pos_val is not None and math.isfinite(pos_val) and pos_val > TIME_EDGE_Q_EPS)
                or (fills_val is not None and math.isfinite(fills_val) and fills_val > 0)
            )
            trace = e.get("trace") if isinstance(e.get("trace"), dict) else {}
            flow_status = str(trace.get("flow_status") or "").strip().lower()
            pending = 1 if flow_status == "pending" else 0
            bottleneck_text = str(trace.get("bottleneck") or "").strip()
            worker_inflight = 1 if ("worker 执行中" in bottleneck_text or "worker执行中" in bottleneck_text) else 0
            event_pos = to_float(e.get("event_live_position_size"))
            has_event_pos = (
                event_pos is not None and math.isfinite(event_pos) and event_pos > TIME_EDGE_Q_EPS
            )
            holding = 1 if (has_live_pos or has_event_pos) else 0
            executing = 0
            if not holding:
                progress = e.get("progress") if isinstance(e.get("progress"), dict) else {}
                stage = str(progress.get("stage") or "").strip().lower()
                if stage in {
                    "ordering",
                    "ordered",
                    "pending",
                    "inflight",
                    "job_queued",
                    "job_running",
                    "job_retrying",
                    "throttled",
                }:
                    executing = 1
                decision = e.get("entry_decision") if isinstance(e.get("entry_decision"), dict) else {}
                if isinstance(decision, dict):
                    will_order = int(decision.get("will_order") or 0)
                    if will_order == 1:
                        executing = 1
                    codes = decision.get("reason_codes") if isinstance(decision.get("reason_codes"), list) else []
                    if any(str(code or "").strip() in {"market_tick_stale", "market_tick_missing"} for code in codes):
                        executing = 1
                order = e.get("entry_order") if isinstance(e.get("entry_order"), dict) else None
                if isinstance(order, dict) and order.get("order_id"):
                    executing = 1
            holding_rank = 1 if holding else 0
            v2_val = to_float(e.get("edge_realizable_v2"))
            primary = float(v2_val) if v2_val is not None and math.isfinite(v2_val) else -999.0
            score_val = None
            v = to_float(e.get("edge_realizable_score_v2"))
            if v is not None and math.isfinite(v):
                score_val = float(v)
            if score_val is None:
                v = to_float(e.get("edge_realizable_score"))
                if v is not None and math.isfinite(v):
                    score_val = float(v)
            if score_val is None:
                v = to_float(e.get("exec_edge_score"))
                if v is not None and math.isfinite(v):
                    score_val = float(v)
            if score_val is None:
                v = to_float(e.get("edge_score"))
                if v is not None and math.isfinite(v):
                    score_val = float(v)
            if score_val is None:
                q = to_float(e.get("q_min_bound"))
                a = to_float(e.get("ask"))
                if q is not None and a is not None and math.isfinite(q) and math.isfinite(a):
                    score_val = float(q - a)
            if score_val is None:
                score_val = -999.0
            updated_text = str(
                e.get("updated_at")
                or trade_info.get("updated_at")
                or trade_info.get("last_fill_at")
                or e.get("entry_at")
                or ""
            ).strip()
            updated_dt = parse_any_ts(updated_text) if updated_text else None
            updated_ts = (
                float(updated_dt.timestamp())
                if isinstance(updated_dt, datetime)
                else float("-inf")
            )
            # For holding cards, prioritize recency first; for others keep score ordering.
            recency_rank = updated_ts if holding_rank else float("-inf")
            return (holding_rank, recency_rank, primary, score_val)

        def _merge_strategy_items(entries: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
            merged: Dict[Tuple[str, str, str, str], Dict[str, Any]] = {}
            for entry in entries:
                if not isinstance(entry, dict):
                    continue
                slug_key = str(entry.get("slug") or "")
                event_date_key = str(entry.get("event_date") or "")
                outcome_key = str(entry.get("outcome") or "")
                side_key = str(entry.get("side") or "").upper()
                if not slug_key or not event_date_key or side_key not in {"YES", "NO"}:
                    continue
                key = (slug_key, event_date_key, outcome_key, side_key)
                strategy_raw = str(entry.get("strategy") or "").strip().lower()
                if key not in merged:
                    payload = dict(entry)
                    payload["strategy_group"] = [strategy_raw] if strategy_raw else []
                    merged[key] = payload
                    continue
                existing = merged[key]
                group_list = existing.get("strategy_group")
                if not isinstance(group_list, list):
                    group_list = []
                if strategy_raw and strategy_raw not in group_list:
                    group_list.append(strategy_raw)
                existing["strategy_group"] = group_list
                if _rank(entry) > _rank(existing):
                    payload = dict(entry)
                    payload["strategy_group"] = group_list
                    merged[key] = payload
            return list(merged.values())

        items = _merge_strategy_items(items)
        v2_floor = _ssot_env_float("PM_EDGE_REALIZABLE_V2_DISPLAY_MIN", 0.1)
        if v2_floor is None or not math.isfinite(v2_floor):
            v2_floor = 0.1
        def _v2_val(entry: Dict[str, Any]) -> Optional[float]:
            v2 = to_float(entry.get("edge_realizable_v2"))
            return float(v2) if v2 is not None and math.isfinite(v2) else None
        def _v2_keep(entry: Dict[str, Any]) -> bool:
            v2_val = _v2_val(entry)
            if v2_val is None:
                return False
            return v2_val >= float(v2_floor) - TIME_EDGE_Q_EPS
        def _not_ok_key(entry: Dict[str, Any]) -> Optional[Tuple[str, str, str, str, str]]:
            slug_key = str(entry.get("slug") or "")
            date_key = str(entry.get("event_date") or "")
            outcome_key = str(entry.get("outcome") or "")
            side_key = str(entry.get("side") or "").upper()
            strategy_key = str(entry.get("strategy") or "")
            if not slug_key or not date_key:
                return None
            return (slug_key, date_key, outcome_key, side_key, strategy_key)
        def _append_not_ok_from_entry(entry: Dict[str, Any], reason: str) -> None:
            key = _not_ok_key(entry)
            if key is None or key in not_ok_keys:
                return
            not_ok_keys.add(key)
            payload = dict(entry)
            payload["entry_ok"] = False
            reasons = payload.get("entry_reasons")
            if not isinstance(reasons, list):
                reasons = []
            reason_text = str(reason or "").strip()
            if reason_text and reason_text not in reasons:
                reasons.insert(0, reason_text)
            payload["entry_reasons"] = reasons
            not_ok_items.append(payload)
        kept_items: List[Dict[str, Any]] = []
        for entry in items:
            if _v2_keep(entry):
                kept_items.append(entry)
                continue
            v2_val = _v2_val(entry)
            if v2_val is None:
                reason = f"可兑现V2缺失(<{v2_floor:.2f})"
            else:
                reason = f"可兑现V2={v2_val:.4f}<{v2_floor:.2f}"
            _append_not_ok_from_entry(entry, reason)
        items = kept_items
        items.sort(key=_rank, reverse=True)
        not_ok_items.sort(key=_rank, reverse=True)

        # Top not-ok reasons for UI chips (SSOT from entry_reasons).
        not_ok_reason_counts: Dict[str, int] = {}
        for it in not_ok_items:
            rs = it.get("entry_reasons") if isinstance(it.get("entry_reasons"), list) else []
            if not rs:
                continue
            key = str(rs[0] or "").strip()
            if not key:
                continue
            not_ok_reason_counts[key] = int(not_ok_reason_counts.get(key) or 0) + 1
        not_ok_reason_top = [
            {"reason": k, "count": v}
            for k, v in sorted(not_ok_reason_counts.items(), key=lambda kv: (-int(kv[1] or 0), str(kv[0] or "")))[:12]
        ]

        def _normalize_blocker_reason_code(reason_text: Any) -> str:
            text = str(reason_text or "").strip()
            if not text:
                return "unknown_blocker"
            if text.startswith("可兑现V2缺失"):
                return "edge_realizable_v2_missing"
            if text.startswith("可兑现V2="):
                return "edge_realizable_v2_below_floor"
            if text.startswith("目标兑现诊断缺失") or text.startswith("可兑现口径缺失"):
                return "edge_tradeability_missing"
            if text.startswith("目标兑现诊断=") or text.startswith("可兑现口径="):
                return "edge_realizable_soft_diagnostic"
            if text.startswith("tradeability快照缺失"):
                return "edge_tradeability_missing"
            if text.startswith("盘口ask缺失（仅bid侧挂单"):
                return "market_ask_missing_bid_only"
            if text.startswith("盘口ask缺失（双侧不可用"):
                return "market_ask_missing_no_bid"
            if text.startswith("盘口ask缺失"):
                return "market_ask_missing"
            if text.startswith("盘口spread缺失"):
                return "market_spread_missing"
            if text.startswith("单边薄簿/不可交易"):
                return "market_one_sided_thin_book"
            if text.startswith("盘口ask异常(<0.02)"):
                return "market_ask_too_low"
            if text.startswith("盘口ask异常(>0.99)"):
                return "market_ask_too_high"
            if text.startswith("盘口spread<0"):
                return "market_spread_negative"
            if "缺少主策略候选" in text:
                return "main_candidate_missing"
            if "YES" in text and "候选" in text:
                return "yes_top_candidate_missing"
            ascii_code = re.sub(r"[^a-z0-9]+", "_", text.lower()).strip("_")
            if ascii_code:
                return ascii_code[:64]
            digest = hashlib.sha1(text.encode("utf-8")).hexdigest()[:10]
            return f"text_{digest}"

        def _entry_blocker_reason(entry: Dict[str, Any]) -> Tuple[str, str]:
            decision = entry.get("entry_decision") if isinstance(entry.get("entry_decision"), dict) else None
            reason_code = ""
            reason_text = ""
            if isinstance(decision, dict):
                reason_codes = decision.get("reason_codes") if isinstance(decision.get("reason_codes"), list) else []
                first_code = ""
                for raw_code in reason_codes:
                    code_text = str(raw_code or "").strip()
                    if code_text:
                        if not first_code:
                            first_code = code_text
                        if is_non_stat_blocker_code(code_text):
                            continue
                        reason_code = code_text
                        break
                if not reason_code and first_code:
                    reason_code = first_code
                reason_text = str(
                    decision.get("reason_text")
                    or decision.get("reason_detail")
                    or ""
                ).strip()
            if not reason_text:
                reasons = entry.get("entry_reasons") if isinstance(entry.get("entry_reasons"), list) else []
                for raw_reason in reasons:
                    reason = str(raw_reason or "").strip()
                    if reason:
                        reason_text = reason
                        break
            if not reason_code:
                reason_code = _normalize_blocker_reason_code(reason_text)
            return (reason_code or "unknown_blocker", reason_text)

        def _build_entry_blocker_table(entries: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
            groups: Dict[str, Dict[str, Any]] = {}
            total = 0
            for entry in entries:
                if not isinstance(entry, dict):
                    continue
                reason_code, reason_text = _entry_blocker_reason(entry)
                code_key = str(reason_code or "unknown_blocker").strip() or "unknown_blocker"
                if is_non_stat_blocker_code(code_key):
                    continue
                total += 1
                payload = groups.get(code_key)
                if payload is None:
                    payload = {
                        "reason_code": code_key,
                        "reason_text": str(reason_text or "").strip(),
                        "count": 0,
                        "share": 0.0,
                        "sample_slug": "",
                        "sample_event_date": "",
                        "sample_outcome": "",
                        "sample_side": "",
                        "sample_strategy": "",
                        "sample_title": "",
                        "sample_event_url": "",
                        "sample_reason_text": "",
                    }
                    groups[code_key] = payload
                payload["count"] = int(payload.get("count") or 0) + 1
                if not payload.get("reason_text") and reason_text:
                    payload["reason_text"] = str(reason_text)
                if not payload.get("sample_slug"):
                    payload["sample_slug"] = str(entry.get("slug") or "")
                    payload["sample_event_date"] = date_only(str(entry.get("event_date") or ""))
                    payload["sample_outcome"] = str(entry.get("outcome") or "")
                    payload["sample_side"] = str(entry.get("side") or "").upper()
                    payload["sample_strategy"] = str(entry.get("strategy") or "")
                    payload["sample_title"] = str(entry.get("title") or "")
                    payload["sample_event_url"] = str(entry.get("event_url") or "")
                    payload["sample_reason_text"] = str(reason_text or "")
            rows = sorted(
                groups.values(),
                key=lambda row: (-int(row.get("count") or 0), str(row.get("reason_code") or "")),
            )
            for row in rows:
                count = int(row.get("count") or 0)
                row["share"] = float(count / total) if total > 0 else 0.0
            return rows[:40]

        def _event_meta_from_fact_dict(fact: Any) -> Dict[str, Any]:
            if not isinstance(fact, dict) or not fact:
                return {}
            distribution = normalize_distribution_rows(fact.get("distribution") or fact.get("rows") or [])
            top_label = str(fact.get("market_top_label") or "").strip()
            if not top_label and distribution:
                try:
                    top_label = str(market_top_label(distribution) or "").strip()
                except Exception:
                    top_label = ""
            return {
                "event_url": str(fact.get("event_url") or ""),
                "title": str(fact.get("title") or ""),
                "city": str(fact.get("city") or ""),
                "market_top_label": top_label,
            }

        def _latest_fact_meta_ro(conn: sqlite3.Connection, slug: str, event_date: str) -> Dict[str, Any]:
            slug_key = str(slug or "").strip()
            event_date_key = date_only(str(event_date or ""))
            if not slug_key or not event_date_key:
                return {}
            try:
                cur = conn.cursor()
                cur.execute(
                    """
                    SELECT h.fact_json
                    FROM event_fact_latest l
                    JOIN event_fact_history h ON h.id = l.fact_id
                    WHERE h.slug = ? AND h.event_date = ?
                    LIMIT 1
                    """,
                    (slug_key, event_date_key),
                )
                row = cur.fetchone()
            except sqlite3.OperationalError:
                return {}
            fact = safe_json_loads(row["fact_json"]) if row else {}
            return _event_meta_from_fact_dict(fact)

        def _build_live_event_list(
            event_map: Dict[Tuple[str, str], Dict[str, Any]],
            *,
            redeemable: bool,
        ) -> List[Dict[str, Any]]:
            out: List[Dict[str, Any]] = []
            if not event_map:
                return out
            meta_conn: Optional[sqlite3.Connection] = None
            try:
                meta_conn_ctx = open_db_ro_fast(timeout_sec=0.15, busy_timeout_ms=150)
            except Exception:
                meta_conn_ctx = None
            try:
                if meta_conn_ctx is not None:
                    meta_conn = meta_conn_ctx.__enter__()
                for (slug_val, event_date_val), ev in event_map.items():
                    slug_val = str(slug_val or "").strip()
                    event_date_val = str(event_date_val or "").strip()
                    if not slug_val or not event_date_val:
                        continue
                    total = to_float(ev.get("total"))
                    count = int(ev.get("count") or 0)
                    if total is None or not math.isfinite(total) or total <= TIME_EDGE_Q_EPS:
                        continue
                    summary_rows = ev.get("summary_rows") if isinstance(ev.get("summary_rows"), list) else []
                    summary = " · ".join([str(x) for x in summary_rows if str(x or "").strip()])
                    if count > len(summary_rows):
                        summary = f"{summary} · +{count - len(summary_rows)} legs" if summary else f"{count} legs"
                    payload: Dict[str, Any] = {
                        "slug": slug_val,
                        "event_date": event_date_val,
                        "event_live_position_size": float(total),
                        "event_live_position_count": int(count),
                        "event_live_position_summary": summary,
                        "updated_at": str(ev.get("updated_at_max") or ""),
                        "redeemable": bool(redeemable),
                    }
                    ctx_item = event_fact_ctx.get((slug_val, event_date_val))
                    fact = (
                        ctx_item.get("fact")
                        if isinstance(ctx_item, dict) and isinstance(ctx_item.get("fact"), dict)
                        else {}
                    )
                    meta = _event_meta_from_fact_dict(fact)
                    if (not meta or not (meta.get("title") or meta.get("event_url"))) and meta_conn is not None:
                        meta = _latest_fact_meta_ro(meta_conn, slug_val, event_date_val) or meta
                    if isinstance(meta, dict) and meta:
                        payload.update({k: meta.get(k) for k in ("event_url", "title", "city", "market_top_label")})
                    out.append(payload)
            finally:
                if meta_conn_ctx is not None:
                    try:
                        meta_conn_ctx.__exit__(None, None, None)
                    except Exception:
                        pass
            return out

        live_position_events = _build_live_event_list(live_positions_by_event, redeemable=False)
        live_redeemable_events = _build_live_event_list(live_redeemable_by_event, redeemable=True)
        if (not live_position_events) and (not use_positions_truth):
            # Fallback: infer live events from SSOT trade_info_map (older payload shape).
            for event_key, ctx_item in event_fact_ctx.items():
                if not isinstance(event_key, tuple) or len(event_key) != 2:
                    continue
                slug_val = str(event_key[0] or "").strip()
                event_date_val = str(event_key[1] or "").strip()
                if not slug_val or not event_date_val:
                    continue
                trade_map = (
                    ctx_item.get("trade_info_map")
                    if isinstance(ctx_item, dict) and isinstance(ctx_item.get("trade_info_map"), dict)
                    else {}
                )
                has_live_position = False
                for trade in trade_map.values():
                    if not isinstance(trade, dict):
                        continue
                    pos_val = to_float(trade.get("position_size"))
                    if pos_val is not None and math.isfinite(pos_val) and pos_val > TIME_EDGE_Q_EPS:
                        has_live_position = True
                        break
                if has_live_position:
                    fact = (
                        ctx_item.get("fact")
                        if isinstance(ctx_item, dict) and isinstance(ctx_item.get("fact"), dict)
                        else {}
                    )
                    meta = _event_meta_from_fact_dict(fact)
                    payload = {"slug": slug_val, "event_date": event_date_val, "redeemable": False}
                    if meta:
                        payload.update(meta)
                    live_position_events.append(payload)

        def _item_live_key(entry: Dict[str, Any]) -> Tuple[str, str, str, str]:
            return (
                str(entry.get("slug") or "").strip(),
                date_only(str(entry.get("event_date") or "").strip()),
                str(entry.get("outcome") or "").strip(),
                str(entry.get("side") or "").strip().upper(),
            )

        def _entry_has_live_position(entry: Dict[str, Any]) -> bool:
            if use_positions_truth:
                key = _item_live_key(entry)
                pos_payload = live_positions_by_key.get(key)
                if isinstance(pos_payload, dict):
                    pos_val = to_float(pos_payload.get("position_size"))
                    return bool(pos_val is not None and math.isfinite(pos_val) and pos_val > TIME_EDGE_Q_EPS)
                return False
            trade_info = entry.get("trade_info") if isinstance(entry.get("trade_info"), dict) else {}
            pos_val = to_float(trade_info.get("position_size"))
            fills_val = to_float(trade_info.get("fills_count"))
            return bool(
                (pos_val is not None and math.isfinite(pos_val) and pos_val > TIME_EDGE_Q_EPS)
                or (fills_val is not None and math.isfinite(fills_val) and fills_val > 0)
            )

        existing_item_keys: Set[Tuple[str, str, str, str]] = set()
        for entry in items:
            if not isinstance(entry, dict):
                continue
            key = _item_live_key(entry)
            if key[0] and key[1] and key[3] in {"YES", "NO"}:
                existing_item_keys.add(key)

        live_promoted_from_not_ok = 0
        for entry in not_ok_items:
            if not isinstance(entry, dict) or not _entry_has_live_position(entry):
                continue
            key = _item_live_key(entry)
            if not key[0] or not key[1] or key[3] not in {"YES", "NO"}:
                continue
            if key in existing_item_keys:
                continue
            promoted = dict(entry)
            promoted["holding_event"] = True
            _apply_live_position_overlay(promoted)
            _apply_recent_trade_overlay(promoted)
            _decorate_entry_execution(
                promoted,
                decisions_by_key=decisions_by_key,
                decisions_by_key_strategy=decisions_by_key_strategy,
                decisions_by_event=decisions_by_event,
                entry_orders_by_key=entry_orders_by_key,
                entry_orders_by_key_strategy=entry_orders_by_key_strategy,
                auto_run_inflight=auto_run_inflight,
                wait_sec=wait_sec,
                last_run_row=last_run_row,
                run_state_public=run_state_public,
                now_dt=now_dt,
            )
            items.append(promoted)
            existing_item_keys.add(key)
            live_promoted_from_not_ok += 1

        live_promoted_fallback = 0
        for (slug_key, event_date_key, outcome_key, side_key), pos_payload in live_positions_by_key.items():
            slug_val = str(slug_key or "").strip()
            date_val = date_only(str(event_date_key or "").strip())
            outcome_val = str(outcome_key or "").strip()
            side_val = str(side_key or "").strip().upper()
            if not slug_val or not date_val or not outcome_val or side_val not in {"YES", "NO"}:
                continue
            key = (slug_val, date_val, outcome_val, side_val)
            if key in existing_item_keys:
                continue
            pos_size = to_float(pos_payload.get("position_size"))
            if pos_size is None or not math.isfinite(pos_size) or pos_size <= TIME_EDGE_Q_EPS:
                continue
            event_ctx = event_fact_ctx.get((slug_val, date_val)) or event_fact_ctx.get((slug_val, event_date_key))
            fact_ref = event_ctx.get("fact") if isinstance(event_ctx, dict) and isinstance(event_ctx.get("fact"), dict) else {}
            event_meta = _event_meta_from_fact_dict(fact_ref)
            event_totals = live_positions_by_event.get((slug_val, date_val)) or live_positions_by_event.get((slug_val, event_date_key)) or {}
            summary_rows = event_totals.get("summary_rows") if isinstance(event_totals, dict) and isinstance(event_totals.get("summary_rows"), list) else []
            summary_text = " · ".join([str(x or "") for x in summary_rows if str(x or "").strip()])
            if isinstance(event_totals, dict):
                count_val = int(event_totals.get("count") or 0)
                if count_val > len(summary_rows):
                    summary_text = (
                        f"{summary_text} · +{count_val - len(summary_rows)} legs"
                        if summary_text
                        else f"{count_val} legs"
                    )
            promoted = {
                "slug": slug_val,
                "event_date": date_val,
                "title": str(event_meta.get("title") or fact_ref.get("title") or slug_val),
                "event_url": str(event_meta.get("event_url") or fact_ref.get("event_url") or ""),
                "run_date": str(run_date_key or ""),
                "strategy": "live_position",
                "side": side_val,
                "outcome": outcome_val,
                "entry_ok": False,
                "holding_event": True,
                "entry_reasons": ["在场持仓事件"],
                "trade_info": {
                    "position_size": float(pos_size),
                    "state": str(pos_payload.get("state") or "entry"),
                    "avg_price": to_float(pos_payload.get("avg_price")),
                    "updated_at": str(pos_payload.get("updated_at") or ""),
                },
                "event_live_position_size": to_float(event_totals.get("total")) if isinstance(event_totals, dict) else float(pos_size),
                "event_live_position_count": int(event_totals.get("count") or 1) if isinstance(event_totals, dict) else 1,
                "event_live_position_summary": summary_text,
            }
            _apply_live_position_overlay(promoted)
            _apply_recent_trade_overlay(promoted)
            _decorate_entry_execution(
                promoted,
                decisions_by_key=decisions_by_key,
                decisions_by_key_strategy=decisions_by_key_strategy,
                decisions_by_event=decisions_by_event,
                entry_orders_by_key=entry_orders_by_key,
                entry_orders_by_key_strategy=entry_orders_by_key_strategy,
                auto_run_inflight=auto_run_inflight,
                wait_sec=wait_sec,
                last_run_row=last_run_row,
                run_state_public=run_state_public,
                now_dt=now_dt,
            )
            items.append(promoted)
            existing_item_keys.add(key)
            live_promoted_fallback += 1

        for entry in items:
            _hydrate_entry_from_decision(entry)
        for entry in not_ok_items:
            _hydrate_entry_from_decision(entry)

        def _normalize_trace_strategy(raw_value: Any) -> str:
            strategy_raw = str(raw_value or "").strip().lower()
            if strategy_raw == "live_position":
                return "live_position"
            fallback = "path_probability_follow" if lcb_global_enabled else "main"
            return _normalize_strategy_key(strategy_raw, fallback=fallback)

        def _normalize_trace_entries(entries: List[Dict[str, Any]]) -> None:
            for entry in entries:
                if not isinstance(entry, dict):
                    continue
                strategy_norm = _normalize_trace_strategy(entry.get("strategy"))
                entry["strategy"] = strategy_norm
                decision = entry.get("entry_decision") if isinstance(entry.get("entry_decision"), dict) else None
                if isinstance(decision, dict):
                    detail_text = str(decision.get("reason_detail") or "").strip()
                    if detail_text:
                        detail_text = re.sub(r"strategy=[a-z0-9_]+", f"strategy={strategy_norm}", detail_text)
                        decision["reason_detail"] = detail_text
                entry_order = entry.get("entry_order") if isinstance(entry.get("entry_order"), dict) else None
                if isinstance(entry_order, dict):
                    order_strategy = str(entry_order.get("strategy") or "").strip()
                    if order_strategy and strategy_norm != "live_position":
                        entry_order["strategy"] = strategy_norm
                group_vals = entry.get("strategy_group")
                if not isinstance(group_vals, list):
                    continue
                normalized_group: List[str] = []
                for raw in group_vals:
                    key = _normalize_trace_strategy(raw)
                    if key and key not in normalized_group:
                        normalized_group.append(key)
                entry["strategy_group"] = normalized_group

        _normalize_trace_entries(items)
        _normalize_trace_entries(not_ok_items)

        neg_hidden_items = sum(1 for e in items if _entry_should_hide_negative(e))
        neg_hidden_not_ok = sum(1 for e in not_ok_items if _entry_should_hide_negative(e))
        if neg_hidden_items:
            items = [e for e in items if not _entry_should_hide_negative(e)]
        if neg_hidden_not_ok:
            not_ok_items = [e for e in not_ok_items if not _entry_should_hide_negative(e)]

        hidden_incomplete_items = 0
        hidden_incomplete_not_ok_items = 0
        filtered_items: List[Dict[str, Any]] = []
        for e in items:
            if _entry_has_required_metrics(e):
                filtered_items.append(e)
                continue
            trade_info = e.get("trade_info") if isinstance(e.get("trade_info"), dict) else {}
            pos_val = to_float(trade_info.get("position_size"))
            holding = pos_val is not None and math.isfinite(pos_val) and pos_val > TIME_EDGE_Q_EPS
            if holding:
                e["metrics_incomplete"] = True
                filtered_items.append(e)
                continue
            filtered_items.append(e)
        items = filtered_items
        filtered_not_ok_items: List[Dict[str, Any]] = []
        for e in not_ok_items:
            if not _entry_has_required_metrics(e):
                e["metrics_incomplete"] = True
                hidden_incomplete_not_ok_items += 1
            filtered_not_ok_items.append(e)
        not_ok_items = filtered_not_ok_items

        def _is_entry_blocker_item(entry: Dict[str, Any]) -> bool:
            if not isinstance(entry, dict):
                return False
            # "入场未达标" should only include candidates for NEW entry.
            # If this key is already in live positions (positions-truth or local fallback),
            # it belongs to in-position exit management and must not appear here.
            if _entry_has_live_position(entry):
                return False
            trade_info = entry.get("trade_info") if isinstance(entry.get("trade_info"), dict) else {}
            pos_val = to_float(trade_info.get("position_size"))
            if pos_val is not None and math.isfinite(pos_val) and pos_val > TIME_EDGE_Q_EPS:
                return False
            state_text = str(trade_info.get("state") or "").strip().lower()
            if state_text in {"entry", "redeemable"}:
                return False
            reasons = entry.get("entry_reasons") if isinstance(entry.get("entry_reasons"), list) else []
            reason_text = " ".join(str(x or "").strip() for x in reasons if str(x or "").strip()).lower()
            if "已在入场态" in reason_text or "already_in_entry" in reason_text:
                return False
            return True

        def _is_new_open_candidate(entry: Dict[str, Any]) -> bool:
            if not isinstance(entry, dict):
                return False
            if not bool(entry.get("entry_ok")):
                return False
            if _entry_has_live_position(entry):
                return False
            event_live_count = to_float(entry.get("event_live_position_count"))
            if event_live_count is not None and math.isfinite(event_live_count) and event_live_count > 0:
                return False
            decision = entry.get("entry_decision") if isinstance(entry.get("entry_decision"), dict) else None
            if isinstance(decision, dict):
                reason_codes = decision.get("reason_codes") if isinstance(decision.get("reason_codes"), list) else []
                normalized_codes = {
                    str(code or "").strip().lower()
                    for code in reason_codes
                    if str(code or "").strip()
                }
                if "already_in_entry" in normalized_codes:
                    return False
                reason_text = str(
                    decision.get("reason_text")
                    or decision.get("reason_detail")
                    or ""
                ).strip()
                if "已在入场态" in reason_text:
                    return False
            return True

        non_stat_not_ok_items = 0
        filtered_not_ok_for_stats: List[Dict[str, Any]] = []
        for entry in not_ok_items:
            if not _is_entry_blocker_item(entry):
                continue
            reason_code, _reason_text = _entry_blocker_reason(entry)
            if is_non_stat_blocker_code(reason_code):
                non_stat_not_ok_items += 1
                continue
            filtered_not_ok_for_stats.append(entry)
        not_ok_items = filtered_not_ok_for_stats
        def _rank_with_key(e: Dict[str, Any]) -> Tuple[int, float, float, float, str, str, str, str, str]:
            base = _rank(e)
            return (
                int(base[0]),
                float(base[1]),
                float(base[2]),
                float(base[3]),
                str(e.get("slug") or ""),
                str(e.get("event_date") or ""),
                str(e.get("outcome") or ""),
                str(e.get("side") or "").upper(),
                str(e.get("strategy") or ""),
            )

        not_ok_items.sort(key=_rank_with_key, reverse=True)

        items.sort(key=_rank_with_key, reverse=True)

        def _trace_hide_past_peak_enabled() -> bool:
            raw = str(os.environ.get("PM_AUTO_TRADE_TRACE_HIDE_CHENGDU_PAST_PEAK", "1") or "1").strip().lower()
            return raw not in {"", "0", "false", "off", "no"}

        def _trace_past_peak_hour() -> float:
            for key, default in (
                ("PM_AUTO_TRADE_TRACE_CHENGDU_PEAK_HOUR", None),
                ("PM_BAYES_LIKELIHOOD_REFRESH_PEAK_HOUR", None),
                ("PM_OBS_NOWCAST_FULL_HOUR", None),
            ):
                raw = os.environ.get(key)
                if raw is None and default is None:
                    continue
                try:
                    val = float(raw if raw is not None else default)
                except (TypeError, ValueError):
                    continue
                if math.isfinite(val):
                    return max(0.0, min(23.99, float(val)))
            return 16.0

        hide_past_peak_enabled = _trace_hide_past_peak_enabled()
        chengdu_peak_hour = _trace_past_peak_hour()
        try:
            chengdu_now_local = datetime.now(ZoneInfo("Asia/Shanghai"))
        except Exception:
            chengdu_now_local = datetime.utcnow().replace(tzinfo=timezone.utc) + timedelta(hours=8)
        chengdu_today = chengdu_now_local.date().isoformat()
        chengdu_local_hour = (
            chengdu_now_local.hour
            + chengdu_now_local.minute / 60.0
            + chengdu_now_local.second / 3600.0
        )

        def _is_chengdu_highest_temp_trace_entry(entry: Dict[str, Any]) -> bool:
            if not isinstance(entry, dict):
                return False
            slug_l = str(entry.get("slug") or "").strip().lower()
            title_l = str(entry.get("title") or "").strip().lower()
            city_l = str(entry.get("city") or "").strip().lower()
            station_l = str(entry.get("station_id") or "").strip().upper()
            source_l = str(entry.get("source") or entry.get("resolution_source") or "").strip().lower()
            is_chengdu = (
                "chengdu" in slug_l
                or "chengdu" in title_l
                or city_l == "chengdu"
                or station_l == "ZUUU"
                or "/cn/chengdu/" in source_l
            )
            if not is_chengdu:
                return False
            return (
                slug_l.startswith("highest-temperature-in-")
                or "highest temperature" in title_l
            )

        def _should_hide_chengdu_past_peak(entry: Dict[str, Any]) -> bool:
            if not hide_past_peak_enabled:
                return False
            if not _is_chengdu_highest_temp_trace_entry(entry):
                return False
            event_date_key = _normalize_date_key(str(entry.get("event_date") or ""))
            if not event_date_key:
                return False
            if event_date_key < chengdu_today:
                return True
            if event_date_key > chengdu_today:
                return False
            return chengdu_local_hour >= float(chengdu_peak_hour) - 1e-9

        hidden_past_peak_items = sum(1 for e in items if _should_hide_chengdu_past_peak(e))
        hidden_past_peak_not_ok_items = sum(1 for e in not_ok_items if _should_hide_chengdu_past_peak(e))
        hidden_past_peak_live_position_events = sum(
            1 for e in live_position_events if _should_hide_chengdu_past_peak(e)
        )
        hidden_past_peak_live_redeemable_events = sum(
            1 for e in live_redeemable_events if _should_hide_chengdu_past_peak(e)
        )
        if hidden_past_peak_items:
            items = [e for e in items if not _should_hide_chengdu_past_peak(e)]
        if hidden_past_peak_not_ok_items:
            not_ok_items = [e for e in not_ok_items if not _should_hide_chengdu_past_peak(e)]
        if hidden_past_peak_live_position_events:
            live_position_events = [e for e in live_position_events if not _should_hide_chengdu_past_peak(e)]
        if hidden_past_peak_live_redeemable_events:
            live_redeemable_events = [
                e for e in live_redeemable_events if not _should_hide_chengdu_past_peak(e)
            ]
        hidden_past_peak_total = (
            hidden_past_peak_items
            + hidden_past_peak_not_ok_items
            + hidden_past_peak_live_position_events
            + hidden_past_peak_live_redeemable_events
        )
        past_peak_display_filter = {
            "enabled": bool(hide_past_peak_enabled),
            "scope": "chengdu_highest_temperature",
            "timezone": "Asia/Shanghai",
            "today": chengdu_today,
            "local_hour": float(chengdu_local_hour),
            "peak_hour": float(chengdu_peak_hour),
            "hidden_items": int(hidden_past_peak_items),
            "hidden_not_ok_items": int(hidden_past_peak_not_ok_items),
            "hidden_live_position_events": int(hidden_past_peak_live_position_events),
            "hidden_live_redeemable_events": int(hidden_past_peak_live_redeemable_events),
            "hidden_total": int(hidden_past_peak_total),
        }

        # Recompute reason aggregates after all hide/filter steps so UI counters match the visible list.
        not_ok_reason_counts = {}
        for it in not_ok_items:
            rs = it.get("entry_reasons") if isinstance(it.get("entry_reasons"), list) else []
            if not rs:
                continue
            key = str(rs[0] or "").strip()
            if not key:
                continue
            not_ok_reason_counts[key] = int(not_ok_reason_counts.get(key) or 0) + 1
        not_ok_reason_top = [
            {"reason": k, "count": v}
            for k, v in sorted(not_ok_reason_counts.items(), key=lambda kv: (-int(kv[1] or 0), str(kv[0] or "")))[:12]
        ]
        entry_blocker_table = _build_entry_blocker_table(not_ok_items)

        def _live_event_rank(entry: Dict[str, Any]) -> Tuple[float, str, str]:
            updated_text = str(entry.get("updated_at") or "").strip()
            updated_dt = parse_any_ts(updated_text) if updated_text else None
            updated_ts = updated_dt.timestamp() if isinstance(updated_dt, datetime) else float("-inf")
            return (
                float(updated_ts),
                date_only(str(entry.get("event_date") or "")),
                str(entry.get("slug") or ""),
            )

        live_position_events.sort(key=_live_event_rank, reverse=True)
        live_redeemable_events.sort(key=_live_event_rank, reverse=True)

        shadow_band_enabled = str(
            os.environ.get("PM_LCB_BAND_V1_SHADOW_ENABLED", "1") or "1"
        ).strip().lower() not in {"", "0", "false", "off", "no"}
        shadow_band_width_min = _ssot_env_int("PM_LCB_BAND_V1_WIDTH_MIN", 1)
        shadow_band_width_max = _ssot_env_int("PM_LCB_BAND_V1_WIDTH_MAX", 2)
        shadow_band_leg_lcb_min = _ssot_env_float("PM_LCB_BAND_V1_LEG_LCB_MIN", 0.003)
        shadow_band_combo_lcb_min = _ssot_env_float("PM_LCB_BAND_V1_COMBO_LCB_MIN", 0.008)
        shadow_band_tail_no_q_min = _ssot_env_float("PM_LCB_BAND_V1_TAIL_NO_Q_MIN", 0.75)
        shadow_band_tail_no_weight = _ssot_env_float("PM_LCB_BAND_V1_TAIL_NO_WEIGHT", 0.60)
        shadow_band_no_legs_max = _ssot_env_int("PM_LCB_BAND_V1_NO_LEGS_MAX", 2)
        shadow_band_min_settled_events = _ssot_env_int("PM_LCB_BAND_V1_MIN_SETTLED_EVENTS", 30)
        shadow_band_min_paired_events = _ssot_env_int("PM_LCB_BAND_V1_MIN_PAIRED_SETTLED_EVENTS", 20)
        try:
            shadow_band_width_min_i = int(shadow_band_width_min or 1)
        except (TypeError, ValueError):
            shadow_band_width_min_i = 1
        try:
            shadow_band_width_max_i = int(shadow_band_width_max or 2)
        except (TypeError, ValueError):
            shadow_band_width_max_i = 2
        if shadow_band_width_min_i < 1:
            shadow_band_width_min_i = 1
        if shadow_band_width_max_i < shadow_band_width_min_i:
            shadow_band_width_max_i = shadow_band_width_min_i
        shadow_band_width_max_i = min(shadow_band_width_max_i, 8)
        try:
            shadow_band_no_legs_max_i = int(shadow_band_no_legs_max or 2)
        except (TypeError, ValueError):
            shadow_band_no_legs_max_i = 2
        try:
            shadow_band_min_settled_events_i = int(shadow_band_min_settled_events or 30)
        except (TypeError, ValueError):
            shadow_band_min_settled_events_i = 30
        try:
            shadow_band_min_paired_events_i = int(shadow_band_min_paired_events or 20)
        except (TypeError, ValueError):
            shadow_band_min_paired_events_i = 20
        shadow_band_no_legs_max_i = max(0, min(4, shadow_band_no_legs_max_i))
        shadow_band_min_settled_events_i = max(1, min(500, shadow_band_min_settled_events_i))
        shadow_band_min_paired_events_i = max(1, min(500, shadow_band_min_paired_events_i))
        if shadow_band_leg_lcb_min is None or not math.isfinite(shadow_band_leg_lcb_min):
            shadow_band_leg_lcb_min = 0.003
        if shadow_band_combo_lcb_min is None or not math.isfinite(shadow_band_combo_lcb_min):
            shadow_band_combo_lcb_min = 0.008
        if shadow_band_tail_no_q_min is None or not math.isfinite(shadow_band_tail_no_q_min):
            shadow_band_tail_no_q_min = 0.75
        shadow_band_tail_no_q_min = min(1.0, max(0.0, float(shadow_band_tail_no_q_min)))
        if shadow_band_tail_no_weight is None or not math.isfinite(shadow_band_tail_no_weight):
            shadow_band_tail_no_weight = 0.35
        shadow_band_tail_no_weight = min(1.0, max(0.0, float(shadow_band_tail_no_weight)))
        shadow_band_scope_max_days = 1 if lcb_global_block_d2_plus else None
        run_date_obj = parse_date(run_date_key)
        shadow_band_timing_filtered = {
            "past": 0,
            "d2_plus": 0,
            "unknown": 0,
        }

        def _shadow_outcome_sort_key(label: str) -> Optional[Tuple[float, float]]:
            label_text = str(label or "").strip()
            if not label_text:
                return None
            parser = scan_parse_outcome_label if callable(scan_parse_outcome_label) else None
            if parser is not None:
                try:
                    spec = parser(label_text)
                except Exception:
                    spec = None
                if spec is not None:
                    kind = str(getattr(spec, "kind", "") or "").strip().lower()
                    k_val = to_float(getattr(spec, "k", None))
                    k2_val = to_float(getattr(spec, "k2", None))
                    if kind == "range" and k_val is not None and k2_val is not None:
                        low_v = min(float(k_val), float(k2_val))
                        high_v = max(float(k_val), float(k2_val))
                        return (0.5 * (low_v + high_v), high_v - low_v)
                    if kind == "eq" and k_val is not None:
                        return (float(k_val), 0.0)
                    if kind == "le" and k_val is not None:
                        return (float(k_val) - 999.0, 999.0)
                    if kind == "ge" and k_val is not None:
                        return (float(k_val) + 999.0, 999.0)
            nums = re.findall(r"-?\d+(?:\.\d+)?", label_text)
            if not nums:
                return None
            vals = []
            for raw in nums:
                try:
                    vals.append(float(raw))
                except (TypeError, ValueError):
                    continue
            if not vals:
                return None
            if len(vals) >= 2:
                low_v = min(vals[0], vals[1])
                high_v = max(vals[0], vals[1])
                return (0.5 * (low_v + high_v), high_v - low_v)
            return (float(vals[0]), 0.0)

        def _shadow_leg_lcb(
            row_ref: Dict[str, Any],
            side: str,
        ) -> Optional[float]:
            side_u = str(side or "").strip().upper()
            if side_u == "YES":
                ask_val = to_float(row_ref.get("best_ask"))
                q_val = _coalesce_metric(row_ref.get("q_entry"), row_ref.get("q_round"))
                fallback_edge = (
                    float(q_val) - float(ask_val)
                    if q_val is not None and ask_val is not None and math.isfinite(ask_val)
                    else None
                )
                return _coalesce_metric(
                    row_ref.get("edge_tradeability_profit_value_yes"),
                    row_ref.get("edge_tradeability_edge_lcb_yes"),
                    row_ref.get("edge_tradeability_profit_value"),
                    row_ref.get("edge_tradeability_edge_lcb"),
                    row_ref.get("edge_realizable_yes"),
                    row_ref.get("edge_realizable"),
                    fallback_edge,
                )
            ask_no = to_float(row_ref.get("best_ask_no"))
            q_no = _coalesce_metric(row_ref.get("q_entry_no"))
            if q_no is None:
                q_yes = _coalesce_metric(row_ref.get("q_entry"), row_ref.get("q_round"))
                if q_yes is not None:
                    q_no = max(0.0, min(1.0, 1.0 - float(q_yes)))
            fallback_edge_no = (
                float(q_no) - float(ask_no)
                if q_no is not None and ask_no is not None and math.isfinite(ask_no)
                else None
            )
            return _coalesce_metric(
                row_ref.get("edge_tradeability_profit_value_no"),
                row_ref.get("edge_tradeability_edge_lcb_no"),
                row_ref.get("edge_tradeability_profit_value"),
                row_ref.get("edge_realizable_no"),
                fallback_edge_no,
            )

        lcb_event_best: Dict[Tuple[str, str], Dict[str, Any]] = {}
        for entry in items:
            if not _is_new_open_candidate(entry):
                continue
            strategy_key = str(entry.get("strategy") or "").strip().lower()
            if strategy_key == "mirror_follow":
                continue
            slug_key = str(entry.get("slug") or "").strip()
            event_date_key = date_only(str(entry.get("event_date") or "").strip())
            if not slug_key or not event_date_key:
                continue
            leg_lcb = _coalesce_metric(
                entry.get("edge_tradeability_profit_value"),
                entry.get("edge_tradeability_edge_lcb"),
                entry.get("edge_realizable"),
                entry.get("edge_realizable_v2"),
            )
            if leg_lcb is None:
                continue
            event_key = (slug_key, event_date_key)
            prev_payload = lcb_event_best.get(event_key) if isinstance(lcb_event_best.get(event_key), dict) else {}
            prev_val = _coalesce_metric((prev_payload or {}).get("edge_lcb"))
            if prev_val is None or float(leg_lcb) > float(prev_val):
                lcb_event_best[event_key] = {
                    "edge_lcb": float(leg_lcb),
                    "ask": _coalesce_metric(entry.get("ask")),
                    "outcome": str(entry.get("outcome") or ""),
                    "side": str(entry.get("side") or "").strip().upper(),
                    "title": str(entry.get("title") or ""),
                    "event_url": str(entry.get("event_url") or ""),
                }

        shadow_band_entries: List[Dict[str, Any]] = []
        shadow_band_blocked = 0
        shadow_band_events_total = 0
        if shadow_band_enabled:
            for raw_key, ctx_item in event_fact_ctx.items():
                if not isinstance(raw_key, tuple) or len(raw_key) != 2:
                    continue
                slug_key = str(raw_key[0] or "").strip()
                event_date_key = date_only(str(raw_key[1] or "").strip())
                if not slug_key or not event_date_key:
                    shadow_band_timing_filtered["unknown"] = int(
                        shadow_band_timing_filtered.get("unknown") or 0
                    ) + 1
                    continue
                event_date_obj = parse_date(event_date_key)
                if run_date_obj is None or event_date_obj is None:
                    shadow_band_timing_filtered["unknown"] = int(
                        shadow_band_timing_filtered.get("unknown") or 0
                    ) + 1
                    continue
                days_to_event = (event_date_obj - run_date_obj).days
                if days_to_event < 0:
                    shadow_band_timing_filtered["past"] = int(
                        shadow_band_timing_filtered.get("past") or 0
                    ) + 1
                    continue
                if (
                    shadow_band_scope_max_days is not None
                    and days_to_event > int(shadow_band_scope_max_days)
                ):
                    shadow_band_timing_filtered["d2_plus"] = int(
                        shadow_band_timing_filtered.get("d2_plus") or 0
                    ) + 1
                    continue
                if not isinstance(ctx_item, dict):
                    continue
                fact_obj = ctx_item.get("fact") if isinstance(ctx_item.get("fact"), dict) else {}
                if not isinstance(fact_obj, dict):
                    continue
                if bool(fact_obj.get("market_closed")):
                    continue
                row_by_outcome = (
                    ctx_item.get("row_by_outcome")
                    if isinstance(ctx_item.get("row_by_outcome"), dict)
                    else {}
                )
                if not row_by_outcome:
                    continue
                shadow_band_events_total += 1
                sortable_rows: List[Dict[str, Any]] = []
                for outcome_label, row_ref in row_by_outcome.items():
                    if not isinstance(row_ref, dict):
                        continue
                    sort_key = _shadow_outcome_sort_key(str(outcome_label or ""))
                    if sort_key is None:
                        continue
                    ask_yes = to_float(row_ref.get("best_ask"))
                    spread_yes = to_float(row_ref.get("spread"))
                    bid_yes = to_float(row_ref.get("best_bid"))
                    one_sided_yes = bool(
                        ask_yes is not None
                        and math.isfinite(ask_yes)
                        and ask_yes <= float(AUTO_TRADE_TRACE_ONE_SIDED_ASK_MAX) + TIME_EDGE_Q_EPS
                        and (bid_yes is None or not math.isfinite(bid_yes))
                    )
                    if (
                        ask_yes is None
                        or not math.isfinite(ask_yes)
                        or ask_yes <= TIME_EDGE_Q_EPS
                        or spread_yes is None
                        or not math.isfinite(spread_yes)
                        or spread_yes < -TIME_EDGE_Q_EPS
                        or spread_yes > lcb_global_max_spread + TIME_EDGE_Q_EPS
                        or one_sided_yes
                    ):
                        continue
                    leg_lcb_yes = _shadow_leg_lcb(row_ref, "YES")
                    if leg_lcb_yes is None or not math.isfinite(leg_lcb_yes):
                        continue
                    q_yes = _coalesce_metric(row_ref.get("q_entry"), row_ref.get("q_round"))
                    sortable_rows.append(
                        {
                            "outcome": str(outcome_label or ""),
                            "sort_key": sort_key,
                            "row": row_ref,
                            "yes_lcb": float(leg_lcb_yes),
                            "q_yes": float(q_yes) if q_yes is not None and math.isfinite(q_yes) else None,
                        }
                    )
                if len(sortable_rows) < shadow_band_width_min_i:
                    shadow_band_blocked += 1
                    continue
                sortable_rows.sort(
                    key=lambda row: (float((row.get("sort_key") or (0.0, 0.0))[0]), float((row.get("sort_key") or (0.0, 0.0))[1]))
                )
                best_window: Optional[Dict[str, Any]] = None
                max_width = min(shadow_band_width_max_i, len(sortable_rows))
                for width in range(shadow_band_width_min_i, max_width + 1):
                    for start in range(0, len(sortable_rows) - width + 1):
                        window = sortable_rows[start:start + width]
                        leg_lcbs = [to_float(item.get("yes_lcb")) for item in window]
                        if not leg_lcbs or any(v is None or not math.isfinite(v) for v in leg_lcbs):
                            continue
                        leg_lcbs_f = [float(v) for v in leg_lcbs if v is not None]
                        if not leg_lcbs_f:
                            continue
                        if min(leg_lcbs_f) + TIME_EDGE_Q_EPS < float(shadow_band_leg_lcb_min):
                            continue
                        score = float(sum(leg_lcbs_f) / max(1, len(leg_lcbs_f)))
                        candidate = {
                            "start": start,
                            "width": width,
                            "score": score,
                            "window": window,
                        }
                        if best_window is None:
                            best_window = candidate
                            continue
                        best_score = float(best_window.get("score") or 0.0)
                        best_width = int(best_window.get("width") or 0)
                        if score > best_score + TIME_EDGE_Q_EPS or (
                            abs(score - best_score) <= TIME_EDGE_Q_EPS and width > best_width
                        ):
                            best_window = candidate
                if not best_window:
                    shadow_band_blocked += 1
                    continue
                window_rows = best_window.get("window") if isinstance(best_window.get("window"), list) else []
                if not window_rows:
                    shadow_band_blocked += 1
                    continue
                used_idx = set()
                for idx in range(int(best_window.get("start") or 0), int(best_window.get("start") or 0) + int(best_window.get("width") or 0)):
                    used_idx.add(idx)
                yes_lcbs = [float(to_float(item.get("yes_lcb")) or 0.0) for item in window_rows]
                yes_lcb_mean = float(sum(yes_lcbs) / max(1, len(yes_lcbs)))
                combo_lcb = float(yes_lcb_mean)
                tail_no_legs: List[Dict[str, Any]] = []
                if shadow_band_tail_no_weight > TIME_EDGE_Q_EPS and shadow_band_no_legs_max_i > 0:
                    no_leg_pool: List[Dict[str, Any]] = []
                    for idx, item in enumerate(sortable_rows):
                        if idx in used_idx:
                            continue
                        row_ref = item.get("row") if isinstance(item.get("row"), dict) else {}
                        ask_no = to_float(row_ref.get("best_ask_no"))
                        bid_no = to_float(row_ref.get("best_bid_no"))
                        spread_no = to_float(row_ref.get("spread_no"))
                        one_sided_no = bool(
                            ask_no is not None
                            and math.isfinite(ask_no)
                            and ask_no <= float(AUTO_TRADE_TRACE_ONE_SIDED_ASK_MAX) + TIME_EDGE_Q_EPS
                            and (bid_no is None or not math.isfinite(bid_no))
                        )
                        if (
                            ask_no is None
                            or not math.isfinite(ask_no)
                            or ask_no <= TIME_EDGE_Q_EPS
                            or spread_no is None
                            or not math.isfinite(spread_no)
                            or spread_no < -TIME_EDGE_Q_EPS
                            or spread_no > lcb_global_max_spread + TIME_EDGE_Q_EPS
                            or one_sided_no
                        ):
                            continue
                        lcb_no = _shadow_leg_lcb(row_ref, "NO")
                        if lcb_no is None or not math.isfinite(lcb_no):
                            continue
                        if float(lcb_no) + TIME_EDGE_Q_EPS < float(shadow_band_leg_lcb_min):
                            continue
                        q_no = _coalesce_metric(row_ref.get("q_entry_no"))
                        if q_no is None:
                            q_yes = _coalesce_metric(row_ref.get("q_entry"), row_ref.get("q_round"))
                            if q_yes is not None:
                                q_no = max(0.0, min(1.0, 1.0 - float(q_yes)))
                        if q_no is None or not math.isfinite(q_no) or float(q_no) + TIME_EDGE_Q_EPS < float(shadow_band_tail_no_q_min):
                            continue
                        no_leg_pool.append(
                            {
                                "outcome": str(item.get("outcome") or ""),
                                "lcb": float(lcb_no),
                                "q_no": float(q_no),
                            }
                        )
                    no_leg_pool.sort(
                        key=lambda row: (
                            float(to_float(row.get("lcb")) or float("-inf")),
                            float(to_float(row.get("q_no")) or float("-inf")),
                        ),
                        reverse=True,
                    )
                    if no_leg_pool:
                        tail_no_legs = no_leg_pool[: shadow_band_no_legs_max_i]
                if tail_no_legs:
                    weight = float(shadow_band_tail_no_weight)
                    no_lcb_sum = 0.0
                    for leg in tail_no_legs:
                        no_lcb_sum += float(to_float(leg.get("lcb")) or 0.0)
                    combo_lcb = float(
                        (
                            float(yes_lcb_mean) * float(len(yes_lcbs))
                            + float(no_lcb_sum) * weight
                        )
                        / max(1e-9, float(len(yes_lcbs)) + float(len(tail_no_legs)) * weight)
                    )
                entry_ok = bool(combo_lcb + TIME_EDGE_Q_EPS >= float(shadow_band_combo_lcb_min))
                if not entry_ok:
                    shadow_band_blocked += 1
                leg_payload = []
                for item in window_rows:
                    leg_payload.append(
                        {
                            "outcome": str(item.get("outcome") or ""),
                            "side": "YES",
                            "lcb": float(to_float(item.get("yes_lcb")) or 0.0),
                        }
                    )
                for tail_no_leg in tail_no_legs:
                    leg_payload.append(
                        {
                            "outcome": str(tail_no_leg.get("outcome") or ""),
                            "side": "NO",
                            "lcb": float(to_float(tail_no_leg.get("lcb")) or 0.0),
                        }
                    )
                band_start = str(window_rows[0].get("outcome") or "")
                band_end = str(window_rows[-1].get("outcome") or "")
                shadow_band_entries.append(
                    {
                        "slug": str(slug_key or ""),
                        "event_date": date_only(str(event_date_key or "")),
                        "days_to_event": int(days_to_event),
                        "title": str(fact_obj.get("title") or slug_key),
                        "event_url": str(fact_obj.get("event_url") or ""),
                        "combo_lcb": float(combo_lcb),
                        "yes_lcb_mean": float(yes_lcb_mean),
                        "yes_leg_count": int(len(yes_lcbs)),
                        "no_lcb_mean": (
                            float(
                                sum(float(to_float(leg.get("lcb")) or 0.0) for leg in tail_no_legs)
                                / max(1, len(tail_no_legs))
                            )
                            if tail_no_legs
                            else None
                        ),
                        "no_leg_count": int(len(tail_no_legs)),
                        "tail_no_added": bool(tail_no_legs),
                        "entry_ok": bool(entry_ok),
                        "band_start": band_start,
                        "band_end": band_end,
                        "legs": leg_payload,
                    }
                )

        shadow_band_ok_entries = [e for e in shadow_band_entries if bool(e.get("entry_ok"))]
        shadow_band_new_open_entries: List[Dict[str, Any]] = []
        for entry in shadow_band_ok_entries:
            key = (str(entry.get("slug") or ""), str(entry.get("event_date") or ""))
            if key in live_positions_by_event:
                continue
            shadow_band_new_open_entries.append(entry)
        shadow_event_key_set = {
            (str(entry.get("slug") or ""), str(entry.get("event_date") or ""))
            for entry in shadow_band_new_open_entries
            if str(entry.get("slug") or "") and str(entry.get("event_date") or "")
        }
        lcb_event_key_set = set(lcb_event_best.keys())
        overlap_keys = shadow_event_key_set & lcb_event_key_set
        shadow_only_keys = shadow_event_key_set - lcb_event_key_set
        lcb_only_keys = lcb_event_key_set - shadow_event_key_set
        better_count = 0
        worse_count = 0
        equal_count = 0
        for entry in shadow_band_new_open_entries:
            key = (str(entry.get("slug") or ""), str(entry.get("event_date") or ""))
            if key not in lcb_event_best:
                continue
            shadow_lcb = to_float(entry.get("combo_lcb"))
            lcb_payload = lcb_event_best.get(key) if isinstance(lcb_event_best.get(key), dict) else {}
            lcb_lcb = _coalesce_metric((lcb_payload or {}).get("edge_lcb"))
            if shadow_lcb is None or lcb_lcb is None:
                continue
            if float(shadow_lcb) > float(lcb_lcb) + TIME_EDGE_Q_EPS:
                better_count += 1
            elif float(shadow_lcb) + TIME_EDGE_Q_EPS < float(lcb_lcb):
                worse_count += 1
            else:
                equal_count += 1

        def _mean_numeric(entries: List[Dict[str, Any]], key: str) -> Optional[float]:
            vals: List[float] = []
            for entry in entries:
                if not isinstance(entry, dict):
                    continue
                val = to_float(entry.get(key))
                if val is None or not math.isfinite(val):
                    continue
                vals.append(float(val))
            if not vals:
                return None
            return float(sum(vals) / len(vals))

        event_fact_ctx_by_date: Dict[Tuple[str, str], Dict[str, Any]] = {}
        for raw_key, ctx_item in event_fact_ctx.items():
            if not isinstance(raw_key, tuple) or len(raw_key) != 2:
                continue
            slug_key = str(raw_key[0] or "").strip()
            date_key = date_only(str(raw_key[1] or "").strip())
            if not slug_key or not date_key or not isinstance(ctx_item, dict):
                continue
            event_fact_ctx_by_date[(slug_key, date_key)] = ctx_item

        settlement_actual_by_event: Dict[Tuple[str, str], float] = {}
        settlement_event_keys = shadow_event_key_set | lcb_event_key_set
        if settlement_event_keys:
            try:
                with open_db_ro_fast(timeout_sec=0.25, busy_timeout_ms=200) as conn_settle:
                    for slug_key, date_key in settlement_event_keys:
                        if not slug_key or not date_key:
                            continue
                        actual_val = _settlement_actual_for_event(conn_settle, slug_key, date_key)
                        if actual_val is None or not math.isfinite(actual_val):
                            continue
                        settlement_actual_by_event[(slug_key, date_key)] = float(actual_val)
            except Exception:
                settlement_actual_by_event = {}

        settlement_label_by_event: Dict[Tuple[str, str], str] = {}

        def _event_settlement_label(event_key: Tuple[str, str]) -> Optional[str]:
            if event_key in settlement_label_by_event:
                label_cached = str(settlement_label_by_event.get(event_key) or "").strip()
                return label_cached or None
            ctx_item = event_fact_ctx_by_date.get(event_key) if isinstance(event_fact_ctx_by_date, dict) else None
            fact_obj = ctx_item.get("fact") if isinstance(ctx_item, dict) and isinstance(ctx_item.get("fact"), dict) else {}
            actual_val = _coalesce_metric(
                (fact_obj or {}).get("settlement_actual"),
                settlement_actual_by_event.get(event_key),
            )
            if actual_val is None or not math.isfinite(actual_val):
                settlement_label_by_event[event_key] = ""
                return None
            distribution = (
                fact_obj.get("distribution")
                if isinstance(fact_obj.get("distribution"), list)
                else (fact_obj.get("rows") if isinstance(fact_obj.get("rows"), list) else [])
            )
            rounding_rule = str(fact_obj.get("rounding_rule") or "").strip()
            market_var = str(fact_obj.get("market_var") or "").strip()
            label = ""
            if distribution:
                try:
                    label = str(
                        bucket_label_for_value(
                            distribution,
                            float(actual_val),
                            rounding_rule,
                            market_var,
                        )
                        or ""
                    ).strip()
                except Exception:
                    label = ""
            if not label:
                row_by_outcome = (
                    ctx_item.get("row_by_outcome")
                    if isinstance(ctx_item, dict) and isinstance(ctx_item.get("row_by_outcome"), dict)
                    else {}
                )
                for outcome_label in row_by_outcome.keys():
                    try:
                        inside = bucket_contains(
                            float(actual_val),
                            str(outcome_label or ""),
                            rounding_rule,
                            market_var,
                        )
                    except Exception:
                        inside = None
                    if inside is True:
                        label = str(outcome_label or "").strip()
                        break
            settlement_label_by_event[event_key] = str(label or "")
            return str(label or "").strip() or None

        def _aggregate_paper_roi(entries: List[Dict[str, Any]]) -> Dict[str, Any]:
            est_values: List[float] = []
            realized_values: List[float] = []
            est_cost_total = 0.0
            est_pnl_total = 0.0
            realized_cost_total = 0.0
            realized_pnl_total = 0.0
            for row in entries:
                if not isinstance(row, dict):
                    continue
                est_val = to_float(row.get("paper_roi_est"))
                if est_val is not None and math.isfinite(est_val):
                    est_values.append(float(est_val))
                cost_val = to_float(row.get("paper_cost"))
                est_pnl_val = to_float(row.get("paper_est_pnl"))
                if (
                    cost_val is not None
                    and math.isfinite(cost_val)
                    and cost_val > TIME_EDGE_Q_EPS
                    and est_pnl_val is not None
                    and math.isfinite(est_pnl_val)
                ):
                    est_cost_total += float(cost_val)
                    est_pnl_total += float(est_pnl_val)
                real_val = to_float(row.get("paper_roi_realized"))
                if real_val is not None and math.isfinite(real_val):
                    realized_values.append(float(real_val))
                real_pnl_val = to_float(row.get("paper_realized_pnl"))
                if (
                    cost_val is not None
                    and math.isfinite(cost_val)
                    and cost_val > TIME_EDGE_Q_EPS
                    and real_pnl_val is not None
                    and math.isfinite(real_pnl_val)
                ):
                    realized_cost_total += float(cost_val)
                    realized_pnl_total += float(real_pnl_val)
            est_count = len(est_values)
            realized_count = len(realized_values)
            return {
                "event_count": int(len(entries)),
                "est_event_count": int(est_count),
                "est_roi_mean": (
                    float(sum(est_values) / est_count)
                    if est_count > 0
                    else None
                ),
                "est_positive_ratio": (
                    float(sum(1 for v in est_values if v > 0) / est_count)
                    if est_count > 0
                    else None
                ),
                "realized_event_count": int(realized_count),
                "realized_roi_mean": (
                    float(sum(realized_values) / realized_count)
                    if realized_count > 0
                    else None
                ),
                "realized_positive_ratio": (
                    float(sum(1 for v in realized_values if v > 0) / realized_count)
                    if realized_count > 0
                    else None
                ),
                "est_cost_total": (
                    float(est_cost_total)
                    if est_cost_total > TIME_EDGE_Q_EPS
                    else None
                ),
                "est_pnl_total": (
                    float(est_pnl_total)
                    if est_cost_total > TIME_EDGE_Q_EPS
                    else None
                ),
                "est_roi_weighted": (
                    float(est_pnl_total / est_cost_total)
                    if est_cost_total > TIME_EDGE_Q_EPS
                    else None
                ),
                "realized_cost_total": (
                    float(realized_cost_total)
                    if realized_cost_total > TIME_EDGE_Q_EPS
                    else None
                ),
                "realized_pnl_total": (
                    float(realized_pnl_total)
                    if realized_cost_total > TIME_EDGE_Q_EPS
                    else None
                ),
                "realized_roi_weighted": (
                    float(realized_pnl_total / realized_cost_total)
                    if realized_cost_total > TIME_EDGE_Q_EPS
                    else None
                ),
            }

        for entry in shadow_band_new_open_entries:
            if not isinstance(entry, dict):
                continue
            slug_key = str(entry.get("slug") or "").strip()
            date_key = str(entry.get("event_date") or "").strip()
            if not slug_key or not date_key:
                continue
            event_key = (slug_key, date_key)
            ctx_item = event_fact_ctx_by_date.get(event_key)
            row_by_outcome = (
                ctx_item.get("row_by_outcome")
                if isinstance(ctx_item, dict) and isinstance(ctx_item.get("row_by_outcome"), dict)
                else {}
            )
            if not row_by_outcome:
                continue
            settlement_label = _event_settlement_label(event_key)
            total_cost = 0.0
            total_edge_lcb = 0.0
            total_realized_pnl = 0.0
            valid_leg_count = 0
            for leg in (entry.get("legs") if isinstance(entry.get("legs"), list) else []):
                if not isinstance(leg, dict):
                    continue
                outcome_label = str(leg.get("outcome") or "").strip()
                side_label = str(leg.get("side") or "").strip().upper()
                if not outcome_label or side_label not in {"YES", "NO"}:
                    continue
                row_ref = row_by_outcome.get(outcome_label)
                if not isinstance(row_ref, dict):
                    continue
                ask_val = to_float(
                    row_ref.get("best_ask")
                    if side_label == "YES"
                    else row_ref.get("best_ask_no")
                )
                leg_lcb = to_float(leg.get("lcb"))
                if (
                    ask_val is None
                    or not math.isfinite(ask_val)
                    or ask_val <= TIME_EDGE_Q_EPS
                    or leg_lcb is None
                    or not math.isfinite(leg_lcb)
                ):
                    continue
                weight = float(shadow_band_tail_no_weight) if side_label == "NO" else 1.0
                total_cost += float(ask_val) * float(weight)
                total_edge_lcb += float(leg_lcb) * float(weight)
                valid_leg_count += 1
                if settlement_label:
                    win = outcome_label == settlement_label
                    payout = 1.0 if ((side_label == "YES" and win) or (side_label == "NO" and (not win))) else 0.0
                    total_realized_pnl += (float(payout) - float(ask_val)) * float(weight)
            if total_cost <= TIME_EDGE_Q_EPS:
                continue
            entry["paper_cost"] = float(total_cost)
            entry["paper_est_pnl"] = float(total_edge_lcb)
            entry["paper_roi_est"] = float(total_edge_lcb / total_cost)
            entry["paper_leg_count"] = int(valid_leg_count)
            if settlement_label:
                entry["paper_realized_pnl"] = float(total_realized_pnl)
                entry["paper_roi_realized"] = float(total_realized_pnl / total_cost)
                entry["paper_settled"] = True
            else:
                entry["paper_settled"] = False

        lcb_event_entries: List[Dict[str, Any]] = []
        for event_key, payload in lcb_event_best.items():
            if not isinstance(payload, dict):
                continue
            ask_val = to_float(payload.get("ask"))
            lcb_val = to_float(payload.get("edge_lcb"))
            if (
                ask_val is None
                or not math.isfinite(ask_val)
                or ask_val <= TIME_EDGE_Q_EPS
                or lcb_val is None
                or not math.isfinite(lcb_val)
            ):
                continue
            entry = dict(payload)
            entry["slug"] = str(event_key[0] or "")
            entry["event_date"] = str(event_key[1] or "")
            entry["paper_cost"] = float(ask_val)
            entry["paper_est_pnl"] = float(lcb_val)
            entry["paper_roi_est"] = float(lcb_val / ask_val)
            settlement_label = _event_settlement_label(event_key)
            outcome_label = str(entry.get("outcome") or "").strip()
            side_label = str(entry.get("side") or "").strip().upper()
            if settlement_label and outcome_label and side_label in {"YES", "NO"}:
                win = outcome_label == settlement_label
                payout = 1.0 if ((side_label == "YES" and win) or (side_label == "NO" and (not win))) else 0.0
                entry["paper_realized_pnl"] = float(float(payout) - float(ask_val))
                entry["paper_roi_realized"] = float((float(payout) - float(ask_val)) / float(ask_val))
                entry["paper_settled"] = True
            else:
                entry["paper_settled"] = False
            lcb_event_entries.append(entry)

        lcb_event_lcb_mean = None
        if lcb_event_best:
            lcb_values: List[float] = []
            for payload in lcb_event_best.values():
                if not isinstance(payload, dict):
                    continue
                val = to_float(payload.get("edge_lcb"))
                if val is None or not math.isfinite(val):
                    continue
                lcb_values.append(float(val))
            if lcb_values:
                lcb_event_lcb_mean = float(sum(lcb_values) / len(lcb_values))
        shadow_paper_summary = _aggregate_paper_roi(shadow_band_new_open_entries)
        lcb_paper_summary = _aggregate_paper_roi(lcb_event_entries)
        shadow_realized_map: Dict[Tuple[str, str], Dict[str, float]] = {}
        for row in shadow_band_new_open_entries:
            if not isinstance(row, dict):
                continue
            key = (str(row.get("slug") or ""), str(row.get("event_date") or ""))
            if not key[0] or not key[1]:
                continue
            cost_val = to_float(row.get("paper_cost"))
            pnl_val = to_float(row.get("paper_realized_pnl"))
            if (
                cost_val is None
                or not math.isfinite(cost_val)
                or cost_val <= TIME_EDGE_Q_EPS
                or pnl_val is None
                or not math.isfinite(pnl_val)
            ):
                continue
            shadow_realized_map[key] = {
                "cost": float(cost_val),
                "pnl": float(pnl_val),
                "roi": float(pnl_val) / float(cost_val),
            }
        lcb_realized_map: Dict[Tuple[str, str], Dict[str, float]] = {}
        for row in lcb_event_entries:
            if not isinstance(row, dict):
                continue
            key = (str(row.get("slug") or ""), str(row.get("event_date") or ""))
            if not key[0] or not key[1]:
                continue
            cost_val = to_float(row.get("paper_cost"))
            pnl_val = to_float(row.get("paper_realized_pnl"))
            if (
                cost_val is None
                or not math.isfinite(cost_val)
                or cost_val <= TIME_EDGE_Q_EPS
                or pnl_val is None
                or not math.isfinite(pnl_val)
            ):
                continue
            lcb_realized_map[key] = {
                "cost": float(cost_val),
                "pnl": float(pnl_val),
                "roi": float(pnl_val) / float(cost_val),
            }

        paired_realized_keys = set(shadow_realized_map.keys()) & set(lcb_realized_map.keys())
        paired_shadow_better = 0
        paired_shadow_worse = 0
        paired_equal = 0
        paired_shadow_cost = 0.0
        paired_shadow_pnl = 0.0
        paired_lcb_cost = 0.0
        paired_lcb_pnl = 0.0
        for key in paired_realized_keys:
            shadow_row = shadow_realized_map.get(key) or {}
            lcb_row = lcb_realized_map.get(key) or {}
            shadow_roi = to_float(shadow_row.get("roi"))
            lcb_roi = to_float(lcb_row.get("roi"))
            if shadow_roi is not None and lcb_roi is not None:
                if float(shadow_roi) > float(lcb_roi) + TIME_EDGE_Q_EPS:
                    paired_shadow_better += 1
                elif float(shadow_roi) + TIME_EDGE_Q_EPS < float(lcb_roi):
                    paired_shadow_worse += 1
                else:
                    paired_equal += 1
            cost_shadow = to_float(shadow_row.get("cost"))
            pnl_shadow = to_float(shadow_row.get("pnl"))
            cost_lcb = to_float(lcb_row.get("cost"))
            pnl_lcb = to_float(lcb_row.get("pnl"))
            if cost_shadow is not None and math.isfinite(cost_shadow) and cost_shadow > TIME_EDGE_Q_EPS:
                paired_shadow_cost += float(cost_shadow)
            if pnl_shadow is not None and math.isfinite(pnl_shadow):
                paired_shadow_pnl += float(pnl_shadow)
            if cost_lcb is not None and math.isfinite(cost_lcb) and cost_lcb > TIME_EDGE_Q_EPS:
                paired_lcb_cost += float(cost_lcb)
            if pnl_lcb is not None and math.isfinite(pnl_lcb):
                paired_lcb_pnl += float(pnl_lcb)
        paired_realized_summary = {
            "paired_event_count": int(len(paired_realized_keys)),
            "shadow_better_count": int(paired_shadow_better),
            "shadow_worse_count": int(paired_shadow_worse),
            "equal_count": int(paired_equal),
            "shadow_cost_total": (
                float(paired_shadow_cost)
                if paired_shadow_cost > TIME_EDGE_Q_EPS
                else None
            ),
            "shadow_pnl_total": (
                float(paired_shadow_pnl)
                if paired_shadow_cost > TIME_EDGE_Q_EPS
                else None
            ),
            "shadow_roi_weighted": (
                float(paired_shadow_pnl / paired_shadow_cost)
                if paired_shadow_cost > TIME_EDGE_Q_EPS
                else None
            ),
            "lcb_cost_total": (
                float(paired_lcb_cost)
                if paired_lcb_cost > TIME_EDGE_Q_EPS
                else None
            ),
            "lcb_pnl_total": (
                float(paired_lcb_pnl)
                if paired_lcb_cost > TIME_EDGE_Q_EPS
                else None
            ),
            "lcb_roi_weighted": (
                float(paired_lcb_pnl / paired_lcb_cost)
                if paired_lcb_cost > TIME_EDGE_Q_EPS
                else None
            ),
            "delta_pnl_total": (
                float(paired_shadow_pnl - paired_lcb_pnl)
                if (paired_shadow_cost > TIME_EDGE_Q_EPS or paired_lcb_cost > TIME_EDGE_Q_EPS)
                else None
            ),
            "delta_roi_weighted": (
                float((paired_shadow_pnl / paired_shadow_cost) - (paired_lcb_pnl / paired_lcb_cost))
                if paired_shadow_cost > TIME_EDGE_Q_EPS and paired_lcb_cost > TIME_EDGE_Q_EPS
                else None
            ),
        }
        shadow_realized_count = int(shadow_paper_summary.get("realized_event_count") or 0)
        lcb_realized_count = int(lcb_paper_summary.get("realized_event_count") or 0)
        paired_realized_count = int(paired_realized_summary.get("paired_event_count") or 0)
        conclusion_metric_source = ""
        conclusion_metric_value: Optional[float] = None
        conclusion_verdict = "insufficient_sample"
        if (
            paired_realized_count >= shadow_band_min_paired_events_i
            and to_float(paired_realized_summary.get("delta_roi_weighted")) is not None
        ):
            conclusion_metric_source = "paired_realized_roi_weighted"
            conclusion_metric_value = float(
                to_float(paired_realized_summary.get("delta_roi_weighted")) or 0.0
            )
        elif (
            shadow_realized_count >= shadow_band_min_settled_events_i
            and lcb_realized_count >= shadow_band_min_settled_events_i
            and to_float((shadow_paper_summary or {}).get("realized_roi_weighted")) is not None
            and to_float((lcb_paper_summary or {}).get("realized_roi_weighted")) is not None
        ):
            conclusion_metric_source = "realized_roi_weighted"
            conclusion_metric_value = float(
                to_float(shadow_paper_summary.get("realized_roi_weighted"))
                - to_float(lcb_paper_summary.get("realized_roi_weighted"))
            )
