    "ssot_target_bucket",
    "target_bucket",
    "target_bucket_source",
    "target_bucket_source_semantics",
    "target_bucket_probability_field",
    "target_bucket_probability",
    "target_bucket_probability_pct",
    "posterior_highest_bucket_label",
    "posterior_highest_probability_pct",
