def _chengdu_intraday_summary_row_keeps_existing(key: str, existing: Any) -> bool:
    if existing is None or existing == "" or existing == [] or existing == {}:
        return False
    key_text = str(key or "")
    return key_text in _CHENGDU_INTRADAY_SUMMARY_ROW_KEEP_EXISTING_KEYS or any(
        key_text.startswith(prefix) for prefix in _CHENGDU_INTRADAY_SUMMARY_ROW_KEEP_EXISTING_PREFIXES
    )


def _chengdu_intraday_summary_row_keeps_ssot_posterior(key: str, existing: Any) -> bool:
    if existing is None or existing == "" or existing == [] or existing == {}:
        return False
    key_text = str(key or "")
    return any(
        key_text.startswith(prefix)
        for prefix in _CHENGDU_INTRADAY_SUMMARY_ROW_KEEP_SSOT_POSTERIOR_PREFIXES
    )


def _chengdu_intraday_summary_row_keeps_hard_source_constraint(
    row: Mapping[str, Any],
    key: str,
    existing: Any,
) -> bool:
    if existing is None or existing == "" or existing == [] or existing == {}:
        return False
    if not (
        _truthy(row.get("hard_source_posterior_override"))
        or _truthy(row.get("hard_source_posterior_override_applied"))
    ):
        return False
    key_text = str(key or "")
    return any(
        key_text.startswith(prefix)
        for prefix in _CHENGDU_INTRADAY_SUMMARY_ROW_KEEP_HARD_SOURCE_CONSTRAINT_PREFIXES
    )


def _merge_chengdu_intraday_summary_distribution_into_fact_item(
    item: Dict[str, Any],
    intraday_summary: Mapping[str, Any],
    *,
    event_date: str = "",
    fact_as_of: str = "",
    event_tz: str = "",
) -> bool:
    if not isinstance(item, dict) or not isinstance(intraday_summary, Mapping):
        return False
    summary_rows = intraday_summary.get("bucket_probabilities")
    if not isinstance(summary_rows, list):
        summary_rows = intraday_summary.get("distribution")
    if not isinstance(summary_rows, list):
        return False
    summary_by_label: Dict[str, Dict[str, Any]] = {}
    for raw in summary_rows:
        if not isinstance(raw, Mapping):
            continue
        label = _row_label(raw)
        if label:
            summary_by_label[label] = dict(raw)
    if not summary_by_label:
        return False

    observation_led = (
        intraday_summary.get("observation_led_likelihood")
        if isinstance(intraday_summary.get("observation_led_likelihood"), Mapping)
        else {}
    )
    selection = intraday_summary.get("target_bucket_selection")
    observation_led_bayes = (
        selection.get("observation_led_bayes")
        if isinstance(selection, Mapping) and isinstance(selection.get("observation_led_bayes"), Mapping)
        else {}
    )
    observation_led_materialization = bool(
        isinstance(observation_led, Mapping)
        and observation_led.get("applied") is True
    ) or bool(
        isinstance(observation_led_bayes, Mapping)
        and observation_led_bayes.get("available") is True
    )
    block_reason = ""
    if observation_led_materialization:
        if not _intraday_summary_can_materialize_target_fields(item, intraday_summary):
            block_reason = "posterior_ssot_fact_missing_for_intraday_observation_led_materialization"
        else:
            block_reason = _d0_observed_max_not_final_materialization_block_reason(
                item,
                event_date=event_date,
                fact_as_of=fact_as_of,
                event_tz=event_tz,
                early_window_only=True,
            )
    if block_reason:
        _mark_intraday_summary_diagnostic_only(item, block_reason, intraday_summary)
        return False

    changed = False
    preserve_ssot_posterior = _payload_has_available_posterior_ssot_target(item) or _preserve_event_fact_distribution_posterior(item)

    def merge_rows(rows_obj: Any) -> None:
        nonlocal changed
        if not isinstance(rows_obj, list):
            return
        for raw in rows_obj:
            if not isinstance(raw, dict):
                continue
            label = _row_label(raw)
            summary_row = summary_by_label.get(label)
            if not summary_row:
                continue
            for key, value in summary_row.items():
                if key in {"label", "bucket"} and key not in raw:
                    continue
                if value in (None, "", [], {}):
                    continue
                if _chengdu_intraday_summary_row_keeps_existing(str(key), raw.get(key)):
                    continue
                if _chengdu_intraday_summary_row_keeps_hard_source_constraint(raw, str(key), raw.get(key)):
                    continue
                if preserve_ssot_posterior and _chengdu_intraday_summary_row_keeps_ssot_posterior(str(key), raw.get(key)):
                    continue
                if raw.get(key) != value:
                    raw[key] = value
                    changed = True

    merge_rows(item.get("distribution"))
    merge_rows(item.get("rows"))
    if not changed:
        return False

    if isinstance(intraday_summary.get("observation_led_likelihood"), Mapping):
        item["observation_led_likelihood"] = dict(intraday_summary.get("observation_led_likelihood") or {})
        item["observation_led_likelihood_applied"] = bool(
            item["observation_led_likelihood"].get("applied")
        )
    provenance = dict(item.get("fact_provenance") or {})
    provenance["observation_led_likelihood"] = {
        "applied": bool(item.get("observation_led_likelihood_applied")),
        "source": "chengdu_intraday_summary.bucket_probabilities",
        "target_bucket_before": (
            item.get("observation_led_likelihood") or {}
        ).get("target_bucket_before") if isinstance(item.get("observation_led_likelihood"), Mapping) else None,
        "target_bucket_after": (
            item.get("observation_led_likelihood") or {}
        ).get("target_bucket_after") if isinstance(item.get("observation_led_likelihood"), Mapping) else None,
        "posterior_materialized": True,
    }
    item["fact_provenance"] = provenance
    item["observation_led_likelihood_posterior_materialized"] = True
    return True


def _attach_chengdu_intraday_summary_fields_for_fact_write(
    item: Dict[str, Any],
    *,
    slug: str,
    event_date: str,
    fact_as_of: str,
    snapshot_id: Any = 0,
) -> None:
    if not _is_chengdu_zuuu_fact_payload(slug, item):
        return
    preserve_fact_write_distribution = bool(
        item.get("hard_source_posterior_override_applied")
        or isinstance(item.get("hard_source_posterior_override"), Mapping)
        or item.get("observation_path_likelihood_posterior_materialized")
        or item.get("temperature_momentum_likelihood_applied")
        or _preserve_event_fact_distribution_posterior(item)
    )
    had_distribution = "distribution" in item
    had_rows = "rows" in item
    preserved_distribution = (
        copy.deepcopy(item.get("distribution"))
        if preserve_fact_write_distribution and isinstance(item.get("distribution"), list)
        else None
    )
    preserved_rows = (
        copy.deepcopy(item.get("rows"))
        if preserve_fact_write_distribution and isinstance(item.get("rows"), list)
        else None
    )
    try:
        summary = build_chengdu_intraday_summary_from_payload(
            item,
            slug=slug,
            event_date=event_date,
            created_at=fact_as_of,
            snapshot_id=snapshot_id,
            snapshot_source="event_fact_history.write",
        )
    except Exception as exc:
        provenance = dict(item.get("fact_provenance") or {})
        provenance["chengdu_intraday_summary_fact_write_error"] = str(exc)[:300]
        item["fact_provenance"] = provenance
        return
    if not isinstance(summary, Mapping) or not summary.get("ok"):
        return
    merged_distribution = _merge_chengdu_intraday_summary_distribution_into_fact_item(
        item,
        summary,
        event_date=event_date,
        fact_as_of=fact_as_of,
        event_tz=str(item.get("event_tz") or item.get("tz") or "Asia/Shanghai"),
    )
    compact = _compact_chengdu_intraday_summary_for_ui_snapshot(summary) or dict(summary)
    _apply_chengdu_intraday_summary_to_snapshot_out(
        item,
        compact,
        force_target_fields=True,
        event_date=event_date,
        fact_as_of=fact_as_of,
        event_tz=str(item.get("event_tz") or item.get("tz") or "Asia/Shanghai"),
    )
    if preserve_fact_write_distribution:
        if preserved_distribution is not None:
            item["distribution"] = preserved_distribution
        elif not had_distribution:
            item.pop("distribution", None)
        if preserved_rows is not None:
            item["rows"] = preserved_rows
        elif not had_rows:
            item.pop("rows", None)
        merged_distribution = False
        _align_snapshot_posterior_derived_fields(item)
    if merged_distribution:
        _normalize_fact_distribution_posterior_ssot_fields(
            item,
            item.get("distribution"),
            source="event_fact_history.write.observation_led_likelihood",
        )
        if isinstance(item.get("rows"), list):
            _normalize_fact_distribution_posterior_ssot_fields(
                item,
                item.get("rows"),
                source="event_fact_history.write.observation_led_likelihood.rows",
            )
        _align_snapshot_posterior_derived_fields(item)


def _upsert_event_fact_summary_cache(
    conn: sqlite3.Connection,
    *,
    fact_id: int,
    run_date: str,
    slug: str,
    event_date: str,
    fact_as_of: str,
    item: Mapping[str, Any],
) -> bool:
    if int(fact_id or 0) <= 0 or not isinstance(item, Mapping):
        return False
    item_for_summary = dict(item)
    _attach_chengdu_intraday_summary_fields_for_fact_write(
        item_for_summary,
        slug=slug,
        event_date=event_date,
        fact_as_of=fact_as_of,
        snapshot_id=fact_id,
    )
    _attach_model_raw_top_history_for_ui_snapshot(conn, item_for_summary)
    _attach_model_member_cache_snapshot_for_ui_snapshot(conn, item_for_summary)
    _attach_model_bucket_rule_comparison_for_ui_snapshot(conn, item_for_summary)
    summary = _slim_fact_payload_for_ui_snapshot_summary(
        item_for_summary,
        include_physical_detail=UI_SNAPSHOT_SUMMARY_PHYSICAL_DETAIL,
    )
    if not isinstance(summary, dict):
        return False
    summary = dict(summary)
    existing_summary = summary.get("chengdu_intraday_summary")
    compact_intraday = _compact_chengdu_intraday_summary_for_ui_snapshot(existing_summary)
    if compact_intraday:
        summary["chengdu_intraday_summary"] = compact_intraday
        _apply_chengdu_intraday_summary_to_snapshot_out(
            summary,
            compact_intraday,
            force_target_fields=True,
            event_date=event_date,
            fact_as_of=fact_as_of,
            event_tz=str(item.get("event_tz") or item.get("tz") or "Asia/Shanghai"),
        )
    elif "chengdu_intraday_summary" in summary:
        summary.pop("chengdu_intraday_summary", None)
    summary.setdefault("slug", slug)
    summary.setdefault("event_date", _normalize_date_key(event_date))
    summary.setdefault("run_date", _normalize_date_key(run_date))
    summary.setdefault("fact_as_of", fact_as_of)
    summary["summary_cache_source"] = "event_fact_summary_cache"
    summary["summary_cache_version"] = EVENT_FACT_SUMMARY_CACHE_VERSION
    plan = build_weather_fact_summary_cache_repair_plan(
        fact_id=int(fact_id),
        slug=slug,
        event_date=_normalize_date_key(event_date),
        run_date=_normalize_date_key(run_date),
        fact_as_of=fact_as_of,
        payload=summary,
        write_reason="ui_event_fact_summary_cache",
        enable_apply_contract=True,
    )
    result = apply_weather_fact_summary_cache_repair_plan(
        conn,
        plan,
        allow_apply=True,
        commit=False,
        created_at=now_text(),
    )
    return bool(result.get("summary_cache_written"))


def _fact_fast_trade_write_enabled(item: Mapping[str, Any]) -> bool:
    if not isinstance(item, Mapping):
        return False
    if item.get("awc_hard_observation_fast_trade_write"):
        return True
    if item.get("posterior_target_direct_fast_trade_write"):
        return True
    return False


