def _compact_ui_contract_value_for_fast_trade(value: Any, *, key: str = "", depth: int = 0) -> Any:
    if value in (None, ""):
        return None
    if isinstance(value, bool):
        return bool(value)
    num = to_float(value)
    if num is not None and math.isfinite(float(num)) and not isinstance(value, str):
        return float(num)
    key_text = str(key or "").strip().lower()
    allowed_text_key = (
        key_text in {"title", "summary", "detail", "text", "source", "role", "status", "state", "reason"}
        or key_text.endswith(
            (
                "_at",
                "_utc",
                "_source",
                "_status",
                "_state",
                "_reason",
                "_label",
                "_bucket",
                "_field",
                "_semantics",
                "_role",
            )
        )
    )
    if isinstance(value, str):
        text = _target_realization_clean_path_text(value)
        return text[:240] if allowed_text_key and text else None
    if depth >= 4:
        return None
    if isinstance(value, Mapping):
        out: Dict[str, Any] = {}
        for raw_key, raw_value in value.items():
            child_key = str(raw_key or "").strip()
            if not child_key:
                continue
            child_value = _compact_ui_contract_value_for_fast_trade(
                raw_value,
                key=child_key,
                depth=depth + 1,
            )
            if child_value not in (None, "", [], {}):
                out[child_key] = child_value
        return out or None
    if isinstance(value, Sequence) and not isinstance(value, (str, bytes, bytearray)):
        out_list: List[Any] = []
        for item in list(value)[:8]:
            child_value = _compact_ui_contract_value_for_fast_trade(
                item,
                key=key,
                depth=depth + 1,
            )
            if child_value not in (None, "", [], {}):
                out_list.append(child_value)
        return out_list or None
    return None


def _compact_fast_trade_ui_snapshot_contract_fields(item: MutableMapping[str, Any]) -> None:
    if not isinstance(item, MutableMapping):
        return
    compact_intraday = _compact_chengdu_intraday_summary_for_ui_snapshot(
        item.get("chengdu_intraday_summary")
    )
    if compact_intraday:
        item["chengdu_intraday_summary"] = compact_intraday
    for key in (
        "target_bucket_outlook",
        "temperature_path_distribution",
        "temperature_realization_reliability",
        "target_switch_context",
    ):
        value = item.get(key)
        if isinstance(value, Mapping):
            item[key] = _target_realization_clean_nested_path_texts(value)
    for key in _FAST_TRADE_UI_SNAPSHOT_KEEP_TOP_LEVEL_KEYS:
        compact_value = _compact_ui_contract_value_for_fast_trade(item.get(key), key=key)
        if compact_value not in (None, "", [], {}):
            item[key] = compact_value
        else:
            item.pop(key, None)


def _compact_physical_components_for_fast_trade(value: Any, *, max_components: int = 8) -> Dict[str, float]:
    if not isinstance(value, Mapping):
        return {}
    out: Dict[str, float] = {}
    for key, raw_value in value.items():
        if len(out) >= max_components:
            break
        name = str(key or "").strip()
        if not name:
            continue
        num = to_float(raw_value)
        if num is None and isinstance(raw_value, Mapping):
            num = to_float(raw_value.get("log_likelihood"))
        if num is None:
            continue
        out[name] = float(num)
    return out


def _compact_physical_group_components_for_fast_trade(
    value: Any,
    *,
    max_components: int = 5,
) -> Dict[str, Dict[str, Any]]:
    if not isinstance(value, Mapping):
        return {}
    out: Dict[str, Dict[str, Any]] = {}
    for key, raw_value in value.items():
        if len(out) >= max_components:
            break
        name = str(key or "").strip()
        if not name or not isinstance(raw_value, Mapping):
            continue
        entry: Dict[str, Any] = {}
        for num_key in ("factor", "weight", "log_likelihood"):
            num = to_float(raw_value.get(num_key))
            if num is not None:
                entry[num_key] = float(num)
        if entry:
            out[name] = entry
    return out


def _compact_physical_component_groups_for_fast_trade(
    value: Any,
    *,
    max_groups: int = 8,
) -> Dict[str, Dict[str, Any]]:
    if not isinstance(value, Mapping):
        return {}
    out: Dict[str, Dict[str, Any]] = {}
    for key, raw_group in value.items():
        if len(out) >= max_groups:
            break
        group_key = str(key or "").strip()
        if not group_key or not isinstance(raw_group, Mapping):
            continue
        group: Dict[str, Any] = {}
        if "available" in raw_group:
            group["available"] = bool(raw_group.get("available"))
        for text_key in ("na_reason", f"{group_key}_na_reason", "evidence_state"):
            text = str(raw_group.get(text_key) or "").strip()
            if text:
                group[text_key] = text[:160]
        for num_key in ("weight", "log_likelihood"):
            num = to_float(raw_group.get(num_key))
            if num is not None:
                group[num_key] = float(num)
        source_profile = raw_group.get("source_profile")
        if isinstance(source_profile, Mapping):
            compact_source: Dict[str, Any] = {}
            for text_key in ("evidence_state", "source_class", "source_field", "source", "na_reason"):
                text = str(source_profile.get(text_key) or "").strip()
                if text:
                    compact_source[text_key] = text[:160]
            for bool_key in ("precip_present", "no_precip_confirmed", "is_real_radar_or_metar", "is_proxy_only"):
                if bool_key in source_profile:
                    compact_source[bool_key] = bool(source_profile.get(bool_key))
            rate = to_float(source_profile.get("rate_mm_per_h"))
            if rate is not None:
                compact_source["rate_mm_per_h"] = float(rate)
            if compact_source:
                group["source_profile"] = compact_source
        components = _compact_physical_group_components_for_fast_trade(raw_group.get("components"))
        if components:
            group["components"] = components
        if group:
            out[group_key] = group
    return out


def _state_evidence_trace_from_component_groups_for_ui(
    value: Any,
    *,
    source: str = "metar_strong_likelihood.component_groups",
) -> Dict[str, Any]:
    groups = _compact_physical_component_groups_for_fast_trade(value)
    if not groups:
        return {}
    return {
        "schema": "metar_strong_state_evidence_trace_v1",
        "source": str(source or "metar_strong_likelihood.component_groups"),
        "role": "state_evidence_trace",
        "replaces": "q_bayes_physical_likelihood_component_groups",
        "dedupe_boundary": "METAR physical evidence is consumed inside L_metar_strong, not as an independent probability channel",
        "group_count": len(groups),
        "groups": groups,
    }


def _compact_state_evidence_trace_for_ui(
    value: Any,
    *,
    fallback_component_groups: Any = None,
    source: str = "metar_strong_likelihood.component_groups",
) -> Dict[str, Any]:
    groups: Dict[str, Any] = {}
    trace_source = str(source or "metar_strong_likelihood.component_groups")
    dedupe_boundary = (
        "METAR physical evidence is consumed inside L_metar_strong, not as an independent probability channel"
    )
    if isinstance(value, Mapping):
        raw_groups = value.get("groups")
        groups = _compact_physical_component_groups_for_fast_trade(raw_groups)
        trace_source = str(value.get("source") or trace_source)
        dedupe_boundary = str(value.get("dedupe_boundary") or dedupe_boundary)
    if not groups:
        groups = _compact_physical_component_groups_for_fast_trade(fallback_component_groups)
    if not groups:
        return {}
    return {
        "schema": "metar_strong_state_evidence_trace_v1",
        "source": trace_source,
        "role": "state_evidence_trace",
        "replaces": "q_bayes_physical_likelihood_component_groups",
        "dedupe_boundary": dedupe_boundary,
        "group_count": len(groups),
        "groups": groups,
    }


def _compact_physical_likelihood_row_for_fast_trade(row: MutableMapping[str, Any]) -> None:
    groups = _compact_physical_component_groups_for_fast_trade(
        row.get("q_bayes_physical_likelihood_component_groups")
    )
    components = _compact_physical_components_for_fast_trade(
        row.get("q_bayes_physical_likelihood_components")
    )
    trace = _compact_state_evidence_trace_for_ui(
        row.get("state_evidence_trace"),
        fallback_component_groups=groups,
    )
    if trace:
        row["state_evidence_trace"] = trace
    else:
        row.pop("state_evidence_trace", None)
    if groups:
        row["q_bayes_physical_likelihood_component_groups"] = groups
    else:
        row.pop("q_bayes_physical_likelihood_component_groups", None)
    if components:
        row["q_bayes_physical_likelihood_components"] = components
    else:
        row.pop("q_bayes_physical_likelihood_components", None)


def _attach_physical_likelihood_audit_fields_from_features(
    rows_obj: Any,
    features: Mapping[str, Any],
    *,
    fact_as_of: str = "",
    source: str = "event_fact_history.write",
) -> bool:
    if not isinstance(rows_obj, list) or not isinstance(features, Mapping) or not features:
        return False
    labels = [
        _row_label(row)
        for row in rows_obj
        if isinstance(row, Mapping) and _row_label(row)
    ]
    if len(labels) != len(rows_obj) or not labels:
        return False
    hours_to_event = to_float(features.get("hours_to_peak_window"))
    base_probs: List[float] = []
    for row in rows_obj:
        if not isinstance(row, Mapping):
            return False
        prob = to_float(
            row.get("q_temperature_bucket_posterior")
            if row.get("q_temperature_bucket_posterior") is not None
            else row.get("q_bayes_posterior")
        )
        if prob is None:
            base_probs = []
            break
        base_probs.append(max(0.0, min(1.0, float(prob))))
    try:
        meta = compute_weather_likelihood_vector(
            labels,
            features,
            hours_to_event=hours_to_event,
            base_probs=base_probs or None,
        )
    except Exception:
        return False
    physical_rows = meta.get("rows") if isinstance(meta, Mapping) else None
    probs = meta.get("likelihood_probs") if isinstance(meta, Mapping) else None
    if not isinstance(physical_rows, list) or len(physical_rows) != len(rows_obj):
        return False
    changed = False
    for idx, raw_row in enumerate(rows_obj):
        if not isinstance(raw_row, dict):
            continue
        physical_row = physical_rows[idx] if idx < len(physical_rows) else None
        if not isinstance(physical_row, Mapping):
            continue
        groups = _compact_physical_component_groups_for_fast_trade(
            physical_row.get("component_groups")
        )
        components = _compact_physical_components_for_fast_trade(
            physical_row.get("components")
        )
        trace = _compact_state_evidence_trace_for_ui(
            physical_row.get("state_evidence_trace"),
            fallback_component_groups=groups,
        )
        if trace and not isinstance(raw_row.get("state_evidence_trace"), Mapping):
            raw_row["state_evidence_trace"] = trace
            changed = True
        if groups and not isinstance(raw_row.get("q_bayes_physical_likelihood_component_groups"), Mapping):
            raw_row["q_bayes_physical_likelihood_component_groups"] = groups
            changed = True
        if components and not isinstance(raw_row.get("q_bayes_physical_likelihood_components"), Mapping):
            raw_row["q_bayes_physical_likelihood_components"] = components
            changed = True
        if raw_row.get("q_bayes_physical_likelihood_hard_zero") is None and physical_row.get("hard_zero") is not None:
            raw_row["q_bayes_physical_likelihood_hard_zero"] = bool(physical_row.get("hard_zero"))
            changed = True
        hard_reasons = physical_row.get("hard_reasons")
        if (
            isinstance(hard_reasons, list)
            and hard_reasons
            and not isinstance(raw_row.get("q_bayes_physical_likelihood_hard_reasons"), list)
        ):
            raw_row["q_bayes_physical_likelihood_hard_reasons"] = [
                str(reason) for reason in hard_reasons if str(reason).strip()
            ]
            changed = True
        if raw_row.get("q_bayes_physical_likelihood_prob") is None and isinstance(probs, list) and idx < len(probs):
            prob = to_float(probs[idx])
            if prob is not None:
                raw_row["q_bayes_physical_likelihood_prob"] = float(prob)
                raw_row["q_bayes_physical_likelihood_observed_prob"] = float(prob)
                changed = True
        if not raw_row.get("q_bayes_physical_likelihood_source"):
            raw_row["q_bayes_physical_likelihood_source"] = str(
                meta.get("source") or "weather_physical_likelihood"
            )
            changed = True
        if fact_as_of and not raw_row.get("weather_likelihood_refreshed_at"):
            raw_row["weather_likelihood_refreshed_at"] = fact_as_of
            changed = True
    if changed:
        for raw_row in rows_obj:
            if isinstance(raw_row, dict):
                raw_row["q_bayes_physical_likelihood_audit_source"] = source
    return changed


