def _prob01_for_fast_trade_fact(value: Any) -> Optional[float]:
    prob = to_float(value)
    if prob is None:
        return None
    if float(prob) > 1.0 and float(prob) <= 100.0:
        prob = float(prob) / 100.0
    return max(0.0, min(1.0, float(prob)))


def _top_target_from_fact_rows_for_fast_trade(item: Mapping[str, Any]) -> Tuple[str, Optional[float]]:
    rows = item.get("distribution")
    if not isinstance(rows, list):
        rows = item.get("rows")
    best_label = ""
    best_prob: Optional[float] = None
    if not isinstance(rows, list):
        return best_label, best_prob
    for raw_row in rows:
        if not isinstance(raw_row, Mapping):
            continue
        label = str(raw_row.get("outcome") or raw_row.get("label") or "").strip()
        if not label:
            continue
        prob = _prob01_for_fast_trade_fact(
            raw_row.get("q_temperature_bucket_posterior")
            if raw_row.get("q_temperature_bucket_posterior") is not None
            else raw_row.get("q_bayes_posterior")
            if raw_row.get("q_bayes_posterior") is not None
            else raw_row.get("q_contract_payout_posterior")
        )
        if prob is None:
            prob = _prob01_for_fast_trade_fact(raw_row.get("q_bayes_posterior_pct"))
        if prob is None:
            continue
        if best_prob is None or float(prob) > float(best_prob):
            best_label = label
            best_prob = float(prob)
    return best_label, best_prob


def _top_target_from_ctp_for_fast_trade(item: Mapping[str, Any]) -> Tuple[str, Optional[float]]:
    posterior = item.get("posterior_temperature_distribution") if isinstance(item, Mapping) else None
    if not isinstance(posterior, Mapping):
        return "", None
    bucket_probs = posterior.get("bucket_probabilities")
    best_label = ""
    best_prob: Optional[float] = None
    if isinstance(bucket_probs, Mapping):
        iterator = bucket_probs.items()
    elif isinstance(bucket_probs, list):
        iterator = (
            (
                str(entry.get("outcome") or entry.get("label") or entry.get("bucket") or "").strip(),
                entry.get("probability") if entry.get("probability") is not None else entry.get("prob"),
            )
            for entry in bucket_probs
            if isinstance(entry, Mapping)
        )
    else:
        return "", None
    for label_raw, prob_raw in iterator:
        label = str(label_raw or "").strip()
        prob = _prob01_for_fast_trade_fact(prob_raw)
        if not label or prob is None:
            continue
        if best_prob is None or float(prob) > float(best_prob):
            best_label = label
            best_prob = float(prob)
    return best_label, best_prob


def _compact_target_selection_for_fast_trade_fact(item: MutableMapping[str, Any]) -> None:
    if not isinstance(item, MutableMapping):
        return
    canonical = _canonical_target_from_fact_payload(item)
    best_label = str(canonical.get("label") or "").strip() if isinstance(canonical, Mapping) else ""
    best_prob = _prob01_for_fast_trade_fact(canonical.get("prob")) if isinstance(canonical, Mapping) else None
    probability_field = str(
        canonical.get("probability_field") or "posterior_ssot_fact.target_probability"
    ) if isinstance(canonical, Mapping) else "posterior_ssot_fact.target_probability"
    if not best_label or best_prob is None:
        item["target_bucket_compaction_skipped_reason"] = "posterior_ssot_fact_missing"
        return
    selection = {
        "target_bucket": best_label,
        "target_probability": float(best_prob),
        "target_probability_pct": float(best_prob) * 100.0,
        "target_posterior": float(best_prob),
        "target_bucket_probability": float(best_prob),
        "target_bucket_probability_pct": float(best_prob) * 100.0,
        "target_probability_field": probability_field,
        "target_bucket_source": "posterior_ssot_fact.top_bucket",
        "target_bucket_source_semantics": "bayes_posterior_ssot_fact_v1",
        "ssot_source": "posterior_ssot_fact",
        "target_bucket_selection_source": "posterior_ssot_fact.top_bucket",
        "source": "posterior_ssot_fact",
        "fast_trade_compacted": True,
        "selection_runtime_recomputed": False,
    }
    item["posterior_target_bucket_selection"] = dict(selection)
    item["target_bucket_selection"] = dict(selection)
    item["target_bucket"] = best_label
    item["ssot_target_bucket"] = best_label
    item["target_bucket_probability_pct"] = float(best_prob) * 100.0
    item["target_bucket_probability_field"] = probability_field


