def strategy_stats_defaults() -> Dict[str, Dict[str, Any]]:
    lcb_global_enabled = _env_bool("PM_LCB_GLOBAL_ENABLED", False)
    if lcb_global_enabled:
        return {
            "path_probability_follow": _empty_strategy_entry(),
            "consensus_top_regional": _empty_strategy_entry(),
            "repricing_bucket": _empty_strategy_entry(),
            "exploration_canary": _empty_strategy_entry(),
                "mirror_follow": _empty_strategy_entry(),
            "unknown": _empty_strategy_entry(),
        }
    return {
        "main": _empty_strategy_entry(),
        "follow_copy": _empty_strategy_entry(),
        "yes_top": _empty_strategy_entry(),
        "hard_bound_no": _empty_strategy_entry(),
        "adj_pair": _empty_strategy_entry(),
        "mirror_follow": _empty_strategy_entry(),
        "unknown": _empty_strategy_entry(),
    }


def compute_strategy_stats_v2(conn: sqlite3.Connection, days: int, run_date: str = "") -> Dict[str, Dict[str, Any]]:
    def _row_text(row_obj: Any, key: str) -> str:
        if row_obj is None:
            return ""
        if isinstance(row_obj, dict):
            value = row_obj.get(key)
            return str(value or "")
        try:
            value = row_obj[key]
        except Exception:
            value = None
        return str(value or "")

    def _row_float(row_obj: Any, key: str) -> Optional[float]:
        if row_obj is None:
            return None
        if isinstance(row_obj, dict):
            return to_float(row_obj.get(key))
        try:
            return to_float(row_obj[key])
        except Exception:
            return None

    run_date_norm = str(run_date or "").strip()
    run_date_day = date_from_any(run_date_norm) if run_date_norm else None
    if run_date_day:
        start_date = run_date_day
        end_date = run_date_day
    else:
        # Strategy execution stats should reflect real executed orders/fills in window,
        # not only already-settled events.
        start_date, end_date = resolve_stats_range(conn, days, require_settlement=False)
    start_text = start_date.isoformat()
    end_text = end_date.isoformat()
    stats: Dict[str, Dict[str, Any]] = strategy_stats_defaults()
    auto_orders = query_auto_orders(conn, apply_cutoff=not bool(run_date_day))

    def _order_key_from_fields(
        slug: str,
        event_date: str,
        outcome: str,
        side: str,
    ) -> Tuple[str, str, str, str]:
        return (
            str(slug or "").strip(),
            str(event_date or "").strip(),
            str(outcome or "").strip(),
            str(side or "").strip().upper(),
        )

    def _order_key(row_obj: Any) -> Tuple[str, str, str, str]:
        return _order_key_from_fields(
            _row_text(row_obj, "slug"),
            _row_text(row_obj, "event_date"),
            _row_text(row_obj, "outcome"),
            _row_text(row_obj, "side"),
        )

    entry_strategy_timeline: Dict[Tuple[str, str, str, str], List[Tuple[Optional[float], str, str]]] = {}
    for order in auto_orders.values():
        action_norm = _row_text(order, "action").strip().lower()
        if action_norm != "entry":
            continue
        strategy = _normalize_strategy_key(_row_text(order, "strategy"), fallback="main")
        key = _order_key(order)
        if not all(key):
            continue
        created_text = _row_text(order, "created_at").strip()
        created_dt = parse_any_ts(created_text) if created_text else None
        created_ts = created_dt.timestamp() if created_dt is not None else None
        entry_strategy_timeline.setdefault(key, []).append((created_ts, created_text, strategy))
    for key in list(entry_strategy_timeline.keys()):
        timeline = entry_strategy_timeline.get(key) or []
        timeline.sort(key=lambda item: (item[0] if item[0] is not None else -10**18, item[1]))
        entry_strategy_timeline[key] = timeline

    def _resolve_strategy_from_timeline(
        key: Tuple[str, str, str, str],
        created_at_text: str,
    ) -> str:
        timeline = entry_strategy_timeline.get(key) or []
        if not timeline:
            return ""
        created_dt = parse_any_ts(created_at_text) if created_at_text else None
        created_ts = created_dt.timestamp() if created_dt is not None else None
        if created_ts is None:
            return str(timeline[-1][2] or "")
        candidate = ""
        for ts_val, _ts_text, strategy in timeline:
            if ts_val is None:
                candidate = str(strategy or "")
                continue
            if ts_val <= created_ts:
                candidate = str(strategy or "")
                continue
            break
        return candidate or str(timeline[-1][2] or "")

    def _resolve_order_strategy(row_obj: Any) -> str:
        action_norm = _row_text(row_obj, "action").strip().lower()
        strategy_raw = _row_text(row_obj, "strategy").strip().lower()
        key = _order_key(row_obj)
        created_text = _row_text(row_obj, "created_at").strip()
        if action_norm == "entry":
            if strategy_raw and strategy_raw != "exit":
                return _normalize_strategy_key(strategy_raw, fallback="main")
            if strategy_raw == "exit":
                return _normalize_strategy_key(
                    _resolve_strategy_from_timeline(key, created_text),
                    fallback="main",
                )
            return _normalize_strategy_key("", fallback="main")
        if action_norm == "exit":
            if strategy_raw and strategy_raw != "exit":
                return _normalize_strategy_key(strategy_raw, fallback="main")
            return _normalize_strategy_key(
                _resolve_strategy_from_timeline(key, created_text),
                fallback="unknown",
            )
        return _normalize_strategy_key(strategy_raw, fallback="main")

    price_acc: Dict[Tuple[str, str], Dict[str, float]] = {}

    def _add_price_sample(strategy: str, bucket: str, price: Optional[float], size: Optional[float]) -> None:
        if price is None or size is None:
            return
        if not math.isfinite(price) or not math.isfinite(size) or size <= 0:
            return
        key = (str(strategy or ""), str(bucket or ""))
        acc = price_acc.setdefault(key, {"count": 0.0, "size": 0.0, "notional": 0.0})
        acc["count"] = float(acc.get("count") or 0.0) + 1.0
        acc["size"] = float(acc.get("size") or 0.0) + float(size)
        acc["notional"] = float(acc.get("notional") or 0.0) + float(price) * float(size)

    def _price_stat(strategy: str, bucket: str, field: str) -> float:
        acc = price_acc.get((str(strategy or ""), str(bucket or ""))) or {}
        val = to_float(acc.get(field))
        if val is None or not math.isfinite(val):
            return 0.0
        return float(val)

    def _weighted_avg_price(strategy: str, bucket: str) -> Optional[float]:
        size_val = _price_stat(strategy, bucket, "size")
        if size_val <= TIME_EDGE_Q_EPS:
            return None
        return _price_stat(strategy, bucket, "notional") / size_val

    for order in auto_orders.values():
        action_norm = _row_text(order, "action").strip().lower()
        if action_norm not in {"entry", "exit"}:
            continue
        order_date = date_from_any(_row_text(order, "event_date"))
        if not order_date or order_date < start_date or order_date > end_date:
            continue
        strategy = _resolve_order_strategy(order)
        if not strategy:
            continue
        if strategy not in stats:
            stats[strategy] = _empty_strategy_entry()
        side_norm = _row_text(order, "side").strip().upper()
        stats[strategy]["order_count"] += 1
        if action_norm == "entry":
            stats[strategy]["entry_order_count"] += 1
            if side_norm == "YES":
                stats[strategy]["entry_order_yes_count"] += 1
            elif side_norm == "NO":
                stats[strategy]["entry_order_no_count"] += 1
        elif action_norm == "exit":
            stats[strategy]["exit_order_count"] += 1
            if side_norm == "YES":
                stats[strategy]["exit_order_yes_count"] += 1
            elif side_norm == "NO":
                stats[strategy]["exit_order_no_count"] += 1
        price_val = _row_float(order, "price")
        size_val = _row_float(order, "size")
        if action_norm == "entry":
            _add_price_sample(strategy, "entry_order_all", price_val, size_val)
            if side_norm == "YES":
                _add_price_sample(strategy, "entry_order_yes", price_val, size_val)
            elif side_norm == "NO":
                _add_price_sample(strategy, "entry_order_no", price_val, size_val)
        elif action_norm == "exit":
            _add_price_sample(strategy, "exit_order_all", price_val, size_val)
            if side_norm == "YES":
                _add_price_sample(strategy, "exit_order_yes", price_val, size_val)
            elif side_norm == "NO":
                _add_price_sample(strategy, "exit_order_no", price_val, size_val)

    open_lots: Dict[Tuple[str, str, str, str, str], List[List[float]]] = {}
    closed_trade_count: Dict[str, int] = {}

    def _resolve_fill_strategy(row_obj: sqlite3.Row, order_entry: Optional[Any]) -> str:
        if order_entry is not None:
            resolved = _resolve_order_strategy(order_entry)
            if resolved:
                return resolved
        key = _order_key_from_fields(
            str(row_obj["slug"] or ""),
            str(row_obj["event_date"] or ""),
            str(row_obj["outcome"] or ""),
            str(row_obj["outcome_side"] or ""),
        )
        if not all(key):
            return ""
        created_text = str(row_obj["trade_time"] or row_obj["created_at"] or "").strip()
        return _resolve_strategy_from_timeline(key, created_text)

    cur = conn.cursor()
    try:
        cur.execute(
            """
            SELECT id, order_id, slug, event_date, outcome, outcome_side, trade_side, price, size, trade_time, created_at
            FROM edge_trade_fills
            WHERE date(event_date) BETWEEN ? AND ?
            ORDER BY datetime(COALESCE(trade_time, created_at)) ASC, id ASC
            """,
            (start_text, end_text),
        )
    except sqlite3.OperationalError:
        return _with_strategy_legacy_aliases(stats)
    for row in cur.fetchall():
        trade_time_text = str(row["trade_time"] or row["created_at"] or "")
        if trade_time_text and is_before_stats_cutoff(trade_time_text):
            continue
        order_id = str(row["order_id"] or "").strip()
        order_entry = auto_orders.get(order_id) if order_id else None
        strategy = _resolve_fill_strategy(row, order_entry)
        if strategy not in stats:
            continue
        event_date = date_from_any(str(row["event_date"] or ""))
        if not event_date or event_date < start_date or event_date > end_date:
            continue
        fill_side = str(row["trade_side"] or "").upper()
        price = to_float(row["price"])
        size = to_float(row["size"])
        if price is None or size is None or not math.isfinite(price) or not math.isfinite(size) or size <= 0:
            continue
        contract_side = str(
            row["outcome_side"]
            or (_row_text(order_entry, "side") if order_entry is not None else "")
        ).strip().upper()
        lot_key = (
            strategy,
            str(row["slug"] or "").strip(),
            str(row["event_date"] or "").strip(),
            str(row["outcome"] or "").strip(),
            contract_side,
        )
        stats_entry = stats[strategy]
        if fill_side == "BUY":
            stats_entry["buy_fill_count"] += 1
            if contract_side == "YES":
                stats_entry["buy_fill_yes_count"] += 1
            elif contract_side == "NO":
                stats_entry["buy_fill_no_count"] += 1
            _add_price_sample(strategy, "buy_fill_all", price, size)
            if contract_side == "YES":
                _add_price_sample(strategy, "buy_fill_yes", price, size)
            elif contract_side == "NO":
                _add_price_sample(strategy, "buy_fill_no", price, size)
            lots = open_lots.setdefault(lot_key, [])
            lots.append([float(size), float(price)])
            continue
        if fill_side != "SELL":
            continue
        stats_entry["sell_fill_count"] += 1
        if contract_side == "YES":
            stats_entry["sell_fill_yes_count"] += 1
        elif contract_side == "NO":
            stats_entry["sell_fill_no_count"] += 1
        _add_price_sample(strategy, "sell_fill_all", price, size)
        if contract_side == "YES":
            _add_price_sample(strategy, "sell_fill_yes", price, size)
        elif contract_side == "NO":
            _add_price_sample(strategy, "sell_fill_no", price, size)
        remaining = float(size)
        matched_qty = 0.0
        matched_cost = 0.0
        matched_pnl = 0.0
        lots = open_lots.setdefault(lot_key, [])
        while remaining > TIME_EDGE_Q_EPS and lots:
            lot_qty, lot_price = lots[0]
            take_qty = min(float(lot_qty), remaining)
            matched_qty += take_qty
            matched_cost += float(lot_price) * take_qty
            matched_pnl += (float(price) - float(lot_price)) * take_qty
            lot_qty -= take_qty
            remaining -= take_qty
            if lot_qty <= TIME_EDGE_Q_EPS:
                lots.pop(0)
            else:
                lots[0][0] = lot_qty
        if matched_qty <= TIME_EDGE_Q_EPS:
            continue
        closed_trade_count[strategy] = int(closed_trade_count.get(strategy) or 0) + 1
        stats_entry["total_pnl"] += matched_pnl
        stats_entry["total_cost"] += matched_cost
        if matched_pnl >= 0:
            stats_entry["win_count"] += 1
        else:
            stats_entry["loss_count"] += 1

    for strategy, stats_entry in stats.items():
        open_trade_count = 0
        for lot_key, lots in open_lots.items():
            if not lots or lot_key[0] != strategy:
                continue
            for lot_qty, _lot_price in lots:
                if to_float(lot_qty) and float(lot_qty) > TIME_EDGE_Q_EPS:
                    open_trade_count += 1
        stats_entry["open_trade_count"] = open_trade_count
        closed_count = int(closed_trade_count.get(strategy) or 0)
        stats_entry["trade_count"] = int(closed_count + open_trade_count)
        entry_total = int(stats_entry.get("entry_order_count") or 0)
        entry_no = int(stats_entry.get("entry_order_no_count") or 0)
        entry_yes = int(stats_entry.get("entry_order_yes_count") or 0)
        stats_entry["entry_order_no_ratio"] = (entry_no / entry_total) if entry_total > 0 else None
        stats_entry["entry_order_yes_ratio"] = (entry_yes / entry_total) if entry_total > 0 else None
        buy_total = int(stats_entry.get("buy_fill_count") or 0)
        buy_no = int(stats_entry.get("buy_fill_no_count") or 0)
        buy_yes = int(stats_entry.get("buy_fill_yes_count") or 0)
        stats_entry["buy_fill_no_ratio"] = (buy_no / buy_total) if buy_total > 0 else None
        stats_entry["buy_fill_yes_ratio"] = (buy_yes / buy_total) if buy_total > 0 else None
        sell_total = int(stats_entry.get("sell_fill_count") or 0)
        sell_no = int(stats_entry.get("sell_fill_no_count") or 0)
        sell_yes = int(stats_entry.get("sell_fill_yes_count") or 0)
        stats_entry["sell_fill_no_ratio"] = (sell_no / sell_total) if sell_total > 0 else None
        stats_entry["sell_fill_yes_ratio"] = (sell_yes / sell_total) if sell_total > 0 else None
        stats_entry["entry_order_avg_price"] = _weighted_avg_price(strategy, "entry_order_all")
        stats_entry["entry_order_yes_avg_price"] = _weighted_avg_price(strategy, "entry_order_yes")
        stats_entry["entry_order_no_avg_price"] = _weighted_avg_price(strategy, "entry_order_no")
        stats_entry["exit_order_avg_price"] = _weighted_avg_price(strategy, "exit_order_all")
        stats_entry["exit_order_yes_avg_price"] = _weighted_avg_price(strategy, "exit_order_yes")
        stats_entry["exit_order_no_avg_price"] = _weighted_avg_price(strategy, "exit_order_no")
        stats_entry["buy_fill_avg_price"] = _weighted_avg_price(strategy, "buy_fill_all")
        stats_entry["buy_fill_yes_avg_price"] = _weighted_avg_price(strategy, "buy_fill_yes")
        stats_entry["buy_fill_no_avg_price"] = _weighted_avg_price(strategy, "buy_fill_no")
        stats_entry["sell_fill_avg_price"] = _weighted_avg_price(strategy, "sell_fill_all")
        stats_entry["sell_fill_yes_avg_price"] = _weighted_avg_price(strategy, "sell_fill_yes")
        stats_entry["sell_fill_no_avg_price"] = _weighted_avg_price(strategy, "sell_fill_no")
        stats_entry["entry_order_notional"] = _price_stat(strategy, "entry_order_all", "notional")
        stats_entry["entry_order_yes_notional"] = _price_stat(strategy, "entry_order_yes", "notional")
        stats_entry["entry_order_no_notional"] = _price_stat(strategy, "entry_order_no", "notional")
        stats_entry["exit_order_notional"] = _price_stat(strategy, "exit_order_all", "notional")
        stats_entry["exit_order_yes_notional"] = _price_stat(strategy, "exit_order_yes", "notional")
        stats_entry["exit_order_no_notional"] = _price_stat(strategy, "exit_order_no", "notional")
        stats_entry["buy_fill_notional"] = _price_stat(strategy, "buy_fill_all", "notional")
        stats_entry["buy_fill_yes_notional"] = _price_stat(strategy, "buy_fill_yes", "notional")
        stats_entry["buy_fill_no_notional"] = _price_stat(strategy, "buy_fill_no", "notional")
        stats_entry["sell_fill_notional"] = _price_stat(strategy, "sell_fill_all", "notional")
        stats_entry["sell_fill_yes_notional"] = _price_stat(strategy, "sell_fill_yes", "notional")
        stats_entry["sell_fill_no_notional"] = _price_stat(strategy, "sell_fill_no", "notional")
        cost = stats_entry.get("total_cost") or 0.0
        pnl = stats_entry.get("total_pnl") or 0.0
        stats_entry["roi"] = (pnl / cost) if cost else None
        win_count = stats_entry.get("win_count") or 0
        stats_entry["win_rate"] = (win_count / closed_count) if closed_count else None
    return stats


def compute_strategy_stats(conn: sqlite3.Connection, days: int, run_date: str = "") -> Dict[str, Dict[str, Any]]:
    """
    Strategy performance SSOT for UI (/api/scoreboard.strategy_stats*).

    Goals:
    - Execution counts: placed orders vs filled orders (distinct order_id).
    - PnL attribution: FIFO lots, attributed to the *entry* strategy (not the exit order strategy).
    - Settlement closure: if settlement_actual is known, close remaining lots at payout (YES=1 if actual bucket,
      NO=1 if NOT actual bucket).
    - Fees: include per-fill fee in net entry/exit cost.
    """

    def _row_text(row_obj: Any, key: str) -> str:
        if row_obj is None:
            return ""
        if isinstance(row_obj, dict):
            return str(row_obj.get(key) or "")
        try:
            return str(row_obj[key] or "")
        except Exception:
            return ""

    def _row_float(row_obj: Any, key: str) -> Optional[float]:
        if row_obj is None:
            return None
        if isinstance(row_obj, dict):
            return to_float(row_obj.get(key))
        try:
            return to_float(row_obj[key])
        except Exception:
            return None

    run_date_norm = str(run_date or "").strip()
    run_date_day = date_from_any(run_date_norm) if run_date_norm else None
    if run_date_day:
        start_date = run_date_day
        end_date = run_date_day
    else:
        start_date, end_date = resolve_stats_range(conn, days, require_settlement=False)
    start_text = start_date.isoformat()
    end_text = end_date.isoformat()
    use_activity_day_window = bool(run_date_day)
    local_tz = datetime.now().astimezone().tzinfo or timezone.utc
    activity_sql_start = (start_date - timedelta(days=1)).isoformat()
    activity_sql_end = (end_date + timedelta(days=1)).isoformat()

    def _in_activity_day_window(ts_text: str) -> bool:
        dt = parse_any_ts(str(ts_text or "").strip())
        if dt is None:
            return False
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=local_tz)
        day = dt.astimezone(local_tz).date()
        return start_date <= day <= end_date

    stats: Dict[str, Dict[str, Any]] = strategy_stats_defaults()

    def _ensure_strategy(key: str) -> Dict[str, Any]:
        k = str(key or "").strip().lower()
        if not k:
            k = "main"
        if k not in stats:
            stats[k] = _empty_strategy_entry()
        return stats[k]

    auto_orders = query_auto_orders(conn, apply_cutoff=not bool(run_date_day))

    def _order_key_from_fields(slug: str, event_date: str, outcome: str, side: str) -> Tuple[str, str, str, str]:
        return (
            str(slug or "").strip(),
            str(event_date or "").strip(),
            str(outcome or "").strip(),
            str(side or "").strip().upper(),
        )

    def _order_key(row_obj: Any) -> Tuple[str, str, str, str]:
        return _order_key_from_fields(
            _row_text(row_obj, "slug"),
            _row_text(row_obj, "event_date"),
            _row_text(row_obj, "outcome"),
            _row_text(row_obj, "side"),
        )

    # Timeline for inferring exit order strategy if order.strategy is missing/"exit".
    entry_strategy_timeline: Dict[Tuple[str, str, str, str], List[Tuple[Optional[float], str, str]]] = {}
    for order in auto_orders.values():
        action_norm = _row_text(order, "action").strip().lower()
        if action_norm != "entry":
            continue
        strategy = _row_text(order, "strategy").strip().lower()
        strategy = _normalize_strategy_key(strategy, fallback="main")
        key = _order_key(order)
        if not all(key):
            continue
        created_text = _row_text(order, "created_at").strip()
        created_dt = parse_any_ts(created_text) if created_text else None
        created_ts = created_dt.timestamp() if created_dt is not None else None
        entry_strategy_timeline.setdefault(key, []).append((created_ts, created_text, strategy))
    for key in list(entry_strategy_timeline.keys()):
        timeline = entry_strategy_timeline.get(key) or []
        timeline.sort(key=lambda item: (item[0] if item[0] is not None else -10**18, item[1]))
        entry_strategy_timeline[key] = timeline

    def _resolve_strategy_from_timeline(key: Tuple[str, str, str, str], created_at_text: str) -> str:
        timeline = entry_strategy_timeline.get(key) or []
        if not timeline:
            return ""
        created_dt = parse_any_ts(created_at_text) if created_at_text else None
        created_ts = created_dt.timestamp() if created_dt is not None else None
        if created_ts is None:
            return str(timeline[-1][2] or "")
        candidate = ""
        for ts_val, _ts_text, strategy in timeline:
            if ts_val is None:
                candidate = str(strategy or "")
                continue
            if ts_val <= created_ts:
                candidate = str(strategy or "")
                continue
            break
        return candidate or str(timeline[-1][2] or "")

    def _resolve_order_strategy(row_obj: Any) -> str:
        action_norm = _row_text(row_obj, "action").strip().lower()
        strategy_raw = _row_text(row_obj, "strategy").strip().lower()
        if action_norm == "entry":
            if strategy_raw and strategy_raw != "exit":
                return _normalize_strategy_key(strategy_raw, fallback="main")
            return _normalize_strategy_key("", fallback="main")
        if action_norm == "exit":
            if strategy_raw and strategy_raw != "exit":
                return _normalize_strategy_key(strategy_raw, fallback="main")
            # Attribute system exits back to the originating entry strategy (event-level归类口径).
            inferred = _resolve_strategy_from_timeline(_order_key(row_obj), _row_text(row_obj, "created_at").strip())
            return _normalize_strategy_key(inferred, fallback="unknown")
        return _normalize_strategy_key(strategy_raw, fallback="main")

    # Weighted price samples: (strategy, bucket) -> [notional, qty]
    price_samples: Dict[Tuple[str, str], List[float]] = {}

    def _add_price_sample(strategy: str, bucket: str, price_val: Optional[float], size_val: Optional[float]) -> None:
        price = to_float(price_val)
        size = to_float(size_val)
        if price is None or size is None:
            return
        if not math.isfinite(price) or not math.isfinite(size) or size <= 0:
            return
        key = (str(strategy or ""), str(bucket or ""))
        sample = price_samples.get(key)
        if sample is None:
            sample = [0.0, 0.0]
            price_samples[key] = sample
        sample[0] += float(price) * float(size)
        sample[1] += float(size)

    def _weighted_avg_price(strategy: str, bucket: str) -> Optional[float]:
        sample = price_samples.get((str(strategy or ""), str(bucket or "")))
        if not sample:
            return None
        notional, qty = float(sample[0] or 0.0), float(sample[1] or 0.0)
        if qty <= TIME_EDGE_Q_EPS:
            return None
        return notional / qty

    def _avg_odds_from_avg_price(avg_price: Any) -> Optional[float]:
        p = to_float(avg_price)
        if p is None or not math.isfinite(p) or p <= 0 or p >= 1:
            return None
        # Net odds: profit per $1 stake (not including returned stake).
        # For a binary $1 payout contract bought at price p:
        #   win profit = 1-p, lose = -p, so net-odds multiple = (1-p)/p.
        return (1.0 - p) / p

    def _add_pnl_cost_side(stats_entry: Dict[str, Any], contract_side: str, pnl_chunk: float, cost_chunk: float) -> None:
        side = str(contract_side or "").strip().upper()
        if side == "YES":
            stats_entry["total_pnl_yes"] += float(pnl_chunk)
            stats_entry["total_cost_yes"] += float(cost_chunk)
        elif side == "NO":
            stats_entry["total_pnl_no"] += float(pnl_chunk)
            stats_entry["total_cost_no"] += float(cost_chunk)

    # Order stats (placed orders).
    for order in auto_orders.values():
        action_norm = _row_text(order, "action").strip().lower()
        if action_norm not in {"entry", "exit"}:
            continue
        created_text = _row_text(order, "created_at").strip()
        if use_activity_day_window:
            if not _in_activity_day_window(created_text):
                continue
        else:
            order_date = date_from_any(_row_text(order, "event_date"))
            if not order_date or order_date < start_date or order_date > end_date:
                continue
        if (not use_activity_day_window) and created_text and is_before_stats_cutoff(created_text):
            continue
        strategy = _resolve_order_strategy(order)
        stats_entry = _ensure_strategy(strategy)
        stats_entry["order_count"] += 1
        side_norm = _row_text(order, "side").strip().upper()
        if action_norm == "entry":
            stats_entry["entry_order_count"] += 1
            if side_norm == "YES":
                stats_entry["entry_order_yes_count"] += 1
            elif side_norm == "NO":
                stats_entry["entry_order_no_count"] += 1
        else:
            stats_entry["exit_order_count"] += 1
            if side_norm == "YES":
                stats_entry["exit_order_yes_count"] += 1
            elif side_norm == "NO":
                stats_entry["exit_order_no_count"] += 1
        price_val = _row_float(order, "price")
        size_val = _row_float(order, "size")
        if price_val is None or size_val is None or not math.isfinite(price_val) or not math.isfinite(size_val) or size_val <= 0:
            continue
        notional = float(price_val) * float(size_val)
        if action_norm == "entry":
            _add_price_sample(strategy, "entry_order_all", price_val, size_val)
            stats_entry["entry_order_notional"] += notional
            if side_norm == "YES":
                _add_price_sample(strategy, "entry_order_yes", price_val, size_val)
                stats_entry["entry_order_yes_notional"] += notional
            elif side_norm == "NO":
                _add_price_sample(strategy, "entry_order_no", price_val, size_val)
                stats_entry["entry_order_no_notional"] += notional
        else:
            _add_price_sample(strategy, "exit_order_all", price_val, size_val)
            stats_entry["exit_order_notional"] += notional
            if side_norm == "YES":
                _add_price_sample(strategy, "exit_order_yes", price_val, size_val)
                stats_entry["exit_order_yes_notional"] += notional
            elif side_norm == "NO":
                _add_price_sample(strategy, "exit_order_no", price_val, size_val)
                stats_entry["exit_order_no_notional"] += notional

    # Fill-level performance.
    # contract_key: (slug, event_date, outcome, YES/NO)
    # We support both long and short lots (SELL can open a short; BUY can cover a short).
    open_pos: Dict[Tuple[str, str, str, str], Dict[str, List[Dict[str, Any]]]] = {}
    # trade_state: (strategy, contract_key) -> {"net_qty": float, "trade_pnl": float}
    trade_state: Dict[Tuple[str, Tuple[str, str, str, str]], Dict[str, float]] = {}

    filled_orders: Dict[str, set] = {}
    filled_entry_orders: Dict[str, set] = {}
    filled_exit_orders: Dict[str, set] = {}

    # settlement cache: (slug,event_date) -> actual_bucket_label
    actual_bucket_cache: Dict[Tuple[str, str], Optional[str]] = {}

    def _actual_bucket_for_event(slug: str, event_date: str) -> Optional[str]:
        key = (slug, event_date)
        if key in actual_bucket_cache:
            return actual_bucket_cache[key]
        row = None
        try:
            row = query_latest_event_run(conn, slug, event_date)
        except Exception:
            row = None
        if not row:
            actual_bucket_cache[key] = None
            return None
        actual_val = to_float(row["settlement_actual"])
        if actual_val is None:
            actual_bucket_cache[key] = None
            return None
        payload = safe_json_loads(row["payload_json"])
        distribution = normalize_distribution_rows(payload.get("rows") or payload.get("distribution") or [])
        if not distribution:
            actual_bucket_cache[key] = None
            return None
        label = str(actual_bucket_label(row, distribution) or "").strip()
        actual_bucket_cache[key] = label or None
        return actual_bucket_cache[key]

    def _state_for(strategy: str, contract_key: Tuple[str, str, str, str]) -> Dict[str, float]:
        k = (strategy, contract_key)
        state = trade_state.get(k)
        if state is None:
            state = {"net_qty": 0.0, "trade_pnl": 0.0}
            trade_state[k] = state
        return state

    def _close_trade_if_needed(strategy: str, contract_key: Tuple[str, str, str, str]) -> None:
        state = _state_for(strategy, contract_key)
        if abs(float(state.get("net_qty") or 0.0)) > TIME_EDGE_Q_EPS:
            return
        trade_pnl = float(state.get("trade_pnl") or 0.0)
        stats_entry = _ensure_strategy(strategy)
        stats_entry["closed_trade_count"] += 1
        contract_side = str(contract_key[3] or "").strip().upper()
        if contract_side == "YES":
            stats_entry["closed_trade_yes_count"] += 1
        elif contract_side == "NO":
            stats_entry["closed_trade_no_count"] += 1
        if abs(trade_pnl) <= 1e-9:
            stats_entry["break_even_count"] += 1
            if contract_side == "YES":
                stats_entry["break_even_yes_count"] += 1
            elif contract_side == "NO":
                stats_entry["break_even_no_count"] += 1
        elif trade_pnl > 0:
            stats_entry["win_count"] += 1
            stats_entry["gross_profit"] += trade_pnl
            if contract_side == "YES":
                stats_entry["win_yes_count"] += 1
                stats_entry["gross_profit_yes"] += trade_pnl
            elif contract_side == "NO":
                stats_entry["win_no_count"] += 1
                stats_entry["gross_profit_no"] += trade_pnl
        else:
            stats_entry["loss_count"] += 1
            stats_entry["gross_loss"] += trade_pnl
            if contract_side == "YES":
                stats_entry["loss_yes_count"] += 1
                stats_entry["gross_loss_yes"] += trade_pnl
            elif contract_side == "NO":
                stats_entry["loss_no_count"] += 1
                stats_entry["gross_loss_no"] += trade_pnl
        state["net_qty"] = 0.0
        state["trade_pnl"] = 0.0

    cur = conn.cursor()
    try:
        if use_activity_day_window:
            cur.execute(
                """
                SELECT id, order_id, slug, event_date, outcome, outcome_side, trade_side, price, size, fee, trade_time, created_at
                FROM edge_trade_fills
                WHERE date(COALESCE(trade_time, created_at)) BETWEEN ? AND ?
                ORDER BY datetime(COALESCE(trade_time, created_at)) ASC, id ASC
                """,
                (activity_sql_start, activity_sql_end),
            )
        else:
            cur.execute(
                """
                SELECT id, order_id, slug, event_date, outcome, outcome_side, trade_side, price, size, fee, trade_time, created_at
                FROM edge_trade_fills
                WHERE event_date BETWEEN ? AND ?
                ORDER BY datetime(COALESCE(trade_time, created_at)) ASC, id ASC
                """,
                (start_text, end_text),
            )
    except sqlite3.OperationalError:
        return _with_strategy_legacy_aliases(stats)

    for row in cur.fetchall():
        trade_time_text = str(row["trade_time"] or row["created_at"] or "").strip()
        if (not use_activity_day_window) and trade_time_text and is_before_stats_cutoff(trade_time_text):
            continue
        if use_activity_day_window and not _in_activity_day_window(trade_time_text):
            continue
        slug = str(row["slug"] or "").strip()
        event_date = str(row["event_date"] or "").strip()
        outcome = str(row["outcome"] or "").strip()
        contract_side = str(row["outcome_side"] or "").strip().upper()
        if not slug or not event_date or not outcome or not contract_side:
            continue
        fill_side = str(row["trade_side"] or "").strip().upper()
        price = to_float(row["price"])
        size = to_float(row["size"])
        fee_val = to_float(row["fee"])
        if price is None or size is None or not math.isfinite(price) or not math.isfinite(size) or size <= 0:
            continue
        fee_val = float(fee_val) if fee_val is not None and math.isfinite(fee_val) else 0.0

        contract_key = (slug, event_date, outcome, contract_side)
        order_id = str(row["order_id"] or "").strip()
        order_entry = auto_orders.get(order_id) if order_id else None
        # Policy (SSOT): fills that can't be tied to an auto_orders row are excluded from strategy stats.
        # This prevents "unknown (0 placed / N filled)" noise when edge_trade_fills contains manual/non-auto fills
        # or when order provenance is missing.
        if order_entry is None:
            continue
        order_strategy = _resolve_order_strategy(order_entry) if order_entry is not None else ""
        if order_id:
            strat = (order_strategy or "unknown").strip().lower()
            filled_orders.setdefault(strat, set()).add(order_id)
            action_norm = _row_text(order_entry, "action").strip().lower() if order_entry is not None else ""
            if action_norm == "entry":
                filled_entry_orders.setdefault(strat, set()).add(order_id)
            elif action_norm == "exit":
                filled_exit_orders.setdefault(strat, set()).add(order_id)

        if fill_side == "BUY":
            strategy = order_strategy or _resolve_strategy_from_timeline(
                _order_key_from_fields(slug, event_date, outcome, contract_side),
                trade_time_text,
            )
            strategy = (strategy or "unknown").strip().lower()
            stats_entry = _ensure_strategy(strategy)
            stats_entry["buy_fill_count"] += 1
            if contract_side == "YES":
                stats_entry["buy_fill_yes_count"] += 1
            elif contract_side == "NO":
                stats_entry["buy_fill_no_count"] += 1
            _add_price_sample(strategy, "buy_fill_all", price, size)
            notional = float(price) * float(size)
            stats_entry["buy_fill_notional"] += notional
            if contract_side == "YES":
                _add_price_sample(strategy, "buy_fill_yes", price, size)
                stats_entry["buy_fill_yes_notional"] += notional
            elif contract_side == "NO":
                _add_price_sample(strategy, "buy_fill_no", price, size)
                stats_entry["buy_fill_no_notional"] += notional
            stats_entry["total_fees"] += fee_val

            per_share_fee = (fee_val / float(size)) if float(size) > TIME_EDGE_Q_EPS else 0.0
            buy_net_per_share = float(price) + per_share_fee

            pos = open_pos.setdefault(contract_key, {"long": [], "short": []})
            shorts = pos.get("short") or []
            pos["short"] = shorts
            longs = pos.get("long") or []
            pos["long"] = longs

            # First cover any open short lots (SELL->BUY round-trip).
            remaining = float(size)
            covered: Dict[str, float] = {}
            while remaining > TIME_EDGE_Q_EPS and shorts:
                lot = shorts[0]
                lot_qty = float(to_float(lot.get("qty")) or 0.0)
                if lot_qty <= TIME_EDGE_Q_EPS:
                    shorts.pop(0)
                    continue
                take_qty = min(lot_qty, remaining)
                lot_strategy = str(lot.get("strategy") or "unknown").strip().lower() or "unknown"
                covered[lot_strategy] = covered.get(lot_strategy, 0.0) + take_qty
                entry_sell_net = float(to_float(lot.get("entry_price")) or 0.0)
                pnl_chunk = (entry_sell_net - buy_net_per_share) * take_qty
                # For shorts, treat max loss (1-entry_price) as capital-at-risk for ROI scaling.
                cost_chunk = max(1.0 - entry_sell_net, 0.0) * take_qty
                stats_cov = _ensure_strategy(lot_strategy)
                stats_cov["total_pnl"] += pnl_chunk
                stats_cov["total_pnl_sell"] += pnl_chunk
                stats_cov["total_cost"] += cost_chunk
                _add_pnl_cost_side(stats_cov, contract_side, pnl_chunk, cost_chunk)
                state_cov = _state_for(lot_strategy, contract_key)
                state_cov["trade_pnl"] += pnl_chunk
                state_cov["net_qty"] += take_qty

                lot_qty -= take_qty
                remaining -= take_qty
                if lot_qty <= TIME_EDGE_Q_EPS:
                    shorts.pop(0)
                else:
                    lot["qty"] = lot_qty

            for lot_strategy in covered.keys():
                _close_trade_if_needed(lot_strategy, contract_key)

            # Remaining BUY opens/extends a long lot.
            if remaining > TIME_EDGE_Q_EPS:
                longs.append(
                    {
                        "qty": remaining,
                        "entry_price": buy_net_per_share,
                        "strategy": strategy,
                    }
                )
                state = _state_for(strategy, contract_key)
                state["net_qty"] += remaining
            continue

        if fill_side != "SELL":
            continue

        pos = open_pos.setdefault(contract_key, {"long": [], "short": []})
        longs = pos.get("long") or []
        pos["long"] = longs
        shorts = pos.get("short") or []
        pos["short"] = shorts

        lots = longs
        remaining = float(size)
        if remaining <= TIME_EDGE_Q_EPS:
            continue
        per_share_fee = (fee_val / float(size)) if float(size) > TIME_EDGE_Q_EPS else 0.0
        sell_net_per_share = float(price) - per_share_fee
        touched: Dict[str, float] = {}

        while remaining > TIME_EDGE_Q_EPS and lots:
            lot = lots[0]
            lot_qty = float(to_float(lot.get("qty")) or 0.0)
            if lot_qty <= TIME_EDGE_Q_EPS:
                lots.pop(0)
                continue
            take_qty = min(lot_qty, remaining)
            lot_strategy = str(lot.get("strategy") or "unknown").strip().lower() or "unknown"
            touched[lot_strategy] = touched.get(lot_strategy, 0.0) + take_qty

            entry_buy_net = float(to_float(lot.get("entry_price")) or 0.0)
            pnl_chunk = (sell_net_per_share - entry_buy_net) * take_qty
            cost_chunk = entry_buy_net * take_qty
            stats_entry = _ensure_strategy(lot_strategy)
            stats_entry["total_pnl"] += pnl_chunk
            stats_entry["total_pnl_sell"] += pnl_chunk
            stats_entry["total_cost"] += cost_chunk
            _add_pnl_cost_side(stats_entry, contract_side, pnl_chunk, cost_chunk)
            state = _state_for(lot_strategy, contract_key)
            state["trade_pnl"] += pnl_chunk
            state["net_qty"] -= take_qty

            lot_qty -= take_qty
            remaining -= take_qty
            if lot_qty <= TIME_EDGE_Q_EPS:
                lots.pop(0)
            else:
                lot["qty"] = lot_qty

        # Any residual SELL opens/extends a short lot.
        if remaining > TIME_EDGE_Q_EPS:
            sell_strategy = order_strategy or _resolve_strategy_from_timeline(
                _order_key_from_fields(slug, event_date, outcome, contract_side),
                trade_time_text,
            )
            sell_strategy = (sell_strategy or "unknown").strip().lower()
            shorts.append(
                {
                    "qty": remaining,
                    "entry_price": sell_net_per_share,
                    "strategy": sell_strategy,
                }
            )
            state_open = _state_for(sell_strategy, contract_key)
            state_open["net_qty"] -= remaining
            # Note: this SELL did not close any long lots for that portion, so it does not contribute to realized PnL yet.

        if touched:
            for lot_strategy, matched_qty in touched.items():
                stats_entry = _ensure_strategy(lot_strategy)
                stats_entry["sell_fill_count"] += 1
                if contract_side == "YES":
                    stats_entry["sell_fill_yes_count"] += 1
                elif contract_side == "NO":
                    stats_entry["sell_fill_no_count"] += 1
                ratio = (matched_qty / float(size)) if float(size) > TIME_EDGE_Q_EPS else 0.0
                fee_alloc = fee_val * ratio
                notional_alloc = float(price) * matched_qty
                stats_entry["sell_fill_notional"] += notional_alloc
                stats_entry["total_fees"] += fee_alloc
                _add_price_sample(lot_strategy, "sell_fill_all", price, matched_qty)
                if contract_side == "YES":
                    stats_entry["sell_fill_yes_notional"] += notional_alloc
                    _add_price_sample(lot_strategy, "sell_fill_yes", price, matched_qty)
                elif contract_side == "NO":
                    stats_entry["sell_fill_no_notional"] += notional_alloc
                    _add_price_sample(lot_strategy, "sell_fill_no", price, matched_qty)
            for lot_strategy in touched.keys():
                _close_trade_if_needed(lot_strategy, contract_key)

    # Ensure strategies seen only via filled-order stats are present.
    for k in set(filled_orders.keys()) | set(filled_entry_orders.keys()) | set(filled_exit_orders.keys()):
        _ensure_strategy(k)

    # Settlement closure for remaining lots (if settlement_actual exists).
    for contract_key, pos in list(open_pos.items()):
        longs = (pos.get("long") or []) if isinstance(pos, dict) else []
        shorts = (pos.get("short") or []) if isinstance(pos, dict) else []
        if not longs and not shorts:
            continue
        slug, event_date, outcome, contract_side = contract_key
        actual_label = _actual_bucket_for_event(slug, event_date)
        if not actual_label:
            continue
        payout = None
        if contract_side == "YES":
            payout = 1.0 if outcome == actual_label else 0.0
        elif contract_side == "NO":
            payout = 0.0 if outcome == actual_label else 1.0
        if payout is None:
            continue
        payout = float(payout)

        # Long lots: payout is a synthetic SELL at price=payout.
        for lot in list(longs):
            lot_qty = float(to_float(lot.get("qty")) or 0.0)
            if lot_qty <= TIME_EDGE_Q_EPS:
                continue
            lot_strategy = str(lot.get("strategy") or "unknown").strip().lower() or "unknown"
            entry_buy_net = float(to_float(lot.get("entry_price")) or 0.0)
            pnl_chunk = (payout - entry_buy_net) * lot_qty
            cost_chunk = entry_buy_net * lot_qty
            stats_entry = _ensure_strategy(lot_strategy)
            stats_entry["total_pnl"] += pnl_chunk
            stats_entry["total_pnl_settlement"] += pnl_chunk
            stats_entry["total_cost"] += cost_chunk
            _add_pnl_cost_side(stats_entry, contract_side, pnl_chunk, cost_chunk)
            state = _state_for(lot_strategy, contract_key)
            state["trade_pnl"] += pnl_chunk
            state["net_qty"] -= lot_qty
            _close_trade_if_needed(lot_strategy, contract_key)

        # Short lots: payout is a synthetic BUY-to-cover at price=payout.
        for lot in list(shorts):
            lot_qty = float(to_float(lot.get("qty")) or 0.0)
            if lot_qty <= TIME_EDGE_Q_EPS:
                continue
            lot_strategy = str(lot.get("strategy") or "unknown").strip().lower() or "unknown"
            entry_sell_net = float(to_float(lot.get("entry_price")) or 0.0)
            pnl_chunk = (entry_sell_net - payout) * lot_qty
            cost_chunk = max(1.0 - entry_sell_net, 0.0) * lot_qty
            stats_entry = _ensure_strategy(lot_strategy)
            stats_entry["total_pnl"] += pnl_chunk
            stats_entry["total_pnl_settlement"] += pnl_chunk
            stats_entry["total_cost"] += cost_chunk
            _add_pnl_cost_side(stats_entry, contract_side, pnl_chunk, cost_chunk)
            state = _state_for(lot_strategy, contract_key)
            state["trade_pnl"] += pnl_chunk
            state["net_qty"] += lot_qty
            _close_trade_if_needed(lot_strategy, contract_key)

    # Final derived fields.
    for strategy, stats_entry in stats.items():
        stats_entry["filled_order_count"] = len(filled_orders.get(strategy) or set())
        stats_entry["filled_entry_order_count"] = len(filled_entry_orders.get(strategy) or set())
        stats_entry["filled_exit_order_count"] = len(filled_exit_orders.get(strategy) or set())

        open_trade_count = 0
        for (s, _ck), state in trade_state.items():
            if s != strategy:
                continue
            if abs(float(state.get("net_qty") or 0.0)) > TIME_EDGE_Q_EPS:
                open_trade_count += 1
        stats_entry["open_trade_count"] = open_trade_count
        closed_count = int(stats_entry.get("closed_trade_count") or 0)
        stats_entry["trade_count"] = int(open_trade_count + closed_count)

        entry_total = int(stats_entry.get("entry_order_count") or 0)
        entry_no = int(stats_entry.get("entry_order_no_count") or 0)
        entry_yes = int(stats_entry.get("entry_order_yes_count") or 0)
        stats_entry["entry_order_no_ratio"] = (entry_no / entry_total) if entry_total > 0 else None
        stats_entry["entry_order_yes_ratio"] = (entry_yes / entry_total) if entry_total > 0 else None

        buy_total = int(stats_entry.get("buy_fill_count") or 0)
        buy_no = int(stats_entry.get("buy_fill_no_count") or 0)
        buy_yes = int(stats_entry.get("buy_fill_yes_count") or 0)
        stats_entry["buy_fill_no_ratio"] = (buy_no / buy_total) if buy_total > 0 else None
        stats_entry["buy_fill_yes_ratio"] = (buy_yes / buy_total) if buy_total > 0 else None

        sell_total = int(stats_entry.get("sell_fill_count") or 0)
        sell_no = int(stats_entry.get("sell_fill_no_count") or 0)
        sell_yes = int(stats_entry.get("sell_fill_yes_count") or 0)
        stats_entry["sell_fill_no_ratio"] = (sell_no / sell_total) if sell_total > 0 else None
        stats_entry["sell_fill_yes_ratio"] = (sell_yes / sell_total) if sell_total > 0 else None

        stats_entry["entry_order_avg_price"] = _weighted_avg_price(strategy, "entry_order_all")
        stats_entry["entry_order_yes_avg_price"] = _weighted_avg_price(strategy, "entry_order_yes")
        stats_entry["entry_order_no_avg_price"] = _weighted_avg_price(strategy, "entry_order_no")
        stats_entry["exit_order_avg_price"] = _weighted_avg_price(strategy, "exit_order_all")
        stats_entry["exit_order_yes_avg_price"] = _weighted_avg_price(strategy, "exit_order_yes")
        stats_entry["exit_order_no_avg_price"] = _weighted_avg_price(strategy, "exit_order_no")
        stats_entry["buy_fill_avg_price"] = _weighted_avg_price(strategy, "buy_fill_all")
        stats_entry["buy_fill_yes_avg_price"] = _weighted_avg_price(strategy, "buy_fill_yes")
        stats_entry["buy_fill_no_avg_price"] = _weighted_avg_price(strategy, "buy_fill_no")
        stats_entry["sell_fill_avg_price"] = _weighted_avg_price(strategy, "sell_fill_all")
        stats_entry["sell_fill_yes_avg_price"] = _weighted_avg_price(strategy, "sell_fill_yes")
        stats_entry["sell_fill_no_avg_price"] = _weighted_avg_price(strategy, "sell_fill_no")

        stats_entry["buy_fill_odds"] = _avg_odds_from_avg_price(stats_entry.get("buy_fill_avg_price"))
        stats_entry["buy_fill_yes_odds"] = _avg_odds_from_avg_price(stats_entry.get("buy_fill_yes_avg_price"))
        stats_entry["buy_fill_no_odds"] = _avg_odds_from_avg_price(stats_entry.get("buy_fill_no_avg_price"))

        cost = float(stats_entry.get("total_cost") or 0.0)
        pnl = float(stats_entry.get("total_pnl") or 0.0)
        stats_entry["roi"] = (pnl / cost) if cost > TIME_EDGE_Q_EPS else None
        cost_yes = float(stats_entry.get("total_cost_yes") or 0.0)
        pnl_yes = float(stats_entry.get("total_pnl_yes") or 0.0)
        stats_entry["roi_yes"] = (pnl_yes / cost_yes) if cost_yes > TIME_EDGE_Q_EPS else None
        cost_no = float(stats_entry.get("total_cost_no") or 0.0)
        pnl_no = float(stats_entry.get("total_pnl_no") or 0.0)
        stats_entry["roi_no"] = (pnl_no / cost_no) if cost_no > TIME_EDGE_Q_EPS else None
        win_count = int(stats_entry.get("win_count") or 0)
        stats_entry["win_rate"] = (win_count / closed_count) if closed_count > 0 else None
        closed_yes = int(stats_entry.get("closed_trade_yes_count") or 0)
        win_yes = int(stats_entry.get("win_yes_count") or 0)
        stats_entry["win_rate_yes"] = (win_yes / closed_yes) if closed_yes > 0 else None
        closed_no = int(stats_entry.get("closed_trade_no_count") or 0)
        win_no = int(stats_entry.get("win_no_count") or 0)
        stats_entry["win_rate_no"] = (win_no / closed_no) if closed_no > 0 else None

        gross_profit = float(stats_entry.get("gross_profit") or 0.0)
        gross_loss = float(stats_entry.get("gross_loss") or 0.0)
        if gross_profit > TIME_EDGE_Q_EPS and gross_loss < -TIME_EDGE_Q_EPS:
            stats_entry["profit_factor"] = gross_profit / abs(gross_loss)
        else:
            stats_entry["profit_factor"] = None
        stats_entry["avg_pnl"] = (pnl / closed_count) if closed_count > 0 else None
        stats_entry["avg_win"] = (gross_profit / win_count) if win_count > 0 else None
        loss_count = int(stats_entry.get("loss_count") or 0)
        stats_entry["avg_loss"] = (gross_loss / loss_count) if loss_count > 0 else None

    return _with_strategy_legacy_aliases(stats)


def compute_strategy_entry_quality(
    conn: sqlite3.Connection,
    days: int,
    run_date: str = "",
) -> Dict[str, Dict[str, Any]]:
    """
    Entry-time expected-edge diagnostics (SSOT) per strategy.

    - Uses *filled entry orders* (auto_orders.action='entry' with >=1 fill).
    - Aligns each order to the latest facts snapshot at/before the first fill time, and reads the outcome row.
    - Returns lightweight aggregates for UI (avoid frontend recomputation).
    """

    def _resolve_entry_strategy(order_row: sqlite3.Row) -> str:
        raw = str(order_row["strategy"] or "").strip().lower()
        if not raw or raw == "exit":
            return _normalize_strategy_key("", fallback="main")
        return _normalize_strategy_key(raw, fallback="main")

    run_date_norm = str(run_date or "").strip()
    run_date_day = date_from_any(run_date_norm) if run_date_norm else None
    if run_date_day:
        start_date = run_date_day
        end_date = run_date_day
    else:
        start_date, end_date = resolve_stats_range(conn, days, require_settlement=False)
    start_text = start_date.isoformat()
    end_text = end_date.isoformat()

    agg: Dict[str, Dict[str, Any]] = {}

    def _ensure(strategy: str) -> Dict[str, Any]:
        key = _normalize_strategy_key(strategy, fallback="main")
        item = agg.get(key)
        if item is None:
            item = {
                "entry_fact_order_count": 0,
                "entry_fact_sample_count": 0,
                "entry_fact_pos_exec_edge_count": 0,
                "_qty_sum": 0.0,
                "_exec_edge_entry_sum": 0.0,
                "_exec_edge_score_sum": 0.0,
                "_model_spread_sum": 0.0,
                "_spread_sum": 0.0,
                "_q_entry_sum": 0.0,
                "_fill_price_sum": 0.0,
                "_trend_down_count": 0,
                "_trend_unknown_count": 0,
            }
            agg[key] = item
        return item

    def _find_outcome_row(fact_payload: Mapping[str, Any], outcome_label: str) -> Optional[Dict[str, Any]]:
        rows = fact_payload.get("distribution")
        if not isinstance(rows, list) or not rows:
            rows = fact_payload.get("rows")
        if not isinstance(rows, list) or not rows:
            ssot = fact_payload.get("auto_trade_ssot")
            if isinstance(ssot, dict):
                rows = ssot.get("distribution") or ssot.get("rows")
        if not isinstance(rows, list):
            return None
        label = str(outcome_label or "").strip()
        if not label:
            return None
        for item in rows:
            if isinstance(item, dict) and str(item.get("outcome") or "").strip() == label:
                return item
        return None

    cur = conn.cursor()
    try:
        cur.execute(
            """
            SELECT
              o.order_id,
              o.slug,
              o.event_date,
              o.outcome,
              o.side,
              o.strategy,
              o.created_at,
              MIN(COALESCE(f.trade_time, f.created_at)) AS first_fill_time,
              SUM(COALESCE(f.size, 0)) AS filled_qty,
              CASE
                WHEN SUM(COALESCE(f.size, 0)) > 0
                THEN SUM(COALESCE(f.price, 0) * COALESCE(f.size, 0)) / SUM(COALESCE(f.size, 0))
                ELSE NULL
              END AS fill_avg_price
            FROM auto_orders o
            JOIN edge_trade_fills f ON f.order_id = o.order_id
            WHERE o.action = 'entry'
              AND o.event_date BETWEEN ? AND ?
            GROUP BY o.order_id
            """,
            (start_text, end_text),
        )
    except sqlite3.OperationalError:
        return {}

    fact_cur = conn.cursor()
    for row in cur.fetchall():
        created_text = str(row["created_at"] or "").strip()
        if created_text and is_before_stats_cutoff(created_text):
            continue
        strategy = _resolve_entry_strategy(row)
        item = _ensure(strategy)
        item["entry_fact_order_count"] += 1

        first_fill_time = str(row["first_fill_time"] or "").strip()
        slug = str(row["slug"] or "").strip()
        event_date = str(row["event_date"] or "").strip()
        outcome = str(row["outcome"] or "").strip()
        side = str(row["side"] or "").strip().upper()
        qty = to_float(row["filled_qty"])
        if (
            not first_fill_time
            or not slug
            or not event_date
            or not outcome
            or side not in {"YES", "NO"}
            or qty is None
            or not math.isfinite(qty)
            or qty <= TIME_EDGE_Q_EPS
        ):
            continue

        try:
            fact_cur.execute(
                """
                SELECT fact_json
                FROM event_fact_history
                WHERE slug = ? AND event_date = ? AND fact_as_of <= ?
                ORDER BY fact_as_of DESC, id DESC
                LIMIT 1
                """,
                (slug, event_date, first_fill_time),
            )
        except sqlite3.OperationalError:
            continue
        fact_row = fact_cur.fetchone()
        if not fact_row:
            continue
        fact_payload = safe_json_loads(fact_row["fact_json"])
        if not fact_payload:
            continue
        out_row = _find_outcome_row(fact_payload, outcome)
        if not out_row:
            continue

        item["entry_fact_sample_count"] += 1
        qty_f = float(qty)
        item["_qty_sum"] += qty_f
        fill_avg_price = to_float(row["fill_avg_price"])

        if side == "YES":
            exec_edge_entry = to_float(out_row.get("exec_edge_entry_yes"))
            exec_edge_score = to_float(out_row.get("exec_edge_score_yes"))
            q_entry = to_float(out_row.get("q_entry"))
            spread = to_float(out_row.get("spread"))
            trend_down = bool(out_row.get("trend_down_yes"))
            trend_unknown = bool(out_row.get("trend_unknown_yes"))
        else:
            exec_edge_entry = to_float(out_row.get("exec_edge_entry_no"))
            exec_edge_score = to_float(out_row.get("exec_edge_score_no"))
            q_entry = to_float(out_row.get("q_entry_no"))
            spread = to_float(out_row.get("spread_no"))
            trend_down = bool(out_row.get("trend_down_no"))
            trend_unknown = bool(out_row.get("trend_unknown_no"))

        model_spread = to_float(out_row.get("model_spread"))
        if exec_edge_entry is not None and math.isfinite(exec_edge_entry):
            item["_exec_edge_entry_sum"] += float(exec_edge_entry) * qty_f
            if exec_edge_entry > 0:
                item["entry_fact_pos_exec_edge_count"] += 1
        if exec_edge_score is not None and math.isfinite(exec_edge_score):
            item["_exec_edge_score_sum"] += float(exec_edge_score) * qty_f
        if model_spread is not None and math.isfinite(model_spread):
            item["_model_spread_sum"] += float(model_spread) * qty_f
        if spread is not None and math.isfinite(spread):
            item["_spread_sum"] += float(spread) * qty_f
        if q_entry is not None and math.isfinite(q_entry):
            item["_q_entry_sum"] += float(q_entry) * qty_f
        if fill_avg_price is not None and math.isfinite(fill_avg_price):
            item["_fill_price_sum"] += float(fill_avg_price) * qty_f
        if trend_down:
            item["_trend_down_count"] += 1
        if trend_unknown:
            item["_trend_unknown_count"] += 1

    out: Dict[str, Dict[str, Any]] = {}
    for strategy, item in agg.items():
        qty_sum = float(item.get("_qty_sum") or 0.0)
        sample_count = int(item.get("entry_fact_sample_count") or 0)
        pos_count = int(item.get("entry_fact_pos_exec_edge_count") or 0)
        out[strategy] = {
            "entry_fact_order_count": int(item.get("entry_fact_order_count") or 0),
            "entry_fact_sample_count": sample_count,
            "entry_fact_pos_exec_edge_count": pos_count,
            "entry_fact_pos_exec_edge_ratio": (pos_count / sample_count) if sample_count > 0 else None,
            "entry_fact_avg_exec_edge_entry": (float(item.get("_exec_edge_entry_sum") or 0.0) / qty_sum) if qty_sum > TIME_EDGE_Q_EPS else None,
            "entry_fact_avg_exec_edge_score": (float(item.get("_exec_edge_score_sum") or 0.0) / qty_sum) if qty_sum > TIME_EDGE_Q_EPS else None,
            "entry_fact_avg_model_spread": (float(item.get("_model_spread_sum") or 0.0) / qty_sum) if qty_sum > TIME_EDGE_Q_EPS else None,
            "entry_fact_avg_spread": (float(item.get("_spread_sum") or 0.0) / qty_sum) if qty_sum > TIME_EDGE_Q_EPS else None,
            "entry_fact_avg_q_entry": (float(item.get("_q_entry_sum") or 0.0) / qty_sum) if qty_sum > TIME_EDGE_Q_EPS else None,
            "entry_fact_avg_fill_price": (float(item.get("_fill_price_sum") or 0.0) / qty_sum) if qty_sum > TIME_EDGE_Q_EPS else None,
            "entry_fact_trend_down_ratio": (float(item.get("_trend_down_count") or 0.0) / sample_count) if sample_count > 0 else None,
            "entry_fact_trend_unknown_ratio": (float(item.get("_trend_unknown_count") or 0.0) / sample_count) if sample_count > 0 else None,
        }
    return out


def _ensure_orphan_fill_tables(conn: sqlite3.Connection) -> None:
    """
    SSOT storage for classifying fills that exist in edge_trade_fills but can't be tied to auto_orders(order_id).

    Why: these orphan fills otherwise pollute strategy reports as an "unknown" bucket or hide real provenance issues.
    """
    cur = conn.cursor()
    cur.execute(
        """
        CREATE TABLE IF NOT EXISTS orphan_fill_classifications (
            trade_id TEXT PRIMARY KEY,
            fill_id INTEGER,
            order_id TEXT,
            slug TEXT,
            event_date TEXT,
            outcome TEXT,
            outcome_side TEXT,
            trade_side TEXT,
            trade_time TEXT,
            created_at TEXT,
            trader_side TEXT,
            classification TEXT,
            note TEXT,
            classified_at TEXT
        )
        """
    )
    cur.execute(
        "CREATE INDEX IF NOT EXISTS idx_orphan_fill_classifications_classified_at ON orphan_fill_classifications(classified_at)"
    )
    cur.execute(
        "CREATE INDEX IF NOT EXISTS idx_orphan_fill_classifications_classification ON orphan_fill_classifications(classification)"
    )

    # Order-level inferred provenance for orphan fills (best-effort; may be empty).
    # Keying by order_id lets us attach multiple fills of the same order consistently.
    cur.execute(
        """
        CREATE TABLE IF NOT EXISTS orphan_order_attributions (
            order_id TEXT PRIMARY KEY,
            slug TEXT,
            event_date TEXT,
            outcome TEXT,
            outcome_side TEXT,
            trade_side TEXT,
            first_fill_time TEXT,
            last_fill_time TEXT,
            filled_qty REAL,
            vwap_price REAL,
            inferred_source TEXT,
            inferred_strategy TEXT,
            confidence REAL,
            note TEXT,
            evidence_json TEXT,
            attributed_at TEXT
        )
        """
    )
    cur.execute(
        "CREATE INDEX IF NOT EXISTS idx_orphan_order_attributions_attributed_at ON orphan_order_attributions(attributed_at)"
    )
    cur.execute(
        "CREATE INDEX IF NOT EXISTS idx_orphan_order_attributions_source ON orphan_order_attributions(inferred_source)"
    )


def compute_orphan_fill_stats(
    conn: sqlite3.Connection,
    days: int = 60,
    *,
    now_dt: Optional[datetime] = None,
    max_rows: int = 400,
    writeback: bool = False,
) -> Dict[str, Any]:
    """
    Re-stat + classify fills that can't be joined to auto_orders(order_id).

    Output is designed to be SSOT-friendly:
    - summary counts for dashboards
    - optional row list (bounded) for debugging / drill-down
    - optional writeback into orphan_fill_classifications for persistent provenance
    """
    try:
        days = int(days)
    except Exception:
        days = 60
    days = max(1, min(days, 3650))
    try:
        max_rows = int(max_rows)
    except Exception:
        max_rows = 400
    max_rows = max(0, min(max_rows, 2000))

    now_dt = now_dt if isinstance(now_dt, datetime) else datetime.now(timezone.utc)
    start_dt = now_dt - timedelta(days=days)
    start_text = start_dt.isoformat()

    auto_orders = query_auto_orders(conn, apply_cutoff=False)
    auto_order_ids = set(auto_orders.keys())

    mirror_order_ids: set[str] = set()
    try:
        cur = conn.cursor()
        cur.execute(
            """
            SELECT DISTINCT mirror_order_id
            FROM mirror_follow_trades
            WHERE mirror_order_id IS NOT NULL AND length(mirror_order_id) > 0
            """
        )
        mirror_order_ids = {str(r[0] or "") for r in cur.fetchall() if str(r[0] or "").strip()}
    except sqlite3.OperationalError:
        mirror_order_ids = set()

    edge_last_order_ids: set[str] = set()
    try:
        cur = conn.cursor()
        cur.execute(
            """
            SELECT DISTINCT last_order_id
            FROM edge_trades
            WHERE last_order_id IS NOT NULL AND length(last_order_id) > 0
            """
        )
        edge_last_order_ids = {str(r[0] or "") for r in cur.fetchall() if str(r[0] or "").strip()}
    except sqlite3.OperationalError:
        edge_last_order_ids = set()

    cur = conn.cursor()
    try:
        cur.execute(
            """
            SELECT id, trade_id, order_id, slug, event_date, outcome, outcome_side, trade_side,
                   price, size, fee, trade_time, created_at, raw_json
            FROM edge_trade_fills
            WHERE datetime(COALESCE(trade_time, created_at)) >= datetime(?)
            ORDER BY datetime(COALESCE(trade_time, created_at)) DESC, id DESC
            """,
            (start_text,),
        )
    except sqlite3.OperationalError as exc:
        return {"ok": False, "error": f"db_error:{exc.__class__.__name__}", "detail": str(exc), "days": days}

    def _to_utc_ts(dt: Optional[datetime]) -> Optional[float]:
        if not isinstance(dt, datetime):
            return None
        try:
            if dt.tzinfo is None:
                # Treat naive as local.
                local_tz = datetime.now().astimezone().tzinfo
                if local_tz is not None:
                    dt = dt.replace(tzinfo=local_tz)
            return dt.astimezone(timezone.utc).timestamp()
        except Exception:
            return None

    def _classify(row: sqlite3.Row) -> Tuple[str, str, str]:
        trade_id = str(row["trade_id"] or "").strip()
        order_id = str(row["order_id"] or "").strip()
        raw = row["raw_json"]
        trader_side = ""
        if isinstance(raw, str) and raw.strip():
            try:
                payload = json.loads(raw)
                trader_side = str(payload.get("trader_side") or "").strip().upper()
            except Exception:
                trader_side = ""

        # Synthetic fills (internal bookkeeping) have no order_id by design.
        if trade_id.startswith("residual_clear:"):
            return ("synthetic_residual_clear", trader_side, "trade_id_prefix")
        if trade_id.startswith("manual_clear:"):
            return ("synthetic_manual_clear", trader_side, "trade_id_prefix")

        if not order_id:
            return ("missing_order_id", trader_side, "")

        if order_id in mirror_order_ids:
            return ("mirror_follow_missing_auto_orders", trader_side, "mirror_follow_trades.mirror_order_id")
        if order_id in edge_last_order_ids:
            return ("local_position_ledger_last_order_id_missing_auto_orders", trader_side, "local_position_ledger.last_order_id")

        if trader_side == "TAKER":
            return ("orphan_order_taker_no_auto_order", trader_side, "")
        if trader_side == "MAKER":
            return ("orphan_order_maker_no_auto_order", trader_side, "")
        return ("orphan_order_unknown_no_auto_order", trader_side, "")

    total_in_window = 0
    orphan_total = 0
    class_counts: Dict[str, int] = {}
    trader_side_counts: Dict[str, int] = {}
    rows_out: List[Dict[str, Any]] = []
    write_rows: List[Tuple[Any, ...]] = []

    # Build order-level aggregates for optional inference attribution (keep lightweight).
    orphan_orders: Dict[str, Dict[str, Any]] = {}

    for row in cur.fetchall():
        total_in_window += 1
        order_id = str(row["order_id"] or "").strip()
        if order_id and order_id in auto_order_ids:
            continue
        orphan_total += 1
        cls, trader_side, note = _classify(row)
        class_counts[cls] = int(class_counts.get(cls) or 0) + 1
        ts_key = trader_side or "(missing)"
        trader_side_counts[ts_key] = int(trader_side_counts.get(ts_key) or 0) + 1

        if order_id:
            # Aggregate per order_id for later provenance inference (mirror/edge/decision backtraces).
            entry = orphan_orders.get(order_id)
            if entry is None:
                entry = {
                    "order_id": order_id,
                    "slug": str(row["slug"] or "").strip(),
                    "event_date": str(row["event_date"] or "").strip(),
                    "outcome": str(row["outcome"] or "").strip(),
                    "outcome_side": str(row["outcome_side"] or "").strip().upper(),
                    "trade_side": str(row["trade_side"] or "").strip().upper(),
                    "token_id": "",
                    "first_fill_time": "",
                    "last_fill_time": "",
                    "_first_ts": None,
                    "_last_ts": None,
                    "_qty_sum": 0.0,
                    "_notional_sum": 0.0,
                    "cls_hint": cls,
                    "trader_side": trader_side or "",
                }
                orphan_orders[order_id] = entry
            # Keep a best-effort "most informative" classification hint.
            if entry.get("cls_hint") in {"orphan_order_unknown_no_auto_order", "missing_order_id"} and cls:
                entry["cls_hint"] = cls
            if not entry.get("trader_side") and trader_side:
                entry["trader_side"] = trader_side
            qty = to_float(row["size"])
            px = to_float(row["price"])
            if qty is not None and math.isfinite(qty) and qty > 0:
                entry["_qty_sum"] = float(entry.get("_qty_sum") or 0.0) + float(qty)
                if px is not None and math.isfinite(px) and px > 0:
                    entry["_notional_sum"] = float(entry.get("_notional_sum") or 0.0) + float(px) * float(qty)
            t_text = str(row["trade_time"] or row["created_at"] or "").strip()
            if t_text:
                dt = parse_any_ts(t_text)
                ts = _to_utc_ts(dt)
                if ts is not None:
                    first_ts = entry.get("_first_ts")
                    last_ts = entry.get("_last_ts")
                    if first_ts is None or ts < float(first_ts):
                        entry["_first_ts"] = float(ts)
                        entry["first_fill_time"] = t_text
                    if last_ts is None or ts > float(last_ts):
                        entry["_last_ts"] = float(ts)
                        entry["last_fill_time"] = t_text
            raw_text = str(row["raw_json"] or "").strip()
            if raw_text and not str(entry.get("token_id") or "").strip():
                try:
                    payload = json.loads(raw_text)
                except Exception:
                    payload = None
                if isinstance(payload, dict):
                    tid = (
                        payload.get("token_id")
                        or payload.get("tokenId")
                        or payload.get("asset_id")
                        or payload.get("assetId")
                    )
                    tid_s = str(tid or "").strip()
                    if tid_s:
                        entry["token_id"] = tid_s

        if max_rows and len(rows_out) < max_rows:
            rows_out.append(
                {
                    "fill_id": int(row["id"] or 0),
                    "trade_id": str(row["trade_id"] or ""),
                    "order_id": str(row["order_id"] or ""),
                    "slug": str(row["slug"] or ""),
                    "event_date": str(row["event_date"] or ""),
                    "outcome": str(row["outcome"] or ""),
                    "outcome_side": str(row["outcome_side"] or ""),
                    "trade_side": str(row["trade_side"] or ""),
                    "price": to_float(row["price"]),
                    "size": to_float(row["size"]),
                    "fee": to_float(row["fee"]),
                    "trade_time": str(row["trade_time"] or ""),
                    "created_at": str(row["created_at"] or ""),
                    "trader_side": trader_side or "",
                    "classification": cls,
                    "note": note,
                }
            )
        if writeback:
            write_rows.append(
                (
                    str(row["trade_id"] or ""),
                    int(row["id"] or 0),
                    str(row["order_id"] or ""),
                    str(row["slug"] or ""),
                    str(row["event_date"] or ""),
                    str(row["outcome"] or ""),
                    str(row["outcome_side"] or ""),
                    str(row["trade_side"] or ""),
                    str(row["trade_time"] or ""),
                    str(row["created_at"] or ""),
                    trader_side or "",
                    cls,
                    note,
                    now_text(),
                )
            )

    # Best-effort provenance inference for orphan orders (does NOT affect strategy stats).
    inferred_by_order_id: Dict[str, Dict[str, Any]] = {}
    by_inferred_source: Dict[str, int] = {}
    if orphan_orders:
        # 1) Strong backtrace: auto_trade_decisions.details_json contains the order_id.
        decision_by_order_id: Dict[str, Dict[str, Any]] = {}
        decisions_by_key: Dict[Tuple[str, str, str, str], List[Dict[str, Any]]] = {}
        try:
            dcur = conn.cursor()
            dcur.execute(
                """
                SELECT run_date, slug, event_date, outcome, side, action, will_order, reason_codes_json, details_json, created_at
                FROM auto_trade_decisions
                WHERE datetime(created_at) >= datetime(?)
                  AND details_json LIKE '%"order_id"%'
                ORDER BY datetime(created_at) DESC, id DESC
                """,
                (start_text,),
            )
            for drow in dcur.fetchall():
                details_raw = str(drow["details_json"] or "").strip()
                if not details_raw:
                    continue
                try:
                    details = json.loads(details_raw)
                except Exception:
                    continue
                if not isinstance(details, dict):
                    continue
                oid = str(details.get("order_id") or "").strip()
                if not oid:
                    continue
                # Prefer will_order=1 and the latest created_at (query already DESC).
                if oid in decision_by_order_id:
                    continue
                strategy = str(details.get("strategy") or "").strip().lower()
                if not strategy:
                    strategy = "main"
                will_order = int(drow["will_order"] or 0)
                decision_by_order_id[oid] = {
                    "inferred_source": "auto_trade_decisions",
                    "inferred_strategy": strategy,
                    "confidence": 0.95 if will_order else 0.85,
                    "note": "matched details_json.order_id",
                    "evidence": {
                        "run_date": str(drow["run_date"] or ""),
                        "slug": str(drow["slug"] or ""),
                        "event_date": str(drow["event_date"] or ""),
                        "outcome": str(drow["outcome"] or ""),
                        "side": str(drow["side"] or ""),
                        "action": str(drow["action"] or ""),
                        "will_order": will_order,
                        "created_at": str(drow["created_at"] or ""),
                    },
                }
        except sqlite3.OperationalError:
            decision_by_order_id = {}

        # 1b) Medium backtrace: match a will_order=1 decision near the fill time for the same contract key.
        # This is intentionally "best-effort" and only used for UI/debugging (not strategy ROI stats).
        try:
            dcur = conn.cursor()
            dcur.execute(
                """
                SELECT run_date, slug, event_date, outcome, side, action, will_order, reason_codes_json, details_json, created_at
                FROM auto_trade_decisions
                WHERE datetime(created_at) >= datetime(?)
                  AND will_order = 1
                  AND (action LIKE 'entry%' OR action = 'entry')
                ORDER BY datetime(created_at) DESC, id DESC
                """,
                (start_text,),
            )
            for drow in dcur.fetchall():
                slug = str(drow["slug"] or "").strip()
                event_date = str(drow["event_date"] or "").strip()
                outcome = str(drow["outcome"] or "").strip()
                side = str(drow["side"] or "").strip().upper()
                if not slug or not event_date or not outcome or side not in {"YES", "NO"}:
                    continue
                created_at = str(drow["created_at"] or "").strip()
                ts = _to_utc_ts(parse_any_ts(created_at))
                if ts is None:
                    continue
                details_raw = str(drow["details_json"] or "").strip()
                details: Dict[str, Any] = {}
                if details_raw:
                    try:
                        loaded = json.loads(details_raw)
                        if isinstance(loaded, dict):
                            details = loaded
                    except Exception:
                        details = {}
                strategy = str(details.get("strategy") or "").strip().lower() or "main"
                token_id = str(
                    details.get("token_id")
                    or details.get("tokenId")
                    or details.get("asset_id")
                    or details.get("assetId")
                    or ""
                ).strip()
                decisions_by_key.setdefault((slug, event_date, outcome, side), []).append(
                    {
                        "strategy": strategy,
                        "token_id": token_id,
                        "created_at": created_at,
                        "_ts": float(ts),
                        "action": str(drow["action"] or ""),
                        "run_date": str(drow["run_date"] or ""),
                        "reason_codes_json": str(drow["reason_codes_json"] or ""),
                    }
                )
        except sqlite3.OperationalError:
            decisions_by_key = {}

        # 2) Fuzzy backtrace: mirror_follow_trades (when mirror_order_id is missing in DB but fills exist).
        mirror_rows: List[Dict[str, Any]] = []
        try:
            mcur = conn.cursor()
            mcur.execute(
                """
                SELECT id, source_address, source_trade_id, slug, event_date, outcome, outcome_side,
                       mirror_action, mirror_price, mirror_size, mirror_order_id, mirror_status, created_at
                FROM mirror_follow_trades
                WHERE datetime(created_at) >= datetime(?)
                ORDER BY datetime(created_at) DESC, id DESC
                """,
                (start_text,),
            )
            for mrow in mcur.fetchall():
                mirror_rows.append(
                    {
                        "id": int(mrow["id"] or 0),
                        "source_address": str(mrow["source_address"] or ""),
                        "source_trade_id": str(mrow["source_trade_id"] or ""),
                        "slug": str(mrow["slug"] or "").strip(),
                        "event_date": str(mrow["event_date"] or "").strip(),
                        "outcome": str(mrow["outcome"] or "").strip(),
                        "outcome_side": str(mrow["outcome_side"] or "").strip().upper(),
                        "mirror_action": str(mrow["mirror_action"] or "").strip().upper(),
                        "mirror_price": to_float(mrow["mirror_price"]),
                        "mirror_size": to_float(mrow["mirror_size"]),
                        "mirror_order_id": str(mrow["mirror_order_id"] or "").strip(),
                        "mirror_status": str(mrow["mirror_status"] or "").strip(),
                        "created_at": str(mrow["created_at"] or "").strip(),
                        "_ts": _to_utc_ts(parse_any_ts(str(mrow["created_at"] or "").strip())),
                    }
                )
        except sqlite3.OperationalError:
            mirror_rows = []

        # 3) Fuzzy backtrace: edge_trades activity near the fill time (older versions may not record auto_orders).
        edge_rows: List[Dict[str, Any]] = []
        try:
            ecur = conn.cursor()
            ecur.execute(
                """
                SELECT slug, event_date, outcome, side, state, last_order_id, last_action, last_action_at, entry_at, updated_at
                FROM edge_trades
                WHERE datetime(COALESCE(last_action_at, entry_at, updated_at)) >= datetime(?)
                ORDER BY datetime(COALESCE(last_action_at, entry_at, updated_at)) DESC, id DESC
                """,
                (start_text,),
            )
            for erow in ecur.fetchall():
                when_text = str(erow["last_action_at"] or erow["entry_at"] or erow["updated_at"] or "").strip()
                edge_rows.append(
                    {
                        "slug": str(erow["slug"] or "").strip(),
                        "event_date": str(erow["event_date"] or "").strip(),
                        "outcome": str(erow["outcome"] or "").strip(),
                        "side": str(erow["side"] or "").strip().upper(),
                        "state": str(erow["state"] or "").strip(),
                        "last_order_id": str(erow["last_order_id"] or "").strip(),
                        "last_action": str(erow["last_action"] or "").strip(),
                        "when": when_text,
                        "_ts": _to_utc_ts(parse_any_ts(when_text)),
                    }
                )
        except sqlite3.OperationalError:
            edge_rows = []

        # Index mirror + edge for simple lookups (keep small; windowed by days).
        mirror_by_key: Dict[Tuple[str, str, str, str, str], List[Dict[str, Any]]] = {}
        for m in mirror_rows:
            key = (m["slug"], m["event_date"], m["outcome"], m["outcome_side"], m["mirror_action"])
            mirror_by_key.setdefault(key, []).append(m)

        edge_by_key: Dict[Tuple[str, str, str, str], List[Dict[str, Any]]] = {}
        for e in edge_rows:
            key = (e["slug"], e["event_date"], e["outcome"], e["side"])
            edge_by_key.setdefault(key, []).append(e)

        for oid, o in orphan_orders.items():
            cls_hint = str(o.get("cls_hint") or "")
            trader_side = str(o.get("trader_side") or "").upper()
            # Focus on the noisy bucket the user cares about (taker orphan orders).
            if cls_hint != "orphan_order_taker_no_auto_order" and trader_side != "TAKER":
                continue

            # a) Decision backtrace wins.
            dec = decision_by_order_id.get(oid)
            if isinstance(dec, dict):
                inferred_by_order_id[oid] = dec
                src = str(dec.get("inferred_source") or "auto_trade_decisions")
                by_inferred_source[src] = int(by_inferred_source.get(src) or 0) + 1
                continue

            # a2) Match a nearby will_order=1 decision (medium confidence).
            key4 = (
                str(o.get("slug") or "").strip(),
                str(o.get("event_date") or "").strip(),
                str(o.get("outcome") or "").strip(),
                str(o.get("outcome_side") or "").strip().upper(),
            )
            first_ts = o.get("_first_ts")
            last_ts = o.get("_last_ts")
            if first_ts is not None and last_ts is not None and decisions_by_key:
                cand_list = decisions_by_key.get(key4) or []
                if cand_list:
                    tok = str(o.get("token_id") or "").strip()
                    best_d: Optional[Tuple[float, Dict[str, Any]]] = None
                    for d in cand_list:
                        dts = d.get("_ts")
                        if dts is None:
                            continue
                        # Window: [-10m, +30m] around fills (same as mirror fuzzy).
                        if dts < float(first_ts) - 600 or dts > float(last_ts) + 1800:
                            continue
                        time_pen = abs(float(dts) - float(first_ts)) / 120.0  # 2-minute units
                        token_pen = 0.0
                        dtok = str(d.get("token_id") or "").strip()
                        if tok and dtok and tok != dtok:
                            token_pen = 1.0
                        score = float(time_pen) + float(token_pen)
                        if best_d is None or score < best_d[0]:
                            best_d = (score, d)
                    if best_d is not None:
                        score, d = best_d
                        dt_min = abs(float(d.get("_ts") or 0.0) - float(first_ts)) / 60.0
                        token_match = bool(tok and str(d.get("token_id") or "").strip() and tok == str(d.get("token_id") or "").strip())
                        conf = 0.72 - 0.03 * float(dt_min)
                        if token_match:
                            conf += 0.10
                        conf = max(0.45, min(0.82, conf))
                        inferred_by_order_id[oid] = {
                            "inferred_source": "decision_near_fill",
                            "inferred_strategy": str(d.get("strategy") or "main"),
                            "confidence": conf,
                            "note": "matched will_order=1 decision near fills",
                            "evidence": {
                                "decision_created_at": str(d.get("created_at") or ""),
                                "decision_run_date": str(d.get("run_date") or ""),
                                "decision_action": str(d.get("action") or ""),
                                "token_match": bool(token_match),
                                "decision_token_id": str(d.get("token_id") or ""),
                            },
                        }
                        by_inferred_source["decision_near_fill"] = int(by_inferred_source.get("decision_near_fill") or 0) + 1
                        continue

            # b) Mirror-follow fuzzy match (only if this order_id isn't already a known mirror_order_id).
            key = (
                str(o.get("slug") or ""),
                str(o.get("event_date") or ""),
                str(o.get("outcome") or ""),
                str(o.get("outcome_side") or "").upper(),
                str(o.get("trade_side") or "").upper(),
            )
            candidates = mirror_by_key.get(key) or []
            first_ts = o.get("_first_ts")
            last_ts = o.get("_last_ts")
            qty_sum = float(o.get("_qty_sum") or 0.0)
            best: Optional[Tuple[float, Dict[str, Any]]] = None
            if candidates and first_ts is not None and last_ts is not None:
                for m in candidates:
                    mts = m.get("_ts")
                    if mts is None:
                        continue
                    # time window: [-10m, +30m] around fills
                    if mts < float(first_ts) - 600 or mts > float(last_ts) + 1800:
                        continue
                    msz = m.get("mirror_size")
                    # prefer close size (if present)
                    size_pen = 0.0
                    if isinstance(msz, float) and math.isfinite(msz) and msz > 0 and qty_sum > 0:
                        size_pen = abs(msz - qty_sum) / max(qty_sum, 1e-9)
                    time_pen = abs(mts - float(first_ts)) / 300.0  # 5-minute units
                    score = float(size_pen) + float(time_pen)
                    if best is None or score < best[0]:
                        best = (score, m)
            if best is not None and best[1].get("mirror_order_id") in {"", None}:
                score, m = best
                conf = max(0.4, min(0.8, 0.75 - 0.15 * float(score)))
                inferred_by_order_id[oid] = {
                    "inferred_source": "mirror_follow_fuzzy",
                    "inferred_strategy": "mirror_follow",
                    "confidence": conf,
                    "note": "matched slug/outcome/side and created_at near fills",
                    "evidence": {
                        "mirror_trade_id": m.get("id"),
                        "source_address": m.get("source_address"),
                        "source_trade_id": m.get("source_trade_id"),
                        "mirror_status": m.get("mirror_status"),
                        "created_at": m.get("created_at"),
                    },
                }
                by_inferred_source["mirror_follow_fuzzy"] = int(by_inferred_source.get("mirror_follow_fuzzy") or 0) + 1
                continue

            # c) Edge-trades fuzzy match.
            ekey = (
                str(o.get("slug") or ""),
                str(o.get("event_date") or ""),
                str(o.get("outcome") or ""),
                str(o.get("outcome_side") or "").upper(),
            )
            e_candidates = edge_by_key.get(ekey) or []
            best_e: Optional[Tuple[float, Dict[str, Any]]] = None
            if e_candidates and first_ts is not None:
                for e in e_candidates:
                    ets = e.get("_ts")
                    if ets is None:
                        continue
                    if abs(float(ets) - float(first_ts)) > 900:  # 15m window
                        continue
                    score = abs(float(ets) - float(first_ts)) / 60.0  # minutes
                    if best_e is None or score < best_e[0]:
                        best_e = (score, e)
            if best_e is not None:
                score, e = best_e
                conf = max(0.35, min(0.7, 0.65 - 0.02 * float(score)))
                inferred_by_order_id[oid] = {
                    "inferred_source": "local_position_ledger_fuzzy",
                    "inferred_strategy": "main",
                    "confidence": conf,
                    "note": "matched local position ledger activity near fills",
                    "evidence": {
                        "state": e.get("state"),
                        "last_action": e.get("last_action"),
                        "when": e.get("when"),
                        "last_order_id": e.get("last_order_id"),
                    },
                }
                by_inferred_source["local_position_ledger_fuzzy"] = int(
                    by_inferred_source.get("local_position_ledger_fuzzy") or 0
                ) + 1

    # Attach inference to sample rows for UI drill-down.
    if inferred_by_order_id and rows_out:
        for item in rows_out:
            oid = str(item.get("order_id") or "").strip()
            inf = inferred_by_order_id.get(oid)
            if not isinstance(inf, dict):
                continue
            item["inferred_source"] = str(inf.get("inferred_source") or "")
            item["inferred_strategy"] = str(inf.get("inferred_strategy") or "")
            item["inferred_confidence"] = to_float(inf.get("confidence"))
            item["inferred_note"] = str(inf.get("note") or "")

    if writeback:
        try:
            _ensure_orphan_fill_tables(conn)
            cur = conn.cursor()
            cur.executemany(
                """
                INSERT OR REPLACE INTO orphan_fill_classifications (
                    trade_id, fill_id, order_id, slug, event_date, outcome, outcome_side, trade_side,
                    trade_time, created_at, trader_side, classification, note, classified_at
                ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                """,
                write_rows,
            )

            # Persist order-level inference (best-effort). This is SSOT for UI/debugging only.
            if inferred_by_order_id and orphan_orders:
                order_rows: List[Tuple[Any, ...]] = []
                for oid, inf in inferred_by_order_id.items():
                    o = orphan_orders.get(oid) or {}
                    qty_sum = float(o.get("_qty_sum") or 0.0)
                    notional = float(o.get("_notional_sum") or 0.0)
                    vwap = (notional / qty_sum) if qty_sum > TIME_EDGE_Q_EPS else None
                    order_rows.append(
                        (
                            oid,
                            str(o.get("slug") or ""),
                            str(o.get("event_date") or ""),
                            str(o.get("outcome") or ""),
                            str(o.get("outcome_side") or ""),
                            str(o.get("trade_side") or ""),
                            str(o.get("first_fill_time") or ""),
                            str(o.get("last_fill_time") or ""),
                            qty_sum,
                            float(vwap) if vwap is not None and math.isfinite(vwap) else None,
                            str(inf.get("inferred_source") or ""),
                            str(inf.get("inferred_strategy") or ""),
                            to_float(inf.get("confidence")),
                            str(inf.get("note") or ""),
                            json.dumps(inf.get("evidence") or {}, ensure_ascii=False),
                            now_text(),
                        )
                    )
                cur.executemany(
                    """
                    INSERT OR REPLACE INTO orphan_order_attributions (
                        order_id, slug, event_date, outcome, outcome_side, trade_side,
                        first_fill_time, last_fill_time, filled_qty, vwap_price,
                        inferred_source, inferred_strategy, confidence, note, evidence_json, attributed_at
                    ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                    """,
                    order_rows,
                )
        except Exception:
            # Best-effort persistence; reporting must still work without write access.
            pass

    return {
        "ok": True,
        "days": days,
        "window_start": start_text,
        "generated_at": now_text(),
        "fills_in_window": int(total_in_window),
        "orphan_fill_count": int(orphan_total),
        "by_class": dict(sorted(class_counts.items(), key=lambda kv: (-int(kv[1] or 0), str(kv[0] or "")))),
        "by_trader_side": dict(sorted(trader_side_counts.items(), key=lambda kv: (-int(kv[1] or 0), str(kv[0] or "")))),
        "by_inferred_source": dict(sorted(by_inferred_source.items(), key=lambda kv: (-int(kv[1] or 0), str(kv[0] or "")))),
        "rows": rows_out,
    }

    run_date_norm = str(run_date or "").strip()
    run_date_day = date_from_any(run_date_norm) if run_date_norm else None
    if run_date_day:
        start_date = run_date_day
        end_date = run_date_day
    else:
        start_date, end_date = resolve_stats_range(conn, days, require_settlement=False)
    start_text = start_date.isoformat()
    end_text = end_date.isoformat()

    # strategy -> aggregate
    agg: Dict[str, Dict[str, Any]] = {}

    def _ensure(strategy: str) -> Dict[str, Any]:
        k = str(strategy or "").strip().lower() or "main"
        entry = agg.get(k)
        if entry is None:
            entry = {
                "entry_fact_order_count": 0,
                "entry_fact_sample_count": 0,
                "entry_fact_pos_exec_edge_count": 0,
                "_qty_sum": 0.0,
                "_exec_edge_entry_sum": 0.0,
                "_exec_edge_score_sum": 0.0,
                "_model_spread_sum": 0.0,
                "_spread_sum": 0.0,
                "_q_entry_sum": 0.0,
                "_fill_price_sum": 0.0,
                "_trend_down_count": 0,
                "_trend_unknown_count": 0,
            }
            agg[k] = entry
        return entry

    def _find_outcome_row(fact_payload: Dict[str, Any], outcome_label: str) -> Optional[Dict[str, Any]]:
        dist = fact_payload.get("distribution")
        if not isinstance(dist, list) or not dist:
            return None
        out_label = str(outcome_label or "").strip()
        if not out_label:
            return None
        for row in dist:
            if not isinstance(row, dict):
                continue
            if str(row.get("outcome") or "").strip() == out_label:
                return row
        return None

    cur = conn.cursor()
    try:
        cur.execute(
            """
            SELECT
              o.order_id,
              o.slug,
              o.event_date,
              o.outcome,
              o.side,
              o.strategy,
              o.created_at,
              MIN(COALESCE(f.trade_time, f.created_at)) AS first_fill_time,
              SUM(COALESCE(f.size, 0)) AS filled_qty,
              CASE
                WHEN SUM(COALESCE(f.size, 0)) > 0 THEN SUM(COALESCE(f.price, 0) * COALESCE(f.size, 0)) / SUM(COALESCE(f.size, 0))
                ELSE NULL
              END AS fill_avg_price
            FROM auto_orders o
            JOIN edge_trade_fills f ON f.order_id = o.order_id
            WHERE o.action = 'entry'
              AND o.event_date BETWEEN ? AND ?
            GROUP BY o.order_id
            """,
            (start_text, end_text),
        )
    except sqlite3.OperationalError:
        return {}

    fact_cur = conn.cursor()
    for row in cur.fetchall():
        created_text = str(row["created_at"] or "").strip()
        if created_text and is_before_stats_cutoff(created_text):
            continue
        strategy = _resolve_entry_strategy(row)
        entry = _ensure(strategy)
        entry["entry_fact_order_count"] += 1

        first_fill_time = str(row["first_fill_time"] or "").strip()
        if not first_fill_time:
            continue
        slug = str(row["slug"] or "").strip()
        event_date = str(row["event_date"] or "").strip()
        outcome = str(row["outcome"] or "").strip()
        side = str(row["side"] or "").strip().upper()
        if not slug or not event_date or not outcome or side not in {"YES", "NO"}:
            continue

        filled_qty = to_float(row["filled_qty"])
        if filled_qty is None or not math.isfinite(filled_qty) or filled_qty <= TIME_EDGE_Q_EPS:
            continue

        fill_avg_price = to_float(row["fill_avg_price"])
        if fill_avg_price is not None and (not math.isfinite(fill_avg_price) or fill_avg_price <= 0):
            fill_avg_price = None

        # Facts snapshot aligned to first fill time.
        try:
            fact_cur.execute(
                """
                SELECT fact_json
                FROM event_fact_history
                WHERE slug = ? AND event_date = ? AND fact_as_of <= ?
                ORDER BY fact_as_of DESC
                LIMIT 1
                """,
                (slug, event_date, first_fill_time),
            )
        except sqlite3.OperationalError:
            continue
        fact_row = fact_cur.fetchone()
        if not fact_row:
            continue
        fact_payload = safe_json_loads(fact_row["fact_json"])
        if not isinstance(fact_payload, dict) or not fact_payload:
            continue
        out_row = _find_outcome_row(fact_payload, outcome)
        if not out_row:
            continue

        entry["entry_fact_sample_count"] += 1
        qty = float(filled_qty)
        entry["_qty_sum"] += qty

        if side == "YES":
            exec_edge_entry = to_float(out_row.get("exec_edge_entry_yes"))
            exec_edge_score = to_float(out_row.get("exec_edge_score_yes"))
            q_entry = to_float(out_row.get("q_entry"))
            spread = to_float(out_row.get("spread"))
            trend_down = bool(out_row.get("trend_down_yes"))
            trend_unknown = bool(out_row.get("trend_unknown_yes"))
        else:
            exec_edge_entry = to_float(out_row.get("exec_edge_entry_no"))
            exec_edge_score = to_float(out_row.get("exec_edge_score_no"))
            q_entry = to_float(out_row.get("q_entry_no"))
            spread = to_float(out_row.get("spread_no"))
            trend_down = bool(out_row.get("trend_down_no"))
            trend_unknown = bool(out_row.get("trend_unknown_no"))

        model_spread = to_float(out_row.get("model_spread"))

        if exec_edge_entry is not None and math.isfinite(exec_edge_entry):
            entry["_exec_edge_entry_sum"] += float(exec_edge_entry) * qty
            if exec_edge_entry > 0:
                entry["entry_fact_pos_exec_edge_count"] += 1
        if exec_edge_score is not None and math.isfinite(exec_edge_score):
            entry["_exec_edge_score_sum"] += float(exec_edge_score) * qty
        if model_spread is not None and math.isfinite(model_spread):
            entry["_model_spread_sum"] += float(model_spread) * qty
        if spread is not None and math.isfinite(spread):
            entry["_spread_sum"] += float(spread) * qty
        if q_entry is not None and math.isfinite(q_entry):
            entry["_q_entry_sum"] += float(q_entry) * qty
        if fill_avg_price is not None and math.isfinite(fill_avg_price):
            entry["_fill_price_sum"] += float(fill_avg_price) * qty
        if trend_down:
            entry["_trend_down_count"] += 1
        if trend_unknown:
            entry["_trend_unknown_count"] += 1

    out: Dict[str, Dict[str, Any]] = {}
    for strategy, entry in agg.items():
        qty_sum = float(entry.get("_qty_sum") or 0.0)
        sample_count = int(entry.get("entry_fact_sample_count") or 0)
        pos_count = int(entry.get("entry_fact_pos_exec_edge_count") or 0)
        out_entry = {
            "entry_fact_order_count": int(entry.get("entry_fact_order_count") or 0),
            "entry_fact_sample_count": sample_count,
            "entry_fact_pos_exec_edge_count": pos_count,
            "entry_fact_pos_exec_edge_ratio": (pos_count / sample_count) if sample_count > 0 else None,
            "entry_fact_avg_exec_edge_entry": (float(entry.get("_exec_edge_entry_sum") or 0.0) / qty_sum) if qty_sum > TIME_EDGE_Q_EPS else None,
            "entry_fact_avg_exec_edge_score": (float(entry.get("_exec_edge_score_sum") or 0.0) / qty_sum) if qty_sum > TIME_EDGE_Q_EPS else None,
            "entry_fact_avg_model_spread": (float(entry.get("_model_spread_sum") or 0.0) / qty_sum) if qty_sum > TIME_EDGE_Q_EPS else None,
            "entry_fact_avg_spread": (float(entry.get("_spread_sum") or 0.0) / qty_sum) if qty_sum > TIME_EDGE_Q_EPS else None,
            "entry_fact_avg_q_entry": (float(entry.get("_q_entry_sum") or 0.0) / qty_sum) if qty_sum > TIME_EDGE_Q_EPS else None,
            "entry_fact_avg_fill_price": (float(entry.get("_fill_price_sum") or 0.0) / qty_sum) if qty_sum > TIME_EDGE_Q_EPS else None,
            "entry_fact_trend_down_ratio": (float(entry.get("_trend_down_count") or 0.0) / sample_count) if sample_count > 0 else None,
            "entry_fact_trend_unknown_ratio": (float(entry.get("_trend_unknown_count") or 0.0) / sample_count) if sample_count > 0 else None,
        }
        out[strategy] = out_entry
    return out


def compute_edge_waterfall(
    conn: sqlite3.Connection,
    days: int,
    run_date: str = "",
    *,
    include_mirror: bool = False,
    max_contracts: int = 5000,
) -> Dict[str, Any]:
    """
    Trade monetization diagnostics (SSOT) for UI.

    A "waterfall" explains:
      q_entry -> exec_entry_price/cost -> exec_edge_entry -> realized (legacy execution ledger)

    We dedupe to the earliest filled entry per (strategy, contract_key) to avoid double counting.
    """

    def _norm_strategy(raw: Any) -> str:
        s = str(raw or "").strip().lower()
        if not s or s == "exit":
            return "main"
        return s

    def _norm_side(raw: Any) -> str:
        s = str(raw or "").strip().upper()
        return s if s in {"YES", "NO"} else ""

    run_date_norm = str(run_date or "").strip()
    run_date_day = date_from_any(run_date_norm) if run_date_norm else None
    if run_date_day:
        start_date = run_date_day
        end_date = run_date_day
    else:
        start_date, end_date = resolve_stats_range(conn, days, require_settlement=False)
    start_text = start_date.isoformat()
    end_text = end_date.isoformat()

    excluded = set()
    if not include_mirror:
        excluded |= {"mirror_follow", "mirror_follow_improve"}

    # First pass: find earliest filled entry per (strategy, contract_key).
    # contract_key is (slug,event_date,outcome,side)
    contract_first: Dict[Tuple[str, str, str, str, str], Dict[str, Any]] = {}
    # Track if a contract had entries from multiple strategies (avoid mis-attributing realized).
    contract_strategies: Dict[Tuple[str, str, str, str], set] = {}

    cur = conn.cursor()
    try:
        cur.execute(
            """
            SELECT
              o.order_id,
              o.slug,
              o.event_date,
              o.outcome,
              o.side,
              o.strategy,
              MIN(COALESCE(f.trade_time, f.created_at)) AS first_fill_time,
              SUM(COALESCE(f.size, 0)) AS filled_qty,
              CASE
                WHEN SUM(COALESCE(f.size, 0)) > 0 THEN SUM(COALESCE(f.price, 0) * COALESCE(f.size, 0)) / SUM(COALESCE(f.size, 0))
                ELSE NULL
              END AS fill_avg_price
            FROM auto_orders o
            JOIN edge_trade_fills f ON f.order_id = o.order_id
            WHERE o.action = 'entry'
              AND o.event_date BETWEEN ? AND ?
            GROUP BY o.order_id
            ORDER BY datetime(first_fill_time) ASC
            """,
            (start_text, end_text),
        )
    except sqlite3.OperationalError:
        return {"window": {"start": start_text, "end": end_text}, "strategies": {}, "bins": []}

    for row in cur.fetchall():
        created_text = str(row["first_fill_time"] or "").strip()
        if created_text and is_before_stats_cutoff(created_text):
            continue
        slug = str(row["slug"] or "").strip()
        event_date = str(row["event_date"] or "").strip()
        outcome = str(row["outcome"] or "").strip()
        side = _norm_side(row["side"])
        if not slug or not event_date or not outcome or not side:
            continue
        strategy = _norm_strategy(row["strategy"])
        ck = (slug, event_date, outcome, side)
        # Track *all* entry strategies touching this contract (including excluded),
        # so realized PnL isn't silently contaminated by mirror trades.
        contract_strategies.setdefault(ck, set()).add(strategy)
        if strategy in excluded:
            continue
        first_fill_time = str(row["first_fill_time"] or "").strip()
        if not first_fill_time:
            continue
        qty = to_float(row["filled_qty"])
        if qty is None or not math.isfinite(qty) or qty <= TIME_EDGE_Q_EPS:
            continue
        fill_avg = to_float(row["fill_avg_price"])
        if fill_avg is not None and (not math.isfinite(fill_avg) or fill_avg <= 0):
            fill_avg = None

        k = (strategy, slug, event_date, outcome, side)
        existing = contract_first.get(k)
        if existing is None or str(existing.get("first_fill_time") or "") > first_fill_time:
            contract_first[k] = {
                "strategy": strategy,
                "slug": slug,
                "event_date": event_date,
                "outcome": outcome,
                "side": side,
                "first_fill_time": first_fill_time,
                "filled_qty": float(qty),
                "fill_avg_price": fill_avg,
            }
        if max_contracts > 0 and len(contract_first) >= max_contracts:
            break

    # Precompute realized PnL/cost per contract from fills (SSOT).
    #
    # Why: edge_trades.realized_pnl can lag / miss settlement closure; strategy stats SSOT uses fills FIFO.
    # This keeps "edge waterfall" consistent with strategy performance statistics.
    target_contracts = {
        (
            str(v.get("slug") or "").strip(),
            str(v.get("event_date") or "").strip(),
            str(v.get("outcome") or "").strip(),
            str(v.get("side") or "").strip(),
        )
        for v in contract_first.values()
        if isinstance(v, dict)
    }
    target_events = {(ck[0], ck[1]) for ck in target_contracts if ck and ck[0] and ck[1]}

    settlement_by_event: Dict[Tuple[str, str], str] = {}
    if target_events:
        ev_cur = conn.cursor()
        try:
            # Prefer the latest known settlement_actual per (slug,event_date).
            ev_cur.execute(
                """
                SELECT slug, event_date, settlement_actual, MAX(created_at) AS max_created_at
                FROM event_runs
                WHERE event_date BETWEEN ? AND ?
                  AND settlement_actual IS NOT NULL
                  AND settlement_actual != ''
                GROUP BY slug, event_date
                """,
                (start_text, end_text),
            )
            for row in ev_cur.fetchall():
                slug = str(row[0] or "").strip()
                event_date = str(row[1] or "").strip()
                if (slug, event_date) not in target_events:
                    continue
                actual = str(row[2] or "").strip()
                if actual:
                    settlement_by_event[(slug, event_date)] = actual
        except sqlite3.OperationalError:
            settlement_by_event = {}

    # Contract -> list of fills (chronological). Each fill tuple is: (trade_side, price, size, fee).
    contract_fills: Dict[Tuple[str, str, str, str], List[Tuple[str, float, float, float]]] = {}
    fill_cur = conn.cursor()
    try:
        fill_cur.execute(
            """
            SELECT
              slug,
              event_date,
              outcome,
              outcome_side,
              trade_side,
              price,
              size,
              fee,
              COALESCE(trade_time, created_at) AS ts
            FROM edge_trade_fills
            WHERE date(event_date) BETWEEN ? AND ?
            ORDER BY datetime(ts) ASC, id ASC
            """,
            (start_text, end_text),
        )
        for row in fill_cur.fetchall():
            slug = str(row[0] or "").strip()
            event_date = str(row[1] or "").strip()
            outcome = str(row[2] or "").strip()
            side = _norm_side(row[3])
            if not slug or not event_date or not outcome or not side:
                continue
            ck = (slug, event_date, outcome, side)
            if ck not in target_contracts:
                continue
            trade_side = str(row[4] or "").strip().upper()
            if trade_side not in {"BUY", "SELL"}:
                continue
            price = to_float(row[5])
            size = to_float(row[6])
            fee = to_float(row[7]) or 0.0
            if (
                price is None
                or size is None
                or not math.isfinite(price)
                or not math.isfinite(size)
                or price <= 0
                or size <= TIME_EDGE_Q_EPS
            ):
                continue
            if not math.isfinite(fee):
                fee = 0.0
            contract_fills.setdefault(ck, []).append((trade_side, float(price), float(size), float(fee)))
    except sqlite3.OperationalError:
        contract_fills = {}

    def _realized_from_fills(
        fills: List[Tuple[str, float, float, float]],
        *,
        settlement_actual: str = "",
        outcome: str = "",
        side: str = "",
    ) -> Tuple[float, float, bool]:
        # FIFO lots via avg-cost accumulator (same as the loss-streak diagnostic in scan_weather_market.py).
        pos = 0.0
        avg = 0.0
        realized_pnl = 0.0
        realized_cost = 0.0
        for trade_side, price, size, fee in fills:
            fee_eff = max(0.0, float(fee or 0.0))
            if trade_side == "BUY":
                new_pos = pos + float(size)
                if new_pos <= TIME_EDGE_Q_EPS:
                    continue
                total_cost = (avg * pos) + (float(price) * float(size)) + fee_eff
                pos = new_pos
                avg = total_cost / new_pos
                continue
            # SELL
            if pos <= TIME_EDGE_Q_EPS:
                continue
            close_size = min(float(size), pos)
            realized_pnl += (float(price) - avg) * close_size - fee_eff
            realized_cost += avg * close_size
            pos -= close_size
            if pos <= TIME_EDGE_Q_EPS:
                pos = 0.0
                avg = 0.0

        closed = pos <= TIME_EDGE_Q_EPS
        actual = str(settlement_actual or "").strip()
        if not closed and actual and outcome:
            sd = str(side or "").strip().upper()
            win = (outcome == actual) if sd == "YES" else (outcome != actual)
            payout = 1.0 if win else 0.0
            close_size = pos
            realized_pnl += (payout - avg) * close_size
            realized_cost += avg * close_size
            pos = 0.0
            avg = 0.0
            closed = True
        return float(realized_pnl), float(realized_cost), bool(closed)

    # Helpers for facts alignment.
    fact_cur = conn.cursor()

    def _fact_row_at(slug: str, event_date: str, ts_text: str) -> Optional[Dict[str, Any]]:
        try:
            fact_cur.execute(
                """
                SELECT fact_json
                FROM event_fact_history
                WHERE slug = ? AND event_date = ? AND fact_as_of <= ?
                ORDER BY fact_as_of DESC
                LIMIT 1
                """,
                (slug, event_date, ts_text),
            )
        except sqlite3.OperationalError:
            return None
        r = fact_cur.fetchone()
        if not r:
            return None
        payload = safe_json_loads(r["fact_json"])
        return payload if isinstance(payload, dict) else None

    def _dist_row(fact_payload: Dict[str, Any], outcome_label: str) -> Optional[Dict[str, Any]]:
        dist = fact_payload.get("distribution")
        if not isinstance(dist, list) or not dist:
            return None
        target = str(outcome_label or "").strip()
        if not target:
            return None
        for item in dist:
            if isinstance(item, dict) and str(item.get("outcome") or "").strip() == target:
                return item
        return None

    bins = [
        {"id": "le_0c", "label": "<=0c", "min": None, "max": 0.0},
        {"id": "0_2c", "label": "0-2c", "min": 0.0, "max": 0.02},
        {"id": "2_4c", "label": "2-4c", "min": 0.02, "max": 0.04},
        {"id": "4_6c", "label": "4-6c", "min": 0.04, "max": 0.06},
        {"id": "6_10c", "label": "6-10c", "min": 0.06, "max": 0.10},
        {"id": "gt_10c", "label": ">10c", "min": 0.10, "max": None},
    ]

    def _bin_for(exec_edge_entry: Optional[float]) -> str:
        v = to_float(exec_edge_entry)
        if v is None or not math.isfinite(v):
            return "na"
        for b in bins:
            bmin = b["min"]
            bmax = b["max"]
            if bmin is None and bmax is not None and v <= bmax + TIME_EDGE_Q_EPS:
                return str(b["id"])
            if bmax is None and bmin is not None and v > bmin + TIME_EDGE_Q_EPS:
                return str(b["id"])
            if bmin is not None and bmax is not None and v > bmin + TIME_EDGE_Q_EPS and v <= bmax + TIME_EDGE_Q_EPS:
                return str(b["id"])
        return "na"

    def _init_bucket() -> Dict[str, Any]:
        return {
            "contracts": 0,
            "filled_qty": 0.0,
            "fact_contracts": 0,
            "exec_fallback_contracts": 0,
            "q_entry_wsum": 0.0,
            "q_entry_wqty": 0.0,
            "exec_entry_price_wsum": 0.0,
            "exec_entry_price_wqty": 0.0,
            "exec_entry_cost_wsum": 0.0,
            "exec_entry_cost_wqty": 0.0,
            "exec_edge_entry_wsum": 0.0,
            "exec_edge_entry_wqty": 0.0,
            "fill_price_wsum": 0.0,
            "fill_price_wqty": 0.0,
            "slippage_wsum": 0.0,
            "slippage_wqty": 0.0,
            "realized_pnl": 0.0,
            "realized_cost": 0.0,
            "realized_closed": 0,
            "multi_strategy_contracts": 0,
        }

    out: Dict[str, Any] = {
        "window": {"start": start_text, "end": end_text},
        "strategies": {},
        "bins": bins,
    }

    for rec in contract_first.values():
        strategy = str(rec.get("strategy") or "")
        slug = str(rec.get("slug") or "")
        event_date = str(rec.get("event_date") or "")
        outcome = str(rec.get("outcome") or "")
        side = str(rec.get("side") or "")
        qty = float(rec.get("filled_qty") or 0.0)
        first_fill_time = str(rec.get("first_fill_time") or "")
        if qty <= TIME_EDGE_Q_EPS or not first_fill_time:
            continue
        strat_entry = out["strategies"].setdefault(strategy, {"all": _init_bucket(), "by_bin": {}})
        all_bucket = strat_entry["all"]
        all_bucket["contracts"] += 1
        all_bucket["filled_qty"] += qty

        # Facts snapshot.
        fact_payload = _fact_row_at(slug, event_date, first_fill_time)
        dist_row = _dist_row(fact_payload, outcome) if fact_payload else None
        q_entry = None
        exec_entry_price = None
        exec_entry_cost = None
        exec_edge_entry = None
        exec_fallback_used = False
        if isinstance(dist_row, dict):
            all_bucket["fact_contracts"] += 1
            if side == "YES":
                q_entry = to_float(dist_row.get("q_entry"))
                exec_entry_price = to_float(dist_row.get("exec_entry_price_yes"))
                exec_entry_cost = to_float(dist_row.get("exec_entry_cost_yes"))
                exec_edge_entry = to_float(dist_row.get("exec_edge_entry_yes"))
            else:
                q_entry = to_float(dist_row.get("q_entry_no"))
                exec_entry_price = to_float(dist_row.get("exec_entry_price_no"))
                exec_entry_cost = to_float(dist_row.get("exec_entry_cost_no"))
                exec_edge_entry = to_float(dist_row.get("exec_edge_entry_no"))
            # Backward-compat fallback: older facts may not have exec_* fields.
            if (
                q_entry is not None
                and math.isfinite(q_entry)
                and (exec_entry_price is None or not math.isfinite(exec_entry_price))
            ):
                if side == "YES":
                    ask = to_float(dist_row.get("best_ask"))
                    bid = to_float(dist_row.get("best_bid"))
                    spread = to_float(dist_row.get("spread"))
                else:
                    ask = to_float(dist_row.get("best_ask_no"))
                    bid = to_float(dist_row.get("best_bid_no"))
                    spread = to_float(dist_row.get("spread_no"))
                if ask is not None and math.isfinite(ask) and ask > 0:
                    # Conservative: assume we pay ask, unless spread looks sane and bid exists.
                    price_est = ask
                    if (
                        bid is not None
                        and math.isfinite(bid)
                        and bid > 0
                        and bid <= ask
                        and spread is not None
                        and math.isfinite(spread)
                        and spread >= 0
                        and spread <= 0.08 + 1e-9
                    ):
                        price_est = (bid + ask) / 2.0
                    exec_entry_price = price_est
                    exec_entry_cost = 0.0 if exec_entry_cost is None else exec_entry_cost
                    exec_edge_entry = float(q_entry) - float(exec_entry_price) - float(exec_entry_cost or 0.0)
                    exec_fallback_used = True

        if q_entry is not None and math.isfinite(q_entry):
            all_bucket["q_entry_wsum"] += float(q_entry) * qty
            all_bucket["q_entry_wqty"] += qty
        if exec_entry_price is not None and math.isfinite(exec_entry_price):
            all_bucket["exec_entry_price_wsum"] += float(exec_entry_price) * qty
            all_bucket["exec_entry_price_wqty"] += qty
        if exec_entry_cost is not None and math.isfinite(exec_entry_cost):
            all_bucket["exec_entry_cost_wsum"] += float(exec_entry_cost) * qty
            all_bucket["exec_entry_cost_wqty"] += qty
        if exec_edge_entry is not None and math.isfinite(exec_edge_entry):
            all_bucket["exec_edge_entry_wsum"] += float(exec_edge_entry) * qty
            all_bucket["exec_edge_entry_wqty"] += qty
        if exec_fallback_used:
            all_bucket["exec_fallback_contracts"] += 1

        fill_avg_price = to_float(rec.get("fill_avg_price"))
        if fill_avg_price is not None and math.isfinite(fill_avg_price):
            all_bucket["fill_price_wsum"] += float(fill_avg_price) * qty
            all_bucket["fill_price_wqty"] += qty
        if (
            fill_avg_price is not None
            and math.isfinite(fill_avg_price)
            and exec_entry_price is not None
            and math.isfinite(exec_entry_price)
        ):
            all_bucket["slippage_wsum"] += (float(fill_avg_price) - float(exec_entry_price)) * qty
            all_bucket["slippage_wqty"] += qty

        # Realized: only count if contract not entered by multiple strategies.
        multi = len(contract_strategies.get((slug, event_date, outcome, side), set())) > 1
        if multi:
            all_bucket["multi_strategy_contracts"] += 1
        if not multi:
            ck = (slug, event_date, outcome, side)
            fills = contract_fills.get(ck) or []
            actual = settlement_by_event.get((slug, event_date), "")
            rpnl, rcost, closed = _realized_from_fills(
                fills, settlement_actual=actual, outcome=outcome, side=side
            )
            all_bucket["realized_pnl"] += float(rpnl)
            all_bucket["realized_cost"] += float(rcost)
            if closed:
                all_bucket["realized_closed"] += 1

        # Per-bin aggregation.
        bkey = _bin_for(exec_edge_entry)
        by_bin = strat_entry["by_bin"]
        bucket = by_bin.get(bkey)
        if bucket is None:
            bucket = _init_bucket()
            by_bin[bkey] = bucket
        bucket["contracts"] += 1
        bucket["filled_qty"] += qty
        if isinstance(dist_row, dict):
            bucket["fact_contracts"] += 1
        if exec_fallback_used:
            bucket["exec_fallback_contracts"] += 1
        if q_entry is not None and math.isfinite(q_entry):
            bucket["q_entry_wsum"] += float(q_entry) * qty
            bucket["q_entry_wqty"] += qty
        if exec_entry_price is not None and math.isfinite(exec_entry_price):
            bucket["exec_entry_price_wsum"] += float(exec_entry_price) * qty
            bucket["exec_entry_price_wqty"] += qty
        if exec_entry_cost is not None and math.isfinite(exec_entry_cost):
            bucket["exec_entry_cost_wsum"] += float(exec_entry_cost) * qty
            bucket["exec_entry_cost_wqty"] += qty
        if exec_edge_entry is not None and math.isfinite(exec_edge_entry):
            bucket["exec_edge_entry_wsum"] += float(exec_edge_entry) * qty
            bucket["exec_edge_entry_wqty"] += qty
        if fill_avg_price is not None and math.isfinite(fill_avg_price):
            bucket["fill_price_wsum"] += float(fill_avg_price) * qty
            bucket["fill_price_wqty"] += qty
        if (
            fill_avg_price is not None
            and math.isfinite(fill_avg_price)
            and exec_entry_price is not None
            and math.isfinite(exec_entry_price)
        ):
            bucket["slippage_wsum"] += (float(fill_avg_price) - float(exec_entry_price)) * qty
            bucket["slippage_wqty"] += qty
        if multi:
            bucket["multi_strategy_contracts"] += 1
        if not multi:
            ck = (slug, event_date, outcome, side)
            fills = contract_fills.get(ck) or []
            actual = settlement_by_event.get((slug, event_date), "")
            rpnl, rcost, closed = _realized_from_fills(
                fills, settlement_actual=actual, outcome=outcome, side=side
            )
            bucket["realized_pnl"] += float(rpnl)
            bucket["realized_cost"] += float(rcost)
            if closed:
                bucket["realized_closed"] += 1

    # Finalize to UI-friendly payload (weighted avgs + ROI).
    for strategy, payload in list(out["strategies"].items()):
        for scope_key in ("all",):
            scope = payload.get(scope_key) if isinstance(payload.get(scope_key), dict) else None
            if not scope:
                continue
            qqty = float(scope.get("q_entry_wqty") or 0.0)
            scope["avg_q_entry"] = (float(scope["q_entry_wsum"]) / qqty) if qqty > TIME_EDGE_Q_EPS else None
            pqty = float(scope.get("exec_entry_price_wqty") or 0.0)
            scope["avg_exec_entry_price"] = (float(scope["exec_entry_price_wsum"]) / pqty) if pqty > TIME_EDGE_Q_EPS else None
            cqty = float(scope.get("exec_entry_cost_wqty") or 0.0)
            scope["avg_exec_entry_cost"] = (float(scope["exec_entry_cost_wsum"]) / cqty) if cqty > TIME_EDGE_Q_EPS else None
            eqty = float(scope.get("exec_edge_entry_wqty") or 0.0)
            scope["avg_exec_edge_entry"] = (float(scope["exec_edge_entry_wsum"]) / eqty) if eqty > TIME_EDGE_Q_EPS else None
            fqty = float(scope.get("fill_price_wqty") or 0.0)
            scope["avg_fill_price"] = (float(scope["fill_price_wsum"]) / fqty) if fqty > TIME_EDGE_Q_EPS else None
            sqty = float(scope.get("slippage_wqty") or 0.0)
            scope["avg_slippage"] = (float(scope["slippage_wsum"]) / sqty) if sqty > TIME_EDGE_Q_EPS else None
            cost = float(scope.get("realized_cost") or 0.0)
            pnl = float(scope.get("realized_pnl") or 0.0)
            scope["realized_roi"] = (pnl / cost) if cost > TIME_EDGE_Q_EPS else None
            # cleanup internals
            for k in list(scope.keys()):
                if k.endswith("_wsum") or k.endswith("_wqty"):
                    scope.pop(k, None)
        by_bin = payload.get("by_bin")
        if isinstance(by_bin, dict):
            for bkey, scope in list(by_bin.items()):
                if not isinstance(scope, dict):
                    continue
                qqty = float(scope.get("q_entry_wqty") or 0.0)
                scope["avg_q_entry"] = (float(scope["q_entry_wsum"]) / qqty) if qqty > TIME_EDGE_Q_EPS else None
                pqty = float(scope.get("exec_entry_price_wqty") or 0.0)
                scope["avg_exec_entry_price"] = (float(scope["exec_entry_price_wsum"]) / pqty) if pqty > TIME_EDGE_Q_EPS else None
                cqty = float(scope.get("exec_entry_cost_wqty") or 0.0)
                scope["avg_exec_entry_cost"] = (float(scope["exec_entry_cost_wsum"]) / cqty) if cqty > TIME_EDGE_Q_EPS else None
                eqty = float(scope.get("exec_edge_entry_wqty") or 0.0)
                scope["avg_exec_edge_entry"] = (float(scope["exec_edge_entry_wsum"]) / eqty) if eqty > TIME_EDGE_Q_EPS else None
                fqty = float(scope.get("fill_price_wqty") or 0.0)
                scope["avg_fill_price"] = (float(scope["fill_price_wsum"]) / fqty) if fqty > TIME_EDGE_Q_EPS else None
                sqty = float(scope.get("slippage_wqty") or 0.0)
                scope["avg_slippage"] = (float(scope["slippage_wsum"]) / sqty) if sqty > TIME_EDGE_Q_EPS else None
                cost = float(scope.get("realized_cost") or 0.0)
                pnl = float(scope.get("realized_pnl") or 0.0)
                scope["realized_roi"] = (pnl / cost) if cost > TIME_EDGE_Q_EPS else None
                for k in list(scope.keys()):
                    if k.endswith("_wsum") or k.endswith("_wqty"):
                        scope.pop(k, None)

    return out


def merge_edge_waterfall_realized(edge_waterfall: Any, strategy_stats: Any) -> None:
    """
    SSOT helper: ensure trade waterfall realized PnL/ROI matches strategy_stats (fills FIFO attribution).
    """
    if not isinstance(edge_waterfall, dict) or not isinstance(strategy_stats, dict):
        return
    strategies = edge_waterfall.get("strategies")
    if not isinstance(strategies, dict):
        return
    for key, payload in strategies.items():
        if not isinstance(payload, dict):
            continue
        scope = payload.get("all")
        if not isinstance(scope, dict):
            continue
        k = str(key or "").strip().lower()
        st = strategy_stats.get(k) or strategy_stats.get(key)
        if not isinstance(st, dict):
            continue
        pnl = to_float(st.get("total_pnl"))
        cost = to_float(st.get("total_cost"))
        roi = to_float(st.get("roi"))
        if pnl is not None and math.isfinite(pnl):
            scope["realized_pnl"] = float(pnl)
        if cost is not None and math.isfinite(cost):
            scope["realized_cost"] = float(cost)
        if roi is not None and math.isfinite(roi):
            scope["realized_roi"] = float(roi)
        elif pnl is not None and cost is not None and math.isfinite(pnl) and math.isfinite(cost) and float(cost) > TIME_EDGE_Q_EPS:
            scope["realized_roi"] = float(pnl) / float(cost)


def compute_positive_exec_edge_blockers(
    conn: sqlite3.Connection,
    days: int,
    run_date: str = "",
    *,
    include_mirror: bool = False,
    max_decisions: int = 25000,
) -> Dict[str, Any]:
    """
    Which gates block "positive tradable edge" (exec_edge_entry>0) opportunities?

    This is used to identify over-filtering / conflicting thresholds. We align each decision row
    to facts at/before decision.created_at and compute exec_edge_entry for that outcome+side.
    """

    def _norm_side(raw: Any) -> str:
        s = str(raw or "").strip().upper()
        return s if s in {"YES", "NO"} else ""

    def _norm_strategy(raw: Any) -> str:
        s = str(raw or "").strip().lower()
        if not s or s == "exit":
            return ""
        return s

    excluded = set()
    if not include_mirror:
        excluded |= {"mirror_follow", "mirror_follow_improve"}

    run_date_norm = str(run_date or "").strip()
    run_date_day = date_from_any(run_date_norm) if run_date_norm else None
    if run_date_day:
        start_date = run_date_day
        end_date = run_date_day
    else:
        start_date, end_date = resolve_stats_range(conn, days, require_settlement=False)
    start_text = start_date.isoformat()
    end_text = end_date.isoformat()

    fact_cur = conn.cursor()

    def _fact_row_at(slug: str, event_date: str, ts_text: str) -> Optional[Dict[str, Any]]:
        try:
            fact_cur.execute(
                """
                SELECT fact_json
                FROM event_fact_history
                WHERE slug = ? AND event_date = ? AND fact_as_of <= ?
                ORDER BY fact_as_of DESC
                LIMIT 1
                """,
                (slug, event_date, ts_text),
            )
        except sqlite3.OperationalError:
            return None
        r = fact_cur.fetchone()
        if not r:
            return None
        payload = safe_json_loads(r["fact_json"])
        return payload if isinstance(payload, dict) else None

    def _dist_row(fact_payload: Dict[str, Any], outcome_label: str) -> Optional[Dict[str, Any]]:
        dist = fact_payload.get("distribution")
        if not isinstance(dist, list) or not dist:
            return None
        target = str(outcome_label or "").strip()
        if not target:
            return None
        for item in dist:
            if isinstance(item, dict) and str(item.get("outcome") or "").strip() == target:
                return item
        return None

    def _exec_edge_entry_from_row(row: Dict[str, Any], side: str) -> Optional[float]:
        if side == "YES":
            v = to_float(row.get("exec_edge_entry_yes"))
            if v is not None and math.isfinite(v):
                return v
            q = to_float(row.get("q_entry"))
            ask = to_float(row.get("best_ask"))
        else:
            v = to_float(row.get("exec_edge_entry_no"))
            if v is not None and math.isfinite(v):
                return v
            q = to_float(row.get("q_entry_no"))
            ask = to_float(row.get("best_ask_no"))
        if q is None or ask is None or not math.isfinite(q) or not math.isfinite(ask):
            return None
        return float(q) - float(ask)

    def _classify_strategy(details: Any, reason_codes: List[str]) -> str:
        if isinstance(details, dict):
            s = _norm_strategy(details.get("strategy"))
            if s:
                return s
        codes = [str(c or "").strip().lower() for c in (reason_codes or []) if str(c or "").strip()]
        for c in codes:
            if c.startswith("yes_top_"):
                return "yes_top"
            if c.startswith("follow_"):
                return "follow_copy"
            if c.startswith("adj_pair_"):
                return "adj_pair"
            if c.startswith("hard_bound_"):
                return "hard_bound_no"
        return "main"

    cur = conn.cursor()
    try:
        cur.execute(
            """
            SELECT slug,event_date,outcome,side,will_order,reason_codes_json,details_json,created_at
            FROM auto_trade_decisions
            WHERE action='entry'
              AND event_date BETWEEN ? AND ?
              AND will_order=0
            ORDER BY datetime(created_at) DESC, id DESC
            """,
            (start_text, end_text),
        )
    except sqlite3.OperationalError:
        return {"window": {"start": start_text, "end": end_text}, "strategies": {}}

    out: Dict[str, Any] = {"window": {"start": start_text, "end": end_text}, "strategies": {}}

    def _ensure(strategy: str) -> Dict[str, Any]:
        k = str(strategy or "").strip().lower() or "main"
        entry = out["strategies"].get(k)
        if entry is None:
            entry = {
                "blocked_decisions": 0,
                "blocked_decisions_with_facts": 0,
                "pos_exec_edge_blocked": 0,
                "pos_exec_edge_blocked_with_facts": 0,
                "reason_code_counts": {},
            }
            out["strategies"][k] = entry
        return entry

    seen = 0
    for row in cur.fetchall():
        if max_decisions > 0 and seen >= max_decisions:
            break
        seen += 1
        created_at = str(row["created_at"] or "").strip()
        if created_at and is_before_stats_cutoff(created_at):
            continue
        slug = str(row["slug"] or "").strip()
        event_date = str(row["event_date"] or "").strip()
        outcome = str(row["outcome"] or "").strip()
        side = _norm_side(row["side"])
        if not slug or not event_date or not outcome or not side:
            continue
        reason_codes = safe_json_loads_any(row["reason_codes_json"])
        reason_codes = reason_codes if isinstance(reason_codes, list) else []
        reason_codes = [str(x or "").strip().lower() for x in reason_codes if str(x or "").strip()]
        countable_reason_codes = [c for c in reason_codes if not is_non_stat_blocker_code(c)]
        if reason_codes and not countable_reason_codes:
            continue
        details = safe_json_loads(row["details_json"])
        strategy = _classify_strategy(details, reason_codes)
        if strategy in excluded:
            continue
        entry = _ensure(strategy)
        entry["blocked_decisions"] += 1
        fact_payload = _fact_row_at(slug, event_date, created_at)
        dist = _dist_row(fact_payload, outcome) if fact_payload else None
        if isinstance(dist, dict):
            entry["blocked_decisions_with_facts"] += 1
        exec_edge = _exec_edge_entry_from_row(dist, side) if isinstance(dist, dict) else None
        if exec_edge is None or not math.isfinite(exec_edge):
            continue
        if exec_edge <= TIME_EDGE_Q_EPS:
            continue
        entry["pos_exec_edge_blocked"] += 1
        if isinstance(dist, dict):
            entry["pos_exec_edge_blocked_with_facts"] += 1
        code = "blocked"
        if countable_reason_codes:
            code = countable_reason_codes[0]
            if code == "entry_gate_blocked" and len(reason_codes) > 1:
                fallback = next((c for c in countable_reason_codes[1:] if c), "")
                if fallback:
                    code = fallback
        counts = entry["reason_code_counts"]
        counts[code] = int(counts.get(code) or 0) + 1

    # Convert counts to sorted list
    for strategy, entry in list(out["strategies"].items()):
        counts = entry.get("reason_code_counts")
        if isinstance(counts, dict):
            items = [{"code": k, "n": int(v or 0)} for k, v in counts.items()]
            items.sort(key=lambda x: x["n"], reverse=True)
            entry["top_reason_codes"] = items[:10]
        entry.pop("reason_code_counts", None)

    return out


def predicted_bucket_for_weighting(
    row: sqlite3.Row,
    distribution: List[Dict[str, Any]],
    weighting: str,
    models: Optional[List[str]] = None,
    weight_maps: Optional[Dict[str, Dict[str, float]]] = None,
    *,
    strict_corrected: bool = False,
) -> str:
    if weighting == "equal":
        label = str(row["corrected_top_bucket_equal"] or "")
        if label:
            return label
    if weighting == "auto":
        label = str(row["corrected_top_bucket_auto"] or "")
        if label:
            return label
    if weighting == "scenario":
        label = str(row["corrected_top_bucket_scenario"] or "")
        if label:
            return label
    if strict_corrected:
        return ""
    if models:
        weights = (weight_maps or {}).get(weighting) if weight_maps else None
        if not weights and distribution:
            weight_maps = resolve_weight_maps_for_row(row, distribution, models)
            weights = weight_maps.get(weighting)
        if weights:
            label, _ = top_bucket_from_distribution_weighted(distribution, models, weights)
            if label:
                return label
    if weighting == "equal":
        return top_bucket_from_distribution(distribution, "q_equal")[0]
    if weighting == "auto":
        return top_bucket_from_distribution(distribution, "q_auto")[0]
    if weighting == "scenario":
        return top_bucket_from_distribution(distribution, "q_scenario")[0]
    return ""


def actual_bucket_label(row: sqlite3.Row, distribution: List[Dict[str, Any]]) -> str:
    rounding_rule = str(row["rounding_rule"] or "")
    market_var = str(row["market_var"] or "")
    actual = to_float(row["settlement_actual"])
    return bucket_label_for_value(distribution, actual, rounding_rule, market_var)


def bias_to_unit(bias_c: Optional[float], unit: str) -> Optional[float]:
    if bias_c is None:
        return None
    if str(unit or "").upper() == "F":
        return float(bias_c) * 9.0 / 5.0
    return float(bias_c)


def compute_model_bias_map(rows: List[sqlite3.Row]) -> Dict[str, Dict[str, float]]:
    bias_sum: Dict[str, float] = {}
    bias_count: Dict[str, int] = {}
    for row in rows:
        payload = safe_json_loads(row["payload_json"])
        distribution = normalize_distribution_rows(payload.get("rows") or [])
        if not distribution:
            continue
        actual_value = to_float(row["settlement_actual"])
        if actual_value is None:
            continue
        unit = str(row["market_unit"] or "")
        actual_c = to_celsius(actual_value, unit)
        if actual_c is None:
            continue
        rounding_rule = str(row["rounding_rule"] or "")
        market_var = str(row["market_var"] or "")
        for model in payload_models(payload):
            expected = expected_value_from_model(distribution, model, rounding_rule, market_var)
            expected_c = to_celsius(expected, unit)
            if expected_c is None:
                continue
            bias_sum[model] = bias_sum.get(model, 0.0) + (expected_c - actual_c)
            bias_count[model] = bias_count.get(model, 0) + 1
    out: Dict[str, Dict[str, float]] = {}
    for model, count in bias_count.items():
        if count < MODEL_BIAS_MIN_COUNT:
            continue
        out[model] = {"mean": bias_sum.get(model, 0.0) / count, "count": float(count)}
    return out


def corrected_top_bucket_for_model(
    distribution: List[Dict[str, Any]],
    model: str,
    shift: float,
    rounding_rule: str,
    market_var: str,
) -> str:
    if not distribution or not model:
        return ""
    mapped: Dict[str, float] = {}
    for row in distribution:
        label = str(row.get("outcome") or "")
        if not label:
            continue
        per_model = row.get("per_model_q") or {}
        if not isinstance(per_model, dict):
            continue
        entry = per_model.get(model) or {}
        if not isinstance(entry, dict):
            continue
        q_val = to_float(entry.get("q_round"))
        if q_val is None:
            continue
        rep = bucket_representative_value(label)
        if rep is None:
            continue
        shifted = rep - shift
        target = bucket_label_for_value(distribution, shifted, rounding_rule, market_var)
        if not target:
            continue
        mapped[target] = mapped.get(target, 0.0) + q_val
    if not mapped:
        return ""
    best_label = ""
    best_q = -1.0
    best_key = (float("inf"), float("inf"), "")
    for label, q_val in mapped.items():
        key = bucket_sort_key(label)
        if q_val > best_q or (q_val == best_q and key < best_key):
            best_q = q_val
            best_label = label
            best_key = key
    return best_label


def init_place_entry() -> Dict[str, Any]:
    return {
        "equal_hit": 0,
        "equal_count": 0,
        "auto_hit": 0,
        "auto_count": 0,
        "scenario_hit": 0,
        "scenario_count": 0,
        "model_hits": {},
        "model_counts": {},
        "model_rates": {},
    }


def update_weight_hit(entry: Dict[str, Any], key: str, predicted: str, actual: str) -> None:
    if not predicted or not actual:
        return
    entry[f"{key}_count"] += 1
    if predicted == actual:
        entry[f"{key}_hit"] += 1


def update_model_hit(entry: Dict[str, Any], model: str, predicted: str, actual: str) -> None:
    if not model or not predicted or not actual:
        return
    counts = entry["model_counts"]
    hits = entry["model_hits"]
    counts[model] = counts.get(model, 0) + 1
    if predicted == actual:
        hits[model] = hits.get(model, 0) + 1


def finalize_place_stats(stats: Dict[str, Dict[str, Any]]) -> Dict[str, Dict[str, Any]]:
    for entry in stats.values():
        for key in ("equal", "auto", "scenario"):
            count = entry.get(f"{key}_count", 0) or 0
            hit = entry.get(f"{key}_hit", 0) or 0
            entry[f"{key}_rate"] = (hit / count) if count else None
        rates = {}
        for model, count in entry.get("model_counts", {}).items():
            if not count:
                continue
            hit = entry.get("model_hits", {}).get(model, 0)
            rates[model] = hit / count
        entry["model_rates"] = rates
    return stats


def station_pred_gap_stats(days: int) -> Dict[str, Any]:
    if not DB_PATH.exists():
        return {}
    with open_db_ro_fast(timeout_sec=SCOREBOARD_DB_TIMEOUT_SEC, busy_timeout_ms=SCOREBOARD_DB_BUSY_TIMEOUT_MS) as conn:
        rows = load_auto_trade_runs(conn, days, require_settlement=True)
        model_bias = compute_model_bias_map(rows)
        station_stats: Dict[str, Dict[str, Any]] = {}
        city_stats: Dict[str, Dict[str, Any]] = {}
        for row in rows:
            payload = safe_json_loads(row["payload_json"])
            distribution = normalize_distribution_rows(payload.get("rows") or [])
            if not distribution:
                continue
            actual_label = actual_bucket_label(row, distribution)
            if not actual_label:
                continue
            models = payload_models(payload)
            weight_maps = resolve_weight_maps_for_row(row, distribution, models) if models else {}
            station_id = str(row["station_id"] or "").strip()
            city = str(row["city"] or "").strip()
            predicted = {
                "equal": predicted_bucket_for_weighting(row, distribution, "equal", models, weight_maps, strict_corrected=True),
                "auto": predicted_bucket_for_weighting(row, distribution, "auto", models, weight_maps, strict_corrected=True),
                "scenario": predicted_bucket_for_weighting(row, distribution, "scenario", models, weight_maps, strict_corrected=True),
            }
            if station_id:
                entry = station_stats.setdefault(station_id, init_place_entry())
                for key in ("equal", "auto", "scenario"):
                    update_weight_hit(entry, key, predicted[key], actual_label)
            if city:
                entry = city_stats.setdefault(city, init_place_entry())
                for key in ("equal", "auto", "scenario"):
                    update_weight_hit(entry, key, predicted[key], actual_label)
            rounding_rule = str(row["rounding_rule"] or "")
            market_var = str(row["market_var"] or "")
            unit = str(row["market_unit"] or "")
            for model in models:
                bias_entry = model_bias.get(model) or {}
                shift = bias_to_unit(bias_entry.get("mean"), unit) or 0.0
                pred_label = corrected_top_bucket_for_model(
                    distribution, model, shift, rounding_rule, market_var
                )
                if station_id:
                    update_model_hit(station_stats[station_id], model, pred_label, actual_label)
                if city:
                    update_model_hit(city_stats[city], model, pred_label, actual_label)
        station_stats = finalize_place_stats(station_stats)
        city_stats = finalize_place_stats(city_stats)
        station_stats["__city_stats__"] = city_stats
        return station_stats


def model_hit_stats(days: int, weighting: str) -> Dict[str, Any]:
    if not DB_PATH.exists():
        return {"days": days, "weighting": weighting, "overall": {}, "models": [], "by_model": {}}
    with open_db() as conn:
        rows = load_auto_trade_runs(conn, days, require_settlement=True)
        model_bias = compute_model_bias_map(rows)
        model_counts: Dict[str, int] = {}
        model_hits: Dict[str, int] = {}
        for row in rows:
            payload = safe_json_loads(row["payload_json"])
            distribution = normalize_distribution_rows(payload.get("rows") or [])
            if not distribution:
                continue
            actual_label = actual_bucket_label(row, distribution)
            if not actual_label:
                continue
            rounding_rule = str(row["rounding_rule"] or "")
            market_var = str(row["market_var"] or "")
            unit = str(row["market_unit"] or "")
            for model in payload_models(payload):
                bias_entry = model_bias.get(model) or {}
                shift = bias_to_unit(bias_entry.get("mean"), unit) or 0.0
                pred_label = corrected_top_bucket_for_model(
                    distribution, model, shift, rounding_rule, market_var
                )
                if not pred_label:
                    continue
                model_counts[model] = model_counts.get(model, 0) + 1
                if pred_label == actual_label:
                    model_hits[model] = model_hits.get(model, 0) + 1
        models_list = []
        total_count = 0
        total_hit = 0
        for model, count in model_counts.items():
            hit = model_hits.get(model, 0)
            total_count += count
            total_hit += hit
            models_list.append(
                {
                    "model": model,
                    "count": count,
                    "hit": hit,
                    "rate": hit / count if count else 0.0,
                }
            )
        models_list.sort(key=lambda item: (-item["rate"], item["model"]))
        return {
            "days": days,
            "weighting": weighting,
            "overall": {
                "count": total_count,
                "hit": total_hit,
                "rate": (total_hit / total_count) if total_count else 0.0,
            },
            "models": models_list,
            "by_model": {
                item["model"]: {"count": item["count"], "hit": item["hit"], "rate": item["rate"]}
                for item in models_list
            },
        }


def station_forecast_hit_stats(days: int) -> Dict[str, Any]:
    if not DB_PATH.exists():
        return {"days": days, "overall": {}, "by_basis": {}}
    with open_db() as conn:
        rows = load_event_rows(conn, days, require_settlement=True)
        latest_rows = pick_latest_rows(rows)
        cur = conn.cursor()
        cur.execute("SELECT * FROM station_forecasts")
        forecast_rows = cur.fetchall()
        start_date, end_date = resolve_stats_range(conn, days, require_settlement=True)
        forecast_map: Dict[Tuple[str, str], sqlite3.Row] = {}
        for frow in forecast_rows:
            station_id = str(frow["station_id"] or "").strip()
            event_date = date_only(str(frow["event_date"] or ""))
            if not station_id or not event_date:
                continue
            event_dt = parse_date(event_date)
            if not event_dt or event_dt < start_date or event_dt > end_date:
                continue
            key = (station_id, event_date)
            prev = forecast_map.get(key)
            if not prev or str(frow["created_at"] or "") > str(prev["created_at"] or ""):
                forecast_map[key] = frow
        overall = {"count": 0, "hit": 0}
        by_basis: Dict[str, Dict[str, int]] = {}
        for row in latest_rows:
            station_id = str(row["station_id"] or "").strip()
            if not station_id:
                continue
            event_date = date_only(str(row["event_date"] or ""))
            forecast = forecast_map.get((station_id, event_date))
            if not forecast:
                continue
            payload = safe_json_loads(row["payload_json"])
            distribution = normalize_distribution_rows(payload.get("rows") or [])
            if not distribution:
                continue
            actual_label = actual_bucket_label(row, distribution)
            if not actual_label:
                continue
            unit = str(row["market_unit"] or "").upper()
            forecast_value = None
            if unit == "F":
                forecast_value = to_float(forecast["forecast_max_f"])
            if forecast_value is None:
                forecast_value = to_float(forecast["forecast_max_c"])
            if forecast_value is None:
                forecast_value = to_float(forecast["forecast_max_f"])
            rounding_rule = str(row["rounding_rule"] or "")
            market_var = str(row["market_var"] or "")
            predicted_label = bucket_label_for_value(distribution, forecast_value, rounding_rule, market_var)
            if not predicted_label:
                continue
            overall["count"] += 1
            if predicted_label == actual_label:
                overall["hit"] += 1
            basis = resolve_basis_from_row(row) or "unknown"
            entry = by_basis.setdefault(basis, {"count": 0, "hit": 0})
            entry["count"] += 1
            if predicted_label == actual_label:
                entry["hit"] += 1
        overall_rate = (overall["hit"] / overall["count"]) if overall["count"] else 0.0
        result_by_basis = {}
        for key, entry in by_basis.items():
            rate = (entry["hit"] / entry["count"]) if entry["count"] else 0.0
            result_by_basis[key] = {"count": entry["count"], "hit": entry["hit"], "rate": rate}
        return {
            "days": days,
            "overall": {"count": overall["count"], "hit": overall["hit"], "rate": overall_rate},
            "by_basis": result_by_basis,
        }


