def _parse_hit_stats_days_values(value: Any) -> List[int]:
    if value is None or value == "":
        raw_items: List[Any] = [30, 0]
    elif isinstance(value, (list, tuple, set)):
        raw_items = list(value)
    else:
        raw_items = str(value).replace(";", ",").split(",")
    out: List[int] = []
    for raw in raw_items:
        text = str(raw or "").strip().lower()
        if not text:
            continue
        if text in {"all", "history", "historical", "full", "0"}:
            days = 0
        else:
            try:
                days = int(text)
            except Exception:
                continue
            if days < 0:
                days = 0
        if days not in out:
            out.append(days)
    return out or [30, 0]


def _prediction_days_label(days: int) -> str:
    return "all_history" if int(days or 0) <= 0 else f"{int(days)}d"


def resolve_prediction_hit_stats_range(
    conn: sqlite3.Connection,
    days: int,
) -> Tuple[datetime.date, datetime.date]:
    if int(days or 0) > 0:
        return resolve_stats_range(conn, int(days), require_settlement=True)
    cur = conn.cursor()
    candidates: List[Tuple[str, str]] = []
    for sql in (
        """
        SELECT MIN(event_date), MAX(event_date)
        FROM event_daily_temps
        WHERE settlement_actual IS NOT NULL
        """,
        """
        SELECT MIN(event_date), MAX(event_date)
        FROM event_runs
        WHERE settlement_actual IS NOT NULL
        """,
    ):
        try:
            cur.execute(sql)
            row = cur.fetchone()
        except sqlite3.OperationalError:
            continue
        if not row:
            continue
        start_text = str(row[0] or "")
        end_text = str(row[1] or "")
        if start_text and end_text:
            candidates.append((start_text, end_text))
    start_values = [parse_date(start) for start, _end in candidates]
    end_values = [parse_date(end) for _start, end in candidates]
    start_dates = [dt for dt in start_values if dt is not None]
    end_dates = [dt for dt in end_values if dt is not None]
    end_date = max(end_dates) if end_dates else datetime.utcnow().date()
    start_date = min(start_dates) if start_dates else end_date
    cutoff = stats_cutoff_date()
    if cutoff and start_date < cutoff:
        start_date = cutoff
    return start_date, end_date


def _load_settlement_meta_map(
    conn: sqlite3.Connection,
    start_key: str,
    end_key: str,
) -> Dict[Tuple[str, str], Dict[str, Any]]:
    cur = conn.cursor()
    out: Dict[Tuple[str, str], Dict[str, Any]] = {}
    sources = (
        (
            "event_daily_temps",
            """
            SELECT slug, event_date, settlement_actual, created_at
            FROM event_daily_temps
            WHERE settlement_actual IS NOT NULL
              AND date(event_date) BETWEEN ? AND ?
            ORDER BY created_at DESC, id DESC
            """,
        ),
        (
            "event_runs",
            """
            SELECT slug, event_date, settlement_actual, created_at
            FROM event_runs
            WHERE settlement_actual IS NOT NULL
              AND date(event_date) BETWEEN ? AND ?
            ORDER BY created_at DESC, id DESC
            """,
        ),
    )
    for source, sql in sources:
        try:
            cur.execute(sql, (start_key, end_key))
            rows = cur.fetchall()
        except sqlite3.OperationalError:
            continue
        for row in rows:
            slug = str(row["slug"] or "")
            event_date = date_only(str(row["event_date"] or ""))
            if not slug or not event_date:
                continue
            key = (slug, event_date)
            if key in out:
                continue
            out[key] = {
                "settlement_actual": to_float(row["settlement_actual"]),
                "settlement_known_at": str(row["created_at"] or ""),
                "settlement_source": source,
            }
    return out


def _row_text_value(row: Any, key: str) -> str:
    try:
        value = row[key]
    except Exception:
        value = row.get(key) if isinstance(row, dict) else ""
    return str(value or "")


def _row_int_value(row: Any, key: str) -> int:
    try:
        value = row[key]
    except Exception:
        value = row.get(key) if isinstance(row, dict) else 0
    try:
        return int(value or 0)
    except Exception:
        return 0


def _prediction_row_dt(row: Dict[str, Any]) -> Optional[datetime]:
    return parse_iso_ts(_row_text_value(row, "fact_as_of") or _row_text_value(row, "created_at"))


def _prediction_cutoff_dt(row: Dict[str, Any]) -> Optional[datetime]:
    cutoffs: List[datetime] = []
    event_end = parse_iso_ts(_row_text_value(row, "event_end_utc"))
    settlement_known = parse_iso_ts(_row_text_value(row, "settlement_known_at"))
    if event_end:
        cutoffs.append(event_end)
    if settlement_known:
        cutoffs.append(settlement_known)
    return min(cutoffs) if cutoffs else None


def _is_pre_settlement_prediction_row(row: Dict[str, Any]) -> bool:
    if _row_int_value(row, "market_closed") == 1:
        return False
    fact_dt = _prediction_row_dt(row)
    cutoff_dt = _prediction_cutoff_dt(row)
    if fact_dt and cutoff_dt and fact_dt > cutoff_dt:
        return False
    return True


def _prediction_snapshot_sort_key(row: Dict[str, Any]) -> str:
    return _row_text_value(row, "fact_as_of") or _row_text_value(row, "created_at")


def load_prediction_hit_snapshots(
    conn: sqlite3.Connection,
    days: int,
) -> Tuple[List[Dict[str, Any]], List[Dict[str, Any]], Dict[str, Any]]:
    start_date, end_date = resolve_prediction_hit_stats_range(conn, days)
    start_key = start_date.isoformat()
    end_key = end_date.isoformat()
    ensure_fact_tables(conn)
    settlement_meta = _load_settlement_meta_map(conn, start_key, end_key)
    settlement_actual_map = {
        key: to_float(meta.get("settlement_actual"))
        for key, meta in settlement_meta.items()
    }
    excluded = {
        "settled_events": 0,
        "no_fact": 0,
        "no_pre_settlement_snapshot": 0,
        "missing_distribution": 0,
        "missing_actual_label": 0,
    }
    excluded["settled_events"] = len(settlement_meta)

    def load_one(key: Tuple[str, str], *, descending: bool) -> Tuple[Optional[Dict[str, Any]], Dict[str, bool]]:
        slug, event_date = key
        state = {
            "saw_fact": False,
            "saw_pre_settlement": False,
            "saw_distribution": False,
            "saw_actual_label": False,
        }
        order = "DESC" if descending else "ASC"
        cur = conn.cursor()
        cur.execute(
            f"""
            SELECT id, fact_as_of, fact_json
            FROM event_fact_history
            WHERE slug = ? AND event_date = ?
            ORDER BY fact_as_of {order}, id {order}
            """,
            (slug, event_date),
        )
        meta = settlement_meta.get(key) or {}
        for row in cur:
            state["saw_fact"] = True
            fact = safe_json_loads(row["fact_json"])
            if not isinstance(fact, dict):
                continue
            if not fact.get("slug"):
                fact["slug"] = slug
            if not fact.get("event_date"):
                fact["event_date"] = event_date
            run_like = _event_run_like_row_from_fact(
                conn,
                fact=fact,
                fact_as_of=str(row["fact_as_of"] or ""),
                settlement_map=settlement_actual_map,
            )
            if to_float(run_like.get("settlement_actual")) is None:
                continue
            run_like["settlement_known_at"] = str(meta.get("settlement_known_at") or "")
            run_like["settlement_source"] = str(meta.get("settlement_source") or "")
            run_like["fact_id"] = int(row["id"] or 0)
            if not _is_pre_settlement_prediction_row(run_like):
                continue
            state["saw_pre_settlement"] = True
            payload = safe_json_loads(run_like.get("payload_json"))
            distribution = normalize_distribution_rows(payload.get("rows") or [])
            if not distribution:
                continue
            state["saw_distribution"] = True
            actual_label = actual_bucket_label(run_like, distribution)
            if not actual_label:
                continue
            state["saw_actual_label"] = True
            return run_like, state
        return None, state

    first_rows: List[Dict[str, Any]] = []
    latest_rows: List[Dict[str, Any]] = []
    for key in sorted(settlement_meta.keys(), key=lambda item: (item[1], item[0])):
        first, first_state = load_one(key, descending=False)
        latest, latest_state = load_one(key, descending=True)
        if first and latest:
            first_rows.append(first)
            latest_rows.append(latest)
            continue
        saw_fact = bool(first_state.get("saw_fact") or latest_state.get("saw_fact"))
        saw_pre = bool(first_state.get("saw_pre_settlement") or latest_state.get("saw_pre_settlement"))
        saw_distribution = bool(first_state.get("saw_distribution") or latest_state.get("saw_distribution"))
        saw_actual_label = bool(first_state.get("saw_actual_label") or latest_state.get("saw_actual_label"))
        if not saw_fact:
            excluded["no_fact"] += 1
        elif not saw_pre:
            excluded["no_pre_settlement_snapshot"] += 1
        elif not saw_distribution:
            excluded["missing_distribution"] += 1
        elif not saw_actual_label:
            excluded["missing_actual_label"] += 1
        else:
            excluded["no_pre_settlement_snapshot"] += 1
    meta = {
        "start_date": start_key,
        "end_date": end_key,
        "settled_events": len(settlement_meta),
        "eligible_events": len(latest_rows),
        "excluded": excluded,
    }
    return first_rows, latest_rows, meta


def _init_hit_entry() -> Dict[str, Any]:
    return {
        "events": 0,
        "count": 0,
        "hit": 0,
        "miss": 0,
        "missing": 0,
        "within_1": 0,
        "within_2": 0,
        "gap_sum": 0.0,
        "gap_abs_sum": 0.0,
        "gap_count": 0,
        "_provenance_counts": {},
    }


def _prediction_provenance_truthy(value: Any) -> bool:
    if isinstance(value, bool):
        return value
    if isinstance(value, (int, float)) and not isinstance(value, bool):
        return bool(value)
    text = str(value or "").strip().lower()
    return text in {"1", "true", "yes", "y", "on"}


def _prediction_sample_provenance_from_row(row: Optional[Mapping[str, Any]]) -> Dict[str, Any]:
    if not isinstance(row, Mapping):
        return {
            "class": "unknown",
            "label": "来源未知",
            "history_only": False,
            "external_archive": False,
            "source": "",
        }
    external_archive = _prediction_provenance_truthy(
        row.get("sample_external_archive", row.get("external_archive"))
    )
    history_only = _prediction_provenance_truthy(row.get("sample_history_only", row.get("history_only")))
    source = str(row.get("sample_provenance_source") or row.get("model_snapshot_source") or row.get("source") or "")
    klass = str(row.get("sample_provenance_class") or "").strip()
    label = str(row.get("sample_provenance_label") or "").strip()
    if not klass:
        if external_archive and history_only:
            klass = "external_history_reconstruction"
        elif external_archive:
            klass = "external_archive"
        elif history_only:
            klass = "history_only_materialized"
        else:
            klass = "native_realtime_archive"
    if not label:
        label = {
            "external_history_reconstruction": "外部历史重建",
            "external_archive": "外部归档",
            "history_only_materialized": "历史物化",
            "native_realtime_archive": "原生采集",
        }.get(klass, "来源未知")
    return {
        "class": klass,
        "label": label,
        "history_only": bool(history_only),
        "external_archive": bool(external_archive),
        "source": source,
    }


def _record_prediction_sample_provenance(
    entry: Dict[str, Any],
    row: Optional[Mapping[str, Any]],
    *,
    counted: bool,
) -> None:
    provenance = _prediction_sample_provenance_from_row(row)
    klass = str(provenance.get("class") or "unknown")
    counts = entry.setdefault("_provenance_counts", {})
    if not isinstance(counts, dict):
        counts = {}
        entry["_provenance_counts"] = counts
    item = counts.setdefault(
        klass,
        {
            "class": klass,
            "label": str(provenance.get("label") or klass),
            "events": 0,
            "count": 0,
            "history_only": bool(provenance.get("history_only")),
            "external_archive": bool(provenance.get("external_archive")),
            "sources": {},
        },
    )
    item["events"] = int(item.get("events") or 0) + 1
    if counted:
        item["count"] = int(item.get("count") or 0) + 1
    if provenance.get("history_only"):
        item["history_only"] = True
    if provenance.get("external_archive"):
        item["external_archive"] = True
    source = str(provenance.get("source") or "").strip()
    if source:
        sources = item.setdefault("sources", {})
        if isinstance(sources, dict):
            sources[source] = int(sources.get(source) or 0) + (1 if counted else 0)


def _finalize_prediction_provenance_counts(entry: Mapping[str, Any]) -> Tuple[Dict[str, Any], Dict[str, int]]:
    raw_counts = entry.get("_provenance_counts") if isinstance(entry, Mapping) else {}
    out: Dict[str, Any] = {}
    totals = {
        "native_count": 0,
        "native_events": 0,
        "history_only_count": 0,
        "history_only_events": 0,
        "external_archive_count": 0,
        "external_archive_events": 0,
    }
    if not isinstance(raw_counts, Mapping):
        return out, totals
    for klass, raw_item in sorted(raw_counts.items(), key=lambda item: str(item[0])):
        if not isinstance(raw_item, Mapping):
            continue
        count = int(raw_item.get("count") or 0)
        events = int(raw_item.get("events") or 0)
        history_only = bool(raw_item.get("history_only"))
        external_archive = bool(raw_item.get("external_archive"))
        if history_only:
            totals["history_only_count"] += count
            totals["history_only_events"] += events
        if external_archive:
            totals["external_archive_count"] += count
            totals["external_archive_events"] += events
        if not history_only and not external_archive and str(klass) == "native_realtime_archive":
            totals["native_count"] += count
            totals["native_events"] += events
        sources = raw_item.get("sources")
        if isinstance(sources, Mapping):
            source_counts = {
                str(source): int(value or 0)
                for source, value in sorted(sources.items(), key=lambda item: (-int(item[1] or 0), str(item[0])))
                if int(value or 0) > 0
            }
        else:
            source_counts = {}
        out[str(klass)] = {
            "class": str(klass),
            "label": str(raw_item.get("label") or klass),
            "events": events,
            "count": count,
            "history_only": history_only,
            "external_archive": external_archive,
            "sources": source_counts,
        }
    return out, totals


def _prediction_sample_mix_summary(
    provenance_counts: Mapping[str, Any],
    *,
    count_key: str = "count",
    event_key: str = "events",
) -> Dict[str, Any]:
    items: List[Dict[str, Any]] = []
    totals = {
        "native_count": 0,
        "native_events": 0,
        "history_only_count": 0,
        "history_only_events": 0,
        "external_archive_count": 0,
        "external_archive_events": 0,
        "external_history_count": 0,
        "external_history_events": 0,
        "other_count": 0,
        "other_events": 0,
    }
    if not isinstance(provenance_counts, Mapping):
        return {"items": items, **totals, "summary": "", "has_external_archive": False, "has_history_only": False}
    for klass, raw_item in sorted(provenance_counts.items(), key=lambda item: str(item[0])):
        if not isinstance(raw_item, Mapping):
            continue
        count = int(raw_item.get(count_key) or 0)
        events = int(raw_item.get(event_key) or 0)
        if count <= 0 and events <= 0:
            continue
        class_key = str(raw_item.get("class") or klass or "unknown")
        history_only = bool(raw_item.get("history_only"))
        external_archive = bool(raw_item.get("external_archive"))
        if class_key == "external_history_reconstruction" or (history_only and external_archive):
            role = "external_history_reconstruction"
            totals["external_history_count"] += count
            totals["external_history_events"] += events
        elif external_archive:
            role = "external_archive"
        elif history_only:
            role = "history_only_materialized"
        elif class_key == "native_realtime_archive":
            role = "native_realtime_archive"
            totals["native_count"] += count
            totals["native_events"] += events
        else:
            role = "other"
            totals["other_count"] += count
            totals["other_events"] += events
        if history_only:
            totals["history_only_count"] += count
            totals["history_only_events"] += events
        if external_archive:
            totals["external_archive_count"] += count
            totals["external_archive_events"] += events
        item_out = {
            "class": class_key,
            "role": role,
            "label": str(raw_item.get("label") or class_key),
            "count": count,
            "events": events,
            "history_only": history_only,
            "external_archive": external_archive,
        }
        sources = raw_item.get("sources")
        if isinstance(sources, Mapping):
            item_out["sources"] = {
                str(source): int(value or 0)
                for source, value in sorted(sources.items(), key=lambda item: (-int(item[1] or 0), str(item[0])))
                if int(value or 0) > 0
            }
        items.append(item_out)
    summary_parts = [
        f"{item['label']} n={item['count']}"
        for item in items
        if int(item.get("count") or 0) > 0
    ]
    return {
        "items": items,
        **totals,
        "summary": "；".join(summary_parts),
        "has_external_archive": bool(totals["external_archive_count"] > 0),
        "has_history_only": bool(totals["history_only_count"] > 0),
        "has_external_history": bool(totals["external_history_count"] > 0),
    }


def _prediction_sample_mix_diagnostic(sample_mix: Any) -> Dict[str, Any]:
    if not isinstance(sample_mix, Mapping):
        return {
            "codes": ["provenance_missing"],
            "summary": "样本 provenance 缺失",
            "has_external_history": False,
            "has_external_archive": False,
            "has_history_only": False,
        }
    external_history_count = int(sample_mix.get("external_history_count") or 0)
    external_count = int(sample_mix.get("external_archive_count") or 0)
    history_count = int(sample_mix.get("history_only_count") or 0)
    native_count = int(sample_mix.get("native_count") or 0)
    codes: List[str] = []
    parts: List[str] = []
    if native_count > 0:
        codes.append("contains_native_realtime_archive")
        parts.append(f"原生实时采集 n={native_count}")
    if external_history_count > 0:
        codes.append("contains_external_history_reconstruction")
        parts.append(f"external_archive+history_only n={external_history_count}")
    if external_count > 0 and external_count != external_history_count:
        codes.append("contains_external_archive")
        parts.append(f"external_archive n={external_count}")
    elif external_count > 0:
        codes.append("contains_external_archive")
    if history_count > 0 and history_count != external_history_count:
        codes.append("contains_history_only")
        parts.append(f"history_only n={history_count}")
    elif history_count > 0:
        codes.append("contains_history_only")
    if external_history_count > 0 or external_count > 0 or history_count > 0:
        codes.append("sample_provenance_layered")
        parts.append("外部重建/历史物化样本已单独分层")
    if not codes:
        codes.append("native_or_unmarked_samples")
        parts.append("未发现 external_archive/history_only 标记")
    return {
        "codes": codes,
        "summary": "；".join(parts),
        "has_external_history": bool(external_history_count > 0),
        "has_external_archive": bool(external_count > 0),
        "has_history_only": bool(history_count > 0),
        "native_count": native_count,
        "external_history_count": external_history_count,
        "external_archive_count": external_count,
        "history_only_count": history_count,
    }


def _legacy_prediction_provenance_counts_from_totals(
    node: Mapping[str, Any],
    *,
    count_key: str = "count",
    event_key: str = "events",
) -> Dict[str, Any]:
    def as_int(value: Any) -> int:
        try:
            return max(0, int(value or 0))
        except Exception:
            return 0

    external_count = as_int(node.get("external_archive_count"))
    history_count = as_int(node.get("history_only_count"))
    native_count = as_int(node.get("native_count"))
    external_events = as_int(node.get("external_archive_events"))
    history_events = as_int(node.get("history_only_events"))
    native_events = as_int(node.get("native_events"))
    if external_count <= 0 and history_count <= 0 and native_count <= 0:
        return {}

    out: Dict[str, Any] = {}

    def with_count_event_keys(item: Dict[str, Any], count: int, events: int) -> Dict[str, Any]:
        item[count_key] = count
        if event_key == count_key:
            item[event_key] = max(count, events)
        else:
            item[event_key] = events
        return item

    external_history_count = min(external_count, history_count)
    external_history_events = min(external_events, history_events)
    if external_history_count > 0 or external_history_events > 0:
        out["external_history_reconstruction"] = with_count_event_keys(
            {
                "class": "external_history_reconstruction",
                "label": "外部历史重建",
                "count": external_history_count,
                "events": external_history_events,
                "history_only": True,
                "external_archive": True,
                "sources": {},
            },
            external_history_count,
            external_history_events,
        )
    external_only_count = max(0, external_count - external_history_count)
    external_only_events = max(0, external_events - external_history_events)
    if external_only_count > 0 or external_only_events > 0:
        out["external_archive"] = with_count_event_keys(
            {
                "class": "external_archive",
                "label": "外部归档",
                "count": external_only_count,
                "events": external_only_events,
                "history_only": False,
                "external_archive": True,
                "sources": {},
            },
            external_only_count,
            external_only_events,
        )
    history_only_count = max(0, history_count - external_history_count)
    history_only_events = max(0, history_events - external_history_events)
    if history_only_count > 0 or history_only_events > 0:
        out["history_only_materialized"] = with_count_event_keys(
            {
                "class": "history_only_materialized",
                "label": "历史物化",
                "count": history_only_count,
                "events": history_only_events,
                "history_only": True,
                "external_archive": False,
                "sources": {},
            },
            history_only_count,
            history_only_events,
        )
    if native_count > 0 or native_events > 0:
        out["native_realtime_archive"] = with_count_event_keys(
            {
                "class": "native_realtime_archive",
                "label": "原生采集",
                "count": native_count,
                "events": native_events,
                "history_only": False,
                "external_archive": False,
                "sources": {},
            },
            native_count,
            native_events,
        )
    return out


def _looks_like_prediction_hit_entry(node: Mapping[str, Any]) -> bool:
    if not isinstance(node, Mapping):
        return False
    has_sample_count = any(
        key in node
        for key in (
            "count",
            "events",
            "external_archive_count",
            "history_only_count",
            "native_count",
        )
    )
    has_hit_metric = any(
        key in node
        for key in (
            "hit",
            "miss",
            "missing",
            "hit_rate",
            "rate",
            "lead_day",
            "bucket_mae",
            "bucket_bias",
        )
    )
    return bool(has_sample_count and has_hit_metric)


def _record_prediction_hit(
    entry: Dict[str, Any],
    predicted: str,
    actual: str,
    *,
    row: Optional[Dict[str, Any]] = None,
) -> None:
    if not actual:
        return
    entry["events"] = int(entry.get("events") or 0) + 1
    if not predicted:
        entry["missing"] = int(entry.get("missing") or 0) + 1
        if isinstance(row, Mapping):
            _record_prediction_sample_provenance(entry, row, counted=False)
        return
    entry["count"] = int(entry.get("count") or 0) + 1
    if isinstance(row, Mapping):
        _record_prediction_sample_provenance(entry, row, counted=True)
    if predicted == actual:
        entry["hit"] = int(entry.get("hit") or 0) + 1
    else:
        entry["miss"] = int(entry.get("miss") or 0) + 1
    if row is not None:
        actual_value = to_float(row.get("settlement_actual"))
        gap, _unit = gap_from_label(
            actual_value,
            predicted,
            str(row.get("rounding_rule") or ""),
            str(row.get("market_var") or ""),
            str(row.get("market_unit") or ""),
        )
        if gap is not None and math.isfinite(gap):
            gap_val = float(gap)
            gap_abs = abs(gap_val)
            entry["gap_sum"] = float(entry.get("gap_sum") or 0.0) + gap_val
            entry["gap_abs_sum"] = float(entry.get("gap_abs_sum") or 0.0) + gap_abs
            entry["gap_count"] = int(entry.get("gap_count") or 0) + 1
            if gap_abs <= 1.0 + 1e-9:
                entry["within_1"] = int(entry.get("within_1") or 0) + 1
            if gap_abs <= 2.0 + 1e-9:
                entry["within_2"] = int(entry.get("within_2") or 0) + 1


def _finalize_hit_entry(entry: Dict[str, Any]) -> Dict[str, Any]:
    events = int(entry.get("events") or 0)
    count = int(entry.get("count") or 0)
    hit = int(entry.get("hit") or 0)
    miss = int(entry.get("miss") or 0)
    missing = int(entry.get("missing") or 0)
    within_1 = int(entry.get("within_1") or 0)
    within_2 = int(entry.get("within_2") or 0)
    gap_count = int(entry.get("gap_count") or 0)
    bucket_mae = (float(entry.get("gap_abs_sum") or 0.0) / gap_count) if gap_count else None
    bucket_bias = (float(entry.get("gap_sum") or 0.0) / gap_count) if gap_count else None
    provenance_counts, provenance_totals = _finalize_prediction_provenance_counts(entry)
    out = {
        "events": events,
        "count": count,
        "hit": hit,
        "miss": miss,
        "missing": missing,
        "rate": (hit / count) if count else None,
        "coverage_rate": (count / events) if events else None,
        "within_1": within_1,
        "within_2": within_2,
        "within_1_rate": (within_1 / count) if count else None,
        "within_2_rate": (within_2 / count) if count else None,
        "mae": bucket_mae,
        "bias": bucket_bias,
        "bucket_mae": bucket_mae,
        "bucket_bias": bucket_bias,
        "gap_count": gap_count,
    }
    out.update(provenance_totals)
    out["provenance_counts"] = provenance_counts
    out["sample_mix"] = _prediction_sample_mix_summary(provenance_counts)
    return out


def _prediction_hit_diagnostic(entry: Mapping[str, Any]) -> Dict[str, Any]:
    events = int(entry.get("events") or 0)
    count = int(entry.get("count") or 0)
    missing = int(entry.get("missing") or 0)
    hit_rate = to_float(entry.get("hit_rate"))
    if hit_rate is None:
        hit_rate = to_float(entry.get("rate"))
    within_1_rate = to_float(entry.get("within_1_rate"))
    bucket_mae = to_float(entry.get("bucket_mae"))
    bucket_bias = to_float(entry.get("bucket_bias"))
    external_count = int(entry.get("external_archive_count") or 0)
    history_count = int(entry.get("history_only_count") or 0)
    sample_mix = entry.get("sample_mix") if isinstance(entry.get("sample_mix"), Mapping) else {}
    external_history_count = int(sample_mix.get("external_history_count") or 0) if isinstance(sample_mix, Mapping) else 0
    codes: List[str] = []
    notes: List[str] = []
    if events > 0 and missing > 0:
        codes.append("coverage_missing")
        notes.append(f"{missing}/{events} events missing this lead snapshot")
    if count <= 0:
        codes.append("no_prediction_samples")
        notes.append("no visible prediction samples; not counted as misses")
    elif count < 5:
        codes.append("small_sample")
        notes.append(f"small n={count}; exact hit rate is volatile")
    if count > 0 and hit_rate is not None and hit_rate <= 0 and within_1_rate is not None and within_1_rate > 0:
        codes.append("exact_zero_adjacent_hits")
        notes.append("exact bucket is 0%, but within-1 bucket has hits")
    if count > 0 and bucket_mae is not None and bucket_mae >= 1.5:
        codes.append("off_by_multiple_buckets")
        notes.append(f"bucket MAE {bucket_mae:.1f}")
    if count > 0 and bucket_bias is not None and abs(bucket_bias) >= 0.5:
        if bucket_bias < 0:
            codes.append("warm_bias")
            notes.append(f"predictions skew warm by about {abs(bucket_bias):.1f} buckets")
        else:
            codes.append("cold_bias")
            notes.append(f"predictions skew cool by about {bucket_bias:.1f} buckets")
    if external_history_count > 0:
        codes.append("contains_external_history_reconstruction")
        notes.append(f"includes external history reconstruction samples n={external_history_count}")
    if external_count > 0:
        codes.append("contains_external_archive")
        notes.append(f"includes external archive samples n={external_count}")
    if history_count > 0:
        codes.append("contains_history_only")
        notes.append(f"includes history-only materialized samples n={history_count}")
    if not codes:
        codes.append("ok_or_mixed")
        notes.append("exact hit rate reflects strict final-bucket matching")
    provenance_diagnostic = _prediction_sample_mix_diagnostic(sample_mix)
    return {
        "codes": codes,
        "summary": "; ".join(notes),
        "sample_note": f"n={count}, missing={missing}, events={events}",
        "sample_mix": sample_mix,
        "provenance_diagnostic": provenance_diagnostic,
        "provenance_summary": str(provenance_diagnostic.get("summary") or ""),
    }


def _normalize_prediction_hit_rate_provenance_payload(payload: Any) -> Any:
    if not isinstance(payload, dict):
        return payload
    coverage = payload.get("coverage")
    if isinstance(coverage, dict):
        sample_counts = coverage.get("sample_provenance_counts")
        if not isinstance(sample_counts, Mapping):
            sample_counts = _legacy_prediction_provenance_counts_from_totals(
                coverage,
                count_key="lead_day_samples",
                event_key="lead_day_samples",
            )
            if sample_counts:
                coverage["sample_provenance_counts"] = sample_counts
        if isinstance(sample_counts, Mapping) and not isinstance(coverage.get("sample_provenance_mix"), Mapping):
            coverage["sample_provenance_mix"] = _prediction_sample_mix_summary(
                sample_counts,
                count_key="lead_day_samples",
                event_key="lead_day_samples",
            )
        if isinstance(coverage.get("sample_provenance_mix"), Mapping):
            coverage["provenance_diagnostic"] = _prediction_sample_mix_diagnostic(
                coverage.get("sample_provenance_mix")
            )

    seen: Set[int] = set()

    def normalize_node(node: Any) -> None:
        if isinstance(node, dict):
            node_id = id(node)
            if node_id in seen:
                return
            seen.add(node_id)
            is_hit_entry = _looks_like_prediction_hit_entry(node)
            provenance_counts = node.get("provenance_counts") if is_hit_entry else None
            if is_hit_entry and not isinstance(provenance_counts, Mapping):
                provenance_counts = _legacy_prediction_provenance_counts_from_totals(node)
                if provenance_counts:
                    node["provenance_counts"] = provenance_counts
            if is_hit_entry and isinstance(provenance_counts, Mapping):
                if not isinstance(node.get("sample_mix"), Mapping):
                    node["sample_mix"] = _prediction_sample_mix_summary(provenance_counts)
                node["diagnostic"] = _prediction_hit_diagnostic(node)
            for key, value in list(node.items()):
                if key in {"provenance_counts", "sample_mix", "diagnostic"}:
                    continue
                normalize_node(value)
        elif isinstance(node, list):
            for value in node:
                normalize_node(value)

    normalize_node(payload.get("sources"))
    normalize_node(payload.get("by_source"))
    return payload


def _top_bucket_for_model(
    distribution: List[Dict[str, Any]],
    model: str,
) -> Tuple[str, Optional[float]]:
    best_label = ""
    best_q: Optional[float] = None
    best_key: Optional[Tuple[float, float, str]] = None
    if not distribution or not model:
        return best_label, best_q
    for row in distribution:
        label = str(row.get("outcome") or "")
        if not label:
            continue
        per_model = row.get("per_model_q") or {}
        if not isinstance(per_model, dict):
            continue
        entry = per_model.get(model) or {}
        if not isinstance(entry, dict):
            continue
        q_val = to_float(entry.get("q_round"))
        if q_val is None:
            q_val = to_float(entry.get("q"))
        if q_val is None:
            continue
        key = bucket_sort_key(label)
        if best_q is None or q_val > best_q or (q_val == best_q and key < (best_key or key)):
            best_q = q_val
            best_label = label
            best_key = key
    return best_label, best_q


def _models_for_prediction_hit(payload: Dict[str, Any], distribution: List[Dict[str, Any]]) -> List[str]:
    models = set(payload_models(payload))
    for model in _models_from_distribution(distribution):
        if model:
            models.add(model)
    return sorted(models)


def _prediction_hit_market_section(rows: List[Dict[str, Any]]) -> Dict[str, Any]:
    overall = _init_hit_entry()
    by_basis: Dict[str, Dict[str, Any]] = {}
    source_counts: Dict[str, int] = {}
    price_sum = 0.0
    price_count = 0
    for row in rows:
        payload = safe_json_loads(row["payload_json"])
        distribution = normalize_distribution_rows(payload.get("rows") or [])
        if not distribution:
            continue
        actual_label = actual_bucket_label(row, distribution)
        if not actual_label:
            continue
        predicted_label, price, source = market_top_label_with_source(distribution)
        _record_prediction_hit(overall, predicted_label, actual_label, row=row)
        basis = resolve_basis_from_row(row) or "unknown"
        _record_prediction_hit(by_basis.setdefault(basis, _init_hit_entry()), predicted_label, actual_label, row=row)
        if predicted_label:
            source_key = source or "unknown"
            source_counts[source_key] = source_counts.get(source_key, 0) + 1
        if price is not None and math.isfinite(price):
            price_sum += float(price)
            price_count += 1
    by_basis_out = {
        key: _finalize_hit_entry(entry)
        for key, entry in sorted(by_basis.items(), key=lambda item: item[0])
    }
    out = _finalize_hit_entry(overall)
    out["by_basis"] = by_basis_out
    out["price_source_counts"] = dict(sorted(source_counts.items(), key=lambda item: (-item[1], item[0])))
    out["avg_top_price"] = (price_sum / price_count) if price_count else None
    return out


def _prediction_hit_models_section(
    rows: List[Dict[str, Any]],
    expected_models: Tuple[str, ...],
) -> Dict[str, Any]:
    stats: Dict[str, Dict[str, Any]] = {}
    observed_models: set[str] = set()
    for model in expected_models:
        stats[model] = {
            **_init_hit_entry(),
            "model": model,
            "avg_gap": None,
            "mae": None,
            "_gap_sum": 0.0,
            "_abs_sum": 0.0,
            "_gap_count": 0,
        }
    for row in rows:
        payload = safe_json_loads(row["payload_json"])
        distribution = normalize_distribution_rows(payload.get("rows") or [])
        if not distribution:
            continue
        actual_value = to_float(row["settlement_actual"])
        actual_label = actual_bucket_label(row, distribution)
        if not actual_label:
            continue
        unit = str(row["market_unit"] or "")
        rounding_rule = str(row["rounding_rule"] or "")
        market_var = str(row["market_var"] or "")
        actual_c = to_celsius(actual_value, unit)
        for model in _models_for_prediction_hit(payload, distribution):
            observed_models.add(model)
        for model in expected_models:
            entry = stats.setdefault(
                model,
                {
                    **_init_hit_entry(),
                    "model": model,
                    "avg_gap": None,
                    "mae": None,
                    "_gap_sum": 0.0,
                    "_abs_sum": 0.0,
                    "_gap_count": 0,
                },
            )
            predicted_label, _q = _top_bucket_for_model(distribution, model)
            _record_prediction_hit(entry, predicted_label, actual_label, row=row)
            expected = expected_value_from_model(distribution, model, rounding_rule, market_var)
            expected_c = to_celsius(expected, unit)
            if expected_c is not None and actual_c is not None:
                gap = expected_c - actual_c
                entry["_gap_sum"] = float(entry.get("_gap_sum") or 0.0) + gap
                entry["_abs_sum"] = float(entry.get("_abs_sum") or 0.0) + abs(gap)
                entry["_gap_count"] = int(entry.get("_gap_count") or 0) + 1
    models_out: List[Dict[str, Any]] = []
    for model in expected_models:
        entry = stats.get(model) or {"model": model, **_init_hit_entry()}
        finalized = _finalize_hit_entry(entry)
        gap_count = int(entry.get("_gap_count") or 0)
        finalized.update(
            {
                "model": model,
                "avg_gap": (float(entry.get("_gap_sum") or 0.0) / gap_count) if gap_count else None,
                "mae": (float(entry.get("_abs_sum") or 0.0) / gap_count) if gap_count else None,
                "gap_count": gap_count,
                "na_reason": "" if int(finalized.get("count") or 0) else "missing_in_window",
            }
        )
        models_out.append(finalized)
    return {
        "models": models_out,
        "by_model": {item["model"]: item for item in models_out},
        "expected_models": list(expected_models),
        "observed_models": sorted(observed_models),
        "missing_models": [model for model in expected_models if model not in observed_models],
        "extra_models": sorted(model for model in observed_models if model not in set(expected_models)),
    }


def _prediction_hit_final_section(rows: List[Dict[str, Any]]) -> Dict[str, Any]:
    weight_stats = {key: _init_hit_entry() for key in ("equal", "auto", "scenario")}
    for row in rows:
        payload = safe_json_loads(row["payload_json"])
        distribution = normalize_distribution_rows(payload.get("rows") or [])
        if not distribution:
            continue
        actual_label = actual_bucket_label(row, distribution)
        if not actual_label:
            continue
        models = payload_models(payload)
        weight_maps = resolve_weight_maps_for_row(row, distribution, models) if models else {}
        for key in ("equal", "auto", "scenario"):
            predicted = predicted_bucket_for_weighting(
                row,
                distribution,
                key,
                models,
                weight_maps,
                strict_corrected=False,
            )
            _record_prediction_hit(weight_stats[key], predicted, actual_label, row=row)
    rows_out = []
    for key in ("equal", "auto", "scenario"):
        entry = _finalize_hit_entry(weight_stats[key])
        entry["weighting"] = key
        rows_out.append(entry)
    return {
        "weightings": rows_out,
        "by_weighting": {item["weighting"]: item for item in rows_out},
    }


def compute_prediction_hit_stats(
    conn: sqlite3.Connection,
    days: int,
    *,
    end_date: str = "",
) -> Dict[str, Any]:
    try:
        days = int(days)
    except Exception:
        days = 30
    if days < 0:
        days = 0
    earliest_rows, latest_rows, range_meta = load_prediction_hit_snapshots(conn, days)
    actual_bucket_counts: Dict[str, int] = {}
    basis_counts: Dict[str, int] = {}
    for row in latest_rows:
        payload = safe_json_loads(row["payload_json"])
        distribution = normalize_distribution_rows(payload.get("rows") or [])
        if not distribution:
            continue
        actual_label = actual_bucket_label(row, distribution)
        if not actual_label:
            continue
        actual_bucket_counts[actual_label] = actual_bucket_counts.get(actual_label, 0) + 1
        basis = resolve_basis_from_row(row) or "unknown"
        basis_counts[basis] = basis_counts.get(basis, 0) + 1
    settlement_events = sum(actual_bucket_counts.values())
    actual_distribution = [
        {
            "label": label,
            "count": count,
            "share": (count / settlement_events) if settlement_events else None,
        }
        for label, count in sorted(actual_bucket_counts.items(), key=lambda item: (-item[1], bucket_sort_key(item[0])))
    ]
    expected_models = PREDICTION_HIT_MODELS or ("gfs_seamless", "icon_seamless", "ecmwf_ifs025", "nws_forecast")
    payload = {
        "ok": True,
        "days": days,
        "window_label": _prediction_days_label(days),
        "start_date": str(range_meta.get("start_date") or ""),
        "end_date": _normalize_date_key(end_date) or str(range_meta.get("end_date") or ""),
        "generated_at": now_text(),
        "auto_update": {
            "enabled": True,
            "policy": "daily_rolling_from_archive_on_read",
            "cache_sec": FIRST_PREDICTION_HIT_RATE_CACHE_SEC,
            "trigger": "post_close_daily_after_new_settlement_visible",
            "refresh_cadence": "post_close_daily",
            "manual_refresh_required": False,
        },
        "source": {
            "table": "event_fact_history",
            "settlement_table": "event_daily_temps,event_runs",
            "snapshot_policy": "pre_settlement_first_market_and_latest_model",
            "timezone": "America/New_York",
            "hit_policy": "exact_bucket_plus_within_1_within_2_and_bucket_mae",
        },
        "coverage": {
            "settled_events": int(range_meta.get("settled_events") or 0),
            "eligible_events": int(range_meta.get("eligible_events") or 0),
            "excluded": range_meta.get("excluded") if isinstance(range_meta.get("excluded"), dict) else {},
        },
        "settlement": {
            "events": settlement_events,
            "actual_bucket_distribution": actual_distribution,
            "by_basis": {
                key: {"events": count}
                for key, count in sorted(basis_counts.items(), key=lambda item: item[0])
            },
        },
        "market": {
            "first": _prediction_hit_market_section(earliest_rows),
            "latest": _prediction_hit_market_section(latest_rows),
        },
        "models": _prediction_hit_models_section(latest_rows, tuple(expected_models)),
        "final": _prediction_hit_final_section(latest_rows),
    }
    if settlement_events <= 0:
        payload["ok"] = False
        payload["na_reason"] = "no_pre_settlement_settled_events"
    return payload


def _first_prediction_source_models() -> Tuple[str, ...]:
    configured = PREDICTION_HIT_MODELS or ("gfs_seamless", "icon_seamless", "ecmwf_ifs025")
    models: List[str] = []
    for model in configured:
        model_key = str(model or "").strip()
        if not model_key or model_key == "nws_forecast":
            continue
        if model_key not in models:
            models.append(model_key)
    for model_key in ("gfs_seamless", "icon_seamless", "ecmwf_ifs025"):
        if model_key not in models:
            models.append(model_key)
    return tuple(models)


def _first_prediction_source_defs() -> List[Dict[str, Any]]:
    rows: List[Dict[str, Any]] = [
        {"source_id": "wu_forecast", "label": "WU forecast", "group": "data_source", "order": 20},
        {"source_id": "weather_com_forecast", "label": "Weather.com/TWC", "group": "data_source", "order": 30},
        {"source_id": "taf_forecast", "label": "AviationWeather TAF", "group": "data_source", "order": 40},
    ]
    model_labels = {
        "gfs_seamless": "GFS",
        "icon_seamless": "ICON",
        "ecmwf_ifs025": "ECMWF",
    }
    for idx, model in enumerate(_first_prediction_source_models()):
        rows.append(
            {
                "source_id": model,
                "label": model_labels.get(model, model),
                "group": "model",
                "order": 100 + idx,
            }
        )
    return rows


def _prediction_lead_day_key(fact_as_of: str, event_date: str) -> str:
    event_dt = parse_date(date_only(str(event_date or "")))
    if event_dt is None:
        return ""
    seen_dt = parse_any_ts(str(fact_as_of or "").strip()) or parse_iso_ts(str(fact_as_of or "").strip())
    if seen_dt is None:
        return ""
    if seen_dt.tzinfo is None:
        seen_dt = seen_dt.replace(tzinfo=timezone.utc)
    try:
        seen_day = seen_dt.astimezone(ZoneInfo("Asia/Shanghai")).date()
    except Exception:
        seen_day = seen_dt.date()
    delta_days = (event_dt - seen_day).days
    if delta_days in (0, 1, 2):
        return f"D{delta_days}"
    return ""


def _first_prediction_text_matches_chengdu(slug: str, fact: Mapping[str, Any]) -> bool:
    fields = [
        slug,
        str(fact.get("slug") or ""),
        str(fact.get("title") or ""),
        str(fact.get("city") or ""),
        str(fact.get("station_id") or ""),
        str(fact.get("resolution_source") or ""),
        str(fact.get("event_url") or ""),
    ]
    return any("chengdu" in field.lower() or "zuuu" in field.lower() for field in fields)


def _first_prediction_channels(payload: Mapping[str, Any], row0: Mapping[str, Any]) -> Dict[str, Any]:
    channels: Dict[str, Any] = {}
    for source in (payload, row0):
        value = source.get("soft_forecast_posterior_channels") if isinstance(source, Mapping) else None
        if isinstance(value, Mapping):
            channels.update({str(k): v for k, v in value.items() if isinstance(v, Mapping)})
    return channels


def _first_prediction_numeric_value(
    payload: Mapping[str, Any],
    row0: Mapping[str, Any],
    channel_name: str,
    keys: Iterable[str],
) -> Optional[float]:
    for source in (row0, payload):
        if not isinstance(source, Mapping):
            continue
        for key in keys:
            value = to_float(source.get(key))
            if value is not None and math.isfinite(value):
                return float(value)
    channels = _first_prediction_channels(payload, row0)
    channel = channels.get(channel_name)
    if isinstance(channel, Mapping):
        for key in ("peak_c", "value_c", "peak", "value"):
            value = to_float(channel.get(key))
            if value is not None and math.isfinite(value):
                return float(value)
    return None


def _forecast_c_to_market_value(value_c: Optional[float], market_unit: str) -> Optional[float]:
    if value_c is None or not math.isfinite(value_c):
        return None
    if str(market_unit or "").strip().upper() == "F":
        return float(value_c) * 9.0 / 5.0 + 32.0
    return float(value_c)


def _first_prediction_numeric_bucket(
    run_like: Mapping[str, Any],
    distribution: List[Dict[str, Any]],
    value_c: Optional[float],
) -> str:
    value = _forecast_c_to_market_value(value_c, str(run_like.get("market_unit") or ""))
    if value is None:
        return ""
    return bucket_label_for_value(
        distribution,
        value,
        str(run_like.get("rounding_rule") or ""),
        str(run_like.get("market_var") or ""),
    )


PREDICTION_MODEL_HIT_MODE_LABELS = {
    "value_bucket": "模型原始/校准最高温值落桶",
    "probability_bucket": "模型桶概率最高",
}


