def _load_latest_feedback_snapshot_ro(
    conn: sqlite3.Connection,
    *,
    kind: str,
    days: int,
    ok_only: bool = False,
) -> Optional[Dict[str, Any]]:
    cur = conn.cursor()
    try:
        cur.execute(
            """
            SELECT id, payload_json, ok, error, created_at, end_date
            FROM feedback_snapshots
            WHERE kind = ? AND days = ?
              AND (? = 0 OR ok = 1)
            ORDER BY created_at DESC, id DESC
            LIMIT 1
            """,
            (str(kind or ""), int(days), 1 if ok_only else 0),
        )
    except sqlite3.OperationalError:
        return None
    row = cur.fetchone()
    if not row:
        return None
    payload = safe_json_loads(row[1]) if row[1] else None
    if not isinstance(payload, dict):
        payload = {}
    payload["_meta"] = {
        "id": int(row[0] or 0),
        "ok": int(row[2] or 0) == 1,
        "error": str(row[3] or ""),
        "created_at": str(row[4] or ""),
        "end_date": str(row[5] or ""),
    }
    return payload


def prediction_hit_stats(days: int) -> Dict[str, Any]:
    try:
        days = int(days)
    except Exception:
        days = 30
    if days < 0:
        days = 0
    if not DB_PATH.exists():
        return {"ok": False, "error": "db_missing", "days": days}
    try:
        with open_db_ro_fast(timeout_sec=0.6, busy_timeout_ms=600) as conn:
            payload = _load_latest_feedback_snapshot_ro(conn, kind="prediction_hit_stats", days=days)
        if payload:
            payload["cached"] = True
            return payload
    except Exception:
        pass
    return {"ok": False, "na_reason": "missing_snapshot", "kind": "prediction_hit_stats", "days": days}


def season_label(lat: Optional[float], event_date: str) -> str:
    dt = parse_date(event_date)
    if not dt:
        return "\u672a\u77e5"
    month = dt.month
    south = is_finite(lat) and float(lat) < 0
    if month in (12, 1, 2):
        return "\u590f\u5b63" if south else "\u51ac\u5b63"
    if month in (3, 4, 5):
        return "\u79cb\u5b63" if south else "\u6625\u5b63"
    if month in (6, 7, 8):
        return "\u51ac\u5b63" if south else "\u590f\u5b63"
    return "\u6625\u5b63" if south else "\u79cb\u5b63"


def model_daily_stats(days: int) -> Dict[str, Any]:
    if not DB_PATH.exists():
        return {"monthly_rows": [], "city_rows": [], "station_rows": []}
    with open_db() as conn:
        rows = load_auto_trade_runs(conn, days, require_settlement=True)
        model_bias = compute_model_bias_map(rows)
        month_stats: Dict[Tuple[str, str], Dict[str, Any]] = {}
        city_stats: Dict[Tuple[str, str], Dict[str, Any]] = {}
        station_stats: Dict[Tuple[str, str], Dict[str, Any]] = {}
        for row in rows:
            payload = safe_json_loads(row["payload_json"])
            distribution = normalize_distribution_rows(payload.get("rows") or [])
            if not distribution:
                continue
            actual_value = to_float(row["settlement_actual"])
            if actual_value is None:
                continue
            actual_label = actual_bucket_label(row, distribution)
            if not actual_label:
                continue
            unit = str(row["market_unit"] or "")
            actual_c = to_celsius(actual_value, unit)
            rounding_rule = str(row["rounding_rule"] or "")
            market_var = str(row["market_var"] or "")
            event_date = date_only(str(row["event_date"] or ""))
            month_key = event_date[:7] if event_date else ""
            city = str(row["city"] or "").strip()
            station_id = str(row["station_id"] or "").strip()
            for model in payload_models(payload):
                bias_entry = model_bias.get(model) or {}
                shift = bias_to_unit(bias_entry.get("mean"), unit) or 0.0
                pred_label = corrected_top_bucket_for_model(
                    distribution, model, shift, rounding_rule, market_var
                )
                if not pred_label:
                    continue
                hit = 1 if pred_label == actual_label else 0
                expected = expected_value_from_model(distribution, model, rounding_rule, market_var)
                expected_c = to_celsius(expected, unit)
                gap = None
                if expected_c is not None and actual_c is not None:
                    gap = expected_c - actual_c
                if month_key:
                    key = (month_key, model)
                    entry = month_stats.setdefault(key, {"month": month_key, "model": model, "hit": 0, "count": 0, "gap_sum": 0.0, "gap_count": 0})
                    entry["count"] += 1
                    entry["hit"] += hit
                    if gap is not None:
                        entry["gap_sum"] += gap
                        entry["gap_count"] += 1
                if city:
                    key = (city, model)
                    entry = city_stats.setdefault(key, {"city": city, "model": model, "hit": 0, "count": 0, "gap_sum": 0.0, "gap_count": 0, "unit": "C"})
                    entry["count"] += 1
                    entry["hit"] += hit
                    if gap is not None:
                        entry["gap_sum"] += gap
                        entry["gap_count"] += 1
                if station_id:
                    key = (station_id, model)
                    entry = station_stats.setdefault(key, {"station_id": station_id, "station_city": city, "model": model, "hit": 0, "count": 0, "gap_sum": 0.0, "gap_count": 0, "unit": "C"})
                    entry["count"] += 1
                    entry["hit"] += hit
                    if gap is not None:
                        entry["gap_sum"] += gap
                        entry["gap_count"] += 1
        def finalize_rows(entries: Dict[Tuple[str, str], Dict[str, Any]]) -> List[Dict[str, Any]]:
            out = []
            for entry in entries.values():
                count = entry["count"]
                hit = entry["hit"]
                gap_count = entry.get("gap_count", 0) or 0
                avg_gap = (entry["gap_sum"] / gap_count) if gap_count else None
                out.append(
                    {
                        **{k: v for k, v in entry.items() if k not in ("gap_sum", "gap_count")},
                        "rate": hit / count if count else 0.0,
                        "weighted_rate": hit / count if count else 0.0,
                        "scenario_rate": hit / count if count else 0.0,
                        "avg_gap": avg_gap,
                        "unit": entry.get("unit") or "C",
                    }
                )
            return out
        return {
            "monthly_rows": finalize_rows(month_stats),
            "city_rows": finalize_rows(city_stats),
            "station_rows": finalize_rows(station_stats),
        }


def median(values: List[float]) -> Optional[float]:
    if not values:
        return None
    ordered = sorted(values)
    mid = len(ordered) // 2
    if len(ordered) % 2:
        return ordered[mid]
    return (ordered[mid - 1] + ordered[mid]) / 2.0


def _scoreboard_stats_uncached(days: int, lightweight: bool = False) -> Dict[str, Any]:
    if not DB_PATH.exists():
        return {
            "models": [],
            "weightings": [],
            "seasons": [],
            "availability_rows": [],
            "availability_total": 0,
            "auto_weight_rows": [],
            "auto_weight_label": "\u52a8\u6001\u6743\u91cd\u5206\u5e03",
            "prediction_hit_stats": {"ok": False, "na_reason": "db_missing", "days": int(days or 0)},
            "prediction_hit_stats_history": {"ok": False, "na_reason": "db_missing", "days": 0},
            "auto_trade_stats": {},
            "q_calibration_health": {},
            "trade_sync_status": load_trade_sync_status(),
        }
    with open_db(timeout_sec=SCOREBOARD_DB_TIMEOUT_SEC, busy_timeout_ms=SCOREBOARD_DB_BUSY_TIMEOUT_MS) as conn:
        cutoff = stats_cutoff_date()
        cutoff_text = cutoff.isoformat() if cutoff else ""
        settled_rows = load_auto_trade_runs(conn, days, require_settlement=True)
        model_bias = compute_model_bias_map(settled_rows)
        model_counts: Dict[str, int] = {}
        model_hits: Dict[str, int] = {}
        weight_stats = {
            "equal": {"hit": 0, "count": 0, "bias_sum": 0.0, "abs_sum": 0.0, "bias_count": 0, "cold": 0, "hot": 0, "flat": 0, "abs_list": []},
            "auto": {"hit": 0, "count": 0, "bias_sum": 0.0, "abs_sum": 0.0, "bias_count": 0, "cold": 0, "hot": 0, "flat": 0, "abs_list": []},
            "scenario": {"hit": 0, "count": 0, "bias_sum": 0.0, "abs_sum": 0.0, "bias_count": 0, "cold": 0, "hot": 0, "flat": 0, "abs_list": []},
        }
        season_stats: Dict[str, Dict[str, Dict[str, int]]] = {}
        for row in settled_rows:
            payload = safe_json_loads(row["payload_json"])
            distribution = normalize_distribution_rows(payload.get("rows") or [])
            if not distribution:
                continue
            actual_value = to_float(row["settlement_actual"])
            if actual_value is None:
                continue
            actual_label = actual_bucket_label(row, distribution)
            if not actual_label:
                continue
            models = payload_models(payload)
            weight_maps = resolve_weight_maps_for_row(row, distribution, models) if models else {}
            unit = str(row["market_unit"] or "")
            actual_c = to_celsius(actual_value, unit)
            rounding_rule = str(row["rounding_rule"] or "")
            market_var = str(row["market_var"] or "")
            for key in ("equal", "auto", "scenario"):
                predicted = predicted_bucket_for_weighting(row, distribution, key, models, weight_maps, strict_corrected=True)
                if predicted and actual_label:
                    weight_stats[key]["count"] += 1
                    if predicted == actual_label:
                        weight_stats[key]["hit"] += 1
                weights = (weight_maps or {}).get(key) if models else None
                expected = expected_value_from_distribution_weighted(
                    distribution,
                    models,
                    weights or {},
                    rounding_rule,
                    market_var,
                )
                if expected is None:
                    q_key = "q_equal" if key == "equal" else ("q_auto" if key == "auto" else "q_scenario")
                    expected = expected_value_from_distribution(distribution, q_key, rounding_rule, market_var)
                expected_c = to_celsius(expected, unit)
                if expected_c is not None and actual_c is not None:
                    err = expected_c - actual_c
                    weight_stats[key]["bias_sum"] += err
                    weight_stats[key]["abs_sum"] += abs(err)
                    weight_stats[key]["bias_count"] += 1
                    weight_stats[key]["abs_list"].append(abs(err))
                    if err > 1e-6:
                        weight_stats[key]["hot"] += 1
                    elif err < -1e-6:
                        weight_stats[key]["cold"] += 1
                    else:
                        weight_stats[key]["flat"] += 1
            season = season_label(to_float(row["lat"]), str(row["event_date"] or ""))
            season_entry = season_stats.setdefault(
                season,
                {
                    "equal": {"hit": 0, "count": 0},
                    "auto": {"hit": 0, "count": 0},
                    "scenario": {"hit": 0, "count": 0},
                },
            )
            for key in ("equal", "auto", "scenario"):
                predicted = predicted_bucket_for_weighting(row, distribution, key, models, weight_maps, strict_corrected=True)
                if not predicted or not actual_label:
                    continue
                season_entry[key]["count"] += 1
                if predicted == actual_label:
                    season_entry[key]["hit"] += 1
            for model in payload_models(payload):
                bias_entry = model_bias.get(model) or {}
                shift = bias_to_unit(bias_entry.get("mean"), unit) or 0.0
                pred_label = corrected_top_bucket_for_model(
                    distribution, model, shift, rounding_rule, market_var
                )
                if not pred_label:
                    continue
                model_counts[model] = model_counts.get(model, 0) + 1
                if pred_label == actual_label:
                    model_hits[model] = model_hits.get(model, 0) + 1
        models_list = []
        for model, count in model_counts.items():
            hit = model_hits.get(model, 0)
            models_list.append(
                {"model": model, "count": count, "hit": hit, "rate": hit / count if count else 0.0}
            )
        models_list.sort(key=lambda item: (-item["rate"], item["model"]))
        weightings = []
        for key in ("equal", "auto", "scenario"):
            entry = weight_stats[key]
            count = entry["count"]
            hit = entry["hit"]
            bias_count = entry["bias_count"]
            bias_mean = (entry["bias_sum"] / bias_count) if bias_count else None
            mae = (entry["abs_sum"] / bias_count) if bias_count else None
            medae = median(entry["abs_list"])
            weightings.append(
                {
                    "weighting": key,
                    "count": count,
                    "hit": hit,
                    "rate": hit / count if count else 0.0,
                    "bias_count": bias_count,
                    "bias_mean": bias_mean,
                    "mae": mae,
                    "medae": medae,
                    "cold": entry["cold"],
                    "hot": entry["hot"],
                    "flat": entry["flat"],
                }
            )
        seasons = []
        for season, data in season_stats.items():
            row = {"season": season}
            for key in ("equal", "auto", "scenario"):
                hit = data[key]["hit"]
                count = data[key]["count"]
                row[f"{key}_hit"] = hit
                row[f"{key}_count"] = count
                row[f"{key}_rate"] = hit / count if count else 0.0
            seasons.append(row)
        seasons.sort(key=lambda item: item["season"])
        availability_rows: List[Dict[str, Any]] = []
        availability_total = 0
        all_latest = load_auto_trade_runs(conn, days, require_settlement=False)
        available_counts: Dict[str, int] = {}
        total_events = 0
        for row in all_latest:
            payload = safe_json_loads(row["payload_json"])
            models = payload_models(payload)
            if not models:
                continue
            total_events += 1
            for model in models:
                available_counts[model] = available_counts.get(model, 0) + 1
        availability_total = total_events
        for model, available in available_counts.items():
            rate = available / availability_total if availability_total else 0.0
            availability_rows.append(
                {"model": model, "available": available, "total": availability_total, "rate": rate}
            )
        availability_rows.sort(key=lambda item: (-item["rate"], item["model"]))
        cur = conn.cursor()
        cur.execute("SELECT MAX(weight_date) FROM model_weights")
        weight_date_row = cur.fetchone()
        weight_date = weight_date_row[0] if weight_date_row else None
        auto_weight_rows = []
        if weight_date:
            cur.execute(
                "SELECT model, weight, created_at FROM model_weights WHERE weight_date = ? ORDER BY created_at DESC, id DESC",
                (weight_date,),
            )
            seen_models: set[str] = set()
            for model, weight, _created_at in cur.fetchall():
                model_key = str(model or "")
                if not model_key or model_key in seen_models:
                    continue
                seen_models.add(model_key)
                auto_weight_rows.append({"model": model_key, "weight": float(weight)})
        auto_trade = {
            "trade_count": 0,
            "fill_count": 0,
            "active_positions": 0,
            "realized_pnl": 0.0,
            "unrealized_pnl": 0.0,
            "total_pnl": 0.0,
            "last_updated": "",
        }
        try:
            position_overrides, _pos_err, _pos_updated = fetch_positions_cache(conn)
            event_status: Dict[Tuple[str, str], Dict[str, Any]] = {}
            try:
                ensure_fact_tables(conn)
            except Exception:
                event_status = {}

            def get_event_status(slug: str, event_date: str) -> Dict[str, Any]:
                slug_key = str(slug or "")
                date_key = date_only(str(event_date or ""))
                key = (slug_key, date_key)
                cached = event_status.get(key)
                if cached is not None:
                    return cached
                meta = _latest_event_meta_from_facts(conn, slug_key, date_key)
                cached = {
                    "settlement_actual": meta.get("settlement_actual"),
                    "market_closed": int(meta.get("market_closed") or 0),
                }
                event_status[key] = cached
                return cached
            cur.execute(
                """
                SELECT slug, event_date, state, position_size, avg_price, entry_price, realized_pnl, unrealized_pnl, updated_at, entry_at
                FROM edge_trades
                """
            )
            if position_overrides:
                for key, entry in position_overrides.items():
                    if cutoff and is_before_stats_cutoff(str(key[1] or "")):
                        continue
                    pos = to_float(entry.get("position_size")) or 0.0
                    if pos <= 0:
                        continue
                    avg_cost = to_float(entry.get("avg_price")) or 0.0
                    notional = pos * avg_cost if avg_cost else 0.0
                    status = get_event_status(str(key[0] or ""), str(key[1] or ""))
                    settled = to_float(status.get("settlement_actual")) is not None
                    closed = int(status.get("market_closed") or 0) == 1
                    if not settled and not closed and notional >= 1.0:
                        auto_trade["active_positions"] += 1
            for slug, event_date, state, position_size, avg_price, entry_price, realized_pnl, unrealized_pnl, updated_at, entry_at in cur.fetchall():
                cutoff_value = str(entry_at or "") or str(event_date or "")
                if cutoff and is_before_stats_cutoff(cutoff_value):
                    continue
                auto_trade["trade_count"] += 1
                if not position_overrides:
                    pos = to_float(position_size) or 0.0
                    if str(state or "") == "entry" and pos > 0:
                        avg_cost = to_float(avg_price)
                        if avg_cost is None:
                            avg_cost = to_float(entry_price)
                        notional = pos * avg_cost if avg_cost is not None else 0.0
                        status = get_event_status(str(slug or ""), str(event_date or ""))
                        settled = to_float(status.get("settlement_actual")) is not None
                        closed = int(status.get("market_closed") or 0) == 1
                        if not settled and not closed and notional >= 1.0:
                            auto_trade["active_positions"] += 1
                auto_trade["realized_pnl"] += to_float(realized_pnl) or 0.0
                auto_trade["unrealized_pnl"] += to_float(unrealized_pnl) or 0.0
                updated = str(updated_at or "")
                if updated and updated > auto_trade["last_updated"]:
                    auto_trade["last_updated"] = updated
            auto_trade["total_pnl"] = auto_trade["realized_pnl"] + auto_trade["unrealized_pnl"]
            try:
                fills_sql = """
                        SELECT trade_time, created_at
                        FROM edge_trade_fills
                        WHERE order_id IN (
                            SELECT order_id FROM auto_orders WHERE order_id IS NOT NULL AND order_id != ''
                        )
                        """
                fills_params: List[Any] = []
                if cutoff_text:
                    fills_sql += " AND (trade_time >= ? OR created_at >= ?)"
                    fills_params.extend([cutoff_text, cutoff_text])
                cur.execute(fills_sql, fills_params)
                count = 0
                for row in cur.fetchall():
                    ts = str(row["trade_time"] or row["created_at"] or "")
                    if ts and is_before_stats_cutoff(ts):
                        continue
                    count += 1
                auto_trade["fill_count"] = count
            except sqlite3.OperationalError:
                pass
        except sqlite3.OperationalError:
            pass
        daily_stats_payload = cached_auto_trade_daily_stats(conn)
        if isinstance(daily_stats_payload, dict) and daily_stats_payload:
            auto_trade.update(daily_stats_payload)
        else:
            auto_trade.update(compute_auto_trade_daily_stats(conn, lightweight=lightweight))
        if auto_trade.get("total_roi") is None:
            total_spend = to_float(auto_trade.get("total_buy_amount"))
            total_pnl = to_float(auto_trade.get("total_pnl"))
            if total_spend and total_spend > 0 and total_pnl is not None:
                auto_trade["total_roi"] = total_pnl / total_spend
            else:
                auto_trade["total_roi"] = None
        open_orders = list(OPEN_ORDER_CACHE.get("data") or [])[:80] if lightweight else compute_open_order_list(conn)
        trade_list = [] if lightweight else compute_global_order_list(conn)
        open_order_sync_error = str(OPEN_ORDER_CACHE.get("error") or "")
        open_order_sync_at = str(OPEN_ORDER_CACHE.get("updated_at") or "")
        position_sync_error = str(POSITIONS_CACHE.get("error") or "")
        position_sync_at = str(POSITIONS_CACHE.get("updated_at") or "")
        strategy_stats_today_date = _normalize_date_key(str(auto_trade.get("stats_today") or ""))
        if not strategy_stats_today_date:
            strategy_stats_today_date = _today_et_key()
        if lightweight:
            strategy_stats = compute_strategy_stats(conn, days)
            try:
                entry_quality = compute_strategy_entry_quality(conn, days)
                if isinstance(entry_quality, dict):
                    for key, payload in entry_quality.items():
                        k = str(key or "").strip().lower()
                        if not k or not isinstance(payload, dict):
                            continue
                        if k in strategy_stats and isinstance(strategy_stats.get(k), dict):
                            strategy_stats[k].update(payload)
            except Exception:
                pass
            strategy_stats_today = compute_strategy_stats(
                conn,
                1,
                run_date=strategy_stats_today_date,
            )
            try:
                entry_quality_today = compute_strategy_entry_quality(
                    conn,
                    1,
                    run_date=strategy_stats_today_date,
                )
                if isinstance(entry_quality_today, dict):
                    for key, payload in entry_quality_today.items():
                        k = str(key or "").strip().lower()
                        if not k or not isinstance(payload, dict):
                            continue
                        if k in strategy_stats_today and isinstance(strategy_stats_today.get(k), dict):
                            strategy_stats_today[k].update(payload)
            except Exception:
                pass
            edge_waterfall = {}
            try:
                orphan_days = int(os.environ.get("PM_ORPHAN_FILL_STATS_DAYS", "60") or 60)
            except Exception:
                orphan_days = 60
            orphan_fill_stats = {"ok": False, "na_reason": "refresh_pending", "days": int(orphan_days)}
        else:
            strategy_stats = compute_strategy_stats(conn, days)
            try:
                entry_quality = compute_strategy_entry_quality(conn, days)
                if isinstance(entry_quality, dict):
                    for key, payload in entry_quality.items():
                        k = str(key or "").strip().lower()
                        if not k or not isinstance(payload, dict):
                            continue
                        if k in strategy_stats and isinstance(strategy_stats.get(k), dict):
                            strategy_stats[k].update(payload)
            except Exception:
                pass
            strategy_stats_today = compute_strategy_stats(
                conn,
                1,
                run_date=strategy_stats_today_date,
            )
            try:
                entry_quality_today = compute_strategy_entry_quality(
                    conn,
                    1,
                    run_date=strategy_stats_today_date,
                )
                if isinstance(entry_quality_today, dict):
                    for key, payload in entry_quality_today.items():
                        k = str(key or "").strip().lower()
                        if not k or not isinstance(payload, dict):
                            continue
                        if k in strategy_stats_today and isinstance(strategy_stats_today.get(k), dict):
                            strategy_stats_today[k].update(payload)
            except Exception:
                pass
            edge_waterfall = {}
            try:
                edge_waterfall = compute_edge_waterfall(conn, days, include_mirror=False)
                merge_edge_waterfall_realized(edge_waterfall, strategy_stats)
                try:
                    blockers = compute_positive_exec_edge_blockers(conn, days, include_mirror=False)
                    if isinstance(blockers, dict):
                        edge_waterfall["blockers"] = blockers
                except Exception:
                    pass
            except Exception:
                edge_waterfall = {}
            orphan_fill_stats: Dict[str, Any] = {"ok": False, "na_reason": "not_computed"}
            try:
                orphan_days = int(os.environ.get("PM_ORPHAN_FILL_STATS_DAYS", "60") or 60)
            except Exception:
                orphan_days = 60
            try:
                orphan_fill_stats = compute_orphan_fill_stats(
                    conn,
                    int(orphan_days),
                    max_rows=240,
                    writeback=False,
                )
            except Exception as exc:
                orphan_fill_stats = {"ok": False, "error": f"{exc.__class__.__name__}: {exc}", "days": int(orphan_days)}
        return {
            "models": models_list,
            "weightings": weightings,
            "seasons": seasons,
            "availability_rows": availability_rows,
            "availability_total": availability_total,
            "auto_weight_rows": auto_weight_rows,
            "auto_weight_label": "\u52a8\u6001\u6743\u91cd\u5206\u5e03",
            "prediction_hit_stats": prediction_hit_stats(int(days or 30)),
            "prediction_hit_stats_history": prediction_hit_stats(0),
            "auto_trade_stats": auto_trade,
            "strategy_stats": strategy_stats,
            "strategy_stats_today": strategy_stats_today,
            "strategy_stats_today_date": strategy_stats_today_date,
            "edge_waterfall": edge_waterfall,
            "orphan_fill_stats": orphan_fill_stats,
            "trade_list": trade_list,
            "order_list": trade_list,
            "open_order_list": open_orders,
            "open_order_sync_error": open_order_sync_error,
            "open_order_sync_at": open_order_sync_at,
            "position_sync_error": position_sync_error,
            "position_sync_at": position_sync_at,
            "q_calibration_health": load_q_calibration_health(conn, days=max(30, int(days or 30))),
            "trade_sync_status": load_trade_sync_status(),
        }


def _scoreboard_base_payload() -> Dict[str, Any]:
    try:
        orphan_days = int(os.environ.get("PM_ORPHAN_FILL_STATS_DAYS", "60") or 60)
    except Exception:
        orphan_days = 60
    return {
        "models": [],
        "weightings": [],
        "seasons": [],
        "availability_rows": [],
        "availability_total": 0,
        "auto_weight_rows": [],
        "auto_weight_label": "\u52a8\u6001\u6743\u91cd\u5206\u5e03",
        "prediction_hit_stats": {"ok": False, "na_reason": "refresh_pending", "days": int(SCOREBOARD_DAYS_DEFAULT)},
        "prediction_hit_stats_history": {"ok": False, "na_reason": "refresh_pending", "days": 0},
        "auto_trade_stats": {},
        "strategy_stats": strategy_stats_defaults(),
        "strategy_stats_today": strategy_stats_defaults(),
        "strategy_stats_today_date": _today_et_key(),
        # Bootstrap: scoreboard may return before the background refresh completes.
        # Use a non-misleading NA reason and include days for UI.
        "orphan_fill_stats": {"ok": False, "na_reason": "refresh_pending", "days": int(orphan_days)},
        "trade_list": [],
        "order_list": [],
        "open_order_list": list(OPEN_ORDER_CACHE.get("data") or [])[:80],
        "open_order_sync_error": str(OPEN_ORDER_CACHE.get("error") or ""),
        "open_order_sync_at": str(OPEN_ORDER_CACHE.get("updated_at") or ""),
        "position_sync_error": str(POSITIONS_CACHE.get("error") or ""),
        "position_sync_at": str(POSITIONS_CACHE.get("updated_at") or ""),
        "q_calibration_health": {},
        "trade_sync_status": load_trade_sync_status(),
    }


def _strategy_stats_has_data(raw_stats: Any) -> bool:
    if not isinstance(raw_stats, dict) or not raw_stats:
        return False
    for entry in raw_stats.values():
        if not isinstance(entry, dict):
            continue
        for key in (
            "order_count",
            "entry_order_count",
            "exit_order_count",
            "trade_count",
            "open_trade_count",
            "buy_fill_count",
            "sell_fill_count",
            "win_count",
            "loss_count",
        ):
            val = to_float(entry.get(key))
            if val is not None and abs(val) > 1e-9:
                return True
        pnl = to_float(entry.get("total_pnl"))
        if pnl is not None and abs(pnl) > 1e-9:
            return True
        if entry.get("roi") is not None or entry.get("win_rate") is not None:
            return True
    return False


def _scoreboard_merge_live_fields(payload: Optional[Dict[str, Any]], days: Optional[int] = None) -> Dict[str, Any]:
    base = dict(payload or {})
    base["trade_sync_status"] = load_trade_sync_status()
    try:
        hit_days = int(days or base.get("days") or SCOREBOARD_DAYS_DEFAULT)
    except Exception:
        hit_days = SCOREBOARD_DAYS_DEFAULT
    base["prediction_hit_stats"] = prediction_hit_stats(max(1, int(hit_days)))
    base["prediction_hit_stats_history"] = prediction_hit_stats(0)
    if OPEN_ORDER_CACHE.get("updated_at"):
        base["open_order_sync_at"] = str(OPEN_ORDER_CACHE.get("updated_at") or "")
    if OPEN_ORDER_CACHE.get("error"):
        base["open_order_sync_error"] = str(OPEN_ORDER_CACHE.get("error") or "")
    if POSITIONS_CACHE.get("updated_at"):
        base["position_sync_at"] = str(POSITIONS_CACHE.get("updated_at") or "")
    if POSITIONS_CACHE.get("error"):
        base["position_sync_error"] = str(POSITIONS_CACHE.get("error") or "")
    auto_trade_stats = base.get("auto_trade_stats")
    today_key = _normalize_date_key(
        str((auto_trade_stats or {}).get("stats_today") if isinstance(auto_trade_stats, dict) else "")
    )
    if not today_key:
        today_key = _today_et_key()
    if not isinstance(base.get("strategy_stats_today"), dict):
        base["strategy_stats_today"] = strategy_stats_defaults()
    if not str(base.get("strategy_stats_today_date") or "").strip():
        base["strategy_stats_today_date"] = today_key
    return base


def _scoreboard_bootstrap_auto_trade_stats(base_payload: Dict[str, Any]) -> Dict[str, Any]:
    if not SCOREBOARD_BOOTSTRAP_SYNC_ENABLED or base_payload.get("auto_trade_stats"):
        return base_payload
    try:
        with open_db_ro_fast(
            timeout_sec=SCOREBOARD_BOOTSTRAP_DB_TIMEOUT_SEC,
            busy_timeout_ms=SCOREBOARD_BOOTSTRAP_DB_BUSY_TIMEOUT_MS,
        ) as conn:
            # Bootstrap payload should still carry real order/fill stats so the
            # overview card does not flash to zeros before async refresh completes.
            base_payload["auto_trade_stats"] = cached_auto_trade_daily_stats(conn)
            today_key = _normalize_date_key(str((base_payload.get("auto_trade_stats") or {}).get("stats_today") or ""))
            if today_key:
                base_payload["strategy_stats_today_date"] = today_key
    except Exception:
        pass
    return base_payload


def _scoreboard_bootstrap_strategy_stats(base_payload: Dict[str, Any], days: int) -> Dict[str, Any]:
    current = base_payload.get("strategy_stats")
    current_today = base_payload.get("strategy_stats_today")
    need_main = not _strategy_stats_has_data(current)
    need_today = not _strategy_stats_has_data(current_today)
    if not isinstance(base_payload.get("strategy_stats_today"), dict):
        base_payload["strategy_stats_today"] = strategy_stats_defaults()
    today_key = _normalize_date_key(str(base_payload.get("strategy_stats_today_date") or ""))
    if not today_key:
        today_key = _today_et_key()
        base_payload["strategy_stats_today_date"] = today_key
    if not SCOREBOARD_BOOTSTRAP_STRATEGY_SYNC_ENABLED or (not need_main and not need_today):
        # Still allow orphan-fill stats to be bootstrapped even if strategy stats are already present.
        if not SCOREBOARD_BOOTSTRAP_ORPHAN_FILL_SYNC_ENABLED:
            return base_payload
        orphan_stats = base_payload.get("orphan_fill_stats")
        if isinstance(orphan_stats, dict) and orphan_stats.get("ok") is True:
            return base_payload
        try:
            orphan_days = int(os.environ.get("PM_ORPHAN_FILL_STATS_DAYS", "60") or 60)
        except Exception:
            orphan_days = 60
        try:
            with open_db_ro_fast(
                timeout_sec=SCOREBOARD_BOOTSTRAP_DB_TIMEOUT_SEC,
                busy_timeout_ms=SCOREBOARD_BOOTSTRAP_DB_BUSY_TIMEOUT_MS,
            ) as conn:
                base_payload["orphan_fill_stats"] = compute_orphan_fill_stats(
                    conn,
                    int(orphan_days),
                    max_rows=0,
                    writeback=False,
                )
        except Exception as exc:
            base_payload["orphan_fill_stats"] = {
                "ok": False,
                "error": f"{exc.__class__.__name__}: {exc}",
                "days": int(orphan_days),
            }
        return base_payload
    stats_days = max(1, int(days or SCOREBOARD_DAYS_DEFAULT))
    try:
        with open_db_ro_fast(
            timeout_sec=SCOREBOARD_BOOTSTRAP_DB_TIMEOUT_SEC,
            busy_timeout_ms=SCOREBOARD_BOOTSTRAP_DB_BUSY_TIMEOUT_MS,
        ) as conn:
            if need_main:
                base_payload["strategy_stats"] = compute_strategy_stats(conn, stats_days)
            if need_today:
                base_payload["strategy_stats_today"] = compute_strategy_stats(
                    conn,
                    1,
                    run_date=today_key,
                )
            if SCOREBOARD_BOOTSTRAP_ORPHAN_FILL_SYNC_ENABLED:
                orphan_stats = base_payload.get("orphan_fill_stats")
                if not (isinstance(orphan_stats, dict) and orphan_stats.get("ok") is True):
                    try:
                        orphan_days = int(os.environ.get("PM_ORPHAN_FILL_STATS_DAYS", "60") or 60)
                    except Exception:
                        orphan_days = 60
                    base_payload["orphan_fill_stats"] = compute_orphan_fill_stats(
                        conn,
                        int(orphan_days),
                        max_rows=0,
                        writeback=False,
                    )
    except Exception:
        pass
    return base_payload


def _scoreboard_attach_meta(
    payload: Dict[str, Any],
    *,
    cached: bool,
    stale: bool,
    refreshing: bool,
    age_sec: float,
    degraded: bool = False,
    error: str = "",
) -> Dict[str, Any]:
    merged = dict(payload or {})
    merged["scoreboard_cached"] = bool(cached)
    merged["scoreboard_stale"] = bool(stale)
    merged["scoreboard_refreshing"] = bool(refreshing)
    merged["scoreboard_age_sec"] = int(max(0.0, float(age_sec or 0.0)))
    if degraded:
        merged["scoreboard_degraded"] = True
    if error:
        merged["scoreboard_error"] = str(error)
    return merged


def _scoreboard_stats_lightweight(days: int) -> Dict[str, Any]:
    payload = _scoreboard_base_payload()
    if not DB_PATH.exists():
        return payload
    stats_days = max(1, int(days or SCOREBOARD_DAYS_DEFAULT))
    try:
        with open_db_ro_fast(
            timeout_sec=SCOREBOARD_BOOTSTRAP_DB_TIMEOUT_SEC,
            busy_timeout_ms=SCOREBOARD_BOOTSTRAP_DB_BUSY_TIMEOUT_MS,
        ) as conn:
            daily_stats = cached_auto_trade_daily_stats(conn)
            payload["auto_trade_stats"] = daily_stats if isinstance(daily_stats, dict) else {}
            today_key = _normalize_date_key(str((payload.get("auto_trade_stats") or {}).get("stats_today") or ""))
            if not today_key:
                today_key = _today_et_key()
            payload["strategy_stats_today_date"] = today_key
            strategy_stats = compute_strategy_stats(conn, stats_days)
            strategy_stats_today = compute_strategy_stats(conn, 1, run_date=today_key)
            try:
                entry_quality = compute_strategy_entry_quality(conn, stats_days)
                if isinstance(entry_quality, dict):
                    for key, entry in entry_quality.items():
                        k = str(key or "").strip().lower()
                        if not k or not isinstance(entry, dict):
                            continue
                        if k in strategy_stats and isinstance(strategy_stats.get(k), dict):
                            strategy_stats[k].update(entry)
            except Exception:
                pass
            try:
                entry_quality_today = compute_strategy_entry_quality(conn, 1, run_date=today_key)
                if isinstance(entry_quality_today, dict):
                    for key, entry in entry_quality_today.items():
                        k = str(key or "").strip().lower()
                        if not k or not isinstance(entry, dict):
                            continue
                        if k in strategy_stats_today and isinstance(strategy_stats_today.get(k), dict):
                            strategy_stats_today[k].update(entry)
            except Exception:
                pass
            payload["strategy_stats"] = strategy_stats
            payload["strategy_stats_today"] = strategy_stats_today
            payload["q_calibration_health"] = load_q_calibration_health(conn, days=max(30, int(stats_days)))
    except Exception:
        return payload
    return payload


def _scoreboard_refresh_worker(days: int) -> None:
    payload: Optional[Dict[str, Any]] = None
    error_text = ""
    worker = threading.current_thread()
    try:
        if SCOREBOARD_REFRESH_HEAVY_ENABLED:
            payload = _scoreboard_stats_uncached(days, lightweight=False)
        else:
            payload = _scoreboard_stats_lightweight(days)
    except Exception as exc:
        error_text = str(exc)
    finished_ts = time.time()
    with SCOREBOARD_CACHE_LOCK:
        entry = SCOREBOARD_CACHE.setdefault(days, {})
        entry["refreshing"] = False
        entry["refresh_started_ts"] = 0.0
        if payload is not None:
            entry["payload"] = payload
            entry["ts"] = finished_ts
            entry["error"] = ""
            entry["error_at"] = ""
        else:
            entry["error"] = error_text or "scoreboard_refresh_failed"
            entry["error_at"] = now_text()
        tracked = SCOREBOARD_REFRESH_THREADS.get(days)
        if tracked is worker or tracked is None or not tracked.is_alive():
            SCOREBOARD_REFRESH_THREADS.pop(days, None)


def _start_scoreboard_refresh(days: int) -> None:
    start_worker = False
    now_ts = time.time()
    worker: Optional[threading.Thread] = None
    with SCOREBOARD_CACHE_LOCK:
        entry = SCOREBOARD_CACHE.setdefault(days, {"ts": 0.0, "payload": None, "refreshing": False, "error": "", "error_at": "", "refresh_started_ts": 0.0})
        tracked = SCOREBOARD_REFRESH_THREADS.get(days)
        if tracked is not None and tracked.is_alive():
            refresh_started_ts = float(entry.get("refresh_started_ts") or 0.0)
            if refresh_started_ts > 0 and (now_ts - refresh_started_ts) > SCOREBOARD_REFRESH_TIMEOUT_SEC:
                entry["error"] = str(entry.get("error") or "scoreboard_refresh_slow")
                entry["error_at"] = now_text()
                entry["refreshing"] = False
                entry["refresh_started_ts"] = 0.0
                SCOREBOARD_REFRESH_THREADS.pop(days, None)
            else:
                if not entry.get("refreshing"):
                    entry["error"] = str(entry.get("error") or "scoreboard_refresh_slow")
                    entry["error_at"] = now_text()
                return
        if tracked is not None and not tracked.is_alive():
            SCOREBOARD_REFRESH_THREADS.pop(days, None)
        if not entry.get("refreshing") or not tracked:
            entry["refreshing"] = True
            entry["refresh_started_ts"] = now_ts
            start_worker = True
    if start_worker:
        worker = threading.Thread(target=_scoreboard_refresh_worker, args=(days,), daemon=True)
        with SCOREBOARD_CACHE_LOCK:
            SCOREBOARD_REFRESH_THREADS[days] = worker
        worker.start()


def scoreboard_stats(days: int) -> Dict[str, Any]:
    if not DB_PATH.exists():
        return _scoreboard_attach_meta(
            _scoreboard_base_payload(),
            cached=False,
            stale=True,
            refreshing=False,
            age_sec=0,
            degraded=True,
            error="db_missing",
        )
    now_ts = time.time()
    with SCOREBOARD_CACHE_LOCK:
        cache_entry = dict(SCOREBOARD_CACHE.get(days) or {})
    cached_payload = cache_entry.get("payload") if isinstance(cache_entry.get("payload"), dict) else None
    cache_ts = float(cache_entry.get("ts") or 0.0)
    cache_age = max(0.0, now_ts - cache_ts) if cache_ts else 0.0
    cache_error = str(cache_entry.get("error") or "")
    refreshing = bool(cache_entry.get("refreshing"))
    refresh_started_ts = float(cache_entry.get("refresh_started_ts") or 0.0)
    refresh_timed_out_alive = False
    refresh_elapsed_sec = 0.0
    if refreshing:
        if refresh_started_ts > 0:
            refresh_elapsed_sec = max(0.0, now_ts - refresh_started_ts)
        elif cached_payload and cache_ts:
            # Recover from stale cache records where refresh_started_ts was lost.
            refresh_elapsed_sec = cache_age

    if refreshing and refresh_elapsed_sec > SCOREBOARD_REFRESH_TIMEOUT_SEC:
        with SCOREBOARD_CACHE_LOCK:
            tracked = SCOREBOARD_REFRESH_THREADS.get(days)
            thread_alive = bool(tracked is not None and tracked.is_alive())
        if thread_alive:
            cache_error = cache_error or "scoreboard_refresh_slow"
            refresh_timed_out_alive = True
            refreshing = False
            with SCOREBOARD_CACHE_LOCK:
                entry = SCOREBOARD_CACHE.setdefault(days, {})
                entry["refreshing"] = False
                entry["refresh_started_ts"] = 0.0
                entry["error"] = cache_error
                entry["error_at"] = now_text()
        else:
            cache_error = cache_error or "scoreboard_refresh_timeout"
            with SCOREBOARD_CACHE_LOCK:
                entry = SCOREBOARD_CACHE.setdefault(days, {})
                entry["refreshing"] = False
                entry["refresh_started_ts"] = 0.0
                entry["error"] = cache_error
                entry["error_at"] = now_text()
            refreshing = False

    if cached_payload and cache_ts and cache_age <= SCOREBOARD_CACHE_MAX_AGE_SEC:
        return _scoreboard_attach_meta(
            _scoreboard_merge_live_fields(cached_payload, days=days),
            cached=True,
            stale=False,
            refreshing=refreshing,
            age_sec=cache_age,
            error=cache_error,
        )

    if not refreshing and not refresh_timed_out_alive:
        _start_scoreboard_refresh(days)
        with SCOREBOARD_CACHE_LOCK:
            refreshing = bool((SCOREBOARD_CACHE.get(days) or {}).get("refreshing"))

    if cached_payload:
        return _scoreboard_attach_meta(
            _scoreboard_merge_live_fields(cached_payload, days=days),
            cached=True,
            stale=True,
            refreshing=refreshing,
            age_sec=cache_age,
            degraded=bool(cache_error),
            error=cache_error,
        )

    base_payload = _scoreboard_base_payload()
    if cache_error:
        base_payload["scoreboard_bootstrap_error"] = cache_error
    base_payload = _scoreboard_bootstrap_auto_trade_stats(base_payload)
    base_payload = _scoreboard_bootstrap_strategy_stats(base_payload, days)
    return _scoreboard_attach_meta(
        base_payload,
        cached=False,
        stale=True,
        refreshing=refreshing,
        age_sec=0,
        degraded=True,
        error=cache_error,
    )


def latest_run_date(conn: sqlite3.Connection) -> str:
    cur = conn.cursor()
    cur.execute(
        """
        SELECT run_date
        FROM event_runs
        WHERE run_date IS NOT NULL AND run_date != ''
        ORDER BY id DESC
        LIMIT 1
        """
    )
    row = cur.fetchone()
    if not row:
        return ""
    key = _normalize_date_key(str(row["run_date"] or ""))
    parsed = parse_date(key)
    return parsed.isoformat() if parsed is not None else ""


def latest_fact_run_date(conn: sqlite3.Connection) -> str:
    try:
        ensure_fact_tables(conn)
    except Exception:
        return ""
    cur = conn.cursor()
    cur.execute(
        """
        SELECT run_date
        FROM event_fact_history
        WHERE run_date IS NOT NULL AND run_date != ''
        GROUP BY run_date
        ORDER BY MAX(COALESCE(fact_as_of, created_at)) DESC, run_date DESC
        LIMIT 1
        """
    )
    row = cur.fetchone()
    if not row:
        return ""
    key = _normalize_date_key(str(row["run_date"] or ""))
    parsed = parse_date(key)
    return parsed.isoformat() if parsed is not None else ""


def latest_unsettled_run_date(conn: sqlite3.Connection) -> str:
    cur = conn.cursor()
    cur.execute(
        """
        SELECT run_date
        FROM event_runs
        WHERE run_date IS NOT NULL AND run_date != ''
          AND (settlement_actual IS NULL OR settlement_actual = '')
        ORDER BY id DESC
        LIMIT 1
        """
    )
    row = cur.fetchone()
    if not row:
        return ""
    key = _normalize_date_key(str(row["run_date"] or ""))
    parsed = parse_date(key)
    return parsed.isoformat() if parsed is not None else ""


def latest_run_date_fast(conn: sqlite3.Connection) -> str:
    """Read latest run_date without running DDL helpers."""
    cur = conn.cursor()
    for sql in (
        """
        SELECT run_date
        FROM event_runs
        WHERE run_date IS NOT NULL AND run_date != ''
          AND (settlement_actual IS NULL OR settlement_actual = '')
        ORDER BY id DESC
        LIMIT 1
        """,
        """
        SELECT run_date
        FROM event_runs
        WHERE run_date IS NOT NULL AND run_date != ''
        ORDER BY id DESC
        LIMIT 1
        """,
        """
        SELECT run_date
        FROM event_fact_history
        WHERE run_date IS NOT NULL AND run_date != ''
        ORDER BY id DESC
        LIMIT 1
        """,
    ):
        try:
            cur.execute(sql)
            row = cur.fetchone()
        except sqlite3.OperationalError:
            continue
        if not row:
            continue
        val = _normalize_date_key(str(row["run_date"] or "").strip())
        parsed = parse_date(val)
        if parsed is not None:
            return parsed.isoformat()
    return ""


def latest_fact_run_date_with_rows(conn: sqlite3.Connection, max_scan: int = 14) -> str:
    limit = max(1, int(max_scan or 1))
    cur = conn.cursor()
    try:
        cur.execute(
            """
            SELECT run_date
            FROM event_fact_history
            WHERE run_date IS NOT NULL AND run_date != ''
            GROUP BY run_date
            ORDER BY run_date DESC, MAX(COALESCE(fact_as_of, created_at)) DESC
            LIMIT ?
            """,
            (limit,),
        )
        rows = cur.fetchall()
    except sqlite3.OperationalError:
        return ""
    for row in rows:
        key = _normalize_date_key(str(row["run_date"] or "").strip())
        parsed = parse_date(key)
        if parsed is None:
            continue
        date_key = parsed.isoformat()
        try:
            if count_event_fact_rows(conn, date_key) > 0:
                return date_key
        except sqlite3.OperationalError:
            continue
    return ""


def _ui_now_utc() -> datetime:
    """Return the clock used only for read-only dashboard date selection."""

    return datetime.now(timezone.utc)


def _ui_event_window_ended(conn: sqlite3.Connection, event_date: str) -> bool:
    """Tell the dashboard whether an event day has passed its published end.

    A settled fact is not required here: the market end is the display-day
    boundary, while posterior materialization may legitimately arrive later.
    The function is deliberately read-only and returns ``False`` when no
    trustworthy end/closed signal is available, preserving the current day.
    """

    date_key = _normalize_date_key(event_date)
    if not date_key:
        return False
    now_utc = _ui_now_utc()
    end_times: List[datetime] = []
    closed_signal = False
    open_signal = False

    def _record_end(raw: Any) -> None:
        value = parse_iso_ts(str(raw or "").strip())
        if value is None:
            return
        if value.tzinfo is None:
            value = value.replace(tzinfo=timezone.utc)
        end_times.append(value.astimezone(timezone.utc))

    try:
        if _sqlite_table_exists(conn, "event_runs"):
            rows = conn.execute(
                """
                SELECT event_end_utc, settlement_actual, market_closed
                FROM event_runs
                WHERE event_date = ?
                """,
                (date_key,),
            ).fetchall()
            for row in rows or []:
                _record_end(row["event_end_utc"] if isinstance(row, sqlite3.Row) else row[0])
                settled = row["settlement_actual"] if isinstance(row, sqlite3.Row) else row[1]
                market_closed = row["market_closed"] if isinstance(row, sqlite3.Row) else row[2]
                if market_closed in (1, True, "1", "true") or settled not in (None, ""):
                    closed_signal = True
                else:
                    open_signal = True
    except sqlite3.Error:
        pass

    try:
        if _sqlite_table_exists(conn, "event_fact_latest") and _sqlite_table_exists(conn, "event_fact_history"):
            rows = conn.execute(
                """
                SELECT h.fact_json
                FROM event_fact_latest l
                JOIN event_fact_history h ON h.id = l.fact_id
                WHERE l.event_date = ?
                """,
                (date_key,),
            ).fetchall()
            for row in rows or []:
                payload = safe_json_loads(str(row["fact_json"] if isinstance(row, sqlite3.Row) else row[0] or ""))
                if not isinstance(payload, Mapping):
                    continue
                _record_end(payload.get("event_end_utc"))
                if _truthy(payload.get("market_closed")) or payload.get("settlement_actual") not in (None, ""):
                    closed_signal = True
                elif payload.get("event_end_utc"):
                    open_signal = True
    except sqlite3.Error:
        pass

    try:
        if _sqlite_table_exists(conn, "weather_market_discovery"):
            rows = conn.execute(
                """
                SELECT details_json
                FROM weather_market_discovery
                WHERE event_date = ?
                  AND COALESCE(status, '') IN ('tokenized', 'known_recent')
                """,
                (date_key,),
            ).fetchall()
            for row in rows or []:
                details = safe_json_loads(str(row["details_json"] if isinstance(row, sqlite3.Row) else row[0] or ""))
                if not isinstance(details, Mapping):
                    continue
                _record_end(details.get("endDate") or details.get("end_date") or details.get("event_end_utc"))
                if _truthy(details.get("closed")) or _truthy(details.get("resolved")):
                    closed_signal = True
                elif details.get("endDate") or details.get("end_date") or details.get("event_end_utc"):
                    open_signal = True
    except sqlite3.Error:
        pass

    if end_times:
        # Any published market for this day still open keeps the dashboard on
        # the current day.  Once every known end is past, advance even if the
        # settlement/posterior row has not been written yet.
        return bool(all(end <= now_utc for end in end_times))
    return bool(closed_signal and not open_signal)


def _ui_earliest_published_market_date(
    conn: sqlite3.Connection,
    start_date: str,
    *,
    max_scan: int = 14,
) -> str:
    """Find the earliest future market day that is actually published.

    This is a read-model lookup only.  Tokenized discovery is preferred; the
    registry and already-persisted facts are fallbacks for a brief discovery
    or materialization race.
    """

    start_key = _normalize_date_key(start_date)
    start_date_obj = parse_date(start_key)
    if start_date_obj is None:
        return ""
    end_key = (start_date_obj + timedelta(days=max(1, int(max_scan or 1)))).isoformat()
    dates: Set[str] = set()

    try:
        if _sqlite_table_exists(conn, "weather_market_discovery"):
            has_tokens = _sqlite_table_exists(conn, "market_tokens")
            if has_tokens:
                rows = conn.execute(
                    """
                    WITH token_latest AS (
                      SELECT slug, event_date,
                             COUNT(*) AS token_count,
                             SUM(CASE
                                   WHEN COALESCE(market_closed, 0) = 0
                                    AND COALESCE(market_archived, 0) = 0
                                    AND COALESCE(market_active, 1) != 0
                                    AND COALESCE(market_accepting_orders, 1) != 0
                                   THEN 1 ELSE 0
                                 END) AS active_token_count
                      FROM market_tokens
                      WHERE event_date >= ? AND event_date <= ?
                      GROUP BY slug, event_date
                    )
                    SELECT DISTINCT wd.event_date
                    FROM weather_market_discovery wd
                    LEFT JOIN token_latest tl
                      ON tl.slug = wd.slug AND tl.event_date = wd.event_date
                    WHERE wd.event_date >= ? AND wd.event_date <= ?
                      AND COALESCE(wd.status, '') IN ('tokenized', 'known_recent')
                      AND COALESCE(NULLIF(wd.token_count, 0), tl.token_count, 0) >= 2
                      AND COALESCE(tl.active_token_count, wd.token_count, 0) > 0
                    ORDER BY wd.event_date ASC
                    """,
                    (start_key, end_key, start_key, end_key),
                ).fetchall()
            else:
                rows = conn.execute(
                    """
                    SELECT DISTINCT event_date
                    FROM weather_market_discovery
                    WHERE event_date >= ? AND event_date <= ?
                      AND COALESCE(status, '') IN ('tokenized', 'known_recent')
                      AND COALESCE(token_count, 0) >= 2
                    ORDER BY event_date ASC
                    """,
                    (start_key, end_key),
                ).fetchall()
            for row in rows or []:
                key = _normalize_date_key(str(row["event_date"] if isinstance(row, sqlite3.Row) else row[0] or ""))
                if key:
                    dates.add(key)
    except sqlite3.Error:
        pass

    try:
        if _sqlite_table_exists(conn, "reported_trajectory_market_registry"):
            rows = conn.execute(
                """
                SELECT event_date
                FROM reported_trajectory_market_registry
                WHERE event_date >= ? AND event_date <= ?
                  AND source_eligible = 1
                  AND COALESCE(market_active, 0) = 1
                  AND COALESCE(market_accepting_orders, 0) = 1
                GROUP BY event_date
                HAVING COUNT(DISTINCT slug) > 0
                ORDER BY event_date ASC
                """,
                (start_key, end_key),
            ).fetchall()
            for row in rows or []:
                key = _normalize_date_key(str(row["event_date"] if isinstance(row, sqlite3.Row) else row[0] or ""))
                if key:
                    dates.add(key)
    except sqlite3.Error:
        pass

    try:
        if _sqlite_table_exists(conn, "event_fact_latest"):
            rows = conn.execute(
                """
                SELECT DISTINCT event_date
                FROM event_fact_latest
                WHERE event_date >= ? AND event_date <= ?
                ORDER BY event_date ASC
                """,
                (start_key, end_key),
            ).fetchall()
            for row in rows or []:
                key = _normalize_date_key(str(row["event_date"] if isinstance(row, sqlite3.Row) else row[0] or ""))
                if key:
                    dates.add(key)
    except sqlite3.Error:
        pass

    return min(dates) if dates else ""


def latest_ui_default_run_date(conn: sqlite3.Connection, max_scan: int = 14) -> str:
    """Choose the earliest still-open published day for the dashboard.

    The current day remains selected while its market window is open.  After
    the window ends, selection advances to the earliest published future day;
    that day may still be shown as a market-only placeholder while production
    posterior materialization catches up.
    """

    today_key = _normalize_date_key(_chengdu_today_date_key())
    today_has_rows = False
    if today_key:
        try:
            today_has_rows = count_event_fact_rows(
                conn,
                today_key,
                include_upcoming=True,
                upcoming_days=_ui_upcoming_days(),
            ) > 0
            if today_has_rows and not _ui_event_window_ended(conn, today_key):
                return today_key
        except sqlite3.OperationalError:
            pass
        except Exception:
            pass

    if today_key:
        next_day = _date_key_offset(today_key, 1)
        published = _ui_earliest_published_market_date(conn, next_day, max_scan=max_scan)
        if published:
            return published

    # If discovery is momentarily behind, use the earliest persisted future
    # fact rather than the newest (which could skip an intermediate market day).
    future_fact = ""
    if today_key:
        try:
            rows = conn.execute(
                """
                SELECT event_date
                FROM event_fact_latest
                WHERE event_date > ?
                GROUP BY event_date
                ORDER BY event_date ASC
                LIMIT ?
                """,
                (today_key, max(1, int(max_scan or 1))),
            ).fetchall()
            for row in rows or []:
                future_fact = _normalize_date_key(str(row["event_date"] if isinstance(row, sqlite3.Row) else row[0] or ""))
                if future_fact:
                    break
        except sqlite3.Error:
            future_fact = ""
    if future_fact:
        return future_fact

    latest = _normalize_date_key(latest_fact_run_date_with_rows(conn, max_scan=max_scan))
    if latest:
        return latest
    return today_key or latest_run_date_fast(conn)


def query_edge_trades(conn: sqlite3.Connection) -> Dict[Tuple[str, str], List[sqlite3.Row]]:
    cur = conn.cursor()
    try:
        cur.execute("SELECT * FROM edge_trades")
    except sqlite3.OperationalError:
        return {}
    rows = cur.fetchall()
    trade_map: Dict[Tuple[str, str], List[sqlite3.Row]] = {}
    for row in rows:
        slug = str(row["slug"] or "")
        event_date = str(row["event_date"] or "")
        if not slug or not event_date:
            continue
        key = (slug, event_date)
        trade_map.setdefault(key, []).append(row)
    return trade_map


def query_trade_fills(conn: sqlite3.Connection) -> Dict[Tuple[str, str, str, str], List[sqlite3.Row]]:
    cur = conn.cursor()
    try:
        cur.execute(
            """
            SELECT *
            FROM edge_trade_fills
            ORDER BY trade_time DESC, id DESC
            """
        )
    except sqlite3.OperationalError:
        return {}
    rows = cur.fetchall()
    fills_map: Dict[Tuple[str, str, str, str], List[sqlite3.Row]] = {}
    for row in rows:
        slug = str(row["slug"] or "")
        event_date = str(row["event_date"] or "")
        outcome = str(row["outcome"] or "")
        outcome_side = str(row["outcome_side"] or "")
        if not slug or not event_date or not outcome or not outcome_side:
            continue
        key = (slug, event_date, outcome, outcome_side)
        bucket = fills_map.setdefault(key, [])
        if len(bucket) >= 20:
            continue
        bucket.append(row)
    return fills_map


def query_auto_orders(
    conn: sqlite3.Connection,
    *,
    apply_cutoff: bool = True,
) -> Dict[str, sqlite3.Row]:
    cur = conn.cursor()
    try:
        cur.execute(
            """
            SELECT *
            FROM auto_orders
            ORDER BY datetime(created_at) ASC, id ASC
            """
        )
    except sqlite3.OperationalError:
        return {}
    rows = cur.fetchall()
    out: Dict[str, sqlite3.Row] = {}
    for row in rows:
        order_id = str(row["order_id"] or "")
        if not order_id:
            continue
        if apply_cutoff and is_before_stats_cutoff(str(row["created_at"] or "")):
            continue
        out[order_id] = row
    return out


def query_market_tick_latest(conn: sqlite3.Connection) -> Dict[Tuple[str, str], str]:
    cur = conn.cursor()
    try:
        cur.execute(
            """
            SELECT slug, event_date, MAX(created_at) AS market_updated_at
            FROM event_market_ticks
            GROUP BY slug, event_date
            """
        )
    except sqlite3.OperationalError:
        return {}
    rows = cur.fetchall()
    out: Dict[Tuple[str, str], str] = {}
    for row in rows:
        slug = str(row["slug"] or "").strip()
        event_date = str(row["event_date"] or "").strip()
        if "T" in event_date:
            event_date = event_date.split("T", 1)[0]
        market_updated_at = str(row["market_updated_at"] or "").strip()
        if not slug or not event_date or not market_updated_at:
            continue
        key = (slug, event_date)
        prev = out.get(key)
        if (not prev) or market_updated_at > prev:
            out[key] = market_updated_at
    return out


def query_market_tick_latest_for_keys(
    conn: sqlite3.Connection,
    keys: Iterable[Tuple[str, str]],
) -> Dict[Tuple[str, str], str]:
    pairs: List[Tuple[str, str]] = []
    seen: Set[Tuple[str, str]] = set()
    for slug, event_date in keys:
        slug_key = str(slug or "").strip()
        date_key = str(event_date or "").strip()
        if "T" in date_key:
            date_key = date_key.split("T", 1)[0]
        if not slug_key or not date_key:
            continue
        pair = (slug_key, date_key)
        if pair in seen:
            continue
        seen.add(pair)
        pairs.append(pair)
    if not pairs:
        return {}
    out: Dict[Tuple[str, str], str] = {}
    cur = conn.cursor()
    for slug_key, date_key in pairs:
        try:
            cur.execute(
                """
                SELECT created_at AS market_updated_at
                FROM event_market_ticks
                WHERE slug = ? AND event_date = ?
                ORDER BY created_at DESC
                LIMIT 1
                """,
                (slug_key, date_key),
            )
        except sqlite3.OperationalError:
            continue
        row = cur.fetchone()
        if not row:
            continue
        market_updated_at = str(row["market_updated_at"] or "").strip()
        if market_updated_at:
            out[(slug_key, date_key)] = market_updated_at
    return out


def _latest_ticks_for_event(
    conn: sqlite3.Connection,
    slug: str,
    event_date: str,
    outcomes: Optional[Iterable[str]] = None,
    *,
    created_at_min: str = "",
    created_at_max: str = "",
) -> Dict[Tuple[str, str], sqlite3.Row]:
    if not slug or not event_date:
        return {}
    date_key = str(event_date or "")
    if "T" in date_key:
        date_key = date_key.split("T", 1)[0]
    cur = conn.cursor()
    created_min = str(created_at_min or "").strip()
    created_max = str(created_at_max or "").strip()
    time_where = ""
    time_params: List[Any] = []
    if created_min:
        time_where += " AND created_at >= ?"
        time_params.append(created_min)
    if created_max:
        time_where += " AND created_at < ?"
        time_params.append(created_max)
    outcome_keys: List[str] = []
    seen_outcomes: Set[str] = set()
    if outcomes is not None:
        for raw_outcome in outcomes:
            outcome = str(raw_outcome or "").strip()
            if not outcome or outcome in seen_outcomes:
                continue
            seen_outcomes.add(outcome)
            outcome_keys.append(outcome)
    if outcome_keys:
        out: Dict[Tuple[str, str], sqlite3.Row] = {}
        for outcome in outcome_keys:
            for side in ("YES", "NO"):
                try:
                    cur.execute(
                        """
                        SELECT outcome, side, best_bid, best_ask, spread, bid_depth_topN, ask_depth_topN, created_at
                        FROM event_market_ticks
                        WHERE slug = ? AND event_date = ? AND outcome = ? AND side = ?
                        """ + time_where + """
                        ORDER BY created_at DESC, id DESC
                        LIMIT 1
                        """,
                        (slug, date_key, outcome, side, *time_params),
                    )
                except sqlite3.OperationalError:
                    continue
                row = cur.fetchone()
                if row:
                    out[(outcome, side)] = row
        return out
    try:
        cur.execute(
            """
            SELECT outcome, side, best_bid, best_ask, spread, bid_depth_topN, ask_depth_topN, created_at
            FROM (
                SELECT outcome, side, best_bid, best_ask, spread, bid_depth_topN, ask_depth_topN, created_at,
                       ROW_NUMBER() OVER (
                           PARTITION BY outcome, side
                           ORDER BY created_at DESC, id DESC
                       ) AS rn
                FROM event_market_ticks
                WHERE slug = ? AND event_date = ?
                """ + time_where + """
            )
            WHERE rn = 1
            ORDER BY outcome ASC, side ASC
            """,
            (slug, date_key, *time_params),
        )
    except sqlite3.OperationalError:
        return {}
    rows = cur.fetchall()
    out: Dict[Tuple[str, str], sqlite3.Row] = {}
    for row in rows:
        outcome = str(row["outcome"] or "")
        side = str(row["side"] or "")
        if not outcome or not side:
            continue
        key = (outcome, side.upper())
        if key in out:
            continue
        out[key] = row
    return out


def _market_snapshot_payload_from_latest_ticks(
    conn: sqlite3.Connection,
    slug: str,
    event_date: str,
    outcomes: Optional[Iterable[str]] = None,
    *,
    created_at_min: str = "",
    created_at_max: str = "",
) -> Tuple[Optional[Dict[str, Any]], str]:
    tick_rows = _latest_ticks_for_event(
        conn,
        slug,
        event_date,
        outcomes=outcomes,
        created_at_min=created_at_min,
        created_at_max=created_at_max,
    )
    if not tick_rows:
        return None, ""
    by_outcome: Dict[str, Dict[str, Any]] = {}
    latest_created = ""
    for (outcome, side), tick in tick_rows.items():
        outcome_key = str(outcome or "").strip()
        side_key = str(side or "").strip().upper()
        if not outcome_key or side_key not in {"YES", "NO"}:
            continue
        row_out = by_outcome.setdefault(outcome_key, {"outcome": outcome_key})
        try:
            created_at = str(tick["created_at"] or "").strip()
        except Exception:
            created_at = ""
        if created_at and (not latest_created or created_at > latest_created):
            latest_created = created_at
        if side_key == "YES":
            field_map = {
                "best_bid": "best_bid",
                "best_ask": "best_ask",
                "spread": "spread",
                "bid_depth_topN": "bid_depth_topN",
                "ask_depth_topN": "ask_depth_topN",
            }
        else:
            field_map = {
                "best_bid": "best_bid_no",
                "best_ask": "best_ask_no",
                "spread": "spread_no",
                "bid_depth_topN": "bid_depth_topN_no",
                "ask_depth_topN": "ask_depth_topN_no",
            }
        for src_key, dst_key in field_map.items():
            try:
                value = tick[src_key]
            except Exception:
                value = None
            if value is not None:
                row_out[dst_key] = value
    rows = list(by_outcome.values())
    if not rows:
        return None, ""
    return {"rows": rows, "market_updated_at": latest_created, "market_source": "event_market_ticks"}, latest_created


_MARKET_QUOTE_ROW_KEYS = (
    "best_bid",
    "best_ask",
    "spread",
    "bid_depth_topN",
    "ask_depth_topN",
    "best_bid_no",
    "best_ask_no",
    "spread_no",
    "bid_depth_topN_no",
    "ask_depth_topN_no",
)


def _merge_market_quote_row_in_place(
    target: Dict[str, Any],
    source_row: Mapping[str, Any],
    *,
    source: str,
    allow_none: bool,
) -> bool:
    if not isinstance(target, dict) or not isinstance(source_row, Mapping):
        return False
    source_name = str(source or "").strip()
    touched = False
    yes_touched = False
    no_touched = False
    yes_overrode_existing = False
    no_overrode_existing = False

    for key in _MARKET_QUOTE_ROW_KEYS:
        if key not in source_row:
            continue
        value = source_row.get(key)
        if value is None and not allow_none:
            continue
        previous = target.get(key)
        prev_float = to_float(previous) if previous is not None else None
        new_float = to_float(value) if value is not None else None
        if (
            prev_float is not None
            and new_float is not None
            and math.isfinite(prev_float)
            and math.isfinite(new_float)
            and abs(float(prev_float) - float(new_float)) > 1e-9
        ):
            if key.endswith("_no"):
                no_overrode_existing = True
            else:
                yes_overrode_existing = True
        target[key] = value
        touched = True
        if key.endswith("_no"):
            no_touched = True
        else:
            yes_touched = True

    bid_yes = to_float(target.get("best_bid"))
    ask_yes = to_float(target.get("best_ask"))
    if bid_yes is not None and ask_yes is not None and math.isfinite(bid_yes) and math.isfinite(ask_yes):
        target["spread"] = max(float(ask_yes) - float(bid_yes), 0.0)
    bid_no = to_float(target.get("best_bid_no"))
    ask_no = to_float(target.get("best_ask_no"))
    if bid_no is not None and ask_no is not None and math.isfinite(bid_no) and math.isfinite(ask_no):
        target["spread_no"] = max(float(ask_no) - float(bid_no), 0.0)

    if target.get("best_ask") is not None:
        target["ask_missing_reason_yes"] = ""
    elif allow_none and "best_ask" in source_row:
        target["ask_missing_reason_yes"] = target.get("ask_missing_reason_yes") or "market_snapshot_missing"
    if target.get("best_ask_no") is not None:
        target["ask_missing_reason_no"] = ""
    elif allow_none and "best_ask_no" in source_row:
        target["ask_missing_reason_no"] = target.get("ask_missing_reason_no") or "market_snapshot_missing"

    if source_name == "event_market_ticks" and touched:
        if yes_touched:
            target["market_tick_override_yes"] = True
            target["market_tick_override_source_yes"] = "event_market_ticks"
            if yes_overrode_existing:
                target["market_tick_quote_overrode_existing_yes"] = True
        if no_touched:
            target["market_tick_override_no"] = True
            target["market_tick_override_source_no"] = "event_market_ticks"
            if no_overrode_existing:
                target["market_tick_quote_overrode_existing_no"] = True
    return touched


