def query_runs(date: str, include_history: bool) -> List[Dict[str, Any]]:
    if not DB_PATH.exists():
        return []
    with open_db() as conn:
        rows = select_event_run_rows(conn, date, include_history)
        if not rows:
            return []
        trade_map = query_edge_trades(conn)
        fills_map = query_trade_fills(conn)
        auto_orders_map = query_auto_orders(conn)
        market_tick_latest_map = query_market_tick_latest_for_keys(
            conn,
            [(row["slug"], row["event_date"]) for row in rows],
        )
        return [
            build_run_item(conn, row, trade_map, fills_map, auto_orders_map, market_tick_latest_map)
            for row in rows
        ]


def select_event_run_rows(conn: sqlite3.Connection, date: str, include_history: bool) -> List[sqlite3.Row]:
    date_key = str(date or "").strip()
    if not date_key:
        date_key = latest_unsettled_run_date(conn) or latest_run_date(conn) or ""
    date_key = _normalize_date_key(date_key)
    if not date_key:
        return []
    cur = conn.cursor()
    if include_history:
        cur.execute(
            "SELECT * FROM event_runs WHERE run_date <= ? ORDER BY run_date DESC, created_at DESC",
            (date_key,),
        )
    else:
        cur.execute(
            "SELECT * FROM event_runs WHERE run_date = ? ORDER BY created_at DESC",
            (date_key,),
        )
    rows = cur.fetchall()
    if not rows:
        return []
    if not include_history:
        seen: set[Tuple[str, str]] = set()
        out: List[sqlite3.Row] = []
        for row in rows:
            slug = str(row["slug"] or "")
            event_date_key = _normalize_date_key(str(row["event_date"] or ""))
            if not slug or not event_date_key:
                continue
            if not _event_date_matches_slug(slug, event_date_key):
                continue
            key = (slug, event_date_key)
            if key in seen:
                continue
            seen.add(key)
            out.append(row)
        return out
    best_rows: Dict[Tuple[str, str], sqlite3.Row] = {}
    fallback_rows: Dict[Tuple[str, str], sqlite3.Row] = {}
    for row in rows:
        slug = str(row["slug"] or "")
        event_date_key = _normalize_date_key(str(row["event_date"] or ""))
        if not slug or not event_date_key:
            continue
        if not _event_date_matches_slug(slug, event_date_key):
            continue
        key = (slug, event_date_key)
        run_date = _normalize_date_key(str(row["run_date"] or ""))
        created_at = str(row["created_at"] or "")
        prev_fallback = fallback_rows.get(key)
        if not prev_fallback or (run_date, created_at) > (
            _normalize_date_key(str(prev_fallback["run_date"] or "")),
            str(prev_fallback["created_at"] or ""),
        ):
            fallback_rows[key] = row
        cutoff = date_key
        if date_key and event_date_key and event_date_key < date_key:
            cutoff = event_date_key
        if cutoff and run_date and run_date > cutoff:
            continue
        prev_best = best_rows.get(key)
        if not prev_best or (run_date, created_at) > (
            _normalize_date_key(str(prev_best["run_date"] or "")),
            str(prev_best["created_at"] or ""),
        ):
            best_rows[key] = row
    out: List[sqlite3.Row] = []
    for key, fallback in fallback_rows.items():
        out.append(best_rows.get(key) or fallback)
    return out


def select_event_run_rows_range(conn: sqlite3.Connection, start_date: str, end_date: str) -> List[sqlite3.Row]:
    start_key = _normalize_date_key(start_date)
    end_key = _normalize_date_key(end_date)
    if not start_key or not end_key:
        return []
    cur = conn.cursor()
    cur.execute(
        """
        SELECT * FROM event_runs
        WHERE run_date >= ? AND run_date <= ?
        ORDER BY run_date DESC, created_at DESC
        """,
        (start_key, end_key),
    )
    return cur.fetchall()


def _load_latest_snapshot(
    conn: sqlite3.Connection,
    table: str,
    slug: str,
    event_date: str,
    run_date_max: str = "",
    created_at_min: str = "",
    created_at_max: str = "",
) -> Tuple[Optional[Dict[str, Any]], Optional[Dict[str, Any]], str, Optional[int]]:
    if table not in {"model_snapshots", "market_snapshots"}:
        return None, None, "", None
    slug_key = str(slug or "").strip()
    date_key = _normalize_date_key(str(event_date or ""))
    run_date_max_key = _normalize_date_key(str(run_date_max or ""))
    if not slug_key or not date_key:
        return None, None, "", None
    cur = conn.cursor()
    where_parts = ["slug = ?", "event_date = ?"]
    params: List[Any] = [slug_key, date_key]
    if run_date_max_key:
        where_parts.append("run_date <= ?")
        params.append(run_date_max_key)
    created_min = str(created_at_min or "").strip()
    created_max = str(created_at_max or "").strip()
    if created_min:
        where_parts.append("created_at >= ?")
        params.append(created_min)
    if created_max:
        where_parts.append("created_at < ?")
        params.append(created_max)
    try:
        cur.execute(
            f"""
            SELECT id, payload_json, meta_json, created_at
            FROM {table}
            WHERE {" AND ".join(where_parts)}
            ORDER BY created_at DESC, id DESC
            LIMIT 1
            """,
            tuple(params),
        )
    except sqlite3.Error:
        return None, None, "", None
    row = cur.fetchone()
    if not row:
        return None, None, "", None
    payload = safe_json_loads(row["payload_json"] if "payload_json" in row.keys() else None)
    meta: Dict[str, Any] = {}
    meta_raw = row["meta_json"] if "meta_json" in row.keys() else None
    if meta_raw:
        try:
            loaded = json.loads(meta_raw)
        except json.JSONDecodeError:
            loaded = {}
        if isinstance(loaded, dict):
            meta = loaded
    created_at = str(row["created_at"] or "")
    snap_id = _to_int(row["id"])
    return payload, meta, created_at, snap_id


def _snapshot_run_date_ceiling_for_event(
    run_date: str,
    event_date: str,
    *,
    today_key: str = "",
) -> str:
    run_key = _normalize_date_key(str(run_date or ""))
    event_key = _normalize_date_key(str(event_date or ""))
    if not event_key:
        return run_key
    if not run_key:
        return event_key
    local_today = _normalize_date_key(today_key)
    if not local_today:
        local_today = _chengdu_today_date_key()
    if event_key == local_today and run_key < event_key:
        return event_key
    return run_key


def _snapshot_time_delta_ok_ui(
    a: Optional[str],
    b: Optional[str],
    window_sec: float,
) -> bool:
    if not a or not b:
        return False
    ta = parse_iso_ts(str(a))
    tb = parse_iso_ts(str(b))
    if ta is None or tb is None:
        return False
    return abs((ta - tb).total_seconds()) <= float(window_sec)


def _snapshot_tick_overlay_allowed_ui(
    model_created_at: Optional[str],
    tick_created_at: Optional[str],
    window_sec: float,
) -> bool:
    if _snapshot_time_delta_ok_ui(model_created_at, tick_created_at, window_sec):
        return True
    if not model_created_at or not tick_created_at:
        return False
    model_dt = parse_iso_ts(str(model_created_at))
    tick_dt = parse_iso_ts(str(tick_created_at))
    if model_dt is None or tick_dt is None:
        return False
    if model_dt.tzinfo is None:
        model_dt = model_dt.replace(tzinfo=timezone.utc)
    if tick_dt.tzinfo is None:
        tick_dt = tick_dt.replace(tzinfo=timezone.utc)
    if tick_dt < model_dt:
        return False
    try:
        max_model_age_sec = float(
            os.environ.get("PM_SCORE_COMPOSE_TICK_MODEL_MAX_AGE_SEC", "129600")
            or 129600.0
        )
    except (TypeError, ValueError):
        max_model_age_sec = 129600.0
    if not math.isfinite(max_model_age_sec) or max_model_age_sec <= 0:
        max_model_age_sec = 129600.0
    return (tick_dt - model_dt).total_seconds() <= float(max_model_age_sec)


def _iso_add_seconds(ts: str, seconds: float) -> str:
    dt = parse_iso_ts(str(ts or ""))
    if dt is None:
        return ""
    if dt.tzinfo is None:
        dt = dt.replace(tzinfo=timezone.utc)
    try:
        return (dt + timedelta(seconds=float(seconds))).isoformat(timespec="seconds")
    except Exception:
        return ""


def _min_iso_ts(a: str, b: str) -> str:
    if not a:
        return str(b or "")
    if not b:
        return str(a or "")
    da = parse_iso_ts(str(a))
    db = parse_iso_ts(str(b))
    if da is not None and db is not None:
        return str(a) if da <= db else str(b)
    return str(a) if str(a) <= str(b) else str(b)


def _sqlite_table_exists(conn: sqlite3.Connection, table: str) -> bool:
    name = str(table or "").strip()
    if not name:
        return False
    try:
        cur = conn.cursor()
        cur.execute(
            "SELECT 1 FROM sqlite_master WHERE type = 'table' AND name = ? LIMIT 1",
            (name,),
        )
        return cur.fetchone() is not None
    except sqlite3.Error:
        return False


def _sqlite_table_columns(conn: sqlite3.Connection, table: str) -> Set[str]:
    name = str(table or "").strip()
    if not name:
        return set()
    try:
        cur = conn.cursor()
        cur.execute(f"PRAGMA table_info({name})")
        return {str(row["name"] if isinstance(row, sqlite3.Row) else row[1] or "") for row in cur.fetchall()}
    except sqlite3.Error:
        return set()


def _discovery_snapshot_key_rows_for_event_date_range(
    conn: sqlite3.Connection,
    start_date: str,
    end_date: str,
    *,
    materialize_run_date: str,
    limit: int = 200,
) -> List[Tuple[str, str, str]]:
    start_key = _normalize_date_key(start_date)
    end_key = _normalize_date_key(end_date)
    run_key = _normalize_date_key(materialize_run_date) or end_key
    if not start_key or not end_key or not run_key:
        return []
    if not _sqlite_table_exists(conn, "weather_market_discovery") or not _sqlite_table_exists(conn, "market_tokens"):
        return []
    try:
        cur = conn.cursor()
        cur.execute(
            """
            WITH token_latest AS (
              SELECT
                slug,
                event_date,
                COUNT(*) AS token_count,
                MAX(updated_at) AS token_updated_at,
                SUM(CASE
                      WHEN COALESCE(market_closed, 0) = 0
                       AND COALESCE(market_archived, 0) = 0
                       AND COALESCE(market_active, 1) != 0
                      THEN 1 ELSE 0
                    END) AS active_token_count
              FROM market_tokens
              WHERE event_date >= ? AND event_date <= ?
              GROUP BY slug, event_date
            )
            SELECT
              wd.slug,
              wd.event_date,
              wd.title
            FROM weather_market_discovery wd
            LEFT JOIN token_latest tl
              ON tl.slug = wd.slug AND tl.event_date = wd.event_date
            WHERE wd.event_date >= ? AND wd.event_date <= ?
              AND (
                LOWER(COALESCE(wd.slug, '')) LIKE '%-in-chengdu-%'
                OR LOWER(COALESCE(wd.title, '')) LIKE '%chengdu%'
              )
              AND COALESCE(NULLIF(wd.token_count, 0), tl.token_count, 0) >= 2
              AND COALESCE(tl.active_token_count, wd.token_count, 0) > 0
              AND COALESCE(wd.status, '') IN ('tokenized', 'known_recent')
            ORDER BY
              wd.event_date ASC,
              COALESCE(wd.first_tokenized_at, wd.first_seen_at, wd.updated_at, tl.token_updated_at) DESC,
              wd.updated_at DESC
            LIMIT ?
            """,
            (start_key, end_key, start_key, end_key, max(1, min(int(limit or 200), 1000))),
        )
        rows = cur.fetchall()
    except sqlite3.Error:
        return []
    out: List[Tuple[str, str, str]] = []
    seen: Set[Tuple[str, str, str]] = set()
    for row in rows or []:
        if isinstance(row, sqlite3.Row):
            raw_slug = row["slug"]
            raw_event_date = row["event_date"]
            raw_title = row["title"]
        else:
            raw_slug = row[0] if len(row) > 0 else ""
            raw_event_date = row[1] if len(row) > 1 else ""
            raw_title = row[2] if len(row) > 2 else ""
        slug = str(raw_slug or "").strip()
        event_date = _normalize_date_key(str(raw_event_date or ""))
        title = str(raw_title or "")
        if not slug or not event_date:
            continue
        if not _is_chengdu_market_identifier(slug, title):
            continue
        if not _event_date_matches_slug(slug, event_date):
            continue
        key = (slug, event_date, run_key)
        if key in seen:
            continue
        seen.add(key)
        out.append(key)
    return out


def _chengdu_slugs_for_event_date(conn: sqlite3.Connection, event_date: str) -> List[str]:
    event_key = _normalize_date_key(str(event_date or ""))
    if not event_key:
        return []
    out: List[str] = []
    seen: Set[str] = set()

    def _add(slug_raw: Any, title_raw: Any = "") -> None:
        slug = str(slug_raw or "").strip()
        title = str(title_raw or "")
        if not slug or slug in seen:
            return
        if not _is_chengdu_market_identifier(slug, title):
            return
        if not _event_date_matches_slug(slug, event_key):
            return
        seen.add(slug)
        out.append(slug)

    try:
        if _sqlite_table_exists(conn, "weather_market_discovery"):
            for row in conn.execute(
                """
                SELECT slug, title
                FROM weather_market_discovery
                WHERE event_date = ?
                  AND (
                    LOWER(COALESCE(slug, '')) LIKE '%-in-chengdu-%'
                    OR LOWER(COALESCE(title, '')) LIKE '%chengdu%'
                  )
                ORDER BY
                  COALESCE(first_tokenized_at, first_seen_at, updated_at) DESC,
                  updated_at DESC
                LIMIT 20
                """,
                (event_key,),
            ).fetchall():
                _add(row["slug"] if isinstance(row, sqlite3.Row) else row[0], row["title"] if isinstance(row, sqlite3.Row) else row[1])
    except sqlite3.Error:
        pass
    try:
        if _sqlite_table_exists(conn, "market_tokens"):
            for row in conn.execute(
                """
                SELECT slug, MAX(updated_at) AS updated_at
                FROM market_tokens
                WHERE event_date = ?
                  AND LOWER(COALESCE(slug, '')) LIKE '%-in-chengdu-%'
                GROUP BY slug
                ORDER BY updated_at DESC
                LIMIT 20
                """,
                (event_key,),
            ).fetchall():
                _add(row["slug"] if isinstance(row, sqlite3.Row) else row[0])
    except sqlite3.Error:
        pass
    for table in ("market_snapshots", "model_snapshots", "event_runs"):
        try:
            if not _sqlite_table_exists(conn, table):
                continue
            title_expr = "title" if "title" in _sqlite_table_columns(conn, table) else "'' AS title"
            for row in conn.execute(
                f"""
                SELECT slug, {title_expr}, MAX(created_at) AS created_at
                FROM {table}
                WHERE event_date = ?
                  AND LOWER(COALESCE(slug, '')) LIKE '%-in-chengdu-%'
                GROUP BY slug
                ORDER BY created_at DESC
                LIMIT 20
                """,
                (event_key,),
            ).fetchall():
                _add(row["slug"] if isinstance(row, sqlite3.Row) else row[0], row["title"] if isinstance(row, sqlite3.Row) else row[1])
        except sqlite3.Error:
            continue
    return out


def _station_observation_event_dates_for_range(
    conn: sqlite3.Connection,
    start_date: str,
    end_date: str,
    *,
    since_key: str = "",
) -> List[str]:
    start_key = _normalize_date_key(start_date)
    end_key = _normalize_date_key(end_date)
    if not start_key or not end_key or not _sqlite_table_exists(conn, "station_observations"):
        return []
    columns = _sqlite_table_columns(conn, "station_observations")
    if not {"event_date", "value", "created_at"}.issubset(columns):
        return []
    where = ["event_date >= ?", "event_date <= ?", "value IS NOT NULL"]
    params: List[Any] = [start_key, end_key]
    if "station_id" in columns or "resolution_source" in columns:
        parts: List[str] = []
        if "station_id" in columns:
            parts.append("UPPER(COALESCE(station_id, '')) = 'ZUUU'")
        if "resolution_source" in columns:
            parts.extend(
                [
                    "LOWER(COALESCE(resolution_source, '')) LIKE '%zuuu%'",
                    "LOWER(COALESCE(resolution_source, '')) LIKE '%chengdu%'",
                ]
            )
        where.append("(" + " OR ".join(parts) + ")")
    if "market_var" in columns:
        where.append("(COALESCE(market_var, '') = '' OR market_var = 'temperature_2m_max')")
    if "source_kind" in columns:
        where.append("LOWER(COALESCE(source_kind, '')) NOT LIKE '%pws%'")
    if since_key and "created_at" in columns:
        where.append("created_at >= ?")
        params.append(str(since_key))
    try:
        rows = conn.execute(
            f"""
            SELECT event_date, MAX(created_at) AS created_at
            FROM station_observations
            WHERE {" AND ".join(where)}
            GROUP BY event_date
            ORDER BY event_date ASC
            """,
            tuple(params),
        ).fetchall()
    except sqlite3.Error:
        return []
    out: List[str] = []
    for row in rows or []:
        value = row["event_date"] if isinstance(row, sqlite3.Row) else row[0]
        key = _normalize_date_key(str(value or ""))
        if key:
            out.append(key)
    return out


def _station_observation_snapshot_key_rows_for_range(
    conn: sqlite3.Connection,
    start_date: str,
    end_date: str,
    *,
    since_key: str = "",
) -> List[Tuple[str, str, str]]:
    rows: List[Tuple[str, str, str]] = []
    for event_key in _station_observation_event_dates_for_range(
        conn,
        start_date,
        end_date,
        since_key=since_key,
    ):
        for slug in _chengdu_slugs_for_event_date(conn, event_key):
            rows.append((slug, event_key, event_key))
    return rows


def _snapshot_key_rows_for_run_date(conn: sqlite3.Connection, run_date: str) -> List[Tuple[str, str, str]]:
    run_key = _normalize_date_key(run_date)
    if not run_key:
        return []
    cur = conn.cursor()
    since_raw = str(os.environ.get("PM_FACTS_MATERIALIZE_SNAPSHOT_SINCE") or "").strip()
    since_key = since_raw if parse_iso_ts(since_raw) is not None else ""
    try:
        source_sql: List[str] = []
        params: List[Any] = []
        source_tables = ["model_snapshots", "market_snapshots", "event_runs"]
        tick_columns = _sqlite_table_columns(conn, "event_market_ticks")
        if {"slug", "event_date", "run_date", "created_at"}.issubset(tick_columns):
            source_tables.append("event_market_ticks")
        for table in source_tables:
            if table == "event_runs" and not _sqlite_table_exists(conn, table):
                continue
            if since_key:
                source_sql.append(
                    f"""
                    SELECT slug, event_date, run_date
                    FROM {table}
                    WHERE (run_date = ? OR event_date = ?) AND created_at >= ?
                    """
                )
                params.extend([run_key, run_key, since_key])
            else:
                source_sql.append(
                    f"""
                    SELECT slug, event_date, run_date
                    FROM {table}
                    WHERE run_date = ? OR event_date = ?
                    """
                )
                params.extend([run_key, run_key])
        if not source_sql:
            return []
        if since_key:
            cur.execute(
                f"""
                SELECT slug, event_date, run_date
                FROM (
                    {" UNION ".join(source_sql)}
                )
                GROUP BY slug, event_date, run_date
                """,
                tuple(params),
            )
        else:
            cur.execute(
                f"""
                SELECT slug, event_date, run_date
                FROM (
                    {" UNION ".join(source_sql)}
                )
                GROUP BY slug, event_date, run_date
                """,
                tuple(params),
            )
        rows = cur.fetchall()
    except sqlite3.Error:
        return []
    out: List[Tuple[str, str, str]] = []
    for r in rows:
        slug = str(r[0] or "")
        event_date = _normalize_date_key(str(r[1] or ""))
        run_date_val = _normalize_date_key(str(r[2] or ""))
        if slug and event_date and run_date_val:
            out.append((slug, event_date, run_date_val))
    seen = set(out)
    for row in _discovery_snapshot_key_rows_for_event_date_range(
        conn,
        run_key,
        run_key,
        materialize_run_date=run_key,
    ):
        if row not in seen:
            seen.add(row)
            out.append(row)
    for row in _station_observation_snapshot_key_rows_for_range(
        conn,
        run_key,
        run_key,
        since_key=since_key,
    ):
        if row not in seen:
            seen.add(row)
            out.append(row)
    return out


def _snapshot_key_rows_for_run_date_range(conn: sqlite3.Connection, start_date: str, end_date: str) -> List[Tuple[str, str, str]]:
    start_key = _normalize_date_key(start_date)
    end_key = _normalize_date_key(end_date)
    if not start_key or not end_key:
        return []
    cur = conn.cursor()
    since_raw = str(os.environ.get("PM_FACTS_MATERIALIZE_SNAPSHOT_SINCE") or "").strip()
    since_key = since_raw if parse_iso_ts(since_raw) is not None else ""
    try:
        source_sql: List[str] = []
        params: List[Any] = []
        source_tables = ["model_snapshots", "market_snapshots", "event_runs"]
        tick_columns = _sqlite_table_columns(conn, "event_market_ticks")
        if {"slug", "event_date", "run_date", "created_at"}.issubset(tick_columns):
            source_tables.append("event_market_ticks")
        for table in source_tables:
            if table == "event_runs" and not _sqlite_table_exists(conn, table):
                continue
            if since_key:
                source_sql.append(
                    f"""
                    SELECT slug, event_date, run_date
                    FROM {table}
                    WHERE run_date >= ? AND run_date <= ? AND created_at >= ?
                    """
                )
                params.extend([start_key, end_key, since_key])
            else:
                source_sql.append(
                    f"""
                    SELECT slug, event_date, run_date
                    FROM {table}
                    WHERE run_date >= ? AND run_date <= ?
                    """
                )
                params.extend([start_key, end_key])
        if not source_sql:
            return []
        if since_key:
            cur.execute(
                f"""
                SELECT slug, event_date, MAX(run_date) AS run_date
                FROM (
                    {" UNION ".join(source_sql)}
                )
                GROUP BY slug, event_date
                """,
                tuple(params),
            )
        else:
            cur.execute(
                f"""
                SELECT slug, event_date, MAX(run_date) AS run_date
                FROM (
                    {" UNION ".join(source_sql)}
                )
                GROUP BY slug, event_date
                """,
                tuple(params),
            )
        rows = cur.fetchall()
    except sqlite3.Error:
        return []
    out: List[Tuple[str, str, str]] = []
    for r in rows:
        slug = str(r[0] or "")
        event_date = _normalize_date_key(str(r[1] or ""))
        run_date_val = _normalize_date_key(str(r[2] or ""))
        if slug and event_date and run_date_val:
            out.append((slug, event_date, run_date_val))
    seen = set(out)
    for row in _discovery_snapshot_key_rows_for_event_date_range(
        conn,
        start_key,
        end_key,
        materialize_run_date=end_key,
    ):
        slug, event_date, _run_date_val = row
        dedupe_key = (slug, event_date)
        existing_for_event = [candidate for candidate in seen if candidate[0] == slug and candidate[1] == event_date]
        if existing_for_event:
            continue
        if row not in seen:
            seen.add(row)
            out.append(row)
    for row in _station_observation_snapshot_key_rows_for_range(
        conn,
        start_key,
        end_key,
        since_key=since_key,
    ):
        if row not in seen:
            seen.add(row)
            out.append(row)
    return out


def _edge_score_penalty(spread: Optional[float], ask: Optional[float]) -> float:
    penalty = 0.0
    if spread is not None and ask is not None:
        spread_pct = max(float(spread) * 100.0, 0.0)
        penalty += max(0.0, (spread_pct - 8.0) / 10.0)
        penalty += max(0.0, (float(ask) - 0.6) / 0.2)
    return penalty


def _direction_base(delta: Optional[float], scale: float = 0.02) -> float:
    """Directional base term used by time_factor.

    This mirrors scan_weather_market.py's sigmoid-based base:
      base = sigmoid((q_entry - ask) / 0.02)
    """
    if delta is None or scale <= 0:
        return 0.0
    try:
        x = float(delta) / float(scale)
    except (TypeError, ValueError):
        return 0.0
    if not math.isfinite(x):
        return 0.0
    if x >= 20:
        return 1.0
    if x <= -20:
        return 0.0
    return 1.0 / (1.0 + math.exp(-x))




def _temperature_trajectory_features_for_composer(
    features: Mapping[str, Any],
    *,
    event_tz: str = "",
) -> Dict[str, Any]:
    out = dict(features or {}) if isinstance(features, Mapping) else {}
    hour = None
    for key in ("observation_hour_local", "hour_local", "local_hour"):
        hour = to_float(out.get(key))
        if hour is not None:
            break
    if hour is None:
        zone_name = str(event_tz or out.get("tz") or out.get("timezone") or "Asia/Shanghai").strip()
        try:
            zone = ZoneInfo(zone_name)
        except Exception:
            zone = timezone.utc
        for key in (
            "temperature_momentum_latest_observation_at",
            "wu_twc_observed_intraday_current_at",
            "zuuu_metar_raw_awc_latest_at",
            "zuuu_metar_raw_awc_today_max_at",
            "zuuu_metar_raw_awc_fetched_at",
            "awc_metar_observed_at",
            "observed_temp_at",
        ):
            dt = parse_iso_ts(str(out.get(key) or ""))
            if dt is None:
                continue
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=timezone.utc)
            local_dt = dt.astimezone(zone)
            out["observation_hour_local"] = (
                local_dt.hour + local_dt.minute / 60.0 + local_dt.second / 3600.0
            )
            out.setdefault("observation_month", local_dt.month)
            out["observation_hour_local_source"] = key
            out["observation_hour_local_timezone"] = zone_name
            break
    peak_meta = out.get("peak_estimator")
    if isinstance(peak_meta, Mapping) and not peak_meta.get("enabled"):
        source = str(peak_meta.get("source") or "")
        if source in {"insufficient_peak_estimator_features", "peak_estimator_disabled"}:
            out.pop("peak_estimator", None)
            out["peak_estimator_rebuilt_from_composer_features"] = True
            out["peak_estimator_rebuilt_reason"] = source
    if not isinstance(out.get("peak_estimator"), Mapping):
        rebuilt_peak: Dict[str, Any] = {}
        for flat_key, meta_key in (
            ("peak_estimator_mu_c", "mu_c"),
            ("peak_estimator_sigma_c", "sigma_c"),
            ("peak_estimator_extrapolation_c", "extrapolation_c"),
            ("peak_estimator_kalman_gain", "kalman_gain"),
            ("peak_estimator_combined_discount", "combined_discount"),
            ("hours_to_peak_window", "hours_to_peak_window"),
            ("peak_window_start_hour_local", "peak_window_start_hour_local"),
            ("peak_window_end_hour_local", "peak_window_end_hour_local"),
            ("lock_threshold_hour_local", "lock_threshold_hour_local"),
            ("temperature_momentum_context_effective_c_per_hour", "temperature_momentum_context_effective_c_per_hour"),
        ):
            val = to_float(out.get(flat_key))
            if val is not None and math.isfinite(float(val)):
                rebuilt_peak[meta_key] = float(val)
        for flat_key, meta_key in (
            ("temperature_momentum_realization_state", "temperature_momentum_realization_state"),
            ("temperature_momentum_context_warming_watch", "temperature_momentum_context_warming_watch"),
        ):
            value = out.get(flat_key)
            if value not in (None, ""):
                rebuilt_peak[meta_key] = value
        if rebuilt_peak.get("mu_c") is not None and rebuilt_peak.get("sigma_c") is not None:
            rebuilt_peak["enabled"] = True
            rebuilt_peak["source"] = str(out.get("peak_estimator_source") or "composer_flat_peak_estimator")
            out["peak_estimator"] = rebuilt_peak
    return out


def _compose_fact_from_snapshots(
    conn: sqlite3.Connection,
    run_date: str,
    slug: str,
    event_date: str,
    trade_map: Dict[Tuple[str, str], List[sqlite3.Row]],
    fills_map: Dict[Tuple[str, str, str, str], List[sqlite3.Row]],
    auto_orders_map: Dict[str, sqlite3.Row],
    market_tick_latest_map: Optional[Dict[Tuple[str, str], str]] = None,
    platt: Optional[Dict[str, Any]] = None,
    snapshot_created_at_min: str = "",
    snapshot_created_at_max: str = "",
    allow_event_run_model_candidate: bool = True,
    allow_latest_fact_overlay: bool = True,
    allow_settlement_status_overlay: bool = True,
) -> Optional[Tuple[Dict[str, Any], Dict[str, Any], str]]:
    snapshot_run_date_ceiling = _snapshot_run_date_ceiling_for_event(run_date, event_date)
    payload_model, meta_model, created_model, model_id = _load_latest_snapshot(
        conn,
        "model_snapshots",
        slug,
        event_date,
        run_date_max=snapshot_run_date_ceiling,
        created_at_min=snapshot_created_at_min,
        created_at_max=snapshot_created_at_max,
    )
    if allow_event_run_model_candidate:
        payload_event_run, meta_event_run, created_event_run, event_run_id = _event_run_payload_model_candidate(
            conn,
            slug,
            event_date,
            run_date,
        )
    else:
        payload_event_run, meta_event_run, created_event_run, event_run_id = None, {}, "", None
    model_source = "model_snapshots"
    loaded_model_snapshot_id = model_id
    loaded_model_snapshot_at = created_model
    referenced_model_snapshot_id = model_id
    referenced_model_snapshot_at = created_model
    if isinstance(meta_event_run, dict):
        referenced_model_snapshot_id_from_event = _to_int(meta_event_run.get("model_snapshot_id"))
        referenced_model_snapshot_at_from_event = str(meta_event_run.get("model_snapshot_at") or "")
    else:
        referenced_model_snapshot_id_from_event = None
        referenced_model_snapshot_at_from_event = ""
    event_run_dt = parse_iso_ts(str(created_event_run or ""))
    model_dt = parse_iso_ts(str(created_model or ""))
    event_run_is_newer = False
    event_run_model_not_older = (
        referenced_model_snapshot_id_from_event is None
        or loaded_model_snapshot_id is None
        or int(referenced_model_snapshot_id_from_event) >= int(loaded_model_snapshot_id)
    )
    event_run_model_strictly_newer = (
        referenced_model_snapshot_id_from_event is not None
        and loaded_model_snapshot_id is not None
        and int(referenced_model_snapshot_id_from_event) > int(loaded_model_snapshot_id)
    )
    if payload_event_run is not None:
        if payload_model is None:
            event_run_is_newer = True
        elif (
            referenced_model_snapshot_id_from_event is not None
            and loaded_model_snapshot_id is not None
            and not event_run_model_strictly_newer
        ):
            event_run_is_newer = False
        elif event_run_dt is not None and model_dt is not None:
            event_run_is_newer = event_run_dt >= model_dt
        elif created_event_run and created_model:
            event_run_is_newer = str(created_event_run) >= str(created_model)
        elif created_event_run:
            event_run_is_newer = True
    if not event_run_model_not_older:
        event_run_is_newer = False
    if event_run_is_newer and payload_event_run is not None:
        payload_model = payload_event_run
        merged_meta = dict(meta_model or {})
        for key, value in (meta_event_run or {}).items():
            if value is not None and value != "":
                merged_meta[key] = value
        meta_model = merged_meta
        created_model = created_event_run
        model_source = "event_runs"
        if referenced_model_snapshot_id_from_event is not None:
            referenced_model_snapshot_id = referenced_model_snapshot_id_from_event
            model_id = referenced_model_snapshot_id_from_event
        if referenced_model_snapshot_at_from_event:
            referenced_model_snapshot_at = referenced_model_snapshot_at_from_event
    payload_market, meta_market, created_market, market_id = _load_latest_snapshot(
        conn,
        "market_snapshots",
        slug,
        event_date,
        run_date_max=snapshot_run_date_ceiling,
        created_at_min=snapshot_created_at_min,
        created_at_max=snapshot_created_at_max,
    )
    if payload_model is None:
        return None
    try:
        snapshot_window_sec = float(os.environ.get("PM_SCORE_COMPOSE_WINDOW_SEC", "10800") or 10800.0)
    except (TypeError, ValueError):
        snapshot_window_sec = 10800.0
    if not math.isfinite(snapshot_window_sec) or snapshot_window_sec <= 0:
        snapshot_window_sec = 10800.0
    if payload_market is not None and not _snapshot_time_delta_ok_ui(created_model, created_market, snapshot_window_sec):
        synced_market_max = _min_iso_ts(
            snapshot_created_at_max,
            _iso_add_seconds(created_model, snapshot_window_sec),
        )
        if synced_market_max:
            (
                payload_market_synced,
                meta_market_synced,
                created_market_synced,
                market_id_synced,
            ) = _load_latest_snapshot(
                conn,
                "market_snapshots",
                slug,
                event_date,
                run_date_max=snapshot_run_date_ceiling,
                created_at_min=snapshot_created_at_min,
                created_at_max=synced_market_max,
            )
            if payload_market_synced is not None and _snapshot_time_delta_ok_ui(
                created_model,
                created_market_synced,
                snapshot_window_sec,
            ):
                payload_market = payload_market_synced
                meta_market = meta_market_synced
                created_market = created_market_synced
                market_id = market_id_synced
    weather_feature_overlay_applied = False
    weather_feature_overlay_as_of = ""
    payload_weather_features = (
        dict(payload_model.get("weather_likelihood_features") or {})
        if isinstance(payload_model.get("weather_likelihood_features"), Mapping)
        else {}
    )
    latest_fact_as_of, latest_fact_payload = _latest_awc_hard_observation_payload_for_merge_fill(conn, slug, event_date)
    latest_fact_features = _awc_features_from_fact_payload_for_merge_fill(latest_fact_payload)
    if not latest_fact_features:
        latest_fact_as_of, latest_fact_payload = _latest_fact_payload_for_merge_fill(conn, slug, event_date)
        latest_fact_features = (
            dict(latest_fact_payload.get("weather_likelihood_features") or {})
            if isinstance(latest_fact_payload.get("weather_likelihood_features"), Mapping)
            else {}
        )
        if not latest_fact_features and isinstance(latest_fact_payload.get("weather_likelihood_features_compact"), Mapping):
            latest_fact_features = dict(latest_fact_payload.get("weather_likelihood_features_compact") or {})
    if allow_latest_fact_overlay and latest_fact_features and _weather_feature_overlay_is_stronger(
        latest_fact_features,
        payload_weather_features,
    ):
        refreshed_at = str(
            latest_fact_features.get("weather_likelihood_refreshed_at")
            or latest_fact_payload.get("weather_likelihood_refreshed_at")
            or latest_fact_as_of
            or ""
        )
        overlay_fields = _distribution_weather_feature_fields(
            latest_fact_features,
            refreshed_at=refreshed_at,
        )
        if overlay_fields:
            payload_model = dict(payload_model)
            payload_weather_features = dict(payload_weather_features)
            payload_weather_features.update(overlay_fields)
            payload_model["weather_likelihood_features"] = payload_weather_features
            payload_model["weather_likelihood_features_compact"] = _compact_weather_likelihood_features_for_ui(
                payload_weather_features
            )
            payload_model["weather_likelihood_refreshed_at"] = refreshed_at
            payload_model["weather_feature_overlay_applied"] = True
            payload_model["weather_feature_overlay_source"] = "event_fact_latest"
            payload_model["weather_feature_overlay_as_of"] = latest_fact_as_of
            weather_feature_overlay_applied = True
            weather_feature_overlay_as_of = latest_fact_as_of
    station_observation_overlay_applied = False
    station_observation_overlay_as_of = ""
    station_features = _station_observation_weather_features(
        conn,
        event_date,
        created_at_min=snapshot_created_at_min,
        created_at_max=snapshot_created_at_max,
    )
    if station_features:
        station_source = str(station_features.get("observed_today_max_source") or "")
        station_is_awc_like = "metar" in station_source.lower() or "awc" in station_source.lower()
        base_has_awc = _features_have_awc_hard_observation(payload_weather_features)
        if (station_is_awc_like or not base_has_awc) and _weather_feature_overlay_is_stronger(
            station_features,
            payload_weather_features,
        ):
            refreshed_at = str(
                station_features.get("weather_likelihood_refreshed_at")
                or station_features.get("station_observation_created_at")
                or station_features.get("observed_today_max_at")
                or ""
            )
            payload_model = dict(payload_model)
            payload_weather_features = dict(payload_weather_features)
            payload_weather_features.update(station_features)
            payload_model["weather_likelihood_features"] = payload_weather_features
            payload_model["weather_likelihood_features_compact"] = _compact_weather_likelihood_features_for_ui(
                payload_weather_features
            )
            if refreshed_at:
                payload_model["weather_likelihood_refreshed_at"] = refreshed_at
            payload_model["weather_feature_overlay_applied"] = True
            payload_model["weather_feature_overlay_source"] = "station_observations"
            payload_model["weather_feature_overlay_as_of"] = refreshed_at
            payload_model["station_observation_overlay_applied"] = True
            weather_feature_overlay_applied = True
            weather_feature_overlay_as_of = refreshed_at or weather_feature_overlay_as_of
            station_observation_overlay_applied = True
            station_observation_overlay_as_of = refreshed_at
    model_outcomes = [
        str(row.get("outcome") or row.get("label") or "").strip()
        for row in (payload_model.get("rows") or [])
        if isinstance(row, Mapping) and str(row.get("outcome") or row.get("label") or "").strip()
    ]
    tick_payload_overlay, tick_created_overlay = _market_snapshot_payload_from_latest_ticks(
        conn,
        slug,
        event_date,
        outcomes=model_outcomes,
        created_at_min=snapshot_created_at_min,
        created_at_max=snapshot_created_at_max,
    )
    market_from_ticks = False
    if payload_market is None or not _snapshot_time_delta_ok_ui(created_model, created_market, snapshot_window_sec):
        if tick_payload_overlay is not None and _snapshot_tick_overlay_allowed_ui(
            created_model,
            tick_created_overlay,
            snapshot_window_sec,
        ):
            payload_market = tick_payload_overlay
            meta_market = dict(meta_market or {})
            meta_market.setdefault("market_snapshot_source", "event_market_ticks")
            created_market = tick_created_overlay
            market_id = None
            market_from_ticks = True
    if payload_market is None:
        return None
    if not market_from_ticks and not _snapshot_time_delta_ok_ui(created_model, created_market, snapshot_window_sec):
        return None
    time_structure_min = 0.1
    try:
        time_structure_min = float(os.environ.get("PM_TIME_STRUCTURE_MIN", "0.1"))
    except (TypeError, ValueError):
        time_structure_min = 0.1
    if not math.isfinite(time_structure_min) or time_structure_min <= 0:
        time_structure_min = 0.1
    market_map: Dict[str, Dict[str, Any]] = {}
    for row in payload_market.get("rows") or []:
        if not isinstance(row, dict):
            continue
        outcome = str(row.get("outcome") or "")
        if not outcome:
            continue
        market_map[outcome] = row
    tick_market_map: Dict[str, Dict[str, Any]] = {}
    for row in (tick_payload_overlay or {}).get("rows") or []:
        if not isinstance(row, dict):
            continue
        outcome = str(row.get("outcome") or "")
        if not outcome:
            continue
        tick_market_map[outcome] = row
    weather_row_fields = _distribution_weather_feature_fields(
        payload_weather_features,
        refreshed_at=str(
            payload_model.get("weather_likelihood_refreshed_at")
            or payload_weather_features.get("weather_likelihood_refreshed_at")
            or ""
        ),
    )
    market_tick_overlay_applied = False
    merged_rows: List[Dict[str, Any]] = []
    for row in payload_model.get("rows") or []:
        if not isinstance(row, dict):
            continue
        outcome = str(row.get("outcome") or "")
        if not outcome:
            continue
        merged = dict(row)
        if weather_row_fields:
            _apply_weather_feature_fields_to_rows([merged], weather_row_fields)
        mrow = market_map.get(outcome)
        if isinstance(mrow, dict):
            _merge_market_quote_row_in_place(
                merged,
                mrow,
                source="market_snapshots",
                allow_none=True,
            )
        trow = tick_market_map.get(outcome)
        if isinstance(trow, dict):
            market_tick_overlay_applied = bool(
                _merge_market_quote_row_in_place(
                    merged,
                    trow,
                    source="event_market_ticks",
                    allow_none=False,
                )
            ) or market_tick_overlay_applied
        if event_date and merged.get("event_date") is None:
            merged["event_date"] = _normalize_date_key(event_date)
        if run_date and merged.get("run_date") is None:
            merged["run_date"] = _normalize_date_key(run_date)
        _apply_market_quote_fallback_for_side_in_place(merged, "YES")
        _apply_market_quote_fallback_for_side_in_place(merged, "NO")
        merged_rows.append(merged)
    if not merged_rows:
        return None
    merged_payload = dict(payload_model)
    merged_payload["rows"] = merged_rows
    market_updated_candidates = [created_market, tick_created_overlay, merged_payload.get("market_updated_at")]
    market_updated_at = ""
    for ts in market_updated_candidates:
        ts_text = str(ts or "")
        if ts_text and (not market_updated_at or ts_text > market_updated_at):
            market_updated_at = ts_text
    merged_payload["market_updated_at"] = market_updated_at
    if market_tick_overlay_applied:
        merged_payload["market_source"] = "event_market_ticks"
        merged_payload["market_tick_overlay_applied"] = True
        merged_payload["market_tick_overlay_at"] = tick_created_overlay
    if weather_feature_overlay_applied:
        merged_payload["weather_feature_overlay_applied"] = True
        merged_payload["weather_feature_overlay_source"] = "event_fact_latest"
        merged_payload["weather_feature_overlay_as_of"] = weather_feature_overlay_as_of
    if station_observation_overlay_applied:
        merged_payload["weather_feature_overlay_source"] = "station_observations"
        merged_payload["station_observation_overlay_applied"] = True
        merged_payload["station_observation_overlay_as_of"] = station_observation_overlay_as_of
    top_label_fallback = ""
    try:
        top_label_fallback, _top_q = top_bucket_from_distribution(merged_rows, "q_round")
    except Exception:
        top_label_fallback = ""
    meta = dict(meta_model or {})
    for source in (meta_market or {},):
        if isinstance(source, dict):
            for key, value in source.items():
                if key not in meta or meta.get(key) in (None, ""):
                    meta[key] = value
    event_run_settlement_status = (
        _event_run_settlement_status_candidate(conn, slug, event_date)
        if allow_settlement_status_overlay
        else {}
    )
    settlement_actual = _coalesce_numeric(
        event_run_settlement_status.get("settlement_actual"),
        meta.get("settlement_actual"),
        merged_payload.get("settlement_actual"),
        (merged_payload.get("weather_likelihood_features") or {}).get("settlement_actual")
        if isinstance(merged_payload.get("weather_likelihood_features"), Mapping)
        else None,
        (merged_payload.get("weather_likelihood_features") or {}).get("settlement_actual_c")
        if isinstance(merged_payload.get("weather_likelihood_features"), Mapping)
        else None,
    )
    if settlement_actual is not None:
        merged_payload.setdefault("settlement_actual", float(settlement_actual))
        features = merged_payload.get("weather_likelihood_features")
        if not isinstance(features, Mapping):
            features = {}
        features = dict(features)
        settlement_source = str(event_run_settlement_status.get("source") or "payload")
        precision_profile = _settlement_actual_boundary_profile_from_c(
            settlement_actual,
            rounding_rule=meta.get("rounding_rule") or merged_payload.get("rounding_rule") or "",
            source=settlement_source,
        )
        boundary_ambiguous = bool(precision_profile.get("boundary_ambiguous"))
        features.setdefault("settlement_actual", float(settlement_actual))
        features.setdefault("settlement_actual_c", float(settlement_actual))
        features.setdefault("market_closed", True)
        features.setdefault("settlement_actual_source", settlement_source)
        if boundary_ambiguous:
            merged_payload["settlement_actual_boundary_ambiguous"] = True
            merged_payload["settlement_actual_boundary_ambiguous_reason"] = str(
                precision_profile.get("ambiguous_reason") or "boundary_ambiguous"
            )
            features["settlement_actual_precision"] = precision_profile
            features["settlement_actual_boundary_ambiguous"] = True
            features["settlement_actual_boundary_ambiguous_reason"] = str(
                precision_profile.get("ambiguous_reason") or "boundary_ambiguous"
            )
        else:
            features.setdefault("observed_today_max_c", float(settlement_actual))
            features.setdefault("hard_source_final_daily_max_source", settlement_source)
            features.setdefault("observed_today_max_source", str(event_run_settlement_status.get("source") or "settlement_actual"))
            for key in (
                "observed_today_max_final",
                "hard_source_final_daily_max",
                "hard_source_settlement_final",
                "temperature_observation_final_daily_max",
            ):
                features.setdefault(key, True)
        merged_payload["weather_likelihood_features"] = features
        merged_payload["market_closed"] = 1
    elif event_run_settlement_status.get("market_closed"):
        merged_payload["market_closed"] = 1
    created_candidates = [created_model, market_updated_at or created_market]
    as_of = ""
    best_dt = None
    for ts in created_candidates:
        dt = parse_iso_ts(str(ts or ""))
        if dt is None:
            continue
        if best_dt is None or dt > best_dt:
            best_dt = dt
            as_of = str(ts or "")
    if not as_of:
        as_of = utc_now_iso()
    event_row: Dict[str, Any] = {
        "slug": slug,
        "event_url": meta.get("event_url") or merged_payload.get("event_url") or "",
        "title": meta.get("title") or merged_payload.get("title") or "",
        "city": meta.get("city") or "",
        "lat": meta.get("lat"),
        "lon": meta.get("lon"),
        "tz": meta.get("tz") or merged_payload.get("tz") or "UTC",
        "location_basis": meta.get("location_basis") or "",
        "resolution_source": meta.get("resolution_source") or merged_payload.get("resolution_source") or "",
        "station_id": meta.get("station_id") or "",
        "rounding_rule": meta.get("rounding_rule") or merged_payload.get("rounding_rule") or "",
        "market_var": meta.get("market_var") or merged_payload.get("market_var") or "",
        "market_unit": meta.get("market_unit") or merged_payload.get("market_unit") or "",
        "market_open_at": meta.get("market_open_at"),
        "event_date": _normalize_date_key(event_date),
        "run_date": _normalize_date_key(run_date),
        "suggestions_json": None,
        "settlement_actual": float(settlement_actual) if settlement_actual is not None else None,
        "city_most_likely_label": meta.get("city_most_likely_label") or merged_payload.get("city_most_likely_label") or "",
        "city_most_likely_q": meta.get("city_most_likely_q") or merged_payload.get("city_most_likely_q"),
        "event_peak_time_utc": meta.get("event_peak_time_utc") or "",
        "event_end_utc": meta.get("event_end_utc") or "",
        "market_closed": 1 if meta.get("market_closed") or merged_payload.get("market_closed") or event_run_settlement_status.get("market_closed") else 0,
        "corrected_top_bucket_equal": top_label_fallback or "",
        "corrected_top_bucket_auto": "",
        "corrected_top_bucket_scenario": "",
        "corrected_top_consistency_equal": "",
        "corrected_top_consistency_auto": "",
        "corrected_top_consistency_scenario": "",
        "created_at": as_of,
        "payload_json": json.dumps(merged_payload, ensure_ascii=False),
    }
    try:
        diag = merged_payload.get("bucket_diag") or merged_payload.get("bucket_diagnostics") or {}
        if isinstance(diag, dict):
            corrected = diag.get("corrected_top3")
            if isinstance(corrected, dict):
                for wk, col in (
                    ("equal", "corrected_top_bucket_equal"),
                    ("auto", "corrected_top_bucket_auto"),
                    ("scenario", "corrected_top_bucket_scenario"),
                ):
                    series = corrected.get(wk)
                    if isinstance(series, list) and series and isinstance(series[0], dict):
                        label = str(series[0].get("label") or "")
                        if label:
                            event_row[col] = label
    except Exception:
        pass
    item = build_run_item(
        conn,
        event_row,
        trade_map,
        fills_map,
        auto_orders_map,
        market_tick_latest_map,
        platt=platt,
    )
    _merge_fill_regime_fields_from_model_payload(item, merged_payload)
    if isinstance(merged_payload.get("weather_likelihood_features"), Mapping):
        item["weather_likelihood_features"] = dict(merged_payload.get("weather_likelihood_features") or {})
    run_payload = {
        "score_composer": {
            "model_snapshot_id": model_id,
            "market_snapshot_id": market_id,
            "model_snapshot_at": created_model,
            "market_snapshot_at": market_updated_at or created_market,
            "source": "snapshots",
            "model_source": model_source,
            "market_source": "event_market_ticks" if (market_from_ticks or market_tick_overlay_applied) else "market_snapshots",
            "snapshot_run_date_ceiling": snapshot_run_date_ceiling,
            "market_tick_overlay_applied": bool(market_tick_overlay_applied),
            "market_tick_overlay_at": tick_created_overlay if market_tick_overlay_applied else "",
            "weather_feature_overlay_applied": bool(weather_feature_overlay_applied),
            "weather_feature_overlay_as_of": weather_feature_overlay_as_of,
            "station_observation_overlay_applied": bool(station_observation_overlay_applied),
            "station_observation_overlay_as_of": station_observation_overlay_as_of,
            "settlement_status_source": str(event_run_settlement_status.get("source") or ""),
            "settlement_event_run_id": event_run_settlement_status.get("event_run_id"),
        }
    }
    if model_source == "event_runs":
        run_payload["score_composer"]["event_run_id"] = event_run_id
        run_payload["score_composer"]["event_run_at"] = created_event_run
        run_payload["score_composer"]["event_run_model_payload_at"] = created_model
        run_payload["score_composer"]["model_snapshot_id"] = referenced_model_snapshot_id
        run_payload["score_composer"]["model_snapshot_at"] = referenced_model_snapshot_at
        run_payload["score_composer"]["stale_model_snapshot_id"] = loaded_model_snapshot_id
        run_payload["score_composer"]["stale_model_snapshot_at"] = loaded_model_snapshot_at
    if isinstance(item.get("fact_provenance"), dict):
        item["fact_provenance"].update(run_payload["score_composer"])
    else:
        item["fact_provenance"] = run_payload["score_composer"]
    return item, run_payload, as_of


def _clone_jsonish(value: Any) -> Any:
    if isinstance(value, Mapping):
        return {str(k): _clone_jsonish(v) for k, v in value.items()}
    if isinstance(value, list):
        return [_clone_jsonish(v) for v in value]
    return value


def _merge_fill_jsonish_mapping(existing: Mapping[str, Any], fallback: Mapping[str, Any]) -> Dict[str, Any]:
    merged = {str(k): _clone_jsonish(v) for k, v in existing.items()}
    for key, value in fallback.items():
        key_text = str(key)
        if key_text not in merged or merged.get(key_text) in (None, ""):
            merged[key_text] = _clone_jsonish(value)
            continue
        existing_value = merged.get(key_text)
        if isinstance(existing_value, Mapping) and isinstance(value, Mapping):
            merged[key_text] = _merge_fill_jsonish_mapping(existing_value, value)
    return merged


def _regime_fact_passthrough_keys(payload: Mapping[str, Any]) -> List[str]:
    keys = [
        "climo_regime",
        "climo_regime_features",
        "post_cool_rebound_risk",
        "post_cool_rebound_risk_features",
        "post_cool_rebound_regime_prior",
        "post_cool_rebound_intraday_likelihood",
    ]
    for key in payload.keys():
        key_text = str(key)
        if key_text.startswith("q_bayes_climo_regime_") or key_text.startswith("q_bayes_post_cool_rebound_"):
            keys.append(key_text)
    out: List[str] = []
    seen: Set[str] = set()
    for key in keys:
        if key not in seen:
            seen.add(key)
            out.append(key)
    return out


def _merge_fill_regime_fields_from_model_payload(item: Dict[str, Any], model_payload: Mapping[str, Any]) -> None:
    if not isinstance(item, dict) or not isinstance(model_payload, Mapping):
        return
    filled: List[str] = []
    for key in _regime_fact_passthrough_keys(model_payload):
        if key not in model_payload:
            continue
        value = model_payload.get(key)
        if value in (None, ""):
            continue
        existing = item.get(key)
        if isinstance(existing, Mapping) and isinstance(value, Mapping):
            merged = _merge_fill_jsonish_mapping(existing, value)
            if merged != existing:
                item[key] = merged
                filled.append(key)
        elif existing in (None, ""):
            item[key] = _clone_jsonish(value)
            filled.append(key)
    if filled:
        provenance = item.get("fact_provenance")
        if isinstance(provenance, dict):
            provenance = dict(provenance)
        else:
            provenance = {}
        provenance["regime_fields_merge_fill"] = {
            "source": "model_snapshot_payload",
            "fields": sorted(set(filled)),
            "policy": "merge_fill_only_no_overwrite",
        }
        item["fact_provenance"] = provenance


def _ui_snapshot_ts_newer_or_equal(candidate: str, existing: str) -> bool:
    if not existing:
        return True
    if not candidate:
        return False
    candidate_dt = parse_iso_ts(str(candidate or ""))
    existing_dt = parse_iso_ts(str(existing or ""))
    if candidate_dt is not None and existing_dt is not None:
        return candidate_dt >= existing_dt
    return str(candidate or "") >= str(existing or "")


def _ui_snapshot_payload_has_final_settlement_lock(payload: Any) -> bool:
    if not isinstance(payload, Mapping):
        return False
    if to_float(payload.get("settlement_actual")) is not None:
        return True
    features = payload.get("weather_likelihood_features")
    if isinstance(features, Mapping) and to_float(
        features.get("settlement_actual")
        if features.get("settlement_actual") is not None
        else features.get("settlement_actual_c")
    ) is not None:
        return True
    meta = payload.get("hard_source_posterior_override_meta")
    if not isinstance(meta, Mapping):
        meta = payload.get("hard_source_posterior_override")
    if isinstance(meta, Mapping) and _truthy(meta.get("final_bucket_lock")):
        return True
    return False


def _event_run_settlement_status_candidate(
    conn: sqlite3.Connection,
    slug: str,
    event_date: str,
) -> Dict[str, Any]:
    slug_key = str(slug or "").strip()
    event_date_key = _normalize_date_key(str(event_date or ""))
    if not slug_key or not event_date_key:
        return {}
    try:
        cur = conn.cursor()
        cur.execute("PRAGMA table_info(event_runs)")
        columns = {str(row["name"] or "") for row in cur.fetchall()}
    except sqlite3.OperationalError:
        return {}
    if not columns or "slug" not in columns or "event_date" not in columns:
        return {}

    select_parts = []
    for col in ("id", "run_date", "settlement_actual", "market_closed", "payload_json", "meta_json", "created_at"):
        if col in columns:
            select_parts.append(col)
        else:
            select_parts.append(f"NULL AS {col}")
    try:
        cur.execute(
            f"""
            SELECT {", ".join(select_parts)}
            FROM event_runs
            WHERE slug = ?
              AND substr(COALESCE(event_date, ''), 1, 10) = ?
            ORDER BY COALESCE(created_at, '') DESC, COALESCE(id, 0) DESC
            LIMIT 20
            """,
            (slug_key, event_date_key),
        )
    except sqlite3.OperationalError:
        return {}

    best_closed: Dict[str, Any] = {}
    for row in cur.fetchall():
        payload = safe_json_loads(str(row["payload_json"] or "")) if row["payload_json"] is not None else {}
        meta = safe_json_loads(str(row["meta_json"] or "")) if row["meta_json"] is not None else {}
        features = (
            payload.get("weather_likelihood_features")
            if isinstance(payload, Mapping) and isinstance(payload.get("weather_likelihood_features"), Mapping)
            else {}
        )
        actual = _coalesce_numeric(
            row["settlement_actual"],
            payload.get("settlement_actual") if isinstance(payload, Mapping) else None,
            meta.get("settlement_actual") if isinstance(meta, Mapping) else None,
            features.get("settlement_actual") if isinstance(features, Mapping) else None,
            features.get("settlement_actual_c") if isinstance(features, Mapping) else None,
        )
        closed = bool(
            _truthy(row["market_closed"])
            or (isinstance(payload, Mapping) and _truthy(payload.get("market_closed")))
            or (isinstance(meta, Mapping) and _truthy(meta.get("market_closed")))
            or actual is not None
        )
        candidate = {
            "settlement_actual": float(actual) if actual is not None else None,
            "market_closed": 1 if closed else 0,
            "created_at": str(row["created_at"] or ""),
            "run_date": _normalize_date_key(str(row["run_date"] or "")),
            "event_run_id": _to_int(row["id"]),
            "source": (
                "event_runs.settlement_actual"
                if actual is not None and to_float(row["settlement_actual"]) is not None
                else (
                    "event_runs.payload_or_meta_settlement_actual"
                    if actual is not None
                    else "event_runs.market_closed"
                )
            ),
        }
        if actual is not None:
            return candidate
        if closed and not best_closed:
            best_closed = candidate
    return best_closed


def _compose_live_snapshot_items_for_ui(
    conn: sqlite3.Connection,
    run_date: str,
    limit: int,
    platt: Optional[Dict[str, Any]],
    existing_as_of_by_key: Optional[Dict[Tuple[str, str], str]] = None,
) -> List[Dict[str, Any]]:
    try:
        event_rows = select_event_run_rows(conn, run_date, include_history=False)
    except sqlite3.Error:
        event_rows = []
    rows = [
        (
            str(row["slug"] or "").strip(),
            _normalize_date_key(str(row["event_date"] or "")),
            _normalize_date_key(str(row["run_date"] or "")),
        )
        for row in event_rows
        if str(row["slug"] or "").strip()
        and _normalize_date_key(str(row["event_date"] or ""))
        and _normalize_date_key(str(row["run_date"] or ""))
    ]
    if not rows:
        rows = _snapshot_key_rows_for_run_date(conn, run_date)
    if not rows:
        return []
    try:
        limit_val = max(1, min(int(limit or 1), 2000))
    except (TypeError, ValueError):
        limit_val = 200
    trade_map = query_edge_trades(conn)
    fills_map = query_trade_fills(conn)
    auto_orders_map = query_auto_orders(conn)
    market_tick_latest_map = query_market_tick_latest_for_keys(
        conn,
        [(slug, event_date) for slug, event_date, _run_date_val in rows],
    )
    out: List[Dict[str, Any]] = []
    existing_map = existing_as_of_by_key or {}
    for slug, event_date, run_date_val in sorted(rows):
        composed = _compose_fact_from_snapshots(
            conn,
            run_date_val,
            slug,
            event_date,
            trade_map,
            fills_map,
            auto_orders_map,
            market_tick_latest_map,
            platt=platt,
        )
        if not composed:
            continue
        item, _run_payload, as_of = composed
        key = (str(slug or "").strip(), _normalize_date_key(str(event_date or "")))
        if not _ui_snapshot_ts_newer_or_equal(as_of, str(existing_map.get(key) or "")):
            continue
        if not isinstance(item, dict):
            continue
        item["fact_as_of"] = as_of
        provenance = item.get("fact_provenance")
        if isinstance(provenance, dict):
            provenance = dict(provenance)
        else:
            provenance = {}
        provenance["ui_snapshot_source"] = "live_snapshot_compose"
        provenance["live_snapshot_composed"] = True
        item["fact_provenance"] = provenance
        out.append(item)
        if len(out) >= limit_val:
            break
    out.sort(
        key=lambda item: str(item.get("fact_as_of") or item.get("market_updated_at") or ""),
        reverse=True,
    )
    return out


def _market_discovery_pending_model_payload(item: Optional[Mapping[str, Any]]) -> bool:
    payload = item if isinstance(item, Mapping) else {}
    if str(payload.get("data_status") or "").strip() == "market_discovery_pending_model":
        return True
    if str(payload.get("weather_strategy_mode") or "").strip() == "market_discovery_pending_model":
        return True
    if _truthy(payload.get("market_discovery_placeholder")):
        return True
    provenance = payload.get("fact_provenance")
    if isinstance(provenance, Mapping) and _truthy(provenance.get("market_discovery_placeholder")):
        return True
    discovery = payload.get("market_discovery")
    return isinstance(discovery, Mapping) and str(discovery.get("source") or "").strip() == "weather_market_discovery"


def _discovery_pending_fact_forward_allowed(event_date: str) -> bool:
    event_key = _normalize_date_key(str(event_date or ""))
    today_key = _normalize_date_key(_today_et_key())
    return bool(event_key and today_key and event_key >= today_key)


def _discovery_placeholder_row_for_key(
    conn: sqlite3.Connection,
    *,
    slug: str,
    event_date: str,
) -> Optional[sqlite3.Row]:
    slug_key = str(slug or "").strip()
    event_key = _normalize_date_key(str(event_date or ""))
    if not slug_key or not event_key:
        return None
    rows = _discovery_placeholder_candidate_rows(
        conn,
        event_key,
        upcoming_days=0,
        exclude_keys=set(),
        limit=64,
    )
    for row in rows:
        row_slug = str((row["slug"] if isinstance(row, sqlite3.Row) else row[0]) or "").strip()
        row_event_date = _normalize_date_key(
            str((row["event_date"] if isinstance(row, sqlite3.Row) else row[1]) or "")
        )
        if row_slug == slug_key and row_event_date == event_key:
            return row
    return None


def _pending_discovery_posterior_run_id(*, slug: str, event_date: str, run_date: str) -> str:
    material = json.dumps(
        {
            "source": "weather_market_discovery",
            "state": "pending_model_snapshot",
            "slug": str(slug or ""),
            "event_date": str(event_date or ""),
            "run_date": str(run_date or ""),
        },
        ensure_ascii=False,
        sort_keys=True,
        separators=(",", ":"),
    )
    digest = hashlib.sha256(material.encode("utf-8")).hexdigest()[:20]
    return f"post_pending_discovery_{digest}"


def _feature_first_float(features: Mapping[str, Any], *keys: str) -> Optional[float]:
    for key in keys:
        value = to_float(features.get(key))
        if value is not None:
            return float(value)
    return None


def _feature_first_text(features: Mapping[str, Any], *keys: str) -> str:
    for key in keys:
        value = str(features.get(key) or "").strip()
        if value:
            return value
    return ""


def _posterior_bucket_labels_from_item(item: Mapping[str, Any]) -> List[str]:
    rows = item.get("distribution") if isinstance(item.get("distribution"), list) else item.get("rows")
    labels: List[str] = []
    if not isinstance(rows, list):
        return labels
    for row in rows:
        if not isinstance(row, Mapping):
            continue
        label = str(row.get("outcome") or row.get("label") or row.get("bucket") or "").strip()
        if label and label not in labels:
            labels.append(label)
    return labels


def _pending_model_observation_inputs_from_features(features: Mapping[str, Any]) -> Dict[str, Any]:
    out: Dict[str, Any] = {}

    def put_float(target: str, *keys: str) -> None:
        value = _feature_first_float(features, *keys)
        if value is not None:
            out[target] = value

    def put_text(target: str, *keys: str) -> None:
        value = _feature_first_text(features, *keys)
        if value:
            out[target] = value

    def put_bool(target: str, *keys: str) -> None:
        for key in keys:
            if key not in features:
                continue
            value = features.get(key)
            if isinstance(value, bool):
                out[target] = value
                return
            text = str(value).strip().lower()
            if text in {"1", "true", "yes", "on"}:
                out[target] = True
                return
            if text in {"0", "false", "no", "off"}:
                out[target] = False
                return

    put_float(
        "current_temp_c",
        "current_temp_c",
        "observed_current_temp_c",
        "observed_temp_c",
        "observed_temp",
        "metar_temperature_c",
        "temperature_c",
        "zuuu_metar_raw_amsc_latest_temp_c",
        "zuuu_metar_raw_awc_latest_temp_c",
    )
    put_float(
        "observed_today_max_c",
        "observed_today_max_c",
        "today_max_c",
        "daily_max_observed_c",
        "zuuu_metar_raw_amsc_today_max_c",
        "zuuu_metar_raw_awc_today_max_c",
    )
    put_float("dewpoint_c", "dewpoint_c", "metar_dewpoint_c", "dew_point_c", "zuuu_metar_raw_amsc_latest_dewpoint_c", "zuuu_metar_raw_awc_latest_dewpoint_c")
    put_float("visibility_m", "visibility_m", "metar_visibility_m", "visibility", "zuuu_metar_raw_amsc_latest_visibility_m")
    put_float("cloud_cover_pct", "cloud_cover_pct", "cloud_pct", "metar_cloud_cover_pct", "zuuu_metar_raw_amsc_latest_cloud_cover_pct")
    put_float("low_cloud_cover_pct", "low_cloud_cover_pct", "low_cloud_pct", "zuuu_metar_raw_amsc_latest_low_cloud_cover_pct")
    put_float("wind_speed_mps", "wind_speed_mps", "metar_wind_speed_mps", "zuuu_metar_raw_amsc_latest_wind_speed_mps", "awc_wind_speed_mps", "zuuu_metar_raw_awc_latest_wind_speed_mps")
    put_float("pressure_hpa", "pressure_hpa", "altimeter_hpa", "metar_pressure_hpa", "zuuu_metar_raw_amsc_latest_pressure_hpa", "awc_pressure_hpa", "zuuu_metar_raw_awc_latest_pressure_hpa")
    put_float("dewpoint_trend_c", "dewpoint_trend_c", "dewpoint_trend_c_per_hour", "zuuu_metar_raw_amsc_dewpoint_trend_c", "zuuu_metar_raw_awc_dewpoint_trend_c")
    put_float(
        "momentum_rate_c_per_hour",
        "momentum_rate_c_per_hour",
        "temperature_rate_c_per_hour",
        "temperature_rise_rate_c_per_hour",
        "observed_temp_rise_rate_c_per_hour",
        "metar_temp_rise_rate_c_per_hour",
        "temperature_momentum_posterior_effective_c_per_hour",
        "temperature_momentum_effective_c_per_hour",
        "temperature_momentum_1h_c_per_hour",
        "zuuu_metar_raw_amsc_temperature_momentum_1h_c_per_hour",
        "zuuu_metar_raw_awc_temperature_momentum_1h_c_per_hour",
    )
    for window in ("30m", "45m", "1h", "2h", "3h", "6h", "12h"):
        put_float(
            f"temperature_momentum_{window}_c_per_hour",
            f"temperature_momentum_{window}_c_per_hour",
            f"temperature_rise_rate_{window}_c_per_hour",
            f"zuuu_metar_raw_amsc_temperature_momentum_{window}_c_per_hour",
            f"zuuu_metar_raw_awc_temperature_momentum_{window}_c_per_hour",
        )
    put_float(
        "temperature_trajectory_stable_rate_c_per_hour",
        "temperature_trajectory_stable_rate_c_per_hour",
        "temperature_momentum_stable_c_per_hour",
        "zuuu_metar_raw_amsc_temperature_trajectory_stable_rate_c_per_hour",
        "zuuu_metar_raw_awc_temperature_trajectory_stable_rate_c_per_hour",
    )
    put_text(
        "temperature_trajectory_realization_state",
        "temperature_trajectory_realization_state",
        "temperature_momentum_realization_state",
        "zuuu_metar_raw_amsc_temperature_momentum_realization_state",
        "zuuu_metar_raw_amsc_temperature_trajectory_realization_state",
        "zuuu_metar_raw_awc_temperature_momentum_realization_state",
    )
    put_text("weather_text", "weather_text", "metar_weather", "weather", "wx", "zuuu_metar_raw_amsc_latest_weather_text", "zuuu_metar_raw_amsc_latest_raw", "zuuu_metar_raw_awc_latest_raw")
    put_text("cloud_text", "cloud_text", "clouds", "metar_cloud_text", "zuuu_metar_raw_amsc_latest_cloud_text", "zuuu_metar_raw_amsc_latest_raw", "zuuu_metar_raw_awc_latest_raw")
    put_bool(
        "hard_source_final_daily_max",
        "hard_source_final_daily_max",
        "hard_source_settlement_final",
        "observed_today_max_final",
        "observed_today_max_is_final",
        "observed_today_max_is_official",
        "observed_today_max_trusted_final",
        "temperature_observation_final_daily_max",
        "no_more_warming_possible",
    )
    return out


def _pending_model_source_observations_from_features(
    *,
    features: Mapping[str, Any],
    event_date: str,
    station_id: str,
) -> List[Dict[str, Any]]:
    observations: List[Dict[str, Any]] = []
    station = str(
        station_id
        or features.get("station_id")
        or features.get("zuuu_metar_raw_amsc_station_id")
        or features.get("zuuu_metar_raw_awc_station_id")
        or "ZUUU"
    )
    hard_inputs = _pending_model_observation_inputs_from_features(features)
    if hard_inputs:
        source_id = (
            "zuuu_metar_raw_amsc"
            if any(
                features.get(key) not in (None, "", [], {})
                for key in (
                    "zuuu_metar_raw_amsc_latest_at",
                    "zuuu_metar_raw_amsc_latest_temp_c",
                    "zuuu_metar_raw_amsc_today_max_c",
                    "zuuu_metar_raw_amsc_latest_raw",
                )
            )
            else "zuuu_metar_raw_awc"
        )
        valid_time = _feature_first_text(
            features,
            f"{source_id}_latest_at",
            "zuuu_metar_raw_amsc_latest_at",
            "zuuu_metar_raw_awc_latest_at",
            "valid_time",
            "valid_time_local",
            "observation_time",
        )
        fetched_at = _feature_first_text(
            features,
            f"{source_id}_fetched_at",
            "zuuu_metar_raw_amsc_fetched_at",
            "zuuu_metar_raw_awc_fetched_at",
            "fetched_at",
            "response_completed_at",
        )
        raw_text = _feature_first_text(
            features,
            f"{source_id}_latest_raw",
            "zuuu_metar_raw_amsc_latest_raw",
            "zuuu_metar_raw_awc_latest_raw",
            "metar_raw",
            "raw_text",
        )
        observations.append(
            build_source_observation(
                source_id=source_id,
                station_id=station,
                event_date=event_date,
                valid_time=valid_time,
                fetched_at=fetched_at,
                response_duration_ms=_feature_first_float(
                    features,
                    f"{source_id}_fetch_duration_ms",
                    "zuuu_metar_raw_amsc_fetch_duration_ms",
                    "zuuu_metar_raw_awc_fetch_duration_ms",
                ),
                temperature_c=_feature_first_float(hard_inputs, "current_temp_c"),
                dewpoint_c=_feature_first_float(hard_inputs, "dewpoint_c"),
                observed_today_max_c=_feature_first_float(hard_inputs, "observed_today_max_c"),
                raw_ref=_feature_first_text(
                    features,
                    "zuuu_metar_raw_amsc_source_url",
                    "zuuu_metar_raw_amsc_url",
                    "zuuu_metar_raw_awc_url",
                ),
                raw_payload={"raw_text": raw_text, "features": dict(features)},
                parser_version="ui_pending_model_hierarchical_posterior_v1",
                payload={
                    **hard_inputs,
                    "raw_text": raw_text,
                    "adapter": "ui_pending_model_hierarchical_posterior_v1",
                },
            ).as_dict(include_payload=True)
        )
    forecast_specs = (
        ("current_model_ensemble", "model", ("forecast_peak_temp_c", "forecast_peak_temp", "forecast_peak_c", "model_peak_c", "expected_peak_temp_c")),
        ("zuuu_taf_forecast_amsc", "taf", ("taf_forecast_peak_c", "taf_peak_c", "taf_tx_c")),
        ("wu_forecast_high", "wu_forecast", ("wu_forecast_peak_c", "wunderground_forecast_peak_c")),
        ("weather_com_forecast_peak", "twc_forecast", ("weather_com_forecast_peak_c", "twc_forecast_peak_c")),
        ("ecmwf_model_peak", "model", ("ecmwf_model_peak_c", "ecmwf_forecast_peak_c")),
        ("gfs_model_peak", "model", ("gfs_model_peak_c", "gfs_forecast_peak_c")),
        ("icon_model_peak", "model", ("icon_model_peak_c",)),
        ("meteoblue_model_peak", "model", ("meteoblue_model_peak_c",)),
    )
    valid_time = _feature_first_text(features, "forecast_valid_time", "model_valid_time", "valid_time")
    for source_id, group, keys in forecast_specs:
        peak_c = _feature_first_float(features, *keys)
        if peak_c is None:
            continue
        observations.append(
            build_source_observation(
                source_id=source_id,
                station_id=station,
                event_date=event_date,
                valid_time=valid_time,
                forecast_peak_c=float(peak_c),
                parser_version="ui_pending_model_hierarchical_posterior_v1",
                payload={
                    "forecast_group": group,
                    "adapter": "ui_pending_model_hierarchical_posterior_v1",
                },
            ).as_dict(include_payload=True)
        )
    return observations


def _source_latency_trace_from_observations(observations: Sequence[Mapping[str, Any]]) -> List[Dict[str, Any]]:
    rows: List[Dict[str, Any]] = []
    for obs in observations:
        if not isinstance(obs, Mapping):
            continue
        rows.append(
            {
                "source_event_id": str(obs.get("source_event_id") or ""),
                "source_id": str(obs.get("source_id") or ""),
                "source_class": str(obs.get("source_class") or ""),
                "role": str(obs.get("role") or ""),
                "station_id": str(obs.get("station_id") or ""),
                "event_date": str(obs.get("event_date") or ""),
                "valid_time": str(obs.get("valid_time") or ""),
                "valid_time_local": str(obs.get("valid_time_local") or ""),
                "fetched_at": str(obs.get("fetched_at") or ""),
                "response_completed_at": str(obs.get("response_completed_at") or ""),
                "response_duration_ms": obs.get("response_duration_ms"),
                "temperature_c": obs.get("temperature_c"),
                "observed_today_max_c": obs.get("observed_today_max_c"),
                "forecast_peak_c": obs.get("forecast_peak_c"),
                "raw_ref": str(obs.get("raw_ref") or ""),
                "hard_eligible": bool(obs.get("hard_eligible")),
                "demotion_reason": str(obs.get("demotion_reason") or ""),
            }
        )
    return rows


def _compose_event_run_fact_for_materialization(
    conn: sqlite3.Connection,
    *,
    run_date: str,
    slug: str,
    event_date: str,
    trade_map: Dict[Tuple[str, str], List[sqlite3.Row]],
    fills_map: Dict[Tuple[str, str, str, str], List[sqlite3.Row]],
    auto_orders_map: Dict[str, sqlite3.Row],
    market_tick_latest_map: Optional[Dict[Tuple[str, str], str]],
    platt: Optional[Dict[str, Any]],
) -> Optional[Tuple[Dict[str, Any], Dict[str, Any], str]]:
    event_run_row = query_latest_event_run_for_run_date(conn, slug, event_date, run_date)
    if event_run_row is None:
        return None
    item = build_run_item(
        conn,
        event_run_row,
        trade_map,
        fills_map,
        auto_orders_map,
        market_tick_latest_map,
        platt=platt,
    )
    run_payload = safe_json_loads(event_run_row["payload_json"])
    _attach_fact_provenance_from_run_payload(item, run_payload)
    provenance = dict(item.get("fact_provenance") or {})
    provenance["fact_materialization_source_resolver"] = {
        "source": "event_runs",
        "state": "resolved",
        "formal_fact_chain": True,
    }
    item["fact_provenance"] = provenance
    return item, run_payload, str(event_run_row["created_at"] or "")


def _compose_discovery_pending_fact_for_materialization(
    conn: sqlite3.Connection,
    *,
    run_date: str,
    slug: str,
    event_date: str,
) -> Optional[Tuple[Dict[str, Any], Dict[str, Any], str]]:
    slug_key = str(slug or "").strip()
    event_key = _normalize_date_key(str(event_date or ""))
    run_key = _normalize_date_key(str(run_date or "")) or event_key
    if not slug_key or not event_key or not run_key:
        return None
    if not _discovery_pending_fact_forward_allowed(event_key):
        return None
    latest_head = _latest_fact_head(conn, slug_key, event_key)
    latest_as_of, latest_payload = _latest_fact_payload_for_merge_fill(conn, slug_key, event_key)
    if latest_head and not _market_discovery_pending_model_payload(latest_payload):
        return None
    discovery_row = _discovery_placeholder_row_for_key(conn, slug=slug_key, event_date=event_key)
    if discovery_row is None:
        return None
    item = _build_discovery_placeholder_payload(conn, discovery_row, display_run_date=run_key)
    latest_dt = parse_iso_ts(str(latest_as_of or ""))
    item_dt = parse_iso_ts(str(item.get("fact_as_of") or item.get("created_at") or ""))
    if latest_dt is not None and (item_dt is None or latest_dt > item_dt):
        item["fact_as_of"] = str(latest_as_of or "")
        item["created_at"] = str(latest_as_of or "")
        item["market_updated_at"] = str(item.get("market_updated_at") or latest_as_of or "")
    source_event_id = f"srcevt_market_discovery:{slug_key}:{event_key}"
    pending_posterior_run_id = _pending_discovery_posterior_run_id(
        slug=slug_key,
        event_date=event_key,
        run_date=run_key,
    )
    item["source_event_id"] = source_event_id
    item["source_event_ids"] = [source_event_id]
    item["posterior_run_id"] = pending_posterior_run_id
    item["posterior_as_of"] = str(item.get("fact_as_of") or item.get("created_at") or now_text())
    provenance = dict(item.get("fact_provenance") or {})
    provenance["fact_materialization"] = {
        "source": "weather_market_discovery",
        "state": "pending_model_snapshot",
        "reason": "market_tokenized_before_model_fact_materialized",
        "forward_only": True,
        "historical_backfill": False,
        "latest_fact_as_of_before_write": latest_as_of,
    }
    provenance["fact_materialization_source_resolver"] = {
        "source": "weather_market_discovery",
        "state": "pending_model_snapshot",
        "formal_fact_chain": True,
    }
    item["fact_provenance"] = provenance
    item["posterior_materialization_state"] = {
        "schema": "posterior_materialization_state_v1",
        "state": "pending_model_snapshot",
        "state_reason": "market_discovery_tokenized_before_model_snapshot",
        "source": "weather_market_discovery",
        "posterior_run_id": pending_posterior_run_id,
        "available_posterior": False,
        "frontend_recompute_allowed": False,
        "decision_recompute_allowed": False,
        "historical_backfill": False,
    }
    item["source_acquisition_trace"] = {
        "schema": "market_discovery_pending_model_source_trace_v1",
        "read_only": True,
        "source_event_ids": [source_event_id],
        "source_observations": [
            {
                "source_event_id": source_event_id,
                "source": "weather_market_discovery",
                "source_class": "market_discovery_pending_model",
                "hard_eligible": False,
                "slug": slug_key,
                "event_date": event_key,
                "observed_at": str(item.get("fact_as_of") or ""),
            }
        ],
        "source_latency_trace": [],
        "hard_observation_candidate_ids": [],
        "forecast_weak_ids": [],
        "diagnostic_current_ids": [source_event_id],
        "next_boundary": "model_snapshot_materializes_available_posterior_ssot_fact",
    }
    run_payload = {
        "source": "weather_market_discovery",
        "score_composer": {
            "model_snapshot_id": None,
            "market_snapshot_id": None,
        },
    }
    return item, run_payload, str(item.get("fact_as_of") or item.get("created_at") or now_text())


def _compose_fact_materialization_candidate(
    conn: sqlite3.Connection,
    *,
    run_date: str,
    slug: str,
    event_date: str,
    trade_map: Dict[Tuple[str, str], List[sqlite3.Row]],
    fills_map: Dict[Tuple[str, str, str, str], List[sqlite3.Row]],
    auto_orders_map: Dict[str, sqlite3.Row],
    market_tick_latest_map: Optional[Dict[Tuple[str, str], str]],
    platt: Optional[Dict[str, Any]],
) -> Optional[Tuple[Dict[str, Any], Dict[str, Any], str]]:
    composed = _compose_fact_from_snapshots(
        conn,
        run_date,
        slug,
        event_date,
        trade_map,
        fills_map,
        auto_orders_map,
        market_tick_latest_map,
        platt=platt,
    )
    if composed:
        item, run_payload, as_of = composed
        if isinstance(item, dict):
            provenance = dict(item.get("fact_provenance") or {})
            provenance["fact_materialization_source_resolver"] = {
                "source": "snapshots",
                "state": "resolved",
                "formal_fact_chain": True,
            }
            item["fact_provenance"] = provenance
        return item, run_payload, as_of
    event_run_composed = _compose_event_run_fact_for_materialization(
        conn,
        run_date=run_date,
        slug=slug,
        event_date=event_date,
        trade_map=trade_map,
        fills_map=fills_map,
        auto_orders_map=auto_orders_map,
        market_tick_latest_map=market_tick_latest_map,
        platt=platt,
    )
    if event_run_composed:
        return event_run_composed
    return _compose_discovery_pending_fact_for_materialization(
        conn,
        run_date=run_date,
        slug=slug,
        event_date=event_date,
    )


def _materialize_facts_from_snapshots_for_run_date(conn: sqlite3.Connection, run_date: str) -> int:
    rows = _snapshot_key_rows_for_run_date(conn, run_date)
    if not rows:
        return 0
    trade_map = query_edge_trades(conn)
    fills_map = query_trade_fills(conn)
    auto_orders_map = query_auto_orders(conn)
    market_tick_latest_map = query_market_tick_latest_for_keys(
        conn,
        [(slug, event_date) for slug, event_date, _run_date_val in rows],
    )
    try:
        platt_days = int(os.environ.get("PM_Q_PLATT_DAYS", "60"))
    except (TypeError, ValueError):
        platt_days = 60
    platt = _load_platt_calibration(platt_days or 0)
    created = 0
    for slug, event_date, run_date_val in sorted(rows):
        composed = _compose_fact_materialization_candidate(
            conn,
            run_date=run_date_val,
            slug=slug,
            event_date=event_date,
            trade_map=trade_map,
            fills_map=fills_map,
            auto_orders_map=auto_orders_map,
            market_tick_latest_map=market_tick_latest_map,
            platt=platt,
        )
        if not composed:
            continue
        item, run_payload, as_of = composed
        fact_id = upsert_event_fact_from_run_item(
            conn,
            run_date=run_date_val,
            slug=slug,
            event_date=event_date,
            run_created_at=as_of,
            run_payload=run_payload,
            item=item,
        )
        if fact_id:
            created += 1
    if created:
        try:
            conn.commit()
        except sqlite3.Error:
            pass
    return created


def _materialize_facts_from_snapshots_for_range(conn: sqlite3.Connection, start_date: str, end_date: str) -> int:
    rows = _snapshot_key_rows_for_run_date_range(conn, start_date, end_date)
    if not rows:
        return 0
    trade_map = query_edge_trades(conn)
    fills_map = query_trade_fills(conn)
    auto_orders_map = query_auto_orders(conn)
    market_tick_latest_map = query_market_tick_latest_for_keys(
        conn,
        [(slug, event_date) for slug, event_date, _run_date_val in rows],
    )
    try:
        platt_days = int(os.environ.get("PM_Q_PLATT_DAYS", "60"))
    except (TypeError, ValueError):
        platt_days = 60
    platt = _load_platt_calibration(platt_days or 0)
    created = 0
    for slug, event_date, run_date_val in sorted(rows):
        composed = _compose_fact_materialization_candidate(
            conn,
            run_date=run_date_val,
            slug=slug,
            event_date=event_date,
            trade_map=trade_map,
            fills_map=fills_map,
            auto_orders_map=auto_orders_map,
            market_tick_latest_map=market_tick_latest_map,
            platt=platt,
        )
        if not composed:
            continue
        item, run_payload, as_of = composed
        fact_id = upsert_event_fact_from_run_item(
            conn,
            run_date=run_date_val,
            slug=slug,
            event_date=event_date,
            run_created_at=as_of,
            run_payload=run_payload,
            item=item,
        )
        if fact_id:
            created += 1
    if created:
        try:
            conn.commit()
        except sqlite3.Error:
            pass
    return created


def _lead_day_run_date_key(event_date: str, lead_key: str) -> str:
    event_dt = parse_date(_normalize_date_key(str(event_date or "")))
    if event_dt is None:
        return ""
    lead_text = str(lead_key or "").strip().upper()
    if not lead_text.startswith("D"):
        return ""
    try:
        delta_days = int(lead_text[1:])
    except ValueError:
        return ""
    return (event_dt - timedelta(days=delta_days)).isoformat()


def _normalize_lead_day_keys(value: Any) -> Tuple[str, ...]:
    raw_parts: Iterable[Any]
    if isinstance(value, str):
        raw_parts = value.split(",")
    elif isinstance(value, (list, tuple, set)):
        raw_parts = value
    else:
        raw_parts = ()
    out: List[str] = []
    for raw in raw_parts:
        lead_key = str(raw or "").strip().upper()
        if lead_key in PREDICTION_LEAD_DAY_KEYS and lead_key not in out:
            out.append(lead_key)
    return tuple(out or PREDICTION_LEAD_DAY_KEYS)


def _lead_day_window_for_materialization(
    event_date: str,
    lead_key: str,
    settlement_known_at: str = "",
    event_end_utc: str = "",
) -> Tuple[str, str]:
    start_ts, end_ts = _prediction_lead_day_utc_window(event_date, lead_key)
    if not start_ts or not end_ts:
        return "", ""
    end_dt = parse_iso_ts(end_ts)
    cutoffs = []
    settlement_dt = parse_iso_ts(str(settlement_known_at or ""))
    event_end_dt = parse_iso_ts(str(event_end_utc or ""))
    if settlement_dt is not None:
        cutoffs.append(settlement_dt)
    if event_end_dt is not None:
        cutoffs.append(event_end_dt)
    if end_dt is not None:
        for cutoff_dt in cutoffs:
            if cutoff_dt < end_dt:
                end_dt = cutoff_dt
        end_ts = end_dt.isoformat(timespec="seconds")
    if start_ts >= end_ts:
        return "", ""
    return start_ts, end_ts


def _load_lead_day_materialization_settlement_meta_map(
    conn: sqlite3.Connection,
    start_key: str,
    end_key: str,
    *,
    scope: str = "chengdu_zuuu",
) -> Dict[Tuple[str, str], Dict[str, Any]]:
    if str(scope or "") != "chengdu_zuuu":
        return _load_settlement_meta_map(conn, start_key, end_key)
    out: Dict[Tuple[str, str], Dict[str, Any]] = {}
    source_tables = (
        ("event_daily_temps", "event_daily_temps"),
        ("event_runs", "event_runs"),
    )
    for table, source_name in source_tables:
        if not _sqlite_table_exists(conn, table):
            continue
        columns = _sqlite_table_columns(conn, table)
        required = {"slug", "event_date", "settlement_actual", "created_at"}
        if not required.issubset(columns):
            continue
        select_parts = [
            "slug",
            "event_date",
            "settlement_actual",
            "created_at",
            "title" if "title" in columns else "NULL AS title",
            "city" if "city" in columns else "NULL AS city",
            "station_id" if "station_id" in columns else "NULL AS station_id",
            "event_end_utc" if "event_end_utc" in columns else "NULL AS event_end_utc",
        ]
        try:
            cur = conn.cursor()
            cur.execute(
                f"""
                SELECT {", ".join(select_parts)}
                FROM {table}
                WHERE settlement_actual IS NOT NULL
                  AND event_date BETWEEN ? AND ?
                ORDER BY created_at DESC
                """,
                (start_key, end_key),
            )
            rows = cur.fetchall()
        except sqlite3.Error:
            continue
        for row in rows:
            slug = str(row["slug"] or "").strip()
            event_date = _normalize_date_key(str(row["event_date"] or ""))
            if not slug or not event_date:
                continue
            if not _event_date_matches_slug(slug, event_date):
                continue
            title = str(row["title"] or "")
            city = str(row["city"] or "")
            station_id = str(row["station_id"] or "").strip().upper()
            if not (
                _is_chengdu_market_identifier(slug, title)
                or "chengdu" in city.lower()
                or station_id == "ZUUU"
            ):
                continue
            key = (slug, event_date)
            if key in out:
                continue
            out[key] = {
                "settlement_actual": to_float(row["settlement_actual"]),
                "settlement_known_at": str(row["created_at"] or ""),
                "settlement_source": source_name,
                "event_end_utc": str(row["event_end_utc"] or ""),
            }
    if out and _sqlite_table_exists(conn, "event_runs"):
        columns = _sqlite_table_columns(conn, "event_runs")
        if {"slug", "event_date", "event_end_utc"}.issubset(columns):
            try:
                cur = conn.cursor()
                cur.execute(
                    """
                    SELECT slug, event_date, event_end_utc
                    FROM event_runs
                    WHERE event_date BETWEEN ? AND ?
                      AND event_end_utc IS NOT NULL
                      AND event_end_utc != ''
                    ORDER BY created_at DESC
                    """,
                    (start_key, end_key),
                )
                rows = cur.fetchall()
            except sqlite3.Error:
                rows = []
            for row in rows:
                key = (str(row["slug"] or "").strip(), _normalize_date_key(str(row["event_date"] or "")))
                if key not in out:
                    continue
                if out[key].get("event_end_utc"):
                    continue
                out[key]["event_end_utc"] = str(row["event_end_utc"] or "")
    return out


def _lead_day_snapshot_availability(
    conn: sqlite3.Connection,
    slug: str,
    event_date: str,
    start_ts: str,
    end_ts: str,
) -> Dict[str, Any]:
    out: Dict[str, Any] = {}
    queries = (
        ("model_snapshots", "model_snapshot_count", "model_snapshot_latest_at"),
        ("market_snapshots", "market_snapshot_count", "market_snapshot_latest_at"),
        ("event_market_ticks", "market_tick_count", "market_tick_latest_at"),
    )
    for table, count_key, latest_key in queries:
        if not _sqlite_table_exists(conn, table):
            out[count_key] = 0
            out[latest_key] = ""
            continue
        try:
            cur = conn.cursor()
            cur.execute(
                f"""
                SELECT COUNT(*) AS n, MAX(created_at) AS latest_at
                FROM {table}
                WHERE slug = ?
                  AND event_date = ?
                  AND created_at >= ?
                  AND created_at < ?
                """,
                (slug, event_date, start_ts, end_ts),
            )
            row = cur.fetchone()
        except sqlite3.Error:
            row = None
        out[count_key] = int(row["n"] or 0) if row is not None else 0
        out[latest_key] = str(row["latest_at"] or "") if row is not None else ""
    return out


def _lead_day_existing_usable_fact(
    conn: sqlite3.Connection,
    slug: str,
    event_date: str,
    start_ts: str,
    end_ts: str,
    settlement_meta: Mapping[str, Any],
) -> Dict[str, Any]:
    if not _sqlite_table_exists(conn, "event_fact_history"):
        return {}
    try:
        cur = conn.cursor()
        cur.execute(
            """
            SELECT id, fact_as_of, fact_json
            FROM event_fact_history
            WHERE slug = ?
              AND event_date = ?
              AND fact_as_of >= ?
              AND fact_as_of < ?
            ORDER BY fact_as_of DESC, id DESC
            LIMIT ?
            """,
            (slug, event_date, start_ts, end_ts, int(FIRST_PREDICTION_HIT_RATE_ROWS_PER_LEAD)),
        )
        rows = cur.fetchall()
    except sqlite3.Error:
        return {}
    for row in rows:
        fact = safe_json_loads(row["fact_json"])
        if not isinstance(fact, dict):
            continue
        if not _first_prediction_text_matches_chengdu(slug, fact):
            continue
        distribution = normalize_distribution_rows(fact.get("distribution") or fact.get("rows") or [])
        if not distribution:
            continue
        settlement_actual = to_float(fact.get("settlement_actual"))
        if settlement_actual is None:
            settlement_actual = to_float(settlement_meta.get("settlement_actual"))
        if settlement_actual is None:
            continue
        fact_as_of = str(row["fact_as_of"] or "")
        run_like = {
            "slug": slug,
            "event_date": event_date,
            "created_at": fact_as_of,
            "fact_as_of": fact_as_of,
            "rounding_rule": str(fact.get("rounding_rule") or ""),
            "market_var": str(fact.get("market_var") or ""),
            "market_unit": str(fact.get("market_unit") or ""),
            "event_end_utc": str(fact.get("event_end_utc") or ""),
            "market_closed": int(fact.get("market_closed") or 0),
            "settlement_actual": settlement_actual,
            "settlement_known_at": str(settlement_meta.get("settlement_known_at") or ""),
        }
        if not _is_pre_settlement_prediction_row(run_like):
            continue
        if not actual_bucket_label(run_like, distribution):
            continue
        return {"id": int(row["id"] or 0), "fact_as_of": fact_as_of}
    return {}


def _sanitize_lead_day_materialized_item(
    item: Dict[str, Any],
    *,
    lead_key: str,
    window_start: str,
    window_end: str,
) -> Dict[str, Any]:
    sanitized = dict(item)
    sanitized.pop("settlement_actual", None)
    sanitized.pop("settlement_known_at", None)
    sanitized.pop("settlement_source", None)
    sanitized["market_closed"] = 0
    features = sanitized.get("weather_likelihood_features")
    if isinstance(features, Mapping):
        features_next = dict(features)
        for key in (
            "settlement_actual",
            "settlement_actual_c",
            "settlement_known_at",
            "settlement_actual_source",
            "hard_source_settlement_final",
            "market_closed",
        ):
            features_next.pop(key, None)
        sanitized["weather_likelihood_features"] = features_next
    provenance = dict(sanitized.get("fact_provenance") or {})
    provenance["historical_lead_day_materialization"] = {
        "source": "model_snapshots+market_snapshots/event_market_ticks",
        "lead_day": lead_key,
        "window_start": window_start,
        "window_end": window_end,
        "history_only": True,
        "updates_event_fact_latest": False,
        "range_collapse": False,
    }
    sanitized["fact_provenance"] = provenance
    return sanitized


def materialize_first_prediction_lead_day_facts(
    conn: sqlite3.Connection,
    *,
    start_date: str,
    end_date: str,
    scope: str = "chengdu_zuuu",
    lead_days: Iterable[str] = PREDICTION_LEAD_DAY_KEYS,
    apply: bool = False,
    limit: int = 0,
) -> Dict[str, Any]:
    start_key = _normalize_date_key(start_date)
    end_key = _normalize_date_key(end_date)
    lead_keys = _normalize_lead_day_keys(tuple(lead_days))
    if not start_key or not end_key:
        return {"ok": False, "error": "bad_date", "dry_run": not bool(apply)}
    if start_key > end_key:
        start_key, end_key = end_key, start_key
    settlement_meta = _load_lead_day_materialization_settlement_meta_map(
        conn,
        start_key,
        end_key,
        scope=scope,
    )
    stats: Dict[str, Any] = {
        "settled_events": len(settlement_meta),
        "existing_usable": 0,
        "would_insert": 0,
        "inserted": 0,
        "skipped": 0,
        "skipped_reasons": {},
        "by_lead_day": {
            lead_key: {
                "existing_usable": 0,
                "would_insert": 0,
                "inserted": 0,
                "skipped": 0,
                "skipped_reasons": {},
            }
            for lead_key in lead_keys
        },
    }
    samples: List[Dict[str, Any]] = []
    max_actions = max(0, int(limit or 0))
    processed_actions = 0

    def _record_skip(lead_key: str, reason: str, sample: Optional[Dict[str, Any]] = None) -> None:
        stats["skipped"] = int(stats.get("skipped") or 0) + 1
        skipped = stats.setdefault("skipped_reasons", {})
        skipped[reason] = int(skipped.get(reason) or 0) + 1
        lead_stats = stats["by_lead_day"].setdefault(lead_key, {})
        lead_stats["skipped"] = int(lead_stats.get("skipped") or 0) + 1
        lead_skipped = lead_stats.setdefault("skipped_reasons", {})
        lead_skipped[reason] = int(lead_skipped.get(reason) or 0) + 1
        if sample is not None and len(samples) < 30:
            sample["reason"] = reason
            samples.append(sample)

    trade_map = query_edge_trades(conn)
    fills_map = query_trade_fills(conn)
    auto_orders_map = query_auto_orders(conn)
    try:
        platt_days = int(os.environ.get("PM_Q_PLATT_DAYS", "60"))
    except (TypeError, ValueError):
        platt_days = 60
    platt = _load_platt_calibration(platt_days or 0)

    if apply:
        ensure_fact_tables(conn)

    for (slug, event_date), meta in sorted(settlement_meta.items(), key=lambda item: (item[0][1], item[0][0])):
        if not _fact_write_allowed_for_chengdu_zuuu(slug, {"event_date": event_date, "title": slug, "station_id": "ZUUU"}):
            for lead_key in lead_keys:
                _record_skip(lead_key, "write_scope_blocked", {"slug": slug, "event_date": event_date, "lead_day": lead_key})
            continue
        for lead_key in lead_keys:
            if max_actions and processed_actions >= max_actions:
                _record_skip(lead_key, "limit_reached", {"slug": slug, "event_date": event_date, "lead_day": lead_key})
                continue
            window_start, window_end = _lead_day_window_for_materialization(
                event_date,
                lead_key,
                str(meta.get("settlement_known_at") or ""),
                str(meta.get("event_end_utc") or ""),
            )
            if not window_start or not window_end:
                _record_skip(lead_key, "bad_lead_day_window", {"slug": slug, "event_date": event_date, "lead_day": lead_key})
                continue
            existing = _lead_day_existing_usable_fact(conn, slug, event_date, window_start, window_end, meta)
            if existing:
                stats["existing_usable"] = int(stats.get("existing_usable") or 0) + 1
                lead_stats = stats["by_lead_day"][lead_key]
                lead_stats["existing_usable"] = int(lead_stats.get("existing_usable") or 0) + 1
                if len(samples) < 30:
                    samples.append(
                        {
                            "action": "existing_usable",
                            "slug": slug,
                            "event_date": event_date,
                            "lead_day": lead_key,
                            "fact_id": existing.get("id"),
                            "fact_as_of": existing.get("fact_as_of"),
                        }
                    )
                continue
            run_date_key = _lead_day_run_date_key(event_date, lead_key)
            if not run_date_key:
                _record_skip(lead_key, "bad_run_date", {"slug": slug, "event_date": event_date, "lead_day": lead_key})
                continue
            availability = _lead_day_snapshot_availability(conn, slug, event_date, window_start, window_end)
            composed = _compose_fact_from_snapshots(
                conn,
                run_date_key,
                slug,
                event_date,
                trade_map,
                fills_map,
                auto_orders_map,
                {},
                platt=platt,
                snapshot_created_at_min=window_start,
                snapshot_created_at_max=window_end,
                allow_event_run_model_candidate=False,
                allow_latest_fact_overlay=False,
                allow_settlement_status_overlay=False,
            )
            if not composed:
                _record_skip(
                    lead_key,
                    "compose_missing_model_market_or_sync",
                    {
                        "slug": slug,
                        "event_date": event_date,
                        "lead_day": lead_key,
                        "window_start": window_start,
                        "window_end": window_end,
                        **availability,
                    },
                )
                continue
            item, run_payload, as_of = composed
            if _prediction_lead_day_key(as_of, event_date) != lead_key:
                _record_skip(
                    lead_key,
                    "composed_as_of_outside_lead_day",
                    {"slug": slug, "event_date": event_date, "lead_day": lead_key, "as_of": as_of},
                )
                continue
            item = _sanitize_lead_day_materialized_item(
                item,
                lead_key=lead_key,
                window_start=window_start,
                window_end=window_end,
            )
            distribution = normalize_distribution_rows(item.get("distribution") or item.get("rows") or [])
            if not distribution:
                _record_skip(
                    lead_key,
                    "missing_distribution",
                    {"slug": slug, "event_date": event_date, "lead_day": lead_key, "as_of": as_of},
                )
                continue
            run_like = {
                "slug": slug,
                "event_date": event_date,
                "run_date": run_date_key,
                "created_at": as_of,
                "fact_as_of": as_of,
                "rounding_rule": str(item.get("rounding_rule") or ""),
                "market_var": str(item.get("market_var") or ""),
                "market_unit": str(item.get("market_unit") or ""),
                "event_end_utc": str(item.get("event_end_utc") or ""),
                "market_closed": 0,
                "settlement_actual": to_float(meta.get("settlement_actual")),
                "settlement_known_at": str(meta.get("settlement_known_at") or ""),
                "settlement_source": str(meta.get("settlement_source") or ""),
            }
            if not _is_pre_settlement_prediction_row(run_like):
                _record_skip(
                    lead_key,
                    "not_pre_settlement",
                    {"slug": slug, "event_date": event_date, "lead_day": lead_key, "as_of": as_of},
                )
                continue
            if not actual_bucket_label(run_like, distribution):
                _record_skip(
                    lead_key,
                    "missing_actual_label",
                    {"slug": slug, "event_date": event_date, "lead_day": lead_key, "as_of": as_of},
                )
                continue
            stats["would_insert"] = int(stats.get("would_insert") or 0) + 1
            lead_stats = stats["by_lead_day"][lead_key]
            lead_stats["would_insert"] = int(lead_stats.get("would_insert") or 0) + 1
            processed_actions += 1
            sample = {
                "action": "insert" if apply else "would_insert",
                "slug": slug,
                "event_date": event_date,
                "lead_day": lead_key,
                "run_date": run_date_key,
                "fact_as_of": as_of,
                "model_snapshot_id": (run_payload.get("score_composer") or {}).get("model_snapshot_id")
                if isinstance(run_payload, Mapping)
                else None,
                "market_snapshot_id": (run_payload.get("score_composer") or {}).get("market_snapshot_id")
                if isinstance(run_payload, Mapping)
                else None,
                "market_source": (run_payload.get("score_composer") or {}).get("market_source")
                if isinstance(run_payload, Mapping)
                else "",
            }
            if apply:
                score_meta = run_payload.get("score_composer") if isinstance(run_payload, Mapping) else {}
                fact_id = _insert_event_fact_history(
                    conn,
                    run_date=run_date_key,
                    slug=slug,
                    event_date=event_date,
                    fact_as_of=as_of,
                    model_snapshot_id=_to_int(score_meta.get("model_snapshot_id")) if isinstance(score_meta, Mapping) else None,
                    market_snapshot_id=_to_int(score_meta.get("market_snapshot_id")) if isinstance(score_meta, Mapping) else None,
                    composer_version=FACTS_COMPOSER_VERSION,
                    item=item,
                    write_latest=False,
                )
                stats["inserted"] = int(stats.get("inserted") or 0) + 1
                lead_stats["inserted"] = int(lead_stats.get("inserted") or 0) + 1
                sample["fact_id"] = fact_id
            if len(samples) < 30:
                samples.append(sample)
    if apply and int(stats.get("inserted") or 0) > 0:
        conn.commit()
    return {
        "ok": True,
        "dry_run": not bool(apply),
        "write_policy": "history_only_event_fact_history_append_no_latest_update",
        "source_policy": "per_lead_day_local_window_no_range_collapse",
        "scope": scope,
        "start_date": start_key,
        "end_date": end_key,
        "lead_days": list(lead_keys),
        "generated_at": now_text(),
        "stats": stats,
        "samples": samples,
    }


def _facts_exist_for_run_date(conn: sqlite3.Connection, run_date: str) -> bool:
    run_key = _normalize_date_key(run_date)
    if not run_key:
        return False
    cur = conn.cursor()
    cur.execute("SELECT 1 FROM event_fact_history WHERE run_date = ? LIMIT 1", (run_key,))
    return cur.fetchone() is not None


def _facts_exist_for_run_date_range(conn: sqlite3.Connection, start_date: str, end_date: str) -> bool:
    start_key = _normalize_date_key(start_date)
    end_key = _normalize_date_key(end_date)
    if not start_key or not end_key:
        return False
    cur = conn.cursor()
    cur.execute(
        "SELECT 1 FROM event_fact_history WHERE run_date >= ? AND run_date <= ? LIMIT 1",
        (start_key, end_key),
    )
    return cur.fetchone() is not None


def _backfill_facts_from_event_run_rows(conn: sqlite3.Connection, rows: List[sqlite3.Row]) -> None:
    if not rows:
        return
    trade_map = query_edge_trades(conn)
    fills_map = query_trade_fills(conn)
    auto_orders_map = query_auto_orders(conn)
    market_tick_latest_map = query_market_tick_latest_for_keys(
        conn,
        [(row["slug"], row["event_date"]) for row in rows],
    )
    try:
        platt_days = int(os.environ.get("PM_Q_PLATT_DAYS", "60"))
    except (TypeError, ValueError):
        platt_days = 60
    platt = _load_platt_calibration(platt_days or 0)
    for row in rows:
        item = build_run_item(
            conn,
            row,
            trade_map,
            fills_map,
            auto_orders_map,
            market_tick_latest_map,
            platt=platt,
        )
        run_payload = safe_json_loads(row["payload_json"])
        _attach_fact_provenance_from_run_payload(item, run_payload)
        upsert_event_fact_from_run_item(
            conn,
            run_date=str(row["run_date"] or ""),
            slug=str(row["slug"] or ""),
            event_date=str(row["event_date"] or ""),
            run_created_at=str(row["created_at"] or ""),
            run_payload=run_payload,
            item=item,
        )


def _backfill_facts_if_needed(
    conn: sqlite3.Connection,
    date_key: str,
    include_history: bool,
    start_date_key: str = "",
) -> None:
    if not DB_PATH.exists():
        return
    date_key = _normalize_date_key(date_key)
    start_date_key = _normalize_date_key(start_date_key)
    if include_history and start_date_key and not _facts_exist_for_run_date_range(conn, start_date_key, date_key):
        _materialize_facts_from_snapshots_for_range(conn, start_date_key, date_key)
        if _facts_exist_for_run_date_range(conn, start_date_key, date_key):
            return
        rows = select_event_run_rows_range(conn, start_date_key, date_key)
        if rows:
            seen: set[Tuple[str, str]] = set()
            selected: List[sqlite3.Row] = []
            for row in rows:
                slug = str(row["slug"] or "")
                event_date_key = _normalize_date_key(str(row["event_date"] or ""))
                if not slug or not event_date_key:
                    continue
                key = (slug, event_date_key)
                if key in seen:
                    continue
                seen.add(key)
                selected.append(row)
            _backfill_facts_from_event_run_rows(conn, selected)
            try:
                conn.commit()
            except sqlite3.Error:
                pass
        return
    facts_exist = _facts_exist_for_run_date(conn, date_key)
    if not include_history and facts_exist:
        rows = select_event_run_rows(conn, date_key, include_history=False)
        if rows:
            _backfill_facts_from_event_run_rows(conn, rows)
            try:
                conn.commit()
            except sqlite3.Error:
                pass
        return
    if not facts_exist:
        _materialize_facts_from_snapshots_for_run_date(conn, date_key)
        facts_exist = _facts_exist_for_run_date(conn, date_key)
        if facts_exist and not include_history:
            rows = select_event_run_rows(conn, date_key, include_history=False)
            if rows:
                _backfill_facts_from_event_run_rows(conn, rows)
                try:
                    conn.commit()
                except sqlite3.Error:
                    pass
            return
    if include_history:
        rows = select_event_run_rows(conn, date_key, include_history=True)
    else:
        rows = select_event_run_rows(conn, date_key, include_history=False)
    if not rows:
        return
    _backfill_facts_from_event_run_rows(conn, rows)
    try:
        conn.commit()
    except sqlite3.Error:
        pass


def select_event_fact_rows(conn: sqlite3.Connection, date_key: str, include_history: bool) -> List[sqlite3.Row]:
    date_key = _normalize_date_key(date_key)
    if not date_key:
        return []
    if not include_history:
        return select_event_fact_rows_latest(conn, date_key)
    cur = conn.cursor()
    if include_history:
        cur.execute(
            """
            SELECT *
            FROM event_fact_history
            WHERE run_date <= ?
            ORDER BY run_date DESC, fact_as_of DESC, id DESC
            """,
            (date_key,),
        )
    rows = cur.fetchall()
    if not rows:
        return []
    if not include_history:
        seen: set[Tuple[str, str]] = set()
        out: List[sqlite3.Row] = []
        for row in rows:
            slug = str(row["slug"] or "")
            event_date_key = _normalize_date_key(str(row["event_date"] or ""))
            if not slug or not event_date_key:
                continue
            key = (slug, event_date_key)
            if key in seen:
                continue
            seen.add(key)
            out.append(row)
        return out
    best_rows: Dict[Tuple[str, str], sqlite3.Row] = {}
    fallback_rows: Dict[Tuple[str, str], sqlite3.Row] = {}
    for row in rows:
        slug = str(row["slug"] or "")
        event_date_key = _normalize_date_key(str(row["event_date"] or ""))
        if not slug or not event_date_key:
            continue
        key = (slug, event_date_key)
        run_date = _normalize_date_key(str(row["run_date"] or ""))
        fact_as_of = str(row["fact_as_of"] or "")
        prev_fallback = fallback_rows.get(key)
        if not prev_fallback or (run_date, fact_as_of) > (
            _normalize_date_key(str(prev_fallback["run_date"] or "")),
            str(prev_fallback["fact_as_of"] or ""),
        ):
            fallback_rows[key] = row
        cutoff = date_key
        if date_key and event_date_key and event_date_key < date_key:
            cutoff = event_date_key
        if cutoff and run_date and run_date > cutoff:
            continue
        prev_best = best_rows.get(key)
        if not prev_best or (run_date, fact_as_of) > (
            _normalize_date_key(str(prev_best["run_date"] or "")),
            str(prev_best["fact_as_of"] or ""),
        ):
            best_rows[key] = row
    out: List[sqlite3.Row] = []
    for key, fallback in fallback_rows.items():
        out.append(best_rows.get(key) or fallback)
    return out


def select_event_fact_rows_latest(conn: sqlite3.Connection, date_key: str) -> List[sqlite3.Row]:
    date_key = _normalize_date_key(date_key)
    if not date_key:
        return []
    cur = conn.cursor()
    try:
        cur.execute(
            """
            SELECT h.id, h.slug, h.event_date, h.run_date, h.fact_as_of, h.model_snapshot_id, h.market_snapshot_id, h.fact_json
            FROM event_fact_latest l
            JOIN event_fact_history h ON h.id = l.fact_id
            WHERE (h.run_date = ? AND h.event_date >= ?) OR h.event_date = ?
            ORDER BY h.event_date ASC, h.fact_as_of DESC, h.id DESC
            """,
            (date_key, date_key, date_key),
        )
        rows = cur.fetchall()
        if rows:
            return _filter_fact_rows_matching_slug_date(rows or [])
    except sqlite3.OperationalError:
        pass
    try:
        cur.execute(
            """
            WITH ranked AS (
                SELECT
                    id, slug, event_date, run_date, fact_as_of, model_snapshot_id, market_snapshot_id, fact_json,
                    ROW_NUMBER() OVER (
                        PARTITION BY slug, event_date
                        ORDER BY fact_as_of DESC, id DESC
                    ) AS rn
                FROM event_fact_history
                WHERE (run_date = ? AND event_date >= ?) OR event_date = ?
            )
            SELECT id, slug, event_date, run_date, fact_as_of, model_snapshot_id, market_snapshot_id, fact_json
            FROM ranked
            WHERE rn = 1
            ORDER BY event_date ASC, fact_as_of DESC, id DESC
            """,
            (date_key, date_key, date_key),
        )
    except sqlite3.OperationalError:
        return []
    rows = cur.fetchall()
    return _filter_fact_rows_matching_slug_date(rows or [])


def _date_key_offset(date_key: str, days: int) -> str:
    parsed = parse_date(_normalize_date_key(date_key))
    if not parsed:
        return ""
    return (parsed + timedelta(days=int(days or 0))).isoformat()


def _is_chengdu_market_identifier(slug: str, title: str = "") -> bool:
    text = f"{slug or ''} {title or ''}".lower()
    return "-in-chengdu-" in text or " chengdu " in f" {text} "


def _fact_row_is_chengdu_market(row: sqlite3.Row) -> bool:
    slug = str(row["slug"] or "")
    if _is_chengdu_market_identifier(slug):
        return True
    try:
        payload = json.loads(str(row["fact_json"] or "{}"))
    except Exception:
        payload = {}
    title = str(payload.get("title") or "") if isinstance(payload, Mapping) else ""
    return _is_chengdu_market_identifier(slug, title)


def _filter_future_fact_rows_to_chengdu(rows: Iterable[sqlite3.Row], date_key: str) -> List[sqlite3.Row]:
    base_key = _normalize_date_key(date_key)
    out: List[sqlite3.Row] = []
    for row in rows or []:
        event_date = _normalize_date_key(str(row["event_date"] or ""))
        if base_key and event_date > base_key and not _fact_row_is_chengdu_market(row):
            continue
        out.append(row)
    return out


def _ui_upcoming_days(default: int = 2) -> int:
    raw = os.environ.get("PM_UI_UPCOMING_DAYS")
    if raw is None:
        raw = os.environ.get("PM_UI_SNAPSHOT_UPCOMING_DAYS")
    try:
        value = int(float(str(raw if raw is not None else default).strip()))
    except (TypeError, ValueError):
        value = int(default)
    return max(0, min(7, int(value)))


def select_event_fact_rows_latest_with_upcoming(
    conn: sqlite3.Connection,
    date_key: str,
    *,
    upcoming_days: int = 2,
) -> List[sqlite3.Row]:
    date_key = _normalize_date_key(date_key)
    end_key = _date_key_offset(date_key, max(0, upcoming_days))
    if not date_key or not end_key:
        return select_event_fact_rows_latest(conn, date_key)
    cur = conn.cursor()
    try:
        cur.execute(
            """
            WITH ranked AS (
                SELECT
                    h.id, h.slug, h.event_date, h.run_date, h.fact_as_of, h.model_snapshot_id, h.market_snapshot_id, h.fact_json,
                    ROW_NUMBER() OVER (
                        PARTITION BY h.slug, h.event_date
                        ORDER BY h.fact_as_of DESC, h.id DESC
                    ) AS rn
                FROM event_fact_latest l
                JOIN event_fact_history h ON h.id = l.fact_id
                WHERE (h.run_date = ? AND h.event_date >= ?)
                   OR l.event_date = ?
                   OR (l.event_date > ? AND l.event_date <= ?)
            )
            SELECT id, slug, event_date, run_date, fact_as_of, model_snapshot_id, market_snapshot_id, fact_json
            FROM ranked
            WHERE rn = 1
            ORDER BY
                CASE
                    WHEN event_date = ? THEN 0
                    WHEN event_date > ? THEN 1
                    ELSE 2
                END,
                event_date ASC,
                fact_as_of DESC,
                id DESC
            """,
            (date_key, date_key, date_key, date_key, end_key, date_key, date_key),
        )
        rows = cur.fetchall()
        if rows:
            return _filter_future_fact_rows_to_chengdu(
                _filter_fact_rows_matching_slug_date(rows),
                date_key,
            )
    except sqlite3.OperationalError:
        pass
    rows = select_event_fact_rows_latest(conn, date_key)
    existing = {
        (str(row["slug"] or ""), _normalize_date_key(str(row["event_date"] or "")))
        for row in rows or []
    }
    try:
        cur.execute(
            """
            SELECT h.id, h.slug, h.event_date, h.run_date, h.fact_as_of, h.model_snapshot_id, h.market_snapshot_id, h.fact_json
            FROM event_fact_latest l
            JOIN event_fact_history h ON h.id = l.fact_id
            WHERE l.event_date > ? AND l.event_date <= ?
            ORDER BY l.event_date ASC, h.fact_as_of DESC, h.id DESC
            """,
            (date_key, end_key),
        )
        for row in _filter_future_fact_rows_to_chengdu(
            _filter_fact_rows_matching_slug_date(cur.fetchall()),
            date_key,
        ):
            key = (str(row["slug"] or ""), _normalize_date_key(str(row["event_date"] or "")))
            if key and key not in existing:
                rows.append(row)
                existing.add(key)
    except sqlite3.OperationalError:
        pass
    return rows


def select_event_fact_rows_paged(
    conn: sqlite3.Connection,
    date_key: str,
    page: int,
    page_size: int,
    *,
    include_upcoming: bool = False,
    upcoming_days: int = 2,
) -> List[sqlite3.Row]:
    date_key = _normalize_date_key(date_key)
    if not date_key:
        return []
    page = max(1, int(page or 1))
    page_size = max(1, min(int(page_size or 1), 200))
    offset = (page - 1) * page_size
    cur = conn.cursor()
    if include_upcoming:
        rows = select_event_fact_rows_latest_with_upcoming(conn, date_key, upcoming_days=upcoming_days)
        return rows[offset : offset + page_size]
    try:
        cur.execute(
            """
            SELECT h.id, h.slug, h.event_date, h.run_date, h.fact_as_of, h.model_snapshot_id, h.market_snapshot_id, h.fact_json
            FROM event_fact_latest l
            JOIN event_fact_history h ON h.id = l.fact_id
            WHERE h.run_date = ? OR l.event_date = ?
            ORDER BY h.event_date ASC, h.fact_as_of DESC, h.id DESC
            LIMIT ? OFFSET ?
            """,
            (date_key, date_key, page_size, offset),
        )
        rows = cur.fetchall()
        if rows:
            return _filter_fact_rows_matching_slug_date(rows)
    except sqlite3.OperationalError:
        pass
    try:
        cur.execute(
            """
            SELECT h.id, h.slug, h.event_date, h.run_date, h.fact_as_of, h.model_snapshot_id, h.market_snapshot_id, h.fact_json
            FROM event_fact_latest l
            JOIN event_fact_history h ON h.id = l.fact_id
            WHERE l.event_date = ?
            ORDER BY h.fact_as_of DESC, h.id DESC
            LIMIT ? OFFSET ?
            """,
            (date_key, page_size, offset),
        )
        rows = cur.fetchall()
        if rows:
            return _filter_fact_rows_matching_slug_date(rows)
    except sqlite3.OperationalError:
        pass
    try:
        cur.execute(
            """
            WITH ranked AS (
                SELECT
                    id, slug, event_date, run_date, fact_as_of, model_snapshot_id, market_snapshot_id, fact_json,
                    ROW_NUMBER() OVER (
                        PARTITION BY slug, event_date
                        ORDER BY fact_as_of DESC, id DESC
                    ) AS rn
                FROM event_fact_history
                WHERE run_date = ?
            )
            SELECT id, slug, event_date, run_date, fact_as_of, model_snapshot_id, market_snapshot_id, fact_json
            FROM ranked
            WHERE rn = 1
            ORDER BY fact_as_of DESC, id DESC
            LIMIT ? OFFSET ?
            """,
            (date_key, page_size, offset),
        )
        return _filter_fact_rows_matching_slug_date(cur.fetchall())
    except sqlite3.OperationalError:
        # Fallback for older SQLite builds without window functions.
        rows = select_event_fact_rows(conn, date_key, include_history=False)
        if not rows:
            return []
        return _filter_fact_rows_matching_slug_date(rows)[offset : offset + page_size]


def _filter_future_summary_rows_to_chengdu(rows: Iterable[sqlite3.Row], date_key: str) -> List[sqlite3.Row]:
    base_key = _normalize_date_key(date_key)
    out: List[sqlite3.Row] = []
    for row in rows or []:
        try:
            event_date = _normalize_date_key(str(row["event_date"] or ""))
            slug = str(row["slug"] or "")
        except Exception:
            out.append(row)
            continue
        if base_key and event_date > base_key and not _is_chengdu_market_identifier(slug):
            continue
        out.append(row)
    return out


def select_event_fact_summary_cache_rows_paged(
    conn: sqlite3.Connection,
    date_key: str,
    page: int,
    page_size: int,
    *,
    include_upcoming: bool = False,
    upcoming_days: int = 2,
) -> List[sqlite3.Row]:
    date_key = _normalize_date_key(date_key)
    if not date_key:
        return []
    page = max(1, int(page or 1))
    page_size = max(1, min(int(page_size or 1), 200))
    offset = (page - 1) * page_size
    end_key = _date_key_offset(date_key, max(0, upcoming_days)) if include_upcoming else ""
    cur = conn.cursor()
    select_cols = """
        h.id, h.slug, h.event_date, h.run_date, h.fact_as_of,
        h.model_snapshot_id, h.market_snapshot_id,
        h.market_updated_at, h.market_stale_sec, h.model_cache_age_sec,
        h.best_side, h.best_outcome, h.best_edge_score, h.best_signal_edge_entry,
        c.summary_json
    """
    try:
        if include_upcoming and end_key:
            cur.execute(
                f"""
                WITH ranked AS (
                    SELECT
                        {select_cols},
                        ROW_NUMBER() OVER (
                            PARTITION BY h.slug, h.event_date
                            ORDER BY h.fact_as_of DESC, h.id DESC
                        ) AS rn
                    FROM event_fact_latest l
                    JOIN event_fact_history h ON h.id = l.fact_id
                    LEFT JOIN event_fact_summary_cache c ON c.fact_id = h.id
                    WHERE (h.run_date = ? AND h.event_date >= ?)
                       OR l.event_date = ?
                       OR (l.event_date > ? AND l.event_date <= ?)
                )
                SELECT
                    id, slug, event_date, run_date, fact_as_of,
                    model_snapshot_id, market_snapshot_id,
                    market_updated_at, market_stale_sec, model_cache_age_sec,
                    best_side, best_outcome, best_edge_score, best_signal_edge_entry,
                    summary_json
                FROM ranked
                WHERE rn = 1
                ORDER BY
                    CASE
                        WHEN event_date = ? THEN 0
                        WHEN event_date > ? THEN 1
                        ELSE 2
                    END,
                    event_date ASC,
                    fact_as_of DESC,
                    id DESC
                LIMIT ? OFFSET ?
                """,
                (date_key, date_key, date_key, date_key, end_key, date_key, date_key, page_size, offset),
            )
            return _filter_future_summary_rows_to_chengdu(
                _filter_fact_rows_matching_slug_date(cur.fetchall()),
                date_key,
            )
        cur.execute(
            f"""
            SELECT {select_cols}
            FROM event_fact_latest l
            JOIN event_fact_history h ON h.id = l.fact_id
            LEFT JOIN event_fact_summary_cache c ON c.fact_id = h.id
            WHERE h.run_date = ? OR l.event_date = ?
            ORDER BY h.event_date ASC, h.fact_as_of DESC, h.id DESC
            LIMIT ? OFFSET ?
            """,
            (date_key, date_key, page_size, offset),
        )
        rows = cur.fetchall()
        if rows:
            return _filter_fact_rows_matching_slug_date(rows)
    except sqlite3.OperationalError:
        return []
    return []


def select_chengdu_event_fact_summary_cache_rows_paged(
    conn: sqlite3.Connection,
    date_key: str,
    page_size: int,
    *,
    upcoming_days: int = 2,
) -> List[sqlite3.Row]:
    date_key = _normalize_date_key(date_key)
    if not date_key:
        return []
    page_size = max(1, min(int(page_size or 1), 80))
    end_key = _date_key_offset(date_key, max(0, upcoming_days)) or date_key
    cur = conn.cursor()
    select_cols = """
        h.id, h.slug, h.event_date, h.run_date, h.fact_as_of,
        h.model_snapshot_id, h.market_snapshot_id,
        h.market_updated_at, h.market_stale_sec, h.model_cache_age_sec,
        h.best_side, h.best_outcome, h.best_edge_score, h.best_signal_edge_entry,
        c.summary_json
    """
    try:
        cur.execute(
            f"""
            SELECT {select_cols}
            FROM event_fact_latest l
            JOIN event_fact_history h ON h.id = l.fact_id
            LEFT JOIN event_fact_summary_cache c ON c.fact_id = h.id
            WHERE l.event_date >= ?
              AND l.event_date <= ?
              AND (
                lower(l.slug) LIKE '%chengdu%'
                OR lower(h.slug) LIKE '%chengdu%'
              )
            ORDER BY
                CASE
                    WHEN l.event_date = ? THEN 0
                    WHEN l.event_date > ? THEN 1
                    ELSE 2
                END,
                l.event_date ASC,
                h.fact_as_of DESC,
                h.id DESC
            LIMIT ?
            """,
            (date_key, end_key, date_key, date_key, page_size),
        )
        return _filter_fact_rows_matching_slug_date(cur.fetchall())
    except sqlite3.OperationalError:
        return []


def count_event_fact_rows(conn: sqlite3.Connection, date_key: str, *, include_upcoming: bool = False, upcoming_days: int = 2) -> int:
    date_key = _normalize_date_key(date_key)
    if not date_key:
        return 0
    if include_upcoming:
        fact_rows = select_event_fact_rows_latest_with_upcoming(conn, date_key, upcoming_days=upcoming_days)
        existing = {
            (str(row["slug"] or ""), _normalize_date_key(str(row["event_date"] or "")))
            for row in fact_rows or []
        }
        return len(fact_rows) + _count_discovery_placeholder_events(
            conn,
            date_key,
            upcoming_days=upcoming_days,
            exclude_keys=existing,
        )
    cur = conn.cursor()
    def _count_rows(rows: Iterable[sqlite3.Row]) -> int:
        keys: Set[Tuple[str, str]] = set()
        for row in rows or []:
            slug = str(row["slug"] or "")
            event_date = _normalize_date_key(str(row["event_date"] or ""))
            if slug and event_date and _event_date_matches_slug(slug, event_date):
                keys.add((slug, event_date))
        return len(keys)
    try:
        cur.execute(
            """
            SELECT h.slug, h.event_date
            FROM event_fact_latest l
            JOIN event_fact_history h ON h.id = l.fact_id
            WHERE h.run_date = ? OR l.event_date = ?
            """,
            (date_key, date_key),
        )
        count = _count_rows(cur.fetchall())
        if count > 0:
            return count
    except sqlite3.OperationalError:
        pass
    try:
        cur.execute(
            """
            SELECT slug, event_date
            FROM event_fact_latest l
            WHERE l.event_date = ?
            """,
            (date_key,),
        )
        count = _count_rows(cur.fetchall())
        if count > 0:
            return count
    except sqlite3.OperationalError:
        pass
    try:
        cur.execute(
            """
            SELECT COUNT(*)
            FROM (
                SELECT 1
                FROM event_fact_history
                WHERE run_date = ?
                GROUP BY slug, event_date
            ) AS t
            """,
            (date_key,),
        )
        row = cur.fetchone()
        raw_count = int(row[0] or 0) if row else 0
        if raw_count <= 0:
            return 0
        rows = select_event_fact_rows(conn, date_key, include_history=False)
        return len(rows)
    except sqlite3.OperationalError:
        rows = select_event_fact_rows(conn, date_key, include_history=False)
        return len(rows)


def _market_var_for_discovery_placeholder(title: str, slug: str) -> str:
    text = f"{title} {slug}".lower()
    if "temperature" in text:
        return "temperature_2m_max"
    if "rain" in text or "precip" in text:
        return "precipitation_sum"
    if "snow" in text:
        return "snowfall_sum"
    if "wind" in text:
        return "wind_speed_10m_max"
    return ""


def _market_unit_for_discovery_placeholder(market_var: str) -> str:
    if market_var == "temperature_2m_max":
        return "C"
    if market_var in {"precipitation_sum", "snowfall_sum"}:
        return "mm"
    if market_var == "wind_speed_10m_max":
        return "kmh"
    return ""


def _discovery_placeholder_candidate_rows(
    conn: sqlite3.Connection,
    date_key: str,
    *,
    upcoming_days: int,
    exclude_keys: Set[Tuple[str, str]],
    limit: int,
) -> List[sqlite3.Row]:
    date_key = _normalize_date_key(date_key)
    end_key = _date_key_offset(date_key, max(0, int(upcoming_days or 0)))
    if not date_key or not end_key or limit <= 0:
        return []
    if not _sqlite_table_exists(conn, "weather_market_discovery"):
        return []
    cur = conn.cursor()
    has_market_tokens = _sqlite_table_exists(conn, "market_tokens")
    try:
        if has_market_tokens:
            cur.execute(
                """
                WITH token_latest AS (
                  SELECT
                    slug,
                    event_date,
                    COUNT(*) AS token_count,
                    MAX(updated_at) AS token_updated_at,
                    SUM(CASE
                          WHEN COALESCE(market_closed, 0) = 0
                           AND COALESCE(market_archived, 0) = 0
                           AND COALESCE(market_active, 1) != 0
                          THEN 1 ELSE 0
                        END) AS active_token_count
                  FROM market_tokens
                  WHERE event_date >= ? AND event_date <= ?
                  GROUP BY slug, event_date
                )
                SELECT
                  wd.slug,
                  wd.event_date,
                  wd.title,
                  wd.market_open_at,
                  wd.first_seen_at,
                  wd.first_tokenized_at,
                  COALESCE(NULLIF(wd.token_count, 0), tl.token_count, 0) AS token_count,
                  wd.status,
                  wd.details_json,
                  wd.updated_at,
                  COALESCE(tl.active_token_count, wd.token_count, 0) AS active_token_count,
                  tl.token_updated_at
                FROM weather_market_discovery wd
                LEFT JOIN token_latest tl
                  ON tl.slug = wd.slug AND tl.event_date = wd.event_date
                WHERE wd.event_date >= ? AND wd.event_date <= ?
                  AND (
                    LOWER(COALESCE(wd.slug, '')) LIKE '%-in-chengdu-%'
                    OR LOWER(COALESCE(wd.title, '')) LIKE '%chengdu%'
                  )
                  AND COALESCE(NULLIF(wd.token_count, 0), tl.token_count, 0) >= 2
                  AND COALESCE(tl.active_token_count, wd.token_count, 0) > 0
                  AND COALESCE(wd.status, '') IN ('tokenized', 'known_recent')
                ORDER BY
                  wd.event_date ASC,
                  COALESCE(wd.first_tokenized_at, wd.first_seen_at, wd.updated_at, tl.token_updated_at) DESC,
                  wd.updated_at DESC
                LIMIT ?
                """,
                (date_key, end_key, date_key, end_key, max(1, int(limit) * 4)),
            )
        else:
            cur.execute(
                """
                SELECT
                  wd.slug,
                  wd.event_date,
                  wd.title,
                  wd.market_open_at,
                  wd.first_seen_at,
                  wd.first_tokenized_at,
                  wd.token_count AS token_count,
                  wd.status,
                  wd.details_json,
                  wd.updated_at,
                  wd.token_count AS active_token_count,
                  '' AS token_updated_at
                FROM weather_market_discovery wd
                WHERE wd.event_date >= ? AND wd.event_date <= ?
                  AND (
                    LOWER(COALESCE(wd.slug, '')) LIKE '%-in-chengdu-%'
                    OR LOWER(COALESCE(wd.title, '')) LIKE '%chengdu%'
                  )
                  AND COALESCE(wd.token_count, 0) >= 2
                  AND COALESCE(wd.status, '') IN ('tokenized', 'known_recent')
                ORDER BY
                  wd.event_date ASC,
                  COALESCE(wd.first_tokenized_at, wd.first_seen_at, wd.updated_at) DESC,
                  wd.updated_at DESC
                LIMIT ?
                """,
                (date_key, end_key, max(1, int(limit) * 4)),
            )
    except sqlite3.OperationalError:
        return []
    out: List[sqlite3.Row] = []
    seen: Set[Tuple[str, str]] = set()
    for row in cur.fetchall() or []:
        slug = str(row["slug"] or "").strip()
        title = str(row["title"] or "")
        event_date = _normalize_date_key(str(row["event_date"] or ""))
        if not slug or not event_date:
            continue
        if not _is_chengdu_market_identifier(slug, title):
            continue
        if not _event_date_matches_slug(slug, event_date):
            continue
        key = (slug, event_date)
        if key in exclude_keys or key in seen:
            continue
        seen.add(key)
        out.append(row)
        if len(out) >= limit:
            break
    return out


def _count_discovery_placeholder_events(
    conn: sqlite3.Connection,
    date_key: str,
    *,
    upcoming_days: int,
    exclude_keys: Set[Tuple[str, str]],
) -> int:
    return len(
        _discovery_placeholder_candidate_rows(
            conn,
            date_key,
            upcoming_days=upcoming_days,
            exclude_keys=exclude_keys,
            limit=1000,
        )
    )


def _market_token_rows_for_discovery_placeholder(
    conn: sqlite3.Connection,
    slug: str,
    event_date: str,
) -> List[sqlite3.Row]:
    try:
        cur = conn.cursor()
        cur.execute(
            """
            SELECT outcome, yes_token, no_token, outcome_volume, liquidity,
                   market_active, market_closed, market_archived,
                   market_accepting_orders, market_enable_orderbook, updated_at
            FROM market_tokens
            WHERE slug = ? AND event_date = ?
            ORDER BY outcome ASC
            """,
            (slug, event_date),
        )
        return list(cur.fetchall() or [])
    except sqlite3.OperationalError:
        return []


def _build_discovery_placeholder_payload(
    conn: sqlite3.Connection,
    discovery_row: sqlite3.Row,
    *,
    display_run_date: str,
) -> Dict[str, Any]:
    slug = str(discovery_row["slug"] or "").strip()
    event_date = _normalize_date_key(str(discovery_row["event_date"] or ""))
    title = str(discovery_row["title"] or slug)
    details = safe_json_loads(str(discovery_row["details_json"] or ""))
    if not isinstance(details, dict):
        details = {}
    market_var = _market_var_for_discovery_placeholder(title, slug)
    market_unit = _market_unit_for_discovery_placeholder(market_var)
    token_rows = _market_token_rows_for_discovery_placeholder(conn, slug, event_date)
    distribution: List[Dict[str, Any]] = []
    latest_token_at = ""
    for token_row in token_rows:
        outcome = str(token_row["outcome"] or "").strip()
        if not outcome:
            continue
        token_at = str(token_row["updated_at"] or "")
        if token_at and token_at > latest_token_at:
            latest_token_at = token_at
        item = {
            "outcome": outcome,
            "label": outcome,
            "yes_token": str(token_row["yes_token"] or ""),
            "no_token": str(token_row["no_token"] or ""),
            "outcome_volume": to_float(token_row["outcome_volume"]),
            "liquidity": to_float(token_row["liquidity"]),
            "market_active": token_row["market_active"],
            "market_closed": token_row["market_closed"],
            "market_archived": token_row["market_archived"],
            "market_accepting_orders": token_row["market_accepting_orders"],
            "market_enable_orderbook": token_row["market_enable_orderbook"],
            "market_token_updated_at": token_at,
            "q_bayes_posterior": None,
            "q_raw": None,
            "q_calibrated": None,
            "q_na_reason": "model_not_materialized_yet",
            "edge_tradeability_na_reason": "model_not_materialized_yet",
            "market_discovery_placeholder": True,
        }
        distribution.append(item)
    fact_as_of = (
        str(discovery_row["updated_at"] or "")
        or latest_token_at
        or str(discovery_row["first_tokenized_at"] or "")
        or str(discovery_row["first_seen_at"] or "")
    )
    payload: Dict[str, Any] = {
        "slug": slug,
        "city": "Chengdu",
        "event_date": event_date,
        "run_date": _normalize_date_key(display_run_date) or event_date,
        "event_url": f"https://polymarket.com/event/{slug}",
        "title": title,
        "station_id": "ZUUU" if market_var == "temperature_2m_max" else "",
        "market_open_at": str(discovery_row["market_open_at"] or ""),
        "event_end_utc": str(details.get("endDate") or ""),
        "market_var": market_var,
        "market_unit": market_unit,
        "market_closed": 1 if _truthy(details.get("closed")) else 0,
        "distribution": distribution,
        "rows": distribution,
        "fact_as_of": fact_as_of,
        "created_at": fact_as_of,
        "market_updated_at": latest_token_at or str(discovery_row["updated_at"] or ""),
        "market_source": "market_tokens",
        # This is a published-market read-model placeholder, not a posterior
        # fact.  Keep the two states explicit so the UI cannot imply that an
        # empty distribution is a computed probability.
        "market_state": "published",
        "market_state_label": "市场已发布",
        "posterior_state": "not_materialized",
        "posterior_state_label": "待接入生产后验",
        "posterior_na_reason": "production_posterior_not_materialized",
        "posterior_materialization": {
            "state": "not_materialized",
            "label": "待接入生产后验",
            "source": "production_event_fact_latest",
            "production_consumer_eligible": False,
            "block_reason": "production_posterior_not_materialized",
        },
        "production_consumer_eligible": False,
        "production_consumer_block_reason": "production_posterior_not_materialized",
        "data_status": "market_discovery_pending_model",
        "weather_strategy_mode": "market_discovery_pending_model",
        "weather_strategy_entry_block_reason": "model_not_materialized_yet",
        "mean_bucket_na_reason": "model_not_materialized_yet",
        "market_discovery": {
            "source": "weather_market_discovery",
            "status": str(discovery_row["status"] or ""),
            "first_seen_at": str(discovery_row["first_seen_at"] or ""),
            "first_tokenized_at": str(discovery_row["first_tokenized_at"] or ""),
            "token_count": int(to_float(discovery_row["token_count"]) or len(distribution)),
            "active_token_count": int(to_float(discovery_row["active_token_count"]) or 0),
            "updated_at": str(discovery_row["updated_at"] or ""),
            "token_updated_at": latest_token_at or str(discovery_row["token_updated_at"] or ""),
            "details": details,
        },
        "fact_provenance": {
            "source": "weather_market_discovery",
            "market_discovery_placeholder": True,
            "ui_display_run_date": _normalize_date_key(display_run_date) or "",
            "reason": "market_tokenized_before_model_fact_materialized",
        },
        "auto_trade_ssot": {
            "version": 2,
            "main_candidate": None,
            "main_entry_ok": False,
            "main_entry_reasons": ["model_not_materialized_yet"],
            "model_yes_top_candidate": None,
            "model_yes_top_label": "",
            "model_yes_top_na_reason": "model_not_materialized_yet",
            "computed_at": fact_as_of,
        },
    }
    return payload


def _discovery_placeholder_payloads(
    conn: sqlite3.Connection,
    date_key: str,
    *,
    upcoming_days: int,
    exclude_keys: Set[Tuple[str, str]],
    limit: int,
) -> List[Dict[str, Any]]:
    rows = _discovery_placeholder_candidate_rows(
        conn,
        date_key,
        upcoming_days=upcoming_days,
        exclude_keys=exclude_keys,
        limit=limit,
    )
    return [
        _build_discovery_placeholder_payload(conn, row, display_run_date=date_key)
        for row in rows
    ]


def select_event_fact_rows_range(conn: sqlite3.Connection, start_date: str, end_date: str) -> List[sqlite3.Row]:
    start_key = _normalize_date_key(start_date)
    end_key = _normalize_date_key(end_date)
    if not start_key or not end_key:
        return []
    cur = conn.cursor()
    try:
        cur.execute(
            """
            SELECT h.id, h.slug, h.event_date, h.run_date, h.fact_as_of, h.model_snapshot_id, h.market_snapshot_id, h.fact_json
            FROM event_fact_latest l
            JOIN event_fact_history h ON h.id = l.fact_id
            WHERE l.event_date >= ? AND l.event_date <= ?
            ORDER BY l.event_date DESC, h.fact_as_of DESC, h.id DESC
            """,
            (start_key, end_key),
        )
        rows = cur.fetchall()
        if rows:
            return _filter_fact_rows_matching_slug_date(rows)
    except sqlite3.OperationalError:
        pass
    cur.execute(
        """
        SELECT *
        FROM event_fact_history
        WHERE run_date >= ? AND run_date <= ?
        ORDER BY run_date DESC, fact_as_of DESC, id DESC
        """,
        (start_key, end_key),
    )
    return _filter_fact_rows_matching_slug_date(cur.fetchall())


def query_runs_paged(
    date: str,
    include_history: bool,
    page: int,
    page_size: int,
) -> Dict[str, Any]:
    if page < 1:
        page = 1
    page_size = max(1, min(page_size, 200))
    if include_history:
        data = query_runs(date, include_history)
        total = len(data)
        start = (page - 1) * page_size
        end = start + page_size
        items = data[start:end] if start < total else []
        return {
            "items": items,
            "page": page,
            "page_size": page_size,
            "has_more": end < total,
            "total": total,
        }
    if not DB_PATH.exists():
        return {
            "items": [],
            "page": page,
            "page_size": page_size,
            "has_more": False,
            "total": None,
        }
    with open_db() as conn:
        if not date:
            date = latest_unsettled_run_date(conn) or latest_run_date(conn)
        if date and "T" in date:
            date = date.split("T", 1)[0]
        cur = conn.cursor()
        cur.execute(
            "SELECT * FROM event_runs WHERE run_date = ? ORDER BY created_at DESC",
            (date,),
        )
        trade_map = query_edge_trades(conn)
        fills_map = query_trade_fills(conn)
        auto_orders_map = query_auto_orders(conn)
        seen: set[Tuple[str, str]] = set()
        selected_rows: List[sqlite3.Row] = []
        skipped = 0
        has_more = False
        offset = (page - 1) * page_size
        for row in cur:
            event_date_key = str(row["event_date"] or "")
            if "T" in event_date_key:
                event_date_key = event_date_key.split("T", 1)[0]
            key = (str(row["slug"] or ""), event_date_key)
            if key in seen:
                continue
            seen.add(key)
            if skipped < offset:
                skipped += 1
                continue
            selected_rows.append(row)
            if len(selected_rows) >= page_size:
                for row_next in cur:
                    event_date_next = str(row_next["event_date"] or "")
                    if "T" in event_date_next:
                        event_date_next = event_date_next.split("T", 1)[0]
                    next_key = (str(row_next["slug"] or ""), event_date_next)
                    if next_key in seen:
                        continue
                    has_more = True
                    break
                break
        market_tick_latest_map = query_market_tick_latest_for_keys(
            conn,
            [(row["slug"], row["event_date"]) for row in selected_rows],
        )
        out = [
            build_run_item(conn, row, trade_map, fills_map, auto_orders_map, market_tick_latest_map)
            for row in selected_rows
        ]
        return {
            "items": out,
            "page": page,
            "page_size": page_size,
            "has_more": has_more,
            "total": None,
        }


def query_runs_range(days: int, end_date: str) -> List[Dict[str, Any]]:
    if not DB_PATH.exists():
        return []
    with open_db() as conn:
        if not end_date:
            end_date = latest_unsettled_run_date(conn) or latest_run_date(conn)
        if not end_date:
            return []
        if "T" in end_date:
            end_date = end_date.split("T", 1)[0]
        try:
            end_dt = datetime.fromisoformat(end_date).date()
        except ValueError:
            return []
        if days <= 0:
            start_dt = end_dt
        else:
            start_dt = end_dt - timedelta(days=max(0, days - 1))
        start_date = start_dt.isoformat()
        cur = conn.cursor()
        cur.execute(
            """
            SELECT * FROM event_runs
            WHERE run_date >= ? AND run_date <= ?
            ORDER BY run_date DESC, created_at DESC
            """,
            (start_date, end_date),
        )
        rows = cur.fetchall()
        trade_map = query_edge_trades(conn)
        fills_map = query_trade_fills(conn)
        auto_orders_map = query_auto_orders(conn)
        selected_rows: List[sqlite3.Row] = []
        seen: set[Tuple[str, str]] = set()
        for row in rows:
            slug = str(row["slug"] or "")
            event_date_key = str(row["event_date"] or "")
            if "T" in event_date_key:
                event_date_key = event_date_key.split("T", 1)[0]
            if not slug or not event_date_key:
                continue
            key = (slug, event_date_key)
            if key in seen:
                continue
            seen.add(key)
            selected_rows.append(row)
        market_tick_latest_map = query_market_tick_latest_for_keys(
            conn,
            [(row["slug"], row["event_date"]) for row in selected_rows],
        )
        out = [
            build_run_item(conn, row, trade_map, fills_map, auto_orders_map, market_tick_latest_map)
            for row in selected_rows
        ]
        return out


def _hydrate_fact_market_updated_at(payload: Any, market_tick_latest_map: Dict[Tuple[str, str], str]) -> None:
    if not isinstance(payload, dict):
        return
    slug = str(payload.get("slug") or "").strip()
    event_date = _normalize_date_key(str(payload.get("event_date") or payload.get("date") or ""))
    if not slug or not event_date:
        return
    tick_updated_at = str(market_tick_latest_map.get((slug, event_date)) or "").strip()
    if not tick_updated_at:
        return
    prev = str(payload.get("market_updated_at") or "").strip()
    if (not prev) or tick_updated_at > prev:
        payload["market_updated_at"] = tick_updated_at
        payload["market_updated_source"] = "tick"
    quote_prev = str(payload.get("market_quote_updated_at") or "").strip()
    if (not quote_prev) or tick_updated_at > quote_prev:
        payload["market_quote_updated_at"] = tick_updated_at
        payload["market_quote_updated_source"] = "tick"


def _hydrate_fact_market_top_label(payload: Any) -> None:
    """
    Backward/forward compatibility:
    - Older fact_json may have market_top_label derived from best_ask, which is misleading in illiquid books.
    - Recompute from distribution at read time so UI always sees the SSOT definition.
    """
    if not isinstance(payload, dict):
        return
    dist = payload.get("distribution") or payload.get("rows") or []
    distribution = normalize_distribution_rows(dist if isinstance(dist, list) else [])
    if not distribution:
        return
    payload["market_top_label"] = market_top_label(distribution)


def _hydrate_fact_single_temperature_top(payload: Any) -> None:
    if not isinstance(payload, dict):
        return
    dist = payload.get("distribution") or payload.get("rows") or []
    distribution = normalize_distribution_rows(dist if isinstance(dist, list) else [])
    if not distribution:
        return
    contract_label, contract_q = top_bucket_from_distribution(distribution, "q_round")
    top_label, top_q = top_posterior_bucket_from_distribution(distribution, "q_round")
    if not top_label:
        top_label, top_q = contract_label, contract_q
    atomic_label, atomic_q = top_single_temperature_bucket_from_distribution(distribution, "q_round")
    payload["contract_payout_top_label"] = contract_label
    payload["contract_payout_top_q"] = contract_q
    payload["single_temperature_top_label"] = top_label
    payload["single_temperature_top_q"] = top_q
    payload["model_top_label"] = top_label
    payload["model_top_q"] = top_q
    payload["atomic_temperature_top_label"] = atomic_label
    payload["atomic_temperature_top_q"] = atomic_q
    corrected = payload.get("corrected_top_bucket")
    if isinstance(corrected, dict):
        for key in ("equal", "auto", "scenario"):
            label = str(corrected.get(key) or "").strip()
            if label and not is_settlement_temperature_bucket_label(label):
                corrected[key] = top_label


def _merge_fill_fact_row_meta(payload: Dict[str, Any], row: Any) -> None:
    if not isinstance(payload, dict) or row is None:
        return

    def _fill(key: str, value: Any, *, normalize_date: bool = False) -> None:
        if value is None:
            return
        next_value = _normalize_date_key(str(value or "")) if normalize_date else value
        if next_value in (None, ""):
            return
        if payload.get(key) in (None, ""):
            payload[key] = next_value

    try:
        keys = row.keys() if hasattr(row, "keys") else []
    except Exception:
        keys = []
    if "slug" in keys:
        _fill("slug", str(row["slug"] or ""))
    if "event_date" in keys:
        _fill("event_date", row["event_date"], normalize_date=True)
    if "run_date" in keys:
        _fill("run_date", row["run_date"], normalize_date=True)
    if "fact_as_of" in keys:
        _fill("fact_as_of", str(row["fact_as_of"] or ""))
    if "id" in keys:
        _fill("fact_id", row["id"])
    if "fact_id" in keys:
        _fill("fact_id", row["fact_id"])
    if "model_snapshot_id" in keys:
        _fill("model_snapshot_id", row["model_snapshot_id"])
    if "market_snapshot_id" in keys:
        _fill("market_snapshot_id", row["market_snapshot_id"])


def _market_flow_row_price(row: Mapping[str, Any]) -> Tuple[Optional[float], str]:
    bid = to_float(row.get("best_bid"))
    ask = to_float(row.get("best_ask"))
    if (
        bid is not None
        and ask is not None
        and math.isfinite(bid)
        and math.isfinite(ask)
        and 0.0 <= bid <= 1.0
        and 0.0 <= ask <= 1.0
    ):
        return (float(bid) + float(ask)) / 2.0, "yes_mid"
    if bid is not None and math.isfinite(bid) and 0.0 <= bid <= 1.0:
        return float(bid), "yes_bid"
    yes_price = to_float(row.get("yes_price"))
    if yes_price is not None and math.isfinite(yes_price) and 0.0 <= yes_price <= 1.0:
        return float(yes_price), "yes_price"
    if ask is not None and math.isfinite(ask) and 0.0 <= ask <= 1.0:
        return float(ask), "yes_ask_only"
    return None, "none"


def _market_flow_row_probability(row: Mapping[str, Any]) -> Optional[float]:
    for key in (
        "q_temperature_bucket_posterior",
        "q_bayes_posterior",
        "q_posterior",
        "q_raw",
        "q_round",
    ):
        val = to_float(row.get(key))
        if val is not None and math.isfinite(val):
            return max(0.0, min(1.0, float(val)))
    return None


def _market_flow_sorted_text(entries: List[Dict[str, Any]], limit: int = 3) -> str:
    parts: List[str] = []
    for entry in entries[: max(1, limit)]:
        label = str(entry.get("outcome") or "").strip()
        delta_pp = to_float(entry.get("delta_pp"))
        if not label or delta_pp is None or not math.isfinite(delta_pp):
            continue
        parts.append(f"{label} {delta_pp:+.1f}pp")
    return "；".join(parts)


def _previous_fact_row_for_market_flow(
    conn: sqlite3.Connection,
    slug: str,
    event_date: str,
    fact_as_of: str,
    fact_id: Optional[int],
) -> Optional[sqlite3.Row]:
    if not slug or not event_date:
        return None
    cur = conn.cursor()
    try:
        if fact_as_of and fact_id is not None:
            cur.execute(
                """
                SELECT id, fact_as_of, model_snapshot_id, market_snapshot_id, market_updated_at, fact_json
                FROM event_fact_history
                WHERE slug = ?
                  AND event_date = ?
                  AND (fact_as_of < ? OR (fact_as_of = ? AND id < ?))
                ORDER BY fact_as_of DESC, id DESC
                LIMIT 1
                """,
                (slug, event_date, fact_as_of, fact_as_of, int(fact_id)),
            )
        elif fact_as_of:
            cur.execute(
                """
                SELECT id, fact_as_of, model_snapshot_id, market_snapshot_id, market_updated_at, fact_json
                FROM event_fact_history
                WHERE slug = ?
                  AND event_date = ?
                  AND fact_as_of < ?
                ORDER BY fact_as_of DESC, id DESC
                LIMIT 1
                """,
                (slug, event_date, fact_as_of),
            )
        else:
            cur.execute(
                """
                SELECT id, fact_as_of, model_snapshot_id, market_snapshot_id, market_updated_at, fact_json
                FROM event_fact_history
                WHERE slug = ?
                  AND event_date = ?
                ORDER BY fact_as_of DESC, id DESC
                LIMIT 1 OFFSET 1
                """,
                (slug, event_date),
            )
        return cur.fetchone()
    except sqlite3.OperationalError:
        return None


def _fact_row_value(row: Any, key: str) -> Any:
    try:
        if row is not None and hasattr(row, "keys") and key in row.keys():
            return row[key]
    except Exception:
        return None
    return None


def build_market_flow_context(
    conn: sqlite3.Connection,
    payload: Mapping[str, Any],
    fact_row: Any = None,
) -> Dict[str, Any]:
    if not isinstance(payload, Mapping):
        return {"version": "market_flow_context_v1", "status": "payload_missing"}
    slug = str(payload.get("slug") or _fact_row_value(fact_row, "slug") or "").strip()
    event_date = _normalize_date_key(str(payload.get("event_date") or _fact_row_value(fact_row, "event_date") or ""))
    fact_as_of = str(payload.get("fact_as_of") or _fact_row_value(fact_row, "fact_as_of") or "").strip()
    fact_id = _to_int(_fact_row_value(fact_row, "id"))
    distribution = normalize_distribution_rows(payload.get("distribution") or payload.get("rows") or [])
    if not slug or not event_date or not distribution:
        return {"version": "market_flow_context_v1", "status": "insufficient_current_snapshot"}
    previous_row = _previous_fact_row_for_market_flow(conn, slug, event_date, fact_as_of, fact_id)
    if not previous_row:
        return {
            "version": "market_flow_context_v1",
            "status": "no_previous_snapshot",
            "latest_at": fact_as_of or str(payload.get("market_updated_at") or ""),
        }
    previous_payload = safe_json_loads(str(previous_row["fact_json"] or ""))
    previous_distribution = normalize_distribution_rows(
        previous_payload.get("distribution") or previous_payload.get("rows") or []
    )
    previous_by_label = {
        str(row.get("outcome") or ""): row
        for row in previous_distribution
        if isinstance(row, Mapping) and str(row.get("outcome") or "")
    }
    entries: List[Dict[str, Any]] = []
    for row in distribution:
        if not isinstance(row, Mapping):
            continue
        label = str(row.get("outcome") or "").strip()
        if not label or not is_settlement_temperature_bucket_label(label):
            continue
        previous = previous_by_label.get(label)
        if not isinstance(previous, Mapping):
            continue
        mid, price_source = _market_flow_row_price(row)
        previous_mid, previous_price_source = _market_flow_row_price(previous)
        if mid is None or previous_mid is None:
            continue
        delta = float(mid) - float(previous_mid)
        q_val = _market_flow_row_probability(row)
        previous_q = _market_flow_row_probability(previous)
        q_delta = (
            float(q_val) - float(previous_q)
            if q_val is not None and previous_q is not None
            else None
        )
        spread = to_float(row.get("spread"))
        entry: Dict[str, Any] = {
            "outcome": label,
            "mid": float(mid),
            "previous_mid": float(previous_mid),
            "delta": delta,
            "delta_pp": delta * 100.0,
            "price_source": price_source,
            "previous_price_source": previous_price_source,
            "q_posterior": q_val,
            "previous_q_posterior": previous_q,
            "q_delta": q_delta,
            "q_delta_pp": q_delta * 100.0 if q_delta is not None else None,
            "spread": spread,
            "bid": to_float(row.get("best_bid")),
            "ask": to_float(row.get("best_ask")),
            "previous_bid": to_float(previous.get("best_bid")),
            "previous_ask": to_float(previous.get("best_ask")),
            "bid_depth_topN": to_float(row.get("bid_depth_topN")),
            "ask_depth_topN": to_float(row.get("ask_depth_topN")),
        }
        if spread is not None and math.isfinite(spread) and spread >= 0.15:
            entry["liquidity_note"] = "wide_spread"
        entries.append(entry)
    entries.sort(key=lambda item: (bucket_sort_key(str(item.get("outcome") or ""))))
    inflows = sorted(
        [entry for entry in entries if to_float(entry.get("delta")) is not None and float(entry["delta"]) > 0.0025],
        key=lambda item: float(item.get("delta") or 0.0),
        reverse=True,
    )
    outflows = sorted(
        [entry for entry in entries if to_float(entry.get("delta")) is not None and float(entry["delta"]) < -0.0025],
        key=lambda item: float(item.get("delta") or 0.0),
    )
    max_market_delta = max((abs(float(entry.get("delta") or 0.0)) for entry in entries), default=0.0)
    q_deltas = [
        abs(float(entry["q_delta"]))
        for entry in entries
        if entry.get("q_delta") is not None and math.isfinite(float(entry["q_delta"]))
    ]
    max_model_delta = max(q_deltas, default=0.0)
    flow_only_repricing = bool(max_market_delta >= 0.08 and max_model_delta <= 0.02)
    market_label, market_price, market_source = market_top_label_with_source(distribution)
    model_label, model_q = top_posterior_bucket_from_distribution(distribution, "q_raw")
    contract_label, contract_q = top_bucket_from_distribution(distribution, "q_round")
    inflow_text = _market_flow_sorted_text(inflows)
    outflow_text = _market_flow_sorted_text(outflows)
    if outflow_text and inflow_text:
        if flow_only_repricing:
            summary = f"盘口报价从 {outflow_text} 转向 {inflow_text}；模型/后验基本未变，判定为盘口重定价。"
        else:
            summary = f"盘口报价变化：流出 {outflow_text}；流入 {inflow_text}。"
    elif outflow_text:
        summary = f"盘口报价流出：{outflow_text}。"
    elif inflow_text:
        summary = f"盘口报价流入：{inflow_text}。"
    else:
        summary = "盘口报价较上一快照无显著迁移。"
    wide_spread = [
        str(entry.get("outcome") or "")
        for entry in entries
        if str(entry.get("liquidity_note") or "") == "wide_spread"
    ]
    notes: List[str] = []
    if flow_only_repricing:
        notes.append("模型概率/温度轨迹未给出同量级变化，当前差异来自盘口报价重定价。")
    if wide_spread:
        notes.append(f"{'、'.join(wide_spread[:3])} 盘口价差较宽，尾部热桶价格可信度需打折。")
    if market_label and model_label and market_label != model_label:
        notes.append(f"盘口最高目标为 {market_label}，模型最终概率最高目标为 {model_label}，两者不一致。")
    return {
        "version": "market_flow_context_v1",
        "status": "ok",
        "label": "盘口重定价" if flow_only_repricing else "盘口流向",
        "summary": summary,
        "latest_at": fact_as_of or str(payload.get("market_updated_at") or ""),
        "previous_at": str(previous_row["fact_as_of"] or previous_payload.get("fact_as_of") or ""),
        "model_snapshot_id": _to_int(payload.get("model_snapshot_id") or _fact_row_value(fact_row, "model_snapshot_id")),
        "market_snapshot_id": _to_int(payload.get("market_snapshot_id") or _fact_row_value(fact_row, "market_snapshot_id")),
        "previous_model_snapshot_id": _to_int(previous_row["model_snapshot_id"]),
        "previous_market_snapshot_id": _to_int(previous_row["market_snapshot_id"]),
        "flow_only_repricing": flow_only_repricing,
        "max_market_delta_pp": max_market_delta * 100.0,
        "max_model_delta_pp": max_model_delta * 100.0,
        "market_top_label": market_label,
        "market_top_mid": market_price,
        "market_top_source": market_source,
        "model_top_label": model_label,
        "model_top_q": model_q,
        "contract_payout_top_label": contract_label,
        "contract_payout_top_q": contract_q,
        "top_outflows": outflows[:4],
        "top_inflows": inflows[:4],
        "bucket_flows": entries,
        "notes": notes,
    }


def _attach_market_flow_context(
    conn: sqlite3.Connection,
    payload: Dict[str, Any],
    fact_row: Any = None,
) -> None:
    if not isinstance(payload, dict):
        return
    try:
        payload["market_flow_context"] = build_market_flow_context(conn, payload, fact_row)
    except Exception as exc:
        payload["market_flow_context"] = {
            "version": "market_flow_context_v1",
            "status": "error",
            "error": str(exc)[:120],
        }


def _first_text_value(mapping: Mapping[str, Any], *keys: str) -> str:
    for key in keys:
        value = mapping.get(key)
        if value is None:
            continue
        text = str(value).strip()
        if text:
            return text
    return ""


def _extract_weather_likelihood_features(payload: Any, distribution: Any) -> Dict[str, Any]:
    if isinstance(payload, Mapping):
        for key in ("weather_likelihood_features", "likelihood_features", "bayes_likelihood_features"):
            value = payload.get(key)
            if isinstance(value, Mapping):
                return dict(value)
    if isinstance(distribution, list):
        for row in distribution:
            if not isinstance(row, Mapping):
                continue
            for key in ("weather_likelihood_features", "likelihood_features", "bayes_likelihood_features"):
                value = row.get(key)
                if isinstance(value, Mapping):
                    return dict(value)
    return {}


def _precip_profile_from_distribution(distribution: Any) -> Dict[str, Any]:
    if not isinstance(distribution, list):
        return {}
    for row in distribution:
        if not isinstance(row, Mapping):
            continue
        groups = row.get("q_bayes_physical_likelihood_observed_component_groups")
        if not isinstance(groups, Mapping):
            groups = row.get("q_bayes_physical_likelihood_component_groups")
        if isinstance(groups, Mapping):
            precip_group = groups.get("precipitation_evaporative_cooling")
            if isinstance(precip_group, Mapping) and isinstance(precip_group.get("source_profile"), Mapping):
                return dict(precip_group.get("source_profile") or {})
        explanation = row.get("q_bayes_physical_d0_explanation")
        if isinstance(explanation, Mapping):
            variables = explanation.get("variables")
            if isinstance(variables, list):
                for variable in variables:
                    if (
                        isinstance(variable, Mapping)
                        and variable.get("key") == "radar_echo"
                        and isinstance(variable.get("source_profile"), Mapping)
                    ):
                        return dict(variable.get("source_profile") or {})
    return {}


def _precip_panel_source_card(
    *,
    key: str,
    label: str,
    source_available: bool,
    strong_available: bool,
    precip_present: bool,
    no_precip_confirmed: bool,
    source: str,
    source_field: str,
    updated_at: str,
    rate_mm_per_h: Optional[float],
    na_reason: str,
    detail: str = "",
) -> Dict[str, Any]:
    if strong_available and no_precip_confirmed:
        state = "strong_no_precip"
    elif strong_available and precip_present:
        state = "strong_precip"
    elif strong_available:
        state = "strong"
    else:
        state = "covered" if source_available else "missing"
    return {
        "key": key,
        "label": label,
        "source_available": bool(source_available),
        "available": bool(strong_available),
        "strong_available": bool(strong_available),
        "precip_present": bool(precip_present),
        "no_precip_confirmed": bool(no_precip_confirmed),
        "state": state,
        "source": source,
        "source_field": source_field,
        "updated_at": updated_at,
        "rate_mm_per_h": rate_mm_per_h,
        "na_reason": "" if strong_available else na_reason,
        "detail": detail,
    }


def _build_precipitation_evidence_coverage(
    payload: Any,
    distribution: Any,
    *,
    fallback_updated_at: str = "",
) -> Dict[str, Any]:
    payload_map = payload if isinstance(payload, Mapping) else {}
    features = _extract_weather_likelihood_features(payload_map, distribution)
    profile = precipitation_evidence_profile(features) if features else {}
    if not profile or profile.get("evidence_state") == "missing":
        fallback_profile = _precip_profile_from_distribution(distribution)
        if fallback_profile:
            profile = dict(fallback_profile)
    if not isinstance(profile, Mapping):
        profile = {}

    source = str(profile.get("source") or features.get("radar_qpe_proxy_source") or "").strip()
    source_field = str(profile.get("source_field") or "").strip()
    source_class = str(profile.get("source_class") or "").strip()
    source_class_l = source_class.lower()
    source_text = " ".join([source, source_field, source_class]).lower()
    rate = to_float(profile.get("rate_mm_per_h"))
    if rate is None:
        rate = to_float(features.get("radar_precip_rate_mm_per_h"))
    if rate is None:
        rate = to_float(features.get("qpe_precip_rate_mm_per_h"))
    if rate is None:
        rate = to_float(features.get("observed_precip_rate_mm_per_h"))
    strong_available = bool(profile.get("available_strong"))
    profile_precip_present = bool(profile.get("precip_present"))
    profile_no_precip = bool(profile.get("no_precip_confirmed"))
    strong_na_reason = str(profile.get("na_reason") or "real_radar_qpe_metar_or_verified_precip_missing")

    lineage = payload_map.get("weather_source_lineage") if isinstance(payload_map.get("weather_source_lineage"), Mapping) else {}
    alert = (
        payload_map.get("weather_source_delay_deformation_alert")
        if isinstance(payload_map.get("weather_source_delay_deformation_alert"), Mapping)
        else {}
    )
    row0 = next((row for row in distribution if isinstance(row, Mapping)), {}) if isinstance(distribution, list) else {}
    aux_source = _first_text_value(row0, "weather_likelihood_aux_source")
    feature_refreshed_at = _first_text_value(row0, "weather_likelihood_refreshed_at") or fallback_updated_at

    awc_updated = (
        _first_text_value(features, "zuuu_metar_raw_awc_latest_at", "metar_observation_time", "metar_latest_at")
        or _first_text_value(alert, "awc_latest_at")
    )
    awc_lineage = lineage.get("zuuu_metar_raw_awc") if isinstance(lineage, Mapping) else {}
    awc_source_name = (
        _first_text_value(features, "zuuu_metar_raw_awc", "source")
        if "metar" in str(features.get("source") or "").lower() or "awc" in str(features.get("source") or "").lower()
        else ""
    )
    if not awc_source_name and isinstance(awc_lineage, Mapping):
        awc_source_name = _first_text_value(awc_lineage, "provider", "source_id", "url")
    awc_source_available = bool(
        features.get("zuuu_metar_raw_awc_available")
        or awc_updated
        or "metar" in aux_source.lower()
        or "awc" in aux_source.lower()
        or awc_lineage
    )
    awc_strong = bool(
        strong_available
        and (
            source_class_l == "metar"
            or "metar" in source_text
            or "awc" in source_text
            or source_field
            in {
                "metar_rain_observed",
                "is_raining_observed",
                "observed_precip_rate_mm_per_h",
                "awc_metar_no_precip_observed",
                "metar_no_precip_observed",
                "metar_cavok_observed",
            }
        )
    )
    awc_reason = (
        strong_na_reason
        if awc_source_available
        else "awc_metar_source_missing"
    )

    mrms_updated = _first_text_value(features, "radar_qpe_latest_at", "radar_qpe_latest_modified_at")
    mrms_source_available = bool(
        features.get("radar_qpe_available")
        or mrms_updated
        or "mrms" in aux_source.lower()
        or "qpe" in source_text
        or "radar_precip_rate_mm_per_h" in features
        or "qpe_precip_rate_mm_per_h" in features
    )
    mrms_source = _first_text_value(features, "radar_qpe_source", "radar_qpe_value_source", "radar_qpe_source_url")
    mrms_strong = bool(strong_available and (source_class_l == "radar_qpe" or "mrms" in source_text or "qpe" in source_text))
    mrms_reason = (
        strong_na_reason
        if mrms_source_available
        else str(features.get("radar_qpe_value_na_reason") or "mrms_qpe_source_missing_or_not_applicable")
    )

    station_updated = _first_text_value(features, "nws_observation_time", "station_observation_time")
    station_source_available = bool(
        station_updated
        or "nws_latest_station_observation" in aux_source
        or "station_observation" in source_text
        or str(features.get("source") or "") == "nws_latest_station_observation"
    )
    station_source = _first_text_value(features, "source", "station_id")
    station_strong = bool(strong_available and (source_class_l == "verifiable_observed" or "station_observation" in source_text or "nws" in source_text))
    station_reason = (
        strong_na_reason
        if station_source_available
        else "verified_station_precip_source_missing"
    )

    sources = [
        _precip_panel_source_card(
            key="awc_metar",
            label="AWC/METAR",
            source_available=awc_source_available,
            strong_available=awc_strong,
            precip_present=bool(awc_strong and profile_precip_present),
            no_precip_confirmed=bool(awc_strong and profile_no_precip),
            source=awc_source_name or "zuuu_metar_raw_awc",
            source_field=source_field if awc_strong else "",
            updated_at=awc_updated,
            rate_mm_per_h=rate if awc_strong else None,
            na_reason=awc_reason,
            detail="NOAA AviationWeather / airport METAR",
        ),
        _precip_panel_source_card(
            key="mrms_qpe",
            label="MRMS-QPE",
            source_available=mrms_source_available,
            strong_available=mrms_strong,
            precip_present=bool(mrms_strong and profile_precip_present),
            no_precip_confirmed=bool(mrms_strong and profile_no_precip),
            source=mrms_source or "NOAA_MRMS",
            source_field=source_field if mrms_strong else "",
            updated_at=mrms_updated,
            rate_mm_per_h=rate if mrms_strong else None,
            na_reason=mrms_reason,
            detail="NOAA MRMS precip-rate/QPE",
        ),
        _precip_panel_source_card(
            key="verified_station_precip",
            label="Verified Station",
            source_available=station_source_available,
            strong_available=station_strong,
            precip_present=bool(station_strong and profile_precip_present),
            no_precip_confirmed=bool(station_strong and profile_no_precip),
            source=station_source or "nws_latest_station_observation",
            source_field=source_field if station_strong else "",
            updated_at=station_updated,
            rate_mm_per_h=rate if station_strong else None,
            na_reason=station_reason,
            detail="NWS/official station observation",
        ),
    ]
    source_covered_count = sum(1 for item in sources if item["source_available"])
    strong_count = sum(1 for item in sources if item["strong_available"])
    strong_precip_count = sum(1 for item in sources if item["strong_available"] and item["precip_present"])
    strong_no_precip_count = sum(1 for item in sources if item["strong_available"] and item["no_precip_confirmed"])
    total = len(sources)
    profile_state = str(profile.get("evidence_state") or ("strong" if strong_count else "missing"))
    state = profile_state
    if strong_no_precip_count:
        state = "strong_no_precip"
    elif strong_precip_count:
        state = "strong_precip"
    elif source_covered_count and not strong_count:
        state = "covered_no_strong_precip"
    return {
        "version": "precipitation_evidence_coverage_v2",
        "strong_available": bool(strong_count > 0),
        "precip_confirmed": bool(strong_precip_count > 0),
        "no_precip_confirmed": bool(strong_no_precip_count > 0),
        "state": state,
        "source_covered_count": int(source_covered_count),
        "strong_source_count": int(strong_count),
        "strong_precip_count": int(strong_precip_count),
        "strong_no_precip_count": int(strong_no_precip_count),
        "source_total": int(total),
        "coverage_rate": float(source_covered_count) / float(total) if total else 0.0,
        "strong_coverage_rate": float(strong_count) / float(total) if total else 0.0,
        "source_profile": dict(profile),
        "rate_mm_per_h": rate,
        "source": source,
        "source_field": source_field,
        "source_class": source_class,
        "updated_at": _first_text_value(features, "weather_likelihood_refreshed_at") or feature_refreshed_at,
        "na_reason": "" if strong_count else strong_na_reason,
        "sources": sources,
    }


def _hydrate_fact_precipitation_evidence_coverage(payload: Any) -> None:
    if not isinstance(payload, dict):
        return
    dist = payload.get("distribution") or payload.get("rows") or []
    distribution = normalize_distribution_rows(dist if isinstance(dist, list) else [])
    payload["precipitation_evidence_coverage"] = _build_precipitation_evidence_coverage(
        payload,
        distribution,
        fallback_updated_at=str(payload.get("fact_as_of") or payload.get("market_updated_at") or ""),
    )


def _sanitize_physical_d0_explanation_in_distribution(distribution: Any) -> None:
    if not isinstance(distribution, list):
        return
    proxy_fields = {
        "observed_precip_rate_mm_per_h",
        "precipitation_rate_mm_per_h",
        "rain_rate_mm_per_h",
        "is_raining",
    }
    for row in distribution:
        if not isinstance(row, dict):
            continue
        explanation = row.get("q_bayes_physical_d0_explanation")
        if not isinstance(explanation, dict):
            continue
        variables = explanation.get("variables")
        if not isinstance(variables, list):
            continue
        changed = False
        for variable in variables:
            if not isinstance(variable, dict) or variable.get("key") != "radar_echo":
                continue
            current = variable.get("current") if isinstance(variable.get("current"), dict) else {}
            source_field = str(current.get("source_field") or "").strip()
            source_profile = variable.get("source_profile") if isinstance(variable.get("source_profile"), dict) else {}
            proxy_source = str(source_profile.get("proxy_source") or "").lower()
            is_proxy = bool(source_profile.get("is_proxy_only")) or source_field in proxy_fields or "open_meteo" in proxy_source
            if not is_proxy:
                continue
            variable["label"] = "Precip Proxy 降水代理"
            variable["evidence_state"] = "proxy"
            variable["na_reason"] = (
                "real_radar_qpe_metar_or_verified_precip_missing;"
                f"proxy={proxy_source or source_field or 'unknown'}"
            )
            variable["direction"] = "neutral"
            variable["observed_warming_pp"] = 0.0
            variable["observed_cooling_pp"] = 0.0
            variable["warming_pp"] = 0.0
            variable["cooling_pp"] = 0.0
            variable["target_buckets"] = []
            variable["target_bucket_text"] = ""
            variable["neutral"] = True
            variable["source_profile"] = {
                "source_field": source_field,
                "proxy_source": source_profile.get("proxy_source") or "",
                "source": source_profile.get("source") or "",
                "source_class": "weak_proxy",
                "available_strong": False,
                "available_proxy": True,
                "evidence_state": "proxy",
                "rate_mm_per_h": current.get("value"),
                "na_reason": variable["na_reason"],
                "is_real_radar_or_metar": False,
                "is_proxy_only": True,
            }
            changed = True
        if not changed:
            continue
        combo = explanation.get("combination")
        if not isinstance(combo, dict):
            continue
        warm = sum(float(to_float(v.get("warming_pp")) or 0.0) for v in variables if isinstance(v, dict))
        cool = sum(float(to_float(v.get("cooling_pp")) or 0.0) for v in variables if isinstance(v, dict))
        obs_warm = sum(float(to_float(v.get("observed_warming_pp")) or 0.0) for v in variables if isinstance(v, dict))
        obs_cool = sum(float(to_float(v.get("observed_cooling_pp")) or 0.0) for v in variables if isinstance(v, dict))
        combo["warming_pp"] = warm
        combo["cooling_pp"] = cool
        combo["net_pp"] = warm - cool
        combo["observed_warming_pp"] = obs_warm
        combo["observed_cooling_pp"] = obs_cool
        combo["observed_net_pp"] = obs_warm - obs_cool
        combo["total_posterior_change_pp"] = warm - cool
        if combo.get("conclusion") in {"cooling_observed_only", "convection_risk"} and obs_warm - obs_cool >= -0.20:
            combo["conclusion"] = "neutral"
            combo["label"] = "中性"
        targets = combo.get("target_buckets")
        if isinstance(targets, list):
            combo["target_buckets"] = [
                str(target)
                for target in targets
                if not re.search(r"\bor\s+(?:below|higher|above|more)\b", str(target), re.IGNORECASE)
            ]


def query_facts(date: str, include_history: bool, include_upcoming: bool = False) -> List[Dict[str, Any]]:
    if not DB_PATH.exists():
        return []
    allow_backfill = _env_bool("PM_FACTS_ALLOW_READ_BACKFILL", False)
    db_cm = open_db if allow_backfill else open_db_ro_fast
    platt_days = None
    try:
        platt_days = int(os.environ.get("PM_Q_PLATT_DAYS", "60"))
    except (TypeError, ValueError):
        platt_days = 60
    platt = _load_platt_calibration(platt_days or 0)
    with db_cm() as conn:
        if allow_backfill:
            ensure_fact_tables(conn)
        date_key = str(date or "").strip()
        if not date_key:
            date_key = latest_unsettled_run_date(conn) or latest_run_date(conn) or ""
        date_key = _normalize_date_key(date_key)
        if not date_key:
            return []
        if allow_backfill:
            try:
                _backfill_facts_if_needed(conn, date_key, include_history)
            except sqlite3.OperationalError:
                pass
        try:
            if include_upcoming and not include_history:
                upcoming_days_val = _ui_upcoming_days()
                fact_rows = select_event_fact_rows_latest_with_upcoming(conn, date_key, upcoming_days=upcoming_days_val)
            else:
                upcoming_days_val = 0
                fact_rows = select_event_fact_rows(conn, date_key, include_history)
            market_tick_latest_map = query_market_tick_latest_for_keys(
                conn,
                [(row["slug"], row["event_date"]) for row in fact_rows],
            )
        except sqlite3.OperationalError:
            return []
        first_prediction_stats = {}
        out: List[Dict[str, Any]] = []
        for row in fact_rows:
            try:
                payload = json.loads(row["fact_json"])
            except Exception:
                continue
            if isinstance(payload, dict):
                _slim_fact_payload_for_ui(payload)
                _merge_fill_fact_row_meta(payload, row)
                distribution = normalize_distribution_rows(payload.get("distribution") or payload.get("rows") or [])
                if distribution:
                    payload["distribution"] = distribution
                    _hydrate_distribution_market_fields_in_place(
                        conn,
                        distribution,
                        str(payload.get("slug") or ""),
                        _normalize_date_key(str(payload.get("event_date") or "")),
                        _normalize_date_key(str(payload.get("run_date") or "")),
                    )
                    _apply_display_probability_fields_in_place(distribution)
                _hydrate_fact_market_updated_at(payload, market_tick_latest_map)
                _hydrate_fact_market_top_label(payload)
                _hydrate_fact_single_temperature_top(payload)
                _attach_market_flow_context(conn, payload, row)
                _hydrate_fact_precipitation_evidence_coverage(payload)
                try:
                    _ensure_fact_q_calibrated(payload, platt)
                except Exception:
                    pass
                try:
                    _set_fact_q_calibrated_na_reason(payload, platt)
                except Exception:
                    pass
                _attach_first_prediction_hit_rates(payload, first_prediction_stats)
                _align_snapshot_posterior_derived_fields(payload)
                _attach_target_switch_context(payload)
                # SSOT: front-end should not recompute entry candidates/reasons from raw distribution.
                payload["auto_trade_ssot"] = _safe_build_auto_trade_ssot(payload)
                out.append(payload)
        if include_upcoming and not include_history:
            existing_keys = {
                (
                    str(item.get("slug") or "").strip(),
                    _normalize_date_key(str(item.get("event_date") or "")),
                )
                for item in out
                if isinstance(item, dict)
            }
            placeholders = _discovery_placeholder_payloads(
                conn,
                date_key,
                upcoming_days=upcoming_days_val,
                exclude_keys=existing_keys,
                limit=max(0, 200 - len(out)),
            )
            out.extend(placeholders)
        return out


def query_facts_paged(
    date: str,
    include_history: bool,
    page: int,
    page_size: int,
    include_upcoming: bool = False,
) -> Dict[str, Any]:
    if page < 1:
        page = 1
    page_size = max(1, min(page_size, 200))
    if include_history:
        data = query_facts(date, include_history=True)
        total = len(data)
        start = (page - 1) * page_size
        end = start + page_size
        items = data[start:end] if start < total else []
        return {
            "items": items,
            "page": page,
            "page_size": page_size,
            "has_more": end < total,
            "total": total,
        }
    if not DB_PATH.exists():
        return {
            "items": [],
            "page": page,
            "page_size": page_size,
            "has_more": False,
            "total": None,
        }
    date_key_cache = _normalize_date_key(str(date or "").strip())
    if not include_history and FACTS_PAGE_CACHE_SEC > 0 and date_key_cache:
        cache_key = f"{date_key_cache}|p={page}|s={page_size}|h=0|u={1 if include_upcoming else 0}"
        cached = _FACTS_PAGE_CACHE.get(cache_key)
        if cached:
            cached_at, payload = cached
            if (time.time() - cached_at) <= FACTS_PAGE_CACHE_SEC:
                return payload
    allow_backfill = _env_bool("PM_FACTS_ALLOW_READ_BACKFILL", False)
    platt_days = None
    try:
        platt_days = int(os.environ.get("PM_Q_PLATT_DAYS", "60"))
    except (TypeError, ValueError):
        platt_days = 60
    platt = _load_platt_calibration(platt_days or 0)
    db_cm = open_db if allow_backfill else open_db_ro_fast
    with db_cm() as conn:
        if allow_backfill:
            ensure_fact_tables(conn)
        date_key = str(date or "").strip()
        if not date_key:
            date_key = latest_unsettled_run_date(conn) or latest_run_date(conn) or ""
        date_key = _normalize_date_key(date_key)
        if not date_key:
            return {
                "items": [],
                "page": page,
                "page_size": page_size,
                "has_more": False,
                "total": 0,
            }
        if allow_backfill:
            try:
                _backfill_facts_if_needed(conn, date_key, include_history=False)
            except sqlite3.OperationalError:
                pass
        try:
            upcoming_days_val = _ui_upcoming_days() if include_upcoming else 0
            total = count_event_fact_rows(conn, date_key, include_upcoming=include_upcoming, upcoming_days=upcoming_days_val)
            start = (page - 1) * page_size
            end = start + page_size
            page_rows = select_event_fact_rows_paged(
                conn,
                date_key,
                page,
                page_size,
                include_upcoming=include_upcoming,
                upcoming_days=upcoming_days_val,
            )
            market_tick_latest_map = query_market_tick_latest_for_keys(
                conn,
                [(row["slug"], row["event_date"]) for row in page_rows],
            )
        except sqlite3.OperationalError:
            return {
                "items": [],
                "page": page,
                "page_size": page_size,
                "has_more": False,
                "total": 0,
            }
        first_prediction_stats = _safe_first_prediction_hit_rates(conn)
        forecast_source_accuracy = _safe_forecast_source_accuracy_snapshot_only(conn)
        joint_weak_bias_research = _safe_joint_weak_bias_research_snapshot_only(conn)
        joint_weak_bias_research = _safe_joint_weak_bias_research_snapshot_only(conn)
        items: List[Dict[str, Any]] = []
        for row in page_rows:
            try:
                payload = json.loads(row["fact_json"])
            except Exception:
                continue
            if isinstance(payload, dict):
                _slim_fact_payload_for_ui(payload)
                _merge_fill_fact_row_meta(payload, row)
                distribution = normalize_distribution_rows(payload.get("distribution") or payload.get("rows") or [])
                if distribution:
                    payload["distribution"] = distribution
                    _hydrate_distribution_market_fields_in_place(
                        conn,
                        distribution,
                        str(payload.get("slug") or ""),
                        _normalize_date_key(str(payload.get("event_date") or "")),
                        _normalize_date_key(str(payload.get("run_date") or "")),
                    )
                    _apply_display_probability_fields_in_place(distribution)
                _hydrate_fact_market_updated_at(payload, market_tick_latest_map)
                _hydrate_fact_market_top_label(payload)
                _hydrate_fact_single_temperature_top(payload)
                _attach_market_flow_context(conn, payload, row)
                _hydrate_fact_precipitation_evidence_coverage(payload)
                try:
                    _ensure_fact_q_calibrated(payload, platt)
                except Exception:
                    pass
                try:
                    _set_fact_q_calibrated_na_reason(payload, platt)
                except Exception:
                    pass
                _attach_first_prediction_hit_rates(payload, first_prediction_stats)
                _attach_forecast_source_accuracy_for_ui_snapshot(payload, forecast_source_accuracy)
                _attach_joint_weak_bias_research_for_ui_snapshot(payload, joint_weak_bias_research)
                _align_snapshot_posterior_derived_fields(payload)
                _attach_target_switch_context(payload)
                payload["auto_trade_ssot"] = _safe_build_auto_trade_ssot(payload)
                items.append(payload)
        if include_upcoming and page == 1 and len(items) < page_size:
            existing_keys = {
                (
                    str(item.get("slug") or "").strip(),
                    _normalize_date_key(str(item.get("event_date") or "")),
                )
                for item in items
                if isinstance(item, dict)
            }
            placeholders = _discovery_placeholder_payloads(
                conn,
                date_key,
                upcoming_days=upcoming_days_val,
                exclude_keys=existing_keys,
                limit=max(0, page_size - len(items)),
            )
            items.extend(placeholders)
        payload = {
            "items": items,
            "page": page,
            "page_size": page_size,
            "has_more": end < total,
            "total": total,
        }
        if not include_history and FACTS_PAGE_CACHE_SEC > 0:
            cache_key = f"{date_key}|p={page}|s={page_size}|h=0|u={1 if include_upcoming else 0}"
            _FACTS_PAGE_CACHE[cache_key] = (time.time(), payload)
        return payload


def query_facts_range(days: int, end_date: str, *, full: bool = False) -> List[Dict[str, Any]]:
    if not DB_PATH.exists():
        return []
    allow_backfill = _env_bool("PM_FACTS_ALLOW_READ_BACKFILL", False)
    db_cm = open_db if allow_backfill else open_db_ro_fast
    with db_cm() as conn:
        if allow_backfill:
            ensure_fact_tables(conn)
        end_key = str(end_date or "").strip()
        if not end_key:
            end_key = latest_unsettled_run_date(conn) or latest_run_date(conn) or ""
        end_key = _normalize_date_key(end_key)
        if not end_key:
            return []
        try:
            end_dt = datetime.fromisoformat(end_key).date()
        except ValueError:
            return []
        if days <= 0:
            start_dt = end_dt
        else:
            start_dt = end_dt - timedelta(days=max(0, days - 1))
        start_key = start_dt.isoformat()
        try:
            days_key = int(days or 0)
        except (TypeError, ValueError):
            days_key = 0
        full_mode = bool(full)
        cache_key = f"{start_key}|{end_key}|days={max(0, days_key)}|full={1 if full_mode else 0}"
        if not allow_backfill and FACTS_RANGE_CACHE_SEC > 0:
            with _FACTS_RANGE_CACHE_LOCK:
                cached = _FACTS_RANGE_CACHE.get(cache_key)
            if cached and (time.time() - float(cached[0] or 0.0)) <= FACTS_RANGE_CACHE_SEC:
                return cached[1]
        inflight_event: Optional[threading.Event] = None
        is_inflight_owner = False
        if not allow_backfill and FACTS_RANGE_CACHE_SEC > 0:
            with _FACTS_RANGE_INFLIGHT_LOCK:
                inflight_event = _FACTS_RANGE_INFLIGHT.get(cache_key)
                if inflight_event is None:
                    inflight_event = threading.Event()
                    _FACTS_RANGE_INFLIGHT[cache_key] = inflight_event
                    is_inflight_owner = True
            if not is_inflight_owner and inflight_event is not None:
                inflight_event.wait(FACTS_RANGE_INFLIGHT_WAIT_SEC)
                with _FACTS_RANGE_CACHE_LOCK:
                    cached = _FACTS_RANGE_CACHE.get(cache_key)
                if cached and (time.time() - float(cached[0] or 0.0)) <= FACTS_RANGE_CACHE_SEC:
                    return cached[1]
                return []

        def _finish_facts_range_inflight() -> None:
            if is_inflight_owner and inflight_event is not None:
                with _FACTS_RANGE_INFLIGHT_LOCK:
                    _FACTS_RANGE_INFLIGHT.pop(cache_key, None)
                inflight_event.set()

        if allow_backfill:
            try:
                _backfill_facts_if_needed(conn, end_key, include_history=True, start_date_key=start_key)
            except sqlite3.OperationalError:
                pass
        try:
            rows = select_event_fact_rows_range(conn, start_key, end_key)
            market_tick_latest_map = query_market_tick_latest_for_keys(
                conn,
                [(row["slug"], row["event_date"]) for row in rows],
            )
        except sqlite3.OperationalError:
            _finish_facts_range_inflight()
            return []
        first_prediction_stats = _safe_first_prediction_hit_rates(conn)
        forecast_source_accuracy = _safe_forecast_source_accuracy_snapshot_only(conn)
        joint_weak_bias_research = _safe_joint_weak_bias_research_snapshot_only(conn)
        platt: Any = {}
        if full_mode:
            try:
                platt_days = int(os.environ.get("PM_Q_PLATT_DAYS", "60"))
            except (TypeError, ValueError):
                platt_days = 60
            platt = _load_platt_calibration(platt_days or 0)
        out: List[Dict[str, Any]] = []
        seen: set[Tuple[str, str]] = set()
        for row in rows:
            slug = str(row["slug"] or "")
            event_date_key = _normalize_date_key(str(row["event_date"] or ""))
            if not slug or not event_date_key:
                continue
            key = (slug, event_date_key)
            if key in seen:
                continue
            seen.add(key)
            try:
                payload = json.loads(row["fact_json"])
            except Exception:
                continue
            if isinstance(payload, dict):
                _slim_fact_payload_for_ui(payload)
                _merge_fill_fact_row_meta(payload, row)
                distribution = normalize_distribution_rows(payload.get("distribution") or payload.get("rows") or [])
                if distribution:
                    payload["distribution"] = distribution
                    if full_mode:
                        _hydrate_distribution_market_fields_in_place(
                            conn,
                            distribution,
                            str(payload.get("slug") or ""),
                            _normalize_date_key(str(payload.get("event_date") or "")),
                            _normalize_date_key(str(payload.get("run_date") or "")),
                        )
                    else:
                        _prepare_summary_distribution_market_fields_in_place(
                            distribution,
                            event_date_key=_normalize_date_key(str(payload.get("event_date") or "")),
                            run_date_key=_normalize_date_key(str(payload.get("run_date") or "")),
                        )
                    _apply_display_probability_fields_in_place(distribution)
                _hydrate_fact_market_updated_at(payload, market_tick_latest_map)
                if distribution and not full_mode:
                    _hydrate_fact_market_top_fields_from_distribution(payload, distribution)
                else:
                    _hydrate_fact_market_top_label(payload)
                    _hydrate_fact_single_temperature_top(payload)
                if full_mode:
                    _attach_market_flow_context(conn, payload, row)
                _hydrate_fact_precipitation_evidence_coverage(payload)
                if full_mode:
                    try:
                        _ensure_fact_q_calibrated(payload, platt)
                    except Exception:
                        pass
                    try:
                        _set_fact_q_calibrated_na_reason(payload, platt)
                    except Exception:
                        pass
                if full_mode:
                    _attach_first_prediction_hit_rates(payload, first_prediction_stats)
                _align_snapshot_posterior_derived_fields(payload)
                if full_mode:
                    _attach_target_switch_context(payload)
                if full_mode:
                    payload["auto_trade_ssot"] = _safe_build_auto_trade_ssot(payload)
                    out.append(payload)
                else:
                    out.append(_slim_fact_payload_for_facts_range_history(payload))
        try:
            if not allow_backfill and FACTS_RANGE_CACHE_SEC > 0:
                with _FACTS_RANGE_CACHE_LOCK:
                    if len(_FACTS_RANGE_CACHE) > 24:
                        stale_keys = sorted(
                            _FACTS_RANGE_CACHE,
                            key=lambda key: float(_FACTS_RANGE_CACHE[key][0] or 0.0),
                        )[:8]
                        for stale_key in stale_keys:
                            _FACTS_RANGE_CACHE.pop(stale_key, None)
                    _FACTS_RANGE_CACHE[cache_key] = (time.time(), out)
        finally:
            _finish_facts_range_inflight()
        return out


def _load_most_likely_history_loaded_rows(
    slug: str,
    event_date: str,
    run_date: str = "",
) -> Tuple[List[Tuple[str, Dict[str, Any], List[Dict[str, Any]]]], Optional[Dict[str, Any]]]:
    slug_key = str(slug or "").strip()
    event_date_key = _normalize_date_key(event_date)
    run_date_key = _normalize_date_key(run_date)
    if not slug_key or not event_date_key or not run_date_key:
        return [], {"ok": False, "items": [], "error": "not_available"}

    allow_backfill = _env_bool("PM_FACTS_ALLOW_READ_BACKFILL", False)
    rows: List[sqlite3.Row] = []

    def _fetch_limited_rows(
        conn: sqlite3.Connection,
        *,
        table: str,
        json_column: str,
        order_id_column: str,
    ) -> List[sqlite3.Row]:
        deadline = time.monotonic() + float(MOST_LIKELY_HISTORY_QUERY_TIMEOUT_SEC)

        def _deadline_handler() -> int:
            return 1 if time.monotonic() >= deadline else 0

        try:
            conn.set_progress_handler(_deadline_handler, 5000)
            cur = conn.cursor()
            cur.execute(
                f"""
                SELECT fact_as_of, {json_column} AS payload_json, '{table}' AS payload_source
                FROM {table}
                WHERE slug = ? AND event_date = ? AND run_date = ?
                ORDER BY fact_as_of DESC, {order_id_column} DESC
                LIMIT ?
                """,
                (
                    slug_key,
                    event_date_key,
                    run_date_key,
                    MOST_LIKELY_HISTORY_ROW_LIMIT,
                ),
            )
            out = list(cur.fetchall() or [])
        finally:
            try:
                conn.set_progress_handler(None, 0)
            except sqlite3.Error:
                pass
        out.reverse()
        return out

    def _fetch_limited_rows_if_present(
        conn: sqlite3.Connection,
        *,
        table: str,
        json_column: str,
        order_id_column: str,
    ) -> List[sqlite3.Row]:
        try:
            return _fetch_limited_rows(
                conn,
                table=table,
                json_column=json_column,
                order_id_column=order_id_column,
            )
        except sqlite3.OperationalError as exc:
            if "no such table" in str(exc).lower():
                return []
            raise

    try:
        if allow_backfill:
            with open_db() as conn:
                ensure_fact_tables(conn)
                try:
                    _backfill_facts_if_needed(conn, run_date_key, include_history=False)
                except sqlite3.OperationalError:
                    pass
                rows = _fetch_limited_rows_if_present(
                    conn,
                    table="event_fact_summary_cache",
                    json_column="summary_json",
                    order_id_column="fact_id",
                )
                if not rows:
                    rows = _fetch_limited_rows_if_present(
                        conn,
                        table="event_fact_history",
                        json_column="fact_json",
                        order_id_column="id",
                    )
        else:
            with open_db_ro_fast(timeout_sec=0.25, busy_timeout_ms=250) as conn:
                rows = _fetch_limited_rows_if_present(
                    conn,
                    table="event_fact_summary_cache",
                    json_column="summary_json",
                    order_id_column="fact_id",
                )
                if not rows:
                    rows = _fetch_limited_rows_if_present(
                        conn,
                        table="event_fact_history",
                        json_column="fact_json",
                        order_id_column="id",
                    )
    except sqlite3.OperationalError as exc:
        error_text = str(exc).lower()
        if "interrupted" in error_text:
            return [], {
                "ok": False,
                "items": [],
                "error": "query_timeout",
                "query_timeout": True,
                "row_limit": MOST_LIKELY_HISTORY_ROW_LIMIT,
            }
        return [], {"ok": False, "items": [], "error": "db_busy", "db_busy": True}
    except Exception:
        return [], {"ok": False, "items": [], "error": "query_failed"}

    if not rows:
        return [], {"ok": False, "items": [], "error": "not_available"}
    loaded_rows: List[Tuple[str, Dict[str, Any], List[Dict[str, Any]]]] = []
    for row in rows:
        fact = safe_json_loads(row["payload_json"])
        if not isinstance(fact, dict):
            continue
        try:
            payload_source = str(row["payload_source"] or "")
        except (KeyError, IndexError, TypeError):
            payload_source = ""
        if payload_source:
            fact["_most_likely_history_source"] = payload_source
        distribution = normalize_distribution_rows(fact.get("distribution") or fact.get("rows") or [])
        if not distribution:
            continue
        loaded_rows.append((str(row["fact_as_of"] or ""), fact, distribution))
    if not loaded_rows:
        return [], {"ok": False, "items": [], "error": "not_available"}
    return loaded_rows, None


def query_most_likely_history(
    slug: str,
    event_date: str,
    weighting: str,
    run_date: str = "",
    *,
    loaded_rows: Optional[List[Tuple[str, Dict[str, Any], List[Dict[str, Any]]]]] = None,
) -> Dict[str, Any]:
    if not DB_PATH.exists():
        return {"ok": False, "items": [], "error": "db_missing"}
    slug_key = str(slug or "").strip()
    event_date_key = _normalize_date_key(event_date)
    run_date_key = _normalize_date_key(run_date)
    if not slug_key or not event_date_key or not run_date_key:
        return {"ok": False, "items": [], "error": "not_available"}
    if loaded_rows is None:
        loaded_rows, error_payload = _load_most_likely_history_loaded_rows(
            slug_key,
            event_date_key,
            run_date_key,
        )
        if error_payload is not None:
            return error_payload
    if not loaded_rows:
        return {"ok": False, "items": [], "error": "not_available"}
    weight_key = "equal"
    if weighting == "auto":
        weight_key = "auto"
    elif weighting == "scenario":
        weight_key = "scenario"
    q_weight_key = "q_round"
    if weight_key == "auto":
        q_weight_key = "q_auto"
    elif weight_key == "scenario":
        q_weight_key = "q_scenario"
    elif weight_key == "equal":
        q_weight_key = "q_equal"
    items: List[Dict[str, Any]] = []
    bucket_series: Dict[str, List[Dict[str, Any]]] = {}
    seen_trend_bucket_labels: Dict[str, Tuple[float, float, str]] = {}
    bucket_series_source = "event_fact_history_distribution"
    for fact_as_of, fact, distribution in loaded_rows:
        if str(fact.get("_most_likely_history_source") or "") == "event_fact_summary_cache":
            bucket_series_source = "event_fact_summary_cache_distribution"
        bucket_diag = fact.get("bucket_diag") or fact.get("bucket_diagnostics") or {}
        corrected_top_bucket = fact.get("corrected_top_bucket") or {}
        preferred_label = ""
        if isinstance(corrected_top_bucket, dict):
            preferred_label = str(corrected_top_bucket.get(weight_key) or "")
        elif isinstance(corrected_top_bucket, str) and weight_key == "equal":
            preferred_label = corrected_top_bucket
        if not preferred_label:
            preferred_label = str(fact.get(f"corrected_top_bucket_{weight_key}") or "")

        def _top3_label(diag: Any, key: str) -> str:
            if not isinstance(diag, dict):
                return ""
            top3 = diag.get(key)
            if not isinstance(top3, dict):
                return ""
            series = top3.get(weight_key)
            if not isinstance(series, list) or not series:
                return ""
            entry = series[0]
            if not isinstance(entry, dict):
                return ""
            return str(entry.get("label") or "")

        raw_label = _top3_label(bucket_diag, "raw_top3")
        corrected_label = _top3_label(bucket_diag, "corrected_top3")
        if preferred_label:
            corrected_label = preferred_label

        def find_dist_row(target: str) -> Optional[Dict[str, Any]]:
            if not target:
                return None
            for row_dist in distribution:
                if str(row_dist.get("outcome") or "") == target:
                    return row_dist
            return None

        def q_from_row(row_dist: Optional[Dict[str, Any]]) -> Optional[float]:
            if not row_dist:
                return None
            q_val = to_float(row_dist.get(q_weight_key))
            if q_val is None:
                q_val = to_float(row_dist.get("q_round"))
            return q_val

        def q_cal_from_row(row_dist: Optional[Dict[str, Any]]) -> Optional[float]:
            if not row_dist:
                return None
            q_val = to_float(row_dist.get("q_calibrated"))
            if q_val is None:
                q_val = to_float(row_dist.get("raw_q_calibrated"))
            return q_val

        def row_float(row_dist: Optional[Dict[str, Any]], key: str) -> Optional[float]:
            if not row_dist:
                return None
            return to_float(row_dist.get(key))

        def row_str(row_dist: Optional[Dict[str, Any]], key: str) -> str:
            if not row_dist:
                return ""
            val = row_dist.get(key)
            if val is None:
                return ""
            return str(val)

        def row_dict(row_dist: Optional[Dict[str, Any]], key: str) -> Dict[str, Any]:
            if not row_dist:
                return {}
            val = row_dist.get(key)
            return val if isinstance(val, dict) else {}

        def bayes_chain_for_bucket(row_dist: Optional[Dict[str, Any]]) -> Dict[str, Any]:
            return _compact_bayes_chain_for_bucket_series(row_dist)

        if not raw_label:
            raw_label, _raw_q = top_bucket_from_distribution(distribution, q_weight_key)
        if not corrected_label:
            corrected_label = raw_label
        label = corrected_label or raw_label
        if not label:
            continue
        chosen_row = find_dist_row(label)
        q_round = q_from_row(chosen_row)
        q_min = to_float(chosen_row.get("q_min")) if chosen_row else None
        q_max = to_float(chosen_row.get("q_max")) if chosen_row else None

        raw_row = find_dist_row(raw_label)
        corrected_row = find_dist_row(corrected_label)
        raw_q_round = q_from_row(raw_row)
        raw_q_calibrated = q_cal_from_row(raw_row)
        raw_q_min = to_float(raw_row.get("q_min")) if raw_row else None
        raw_q_max = to_float(raw_row.get("q_max")) if raw_row else None
        corrected_q_round = q_from_row(corrected_row)
        corrected_q_calibrated = q_cal_from_row(corrected_row)
        corrected_q_min = to_float(corrected_row.get("q_min")) if corrected_row else None
        corrected_q_max = to_float(corrected_row.get("q_max")) if corrected_row else None
        attribution_row = corrected_row or chosen_row or raw_row
        trend_bucket_rows: List[Tuple[Tuple[float, float, str], str, Dict[str, Any]]] = []
        for bucket_row in distribution:
            bucket_label = str(bucket_row.get("outcome") or "")
            if not bucket_label or not is_settlement_temperature_bucket_label(bucket_label):
                continue
            seen_trend_bucket_labels[bucket_label] = bucket_sort_key(bucket_label)
            trend_bucket_rows.append((bucket_sort_key(bucket_label), bucket_label, bucket_row))

        for _bucket_key, bucket_label, bucket_row in sorted(trend_bucket_rows, key=lambda item: item[0]):
            q_raw_for_bucket = q_from_row(bucket_row)
            q_cal_for_bucket = q_cal_from_row(bucket_row)
            q_posterior_for_bucket = row_float(bucket_row, "q_temperature_bucket_posterior")
            q_bayes_for_bucket = row_float(bucket_row, "q_bayes_posterior")
            bayes_chain = bayes_chain_for_bucket(bucket_row)
            if q_posterior_for_bucket is None:
                q_posterior_for_bucket = q_bayes_for_bucket
            if q_posterior_for_bucket is None:
                q_posterior_for_bucket = q_raw_for_bucket
            bucket_series.setdefault(bucket_label, []).append(
                {
                    "ts": fact_as_of,
                    "label": bucket_label,
                    "q_posterior": q_posterior_for_bucket,
                    "q_bayes_posterior": q_bayes_for_bucket,
                    "q_raw": q_raw_for_bucket,
                    "q_prior": bayes_chain.get("prior_prob"),
                    "q_likelihood": bayes_chain.get("likelihood_prob"),
                    "q_calibrated": q_cal_for_bucket,
                    "bayes_chain": bayes_chain,
                    "chain": bayes_chain,
                }
            )
        items.append(
            {
                "label": label,
                "q": q_round,
                "q_round": q_round,
                "q_min": q_min,
                "q_max": q_max,
                "raw_label": raw_label,
                "raw_q": raw_q_round,
                "raw_q_round": raw_q_round,
                "raw_q_calibrated": raw_q_calibrated,
                "raw_q_min": raw_q_min,
                "raw_q_max": raw_q_max,
                "corrected_label": corrected_label,
                "corrected_q": corrected_q_round,
                "corrected_q_round": corrected_q_round,
                "corrected_q_calibrated": corrected_q_calibrated,
                "corrected_q_min": corrected_q_min,
                "corrected_q_max": corrected_q_max,
                "q_model_temperature_bucket_round": row_float(attribution_row, "q_model_temperature_bucket_round"),
                "q_ensemble_qm_bucket": row_float(attribution_row, "q_ensemble_qm_bucket"),
                "q_ensemble_qm_raw_bucket": row_float(attribution_row, "q_ensemble_qm_raw_bucket"),
                "q_bayes_posterior": row_float(attribution_row, "q_bayes_posterior"),
                "q_temperature_bucket_posterior": row_float(attribution_row, "q_temperature_bucket_posterior"),
                "q_bayes_alpha_total": row_float(attribution_row, "q_bayes_alpha_total"),
                "q_temperature_bucket_alpha_total": row_float(attribution_row, "q_temperature_bucket_alpha_total"),
                "q_bayes_source": row_str(attribution_row, "q_bayes_source"),
                "q_calibration_source": row_str(attribution_row, "q_calibration_source"),
                "q_calibration_version": row_str(attribution_row, "q_calibration_version"),
                "q_temperature_bucket_score_components": row_dict(
                    attribution_row,
                    "q_temperature_bucket_score_components",
                ),
                "q_temperature_bucket_score_component_details": row_dict(
                    attribution_row,
                    "q_temperature_bucket_score_component_details",
                ),
                "market_updated_at": str(fact.get("market_updated_at") or ""),
                "market_updated_source": str(fact.get("market_updated_source") or ""),
                "weather_likelihood_refreshed_at": str(fact.get("weather_likelihood_refreshed_at") or ""),
                "model_cache_age_sec": to_float(fact.get("model_cache_age_sec")),
                "model_top_label": str(fact.get("model_top_label") or ""),
                "market_top_label": str(fact.get("market_top_label") or ""),
                "ts": fact_as_of,
            }
        )
    ordered_bucket_series = {
        label: bucket_series.get(label, [])
        for label, _bucket_key in sorted(
            seen_trend_bucket_labels.items(),
            key=lambda item: item[1],
        )
    }
    boundary_labels = [
        label
        for label in ordered_bucket_series
        if not is_single_temperature_bucket_label(label)
    ]
    return {
        "ok": True,
        "items": items,
        "bucket_series": ordered_bucket_series,
        "bucket_series_labels": list(ordered_bucket_series.keys()),
        "bucket_series_boundary_labels": boundary_labels,
        "bucket_series_has_boundary_buckets": bool(boundary_labels),
        "bucket_series_source": bucket_series_source,
    }


def _summary_bucket_series_history_from_event_fact_history(
    conn: sqlite3.Connection,
    *,
    slug: str,
    event_date: str,
    run_date: str,
    max_points: int = UI_SNAPSHOT_SUMMARY_BUCKET_SERIES_POINTS,
) -> Dict[str, Any]:
    slug_key = str(slug or "").strip()
    event_date_key = _normalize_date_key(event_date)
    run_date_key = _normalize_date_key(run_date)
    if not slug_key or not event_date_key:
        return {}
    try:
        limit = max(2, min(int(max_points or UI_SNAPSHOT_SUMMARY_BUCKET_SERIES_POINTS), 96))
    except (TypeError, ValueError):
        limit = UI_SNAPSHOT_SUMMARY_BUCKET_SERIES_POINTS
    cur = conn.cursor()
    rows: List[sqlite3.Row] = []
    try:
        if run_date_key:
            cur.execute(
                """
                SELECT fact_as_of, fact_json
                FROM event_fact_history
                WHERE slug = ? AND event_date = ? AND run_date = ?
                ORDER BY fact_as_of DESC, id DESC
                LIMIT ?
                """,
                (slug_key, event_date_key, run_date_key, limit),
            )
            rows = cur.fetchall()
        if not rows:
            cur.execute(
                """
                SELECT fact_as_of, fact_json
                FROM event_fact_history
                WHERE slug = ? AND event_date = ?
                ORDER BY fact_as_of DESC, id DESC
                LIMIT ?
                """,
                (slug_key, event_date_key, limit),
            )
            rows = cur.fetchall()
    except sqlite3.OperationalError:
        return {}
    if not rows:
        return {}
    bucket_series: Dict[str, List[Dict[str, Any]]] = {}
    seen_labels: Dict[str, Tuple[float, float, str]] = {}

    def first_float(row: Mapping[str, Any], keys: Sequence[str]) -> Optional[float]:
        for key in keys:
            value = to_float(row.get(key))
            if value is not None:
                return value
        return None

    for row in reversed(rows):
        fact = safe_json_loads(str(row["fact_json"] or ""))
        if not isinstance(fact, Mapping):
            continue
        raw_distribution = fact.get("distribution") or fact.get("rows") or []
        distribution = [dict(entry) for entry in raw_distribution if isinstance(entry, Mapping)] if isinstance(raw_distribution, list) else []
        if not distribution:
            continue
        ts = str(row["fact_as_of"] or "")
        if not ts:
            continue
        for bucket_row in distribution:
            if not isinstance(bucket_row, Mapping):
                continue
            label = str(bucket_row.get("outcome") or "")
            if not label or not is_settlement_temperature_bucket_label(label):
                continue
            q_raw = first_float(bucket_row, ("q_equal", "q_raw", "q_round"))
            q_bayes = first_float(bucket_row, ("q_bayes_posterior",))
            q_posterior = first_float(bucket_row, ("q_temperature_bucket_posterior", "q_bayes_posterior"))
            if q_posterior is None:
                q_posterior = q_raw
            chain = _compact_bayes_chain_for_bucket_series(bucket_row)
            seen_labels[label] = bucket_sort_key(label)
            bucket_series.setdefault(label, []).append(
                {
                    "ts": ts,
                    "label": label,
                    "q_posterior": q_posterior,
                    "q_bayes_posterior": q_bayes,
                    "q_raw": q_raw,
                    "q_prior": chain.get("prior_prob"),
                    "q_likelihood": chain.get("likelihood_prob"),
                    "q_ensemble_qm_bucket": first_float(
                        bucket_row,
                        ("q_ensemble_qm_bucket", "q_model_temperature_bucket_round"),
                    ),
                    "bayes_chain": chain,
                    "chain": chain,
                }
            )
    if not bucket_series:
        return {}
    ordered_series = {
        label: bucket_series.get(label, [])
        for label, _bucket_key in sorted(seen_labels.items(), key=lambda item: item[1])
    }
    point_count = sum(len(rows_for_label) for rows_for_label in ordered_series.values())
    return {
        "bucket_series": ordered_series,
        "bucket_series_labels": list(ordered_series.keys()),
        "bucket_series_point_count": point_count,
        "bucket_series_snapshot_count": len(rows),
        "bucket_series_source": "event_fact_history_distribution_summary",
        "bucket_series_run_date": run_date_key,
    }


