def _attach_summary_bucket_series_history(
    conn: sqlite3.Connection,
    payload: MutableMapping[str, Any],
    row: sqlite3.Row,
) -> None:
    if not UI_SNAPSHOT_SUMMARY_BUCKET_SERIES_ENABLED or not isinstance(payload, MutableMapping):
        return

    def row_get(key: str) -> Any:
        try:
            return row[key]
        except (IndexError, KeyError, TypeError):
            return None

    slug = str(payload.get("slug") or row_get("slug") or "").strip()
    event_date = _normalize_date_key(str(payload.get("event_date") or row_get("event_date") or ""))
    run_date = _normalize_date_key(str(payload.get("run_date") or row_get("run_date") or ""))
    fact_as_of = str(payload.get("fact_as_of") or row_get("fact_as_of") or "").strip()
    cache_key = "\n".join(
        [
            slug,
            event_date,
            run_date,
            fact_as_of,
            str(UI_SNAPSHOT_SUMMARY_BUCKET_SERIES_POINTS),
        ]
    )
    now_ts = time.time()
    if UI_SNAPSHOT_SUMMARY_BUCKET_SERIES_CACHE_SEC > 0:
        with _UI_SNAPSHOT_SUMMARY_BUCKET_SERIES_CACHE_LOCK:
            cached = _UI_SNAPSHOT_SUMMARY_BUCKET_SERIES_CACHE.get(cache_key)
            if cached and now_ts - cached[0] <= UI_SNAPSHOT_SUMMARY_BUCKET_SERIES_CACHE_SEC:
                payload.update(copy.deepcopy(cached[1]))
                return

    history = _summary_bucket_series_history_from_summary_cache(
        conn,
        slug=slug,
        event_date=event_date,
        run_date=run_date,
        max_points=UI_SNAPSHOT_SUMMARY_BUCKET_SERIES_POINTS,
    )
    if not history:
        history = _summary_bucket_series_history_from_event_fact_history(
            conn,
            slug=slug,
            event_date=event_date,
            run_date=run_date,
            max_points=UI_SNAPSHOT_SUMMARY_BUCKET_SERIES_POINTS,
        )
    if not history:
        return
    if UI_SNAPSHOT_SUMMARY_BUCKET_SERIES_CACHE_SEC > 0:
        with _UI_SNAPSHOT_SUMMARY_BUCKET_SERIES_CACHE_LOCK:
            if len(_UI_SNAPSHOT_SUMMARY_BUCKET_SERIES_CACHE) >= 128:
                oldest_key = min(
                    _UI_SNAPSHOT_SUMMARY_BUCKET_SERIES_CACHE.items(),
                    key=lambda item: item[1][0],
                )[0]
                _UI_SNAPSHOT_SUMMARY_BUCKET_SERIES_CACHE.pop(oldest_key, None)
            _UI_SNAPSHOT_SUMMARY_BUCKET_SERIES_CACHE[cache_key] = (now_ts, copy.deepcopy(history))
    payload.update(history)


def _ui_timeline_local_label(ts: Any, event_tz: Any = "Asia/Shanghai") -> str:
    text = str(ts or "").strip()
    if not text:
        return ""
    dt = parse_iso_ts(text)
    if dt is None:
        return ""
    if dt.tzinfo is None:
        dt = dt.replace(tzinfo=timezone.utc)
    try:
        zone = ZoneInfo(str(event_tz or "Asia/Shanghai").strip() or "Asia/Shanghai")
    except Exception:
        zone = ZoneInfo("Asia/Shanghai")
    try:
        return dt.astimezone(zone).strftime("%H:%M")
    except Exception:
        return ""


def _ui_event_day_start_utc_iso(event_date_key: str, event_tz: Any = "Asia/Shanghai") -> str:
    date_text = _normalize_date_key(str(event_date_key or ""))
    if not date_text:
        return ""
    try:
        zone = ZoneInfo(str(event_tz or "Asia/Shanghai").strip() or "Asia/Shanghai")
    except Exception:
        zone = ZoneInfo("Asia/Shanghai")
    try:
        local_start = datetime.fromisoformat(date_text).replace(tzinfo=zone)
        return (
            local_start.astimezone(timezone.utc)
            .replace(microsecond=0)
            .isoformat()
            .replace("+00:00", "Z")
        )
    except Exception:
        return f"{date_text}T00:00:00"


def _ui_temperature_timeline_pct_from_keys(row: Mapping[str, Any], keys: Sequence[str]) -> Optional[float]:
    for key in keys:
        pct = _prob_pct_from_ssot_value(row.get(key))
        if pct is not None and math.isfinite(float(pct)):
            return max(0.0, min(100.0, float(pct)))
    return None


def _ui_temperature_timeline_pct_raw(row: Mapping[str, Any], keys: Sequence[str]) -> Optional[float]:
    for key in keys:
        value = to_float(row.get(key))
        if value is not None and math.isfinite(float(value)):
            return max(0.0, min(100.0, float(value)))
    return None


def _ui_temperature_timeline_bucket_row(
    distribution: Sequence[Mapping[str, Any]],
    target_label: str,
) -> Tuple[Dict[str, Any], str]:
    wanted = str(target_label or "").strip()
    if wanted:
        exact = _ssot_bucket_row_by_label(list(distribution), wanted)
        if exact:
            return exact, "target_bucket_exact"
    best_row: Dict[str, Any] = {}
    best_pct: Optional[float] = None
    for raw in distribution or []:
        if not isinstance(raw, Mapping):
            continue
        label = _bucket_label_from_ssot_row(raw)
        if wanted and label and label == wanted:
            return dict(raw), "target_bucket_label"
        pct = _posterior_pct_from_ssot_row(raw)
        if pct is not None and math.isfinite(float(pct)) and (best_pct is None or pct > best_pct):
            best_pct = float(pct)
            best_row = dict(raw)
    return best_row, "posterior_top_fallback" if best_row else ""


def _ui_temperature_timeline_signature(point: Mapping[str, Any]) -> Tuple[Any, ...]:
    def rounded(value: Any, digits: int) -> Any:
        num = to_float(value)
        if num is None or not math.isfinite(float(num)):
            return None
        return round(float(num), digits)

    def first_value(*keys: str) -> Any:
        for key in keys:
            value = point.get(key)
            if value not in (None, "", [], {}):
                return value
        return None

    return (
        str(first_value("primary_metar_latest_at", "amsc_latest_at", "awc_latest_at") or ""),
        rounded(first_value("primary_metar_temp_c", "amsc_temp_c", "awc_temp_c"), 1),
        rounded(first_value("primary_metar_today_max_c", "amsc_today_max_c", "awc_today_max_c"), 1),
        rounded(point.get("temperature_rise_rate_c_per_hour"), 2),
        rounded(point.get("temperature_momentum_1h_c_per_hour"), 2),
        rounded(point.get("temperature_momentum_2h_c_per_hour"), 2),
        rounded(point.get("temperature_momentum_3h_c_per_hour"), 2),
        str(point.get("temperature_momentum_realization_state") or ""),
        point.get("temperature_momentum_posterior_gate_allowed"),
        rounded(point.get("target_probability_pct"), 1),
        rounded(point.get("target_probability_pre_hard_source_pct"), 1),
        rounded(point.get("temperature_trajectory_probability_pct"), 1),
        rounded(point.get("temperature_trajectory_mu_c"), 2),
        rounded(point.get("peak_estimator_mu_c"), 2),
    )


def _ui_temperature_timeline_sample(points: List[Dict[str, Any]], limit: int) -> List[Dict[str, Any]]:
    if len(points) <= limit:
        return points
    must: Set[int] = {0, len(points) - 1}
    scored: List[Tuple[float, int]] = []
    prev: Optional[Mapping[str, Any]] = None
    for idx, point in enumerate(points):
        if prev is None:
            prev = point
            continue
        score = 0.0
        point_latest = str(point.get("primary_metar_latest_at") or point.get("amsc_latest_at") or point.get("awc_latest_at") or "")
        prev_latest = str(prev.get("primary_metar_latest_at") or prev.get("amsc_latest_at") or prev.get("awc_latest_at") or "")
        if point_latest != prev_latest:
            must.add(idx)
            score += 10.0
        if point.get("temperature_momentum_posterior_gate_allowed") != prev.get("temperature_momentum_posterior_gate_allowed"):
            score += 8.0
        if str(point.get("temperature_momentum_realization_state") or "") != str(prev.get("temperature_momentum_realization_state") or ""):
            score += 6.0
        for key, threshold in (
            ("primary_metar_today_max_c", 0.05),
            ("target_probability_pct", 3.0),
            ("target_probability_pre_hard_source_pct", 3.0),
            ("temperature_trajectory_mu_c", 0.25),
            ("peak_estimator_mu_c", 0.25),
        ):
            a = to_float(point.get(key))
            b = to_float(prev.get(key))
            if a is not None and b is None and key in {
                "temperature_trajectory_mu_c",
                "peak_estimator_mu_c",
            }:
                if key == "temperature_trajectory_mu_c":
                    must.add(idx)
                score += 8.0
            elif a is not None and b is not None and abs(float(a) - float(b)) >= threshold:
                if key == "primary_metar_today_max_c":
                    must.add(idx)
                    score += 10.0
                elif key in {"temperature_trajectory_mu_c", "peak_estimator_mu_c"}:
                    if key == "temperature_trajectory_mu_c" and float(a) >= 35.0:
                        must.add(idx)
                    score += 8.0 + min(6.0, abs(float(a) - float(b)))
                else:
                    score += min(5.0, abs(float(a) - float(b)) / 3.0)
        prev = point
        if score > 0.0:
            scored.append((score, idx))
    if len(must) > limit:
        ordered = sorted(must)
        if limit <= 2:
            return [points[ordered[0]], points[ordered[-1]]]
        step = (len(ordered) - 1) / float(limit - 1)
        chosen = sorted({ordered[int(round(i * step))] for i in range(limit)})
        return [points[idx] for idx in chosen]
    chosen = set(must)
    remaining = max(0, limit - len(chosen))
    for _score, idx in sorted(scored, key=lambda item: (-item[0], item[1])):
        if remaining <= 0:
            break
        if idx in chosen:
            continue
        chosen.add(idx)
        remaining -= 1
    if remaining > 0:
        candidates = [idx for idx in range(len(points)) if idx not in chosen]
        if candidates:
            step = max(1, int(math.floor(len(candidates) / float(remaining + 1))))
            for idx in candidates[step - 1 :: step]:
                chosen.add(idx)
                if len(chosen) >= limit:
                    break
    return [points[idx] for idx in sorted(chosen)]


def _ui_temperature_timeline_finalize(
    points: List[Dict[str, Any]],
    *,
    slug_key: str,
    event_date_key: str,
    run_date_key: str,
    target_label: str,
    event_tz: str,
    cache_key: str,
    now_ts: float,
) -> Dict[str, Any]:
    if not points:
        return {}
    sampled = _ui_temperature_timeline_sample(
        points,
        UI_SNAPSHOT_TEMPERATURE_TRAJECTORY_TIMELINE_POINTS,
    )
    peak_point = max(
        (point for point in points if to_float(point.get("primary_metar_today_max_c") if point.get("primary_metar_today_max_c") is not None else point.get("awc_today_max_c")) is not None),
        key=lambda point: (
            float(to_float(point.get("primary_metar_today_max_c") if point.get("primary_metar_today_max_c") is not None else point.get("awc_today_max_c")) or -999.0),
            str(point.get("primary_metar_today_max_at") or point.get("awc_today_max_at") or point.get("primary_metar_latest_at") or point.get("awc_latest_at") or ""),
        ),
        default=None,
    )
    timeline = {
        "available": True,
        "version": "temperature_trajectory_timeline_v1",
        "source": "event_fact_history",
        "slug": slug_key,
        "event_date": event_date_key,
        "run_date": run_date_key,
        "event_tz": str(event_tz or "Asia/Shanghai"),
        "target_bucket": target_label or (sampled[-1].get("target_bucket") if sampled else ""),
        "rows": sampled,
        "row_count": len(points),
        "sampled_count": len(sampled),
        "truncated": len(points) > len(sampled),
        "scan_limit": UI_SNAPSHOT_TEMPERATURE_TRAJECTORY_TIMELINE_SCAN_LIMIT,
        "primary_source_id": "zuuu_metar_raw_amsc",
        "source_priority": ["zuuu_metar_raw_amsc", "zuuu_metar_raw_awc"],
        "peak_metar_today_max_c": (
            peak_point.get("primary_metar_today_max_c")
            if peak_point and peak_point.get("primary_metar_today_max_c") is not None
            else (peak_point.get("awc_today_max_c") if peak_point else None)
        ),
        "peak_metar_latest_local_hhmm": (
            peak_point.get("primary_metar_latest_local_hhmm")
            or peak_point.get("awc_latest_local_hhmm")
            if peak_point
            else ""
        ),
        "peak_amsc_today_max_c": peak_point.get("amsc_today_max_c") if peak_point else None,
        "peak_awc_today_max_c": peak_point.get("awc_today_max_c") if peak_point else None,
        "peak_awc_latest_local_hhmm": peak_point.get("awc_latest_local_hhmm") if peak_point else "",
        "latest_probability_pct": sampled[-1].get("target_probability_pct") if sampled else None,
        "latest_fact_as_of": sampled[-1].get("fact_as_of") if sampled else "",
    }
    if UI_SNAPSHOT_TEMPERATURE_TRAJECTORY_TIMELINE_CACHE_SEC > 0:
        with _UI_SNAPSHOT_TEMPERATURE_TRAJECTORY_TIMELINE_CACHE_LOCK:
            if len(_UI_SNAPSHOT_TEMPERATURE_TRAJECTORY_TIMELINE_CACHE) >= 128:
                oldest_key = min(
                    _UI_SNAPSHOT_TEMPERATURE_TRAJECTORY_TIMELINE_CACHE.items(),
                    key=lambda item: item[1][0],
                )[0]
                _UI_SNAPSHOT_TEMPERATURE_TRAJECTORY_TIMELINE_CACHE.pop(oldest_key, None)
            _UI_SNAPSHOT_TEMPERATURE_TRAJECTORY_TIMELINE_CACHE[cache_key] = (
                now_ts,
                copy.deepcopy(timeline),
            )
    return timeline


def _ui_temperature_timeline_points_from_sql(
    conn: sqlite3.Connection,
    *,
    slug_key: str,
    event_date_key: str,
    target_label: str,
    event_tz: str,
) -> List[Dict[str, Any]]:
    if not target_label:
        return []
    start_after = _ui_event_day_start_utc_iso(event_date_key, event_tz) or f"{event_date_key}T00:00:00"
    cur = conn.cursor()
    try:
        cur.execute(
            """
            WITH base AS (
              SELECT
                id,
                fact_as_of,
                CAST(strftime('%s', replace(substr(fact_as_of, 1, 19), 'T', ' ')) / 600 AS INTEGER) AS time_bucket
              FROM event_fact_history
              WHERE slug = ? AND event_date = ?
                AND fact_as_of >= ?
              ORDER BY fact_as_of DESC, id DESC
              LIMIT ?
            ),
            ranked AS (
              SELECT
                id,
                fact_as_of,
                ROW_NUMBER() OVER (PARTITION BY time_bucket ORDER BY fact_as_of ASC, id ASC) AS bucket_rn,
                ROW_NUMBER() OVER (ORDER BY fact_as_of DESC, id DESC) AS latest_rn
              FROM base
            ),
            selected AS (
              SELECT id FROM ranked
              WHERE bucket_rn = 1 OR latest_rn = 1 OR fact_as_of NOT LIKE '%.%'
            )
            SELECT
              h.id AS fact_id,
              h.fact_as_of AS fact_as_of,
              h.created_at AS created_at,
              COALESCE(
                json_extract(d.value, '$.outcome'),
                json_extract(d.value, '$.bucket'),
                json_extract(d.value, '$.label'),
                json_extract(d.value, '$.target_bucket')
              ) AS target_bucket,
              json_extract(d.value, '$.q_temperature_bucket_posterior') AS q_temperature_bucket_posterior,
              json_extract(d.value, '$.q_bayes_posterior') AS q_bayes_posterior,
              json_extract(d.value, '$.target_bucket_probability') AS target_bucket_probability,
              json_extract(d.value, '$.q_temperature_bucket_posterior_pct') AS q_temperature_bucket_posterior_pct,
              json_extract(d.value, '$.q_bayes_posterior_pct') AS q_bayes_posterior_pct,
              json_extract(d.value, '$.target_bucket_probability_pct') AS target_bucket_probability_pct,
              json_extract(d.value, '$.q_bayes_posterior_pre_hard_source_override') AS q_bayes_posterior_pre_hard_source_override,
              json_extract(d.value, '$.q_bayes_posterior_pre_observed_constraints') AS q_bayes_posterior_pre_observed_constraints,
              json_extract(d.value, '$.q_contract_payout_posterior_pre_observed_constraints') AS q_contract_payout_posterior_pre_observed_constraints,
              json_extract(d.value, '$.q_bayes_temperature_trajectory_status') AS q_bayes_temperature_trajectory_status,
              json_extract(d.value, '$.q_bayes_temperature_trajectory_mu_c') AS q_bayes_temperature_trajectory_mu_c,
              json_extract(d.value, '$.q_bayes_temperature_trajectory_sigma_c') AS q_bayes_temperature_trajectory_sigma_c,
              json_extract(d.value, '$.q_bayes_temperature_trajectory_path_mu_c') AS q_bayes_temperature_trajectory_path_mu_c,
              json_extract(d.value, '$.q_bayes_temperature_trajectory_path_sigma_c') AS q_bayes_temperature_trajectory_path_sigma_c,
              json_extract(d.value, '$.q_bayes_temperature_trajectory_rate_hat_c_per_hour') AS q_bayes_temperature_trajectory_rate_hat_c_per_hour,
              json_extract(d.value, '$.q_bayes_temperature_trajectory_accel_hat_c_per_hour2') AS q_bayes_temperature_trajectory_accel_hat_c_per_hour2,
              json_extract(d.value, '$.q_bayes_meta.temperature_trajectory_prob') AS meta_temperature_trajectory_prob,
              json_extract(d.value, '$.q_bayes_meta.temperature_trajectory_mu_c') AS meta_temperature_trajectory_mu_c,
              json_extract(d.value, '$.q_bayes_meta.temperature_trajectory_sigma_c') AS meta_temperature_trajectory_sigma_c,
              json_extract(d.value, '$.q_bayes_meta.temperature_trajectory_path_mu_c') AS meta_temperature_trajectory_path_mu_c,
              json_extract(d.value, '$.q_bayes_meta.temperature_trajectory_path_sigma_c') AS meta_temperature_trajectory_path_sigma_c,
              json_extract(d.value, '$.q_bayes_meta.temperature_trajectory_rate_c_per_hour') AS meta_temperature_trajectory_rate_c_per_hour,
              json_extract(d.value, '$.q_bayes_meta.temperature_trajectory_rate_hat_c_per_hour') AS meta_temperature_trajectory_rate_hat_c_per_hour,
              json_extract(d.value, '$.q_bayes_meta.temperature_trajectory_accel_hat_c_per_hour2') AS meta_temperature_trajectory_accel_hat_c_per_hour2,
              json_extract(d.value, '$.q_bayes_meta.temperature_trajectory_hours_to_peak_window') AS meta_temperature_trajectory_hours_to_peak_window,
              json_extract(d.value, '$.q_bayes_meta.temperature_trajectory_posterior_status') AS meta_temperature_trajectory_posterior_status,
              json_extract(d.value, '$.q_bayes_physical_likelihood_component') AS q_bayes_physical_likelihood_component,
              COALESCE(
                json_extract(h.fact_json, '$.weather_likelihood_features_compact.zuuu_metar_raw_amsc_latest_at'),
                json_extract(h.fact_json, '$.weather_likelihood_features.zuuu_metar_raw_amsc_latest_at')
              ) AS amsc_latest_at,
              COALESCE(
                json_extract(h.fact_json, '$.weather_likelihood_features_compact.zuuu_metar_raw_amsc_latest_temp_c'),
                json_extract(h.fact_json, '$.weather_likelihood_features.zuuu_metar_raw_amsc_latest_temp_c')
              ) AS amsc_temp_c,
              COALESCE(
                json_extract(h.fact_json, '$.weather_likelihood_features_compact.zuuu_metar_raw_amsc_today_max_c'),
                json_extract(h.fact_json, '$.weather_likelihood_features.zuuu_metar_raw_amsc_today_max_c')
              ) AS amsc_today_max_c,
              COALESCE(
                json_extract(h.fact_json, '$.weather_likelihood_features_compact.zuuu_metar_raw_amsc_today_max_at'),
                json_extract(h.fact_json, '$.weather_likelihood_features.zuuu_metar_raw_amsc_today_max_at')
              ) AS amsc_today_max_at,
              COALESCE(
                json_extract(h.fact_json, '$.weather_likelihood_features_compact.zuuu_metar_raw_amsc_latest_raw'),
                json_extract(h.fact_json, '$.weather_likelihood_features.zuuu_metar_raw_amsc_latest_raw')
              ) AS amsc_raw,
              COALESCE(
                json_extract(h.fact_json, '$.weather_likelihood_features_compact.zuuu_metar_raw_amsc_latest_at'),
                json_extract(h.fact_json, '$.weather_likelihood_features.zuuu_metar_raw_amsc_latest_at'),
                json_extract(h.fact_json, '$.weather_likelihood_features_compact.zuuu_metar_raw_awc_latest_at'),
                json_extract(h.fact_json, '$.weather_likelihood_features.zuuu_metar_raw_awc_latest_at')
              ) AS awc_latest_at,
              COALESCE(
                json_extract(h.fact_json, '$.weather_likelihood_features_compact.zuuu_metar_raw_amsc_latest_temp_c'),
                json_extract(h.fact_json, '$.weather_likelihood_features.zuuu_metar_raw_amsc_latest_temp_c'),
                json_extract(h.fact_json, '$.weather_likelihood_features_compact.zuuu_metar_raw_awc_latest_temp_c'),
                json_extract(h.fact_json, '$.weather_likelihood_features.zuuu_metar_raw_awc_latest_temp_c'),
                json_extract(h.fact_json, '$.weather_likelihood_features_compact.observed_current_temp_c'),
                json_extract(h.fact_json, '$.weather_likelihood_features.observed_current_temp_c'),
                json_extract(h.fact_json, '$.weather_likelihood_features_compact.observed_temp_c'),
                json_extract(h.fact_json, '$.weather_likelihood_features.observed_temp_c')
              ) AS awc_temp_c,
              COALESCE(
                json_extract(h.fact_json, '$.weather_likelihood_features_compact.zuuu_metar_raw_amsc_today_max_c'),
                json_extract(h.fact_json, '$.weather_likelihood_features.zuuu_metar_raw_amsc_today_max_c'),
                json_extract(h.fact_json, '$.weather_likelihood_features_compact.zuuu_metar_raw_awc_today_max_c'),
                json_extract(h.fact_json, '$.weather_likelihood_features.zuuu_metar_raw_awc_today_max_c'),
                json_extract(h.fact_json, '$.weather_likelihood_features_compact.observed_today_max_c'),
                json_extract(h.fact_json, '$.weather_likelihood_features.observed_today_max_c')
              ) AS awc_today_max_c,
              COALESCE(
                json_extract(h.fact_json, '$.weather_likelihood_features_compact.zuuu_metar_raw_amsc_today_max_at'),
                json_extract(h.fact_json, '$.weather_likelihood_features.zuuu_metar_raw_amsc_today_max_at'),
                json_extract(h.fact_json, '$.weather_likelihood_features_compact.zuuu_metar_raw_awc_today_max_at'),
                json_extract(h.fact_json, '$.weather_likelihood_features.zuuu_metar_raw_awc_today_max_at')
              ) AS awc_today_max_at,
              COALESCE(
                json_extract(h.fact_json, '$.weather_likelihood_features_compact.zuuu_metar_raw_amsc_latest_raw'),
                json_extract(h.fact_json, '$.weather_likelihood_features.zuuu_metar_raw_amsc_latest_raw'),
                json_extract(h.fact_json, '$.weather_likelihood_features_compact.zuuu_metar_raw_awc_latest_raw'),
                json_extract(h.fact_json, '$.weather_likelihood_features.zuuu_metar_raw_awc_latest_raw')
              ) AS awc_raw,
              COALESCE(
                json_extract(h.fact_json, '$.weather_likelihood_features_compact.temperature_rise_rate_c_per_hour'),
                json_extract(h.fact_json, '$.weather_likelihood_features.temperature_rise_rate_c_per_hour'),
                json_extract(h.fact_json, '$.weather_likelihood_features_compact.temperature_trajectory_stable_rate_c_per_hour'),
                json_extract(h.fact_json, '$.weather_likelihood_features.temperature_trajectory_stable_rate_c_per_hour')
              ) AS temperature_rise_rate_c_per_hour,
              COALESCE(
                json_extract(h.fact_json, '$.weather_likelihood_features_compact.temperature_rise_rate_window'),
                json_extract(h.fact_json, '$.weather_likelihood_features.temperature_rise_rate_window'),
                json_extract(h.fact_json, '$.weather_likelihood_features_compact.temperature_trajectory_stable_rate_window'),
                json_extract(h.fact_json, '$.weather_likelihood_features.temperature_trajectory_stable_rate_window')
              ) AS temperature_rise_rate_window,
              COALESCE(
                json_extract(h.fact_json, '$.weather_likelihood_features_compact.temperature_momentum_effective_c_per_hour'),
                json_extract(h.fact_json, '$.weather_likelihood_features.temperature_momentum_effective_c_per_hour'),
                json_extract(h.fact_json, '$.weather_likelihood_features_compact.temperature_momentum_posterior_effective_c_per_hour'),
                json_extract(h.fact_json, '$.weather_likelihood_features.temperature_momentum_posterior_effective_c_per_hour')
              ) AS temperature_momentum_effective_c_per_hour,
              COALESCE(
                json_extract(h.fact_json, '$.weather_likelihood_features_compact.temperature_momentum_1h_c_per_hour'),
                json_extract(h.fact_json, '$.weather_likelihood_features.temperature_momentum_1h_c_per_hour')
              ) AS temperature_momentum_1h_c_per_hour,
              COALESCE(
                json_extract(h.fact_json, '$.weather_likelihood_features_compact.temperature_momentum_2h_c_per_hour'),
                json_extract(h.fact_json, '$.weather_likelihood_features.temperature_momentum_2h_c_per_hour')
              ) AS temperature_momentum_2h_c_per_hour,
              COALESCE(
                json_extract(h.fact_json, '$.weather_likelihood_features_compact.temperature_momentum_3h_c_per_hour'),
                json_extract(h.fact_json, '$.weather_likelihood_features.temperature_momentum_3h_c_per_hour')
              ) AS temperature_momentum_3h_c_per_hour,
              COALESCE(
                json_extract(h.fact_json, '$.weather_likelihood_features_compact.temperature_momentum_realization_state'),
                json_extract(h.fact_json, '$.weather_likelihood_features.temperature_momentum_realization_state')
              ) AS temperature_momentum_realization_state,
              COALESCE(
                json_extract(h.fact_json, '$.weather_likelihood_features_compact.temperature_momentum_posterior_gate_allowed'),
                json_extract(h.fact_json, '$.weather_likelihood_features.temperature_momentum_posterior_gate_allowed')
              ) AS temperature_momentum_posterior_gate_allowed,
              COALESCE(
                json_extract(h.fact_json, '$.weather_likelihood_features_compact.temperature_momentum_posterior_gate_state'),
                json_extract(h.fact_json, '$.weather_likelihood_features.temperature_momentum_posterior_gate_state')
              ) AS temperature_momentum_posterior_gate_state,
              COALESCE(
                json_extract(h.fact_json, '$.weather_likelihood_features_compact.temperature_momentum_posterior_gate_reason'),
                json_extract(h.fact_json, '$.weather_likelihood_features.temperature_momentum_posterior_gate_reason')
              ) AS temperature_momentum_posterior_gate_reason,
              COALESCE(
                json_extract(h.fact_json, '$.weather_likelihood_features_compact.peak_estimator_mu_c'),
                json_extract(h.fact_json, '$.weather_likelihood_features.peak_estimator_mu_c')
              ) AS peak_estimator_mu_c,
              COALESCE(
                json_extract(h.fact_json, '$.weather_likelihood_features_compact.peak_estimator_sigma_c'),
                json_extract(h.fact_json, '$.weather_likelihood_features.peak_estimator_sigma_c')
              ) AS peak_estimator_sigma_c,
              COALESCE(
                json_extract(h.fact_json, '$.weather_likelihood_features_compact.peak_estimator_source'),
                json_extract(h.fact_json, '$.weather_likelihood_features.peak_estimator_source')
              ) AS peak_estimator_source
            FROM event_fact_history h
            JOIN selected s ON s.id = h.id
            JOIN json_each(h.fact_json, '$.distribution') AS d
            WHERE COALESCE(
                json_extract(d.value, '$.outcome'),
                json_extract(d.value, '$.bucket'),
                json_extract(d.value, '$.label'),
                json_extract(d.value, '$.target_bucket')
              ) = ?
            ORDER BY h.fact_as_of DESC, h.id DESC
            """,
            (
                slug_key,
                event_date_key,
                start_after,
                UI_SNAPSHOT_TEMPERATURE_TRAJECTORY_TIMELINE_SCAN_LIMIT,
                target_label,
            ),
        )
        rows = list(cur.fetchall())
    except sqlite3.OperationalError:
        return []
    points: List[Dict[str, Any]] = []
    last_sig: Optional[Tuple[Any, ...]] = None

    def row_get(row: Any, key: str) -> Any:
        try:
            return row[key]
        except (KeyError, IndexError, TypeError):
            return None

    def pct_from_fraction_keys(row: Any, keys: Sequence[str]) -> Optional[float]:
        for key in keys:
            pct = _prob_pct_from_ssot_value(row_get(row, key))
            if pct is not None and math.isfinite(float(pct)):
                return max(0.0, min(100.0, float(pct)))
        return None

    def pct_from_raw_keys(row: Any, keys: Sequence[str]) -> Optional[float]:
        for key in keys:
            pct = to_float(row_get(row, key))
            if pct is not None and math.isfinite(float(pct)):
                return max(0.0, min(100.0, float(pct)))
        return None

    for row in reversed(rows):
        target_pct = (
            pct_from_fraction_keys(
                row,
                ("q_temperature_bucket_posterior", "q_bayes_posterior", "target_bucket_probability"),
            )
            or pct_from_raw_keys(
                row,
                ("q_temperature_bucket_posterior_pct", "q_bayes_posterior_pct", "target_bucket_probability_pct"),
            )
        )
        gate_raw = row_get(row, "temperature_momentum_posterior_gate_allowed")
        if isinstance(gate_raw, bool):
            gate_allowed: Optional[bool] = gate_raw
        elif isinstance(gate_raw, (int, float)):
            gate_allowed = bool(gate_raw)
        else:
            gate_text = str(gate_raw or "").strip().lower()
            gate_allowed = True if gate_text in {"1", "true", "yes", "on"} else (False if gate_text in {"0", "false", "no", "off"} else None)
        amsc_latest_at = str(row_get(row, "amsc_latest_at") or "")
        amsc_today_max_at = str(row_get(row, "amsc_today_max_at") or "")
        amsc_temp_c = to_float(row_get(row, "amsc_temp_c"))
        amsc_today_max_c = to_float(row_get(row, "amsc_today_max_c"))
        amsc_raw = str(row_get(row, "amsc_raw") or "")[:240]
        primary_source_id = (
            "zuuu_metar_raw_amsc"
            if any(value not in (None, "", [], {}) for value in (amsc_latest_at, amsc_temp_c, amsc_today_max_c, amsc_raw))
            else "zuuu_metar_raw_awc"
        )
        primary_latest_at = amsc_latest_at or str(row_get(row, "awc_latest_at") or "")
        primary_today_max_at = amsc_today_max_at or str(row_get(row, "awc_today_max_at") or "")
        primary_temp_c = amsc_temp_c if amsc_temp_c is not None else to_float(row_get(row, "awc_temp_c"))
        primary_today_max_c = amsc_today_max_c if amsc_today_max_c is not None else to_float(row_get(row, "awc_today_max_c"))
        primary_raw = amsc_raw or str(row_get(row, "awc_raw") or "")[:240]
        point = {
            "fact_id": int(row_get(row, "fact_id") or 0),
            "fact_as_of": str(row_get(row, "fact_as_of") or ""),
            "fact_as_of_local_hhmm": _ui_timeline_local_label(row_get(row, "fact_as_of"), event_tz),
            "created_at": str(row_get(row, "created_at") or ""),
            "target_bucket": str(row_get(row, "target_bucket") or target_label),
            "probability_source": "event_fact_history_json1_target_bucket",
            "target_probability_pct": target_pct,
            "target_probability_pre_hard_source_pct": pct_from_fraction_keys(
                row,
                (
                    "q_bayes_posterior_pre_hard_source_override",
                    "q_bayes_posterior_pre_observed_constraints",
                    "q_contract_payout_posterior_pre_observed_constraints",
                ),
            ),
            "primary_source_id": primary_source_id,
            "primary_metar_latest_at": primary_latest_at,
            "primary_metar_latest_local_hhmm": _ui_timeline_local_label(primary_latest_at, event_tz),
            "primary_metar_temp_c": primary_temp_c,
            "primary_metar_today_max_c": primary_today_max_c,
            "primary_metar_today_max_at": primary_today_max_at,
            "primary_metar_today_max_local_hhmm": _ui_timeline_local_label(primary_today_max_at, event_tz),
            "primary_metar_raw": primary_raw,
            "amsc_latest_at": amsc_latest_at,
            "amsc_latest_local_hhmm": _ui_timeline_local_label(amsc_latest_at, event_tz),
            "amsc_temp_c": amsc_temp_c,
            "amsc_today_max_c": amsc_today_max_c,
            "amsc_today_max_at": amsc_today_max_at,
            "amsc_today_max_local_hhmm": _ui_timeline_local_label(amsc_today_max_at, event_tz),
            "amsc_raw": amsc_raw,
            "awc_latest_at": primary_latest_at,
            "awc_latest_local_hhmm": _ui_timeline_local_label(primary_latest_at, event_tz),
            "awc_temp_c": primary_temp_c,
            "awc_today_max_c": primary_today_max_c,
            "awc_today_max_at": primary_today_max_at,
            "awc_today_max_local_hhmm": _ui_timeline_local_label(primary_today_max_at, event_tz),
            "awc_raw": primary_raw,
            "temperature_rise_rate_c_per_hour": to_float(row_get(row, "temperature_rise_rate_c_per_hour")),
            "temperature_rise_rate_window": str(row_get(row, "temperature_rise_rate_window") or ""),
            "temperature_momentum_effective_c_per_hour": to_float(row_get(row, "temperature_momentum_effective_c_per_hour")),
            "temperature_momentum_1h_c_per_hour": to_float(row_get(row, "temperature_momentum_1h_c_per_hour")),
            "temperature_momentum_2h_c_per_hour": to_float(row_get(row, "temperature_momentum_2h_c_per_hour")),
            "temperature_momentum_3h_c_per_hour": to_float(row_get(row, "temperature_momentum_3h_c_per_hour")),
            "temperature_momentum_realization_state": str(row_get(row, "temperature_momentum_realization_state") or "").strip(),
            "temperature_momentum_posterior_gate_allowed": gate_allowed,
            "temperature_momentum_posterior_gate_state": str(row_get(row, "temperature_momentum_posterior_gate_state") or "").strip(),
            "temperature_momentum_posterior_gate_reason": str(row_get(row, "temperature_momentum_posterior_gate_reason") or "").strip(),
            "temperature_trajectory_status": str(
                row_get(row, "q_bayes_temperature_trajectory_status")
                or row_get(row, "meta_temperature_trajectory_posterior_status")
                or ""
            ).strip(),
            "temperature_trajectory_probability_pct": pct_from_fraction_keys(
                row,
                ("meta_temperature_trajectory_prob",),
            ),
            "temperature_trajectory_mu_c": _coalesce_numeric(
                row_get(row, "q_bayes_temperature_trajectory_path_mu_c"),
                row_get(row, "meta_temperature_trajectory_path_mu_c"),
                row_get(row, "q_bayes_temperature_trajectory_mu_c"),
                row_get(row, "meta_temperature_trajectory_mu_c"),
            ),
            "temperature_trajectory_sigma_c": _coalesce_numeric(
                row_get(row, "q_bayes_temperature_trajectory_path_sigma_c"),
                row_get(row, "meta_temperature_trajectory_path_sigma_c"),
                row_get(row, "q_bayes_temperature_trajectory_sigma_c"),
                row_get(row, "meta_temperature_trajectory_sigma_c"),
            ),
            "temperature_trajectory_path_mu_c": _coalesce_numeric(
                row_get(row, "q_bayes_temperature_trajectory_path_mu_c"),
                row_get(row, "meta_temperature_trajectory_path_mu_c"),
            ),
            "temperature_trajectory_path_sigma_c": _coalesce_numeric(
                row_get(row, "q_bayes_temperature_trajectory_path_sigma_c"),
                row_get(row, "meta_temperature_trajectory_path_sigma_c"),
            ),
            "temperature_trajectory_rate_c_per_hour": _coalesce_numeric(
                row_get(row, "q_bayes_temperature_trajectory_rate_hat_c_per_hour"),
                row_get(row, "meta_temperature_trajectory_rate_hat_c_per_hour"),
                row_get(row, "meta_temperature_trajectory_rate_c_per_hour"),
            ),
            "temperature_trajectory_rate_hat_c_per_hour": _coalesce_numeric(
                row_get(row, "q_bayes_temperature_trajectory_rate_hat_c_per_hour"),
                row_get(row, "meta_temperature_trajectory_rate_hat_c_per_hour"),
            ),
            "temperature_trajectory_accel_hat_c_per_hour2": _coalesce_numeric(
                row_get(row, "q_bayes_temperature_trajectory_accel_hat_c_per_hour2"),
                row_get(row, "meta_temperature_trajectory_accel_hat_c_per_hour2"),
            ),
            "temperature_trajectory_hours_to_peak_window": to_float(row_get(row, "meta_temperature_trajectory_hours_to_peak_window")),
            "peak_estimator_mu_c": to_float(row_get(row, "peak_estimator_mu_c")),
            "peak_estimator_sigma_c": to_float(row_get(row, "peak_estimator_sigma_c")),
            "peak_estimator_source": str(row_get(row, "peak_estimator_source") or ""),
            "physical_likelihood_component_pct": pct_from_fraction_keys(
                row,
                ("q_bayes_physical_likelihood_component",),
            ),
        }
        if not any(
            point.get(key) not in (None, "", [], {})
            for key in (
                "awc_latest_at",
                "target_probability_pct",
                "peak_estimator_mu_c",
                "temperature_momentum_effective_c_per_hour",
            )
        ):
            continue
        sig = _ui_temperature_timeline_signature(point)
        if sig == last_sig:
            continue
        last_sig = sig
        points.append(point)
    return points


def _build_temperature_trajectory_timeline_for_ui_snapshot(
    conn: sqlite3.Connection,
    *,
    slug: str,
    event_date: str,
    run_date: str = "",
    target_bucket: str = "",
    event_tz: str = "Asia/Shanghai",
) -> Dict[str, Any]:
    if not UI_SNAPSHOT_TEMPERATURE_TRAJECTORY_TIMELINE_ENABLED:
        return {}
    slug_key = str(slug or "").strip()
    event_date_key = _normalize_date_key(str(event_date or ""))
    if not slug_key or not event_date_key:
        return {}
    target_label = str(target_bucket or "").strip()
    run_date_key = _normalize_date_key(str(run_date or ""))
    cache_key = "\n".join(
        [
            slug_key,
            event_date_key,
            run_date_key,
            target_label,
            str(event_tz or "Asia/Shanghai"),
            str(UI_SNAPSHOT_TEMPERATURE_TRAJECTORY_TIMELINE_POINTS),
            str(UI_SNAPSHOT_TEMPERATURE_TRAJECTORY_TIMELINE_SCAN_LIMIT),
        ]
    )
    now_ts = time.time()
    if UI_SNAPSHOT_TEMPERATURE_TRAJECTORY_TIMELINE_CACHE_SEC > 0:
        with _UI_SNAPSHOT_TEMPERATURE_TRAJECTORY_TIMELINE_CACHE_LOCK:
            cached = _UI_SNAPSHOT_TEMPERATURE_TRAJECTORY_TIMELINE_CACHE.get(cache_key)
            if cached and now_ts - cached[0] <= UI_SNAPSHOT_TEMPERATURE_TRAJECTORY_TIMELINE_CACHE_SEC:
                return copy.deepcopy(cached[1])
    fast_points = _ui_temperature_timeline_points_from_sql(
        conn,
        slug_key=slug_key,
        event_date_key=event_date_key,
        target_label=target_label,
        event_tz=event_tz,
    )
    if fast_points:
        return _ui_temperature_timeline_finalize(
            fast_points,
            slug_key=slug_key,
            event_date_key=event_date_key,
            run_date_key=run_date_key,
            target_label=target_label,
            event_tz=event_tz,
            cache_key=cache_key,
            now_ts=now_ts,
        )
    cur = conn.cursor()
    rows: List[sqlite3.Row] = []
    start_after = _ui_event_day_start_utc_iso(event_date_key, event_tz) or f"{event_date_key}T00:00:00"
    try:
        cur.execute(
            """
            SELECT id, fact_as_of, fact_json, created_at
            FROM event_fact_history
            WHERE slug = ? AND event_date = ?
              AND fact_as_of >= ?
            ORDER BY fact_as_of DESC, id DESC
            LIMIT ?
            """,
            (
                slug_key,
                event_date_key,
                start_after,
                UI_SNAPSHOT_TEMPERATURE_TRAJECTORY_TIMELINE_SCAN_LIMIT,
            ),
        )
        rows = list(cur.fetchall())
        if not rows and run_date_key:
            cur.execute(
                """
                SELECT id, fact_as_of, fact_json, created_at
                FROM event_fact_history
                WHERE slug = ? AND event_date = ? AND run_date = ?
                ORDER BY fact_as_of DESC, id DESC
                LIMIT ?
                """,
                (
                    slug_key,
                    event_date_key,
                    run_date_key,
                    UI_SNAPSHOT_TEMPERATURE_TRAJECTORY_TIMELINE_SCAN_LIMIT,
                ),
            )
            rows = list(cur.fetchall())
    except sqlite3.OperationalError:
        return {}
    if not rows:
        return {}
    points: List[Dict[str, Any]] = []
    last_sig: Optional[Tuple[Any, ...]] = None
    for row in reversed(rows):
        fact = safe_json_loads(str(row["fact_json"] or ""))
        if not isinstance(fact, Mapping):
            continue
        distribution = normalize_distribution_rows(fact.get("distribution") or fact.get("rows") or [])
        if not distribution:
            continue
        if not target_label:
            target_label = str(
                fact.get("target_bucket")
                or fact.get("ssot_target_bucket")
                or fact.get("posterior_highest_bucket_label")
                or ""
            ).strip()
        bucket_row, probability_source = _ui_temperature_timeline_bucket_row(distribution, target_label)
        if not bucket_row:
            continue
        features = fact.get("weather_likelihood_features_compact")
        if not isinstance(features, Mapping):
            features = _compact_weather_likelihood_features_for_ui(fact.get("weather_likelihood_features"))
        if not isinstance(features, Mapping):
            features = {}
        features = _normalize_ui_temperature_rise_rate_fields(features)
        q_meta = bucket_row.get("q_bayes_meta") if isinstance(bucket_row.get("q_bayes_meta"), Mapping) else {}
        observed_temp = _coalesce_numeric(
            features.get("zuuu_metar_raw_amsc_latest_temp_c"),
            features.get("zuuu_metar_raw_awc_latest_temp_c"),
            features.get("observed_current_temp_c"),
            features.get("observed_temp_c"),
        )
        observed_max = _coalesce_numeric(
            features.get("zuuu_metar_raw_amsc_today_max_c"),
            features.get("zuuu_metar_raw_awc_today_max_c"),
            features.get("observed_today_max_c"),
        )
        amsc_latest_at = str(features.get("zuuu_metar_raw_amsc_latest_at") or "")
        amsc_today_max_at = str(features.get("zuuu_metar_raw_amsc_today_max_at") or "")
        amsc_temp_c = to_float(features.get("zuuu_metar_raw_amsc_latest_temp_c"))
        amsc_today_max_c = to_float(features.get("zuuu_metar_raw_amsc_today_max_c"))
        amsc_raw = str(features.get("zuuu_metar_raw_amsc_latest_raw") or "")[:240]
        primary_source_id = (
            "zuuu_metar_raw_amsc"
            if any(value not in (None, "", [], {}) for value in (amsc_latest_at, amsc_temp_c, amsc_today_max_c, amsc_raw))
            else "zuuu_metar_raw_awc"
        )
        primary_latest_at = amsc_latest_at or str(features.get("zuuu_metar_raw_awc_latest_at") or "")
        primary_today_max_at = amsc_today_max_at or str(features.get("zuuu_metar_raw_awc_today_max_at") or "")
        primary_temp_c = amsc_temp_c if amsc_temp_c is not None else observed_temp
        primary_today_max_c = amsc_today_max_c if amsc_today_max_c is not None else observed_max
        primary_raw = amsc_raw or str(features.get("zuuu_metar_raw_awc_latest_raw") or "")[:240]
        target_pct = _posterior_pct_from_ssot_row(bucket_row)
        target_pre_hard_pct = _ui_temperature_timeline_pct_from_keys(
            bucket_row,
            (
                "q_bayes_posterior_pre_hard_source_override",
                "q_bayes_posterior_pre_observed_constraints",
                "q_contract_payout_posterior_pre_observed_constraints",
            ),
        )
        trajectory_prob_pct = _ui_temperature_timeline_pct_from_keys(
            q_meta,
            ("temperature_trajectory_prob", "temperature_trajectory_probability"),
        )
        point = {
            "fact_id": int(row["id"] or 0),
            "fact_as_of": str(row["fact_as_of"] or fact.get("fact_as_of") or ""),
            "fact_as_of_local_hhmm": _ui_timeline_local_label(row["fact_as_of"], event_tz),
            "created_at": str(row["created_at"] or ""),
            "target_bucket": _bucket_label_from_ssot_row(bucket_row) or target_label,
            "probability_source": probability_source,
            "target_probability_pct": target_pct,
            "target_probability_pre_hard_source_pct": target_pre_hard_pct,
            "primary_source_id": primary_source_id,
            "primary_metar_latest_at": primary_latest_at,
            "primary_metar_latest_local_hhmm": _ui_timeline_local_label(primary_latest_at, event_tz),
            "primary_metar_temp_c": primary_temp_c,
            "primary_metar_today_max_c": primary_today_max_c,
            "primary_metar_today_max_at": primary_today_max_at,
            "primary_metar_today_max_local_hhmm": _ui_timeline_local_label(primary_today_max_at, event_tz),
            "primary_metar_raw": primary_raw,
            "amsc_latest_at": amsc_latest_at,
            "amsc_latest_local_hhmm": _ui_timeline_local_label(amsc_latest_at, event_tz),
            "amsc_temp_c": amsc_temp_c,
            "amsc_today_max_c": amsc_today_max_c,
            "amsc_today_max_at": amsc_today_max_at,
            "amsc_today_max_local_hhmm": _ui_timeline_local_label(amsc_today_max_at, event_tz),
            "amsc_raw": amsc_raw,
            "awc_latest_at": primary_latest_at,
            "awc_latest_local_hhmm": _ui_timeline_local_label(primary_latest_at, event_tz),
            "awc_temp_c": primary_temp_c,
            "awc_today_max_c": primary_today_max_c,
            "awc_today_max_at": primary_today_max_at,
            "awc_today_max_local_hhmm": _ui_timeline_local_label(primary_today_max_at, event_tz),
            "awc_raw": primary_raw,
            "temperature_rise_rate_c_per_hour": _coalesce_numeric(
                features.get("temperature_rise_rate_c_per_hour"),
                features.get("temperature_trajectory_stable_rate_c_per_hour"),
            ),
            "temperature_rise_rate_window": str(
                features.get("temperature_rise_rate_window")
                or features.get("temperature_trajectory_stable_rate_window")
                or ""
            ),
            "temperature_momentum_effective_c_per_hour": _coalesce_numeric(
                features.get("temperature_momentum_effective_c_per_hour"),
                features.get("temperature_momentum_posterior_effective_c_per_hour"),
            ),
            "temperature_momentum_1h_c_per_hour": to_float(features.get("temperature_momentum_1h_c_per_hour")),
            "temperature_momentum_2h_c_per_hour": to_float(features.get("temperature_momentum_2h_c_per_hour")),
            "temperature_momentum_3h_c_per_hour": to_float(features.get("temperature_momentum_3h_c_per_hour")),
            "temperature_momentum_realization_state": str(
                features.get("temperature_momentum_realization_state") or ""
            ).strip(),
            "temperature_momentum_posterior_gate_allowed": (
                bool(features.get("temperature_momentum_posterior_gate_allowed"))
                if isinstance(features.get("temperature_momentum_posterior_gate_allowed"), bool)
                else str(features.get("temperature_momentum_posterior_gate_allowed") or "").strip().lower()
                in {"1", "true", "yes", "on"}
            ),
            "temperature_momentum_posterior_gate_state": str(
                features.get("temperature_momentum_posterior_gate_state") or ""
            ).strip(),
            "temperature_momentum_posterior_gate_reason": str(
                features.get("temperature_momentum_posterior_gate_reason") or ""
            ).strip(),
            "temperature_trajectory_status": str(
                bucket_row.get("q_bayes_temperature_trajectory_status")
                or q_meta.get("temperature_trajectory_posterior_status")
                or ""
            ).strip(),
            "temperature_trajectory_probability_pct": trajectory_prob_pct,
            "temperature_trajectory_mu_c": _coalesce_numeric(
                bucket_row.get("q_bayes_temperature_trajectory_path_mu_c"),
                q_meta.get("temperature_trajectory_path_mu_c"),
                bucket_row.get("q_bayes_temperature_trajectory_mu_c"),
                q_meta.get("temperature_trajectory_mu_c"),
            ),
            "temperature_trajectory_sigma_c": _coalesce_numeric(
                bucket_row.get("q_bayes_temperature_trajectory_path_sigma_c"),
                q_meta.get("temperature_trajectory_path_sigma_c"),
                bucket_row.get("q_bayes_temperature_trajectory_sigma_c"),
                q_meta.get("temperature_trajectory_sigma_c"),
            ),
            "temperature_trajectory_path_mu_c": _coalesce_numeric(
                bucket_row.get("q_bayes_temperature_trajectory_path_mu_c"),
                q_meta.get("temperature_trajectory_path_mu_c"),
            ),
            "temperature_trajectory_path_sigma_c": _coalesce_numeric(
                bucket_row.get("q_bayes_temperature_trajectory_path_sigma_c"),
                q_meta.get("temperature_trajectory_path_sigma_c"),
            ),
            "temperature_trajectory_rate_c_per_hour": _coalesce_numeric(
                bucket_row.get("q_bayes_temperature_trajectory_rate_hat_c_per_hour"),
                q_meta.get("temperature_trajectory_rate_hat_c_per_hour"),
                bucket_row.get("q_bayes_temperature_trajectory_rate_c_per_hour"),
                q_meta.get("temperature_trajectory_rate_c_per_hour"),
                features.get("temperature_trajectory_stable_rate_c_per_hour"),
            ),
            "temperature_trajectory_rate_hat_c_per_hour": _coalesce_numeric(
                bucket_row.get("q_bayes_temperature_trajectory_rate_hat_c_per_hour"),
                q_meta.get("temperature_trajectory_rate_hat_c_per_hour"),
            ),
            "temperature_trajectory_accel_hat_c_per_hour2": _coalesce_numeric(
                bucket_row.get("q_bayes_temperature_trajectory_accel_hat_c_per_hour2"),
                q_meta.get("temperature_trajectory_accel_hat_c_per_hour2"),
            ),
            "temperature_trajectory_hours_to_peak_window": _coalesce_numeric(
                q_meta.get("temperature_trajectory_hours_to_peak_window"),
            ),
            "peak_estimator_mu_c": _coalesce_numeric(features.get("peak_estimator_mu_c")),
            "peak_estimator_sigma_c": _coalesce_numeric(features.get("peak_estimator_sigma_c")),
            "peak_estimator_source": str(features.get("peak_estimator_source") or ""),
            "physical_likelihood_component_pct": _ui_temperature_timeline_pct_from_keys(
                bucket_row,
                ("q_bayes_physical_likelihood_component",),
            ),
        }
        if not any(
            point.get(key) not in (None, "", [], {})
            for key in (
                "awc_latest_at",
                "target_probability_pct",
                "peak_estimator_mu_c",
                "temperature_momentum_effective_c_per_hour",
            )
        ):
            continue
        sig = _ui_temperature_timeline_signature(point)
        if sig == last_sig:
            continue
        last_sig = sig
        points.append(point)
    if not points:
        return {}
    sampled = _ui_temperature_timeline_sample(
        points,
        UI_SNAPSHOT_TEMPERATURE_TRAJECTORY_TIMELINE_POINTS,
    )
    peak_point = max(
        (
            point
            for point in points
            if to_float(
                point.get("primary_metar_today_max_c")
                if point.get("primary_metar_today_max_c") is not None
                else point.get("awc_today_max_c")
            )
            is not None
        ),
        key=lambda point: (
            float(
                to_float(
                    point.get("primary_metar_today_max_c")
                    if point.get("primary_metar_today_max_c") is not None
                    else point.get("awc_today_max_c")
                )
                or -999.0
            ),
            str(
                point.get("primary_metar_today_max_at")
                or point.get("awc_today_max_at")
                or point.get("primary_metar_latest_at")
                or point.get("awc_latest_at")
                or ""
            ),
        ),
        default=None,
    )
    timeline = {
        "available": True,
        "version": "temperature_trajectory_timeline_v1",
        "source": "event_fact_history",
        "slug": slug_key,
        "event_date": event_date_key,
        "run_date": run_date_key,
        "event_tz": str(event_tz or "Asia/Shanghai"),
        "target_bucket": target_label or (sampled[-1].get("target_bucket") if sampled else ""),
        "rows": sampled,
        "row_count": len(points),
        "sampled_count": len(sampled),
        "truncated": len(points) > len(sampled),
        "scan_limit": UI_SNAPSHOT_TEMPERATURE_TRAJECTORY_TIMELINE_SCAN_LIMIT,
        "primary_source_id": "zuuu_metar_raw_amsc",
        "source_priority": ["zuuu_metar_raw_amsc", "zuuu_metar_raw_awc"],
        "peak_metar_today_max_c": (
            peak_point.get("primary_metar_today_max_c")
            if peak_point and peak_point.get("primary_metar_today_max_c") is not None
            else (peak_point.get("awc_today_max_c") if peak_point else None)
        ),
        "peak_metar_latest_local_hhmm": (
            peak_point.get("primary_metar_latest_local_hhmm")
            or peak_point.get("awc_latest_local_hhmm")
            if peak_point
            else ""
        ),
        "peak_amsc_today_max_c": peak_point.get("amsc_today_max_c") if peak_point else None,
        "peak_awc_today_max_c": peak_point.get("awc_today_max_c") if peak_point else None,
        "peak_awc_latest_local_hhmm": peak_point.get("awc_latest_local_hhmm") if peak_point else "",
        "latest_probability_pct": sampled[-1].get("target_probability_pct") if sampled else None,
        "latest_fact_as_of": sampled[-1].get("fact_as_of") if sampled else "",
    }
    if UI_SNAPSHOT_TEMPERATURE_TRAJECTORY_TIMELINE_CACHE_SEC > 0:
        with _UI_SNAPSHOT_TEMPERATURE_TRAJECTORY_TIMELINE_CACHE_LOCK:
            if len(_UI_SNAPSHOT_TEMPERATURE_TRAJECTORY_TIMELINE_CACHE) >= 128:
                oldest_key = min(
                    _UI_SNAPSHOT_TEMPERATURE_TRAJECTORY_TIMELINE_CACHE.items(),
                    key=lambda item: item[1][0],
                )[0]
                _UI_SNAPSHOT_TEMPERATURE_TRAJECTORY_TIMELINE_CACHE.pop(oldest_key, None)
            _UI_SNAPSHOT_TEMPERATURE_TRAJECTORY_TIMELINE_CACHE[cache_key] = (
                now_ts,
                copy.deepcopy(timeline),
            )
    return timeline


def _build_sequential_physical_timeline_for_ui_snapshot(
    conn: sqlite3.Connection,
    *,
    posterior_ssot: Mapping[str, Any],
    slug: str,
    event_date: str,
    run_date: str,
    event_tz: str,
) -> Dict[str, Any]:
    """Read one successor checkpoint chain as a report-defined-X timeline.

    The legacy timeline is keyed by a market outcome and reads retired v3.1
    distributions.  Sequential Bayes v2 is instead keyed by a physical
    reported-X distribution until X->S->B is available, so its timeline must
    come from the same checkpoint/canonical-event lineage as the current SSOT.
    """

    checkpoint_id = str(posterior_ssot.get("posterior_checkpoint_id") or "").strip()
    posterior_run_id = str(posterior_ssot.get("posterior_run_id") or "").strip()
    fact_snapshot_id = str(posterior_ssot.get("fact_snapshot_id") or "").strip()
    if not checkpoint_id or not posterior_run_id:
        return {}

    def reported_x_ssot_freshness() -> Dict[str, Any]:
        """Compare the displayed checkpoint with same-day canonical facts.

        This is a read-only projection from ``archive.db``.  It never computes
        a replacement posterior; it only prevents an older checkpoint from
        being presented as current while accepted canonical observations are
        waiting for the unique production composer.
        """

        base = {
            "schema": "reported_x_ui_ssot_freshness_v1",
            "state": "na",
            "probability_display_state": "unavailable",
            "posterior_checkpoint_id": checkpoint_id,
            "pending_canonical_event_count": 0,
            "pending_canonical_event_ids": [],
            "pending_canonical_events": [],
            "checkpoint_reported_x_lower_bound_c": to_float(
                posterior_ssot.get("reported_x_lower_bound_c")
            ),
            "frontend_recompute_allowed": False,
            "source": "archive.db:posterior_checkpoints+canonical_observation_events",
        }
        try:
            checkpoint_row = conn.execute(
                """
                SELECT target_identity, consumed_event_ids_json, reported_x_lower_bound_c
                FROM posterior_checkpoints
                WHERE posterior_checkpoint_id=?
                """,
                (checkpoint_id,),
            ).fetchone()
            if checkpoint_row is None:
                return {**base, "na_reason": "posterior_checkpoint_not_found"}
            consumed_raw = safe_json_loads_any(str(checkpoint_row[1] or "[]"))
            consumed_ids = {
                str(value).strip()
                for value in (consumed_raw if isinstance(consumed_raw, list) else [])
                if str(value or "").strip()
            }
            checkpoint_lower = to_float(checkpoint_row[2])
            base["checkpoint_reported_x_lower_bound_c"] = checkpoint_lower
            local_tz = ZoneInfo(str(event_tz or "Asia/Shanghai"))
            local_start = datetime.fromisoformat(str(event_date)).replace(tzinfo=local_tz)
            utc_start = local_start.astimezone(timezone.utc).isoformat(timespec="seconds")
            utc_end = (local_start + timedelta(days=1)).astimezone(timezone.utc).isoformat(
                timespec="seconds"
            )
            canonical_rows = conn.execute(
                """
                SELECT canonical_observation_event_id, report_type, valid_time,
                       first_actionable_seen_at, selected_source_id,
                       parsed_observation_json
                FROM canonical_observation_events
                WHERE target_identity=?
                  AND valid_time>=? AND valid_time<?
                  AND state IN ('accepted_primary','accepted_substitute','confirmed')
                ORDER BY valid_time ASC, revision_no ASC, accepted_at ASC
                """,
                (str(checkpoint_row[0] or ""), utc_start, utc_end),
            ).fetchall()
        except (sqlite3.Error, ValueError, TypeError):
            return {**base, "na_reason": "reported_x_freshness_query_unavailable"}

        pending: List[Dict[str, Any]] = []
        pending_regular_temperatures: List[float] = []
        for event_row in canonical_rows:
            event_id = str(event_row[0] or "").strip()
            if not event_id or event_id in consumed_ids:
                continue
            observation = safe_json_loads(str(event_row[5] or ""))
            if not isinstance(observation, Mapping):
                observation = {}
            temperature_c = to_float(observation.get("temperature_c"))
            report_type = str(event_row[1] or observation.get("report_type") or "").upper()
            if report_type == "METAR" and temperature_c is not None:
                pending_regular_temperatures.append(float(temperature_c))
            pending.append(
                {
                    "canonical_observation_event_id": event_id,
                    "report_type": report_type,
                    "valid_time": str(event_row[2] or ""),
                    "valid_time_local_hhmm": _ui_timeline_local_label(event_row[2], event_tz),
                    "first_actionable_seen_at": str(event_row[3] or ""),
                    "selected_source_id": str(event_row[4] or ""),
                    "temperature_c": temperature_c,
                    "x_hard_bound_role": report_type == "METAR",
                }
            )
        base["pending_canonical_event_count"] = len(pending)
        base["pending_canonical_event_ids"] = [
            str(row["canonical_observation_event_id"]) for row in pending
        ]
        base["pending_canonical_events"] = pending[-8:]
        base["latest_pending_valid_time"] = str(pending[-1].get("valid_time") or "") if pending else ""
        base["latest_pending_valid_time_local_hhmm"] = (
            str(pending[-1].get("valid_time_local_hhmm") or "") if pending else ""
        )
        base["latest_pending_temperature_c"] = (
            pending[-1].get("temperature_c") if pending else None
        )
        base["pending_regular_metar_max_temperature_c"] = (
            max(pending_regular_temperatures) if pending_regular_temperatures else None
        )
        hard_bound_ahead = bool(
            pending_regular_temperatures
            and (
                checkpoint_lower is None
                or max(pending_regular_temperatures) > float(checkpoint_lower)
            )
        )
        base["pending_regular_metar_hard_bound_ahead_of_checkpoint"] = hard_bound_ahead
        if pending:
            base.update(
                {
                    "state": "blocked_unconsumed_canonical_events",
                    "probability_display_state": "frozen_stale_checkpoint",
                    "probability_current": False,
                    "block_reason": "accepted_canonical_observations_not_consumed_by_displayed_checkpoint",
                }
            )
        else:
            base.update(
                {
                    "state": "current",
                    "probability_display_state": "current_checkpoint",
                    "probability_current": True,
                    "block_reason": "",
                }
            )
        return base

    ssot_freshness = reported_x_ssot_freshness()
    try:
        rows = list(
            conn.execute(
                """
                WITH RECURSIVE checkpoint_chain AS (
                    SELECT
                        p.posterior_checkpoint_id,
                        p.previous_checkpoint_id,
                        p.last_canonical_event_id,
                        p.last_strong_update_id,
                        p.reported_physical_x_distribution_json,
                        p.latent_post_state_json,
                        p.reported_x_lower_bound_c,
                        p.committed_at,
                        0 AS depth
                    FROM posterior_checkpoints p
                    WHERE p.posterior_checkpoint_id = ?
                    UNION ALL
                    SELECT
                        previous.posterior_checkpoint_id,
                        previous.previous_checkpoint_id,
                        previous.last_canonical_event_id,
                        previous.last_strong_update_id,
                        previous.reported_physical_x_distribution_json,
                        previous.latent_post_state_json,
                        previous.reported_x_lower_bound_c,
                        previous.committed_at,
                        chain.depth + 1
                    FROM posterior_checkpoints previous
                    JOIN checkpoint_chain chain
                      ON previous.posterior_checkpoint_id = chain.previous_checkpoint_id
                    WHERE chain.depth < 256
                )
                SELECT
                    chain.posterior_checkpoint_id,
                    chain.reported_physical_x_distribution_json,
                    chain.reported_x_lower_bound_c,
                    chain.committed_at,
                    event.canonical_observation_event_id,
                    event.report_type,
                    event.valid_time,
                    event.first_actionable_seen_at,
                    event.accepted_at,
                    event.selected_source_id,
                    event.parsed_observation_json,
                    update_row.strong_observation_update_id,
                    update_row.raw_log_score_json,
                    update_row.path_auxiliary_json,
                    chain.latent_post_state_json
                FROM checkpoint_chain chain
                JOIN canonical_observation_events event
                  ON event.canonical_observation_event_id = chain.last_canonical_event_id
                LEFT JOIN strong_observation_updates update_row
                  ON update_row.strong_observation_update_id = chain.last_strong_update_id
                ORDER BY event.valid_time ASC, chain.committed_at ASC
                """,
                (checkpoint_id,),
            ).fetchall()
        )
    except sqlite3.Error:
        return {}
    points: List[Dict[str, Any]] = []
    for raw_row in rows:
        distribution = safe_json_loads(str(raw_row[1] or ""))
        if not isinstance(distribution, Mapping) or not distribution:
            continue
        physical_rows: List[Tuple[float, float]] = []
        for raw_temperature, raw_probability in distribution.items():
            temperature_c = to_float(raw_temperature)
            probability = to_float(raw_probability)
            if (
                temperature_c is None
                or probability is None
                or not math.isfinite(float(temperature_c))
                or not math.isfinite(float(probability))
                or float(probability) < 0.0
            ):
                continue
            physical_rows.append((float(temperature_c), float(probability)))
        if not physical_rows:
            continue
        top_temperature_c, top_probability = max(
            physical_rows,
            key=lambda item: (item[1], -item[0]),
        )
        observation = safe_json_loads(str(raw_row[10] or ""))
        if not isinstance(observation, Mapping):
            observation = {}
        raw_scores = safe_json_loads_any(str(raw_row[12] or ""))
        score_row = next(
            (item for item in raw_scores if isinstance(item, Mapping)),
            {},
        ) if isinstance(raw_scores, Sequence) and not isinstance(raw_scores, (str, bytes, bytearray)) else {}
        feature_values = (
            score_row.get("feature_values")
            if isinstance(score_row, Mapping)
            and isinstance(score_row.get("feature_values"), Mapping)
            else {}
        )
        feature_audit = (
            score_row.get("feature_audit")
            if isinstance(score_row, Mapping)
            and isinstance(score_row.get("feature_audit"), Mapping)
            else {}
        )
        path_auxiliary = safe_json_loads(str(raw_row[13] or ""))
        if not isinstance(path_auxiliary, Mapping):
            path_auxiliary = {}
        termination_risk = (
            dict(path_auxiliary.get("termination_risk") or {})
            if isinstance(path_auxiliary.get("termination_risk"), Mapping)
            else {}
        )
        latent_state_map = safe_json_loads(str(raw_row[14] or ""))
        if not isinstance(latent_state_map, Mapping):
            latent_state_map = {}
        latent_state_probabilities = [
            {"state": str(state), "probability": float(probability)}
            for state, probability in latent_state_map.items()
            if to_float(probability) is not None and float(probability) >= 0.0
        ]
        latent_state_probabilities.sort(
            key=lambda item: (-item["probability"], item["state"])
        )
        top_state = latent_state_probabilities[0] if latent_state_probabilities else {}
        # Strong LR scores live on continuous Z cells.  A reported X bucket
        # combines several such cells, so binding one arbitrary Z score to the
        # top integer X would create a false second probability explanation.
        top_temperature_state_scores: List[Dict[str, Any]] = []
        state_score_values: List[float] = []
        scoring_kind = str(score_row.get("scoring_kind") or "")
        valid_time = str(raw_row[7] or observation.get("valid_time") or "")
        observed_peak_c = _coalesce_numeric(
            feature_values.get("trajectory.observed_peak_including_current_c"),
            raw_row[2],
            observation.get("temperature_c"),
        )
        first_cb_valid_time = str(feature_audit.get("physical.first_cb_valid_time") or "")
        first_cb_local_hhmm = _ui_timeline_local_label(first_cb_valid_time, event_tz)
        first_cb_temperature_c = to_float(feature_audit.get("physical.first_cb_temperature_c"))
        first_cb_event_state = str(feature_values.get("physical.first_cb_event_state") or "no_cb_yet")
        first_cb_timing_phase = str(feature_values.get("physical.first_cb_timing_phase") or "no_cb_yet")
        first_cb_peak_relation = str(feature_values.get("physical.first_cb_peak_relation") or "no_cb_yet")
        if first_cb_timing_phase == "early_before_peak_window":
            first_cb_effect = "峰值前首次 CB：显著提高升温提前终止风险"
        elif first_cb_timing_phase == "peak_window":
            first_cb_effect = "峰值窗口首次 CB：提高升温终止风险"
        elif first_cb_timing_phase == "late_after_peak_window" and first_cb_peak_relation == "at_observed_peak":
            first_cb_effect = "CB 晚到：不逆转已形成日高，仅轻微约束剩余升温"
        elif first_cb_timing_phase == "late_after_peak_window":
            first_cb_effect = "CB 晚到且温度已回落：支持升温终止，但不逆转已形成日高"
        else:
            first_cb_effect = "尚未报告 CB；不把无 CB 当作继续升温保证"
        first_cb_display = (
            f"首次 CB {first_cb_local_hhmm} · {first_cb_temperature_c:g}°C · {first_cb_effect}"
            if first_cb_valid_time and first_cb_temperature_c is not None
            else first_cb_effect
        )
        points.append(
            {
                "posterior_checkpoint_id": str(raw_row[0] or ""),
                "canonical_observation_event_id": str(raw_row[4] or ""),
                "strong_observation_update_id": str(raw_row[11] or ""),
                "fact_as_of": str(raw_row[3] or ""),
                "fact_as_of_local_hhmm": _ui_timeline_local_label(raw_row[3], event_tz),
                "report_type": str(raw_row[5] or observation.get("report_type") or ""),
                "primary_source_id": str(raw_row[9] or ""),
                "primary_metar_latest_at": valid_time,
                "primary_metar_latest_local_hhmm": _ui_timeline_local_label(valid_time, event_tz),
                "primary_metar_temp_c": to_float(observation.get("temperature_c")),
                "primary_metar_today_max_c": observed_peak_c,
                "amsc_latest_at": valid_time,
                "amsc_latest_local_hhmm": _ui_timeline_local_label(valid_time, event_tz),
                "amsc_temp_c": to_float(observation.get("temperature_c")),
                "amsc_today_max_c": observed_peak_c,
                # The sequential checkpoint contains the selected AMSC
                # observation only.  Never relabel it as an AWC observation.
                "awc_latest_at": "",
                "awc_latest_local_hhmm": "",
                "awc_temp_c": None,
                "awc_today_max_c": None,
                "awc_na_reason": "awc_not_in_sequential_checkpoint_chain",
                "reported_x_lower_bound_c": to_float(raw_row[2]),
                "temperature_momentum_effective_c_per_hour": _coalesce_numeric(
                    feature_values.get("trajectory.current_step_rate_c_per_hour"),
                    feature_values.get("trajectory.slope_60m_c_per_hour"),
                ),
                "temperature_momentum_1h_c_per_hour": to_float(
                    feature_values.get("trajectory.slope_60m_c_per_hour")
                ),
                "temperature_momentum_2h_c_per_hour": to_float(
                    feature_values.get("trajectory.slope_120m_c_per_hour")
                ),
                "temperature_momentum_realization_state": str(
                    feature_values.get("trajectory.pre_event_path_state") or ""
                ),
                "cloud_text": str(observation.get("cloud_text") or ""),
                "weather_text": str(observation.get("weather_text") or ""),
                "dewpoint_c": to_float(observation.get("dewpoint_c")),
                "first_cb_valid_time": first_cb_valid_time,
                "first_cb_local_hhmm": first_cb_local_hhmm,
                "first_cb_temperature_c": first_cb_temperature_c,
                "first_cb_event_state": first_cb_event_state,
                "first_cb_timing_phase": first_cb_timing_phase,
                "first_cb_peak_relation": first_cb_peak_relation,
                "first_cb_present_in_current_event": feature_audit.get("physical.cb_present_in_current_event") is True,
                "first_cb_effect": first_cb_effect,
                "first_cb_display": first_cb_display,
                "reported_x_top_temperature_c": top_temperature_c,
                "reported_x_top_probability": top_probability,
                "reported_x_top_probability_pct": top_probability * 100.0,
                "latent_state_probabilities": latent_state_probabilities,
                "latent_top_state": str(top_state.get("state") or ""),
                "latent_top_state_probability": to_float(top_state.get("probability")),
                "strong_lr_scoring_kind": scoring_kind,
                "strong_lr_state_discriminating": None,
                "strong_lr_state_discriminating_na_reason": "reported_x_bucket_combines_multiple_latent_z_cells",
                "strong_lr_top_temperature_state_scores": sorted(
                    top_temperature_state_scores,
                    key=lambda item: str(item.get("state") or ""),
                ),
                "target_bucket": f"{top_temperature_c:.0f}°C",
                "target_probability_pct": top_probability * 100.0,
                "probability_semantics": "amsc_scheduled_regular_metar_reported_daily_max_integer_x",
                "termination_risk": termination_risk,
                "probability_no_material_new_daily_high": to_float(
                    termination_risk.get("probability_no_material_new_daily_high")
                ),
                "market_projection_state": "na",
                "market_projection_na_reason": str(
                    posterior_ssot.get("market_bucket_probabilities_na_reason")
                    or "x_to_s_to_b_bridge_unavailable"
                ),
            }
        )
    if not points:
        return {}
    sampled = _ui_temperature_timeline_sample(
        points,
        UI_SNAPSHOT_TEMPERATURE_TRAJECTORY_TIMELINE_POINTS,
    )
    latest = sampled[-1]
    peak_observed = max(
        (
            float(point["amsc_today_max_c"])
            for point in points
            if to_float(point.get("amsc_today_max_c")) is not None
        ),
        default=None,
    )
    peak_timing = posterior_ssot.get("peak_timing_state")
    peak_timing = dict(peak_timing) if isinstance(peak_timing, Mapping) else {}
    peak_timing_state = {
        "schema": str(peak_timing.get("schema") or "peak_timing_state_l3_v1"),
        "state": str(peak_timing.get("state") or "na"),
        "peak_timing_state_id": str(peak_timing.get("peak_timing_state_id") or ""),
        "mode_time_state": str(peak_timing.get("mode_time_state") or ""),
        "mode_probability": to_float(peak_timing.get("mode_probability")),
        "peak_already_probability": to_float(peak_timing.get("peak_already_probability")),
        "future_peak_probability": to_float(peak_timing.get("future_peak_probability")),
        "entry_peak_at": str(peak_timing.get("entry_peak_at") or ""),
        "entry_peak_local_hhmm": _ui_timeline_local_label(
            peak_timing.get("entry_peak_at"), event_tz
        ),
        "observed_peak_at": str(peak_timing.get("observed_peak_at") or ""),
        "observed_peak_local_hhmm": _ui_timeline_local_label(
            peak_timing.get("observed_peak_at"), event_tz
        ),
        "na_reason": str(
            peak_timing.get("entry_peak_at_na_reason")
            or peak_timing.get("na_reason")
            or ""
        ),
        "does_not_update_physical_x": peak_timing.get("does_not_update_physical_x") is True,
        "source": "posterior_ssot_fact.peak_timing_state",
    }
    second_yes_window: Dict[str, Any] = {
        "state": "na",
        "entry_allowed": False,
        "na_reason": "current_posterior_second_yes_auto_trade_decision_missing",
        "source": "auto_trade_decisions",
        "frontend_recompute_allowed": False,
    }
    try:
        decision_rows = conn.execute(
            """
            SELECT outcome,side,decided_state,will_order,reason_codes_json,details_json,created_at
            FROM auto_trade_decisions
            WHERE slug=? AND event_date=? AND posterior_run_id=?
            ORDER BY id DESC
            LIMIT 64
            """,
            (str(slug or ""), str(event_date or ""), posterior_run_id),
        ).fetchall()
    except sqlite3.Error:
        decision_rows = []
    for decision_row in decision_rows:
        details = safe_json_loads(str(decision_row[5] or ""))
        if not isinstance(details, Mapping):
            continue
        window = details.get("second_yes_entry_window_state")
        if not isinstance(window, Mapping):
            continue
        strategy_leg = str(
            details.get("strategy_leg")
            or details.get("target_realization_v3_role")
            or ""
        )
        if strategy_leg != "second_yes":
            continue
        reason_codes = safe_json_loads_any(str(decision_row[4] or ""))
        reason_code = str(
            details.get("entry_block_reason")
            or window.get("entry_block_reason")
            or (
                reason_codes[0]
                if isinstance(reason_codes, Sequence)
                and not isinstance(reason_codes, (str, bytes, bytearray))
                and reason_codes
                else ""
            )
        )
        second_yes_window = {
            "state": "available",
            "second_yes_entry_window_state_id": str(
                window.get("second_yes_entry_window_state_id") or ""
            ),
            "decision_state": str(decision_row[2] or ""),
            "decision_created_at": str(decision_row[6] or ""),
            "decision_created_local_hhmm": _ui_timeline_local_label(
                decision_row[6], event_tz
            ),
            "bucket": str(decision_row[0] or ""),
            "side": str(decision_row[1] or ""),
            "will_order": int(decision_row[3] or 0) == 1,
            "entry_allowed": window.get("entry_allowed") is True,
            "entry_block_reason": reason_code,
            "predicted_peak_at": str(window.get("predicted_peak_at") or ""),
            "predicted_peak_local_hhmm": _ui_timeline_local_label(
                window.get("predicted_peak_at"), event_tz
            ),
            "entry_window_start_at": str(window.get("entry_window_start_at") or ""),
            "entry_window_start_local_hhmm": _ui_timeline_local_label(
                window.get("entry_window_start_at"), event_tz
            ),
            "entry_window_end_at": str(window.get("entry_window_end_at") or ""),
            "entry_window_end_local_hhmm": _ui_timeline_local_label(
                window.get("entry_window_end_at"), event_tz
            ),
            "entry_window_minutes": int(window.get("entry_window_minutes") or 30),
            "max_notional_usdc": 4.99,
            "strictly_below_5_usdc": True,
            "same_bucket_existing_position_may_be_retained": (
                details.get("same_bucket_existing_position_may_be_retained") is True
                or window.get("existing_same_bucket_position_may_be_retained") is True
            ),
            "source": "auto_trade_decisions.details_json",
            "frontend_recompute_allowed": False,
        }
        break
    return {
        "available": True,
        "version": "sequential_reported_x_temperature_timeline_v3",
        "source": "posterior_checkpoints+canonical_observation_events+strong_observation_updates",
        "probability_semantics": "amsc_scheduled_regular_metar_reported_daily_max_integer_x",
        "boundary": "reported_X_only_not_latent_Z_not_market_B_not_cumulative_edge_bucket",
        "slug": str(slug or ""),
        "event_date": str(event_date or ""),
        "run_date": str(run_date or ""),
        "event_tz": str(event_tz or "Asia/Shanghai"),
        "fact_snapshot_id": fact_snapshot_id,
        "posterior_run_id": posterior_run_id,
        "posterior_checkpoint_id": checkpoint_id,
        "target_bucket": str(latest.get("target_bucket") or ""),
        "rows": sampled,
        "row_count": len(points),
        "sampled_count": len(sampled),
        "truncated": len(points) > len(sampled),
        "primary_source_id": "zuuu_metar_raw_amsc",
        "source_priority": ["zuuu_metar_raw_amsc"],
        "peak_metar_today_max_c": peak_observed,
        "peak_amsc_today_max_c": peak_observed,
        "peak_awc_today_max_c": peak_observed,
        "latest_probability_pct": latest.get("reported_x_top_probability_pct"),
        "latest_reported_x_top_temperature_c": latest.get("reported_x_top_temperature_c"),
        "latest_latent_top_state": latest.get("latent_top_state"),
        "latest_latent_top_state_probability": latest.get("latent_top_state_probability"),
        "latest_first_cb_valid_time": latest.get("first_cb_valid_time"),
        "latest_first_cb_local_hhmm": latest.get("first_cb_local_hhmm"),
        "latest_first_cb_temperature_c": latest.get("first_cb_temperature_c"),
        "latest_first_cb_event_state": latest.get("first_cb_event_state"),
        "latest_first_cb_timing_phase": latest.get("first_cb_timing_phase"),
        "latest_first_cb_peak_relation": latest.get("first_cb_peak_relation"),
        "latest_first_cb_effect": latest.get("first_cb_effect"),
        "latest_first_cb_display": latest.get("first_cb_display"),
        "latest_strong_lr_scoring_kind": latest.get("strong_lr_scoring_kind"),
        "latest_strong_lr_state_discriminating": latest.get("strong_lr_state_discriminating"),
        "peak_timing_state": peak_timing_state,
        "second_yes_entry_window": second_yes_window,
        "reported_x_ssot_freshness": ssot_freshness,
        "probability_display_state": str(
            ssot_freshness.get("probability_display_state") or "unavailable"
        ),
        "probability_current": ssot_freshness.get("probability_current") is True,
        "latest_fact_as_of": latest.get("fact_as_of"),
        "market_projection_state": "na",
        "market_projection_na_reason": str(
            posterior_ssot.get("market_bucket_probabilities_na_reason")
            or "x_to_s_to_b_bridge_unavailable"
        ),
        "frontend_recompute_allowed": False,
    }


def _attach_v6_frozen_probability_layers_for_ui_snapshot(
    conn: sqlite3.Connection,
    payload: MutableMapping[str, Any],
    *,
    event_date: str,
) -> None:
    """Expose the frozen P0 prior and weak likelihood without a UI-side model.

    P0 stores the normalized prior×weak joint.  Dividing its Y marginal by the
    exact immutable weak snapshot reconstructs the frozen prior used by that
    checkpoint; this is a read-only lineage projection, never a new posterior.
    """
    ssot = payload.get("posterior_ssot_fact")
    if not isinstance(ssot, Mapping):
        return
    checkpoint_id = str(ssot.get("posterior_checkpoint_id") or "").strip()
    target_identity = str(
        ssot.get("probability_runtime_identity", {}).get("target_identity") or ""
        if isinstance(ssot.get("probability_runtime_identity"), Mapping)
        else ""
    ).strip() or f"physical_weather_day_v1:ZUUU:{event_date}"

    # The active state-space pipeline persists the official observation update
    # in ``strong_observation_updates``.  Keep this as an explicit, read-only
    # UI fact even though the state-space contract intentionally does not
    # expose a standalone bucket likelihood.  The old UI inferred
    # "likelihood missing" merely because no legacy bucket map was present.
    try:
        strong_update = conn.execute(
            "SELECT * FROM strong_observation_updates "
            "WHERE strong_observation_update_id=? LIMIT 1",
            (str(ssot.get("last_strong_update_id") or "").strip(),),
        ).fetchone() if str(ssot.get("last_strong_update_id") or "").strip() else None
    except sqlite3.Error:
        strong_update = None
    if strong_update is not None:
        update_keys = set(strong_update.keys()) if hasattr(strong_update, "keys") else set()

        def update_value(key: str) -> Any:
            if key not in update_keys:
                return None
            try:
                return strong_update[key]
            except (IndexError, KeyError, TypeError):
                return None

        update_state = str(update_value("state") or "").strip().lower()
        update_event_id = str(update_value("canonical_observation_event_id") or "").strip()
        update_count = to_float(update_value("physical_current_event_consumption_count"))
        likelihood_hash = str(
            update_value("physical_observation_likelihood_sha256")
            or ssot.get("physical_observation_likelihood_sha256")
            or ""
        ).strip()
        pre_state_hash = str(
            update_value("physical_pre_event_state_sha256")
            or ssot.get("physical_pre_event_state_sha256")
            or ""
        ).strip()
        post_state_hash = str(
            update_value("physical_post_event_state_sha256")
            or ssot.get("physical_post_event_state_sha256")
            or ""
        ).strip()
        applied = update_state == "applied"
        artifact_complete = bool(likelihood_hash and post_state_hash)
        payload["observation_update_materialization"] = {
            "schema": "ui_state_space_observation_update_materialization_v1",
            "state": "materialized" if applied and artifact_complete else "pending_artifact",
            "materialized": bool(applied and artifact_complete),
            "strong_observation_update_id": str(
                update_value("strong_observation_update_id")
                or ssot.get("last_strong_update_id")
                or ""
            ),
            "canonical_observation_event_id": update_event_id,
            "consumption_count": int(update_count) if update_count is not None else None,
            "physical_observation_likelihood_sha256": likelihood_hash,
            "physical_pre_event_state_sha256": pre_state_hash,
            "physical_post_event_state_sha256": post_state_hash,
            "started_at": str(update_value("started_at") or ""),
            "completed_at": str(update_value("completed_at") or ""),
            "source": "archive.db.strong_observation_updates",
            "contract": "state_transition_plus_observation_update_no_standalone_bucket_likelihood",
            "frontend_recompute_allowed": False,
        }
    try:
        weak_columns = {
            str(row[1]) for row in conn.execute("PRAGMA table_info(weak_forecast_evidence_snapshots)").fetchall()
        }
        checkpoint_columns = {
            str(row[1]) for row in conn.execute("PRAGMA table_info(posterior_checkpoints)").fetchall()
        }
        optional_columns = (
            "source_revisions_json",
            "forecast_peak_timing_prior_json",
            "forecast_background_context_json",
            "source_expert_trace_json",
            "forecast_multimodality_trace_json",
            "weak_model_diagnostics_json",
            "prior_context_audit_json",
        )
        optional_select = "".join(
            f",w.{column}" for column in optional_columns if column in weak_columns
        )
        # Checkpoint reporting/state columns were added after the first v6
        # archive schema.  They are optional for this read-only projection:
        # the legacy joint-posterior representation below remains sufficient
        # to expose the frozen prior and current weak snapshot.  Selecting a
        # missing column used to abort the whole function, hiding the current
        # weak attribution even though its table was present.
        checkpoint_optional_select = (
            ",p.reported_physical_x_distribution_json AS reported_physical_x_distribution_json,"
            "p.physical_state_posterior_sha256 AS physical_state_posterior_sha256,"
            "p.committed_at AS p0_committed_at"
            if {
                "reported_physical_x_distribution_json",
                "physical_state_posterior_sha256",
                "committed_at",
            }.issubset(checkpoint_columns)
            else ",'' AS reported_physical_x_distribution_json,'' AS physical_state_posterior_sha256,'' AS p0_committed_at"
        )
        # The initial lineage remains the immutable source for reconstructing
        # the frozen prior.  It must not also select the weak layer shown in
        # the UI after a forward-only weak revision.
        prior_lineage = conn.execute(
            "SELECT l.posterior_checkpoint_id,l.prior_context_id,l.prior_artifact_sha256,"
            "l.forecast_evidence_snapshot_id,l.weak_likelihood_sha256,"
            "p.joint_posterior_json"
            + checkpoint_optional_select
            + ",w.likelihood_by_x_json,w.source_set_key,"
            "w.source_revision_ids_json,w.created_at "
            + optional_select +
            " FROM production_initial_posterior_lineage l "
            "JOIN posterior_checkpoints p ON p.posterior_checkpoint_id=l.posterior_checkpoint_id "
            "JOIN weak_forecast_evidence_snapshots w "
            "ON w.forecast_evidence_snapshot_id=l.forecast_evidence_snapshot_id "
            "WHERE l.target_identity=? "
            "ORDER BY l.created_at DESC LIMIT 1",
            (target_identity,),
        ).fetchone()
        current_weak_id = str(ssot.get("forecast_evidence_snapshot_id") or "").strip()
        if not current_weak_id and checkpoint_id:
            current_checkpoint = conn.execute(
                "SELECT forecast_evidence_snapshot_id FROM posterior_checkpoints "
                "WHERE posterior_checkpoint_id=? LIMIT 1",
                (checkpoint_id,),
            ).fetchone()
            if current_checkpoint is not None:
                current_weak_id = str(current_checkpoint[0] or "").strip()
        weak_lineage = conn.execute(
            "SELECT w.forecast_evidence_snapshot_id,w.weak_likelihood_sha256,"
            "w.likelihood_by_x_json,w.source_set_key,w.source_revision_ids_json,w.created_at "
            + optional_select + " FROM weak_forecast_evidence_snapshots w "
            "WHERE w.forecast_evidence_snapshot_id=? LIMIT 1",
            (current_weak_id,),
        ).fetchone() if current_weak_id else None
    except sqlite3.Error:
        return
    if prior_lineage is None:
        # No initial lineage is a real data-quality issue, but do not turn a
        # valid successor chain into a false "prior missing" banner.  The
        # immediately preceding checkpoint is an explicit previous-state
        # reference, not an invented prior; label it as such below.
        try:
            previous_row = conn.execute(
                "SELECT previous_checkpoint_id FROM posterior_checkpoints "
                "WHERE posterior_checkpoint_id=? LIMIT 1",
                (checkpoint_id,),
            ).fetchone()
            previous_id = str(previous_row[0] or "") if previous_row is not None else ""
            if previous_id:
                previous_checkpoint = conn.execute(
                    "SELECT posterior_checkpoint_id,reported_physical_x_distribution_json,"
                    "physical_state_posterior_sha256,committed_at "
                    "FROM posterior_checkpoints WHERE posterior_checkpoint_id=? LIMIT 1",
                    (previous_id,),
                ).fetchone()
            else:
                previous_checkpoint = None
        except sqlite3.Error:
            previous_checkpoint = None
        previous_distribution = (
            safe_json_loads_any(str(previous_checkpoint[1] or ""))
            if previous_checkpoint is not None
            else None
        )
        if isinstance(previous_distribution, Mapping) and previous_distribution:
            payload["prior_distribution"] = dict(previous_distribution)
            payload["prior_meta"] = {
                "source": "archive.db.posterior_checkpoints.previous_checkpoint.reported_physical_x_distribution_json",
                "source_kind": "previous_checkpoint_state",
                "checkpoint_id": str(previous_checkpoint[0] or ""),
                "physical_state_posterior_sha256": str(previous_checkpoint[2] or ""),
                "as_of": str(previous_checkpoint[3] or ""),
                "prior_semantics": "previous_state_reference_not_initial_P0_prior",
                "read_only": True,
                "frontend_recompute_allowed": False,
            }
            payload["prior_na_reason"] = ""
        else:
            payload["prior_na_reason"] = "initial_p0_lineage_and_previous_checkpoint_missing"
        return
    prior_weak_raw = safe_json_loads(str(prior_lineage["likelihood_by_x_json"] or "{}"))
    try:
        joint_raw = json.loads(str(prior_lineage["joint_posterior_json"] or "[]"))
    except (TypeError, ValueError):
        joint_raw = []
    # P0 in the active state-space epoch is a persisted Gaussian-mixture
    # artifact, not the retired list of joint cells.  Prefer its persisted X
    # reporting distribution; only retain the list division path for old
    # archive rows that genuinely use that representation.
    p0_distribution = safe_json_loads_any(
        str(prior_lineage["reported_physical_x_distribution_json"] or "")
    )
    if isinstance(p0_distribution, Mapping) and p0_distribution:
        payload["prior_distribution"] = {
            f"{float(key):g}°C": float(value)
            for key, value in p0_distribution.items()
            if to_float(key) is not None
            and to_float(value) is not None
            and math.isfinite(float(value))
            and float(value) >= 0.0
        }
        payload["prior_meta"] = {
            "prior_context_id": str(prior_lineage["prior_context_id"] or ""),
            "prior_artifact_sha256": str(prior_lineage["prior_artifact_sha256"] or ""),
            "p0_checkpoint_id": str(prior_lineage["posterior_checkpoint_id"] or ""),
            "p0_physical_state_posterior_sha256": str(
                prior_lineage["physical_state_posterior_sha256"] or ""
            ),
            "as_of": str(prior_lineage["p0_committed_at"] or ""),
            "source": "archive.db.posterior_checkpoints.reported_physical_x_distribution_json",
            "source_kind": "persisted_state_space_p0",
            "prior_semantics": "P0_state_space_pre_official_observation_distribution",
            "derivation": "persisted_reporting_operator_projection_no_ui_recompute",
            "read_only": True,
            "frontend_recompute_allowed": False,
        }
        payload["prior_na_reason"] = ""
    elif not isinstance(prior_weak_raw, Mapping) or not isinstance(joint_raw, list):
        payload["prior_na_reason"] = "p0_distribution_artifact_unavailable"
        return
    prior_weak = {
        float(key): float(value)
        for key, value in prior_weak_raw.items()
        if to_float(key) is not None and to_float(value) is not None and float(value) > 0.0
    }
    marginal: Dict[float, float] = {}
    for cell in joint_raw:
        if not isinstance(cell, Mapping):
            continue
        y = to_float(cell.get("continuous_y_c"))
        probability = to_float(cell.get("probability"))
        if y is None or probability is None or probability <= 0.0:
            continue
        marginal[float(y)] = marginal.get(float(y), 0.0) + float(probability)
    prior_unnormalized = {
        y: mass / prior_weak[y]
        for y, mass in marginal.items()
        if y in prior_weak and prior_weak[y] > 0.0
    }
    prior_total = sum(prior_unnormalized.values())
    weak_raw = safe_json_loads(str(weak_lineage["likelihood_by_x_json"] or "{}")) if weak_lineage else {}
    weak = {
        float(key): float(value)
        for key, value in weak_raw.items()
        if to_float(key) is not None and to_float(value) is not None and float(value) > 0.0
    } if isinstance(weak_raw, Mapping) else {}
    if weak and weak_lineage is not None:
        payload["forecast_weak_likelihood"] = {
            f"{temperature_c:g}°C": probability
            for temperature_c, probability in weak.items()
        }
        payload["forecast_weak_attribution"] = {
            "forecast_evidence_snapshot_id": str(weak_lineage["forecast_evidence_snapshot_id"] or ""),
            "weak_likelihood_sha256": str(weak_lineage["weak_likelihood_sha256"] or ""),
            "source_set_key": str(weak_lineage["source_set_key"] or ""),
            "source_revision_ids": safe_json_loads_any(str(weak_lineage["source_revision_ids_json"] or "[]")),
            "created_at": str(weak_lineage["created_at"] or ""),
            "source": "archive.db.weak_forecast_evidence_snapshots.likelihood_by_x_json",
            "frontend_recompute_allowed": False,
        }
        attribution = payload["forecast_weak_attribution"]
        for column, key, empty in (
            ("source_revisions_json", "source_revisions", []),
            ("forecast_peak_timing_prior_json", "forecast_peak_timing_prior", {}),
            ("forecast_background_context_json", "forecast_background_context", {}),
            ("source_expert_trace_json", "source_expert_trace", []),
            ("forecast_multimodality_trace_json", "forecast_multimodality_trace", {}),
            ("weak_model_diagnostics_json", "weak_model_diagnostics", {}),
            ("prior_context_audit_json", "prior_context_audit", {}),
        ):
            if column not in weak_columns:
                attribution[f"{key}_na_reason"] = "archive_schema_column_not_installed"
                continue
            parsed = safe_json_loads_any(str(weak_lineage[column] or ("[]" if isinstance(empty, list) else "{}")))
            if isinstance(parsed, type(empty)) and parsed:
                attribution[key] = parsed
            else:
                attribution[f"{key}_na_reason"] = "historical_snapshot_did_not_persist_field"
    if prior_total > 0.0 and not payload.get("prior_distribution"):
        payload["prior_distribution"] = {
            f"{temperature_c:g}°C": mass / prior_total
            for temperature_c, mass in prior_unnormalized.items()
        }
        payload["prior_meta"] = {
            "prior_context_id": str(prior_lineage["prior_context_id"] or ""),
            "prior_artifact_sha256": str(prior_lineage["prior_artifact_sha256"] or ""),
            "p0_checkpoint_id": str(prior_lineage["posterior_checkpoint_id"] or ""),
            "source": "archive.db.posterior_checkpoints.P0_joint_div_frozen_weak",
            "derivation": "normalized_marginal_P0_Y_div_exact_weak_snapshot",
            "read_only": True,
            "frontend_recompute_allowed": False,
        }
        prior_audit = payload.get("forecast_weak_attribution", {}).get("prior_context_audit")
        if isinstance(prior_audit, Mapping) and prior_audit:
            payload["prior_meta"]["climate_background"] = copy.deepcopy(prior_audit)
            payload["prior_meta"]["climate_background_na_reason"] = ""
        else:
            payload["prior_meta"]["climate_background_na_reason"] = str(
                payload.get("forecast_weak_attribution", {}).get("prior_context_audit_na_reason")
                or "prior_context_audit_not_persisted"
            )


def _compact_v6_probability_distribution(raw: Any, *, limit: int = 6) -> List[Dict[str, Any]]:
    value = safe_json_loads(str(raw or "{}")) if isinstance(raw, str) else raw
    rows: List[Dict[str, Any]] = []
    if isinstance(value, Mapping):
        for label, probability in value.items():
            number = to_float(probability)
            if number is not None and math.isfinite(float(number)):
                rows.append({"label": str(label), "probability": float(number), "probability_pct": float(number) * 100.0})
    rows.sort(key=lambda row: (-float(row["probability"]), str(row["label"])))
    return rows[: max(0, int(limit))]


def _attach_v6_probability_audit_for_ui_snapshot(
    conn: sqlite3.Connection,
    payload: MutableMapping[str, Any],
    *,
    event_date: str,
) -> None:
    """Build a read-only probability-chain audit from persisted archive facts."""
    if not event_date:
        return
    target = f"physical_weather_day_v1:ZUUU:{event_date}"
    attribution = payload.get("forecast_weak_attribution")
    attribution_map = attribution if isinstance(attribution, Mapping) else {}
    source_revisions = attribution_map.get("source_revisions")
    expert_trace = attribution_map.get("source_expert_trace")
    expert_by_identity = {
        (str(row.get("source_id") or ""), str(row.get("source_revision_id") or "")): row
        for row in expert_trace or []
        if isinstance(row, Mapping)
    }
    weak_sources: List[Dict[str, Any]] = []
    for raw in source_revisions or []:
        if not isinstance(raw, Mapping):
            continue
        identity = (str(raw.get("source_id") or ""), str(raw.get("source_revision_id") or ""))
        expert = expert_by_identity.get(identity, {})
        weak_sources.append(
            {
                key: value
                for key, value in {
                    "source_id": identity[0],
                    "source_revision_id": identity[1],
                    "available_at": raw.get("available_at"),
                    "forecast_peak_c": raw.get("forecast_peak_c"),
                    "forecast_peak_valid_time": raw.get("forecast_peak_valid_time"),
                    "forecast_weather_regime": raw.get("forecast_weather_regime") or "unknown",
                    "forecast_weather_regime_origin": raw.get("forecast_weather_regime_origin"),
                    "calibration_bias_c": expert.get("calibration_bias_c"),
                    "calibrated_mean_c": expert.get("calibrated_mean_c"),
                    "calibrated_sigma_c": expert.get("calibrated_sigma_c"),
                    "bias_level": expert.get("bias_level"),
                    "bias_sample_count": expert.get("bias_sample_count"),
                    "information_weight": expert.get("information_weight"),
                    "base_information_weight": expert.get("base_information_weight"),
                    "family_information_cap": expert.get("family_information_cap"),
                    "family_raw_information_weight": expert.get("family_raw_information_weight"),
                    "family_cap_scale": expert.get("family_cap_scale"),
                    "family_capped_information_weight": expert.get("family_capped_information_weight"),
                    "normalized_information_share": expert.get("normalized_information_share"),
                    "correlation_discount": expert.get("correlation_discount"),
                    "joint_information_scale": expert.get("joint_information_scale"),
                    "final_information_index": expert.get("final_information_index"),
                    "provider_family": expert.get("provider_family"),
                    "future_forcing_available": expert.get("future_forcing_available"),
                    "source_modes_schema": expert.get("source_modes_schema") or raw.get("source_modes_schema"),
                    "source_mode_count": expert.get("source_mode_count"),
                    "source_modes": expert.get("source_modes") or raw.get("source_modes"),
                    "cloud_cover_pct": raw.get("cloud_cover_pct"),
                    "precipitation_mm": raw.get("precipitation_mm"),
                    "convective_precipitation_mm": raw.get("convective_precipitation_mm"),
                    "boundary_layer_height_m": raw.get("boundary_layer_height_m"),
                    "calibration_na_reason": "" if expert else str(
                        attribution_map.get("source_expert_trace_na_reason")
                        or "source_expert_trace_not_persisted"
                    ),
                }.items()
                if value not in (None, "", [], {}) or key.endswith("_na_reason")
            }
        )

    newer_weak_revisions: List[Dict[str, Any]] = []
    snapshot_as_of = str(attribution_map.get("created_at") or "")
    consumed_revision_ids = {
        str(value or "") for value in attribution_map.get("source_revision_ids") or [] if str(value or "")
    }
    try:
        newer_rows = conn.execute(
            """
            SELECT source_id,source_event_id,forecast_peak_c,valid_time,fetched_at,
                   response_completed_at,observation_json
            FROM source_observations
            WHERE event_date=? AND source_class='forecast_weak_source'
              AND datetime(COALESCE(response_completed_at,fetched_at,created_at)) > datetime(?)
            ORDER BY datetime(COALESCE(response_completed_at,fetched_at,created_at)) DESC LIMIT 20
            """,
            (event_date, snapshot_as_of),
        ).fetchall() if snapshot_as_of else []
        for row in newer_rows:
            revision_id = str(row["source_event_id"] or "")
            if revision_id in consumed_revision_ids:
                continue
            source_id = str(row["source_id"] or "").lower()
            if "taf" in source_id:
                source_id = "taf"
            newer_weak_revisions.append(
                {
                    "source_id": source_id,
                    "source_revision_id": revision_id,
                    "forecast_peak_c": row["forecast_peak_c"],
                    "forecast_peak_valid_time": str(row["valid_time"] or ""),
                    "available_at": str(row["response_completed_at"] or row["fetched_at"] or ""),
                }
            )
    except sqlite3.Error:
        newer_weak_revisions = []

    observation_rows: List[Dict[str, Any]] = []
    try:
        rows = conn.execute(
            """
            SELECT c.canonical_observation_event_id,c.report_type,c.valid_time,c.accepted_at,
                   c.selected_source_id,c.parsed_observation_json,c.quality_flags_json,
                   s.source_observation_id,s.raw_ref,s.fetched_at
            FROM canonical_observation_events c
            LEFT JOIN source_observations s
              ON s.source_observation_id=c.selected_source_observation_id
              OR s.source_event_id=c.selected_source_observation_id
            WHERE c.target_identity=? AND c.state IN ('accepted_primary','accepted_substitute','confirmed')
            ORDER BY datetime(c.valid_time) DESC,c.revision_no DESC LIMIT 12
            """,
            (target,),
        ).fetchall()
        for row in rows:
            parsed = safe_json_loads(str(row["parsed_observation_json"] or "{}"))
            observation_rows.append(
                {
                    "canonical_observation_event_id": str(row["canonical_observation_event_id"] or ""),
                    "report_type": str(row["report_type"] or ""),
                    "source_id": str(row["selected_source_id"] or ""),
                    "valid_time": str(row["valid_time"] or ""),
                    "accepted_at": str(row["accepted_at"] or ""),
                    "fetched_at": str(row["fetched_at"] or ""),
                    "temperature_c": parsed.get("temperature_c"),
                    "dewpoint_c": parsed.get("dewpoint_c"),
                    "weather_text": str(parsed.get("weather_text") or ""),
                    "cloud_text": str(parsed.get("cloud_text") or ""),
                    "visibility_m": parsed.get("visibility_m"),
                    "pressure_hpa": parsed.get("pressure_hpa"),
                    "raw_report": str(row["raw_ref"] or "")[:360],
                }
            )
    except sqlite3.Error:
        observation_rows = []

    history: List[Dict[str, Any]] = []
    try:
        strong_columns = {
            str(column[1] or "")
            for column in conn.execute("PRAGMA table_info(strong_observation_updates)").fetchall()
        }
        emission_select = (
            "u.observation_emission_json"
            if "observation_emission_json" in strong_columns
            else "NULL AS observation_emission_json"
        )
        auxiliary_select = (
            "u.path_auxiliary_json"
            if "path_auxiliary_json" in strong_columns
            else "NULL AS path_auxiliary_json"
        )
        checkpoint_columns = {
            str(column[1] or "")
            for column in conn.execute("PRAGMA table_info(posterior_checkpoints)").fetchall()
        }
        scenario_checkpoint_select = ",".join(
            f"p.{column}" if column in checkpoint_columns else f"NULL AS {column}"
            for column in (
                "scenario_joint_posterior_sha256", "scenario_joint_schema",
                "scenario_joint_forcing_generation_sha256",
            )
        )
        emission_join = (
            "LEFT JOIN strong_observation_updates u "
            "ON u.strong_observation_update_id=p.last_strong_update_id"
            if {"observation_emission_json", "path_auxiliary_json"} & strong_columns
            else ""
        )
        checkpoint_rows = conn.execute(
            f"""
            SELECT p.posterior_checkpoint_id,p.posterior_run_id,p.checkpoint_kind,p.last_canonical_event_id,
                   p.last_strong_update_id,p.reported_physical_x_distribution_json,p.latent_post_state_json,
                   p.reported_x_lower_bound_c,p.committed_at,{emission_select},{auxiliary_select},
                   {scenario_checkpoint_select}
            FROM posterior_checkpoints p
            {emission_join}
            WHERE p.target_identity=? AND p.state='committed'
            ORDER BY datetime(p.committed_at) DESC,p.rowid DESC LIMIT 12
            """,
            (target,),
        ).fetchall()[::-1]
        previous: Dict[str, float] = {}
        for row in checkpoint_rows:
            distribution_raw = safe_json_loads(str(row["reported_physical_x_distribution_json"] or "{}"))
            current = {
                str(key): float(value)
                for key, value in distribution_raw.items()
                if isinstance(distribution_raw, Mapping) and to_float(value) is not None
            }
            ranked = _compact_v6_probability_distribution(current, limit=5)
            delta_rows = [
                {
                    "label": key,
                    "delta": current.get(key, 0.0) - previous.get(key, 0.0),
                    "delta_pct_points": (current.get(key, 0.0) - previous.get(key, 0.0)) * 100.0,
                }
                for key in set(current) | set(previous)
            ] if previous else []
            delta_rows.sort(key=lambda item: (-abs(float(item["delta"])), str(item["label"])))
            latent = _compact_v6_probability_distribution(row["latent_post_state_json"], limit=4)
            emission = safe_json_loads(str(row["observation_emission_json"] or "{}"))
            bucket_evidence = (
                emission.get("bucket_observation_evidence")
                if isinstance(emission, Mapping)
                and isinstance(emission.get("bucket_observation_evidence"), Mapping)
                else {}
            )
            evidence_rows = (
                [dict(item) for item in bucket_evidence.get("rows") or [] if isinstance(item, Mapping)]
                if isinstance(bucket_evidence, Mapping)
                else []
            )
            feature_trace = (
                dict(emission.get("observation_feature_trace"))
                if isinstance(emission, Mapping)
                and isinstance(emission.get("observation_feature_trace"), Mapping)
                else {}
            )
            path_auxiliary = safe_json_loads(str(row["path_auxiliary_json"] or "{}"))
            scenario_responsibility_trace = (
                dict(path_auxiliary.get("event_local_scenario_responsibility_trace"))
                if isinstance(path_auxiliary, Mapping)
                and isinstance(path_auxiliary.get("event_local_scenario_responsibility_trace"), Mapping)
                else {}
            )
            history.append(
                {
                    "posterior_checkpoint_id": str(row["posterior_checkpoint_id"] or ""),
                    "posterior_run_id": str(row["posterior_run_id"] or ""),
                    "checkpoint_kind": str(row["checkpoint_kind"] or ""),
                    "committed_at": str(row["committed_at"] or ""),
                    "canonical_observation_event_id": str(row["last_canonical_event_id"] or ""),
                    "strong_observation_update_id": str(row["last_strong_update_id"] or ""),
                    "reported_x_lower_bound_c": row["reported_x_lower_bound_c"],
                    "top_temperature": ranked[0] if ranked else {},
                    "top_temperature_distribution": ranked,
                    "top_state_distribution": latent,
                    "largest_probability_changes": delta_rows[:5],
                    "change_na_reason": "" if previous else "initial_checkpoint_has_no_previous_checkpoint",
                    "observation_bucket_evidence": dict(bucket_evidence) if bucket_evidence else {},
                    "observation_bucket_evidence_rows": evidence_rows,
                    "observation_bucket_evidence_na_reason": (
                        "" if evidence_rows
                        else "historical_strong_update_did_not_persist_bucket_component_trace"
                    ),
                    "observation_feature_trace": feature_trace,
                    "event_local_scenario_responsibility_trace": scenario_responsibility_trace,
                    "event_local_scenario_responsibility_trace_na_reason": (
                        "" if scenario_responsibility_trace
                        else "historical_strong_update_did_not_persist_scenario_responsibility_trace"
                    ),
                    "scenario_joint_checkpoint": {
                        "schema": str(row["scenario_joint_schema"] or ""),
                        "sha256": str(row["scenario_joint_posterior_sha256"] or ""),
                        "forcing_generation_sha256": str(row["scenario_joint_forcing_generation_sha256"] or ""),
                        "persistent_across_events": bool(row["scenario_joint_posterior_sha256"]),
                    },
                }
            )
            previous = current
    except sqlite3.Error:
        history = []

    posterior_ssot = payload.get("posterior_ssot_fact")
    ssot_map = posterior_ssot if isinstance(posterior_ssot, Mapping) else {}
    try:
        strong_update = conn.execute(
            "SELECT * FROM strong_observation_updates "
            "WHERE strong_observation_update_id=? LIMIT 1",
            (str(ssot_map.get("last_strong_update_id") or "").strip(),),
        ).fetchone() if str(ssot_map.get("last_strong_update_id") or "").strip() else None
    except sqlite3.Error:
        strong_update = None
    compact_ssot = _compact_posterior_ssot_fact_for_ui_snapshot(ssot_map)
    checkpoint_lineage: Dict[str, Any] = {}
    try:
        checkpoint_columns = {
            str(column[1] or "")
            for column in conn.execute("PRAGMA table_info(posterior_checkpoints)").fetchall()
        }
        lineage_fields = [
            "posterior_checkpoint_id",
            "previous_checkpoint_id",
            "prior_context_id",
            "state_space_schema",
            "physical_state_posterior_schema",
            "physical_state_posterior_sha256",
            "physical_pre_event_state_sha256",
            "physical_observation_likelihood_sha256",
            "physical_post_event_state_sha256",
            "physical_weak_advance_json",
            "physical_last_weak_advance_json",
            "physical_weak_advance_sha256",
            "physical_last_weak_advance_sha256",
            "physical_forcing_rebind_json",
            "physical_forcing_rebind_sha256",
            "physical_path_projection_json",
            "physical_path_projection_sha256",
            "physical_state_model_artifact_sha256",
            "physical_observation_artifact_sha256",
            "physical_reporting_operator_sha256",
            "physical_driver_generation_sha256",
            "physical_state_reference_valid_at",
            "last_event_valid_at",
            "last_canonical_event_id",
            "reported_x_lower_bound_c",
            "reported_x_projection_sha256",
            "consumed_event_ids_json",
            "committed_at",
        ]
        selected_fields = [field for field in lineage_fields if field in checkpoint_columns]
        if selected_fields:
            checkpoint_row = conn.execute(
                f"SELECT {','.join(selected_fields)} FROM posterior_checkpoints "
                "WHERE target_identity=? AND state='committed' "
                "ORDER BY datetime(committed_at) DESC,rowid DESC LIMIT 1",
                (target,),
            ).fetchone()
            if checkpoint_row is not None:
                checkpoint_raw = {
                    key: checkpoint_row[key]
                    for key in selected_fields
                    if checkpoint_row[key] not in (None, "", [], {})
                }
                if checkpoint_raw.get("state_space_schema") and not checkpoint_raw.get("physical_state_posterior_schema"):
                    checkpoint_raw["physical_state_posterior_schema"] = checkpoint_raw["state_space_schema"]
                if checkpoint_raw.get("physical_weak_advance_sha256") is None:
                    checkpoint_raw["physical_weak_advance_sha256"] = checkpoint_raw.get("physical_last_weak_advance_sha256")
                # ``consumed_event_ids_json`` is a JSON array.  Parsing it as
                # an object silently produced ``{}`` and made an applied
                # official observation look unconsumed in the UI.
                consumed_ids = safe_json_loads_any(str(checkpoint_raw.get("consumed_event_ids_json") or "[]"))
                last_event_id = str(checkpoint_raw.get("last_canonical_event_id") or "")
                if strong_update is not None:
                    update_event_id = str(strong_update["canonical_observation_event_id"] or "")
                    update_count = to_float(strong_update["physical_current_event_consumption_count"])
                    if update_event_id and update_event_id == last_event_id:
                        checkpoint_raw["physical_current_event_consumption_count"] = (
                            int(update_count) if update_count is not None else 1
                        )
                        checkpoint_raw["physical_observation_likelihood_sha256"] = str(
                            strong_update["physical_observation_likelihood_sha256"] or ""
                        )
                        checkpoint_raw["physical_pre_event_state_sha256"] = str(
                            strong_update["physical_pre_event_state_sha256"] or ""
                        )
                        checkpoint_raw["physical_post_event_state_sha256"] = str(
                            strong_update["physical_post_event_state_sha256"] or ""
                        )
                checkpoint_raw["current_observation_consumed_once"] = bool(
                    last_event_id and isinstance(consumed_ids, list) and last_event_id in {str(value) for value in consumed_ids}
                )
                checkpoint_raw["current_observation_consumed"] = checkpoint_raw["current_observation_consumed_once"]
                if checkpoint_raw.get("physical_current_event_consumption_count") in (None, ""):
                    checkpoint_raw["physical_current_event_consumption_count"] = (
                        1 if checkpoint_raw["current_observation_consumed_once"] else 0
                    )
                checkpoint_raw["forecast_revision_used_as_likelihood"] = False
                checkpoint_raw["nwp_hourly_path_likelihood_reapplied"] = False
                checkpoint_lineage = _build_ui_snapshot_state_space_lineage(checkpoint_raw)
    except (sqlite3.Error, TypeError, ValueError):
        checkpoint_lineage = {}
    state_space_lineage = checkpoint_lineage or _build_ui_snapshot_state_space_lineage(compact_ssot)
    if state_space_lineage:
        payload["state_space_lineage"] = state_space_lineage
    weak_diagnostics = dict(attribution_map.get("weak_model_diagnostics") or {})
    source_weight_attribution = (
        dict(weak_diagnostics.get("source_weight_attribution"))
        if isinstance(weak_diagnostics.get("source_weight_attribution"), Mapping)
        else {}
    )
    weak_model_payload: Dict[str, Any] = {
        "forecast_evidence_snapshot_id": attribution_map.get("forecast_evidence_snapshot_id"),
        "weak_likelihood_sha256": attribution_map.get("weak_likelihood_sha256"),
        "source_set_key": attribution_map.get("source_set_key"),
        "snapshot_as_of": snapshot_as_of,
        "snapshot_state": "stale_newer_revision_not_consumed" if newer_weak_revisions else "current_as_of_archive",
        "newer_source_revisions": newer_weak_revisions,
        "newer_source_revisions_na_reason": "" if newer_weak_revisions else "no_newer_archived_revision_detected",
        "source_rows": weak_sources,
        "source_rows_na_reason": "" if weak_sources else "source_revisions_not_persisted",
        "multimodality": dict(attribution_map.get("forecast_multimodality_trace") or {}),
        "multimodality_na_reason": str(attribution_map.get("forecast_multimodality_trace_na_reason") or ""),
        "diagnostics": weak_diagnostics,
        "diagnostics_na_reason": str(attribution_map.get("weak_model_diagnostics_na_reason") or ""),
        "source_weight_attribution": source_weight_attribution,
        "source_weight_attribution_na_reason": (
            "" if source_weight_attribution
            else "source_weight_attribution_not_persisted_in_weak_snapshot"
        ),
    }
    if state_space_lineage:
        # The active state-space contract has no standalone temperature
        # likelihood contribution.  Keep the legacy trace identifiable but
        # prevent the UI from presenting it as an input to the active SSOT.
        weak_model_payload = {
            "mode": "state_transition_forcing",
            "snapshot_as_of": snapshot_as_of,
            "source_rows": [],
            "source_rows_na_reason": "active_state_space_does_not_use_forecast_revision_as_temperature_likelihood",
            "state_space_lineage": state_space_lineage,
            "forecast_revision_used_as_likelihood": compact_ssot.get("forecast_revision_used_as_likelihood", False),
        }
    payload["probability_audit"] = {
        "schema": "ui_probability_chain_audit_v1",
        "state": "available" if ssot_map else "missing",
        "read_only": True,
        "source": "archive.db weak snapshots+canonical observations+posterior checkpoints",
        "frontend_recompute_allowed": False,
        "target_identity": target,
        "event_date": event_date,
        "as_of": str(ssot_map.get("committed_at") or payload.get("fact_as_of") or ""),
        "prior_context": dict(payload.get("prior_meta") or {}),
        "observation_update_materialization": dict(
            payload.get("observation_update_materialization") or {}
        ),
        "weak_model": weak_model_payload,
        "forecast_regime": dict(attribution_map.get("forecast_background_context") or {}),
        "forecast_regime_na_reason": str(attribution_map.get("forecast_background_context_na_reason") or ""),
        "peak_window": dict(ssot_map.get("peak_timing_state") or attribution_map.get("forecast_peak_timing_prior") or {}),
        "peak_window_na_reason": "" if (ssot_map.get("peak_timing_state") or attribution_map.get("forecast_peak_timing_prior")) else "peak_timing_state_missing",
        "observations": observation_rows,
        "observations_na_reason": "" if observation_rows else "canonical_observation_events_missing",
        "posterior_history": history,
        "posterior_history_na_reason": "" if history else "posterior_checkpoints_missing",
        "na_reason": "" if ssot_map else "posterior_ssot_fact_missing",
    }
    if state_space_lineage:
        payload["probability_audit"]["state_space_lineage"] = state_space_lineage


def _attach_v6_source_to_posterior_timing_for_ui_snapshot(
    conn: sqlite3.Connection,
    payload: MutableMapping[str, Any],
    *,
    event_date: str,
) -> None:
    """Join the latest canonical AMSC event through checkpoint and decision.

    This is a read-only archive projection.  Every duration is calculated on
    the server from persisted timestamps and shipped as one UI snapshot fact.
    """
    if not event_date:
        return
    target_identity = f"physical_weather_day_v1:ZUUU:{event_date}"
    try:
        chain = conn.execute(
            """
            SELECT
                c.canonical_observation_event_id,c.selected_source_observation_id,
                c.selected_source_id,c.valid_time,c.first_transport_seen_at,
                c.first_actionable_seen_at,c.accepted_at,c.parsed_observation_json,
                u.strong_observation_update_id,u.started_at AS update_started_at,
                u.completed_at AS update_completed_at,
                p.posterior_checkpoint_id,p.posterior_run_id,p.committed_at
            FROM canonical_observation_events c
            JOIN strong_observation_updates u
              ON u.canonical_observation_event_id=c.canonical_observation_event_id
             AND u.state='applied'
            JOIN posterior_checkpoints p
              ON p.last_strong_update_id=u.strong_observation_update_id
             AND p.state='committed'
            WHERE c.target_identity=?
              AND c.state LIKE 'accepted%'
            ORDER BY datetime(p.committed_at) DESC,p.rowid DESC
            LIMIT 1
            """,
            (target_identity,),
        ).fetchone()
    except sqlite3.Error:
        return
    if chain is None:
        return

    def chain_text(key: str) -> str:
        try:
            return str(chain[key] or "").strip()
        except (IndexError, KeyError, TypeError):
            return ""

    canonical_event_id = chain_text("canonical_observation_event_id")
    checkpoint_id = chain_text("posterior_checkpoint_id")
    posterior_run_id = chain_text("posterior_run_id")
    update_id = chain_text("strong_observation_update_id")
    accepted_at = chain_text("accepted_at")
    checkpoint_committed_at = chain_text("committed_at")
    public_fact_written_at = ""
    public_fact_snapshot_id = ""
    try:
        public_fact = conn.execute(
            """
            SELECT fact_as_of,
                   json_extract(fact_json,'$.posterior_ssot_fact.fact_snapshot_id') AS fact_snapshot_id
            FROM event_fact_history
            WHERE event_date=?
              AND (
                json_extract(fact_json,'$.posterior_ssot_fact.posterior_checkpoint_id')=?
                OR json_extract(fact_json,'$.posterior_ssot_fact.last_canonical_event_id')=?
              )
            ORDER BY datetime(fact_as_of) ASC,id ASC
            LIMIT 1
            """,
            (event_date, checkpoint_id, canonical_event_id),
        ).fetchone()
        if public_fact is not None:
            public_fact_written_at = str(public_fact["fact_as_of"] or "").strip()
            public_fact_snapshot_id = str(public_fact["fact_snapshot_id"] or "").strip()
    except sqlite3.Error:
        pass

    decision_at = ""
    decision_id = ""
    decision_action = ""
    decision_state = ""
    try:
        decision = conn.execute(
            """
            SELECT decision_id,action,decided_state,created_at
            FROM auto_trade_decisions
            WHERE event_date=?
              AND (correlation_id=? OR posterior_run_id=?)
            ORDER BY datetime(created_at) ASC,id ASC
            LIMIT 1
            """,
            (event_date, update_id, posterior_run_id),
        ).fetchone()
        if decision is not None:
            decision_at = str(decision["created_at"] or "").strip()
            decision_id = str(decision["decision_id"] or "").strip()
            decision_action = str(decision["action"] or "").strip()
            decision_state = str(decision["decided_state"] or "").strip()
    except sqlite3.Error:
        pass

    parsed = safe_json_loads(chain_text("parsed_observation_json"))
    valid_time = chain_text("valid_time")
    fetched_at = chain_text("first_transport_seen_at")
    update_started_at = chain_text("update_started_at")
    update_completed_at = chain_text("update_completed_at") or checkpoint_committed_at
    source_id = chain_text("selected_source_id")
    source_observation_id = chain_text("selected_source_observation_id")
    timing: Dict[str, Any] = {
        "schema": "v6_source_to_posterior_timing_ssot_v1",
        "state": "available",
        "state_reason": "latest_committed_v6_canonical_chain",
        "surface": "production_probability_v6",
        "source": (
            "archive.db.canonical_observation_events+strong_observation_updates+"
            "posterior_checkpoints+event_fact_history+auto_trade_decisions"
        ),
        "source_provider": "AMSC",
        "source_kind": "canonical_hard_observation",
        "latest_source_id": source_id,
        "slug": str(payload.get("slug") or ""),
        "event_date": event_date,
        "latest_source_valid_time": valid_time,
        "latest_source_response_completed_at": fetched_at,
        "latest_source_fact_as_of": accepted_at,
        "canonical_event_accepted_at": accepted_at,
        "posterior_apply_started_at": update_started_at,
        "posterior_apply_completed_at": update_completed_at,
        "checkpoint_committed_at": checkpoint_committed_at,
        "public_fact_written_at": public_fact_written_at,
        "decision_written_at": decision_at,
        "latest_source_event_id": canonical_event_id,
        "latest_source_observation_id": source_observation_id,
        "source_event_ids": [canonical_event_id] if canonical_event_id else [],
        "source_observation_ids": [source_observation_id] if source_observation_id else [],
        "strong_observation_update_id": update_id,
        "posterior_checkpoint_id": checkpoint_id,
        "posterior_run_id": posterior_run_id,
        "public_fact_snapshot_id": public_fact_snapshot_id,
        "decision_id": decision_id,
        "decision_action": decision_action,
        "decision_state": decision_state,
        "order_signal_applicability": (
            "applicable_v6_decision" if decision_at else "applicable_v6_decision_pending"
        ),
        "source_response_to_posterior_apply_start_ms": _ui_snapshot_ms_between(
            fetched_at, update_started_at
        ),
        "source_fact_to_posterior_apply_start_ms": _ui_snapshot_ms_between(
            accepted_at, update_started_at
        ),
        "source_valid_to_posterior_apply_start_ms": _ui_snapshot_ms_between(
            valid_time, update_started_at
        ),
        "posterior_apply_runtime_ms": _ui_snapshot_ms_between(
            update_started_at, update_completed_at
        ),
        "checkpoint_to_public_fact_ms": _ui_snapshot_ms_between(
            checkpoint_committed_at, public_fact_written_at
        ),
        "public_fact_to_decision_ms": _ui_snapshot_ms_between(
            public_fact_written_at, decision_at
        ),
        "latest_temperature_c": parsed.get("temperature_c"),
        "amsc_latency_slo_audit": {
            "schema": "amsc_latency_slo_audit_v1",
            "source": "archive.db.v6_canonical_chain",
            "source_provider": "AMSC",
            "source_id": source_id,
            "source_event_id": canonical_event_id,
            "source_observation_id": source_observation_id,
            "valid_time": valid_time,
            "fetched_at": fetched_at,
            "fact_as_of": accepted_at,
            "posterior_as_of": checkpoint_committed_at,
            "decision_at": decision_at,
        },
        "guards": {
            "read_only": True,
            "frontend_recompute_allowed": False,
            "decision_recompute_allowed": False,
        },
    }
    payload["source_to_posterior_timing"] = {
        key: value for key, value in timing.items() if value not in (None, "", [], {})
    }


def _attach_v6_execution_deadline_timing_for_ui_snapshot(
    conn: sqlite3.Connection,
    payload: MutableMapping[str, Any],
    *,
    event_date: str,
) -> None:
    if not event_date:
        return
    target_identity = f"physical_weather_day_v1:ZUUU:{event_date}"
    try:
        row = conn.execute(
            """
            SELECT
              c.canonical_observation_event_id,c.first_actionable_seen_at,
              u.strong_observation_update_id,p.posterior_run_id,p.posterior_checkpoint_id,
              x.outbox_event_id,x.observation_to_order_hard_deadline_at,
              x.inference_decision_deadline_at,x.transaction_b_committed_at,
              x.execution_eligible_at_commit,x.execution_na_reason,x.deadline_policy,
              o.state AS outbox_state,o.created_at AS outbox_created_at,
              o.claimed_at,o.completed_at,o.attempt_count,o.error_class,o.last_error,
              o.terminal_reason,o.completed_decision_id
            FROM canonical_observation_events c
            JOIN strong_observation_updates u
              ON u.canonical_observation_event_id=c.canonical_observation_event_id
             AND u.state='applied'
            JOIN posterior_checkpoints p
              ON p.last_strong_update_id=u.strong_observation_update_id
             AND p.state='committed'
            JOIN posterior_outbox_execution_contracts x
              ON x.posterior_run_id=p.posterior_run_id
             AND x.canonical_observation_event_id=c.canonical_observation_event_id
            JOIN posterior_commit_outbox o ON o.outbox_event_id=x.outbox_event_id
            WHERE c.target_identity=? AND c.state LIKE 'accepted%'
            ORDER BY datetime(x.transaction_b_committed_at) DESC,p.rowid DESC
            LIMIT 1
            """,
            (target_identity,),
        ).fetchone()
    except sqlite3.Error:
        return
    if row is None:
        return

    def value(key: str) -> Any:
        try:
            return row[key]
        except (IndexError, KeyError, TypeError):
            return None

    def text(key: str) -> str:
        return str(value(key) or "").strip()

    posterior_run_id = text("posterior_run_id")
    update_id = text("strong_observation_update_id")
    deadline_at = text("observation_to_order_hard_deadline_at")
    actionable_at = text("first_actionable_seen_at")
    committed_at = text("transaction_b_committed_at")
    terminal_at = text("completed_at")
    decision_at = ""
    decision_id = ""
    decision_action = ""
    decision_state = ""
    called_gateway = False
    late_execution_forbidden = False
    completed_decision_id = text("completed_decision_id")
    try:
        decision = conn.execute(
            """
            SELECT decision_id,action,decided_state,created_at,details_json
            FROM auto_trade_decisions
            WHERE event_date=? AND (decision_id=? OR correlation_id=? OR posterior_run_id=?)
            ORDER BY CASE WHEN decision_id=? THEN 0 ELSE 1 END,
                     datetime(created_at) ASC,id ASC LIMIT 1
            """,
            (event_date, completed_decision_id, update_id, posterior_run_id, completed_decision_id),
        ).fetchone()
        if decision is not None:
            decision_at = str(decision["created_at"] or "").strip()
            decision_id = str(decision["decision_id"] or "").strip()
            decision_action = str(decision["action"] or "").strip()
            decision_state = str(decision["decided_state"] or "").strip()
            details = safe_json_loads(str(decision["details_json"] or "{}"))
            called_gateway = details.get("called_gateway") is True
            late_execution_forbidden = details.get("late_execution_forbidden") is True
    except sqlite3.Error:
        pass

    intent_state = ""
    order_intent_id = ""
    exchange_post_started_at = ""
    exchange_order_id = ""
    gateway_response_present = False
    try:
        intent = conn.execute(
            """
            SELECT order_intent_id,state,exchange_post_started_at,exchange_order_id,
                   gateway_response_json
            FROM posterior_execution_intents
            WHERE posterior_run_id=?
            ORDER BY datetime(created_at) ASC,rowid ASC LIMIT 1
            """,
            (posterior_run_id,),
        ).fetchone()
        if intent is not None:
            order_intent_id = str(intent["order_intent_id"] or "").strip()
            intent_state = str(intent["state"] or "").strip()
            exchange_post_started_at = str(intent["exchange_post_started_at"] or "").strip()
            exchange_order_id = str(intent["exchange_order_id"] or "").strip()
            gateway_response_present = bool(str(intent["gateway_response_json"] or "").strip())
    except sqlite3.Error:
        pass

    deadline_budget_ms = _ui_snapshot_ms_between(actionable_at, deadline_at)
    actionable_to_commit_ms = _ui_snapshot_ms_between(actionable_at, committed_at)
    remaining_at_commit_ms = _ui_snapshot_ms_between(committed_at, deadline_at)
    terminal_reference_at = exchange_post_started_at or terminal_at or decision_at
    actionable_to_terminal_ms = _ui_snapshot_ms_between(actionable_at, terminal_reference_at)
    deadline_overrun_ms = _ui_snapshot_ms_between(deadline_at, terminal_reference_at)
    deadline_met = bool(
        exchange_post_started_at
        and deadline_overrun_ms is not None
        and deadline_overrun_ms <= 0
    )
    outbox_state = text("outbox_state")
    terminal_reason = text("terminal_reason") or text("last_error") or text("error_class")
    fail_closed = bool(
        outbox_state == "dead_letter"
        or late_execution_forbidden
        or terminal_reason == "production_observation_to_order_hard_deadline_expired"
    )
    state = (
        "deadline_expired_fail_closed"
        if fail_closed
        else "submitted_within_deadline"
        if deadline_met
        else "execution_pending"
    )
    timing = {
        "schema": "v6_execution_deadline_timing_ssot_v1",
        "state": state,
        "source": (
            "archive.db.posterior_outbox_execution_contracts+posterior_commit_outbox+"
            "posterior_execution_intents+auto_trade_decisions"
        ),
        "event_date": event_date,
        "canonical_observation_event_id": text("canonical_observation_event_id"),
        "strong_observation_update_id": update_id,
        "posterior_checkpoint_id": text("posterior_checkpoint_id"),
        "posterior_run_id": posterior_run_id,
        "outbox_event_id": text("outbox_event_id"),
        "order_intent_id": order_intent_id,
        "decision_id": decision_id,
        "deadline_policy": text("deadline_policy"),
        "first_actionable_seen_at": actionable_at,
        "transaction_b_committed_at": committed_at,
        "outbox_created_at": text("outbox_created_at"),
        "outbox_claimed_at": text("claimed_at"),
        "outbox_completed_at": terminal_at,
        "decision_written_at": decision_at,
        "observation_to_order_hard_deadline_at": deadline_at,
        "inference_decision_deadline_at": text("inference_decision_deadline_at"),
        "exchange_post_started_at": exchange_post_started_at,
        "deadline_budget_ms": deadline_budget_ms,
        "actionable_to_commit_ms": actionable_to_commit_ms,
        "remaining_at_commit_ms": remaining_at_commit_ms,
        "actionable_to_terminal_ms": actionable_to_terminal_ms,
        "deadline_overrun_ms": max(0, int(deadline_overrun_ms or 0)),
        "execution_eligible_at_commit": int(value("execution_eligible_at_commit") or 0) == 1,
        "execution_na_reason": text("execution_na_reason"),
        "outbox_state": outbox_state,
        "outbox_attempt_count": int(value("attempt_count") or 0),
        "outbox_error_class": text("error_class"),
        "outbox_last_error": text("last_error"),
        "terminal_reason": terminal_reason,
        "decision_action": decision_action,
        "decision_state": decision_state,
        "intent_state": intent_state,
        "called_gateway": called_gateway,
        "gateway_response_present": gateway_response_present,
        "exchange_order_id": exchange_order_id,
        "deadline_met": deadline_met,
        "fail_closed": fail_closed,
        "late_execution_forbidden": late_execution_forbidden,
        "read_only": True,
        "frontend_recompute_allowed": False,
        "decision_recompute_allowed": False,
    }
    payload["v6_execution_deadline_timing"] = {
        key: raw for key, raw in timing.items() if raw not in (None, "", [], {})
    }


def _attach_temperature_trajectory_timeline_for_ui_snapshot(
    conn: sqlite3.Connection,
    payload: MutableMapping[str, Any],
    row: Any,
) -> None:
    if not isinstance(payload, MutableMapping):
        return

    def row_get(key: str) -> Any:
        try:
            return row[key]
        except (IndexError, KeyError, TypeError):
            return None

    slug = str(payload.get("slug") or row_get("slug") or "").strip()
    event_date = _normalize_date_key(str(payload.get("event_date") or row_get("event_date") or ""))
    if not _is_chengdu_zuuu_fact_payload(slug, payload):
        return
    if not event_date:
        return
    posterior_ssot = payload.get("posterior_ssot_fact")
    if (
        isinstance(posterior_ssot, Mapping)
        and _is_reported_physical_x_ssot_schema(posterior_ssot.get("schema"))
    ):
        _attach_v6_execution_deadline_timing_for_ui_snapshot(
            conn,
            payload,
            event_date=event_date,
        )
        _attach_v6_source_to_posterior_timing_for_ui_snapshot(
            conn,
            payload,
            event_date=event_date,
        )
        _attach_v6_frozen_probability_layers_for_ui_snapshot(
            conn,
            payload,
            event_date=event_date,
        )
        _attach_v6_probability_audit_for_ui_snapshot(
            conn,
            payload,
            event_date=event_date,
        )
        timeline = _build_sequential_physical_timeline_for_ui_snapshot(
            conn,
            posterior_ssot=posterior_ssot,
            slug=slug,
            event_date=event_date,
            run_date=_normalize_date_key(
                str(payload.get("run_date") or row_get("run_date") or "")
            ),
            event_tz=str(payload.get("event_tz") or payload.get("tz") or "Asia/Shanghai"),
        )
        if timeline:
            payload["temperature_trajectory_timeline"] = timeline
            summary = payload.get("chengdu_intraday_summary")
            if isinstance(summary, MutableMapping):
                summary["temperature_trajectory_timeline"] = timeline
        else:
            # A production reported-X posterior must never inherit the retired
            # v3.1 market-bucket timeline.  Missing checkpoint lineage is
            # explicit NA, not permission to fall back to a stale edge bucket.
            payload.pop("temperature_trajectory_timeline", None)
            payload["temperature_trajectory_timeline_na_reason"] = (
                "sequential_checkpoint_timeline_unavailable"
            )
            summary = payload.get("chengdu_intraday_summary")
            if isinstance(summary, MutableMapping):
                summary.pop("temperature_trajectory_timeline", None)
                summary["temperature_trajectory_timeline_na_reason"] = (
                    "sequential_checkpoint_timeline_unavailable"
                )
        return
    timeline = _build_temperature_trajectory_timeline_for_ui_snapshot(
        conn,
        slug=slug,
        event_date=event_date,
        run_date=_normalize_date_key(str(payload.get("run_date") or row_get("run_date") or "")),
        target_bucket=str(
            payload.get("target_bucket")
            or payload.get("ssot_target_bucket")
            or payload.get("posterior_highest_bucket_label")
            or ""
        ),
        event_tz=str(payload.get("event_tz") or payload.get("tz") or "Asia/Shanghai"),
    )
    if not timeline:
        return
    payload["temperature_trajectory_timeline"] = timeline
    summary = payload.get("chengdu_intraday_summary")
    if isinstance(summary, MutableMapping):
        summary["temperature_trajectory_timeline"] = timeline


def tail_log_lines(path: Path, max_lines: int) -> List[str]:
    if not path.exists():
        return []
    try:
        text = path.read_text(encoding="utf-8", errors="replace")
    except OSError:
        return []
    lines = text.splitlines()
    if max_lines <= 0:
        return lines
    return lines[-max_lines:]


def _detect_scan_stage(lines: List[str]) -> Tuple[int, str]:
    joined = "\n".join(lines[-220:]).lower()
    stage = 0
    if re.search(r"(fetch|request|download|scrape|wunderground|polymarket|api)", joined):
        stage = max(stage, 1)
    if re.search(r"(model|score|weight|prob|aggregate|compute|calc)", joined):
        stage = max(stage, 2)
    if re.search(r"(write|save|db|sqlite|insert|commit|archive)", joined):
        stage = max(stage, 3)
    names = ["准备", "抓取", "计算", "写库"]
    return stage, names[stage] if stage < len(names) else ""


def model_scan_meta() -> Dict[str, Any]:
    meta = {
        "last_start": "",
        "log_mtime": "",
        "trade_sync_failed": False,
        "stage": 0,
        "stage_text": "",
    }
    if not MODEL_SCAN_LOG_PATH.exists():
        return meta
    try:
        mtime = MODEL_SCAN_LOG_PATH.stat().st_mtime
        meta["log_mtime"] = datetime.fromtimestamp(mtime).strftime("%Y-%m-%d %H:%M:%S")
    except OSError:
        meta["log_mtime"] = ""
    if MODEL_SCAN_START_PATH.exists():
        try:
            stamp = MODEL_SCAN_START_PATH.read_text(encoding="utf-8").strip()
        except OSError:
            stamp = ""
        if stamp:
            meta["last_start"] = stamp
    lines = tail_log_lines(MODEL_SCAN_LOG_PATH, 800)
    if not meta["last_start"]:
        for line in reversed(lines):
            match = re.search(r"----\s+(\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2})\s+model_scan start", line)
            if match:
                meta["last_start"] = match.group(1)
                break
    meta["trade_sync_failed"] = any("trade sync failed" in line for line in lines[-80:])
    stage_idx, stage_text = _detect_scan_stage(lines)
    meta["stage"] = int(stage_idx)
    meta["stage_text"] = stage_text
    return meta


def model_scan_running() -> bool:
    if not MODEL_SCAN_LOCK_DIR.exists():
        return False
    pid_file = MODEL_SCAN_LOCK_DIR / "pid"
    pid_text = ""
    if pid_file.exists():
        try:
            pid_text = pid_file.read_text(encoding="utf-8").strip()
        except OSError:
            pid_text = ""
    if pid_text:
        try:
            pid = int(pid_text)
        except (TypeError, ValueError):
            pid = 0
        if pid > 0:
            try:
                os.kill(pid, 0)
                command = pid_command(pid)
                if command and "model_scan.sh" in command:
                    return True
            except OSError:
                pass
    try:
        if os.environ.get("PM_SCAN_15M_LOCK_CLEANUP", "1").strip().lower() in {"1", "true", "yes", "on"}:
            shutil.rmtree(MODEL_SCAN_LOCK_DIR, ignore_errors=True)
    except OSError:
        pass
    return False


def market_refresh_running() -> bool:
    if not MARKET_REFRESH_LOCK_DIR.exists():
        return False
    pid_text = ""
    if MARKET_REFRESH_PID_PATH.exists():
        try:
            pid_text = MARKET_REFRESH_PID_PATH.read_text(encoding="utf-8").strip()
        except OSError:
            pid_text = ""
    if pid_text:
        try:
            pid = int(pid_text)
        except (TypeError, ValueError):
            pid = 0
        if pid > 0:
            try:
                os.kill(pid, 0)
                command = pid_command(pid)
                if command and "market_refresh_1m.sh" in command:
                    return True
            except OSError:
                pass
    try:
        shutil.rmtree(MARKET_REFRESH_LOCK_DIR, ignore_errors=True)
    except OSError:
        pass
    return False


def market_refresh_meta() -> Dict[str, Any]:
    meta = {
        "last_start": "",
        "log_mtime": "",
        "events_fetched": None,
        "events_planned": None,
        "events_seen": 0,
        "last_exit_code": None,
        "last_timeout": False,
        "stage": 0,
        "stage_text": "",
    }
    if not MARKET_REFRESH_LOG_PATH.exists():
        return meta
    try:
        mtime = MARKET_REFRESH_LOG_PATH.stat().st_mtime
        meta["log_mtime"] = datetime.fromtimestamp(mtime).strftime("%Y-%m-%d %H:%M:%S")
    except OSError:
        meta["log_mtime"] = ""
    lines = tail_log_lines(MARKET_REFRESH_LOG_PATH, 800)
    start_idx = None
    for idx in range(len(lines) - 1, -1, -1):
        line = lines[idx]
        match = re.search(r"----\s+(\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2})\s+market_refresh start", line)
        if match:
            meta["last_start"] = match.group(1)
            start_idx = idx
            break
    run_lines = lines[start_idx:] if start_idx is not None else lines
    for line in run_lines:
        if meta["events_fetched"] is None:
            fetched_match = re.search(r"Weather events fetched:\\s*(\\d+)", line)
            if fetched_match:
                try:
                    meta["events_fetched"] = int(fetched_match.group(1))
                except (TypeError, ValueError):
                    meta["events_fetched"] = None
        if meta["events_planned"] is None:
            planned_match = re.search(r"max_events_per_run=(\\d+)", line)
            if planned_match:
                try:
                    meta["events_planned"] = int(planned_match.group(1))
                except (TypeError, ValueError):
                    meta["events_planned"] = None
        exit_match = re.search(r"\[market_refresh\]\s+scan exit=(-?\d+)", line)
        if exit_match:
            try:
                meta["last_exit_code"] = int(exit_match.group(1))
            except (TypeError, ValueError):
                meta["last_exit_code"] = None
        if "[timeout] kill pid=" in line:
            meta["last_timeout"] = True
    meta["events_seen"] = sum(1 for line in run_lines if line.lstrip().startswith("- "))
    stage_idx, stage_text = _detect_scan_stage(run_lines)
    meta["stage"] = int(stage_idx)
    meta["stage_text"] = stage_text
    return meta


def pid_command(pid: int) -> str:
    try:
        output = subprocess.check_output(
            ["ps", "-p", str(pid), "-o", "command="],
            text=True,
        )
    except (OSError, subprocess.CalledProcessError):
        return ""
    return output.strip()


def pid_running(pid: int) -> bool:
    if pid <= 0:
        return False
    if not SCAN_PID_PATH.exists():
        return False
    try:
        os.kill(pid, 0)
    except OSError:
        return False
    command = pid_command(pid)
    if command and "scan_weather_market.py" not in command:
        return False
    return True


def load_scan_state() -> Dict[str, Any]:
    default_state = {"running": False, "started_at": "", "ended_at": "", "exit_code": None, "pid": None}
    if not SCAN_STATE_PATH.exists():
        return dict(default_state)
    try:
        stat = SCAN_STATE_PATH.stat()
    except OSError:
        return dict(default_state)
    mtime_ns = int(getattr(stat, "st_mtime_ns", 0) or 0)
    now_mono = time.monotonic()
    with _SCAN_STATE_CACHE_LOCK:
        cached = _SCAN_STATE_CACHE.get("data")
        cached_mtime_ns = _SCAN_STATE_CACHE.get("mtime_ns")
        cached_ts = float(_SCAN_STATE_CACHE.get("ts") or 0.0)
        if (
            isinstance(cached, dict)
            and cached_mtime_ns == mtime_ns
            and SCAN_STATE_CACHE_SEC > 0
            and (now_mono - cached_ts) <= SCAN_STATE_CACHE_SEC
        ):
            return dict(cached)
    try:
        data = json.loads(SCAN_STATE_PATH.read_text(encoding="utf-8"))
    except (json.JSONDecodeError, OSError):
        return dict(default_state)
    if not isinstance(data, dict):
        return dict(default_state)
    with _SCAN_STATE_CACHE_LOCK:
        _SCAN_STATE_CACHE["data"] = dict(data)
        _SCAN_STATE_CACHE["mtime_ns"] = mtime_ns
        _SCAN_STATE_CACHE["ts"] = now_mono
    return dict(data)


def write_scan_state(state: Dict[str, Any]) -> None:
    if not isinstance(state, dict):
        return
    try:
        payload = json.dumps(state, ensure_ascii=True)
    except Exception:
        return
    with _SCAN_STATE_CACHE_LOCK:
        cached = _SCAN_STATE_CACHE.get("data")
        if isinstance(cached, dict) and cached == state:
            _SCAN_STATE_CACHE["ts"] = time.monotonic()
            return
    try:
        SCAN_STATE_PATH.write_text(payload, encoding="utf-8")
        try:
            mtime_ns = int(getattr(SCAN_STATE_PATH.stat(), "st_mtime_ns", 0) or 0)
        except OSError:
            mtime_ns = None
        with _SCAN_STATE_CACHE_LOCK:
            _SCAN_STATE_CACHE["data"] = dict(state)
            _SCAN_STATE_CACHE["mtime_ns"] = mtime_ns
            _SCAN_STATE_CACHE["ts"] = time.monotonic()
    except OSError:
        # Under temporary FD pressure, keep in-memory state to avoid crashing request path.
        with _SCAN_STATE_CACHE_LOCK:
            _SCAN_STATE_CACHE["data"] = dict(state)
            _SCAN_STATE_CACHE["ts"] = time.monotonic()


def load_scan_timing() -> Dict[str, Any]:
    if not SCAN_TIMING_PATH.exists():
        return {}
    try:
        stat = SCAN_TIMING_PATH.stat()
    except OSError:
        return {}
    mtime_ns = int(getattr(stat, "st_mtime_ns", 0) or 0)
    now_mono = time.monotonic()
    with _SCAN_TIMING_CACHE_LOCK:
        cached = _SCAN_TIMING_CACHE.get("data")
        cached_mtime_ns = _SCAN_TIMING_CACHE.get("mtime_ns")
        cached_ts = float(_SCAN_TIMING_CACHE.get("ts") or 0.0)
        if (
            isinstance(cached, dict)
            and cached_mtime_ns == mtime_ns
            and SCAN_TIMING_CACHE_SEC > 0
            and (now_mono - cached_ts) <= SCAN_TIMING_CACHE_SEC
        ):
            return dict(cached)
    try:
        data = json.loads(SCAN_TIMING_PATH.read_text(encoding="utf-8"))
    except (json.JSONDecodeError, OSError):
        return {}
    if not isinstance(data, dict):
        return {}
    with _SCAN_TIMING_CACHE_LOCK:
        _SCAN_TIMING_CACHE["data"] = dict(data)
        _SCAN_TIMING_CACHE["mtime_ns"] = mtime_ns
        _SCAN_TIMING_CACHE["ts"] = now_mono
    return dict(data)


def normalize_scan_timing(data: Dict[str, Any]) -> Dict[str, Any]:
    if not data:
        return {}
    payload = dict(data)
    updated_raw = str(payload.get("updated_at") or "")
    dt = parse_iso_ts(updated_raw)
    if dt is not None:
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=timezone.utc)
        age_sec = max(0, int((datetime.now(timezone.utc) - dt).total_seconds()))
        payload["age_sec"] = age_sec
    return payload


def scan_status() -> Dict[str, Any]:
    with SCAN_LOCK:
        state = load_scan_state()
        state_before = dict(state)
        pid = state.get("pid")
        running = False
        if pid:
            running = pid_running(int(pid))
        if state.get("running") and not running:
            state["running"] = False
            if not state.get("ended_at"):
                state["ended_at"] = now_text()
        state["running"] = running
        if not running and SCAN_PID_PATH.exists():
            try:
                SCAN_PID_PATH.unlink()
            except OSError:
                pass
        meta_15m = model_scan_meta()
        if state != state_before:
            write_scan_state(state)
        timing = normalize_scan_timing(load_scan_timing())
        market_meta = market_refresh_meta()
        market_meta["running"] = market_refresh_running()
        return {
            "running": bool(state.get("running")),
            "started_at": state.get("started_at") or "",
            "ended_at": state.get("ended_at") or "",
            "exit_code": state.get("exit_code"),
            "scan_alerts_paused": bool(_scan_alerts_paused()),
            "model_scan_running": model_scan_running(),
            "model_scan_last_start": meta_15m.get("last_start") or "",
            "model_scan_log_mtime": meta_15m.get("log_mtime") or "",
            "model_scan_trade_sync_failed": bool(meta_15m.get("trade_sync_failed")),
            "model_scan_stage": int(meta_15m.get("stage") or 0),
            "model_scan_stage_text": meta_15m.get("stage_text") or "",
            "scan_15m_running": model_scan_running(),
            "scan_15m_last_start": meta_15m.get("last_start") or "",
            "scan_15m_log_mtime": meta_15m.get("log_mtime") or "",
            "scan_15m_trade_sync_failed": bool(meta_15m.get("trade_sync_failed")),
            "scan_timing": timing,
            "market_refresh": market_meta,
        }


def start_scan(force: bool, refresh_models: bool, mode: str) -> Dict[str, Any]:
    with SCAN_LOCK:
        diag = auto_trade_env_diagnostics()
        if diag.get("enabled") and (diag.get("dry_run") or diag.get("missing")):
            return {
                "started": False,
                "running": False,
                "message": "auto_trade_env_invalid",
                "detail": auto_trade_env_error_text(diag),
            }
        apply_auto_trade_config(load_auto_trade_config())
        state = load_scan_state()
        pid = state.get("pid")
        if pid and pid_running(int(pid)):
            if not force:
                state["running"] = True
                write_scan_state(state)
                return {"started": False, "running": True, "message": "scan already running"}
            try:
                os.kill(int(pid), 15)
            except OSError:
                pass
            state["running"] = False
            state["ended_at"] = now_text()
            state["exit_code"] = None
            state["pid"] = None
            write_scan_state(state)

        DATA_DIR.mkdir(parents=True, exist_ok=True)
        python = ROOT_DIR / ".venv" / "bin" / "python"
        py_cmd = str(python) if python.exists() else "python3"
        scan_mode = str(mode or "all").strip().lower()
        if scan_mode not in {"all", "model", "market"}:
            scan_mode = "all"
        cmd = [
            py_cmd,
            str(ROOT_DIR / "scan_weather_market.py"),
            "--scan-weather-today",
            "--tz",
            "America/New_York",
            "--days-ahead",
            "-1",
            "--no-update-models",
        ]
        if scan_mode == "market":
            cmd.append("--market-refresh-only")
            cmd.append("--no-auto-trade")
        elif scan_mode == "model":
            cmd.append("--model-refresh-only")
            cmd.append("--no-auto-trade")
        if force:
            cmd.append("--insecure")
        env = os.environ.copy()
        env.setdefault("PM_DISABLE_OPEN_METEO_GEOCODE", "1")
        env.setdefault("PM_SCAN_DB_LOCK_WAIT_SEC", "45")
        env.setdefault("PM_SCAN_FETCH_EVENT_DETAIL", "0")
        env.setdefault("PM_SCAN_GAMMA_TIMEOUT", "12")
        env.setdefault("PM_SCAN_GAMMA_RETRIES", "2")
        env.setdefault("PM_SCAN_GAMMA_BACKOFF", "0.6")
        env.setdefault("PM_SCAN_GAMMA_MAX_PAGES", "60")
        env.setdefault("PM_SCAN_OPEN_METEO_TIMEOUT_SEC", "10")
        env.setdefault("PM_SCAN_OPEN_METEO_RETRIES", "2")
        env.setdefault("PM_SCAN_OPEN_METEO_429_RETRIES", "2")
        env.setdefault("PM_DB_CONNECT_TIMEOUT_SEC", "5")
        env.setdefault("PM_DB_BUSY_TIMEOUT_MS", "5000")
        if scan_mode == "market":
            env.setdefault("PM_SCAN_MAX_EVENTS_PER_RUN", "2")
            max_events = env.get("PM_SCAN_MAX_EVENTS_PER_RUN", "2")
            env.setdefault("PM_SCAN_MAX_MATCHED_PER_RUN", max_events)
            env.setdefault("PM_MARKET_REFRESH_CACHE_ONLY", "1")
            env.setdefault("PM_MARKET_REFRESH_COMPOSE_SCORE", "0")
            env.setdefault("PM_SCAN_MARKET_REFRESH_MAX_OUTCOMES", "4")
            env.setdefault("PM_SCAN_MARKET_REFRESH_TIME_BUDGET_SEC", "6")
            env.setdefault("PM_SCAN_MARKET_REFRESH_CLOB_BOOK_TIMEOUT_SEC", "2")
            env.setdefault("PM_SCAN_MARKET_REFRESH_CLOB_BOOK_RETRIES", "1")
        elif scan_mode == "model":
            env.setdefault("PM_SCAN_MAX_EVENTS_PER_RUN", "6")
            max_events = env.get("PM_SCAN_MAX_EVENTS_PER_RUN", "6")
            env.setdefault("PM_SCAN_MAX_MATCHED_PER_RUN", max_events)
        if refresh_models or scan_mode == "model":
            env["PM_FORCE_MODEL_REFRESH"] = "1"
        log_file = open(SCAN_LOG_PATH, "a", encoding="utf-8")
        proc = subprocess.Popen(
            cmd,
            stdout=log_file,
            stderr=log_file,
            cwd=str(ROOT_DIR),
            env=env,
        )
        SCAN_PID_PATH.write_text(str(proc.pid), encoding="utf-8")
        state = {
            "running": True,
            "started_at": now_text(),
            "ended_at": "",
            "exit_code": None,
            "pid": proc.pid,
        }
        write_scan_state(state)

        def _watch() -> None:
            code = proc.wait()
            log_file.close()
            with SCAN_LOCK:
                state = load_scan_state()
                state["running"] = False
                state["ended_at"] = now_text()
                state["exit_code"] = code
                state["pid"] = None
                write_scan_state(state)
                try:
                    SCAN_PID_PATH.unlink()
                except OSError:
                    pass

        threading.Thread(target=_watch, daemon=True).start()
        return {"started": True, "running": True}


def _latest_event_run_meta(
    conn: sqlite3.Connection,
    slug: str,
    event_date: str,
) -> Optional[Dict[str, Any]]:
    cur = conn.cursor()
    cur.execute(
        """
        SELECT event_url, lat, lon, tz, title
        FROM event_runs
        WHERE slug = ? AND event_date = ?
        ORDER BY created_at DESC
        LIMIT 1
        """,
        (slug, event_date),
    )
    row = cur.fetchone()
    if not row:
        return None
    return {
        "event_url": str(row["event_url"] or ""),
        "lat": row["lat"],
        "lon": row["lon"],
        "tz": str(row["tz"] or ""),
        "title": str(row["title"] or ""),
    }


def start_market_refresh(slug: str, event_date: str) -> Dict[str, Any]:
    if not slug or not event_date:
        return {"ok": False, "error": "missing_params"}
    if not DB_PATH.exists():
        return {"ok": False, "error": "db_missing"}
    event_date = event_date.split("T", 1)[0]
    with MARKET_REFRESH_LOCK:
        pid = MARKET_REFRESH_STATE.get("pid")
        if pid and pid_running(int(pid)):
            return {"ok": False, "error": "refresh_running", "state": dict(MARKET_REFRESH_STATE)}
        MARKET_REFRESH_STATE.update(
            {
                "running": False,
                "started_at": "",
                "ended_at": "",
                "exit_code": None,
                "pid": None,
                "slug": "",
                "event_date": "",
                "error": "",
            }
        )
        with open_db() as conn:
            meta = _latest_event_run_meta(conn, slug, event_date)
        if not meta:
            return {"ok": False, "error": "event_not_found"}
        tz = meta.get("tz") or "UTC"
        event_url = meta.get("event_url") or f"https://polymarket.com/event/{slug}"
        python = ROOT_DIR / ".venv" / "bin" / "python"
        py_cmd = str(python) if python.exists() else "python3"
        cmd = [
            py_cmd,
            str(ROOT_DIR / "scan_weather_market.py"),
            "--event-url",
            event_url,
            "--date",
            event_date,
            "--tz",
            tz,
            "--market-refresh-only",
            "--no-update-models",
            "--no-auto-trade",
        ]
        DATA_DIR.mkdir(parents=True, exist_ok=True)
        log_file = open(MARKET_REFRESH_LOG_PATH, "a", encoding="utf-8")
        log_file.write(f"\n[{now_text()}] refresh {slug} {event_date}\n")
        log_file.flush()
        proc = subprocess.Popen(
            cmd,
            stdout=log_file,
            stderr=log_file,
            cwd=str(ROOT_DIR),
            env=os.environ.copy(),
        )
        MARKET_REFRESH_STATE.update(
            {
                "running": True,
                "started_at": now_text(),
                "ended_at": "",
                "exit_code": None,
                "pid": proc.pid,
                "slug": slug,
                "event_date": event_date,
                "error": "",
            }
        )

    def _watch_refresh() -> None:
        code = proc.wait()
        log_file.close()
        with MARKET_REFRESH_LOCK:
            MARKET_REFRESH_STATE["running"] = False
            MARKET_REFRESH_STATE["ended_at"] = now_text()
            MARKET_REFRESH_STATE["exit_code"] = code
            MARKET_REFRESH_STATE["pid"] = None

    threading.Thread(target=_watch_refresh, daemon=True).start()
    return {"ok": True, "started": True, "slug": slug, "event_date": event_date}


def parse_iso_date(value: str) -> Optional[datetime]:
    if not value:
        return None
    try:
        return datetime.fromisoformat(value.replace("Z", "+00:00"))
    except ValueError:
        return None


