def _iso_day_in_tz(ts: str, tz: ZoneInfo) -> str:
    dt = parse_any_ts(str(ts or "").strip())
    if dt is None:
        dt = parse_iso_ts(str(ts or "").strip())
    if dt is None:
        return ""
    if dt.tzinfo is None:
        dt = dt.replace(tzinfo=timezone.utc)
    try:
        return dt.astimezone(tz).date().isoformat()
    except Exception:
        return dt.date().isoformat()


def _ui_snapshot_cache_entry(cache_key: str) -> Optional[Tuple[float, Dict[str, Any]]]:
    if UI_SNAPSHOT_CACHE_SEC <= 0:
        return None
    with _UI_SNAPSHOT_CACHE_LOCK:
        return _UI_SNAPSHOT_CACHE.get(cache_key)


def _ui_snapshot_dirty_stamp_mtime() -> float:
    try:
        return float(UI_SNAPSHOT_DIRTY_STAMP_PATH.stat().st_mtime)
    except OSError:
        return 0.0


def _ui_snapshot_cache_is_dirty(entry: Optional[Tuple[float, Dict[str, Any]]]) -> bool:
    if not entry:
        return False
    cache_ts = float(entry[0] or 0.0)
    dirty_ts = _ui_snapshot_dirty_stamp_mtime()
    if dirty_ts > cache_ts + 0.001:
        return True
    return not _ui_snapshot_cached_fact_pointers_current(entry)


def _ui_snapshot_cached_fact_pointers_current(
    entry: Optional[Tuple[float, Dict[str, Any]]],
) -> bool:
    """Reject a cached screen whose facts are no longer the latest SSOT rows.

    Some production writers atomically repoint ``event_fact_latest`` without
    participating in the UI dirty-stamp side channel.  Cache validity must
    therefore be derived from the database SSOT itself, not from that optional
    notification file.
    """
    if not entry or not isinstance(entry[1], Mapping):
        return True
    if entry[1].get("cache_fact_pointer_guard") is not True:
        return True
    facts = entry[1].get("facts")
    items = facts.get("items") if isinstance(facts, Mapping) else None
    if not isinstance(items, list):
        return True
    expected: List[Tuple[str, str, int]] = []
    seen: Set[Tuple[str, str]] = set()
    for item in items:
        if not isinstance(item, Mapping):
            continue
        slug = str(item.get("slug") or "").strip()
        event_date = _normalize_date_key(str(item.get("event_date") or ""))
        try:
            fact_id = int(item.get("fact_id") or 0)
        except (TypeError, ValueError):
            fact_id = 0
        key = (slug, event_date)
        if not slug or not event_date or fact_id <= 0 or key in seen:
            continue
        seen.add(key)
        expected.append((slug, event_date, fact_id))
    if not expected:
        return True
    values_sql = ",".join("(?,?,?)" for _ in expected)
    params: List[Any] = []
    for slug, event_date, fact_id in expected:
        params.extend((slug, event_date, fact_id))
    try:
        with open_db_ro_fast(timeout_sec=0.03, busy_timeout_ms=0) as conn:
            mismatch = conn.execute(
                "WITH expected(slug,event_date,fact_id) AS (VALUES " + values_sql + ") "
                "SELECT COUNT(*) FROM expected e "
                "LEFT JOIN event_fact_latest l ON l.slug=e.slug AND l.event_date=e.event_date "
                "WHERE l.fact_id IS NULL OR l.fact_id<>e.fact_id",
                tuple(params),
            ).fetchone()
    except (sqlite3.Error, OSError):
        # A transient read lock does not make an otherwise fresh snapshot
        # unusable; the next request retries this SSOT pointer check.
        return True
    return mismatch is not None and int(mismatch[0] or 0) == 0


def _ui_snapshot_dirty_stamp_in_grace() -> bool:
    dirty_ts = _ui_snapshot_dirty_stamp_mtime()
    if dirty_ts <= 0 or UI_SNAPSHOT_DIRTY_GRACE_SEC <= 0:
        return False
    return (time.time() - dirty_ts) < UI_SNAPSHOT_DIRTY_GRACE_SEC


def _pid_alive(pid: Any) -> bool:
    try:
        pid_val = int(pid)
    except (TypeError, ValueError):
        return False
    if pid_val <= 0:
        return False
    try:
        os.kill(pid_val, 0)
        return True
    except OSError:
        return False


def _process_command_for_pid(pid: Any) -> str:
    try:
        pid_val = int(pid)
    except (TypeError, ValueError):
        return ""
    if pid_val <= 0:
        return ""
    try:
        res = subprocess.run(
            ["ps", "-p", str(pid_val), "-o", "command="],
            capture_output=True,
            text=True,
            timeout=float(UI_RUNTIME_HEALTH_PROCESS_SCAN_TIMEOUT_SEC),
            check=False,
        )
    except Exception:
        return ""
    if res.returncode != 0:
        return ""
    return str(res.stdout or "").strip()


def _write_facts_materialize_lock_meta(
    *,
    mode: str,
    facts_date: str = "",
    facts_days: Any = "",
    write_scope: str = "",
    extra: Optional[Mapping[str, Any]] = None,
) -> None:
    try:
        FACTS_MATERIALIZE_LOCK_DIR.mkdir(parents=True, exist_ok=True)
        meta: Dict[str, Any] = {
            "pid": os.getpid(),
            "mode": str(mode or "facts_materialize"),
            "started_at": now_text(),
            "facts_date": str(facts_date or ""),
            "facts_days": facts_days,
            "write_scope": str(write_scope or os.environ.get("PM_ARCHIVE_WRITE_SCOPE") or ""),
            "argv": list(sys.argv or []),
        }
        if isinstance(extra, Mapping):
            meta.update({str(k): v for k, v in extra.items()})
        FACTS_MATERIALIZE_LOCK_META_PATH.write_text(
            json.dumps(meta, ensure_ascii=False, sort_keys=True),
            encoding="utf-8",
        )
    except Exception:
        pass


def _facts_materialize_lock_state_uncached() -> Dict[str, Any]:
    lock_dir = FACTS_MATERIALIZE_LOCK_DIR
    meta_path = FACTS_MATERIALIZE_LOCK_META_PATH
    pid_path = lock_dir / "pid"
    exists = lock_dir.exists()
    out: Dict[str, Any] = {
        "exists": bool(exists),
        "active": False,
        "stale": False,
        "path": str(lock_dir),
        "pid": None,
        "pid_alive": False,
        "command": "",
        "mode": "",
        "started_at": "",
        "age_sec": None,
    }
    if not exists:
        return out
    try:
        mtime = float(lock_dir.stat().st_mtime)
        out["mtime"] = mtime
        out["age_sec"] = max(0.0, time.time() - mtime)
    except OSError:
        pass
    meta: Dict[str, Any] = {}
    try:
        meta = json.loads(meta_path.read_text(encoding="utf-8"))
        if not isinstance(meta, dict):
            meta = {}
    except Exception:
        meta = {}
    pid_raw = meta.get("pid")
    if not pid_raw:
        try:
            pid_raw = pid_path.read_text(encoding="utf-8").strip()
        except OSError:
            pid_raw = ""
    try:
        pid_val = int(pid_raw)
    except (TypeError, ValueError):
        pid_val = 0
    if pid_val > 0:
        out["pid"] = pid_val
    if meta:
        out["mode"] = str(meta.get("mode") or "")
        out["started_at"] = str(meta.get("started_at") or "")
        out["facts_date"] = str(meta.get("facts_date") or "")
        out["facts_days"] = meta.get("facts_days")
        out["write_scope"] = str(meta.get("write_scope") or "")
    if out.get("started_at"):
        started_dt = parse_any_ts(str(out.get("started_at") or ""))
        if started_dt is not None:
            if started_dt.tzinfo is None:
                started_dt = started_dt.replace(tzinfo=timezone.utc)
            out["age_sec"] = max(0.0, (datetime.now(timezone.utc) - started_dt).total_seconds())
    alive = _pid_alive(pid_val)
    out["pid_alive"] = bool(alive)
    command = _process_command_for_pid(pid_val) if alive else ""
    out["command"] = command
    command_matches = "ui/server.py" in command and (
        "--materialize-facts" in command or "--materialize-first-prediction-lead-day-facts" in command
    )
    mode_matches = str(out.get("mode") or "").startswith("facts_materialize") or str(out.get("mode") or "").startswith(
        "first_prediction"
    )
    out["active"] = bool(alive and (command_matches or (not command and mode_matches)))
    out["stale"] = bool(exists and not out["active"])
    if out["stale"]:
        out["stale_reason"] = "pid_not_alive" if not alive else "pid_command_not_materialize"
    return out


def _facts_materialize_lock_state() -> Dict[str, Any]:
    global _UI_MATERIALIZE_STATUS_CACHE
    now_ts = time.time()
    with _UI_MATERIALIZE_STATUS_CACHE_LOCK:
        cached_ts, cached_payload = _UI_MATERIALIZE_STATUS_CACHE
        if cached_payload and (now_ts - float(cached_ts or 0.0)) <= UI_RUNTIME_HEALTH_PROCESS_SCAN_CACHE_SEC:
            return dict(cached_payload)
    payload = _facts_materialize_lock_state_uncached()
    with _UI_MATERIALIZE_STATUS_CACHE_LOCK:
        _UI_MATERIALIZE_STATUS_CACHE = (time.time(), dict(payload))
    return payload


def _sqlite_file_runtime_state() -> Dict[str, Any]:
    paths = {
        "db": DB_PATH,
        "wal": Path(str(DB_PATH) + "-wal"),
        "shm": Path(str(DB_PATH) + "-shm"),
    }
    out: Dict[str, Any] = {"path": str(DB_PATH), "exists": DB_PATH.exists()}
    for key, path in paths.items():
        try:
            stat = path.stat()
            out[f"{key}_bytes"] = int(stat.st_size)
            out[f"{key}_mtime"] = float(stat.st_mtime)
            out[f"{key}_age_sec"] = max(0.0, time.time() - float(stat.st_mtime))
        except OSError:
            out[f"{key}_bytes"] = 0
    return out


def _record_ui_endpoint_observation(path: str, *, method: str, elapsed_sec: float) -> None:
    try:
        parsed = urlparse(str(path or ""))
        key = parsed.path or str(path or "")
    except Exception:
        key = str(path or "")
    if not key:
        return
    elapsed_ms = max(0.0, float(elapsed_sec or 0.0) * 1000.0)
    now_txt = now_text()
    threshold_ms = max(0.0, float(UI_SLOW_REQUEST_LOG_SEC or 0.0) * 1000.0)
    with _UI_ENDPOINT_METRICS_LOCK:
        entry = _UI_ENDPOINT_METRICS.setdefault(
            key,
            {
                "path": key,
                "method": str(method or ""),
                "count": 0,
                "slow_count": 0,
                "max_elapsed_ms": 0.0,
            },
        )
        entry["method"] = str(method or entry.get("method") or "")
        entry["count"] = int(entry.get("count") or 0) + 1
        entry["last_elapsed_ms"] = elapsed_ms
        entry["last_at"] = now_txt
        entry["max_elapsed_ms"] = max(float(entry.get("max_elapsed_ms") or 0.0), elapsed_ms)
        if threshold_ms > 0 and elapsed_ms >= threshold_ms:
            entry["slow_count"] = int(entry.get("slow_count") or 0) + 1
            entry["last_slow_at"] = now_txt
            entry["last_slow_elapsed_ms"] = elapsed_ms
        if len(_UI_ENDPOINT_METRICS) > UI_RUNTIME_HEALTH_ENDPOINT_LIMIT * 3:
            stale = sorted(
                _UI_ENDPOINT_METRICS,
                key=lambda name: str((_UI_ENDPOINT_METRICS.get(name) or {}).get("last_at") or ""),
            )[:UI_RUNTIME_HEALTH_ENDPOINT_LIMIT]
            for old_key in stale:
                _UI_ENDPOINT_METRICS.pop(old_key, None)


def _ui_endpoint_metrics_snapshot(limit: Optional[int] = None) -> List[Dict[str, Any]]:
    try:
        limit_val = int(limit if limit is not None else UI_RUNTIME_HEALTH_ENDPOINT_LIMIT)
    except (TypeError, ValueError):
        limit_val = UI_RUNTIME_HEALTH_ENDPOINT_LIMIT
    limit_val = max(1, min(limit_val, UI_RUNTIME_HEALTH_ENDPOINT_LIMIT))
    with _UI_ENDPOINT_METRICS_LOCK:
        rows = [dict(item) for item in _UI_ENDPOINT_METRICS.values()]
    rows.sort(
        key=lambda item: (
            float(item.get("last_elapsed_ms") or 0.0),
            float(item.get("max_elapsed_ms") or 0.0),
        ),
        reverse=True,
    )
    return rows[:limit_val]


def ui_runtime_health(*, include_endpoint_metrics: bool = True) -> Dict[str, Any]:
    payload: Dict[str, Any] = {
        "ok": True,
        "generated_at": now_text(),
        "facts_materialize": _facts_materialize_lock_state(),
        "sqlite": _sqlite_file_runtime_state(),
        "slow_request_threshold_ms": max(0.0, float(UI_SLOW_REQUEST_LOG_SEC or 0.0) * 1000.0),
    }
    if include_endpoint_metrics:
        payload["endpoint_metrics"] = _ui_endpoint_metrics_snapshot()
    return payload


def _attach_ui_runtime_health(payload: Dict[str, Any], *, include_endpoint_metrics: bool = False) -> Dict[str, Any]:
    if not isinstance(payload, dict):
        return payload
    try:
        payload["runtime_health"] = ui_runtime_health(include_endpoint_metrics=include_endpoint_metrics)
    except Exception:
        pass
    return payload


def _ui_snapshot_cache_store(cache_key: str, payload: Dict[str, Any]) -> None:
    if UI_SNAPSHOT_CACHE_SEC <= 0:
        return
    payload["cache_fact_pointer_guard"] = True
    with _UI_SNAPSHOT_CACHE_LOCK:
        _UI_SNAPSHOT_CACHE[cache_key] = (time.time(), payload)
        overflow = len(_UI_SNAPSHOT_CACHE) - int(UI_SNAPSHOT_CACHE_MAX_ENTRIES)
        if overflow > 0:
            for old_key, _ in sorted(
                _UI_SNAPSHOT_CACHE.items(),
                key=lambda item: float((item[1] or (0, {}))[0] or 0.0),
            )[:overflow]:
                _UI_SNAPSHOT_CACHE.pop(old_key, None)


def _ui_snapshot_rebuild_state_stale(state: Any, now_monotonic: Optional[float] = None) -> bool:
    if not isinstance(state, Mapping):
        return False
    started_monotonic = to_float(state.get("started_monotonic"))
    if started_monotonic is None:
        return True
    if now_monotonic is None:
        now_monotonic = time.monotonic()
    return max(0.0, float(now_monotonic) - float(started_monotonic)) > float(UI_SNAPSHOT_REBUILD_STALE_SEC)


def _ui_snapshot_expire_stale_rebuild_locked(cache_key: str, now_monotonic: Optional[float] = None) -> bool:
    state = _UI_SNAPSHOT_REBUILDING.get(cache_key)
    if not _ui_snapshot_rebuild_state_stale(state, now_monotonic):
        return False
    stale = _UI_SNAPSHOT_REBUILDING.pop(cache_key, None)
    started_monotonic = to_float(stale.get("started_monotonic")) if isinstance(stale, Mapping) else None
    duration_ms = (
        max(0.0, (float(now_monotonic or time.monotonic()) - float(started_monotonic)) * 1000.0)
        if started_monotonic is not None
        else None
    )
    _UI_SNAPSHOT_REBUILD_LAST[cache_key] = {
        "cache_key": cache_key,
        "mode": (stale or {}).get("mode") if isinstance(stale, Mapping) else (
            "summary" if str(cache_key).startswith("summary:") else "full"
        ),
        "started_at": (stale or {}).get("started_at") if isinstance(stale, Mapping) else "",
        "ended_at": now_text(),
        "duration_ms": duration_ms,
        "stale_expired": True,
        "stale_sec": UI_SNAPSHOT_REBUILD_STALE_SEC,
    }
    return True


def _ui_snapshot_rebuild_start(cache_key: str) -> bool:
    with _UI_SNAPSHOT_REBUILD_LOCK:
        _ui_snapshot_expire_stale_rebuild_locked(cache_key, time.monotonic())
        if cache_key in _UI_SNAPSHOT_REBUILDING:
            return False
        _UI_SNAPSHOT_REBUILDING[cache_key] = {
            "cache_key": cache_key,
            "started_at": now_text(),
            "started_monotonic": time.monotonic(),
            "mode": "summary" if str(cache_key).startswith("summary:") else "full",
        }
        return True


def _ui_snapshot_rebuild_done(cache_key: str, *, error: str = "") -> None:
    with _UI_SNAPSHOT_REBUILD_LOCK:
        state = _UI_SNAPSHOT_REBUILDING.pop(cache_key, None)
        ended_monotonic = time.monotonic()
        if isinstance(state, Mapping):
            started_monotonic = to_float(state.get("started_monotonic"))
            duration_ms = (
                max(0.0, (ended_monotonic - float(started_monotonic)) * 1000.0)
                if started_monotonic is not None
                else None
            )
            _UI_SNAPSHOT_REBUILD_LAST[cache_key] = {
                "cache_key": cache_key,
                "mode": state.get("mode") or ("summary" if str(cache_key).startswith("summary:") else "full"),
                "started_at": state.get("started_at") or "",
                "ended_at": now_text(),
                "duration_ms": duration_ms,
                "ok": not bool(str(error or "").strip()),
                "error": str(error or "").strip(),
            }
            if len(_UI_SNAPSHOT_REBUILD_LAST) > 128:
                for old_key, _old_state in sorted(
                    _UI_SNAPSHOT_REBUILD_LAST.items(),
                    key=lambda item: str((item[1] or {}).get("ended_at") or ""),
                )[:32]:
                    _UI_SNAPSHOT_REBUILD_LAST.pop(old_key, None)


def _ui_snapshot_record_rebuild_last(
    cache_key: str,
    *,
    started_at: str,
    duration_ms: Optional[float],
    forced: bool = False,
) -> None:
    key = str(cache_key or "")
    if not key:
        return
    with _UI_SNAPSHOT_REBUILD_LOCK:
        _UI_SNAPSHOT_REBUILD_LAST[key] = {
            "cache_key": key,
            "mode": "summary" if key.startswith("summary:") else "full",
            "started_at": str(started_at or ""),
            "ended_at": now_text(),
            "duration_ms": duration_ms,
            "forced": bool(forced),
        }
        if len(_UI_SNAPSHOT_REBUILD_LAST) > 128:
            for old_key, _old_state in sorted(
                _UI_SNAPSHOT_REBUILD_LAST.items(),
                key=lambda item: str((item[1] or {}).get("ended_at") or ""),
            )[:32]:
                _UI_SNAPSHOT_REBUILD_LAST.pop(old_key, None)


def _ui_snapshot_rebuild_active(cache_key: str) -> bool:
    with _UI_SNAPSHOT_REBUILD_LOCK:
        _ui_snapshot_expire_stale_rebuild_locked(cache_key, time.monotonic())
        return cache_key in _UI_SNAPSHOT_REBUILDING


def _ui_snapshot_rebuild_status(cache_key: str) -> Dict[str, Any]:
    key = str(cache_key or "")
    if not key:
        return {}
    now_monotonic = time.monotonic()
    with _UI_SNAPSHOT_REBUILD_LOCK:
        _ui_snapshot_expire_stale_rebuild_locked(key, now_monotonic)
        active = _UI_SNAPSHOT_REBUILDING.get(key)
        last = _UI_SNAPSHOT_REBUILD_LAST.get(key)
        active_copy = dict(active) if isinstance(active, Mapping) else {}
        last_copy = dict(last) if isinstance(last, Mapping) else {}
    mode = active_copy.get("mode") or last_copy.get("mode") or ("summary" if key.startswith("summary:") else "full")
    out: Dict[str, Any] = {
        "cache_key": key,
        "mode": mode,
        "active": bool(active_copy),
    }
    if active_copy:
        started_monotonic = to_float(active_copy.get("started_monotonic"))
        elapsed_ms = (
            max(0.0, (now_monotonic - float(started_monotonic)) * 1000.0)
            if started_monotonic is not None
            else None
        )
        out.update(
            {
                "started_at": str(active_copy.get("started_at") or ""),
                "elapsed_ms": elapsed_ms,
                "stage": "rebuild_running",
            }
        )
    if last_copy:
        out.update(
            {
                "last_started_at": str(last_copy.get("started_at") or ""),
                "last_ended_at": str(last_copy.get("ended_at") or ""),
                "last_duration_ms": last_copy.get("duration_ms"),
                "last_ok": last_copy.get("ok"),
                "last_error": str(last_copy.get("error") or ""),
            }
        )
    return out


def _attach_ui_snapshot_rebuild_status(payload: Dict[str, Any], cache_key: str) -> Dict[str, Any]:
    if not isinstance(payload, dict):
        return payload
    status = _ui_snapshot_rebuild_status(cache_key)
    if status:
        payload["cache_rebuild_status"] = status
        payload["cache_rebuild_cache_key"] = status.get("cache_key")
        payload["cache_rebuild_mode"] = status.get("mode")
        if status.get("active"):
            payload["cache_rebuild_in_flight"] = True
            payload["cache_rebuild_started_at"] = status.get("started_at")
            payload["cache_rebuild_elapsed_ms"] = status.get("elapsed_ms")
        if status.get("last_duration_ms") is not None:
            payload["cache_rebuild_last_duration_ms"] = status.get("last_duration_ms")
            payload["cache_rebuild_last_ended_at"] = status.get("last_ended_at")
    _attach_ui_runtime_health(payload, include_endpoint_metrics=False)
    return payload


def _ui_snapshot_append_unique_text(out: List[str], raw: Any) -> None:
    text = str(raw or "").strip()
    if text and text not in out:
        out.append(text)


def _ui_snapshot_first_text(*values: Any) -> str:
    for raw in values:
        text = str(raw or "").strip()
        if text:
            return text
    return ""


def _ui_snapshot_item_source_event_ids(raw_item: Mapping[str, Any]) -> List[str]:
    source_event_ids: List[str] = []
    lineage = raw_item.get("lineage_state")
    if isinstance(lineage, Mapping):
        for source_event_id in lineage.get("source_event_ids") or []:
            _ui_snapshot_append_unique_text(source_event_ids, source_event_id)
        _ui_snapshot_append_unique_text(source_event_ids, lineage.get("source_event_id"))
    for source_event_id in raw_item.get("source_event_ids") or []:
        _ui_snapshot_append_unique_text(source_event_ids, source_event_id)
    for row in raw_item.get("source_observations") or []:
        if isinstance(row, Mapping):
            _ui_snapshot_append_unique_text(source_event_ids, row.get("source_event_id"))
    trace = raw_item.get("source_acquisition_trace")
    if isinstance(trace, Mapping):
        for source_event_id in trace.get("source_event_ids") or []:
            _ui_snapshot_append_unique_text(source_event_ids, source_event_id)
        for row in trace.get("source_observations") or []:
            if isinstance(row, Mapping):
                _ui_snapshot_append_unique_text(source_event_ids, row.get("source_event_id"))
    for key in ("signal_to_order_timing", "hard_source_acceptance_state"):
        nested = raw_item.get(key)
        if isinstance(nested, Mapping):
            _ui_snapshot_append_unique_text(source_event_ids, nested.get("source_event_id"))
    _ui_snapshot_append_unique_text(source_event_ids, raw_item.get("source_event_id"))
    posterior_ssot = raw_item.get("posterior_ssot_fact")
    if isinstance(posterior_ssot, Mapping):
        _ui_snapshot_append_unique_text(
            source_event_ids,
            posterior_ssot.get("last_canonical_event_id"),
        )
    return source_event_ids


def _ui_snapshot_item_source_observation_ids(raw_item: Mapping[str, Any]) -> List[str]:
    source_observation_ids: List[str] = []
    lineage = raw_item.get("lineage_state")
    if isinstance(lineage, Mapping):
        for source_observation_id in lineage.get("source_observation_ids") or []:
            _ui_snapshot_append_unique_text(source_observation_ids, source_observation_id)
        _ui_snapshot_append_unique_text(source_observation_ids, lineage.get("source_observation_id"))
    posterior_ssot = raw_item.get("posterior_ssot_fact")
    posterior_lineage = posterior_ssot.get("lineage") if isinstance(posterior_ssot, Mapping) else {}
    if isinstance(posterior_lineage, Mapping):
        for source_observation_id in posterior_lineage.get("source_observation_ids") or []:
            _ui_snapshot_append_unique_text(source_observation_ids, source_observation_id)
    for source_observation_id in raw_item.get("source_observation_ids") or []:
        _ui_snapshot_append_unique_text(source_observation_ids, source_observation_id)
    for row in raw_item.get("source_observations") or []:
        if isinstance(row, Mapping):
            _ui_snapshot_append_unique_text(source_observation_ids, row.get("source_observation_id"))
    trace = raw_item.get("source_acquisition_trace")
    if isinstance(trace, Mapping):
        for source_observation_id in trace.get("source_observation_ids") or []:
            _ui_snapshot_append_unique_text(source_observation_ids, source_observation_id)
        for row in trace.get("source_observations") or []:
            if isinstance(row, Mapping):
                _ui_snapshot_append_unique_text(source_observation_ids, row.get("source_observation_id"))
    for key in ("signal_to_order_timing", "hard_source_acceptance_state"):
        nested = raw_item.get(key)
        if isinstance(nested, Mapping):
            _ui_snapshot_append_unique_text(source_observation_ids, nested.get("source_observation_id"))
    _ui_snapshot_append_unique_text(source_observation_ids, raw_item.get("source_observation_id"))
    return source_observation_ids


def _ui_snapshot_lineage_item(raw_item: Mapping[str, Any]) -> Dict[str, Any]:
    lineage = raw_item.get("lineage_state")
    lineage_map = lineage if isinstance(lineage, Mapping) else {}
    timing = raw_item.get("signal_to_order_timing")
    timing_map = timing if isinstance(timing, Mapping) else {}
    acceptance = raw_item.get("hard_source_acceptance_state")
    acceptance_map = acceptance if isinstance(acceptance, Mapping) else {}
    posterior_runtime = raw_item.get("posterior_runtime")
    posterior_runtime_map = posterior_runtime if isinstance(posterior_runtime, Mapping) else {}
    posterior_ssot = raw_item.get("posterior_ssot_fact")
    posterior_ssot_map = posterior_ssot if isinstance(posterior_ssot, Mapping) else {}
    decision = raw_item.get("auto_trade_ssot")
    decision_map = decision if isinstance(decision, Mapping) else {}
    source_event_ids = _ui_snapshot_item_source_event_ids(raw_item)
    source_observation_ids = _ui_snapshot_item_source_observation_ids(raw_item)
    signal_id = _ui_snapshot_first_text(
        raw_item.get("signal_id"),
        timing_map.get("signal_id"),
        acceptance_map.get("signal_id"),
        raw_item.get("hard_source_signal_id"),
    )
    decision_id = _ui_snapshot_first_text(
        raw_item.get("decision_id"),
        timing_map.get("decision_id"),
        decision_map.get("decision_id"),
    )
    order_intent_id = _ui_snapshot_first_text(
        raw_item.get("order_intent_id"),
        raw_item.get("order_id"),
        timing_map.get("order_intent_id"),
        timing_map.get("order_id"),
        decision_map.get("order_intent_id"),
        decision_map.get("order_id"),
    )
    review_id = _ui_snapshot_first_text(raw_item.get("review_id"), lineage_map.get("review_id"))
    fact_id = _to_int(raw_item.get("fact_id"))
    fact_snapshot_id = _ui_snapshot_first_text(
        raw_item.get("fact_snapshot_id"),
        lineage_map.get("fact_snapshot_id"),
        posterior_ssot_map.get("fact_snapshot_id"),
    )
    posterior_run_id = _ui_snapshot_first_text(
        raw_item.get("posterior_run_id"),
        lineage_map.get("posterior_run_id"),
        posterior_runtime_map.get("posterior_run_id"),
        posterior_ssot_map.get("posterior_run_id"),
    )
    correlation_id = _ui_snapshot_first_text(raw_item.get("correlation_id"), lineage_map.get("correlation_id"))
    hard_source_expected = bool(
        timing_map
        or acceptance_map
        or raw_item.get("hard_source_direct")
        or raw_item.get("hard_source_posterior_override")
        or raw_item.get("awc_hard_source_signal_candidate")
    )
    missing_keys: List[str] = []
    sequential_ssot = _is_sequential_temperature_ssot_schema(
        posterior_ssot_map.get("schema")
    )
    if not correlation_id and not sequential_ssot:
        missing_keys.append("correlation_id")
    if not source_event_ids and not sequential_ssot:
        missing_keys.append("source_event_id")
    if not fact_snapshot_id:
        missing_keys.append("fact_snapshot_id")
    if not posterior_run_id:
        missing_keys.append("posterior_run_id")
    if hard_source_expected and not signal_id:
        missing_keys.append("signal_id")
    na_reasons: Dict[str, str] = {}
    if not correlation_id and sequential_ssot:
        na_reasons["correlation_id"] = "not_defined_by_sequential_probability_ssot"
    if not source_event_ids and sequential_ssot:
        na_reasons["source_event_id"] = "initial_checkpoint_has_no_canonical_observation_event"
    if not decision_id:
        na_reasons["decision_id"] = "not_present_in_ui_fact_item"
    if not order_intent_id:
        na_reasons["order_intent_id"] = "not_present_in_ui_fact_item"
    if not review_id:
        na_reasons["review_id"] = "daily_review_not_materialized_or_not_linked"
    return {
        "slug": str(raw_item.get("slug") or ""),
        "event_date": _normalize_date_key(str(raw_item.get("event_date") or "")),
        "fact_id": fact_id,
        "fact_as_of": str(raw_item.get("fact_as_of") or ""),
        "correlation_id": correlation_id,
        "fact_snapshot_id": fact_snapshot_id,
        "posterior_run_id": posterior_run_id,
        "source_event_ids": source_event_ids,
        "source_observation_ids": source_observation_ids,
        "signal_id": signal_id,
        "decision_id": decision_id,
        "order_intent_id": order_intent_id,
        "review_id": review_id,
        "hard_source_signal_expected": hard_source_expected,
        "missing_keys": missing_keys,
        "na_reasons": na_reasons,
    }


def _ui_snapshot_latest_timestamp_text(*values: Any) -> str:
    latest_text = ""
    latest_key: Optional[Tuple[int, float, str]] = None
    for value in values:
        text = str(value or "").strip()
        if not text:
            continue
        dt = parse_any_ts(text)
        if dt is not None:
            try:
                key = (1, float(dt.timestamp()), text)
            except Exception:
                key = (0, 0.0, text)
        else:
            key = (0, 0.0, text)
        if latest_key is None or key > latest_key:
            latest_key = key
            latest_text = text
    return latest_text


def _ui_snapshot_timing_ms(raw: Any) -> Optional[int]:
    value = to_float(raw)
    if value is None:
        return None
    try:
        if not math.isfinite(float(value)):
            return None
    except Exception:
        return None
    return int(round(float(value)))


def _ui_snapshot_timestamp_sort_value(*values: Any) -> Tuple[int, float, str]:
    text = _ui_snapshot_latest_timestamp_text(*values)
    if not text:
        return (0, 0.0, "")
    dt = parse_any_ts(text)
    if dt is None:
        return (0, 0.0, text)
    try:
        return (1, float(dt.timestamp()), text)
    except Exception:
        return (0, 0.0, text)


def _ui_snapshot_ms_between(start: Any, end: Any) -> Optional[int]:
    start_dt = parse_any_ts(str(start or ""))
    end_dt = parse_any_ts(str(end or ""))
    if start_dt is None or end_dt is None:
        return None
    return _ui_snapshot_timing_ms((end_dt - start_dt).total_seconds() * 1000.0)


def _ui_snapshot_amsc_latency_slo_audit_from_timing(timing_map: Mapping[str, Any]) -> Dict[str, Any]:
    raw_audit = timing_map.get("amsc_latency_slo_audit")
    audit: Dict[str, Any] = copy.deepcopy(dict(raw_audit)) if isinstance(raw_audit, Mapping) else {}
    valid_time = _ui_snapshot_first_text(audit.get("valid_time"), timing_map.get("latest_source_valid_time"))
    fetched_at = _ui_snapshot_first_text(
        audit.get("fetched_at"),
        timing_map.get("latest_source_response_completed_at"),
    )
    fact_as_of = _ui_snapshot_first_text(audit.get("fact_as_of"), timing_map.get("latest_source_fact_as_of"))
    posterior_as_of = _ui_snapshot_first_text(
        audit.get("posterior_as_of"),
        timing_map.get("posterior_apply_completed_at"),
        timing_map.get("posterior_apply_started_at"),
    )
    decision_at = _ui_snapshot_first_text(audit.get("decision_at"))
    stage_latencies = (
        copy.deepcopy(dict(audit.get("stage_latencies_ms")))
        if isinstance(audit.get("stage_latencies_ms"), Mapping)
        else {}
    )
    if stage_latencies.get("valid_to_fetched") is None:
        stage_latencies["valid_to_fetched"] = _ui_snapshot_ms_between(valid_time, fetched_at)
    if stage_latencies.get("fetched_to_fact") is None:
        stage_latencies["fetched_to_fact"] = _ui_snapshot_ms_between(fetched_at, fact_as_of)
    if stage_latencies.get("fact_to_posterior") is None:
        stage_latencies["fact_to_posterior"] = _ui_snapshot_ms_between(fact_as_of, posterior_as_of)
    if stage_latencies.get("posterior_to_decision") is None:
        stage_latencies["posterior_to_decision"] = _ui_snapshot_ms_between(posterior_as_of, decision_at)

    stage_slo = copy.deepcopy(dict(audit.get("stage_slo_ms"))) if isinstance(audit.get("stage_slo_ms"), Mapping) else {}
    stage_slo.setdefault("valid_to_fetched", 90_000)
    stage_slo.setdefault("fetched_to_fact", 5_000)
    stage_slo.setdefault("fact_to_posterior", 10_000)
    stage_slo.setdefault("posterior_to_decision", 3_000)

    stage_status: Dict[str, str] = {}
    for key, slo in stage_slo.items():
        value = stage_latencies.get(key)
        if value is None:
            stage_status[key] = "missing"
        elif isinstance(value, (int, float)) and float(value) < 0:
            stage_status[key] = "clock_order_anomaly"
        elif isinstance(value, (int, float)) and float(value) <= float(slo):
            stage_status[key] = "met"
        else:
            stage_status[key] = "breached"

    missing_fields = [
        key
        for key, value in (
            ("valid_time", valid_time),
            ("fetched_at", fetched_at),
            ("fact_as_of", fact_as_of),
            ("posterior_as_of", posterior_as_of),
            ("decision_at", decision_at),
        )
        if not value
    ]
    available_stage_values = {
        key: int(value)
        for key, value in stage_latencies.items()
        if isinstance(value, (int, float)) and float(value) >= 0
    }
    slow_stage = max(available_stage_values, key=available_stage_values.get) if available_stage_values else ""
    breached_stages = [key for key, status in stage_status.items() if status == "breached"]
    audit.update(
        {
            "schema": str(audit.get("schema") or "amsc_latency_slo_audit_v1"),
            "state": "partial" if missing_fields else "available",
            "state_reason": (
                "missing_fields:" + ",".join(missing_fields)
                if missing_fields
                else "all_chain_timestamps_available"
            ),
            "source": str(audit.get("source") or "facts.items[].source_to_posterior_timing"),
            "source_provider": str(audit.get("source_provider") or timing_map.get("source_provider") or "AMSC"),
            "source_id": str(audit.get("source_id") or timing_map.get("latest_source_id") or ""),
            "source_event_id": str(audit.get("source_event_id") or timing_map.get("latest_source_event_id") or ""),
            "source_observation_id": str(
                audit.get("source_observation_id") or timing_map.get("latest_source_observation_id") or ""
            ),
            "valid_time": valid_time,
            "fetched_at": fetched_at,
            "fact_as_of": fact_as_of,
            "posterior_as_of": posterior_as_of,
            "decision_at": decision_at,
            "stage_order": ["valid_time", "fetched_at", "fact_as_of", "posterior_as_of", "decision_at"],
            "stage_latencies_ms": stage_latencies,
            "stage_slo_ms": stage_slo,
            "stage_status": stage_status,
            "slow_stage": slow_stage,
            "breached_stages": breached_stages,
            "valid_to_fetched_ms": stage_latencies.get("valid_to_fetched"),
            "fetched_to_fact_ms": stage_latencies.get("fetched_to_fact"),
            "fact_to_posterior_ms": stage_latencies.get("fact_to_posterior"),
            "posterior_to_decision_ms": stage_latencies.get("posterior_to_decision"),
            "valid_to_posterior_ms": _ui_snapshot_ms_between(valid_time, posterior_as_of),
            "fetched_to_posterior_ms": _ui_snapshot_ms_between(fetched_at, posterior_as_of),
            "valid_to_decision_ms": _ui_snapshot_ms_between(valid_time, decision_at),
            "fetched_to_decision_ms": _ui_snapshot_ms_between(fetched_at, decision_at),
            "fact_to_decision_ms": _ui_snapshot_ms_between(fact_as_of, decision_at),
            "missing_fields": missing_fields,
            "slo_met": False if breached_stages else (None if missing_fields else True),
            "hard_source_latency_slo_met": False if breached_stages else (None if missing_fields else True),
            "read_only": True,
            "frontend_recompute_allowed": False,
            "decision_recompute_allowed": False,
        }
    )
    if not decision_at:
        audit.setdefault("decision_at_na_reason", "decision_not_available_in_ui_snapshot_decision_feed")
    else:
        audit.pop("decision_at_na_reason", None)
    return audit


def _ui_snapshot_source_to_posterior_timing_from_item(raw_item: Mapping[str, Any]) -> Dict[str, Any]:
    if not isinstance(raw_item, Mapping):
        return {}
    timing = raw_item.get("source_to_posterior_timing")
    timing_map = timing if isinstance(timing, Mapping) else {}
    if not timing_map:
        signal_timing = raw_item.get("signal_to_order_timing")
        signal_timing_map = signal_timing if isinstance(signal_timing, Mapping) else {}
        nested = signal_timing_map.get("source_to_posterior_timing")
        timing_map = nested if isinstance(nested, Mapping) else {}
    if not timing_map:
        return {}

    def text(key: str, *fallbacks: Any) -> str:
        return _ui_snapshot_first_text(timing_map.get(key), *fallbacks)

    source_event_ids = [
        str(value or "").strip()
        for value in timing_map.get("source_event_ids") or []
        if str(value or "").strip()
    ]
    source_observation_ids = [
        str(value or "").strip()
        for value in timing_map.get("source_observation_ids") or []
        if str(value or "").strip()
    ]
    latest_source_event_id = text("latest_source_event_id")
    latest_source_observation_id = text("latest_source_observation_id")
    if latest_source_event_id and latest_source_event_id not in source_event_ids:
        source_event_ids.insert(0, latest_source_event_id)
    if latest_source_observation_id and latest_source_observation_id not in source_observation_ids:
        source_observation_ids.insert(0, latest_source_observation_id)

    row: Dict[str, Any] = {
        "schema": "ui_snapshot_source_to_posterior_timing_row_v1",
        "state": text("state") or "available",
        "state_reason": text("state_reason"),
        "surface": text("surface"),
        "source": text("source"),
        "source_provider": text("source_provider"),
        "source_kind": text("source_kind"),
        "source_id": text("latest_source_id"),
        "latest_source_id": text("latest_source_id"),
        "slug": text("slug", raw_item.get("slug")),
        "event_date": _normalize_date_key(text("event_date", raw_item.get("event_date"))),
        "fact_id": _to_int(raw_item.get("fact_id")),
        "fact_as_of": str(raw_item.get("fact_as_of") or ""),
        "task_queue_id": _to_int(timing_map.get("task_queue_id")),
        "task_queue_status": text("task_queue_status"),
        "task_created_at": text("task_created_at"),
        "task_started_at": text("task_started_at"),
        "task_completed_at": text("task_completed_at"),
        "latest_source_fact_as_of": text("latest_source_fact_as_of"),
        "latest_source_response_completed_at": text("latest_source_response_completed_at"),
        "latest_source_valid_time": text("latest_source_valid_time"),
        "posterior_apply_started_at": text(
            "posterior_apply_started_at",
            raw_item.get("posterior_as_of"),
            raw_item.get("fact_as_of"),
        ),
        "posterior_apply_completed_at": text("posterior_apply_completed_at"),
        "checkpoint_committed_at": text("checkpoint_committed_at"),
        "public_fact_written_at": text("public_fact_written_at"),
        "decision_written_at": text("decision_written_at"),
        "posterior_checkpoint_id": text("posterior_checkpoint_id"),
        "strong_observation_update_id": text("strong_observation_update_id"),
        "public_fact_snapshot_id": text("public_fact_snapshot_id"),
        "decision_id": text("decision_id"),
        "decision_action": text("decision_action"),
        "decision_state": text("decision_state"),
        "source_response_to_posterior_apply_start_ms": _ui_snapshot_timing_ms(
            timing_map.get("source_response_to_posterior_apply_start_ms")
        ),
        "source_fact_to_posterior_apply_start_ms": _ui_snapshot_timing_ms(
            timing_map.get("source_fact_to_posterior_apply_start_ms")
        ),
        "source_valid_to_posterior_apply_start_ms": _ui_snapshot_timing_ms(
            timing_map.get("source_valid_to_posterior_apply_start_ms")
        ),
        "task_queue_wait_ms": _ui_snapshot_timing_ms(timing_map.get("task_queue_wait_ms")),
        "task_created_to_posterior_apply_start_ms": _ui_snapshot_timing_ms(
            timing_map.get("task_created_to_posterior_apply_start_ms")
        ),
        "posterior_apply_runtime_ms": _ui_snapshot_timing_ms(timing_map.get("posterior_apply_runtime_ms")),
        "checkpoint_to_public_fact_ms": _ui_snapshot_timing_ms(
            timing_map.get("checkpoint_to_public_fact_ms")
        ),
        "public_fact_to_decision_ms": _ui_snapshot_timing_ms(
            timing_map.get("public_fact_to_decision_ms")
        ),
        "latest_temperature_c": timing_map.get("latest_temperature_c"),
        "latest_observed_today_max_c": timing_map.get("latest_observed_today_max_c"),
        "source_history_fact_ids": [
            _to_int(value)
            for value in timing_map.get("source_history_fact_ids") or []
            if _to_int(value) is not None
        ],
        "source_history_fact_count": _to_int(timing_map.get("source_history_fact_count")),
        "source_history_merged_observation_count": _to_int(
            timing_map.get("source_history_merged_observation_count")
        ),
        "source_event_ids": source_event_ids[:20],
        "source_observation_ids": source_observation_ids[:20],
        "latest_source_event_id": latest_source_event_id,
        "latest_source_observation_id": latest_source_observation_id,
        "order_signal_applicability": text("order_signal_applicability"),
        "amsc_latency_slo_audit": _ui_snapshot_amsc_latency_slo_audit_from_timing(timing_map),
        "guards": copy.deepcopy(timing_map.get("guards")) if isinstance(timing_map.get("guards"), Mapping) else {},
        "read_only": True,
        "frontend_recompute_allowed": False,
        "decision_recompute_allowed": False,
    }
    return {key: value for key, value in row.items() if value not in (None, "", [], {})}


def _ui_snapshot_source_to_posterior_section(
    items: Sequence[Mapping[str, Any]],
    *,
    freshness_state: str,
    freshness_reason: str,
    latest_decision_at: str = "",
) -> Dict[str, Any]:
    timing_rows = [
        row
        for raw_item in items[:200]
        if isinstance(raw_item, Mapping)
        for row in (_ui_snapshot_source_to_posterior_timing_from_item(raw_item),)
        if row
    ]
    timing_rows.sort(
        key=lambda row: _ui_snapshot_timestamp_sort_value(
            row.get("posterior_apply_completed_at"),
            row.get("posterior_apply_started_at"),
            row.get("latest_source_response_completed_at"),
            row.get("latest_source_fact_as_of"),
        ),
        reverse=True,
    )
    if not timing_rows:
        return {
            "schema": "ui_snapshot_source_to_posterior_section_v1",
            "state": "empty" if not items else "missing",
            "source": "facts.items[].source_to_posterior_timing",
            "read_only": True,
            "timing_count": 0,
            "items": [],
            "latest": {},
            "na_reason": "source_to_posterior_timing_missing" if items else "no_fact_items",
            "frontend_recompute_allowed": False,
            "decision_recompute_allowed": False,
        }
    latest = dict(timing_rows[0])
    posterior_apply_at = str(
        latest.get("posterior_apply_completed_at") or latest.get("posterior_apply_started_at") or ""
    )
    order_signal_applicability = str(latest.get("order_signal_applicability") or "")
    decision_state = "not_applicable_no_order_signal"
    posterior_to_decision_ms: Optional[int] = None
    if order_signal_applicability == "not_applicable_no_order_signal":
        decision_state = "not_applicable_no_order_signal"
    elif latest_decision_at:
        decision_dt = parse_any_ts(latest_decision_at)
        posterior_dt = parse_any_ts(posterior_apply_at)
        if decision_dt is not None and posterior_dt is not None and decision_dt >= posterior_dt:
            posterior_to_decision_ms = _ui_snapshot_timing_ms(
                (decision_dt - posterior_dt).total_seconds() * 1000.0
            )
            decision_state = "decision_after_latest_posterior"
        else:
            decision_state = "latest_decision_before_latest_posterior"
    else:
        decision_state = "decision_missing_after_posterior"
    latest_audit_raw = copy.deepcopy(latest.get("amsc_latency_slo_audit")) if isinstance(
        latest.get("amsc_latency_slo_audit"), Mapping
    ) else {}
    if order_signal_applicability != "not_applicable_no_order_signal" and latest_decision_at:
        latest_audit_raw["decision_at"] = latest_decision_at
    latest_audit = _ui_snapshot_amsc_latency_slo_audit_from_timing(
        {
            "source_provider": latest.get("source_provider"),
            "latest_source_id": latest.get("latest_source_id") or latest.get("source_id"),
            "latest_source_event_id": latest.get("latest_source_event_id"),
            "latest_source_observation_id": latest.get("latest_source_observation_id"),
            "latest_source_valid_time": latest.get("latest_source_valid_time"),
            "latest_source_response_completed_at": latest.get("latest_source_response_completed_at"),
            "latest_source_fact_as_of": latest.get("latest_source_fact_as_of"),
            "posterior_apply_completed_at": latest.get("posterior_apply_completed_at"),
            "posterior_apply_started_at": latest.get("posterior_apply_started_at"),
            "amsc_latency_slo_audit": latest_audit_raw,
        }
    )
    if posterior_to_decision_ms is not None:
        latest_audit["posterior_to_decision_ms"] = posterior_to_decision_ms
        latest_audit.setdefault("stage_latencies_ms", {})["posterior_to_decision"] = posterior_to_decision_ms
    latest["amsc_latency_slo_audit"] = latest_audit
    latest_ms = latest_audit.get("fetched_to_posterior_ms")
    if latest_ms is None:
        latest_ms = latest.get("source_fact_to_posterior_apply_start_ms")
    return {
        "schema": "ui_snapshot_source_to_posterior_section_v1",
        "state": freshness_state,
        "source": "facts.items[].source_to_posterior_timing",
        "read_only": True,
        "timing_count": len(timing_rows),
        "latest": latest,
        "items": timing_rows[:20],
        "latest_source_response_completed_at": str(latest.get("latest_source_response_completed_at") or ""),
        "latest_source_fact_as_of": str(latest.get("latest_source_fact_as_of") or ""),
        "latest_source_valid_time": str(latest.get("latest_source_valid_time") or ""),
        "latest_posterior_apply_started_at": str(latest.get("posterior_apply_started_at") or ""),
        "latest_posterior_apply_completed_at": str(latest.get("posterior_apply_completed_at") or ""),
        "latest_source_to_posterior_ms": latest_ms,
        "latest_source_response_to_posterior_ms": latest_audit.get("fetched_to_posterior_ms"),
        "task_queue_wait_ms": latest.get("task_queue_wait_ms"),
        "source_provider": str(latest.get("source_provider") or ""),
        "latest_source_id": str(latest.get("latest_source_id") or latest.get("source_id") or ""),
        "order_signal_applicability": order_signal_applicability,
        "decision_candidate_state": decision_state,
        "latest_decision_at": latest_decision_at,
        "posterior_to_decision_ms": posterior_to_decision_ms,
        "amsc_latency_slo_audit": latest_audit,
        "stale_reason": freshness_reason if freshness_state != "fresh" else "",
        "na_reason": "",
        "next_boundary": "auto_trade_decisions",
        "frontend_recompute_allowed": False,
        "decision_recompute_allowed": False,
    }


def _ui_snapshot_signal_to_order_timing_from_item(raw_item: Mapping[str, Any]) -> Dict[str, Any]:
    if not isinstance(raw_item, Mapping):
        return {}
    timing = raw_item.get("signal_to_order_timing")
    timing_map = timing if isinstance(timing, Mapping) else {}
    if not timing_map:
        return {}
    signal_at = _ui_snapshot_first_text(
        timing_map.get("awc_hard_source_signal_at"),
        raw_item.get("awc_hard_source_signal_at"),
    )
    if not signal_at:
        return {}
    schema = str(timing_map.get("schema") or "").strip()
    if schema == "signal_to_order_timing_placeholder_v1":
        return {}

    def text(key: str, *fallbacks: Any) -> str:
        return _ui_snapshot_first_text(timing_map.get(key), *fallbacks)

    terminal_state = text("terminal_state") or "pending"
    terminal_at = text(
        "terminal_at",
        "order_submitted_at",
        "exchange_ack_at",
        "order_ack_at",
        "job_enqueued_at",
        "decision_written_at",
        "posterior_written_at",
        "fact_written_at",
    )
    if terminal_at in {
        "order_submitted_at",
        "exchange_ack_at",
        "order_ack_at",
        "job_enqueued_at",
        "decision_written_at",
        "posterior_written_at",
        "fact_written_at",
    }:
        terminal_at = text(terminal_at)
    row: Dict[str, Any] = {
        "schema": "ui_snapshot_awc_signal_to_order_timing_row_v1",
        "state": "available",
        "source": "facts.items[].signal_to_order_timing",
        "signal_id": text("signal_id", raw_item.get("signal_id")),
        "source_event_id": text("source_event_id", raw_item.get("source_event_id")),
        "source_observation_id": text("source_observation_id", raw_item.get("source_observation_id")),
        "source_id": text("source_id"),
        "slug": text("slug", raw_item.get("slug")),
        "event_date": _normalize_date_key(text("event_date", raw_item.get("event_date"))),
        "fact_id": _to_int(raw_item.get("fact_id")),
        "fact_snapshot_id": text("fact_snapshot_id", raw_item.get("fact_snapshot_id")),
        "posterior_run_id": text("posterior_run_id", raw_item.get("posterior_run_id")),
        "awc_valid_time": text("awc_valid_time"),
        "awc_hard_source_signal_at": signal_at,
        "source_fetched_at": text("source_fetched_at"),
        "source_parsed_at": text("source_parsed_at"),
        "fact_written_at": text("fact_written_at", timing_map.get("fact_snapshot_written_at")),
        "posterior_written_at": text("posterior_written_at"),
        "decision_started_at": text("decision_started_at"),
        "decision_written_at": text("decision_written_at", timing_map.get("auto_trade_decision_written_at")),
        "job_enqueued_at": text("job_enqueued_at", timing_map.get("order_job_enqueued_at")),
        "execution_consumer_seen_decision_at": text("execution_consumer_seen_decision_at"),
        "orderbook_checked_at": text("orderbook_checked_at"),
        "risk_checked_at": text("risk_checked_at"),
        "idempotency_checked_at": text("idempotency_checked_at"),
        "submit_requested_at": text("submit_requested_at"),
        "exchange_ack_at": text("exchange_ack_at", timing_map.get("order_ack_at")),
        "order_submitted_at": text("order_submitted_at"),
        "terminal_at": terminal_at,
        "terminal_state": terminal_state,
        "terminal_reason": text("terminal_reason", timing_map.get("signal_to_order_slo_violation_reason")),
        "acceptance_state": text("acceptance_state"),
        "acceptance_reason": text("acceptance_reason"),
        "pre_signal_prepare_state": text("pre_signal_prepare_state"),
        "pre_signal_prepare_reason": text("pre_signal_prepare_reason"),
        "pre_signal_prepare_complete": timing_map.get("pre_signal_prepare_complete"),
        "pre_signal_prepared_before_deadline": timing_map.get("pre_signal_prepared_before_deadline"),
        "pre_signal_prepare_missing_components": [
            str(value or "").strip()
            for value in timing_map.get("pre_signal_prepare_missing_components") or []
            if str(value or "").strip()
        ],
        "signal_to_fact_ms": _ui_snapshot_timing_ms(timing_map.get("signal_to_fact_ms")),
        "signal_to_decision_ms": _ui_snapshot_timing_ms(timing_map.get("signal_to_decision_ms")),
        "signal_to_job_enqueue_ms": _ui_snapshot_timing_ms(timing_map.get("signal_to_job_enqueue_ms")),
        "signal_to_order_submit_ms": _ui_snapshot_timing_ms(
            timing_map.get("awc_signal_to_order_submit_ms") or timing_map.get("signal_to_order_submit_ms")
        ),
        "signal_to_terminal_ms": _ui_snapshot_timing_ms(timing_map.get("signal_to_terminal_ms")),
        "signal_to_order_slo_ms": _ui_snapshot_timing_ms(timing_map.get("signal_to_order_slo_ms")),
        "signal_to_order_slo_met": timing_map.get("signal_to_order_slo_met"),
        "signal_to_order_slo_violation_reason": text("signal_to_order_slo_violation_reason"),
        "guards": copy.deepcopy(timing_map.get("guards")) if isinstance(timing_map.get("guards"), Mapping) else {},
        "read_only": True,
        "frontend_recompute_allowed": False,
        "decision_recompute_allowed": False,
    }
    return {key: value for key, value in row.items() if value not in (None, "", [], {})}


def _ui_snapshot_v6_execution_deadline_from_item(raw_item: Mapping[str, Any]) -> Dict[str, Any]:
    if not isinstance(raw_item, Mapping):
        return {}
    timing = raw_item.get("v6_execution_deadline_timing")
    if not isinstance(timing, Mapping) or not timing:
        return {}
    row = copy.deepcopy(dict(timing))
    row.setdefault("schema", "v6_execution_deadline_timing_ssot_v1")
    row.setdefault("slug", str(raw_item.get("slug") or ""))
    row.setdefault("event_date", _normalize_date_key(str(raw_item.get("event_date") or "")))
    row["read_only"] = True
    row["frontend_recompute_allowed"] = False
    row["decision_recompute_allowed"] = False
    return row


def _ui_snapshot_awc_signal_to_order_section(
    items: Sequence[Mapping[str, Any]],
    *,
    freshness_state: str,
    freshness_reason: str,
) -> Dict[str, Any]:
    v6_rows = [
        row
        for raw_item in items[:200]
        if isinstance(raw_item, Mapping)
        for row in (_ui_snapshot_v6_execution_deadline_from_item(raw_item),)
        if row
    ]
    v6_rows.sort(
        key=lambda row: _ui_snapshot_timestamp_sort_value(
            row.get("exchange_post_started_at"),
            row.get("outbox_completed_at"),
            row.get("decision_written_at"),
            row.get("transaction_b_committed_at"),
        ),
        reverse=True,
    )
    if v6_rows:
        latest = dict(v6_rows[0])
        fail_closed = latest.get("fail_closed") is True
        deadline_met = latest.get("deadline_met") is True
        terminal_state = str(latest.get("state") or "execution_pending")
        return {
            "schema": "ui_snapshot_v6_execution_deadline_section_v1",
            "state": "blocked" if fail_closed else freshness_state,
            "source": "facts.items[].v6_execution_deadline_timing",
            "read_only": True,
            "timing_count": len(v6_rows),
            "canonical_event_count": len(v6_rows),
            "submitted_count": sum(1 for row in v6_rows if row.get("deadline_met") is True),
            "deadline_met_count": sum(1 for row in v6_rows if row.get("deadline_met") is True),
            "fail_closed_count": sum(1 for row in v6_rows if row.get("fail_closed") is True),
            "latest": latest,
            "items": v6_rows[:20],
            "latest_terminal_at": str(
                latest.get("exchange_post_started_at")
                or latest.get("outbox_completed_at")
                or latest.get("decision_written_at")
                or ""
            ),
            "latest_terminal_state": terminal_state,
            "latest_terminal_reason": str(latest.get("terminal_reason") or ""),
            "latest_signal_to_order_ms": latest.get("actionable_to_terminal_ms"),
            "signal_to_order_slo_ms": latest.get("deadline_budget_ms"),
            "signal_to_order_slo_met": deadline_met,
            "signal_to_order_slo_violation_reason": (
                str(latest.get("terminal_reason") or "") if fail_closed else ""
            ),
            "deadline_policy": str(latest.get("deadline_policy") or ""),
            "deadline_at": str(latest.get("observation_to_order_hard_deadline_at") or ""),
            "deadline_overrun_ms": latest.get("deadline_overrun_ms"),
            "remaining_at_commit_ms": latest.get("remaining_at_commit_ms"),
            "outbox_state": str(latest.get("outbox_state") or ""),
            "outbox_attempt_count": int(_to_int(latest.get("outbox_attempt_count")) or 0),
            "called_gateway": latest.get("called_gateway") is True,
            "gateway_response_present": latest.get("gateway_response_present") is True,
            "fail_closed": fail_closed,
            "stale_reason": str(latest.get("terminal_reason") or "") if fail_closed else "",
            "na_reason": "",
            "frontend_recompute_allowed": False,
            "decision_recompute_allowed": False,
        }
    timing_rows = [
        row
        for raw_item in items[:200]
        if isinstance(raw_item, Mapping)
        for row in (_ui_snapshot_signal_to_order_timing_from_item(raw_item),)
        if row
    ]
    timing_rows.sort(
        key=lambda row: _ui_snapshot_timestamp_sort_value(
            row.get("order_submitted_at"),
            row.get("terminal_at"),
            row.get("decision_written_at"),
            row.get("awc_hard_source_signal_at"),
        ),
        reverse=True,
    )
    if not timing_rows:
        return {
            "schema": "ui_snapshot_awc_signal_to_order_section_v1",
            "state": "empty",
            "source": "facts.items[].signal_to_order_timing",
            "read_only": True,
            "timing_count": 0,
            "items": [],
            "latest": {},
            "accepted_signal_count": 0,
            "submitted_signal_count": 0,
            "slo_met_count": 0,
            "slo_miss_count": 0,
            "na_reason": "awc_signal_to_order_timing_not_applicable_or_no_sample" if items else "no_fact_items",
            "frontend_recompute_allowed": False,
            "decision_recompute_allowed": False,
        }
    accepted_count = sum(
        1
        for row in timing_rows
        if str(row.get("acceptance_state") or "").strip() in {"accepted", "eligible", ""}
    )
    submitted_count = sum(1 for row in timing_rows if str(row.get("terminal_state") or "") == "submitted")
    slo_met_count = sum(1 for row in timing_rows if row.get("signal_to_order_slo_met") is True)
    slo_miss_count = sum(1 for row in timing_rows if row.get("signal_to_order_slo_met") is False)
    latest = dict(timing_rows[0])
    terminal_state = str(latest.get("terminal_state") or "pending")
    latest_ms = latest.get("signal_to_order_submit_ms")
    if latest_ms is None:
        latest_ms = latest.get("signal_to_terminal_ms")
    if terminal_state in {"error"}:
        state = "error"
    elif terminal_state in {"blocked", "stale", "skipped", "no_action"} or latest.get("signal_to_order_slo_met") is False:
        state = "stale"
    else:
        state = freshness_state
    return {
        "schema": "ui_snapshot_awc_signal_to_order_section_v1",
        "state": state,
        "source": "facts.items[].signal_to_order_timing",
        "read_only": True,
        "timing_count": len(timing_rows),
        "accepted_signal_count": accepted_count,
        "submitted_signal_count": submitted_count,
        "slo_met_count": slo_met_count,
        "slo_miss_count": slo_miss_count,
        "latest": latest,
        "items": timing_rows[:20],
        "latest_signal_id": str(latest.get("signal_id") or ""),
        "latest_signal_at": str(latest.get("awc_hard_source_signal_at") or ""),
        "latest_terminal_at": str(latest.get("terminal_at") or ""),
        "latest_terminal_state": terminal_state,
        "latest_terminal_reason": str(latest.get("terminal_reason") or ""),
        "latest_signal_to_order_ms": latest_ms,
        "latest_signal_to_fact_ms": latest.get("signal_to_fact_ms"),
        "latest_signal_to_decision_ms": latest.get("signal_to_decision_ms"),
        "latest_signal_to_job_enqueue_ms": latest.get("signal_to_job_enqueue_ms"),
        "signal_to_order_slo_ms": latest.get("signal_to_order_slo_ms"),
        "signal_to_order_slo_met": latest.get("signal_to_order_slo_met"),
        "signal_to_order_slo_violation_reason": str(latest.get("signal_to_order_slo_violation_reason") or ""),
        "pre_signal_prepare_state": str(latest.get("pre_signal_prepare_state") or ""),
        "pre_signal_prepare_complete": latest.get("pre_signal_prepare_complete"),
        "pre_signal_prepared_before_deadline": latest.get("pre_signal_prepared_before_deadline"),
        "safety_checks": {
            "orderbook_checked_at": str(latest.get("orderbook_checked_at") or ""),
            "risk_checked_at": str(latest.get("risk_checked_at") or ""),
            "idempotency_checked_at": str(latest.get("idempotency_checked_at") or ""),
            "submit_requested_at": str(latest.get("submit_requested_at") or ""),
            "exchange_ack_at": str(latest.get("exchange_ack_at") or ""),
        },
        "stale_reason": (
            str(latest.get("signal_to_order_slo_violation_reason") or latest.get("terminal_reason") or "")
            if state in {"stale", "error"}
            else freshness_reason
            if freshness_state != "fresh"
            else ""
        ),
        "na_reason": "",
        "frontend_recompute_allowed": False,
        "decision_recompute_allowed": False,
    }


def _ui_snapshot_compact_decision_row(row: Mapping[str, Any]) -> Dict[str, Any]:
    reason_codes = row.get("reason_codes")
    reasons = row.get("reasons")
    return {
        "slug": str(row.get("slug") or ""),
        "event_date": _normalize_date_key(str(row.get("event_date") or "")),
        "title": str(row.get("title") or ""),
        "outcome": str(row.get("outcome") or ""),
        "side": str(row.get("side") or ""),
        "action": str(row.get("action") or ""),
        "decided_state": str(row.get("decided_state") or ""),
        "will_order": int(_to_int(row.get("will_order")) or 0),
        "reason_codes": list(reason_codes) if isinstance(reason_codes, list) else [],
        "reasons": list(reasons) if isinstance(reasons, list) else [],
        "created_at": str(row.get("created_at") or ""),
    }


def _ui_snapshot_orderbook_blocker_codes(
    blocked_reasons: Sequence[Mapping[str, Any]],
    decision_rows: Sequence[Mapping[str, Any]],
) -> List[str]:
    codes: List[str] = []
    for row in blocked_reasons:
        code = str(row.get("code") or "").strip()
        if code and "orderbook" in code.lower():
            _ui_snapshot_append_unique_text(codes, code)
    for row in decision_rows:
        for code_value in row.get("reason_codes") or []:
            code = str(code_value or "").strip()
            if code and "orderbook" in code.lower():
                _ui_snapshot_append_unique_text(codes, code)
    return codes


def _ui_snapshot_operator_apply_gate_summary(payload: Mapping[str, Any]) -> Dict[str, Any]:
    source = ""
    summary: Any = payload.get("operator_apply_gate_summary")
    if isinstance(summary, Mapping):
        source = "operator_apply_gate_summary"
    else:
        attachments = payload.get("audit_attachments")
        attachments_map = attachments if isinstance(attachments, Mapping) else {}
        summary = attachments_map.get("operator_apply_gate_summary")
        if isinstance(summary, Mapping):
            source = "audit_attachments.operator_apply_gate_summary"
    if not isinstance(summary, Mapping):
        return {
            "schema": "ui_snapshot_apply_gate_summary_v1",
            "available": False,
            "read_only": True,
            "state": "missing",
            "source": "operator_apply_gate_summary",
            "source_schema": "",
            "na_reason": "operator_apply_gate_summary_not_attached",
            "gates": [],
        }
    gates: List[Dict[str, Any]] = []
    for raw_gate in summary.get("gates") or []:
        if not isinstance(raw_gate, Mapping):
            continue
        blockers_now = [
            str(blocker or "").strip()
            for blocker in raw_gate.get("blockers_now") or []
            if str(blocker or "").strip()
        ]
        applicable = bool(raw_gate.get("applicable"))
        ready_now = bool(raw_gate.get("ready_now"))
        ready_after_operator_preflight = bool(raw_gate.get("ready_after_operator_preflight"))
        blocked = bool(raw_gate.get("blocked"))
        if blocked:
            gate_state = "blocked"
        elif ready_now:
            gate_state = "ready_now"
        elif ready_after_operator_preflight:
            gate_state = "operator_preflight_ready"
        elif not applicable:
            gate_state = "not_applicable"
        else:
            gate_state = "pending"
        gates.append(
            {
                "gate": str(raw_gate.get("gate") or ""),
                "state": gate_state,
                "applicable": applicable,
                "ready_now": ready_now,
                "ready_after_operator_preflight": ready_after_operator_preflight,
                "blocked": blocked,
                "blockers_now": blockers_now[:10],
                "reason": str(raw_gate.get("reason") or ""),
                "source": str(raw_gate.get("source") or ""),
            }
        )
    ok = summary.get("ok") is not False
    ready_now = bool(summary.get("ready_now"))
    ready_after_operator_preflight = bool(summary.get("ready_after_operator_preflight"))
    first_blocked_gate = str(summary.get("first_blocked_gate") or "")
    if not ok:
        state = "error"
    elif ready_now:
        state = "ready_now"
    elif ready_after_operator_preflight:
        state = "operator_preflight_ready"
    elif first_blocked_gate or any(gate.get("blocked") for gate in gates):
        state = "blocked"
    else:
        state = "available"
    return {
        "schema": "ui_snapshot_apply_gate_summary_v1",
        "available": True,
        "read_only": summary.get("read_only") is not False,
        "state": state,
        "source": source,
        "source_schema": str(summary.get("schema") or ""),
        "execution_mode": str(summary.get("execution_mode") or ""),
        "ready_now": ready_now,
        "ready_after_operator_preflight": ready_after_operator_preflight,
        "first_blocked_gate": first_blocked_gate,
        "actionable_blocked_gates": [
            str(gate or "").strip()
            for gate in summary.get("actionable_blocked_gates") or []
            if str(gate or "").strip()
        ][:10],
        "gate_count": len(gates),
        "gates": gates[:5],
        "na_reason": "",
    }


def _build_ui_snapshot_dashboard_sections(
    payload: Mapping[str, Any],
    *,
    facts_map: Mapping[str, Any],
    items: Sequence[Mapping[str, Any]],
    freshness_state: str,
    freshness_reason: str,
    latest_fact_as_of: str,
    posterior_available_count: int,
    posterior_not_materialized_count: int,
    posterior_missing_count: int,
    latest_posterior_as_of: str,
) -> Dict[str, Any]:
    follow = payload.get("path_probability_follow")
    follow_map = follow if isinstance(follow, Mapping) else {}
    entry = follow_map.get("entry")
    entry_map = entry if isinstance(entry, Mapping) else {}
    jobs = follow_map.get("jobs")
    jobs_map = jobs if isinstance(jobs, Mapping) else {}
    entry_counts_raw = entry_map.get("counts")
    entry_counts = dict(entry_counts_raw) if isinstance(entry_counts_raw, Mapping) else {}
    blocked_reasons_raw = entry_map.get("blocked_reasons")
    blocked_reasons = [
        dict(row) for row in blocked_reasons_raw or [] if isinstance(row, Mapping)
    ]
    latest_rows_raw = entry_map.get("latest")
    decision_rows = [
        _ui_snapshot_compact_decision_row(row)
        for row in latest_rows_raw or []
        if isinstance(row, Mapping)
    ]
    latest_decision_at = _ui_snapshot_latest_timestamp_text(
        *[row.get("created_at") for row in decision_rows]
    )
    source_to_posterior_section = _ui_snapshot_source_to_posterior_section(
        items,
        freshness_state=freshness_state,
        freshness_reason=freshness_reason,
        latest_decision_at=latest_decision_at,
    )
    awc_signal_to_order_section = _ui_snapshot_awc_signal_to_order_section(
        items,
        freshness_state=freshness_state,
        freshness_reason=freshness_reason,
    )
    decision_total = _to_int(entry_counts.get("total")) or len(decision_rows)
    decision_present = bool(decision_total or decision_rows or blocked_reasons)
    decision_state = freshness_state if decision_present else ("empty" if not items else "missing")
    orderbook_blockers = _ui_snapshot_orderbook_blocker_codes(blocked_reasons, decision_rows)
    orderbook_state = (
        "stale"
        if orderbook_blockers
        else (freshness_state if decision_present else ("empty" if not items else "missing"))
    )
    orderbook_na_reason = "" if decision_present else "auto_trade_decisions_missing_or_no_rows"
    orderbook_stale_reason = ",".join(orderbook_blockers[:6])

    jobs_counts_raw = jobs_map.get("counts")
    jobs_counts = dict(jobs_counts_raw) if isinstance(jobs_counts_raw, Mapping) else {}
    jobs_updated_at = str(jobs_map.get("updated_at") or "")
    positions = payload.get("positions")
    positions_map = positions if isinstance(positions, Mapping) else {}
    fills = payload.get("fills")
    fills_map = fills if isinstance(fills, Mapping) else {}
    position_sync_at = str(positions_map.get("sync_at") or "")
    latest_execution_at = _ui_snapshot_latest_timestamp_text(jobs_updated_at, position_sync_at)
    execution_present = bool(jobs_counts or jobs_updated_at or positions_map or fills_map)
    execution_state = freshness_state if execution_present else ("empty" if not items else "missing")

    review_items: List[Dict[str, Any]] = []
    for item in items:
        review_state = item.get("daily_review_state")
        review_map = review_state if isinstance(review_state, Mapping) else {}
        review_id = _ui_snapshot_first_text(
            item.get("review_id"),
            review_map.get("review_id"),
            review_map.get("id"),
        )
        if not review_id and not review_map:
            continue
        generated_at = _ui_snapshot_latest_timestamp_text(
            review_map.get("generated_at"),
            review_map.get("created_at"),
            review_map.get("reviewed_at"),
            item.get("review_generated_at"),
        )
        review_items.append(
            {
                "slug": str(item.get("slug") or ""),
                "event_date": _normalize_date_key(str(item.get("event_date") or "")),
                "review_id": review_id,
                "generated_at": generated_at,
                "state": str(review_map.get("state") or ("ready" if review_id else "present")),
                "first_bad_link": str(review_map.get("first_bad_link") or ""),
            }
        )
    latest_review_at = _ui_snapshot_latest_timestamp_text(
        *[row.get("generated_at") for row in review_items]
    )
    review_state = freshness_state if review_items else ("empty" if not items else "missing")
    latest_review_id = next(
        (str(row.get("review_id") or "") for row in review_items if row.get("review_id")),
        "",
    )
    apply_gate_summary = _ui_snapshot_operator_apply_gate_summary(payload)

    facts_total = facts_map.get("total")
    posterior_state = (
        freshness_state
        if posterior_available_count > 0
        else "pending"
        if posterior_not_materialized_count > 0
        else "missing"
        if posterior_missing_count > 0 or items
        else "empty"
    )
    posterior_na_reason = (
        ""
        if posterior_available_count > 0
        else "posterior_ssot_fact_not_materialized"
        if posterior_not_materialized_count > 0
        else ("posterior_ssot_fact_missing" if items else "no_fact_items")
    )
    return {
        "schema": "ui_snapshot_dashboard_sections_v1",
        "read_only": True,
        "source": "/api/ui_snapshot",
        "order": ["facts", "source_to_posterior", "posterior", "awc_signal_to_order", "decisions", "execution", "review"],
        "facts": {
            "schema": "ui_snapshot_facts_section_v1",
            "state": freshness_state,
            "source": str(facts_map.get("source") or ""),
            "item_count": len(items),
            "total": facts_total,
            "latest_fact_as_of": latest_fact_as_of,
            "stale_reason": freshness_reason if freshness_state != "fresh" else "",
            "na_reason": "" if items else "no_fact_items",
        },
        "posterior": {
            "schema": "ui_snapshot_posterior_section_v1",
            "state": posterior_state,
            "source": "facts.items[].ui_sections.bayes_posterior_ssot",
            "available_count": posterior_available_count,
            "not_materialized_count": posterior_not_materialized_count,
            "missing_count": posterior_missing_count,
            "latest_posterior_as_of": latest_posterior_as_of,
            "stale_reason": freshness_reason if posterior_state != "fresh" and freshness_state != "fresh" else "",
            "na_reason": posterior_na_reason,
        },
        "source_to_posterior": source_to_posterior_section,
        "awc_signal_to_order": awc_signal_to_order_section,
        "decisions": {
            "schema": "ui_snapshot_decisions_section_v1",
            "state": decision_state,
            "source": "auto_trade_decisions",
            "counts": entry_counts,
            "latest_decision_at": latest_decision_at,
            "blocked_reasons": blocked_reasons[:20],
            "latest": decision_rows[:20],
            "stale_reason": freshness_reason if decision_state != "fresh" and freshness_state != "fresh" else "",
            "na_reason": "" if decision_present else "auto_trade_decisions_missing_or_no_rows",
        },
        "execution": {
            "schema": "ui_snapshot_execution_section_v1",
            "state": execution_state,
            "source": "auto_trade_jobs+positions+fills",
            "jobs": {
                "counts": jobs_counts,
                "updated_at": jobs_updated_at,
            },
            "positions": dict(positions_map),
            "fills": dict(fills_map),
            "latest_execution_at": latest_execution_at,
            "orderbook": {
                "state": orderbook_state,
                "source": "auto_trade_decisions.reason_codes",
                "stale_reason": orderbook_stale_reason,
                "na_reason": orderbook_na_reason,
            },
            "stale_reason": freshness_reason if execution_state != "fresh" and freshness_state != "fresh" else "",
            "na_reason": "" if execution_present else "execution_facts_missing",
        },
        "review": {
            "schema": "ui_snapshot_review_section_v1",
            "state": review_state,
            "source": "facts.items[].daily_review_state",
            "review_count": len(review_items),
            "latest_review_id": latest_review_id,
            "latest_review_at": latest_review_at,
            "items": review_items[:20],
            "apply_gate_summary": apply_gate_summary,
            "apply_gate_na_reason": "" if apply_gate_summary.get("available") else str(apply_gate_summary.get("na_reason") or ""),
            "stale_reason": freshness_reason if review_state != "fresh" and freshness_state != "fresh" else "",
            "na_reason": "" if review_items else "daily_review_not_materialized_or_not_linked",
        },
    }


def _ui_snapshot_section_panel_freshness(section: Mapping[str, Any]) -> Dict[str, Any]:
    panel = {
        "state": str(section.get("state") or ""),
        "source": str(section.get("source") or ""),
        "stale_reason": str(section.get("stale_reason") or ""),
        "na_reason": str(section.get("na_reason") or ""),
    }
    for key in (
        "latest_fact_as_of",
        "latest_posterior_as_of",
        "latest_decision_at",
        "latest_execution_at",
        "latest_review_at",
        "latest_source_response_completed_at",
        "latest_source_fact_as_of",
        "latest_source_valid_time",
        "latest_posterior_apply_started_at",
        "latest_posterior_apply_completed_at",
        "latest_source_to_posterior_ms",
        "latest_source_response_to_posterior_ms",
        "task_queue_wait_ms",
        "posterior_to_decision_ms",
        "latest_source_id",
        "source_provider",
        "order_signal_applicability",
        "decision_candidate_state",
        "latest_signal_id",
        "latest_signal_at",
        "latest_terminal_at",
        "latest_terminal_state",
        "latest_terminal_reason",
        "latest_signal_to_order_ms",
        "latest_signal_to_fact_ms",
        "latest_signal_to_decision_ms",
        "latest_signal_to_job_enqueue_ms",
        "signal_to_order_slo_ms",
        "signal_to_order_slo_met",
        "signal_to_order_slo_violation_reason",
        "accepted_signal_count",
        "submitted_signal_count",
        "slo_met_count",
        "slo_miss_count",
        "pre_signal_prepare_state",
        "pre_signal_prepare_complete",
        "pre_signal_prepared_before_deadline",
        "available_count",
        "not_materialized_count",
        "missing_count",
        "item_count",
        "review_count",
    ):
        if key in section:
            panel[key] = section.get(key)
    return panel


def _attach_ui_snapshot_phase0_contract(
    payload: Dict[str, Any],
    *,
    cache_key: str = "",
) -> Dict[str, Any]:
    if not isinstance(payload, dict):
        return payload
    facts = payload.get("facts")
    facts_map = facts if isinstance(facts, Mapping) else {}
    items = facts_map.get("items") if isinstance(facts_map, Mapping) else []
    if not isinstance(items, list):
        items = []
    fact_id_values: List[int] = []
    fact_snapshot_ids: List[str] = []
    posterior_run_ids: List[str] = []
    source_event_ids: List[str] = []
    source_observation_ids: List[str] = []
    signal_ids: List[str] = []
    lineage_items: List[Dict[str, Any]] = []
    identity_items: List[Dict[str, Any]] = []
    latest_fact_as_of = ""
    latest_posterior_as_of = ""
    posterior_available_count = 0
    posterior_not_materialized_count = 0
    posterior_missing_count = 0
    for raw_item in items[:200]:
        if not isinstance(raw_item, Mapping):
            continue
        fact_id = _to_int(raw_item.get("fact_id"))
        if fact_id is not None:
            fact_id_values.append(int(fact_id))
        fact_as_of = str(raw_item.get("fact_as_of") or "")
        if fact_as_of and fact_as_of > latest_fact_as_of:
            latest_fact_as_of = fact_as_of
        posterior_section = _build_ui_snapshot_bayes_posterior_ssot_section(raw_item)
        posterior_state = str(posterior_section.get("state") or "").strip()
        physical_section = _build_ui_snapshot_physical_high_posterior_section(raw_item)
        physical_available = str(physical_section.get("state") or "") == "available"
        if posterior_state == "available" or (
            posterior_state == "market_projection_na" and physical_available
        ):
            posterior_available_count += 1
            posterior_as_of = str(posterior_section.get("posterior_as_of") or "")
            if posterior_as_of and posterior_as_of > latest_posterior_as_of:
                latest_posterior_as_of = posterior_as_of
        elif posterior_state in {"not_materialized", "pending"}:
            posterior_not_materialized_count += 1
        elif fact_id is not None or raw_item.get("fact_snapshot_id"):
            posterior_missing_count += 1
        lineage_item = _ui_snapshot_lineage_item(raw_item)
        if lineage_item.get("fact_id") is not None or lineage_item.get("fact_snapshot_id"):
            lineage_items.append(lineage_item)
            _ui_snapshot_append_unique_text(fact_snapshot_ids, lineage_item.get("fact_snapshot_id"))
            _ui_snapshot_append_unique_text(posterior_run_ids, lineage_item.get("posterior_run_id"))
            _ui_snapshot_append_unique_text(signal_ids, lineage_item.get("signal_id"))
            for source_event_id in lineage_item.get("source_event_ids") or []:
                _ui_snapshot_append_unique_text(source_event_ids, source_event_id)
            for source_observation_id in lineage_item.get("source_observation_ids") or []:
                _ui_snapshot_append_unique_text(source_observation_ids, source_observation_id)
        identity_items.append(
            {
                "slug": str(raw_item.get("slug") or ""),
                "event_date": _normalize_date_key(str(raw_item.get("event_date") or "")),
                "fact_id": fact_id,
                "fact_as_of": fact_as_of,
                "fact_snapshot_id": lineage_item.get("fact_snapshot_id"),
                "posterior_run_id": lineage_item.get("posterior_run_id"),
                "model_snapshot_id": _to_int(raw_item.get("model_snapshot_id")),
                "market_snapshot_id": _to_int(raw_item.get("market_snapshot_id")),
            }
        )
    generated_at = str(payload.get("as_of") or now_text())
    identity = {
        "schema": "ui_snapshot_phase0_contract_v1",
        "run_date": _normalize_date_key(str(payload.get("run_date") or "")),
        "generated_at": generated_at,
        "facts_source": str(facts_map.get("source") or "") if isinstance(facts_map, Mapping) else "",
        "items": identity_items,
    }
    digest = hashlib.sha256(
        json.dumps(identity, ensure_ascii=False, sort_keys=True, default=str).encode("utf-8")
    ).hexdigest()[:24]
    snapshot_id = f"uisnap_{digest}"
    cache_stale = bool(payload.get("cache_stale"))
    busy = bool(payload.get("busy"))
    freshness_state = "blocked" if busy else ("stale" if cache_stale else "fresh")
    freshness_reason = (
        str(payload.get("cache_stale_reason") or "")
        if cache_stale
        else ("snapshot_rebuild_in_flight" if busy else "snapshot_ready")
    )
    payload["ui_snapshot_schema_version"] = "ui_snapshot_phase0_v1"
    payload["snapshot_id"] = snapshot_id
    payload["snapshot_etag"] = f'W/"{snapshot_id}"'
    payload["snapshot_generated_at"] = generated_at
    payload["server_time"] = now_text()
    payload["snapshot_freshness_state"] = freshness_state
    payload["snapshot_freshness_reason"] = freshness_reason
    payload["source_fact_ids"] = fact_id_values[:200]
    payload["fact_snapshot_ids"] = fact_snapshot_ids[:200]
    payload["posterior_run_ids"] = posterior_run_ids[:200]
    payload["source_event_ids"] = source_event_ids[:200]
    payload["source_observation_ids"] = source_observation_ids[:200]
    payload["signal_ids"] = signal_ids[:200]
    if fact_id_values:
        payload.setdefault("primary_fact_id", fact_id_values[0])
    if fact_snapshot_ids:
        payload.setdefault("primary_fact_snapshot_id", fact_snapshot_ids[0])
        if len(fact_snapshot_ids) == 1:
            payload.setdefault("fact_snapshot_id", fact_snapshot_ids[0])
    if posterior_run_ids:
        payload.setdefault("primary_posterior_run_id", posterior_run_ids[0])
        if len(posterior_run_ids) == 1:
            payload.setdefault("posterior_run_id", posterior_run_ids[0])
    if lineage_items:
        missing_keys: List[str] = []
        chain_na_reasons: Dict[str, str] = {}
        for item in lineage_items:
            for missing_key in item.get("missing_keys") or []:
                _ui_snapshot_append_unique_text(missing_keys, missing_key)
            na_reasons = item.get("na_reasons")
            if isinstance(na_reasons, Mapping):
                for key, reason in na_reasons.items():
                    if str(reason or "").strip() and key not in chain_na_reasons:
                        chain_na_reasons[str(key)] = str(reason or "")
        fact_lineage_complete = all(
            item.get("fact_id") is not None and bool(item.get("fact_snapshot_id"))
            for item in lineage_items
        )
        execution_lineage_complete = all(
            (not item.get("hard_source_signal_expected"))
            or (bool(item.get("signal_id")) and bool(item.get("decision_id")) and bool(item.get("order_intent_id")))
            for item in lineage_items
        )
        payload["lineage_state"] = {
            "schema": "ui_snapshot_lineage_state_v1",
            "placeholder": False,
            "complete": bool(lineage_items) and not missing_keys and not chain_na_reasons,
            "fact_lineage_complete": fact_lineage_complete,
            "execution_lineage_complete": execution_lineage_complete,
            "ui_snapshot_id": snapshot_id,
            "snapshot_id": snapshot_id,
            "snapshot_cache_key": cache_key,
            "source_fact_ids": fact_id_values[:200],
            "fact_snapshot_ids": fact_snapshot_ids[:200],
            "posterior_run_ids": posterior_run_ids[:200],
            "source_event_ids": source_event_ids[:200],
            "source_observation_ids": source_observation_ids[:200],
            "signal_ids": signal_ids[:200],
            "items": lineage_items[:200],
            "missing_keys": missing_keys,
            "chain_na_reasons": chain_na_reasons,
            "source": "ui_snapshot_phase0_contract",
            "read_only": True,
        }
    else:
        payload.setdefault(
            "lineage_state",
            {
                "schema": "lineage_state_phase0_placeholder_v1",
                "placeholder": True,
                "complete": False,
                "missing_keys": [
                    "correlation_id",
                    "source_event_id",
                    "fact_snapshot_id",
                    "posterior_run_id",
                    "decision_id",
                    "signal_id",
                    "order_intent_id",
                    "review_id",
                ],
                "source": "ui_snapshot_read_model_placeholder",
            },
        )
    dashboard_sections = _build_ui_snapshot_dashboard_sections(
        payload,
        facts_map=facts_map if isinstance(facts_map, Mapping) else {},
        items=items,
        freshness_state=freshness_state,
        freshness_reason=freshness_reason,
        latest_fact_as_of=latest_fact_as_of,
        posterior_available_count=posterior_available_count,
        posterior_not_materialized_count=posterior_not_materialized_count,
        posterior_missing_count=posterior_missing_count,
        latest_posterior_as_of=latest_posterior_as_of,
    )
    payload["ui_sections"] = dashboard_sections
    if not isinstance(payload.get("panel_freshness"), MutableMapping):
        payload["panel_freshness"] = {}
    panel_freshness = payload.get("panel_freshness")
    if isinstance(panel_freshness, MutableMapping):
        for section_key in dashboard_sections.get("order") or []:
            section = dashboard_sections.get(section_key)
            if isinstance(section, Mapping):
                panel_freshness[str(section_key)] = _ui_snapshot_section_panel_freshness(section)
        execution_section = dashboard_sections.get("execution")
        execution_map = execution_section if isinstance(execution_section, Mapping) else {}
        orderbook_section = execution_map.get("orderbook")
        if isinstance(orderbook_section, Mapping):
            panel_freshness["orderbook"] = _ui_snapshot_section_panel_freshness(orderbook_section)
    if "next_recommended_poll_ms" not in payload:
        try:
            cache_ms = int(max(1000.0, min(15000.0, float(UI_SNAPSHOT_CACHE_SEC) * 1000.0)))
        except Exception:
            cache_ms = 3000
        payload["next_recommended_poll_ms"] = 1000 if freshness_state != "fresh" else cache_ms
    payload.setdefault(
        "ui_refresh_reason",
        "snapshot_rebuild_in_flight" if busy else ("cache_stale" if cache_stale else "snapshot_ready"),
    )
    if cache_key:
        payload.setdefault("snapshot_cache_key", cache_key)
    return payload


def _ui_snapshot_revalidate_allowed(cache_key: str, min_interval_sec: float) -> bool:
    if min_interval_sec <= 0:
        return True
    now_ts = time.time()
    with _UI_SNAPSHOT_REVALIDATE_LOCK:
        last_ts = float(_UI_SNAPSHOT_REVALIDATE_LAST.get(cache_key) or 0.0)
        if last_ts and (now_ts - last_ts) < float(min_interval_sec):
            return False
        _UI_SNAPSHOT_REVALIDATE_LAST[cache_key] = now_ts
        if len(_UI_SNAPSHOT_REVALIDATE_LAST) > 128:
            for old_key, _old_ts in sorted(
                _UI_SNAPSHOT_REVALIDATE_LAST.items(),
                key=lambda item: float(item[1] or 0.0),
            )[:32]:
                _UI_SNAPSHOT_REVALIDATE_LAST.pop(old_key, None)
        return True


def _ui_snapshot_cached_payload(
    entry: Tuple[float, Dict[str, Any]],
    *,
    stale: bool,
    rebuild_started: bool = False,
    rebuild_in_flight: bool = False,
    stale_reason: str = "",
    cache_key: str = "",
) -> Dict[str, Any]:
    ts, payload = entry
    out = dict(payload)
    out["ui_html_mtime"] = html_mtime()
    out["cache_hit"] = True
    out["cache_age_sec"] = max(0.0, time.time() - float(ts or 0.0))
    if stale:
        out["cache_stale"] = True
        out["cache_stale_reason"] = (
            stale_reason
            or ("snapshot_rebuild_started" if rebuild_started else "snapshot_rebuild_in_flight")
        )
        out["cache_rebuild_started"] = bool(rebuild_started)
        out["cache_rebuild_in_flight"] = bool(rebuild_in_flight)
    if cache_key:
        _attach_ui_snapshot_rebuild_status(out, cache_key)
    _attach_ui_snapshot_phase0_contract(out, cache_key=cache_key)
    return out


def _refresh_ui_snapshot_summary_envelope(payload: Dict[str, Any]) -> Dict[str, Any]:
    if isinstance(payload, dict):
        payload["ui_html_mtime"] = html_mtime()
    return payload


def _ui_snapshot_summary_payload_items(payload: Any) -> List[Dict[str, Any]]:
    if not isinstance(payload, Mapping):
        return []
    facts = payload.get("facts")
    if not isinstance(facts, Mapping):
        return []
    items = facts.get("items")
    if not isinstance(items, list):
        return []
    return [dict(item) for item in items if isinstance(item, Mapping)]


def _ui_snapshot_summary_item_has_display_ssot_contract(item: Mapping[str, Any]) -> bool:
    if not isinstance(item, Mapping):
        return False
    fact_id = _to_int(item.get("fact_id"))
    if fact_id is None or fact_id <= 0:
        return True
    if bool(item.get("summary_metadata_only")):
        return False
    if _lineage_field_for_ui_snapshot_item(item, "fact_snapshot_id") in ("", "None"):
        return False
    posterior_ssot = item.get("posterior_ssot_fact")
    if not isinstance(posterior_ssot, Mapping):
        return False
    posterior_schema = str(posterior_ssot.get("schema") or "")
    sections = item.get("ui_sections")
    sections_map = sections if isinstance(sections, Mapping) else {}
    if _is_reported_physical_x_ssot_schema(posterior_schema):
        if not str(posterior_ssot.get("posterior_run_id") or "").strip():
            return False
        physical_rows = posterior_ssot.get("reported_physical_x_distribution")
        if not isinstance(physical_rows, list) or not physical_rows:
            return False
        physical_section = sections_map.get("physical_high_posterior")
        if not isinstance(physical_section, Mapping):
            return False
        if str(physical_section.get("state") or "") != "available":
            return False
        if physical_section.get("top_temperature_c") is None:
            return False
        if physical_section.get("top_probability") is None:
            return False
        market_section = sections_map.get("bayes_posterior_ssot")
        if not isinstance(market_section, Mapping):
            return False
        market_state = str(market_section.get("state") or "")
        if market_state == "market_projection_na" and not str(
            market_section.get("na_reason") or ""
        ).strip():
            return False
        return market_state in {"available", "market_projection_na"}
    if posterior_schema == "sequential_temperature_posterior_ssot_v2":
        # The active legacy epoch remains a valid durable fact, but its
        # continuous grid is deliberately not rendered as report-defined X.
        physical_section = sections_map.get("physical_high_posterior")
        return bool(
            str(posterior_ssot.get("posterior_run_id") or "").strip()
            and isinstance(physical_section, Mapping)
            and str(physical_section.get("state") or "") == "missing"
            and str(physical_section.get("na_reason") or "")
            == "legacy_continuous_latent_distribution_is_not_reported_x"
        )
    if not _ui_snapshot_item_source_event_ids(item):
        return False
    if posterior_schema not in {
        "bayes_posterior_ssot_fact_v1",
        "bayes_posterior_ssot_fact_placeholder_v1",
    }:
        return False
    if str(posterior_ssot.get("state") or "") == "available":
        for key in ("posterior_target_bucket_selection", "target_bucket_selection"):
            if not isinstance(item.get(key), Mapping):
                return False
    if not isinstance(item.get("prior_distribution"), Mapping) and not isinstance(
        sections_map.get("prior"), Mapping
    ):
        return False
    if not (
        isinstance(item.get("metar_strong_likelihood"), Mapping)
        or bool(item.get("source_observations"))
        or isinstance(sections_map.get("observation_strong"), Mapping)
    ):
        return False
    return True


def _ui_snapshot_summary_payload_has_display_items(
    payload: Any,
    *,
    city_filter: str = "",
) -> bool:
    city_key = _normalize_ui_snapshot_city_filter(city_filter)
    matched = False
    for item in _ui_snapshot_summary_payload_items(payload):
        if not _ui_snapshot_summary_item_matches_city_filter(item, city_key):
            continue
        matched = True
        if not _ui_snapshot_summary_item_has_display_ssot_contract(item):
            return False
    return matched


def _ui_snapshot_summary_cache_entry_has_display_items(
    entry: Optional[Tuple[float, Dict[str, Any]]],
    *,
    city_filter: str = "",
) -> bool:
    if not entry or not isinstance(entry[1], Mapping):
        return False
    return _ui_snapshot_summary_payload_has_display_items(entry[1], city_filter=city_filter)


def _ui_snapshot_summary_cache_limit(limit_val: int) -> int:
    try:
        value = int(limit_val or 0)
    except (TypeError, ValueError):
        value = 24
    value = max(1, min(value, 80))
    if value <= 24:
        return 24
    return value


def _normalize_ui_snapshot_city_filter(value: str) -> str:
    raw = str(value or "").strip().lower()
    if not raw:
        return ""
    raw = raw.replace("_", " ").replace("-", " ")
    raw = re.sub(r"\s+", " ", raw).strip()
    aliases = {
        "beijing": "beijing",
        "北京": "beijing",
        "zbaa": "beijing",
        "guangzhou": "guangzhou",
        "广州": "guangzhou",
        "zggg": "guangzhou",
        "shenzhen": "shenzhen",
        "深圳": "shenzhen",
        "zgsz": "shenzhen",
        "wuhan": "wuhan",
        "武汉": "wuhan",
        "zhhh": "wuhan",
        "shanghai": "shanghai",
        "上海": "shanghai",
        "zspd": "shanghai",
        "qingdao": "qingdao",
        "青岛": "qingdao",
        "zsqd": "qingdao",
        "chongqing": "chongqing",
        "重庆": "chongqing",
        "zuck": "chongqing",
        "chengdu": "chengdu",
        "成都": "chengdu",
        "zuuu": "chengdu",
        "ctu": "chengdu",
        "chengdu zuuu": "chengdu",
    }
    if raw in aliases:
        return aliases[raw]
    station_city = _STATION_CITY_MAP.get(raw.upper())
    if station_city:
        return station_city.casefold()
    return _normalize_weather_city_label(raw).casefold()


def _ui_snapshot_summary_item_matches_city_filter(item: Any, city_filter: str) -> bool:
    city_key = _normalize_ui_snapshot_city_filter(city_filter)
    if not city_key:
        return True
    if not isinstance(item, Mapping):
        return False
    city = _normalize_city_from_fact(dict(item)).casefold()
    if city:
        return city == city_key
    slug = str(
        item.get("slug")
        or item.get("market_slug")
        or item.get("event_id")
        or item.get("condition_id")
        or ""
    )
    return city_key == "chengdu" and _is_chengdu_zuuu_fact_payload(slug, item)


def _ui_snapshot_summary_row_matches_city_filter(row: sqlite3.Row, city_filter: str) -> bool:
    city_key = _normalize_ui_snapshot_city_filter(city_filter)
    if not city_key:
        return True

    def row_get(key: str) -> Any:
        try:
            return row[key]
        except (IndexError, KeyError, TypeError):
            return None

    slug = str(row_get("slug") or "")
    row_payload = {"slug": slug, "station_id": row_get("station_id"), "city": row_get("city")}
    if _ui_snapshot_summary_item_matches_city_filter(row_payload, city_key):
        return True
    for json_key in ("summary_json", "fact_json"):
        raw = row_get(json_key)
        if raw in (None, ""):
            continue
        payload = safe_json_loads(str(raw))
        if isinstance(payload, Mapping) and _ui_snapshot_summary_item_matches_city_filter(payload, city_key):
            return True
    return False


def _compact_ui_snapshot_summary_item_for_first_screen(item: Any) -> Any:
    if not isinstance(item, Mapping):
        return item
    if item.get("summary_first_screen_compact") is True:
        out = dict(item)
        _attach_ui_temperature_trajectory_status_from_payload(out)
        _attach_ui_snapshot_sections_to_item(out)
        return out
    compact = _slim_fact_payload_for_ui_snapshot_summary(
        item,
        include_physical_detail=False,
    )
    if isinstance(compact, Mapping):
        out = dict(compact)
        out["summary_first_screen_compact"] = True
        return out
    return item


def _summary_item_event_date(item: Any) -> str:
    if not isinstance(item, Mapping):
        return ""
    return _normalize_date_key(str(item.get("event_date") or ""))


def _summary_item_likelihood_features(item: Mapping[str, Any]) -> Dict[str, Any]:
    if not isinstance(item, Mapping):
        return {}
    for key in ("weather_likelihood_features", "weather_likelihood_features_compact"):
        value = item.get(key)
        if isinstance(value, Mapping):
            return dict(value)
    summary = item.get("chengdu_intraday_summary")
    if isinstance(summary, Mapping):
        for key in ("weather_likelihood_features", "weather_likelihood_features_compact"):
            value = summary.get(key)
            if isinstance(value, Mapping):
                return dict(value)
    return {}


def _summary_item_physical_modifier(item: Mapping[str, Any]) -> Dict[str, Any]:
    if not isinstance(item, Mapping):
        return {}
    value = item.get("physical_weather_modifier")
    if isinstance(value, Mapping):
        return dict(value)
    summary = item.get("chengdu_intraday_summary")
    if isinstance(summary, Mapping) and isinstance(summary.get("physical_weather_modifier"), Mapping):
        return dict(summary.get("physical_weather_modifier") or {})
    physical = item.get("physical_likelihood")
    if isinstance(physical, Mapping) and isinstance(physical.get("weather_modifier"), Mapping):
        return dict(physical.get("weather_modifier") or {})
    return {}


def _summary_physical_num(value: Any) -> Optional[float]:
    out = to_float(value)
    if out is None or not math.isfinite(float(out)):
        return None
    return float(out)


def _summary_physical_metric(
    label: str,
    value: Optional[float],
    suffix: str = "",
    *,
    decimals: int = 1,
) -> str:
    if value is None:
        return ""
    if decimals <= 0:
        text = str(int(round(float(value))))
    else:
        text = f"{float(value):.{int(decimals)}f}"
    return f"{label} {text}{suffix}"


def _summary_physical_compact_metrics(parts: Sequence[str]) -> str:
    return " · ".join(str(part).strip() for part in parts if str(part or "").strip())


def _summary_physical_fact_age_hours(item: Mapping[str, Any]) -> Optional[float]:
    raw = str(item.get("fact_as_of") or item.get("weather_likelihood_refreshed_at") or "").strip()
    if not raw:
        return None
    try:
        dt = datetime.fromisoformat(raw.replace("Z", "+00:00"))
    except Exception:
        return None
    if dt.tzinfo is None:
        dt = dt.replace(tzinfo=timezone.utc)
    return max(0.0, (datetime.now(timezone.utc) - dt.astimezone(timezone.utc)).total_seconds() / 3600.0)


_D1_FORECAST_D0_FACT_CACHE: Dict[str, Tuple[float, Dict[str, Any]]] = {}
_D1_FORECAST_D0_FACT_CACHE_LOCK = threading.Lock()
_D1_FORECAST_D0_FACT_CACHE_SEC = max(
    5,
    int(os.environ.get("PM_UI_D1_FORECAST_D0_FACT_CACHE_SEC", "60") or 60),
)


def _summary_parse_dt_utc(value: Any) -> Optional[datetime]:
    raw = str(value or "").strip()
    if not raw:
        return None
    try:
        dt = datetime.fromisoformat(raw.replace("Z", "+00:00"))
    except Exception:
        return None
    if dt.tzinfo is None:
        dt = dt.replace(tzinfo=timezone.utc)
    return dt.astimezone(timezone.utc)


def _summary_event_zone(item: Mapping[str, Any]) -> ZoneInfo:
    raw = str(item.get("event_tz") or item.get("timezone") or "Asia/Shanghai").strip() or "Asia/Shanghai"
    try:
        return ZoneInfo(raw)
    except Exception:
        return ZoneInfo("Asia/Shanghai")


def _summary_local_midnight_utc(date_key: str, tz: ZoneInfo) -> Optional[datetime]:
    key = _normalize_date_key(str(date_key or ""))
    if not key:
        return None
    try:
        local = datetime.fromisoformat(key).replace(tzinfo=tz)
    except Exception:
        return None
    return local.astimezone(timezone.utc)


def _summary_format_local_snapshot_label(dt_utc: Optional[datetime], tz: ZoneInfo) -> str:
    if dt_utc is None:
        return ""
    local = dt_utc.astimezone(tz)
    return local.strftime("%m-%d %H:%M")


def _load_d1_forecast_fact_for_d0(d0_item: Mapping[str, Any], *, event_date_key: str) -> Dict[str, Any]:
    event_key = _normalize_date_key(event_date_key)
    slug = str(d0_item.get("slug") or d0_item.get("market_slug") or "").strip()
    if not event_key or not slug or not DB_PATH.exists():
        return {}
    tz = _summary_event_zone(d0_item)
    d0_start_utc = _summary_local_midnight_utc(event_key, tz)
    d1_key = _date_key_offset(event_key, -1)
    d1_start_utc = _summary_local_midnight_utc(d1_key, tz)
    if d0_start_utc is None or d1_start_utc is None:
        return {}
    d0_cutoff = d0_start_utc.isoformat()
    d1_start = d1_start_utc.isoformat()
    cache_key = f"{slug}:{event_key}:{d1_start}:{d0_cutoff}"
    now_ts = time.time()
    with _D1_FORECAST_D0_FACT_CACHE_LOCK:
        cached = _D1_FORECAST_D0_FACT_CACHE.get(cache_key)
    if cached and (now_ts - float(cached[0] or 0.0)) <= _D1_FORECAST_D0_FACT_CACHE_SEC:
        return dict(cached[1] or {})

    row: Optional[sqlite3.Row] = None
    source_window = "d1_local_window"
    try:
        # The sqlite3.connect transaction context is not a lifetime manager.
        # Close the read connection on every D1 lookup to keep UI polling
        # from exhausting descriptors and resetting the local HTTP socket.
        with open_db_ro_fast(timeout_sec=0.12, busy_timeout_ms=0) as conn:
            conn.row_factory = sqlite3.Row
            row = conn.execute(
                """
                SELECT id, fact_as_of, fact_json
                FROM event_fact_history
                WHERE slug = ?
                  AND event_date = ?
                  AND fact_as_of >= ?
                  AND fact_as_of < ?
                ORDER BY fact_as_of DESC, id DESC
                LIMIT 1
                """,
                (slug, event_key, d1_start, d0_cutoff),
            ).fetchone()
            if not row:
                source_window = "fallback_latest_before_d0"
                row = conn.execute(
                    """
                    SELECT id, fact_as_of, fact_json
                    FROM event_fact_history
                    WHERE slug = ?
                      AND event_date = ?
                      AND fact_as_of < ?
                    ORDER BY fact_as_of DESC, id DESC
                    LIMIT 1
                    """,
                    (slug, event_key, d0_cutoff),
                ).fetchone()
    except sqlite3.Error:
        row = None
    if not row:
        payload: Dict[str, Any] = {}
    else:
        try:
            loaded = json.loads(row["fact_json"] or "{}")
        except Exception:
            loaded = {}
        payload = dict(loaded) if isinstance(loaded, Mapping) else {}
        fact_dt = _summary_parse_dt_utc(row["fact_as_of"])
        payload["_d1_forecast_d0_snapshot_meta"] = {
            "fact_id": int(row["id"] or 0),
            "fact_as_of": str(row["fact_as_of"] or ""),
            "source_window": source_window,
            "snapshot_local_label": _summary_format_local_snapshot_label(fact_dt, tz),
            "snapshot_local_date": fact_dt.astimezone(tz).date().isoformat() if fact_dt else "",
            "d1_local_date": d1_key,
            "d0_event_date": event_key,
            "matched_d1_window": source_window == "d1_local_window",
        }
    with _D1_FORECAST_D0_FACT_CACHE_LOCK:
        _D1_FORECAST_D0_FACT_CACHE[cache_key] = (now_ts, dict(payload))
        if len(_D1_FORECAST_D0_FACT_CACHE) > 64:
            for old_key, _old_value in sorted(
                _D1_FORECAST_D0_FACT_CACHE.items(),
                key=lambda item: float(item[1][0] or 0.0),
            )[:16]:
                _D1_FORECAST_D0_FACT_CACHE.pop(old_key, None)
    return payload


def _summary_peak_distribution_rows(value: Any, *, limit: int = 8) -> List[Dict[str, Any]]:
    rows: List[Dict[str, Any]] = []
    if isinstance(value, Mapping):
        iterable = [
            {"hour_local": key, "prob": prob}
            for key, prob in value.items()
        ]
    elif isinstance(value, list):
        iterable = value
    else:
        iterable = []
    for row in iterable:
        if not isinstance(row, Mapping):
            continue
        hour = _summary_physical_num(row.get("hour_local") or row.get("hour") or row.get("peak_hour"))
        prob = _summary_physical_num(row.get("prob") or row.get("probability") or row.get("weight"))
        if hour is None or prob is None or float(prob) <= 0:
            continue
        item: Dict[str, Any] = {
            "hour_local": max(0.0, min(23.99, float(hour))),
            "prob": max(0.0, float(prob)),
        }
        temp_c = _summary_physical_num(row.get("temperature_c") or row.get("temp_c"))
        if temp_c is not None:
            item["temperature_c"] = float(temp_c)
        valid_local = str(row.get("valid_time_local") or row.get("expected_peak_at_local") or "").strip()
        if valid_local:
            item["valid_time_local"] = valid_local
        rows.append(item)
    total = sum(float(row["prob"]) for row in rows)
    if total > 0:
        for row in rows:
            row["prob"] = float(row["prob"]) / float(total)
    rows.sort(key=lambda row: float(row.get("hour_local") or 0.0))
    return rows[: max(1, int(limit))]


def _summary_hour_window_text(start: Any, end: Any, distribution: Sequence[Mapping[str, Any]] = ()) -> str:
    start_num = _summary_physical_num(start)
    end_num = _summary_physical_num(end)
    if start_num is None or end_num is None:
        hours = [
            _summary_physical_num(row.get("hour_local"))
            for row in distribution
            if isinstance(row, Mapping)
        ]
        hours = [hour for hour in hours if hour is not None]
        if hours:
            start_num = min(hours)
            end_num = max(hours)
    if start_num is None or end_num is None:
        return ""
    return f"{int(round(float(start_num))):02d}:00-{int(round(float(end_num))):02d}:00"


def _summary_d1_peak_platform(
    features: Mapping[str, Any],
    *,
    label: str,
    prefix: str,
    peak_keys: Sequence[str],
) -> Dict[str, Any]:
    distribution = _summary_peak_distribution_rows(features.get(f"{prefix}_peak_hour_distribution"))
    peak_c = None
    for key in peak_keys:
        peak_c = _summary_physical_num(features.get(key))
        if peak_c is not None:
            break
    source = str(
        features.get(f"{prefix}_peak_hour_distribution_source")
        or features.get(f"{prefix}_peak_source")
        or features.get(f"{prefix}_source")
        or ""
    ).strip()
    na_reason = str(features.get(f"{prefix}_peak_hour_distribution_na_reason") or "").strip()
    window = _summary_hour_window_text(
        features.get(f"{prefix}_peak_window_start_hour_local"),
        features.get(f"{prefix}_peak_window_end_hour_local"),
        distribution,
    )
    expected_hour = _summary_physical_num(features.get(f"{prefix}_expected_peak_hour_local"))
    expected_at = str(features.get(f"{prefix}_expected_peak_at_local") or features.get(f"{prefix}_peak_at") or "").strip()
    return {
        "label": label,
        "prefix": prefix,
        "available": bool(distribution),
        "peak_c": peak_c,
        "window": window,
        "expected_peak_hour_local": expected_hour,
        "expected_peak_at_local": expected_at,
        "source": source,
        "na_reason": na_reason,
        "distribution": [dict(row) for row in distribution],
    }


def _summary_d1_peak_platforms(features: Mapping[str, Any]) -> List[Dict[str, Any]]:
    if not isinstance(features, Mapping):
        return []
    platforms = [
        _summary_d1_peak_platform(
            features,
            label="TWC hourly",
            prefix="twc_forecast",
            peak_keys=(
                "twc_hourly_forecast_peak_c",
                "weather_com_hourly_forecast_peak_c",
                "twc_forecast_peak_c",
                "weather_com_forecast_peak_c",
            ),
        ),
        _summary_d1_peak_platform(
            features,
            label="WU hourly",
            prefix="wu_forecast",
            peak_keys=("wu_forecast_peak_c", "settlement_source_forecast_peak_c"),
        ),
    ]
    out = [
        platform
        for platform in platforms
        if platform.get("available") or platform.get("peak_c") is not None or platform.get("na_reason")
    ]
    if not any(platform.get("available") for platform in out):
        expected_distribution = _summary_peak_distribution_rows(
            features.get("expected_peak_hour_distribution") or features.get("peak_hour_distribution")
        )
        if expected_distribution:
            out.append(
                {
                    "label": "融合窗口",
                    "prefix": "expected_peak",
                    "available": True,
                    "peak_c": _summary_physical_num(features.get("forecast_peak_temp_c") or features.get("forecast_peak_temp")),
                    "window": _summary_hour_window_text(
                        features.get("expected_peak_window_start_hour_local"),
                        features.get("expected_peak_window_end_hour_local"),
                        expected_distribution,
                    ),
                    "expected_peak_hour_local": _summary_physical_num(features.get("expected_peak_hour_local")),
                    "expected_peak_at_local": str(features.get("expected_peak_at_local") or "").strip(),
                    "source": str(features.get("expected_peak_hour_source") or "").strip(),
                    "na_reason": "",
                    "distribution": [dict(row) for row in expected_distribution],
                }
            )
    return out


def _summary_d1_hourly_forcing_timeline(features: Mapping[str, Any], *, limit: int = 24) -> List[Dict[str, Any]]:
    if not isinstance(features, Mapping):
        return []
    raw = features.get("open_meteo_hourly_forcing_timeline") or features.get("forecast_hourly_forcing_timeline")
    if not isinstance(raw, list):
        return []
    rows: List[Dict[str, Any]] = []
    numeric_keys = (
        "hour_local",
        "temperature_c",
        "dewpoint_c",
        "cloud_cover_pct",
        "cloud_cover_low_pct",
        "cloud_cover_mid_pct",
        "cloud_cover_high_pct",
        "shortwave_radiation_w_m2",
        "precipitation_probability_pct",
        "precipitation_rate_mm_per_h",
        "precipitation_mm",
        "rain_mm",
        "showers_mm",
        "wind_speed_mps",
        "wind_direction_deg",
        "pressure_hpa",
        "weather_code",
    )
    for row in raw:
        if not isinstance(row, Mapping):
            continue
        item: Dict[str, Any] = {}
        time_local = str(row.get("time_local") or row.get("valid_time_local") or row.get("time") or "").strip()
        if time_local:
            item["time_local"] = time_local
        for key in numeric_keys:
            value = _summary_physical_num(row.get(key))
            if value is not None:
                item[key] = float(value)
        if "hour_local" not in item and time_local:
            try:
                dt = datetime.fromisoformat(time_local.replace("Z", "+00:00"))
                item["hour_local"] = float(dt.hour) + float(dt.minute) / 60.0
            except Exception:
                pass
        if item:
            rows.append(item)
    rows.sort(key=lambda row: float(row.get("hour_local") or 0.0))
    return rows[: max(1, int(limit))]


def _summary_d1_hour_list(
    rows: Sequence[Mapping[str, Any]],
    predicate: Callable[[Mapping[str, Any]], bool],
    *,
    limit: int = 6,
) -> str:
    hours: List[str] = []
    for row in rows:
        if not isinstance(row, Mapping):
            continue
        try:
            matched = bool(predicate(row))
        except Exception:
            matched = False
        if not matched:
            continue
        hour = _summary_physical_num(row.get("hour_local"))
        if hour is None:
            continue
        label = f"{int(round(float(hour))):02d}:00"
        if label not in hours:
            hours.append(label)
        if len(hours) >= limit:
            break
    return "/".join(hours)


def _summary_d1_numeric_series(rows: Sequence[Mapping[str, Any]], key: str) -> List[float]:
    values: List[float] = []
    for row in rows:
        if not isinstance(row, Mapping):
            continue
        value = _summary_physical_num(row.get(key))
        if value is not None:
            values.append(float(value))
    return values


def _summary_d1_mean(values: Sequence[float]) -> Optional[float]:
    clean = [float(value) for value in values if math.isfinite(float(value))]
    if not clean:
        return None
    return sum(clean) / len(clean)


def _summary_d1_delta(values: Sequence[float]) -> Optional[float]:
    clean = [float(value) for value in values if math.isfinite(float(value))]
    if len(clean) < 2:
        return None
    return clean[-1] - clean[0]


def _summary_d1_taf_physical_profile(features: Mapping[str, Any]) -> Dict[str, Any]:
    if not isinstance(features, Mapping):
        return {"available": False, "reason": "features_missing"}
    raw = str(features.get("taf_forecast_peak_raw") or "").strip()
    if not raw:
        return {"available": False, "reason": "taf_raw_missing"}
    text = " ".join(raw.split())
    upper = f" {text.upper()} "
    cloud_matches = re.findall(r"\b(FEW|SCT|BKN|OVC|VV)(\d{3})(CB|TCU)?\b", upper)
    cloud_tokens = [f"{amount}{height}{suffix or ''}" for amount, height, suffix in cloud_matches[:6]]
    weather_tokens: List[str] = []
    for token in ("+TSRA", "-TSRA", "TSRA", "VCTS", "+SHRA", "-SHRA", "SHRA", "+RA", "-RA", "RA", "NSW"):
        if re.search(rf"\b{re.escape(token)}\b", upper) and token not in weather_tokens:
            weather_tokens.append(token)
    has_cb_tcu = bool(re.search(r"\b(?:FEW|SCT|BKN|OVC)\d{3}(?:CB|TCU)\b", upper))
    has_thunder = any(token in weather_tokens for token in ("+TSRA", "-TSRA", "TSRA", "VCTS"))
    has_rain = any("RA" in token for token in weather_tokens)
    has_nsw = "NSW" in weather_tokens
    has_thick_low_cloud = False
    has_only_scattered_cloud = bool(cloud_matches) and not has_rain and not has_thunder
    for amount, height, _suffix in cloud_matches:
        try:
            base_hundreds_ft = int(height)
        except Exception:
            continue
        if amount in {"BKN", "OVC", "VV"} and base_hundreds_ft <= 60:
            has_thick_low_cloud = True
        if amount not in {"FEW", "SCT"}:
            has_only_scattered_cloud = False
    if has_cb_tcu or has_thunder or has_rain or has_thick_low_cloud:
        effect = "cooling"
    elif has_nsw or has_only_scattered_cloud:
        effect = "warming"
    else:
        effect = "neutral"
    value = _summary_physical_compact_metrics(
        [
            "CB/TCU" if has_cb_tcu else "",
            "/".join(weather_tokens[:4]),
            "/".join(cloud_tokens[:4]),
        ]
    )
    if not value:
        value = "TAF 已抓取"
    detail = "AWC TAF 作为明日航空预报证据；不使用实时 METAR 判明日。"
    if has_cb_tcu or has_thunder:
        detail = "TAF 出现 CB/雷阵雨信号，偏压制辐射与高温兑现。"
    elif has_rain:
        detail = "TAF 出现降雨信号，偏压制升温。"
    elif has_nsw and has_only_scattered_cloud:
        detail = "TAF 转 NSW 且云量偏散，偏支持辐射。"
    return {
        "available": True,
        "raw": text,
        "effect": effect,
        "value": value,
        "detail": detail,
        "weather_tokens": weather_tokens,
        "cloud_tokens": cloud_tokens,
        "has_cb_tcu": has_cb_tcu,
        "has_thunder": has_thunder,
        "has_rain": has_rain,
        "has_nsw": has_nsw,
        "has_thick_low_cloud": has_thick_low_cloud,
    }


def _summary_d1_physical_signal(
    *,
    taf_profile: Mapping[str, Any],
    hourly_rows: Sequence[Mapping[str, Any]],
    cloud_total: Optional[float],
    cloud_low: Optional[float],
    precip_rate: Optional[float],
    rain_hours_text: str,
    dewpoint: Optional[float],
    pressure_trend: Optional[float],
) -> Dict[str, Any]:
    warming = 0.0
    cooling = 0.0
    drivers: List[str] = []

    if isinstance(taf_profile, Mapping) and taf_profile.get("available"):
        if taf_profile.get("has_cb_tcu") or taf_profile.get("has_thunder"):
            cooling += 1.2
            drivers.append("AWC TAF CB/雷阵雨")
        elif taf_profile.get("has_rain"):
            cooling += 0.8
            drivers.append("AWC TAF 降雨")
        if taf_profile.get("has_thick_low_cloud"):
            cooling += 0.7
            drivers.append("AWC TAF 厚低云")
        if taf_profile.get("has_nsw") and not taf_profile.get("has_rain") and not taf_profile.get("has_thunder"):
            warming += 0.5
            drivers.append("AWC TAF NSW")
        if taf_profile.get("effect") == "warming" and not taf_profile.get("has_cb_tcu"):
            warming += 0.3
            drivers.append("AWC TAF 云量偏散")

    rain_prob_values = _summary_d1_numeric_series(hourly_rows, "precipitation_probability_pct")
    rain_rate_values = _summary_d1_numeric_series(hourly_rows, "precipitation_rate_mm_per_h")
    low_cloud_values = _summary_d1_numeric_series(hourly_rows, "cloud_cover_low_pct")
    total_cloud_values = _summary_d1_numeric_series(hourly_rows, "cloud_cover_pct")
    radiation_values = [
        value
        for value in _summary_d1_numeric_series(hourly_rows, "shortwave_radiation_w_m2")
        if value > 0
    ]
    dewpoint_values = _summary_d1_numeric_series(hourly_rows, "dewpoint_c")
    pressure_values = _summary_d1_numeric_series(hourly_rows, "pressure_hpa")
    wind_values = _summary_d1_numeric_series(hourly_rows, "wind_speed_mps")

    max_rain_prob = max(rain_prob_values) if rain_prob_values else None
    max_rain_rate = max(rain_rate_values) if rain_rate_values else None
    avg_low_cloud = _summary_d1_mean(low_cloud_values)
    avg_total_cloud = _summary_d1_mean(total_cloud_values)
    max_radiation = max(radiation_values) if radiation_values else None
    avg_dewpoint = _summary_d1_mean(dewpoint_values) if dewpoint_values else dewpoint
    pressure_delta = _summary_d1_delta(pressure_values)
    avg_wind = _summary_d1_mean(wind_values)

    rain_risk = bool(rain_hours_text) or (
        max_rain_prob is not None and float(max_rain_prob) >= 50.0
    ) or (
        max_rain_rate is not None and float(max_rain_rate) >= 0.2
    ) or (
        precip_rate is not None and float(precip_rate) >= 0.2
    )
    if rain_risk:
        cooling += 1.1
        drivers.append("逐小时降雨风险")
    elif max_rain_prob is not None and max_rain_prob <= 20 and (max_rain_rate or 0.0) < 0.1:
        warming += 0.4
        drivers.append("逐小时少雨")

    if avg_low_cloud is not None and avg_low_cloud >= 50:
        cooling += 0.9
        drivers.append("低云偏多")
    elif avg_low_cloud is not None and avg_total_cloud is not None and avg_low_cloud <= 25 and avg_total_cloud <= 55:
        warming += 0.5
        drivers.append("低云少")
    elif avg_total_cloud is not None and avg_total_cloud >= 70:
        cooling += 0.5
        drivers.append("总云偏多")

    if max_radiation is not None and max_radiation >= 650 and not rain_risk:
        warming += 0.7
        drivers.append("辐射窗口强")
    elif max_radiation is not None and max_radiation < 350:
        cooling += 0.5
        drivers.append("辐射弱")

    if avg_dewpoint is not None and avg_dewpoint >= 24:
        cooling += 0.35
        drivers.append("露点偏高")
    elif avg_dewpoint is not None and avg_dewpoint <= 18:
        warming += 0.25
        drivers.append("空气偏干")

    pressure_reference = pressure_delta if pressure_delta is not None else pressure_trend
    if pressure_reference is not None and pressure_reference >= 1.0:
        warming += 0.2
        drivers.append("气压趋稳/上升")
    elif pressure_reference is not None and pressure_reference <= -1.0:
        cooling += 0.2
        drivers.append("气压下降")

    if avg_wind is not None and avg_wind >= 5.0 and rain_risk:
        cooling += 0.2
        drivers.append("风雨边界扰动")

    net = warming - cooling
    if net >= 0.75:
        day_type = "warming_reference"
        label = "升温日"
        physical_label = "物理证据偏升温"
    elif net <= -0.75:
        day_type = "cooling_reference"
        label = "降温日"
        physical_label = "物理证据偏降温"
    else:
        day_type = "neutral_reference"
        label = "平常日"
        physical_label = "物理证据中性"
    return {
        "day_type": day_type,
        "day_type_label": label,
        "physical_label": physical_label,
        "warming_score": round(float(warming), 3),
        "cooling_score": round(float(cooling), 3),
        "net_score": round(float(net), 3),
        "drivers": drivers[:6],
        "metrics": {
            "max_rain_probability_pct": max_rain_prob,
            "max_rain_rate_mm_per_h": max_rain_rate,
            "avg_low_cloud_pct": avg_low_cloud,
            "avg_total_cloud_pct": avg_total_cloud,
            "max_radiation_w_m2": max_radiation,
            "avg_dewpoint_c": avg_dewpoint,
            "pressure_delta_hpa": pressure_delta,
            "avg_wind_speed_mps": avg_wind,
        },
    }


def _build_d1_physical_evidence_overview(
    items: Sequence[Any],
    *,
    run_date_key: str,
) -> Dict[str, Any]:
    base_date = _normalize_date_key(run_date_key)
    typed_items = [item for item in items or [] if isinstance(item, Mapping)]
    if not base_date:
        dates = sorted(_summary_item_event_date(item) for item in typed_items if _summary_item_event_date(item))
        base_date = dates[0] if dates else ""
    if not base_date:
        return {"available": False, "reason": "run_date_missing"}
    target_date = _date_key_offset(base_date, 1) or base_date
    target_selection_reason = "run_date_plus_1"
    d0_item = next((item for item in typed_items if _summary_item_event_date(item) == target_date), {})
    if not d0_item and typed_items:
        future_items = [
            item for item in typed_items
            if _summary_item_event_date(item) and _summary_item_event_date(item) > base_date
        ]
        future_items.sort(key=_summary_item_event_date)
        if future_items:
            d0_item = future_items[0]
            target_date = _summary_item_event_date(d0_item)
            target_selection_reason = "first_future_event"
    if not d0_item and typed_items:
        dated_items = [
            item for item in typed_items
            if _summary_item_event_date(item)
        ]
        dated_items.sort(key=_summary_item_event_date)
        d0_item = dated_items[0] if dated_items else {}
        target_date = _summary_item_event_date(d0_item) if isinstance(d0_item, Mapping) else base_date
        target_selection_reason = "fallback_first_event"
    d0_date = _summary_item_event_date(d0_item) if isinstance(d0_item, Mapping) else base_date
    d1_item = _load_d1_forecast_fact_for_d0(d0_item, event_date_key=d0_date) if isinstance(d0_item, Mapping) else {}
    if not d1_item:
        return {
            "available": False,
            "reason": "d1_forecast_target_fact_missing",
            "reference_only": True,
            "base_date": base_date,
            "target_event_date": d0_date,
            "target_selection_reason": target_selection_reason,
            "d0_event_date": _summary_item_event_date(d0_item) if isinstance(d0_item, Mapping) else base_date,
        }

    d0_features = _summary_item_likelihood_features(d0_item) if isinstance(d0_item, Mapping) else {}
    d1_features = _summary_item_likelihood_features(d1_item)
    d1_physical = _summary_item_physical_modifier(d1_item)
    d1_snapshot_meta = d1_item.get("_d1_forecast_d0_snapshot_meta")
    d1_snapshot_meta = d1_snapshot_meta if isinstance(d1_snapshot_meta, Mapping) else {}
    d0_high = None
    for key in (
        "observed_today_max_c",
        "zuuu_metar_raw_awc_today_max_c",
        "raw_observed_today_max_c",
        "peak_estimator_mu_c",
    ):
        d0_high = _summary_physical_num(d0_features.get(key))
        if d0_high is not None:
            break
    d1_wu = _summary_physical_num(d1_features.get("wu_forecast_peak_c"))
    d1_twc = _summary_physical_num(
        d1_features.get("twc_forecast_peak_c")
        if d1_features.get("twc_forecast_peak_c") is not None
        else d1_features.get("weather_com_forecast_peak_c")
    )
    d1_hourly_peak = _summary_physical_num(
        d1_features.get("twc_hourly_forecast_peak_c")
        if d1_features.get("twc_hourly_forecast_peak_c") is not None
        else d1_features.get("weather_com_hourly_forecast_peak_c")
        if d1_features.get("weather_com_hourly_forecast_peak_c") is not None
        else d1_features.get("twc_forecast_peak_c")
        if d1_features.get("twc_forecast_peak_hour_distribution") is not None
        else d1_features.get("weather_com_forecast_peak_c")
        if d1_features.get("weather_com_forecast_peak_hour_distribution") is not None
        else None
    )
    d1_blend_peak = _summary_physical_num(
        d1_features.get("forecast_peak_temp_c")
        if d1_features.get("forecast_peak_temp_c") is not None
        else d1_features.get("forecast_peak_temp")
    )
    forecast_values = [value for value in (d1_blend_peak, d1_wu, d1_twc, d1_hourly_peak) if value is not None]
    d1_ref_peak = sum(forecast_values) / len(forecast_values) if forecast_values else None
    realization_gap_vs_d1 = (
        float(d0_high) - float(d1_ref_peak)
        if d1_ref_peak is not None and d0_high is not None
        else None
    )

    day_type = "neutral_reference"
    day_type_label = "平常日"

    snapshot_local_label = str(d1_snapshot_meta.get("snapshot_local_label") or "").strip()
    snapshot_matched_d1 = bool(d1_snapshot_meta.get("matched_d1_window", False))
    stale = not snapshot_matched_d1
    stale_label = (
        f"D1快照 {snapshot_local_label}"
        if snapshot_local_label
        else "D1快照时间未知"
    )
    if not snapshot_matched_d1:
        stale_label = f"{stale_label} · 非D1窗口"

    cloud_total = _summary_physical_num(d1_physical.get("cloud_cover_pct"))
    cloud_low = _summary_physical_num(d1_physical.get("cloud_cover_low_pct"))
    cloud_mid = _summary_physical_num(d1_physical.get("cloud_cover_mid_pct"))
    cloud_high = _summary_physical_num(d1_physical.get("cloud_cover_high_pct"))
    precip_profile = d1_physical.get("precipitation_profile")
    precip_profile = precip_profile if isinstance(precip_profile, Mapping) else {}
    precip_state = str(precip_profile.get("evidence_state") or "").strip()
    precip_rate = _summary_physical_num(precip_profile.get("rate_mm_per_h"))
    precip_nowcast = d1_physical.get("precip_nowcast_1_3h")
    precip_nowcast = precip_nowcast if isinstance(precip_nowcast, Mapping) else {}
    nowcast_state = str(precip_nowcast.get("risk_state") or precip_nowcast.get("state") or "").strip()
    dewpoint = _summary_physical_num(d1_physical.get("dewpoint_c"))
    radiation = _summary_physical_num(d1_physical.get("solar_radiation"))
    pressure_profile = d1_physical.get("pressure_profile")
    pressure_profile = pressure_profile if isinstance(pressure_profile, Mapping) else {}
    pressure = _summary_physical_num(pressure_profile.get("pressure_hpa"))
    pressure_trend = _summary_physical_num(pressure_profile.get("pressure_trend_hpa"))
    components = [
        dict(component)
        for component in (d1_physical.get("components") or [])
        if isinstance(component, Mapping)
    ]
    component_lines = [
        str(component.get("reason") or component.get("label") or component.get("key") or "").strip()
        for component in components[:3]
    ]
    component_lines = [line for line in component_lines if line]

    peak_platforms = _summary_d1_peak_platforms(d1_features)
    hourly_forcing_timeline = _summary_d1_hourly_forcing_timeline(d1_features)
    rain_hours_text = _summary_d1_hour_list(
        hourly_forcing_timeline,
        lambda row: (
            float(row.get("precipitation_rate_mm_per_h") or 0.0) >= 0.2
            or float(row.get("precipitation_probability_pct") or 0.0) >= 50.0
        ),
    )
    low_cloud_hours_text = _summary_d1_hour_list(
        hourly_forcing_timeline,
        lambda row: float(row.get("cloud_cover_low_pct") or 0.0) >= 50.0,
    )
    high_cloud_hours_text = _summary_d1_hour_list(
        hourly_forcing_timeline,
        lambda row: float(row.get("cloud_cover_high_pct") or 0.0) >= 60.0,
    )
    taf_profile = _summary_d1_taf_physical_profile(d1_features)
    physical_signal = _summary_d1_physical_signal(
        taf_profile=taf_profile,
        hourly_rows=hourly_forcing_timeline,
        cloud_total=cloud_total,
        cloud_low=cloud_low,
        precip_rate=precip_rate,
        rain_hours_text=rain_hours_text,
        dewpoint=dewpoint,
        pressure_trend=pressure_trend,
    )
    day_type = str(physical_signal.get("day_type") or day_type)
    day_type_label = str(physical_signal.get("day_type_label") or day_type_label)

    hour_distribution = []
    for platform in peak_platforms:
        platform_distribution = platform.get("distribution")
        if isinstance(platform_distribution, list) and platform_distribution:
            hour_distribution = [row for row in platform_distribution if isinstance(row, Mapping)]
            if hour_distribution:
                break
    for key in (
        "twc_forecast_peak_hour_distribution",
        "weather_com_forecast_peak_hour_distribution",
        "wu_forecast_peak_hour_distribution",
        "expected_peak_hour_distribution",
    ):
        if hour_distribution:
            break
        value = d1_features.get(key)
        if isinstance(value, list) and value:
            hour_distribution = [row for row in value if isinstance(row, Mapping)]
            if hour_distribution:
                break
    peak_window_start = _summary_physical_num(
        d1_features.get("twc_forecast_peak_window_start_hour_local")
        if d1_features.get("twc_forecast_peak_window_start_hour_local") is not None
        else d1_features.get("weather_com_forecast_peak_window_start_hour_local")
    )
    peak_window_end = _summary_physical_num(
        d1_features.get("twc_forecast_peak_window_end_hour_local")
        if d1_features.get("twc_forecast_peak_window_end_hour_local") is not None
        else d1_features.get("weather_com_forecast_peak_window_end_hour_local")
    )
    if peak_window_start is None:
        peak_window_start = _summary_physical_num(d1_features.get("expected_peak_window_start_hour_local"))
    if peak_window_end is None:
        peak_window_end = _summary_physical_num(d1_features.get("expected_peak_window_end_hour_local"))
    def _summary_hour_label(value: Any) -> str:
        hour_value = _summary_physical_num(value)
        if hour_value is None:
            return ""
        total_minutes = int(round(max(0.0, min(23.99, float(hour_value))) * 60.0))
        total_minutes = max(0, min((23 * 60) + 59, total_minutes))
        return f"{total_minutes // 60:02d}:{total_minutes % 60:02d}"

    peak_window = ""
    if peak_window_start is not None and peak_window_end is not None:
        peak_window = f"{_summary_hour_label(peak_window_start)}-{_summary_hour_label(peak_window_end)}"
    elif hour_distribution:
        hours = [
            _summary_physical_num(row.get("hour_local"))
            for row in hour_distribution
            if isinstance(row, Mapping)
        ]
        hours = [hour for hour in hours if hour is not None]
        if hours:
            peak_window = f"{_summary_hour_label(min(hours))}-{_summary_hour_label(max(hours))}"

    signal_metrics = physical_signal.get("metrics") if isinstance(physical_signal.get("metrics"), Mapping) else {}
    max_radiation = _summary_physical_num(signal_metrics.get("max_radiation_w_m2"))
    avg_wind = _summary_physical_num(signal_metrics.get("avg_wind_speed_mps"))
    pressure_delta = _summary_physical_num(signal_metrics.get("pressure_delta_hpa"))
    avg_low_cloud = _summary_physical_num(signal_metrics.get("avg_low_cloud_pct"))
    avg_total_cloud = _summary_physical_num(signal_metrics.get("avg_total_cloud_pct"))
    max_rain_probability = _summary_physical_num(signal_metrics.get("max_rain_probability_pct"))
    max_rain_rate = _summary_physical_num(signal_metrics.get("max_rain_rate_mm_per_h"))

    evidence_cards: List[Dict[str, Any]] = []
    if taf_profile.get("available"):
        evidence_cards.append(
            {
                "key": "awc_taf",
                "label": "AWC TAF",
                "value": str(taf_profile.get("value") or "TAF 已抓取"),
                "effect": str(taf_profile.get("effect") or "neutral"),
                "detail": str(taf_profile.get("detail") or "明日航空预报证据。"),
            }
        )
    cloud_value = _summary_physical_compact_metrics(
        [
            _summary_physical_metric("总云", avg_total_cloud if avg_total_cloud is not None else cloud_total, "%", decimals=0),
            _summary_physical_metric("低云", avg_low_cloud if avg_low_cloud is not None else cloud_low, "%", decimals=0),
            _summary_physical_metric("中云", cloud_mid, "%", decimals=0),
            _summary_physical_metric("高云", cloud_high, "%", decimals=0),
        ]
    )
    evidence_cards.append(
        {
            "key": "cloud",
            "label": "云",
            "value": cloud_value or "云量时间分布缺失",
            "effect": "cooling" if cloud_total is not None and cloud_total >= 60 else "neutral",
            "detail": (
                f"低云高值 {low_cloud_hours_text}" if low_cloud_hours_text
                else f"高云高值 {high_cloud_hours_text}" if high_cloud_hours_text
                else "云量越高，辐射越容易被压制；D1卡片仅显示事实层已有预报字段。"
            ),
        }
    )
    rain_value = _summary_physical_compact_metrics(
        [
            precip_state,
            _summary_physical_metric("概率峰值", max_rain_probability, "%", decimals=0),
            _summary_physical_metric("雨强峰值", max_rain_rate if max_rain_rate is not None else precip_rate, "mm/h", decimals=1),
            f"1-3h {nowcast_state}" if nowcast_state else "",
        ]
    )
    precip_state_lower = precip_state.lower()
    nowcast_state_lower = nowcast_state.lower()
    if "no_precip" in precip_state_lower or "no precip" in precip_state_lower:
        rain_effect = "warming"
    elif (
        ("precip" in precip_state_lower or "rain" in precip_state_lower or "shower" in precip_state_lower)
        and "missing" not in precip_state_lower
    ) or (
        ("risk" in nowcast_state_lower or "rain" in nowcast_state_lower or "precip" in nowcast_state_lower)
        and "missing" not in nowcast_state_lower
    ):
        rain_effect = "cooling"
    else:
        rain_effect = "neutral"
    evidence_cards.append(
        {
            "key": "rain",
            "label": "雨",
            "value": rain_value or "降雨时间/概率缺失",
            "effect": rain_effect,
            "detail": (
                f"高风险小时 {rain_hours_text}" if rain_hours_text
                else str(precip_nowcast.get("conclusion") or precip_profile.get("source_field") or "缺少逐小时降雨时间时不推断。")
            ),
        }
    )
    radiation_value = _summary_physical_compact_metrics(
        [
            _summary_physical_metric("峰值辐射", max_radiation if max_radiation is not None else radiation, "W/m²", decimals=0),
        ]
    )
    evidence_cards.append(
        {
            "key": "radiation",
            "label": "辐射",
            "value": radiation_value or "辐射字段缺失",
            "effect": (
                "warming"
                if max_radiation is not None and max_radiation >= 650 and rain_effect != "cooling"
                else "cooling"
                if max_radiation is not None and max_radiation < 350
                else "neutral"
            ),
            "detail": "辐射窗口强则支持升温；弱辐射或雨云遮挡则偏压制。",
        }
    )
    moisture_value = _summary_physical_compact_metrics(
        [
            _summary_physical_metric("露点", dewpoint, "°C", decimals=1),
            _summary_physical_metric("气压", pressure, "hPa", decimals=0),
            _summary_physical_metric("趋势", pressure_delta if pressure_delta is not None else pressure_trend, "hPa", decimals=1),
        ]
    )
    evidence_cards.append(
        {
            "key": "moisture_pressure",
            "label": "露点/气压",
            "value": moisture_value or "湿压字段缺失",
            "effect": "neutral",
            "detail": "露点和气压只作为湿球/环流背景，不单独覆盖温度轨迹。",
        }
    )
    wind_value = _summary_physical_compact_metrics(
        [
            _summary_physical_metric("均风", avg_wind, "m/s", decimals=1),
        ]
    )
    evidence_cards.append(
        {
            "key": "wind",
            "label": "风",
            "value": wind_value or "风字段缺失",
            "effect": "neutral",
            "detail": "风只作为通风/平流/对流边界证据，不单独判定升降温。",
        }
    )

    missing: List[str] = []
    if not taf_profile.get("available"):
        missing.append("AWC TAF")
    if not hourly_forcing_timeline:
        missing.append("逐小时物理证据")
    else:
        if cloud_total is None:
            missing.append("逐小时云量")
        if not rain_value and not rain_hours_text:
            missing.append("逐小时降雨概率/雨量")
    if not snapshot_matched_d1:
        missing.append("D1预测D0快照窗口")

    score_text = _summary_physical_compact_metrics(
        [
            _summary_physical_metric("升温证据", _summary_physical_num(physical_signal.get("warming_score")), "", decimals=1),
            _summary_physical_metric("降温证据", _summary_physical_num(physical_signal.get("cooling_score")), "", decimals=1),
        ]
    )
    driver_text = "主因 " + " / ".join(str(item) for item in physical_signal.get("drivers") or []) if physical_signal.get("drivers") else ""
    physical_label = str(physical_signal.get("physical_label") or d1_physical.get("label") or d1_physical.get("state") or "").strip()
    lead_label = "D1预测明日" if d0_date != base_date else "D1预测D0"
    verdict = f"{lead_label} · {day_type_label} · {physical_label or '物理证据参考'}"
    if stale:
        verdict = f"{verdict} · 待刷新确认"
    summary_parts = [
        driver_text,
        score_text,
        str(taf_profile.get("value") or "") if taf_profile.get("available") else "",
        cloud_value,
        rain_value,
        radiation_value,
        wind_value,
        ]
    summary_text = "；".join(part for part in summary_parts if part)
    if missing:
        summary_text = f"{summary_text}；缺字段：{'、'.join(missing[:4])}" if summary_text else f"缺字段：{'、'.join(missing[:4])}"
    if not summary_text:
        summary_text = "明日物理证据不足，仅保留参考入口。"

    return {
        "available": True,
        "version": "d1_physical_evidence_overview_v1",
        "reference_only": True,
        "physical_only": True,
        "source": "event_fact_history.d1_forecast_target",
        "base_date": base_date,
        "target_event_date": d0_date,
        "target_selection_reason": target_selection_reason,
        "lead_day_label": lead_label,
        "d0_event_date": _summary_item_event_date(d0_item) if isinstance(d0_item, Mapping) else "",
        "d1_forecast_for_event_date": _summary_item_event_date(d0_item) if isinstance(d0_item, Mapping) else "",
        "d1_snapshot_local_date": str(d1_snapshot_meta.get("snapshot_local_date") or ""),
        "d1_snapshot_local_label": snapshot_local_label,
        "d1_snapshot_source_window": str(d1_snapshot_meta.get("source_window") or ""),
        "d1_snapshot_fact_id": d1_snapshot_meta.get("fact_id"),
        "d0_observed_high_c": d0_high,
        "d1_blend_peak_c": d1_blend_peak,
        "d1_wu_peak_c": d1_wu,
        "d1_twc_peak_c": d1_twc,
        "d1_hourly_peak_c": d1_hourly_peak,
        "realization_gap_vs_d1_c": realization_gap_vs_d1,
        "day_type": day_type,
        "day_type_label": day_type_label,
        "verdict": verdict,
        "summary": summary_text,
        "physical_signal": dict(physical_signal),
        "taf_profile": dict(taf_profile),
        "taf_raw": str(taf_profile.get("raw") or ""),
        "fact_as_of": str(d1_item.get("fact_as_of") or ""),
        "weather_likelihood_refreshed_at": str(d1_item.get("weather_likelihood_refreshed_at") or ""),
        "freshness_label": stale_label,
        "stale": bool(stale),
        "physical_state": str(d1_physical.get("state") or ""),
        "physical_label": physical_label,
        "cloud_cover_pct": cloud_total,
        "cloud_cover_low_pct": cloud_low,
        "cloud_cover_mid_pct": cloud_mid,
        "cloud_cover_high_pct": cloud_high,
        "precipitation_state": precip_state,
        "precipitation_rate_mm_per_h": precip_rate,
        "precip_nowcast_state": nowcast_state,
        "dewpoint_c": dewpoint,
        "pressure_hpa": pressure,
        "pressure_trend_hpa": pressure_trend,
        "solar_radiation": radiation,
        "peak_window": peak_window,
        "peak_hour_distribution": [dict(row) for row in hour_distribution[:6]],
        "peak_platforms": [dict(platform) for platform in peak_platforms[:3]],
        "hourly_forcing_timeline": [dict(row) for row in hourly_forcing_timeline[:24]],
        "hourly_forcing_timeline_source": str(
            d1_features.get("forecast_hourly_forcing_timeline_source")
            or d1_features.get("open_meteo_hourly_forcing_timeline_source")
            or "open_meteo_forecast_hourly"
            if hourly_forcing_timeline
            else ""
        ),
        "rain_high_risk_hours": rain_hours_text,
        "low_cloud_high_hours": low_cloud_hours_text,
        "high_cloud_high_hours": high_cloud_hours_text,
        "evidence_cards": evidence_cards,
        "component_reasons": component_lines,
        "missing": missing,
        "notice": "仅参考：D1预测物理证据不触发交易，不覆盖目标日硬实况/SSOT目标桶。",
    }


def _attach_d1_physical_evidence_overview(payload: Dict[str, Any]) -> None:
    if not isinstance(payload, dict):
        return
    facts = payload.get("facts")
    if not isinstance(facts, Mapping):
        return
    items = facts.get("items")
    if not isinstance(items, list):
        return
    run_date_key = _normalize_date_key(str(payload.get("run_date") or ""))
    overview = _build_d1_physical_evidence_overview(items, run_date_key=run_date_key)
    payload["d1_physical_evidence_overview"] = overview


def _attach_target_direction_bias(payload: Dict[str, Any]) -> None:
    """Expose the current event's read-only regime-gate direction on SSOT."""
    if not isinstance(payload, dict):
        return
    # The full/summary builders now attach the city strategy's production
    # regime gate.  Trimming the payload must not replace that with the older
    # D1 physical-evidence-only fallback.
    existing = payload.get("target_direction_bias")
    if isinstance(existing, Mapping) and str(existing.get("direction") or "").strip().upper() in {"UP", "DOWN"}:
        return
    d1 = payload.get("d1_physical_evidence_overview") if isinstance(payload.get("d1_physical_evidence_overview"), Mapping) else {}
    signal = d1.get("physical_signal") if isinstance(d1.get("physical_signal"), Mapping) else {}
    basket_root = payload.get("basket_strategy_ssot") if isinstance(payload.get("basket_strategy_ssot"), Mapping) else {}
    basket_items = basket_root.get("items") if isinstance(basket_root.get("items"), list) else []
    facts = payload.get("facts") if isinstance(payload.get("facts"), Mapping) else {}
    fact_items = facts.get("items") if isinstance(facts.get("items"), list) else []
    primary = fact_items[0] if fact_items and isinstance(fact_items[0], Mapping) else {}
    primary_key = (str(primary.get("slug") or ""), _normalize_date_key(str(primary.get("event_date") or "")))
    basket_item = next(
        (row for row in basket_items if isinstance(row, Mapping) and (str(row.get("slug") or ""), _normalize_date_key(str(row.get("event_date") or ""))) == primary_key),
        None,
    )
    basket = basket_item.get("basket") if isinstance(basket_item, Mapping) and isinstance(basket_item.get("basket"), Mapping) else {}
    direction = str(basket.get("direction") or "").strip().upper()
    payload["target_direction_bias"] = {
        "schema": "target_direction_bias_ui_v1",
        "available": direction in {"UP", "DOWN"},
        "direction": direction if direction in {"UP", "DOWN"} else "",
        "label": "偏上 ↑" if direction == "UP" else "偏下 ↓" if direction == "DOWN" else "未物化",
        "source": "basket.direction_bias" if direction else "city_strategy.direction_bias.regime_gate",
        "target_event_date": str(primary.get("event_date") or d1.get("target_event_date") or ""),
        "net_score": None,
        "score_available": False,
        "regime_state": "",
        "regime_labels": [],
        "reason": "目标日 regime 闸门未物化",
        "updated_at": str(d1.get("fact_as_of") or payload.get("snapshot_generated_at") or ""),
    }


def _trim_ui_snapshot_summary_payload(
    payload: Dict[str, Any],
    requested_limit: int,
    *,
    city_filter: str = "",
) -> Dict[str, Any]:
    try:
        limit_val = max(1, min(int(requested_limit or 0), 80))
    except (TypeError, ValueError):
        limit_val = 24
    if not isinstance(payload, dict):
        return payload
    city_key = _normalize_ui_snapshot_city_filter(city_filter)
    out = dict(payload)
    _refresh_ui_snapshot_summary_envelope(out)
    facts = out.get("facts")
    if isinstance(facts, dict):
        facts_out = dict(facts)
        items = facts_out.get("items")
        if isinstance(items, list):
            if city_key:
                compact_items = [
                    _compact_ui_snapshot_summary_item_for_first_screen(item)
                    for item in items
                    if _ui_snapshot_summary_item_matches_city_filter(item, city_key)
                ]
            else:
                compact_items = list(items)
            if len(compact_items) > limit_val:
                compact_items = compact_items[:limit_val]
            facts_out["items"] = compact_items
            if city_key:
                facts_out["city_filter"] = city_key
                facts_out["total"] = len(compact_items)
                source = str(facts_out.get("source") or "")
                if source and not source.endswith("_city_filtered"):
                    facts_out["source"] = f"{source}_city_filtered"
        facts_out["page_size"] = limit_val
        out["facts"] = facts_out
    if city_key:
        out["ui_snapshot_city_filter"] = city_key
    out["summary_requested_limit"] = limit_val
    _attach_d1_physical_evidence_overview(out)
    _attach_target_direction_bias(out)
    return out


