def _event_fact_metadata_only_summary_items(
    conn: sqlite3.Connection,
    run_date_key: str,
    *,
    limit_val: int,
    upcoming_days: int = 2,
) -> List[Dict[str, Any]]:
    date_key = _normalize_date_key(run_date_key)
    if not date_key:
        return []
    try:
        limit = max(1, min(int(limit_val or 0), 80))
    except (TypeError, ValueError):
        limit = 24
    end_key = _date_key_offset(date_key, max(0, int(upcoming_days or 0))) or date_key
    cur = conn.cursor()
    try:
        cur.execute(
            """
            SELECT
                h.id AS fact_id,
                h.slug,
                h.event_date,
                h.run_date,
                h.fact_as_of,
                h.model_snapshot_id,
                h.market_snapshot_id,
                h.market_updated_at,
                h.model_updated_at,
                h.market_stale_sec,
                h.model_cache_age_sec,
                h.best_side,
                h.best_outcome,
                h.best_edge_score,
                h.best_signal_edge_entry,
                d.title AS discovery_title,
                d.status AS discovery_status,
                d.token_count AS discovery_token_count,
                d.first_seen_at AS discovery_first_seen_at,
                d.first_tokenized_at AS discovery_first_tokenized_at,
                d.updated_at AS discovery_updated_at
            FROM event_fact_latest l
            JOIN event_fact_history h ON h.id = l.fact_id
            LEFT JOIN weather_market_discovery d
              ON d.slug = l.slug
             AND d.event_date = l.event_date
            WHERE h.run_date = ?
               OR l.event_date = ?
               OR (l.event_date > ? AND l.event_date <= ?)
            ORDER BY h.event_date ASC, h.fact_as_of DESC, h.id DESC
            LIMIT ?
            """,
            (date_key, date_key, date_key, end_key, limit),
        )
        rows = cur.fetchall()
    except sqlite3.OperationalError:
        return []
    out: List[Dict[str, Any]] = []
    seen: Set[Tuple[str, str]] = set()
    for row in rows or []:
        slug = str(row["slug"] or "").strip()
        event_date = _normalize_date_key(str(row["event_date"] or ""))
        if not slug or not event_date or not _event_date_matches_slug(slug, event_date):
            continue
        title = str(row["discovery_title"] or "").strip()
        if date_key and event_date > date_key and not _is_chengdu_market_identifier(slug, title):
            continue
        key = (slug, event_date)
        if key in seen:
            continue
        seen.add(key)
        market_var = _market_var_for_discovery_placeholder(title, slug)
        item: Dict[str, Any] = {
            "slug": slug,
            "event_date": event_date,
            "run_date": _normalize_date_key(str(row["run_date"] or "")),
            "fact_as_of": str(row["fact_as_of"] or ""),
            "fact_id": int(row["fact_id"] or 0),
            "model_snapshot_id": row["model_snapshot_id"],
            "market_snapshot_id": row["market_snapshot_id"],
            "market_updated_at": str(row["market_updated_at"] or ""),
            "model_updated_at": str(row["model_updated_at"] or ""),
            "market_stale_sec": row["market_stale_sec"],
            "model_cache_age_sec": row["model_cache_age_sec"],
            "summary_metadata_only": True,
            "summary_metadata_only_reason": "ui_snapshot_rebuild_in_flight",
            "snapshot_source": "event_fact_latest_metadata_only",
            "detail_available": False,
            "detail_na_reason": "ui_snapshot_rebuild_in_flight",
            "frontend_inference_allowed": False,
            "ssot_detail_state": {
                "state": "metadata_only",
                "label": "事实详情缓存中",
                "reason": "ui_snapshot_rebuild_in_flight",
                "detail_available": False,
                "frontend_inference_allowed": False,
                "frontend_behavior": "placeholder_only",
                "ssot_source": "event_fact_latest/event_fact_history_columns",
            },
            "data_status": {
                "status": "metadata_only",
                "reason": "ui_snapshot_rebuild_in_flight",
                "label": "事实详情缓存中",
                "detail_available": False,
                "frontend_inference_allowed": False,
                "ssot_source": "event_fact_latest/event_fact_history_columns",
            },
        }
        if title:
            item["title"] = title
        if market_var:
            item["market_var"] = market_var
        discovery: Dict[str, Any] = {}
        for dst, src in (
            ("status", "discovery_status"),
            ("token_count", "discovery_token_count"),
            ("first_seen_at", "discovery_first_seen_at"),
            ("first_tokenized_at", "discovery_first_tokenized_at"),
            ("updated_at", "discovery_updated_at"),
        ):
            value = row[src]
            if value not in (None, ""):
                discovery[dst] = value
        if discovery:
            item["market_discovery"] = discovery
        # Keep raw execution metadata distinct from target-bucket fields.
        if row["best_side"] not in (None, ""):
            item["fact_best_side"] = str(row["best_side"] or "")
        if row["best_outcome"] not in (None, ""):
            item["fact_best_outcome"] = str(row["best_outcome"] or "")
        if row["best_edge_score"] is not None:
            item["fact_best_edge_score"] = row["best_edge_score"]
        if row["best_signal_edge_entry"] is not None:
            item["fact_best_signal_edge_entry"] = row["best_signal_edge_entry"]
        out.append(item)
        if len(out) >= limit:
            break
    return out


def _event_fact_summary_cache_rebuild_fallback_items(
    conn: sqlite3.Connection,
    run_date_key: str,
    *,
    limit_val: int,
    upcoming_days: int = 2,
) -> List[Dict[str, Any]]:
    try:
        limit = max(1, min(int(limit_val or 0), 80))
    except (TypeError, ValueError):
        limit = 24
    rows = select_event_fact_summary_cache_rows_paged(
        conn,
        run_date_key,
        1,
        limit,
        include_upcoming=True,
        upcoming_days=upcoming_days,
    )
    if not rows:
        return []
    try:
        trade_map_for_plan = query_edge_trades(conn)
    except Exception:
        trade_map_for_plan = {}
    out: List[Dict[str, Any]] = []
    for row in rows:
        payload = safe_json_loads(str(row["summary_json"] or ""))
        if not isinstance(payload, dict) or not payload:
            continue
        _merge_fill_fact_row_meta(payload, row)
        distribution = normalize_distribution_rows(payload.get("distribution") or payload.get("rows") or [])
        if distribution:
            payload["distribution"] = distribution
            _sanitize_physical_d0_explanation_in_distribution(distribution)
            event_date_key = _normalize_date_key(str(payload.get("event_date") or row["event_date"] or ""))
            run_date_for_payload = _normalize_date_key(str(payload.get("run_date") or row["run_date"] or ""))
            _prepare_summary_distribution_market_fields_in_place(
                distribution,
                event_date_key=event_date_key,
                run_date_key=run_date_for_payload,
            )
            _apply_display_probability_fields_in_place(distribution)
            _hydrate_fact_market_top_fields_from_distribution(payload, distribution)
            if _is_chengdu_zuuu_fact_payload(str(payload.get("slug") or row["slug"] or ""), payload):
                _attach_model_raw_top_history_for_ui_snapshot(conn, payload, row)
            _attach_model_member_cache_snapshot_for_ui_snapshot(conn, payload, row)
            _attach_model_bucket_rule_comparison_for_ui_snapshot(conn, payload, row)
        else:
            _hydrate_fact_market_top_label(payload)
            _hydrate_fact_single_temperature_top(payload)
        compact_intraday = _compact_chengdu_intraday_summary_for_ui_snapshot(
            payload.get("chengdu_intraday_summary")
        )
        if compact_intraday:
            payload["chengdu_intraday_summary"] = compact_intraday
            _apply_chengdu_intraday_summary_to_snapshot_out(
                payload,
                compact_intraday,
                force_target_fields=True,
            )
        try:
            _merge_fill_fast_observation_fields_from_latest_fact(
                conn,
                payload,
                str(row["slug"] or ""),
                _normalize_date_key(str(row["event_date"] or "")),
            )
        except Exception:
            pass
        _align_snapshot_posterior_derived_fields(payload)
        _attach_temperature_trajectory_timeline_for_ui_snapshot(conn, payload, row)
        _attach_target_realization_capital_plan(
            payload,
            trade_map=trade_map_for_plan,
            fills_map={},
            auto_orders_map={},
        )
        out.append(
            _slim_fact_payload_for_ui_snapshot_summary(
                payload,
                include_physical_detail=UI_SNAPSHOT_SUMMARY_PHYSICAL_DETAIL,
            )
        )
        if len(out) >= limit:
            break
    return out


def _event_fact_summary_cache_fast_fallback_items(
    conn: sqlite3.Connection,
    run_date_key: str,
    *,
    limit_val: int,
    upcoming_days: int = 2,
    include_dynamic_overlays: bool = True,
    city_filter: str = "",
    compact_for_summary: bool = False,
) -> List[Dict[str, Any]]:
    try:
        limit = max(1, min(int(limit_val or 0), 80))
    except (TypeError, ValueError):
        limit = 24
    city_key = _normalize_ui_snapshot_city_filter(city_filter)
    query_limit = 200 if city_key else limit
    if city_key == "chengdu":
        rows = select_chengdu_event_fact_summary_cache_rows_paged(
            conn,
            run_date_key,
            query_limit,
            upcoming_days=upcoming_days,
        )
    else:
        rows = select_event_fact_summary_cache_rows_paged(
            conn,
            run_date_key,
            1,
            query_limit,
            include_upcoming=True,
            upcoming_days=upcoming_days,
        )
    out: List[Dict[str, Any]] = []
    for row in rows:
        if city_key and not _ui_snapshot_summary_row_matches_city_filter(row, city_key):
            continue
        raw_summary_json = str(row["summary_json"] or "")
        summary_cache_current = _event_fact_summary_cache_json_current(raw_summary_json)
        payload = safe_json_loads(raw_summary_json)
        if not isinstance(payload, dict) or not payload:
            continue
        _merge_fill_fact_row_meta(payload, row)
        if city_key and not _ui_snapshot_summary_item_matches_city_filter(payload, city_key):
            continue
        payload_is_chengdu = _is_chengdu_zuuu_fact_payload(
            str(payload.get("slug") or row["slug"] or ""),
            payload,
        )
        dynamic_overlay_for_payload = bool(include_dynamic_overlays or payload_is_chengdu)
        compact_intraday = _compact_chengdu_intraday_summary_for_ui_snapshot(
            payload.get("chengdu_intraday_summary")
        )
        if compact_intraday:
            payload["chengdu_intraday_summary"] = compact_intraday
            _apply_chengdu_intraday_summary_to_snapshot_out(
                payload,
                compact_intraday,
                force_target_fields=True,
                align_latest_fact=dynamic_overlay_for_payload,
            )
        if dynamic_overlay_for_payload or not summary_cache_current:
            try:
                _merge_fill_fast_observation_fields_from_latest_fact(
                    conn,
                    payload,
                    str(row["slug"] or ""),
                    _normalize_date_key(str(row["event_date"] or "")),
                )
            except Exception:
                pass
        if not summary_cache_current:
            payload["summary_cache_stale_version_guard_applied"] = True
        _attach_model_member_cache_snapshot_for_ui_snapshot(conn, payload, row)
        if isinstance(payload.get("distribution"), list):
            _attach_model_bucket_rule_comparison_for_ui_snapshot(conn, payload, row)
        _suppress_ui_target_fields_when_posterior_ssot_unavailable(payload)
        _align_snapshot_posterior_derived_fields(payload)
        if dynamic_overlay_for_payload:
            _attach_temperature_trajectory_timeline_for_ui_snapshot(conn, payload, row)
        _align_item_target_fields_to_canonical_posterior_top(payload)
        _attach_target_switch_context(payload)
        _align_item_target_fields_to_canonical_posterior_top(payload)
        _sync_ui_probability_copy_fields_to_canonical(payload)
        _compact_ui_snapshot_target_fields_in_place(payload)
        _suppress_ui_target_fields_when_posterior_ssot_unavailable(payload)
        _attach_ui_temperature_trajectory_status_from_payload(payload)
        _attach_ui_snapshot_sections_to_item(payload)
        _attach_chengdu_model_weight_shadow_for_ui_snapshot(payload)
        payload["summary_cache_fallback_fast"] = True
        if not dynamic_overlay_for_payload:
            payload["summary_cache_dynamic_overlays_skipped"] = True
        payload.setdefault("summary_cache_source", "event_fact_summary_cache")
        if compact_for_summary:
            payload = _compact_ui_snapshot_summary_item_for_first_screen(payload)
        out.append(payload)
        if len(out) >= limit:
            break
    return out


def _ui_snapshot_summary_item_key(item: Mapping[str, Any]) -> Optional[Tuple[str, str]]:
    slug = str(item.get("slug") or "").strip()
    event_date = _normalize_date_key(str(item.get("event_date") or ""))
    if not slug or not event_date:
        return None
    return slug, event_date


def _merge_ui_snapshot_summary_fallback_items(
    primary_items: Sequence[Mapping[str, Any]],
    supplement_items: Sequence[Mapping[str, Any]],
    *,
    limit_val: int,
) -> List[Dict[str, Any]]:
    try:
        limit = max(1, min(int(limit_val or 0), 80))
    except (TypeError, ValueError):
        limit = 24
    out: List[Dict[str, Any]] = []
    seen: Set[Tuple[str, str]] = set()
    for item in list(primary_items or []) + list(supplement_items or []):
        if not isinstance(item, Mapping):
            continue
        key = _ui_snapshot_summary_item_key(item)
        if key is not None:
            if key in seen:
                continue
            seen.add(key)
        out.append(dict(item))
        if len(out) >= limit:
            break
    return out


def _ui_snapshot_summary_item_keys(items: Sequence[Mapping[str, Any]]) -> Set[Tuple[str, str]]:
    keys: Set[Tuple[str, str]] = set()
    for item in items or []:
        if not isinstance(item, Mapping):
            continue
        key = _ui_snapshot_summary_item_key(item)
        if key is not None:
            keys.add(key)
    return keys


def _merge_fill_fast_observation_fields_from_latest_fact(
    conn: sqlite3.Connection,
    payload: Dict[str, Any],
    slug: str,
    event_date: str,
) -> None:
    if not isinstance(payload, dict):
        return
    slug_key = str(slug or payload.get("slug") or "").strip()
    event_key = _normalize_date_key(str(event_date or payload.get("event_date") or ""))
    if not slug_key or not event_key:
        return
    cur = conn.cursor()
    try:
        cur.execute(
            """
            SELECT h.id, h.run_date, h.slug, h.event_date, h.fact_as_of, h.composer_version, h.fact_json
            FROM event_fact_latest l
            JOIN event_fact_history h ON h.id = l.fact_id
            WHERE l.slug = ? AND l.event_date = ?
            LIMIT 1
            """,
            (slug_key, event_key),
        )
        row = cur.fetchone()
    except sqlite3.OperationalError:
        row = None
    if not row:
        return
    latest_payload = safe_json_loads(str(row["fact_json"] or ""))
    if not isinstance(latest_payload, Mapping):
        return
    overlay_payload, projection_meta = _ui_snapshot_project_latest_fact_payload_no_apply(
        conn,
        fact_id=row["id"],
        slug=str(row["slug"] or slug_key),
        event_date=str(row["event_date"] or event_key),
        run_date=str(row["run_date"] or event_key),
        fact_as_of=str(row["fact_as_of"] or ""),
        composer_version=str(row["composer_version"] or ""),
        payload=latest_payload,
    )
    _overlay_latest_fact_observation_fields(payload, overlay_payload)
    _overlay_latest_fact_bayes_fields(payload, overlay_payload)
    if projection_meta:
        provenance = dict(payload.get("fact_provenance") or {})
        provenance["ui_snapshot_latest_fact_projection"] = projection_meta
        payload["fact_provenance"] = provenance
    payload["fast_observation_overlay_source"] = "event_fact_latest"


def _ui_snapshot_summary_metadata_fallback_payload(
    *,
    run_date_key: str,
    requested_limit_val: int,
    limit_val: int,
    cache_key: str = "",
    city_filter: str = "",
) -> Optional[Dict[str, Any]]:
    metadata_overlay_available = False
    try:
        upcoming_days_val = _ui_upcoming_days()
        city_key = _normalize_ui_snapshot_city_filter(city_filter)
        try:
            requested_limit_cap = max(1, min(int(requested_limit_val or 0), 80))
        except (TypeError, ValueError):
            requested_limit_cap = 24
        with open_db_ro_fast(timeout_sec=0.06, busy_timeout_ms=0) as conn:
            conn.row_factory = sqlite3.Row
            items = _event_fact_summary_cache_fast_fallback_items(
                conn,
                run_date_key,
                limit_val=limit_val,
                upcoming_days=upcoming_days_val,
                include_dynamic_overlays=False,
                city_filter=city_key,
                compact_for_summary=bool(city_key),
            )
            if items:
                metadata_items = []
                if not city_key:
                    metadata_items = _event_fact_metadata_only_summary_items(
                        conn,
                        run_date_key,
                        limit_val=limit_val,
                        upcoming_days=upcoming_days_val,
                    )
                    metadata_items = [
                        item
                        for item in metadata_items
                        if _normalize_date_key(str(item.get("event_date") or "")) >= run_date_key
                        and _ui_snapshot_summary_item_matches_city_filter(item, city_key)
                    ]
                supplement_items: List[Dict[str, Any]] = list(metadata_items)
                existing_keys = _ui_snapshot_summary_item_keys(list(items) + supplement_items)
                remaining = max(0, requested_limit_cap - len(existing_keys))
                discovery_items: List[Dict[str, Any]] = []
                if remaining > 0 and not city_key:
                    discovery_items = [
                        _slim_fact_payload_for_ui_snapshot_summary(
                            payload,
                            include_physical_detail=UI_SNAPSHOT_SUMMARY_PHYSICAL_DETAIL,
                        )
                        for payload in _discovery_placeholder_payloads(
                            conn,
                            run_date_key,
                            upcoming_days=upcoming_days_val,
                            exclude_keys=existing_keys,
                            limit=(200 if city_key else remaining),
                        )
                        if _ui_snapshot_summary_item_matches_city_filter(payload, city_key)
                    ]
                    discovery_items = discovery_items[:remaining]
                    supplement_items.extend(discovery_items)
                merged_items = _merge_ui_snapshot_summary_fallback_items(
                    items,
                    supplement_items,
                    limit_val=requested_limit_cap,
                )
                source = "event_fact_summary_cache_fast_fallback"
                if metadata_items and discovery_items:
                    source = "event_fact_summary_cache_fast_fallback_with_metadata_and_discovery"
                elif metadata_items:
                    source = "event_fact_summary_cache_fast_fallback_with_metadata"
                elif discovery_items:
                    source = "event_fact_summary_cache_fast_fallback_with_discovery"
                payload = _ui_snapshot_busy_payload(
                    run_date_key=run_date_key,
                    limit_val=requested_limit_val,
                    summary_mode=True,
                    cache_key=cache_key,
                )
                payload["summary_cache_fallback"] = True
                payload["summary_cache_fallback_reason"] = "ui_snapshot_rebuild_in_flight"
                payload["summary_cache_fallback_fast"] = True
                if metadata_items:
                    payload["summary_metadata_only_supplement"] = True
                if discovery_items:
                    payload["summary_discovery_placeholder_supplement"] = True
                payload["facts"] = {
                    "items": merged_items,
                    "total": len(merged_items),
                    "page": 1,
                    "page_size": int(requested_limit_val),
                    "source": source,
                }
                return payload
            items = _event_fact_metadata_only_summary_items(
                conn,
                run_date_key,
                limit_val=limit_val,
                upcoming_days=upcoming_days_val,
            )
            if city_key:
                items = [
                    item
                    for item in items
                    if _ui_snapshot_summary_item_matches_city_filter(item, city_key)
                ]
            overlay_items: List[Dict[str, Any]] = []
            for raw_item in items:
                item = dict(raw_item) if isinstance(raw_item, Mapping) else {}
                if not item:
                    continue
                try:
                    _merge_fill_fast_observation_fields_from_latest_fact(
                        conn,
                        item,
                        str(item.get("slug") or ""),
                        _normalize_date_key(str(item.get("event_date") or "")),
                    )
                    _align_snapshot_posterior_derived_fields(item)
                    _attach_temperature_trajectory_timeline_for_ui_snapshot(
                        conn,
                        item,
                        raw_item,
                    )
                    _attach_target_switch_context(item)
                    _attach_ui_snapshot_sections_to_item(item)
                    slim_item = _slim_fact_payload_for_ui_snapshot_summary(
                        item,
                        include_physical_detail=UI_SNAPSHOT_SUMMARY_PHYSICAL_DETAIL,
                    )
                    if (
                        isinstance(slim_item, dict)
                        and _ui_snapshot_summary_item_has_display_ssot_contract(slim_item)
                    ):
                        overlay_items.append(slim_item)
                    else:
                        overlay_items.append(item)
                except Exception:
                    overlay_items.append(item)
            if overlay_items and any(
                _ui_snapshot_summary_item_has_display_ssot_contract(item)
                for item in overlay_items
                if isinstance(item, Mapping)
            ):
                items = overlay_items
                metadata_overlay_available = True
    except Exception:
        return None
    if not items:
        return None
    items = list(items)
    existing_keys = _ui_snapshot_summary_item_keys(items)
    remaining = max(0, requested_limit_cap - len(existing_keys))
    discovery_items: List[Dict[str, Any]] = []
    if remaining > 0:
        try:
            discovery_items = [
                _slim_fact_payload_for_ui_snapshot_summary(
                    payload,
                    include_physical_detail=UI_SNAPSHOT_SUMMARY_PHYSICAL_DETAIL,
                )
                for payload in _discovery_placeholder_payloads(
                    conn,
                    run_date_key,
                    upcoming_days=upcoming_days_val,
                    exclude_keys=existing_keys,
                    limit=(200 if _normalize_ui_snapshot_city_filter(city_filter) else remaining),
                )
                if _ui_snapshot_summary_item_matches_city_filter(payload, city_filter)
            ]
            discovery_items = discovery_items[:remaining]
        except Exception:
            discovery_items = []
    if discovery_items:
        items = _merge_ui_snapshot_summary_fallback_items(
            items,
            discovery_items,
            limit_val=requested_limit_cap,
        )
    payload = _ui_snapshot_busy_payload(
        run_date_key=run_date_key,
        limit_val=requested_limit_val,
        summary_mode=True,
        cache_key=cache_key,
    )
    payload["summary_metadata_only"] = not metadata_overlay_available
    payload["summary_metadata_only_reason"] = (
        "ui_snapshot_rebuild_in_flight"
        if not metadata_overlay_available
        else "latest_fact_overlay_available_during_ui_snapshot_rebuild"
    )
    if metadata_overlay_available:
        payload["summary_latest_fact_overlay_fallback"] = True
    if discovery_items:
        payload["summary_discovery_placeholder_supplement"] = True
    payload["facts"] = {
        "items": items[:requested_limit_cap],
        "total": None,
        "page": 1,
        "page_size": int(requested_limit_val),
        "source": (
            "event_fact_latest_summary_overlay_with_discovery"
            if metadata_overlay_available and discovery_items
            else "event_fact_latest_summary_overlay"
            if metadata_overlay_available
            else "event_fact_latest_summary_metadata_only_with_discovery"
            if discovery_items
            else "event_fact_latest_summary_metadata_only"
        ),
    }
    return payload


def _ui_snapshot_summary_latest_run_date_cached() -> str:
    """Resolve the dashboard date without making every summary request rescan SQLite."""

    global _UI_SNAPSHOT_SUMMARY_RUN_DATE_CACHE
    now_ts = time.time()
    if UI_SNAPSHOT_SUMMARY_RUN_DATE_CACHE_SEC > 0:
        with _UI_SNAPSHOT_SUMMARY_RUN_DATE_CACHE_LOCK:
            cached_ts, cached_value = _UI_SNAPSHOT_SUMMARY_RUN_DATE_CACHE
        if cached_value and (now_ts - float(cached_ts or 0.0)) <= UI_SNAPSHOT_SUMMARY_RUN_DATE_CACHE_SEC:
            return cached_value
    run_date_key = ""
    try:
        with open_db_ro_fast(timeout_sec=0.12, busy_timeout_ms=0) as conn:
            run_date_key = latest_ui_default_run_date(conn) or ""
    except Exception:
        run_date_key = ""
    if not run_date_key:
        try:
            with open_db_ro_fast(timeout_sec=0.08, busy_timeout_ms=0) as conn:
                run_date_key = (
                    latest_ui_default_run_date(conn)
                    or latest_fact_run_date(conn)
                    or latest_unsettled_run_date(conn)
                    or latest_run_date(conn)
                    or ""
                )
        except Exception:
            run_date_key = ""
    run_date_key = _normalize_date_key(run_date_key)
    if run_date_key and UI_SNAPSHOT_SUMMARY_RUN_DATE_CACHE_SEC > 0:
        with _UI_SNAPSHOT_SUMMARY_RUN_DATE_CACHE_LOCK:
            _UI_SNAPSHOT_SUMMARY_RUN_DATE_CACHE = (time.time(), run_date_key)
    return run_date_key


def _reported_trajectory_no_ui_ssot(conn: sqlite3.Connection, *, limit: int = 24) -> Dict[str, Any]:
    """Read the unique production strategy from one archive.db snapshot."""

    try:
        activation_row = conn.execute(
            """SELECT generation,state,activation_sha256,config_sha256,
                      old_bayes_execution_disabled,awc_amsc_disjoint,activation_json,updated_at
               FROM reported_trajectory_activation_state WHERE singleton=1"""
        ).fetchone()
    except sqlite3.OperationalError as exc:
        return {
            "schema": "reported_trajectory_no_ui_ssot_v1",
            "available": False,
            "na_reason": f"reported_trajectory_schema_unavailable:{type(exc).__name__}",
        }
    if activation_row is None:
        return {
            "schema": "reported_trajectory_no_ui_ssot_v1",
            "available": False,
            "na_reason": "reported_trajectory_activation_missing",
        }
    try:
        activation_policy = json.loads(str(activation_row[6] or "{}"))
    except (TypeError, ValueError):
        activation_policy = {}
    registry_rows = conn.execute(
        """SELECT source_lane,
                  COUNT(DISTINCT CASE WHEN source_eligible=1 THEN slug||'|'||event_date END) eligible_market_days,
                  COUNT(DISTINCT CASE WHEN source_eligible=0 THEN slug||'|'||event_date END) blocked_market_days,
                  COUNT(DISTINCT CASE WHEN source_eligible=1 THEN station_id END) station_count,
                  MAX(refreshed_at) refreshed_at
           FROM reported_trajectory_market_registry GROUP BY source_lane ORDER BY source_lane"""
    ).fetchall()
    latest_polls = conn.execute(
        """SELECT p.source_lane,p.request_started_at,p.response_started_at,p.response_completed_at,
                  p.duration_ms,p.report_count,p.new_report_count,p.error_code,p.poll_json
           FROM reported_trajectory_source_polls p
           JOIN (
             SELECT source_lane,MAX(response_completed_at) completed
             FROM reported_trajectory_source_polls GROUP BY source_lane
           ) latest ON latest.source_lane=p.source_lane AND latest.completed=p.response_completed_at
           ORDER BY p.source_lane"""
    ).fetchall()
    poll_rows: List[Dict[str, Any]] = []
    for row in latest_polls:
        try:
            poll_meta = json.loads(str(row[8] or "{}"))
        except (TypeError, ValueError):
            poll_meta = {}
        poll_rows.append(
            {
                "source_lane": str(row[0] or ""),
                "request_started_at": str(row[1] or ""),
                "response_started_at": str(row[2] or ""),
                "response_completed_at": str(row[3] or ""),
                "canonical_processing_ms": float(row[4] or 0.0),
                "report_count": int(row[5] or 0),
                "new_report_count": int(row[6] or 0),
                "error_code": str(row[7] or ""),
                "transport": str(poll_meta.get("transport") or ""),
                "taf_requested": poll_meta.get("taf_requested"),
            }
        )
    bound_rows = [
        {
            "source_lane": str(row[0] or ""), "station_id": str(row[1] or ""),
            "event_date": str(row[2] or ""), "settlement_timezone": str(row[3] or ""),
            "reported_max_c": int(row[4]), "max_valid_at": str(row[5] or ""),
            "bound_generation": int(row[6] or 0), "updated_at": str(row[7] or ""),
        }
        for row in conn.execute(
            """SELECT source_lane,station_id,event_date,settlement_timezone,reported_max_c,
                      max_valid_at,bound_generation,updated_at
               FROM reported_trajectory_station_day_bounds
               ORDER BY datetime(updated_at) DESC LIMIT ?""",
            (max(1, min(int(limit), 100)),),
        ).fetchall()
    ]
    intent_rows = [
        {
            "order_intent_id": str(row[0] or ""), "source_lane": str(row[1] or ""),
            "station_id": str(row[2] or ""), "slug": str(row[3] or ""),
            "event_date": str(row[4] or ""), "outcome": str(row[5] or ""),
            "reported_max_c": int(row[6]), "hard_lower_bound_market_unit": int(row[7]),
            "limit_price": float(row[8]), "order_type": str(row[9] or ""),
            "requested_notional_usdc": float(row[10] or 0.0), "state": str(row[11] or ""),
            "fetch_completed_at": str(row[12] or ""), "decision_created_at": str(row[13] or ""),
            "gateway_received_at": str(row[14] or ""), "exchange_post_started_at": str(row[15] or ""),
            "created_at": str(row[16] or ""), "updated_at": str(row[17] or ""),
        }
        for row in conn.execute(
            """SELECT order_intent_id,source_lane,station_id,slug,event_date,outcome,
                      reported_max_c,hard_lower_bound_market_unit,limit_price,order_type,
                      requested_notional_usdc,state,fetch_completed_at,decision_created_at,
                      gateway_received_at,exchange_post_started_at,created_at,updated_at
               FROM reported_trajectory_no_intents ORDER BY datetime(updated_at) DESC LIMIT ?""",
            (max(1, min(int(limit), 100)),),
        ).fetchall()
    ]
    capital_rows = [
        {
            "source_lane": str(row[0] or ""), "state": str(row[1] or ""),
            "notional_usdc": float(row[2] or 0.0), "intent_count": int(row[3] or 0),
        }
        for row in conn.execute(
            """SELECT source_lane,state,COALESCE(SUM(reserved_notional_usdc),0),COUNT(*)
               FROM reported_trajectory_capital_ledger GROUP BY source_lane,state
               ORDER BY source_lane,state"""
        ).fetchall()
    ]
    return {
        "schema": "reported_trajectory_no_ui_ssot_v1",
        "available": True,
        "production_strategy_id": str(activation_policy.get("strategy_id") or "reported_trajectory_no_v1"),
        "production_semantics": "metar_speci_reported_max_hard_lower_bound_to_nearest_impossible_bucket_no",
        "probability_model_active": False,
        "bayes_consumed": False,
        "taf_consumed": False,
        "yes_orders_allowed": False,
        "activation": {
            "generation": int(activation_row[0] or 0), "state": str(activation_row[1] or ""),
            "activation_sha256": str(activation_row[2] or ""), "config_sha256": str(activation_row[3] or ""),
            "old_bayes_execution_disabled": bool(activation_row[4]),
            "awc_amsc_disjoint": bool(activation_row[5]), "updated_at": str(activation_row[7] or ""),
        },
        "order_policy": {
            "outcome_side": "NO", "order_type": str(activation_policy.get("order_type") or "FAK"),
            "maximum_buy_price": activation_policy.get("maximum_buy_price"),
            "historical_shadow_bounds_replayed": False,
        },
        "capital_split": activation_policy.get("capital_split") or {},
        "market_registry": [
            {
                "source_lane": str(row[0] or ""), "eligible_market_days": int(row[1] or 0),
                "blocked_market_days": int(row[2] or 0), "station_count": int(row[3] or 0),
                "refreshed_at": str(row[4] or ""),
            }
            for row in registry_rows
        ],
        "latest_source_polls": poll_rows,
        "station_day_bounds": bound_rows,
        "recent_order_intents": intent_rows,
        "capital_ledger": capital_rows,
        "ssot": "/api/ui_snapshot",
        "read_model": "data/archive.db",
    }


def _basket_strategy_ui_ssot(
    conn: sqlite3.Connection,
    *,
    items: Sequence[Mapping[str, Any]] = (),
    limit: int = 24,
) -> Dict[str, Any]:
    """Read the production basket plan/cycle ledger for the UI.

    This is deliberately a read model only.  The browser must never rebuild a
    basket from posterior probabilities or market quotes: the selected bucket
    set comes from the immutable ``plan_json`` written by the production
    basket executor, while leg state/notional comes from the formal legs
    table.  Missing tables or rows are represented explicitly as ``available``
    with a ``na_reason`` so the dashboard cannot silently display a guessed
    basket.
    """

    schema = "basket_strategy_ui_ssot_v1"
    strategy_id = "weather_basket_yes_v2"
    row_limit = max(1, min(int(limit or 24), 200))

    def _number(value: Any, default: float = 0.0) -> float:
        try:
            parsed = float(value)
        except (TypeError, ValueError):
            return float(default)
        return parsed if math.isfinite(parsed) else float(default)

    try:
        activation_row = conn.execute(
            """SELECT generation,state,strategy_id,activation_sha256,activation_json,updated_at
               FROM basket_strategy_activation_state WHERE singleton=1"""
        ).fetchone()
        cycle_rows = conn.execute(
            """SELECT cycle_id,strategy_id,slug,event_date,plan_sha256,plan_json,state,
                      total_cost_usdc,quantity_per_bucket,created_at,updated_at
               FROM basket_strategy_cycles
              WHERE strategy_id=?
              ORDER BY datetime(updated_at) DESC, rowid DESC
              LIMIT ?""",
            (strategy_id, max(row_limit * 8, 48)),
        ).fetchall()
        leg_rows = conn.execute(
            """SELECT cycle_id,bucket,token_id,side,limit_price,requested_size,
                      requested_notional_usdc,order_type,state,size_matched,created_at,updated_at
               FROM basket_strategy_legs
              WHERE cycle_id IN (
                    SELECT cycle_id FROM basket_strategy_cycles
                     WHERE strategy_id=?
              )
              ORDER BY datetime(created_at), rowid""",
            (strategy_id,),
        ).fetchall()
    except sqlite3.OperationalError as exc:
        return {
            "schema": schema,
            "available": False,
            "materialized": False,
            "read_only": True,
            "production_strategy_id": strategy_id,
            "source": {"read_model": "data/archive.db", "tables": ["basket_strategy_cycles", "basket_strategy_legs"]},
            "items": [],
            "na_reason": f"basket_strategy_schema_unavailable:{type(exc).__name__}",
        }

    activation: Dict[str, Any] = {}
    activation_policy: Dict[str, Any] = {}
    if activation_row is not None:
        try:
            parsed_activation = json.loads(str(activation_row[4] or "{}"))
            activation_policy = dict(parsed_activation) if isinstance(parsed_activation, Mapping) else {}
        except (TypeError, ValueError):
            activation_policy = {}
        activation = {
            "generation": int(activation_row[0] or 0),
            "state": str(activation_row[1] or ""),
            "strategy_id": str(activation_row[2] or strategy_id),
            "activation_sha256": str(activation_row[3] or ""),
            "updated_at": str(activation_row[5] or ""),
        }

    item_keys = {
        (
            str(item.get("slug") or "").strip(),
            _normalize_date_key(str(item.get("event_date") or "")),
        )
        for item in items
        if isinstance(item, Mapping)
        and str(item.get("slug") or "").strip()
        and _normalize_date_key(str(item.get("event_date") or ""))
    }
    # Keep the latest cycle per market-day.  Prefer cycles represented in the
    # current facts page, then use recent unmatched cycles as a bounded audit
    # trail for the event strip.
    selected_cycles: List[Any] = []
    seen_keys: Set[Tuple[str, str]] = set()
    for row in cycle_rows:
        key = (str(row[2] or "").strip(), _normalize_date_key(str(row[3] or "")))
        if not key[0] or not key[1] or key in seen_keys:
            continue
        if item_keys and key not in item_keys:
            continue
        selected_cycles.append(row)
        seen_keys.add(key)
        if len(selected_cycles) >= row_limit:
            break
    if len(selected_cycles) < row_limit:
        for row in cycle_rows:
            key = (str(row[2] or "").strip(), _normalize_date_key(str(row[3] or "")))
            if not key[0] or not key[1] or key in seen_keys:
                continue
            selected_cycles.append(row)
            seen_keys.add(key)
            if len(selected_cycles) >= row_limit:
                break

    legs_by_cycle: Dict[str, List[Dict[str, Any]]] = {}
    for row in leg_rows:
        cycle_id = str(row[0] or "").strip()
        if not cycle_id:
            continue
        legs_by_cycle.setdefault(cycle_id, []).append(
            {
                "bucket": str(row[1] or ""),
                "side": str(row[3] or "YES").upper(),
                "limit_price": _number(row[4]),
                "requested_size": _number(row[5]),
                "requested_notional_usdc": _number(row[6]),
                "order_type": str(row[7] or "FOK"),
                "state": str(row[8] or ""),
                "size_matched": _number(row[9]),
                "created_at": str(row[10] or ""),
                "updated_at": str(row[11] or ""),
            }
        )

    output_items: List[Dict[str, Any]] = []
    for row in selected_cycles:
        cycle_id = str(row[0] or "")
        try:
            plan_value = json.loads(str(row[5] or "{}"))
            plan = dict(plan_value) if isinstance(plan_value, Mapping) else {}
        except (TypeError, ValueError):
            plan = {}
        plan_basket = plan.get("basket") if isinstance(plan.get("basket"), Mapping) else {}
        legs = legs_by_cycle.get(cycle_id, [])
        plan_orders = plan_basket.get("orders") if isinstance(plan_basket.get("orders"), list) else []
        selected_buckets = plan_basket.get("selected_buckets")
        if not isinstance(selected_buckets, list) or not selected_buckets:
            selected_buckets = [leg.get("bucket") for leg in legs if leg.get("bucket")]
        selected_buckets = [str(bucket) for bucket in selected_buckets if str(bucket or "").strip()]
        if not legs and plan_orders:
            # A prepared plan may be visible before its legs are persisted;
            # retain only the non-sensitive execution facts needed by UI.
            legs = [
                {
                    "bucket": str(order.get("bucket") or ""),
                    "side": str(order.get("side") or "YES").upper(),
                    "limit_price": _number(order.get("limit_price")),
                    "requested_size": _number(order.get("quantity")),
                    "requested_notional_usdc": _number(order.get("estimated_notional_usdc")),
                    "order_type": str(order.get("order_type") or "FOK"),
                    "state": "planned",
                    "size_matched": 0.0,
                    "created_at": "",
                    "updated_at": "",
                }
                for order in plan_orders
                if isinstance(order, Mapping) and str(order.get("bucket") or "").strip()
            ]
        probability = plan.get("probability_projection") if isinstance(plan.get("probability_projection"), Mapping) else {}
        direction = plan.get("direction_bias") if isinstance(plan.get("direction_bias"), Mapping) else {}
        regime = plan.get("regime") if isinstance(plan.get("regime"), Mapping) else {}
        output_items.append(
            {
                "slug": str(row[2] or ""),
                "event_date": _normalize_date_key(str(row[3] or "")),
                "cycle_id": cycle_id,
                "plan_id": str(plan.get("plan_id") or cycle_id),
                "plan_sha256": str(row[4] or ""),
                "state": str(row[6] or ""),
                "created_at": str(row[9] or ""),
                "updated_at": str(row[10] or ""),
                "basket": {
                    "status": str(plan_basket.get("status") or ""),
                    "mode": str(plan_basket.get("mode") or "pure_yes_basket"),
                    "direction": str(plan_basket.get("direction") or direction.get("direction") or ""),
                    "tranche_width": int(plan_basket.get("tranche_width")) if str(plan_basket.get("tranche_width") or "").isdigit() else None,
                    "convergence_coverage": _number(plan_basket.get("convergence_coverage")) if plan_basket.get("convergence_coverage") is not None and math.isfinite(_number(plan_basket.get("convergence_coverage"))) else None,
                    "convergence_target": _number(plan_basket.get("convergence_target")) if plan_basket.get("convergence_target") is not None and math.isfinite(_number(plan_basket.get("convergence_target"))) else None,
                    "tranche_signature": str(plan_basket.get("tranche_signature") or ""),
                    "selected_buckets": selected_buckets,
                    "orders": legs,
                    "quantity_per_bucket": _number(row[8], _number(plan_basket.get("quantity_per_bucket"))),
                    "per_share_all_in_cost": plan_basket.get("per_share_all_in_cost"),
                    "total_cost_usdc": _number(row[7], _number(plan_basket.get("total_cost_usdc"))),
                    "worst_case_settlement_payout_usdc": plan_basket.get("worst_case_settlement_payout_usdc"),
                    "guaranteed_profit_usdc": plan_basket.get("guaranteed_profit_usdc"),
                    "reason_codes": list(plan_basket.get("reason_codes") or []) if isinstance(plan_basket.get("reason_codes"), list) else [],
                },
                "lineage": {
                    "fact_snapshot_id": str(probability.get("fact_snapshot_id") or ""),
                    "posterior_run_id": str(probability.get("posterior_run_id") or ""),
                    "posterior_checkpoint_id": str(probability.get("posterior_checkpoint_id") or ""),
                    "probability_stage": str(probability.get("stage") or ""),
                    "direction": str(direction.get("direction") or ""),
                    "direction_status": str(direction.get("status") or ""),
                    "regime": regime,
                },
            }
        )

    return {
        "schema": schema,
        "available": True,
        "materialized": bool(output_items),
        "read_only": True,
        "production_strategy_id": str(activation_policy.get("strategy_id") or strategy_id),
        "activation": activation,
        "activation_state": str(activation_policy.get("state") or activation.get("state") or ""),
        "source": {
            "read_model": "data/archive.db",
            "tables": ["basket_strategy_cycles", "basket_strategy_legs"],
            "selection": "latest_cycle_per_slug_event_date",
        },
        "items": output_items,
        "na_reason": "" if output_items else "basket_cycle_not_materialized",
    }


def _ui_snapshot_primary_city_strategy(
    conn: sqlite3.Connection,
    item: Mapping[str, Any],
) -> Dict[str, Any]:
    """Read the same city SSOT/regime/basket view used by the multi-city UI.

    The digital dashboard and the city cards must not derive direction from
    different branches.  This is a read-only bridge to the board read model;
    it never invokes the basket executor or a quote precheck.
    """

    slug = str(item.get("slug") or "").strip()
    event_date = _normalize_date_key(str(item.get("event_date") or ""))
    if not slug or not event_date:
        return {}
    try:
        row = conn.execute(
            """SELECT station_id FROM reported_trajectory_market_registry
                 WHERE slug=? AND event_date=? AND source_eligible=1
                 ORDER BY station_id LIMIT 1""",
            (slug, event_date),
        ).fetchone()
    except sqlite3.Error:
        row = None
    station_id = str(row[0] or "").strip() if row is not None else ""
    if not station_id:
        return {}
    try:
        state = _china_board_city_strategy_state(
            conn,
            station_id=station_id,
            event_date=event_date,
            now=datetime.now(timezone.utc),
        )
        if isinstance(state, dict):
            state["station_id"] = station_id
        return state
    except Exception:
        return {}


def ui_snapshot(run_date: str = "", limit: int = 120, *, force_rebuild: bool = False) -> Dict[str, Any]:
    run_date_key = _normalize_date_key(run_date)
    if not run_date_key:
        try:
            with open_db_ro_fast(timeout_sec=0.25, busy_timeout_ms=200) as conn:
                run_date_key = latest_ui_default_run_date(conn) or ""
        except Exception:
            run_date_key = ""
        if not run_date_key:
            try:
                with open_db_ro_fast(timeout_sec=0.08, busy_timeout_ms=0) as conn:
                    run_date_key = (
                        latest_ui_default_run_date(conn)
                        or latest_fact_run_date(conn)
                        or latest_unsettled_run_date(conn)
                        or latest_run_date(conn)
                        or ""
                    )
            except Exception:
                run_date_key = ""
    if not run_date_key:
        return {"ok": False, "error": "no_run_date"}
    if not DB_PATH.exists():
        return {"ok": False, "error": "db_missing"}

    try:
        limit_val = int(limit or 0)
    except (TypeError, ValueError):
        limit_val = 120
    limit_val = max(10, min(limit_val, 2000))

    cache_key = f"{run_date_key}:{limit_val}"
    now_ts = time.time()
    cached = _ui_snapshot_cache_entry(cache_key)
    cache_dirty = _ui_snapshot_cache_is_dirty(cached)
    if (
        not force_rebuild
        and cached
        and not cache_dirty
        and (now_ts - float(cached[0])) <= float(UI_SNAPSHOT_CACHE_SEC)
    ):
        return _ui_snapshot_cached_payload(cached, stale=False, cache_key=cache_key)

    materialize_state = _facts_materialize_lock_state()
    if not force_rebuild and bool(materialize_state.get("active")):
        if cached:
            payload = _ui_snapshot_cached_payload(
                cached,
                stale=True,
                stale_reason="facts_materialize_active",
                cache_key=cache_key,
            )
            payload["cache_rebuild_skipped_reason"] = "facts_materialize_active"
            return payload
        return _ui_snapshot_busy_payload(
            run_date_key=run_date_key,
            limit_val=limit_val,
            summary_mode=False,
            cache_key=cache_key,
        )

    diag = auto_trade_env_diagnostics()

    def _compute(conn: sqlite3.Connection) -> Dict[str, Any]:
        conn.row_factory = sqlite3.Row
        cur = conn.cursor()
        run_row = None
        try:
            cur.execute(
                """
                SELECT id, run_date, started_at, ended_at, ok, error, processed, skipped, created_at
                FROM auto_trade_runs
                WHERE run_date = ?
                ORDER BY datetime(started_at) DESC, id DESC
                LIMIT 1
                """,
                (run_date_key,),
            )
            run_row = cur.fetchone()
        except sqlite3.OperationalError:
            run_row = None
        if not run_row:
            try:
                cur.execute(
                    """
                    SELECT id, run_date, started_at, ended_at, ok, error, processed, skipped, created_at
                    FROM auto_trade_runs
                    ORDER BY id DESC
                    LIMIT 1
                    """
                )
                run_row = cur.fetchone()
            except sqlite3.OperationalError:
                run_row = None
        run_id = int(run_row["id"]) if run_row else 0
        run_meta = {
            "id": run_id,
            "run_date": str(run_row["run_date"] or "") if run_row else run_date_key,
            "started_at": str(run_row["started_at"] or "") if run_row else "",
            "ended_at": str(run_row["ended_at"] or "") if run_row else "",
            "ok": int(run_row["ok"] or 0) if run_row else 0,
            "error": str(run_row["error"] or "") if run_row else "",
            "processed": int(run_row["processed"] or 0) if run_row else 0,
            "skipped": int(run_row["skipped"] or 0) if run_row else 0,
            "created_at": str(run_row["created_at"] or "") if run_row else "",
        }

        job_counts: Dict[str, int] = {}
        jobs_updated_at = ""
        try:
            cur.execute(
                """
                SELECT state, COUNT(*) AS n, MAX(updated_at) AS updated_at_max
                FROM auto_trade_jobs
                WHERE run_date = ?
                GROUP BY state
                """,
                (run_date_key,),
            )
            for row in cur.fetchall():
                state = str(row["state"] or "")
                if state:
                    job_counts[state] = int(row["n"] or 0)
                updated_at = str(row["updated_at_max"] or "")
                if updated_at and updated_at > jobs_updated_at:
                    jobs_updated_at = updated_at
        except sqlite3.OperationalError:
            job_counts = {}
            jobs_updated_at = ""

        entry_rows: List[Dict[str, Any]] = []
        entry_counts: Dict[str, int] = {"total": 0, "blocked": 0, "will_order": 0}
        reason_counts: Dict[str, int] = {}
        reason_examples: Dict[str, Dict[str, Any]] = {}

        def _parse_json_list(raw: Any) -> List[str]:
            text = str(raw or "").strip()
            if not text:
                return []
            try:
                val = json.loads(text)
            except Exception:
                return []
            if not isinstance(val, list):
                return []
            out: List[str] = []
            for item in val:
                if item is None:
                    continue
                tok = str(item).strip()
                if tok:
                    out.append(tok)
            return out

        if run_date_key:
            try:
                cur.execute(
                    """
                    SELECT slug, event_date, title, outcome, side, action, decided_state, will_order,
                           reason_codes_json, reasons_json, details_json, created_at
                    FROM auto_trade_decisions
                    WHERE run_date = ?
                    ORDER BY id DESC
                    LIMIT ?
                    """,
                    (run_date_key, limit_val),
                )
                for row in cur.fetchall():
                    entry_counts["total"] += 1
                    decided_state = str(row["decided_state"] or "")
                    will_order = int(row["will_order"] or 0)
                    if decided_state == "blocked" or (will_order == 0 and decided_state):
                        entry_counts["blocked"] += 1
                    if will_order:
                        entry_counts["will_order"] += 1
                    reason_codes = _parse_json_list(row["reason_codes_json"])
                    reasons = _parse_json_list(row["reasons_json"])
                    details = {}
                    try:
                        details_text = str(row["details_json"] or "").strip()
                        if details_text:
                            details = json.loads(details_text)
                    except Exception:
                        details = {}
                    payload = {
                        "slug": str(row["slug"] or ""),
                        "event_date": date_only(str(row["event_date"] or "")),
                        "title": str(row["title"] or ""),
                        "outcome": str(row["outcome"] or ""),
                        "side": str(row["side"] or "").strip().upper(),
                        "action": str(row["action"] or ""),
                        "decided_state": decided_state,
                        "will_order": will_order,
                        "reason_codes": reason_codes,
                        "reasons": reasons,
                        "details": details if isinstance(details, dict) else {},
                        "created_at": str(row["created_at"] or ""),
                    }
                    entry_rows.append(payload)

                    if decided_state == "blocked" and reason_codes:
                        code0 = reason_codes[0]
                        reason_counts[code0] = int(reason_counts.get(code0) or 0) + 1
                        if code0 not in reason_examples:
                            meta = _latest_event_meta_from_facts(
                                conn, payload["slug"], payload["event_date"]
                            ) if payload["slug"] and payload["event_date"] else {}
                            reason_examples[code0] = {
                                "slug": payload["slug"],
                                "event_date": payload["event_date"],
                                "title": str(meta.get("title") or payload["title"] or ""),
                                "event_url": str(meta.get("event_url") or ""),
                                "outcome": payload["outcome"],
                                "side": payload["side"],
                            }
            except sqlite3.OperationalError:
                entry_rows = []

        reason_stats: List[Dict[str, Any]] = []
        blocked_total = max(1, int(entry_counts.get("blocked") or 0))
        for code, n in sorted(reason_counts.items(), key=lambda it: (-it[1], it[0])):
            example = reason_examples.get(code) or {}
            reason_stats.append(
                {
                    "code": code,
                    "count": int(n),
                    "share": float(n) / float(blocked_total) if blocked_total else 0.0,
                    "example": example,
                }
            )

        # Live positions (truth = positions api funder; fallback = local).
        pos_overrides, pos_err, pos_updated = fetch_positions_cache(conn, force=False)
        trading_open = 0
        redeemable_open = 0
        closed_nonredeemable = 0
        closed_redeemable = 0
        if isinstance(pos_overrides, dict):
            event_status_cache: Dict[Tuple[str, str], Dict[str, Any]] = {}

            def _event_status(slug: str, event_date: str) -> Dict[str, Any]:
                key = (str(slug or "").strip(), date_only(str(event_date or "")))
                cached = event_status_cache.get(key)
                if cached is not None:
                    return cached
                meta = _latest_event_meta_from_facts(conn, key[0], key[1]) if key[0] and key[1] else {}
                status = {
                    "settlement_actual": to_float(meta.get("settlement_actual")) if isinstance(meta, dict) else None,
                    "market_closed": int((meta or {}).get("market_closed") or 0) if isinstance(meta, dict) else 0,
                }
                event_status_cache[key] = status
                return status

            for raw_key, entry in pos_overrides.items():
                if not (isinstance(raw_key, tuple) and len(raw_key) == 4 and isinstance(entry, dict)):
                    continue
                slug = str(raw_key[0] or "").strip()
                event_date = date_only(str(raw_key[1] or ""))
                size = to_float(entry.get("position_size"))
                if size is None:
                    size = to_float(entry.get("size"))
                if size is None or not math.isfinite(size) or size <= TIME_EDGE_Q_EPS:
                    continue
                redeemable = bool(entry.get("redeemable"))
                status = _event_status(slug, event_date)
                is_settled = status.get("settlement_actual") is not None
                is_closed = int(status.get("market_closed") or 0) == 1
                if is_settled or is_closed:
                    if redeemable:
                        closed_redeemable += 1
                    else:
                        closed_nonredeemable += 1
                    continue
                if redeemable:
                    redeemable_open += 1
                else:
                    trading_open += 1

        position_truth_source = "positions_api_funder"
        if ACCOUNT_REQUESTS_DISABLED:
            position_truth_source = "data_only_local"
        elif not POSITIONS_SYNC_ENABLED:
            position_truth_source = "local_position_ledger_sync_disabled"
        elif not POSITIONS_API_URL:
            position_truth_source = "local_position_ledger_missing_url"
        elif pos_err:
            position_truth_source = "local_position_ledger_sync_error"

        # Filled orders today (ET): distinct order_ids with linked attributions.
        filled_orders_today: Set[str] = set()
        try:
            lookback_days = 6
            since_dt = datetime.now().astimezone() - timedelta(days=lookback_days)
            since_key = since_dt.strftime("%Y-%m-%d %H:%M:%S")
            cur.execute(
                """
                SELECT a.order_id, f.trade_time, f.created_at
                FROM trade_fill_attributions a
                JOIN edge_trade_fills f ON f.id = a.fill_id
                WHERE a.linked = 1
                  AND a.attributed_at >= ?
                  AND a.order_id IS NOT NULL
                  AND a.order_id != ''
                """,
                (since_key,),
            )
            for row in cur.fetchall():
                order_id = str(row["order_id"] or "").strip()
                if not order_id:
                    continue
                day = _iso_day_in_tz(str(row["trade_time"] or row["created_at"] or ""), _ET_TZ)
                if day == run_date_key:
                    filled_orders_today.add(order_id)
        except sqlite3.OperationalError:
            filled_orders_today = set()
        except Exception:
            filled_orders_today = filled_orders_today

        fact_items: List[Dict[str, Any]] = []
        fact_total: Optional[int] = None
        fact_rows: List[sqlite3.Row] = []
        facts_source = "event_fact_latest_with_upcoming"
        upcoming_days_val = _ui_upcoming_days()
        try:
            fact_total = count_event_fact_rows(
                conn,
                run_date_key,
                include_upcoming=True,
                upcoming_days=upcoming_days_val,
            )
            fact_rows = select_event_fact_rows_paged(
                conn,
                run_date_key,
                1,
                min(limit_val, 200),
                include_upcoming=True,
                upcoming_days=upcoming_days_val,
            )
            market_tick_latest_map = query_market_tick_latest_for_keys(
                conn,
                [(row["slug"], row["event_date"]) for row in fact_rows],
            )
        except sqlite3.OperationalError:
            fact_rows = []
            market_tick_latest_map = {}
        try:
            platt_days = int(os.environ.get("PM_Q_PLATT_DAYS", "60"))
        except (TypeError, ValueError):
            platt_days = 60
        platt = _load_platt_calibration(platt_days or 0)
        first_prediction_stats = _safe_first_prediction_hit_rates(conn)
        forecast_source_accuracy = _safe_forecast_source_accuracy_snapshot_only(conn)
        joint_weak_bias_research = _safe_joint_weak_bias_research_snapshot_only(conn)
        try:
            trade_map_for_plan = query_edge_trades(conn)
            fills_map_for_plan = query_trade_fills(conn)
            auto_orders_map_for_plan = query_auto_orders(conn)
        except Exception:
            trade_map_for_plan = {}
            fills_map_for_plan = {}
            auto_orders_map_for_plan = {}
        intraday_summary_cache: Dict[str, Optional[Dict[str, Any]]] = {}
        fact_as_of_by_key: Dict[Tuple[str, str], str] = {}
        for row in fact_rows:
            try:
                payload = json.loads(row["fact_json"])
            except Exception:
                continue
            if not isinstance(payload, dict):
                continue
            _slim_fact_payload_for_ui(payload)
            _merge_fill_fact_row_meta(payload, row)
            distribution = normalize_distribution_rows(payload.get("distribution") or payload.get("rows") or [])
            if distribution:
                payload["distribution"] = distribution
                _sanitize_physical_d0_explanation_in_distribution(distribution)
                _hydrate_distribution_market_fields_in_place(
                    conn,
                    distribution,
                    str(payload.get("slug") or ""),
                    _normalize_date_key(str(payload.get("event_date") or "")),
                    _normalize_date_key(str(payload.get("run_date") or "")),
                )
                _apply_display_probability_fields_in_place(distribution)
            _hydrate_fact_market_updated_at(payload, market_tick_latest_map)
            _hydrate_fact_market_top_label(payload)
            _hydrate_fact_single_temperature_top(payload)
            _attach_market_flow_context(conn, payload, row)
            _hydrate_fact_precipitation_evidence_coverage(payload)
            try:
                _ensure_fact_q_calibrated(payload, platt)
            except Exception:
                pass
            try:
                _set_fact_q_calibrated_na_reason(payload, platt)
            except Exception:
                pass
            _attach_first_prediction_hit_rates(payload, first_prediction_stats)
            _attach_forecast_source_accuracy_for_ui_snapshot(payload, forecast_source_accuracy)
            _attach_joint_weak_bias_research_for_ui_snapshot(payload, joint_weak_bias_research)
            _attach_chengdu_intraday_summary_fields_for_ui_snapshot(
                payload,
                row,
                payload,
                intraday_summary_cache,
                run_date_key,
            )
            if distribution:
                _hydrate_distribution_market_fields_in_place(
                    conn,
                    distribution,
                    str(payload.get("slug") or row["slug"] or ""),
                    _normalize_date_key(str(payload.get("event_date") or row["event_date"] or "")),
                    _normalize_date_key(str(payload.get("run_date") or "")),
                )
                # Chengdu intraday SSOT alignment may replace payload["distribution"]
                # with a fact-cache copy. Keep the returned rows on the live-hydrated
                # distribution object so UI quote fields do not fall back to stale cache.
                payload["distribution"] = distribution
                _apply_display_probability_fields_in_place(distribution)
                _hydrate_fact_market_updated_at(payload, market_tick_latest_map)
                _hydrate_fact_market_top_fields_from_distribution(payload, distribution)
            _align_snapshot_posterior_derived_fields(payload)
            _attach_summary_bucket_series_history(conn, payload, row)
            _attach_temperature_trajectory_timeline_for_ui_snapshot(conn, payload, row)
            _attach_target_realization_capital_plan(
                payload,
                trade_map=trade_map_for_plan,
                fills_map=fills_map_for_plan,
                auto_orders_map=auto_orders_map_for_plan,
            )
            _attach_target_switch_context(payload)
            _attach_ui_snapshot_sections_to_item(payload)
            payload["auto_trade_ssot"] = _safe_build_auto_trade_ssot(payload)
            fact_key = (
                str(payload.get("slug") or row["slug"] or "").strip(),
                _normalize_date_key(str(payload.get("event_date") or row["event_date"] or "")),
            )
            if fact_key[0] and fact_key[1]:
                fact_as_of_by_key[fact_key] = str(row["fact_as_of"] or payload.get("fact_as_of") or "")
            fact_items.append(payload)

        if len(fact_items) < min(limit_val, 200):
            existing_keys = {
                (
                    str(item.get("slug") or "").strip(),
                    _normalize_date_key(str(item.get("event_date") or "")),
                )
                for item in fact_items
                if isinstance(item, dict)
            }
            placeholders = _discovery_placeholder_payloads(
                conn,
                run_date_key,
                upcoming_days=upcoming_days_val,
                exclude_keys=existing_keys,
                limit=max(0, min(limit_val, 200) - len(fact_items)),
            )
            if placeholders:
                fact_items.extend(placeholders)
                facts_source = "event_fact_latest_with_upcoming_and_discovery"
                if fact_total is not None:
                    fact_total = max(int(fact_total or 0), len(fact_items))

        live_items = _compose_live_snapshot_items_for_ui(
            conn,
            run_date_key,
            min(limit_val, 200),
            platt,
            fact_as_of_by_key,
        )
        for payload in live_items or []:
            _slim_fact_payload_for_ui(payload)
            _attach_first_prediction_hit_rates(payload, first_prediction_stats)
        if live_items:
            facts_source = "ui_snapshot_live_compose"
            by_key: Dict[Tuple[str, str], Dict[str, Any]] = {}
            order: List[Tuple[str, str]] = []
            for payload in fact_items:
                key = (
                    str(payload.get("slug") or "").strip(),
                    _normalize_date_key(str(payload.get("event_date") or "")),
                )
                if not key[0] or not key[1]:
                    continue
                if key not in by_key:
                    order.append(key)
                by_key[key] = payload
            for payload in live_items:
                key = (
                    str(payload.get("slug") or "").strip(),
                    _normalize_date_key(str(payload.get("event_date") or "")),
                )
                if not key[0] or not key[1]:
                    continue
                existing_payload = by_key.get(key)
                if (
                    _ui_snapshot_payload_has_final_settlement_lock(existing_payload)
                    and not _ui_snapshot_payload_has_final_settlement_lock(payload)
                ):
                    continue
                if isinstance(existing_payload, Mapping):
                    for audit_key in ("forecast_weak_attribution", "probability_audit"):
                        audit_value = existing_payload.get(audit_key)
                        if audit_value not in (None, "", [], {}) and payload.get(audit_key) in (None, "", [], {}):
                            payload[audit_key] = copy.deepcopy(audit_value)
                    existing_sections = existing_payload.get("ui_sections")
                    payload_sections = payload.get("ui_sections")
                    if isinstance(existing_sections, Mapping) and isinstance(existing_sections.get("probability_audit"), Mapping):
                        merged_sections = dict(payload_sections) if isinstance(payload_sections, Mapping) else {}
                        merged_sections["probability_audit"] = copy.deepcopy(existing_sections["probability_audit"])
                        payload["ui_sections"] = merged_sections
                if key not in by_key:
                    order.append(key)
                by_key[key] = payload
            fact_items = [by_key[key] for key in order if key in by_key]
            fact_items.sort(
                key=lambda item: str(item.get("fact_as_of") or item.get("market_updated_at") or ""),
                reverse=True,
            )
            fact_items = fact_items[: min(limit_val, 200)]
            if fact_total is not None:
                fact_total = max(int(fact_total or 0), len(fact_items))

        model_update_payload = _safe_model_update_stats(limit=120)
        basket_strategy_ssot = _basket_strategy_ui_ssot(
            conn,
            items=fact_items,
            limit=limit_val,
        )

        payload = {
            "ok": True,
            "as_of": now_text(),
            "run_date": run_date_key,
            "ui_html_mtime": html_mtime(),
            "auto_trade_env": diag,
            "positions": {
                "trading_open_count": trading_open,
                "redeemable_open_count": redeemable_open,
                "closed_nonredeemable_count": closed_nonredeemable,
                "closed_redeemable_count": closed_redeemable,
                "truth_source": position_truth_source,
                "sync_at": str(pos_updated or ""),
                "sync_error": str(pos_err or ""),
            },
            "fills": {
                "filled_order_count_today": len(filled_orders_today),
            },
            "facts": {
                "items": fact_items,
                "total": fact_total,
                "page": 1,
                "page_size": min(limit_val, 200),
                "source": facts_source,
            },
            "first_prediction_hit_rates": first_prediction_stats,
            "model_update_stats": model_update_payload,
            "modelUpdateStats": model_update_payload,
            "q_calibration_health": load_q_calibration_health(conn, days=30),
            "reject_ledger": _compact_reject_ledger_report(),
            "path_probability_follow": _path_probability_follow_status_payload(
                run_meta=run_meta,
                job_counts=job_counts,
                jobs_updated_at=jobs_updated_at,
                entry_counts=entry_counts,
                reason_stats=reason_stats,
                entry_rows=entry_rows,
                limit=limit_val,
            ),
            "basket_strategy_ssot": basket_strategy_ssot,
            "reported_trajectory_no": _reported_trajectory_no_ui_ssot(conn, limit=limit_val),
        }
        # Keep the full snapshot and summary endpoint on the same direction
        # SSOT surface.  Previously only the summary trim path attached D1,
        # so the dashboard's target-day direction card silently rendered missing.
        _attach_d1_physical_evidence_overview(payload)
        d1 = payload.get("d1_physical_evidence_overview") if isinstance(payload.get("d1_physical_evidence_overview"), Mapping) else {}
        signal = d1.get("physical_signal") if isinstance(d1.get("physical_signal"), Mapping) else {}
        basket_items = basket_strategy_ssot.get("items") if isinstance(basket_strategy_ssot, Mapping) else []
        primary_item = fact_items[0] if fact_items else {}
        primary_key = (str(primary_item.get("slug") or ""), _normalize_date_key(str(primary_item.get("event_date") or "")))
        basket_item = next(
            (row for row in basket_items if isinstance(row, Mapping) and (str(row.get("slug") or ""), _normalize_date_key(str(row.get("event_date") or ""))) == primary_key),
            None,
        )
        basket_value = basket_item.get("basket") if isinstance(basket_item, Mapping) and isinstance(basket_item.get("basket"), Mapping) else {}
        raw_direction = str(basket_value.get("direction") or "").strip().upper()
        primary_strategy = _ui_snapshot_primary_city_strategy(conn, primary_item)
        strategy_direction = primary_strategy.get("direction_bias") if isinstance(primary_strategy.get("direction_bias"), Mapping) else {}
        strategy_basket = primary_strategy.get("basket") if isinstance(primary_strategy.get("basket"), Mapping) else {}
        if isinstance(primary_item, dict) and primary_strategy.get("station_id"):
            primary_item["official_amsc_taf_snapshot"] = _china_board_taf_snapshot(
                conn,
                station_id=str(primary_strategy.get("station_id") or ""),
                event_date=str(primary_item.get("event_date") or ""),
                now=datetime.now(timezone.utc),
            )
        gate_state = str(strategy_direction.get("gate_state") or "").strip().upper()
        if gate_state in {"UP", "DOWN"}:
            raw_direction = gate_state
        regime_labels = [str(value).strip() for value in (strategy_direction.get("labels") or []) if str(value).strip()]
        numeric_score_available = isinstance(strategy_direction.get("vector_up_mass"), (int, float)) and isinstance(strategy_direction.get("vector_down_mass"), (int, float))
        payload["target_direction_bias"] = {
            "schema": "target_direction_bias_ui_v1",
            "available": raw_direction in {"UP", "DOWN"},
            "direction": raw_direction if raw_direction in {"UP", "DOWN"} else "",
            "label": "偏上 ↑" if raw_direction == "UP" else "偏下 ↓" if raw_direction == "DOWN" else "未物化",
            "source": "city_strategy.direction_bias.regime_gate" if gate_state in {"UP", "DOWN"} else ("basket.direction_bias" if raw_direction else "d1_physical_evidence_overview"),
            "target_event_date": str(primary_item.get("event_date") or ""),
            "net_score": strategy_direction.get("vector_up_mass") - strategy_direction.get("vector_down_mass") if numeric_score_available else None,
            "score_available": numeric_score_available,
            "regime_state": gate_state,
            "regime_labels": regime_labels,
            "reason": (
                f"目标日 regime 闸门 · {', '.join(regime_labels[:2]) or '已物化'} · 仅作方向一致性闸门"
                if gate_state in {"UP", "DOWN"}
                else "目标日 regime 闸门未形成一致方向"
            ),
            "updated_at": str(strategy_direction.get("updated_at") or d1.get("fact_as_of") or payload.get("snapshot_generated_at") or ""),
        }
        payload["basket_precheck"] = {
            "state": str(strategy_basket.get("precheck") or "not_run"),
            "reason": str(strategy_basket.get("precheck_reason") or ""),
            "next_action": str(strategy_basket.get("next_action") or ""),
            "source": str(strategy_basket.get("source") or "archive.db.basket_strategy_cycles"),
            "event_date": str(primary_item.get("event_date") or ""),
            "slug": str(primary_item.get("slug") or ""),
        }
        return payload

    def _build_payload() -> Dict[str, Any]:
        with open_db_ro_snapshot(timeout_sec=0.6, busy_timeout_ms=600) as conn:
            return _compute(conn)

    def _background_rebuild() -> None:
        rebuild_error = ""
        try:
            _ui_snapshot_cache_store(cache_key, _build_payload())
        except Exception as exc:
            rebuild_error = f"{type(exc).__name__}:{exc}"
        finally:
            _ui_snapshot_rebuild_done(cache_key, error=rebuild_error)

    if force_rebuild:
        forced_started_at = now_text()
        forced_started_monotonic = time.monotonic()
        payload = _build_payload()
        forced_duration_ms = max(0.0, (time.monotonic() - forced_started_monotonic) * 1000.0)
        payload["cache_forced_rebuild"] = True
        payload["cache_forced_rebuild_duration_ms"] = forced_duration_ms
        _ui_snapshot_record_rebuild_last(
            cache_key,
            started_at=forced_started_at,
            duration_ms=forced_duration_ms,
            forced=True,
        )
        _ui_snapshot_cache_store(cache_key, payload)
        _attach_ui_snapshot_rebuild_status(payload, cache_key)
        status = payload.get("cache_rebuild_status")
        if isinstance(status, dict):
            status["stage"] = "forced_rebuild_completed"
            status["duration_ms"] = forced_duration_ms
        _attach_ui_snapshot_phase0_contract(payload, cache_key=cache_key)
        return payload

    cache_dirty_sync_rebuild = (
        cache_dirty
        and UI_SNAPSHOT_DIRTY_SYNC_REBUILD
        and not _ui_snapshot_dirty_stamp_in_grace()
    )
    if UI_SNAPSHOT_STALE_WHILE_REVALIDATE and cached and not cache_dirty_sync_rebuild:
        if _ui_snapshot_rebuild_start(cache_key):
            threading.Thread(
                target=_background_rebuild,
                name=f"ui_snapshot_rebuild:{cache_key}",
                daemon=True,
            ).start()
            return _ui_snapshot_cached_payload(cached, stale=True, rebuild_started=True, cache_key=cache_key)
        return _ui_snapshot_cached_payload(cached, stale=True, rebuild_in_flight=True, cache_key=cache_key)

    if UI_SNAPSHOT_STALE_WHILE_REVALIDATE and not cached:
        rebuild_started = False
        if _ui_snapshot_rebuild_start(cache_key):
            rebuild_started = True
            threading.Thread(
                target=_background_rebuild,
                name=f"ui_snapshot_cold_rebuild:{cache_key}",
                daemon=True,
            ).start()
        payload = _ui_snapshot_busy_payload(
            run_date_key=run_date_key,
            limit_val=limit_val,
            summary_mode=False,
            cache_key=cache_key,
        )
        payload["cache_rebuild_started"] = rebuild_started
        payload["cache_rebuild_in_flight"] = True
        payload["synchronous_rebuild_allowed"] = False
        return payload

    if UI_SNAPSHOT_STALE_WHILE_REVALIDATE and _ui_snapshot_rebuild_active(cache_key):
        return _ui_snapshot_busy_payload(
            run_date_key=run_date_key,
            limit_val=limit_val,
            summary_mode=False,
            cache_key=cache_key,
        )

    rebuild_owner = _ui_snapshot_rebuild_start(cache_key)
    if UI_SNAPSHOT_STALE_WHILE_REVALIDATE and not rebuild_owner:
        if cached and not cache_dirty:
            return _ui_snapshot_cached_payload(cached, stale=True, rebuild_in_flight=True, cache_key=cache_key)
        return _ui_snapshot_busy_payload(
            run_date_key=run_date_key,
            limit_val=limit_val,
            summary_mode=False,
            cache_key=cache_key,
        )
    try:
        payload = _build_payload()
    finally:
        if rebuild_owner:
            _ui_snapshot_rebuild_done(cache_key)

    _ui_snapshot_cache_store(cache_key, payload)
    _attach_ui_snapshot_rebuild_status(payload, cache_key)
    _attach_ui_snapshot_phase0_contract(payload, cache_key=cache_key)
    return payload


def ui_snapshot_summary(
    run_date: str = "",
    limit: int = 24,
    *,
    force_rebuild: bool = False,
    city_filter: str = "",
) -> Dict[str, Any]:
    run_date_key = _normalize_date_key(run_date)
    city_filter_key = _normalize_ui_snapshot_city_filter(city_filter)
    explicit_run_date_requested = bool(run_date_key)
    if not run_date_key:
        run_date_key = _ui_snapshot_summary_latest_run_date_cached()
    if not run_date_key:
        return {"ok": False, "error": "no_run_date", "summary_mode": True}
    if not DB_PATH.exists():
        return {"ok": False, "error": "db_missing", "summary_mode": True}

    try:
        limit_val = int(limit or 0)
    except (TypeError, ValueError):
        limit_val = 24
    limit_val = max(1, min(limit_val, 80))
    requested_limit_val = limit_val
    cache_limit_val = _ui_snapshot_summary_cache_limit(requested_limit_val)
    limit_val = cache_limit_val

    cache_key = (
        f"summary:{run_date_key}:{limit_val}:{city_filter_key}"
        if city_filter_key
        else f"summary:{run_date_key}:{limit_val}"
    )

    def _trim_summary_payload(payload: Dict[str, Any]) -> Dict[str, Any]:
        trimmed = _trim_ui_snapshot_summary_payload(
            payload,
            requested_limit_val,
            city_filter=city_filter_key,
        )
        _attach_ui_snapshot_phase0_contract(trimmed, cache_key=cache_key)
        return trimmed

    now_ts = time.time()
    cached = _ui_snapshot_cache_entry(cache_key)
    cache_dirty = _ui_snapshot_cache_is_dirty(cached)
    cached_has_display_items = _ui_snapshot_summary_cache_entry_has_display_items(
        cached,
        city_filter=city_filter_key,
    )
    if (
        not force_rebuild
        and cached
        and cached_has_display_items
        and not cache_dirty
        and (now_ts - float(cached[0])) <= float(UI_SNAPSHOT_CACHE_SEC)
    ):
        return _trim_summary_payload(
            _ui_snapshot_cached_payload(cached, stale=False, cache_key=cache_key),
        )

    materialize_state = _facts_materialize_lock_state()
    if not force_rebuild and bool(materialize_state.get("active")):
        if cached and cached_has_display_items:
            payload = _trim_summary_payload(
                _ui_snapshot_cached_payload(
                    cached,
                    stale=True,
                    stale_reason="facts_materialize_active",
                    cache_key=cache_key,
                ),
            )
            payload["cache_rebuild_skipped_reason"] = "facts_materialize_active"
            return payload
        fallback_payload = _ui_snapshot_summary_metadata_fallback_payload(
            run_date_key=run_date_key,
            requested_limit_val=requested_limit_val,
            limit_val=limit_val,
            cache_key=cache_key,
            city_filter=city_filter_key,
        )
        if fallback_payload:
            fallback_payload["cache_rebuild_skipped_reason"] = "facts_materialize_active"
            return _trim_summary_payload(fallback_payload)
        payload = _ui_snapshot_busy_payload(
            run_date_key=run_date_key,
            limit_val=requested_limit_val,
            summary_mode=True,
            cache_key=cache_key,
        )
        payload["cache_rebuild_skipped_reason"] = "facts_materialize_active"
        return _trim_summary_payload(payload)

    def _empty_run_meta() -> Dict[str, Any]:
        return {
            "id": 0,
            "run_date": run_date_key,
            "started_at": "",
            "ended_at": "",
            "ok": 0,
            "error": "",
            "processed": 0,
            "skipped": 0,
            "created_at": "",
        }

    def _compute(conn: sqlite3.Connection) -> Dict[str, Any]:
        conn.row_factory = sqlite3.Row
        cur = conn.cursor()
        run_meta = _empty_run_meta()
        try:
            cur.execute(
                """
                SELECT id, run_date, started_at, ended_at, ok, error, processed, skipped, created_at
                FROM auto_trade_runs
                WHERE run_date = ?
                ORDER BY datetime(started_at) DESC, id DESC
                LIMIT 1
                """,
                (run_date_key,),
            )
            run_row = cur.fetchone()
            if run_row:
                run_meta = {
                    "id": int(run_row["id"] or 0),
                    "run_date": str(run_row["run_date"] or run_date_key),
                    "started_at": str(run_row["started_at"] or ""),
                    "ended_at": str(run_row["ended_at"] or ""),
                    "ok": int(run_row["ok"] or 0),
                    "error": str(run_row["error"] or ""),
                    "processed": int(run_row["processed"] or 0),
                    "skipped": int(run_row["skipped"] or 0),
                    "created_at": str(run_row["created_at"] or ""),
                }
        except sqlite3.OperationalError:
            pass

        job_counts: Dict[str, int] = {}
        jobs_updated_at = ""
        try:
            cur.execute(
                """
                SELECT state, COUNT(*) AS n, MAX(updated_at) AS updated_at_max
                FROM auto_trade_jobs
                WHERE run_date = ?
                GROUP BY state
                """,
                (run_date_key,),
            )
            for row in cur.fetchall():
                state = str(row["state"] or "")
                if state:
                    job_counts[state] = int(row["n"] or 0)
                updated_at = str(row["updated_at_max"] or "")
                if updated_at and updated_at > jobs_updated_at:
                    jobs_updated_at = updated_at
        except sqlite3.OperationalError:
            pass

        fact_items: List[Dict[str, Any]] = []
        fact_total: Optional[int] = None
        facts_source = "event_fact_latest_summary_with_upcoming"
        upcoming_days_val = _ui_upcoming_days()
        use_summary_cache_rows = False
        try:
            query_limit_val = 200 if city_filter_key else limit_val
            summary_cache_rows = select_event_fact_summary_cache_rows_paged(
                conn,
                run_date_key,
                1,
                query_limit_val,
                include_upcoming=True,
                upcoming_days=upcoming_days_val,
            )
            use_summary_cache_rows = bool(summary_cache_rows) and all(
                _event_fact_summary_cache_json_current(str(row["summary_json"] or ""))
                for row in summary_cache_rows
            )
            if use_summary_cache_rows:
                fact_rows = summary_cache_rows
                facts_source = "event_fact_summary_cache_with_upcoming"
            else:
                fact_rows = select_event_fact_rows_paged(
                    conn,
                    run_date_key,
                    1,
                    query_limit_val,
                    include_upcoming=True,
                    upcoming_days=upcoming_days_val,
                )
            if city_filter_key:
                fact_rows = [
                    row
                    for row in fact_rows
                    if _ui_snapshot_summary_row_matches_city_filter(row, city_filter_key)
                ][:limit_val]
                fact_total = len(fact_rows)
            elif len(fact_rows) < limit_val:
                existing = {
                    (str(row["slug"] or ""), _normalize_date_key(str(row["event_date"] or "")))
                    for row in fact_rows or []
                }
                fact_total = len(fact_rows) + _count_discovery_placeholder_events(
                    conn,
                    run_date_key,
                    upcoming_days=upcoming_days_val,
                    exclude_keys=existing,
                )
            else:
                fact_total = (
                    len(fact_rows)
                    if use_summary_cache_rows
                    else count_event_fact_rows(
                        conn,
                        run_date_key,
                        include_upcoming=True,
                        upcoming_days=upcoming_days_val,
                    )
                )
            if (
                use_summary_cache_rows
                and UI_SNAPSHOT_SUMMARY_FAST
                and not UI_SNAPSHOT_SUMMARY_LIVE_MARKET_HYDRATE
            ):
                market_tick_latest_map = {}
            else:
                market_tick_latest_map = query_market_tick_latest_for_keys(
                    conn,
                    [(row["slug"], row["event_date"]) for row in fact_rows],
                )
        except sqlite3.OperationalError:
            fact_rows = []
            market_tick_latest_map = {}
            fact_total = 0

        first_prediction_stats = _safe_first_prediction_hit_rates_snapshot_only(conn)
        if UI_SNAPSHOT_SUMMARY_FAST:
            try:
                trade_map_for_plan = query_edge_trades(conn)
            except Exception:
                trade_map_for_plan = {}
            fills_map_for_plan = {}
            auto_orders_map_for_plan = {}
        else:
            try:
                trade_map_for_plan = query_edge_trades(conn)
                fills_map_for_plan = query_trade_fills(conn)
                auto_orders_map_for_plan = query_auto_orders(conn)
            except Exception:
                trade_map_for_plan = {}
                fills_map_for_plan = {}
                auto_orders_map_for_plan = {}

        intraday_summary_cache: Dict[str, Optional[Dict[str, Any]]] = {}
        for row in fact_rows:
            if use_summary_cache_rows:
                payload = safe_json_loads(str(row["summary_json"] or ""))
            else:
                try:
                    payload = json.loads(row["fact_json"])
                except Exception:
                    continue
            if not isinstance(payload, dict):
                continue
            if city_filter_key and not _ui_snapshot_summary_item_matches_city_filter(
                {
                    **payload,
                    "slug": payload.get("slug") or row["slug"],
                    "event_date": payload.get("event_date") or row["event_date"],
                },
                city_filter_key,
            ):
                continue
            _slim_fact_payload_for_ui(payload)
            _merge_fill_fact_row_meta(payload, row)
            if use_summary_cache_rows:
                try:
                    _merge_fill_fast_observation_fields_from_latest_fact(
                        conn,
                        payload,
                        str(payload.get("slug") or row["slug"] or ""),
                        _normalize_date_key(str(payload.get("event_date") or row["event_date"] or "")),
                    )
                except Exception:
                    pass
            event_date_key = _normalize_date_key(str(payload.get("event_date") or row["event_date"] or ""))
            distribution = normalize_distribution_rows(payload.get("distribution") or payload.get("rows") or [])
            if distribution:
                payload["distribution"] = distribution
                _sanitize_physical_d0_explanation_in_distribution(distribution)
                if (
                    not (
                        UI_SNAPSHOT_SUMMARY_FAST
                        and _ui_snapshot_distribution_has_model_probability_maps(distribution)
                    )
                    or _is_chengdu_zuuu_fact_payload(str(payload.get("slug") or row["slug"] or ""), payload)
                ):
                    _attach_model_raw_top_history_for_ui_snapshot(conn, payload, row)
                _attach_model_member_cache_snapshot_for_ui_snapshot(conn, payload, row)
                _attach_model_bucket_rule_comparison_for_ui_snapshot(conn, payload, row)
                run_date_key_for_payload = _normalize_date_key(str(payload.get("run_date") or ""))
                if UI_SNAPSHOT_SUMMARY_FAST and not UI_SNAPSHOT_SUMMARY_LIVE_MARKET_HYDRATE:
                    _prepare_summary_distribution_market_fields_in_place(
                        distribution,
                        event_date_key=event_date_key,
                        run_date_key=run_date_key_for_payload,
                    )
                else:
                    _hydrate_distribution_market_fields_in_place(
                        conn,
                        distribution,
                        str(payload.get("slug") or ""),
                        event_date_key,
                        run_date_key_for_payload,
                    )
                _apply_display_probability_fields_in_place(distribution)
            # State-space facts intentionally have no temperature bucket
            # distribution.  Model peak cards are still display-only data and
            # must be hydrated on that path as well.
            _attach_model_member_cache_snapshot_for_ui_snapshot(conn, payload, row)
            if (
                not (use_summary_cache_rows and UI_SNAPSHOT_SUMMARY_FAST)
                or UI_SNAPSHOT_SUMMARY_LIVE_MARKET_HYDRATE
            ):
                _hydrate_fact_market_updated_at(payload, market_tick_latest_map)
            if distribution:
                _hydrate_fact_market_top_fields_from_distribution(payload, distribution)
            else:
                _hydrate_fact_market_top_label(payload)
                _hydrate_fact_single_temperature_top(payload)
            if not UI_SNAPSHOT_SUMMARY_FAST:
                _attach_market_flow_context(conn, payload, row)
            _hydrate_fact_precipitation_evidence_coverage(payload)
            _attach_first_prediction_hit_rates(payload, first_prediction_stats)
            _attach_chengdu_intraday_summary_fields_for_ui_snapshot(
                payload,
                row,
                payload,
                intraday_summary_cache,
                run_date_key,
            )
            if distribution and UI_SNAPSHOT_SUMMARY_LIVE_MARKET_HYDRATE:
                _hydrate_distribution_market_fields_in_place(
                    conn,
                    distribution,
                    str(payload.get("slug") or row["slug"] or ""),
                    event_date_key,
                    _normalize_date_key(str(payload.get("run_date") or "")),
                )
                # Chengdu intraday SSOT alignment may replace payload["distribution"]
                # with a fact-cache copy. Keep the returned rows on the live-hydrated
                # distribution object so UI quote fields do not fall back to stale cache.
                payload["distribution"] = distribution
                _apply_display_probability_fields_in_place(distribution)
                _hydrate_fact_market_updated_at(payload, market_tick_latest_map)
                _hydrate_fact_market_top_fields_from_distribution(payload, distribution)
            _align_snapshot_posterior_derived_fields(payload)
            if (not UI_SNAPSHOT_SUMMARY_FAST) or event_date_key == run_date_key:
                _attach_summary_bucket_series_history(conn, payload, row)
            _attach_temperature_trajectory_timeline_for_ui_snapshot(conn, payload, row)
            _attach_target_realization_capital_plan(
                payload,
                trade_map=trade_map_for_plan,
                fills_map=fills_map_for_plan,
                auto_orders_map=auto_orders_map_for_plan,
            )
            _attach_target_switch_context(payload)
            fact_items.append(
                _slim_fact_payload_for_ui_snapshot_summary(
                    payload,
                    include_physical_detail=UI_SNAPSHOT_SUMMARY_PHYSICAL_DETAIL,
                )
            )

        if len(fact_items) < limit_val:
            existing_keys = {
                (
                    str(item.get("slug") or "").strip(),
                    _normalize_date_key(str(item.get("event_date") or "")),
                )
                for item in fact_items
                if isinstance(item, dict)
            }
            placeholders = _discovery_placeholder_payloads(
                conn,
                run_date_key,
                upcoming_days=upcoming_days_val,
                exclude_keys=existing_keys,
                limit=(200 if city_filter_key else max(0, limit_val - len(fact_items))),
            )
            if city_filter_key:
                remaining = max(0, limit_val - len(fact_items))
                placeholders = [
                    payload
                    for payload in placeholders
                    if _ui_snapshot_summary_item_matches_city_filter(payload, city_filter_key)
                ][:remaining]
            if placeholders:
                fact_items.extend(
                    _slim_fact_payload_for_ui_snapshot_summary(
                        payload,
                        include_physical_detail=UI_SNAPSHOT_SUMMARY_PHYSICAL_DETAIL,
                    )
                    for payload in placeholders
                )
                facts_source = (
                    "event_fact_summary_cache_with_upcoming_and_discovery"
                    if use_summary_cache_rows
                    else "event_fact_latest_summary_with_upcoming_and_discovery"
                )
                if fact_total is not None:
                    fact_total = max(int(fact_total or 0), len(fact_items))

        if not fact_items:
            try:
                fallback_items = _event_fact_summary_cache_rebuild_fallback_items(
                    conn,
                    run_date_key,
                    limit_val=limit_val,
                    upcoming_days=upcoming_days_val,
                )
            except Exception:
                fallback_items = []
            if fallback_items:
                if city_filter_key:
                    fallback_items = [
                        item
                        for item in fallback_items
                        if _ui_snapshot_summary_item_matches_city_filter(item, city_filter_key)
                    ]
                fact_items = fallback_items[:limit_val]
                fact_total = max(int(fact_total or 0), len(fact_items))
                facts_source = "event_fact_summary_cache_empty_result_guard"
                use_summary_cache_rows = True

        if city_filter_key:
            fact_total = len(fact_items)

        model_update_payload = _safe_model_update_stats(limit=48)
        decision_rows: List[Dict[str, Any]] = []
        decision_counts = {"total": 0, "blocked": 0, "will_order": 0}
        decision_reason_counts: Dict[str, int] = {}
        try:
            cur.execute(
                """
                SELECT slug,event_date,title,outcome,side,action,decided_state,will_order,
                       reason_codes_json,reasons_json,created_at
                FROM auto_trade_decisions
                WHERE run_date = ?
                ORDER BY id DESC
                LIMIT ?
                """,
                (run_date_key, limit_val),
            )
            for row in cur.fetchall():
                try:
                    reason_codes = json.loads(str(row["reason_codes_json"] or "[]"))
                except (TypeError, ValueError):
                    reason_codes = []
                try:
                    reasons = json.loads(str(row["reasons_json"] or "[]"))
                except (TypeError, ValueError):
                    reasons = []
                reason_codes = reason_codes if isinstance(reason_codes, list) else []
                reasons = reasons if isinstance(reasons, list) else []
                decided_state = str(row["decided_state"] or "")
                will_order = int(row["will_order"] or 0)
                decision_counts["total"] += 1
                if decided_state == "blocked" or (decided_state and not will_order):
                    decision_counts["blocked"] += 1
                if will_order:
                    decision_counts["will_order"] += 1
                for code in reason_codes[:1]:
                    code_text = str(code or "").strip()
                    if code_text:
                        decision_reason_counts[code_text] = decision_reason_counts.get(code_text, 0) + 1
                decision_rows.append(
                    {
                        "slug": str(row["slug"] or ""),
                        "event_date": date_only(str(row["event_date"] or "")),
                        "title": str(row["title"] or ""),
                        "outcome": str(row["outcome"] or ""),
                        "side": str(row["side"] or "").upper(),
                        "action": str(row["action"] or ""),
                        "decided_state": decided_state,
                        "will_order": will_order,
                        "reason_codes": [str(code) for code in reason_codes],
                        "reasons": [
                            str(
                                reason.get("reason_code")
                                or reason.get("message")
                                or reason.get("reason_family")
                                or ""
                            )
                            if isinstance(reason, Mapping)
                            else str(reason)
                            for reason in reasons
                        ],
                        "created_at": str(row["created_at"] or ""),
                    }
                )
        except sqlite3.OperationalError:
            decision_rows = []
            decision_counts = {"total": 0, "blocked": 0, "will_order": 0}
            decision_reason_counts = {}
        blocked_total = max(1, int(decision_counts["blocked"] or 0))
        decision_reason_stats = [
            {"code": code, "count": count, "share": float(count) / float(blocked_total)}
            for code, count in sorted(
                decision_reason_counts.items(),
                key=lambda item: (-item[1], item[0]),
            )
        ]
        basket_strategy_ssot = _basket_strategy_ui_ssot(
            conn,
            items=fact_items,
            limit=limit_val,
        )

        payload = {
            "ok": True,
            "summary_mode": True,
            "summary_fast_mode": bool(UI_SNAPSHOT_SUMMARY_FAST),
            "summary_cache_limit": limit_val,
            "as_of": now_text(),
            "run_date": run_date_key,
            "ui_html_mtime": html_mtime(),
            "auto_trade_env": auto_trade_env_diagnostics(),
            "positions": {
                "trading_open_count": 0,
                "redeemable_open_count": 0,
                "closed_nonredeemable_count": 0,
                "closed_redeemable_count": 0,
                "truth_source": "ui_snapshot_summary_skipped",
                "sync_at": "",
                "sync_error": "",
            },
            "fills": {"filled_order_count_today": 0},
            "facts": {
                "items": fact_items,
                "total": fact_total,
                "page": 1,
                "page_size": limit_val,
                "source": facts_source,
            },
            "first_prediction_hit_rates": first_prediction_stats,
            "model_update_stats": model_update_payload,
            "modelUpdateStats": model_update_payload,
            "q_calibration_health": {"ok": False, "skipped": "ui_snapshot_summary"},
            "reject_ledger": {"ok": False, "skipped": "ui_snapshot_summary"},
            "path_probability_follow": _path_probability_follow_status_payload(
                run_meta=run_meta,
                job_counts=job_counts,
                jobs_updated_at=jobs_updated_at,
                entry_counts=decision_counts,
                reason_stats=decision_reason_stats,
                entry_rows=decision_rows,
                limit=limit_val,
            ),
            "basket_strategy_ssot": basket_strategy_ssot,
            "reported_trajectory_no": _reported_trajectory_no_ui_ssot(conn, limit=limit_val),
        }
        _attach_d1_physical_evidence_overview(payload)
        d1 = payload.get("d1_physical_evidence_overview") if isinstance(payload.get("d1_physical_evidence_overview"), Mapping) else {}
        signal = d1.get("physical_signal") if isinstance(d1.get("physical_signal"), Mapping) else {}
        primary_item = fact_items[0] if fact_items else {}
        primary_strategy = _ui_snapshot_primary_city_strategy(conn, primary_item)
        strategy_direction = primary_strategy.get("direction_bias") if isinstance(primary_strategy.get("direction_bias"), Mapping) else {}
        strategy_basket = primary_strategy.get("basket") if isinstance(primary_strategy.get("basket"), Mapping) else {}
        if isinstance(primary_item, dict) and primary_strategy.get("station_id"):
            primary_item["official_amsc_taf_snapshot"] = _china_board_taf_snapshot(
                conn,
                station_id=str(primary_strategy.get("station_id") or ""),
                event_date=str(primary_item.get("event_date") or ""),
                now=datetime.now(timezone.utc),
            )
        gate_state = str(strategy_direction.get("gate_state") or "").strip().upper()
        regime_labels = [str(value).strip() for value in (strategy_direction.get("labels") or []) if str(value).strip()]
        numeric_score_available = isinstance(strategy_direction.get("vector_up_mass"), (int, float)) and isinstance(strategy_direction.get("vector_down_mass"), (int, float))
        payload["target_direction_bias"] = {
            "schema": "target_direction_bias_ui_v1",
            "available": gate_state in {"UP", "DOWN"},
            "direction": gate_state if gate_state in {"UP", "DOWN"} else "",
            "label": "偏上 ↑" if gate_state == "UP" else "偏下 ↓" if gate_state == "DOWN" else "未物化",
            "source": "city_strategy.direction_bias.regime_gate" if gate_state in {"UP", "DOWN"} else "d1_physical_evidence_overview",
            "target_event_date": str(primary_item.get("event_date") or ""),
            "net_score": strategy_direction.get("vector_up_mass") - strategy_direction.get("vector_down_mass") if numeric_score_available else None,
            "score_available": numeric_score_available,
            "regime_state": gate_state,
            "regime_labels": regime_labels,
            "reason": (
                f"目标日 regime 闸门 · {', '.join(regime_labels[:2]) or '已物化'} · 仅作方向一致性闸门"
                if gate_state in {"UP", "DOWN"}
                else "目标日 regime 闸门未形成一致方向"
            ),
            "updated_at": str(strategy_direction.get("updated_at") or d1.get("fact_as_of") or payload.get("as_of") or ""),
        }
        payload["basket_precheck"] = {
            "state": str(strategy_basket.get("precheck") or "not_run"),
            "reason": str(strategy_basket.get("precheck_reason") or ""),
            "next_action": str(strategy_basket.get("next_action") or ""),
            "source": str(strategy_basket.get("source") or "archive.db.basket_strategy_cycles"),
            "event_date": str(primary_item.get("event_date") or ""),
            "slug": str(primary_item.get("slug") or ""),
        }
        return payload

    def _build_payload() -> Dict[str, Any]:
        with open_db_ro_fast(
            timeout_sec=UI_SNAPSHOT_SUMMARY_REBUILD_DB_TIMEOUT_SEC,
            busy_timeout_ms=UI_SNAPSHOT_SUMMARY_REBUILD_DB_BUSY_TIMEOUT_MS,
        ) as conn:
            return _compute(conn)

    def _background_rebuild() -> None:
        rebuild_error = ""
        try:
            _ui_snapshot_cache_store(cache_key, _build_payload())
        except Exception as exc:
            rebuild_error = f"{type(exc).__name__}:{exc}"
        finally:
            _ui_snapshot_rebuild_done(cache_key, error=rebuild_error)

    if force_rebuild:
        forced_started_at = now_text()
        forced_started_monotonic = time.monotonic()
        payload = _build_payload()
        forced_duration_ms = max(0.0, (time.monotonic() - forced_started_monotonic) * 1000.0)
        payload["cache_forced_rebuild"] = True
        payload["cache_forced_rebuild_duration_ms"] = forced_duration_ms
        _ui_snapshot_record_rebuild_last(
            cache_key,
            started_at=forced_started_at,
            duration_ms=forced_duration_ms,
            forced=True,
        )
        _ui_snapshot_cache_store(cache_key, payload)
        _attach_ui_snapshot_rebuild_status(payload, cache_key)
        status = payload.get("cache_rebuild_status")
        if isinstance(status, dict):
            status["stage"] = "forced_rebuild_completed"
            status["duration_ms"] = forced_duration_ms
        return _trim_summary_payload(payload)

    cache_dirty_sync_rebuild = (
        cache_dirty
        and UI_SNAPSHOT_DIRTY_SYNC_REBUILD
        and not _ui_snapshot_dirty_stamp_in_grace()
    )
    cold_explicit_sync_rebuild = (
        explicit_run_date_requested
        and UI_SNAPSHOT_SUMMARY_SYNC_COLD_EXPLICIT_DATE
        and (not UI_SNAPSHOT_STALE_WHILE_REVALIDATE or UI_SNAPSHOT_CACHE_SEC <= 0)
        and not cached
        and not cache_dirty
    )
    if _ui_snapshot_rebuild_active(cache_key) and not cold_explicit_sync_rebuild:
        if cached and cached_has_display_items and not cache_dirty:
            return _trim_summary_payload(
                _ui_snapshot_cached_payload(cached, stale=True, rebuild_in_flight=True, cache_key=cache_key),
            )
        fallback_payload = _ui_snapshot_summary_metadata_fallback_payload(
            run_date_key=run_date_key,
            requested_limit_val=requested_limit_val,
            limit_val=limit_val,
            cache_key=cache_key,
            city_filter=city_filter_key,
        )
        if fallback_payload:
            return _trim_summary_payload(fallback_payload)
        return _trim_summary_payload(_ui_snapshot_busy_payload(
            run_date_key=run_date_key,
            limit_val=requested_limit_val,
            summary_mode=True,
            cache_key=cache_key,
        ))
    if (
        UI_SNAPSHOT_STALE_WHILE_REVALIDATE
        and cached
        and cached_has_display_items
        and not cache_dirty
        and not cache_dirty_sync_rebuild
    ):
        revalidate_allowed = _ui_snapshot_revalidate_allowed(
            cache_key,
            UI_SNAPSHOT_SUMMARY_REVALIDATE_MIN_INTERVAL_SEC,
        )
        if revalidate_allowed and _ui_snapshot_rebuild_start(cache_key):
            threading.Thread(
                target=_background_rebuild,
                name=f"ui_snapshot_summary_rebuild:{cache_key}",
                daemon=True,
            ).start()
            return _trim_summary_payload(
                _ui_snapshot_cached_payload(cached, stale=True, rebuild_started=True, cache_key=cache_key),
            )
        if not revalidate_allowed:
            return _trim_summary_payload(
                _ui_snapshot_cached_payload(
                    cached,
                    stale=True,
                    stale_reason="summary_revalidate_throttled",
                    cache_key=cache_key,
                ),
            )
        return _trim_summary_payload(
            _ui_snapshot_cached_payload(cached, stale=True, rebuild_in_flight=True, cache_key=cache_key),
        )

    if (
        UI_SNAPSHOT_STALE_WHILE_REVALIDATE
        and UI_SNAPSHOT_CACHE_SEC > 0
        and not cold_explicit_sync_rebuild
    ):
        if _ui_snapshot_rebuild_start(cache_key):
            threading.Thread(
                target=_background_rebuild,
                name=f"ui_snapshot_summary_rebuild:{cache_key}",
                daemon=True,
            ).start()
        fallback_payload = _ui_snapshot_summary_metadata_fallback_payload(
            run_date_key=run_date_key,
            requested_limit_val=requested_limit_val,
            limit_val=limit_val,
            cache_key=cache_key,
            city_filter=city_filter_key,
        )
        if fallback_payload:
            return _trim_summary_payload(fallback_payload)
        return _trim_summary_payload(_ui_snapshot_busy_payload(
            run_date_key=run_date_key,
            limit_val=requested_limit_val,
            summary_mode=True,
            cache_key=cache_key,
        ))

    rebuild_owner = _ui_snapshot_rebuild_start(cache_key)
    if UI_SNAPSHOT_STALE_WHILE_REVALIDATE and not rebuild_owner:
        if cached and cached_has_display_items:
            return _trim_summary_payload(
                _ui_snapshot_cached_payload(cached, stale=True, rebuild_in_flight=True, cache_key=cache_key),
            )
        fallback_payload = _ui_snapshot_summary_metadata_fallback_payload(
            run_date_key=run_date_key,
            requested_limit_val=requested_limit_val,
            limit_val=limit_val,
            cache_key=cache_key,
            city_filter=city_filter_key,
        )
        if fallback_payload:
            return _trim_summary_payload(fallback_payload)
        return _trim_summary_payload(_ui_snapshot_busy_payload(
            run_date_key=run_date_key,
            limit_val=requested_limit_val,
            summary_mode=True,
            cache_key=cache_key,
        ))
    try:
        payload = _build_payload()
    finally:
        if rebuild_owner:
            _ui_snapshot_rebuild_done(cache_key)

    _ui_snapshot_cache_store(cache_key, payload)
    _attach_ui_snapshot_rebuild_status(payload, cache_key)
    return _trim_summary_payload(payload)


def _read_weather_events_cached() -> List[Dict[str, Any]]:
    latest_payload: Optional[Dict[str, Any]] = None
    latest_mtime = 0.0
    for path in _WEATHER_EVENTS_CACHE_FILES:
        if not path.exists():
            continue
        try:
            mtime = path.stat().st_mtime
            payload = json.loads(path.read_text(encoding="utf-8", errors="replace"))
        except Exception:
            continue
        if not isinstance(payload, dict):
            continue
        if mtime >= latest_mtime:
            latest_mtime = mtime
            latest_payload = payload
    if not isinstance(latest_payload, dict):
        return []
    events = latest_payload.get("events")
    if not isinstance(events, list):
        return []
    out: List[Dict[str, Any]] = []
    for item in events:
        if isinstance(item, dict):
            out.append(item)
    return out


def _normalize_weather_city_label(value: str) -> str:
    text = str(value or "").strip().strip("?")
    if not text:
        return ""
    text = text.replace("-", " ")
    text = re.sub(r"\s+", " ", text).strip()
    if not text:
        return ""
    alias = _WEATHER_CITY_ALIAS.get(text.lower())
    if alias:
        return alias
    words: List[str] = []
    for raw in text.split(" "):
        part = raw.strip()
        if not part:
            continue
        if part.upper() in {"NYC", "USA", "UK", "EU"}:
            words.append(part.upper())
        else:
            words.append(part[:1].upper() + part[1:].lower())
    return " ".join(words)


def _extract_city_from_weather_event(event: Dict[str, Any]) -> str:
    title = str(event.get("title") or "").strip()
    slug = str(event.get("slug") or "").strip().lower()
    city_raw = ""
    if title:
        m = _WEATHER_CITY_FROM_TITLE_RE.match(title.lower())
        if m:
            city_raw = str(m.group("city") or "")
    if (not city_raw) and slug:
        m = _WEATHER_CITY_FROM_SLUG_RE.match(slug)
        if m:
            city_raw = str(m.group("city") or "")
    return _normalize_weather_city_label(city_raw)


def _extract_event_date_from_weather_event(event: Dict[str, Any]) -> str:
    end_date = str(event.get("endDate") or "").strip()
    if len(end_date) >= 10:
        key = _normalize_date_key(end_date[:10])
        if key:
            return key
    return ""


def _is_highest_temperature_event_slug(slug: str) -> bool:
    text = str(slug or "").strip().lower()
    if not text:
        return False
    return bool(_HIGHEST_TEMPERATURE_SLUG_RE.match(text))


def _event_expired(end_time_text: str, now_utc: datetime) -> bool:
    dt = parse_iso_ts(str(end_time_text or "").strip())
    if dt is None:
        return False
    if dt.tzinfo is None:
        dt = dt.replace(tzinfo=timezone.utc)
    return dt <= now_utc


def _truthy(value: Any) -> bool:
    text = str(value or "").strip().lower()
    return text in {"1", "true", "yes", "on"}


def _normalize_city_from_fact(fact: Dict[str, Any]) -> str:
    candidates: List[Mapping[str, Any]] = [fact]
    for key in ("posterior_ssot_fact", "posterior_ssot", "ssot"):
        nested = fact.get(key)
        if isinstance(nested, Mapping):
            candidates.append(nested)
    for candidate in candidates:
        station_id = str(candidate.get("station_id") or "").strip().upper()
        if station_id and station_id in _STATION_CITY_MAP:
            return _STATION_CITY_MAP[station_id]
        city_raw = str(candidate.get("city") or "").strip()
        city_up = city_raw.upper()
        if city_up and city_up in _STATION_CITY_MAP:
            return _STATION_CITY_MAP[city_up]
        city = _normalize_weather_city_label(city_raw)
        if city:
            return city
    return _extract_city_from_weather_event(
        {
            "slug": str(fact.get("slug") or ""),
            "title": str(fact.get("title") or ""),
        }
    )


def _today_et_key() -> str:
    try:
        return datetime.now(_ET_TZ).date().isoformat()
    except Exception:
        return datetime.now().date().isoformat()


_LONDON_TEMP_MARKET_RE = re.compile(r"highest[-\s]temperature\s+in\s+london", re.IGNORECASE)
_LONDON_TEMP_SLUG_RE = re.compile(r"highest-temperature-in-london", re.IGNORECASE)
_HIGHEST_TEMP_MARKET_RE = re.compile(r"highest[-\s]temperature\s+in\s+", re.IGNORECASE)
_HIGHEST_TEMP_SLUG_RE = re.compile(r"highest-temperature-in-", re.IGNORECASE)
_LONDON_EVENT_DATE_RE = re.compile(
    r"on-(january|february|march|april|may|june|july|august|september|october|november|december)-(\d{1,2})(?:-(\d{4}))?",
    re.IGNORECASE,
)
_HIGHEST_TEMP_EVENT_KEY_RE = re.compile(
    r"highest-temperature-in-(?P<city>.+?)-on-"
    r"(?P<month>january|february|march|april|may|june|july|august|september|october|november|december)-"
    r"(?P<day>\d{1,2})(?:-(?P<year>\d{4}))?$",
    re.IGNORECASE,
)
_LONDON_MONTH_INDEX: Dict[str, int] = {
    "january": 1,
    "february": 2,
    "march": 3,
    "april": 4,
    "may": 5,
    "june": 6,
    "july": 7,
    "august": 8,
    "september": 9,
    "october": 10,
    "november": 11,
    "december": 12,
}
_LONDON_BUCKET_FROM_TITLE_RE = re.compile(
    r"\bbe(?:\s+between)?\s+(.+?)\s+on\s+"
    r"(?:january|february|march|april|may|june|july|august|september|october|november|december)\b",
    re.IGNORECASE,
)


def _canonical_london_bucket_label(value: str) -> str:
    text = str(value or "").strip().lower()
    if not text:
        return ""
    text = text.replace("between ", "")
    text = text.replace("degrees", "deg")
    text = text.replace("degree", "deg")
    text = text.replace("fahrenheit", "f")
    text = text.replace("celsius", "c")
    text = text.replace("°", "")
    return re.sub(r"[^a-z0-9]+", "", text)


def _extract_london_bucket_label(item: Dict[str, Any]) -> str:
    title = str(item.get("title") or item.get("name") or "").strip()
    if title:
        match = _LONDON_BUCKET_FROM_TITLE_RE.search(title)
        if match:
            return str(match.group(1) or "").strip().rstrip("?")
    market_slug = str(item.get("slug") or "").strip().lower()
    if not market_slug:
        return ""
    match = re.search(r"-([0-9]+c|[0-9]+f)$", market_slug)
    if match:
        token = str(match.group(1) or "").strip().lower()
        num = token[:-1]
        unit = token[-1]
        if unit == "c":
            return f"{num}\u00b0C"
        if unit == "f":
            return f"{num}\u00b0F"
    return ""


def _load_london_event_prob_lookup(event_slug: str) -> Dict[str, Any]:
    key = str(event_slug or "").strip().lower()
    if not key:
        return {"fact_as_of": "", "rows": {}}
    now = time.time()
    with _LONDON_FOLLOW_FACT_CACHE_LOCK:
        cached = _LONDON_FOLLOW_FACT_CACHE.get(key)
        if cached and (now - cached[0]) <= LONDON_FOLLOW_SIM_CACHE_SEC:
            return cached[1]
    payload: Dict[str, Any] = {"fact_as_of": "", "rows": {}}
    if not DB_PATH.exists():
        with _LONDON_FOLLOW_FACT_CACHE_LOCK:
            _LONDON_FOLLOW_FACT_CACHE[key] = (now, payload)
        return payload
    try:
        with open_db_ro_fast(timeout_sec=0.25, busy_timeout_ms=250) as conn:
            row = conn.execute(
                """
                SELECT fact_as_of, fact_json
                  FROM event_fact_history
                 WHERE slug=?
                 ORDER BY fact_as_of DESC, id DESC
                 LIMIT 1
                """,
                (key,),
            ).fetchone()
    except sqlite3.Error:
        row = None
    if row:
        fact_json = str(row["fact_json"] or "")
        fact_as_of = str(row["fact_as_of"] or "")
        distribution: List[Dict[str, Any]] = []
        try:
            fact_obj = json.loads(fact_json) if fact_json else {}
            distribution_raw = fact_obj.get("distribution") if isinstance(fact_obj, dict) else []
            if isinstance(distribution_raw, list):
                distribution = [item for item in distribution_raw if isinstance(item, dict)]
        except Exception:
            distribution = []
            fact_as_of = ""
        rows_map: Dict[str, Dict[str, Any]] = {}
        for item in distribution:
            label = str(item.get("outcome") or "").strip()
            canonical = _canonical_london_bucket_label(label)
            if not canonical:
                continue
            q_entry = to_float(item.get("q_entry"))
            if q_entry is None:
                q_entry = to_float(item.get("q_calibrated"))
            if q_entry is None:
                q_entry = to_float(item.get("q_raw"))
            rows_map[canonical] = {
                "outcome": label,
                "p_yes_true": q_entry,
                "best_ask_yes": to_float(item.get("best_ask")),
                "best_ask_no": to_float(item.get("best_ask_no")),
            }
        payload = {"fact_as_of": fact_as_of, "rows": rows_map}
    with _LONDON_FOLLOW_FACT_CACHE_LOCK:
        _LONDON_FOLLOW_FACT_CACHE[key] = (now, payload)
    return payload


def _evaluate_london_follow_edge(
    *,
    source_side: str,
    contract_outcome: str,
    source_price: float,
    p_yes_true: Optional[float],
) -> Dict[str, Any]:
    # strict mode mirrors source flow without model gating.
    if LONDON_FOLLOW_SIM_MODE == "strict" or source_side != "BUY":
        return {
            "evaluated": False,
            "pass": True,
            "reason": "strict_follow",
            "edge_value": None,
            "threshold": None,
            "cost_buffer": LONDON_FOLLOW_SIM_EDGE_COST_BUFFER,
        }
    outcome = str(contract_outcome or "").strip().capitalize()
    if outcome == "Yes" and not LONDON_FOLLOW_SIM_EDGE_APPLY_YES:
        return {
            "evaluated": False,
            "pass": True,
            "reason": "edge_yes_gate_disabled",
            "edge_value": None,
            "threshold": None,
            "cost_buffer": LONDON_FOLLOW_SIM_EDGE_COST_BUFFER,
        }
    if p_yes_true is None or not math.isfinite(float(p_yes_true)):
        return {
            "evaluated": True,
            "pass": not LONDON_FOLLOW_SIM_EDGE_REQUIRE_PROB,
            "reason": "edge_prob_missing",
            "edge_value": None,
            "threshold": None,
            "cost_buffer": LONDON_FOLLOW_SIM_EDGE_COST_BUFFER,
        }
    p_yes = float(min(1.0, max(0.0, p_yes_true)))
    cost = float(LONDON_FOLLOW_SIM_EDGE_COST_BUFFER)
    if outcome == "No":
        edge = (1.0 - p_yes) - float(source_price) - cost
        threshold = 1.0 - float(source_price) - cost
        ok = edge > 0
        reason = "edge_no_ok" if ok else "edge_no_le_0"
    else:
        edge = p_yes - float(source_price) - cost
        threshold = float(source_price) + cost
        ok = edge > 0
        reason = "edge_yes_ok" if ok else "edge_yes_le_0"
    return {
        "evaluated": True,
        "pass": ok,
        "reason": reason,
        "edge_value": edge,
        "threshold": threshold,
        "cost_buffer": cost,
    }


def _http_get_json_any(
    url: str,
    *,
    params: Optional[Dict[str, Any]] = None,
    timeout: float = 20.0,
    retries: int = 3,
) -> Any:
    full_url = url
    if params:
        full_url = f"{url}?{urlencode(params)}"
    verify = not _allow_insecure_ssl()
    last_error = ""
    for attempt in range(max(1, retries)):
        try:
            resp = requests.get(full_url, timeout=timeout, verify=verify)
            if resp.status_code == 200:
                return resp.json()
            last_error = f"http_{resp.status_code}"
        except Exception as exc:
            last_error = str(exc)
            if verify:
                try:
                    resp = requests.get(full_url, timeout=timeout, verify=False)
                    if resp.status_code == 200:
                        return resp.json()
                    last_error = f"http_{resp.status_code}"
                except Exception as fallback_exc:
                    last_error = str(fallback_exc)
        time.sleep(min(0.8 * (attempt + 1), 2.5))
    raise RuntimeError(last_error or "request_failed")


def _parse_unix_ts(raw_value: Any) -> int:
    try:
        ts_num = float(raw_value)
    except (TypeError, ValueError):
        return 0
    if not math.isfinite(ts_num) or ts_num <= 0:
        return 0
    if ts_num > 1e12:
        ts_num = ts_num / 1000.0
    return int(ts_num)


def _is_london_temperature_trade(item: Dict[str, Any]) -> bool:
    slug = str(item.get("slug") or item.get("eventSlug") or "").strip()
    title = str(item.get("title") or item.get("name") or "").strip()
    if LONDON_FOLLOW_SIM_ALL_HIGHEST_TEMP:
        if slug and _HIGHEST_TEMP_SLUG_RE.search(slug):
            return True
        text_all = f"{slug} {title}".strip()
        return bool(text_all and _HIGHEST_TEMP_MARKET_RE.search(text_all))
    if slug and _LONDON_TEMP_SLUG_RE.search(slug):
        return True
    text = f"{slug} {title}".strip()
    return bool(text and _LONDON_TEMP_MARKET_RE.search(text))


def _infer_london_event_close_utc(slug: str, trade_ts: int) -> Optional[datetime]:
    text = str(slug or "").strip().lower()
    matches = list(_LONDON_EVENT_DATE_RE.finditer(text))
    if not matches:
        return None
    m = matches[-1]
    month_name = str(m.group(1) or "").lower()
    day_raw = str(m.group(2) or "")
    year_raw = str(m.group(3) or "")
    month = _LONDON_MONTH_INDEX.get(month_name)
    if month is None:
        return None
    try:
        day = int(day_raw)
    except ValueError:
        return None
    trade_dt = datetime.fromtimestamp(max(1, trade_ts), timezone.utc)
    if year_raw:
        candidate_years = [int(year_raw)]
    else:
        candidate_years = [trade_dt.year - 1, trade_dt.year, trade_dt.year + 1]
    candidates: List[datetime] = []
    for year in candidate_years:
        try:
            # London weather markets generally end around 12:00 UTC in this dataset.
            candidates.append(datetime(year, month, day, 12, 0, 0, tzinfo=timezone.utc))
        except ValueError:
            continue
    if not candidates:
        return None
    return min(candidates, key=lambda dt: abs((dt - trade_dt).total_seconds()))


def _london_event_key(slug: str) -> str:
    text = str(slug or "").strip().lower()
    match_event = _HIGHEST_TEMP_EVENT_KEY_RE.search(text)
    if match_event:
        city = str(match_event.group("city") or "").strip("-")
        mon = str(match_event.group("month") or "").lower()
        day = str(match_event.group("day") or "")
        year = str(match_event.group("year") or "")
        city_key = re.sub(r"[^a-z0-9]+", "-", city).strip("-")
        return f"{city_key}:{mon}-{day}-{year}".rstrip("-")
    matches = list(_LONDON_EVENT_DATE_RE.finditer(text))
    if not matches:
        return text
    m = matches[-1]
    mon = str(m.group(1) or "").lower()
    day = str(m.group(2) or "")
    year = str(m.group(3) or "")
    return f"{mon}-{day}-{year}".rstrip("-")


def _resolve_london_follow_sim_notional(account_balance: Optional[float]) -> float:
    notional = 0.0
    if LONDON_FOLLOW_SIM_ORDER_FIXED_USDC > 0:
        notional = float(LONDON_FOLLOW_SIM_ORDER_FIXED_USDC)
    elif account_balance is not None and math.isfinite(account_balance) and account_balance > 0:
        notional = float(account_balance) * float(LONDON_FOLLOW_SIM_BALANCE_PCT)
    else:
        fallback = to_float(os.environ.get("PM_ORDER_USDC"))
        if fallback is not None and math.isfinite(fallback) and fallback > 0:
            notional = float(fallback)
    if LONDON_FOLLOW_SIM_ORDER_MIN_USDC > 0:
        notional = max(notional, float(LONDON_FOLLOW_SIM_ORDER_MIN_USDC))
    if LONDON_FOLLOW_SIM_ORDER_MAX_USDC > 0:
        notional = min(notional, float(LONDON_FOLLOW_SIM_ORDER_MAX_USDC))
    return max(0.0, float(notional))


def _follow_flow_sign(outcome: str, side: str) -> int:
    outcome_up = str(outcome or "").strip().upper()
    side_up = str(side or "").strip().upper()
    # +1 means short YES (BUY NO / SELL YES); -1 means long YES (BUY YES / SELL NO)
    if (outcome_up == "NO" and side_up == "BUY") or (outcome_up == "YES" and side_up == "SELL"):
        return 1
    if (outcome_up == "YES" and side_up == "BUY") or (outcome_up == "NO" and side_up == "SELL"):
        return -1
    return 0


def _build_london_follow_signal(
    orders: List[Dict[str, Any]],
    account_balance: Optional[float],
) -> Dict[str, Any]:
    now_ts = int(time.time())
    window_sec = max(60, int(LONDON_FOLLOW_SIM_SIGNAL_WINDOW_HOURS * 3600))
    filled_recent: List[Dict[str, Any]] = []
    for row in orders:
        if str(row.get("status") or "") != "filled":
            continue
        ts = _parse_unix_ts(row.get("source_ts"))
        if ts <= 0 or now_ts - ts > window_sec:
            continue
        filled_recent.append(row)
    short_yes = 0.0
    long_yes = 0.0
    flow_by_event: Dict[str, float] = {}
    for row in filled_recent:
        sign = _follow_flow_sign(str(row.get("outcome") or ""), str(row.get("source_side") or ""))
        notional = to_float(row.get("sim_notional_filled")) or 0.0
        if sign > 0:
            short_yes += notional
        elif sign < 0:
            long_yes += notional
        event_key = str(row.get("event_key") or row.get("slug") or "")
        flow_by_event[event_key] = float(flow_by_event.get(event_key, 0.0)) + sign * notional
    net_short_yes = short_yes - long_yes
    threshold = max(2.0, (account_balance or 0.0) * 0.003)
    if net_short_yes > threshold:
        bias = "short_yes"
        message = "短线提示：近端流向偏 NO（看该桶不发生）"
    elif net_short_yes < -threshold:
        bias = "long_yes"
        message = "短线提示：近端流向偏 YES（看该桶发生）"
    else:
        bias = "neutral"
        message = "短线提示：近端流向中性，等待更清晰信号"
    total_abs = short_yes + long_yes
    confidence = abs(net_short_yes) / total_abs if total_abs > 1e-9 else 0.0
    event_items = [
        {"event": key, "net_flow": value}
        for key, value in sorted(flow_by_event.items(), key=lambda kv: abs(kv[1]), reverse=True)[:8]
    ]
    return {
        "window_hours": LONDON_FOLLOW_SIM_SIGNAL_WINDOW_HOURS,
        "filled_orders": len(filled_recent),
        "short_yes_notional": short_yes,
        "long_yes_notional": long_yes,
        "net_short_yes_notional": net_short_yes,
        "bias": bias,
        "confidence": confidence,
        "message": message,
        "top_events": event_items,
    }


def _load_london_follow_source_rows_data_api(
    *,
    source_address: str,
    cutoff_ts: int,
) -> Tuple[List[Dict[str, Any]], str]:
    raw_rows: List[Dict[str, Any]] = []
    stop_paging = False
    for page_idx in range(LONDON_FOLLOW_SIM_MAX_PAGES):
        offset = page_idx * LONDON_FOLLOW_SIM_FETCH_LIMIT
        try:
            rows = _http_get_json_any(
                "https://data-api.polymarket.com/trades",
                params={
                    "user": source_address,
                    "limit": LONDON_FOLLOW_SIM_FETCH_LIMIT,
                    "offset": offset,
                },
                timeout=20,
                retries=3,
            )
        except Exception as exc:
            return raw_rows, f"fetch_failed:{exc}"
        if not isinstance(rows, list) or not rows:
            break
        for row in rows:
            if not isinstance(row, dict):
                continue
            ts = _parse_unix_ts(row.get("timestamp"))
            if ts > 0 and ts < cutoff_ts:
                stop_paging = True
            if not _is_london_temperature_trade(row):
                continue
            if ts <= 0 or ts < cutoff_ts:
                continue
            side = str(row.get("side") or "").strip().upper()
            outcome = str(row.get("outcome") or "").strip().capitalize()
            if side not in {"BUY", "SELL"} or outcome not in {"Yes", "No"}:
                continue
            price = to_float(row.get("price"))
            size = to_float(row.get("size") or row.get("quantity"))
            if price is None or size is None or not math.isfinite(price) or not math.isfinite(size):
                continue
            if price <= 0 or size <= 0:
                continue
            market_slug = str(row.get("slug") or "").strip().lower()
            event_slug = str(row.get("eventSlug") or "").strip().lower()
            if not market_slug and event_slug:
                market_slug = event_slug
            if not market_slug:
                continue
            event_slug_for_time = event_slug or market_slug
            event_close = _infer_london_event_close_utc(event_slug_for_time, ts)
            hrs_to_settle = None
            if event_close is not None:
                hrs_to_settle = (event_close.timestamp() - ts) / 3600.0
            near_settlement = (
                hrs_to_settle is not None
                and hrs_to_settle <= LONDON_FOLLOW_SIM_NEAR_BEFORE_HOURS
                and hrs_to_settle >= -LONDON_FOLLOW_SIM_NEAR_AFTER_HOURS
            )
            if LONDON_FOLLOW_SIM_REQUIRE_NEAR_SETTLEMENT and not near_settlement:
                continue
            raw_rows.append(
                {
                    "source_ts": ts,
                    "source_side": side,
                    "outcome": outcome,
                    "source_price": float(price),
                    "source_size": float(size),
                    "source_notional": float(price) * float(size),
                    "slug": market_slug,
                    "event_slug": event_slug or market_slug,
                    "bucket_label": _extract_london_bucket_label(row),
                    "event_key": _london_event_key(event_slug or market_slug),
                    "near_settlement": bool(near_settlement),
                    "hours_to_settlement": hrs_to_settle,
                    "source_trade_id": str(
                        row.get("id")
                        or row.get("tradeID")
                        or row.get("tradeId")
                        or row.get("transactionHash")
                        or ""
                    ),
                    "mirror_status": "",
                    "mirror_error": "",
                    "mirror_price": None,
                    "mirror_size": None,
                    "mirror_order_id": "",
                    "mirror_created_at": "",
                }
            )
        if stop_paging or len(rows) < LONDON_FOLLOW_SIM_FETCH_LIMIT:
            break
    return raw_rows, ""


def _load_london_follow_source_rows_mirror(
    *,
    source_address: str,
    cutoff_ts: int,
) -> Tuple[List[Dict[str, Any]], str]:
    raw_rows: List[Dict[str, Any]] = []
    if not DB_PATH.exists():
        return raw_rows, "db_missing"
    max_rows = max(1000, min(20000, LONDON_FOLLOW_SIM_FETCH_LIMIT * LONDON_FOLLOW_SIM_MAX_PAGES))
    query = """
        SELECT source_trade_id, source_side, source_price, source_size, source_notional, source_ts,
               slug, event_date, outcome, outcome_side, source_address,
               mirror_status, mirror_error, mirror_price, mirror_size, mirror_order_id, created_at
          FROM mirror_follow_trades
         WHERE COALESCE(source_ts, 0) >= ?
    """
    params: List[Any] = [int(cutoff_ts)]
    addr = str(source_address or "").strip().lower()
    if addr:
        query += " AND LOWER(COALESCE(source_address, '')) = ?"
        params.append(addr)
    query += " ORDER BY COALESCE(source_ts, 0) ASC, id ASC LIMIT ?"
    params.append(int(max_rows))
    try:
        with open_db_ro_fast(timeout_sec=0.35, busy_timeout_ms=300) as conn:
            rows = conn.execute(query, tuple(params)).fetchall()
    except sqlite3.Error as exc:
        return raw_rows, f"mirror_query_failed:{exc}"
    for row in rows:
        ts = _parse_unix_ts(row["source_ts"])
        if ts <= 0 or ts < cutoff_ts:
            continue
        slug = str(row["slug"] or "").strip().lower()
        if not slug:
            continue
        if not _is_london_temperature_trade({"slug": slug, "title": ""}):
            continue
        side = str(row["source_side"] or "").strip().upper()
        outcome_side = str(row["outcome_side"] or "").strip().upper()
        if side not in {"BUY", "SELL"} or outcome_side not in {"YES", "NO"}:
            continue
        price = to_float(row["source_price"])
        size = to_float(row["source_size"])
        if price is None or size is None or not math.isfinite(price) or not math.isfinite(size):
            continue
        if price <= 0 or size <= 0:
            continue
        event_close = _infer_london_event_close_utc(slug, ts)
        hrs_to_settle = None
        if event_close is not None:
            hrs_to_settle = (event_close.timestamp() - ts) / 3600.0
        near_settlement = (
            hrs_to_settle is not None
            and hrs_to_settle <= LONDON_FOLLOW_SIM_NEAR_BEFORE_HOURS
            and hrs_to_settle >= -LONDON_FOLLOW_SIM_NEAR_AFTER_HOURS
        )
        if LONDON_FOLLOW_SIM_REQUIRE_NEAR_SETTLEMENT and not near_settlement:
            continue
        source_notional = to_float(row["source_notional"])
        if source_notional is None or not math.isfinite(source_notional) or source_notional <= 0:
            source_notional = float(price) * float(size)
        raw_rows.append(
            {
                "source_ts": ts,
                "source_side": side,
                "outcome": outcome_side.capitalize(),
                "source_price": float(price),
                "source_size": float(size),
                "source_notional": float(source_notional),
                "slug": slug,
                "event_slug": slug,
                "bucket_label": str(row["outcome"] or "").strip(),
                "event_key": _london_event_key(slug),
                "near_settlement": bool(near_settlement),
                "hours_to_settlement": hrs_to_settle,
                "source_trade_id": str(row["source_trade_id"] or ""),
                "mirror_status": str(row["mirror_status"] or "").strip().lower(),
                "mirror_error": str(row["mirror_error"] or "").strip(),
                "mirror_price": to_float(row["mirror_price"]),
                "mirror_size": to_float(row["mirror_size"]),
                "mirror_order_id": str(row["mirror_order_id"] or "").strip(),
                "mirror_created_at": str(row["created_at"] or "").strip(),
            }
        )
    return raw_rows, ""


def _classify_follow_mirror_diff(*, paper_status: str, mirror_status: str) -> str:
    paper_acted = str(paper_status or "").strip().lower() == "filled"
    mirror_acted = str(mirror_status or "").strip().lower() == "placed"
    if paper_acted and mirror_acted:
        return "aligned"
    if mirror_acted and not paper_acted:
        return "mirror_only"
    if paper_acted and not mirror_acted:
        return "paper_only"
    return "both_skipped"


def _build_london_follow_sim_full(days: int, refresh: bool = False) -> Dict[str, Any]:
    lookback_days = max(7, min(int(days or LONDON_FOLLOW_SIM_LOOKBACK_DAYS), 365))
    source_address = str(LONDON_FOLLOW_SIM_SOURCE_ADDRESS or "").strip().lower()
    source_mode = str(LONDON_FOLLOW_SIM_SOURCE_MODE or "mirror_follow").strip().lower()
    now_ts = int(time.time())
    cache_key = (
        f"{source_mode}|{source_address}|{lookback_days}|{LONDON_FOLLOW_SIM_MODE}|"
        f"{LONDON_FOLLOW_SIM_EDGE_COST_BUFFER:.6f}|{int(LONDON_FOLLOW_SIM_EDGE_REQUIRE_PROB)}|"
        f"{int(LONDON_FOLLOW_SIM_EDGE_APPLY_YES)}|{int(LONDON_FOLLOW_SIM_ALL_HIGHEST_TEMP)}"
    )
    if not refresh:
        with _LONDON_FOLLOW_SIM_CACHE_LOCK:
            cached = _LONDON_FOLLOW_SIM_CACHE.get(cache_key)
            if cached and (time.time() - cached[0]) <= LONDON_FOLLOW_SIM_CACHE_SEC:
                out_cached = dict(cached[1])
                out_cached["cached"] = True
                return out_cached

    payload: Dict[str, Any] = {
        "ok": True,
        "cached": False,
        "paper_only": True,
        "strategy": (
            "london_near_settlement_distribution_follow_sim_edge_gated"
            if LONDON_FOLLOW_SIM_MODE == "edge_gated"
            else "london_near_settlement_distribution_follow_sim_strict"
        ),
        "window_start_utc": (
            datetime.fromtimestamp(now_ts - lookback_days * 86400, timezone.utc).isoformat(timespec="seconds")
        ),
        "source_address": source_address,
        "source_mode": source_mode,
        "config": {
            "enabled": bool(LONDON_FOLLOW_SIM_ENABLED),
            "lookback_days": lookback_days,
            "source_mode": source_mode,
            "mode": LONDON_FOLLOW_SIM_MODE,
            "all_highest_temp": bool(LONDON_FOLLOW_SIM_ALL_HIGHEST_TEMP),
            "require_near_settlement": bool(LONDON_FOLLOW_SIM_REQUIRE_NEAR_SETTLEMENT),
            "near_before_hours": LONDON_FOLLOW_SIM_NEAR_BEFORE_HOURS,
            "near_after_hours": LONDON_FOLLOW_SIM_NEAR_AFTER_HOURS,
            "balance_pct": LONDON_FOLLOW_SIM_BALANCE_PCT,
            "order_fixed_usdc": LONDON_FOLLOW_SIM_ORDER_FIXED_USDC,
            "order_min_usdc": LONDON_FOLLOW_SIM_ORDER_MIN_USDC,
            "order_max_usdc": LONDON_FOLLOW_SIM_ORDER_MAX_USDC,
            "edge_cost_buffer": LONDON_FOLLOW_SIM_EDGE_COST_BUFFER,
            "edge_require_prob": bool(LONDON_FOLLOW_SIM_EDGE_REQUIRE_PROB),
            "edge_apply_yes": bool(LONDON_FOLLOW_SIM_EDGE_APPLY_YES),
            "no_price_min": LONDON_FOLLOW_SIM_NO_PRICE_MIN,
            "yes_price_max": LONDON_FOLLOW_SIM_YES_PRICE_MAX,
            "signal_window_hours": LONDON_FOLLOW_SIM_SIGNAL_WINDOW_HOURS,
            "align_follow_entry": bool(LONDON_FOLLOW_SIM_ALIGN_FOLLOW_ENTRY),
            "align_mirror_strategy": bool(LONDON_FOLLOW_SIM_ALIGN_MIRROR_STRATEGY),
        },
    }
    if not LONDON_FOLLOW_SIM_ENABLED:
        payload.update({"ok": False, "error": "disabled"})
        return payload
    source_address_valid = bool(re.fullmatch(r"0x[a-f0-9]{40}", source_address))
    if source_mode == "data_api" and not source_address_valid:
        payload.update({"ok": False, "error": "invalid_source_address"})
        return payload

    cutoff_ts = now_ts - lookback_days * 86400
    raw_rows: List[Dict[str, Any]]
    source_error = ""
    source_addr_for_query = source_address if source_address_valid else ""
    if source_mode == "mirror_follow":
        raw_rows, source_error = _load_london_follow_source_rows_mirror(
            source_address=source_addr_for_query,
            cutoff_ts=cutoff_ts,
        )
    else:
        raw_rows, source_error = _load_london_follow_source_rows_data_api(
            source_address=source_address,
            cutoff_ts=cutoff_ts,
        )
    if source_error:
        payload.update({"ok": False, "error": source_error})
        return payload

    raw_rows.sort(key=lambda item: int(item.get("source_ts") or 0))
    balance_payload = fetch_auto_trade_balance(force=False, refresh=False)
    account_balance = to_float(balance_payload.get("balance") if isinstance(balance_payload, dict) else None)
    if account_balance is None:
        account_balance = to_float(
            balance_payload.get("balance_allowance") if isinstance(balance_payload, dict) else None
        )
    sim_notional_target = _resolve_london_follow_sim_notional(account_balance)
    align_mirror_strategy = bool(
        LONDON_FOLLOW_SIM_ALIGN_MIRROR_STRATEGY and source_mode == "mirror_follow"
    )
    mirror_copy_ratio = to_float(os.environ.get("PM_MIRROR_COPY_RATIO"))
    if mirror_copy_ratio is None or not math.isfinite(mirror_copy_ratio) or mirror_copy_ratio <= 0:
        mirror_copy_ratio = 1.0
    mirror_notional_mode = str(
        os.environ.get("PM_MIRROR_NOTIONAL_MODE", "source_copy") or "source_copy"
    ).strip().lower()
    if mirror_notional_mode not in {"source_copy", "daily_remaining_ratio"}:
        mirror_notional_mode = "source_copy"
    mirror_order_usdc = to_float(os.environ.get("PM_MIRROR_ORDER_USDC"))
    mirror_min_order_usdc = to_float(os.environ.get("PM_MIRROR_MIN_ORDER_USDC"))
    if mirror_min_order_usdc is None or not math.isfinite(mirror_min_order_usdc) or mirror_min_order_usdc < 0:
        mirror_min_order_usdc = 0.0
    mirror_max_order_usdc = to_float(os.environ.get("PM_MIRROR_MAX_ORDER_USDC"))
    if mirror_max_order_usdc is None or not math.isfinite(mirror_max_order_usdc) or mirror_max_order_usdc <= 0:
        mirror_max_order_usdc = 0.0
    if mirror_max_order_usdc > 0 and mirror_max_order_usdc < mirror_min_order_usdc:
        mirror_max_order_usdc = mirror_min_order_usdc
    mirror_daily_budget_ratio = to_float(os.environ.get("PM_MIRROR_DAILY_BUDGET_RATIO"))
    if (
        mirror_daily_budget_ratio is None
        or not math.isfinite(mirror_daily_budget_ratio)
        or mirror_daily_budget_ratio <= 0
    ):
        mirror_daily_budget_ratio = 0.5
    mirror_daily_budget_ratio = min(max(float(mirror_daily_budget_ratio), 0.0), 1.0)
    mirror_daily_budget_usdc = to_float(os.environ.get("PM_MIRROR_DAILY_BUDGET_USDC"))
    if (
        mirror_daily_budget_usdc is None
        or not math.isfinite(mirror_daily_budget_usdc)
        or mirror_daily_budget_usdc <= 0
    ):
        mirror_daily_budget_usdc = None
    mirror_daily_budget_total: Optional[float] = None
    mirror_daily_budget_remaining: Optional[float] = None
    if (
        align_mirror_strategy
        and mirror_notional_mode == "daily_remaining_ratio"
    ):
        if mirror_daily_budget_usdc is not None:
            mirror_daily_budget_total = float(mirror_daily_budget_usdc)
        elif (
            account_balance is not None
            and math.isfinite(account_balance)
            and account_balance > 0
        ):
            mirror_daily_budget_total = float(account_balance) * float(mirror_daily_budget_ratio)
        else:
            mirror_daily_budget_total = None
        if mirror_daily_budget_total is not None and mirror_daily_budget_total < 0:
            mirror_daily_budget_total = 0.0
        mirror_daily_budget_remaining = max(0.0, float(mirror_daily_budget_total))

    def _resolve_follow_paper_notional(source_price: float, source_size: float) -> Optional[float]:
        source_notional = source_price * source_size if source_price > 0 and source_size > 0 else None
        notional: Optional[float] = None
        if mirror_notional_mode == "daily_remaining_ratio":
            if source_notional is not None:
                notional = source_notional * float(mirror_copy_ratio)
            elif mirror_order_usdc is not None and math.isfinite(mirror_order_usdc) and mirror_order_usdc > 0:
                notional = float(mirror_order_usdc)
        else:
            if mirror_order_usdc is not None and math.isfinite(mirror_order_usdc) and mirror_order_usdc > 0:
                notional = float(mirror_order_usdc)
            elif source_notional is not None:
                notional = source_notional * float(mirror_copy_ratio)
        if notional is None or not math.isfinite(notional) or notional <= 0:
            return None
        if mirror_min_order_usdc > 0:
            notional = max(notional, float(mirror_min_order_usdc))
        if mirror_max_order_usdc > 0:
            notional = min(notional, float(mirror_max_order_usdc))
        if (
            mirror_daily_budget_remaining is not None
            and math.isfinite(mirror_daily_budget_remaining)
            and mirror_daily_budget_remaining > 0
            and notional > mirror_daily_budget_remaining
        ):
            notional = float(mirror_daily_budget_remaining)
        return notional if notional > 0 else None

    positions_lots: Dict[Tuple[str, str], List[List[float]]] = {}
    last_price: Dict[Tuple[str, str], float] = {}
    orders: List[Dict[str, Any]] = []
    realized_pnl = 0.0
    filled_count = 0
    skipped_count = 0
    event_buckets: Dict[str, set[str]] = {}
    edge_eval_count = 0
    edge_pass_count = 0
    edge_fail_count = 0
    edge_missing_prob_count = 0
    skip_reason_counts: Dict[str, int] = {}
    event_prob_cache: Dict[str, Dict[str, Any]] = {}
    diff_counts: Dict[str, int] = {
        "aligned": 0,
        "mirror_only": 0,
        "paper_only": 0,
        "both_skipped": 0,
    }
    diff_reason_counts: Dict[str, int] = {}
    mirror_reason_counts: Dict[str, int] = {}
    paper_skip_reason_counts: Dict[str, int] = {}
    diff_rows: List[Dict[str, Any]] = []

    for row in raw_rows:
        slug = str(row["slug"])
        event_slug = str(row.get("event_slug") or slug)
        bucket_label = str(row.get("bucket_label") or "").strip()
        bucket_key = _canonical_london_bucket_label(bucket_label) or slug
        outcome = str(row["outcome"])
        side = str(row["source_side"])
        key = (slug, outcome)
        event_buckets.setdefault(str(row["event_key"]), set()).add(bucket_key)
        source_price = float(row["source_price"])
        last_price[key] = source_price
        source_size_value = float(row["source_size"])
        target_notional = sim_notional_target
        if align_mirror_strategy:
            if side == "BUY":
                target_notional = _resolve_follow_paper_notional(source_price, source_size_value) or 0.0
                target_qty = (
                    target_notional / source_price
                    if source_price > 0 and target_notional > 0
                    else 0.0
                )
            else:
                target_qty = max(0.0, source_size_value * float(mirror_copy_ratio))
                target_notional = target_qty * source_price if target_qty > 0 and source_price > 0 else 0.0
        else:
            target_qty = target_notional / source_price if source_price > 0 and target_notional > 0 else 0.0
        event_prob_lookup = event_prob_cache.get(event_slug)
        if event_prob_lookup is None:
            event_prob_lookup = _load_london_event_prob_lookup(event_slug)
            event_prob_cache[event_slug] = event_prob_lookup
        prob_row: Dict[str, Any] = {}
        if bucket_key:
            rows_map = event_prob_lookup.get("rows")
            if isinstance(rows_map, dict):
                prob_row = rows_map.get(bucket_key) or {}
        p_yes_true = to_float(prob_row.get("p_yes_true")) if isinstance(prob_row, dict) else None
        edge_eval = _evaluate_london_follow_edge(
            source_side=side,
            contract_outcome=outcome,
            source_price=source_price,
            p_yes_true=p_yes_true,
        )
        if bool(edge_eval.get("evaluated")):
            edge_eval_count += 1
            if edge_eval.get("reason") == "edge_prob_missing":
                edge_missing_prob_count += 1
            if bool(edge_eval.get("pass")):
                edge_pass_count += 1
            else:
                edge_fail_count += 1
        status = "filled"
        skip_reason = ""
        fill_qty = 0.0
        fill_notional = 0.0
        order_realized = 0.0
        mirror_status = str(row.get("mirror_status") or "").strip().lower()
        if mirror_status not in {"placed", "failed", "skipped"}:
            mirror_status = "unknown"
        mirror_error = str(row.get("mirror_error") or "").strip()
        mirror_price = to_float(row.get("mirror_price"))
        mirror_size = to_float(row.get("mirror_size"))
        mirror_order_id = str(row.get("mirror_order_id") or "").strip()
        mirror_created_at = str(row.get("mirror_created_at") or "").strip()
        if side == "BUY" and target_qty <= 1e-9:
            status = "skipped"
            skip_reason = "sim_notional_zero"
        elif side == "BUY" and outcome == "No" and source_price < float(LONDON_FOLLOW_SIM_NO_PRICE_MIN):
            status = "skipped"
            skip_reason = "no_price_below_min"
        elif side == "BUY" and outcome == "Yes" and source_price > float(LONDON_FOLLOW_SIM_YES_PRICE_MAX):
            status = "skipped"
            skip_reason = "yes_price_above_max"
        elif side == "BUY" and not bool(edge_eval.get("pass")):
            status = "skipped"
            skip_reason = str(edge_eval.get("reason") or "edge_gate_rejected")
        elif side == "BUY":
            fill_qty = float(target_qty)
            fill_notional = fill_qty * source_price
            positions_lots.setdefault(key, []).append([fill_qty, source_price, float(row["source_ts"])])
            if (
                align_mirror_strategy
                and mirror_notional_mode == "daily_remaining_ratio"
                and mirror_daily_budget_remaining is not None
                and math.isfinite(mirror_daily_budget_remaining)
                and fill_notional > 0
            ):
                mirror_daily_budget_remaining = max(
                    float(mirror_daily_budget_remaining) - float(fill_notional),
                    0.0,
                )
        else:
            lots = positions_lots.get(key) or []
            available = sum(max(0.0, lot[0]) for lot in lots)
            if available <= 1e-9:
                status = "skipped"
                skip_reason = "sell_no_position"
            else:
                fill_qty = min(float(target_qty), available)
                fill_notional = fill_qty * source_price
                qty_left = fill_qty
                while qty_left > 1e-9 and lots:
                    lot_qty, lot_price, _lot_ts = lots[0]
                    take = min(qty_left, max(0.0, lot_qty))
                    if take <= 1e-9:
                        lots.pop(0)
                        continue
                    pnl_delta = (source_price - lot_price) * take
                    order_realized += pnl_delta
                    realized_pnl += pnl_delta
                    lot_qty -= take
                    qty_left -= take
                    if lot_qty <= 1e-9:
                        lots.pop(0)
                    else:
                        lots[0][0] = lot_qty
                positions_lots[key] = lots
                if fill_qty <= 1e-9:
                    status = "skipped"
                    skip_reason = "sell_size_too_small"
        if status == "filled":
            filled_count += 1
        else:
            skipped_count += 1
            skip_reason_counts[skip_reason or "unknown"] = int(skip_reason_counts.get(skip_reason or "unknown", 0)) + 1
            paper_skip_reason_counts[skip_reason or "unknown"] = int(
                paper_skip_reason_counts.get(skip_reason or "unknown", 0)
            ) + 1
        diff_type = ""
        if source_mode == "mirror_follow":
            diff_type = _classify_follow_mirror_diff(paper_status=status, mirror_status=mirror_status)
            diff_counts[diff_type] = int(diff_counts.get(diff_type, 0)) + 1
            if mirror_status != "placed":
                mirror_reason = mirror_error or f"mirror_{mirror_status}"
                mirror_reason_counts[mirror_reason] = int(mirror_reason_counts.get(mirror_reason, 0)) + 1
            if diff_type == "mirror_only":
                reason_key = f"paper:{skip_reason or 'unknown'}"
                diff_reason_counts[reason_key] = int(diff_reason_counts.get(reason_key, 0)) + 1
            elif diff_type == "paper_only":
                reason_key = f"mirror:{mirror_error or mirror_status}"
                diff_reason_counts[reason_key] = int(diff_reason_counts.get(reason_key, 0)) + 1
            if diff_type in {"mirror_only", "paper_only"}:
                diff_rows.append(
                    {
                        "source_trade_id": str(row.get("source_trade_id") or ""),
                        "source_ts": int(row.get("source_ts") or 0),
                        "source_time_utc": datetime.fromtimestamp(
                            int(row["source_ts"]), timezone.utc
                        ).isoformat(timespec="seconds"),
                        "event_key": row.get("event_key"),
                        "slug": slug,
                        "event_slug": event_slug,
                        "bucket_label": bucket_label,
                        "outcome": outcome,
                        "source_side": side,
                        "source_price": source_price,
                        "source_size": float(row["source_size"]),
                        "diff_type": diff_type,
                        "mirror_status": mirror_status,
                        "mirror_error": mirror_error,
                        "mirror_price": mirror_price,
                        "mirror_size": mirror_size,
                        "mirror_order_id": mirror_order_id,
                        "mirror_created_at": mirror_created_at,
                        "paper_status": status,
                        "paper_skip_reason": skip_reason,
                        "p_yes_true": p_yes_true,
                        "edge_gate_mode": LONDON_FOLLOW_SIM_MODE,
                        "edge_gate_pass": bool(edge_eval.get("pass")),
                        "edge_gate_reason": str(edge_eval.get("reason") or ""),
                        "edge_value": edge_eval.get("edge_value"),
                    }
                )
        raw_id = (
            f"{row.get('source_trade_id')}|{slug}|{outcome}|{side}|{row.get('source_ts')}|"
            f"{source_price:.6f}|{target_qty:.6f}"
        )
        order_id = hashlib.sha1(raw_id.encode("utf-8")).hexdigest()
        orders.append(
            {
                "id": order_id,
                "source_ts": int(row["source_ts"]),
                "source_time_utc": datetime.fromtimestamp(
                    int(row["source_ts"]), timezone.utc
                ).isoformat(timespec="seconds"),
                "event_key": row["event_key"],
                "event_slug": event_slug,
                "slug": slug,
                "bucket_label": bucket_label,
                "outcome": outcome,
                "source_side": side,
                "source_price": source_price,
                "source_size": float(row["source_size"]),
                "source_notional": float(row["source_notional"]),
                "sim_notional_target": target_notional,
                "sim_size_target": target_qty,
                "sim_size_filled": fill_qty,
                "sim_notional_filled": fill_notional,
                "status": status,
                "skip_reason": skip_reason,
                "near_settlement": bool(row["near_settlement"]),
                "hours_to_settlement": row.get("hours_to_settlement"),
                "fact_as_of": event_prob_lookup.get("fact_as_of"),
                "p_yes_true": p_yes_true,
                "edge_gate_mode": LONDON_FOLLOW_SIM_MODE,
                "edge_gate_evaluated": bool(edge_eval.get("evaluated")),
                "edge_gate_pass": bool(edge_eval.get("pass")),
                "edge_gate_reason": str(edge_eval.get("reason") or ""),
                "edge_gate_threshold": edge_eval.get("threshold"),
                "edge_value": edge_eval.get("edge_value"),
                "edge_cost_buffer": edge_eval.get("cost_buffer"),
                "mirror_status": mirror_status if source_mode == "mirror_follow" else "",
                "mirror_error": mirror_error if source_mode == "mirror_follow" else "",
                "mirror_price": mirror_price if source_mode == "mirror_follow" else None,
                "mirror_size": mirror_size if source_mode == "mirror_follow" else None,
                "mirror_order_id": mirror_order_id if source_mode == "mirror_follow" else "",
                "mirror_created_at": mirror_created_at if source_mode == "mirror_follow" else "",
                "diff_type": diff_type,
                "realized_pnl": order_realized,
                "realized_pnl_cum": realized_pnl,
            }
        )

    open_positions: List[Dict[str, Any]] = []
    unrealized_est = 0.0
    for key, lots in positions_lots.items():
        slug, outcome = key
        qty = sum(max(0.0, lot[0]) for lot in lots)
        if qty <= 1e-9:
            continue
        cost = sum(max(0.0, lot[0]) * lot[1] for lot in lots)
        avg_price = cost / qty if qty > 1e-9 else 0.0
        mark_price = last_price.get(key, avg_price)
        unreal = (mark_price - avg_price) * qty
        unrealized_est += unreal
        open_positions.append(
            {
                "slug": slug,
                "event_key": _london_event_key(slug),
                "outcome": outcome,
                "qty": qty,
                "avg_price": avg_price,
                "mark_price_est": mark_price,
                "unrealized_pnl_est": unreal,
            }
        )
    open_positions.sort(key=lambda row: abs(float(row.get("unrealized_pnl_est") or 0.0)), reverse=True)
    signal = _build_london_follow_signal(orders, account_balance)
    events_with_multi_bucket = sum(1 for buckets in event_buckets.values() if len(buckets) >= 2)
    diff_rows_sorted = sorted(
        (row for row in diff_rows if isinstance(row, dict)),
        key=lambda item: int(item.get("source_ts") or 0),
        reverse=True,
    )

    def _top_counts(counter: Dict[str, int], limit: int = 6) -> List[Dict[str, Any]]:
        return [
            {"label": key, "count": int(value)}
            for key, value in sorted(counter.items(), key=lambda kv: kv[1], reverse=True)[:limit]
        ]

    diff_payload = {
        "enabled": source_mode == "mirror_follow",
        "source_mode": source_mode,
        "counts": diff_counts,
        "mismatch_count": int(diff_counts.get("mirror_only", 0)) + int(diff_counts.get("paper_only", 0)),
        "reason_top": _top_counts(diff_reason_counts),
        "mirror_reason_top": _top_counts(mirror_reason_counts),
        "paper_skip_reason_top": _top_counts(paper_skip_reason_counts),
        "rows": diff_rows_sorted[:LONDON_FOLLOW_SIM_DIFF_ROWS_LIMIT],
    }
    payload_full = {
        **payload,
        "as_of": now_text(),
        "counts": {
            "source_trades_filtered": len(raw_rows),
            "sim_orders": len(orders),
            "filled": filled_count,
            "skipped": skipped_count,
            "events": len(event_buckets),
            "events_multi_bucket": events_with_multi_bucket,
            "near_settlement_rows": sum(1 for row in raw_rows if bool(row.get("near_settlement"))),
            "edge_gate_evaluated": edge_eval_count,
            "edge_gate_passed": edge_pass_count,
            "edge_gate_failed": edge_fail_count,
            "edge_prob_missing": edge_missing_prob_count,
            "skip_reason_counts": skip_reason_counts,
        },
        "account": {
            "balance": account_balance,
            "balance_owner": balance_payload.get("balance_owner") if isinstance(balance_payload, dict) else "",
            "funder_address": balance_payload.get("funder_address") if isinstance(balance_payload, dict) else "",
            "sim_notional_per_order": sim_notional_target,
            "sim_sizing_mode": "mirror_strategy" if align_mirror_strategy else "account_balance_pct",
            "mirror_copy_ratio": float(mirror_copy_ratio),
            "mirror_notional_mode": mirror_notional_mode,
            "mirror_daily_budget_usdc": mirror_daily_budget_usdc,
            "mirror_daily_budget_total": mirror_daily_budget_total,
            "mirror_daily_budget_remaining": mirror_daily_budget_remaining,
        },
        "result": {
            "realized_pnl": realized_pnl,
            "unrealized_pnl_est": unrealized_est,
            "total_pnl_est": realized_pnl + unrealized_est,
            "open_positions": len(open_positions),
        },
        "signal": signal,
        "diff": diff_payload,
        "open_positions": open_positions,
        "orders_all": orders,
    }
    with _LONDON_FOLLOW_SIM_CACHE_LOCK:
        _LONDON_FOLLOW_SIM_CACHE[cache_key] = (time.time(), payload_full)
    return payload_full


def _london_follow_sim_cache_key(days: int) -> str:
    lookback_days = max(7, min(int(days or LONDON_FOLLOW_SIM_LOOKBACK_DAYS), 365))
    source_address = str(LONDON_FOLLOW_SIM_SOURCE_ADDRESS or "").strip().lower()
    source_mode = str(LONDON_FOLLOW_SIM_SOURCE_MODE or "mirror_follow").strip().lower()
    return (
        f"{source_mode}|{source_address}|{lookback_days}|{LONDON_FOLLOW_SIM_MODE}|"
        f"{LONDON_FOLLOW_SIM_EDGE_COST_BUFFER:.6f}|{int(LONDON_FOLLOW_SIM_EDGE_REQUIRE_PROB)}|"
        f"{int(LONDON_FOLLOW_SIM_EDGE_APPLY_YES)}|{int(LONDON_FOLLOW_SIM_ALL_HIGHEST_TEMP)}"
    )


def _paginate_london_follow_sim_payload(payload_full: Dict[str, Any], page: int, limit: int) -> Dict[str, Any]:
    all_orders = payload_full.get("orders_all")
    if not isinstance(all_orders, list):
        all_orders = []
    all_orders_sorted = sorted(
        (row for row in all_orders if isinstance(row, dict)),
        key=lambda row: int(row.get("source_ts") or 0),
        reverse=True,
    )
    page_norm = max(1, int(page or 1))
    limit_norm = max(10, min(int(limit or 100), 500))
    total = len(all_orders_sorted)
    start_idx = (page_norm - 1) * limit_norm
    end_idx = start_idx + limit_norm
    items = all_orders_sorted[start_idx:end_idx]
    out = dict(payload_full)
    out.pop("orders_all", None)
    out["orders"] = items
    out["pagination"] = {
        "total": total,
        "page": page_norm,
        "limit": limit_norm,
        "pages": max(1, math.ceil(total / limit_norm)) if limit_norm > 0 else 1,
    }
    return out


def london_follow_sim_report(
    *,
    days: int,
    page: int,
    limit: int,
    refresh: bool = False,
    quick: bool = False,
) -> Dict[str, Any]:
    if quick:
        cache_key = _london_follow_sim_cache_key(days)
        cached_payload: Optional[Dict[str, Any]] = None
        cache_age_sec: Optional[float] = None
        with _LONDON_FOLLOW_SIM_CACHE_LOCK:
            cached = _LONDON_FOLLOW_SIM_CACHE.get(cache_key)
            if cached and isinstance(cached[1], dict):
                cache_age_sec = max(0.0, time.time() - float(cached[0] or 0.0))
                cached_payload = dict(cached[1])
        if not isinstance(cached_payload, dict):
            return {
                "ok": True,
                "cached": False,
                "stale": True,
                "warming": True,
                "paper_only": True,
                "source_mode": str(LONDON_FOLLOW_SIM_SOURCE_MODE or "mirror_follow").strip().lower(),
                "strategy": (
                    "london_near_settlement_distribution_follow_sim_edge_gated"
                    if LONDON_FOLLOW_SIM_MODE == "edge_gated"
                    else "london_near_settlement_distribution_follow_sim_strict"
                ),
                "as_of": "",
                "counts": {},
                "account": {},
                "result": {},
                "signal": {},
                "diff": {
                    "enabled": False,
                    "source_mode": str(LONDON_FOLLOW_SIM_SOURCE_MODE or "mirror_follow").strip().lower(),
                    "counts": {},
                    "mismatch_count": 0,
                    "reason_top": [],
                    "mirror_reason_top": [],
                    "paper_skip_reason_top": [],
                    "rows": [],
                },
                "orders": [],
                "pagination": {
                    "total": 0,
                    "page": max(1, int(page or 1)),
                    "limit": max(10, min(int(limit or 100), 500)),
                    "pages": 1,
                },
                "na_reason": "cache_miss",
            }
        cached_payload["cached"] = True
        cached_payload["stale"] = (
            cache_age_sec is None
            or cache_age_sec > float(LONDON_FOLLOW_SIM_CACHE_SEC)
        )
        cached_payload["warming"] = False
        payload_full = cached_payload
    else:
        payload_full = _build_london_follow_sim_full(days=days, refresh=refresh)
    if not payload_full.get("ok"):
        return payload_full
    return _paginate_london_follow_sim_payload(payload_full, page=page, limit=limit)


def _london_follow_tuning_default_state() -> Dict[str, Any]:
    return {"ok": True, "updated_at": "", "latest": None, "history": []}


def _load_london_follow_tuning_state() -> Dict[str, Any]:
    with LONDON_FOLLOW_TUNING_LOCK:
        if not LONDON_FOLLOW_TUNING_STATE_PATH.exists():
            return _london_follow_tuning_default_state()
        try:
            raw = LONDON_FOLLOW_TUNING_STATE_PATH.read_text(encoding="utf-8")
            payload = json.loads(raw)
        except (OSError, json.JSONDecodeError):
            return _london_follow_tuning_default_state()
        if not isinstance(payload, dict):
            return _london_follow_tuning_default_state()
        history = payload.get("history")
        if not isinstance(history, list):
            history = []
        payload["history"] = [row for row in history if isinstance(row, dict)]
        if not isinstance(payload.get("latest"), dict):
            payload["latest"] = None
        payload.setdefault("ok", True)
        payload.setdefault("updated_at", "")
        return payload


def _save_london_follow_tuning_state(payload: Dict[str, Any]) -> None:
    if not isinstance(payload, dict):
        return
    payload = dict(payload)
    history = payload.get("history")
    if not isinstance(history, list):
        history = []
    payload["history"] = history[:LONDON_FOLLOW_TUNING_HISTORY_MAX]
    payload["updated_at"] = now_text()
    payload["ok"] = True
    with LONDON_FOLLOW_TUNING_LOCK:
        try:
            DATA_DIR.mkdir(parents=True, exist_ok=True)
            LONDON_FOLLOW_TUNING_STATE_PATH.write_text(
                json.dumps(payload, ensure_ascii=True),
                encoding="utf-8",
            )
        except OSError:
            pass


def _local_date_iso() -> str:
    return datetime.now().astimezone().date().isoformat()


def _follow_percentile(values: List[float], q: float) -> Optional[float]:
    valid = [float(v) for v in values if v is not None and math.isfinite(v)]
    if not valid:
        return None
    valid.sort()
    if len(valid) == 1:
        return valid[0]
    q_norm = min(max(float(q), 0.0), 1.0)
    pos = q_norm * (len(valid) - 1)
    lo = int(math.floor(pos))
    hi = int(math.ceil(pos))
    if lo == hi:
        return valid[lo]
    w = pos - lo
    return valid[lo] * (1.0 - w) + valid[hi] * w


def _follow_gate_reason_for_order(order: Dict[str, Any], cfg: Dict[str, Any]) -> str:
    side = str(order.get("source_side") or "").strip().upper()
    if side != "BUY":
        return "side_not_buy"
    outcome = str(order.get("outcome") or "").strip().lower()
    if cfg.get("entry_follow_no_only") and outcome != "no":
        return "follow_no_only"
    price = to_float(order.get("source_price"))
    if price is None or not math.isfinite(price) or price <= 0:
        return "price_missing"
    hours_to_settle = to_float(order.get("hours_to_settlement"))
    if cfg.get("entry_follow_require_near_settlement"):
        before = float(cfg.get("entry_follow_near_before_hours") or 24.0)
        after = float(cfg.get("entry_follow_near_after_hours") or 6.0)
        if hours_to_settle is None or not math.isfinite(hours_to_settle):
            return "follow_not_near_settlement"
        if not (hours_to_settle <= before + 1e-9 and hours_to_settle >= -after - 1e-9):
            return "follow_not_near_settlement"
    if outcome == "no":
        if price < float(cfg.get("entry_follow_no_price_min") or 0.0) - 1e-9:
            return "follow_no_price_low"
    elif outcome == "yes":
        if price > float(cfg.get("entry_follow_yes_price_max") or 1.0) + 1e-9:
            return "follow_yes_price_high"
    p_yes = to_float(order.get("p_yes_true"))
    if cfg.get("entry_follow_mode") == "edge_gated":
        if p_yes is None or not math.isfinite(p_yes):
            return "follow_signal_edge_missing"
        if outcome == "no":
            signal_edge = (1.0 - p_yes) - price - float(cfg.get("entry_follow_edge_cost_buffer") or 0.0)
        elif outcome == "yes":
            signal_edge = p_yes - price - float(cfg.get("entry_follow_edge_cost_buffer") or 0.0)
        else:
            return "follow_outcome_unknown"
        if signal_edge <= float(cfg.get("entry_follow_signal_edge_min") or 0.0) + 1e-9:
            return "follow_signal_edge_low"
    return ""


def _follow_config_snapshot() -> Dict[str, Any]:
    full_config = auto_trade_config_defaults()
    full_config.update(load_auto_trade_config())
    bypass_exec_edge = bool(full_config.get("entry_follow_bypass_exec_edge_gate"))
    return {
        "entry_follow_no_only": bool(full_config.get("entry_follow_no_only", False)),
        "entry_follow_require_near_settlement": True,
        "entry_follow_near_before_hours": float(full_config.get("entry_follow_near_before_hours") or 24.0),
        "entry_follow_near_after_hours": float(full_config.get("entry_follow_near_after_hours") or 6.0),
        "entry_follow_no_price_min": float(full_config.get("entry_follow_no_price_min") or 0.95),
        "entry_follow_yes_price_max": float(full_config.get("entry_follow_yes_price_max") or 0.35),
        "entry_follow_edge_cost_buffer": float(full_config.get("entry_follow_edge_cost_buffer") or 0.01),
        "entry_follow_signal_edge_min": float(full_config.get("entry_follow_signal_edge_min") or 0.0),
        "entry_follow_mode": "strict" if bypass_exec_edge else "edge_gated",
    }


def _build_london_follow_tuning_suggestion(*, lookback_days: int) -> Dict[str, Any]:
    run_date = _local_date_iso()
    report = _build_london_follow_sim_full(days=lookback_days, refresh=True)
    if not isinstance(report, dict) or not report.get("ok"):
        return {
            "id": uuid.uuid4().hex[:12],
            "run_date": run_date,
            "generated_at": utc_now_iso(),
            "status": "error",
            "error": str(report.get("error") if isinstance(report, dict) else "report_failed"),
            "lookback_days": lookback_days,
        }
    orders_all = report.get("orders_all")
    if not isinstance(orders_all, list):
        orders_all = []
    baseline_buys = [
        row
        for row in orders_all
        if isinstance(row, dict)
        and str(row.get("source_side") or "").strip().upper() == "BUY"
        and str(row.get("status") or "").strip().lower() == "filled"
    ]
    current_cfg = _follow_config_snapshot()
    baseline_count = len(baseline_buys)

    current_reasons: Dict[str, int] = {}
    current_pass = 0
    for row in baseline_buys:
        reason = _follow_gate_reason_for_order(row, current_cfg)
        if reason:
            current_reasons[reason] = int(current_reasons.get(reason, 0)) + 1
        else:
            current_pass += 1
    current_ratio = (float(current_pass) / float(baseline_count)) if baseline_count > 0 else 0.0

    target = float(LONDON_FOLLOW_TUNING_TARGET_COVERAGE)
    q_low = max(0.0, 1.0 - target)
    q_high = min(0.99, target)
    no_prices: List[float] = []
    yes_prices: List[float] = []
    before_hours: List[float] = []
    after_hours: List[float] = []
    signal_edges: List[float] = []
    for row in baseline_buys:
        outcome = str(row.get("outcome") or "").strip().lower()
        price = to_float(row.get("source_price"))
        if price is None or not math.isfinite(price) or price <= 0:
            continue
        if outcome == "no":
            no_prices.append(float(price))
        elif outcome == "yes":
            yes_prices.append(float(price))
        hrs = to_float(row.get("hours_to_settlement"))
        if hrs is not None and math.isfinite(hrs):
            if hrs >= 0:
                before_hours.append(float(hrs))
            else:
                after_hours.append(abs(float(hrs)))
        p_yes = to_float(row.get("p_yes_true"))
        if p_yes is not None and math.isfinite(p_yes):
            if outcome == "no":
                edge_raw = (1.0 - p_yes) - float(price) - float(current_cfg["entry_follow_edge_cost_buffer"])
            elif outcome == "yes":
                edge_raw = p_yes - float(price) - float(current_cfg["entry_follow_edge_cost_buffer"])
            else:
                edge_raw = None
            if edge_raw is not None and math.isfinite(edge_raw):
                signal_edges.append(float(edge_raw))

    changes: Dict[str, Any] = {}
    rationales: Dict[str, str] = {}

    def _add_change(key: str, value: Any, rationale: str, *, tol: float = 1e-6) -> None:
        current_val = current_cfg.get(key)
        if isinstance(value, float):
            if not math.isfinite(value):
                return
            if isinstance(current_val, (int, float)) and math.isfinite(float(current_val)):
                if abs(float(value) - float(current_val)) <= tol:
                    return
        else:
            if value == current_val:
                return
        changes[key] = value
        rationales[key] = rationale

    if len(before_hours) >= LONDON_FOLLOW_TUNING_MIN_SAMPLES:
        p = _follow_percentile(before_hours, q_high)
        if p is not None:
            p = round(max(0.0, min(72.0, p + 0.2)), 1)
            if p > float(current_cfg["entry_follow_near_before_hours"]) + 0.1:
                _add_change(
                    "entry_follow_near_before_hours",
                    p,
                    f"扩展结算前窗口以覆盖基线 {int(target*100)}% 样本",
                    tol=0.1,
                )
    if len(after_hours) >= LONDON_FOLLOW_TUNING_MIN_SAMPLES:
        p = _follow_percentile(after_hours, q_high)
        if p is not None:
            p = round(max(0.0, min(24.0, p + 0.2)), 1)
            if p > float(current_cfg["entry_follow_near_after_hours"]) + 0.1:
                _add_change(
                    "entry_follow_near_after_hours",
                    p,
                    f"扩展结算后窗口以覆盖基线 {int(target*100)}% 样本",
                    tol=0.1,
                )
    if len(no_prices) >= LONDON_FOLLOW_TUNING_MIN_SAMPLES:
        p = _follow_percentile(no_prices, q_low)
        if p is not None:
            p = round(max(0.0, min(1.0, p)), 3)
            if p < float(current_cfg["entry_follow_no_price_min"]) - 0.003:
                _add_change(
                    "entry_follow_no_price_min",
                    p,
                    "下调 NO 价格下限，提升对齐基线成交覆盖",
                    tol=0.003,
                )
    if len(yes_prices) >= LONDON_FOLLOW_TUNING_MIN_SAMPLES and not bool(current_cfg["entry_follow_no_only"]):
        p = _follow_percentile(yes_prices, q_high)
        if p is not None:
            p = round(max(0.0, min(1.0, p)), 3)
            if p > float(current_cfg["entry_follow_yes_price_max"]) + 0.003:
                _add_change(
                    "entry_follow_yes_price_max",
                    p,
                    "上调 YES 价格上限，提升对齐基线成交覆盖",
                    tol=0.003,
                )
    if len(signal_edges) >= LONDON_FOLLOW_TUNING_MIN_SAMPLES and current_cfg["entry_follow_mode"] == "edge_gated":
        p = _follow_percentile(signal_edges, q_low)
        if p is not None:
            p = round(max(0.0, p), 4)
            if p < float(current_cfg["entry_follow_signal_edge_min"]) - 0.0005:
                _add_change(
                    "entry_follow_signal_edge_min",
                    p,
                    "下调旧信号诊断门槛，提升对齐基线成交覆盖",
                    tol=0.0005,
                )
    if bool(current_cfg["entry_follow_no_only"]) and len(yes_prices) >= max(6, LONDON_FOLLOW_TUNING_MIN_SAMPLES // 2):
        _add_change(
            "entry_follow_no_only",
            False,
            "基线存在较多 YES 买单，建议关闭仅 NO 限制",
        )

    proposed_cfg = dict(current_cfg)
    for key, value in changes.items():
        proposed_cfg[key] = value
    proposed_reasons: Dict[str, int] = {}
    proposed_pass = 0
    for row in baseline_buys:
        reason = _follow_gate_reason_for_order(row, proposed_cfg)
        if reason:
            proposed_reasons[reason] = int(proposed_reasons.get(reason, 0)) + 1
        else:
            proposed_pass += 1
    proposed_ratio = (float(proposed_pass) / float(baseline_count)) if baseline_count > 0 else 0.0

    status = "pending" if changes else "no_change"
    if baseline_count < LONDON_FOLLOW_TUNING_MIN_SAMPLES:
        status = "insufficient_samples"

    suggestion = {
        "id": uuid.uuid4().hex[:12],
        "run_date": run_date,
        "generated_at": utc_now_iso(),
        "status": status,
        "lookback_days": lookback_days,
        "target_coverage": target,
        "source_mode": report.get("source_mode"),
        "baseline": {
            "total_buy_filled": baseline_count,
            "no_prices": len(no_prices),
            "yes_prices": len(yes_prices),
            "current_pass_count": current_pass,
            "current_pass_ratio": round(current_ratio, 4),
            "proposed_pass_count": proposed_pass,
            "proposed_pass_ratio": round(proposed_ratio, 4),
            "current_block_reasons": current_reasons,
            "proposed_block_reasons": proposed_reasons,
        },
        "proposal": {
            "changes": changes,
            "rationales": rationales,
            "current_config": current_cfg,
        },
    }
    if status == "insufficient_samples":
        suggestion["na_reason"] = "insufficient_baseline_samples"
    if status == "no_change":
        suggestion["na_reason"] = "no_actionable_delta"
    return suggestion


def generate_london_follow_tuning_suggestion(
    *,
    force: bool = False,
    source: str = "auto",
) -> Dict[str, Any]:
    state = _load_london_follow_tuning_state()
    today = _local_date_iso()
    latest = state.get("latest")
    if (
        not force
        and isinstance(latest, dict)
        and str(latest.get("run_date") or "") == today
    ):
        out = dict(state)
        out["generated"] = False
        out["latest"] = latest
        return out
    suggestion = _build_london_follow_tuning_suggestion(
        lookback_days=LONDON_FOLLOW_TUNING_LOOKBACK_DAYS
    )
    suggestion["source"] = source
    history = state.get("history") if isinstance(state.get("history"), list) else []
    history = [row for row in history if isinstance(row, dict)]
    history.insert(0, suggestion)
    state["history"] = history[:LONDON_FOLLOW_TUNING_HISTORY_MAX]
    state["latest"] = suggestion
    _save_london_follow_tuning_state(state)
    out = dict(state)
    out["generated"] = True
    out["latest"] = suggestion
    return out


def get_london_follow_tuning_suggestions(*, refresh: bool = False) -> Dict[str, Any]:
    state = _load_london_follow_tuning_state()
    if refresh:
        return generate_london_follow_tuning_suggestion(force=True, source="manual_refresh")
    latest = state.get("latest")
    today = _local_date_iso()
    if (
        LONDON_FOLLOW_TUNING_AUTO_ENABLED
        and (
            not isinstance(latest, dict)
            or str(latest.get("run_date") or "") != today
        )
    ):
        return generate_london_follow_tuning_suggestion(force=True, source="auto_daily")
    state["generated"] = False
    return state


def apply_london_follow_tuning_suggestion(
    *,
    suggestion_id: str = "",
    restart: bool = False,
    scan: bool = False,
) -> Dict[str, Any]:
    state = _load_london_follow_tuning_state()
    history = state.get("history") if isinstance(state.get("history"), list) else []
    latest = state.get("latest") if isinstance(state.get("latest"), dict) else None
    target: Optional[Dict[str, Any]] = None
    if suggestion_id:
        for row in history:
            if str(row.get("id") or "") == suggestion_id:
                target = row
                break
        if target is None:
            return {"ok": False, "error": "missing_suggestion"}
    if target is None:
        target = latest
    if not isinstance(target, dict):
        return {"ok": False, "error": "missing_suggestion"}
    status = str(target.get("status") or "")
    if status not in {"pending", "no_change", "insufficient_samples"}:
        return {"ok": False, "error": "suggestion_not_pending", "status": status}
    proposal = target.get("proposal") if isinstance(target.get("proposal"), dict) else {}
    changes = proposal.get("changes") if isinstance(proposal.get("changes"), dict) else {}
    if not changes:
        target["status"] = "applied_no_change"
        target["applied_at"] = utc_now_iso()
        _save_london_follow_tuning_state(state)
        return {"ok": True, "applied": False, "reason": "no_changes", "suggestion": target}

    payload = load_auto_trade_config()
    payload.update(changes)
    full_config = auto_trade_config_defaults()
    full_config.update(payload)
    validation = validate_auto_trade_config(full_config)
    if not validation.get("ok"):
        return {
            "ok": False,
            "error": "invalid_config",
            "errors": validation.get("errors") or [],
            "warnings": validation.get("warnings") or [],
        }
    save_auto_trade_config(payload)
    apply_auto_trade_config(payload)
    restart_result = restart_auto_trade_watcher() if restart else None
    scan_result = start_scan(False, False) if scan else None
    target["status"] = "applied"
    target["applied_at"] = utc_now_iso()
    target["apply_warnings"] = validation.get("warnings") or []
    if isinstance(latest, dict) and str(latest.get("id") or "") == str(target.get("id") or ""):
        state["latest"] = target
    for idx, row in enumerate(history):
        if str(row.get("id") or "") == str(target.get("id") or ""):
            history[idx] = target
            break
    state["history"] = history
    _save_london_follow_tuning_state(state)
    return {
        "ok": True,
        "applied": True,
        "suggestion": target,
        "warnings": validation.get("warnings") or [],
        "restart": restart_result,
        "scan": scan_result,
    }


def reject_london_follow_tuning_suggestion(*, suggestion_id: str = "", note: str = "") -> Dict[str, Any]:
    state = _load_london_follow_tuning_state()
    history = state.get("history") if isinstance(state.get("history"), list) else []
    latest = state.get("latest") if isinstance(state.get("latest"), dict) else None
    target: Optional[Dict[str, Any]] = None
    if suggestion_id:
        for row in history:
            if str(row.get("id") or "") == suggestion_id:
                target = row
                break
        if target is None:
            return {"ok": False, "error": "missing_suggestion"}
    if target is None:
        target = latest
    if not isinstance(target, dict):
        return {"ok": False, "error": "missing_suggestion"}
    target["status"] = "rejected"
    target["rejected_at"] = utc_now_iso()
    if note:
        target["reject_note"] = note[:240]
    if isinstance(latest, dict) and str(latest.get("id") or "") == str(target.get("id") or ""):
        state["latest"] = target
    for idx, row in enumerate(history):
        if str(row.get("id") or "") == str(target.get("id") or ""):
            history[idx] = target
            break
    state["history"] = history
    _save_london_follow_tuning_state(state)
    return {"ok": True, "suggestion": target}


def london_follow_tuning_auto_loop() -> None:
    while True:
        try:
            if LONDON_FOLLOW_TUNING_AUTO_ENABLED:
                get_london_follow_tuning_suggestions(refresh=False)
        except Exception as exc:
            print(f"[follow-tuning] auto loop failed: {exc}")
        time.sleep(float(LONDON_FOLLOW_TUNING_AUTO_INTERVAL_SEC))


class Handler(BaseHTTPRequestHandler):
    server_version = "WeatherUI/1.0"

    def handle_one_request(self) -> None:
        started = time.perf_counter()
        try:
            super().handle_one_request()
        finally:
            threshold = float(UI_SLOW_REQUEST_LOG_SEC or 0.0)
            elapsed = time.perf_counter() - started
            path = str(getattr(self, "path", "") or "")
            command = str(getattr(self, "command", "") or "")
            _record_ui_endpoint_observation(path, method=command, elapsed_sec=elapsed)
            if threshold <= 0:
                return
            if elapsed < threshold:
                return
            self.log_message("slow_request method=%s path=%s elapsed=%.3fs", command, path, elapsed)

    def _send(self, status: int, body: bytes, content_type: str) -> None:
        try:
            self.close_connection = True
            self.send_response(status)
            self.send_header("Access-Control-Allow-Origin", "*")
            self.send_header("Access-Control-Allow-Methods", "GET, OPTIONS")
            self.send_header("Access-Control-Allow-Headers", "*")
            self.send_header("Content-Type", content_type)
            self.send_header("Cache-Control", "no-store, no-cache, must-revalidate, max-age=0")
            self.send_header("Pragma", "no-cache")
            self.send_header("Expires", "0")
            self.send_header("Content-Length", str(len(body)))
            self.send_header("Connection", "close")
            self.end_headers()
            self.wfile.write(body)
        except (BrokenPipeError, ConnectionResetError):
            return

    def _send_json(self, payload: Any, status: int = 200) -> None:
        safe_payload = _sanitize_errno24_payload(payload)
        body = json.dumps(safe_payload, ensure_ascii=True, separators=(",", ":")).encode("utf-8")
        self._send(status, body, "application/json; charset=utf-8")

    def _send_html(self) -> None:
        try:
            html = load_html().encode("utf-8")
        except FileNotFoundError:
            self._send(404, b"missing index.html", "text/plain; charset=utf-8")
            return
        self._send(200, html, "text/html; charset=utf-8")

    def _send_text(self, status: int, text: str) -> None:
        self._send(status, text.encode("utf-8"), "text/plain; charset=utf-8")

    def do_OPTIONS(self) -> None:
        self.close_connection = True
        self.send_response(204)
        self.send_header("Access-Control-Allow-Origin", "*")
        self.send_header("Access-Control-Allow-Methods", "GET, OPTIONS")
        self.send_header("Access-Control-Allow-Headers", "*")
        self.send_header("Connection", "close")
        self.end_headers()

    def do_GET(self) -> None:
        parsed = urlparse(self.path)
        path = parsed.path
        params = parse_qs(parsed.query)

        if path in ("/", "/index.html"):
            mtime = html_mtime()
            version = ""
            if params.get("v"):
                version = params.get("v")[0] or ""
            if version != str(mtime):
                redirect_params = {
                    key: values[-1]
                    for key, values in params.items()
                    if values
                }
                redirect_params["v"] = str(mtime)
                target = f"/index.html?{urlencode(redirect_params)}"
                self.send_response(302)
                self.send_header("Location", target)
                self.send_header("Cache-Control", "no-store, no-cache, must-revalidate, max-age=0")
                self.send_header("Pragma", "no-cache")
                self.send_header("Expires", "0")
                self.end_headers()
                return
            self._send_html()
            return

        if path in ("/follow-london", "/follow-london.html"):
            try:
                html = load_follow_html().encode("utf-8")
            except FileNotFoundError:
                self._send(404, b"missing follow_london.html", "text/plain; charset=utf-8")
                return
            self._send(200, html, "text/html; charset=utf-8")
            return

        if path in ("/lcb", "/lcb.html"):
            try:
                html = load_lcb_html().encode("utf-8")
            except FileNotFoundError:
                self._send(404, b"missing lcb.html", "text/plain; charset=utf-8")
                return
            self._send(200, html, "text/html; charset=utf-8")
            return

        if path == "/api/ui_snapshot_summary":
            try:
                limit = int(params.get("limit", ["24"])[0])
            except ValueError:
                limit = 24
            run_date = str(
                params.get("run_date", [""])[0]
                or params.get("date", [""])[0]
                or ""
            )
            city_filter = str(
                params.get("city", [""])[0]
                or params.get("scope", [""])[0]
                or ""
            )
            refresh = str(params.get("refresh", [""])[0] or "").strip().lower() in {
                "1",
                "true",
                "yes",
                "on",
            }
            force = str(params.get("force", [""])[0] or "").strip().lower() in {
                "1",
                "true",
                "yes",
                "on",
            }
            payload = ui_snapshot_summary(
                run_date=run_date,
                limit=limit,
                force_rebuild=False,
                city_filter=city_filter,
            )
            if isinstance(payload, dict) and (refresh or force):
                payload["refresh_requested"] = bool(refresh)
                payload["force_requested"] = bool(force)
                payload["refresh_mode"] = "stale_while_revalidate"
                payload["synchronous_rebuild_allowed"] = False
            self._send_json(payload)
            return

        if path == "/api/ui_snapshot":
            try:
                limit = int(params.get("limit", ["120"])[0])
            except ValueError:
                limit = 120
