            cached_age_sec = None
            with LATEST_DATE_CACHE_LOCK:
                cached_date = str(LATEST_DATE_CACHE.get("date") or "").strip()
                cached_ts = float(LATEST_DATE_CACHE.get("ts") or 0.0)
                if cached_ts > 0:
                    cached_age_sec = max(0.0, now_ts - cached_ts)
                if cached_date and (now_ts - cached_ts) <= float(LATEST_DATE_CACHE_SEC):
                    self._send_json(
                        {
                            "ok": True,
                            "date": cached_date,
                            "cache_hit": True,
                            "stale": False,
                            "cache_age_sec": round(cached_age_sec or 0.0, 3),
                        }
                    )
                    return
            latest = ""
            read_error = ""
            try:
                with open_db_ro_fast(timeout_sec=0.12, busy_timeout_ms=0) as conn:
                    latest = latest_ui_default_run_date(conn, max_scan=14)
                    if not latest:
                        latest = latest_run_date_fast(conn)
            except Exception as exc:
                latest = ""
                read_error = f"{exc.__class__.__name__}"
            if latest:
                with LATEST_DATE_CACHE_LOCK:
                    LATEST_DATE_CACHE["ts"] = now_ts
                    LATEST_DATE_CACHE["date"] = str(latest or "")
                self._send_json({"ok": True, "date": latest, "source": "latest_ro_fast", "cache_hit": False})
                return
            if cached_date:
                self._send_json(
                    {
                        "ok": True,
                        "date": cached_date,
                        "cache_hit": True,
                        "stale": True,
                        "cache_age_sec": round(cached_age_sec or 0.0, 3),
                        "error": read_error or "latest_ro_fast_unavailable",
                    }
                )
                return
            self._send_json({"ok": False, "date": "", "error": read_error or "latest_ro_fast_unavailable"})
            return

