        if path == "/api/q-calibration":
            method = str(params.get("method", [""])[0] or "").strip().lower()
            if method in {"platt", "q_platt"}:
                if not DB_PATH.exists():
                    self._send_json({"ok": False, "error": "db_missing"})
                    return
                days_raw = params.get("days", [""])[0]
                days_val = None
                if days_raw:
                    try:
                        days_val = int(days_raw)
                    except ValueError:
                        days_val = None
                if days_val is None or days_val <= 0:
                    try:
                        days_val = int(os.environ.get("PM_Q_PLATT_DAYS", "30"))
                    except (TypeError, ValueError):
                        days_val = 30
                platt = _load_platt_calibration(int(days_val))
                if not platt:
                    self._send_json({"ok": False, "error": "not_available", "method": "platt", "days": int(days_val)})
                    return
                self._send_json(platt)
                return

            try:
                days = int(params.get("days", [str(Q_CALIBRATION_DAYS)])[0])
            except ValueError:
                days = Q_CALIBRATION_DAYS
            platt_days = None
            try:
                platt_days = int(os.environ.get("PM_Q_PLATT_DAYS", str(days)))
            except (TypeError, ValueError):
                platt_days = days
            platt: Optional[Dict[str, Any]] = _load_platt_calibration(int(platt_days or 0))
            fast_platt = str(os.environ.get("PM_Q_CALIBRATION_FAST_PLATT", "1")).strip().lower() not in {"0", "false", "no"}
            platt_ok = bool(platt and platt.get("ok") and platt.get("stable_ok"))
            if platt_ok and fast_platt:
                out_fast = {
                    "ok": True,
                    "days": int(days),
                    "events": _to_int(platt.get("event_count")),
                    "min_count": Q_CALIBRATION_MIN_COUNT,
                    "bins": [],
                    "metrics": {},
                    "generated_at": now_text(),
                    "platt": platt,
                    "active_method": "platt",
                }
                self._send_json(out_fast)
                return
            out = q_round_calibration_stats(days)
            if not isinstance(out, dict):
                out = {"ok": False, "days": days, "events": 0, "generated_at": now_text()}
            out["platt"] = platt or {"ok": False, "method": "platt", "days": int(platt_days or 0)}
            out["active_method"] = "platt" if platt_ok else "binning"
            if not bool(out.get("ok")) and platt_ok:
                out["ok"] = True
            self._send_json(out)
            return

